INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (1, 'Aksesoari', 'aksesoari', 'Beauty aksesoari su mali, ali važni dodaci koji olakšavaju svakodnevnu negu i čine rutinu urednijom i praktičnijom. Namenjeni su boljoj organizaciji, preciznijoj primeni proizvoda i ugodnijem iskustvu nege.', NULL, 1, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (2, 'Aktivni sastojci', 'aktivni-sastojci', NULL, NULL, 2, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (3, 'Aparati', 'beauty-aparati', 'Beauty aparati omogućavaju ciljanu negu kože i tela u kućnim uslovima, uz tehnologije koje pomažu u poboljšanju teksture, tonusa i opšteg izgleda. Namenjeni su onima koji žele napredniju rutinu i dodatnu podršku svakodnevnoj nezi. Redovnom upotrebom doprinose vidljivijim i dugotrajnijim rezultatima.', NULL, 3, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (4, 'Kosa', 'kosa', 'Kada kosa izgleda suvo, beživotno ili teško za oblikovanje, problem je gotovo uvek u pogrešnoj nezi. Ovde su proizvodi za negu kose koji su fokusirani na rezultat — od hidratacije i obnove, do sjaja i lakšeg stilizovanja. U ponudi su i brendovi poput Shiseido, poznati po formulama koje rade na strukturi kose, a ne samo na površinskom utisku.', NULL, 4, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (5, 'Lice', 'lice', NULL, NULL, 5, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (6, 'Make-up', 'make-up', 'U ponudi su pažljivo odabrani make-up proizvodi koji kombinuju lepu završnicu i negujuće formule. Posebno mesto zauzima K-beauty estetika — brendovi poput TIRTIR i Laneige poznati su po prirodnom sjaju, laganim teksturama i efektu zdrave, negovane kože. Idealno za one koji žele make-up koji se nosi lako, izgleda sveže i prati tempo svakog dana.', NULL, 6, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (7, 'Outlet', 'outlet', 'Ovo nisu “loši proizvodi” — ovo su potpuno ispravni preparati koji samo ulaze u poslednje mesece roka. Ako želiš da probaš nešto novo, obnoviš zalihe ili uštediš na omiljenim proizvodima, ovo je tvoj momenat.', NULL, 7, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (8, 'Popust do -50%', 'popusti-do-50', NULL, NULL, 8, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (9, 'Stanje kože', 'stanje-koze', 'Koža se menja — reaguje na stres, hormonske promene, vreme i pogrešnu negu. Umesto da biraš proizvode nasumično, ovde možeš da ih pronađeš prema stvarnom stanju kože: dehidratacija, crvenilo, nepravilnosti, gubitak sjaja ili osećaj zatezanja. Kada se nega prilagodi onome što koža trenutno pokazuje, rezultati postaju vidljiviji i rutine imaju više smisla.', NULL, 9, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (10, 'Telo', 'telo', NULL, NULL, 10, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (11, 'Tip kože', 'tip-koze', NULL, 5, 11, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (12, 'Clay maske', 'clay-maske', 'Clay maske koriste moć prirodnih glina za upijanje viška sebuma i uklanjanje nečistoća iz pora. Tokom delovanja pomažu u pročišćavanju kože, smanjenju sjaja i poboljšanju teksture, dok ten izgleda čistije i uravnoteženije. Posebno su korisne kada koža deluje zagušeno, masno ili sklono nepravilnostima, a cilj je čist i svež izgled bez preteranog isušivanja.', NULL, 12, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (13, 'Hidrogel maske', 'hidrogel-maske', 'Hidrogel maske prijanjaju uz kožu poput druge kože i polako otpuštaju aktivne sastojke tamo gde su najpotrebniji. Dok hlade, umiruju i dubinski hidriraju, koža postaje punija, zaglađenija i vidljivo osvežena, kao nakon dobrog sna. Idealne su kada ten deluje umorno, dehidrirano ili bez sjaja, a želiš brz, ali primetan efekat.', NULL, 13, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (14, 'Modeling maske', 'modeling-maske', 'Modeling maske se nanose kao tečna smesa koja se tokom delovanja pretvara u elastični sloj i „zaključava“ aktivne sastojke u koži. Ovakav efekat pojačava njihovo delovanje, dok se koža istovremeno hladi, umiruje i regeneriše. Nakon skidanja, ten izgleda zaglađenije, ujednačenije i osveženije, a koža deluje smirenije i otpornije, posebno kada je umorna, osetljiva ili pod stresom.', NULL, 14, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (15, 'Multi-Step maske', 'multi-step-maske', 'Multi-Step maske pretvaraju negu u mali ritual sastavljen od više pažljivo povezanih koraka. Svaki korak ima svoju ulogu — od pripreme kože, preko aktivne nege, do završnog sloja koji produžava efekat i zaključava vlagu. Koža nakon toga deluje smireno, hidrirano i vidljivo negovano, kao da je prošla kompletnu rutinu u samo jednom trenutku.', NULL, 15, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (16, 'Patch maske', 'patch-maske', 'Patch maske pružaju ciljanu negu tačno tamo gde je koži najpotrebnija. Namenjene su zonama poput podočnjaka, vrata i linije vilice, gde koža često prva pokazuje umor, dehidrataciju ili gubitak svežine. Dok deluju, umiruju, hidriraju i zaglađuju kožu, ostavljajući regiju vidljivo odmornijom i negovanijom.', NULL, 16, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (17, 'Peel-off', 'peel-off', 'Peel-off maske se nanose u tankom sloju i nakon sušenja skidaju u jednom potezu, uklanjajući nečistoće sa površine kože. Dok se maska suši, koža se pročišćava i zaglađuje, a ten nakon skidanja izgleda čistije, svežije i vizuelno ujednačenije. Idealne su kada želiš brz efekat čiste kože i osećaj momentalnog osveženja.', NULL, 17, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (18, 'Sheet maske', 'sheet-maske', 'Sheet maske su natopljene esencijom i priljubljuju se uz kožu, omogućavajući aktivnim sastojcima da deluju direktno i ravnomerno. Dok su na licu, koža se intenzivno hidrira, smiruje i osvežava, a nakon skidanja izgleda punije, sjajnije i vidljivo odmornije. Idealne su kada želiš brz, ali prijatan efekat nege bez komplikovanja rutine.', NULL, 18, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (19, 'Sleeping maske', 'sleeping-mask', 'Sleeping maske se nanose kao poslednji korak večernje rutine i ostavljaju da deluju tokom noći. Dok koža miruje, maska postepeno hidrira, obnavlja i pomaže da se ten ujutru probudi mekši, puniji i vidljivo osvežen. Idealne su kada želiš da iskoristiš noć za dubinsku negu bez dodatnog truda.', NULL, 19, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (20, 'Wash-off maske', 'wash-off-maske', 'Wash-off maske se nanose na kožu, ostavljaju da deluju određeno vreme i zatim ispiraju vodom. Dok su na licu, pročišćavaju, hidriraju ili umiruju kožu, u zavisnosti od formule, a ten nakon ispiranja izgleda svežije, uravnoteženije i prijatno negovano. Idealne su kada želiš vidljiv efekat bez zadržavanja proizvoda na koži.', NULL, 20, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (21, 'Wrapping maske', 'wrapping-maske', 'Wrapping maske obavijaju kožu i stvaraju zaštitni sloj koji pomaže da se aktivni sastojci duže zadrže i deluju intenzivnije. Dok su na licu, koža se zagreva, opušta i postaje prijemčivija za negu, a nakon skidanja izgleda hidriranije, mekše i vidljivo nahranjeno. Idealne su kada želiš pojačan efekat i osećaj dubinske nege koji traje i nakon same maske.', NULL, 21, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (22, 'Balzami', 'balzami', 'Balzami za čišćenje tope šminku, SPF i nečistoće u dodiru sa kožom, bez isušivanja i narušavanja barijere. Tokom masaže prelaze u uljanu teksturu koja temeljno čisti, a pritom ostavlja kožu mekanom i prijatnom. Idealan su izbor za sve koji žele efikasno čišćenje uz osećaj nege i komfora.', NULL, 22, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (23, 'Jastučići', 'jastucici-za-ciscenje', 'Praktični i efikasni, jastučići za čišćenje brzo uklanjaju šminku, višak sebuma i nečistoće u jednom potezu. Ostavljuju kožu čistom, osveženom i prijatnom na dodir, bez komplikovane rutine. Idealni su za svakodnevnu upotrebu, ali i za putovanja kada je brzina najvažnija.', NULL, 23, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (24, 'Maramice', 'maramice', 'Maramice za čišćenje kože omogućavaju brzo i jednostavno uklanjanje šminke i nečistoća u svakom trenutku. Praktične su za upotrebu van kuće, na putovanjima ili kada nema vremena za kompletnu rutinu. Kožu ostavljaju osveženom i čistom, bez dodatnih koraka.', NULL, 24, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (25, 'Micelarne vode', 'micelarne-vode', 'Micelarne vode uklanjaju šminku, nečistoće i višak sebuma u jednom koraku, bez ispiranja. Namenjene su brzom i nežnom čišćenju kože, bez narušavanja prirodne ravnoteže. Koža ostaje čista, osvežena i prijatna, bez osećaja suvoće ili zatezanja.', NULL, 25, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (26, 'Uljani čistači', 'uljani-cistaci', 'Uljani čistači rastvaraju šminku, SPF, višak sebuma i nečistoće koje se tokom dana zadržavaju na koži. Čiste temeljno, ali nežno, bez narušavanja prirodne barijere kože. Nakon upotrebe koža ostaje čista, mekana i hidrirana, bez osećaja zatezanja.', NULL, 26, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (27, 'Čistači na vodenoj bazi', 'cistaci-na-vodenoj-bazi', 'Čistači na vodenoj bazi uklanjaju znoj, ostatke nečistoća i višak sebuma koji ostaju na koži nakon prvog čišćenja. Namenjeni su svakodnevnoj upotrebi i ostavljaju kožu čistom, osveženom i prijatnom, bez osećaja zatezanja. Idealni su kao drugi korak čišćenja ili kao samostalan izbor za laganu i uravnoteženu rutinu.', NULL, 27, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (28, 'BB i CC kreme', 'bb-cc-kreme', 'BB i CC kreme su pametna kombinacija nege kože i šminke, idealna za svakodnevnu rutinu. BB kreme (Beauty Balm) pružaju laganu pokrivnu moć, hidrataciju i zaštitu, dok CC kreme (Color Correcting) dodatno ujednačavaju ten i koriguju nepravilnosti poput crvenila i tamnih fleka.', 5, 28, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (29, 'Ciljani tretmani', 'tretman', 'Kada se nepravilnosti pojave, brzina reakcije je ključna. Ciljani tretmani deluju na problematična mesta, smanjuju crvenilo, ubrzavaju smirivanje i sprečavaju širenje upale.', 5, 29, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (30, 'Esencije', 'esencija', 'Ako želiš da koža zaista izvuče maksimum iz seruma i krema, esencija je ključni korak rutine. Njena lagana, ali koncentrisana formula intenzivno hidrira, obnavlja kožu i priprema je da bolje upije sve što dolazi nakon nje. Kada je esencija deo rutine, koža reaguje brže, a rezultati su vidljiviji i ujednačeniji.', 5, 30, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (31, 'Jastučići', 'pads', 'Jastučići su najbrži način da koži pružiš eksfolijaciju, hidrataciju ili umirenje — sve u jednom potezu. Precizno dozirani i spremni za upotrebu, štede vreme i uklapaju se u svaku rutinu, čak i kada nemaš mnogo vremena. Rezultat je vidljivo osvežena, negovana i uravnotežena koža, bez komplikovanih koraka.', 5, 31, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (32, 'Kreme', 'krema', 'Više od hidratacije — dobre kreme hrane, štite i obnavljaju kožu, prilagođavajući se njenim svakodnevnim potrebama. Bilo da želite više sjaja, čvrstoće ili zaštite, prava krema čini razliku koju vidite i osećate.', 5, 32, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (33, 'Losion', 'losion', NULL, 5, 33, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (34, 'Maske', 'maske', 'Maske za lice pružaju ciljanu i intenzivnu negu kada koži treba više od svakodnevne rutine. Deluju brzo i fokusirano — bilo da je cilj hidratacija, umirenje, čišćenje, obnova ili poboljšanje teksture kože. Redovnom upotrebom maske pomažu da ten izgleda svežije, ujednačenije i negovanije, uz efekte koji se vide i osećaju odmah nakon upotrebe.', 5, 34, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (35, 'Mist', 'mist', 'Mist je lagani, osvežavajući sprej koji trenutno hidrira, umiruje i revitalizuje kožu tokom dana. Idealan je za brzo obnavljanje vlage, osveženje tena i fiksiranje šminke, bez narušavanja postojeće rutine. Koža izgleda svežije, hidriranije i blistavije, čak i kada je dan dinamičan i naporan.', 5, 35, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (36, 'Nega trepavica', 'nega-trepavica', 'Trepavicama je, kao i koži, potrebna svakodnevna nega da bi ostale snažne, guste i zdrave. Serumi i tretmani za trepavice hrane, jačaju i podstiču njihov prirodni rast, čineći pogled izražajnijim i zavodljivijim.', 5, 36, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (37, 'Nega usana', 'nega-usana', 'Usne su posebno osetljive i brzo gube vlagu, zato im je potrebna ciljana nega. Balzami, maske i serumi za usne pružaju hidrataciju, obnavljanje i zaštitu, čineći ih mekim, glatkim i zdravim tokom cele godine.', 5, 37, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (38, 'Nega vrata', 'nega-vrata', NULL, 5, 38, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (39, 'Okoloočna nega', 'okoloocna-nega', 'Koža oko očiju je tanja i osetljivija od ostatka lica, zato zahteva posebnu pažnju. Preparati za okoloočnu negu pomažu u smanjenju natečenosti, tamnih kolutova i finih linija, dok istovremeno hidriraju i jačaju ovu regiju. Pravilnom negom pogled deluje odmornije, čvršće i vidno svežije.', 5, 39, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (40, 'Pilinzi', 'pilinzi', 'Ovde ćeš pronaći pažljivo odabrane pilinge – od blagih enzimskih i AHA/BHA formula, do mehaničkih pilinga za trenutni efekat zaglađivanja. Redovnim korišćenjem, piling uklanja mrtve ćelije, otčepljuje pore, ujednačava teksturu i poboljšava upijanje seruma i krema. Biraj piling prema svom tipu kože i potrebama – za lice koje izgleda osveženo, čisto i puno sjaja.', 5, 40, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (41, 'Serumi', 'serumi', 'Serumi su koncentrisana nega namenjena rešavanju konkretnih potreba kože. U formulama se često nalaze aktivni sastojci poput hijaluronske kiseline za hidrataciju, niacinamida za ujednačavanje tena, vitamina C za sjaj, kao i peptida i retinola za poboljšanje teksture i čvrstoće. Lagane teksture omogućavaju brzo upijanje i lako uklapanje u rutinu, dok pravilno odabran serum donosi vidljive promene u kvalitetu kože.', 5, 41, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (42, 'Setovi za kožu', 'setovi-za-kozu', NULL, 5, 42, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (43, 'SPF', 'zastita-od-sunca', 'SPF je najvažniji korak u svakodnevnoj nezi kože. Štiti od UV zračenja koje uzrokuje prevremeno starenje, fleke i gubitak elastičnosti. Moderni SPF proizvodi su lagani, prijatni za nošenje i lako se uklapaju u svaku rutinu, bez belog traga i težine na koži. Pravilna zaštita čuva izgled i zdravlje kože dugoročno.', 5, 43, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (44, 'Toneri', 'toner', 'Toneri nisu samo &#8220;još jedan korak&#8221; — oni vraćaju koži optimalan pH, uklanjaju ostatke nečistoća i pripremaju je da bolje primi aktivne sastojke. Bez pravilnog toniranja, vaša rutina jednostavno nije potpuna.', 5, 44, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (45, 'Ulja za kožu', 'ulje', 'Ulja za kožu pružaju intenzivnu hidrataciju, hrane i jačaju prirodnu barijeru, ostavljajući kožu mekšom, elastičnijom i otpornijom. Idealna su za suvu, dehidriranu ili umornu kožu kojoj je potrebna dodatna nega.', 5, 45, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (46, 'Čišćenje kože', 'ciscenje', 'Pravilno čišćenje kože čini razliku između umorne i blistave kože. Proizvodi iz ove kategorije uklanjaju nečistoće, višak sebuma i šminku, dok istovremeno čuvaju prirodnu barijeru kože. Kada je koža dobro očišćena, izgleda svežije, glađe i spremna je da iz nege izvuče maksimum.', 5, 46, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (47, 'Masna koža', 'masna-koza-tip-koze', NULL, 11, 47, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (48, 'Mešovita koža', 'mesovita-i-normalna-koza', NULL, 11, 48, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (49, 'Normalna', 'normalna', NULL, 11, 49, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (50, 'Osetljiva koža', 'osetljiva-koza', NULL, 11, 50, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (51, 'Problematična koža', 'problematicna', NULL, 11, 51, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (52, 'Suva koža', 'suva-koza-tip-koze', NULL, 11, 52, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (53, 'Svi tipovi kože', 'svi-tipovi-koze', NULL, 11, 53, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (54, 'Akne', 'akne', 'Akne nisu samo estetski problem, već znak da koži treba drugačiji pristup. Bilo da su povremene ili uporne, pravilno odabrana nega pomaže u smirivanju upala, čišćenju pora i sprečavanju novih nepravilnosti. Ovde su proizvodi koji ciljaju stvarne uzroke akni — višak sebuma, zapušene pore i narušenu kožnu ravnotežu — bez agresivnog isušivanja.', 9, 54, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (55, 'Antiage', 'antiage', NULL, 9, 55, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (56, 'Beživotna koža', 'bezivotna-koza', 'Beživotna koža često izgleda sivo, umorno i bez svežine, čak i kada nema vidljivih problema. Uzrok može biti dehidratacija, usporena obnova kože, stres ili neadekvatna nega. Pravilno odabrani proizvodi pomažu da se koži vrati sjaj, bolja tekstura i osećaj vitalnosti, bez teških formula i agresivnih koraka.', 9, 56, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (57, 'Crvenilo', 'crvenilo', 'Crvenilo je znak da je koža pod stresom ili da joj je narušena prirodna ravnoteža. Može se pojaviti povremeno ili biti stalno prisutno, praćeno osećajem peckanja, zatezanja ili toplote. Pravilno odabrana nega pomaže u smirivanju kože, jačanju barijere i smanjenju vidljivosti crvenila, bez dodatnog iritiranja.', 9, 57, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (58, 'Hidratacija', 'hidratacija', NULL, 9, 58, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (59, 'Hiperpigmentacije', 'hiperpigmentacije', NULL, 9, 59, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (60, 'Proširene pore', 'prosirene-pore', NULL, 9, 60, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (61, 'Tonus kože', 'tonus-koze', NULL, 9, 61, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (62, 'Aha kiseline', 'aha', 'AHA kiseline deluju na površini kože i pomažu da se ukloni višak nagomilanih ćelija koji ten čini neujednačenim i bez sjaja. Koža dobija glađu teksturu i jasniji izgled, uz suptilan sjaj. Glikolna, mlečna i citrična kiselina ostaju pouzdan izbor kada je fokus na kvalitetu kože, a ne na prikrivanju njenog izgleda.', 2, 62, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (63, 'Alfa arbutin', 'alfa-arbutin', 'Alfa arbutin je sastojak kome se često okrećemo kada ten izgleda neujednačeno ili se pojave tamne mrlje. Deluje ciljano na hiperpigmentacije, pomažući koži da postepeno izgleda čistije i ujednačenije. Zbog blagog, ali efikasnog delovanja, često je izbor i za kožu koja ne podnosi agresivne aktivne sastojke.', 2, 63, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (64, 'Aloe vera', 'aloe-vera', 'Prirodna snaga aloe vere umiruje iritacije, hidrira kožu i pomaže u oporavku od upala i crvenila. Bogata vitaminima i antioksidansima, jača zaštitnu barijeru i vraća koži elastičnost. Idealna je za sve tipove kože kojima treba nežna, ali efikasna nega.', 2, 64, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (65, 'Azelaična kiselina', 'azelaicna-kiselina', 'Azelaična kiselina deluje protiv upala, smanjuje crvenilo i ujednačava ten. Efikasna je u borbi protiv akni, rozacee i hiperpigmentacija, a pritom nežna prema osetljivoj koži. Rezultat je čista, smirena i vidljivo ujednačenija koža.', 2, 65, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (66, 'Bakučiol', 'bakuchiol', 'Bakučiol je biljna alternativa retinolu, namenjena onima koji žele ujednačeniju teksturu i mekšu kožu bez iritacija. Pomaže u zaglađivanju finih linija i poboljšanju tonusa, a pritom je prijatan i za osetljivu kožu. Često se bira za svakodnevnu rutinu i stabilan, negovan izgled tena.', 2, 66, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (67, 'Centella Asiatica', 'centella-asiatica', 'Centella Asiatica je sastojak kome se koža često vraća kada je osetljiva, crvena ili iscrpljena. Poznata je po umirujućem dejstvu i podršci kožnoj barijeri, pa koža s vremenom deluje stabilnije i prijatnije na dodir. Zato se nalazi u preparatima namenjenim svakodnevnoj nezi i dugoročnoj udobnosti kože.', 2, 67, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (68, 'Ceramidi', 'ceramidi', 'Ceramidi su štit koji vaša koža svakodnevno treba. Obnavljaju oštećenu barijeru, zaključavaju vlagu i čuvaju kožu od spoljašnjih napada. Bez njih, koža postaje tanka, suva i ranjiva — sa njima ostaje jaka, hidrirana i zaštićena.', 2, 68, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (69, 'Egzozomi', 'egzozomi', 'Egzozomi prenose ključne signale koji podržavaju regeneraciju i obnovu kože na ćelijskom nivou. Ubrzavaju oporavak, jačaju strukturu kože i doprinose njenoj boljoj elastičnosti. Koža vremenom izgleda svežije, zategnutije i otpornije, sa vidljivo ublaženim znacima starenja..', 2, 69, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (70, 'Faktori rasta', 'egf-faktori-rasta', 'Epidermalni faktori rasta podstiču prirodnu obnovu kože na najdubljem nivou. Ubrzavaju zaceljivanje, poboljšavaju elastičnost i vidljivo umanjuju znakove starenja. Rezultat je koža koja izgleda svežije, čvršće i punije iznutra.', 2, 70, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (71, 'Galaktomiceti', 'galaktomiceti', 'Galaktomiceti su prirodni fermenti bogati hranljivim materijama koji vidljivo poboljšavaju teksturu kože i ujednačavaju ten. Deluju tako što podržavaju kožni mikrobiom i jačaju sposobnost kože da zadrži vlagu. Koža s vremenom izgleda zdravije, svežije i sa više prirodnog sjaja.', 2, 71, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (72, 'Glutation', 'glutation', 'Glutation je jedan od najmoćnijih prirodnih antioksidanasa koji štiti kožu od oštećenja i usporava procese starenja . Pomaže u posvetljivanju tena, smanjenju tamnih fleka i vraća koži ujednačen, zdrav sjaj.', 2, 72, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (73, 'Heartleaf', 'heartleaf', 'Heartleaf (Houttuynia Cordata) je biljka poznata po snažnim umirujućim i antioksidativnim svojstvima. Koristi se za smanjenje upala, kontrolu sebuma i jačanje prirodne barijere kože. Idealna je za osetljivu, reaktivnu kožu kojoj je potrebna smirenost, čistoća i otpornost', 2, 73, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (74, 'Hijaluronska kiselina', 'hijaluronska-kiselina', 'Više od hidratacije: hijaluronska kiselina puni kožu iznutra, vraćajući joj volumen, elastičnost i prirodnu svežinu. Deluje kao magnet za vlagu, čineći kožu vidljivo zategnutijom, mekšom i sjajnijom već nakon prve upotrebe.', 2, 74, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (75, 'Kojična kiselina', 'kojicna-kiselina', 'Kojična kiselina deluje ciljano na smanjenje pigmentacija i posvetljivanje tamnih mrlja. Usporava proizvodnju melanina i pomaže da ten izgleda ujednačenije i svetlije. Koža dobija blistaviji i nežniji izgled, bez osećaja težine.', 2, 75, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (76, 'Kolagen', 'kolagen', 'Kolagen je ključan za strukturu kože i odgovoran za njen čvrst i elastičan izgled. Njegova uloga u nezi kože je da doprinese boljoj punoći, zaglađivanju finih linija i očuvanju tonusa. Preparati sa kolagenom pomažu koži da izgleda zategnutije, mekše i vizuelno odmornije.', 2, 76, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (77, 'Niacinamid', 'niacinamid', 'Niacinamid pruža višenamensku podršku koži kroz ujednačavanje tona, smanjenje vidljivosti pora i regulaciju sebuma. Istovremeno jača kožnu barijeru i pomaže koži da izgleda stabilnije i zdravije. Zato je čest izbor kada je potreban prirodan sjaj i dobra tolerancija, bez iritacija.', 2, 77, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (78, 'Peptidi', 'pepidi', 'Peptidi su aminokiseline koje podstiču kožu da se obnavlja i jača iznutra. Pomažu u poboljšanju tonusa, smanjenju sitnih bora i očuvanju čvrstoće kože. Ne preuzimaju ulogu prirodnih procesa — oni ih samo pametno pokreću!', 2, 78, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (79, 'PHA', 'polihidroksi-kiseline', 'Polihidroksi kiseline (PHA) nežno uklanjaju mrtve ćelije sa površine kože, bez iritacija koje se često vezuju za jače eksfolijante. Istovremeno doprinose hidrataciji, jačanju zaštitne barijere i poboljšanju teksture kože. Posebno su pogodne za osetljivu kožu kojoj je potrebna obnova bez crvenila i nelagodnosti.', 2, 79, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (80, 'Polinukleotidi', 'polinukleotidi', 'Polinukleotidi deluju na dubinsku regeneraciju kože i podržavaju njene prirodne reparativne procese. Pomažu u poboljšanju elastičnosti, hidratacije i ukupnog kvaliteta kože, posebno kada je ona umorna, dehidrirana ili oštećena. Koža s vremenom izgleda zdravije, punije i otpornije.', 2, 80, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (81, 'Probiotici', 'probiotici', 'Probiotici pomažu u obnavljanju prirodne ravnoteže kože jačajući njen mikrobiom. Doprinose smanjenju upala, boljoj zaštiti od spoljašnjih uticaja i stabilnijem izgledu tena. Posebno prijaju osetljivoj i reaktivnoj koži kojoj je potrebna dodatna podrška i otpornost.', 2, 81, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (82, 'Propolis', 'propolis', 'Propolis je prirodni sastojak poznat po antibakterijskom i umirujućem delovanju. Pomaže u smanjenju upala, podržava regeneraciju kože i jača njenu prirodnu zaštitnu barijeru. Koža deluje smirenije, otpornije i zdravijeg izgleda, posebno kada je sklona nepravilnostima ili iritacijama.', 2, 82, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (83, 'Puževa sluz', 'puzeva-sluz', 'Puževa sluz je bogata prirodnim proteinima, elastinom i hijaluronskom kiselinom, koji su ključni za obnovu i hidrataciju kože. Pomaže u regeneraciji oštećenja, ublažavanju vidljivosti ožiljaka i poboljšanju teksture kože. Koža deluje glađe, elastičnije i dobija zdrav, ujednačen sjaj.', 2, 83, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (84, 'Retinol', 'retinol', 'Retinol je jedan od najistraženijih aktivnih sastojaka u nezi kože, poznat po svom delovanju na fine linije, bore i neujednačenu teksturu. Podstiče obnovu ćelija i poboljšava tonus kože, čineći je glađom i ujednačenijom. Redovno se koristi u rutinama koje su usmerene na vidljivo unapređenje kvaliteta kože.', 2, 84, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (85, 'Salicilna kiselina', 'salicilna', 'Salicilna kiselina prodire u pore i pomaže u uklanjanju viška sebuma i nečistoća koje dovode do zapušenih pora i nepravilnosti. Deluje keratolitički, smanjuje upale i doprinosi čistijem, ujednačenijem izgledu kože. Posebno je pogodna za masnu i problematičnu kožu sklonu aknama.', 2, 85, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (86, 'Shea puter', 'shea-puter', 'Shea puter je bogat masnim kiselinama i vitaminima koji hrane kožu, obnavljaju njenu zaštitnu barijeru i sprečavaju gubitak vlage. Posebno prija suvoj, osetljivoj i koži sklonoj zatezanju, ostavljajući je mekšom, elastičnijom i prijatnijom na dodir. Doprinosi dugotrajnom osećaju komfora i zdravijem izgledu kože.', 2, 86, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (87, 'Spikule', 'spikule', 'Spikule su mikroskopske iglice prirodnog porekla koje stimulišu obnovu kože i poboljšavaju prodiranje aktivnih sastojaka. Deluju tako što podstiču regeneraciju, zaglađuju teksturu i doprinose ujednačenijem izgledu tena. Koža postaje aktivnija, čvršća i vidno osvežena nakon redovne upotrebe.', 2, 87, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (88, 'Traneksaminska kiselina', 'traneksaminska-kiselina', 'Traneksaminska kiselina je poznata po ciljnom delovanju na hiperpigmentacije i neujednačen ton kože. Pomaže u smanjenju tamnih fleka, postinflamatornih tragova i sivila tena, dok istovremeno doprinosi mirnijem i čistijem izgledu kože. Često se bira u rutinama usmerenim na posvetljivanje i dugoročno ujednačavanje tena.', 2, 88, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (89, 'Vitamin C', 'vitamin-c', 'Vitamin C je snažan antioksidans koji pomaže u posvetljivanju tena, ujednačavanju pigmentacija i poboljšanju sjaja kože. Podstiče sintezu kolagena i štiti kožu od oksidativnog stresa, što doprinosi svežijem i čvršćem izgledu. Redovno se koristi u rutinama usmerenim na blistav i zdrav izgled kože.', 2, 89, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (90, 'Zeleni čaj', 'zeleni-caj', 'Zeleni čaj je snažan prirodni antioksidans koji pomaže u zaštiti kože od spoljašnjih uticaja i prevremenog starenja. Deluje umirujuće, smanjuje crvenilo i doprinosi čistijem, ujednačenijem izgledu kože. Posebno prija koži koja je sklona iritacijama i oksidativnom stresu.', 2, 90, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (91, 'Žen-šen', 'zen-sen', 'Žen-šen je biljni sastojak poznat po snažnom antioksidativnom i revitalizujućem delovanju. Pomaže u poboljšanju tonusa, elastičnosti i ukupne vitalnosti kože, dok istovremeno štiti od spoljašnjih stresora. Koža izgleda svežije, čvršće i dobija zdraviji, odmorniji izgled.', 2, 91, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (92, 'Dezodoransi', 'dezodoransi', NULL, 10, 92, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (93, 'Higijena usta i zuba', 'higijena-usta-i-zuba', 'Pravilna higijena usta i zuba ključna je za očuvanje zdravlja desni, zuba i celokupne usne duplje. Proizvodi iz ove kategorije pomažu u uklanjanju naslaga, zaštiti od karijesa i održavanju dugotrajne svežine daha. Redovna i pravilna nega doprinosi čistijem osećaju u ustima i zdravijem osmehu.', 10, 93, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (94, 'Krema za depilaciju', 'krema-za-depilaciju', NULL, 10, 94, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (95, 'Kupke i gelovi', 'kupke-i-gelovi-za-tusiranje', NULL, 10, 95, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (96, 'Mist', 'mist-telo', NULL, 10, 96, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (97, 'Mleka i losioni', 'mleka-i-losioni', NULL, 10, 97, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (98, 'Nega noktiju', 'nega-noktiju', NULL, 10, 98, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (99, 'Nega ruku', 'nega-ruku', NULL, 10, 99, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (100, 'Nega stopala', 'nega-stopala', NULL, 10, 100, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (101, 'Pilinzi', 'pilinzi-telo', NULL, 10, 101, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (102, 'Setovi za telo', 'setovi-za-telo', NULL, 10, 102, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (103, 'Balzami za kosu', 'balzami-za-kosu', 'Balzami za kosu namenjeni su nezi dužine i krajeva, gde je kosa najčešće suva i oštećena. Pomažu u hidrataciji, zaglađivanju vlasi i smanjenju mršenja, čineći kosu mekšom, sjajnijom i lakšom za oblikovanje. Redovnom upotrebom kosa izgleda negovanije i otpornije na spoljašnje uticaje.', 4, 103, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (104, 'Leave-in', 'leave-in', 'Leave-in preparati ostaju na kosi i pružaju kontinuiranu negu tokom dana. Pomažu u hidrataciji, zaštiti od toplote i spoljašnjih uticaja, kao i u smanjenju frizza i lomljenja. Kosa je mekša, zaglađenija i lakša za oblikovanje, bez osećaja težine.', 4, 104, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (105, 'Maske', 'maska', 'Maske za kosu pružaju intenzivnu negu, namenjenu obnovi suve, oštećene ili hemijski tretirane kose. Pomažu u hidrataciji, jačanju vlasi i vraćanju mekoće i sjaja. Redovnom upotrebom kosa izgleda zdravije, zaglađenije i otpornije na dalja oštećenja.', 4, 105, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (106, 'Puderi', 'puderi-kosa', 'Puderi za kosu namenjeni su brzom podizanju volumena i osvežavanju frizure bez pranja. Pomažu u upijanju viška masnoće, daju teksturu kosi i produžavaju trajanje frizure. Posebno su praktični za tanku kosu ili dane kada je potreban brz i uredan izgled.', 4, 106, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (107, 'Serumi za kosu', 'serumi-i-ampule', 'Serumi za kosu namenjeni su ciljanoj nezi vlasi i vlasišta, sa fokusom na jačanje kose, podsticanje rasta i smanjenje opadanja. Aktivne formule deluju na koren kose, poboljšavaju kvalitet vlasi i doprinose zdravijem izgledu kose od samog početka rasta. Redovnom upotrebom kosa postaje jača, gušća i otpornija, uz vidljivo poboljšan kvalitet.', 4, 107, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (108, 'Setovi za kosu', 'setovi-za-kosu', NULL, 4, 108, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (109, 'Stilizovanje kose', 'stilizovanje', 'Proizvodi za stilizovanje kose pomažu u oblikovanju frizure, kontroli volumena i produženju njenog trajanja. Namenjeni su definisanju teksture, zaglađivanju, učvršćivanju ili naglašavanju prirodnog oblika kose. Pravilno odabrani proizvodi omogućavaju uredan i postojan izgled bez slepljivanja i osećaja težine.', 4, 109, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (110, 'Tretmani za kosu', 'tretman-kosa', 'Tretmani za kosu namenjeni su ciljanoj nezi kada je kosi potrebna dodatna obnova i jačanje. Deluju na hidrataciju, strukturu vlasi i otpornost kose, posebno kod oštećenja, suvoće ili gubitka sjaja. Redovnom primenom kosa postaje snažnija, mekša i vidno negovanija.', 4, 110, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (111, 'Ulje za kosu', 'ulje-za-kosu', 'Ulja za kosu namenjena su nezi dužine i krajeva, gde je kosa najčešće suva i sklona oštećenjima. Pomažu u zaglađivanju vlasi, smanjenju frizza i vraćanju sjaja, bez otežavanja kose. Pravilno odabrano ulje doprinosi mekšoj, negovanijoj i vizuelno zdravijoj kosi.', 4, 111, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (112, 'Šamponi', 'samponi', 'Šamponi su osnova svake rutine nege kose i vlasišta. Namenjeni su temeljnom čišćenju, uklanjanju viška sebuma i nečistoća, uz očuvanje prirodne ravnoteže kože glave. Pravilno odabran šampon doprinosi zdravijem vlasištu i lepšem izgledu kose u celini.', 4, 112, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (113, 'Ajlajneri', 'ajlajneri', 'Dobar ajlajner se ne razmazuje, ne puca i ne zahteva popravke tokom dana. Ovde su formule koje omogućavaju kontrolu, preciznost i postojanost — bilo da voliš tanku, diskretnu liniju ili izraženiji pogled. Cilj je jednostavan: linija ostaje tamo gde treba, bez kompromisa.', 6, 113, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (114, 'Fiksatori', 'fiksator', 'Fiksatori za šminku koriste se kao završni korak kako bi produžili trajanje make-upa i smanjili njegovo razmazivanje ili razgradnju tokom dana. U zavisnosti od formule, mogu pomoći u kontroli sjaja, smanjenju praškastog izgleda i očuvanju svežine tena.', 6, 114, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (115, 'Karmini', 'karmini', NULL, 6, 115, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (116, 'Maskara', 'maskara', 'Maskara naglašava trepavice tako što im daje boju, definiciju i, u zavisnosti od formule, volumen ili dužinu. Pravilno odabrana maskara razdvaja trepavice, naglašava pogled i čini oči izražajnijim, bez slepljivanja i razmazivanja.', 6, 116, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (117, 'Palete i senke za oči', 'palete-i-senke-za-oci', NULL, 6, 117, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (118, 'Prajmeri', 'prajmeri', 'Prajmeri pripremaju kožu za make-up tako što zaglađuju teksturu, smanjuju vidljivost pora i pomažu da puder lepše „legne“. Pravi prajmer daje koži ujednačen izgled, produžava trajanje šminke i stvara onaj suptilan blur efekat — kao da koža već izgleda dobro i pre svega ostalog.', 6, 118, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (119, 'Puderi', 'puderi', 'Dobri puderi ne prekrivaju kožu — oni je zaglađuju. Smanjuju vidljivost pora, ujednačavaju teksturu i ostavljaju ten mekšim na pogled, skoro kao da ima blagi filter. Rezultat je prirodan, uredan izgled kože koji izgleda dobro izbliza, ne samo na kameri.', 6, 119, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (120, 'Sjajevi za usne', 'sjajevi-za-usne', 'Sjajevi za usne vraćaju usnama sjaj, mekoću i vizuelnu punoću bez teškog osećaja. Lagane formule se lako nanose, prijatne su za nošenje i čine usne negovanijim i svežijim. Idealni su za prirodan dnevni look, ali i kao završni dodir uz jaču šminku.', 6, 120, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO category (id, name, slug, description, parent_category_id, sort_order, is_active, created_at, updated_at) VALUES (121, 'Tečni karmin', 'tecni-karmin', NULL, 6, 121, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1, 53, 'Dr.nineteen PoreXsome V.Peptox Jelly Toner', 'dr-nineteen-porexsome-v-peptox-jelly-toner', 'Ključne prednosti: Poboljšanje elastičnosti i čvrstine: Doprinosi zategnutijem i otpornijem izgledu kože. Smanjenje vidljivosti pora: Pomaže u ujednačavanju teksture i glađem finišu kože. Dubinska hidratacija bez težine: Održava stabilan nivo vlage i punoću kože. Kome je namenjen? Namenjen je mešovitoj, masnoj i koži sa proširenim porama, kao i koži koja pokazuje prve znake starenja. Pogodan je i za dehidriranu kožu kojoj je potrebna lagana, ali efikasna hidratacija. Zašto volimo Dr.nineteen PoreXsome V.Peptox Jelly Toner? Ovaj tonik se izdvaja po teksturi koja spaja osećaj svežine i hidratacije bez lepljivosti. Nakon nanošenja brzo prelazi u laganu tečnost koja se lako upija. Koža deluje hidrirano, ali ne opterećeno. Posebno je zanimljiv fokus na pore i elastičnost u jednom koraku. Daje utisak zaglađene i ujednačene kože bez agresivnih sastojaka. Pogodan je za slojevitu rutinu jer ne stvara težinu. Lako se uklapa kao prvi hidratantni korak posle čišćenja. Aktivni sastojci PEPTOX kompleks (13 peptida) Peptidi deluju kao signalni molekuli koji utiču na regeneraciju kože. Pomažu u stimulaciji sinteze kolagena i elastina. Doprinosi poboljšanju elastičnosti i smanjenju znakova starenja. Njihovo dejstvo je postepeno i zahteva kontinuitet. Imaju i antioksidativna svojstva. U ovoj formuli imaju ključnu ulogu u jačanju kože. Egzozomi Egzozomi deluju kao sistem za prenos aktivnih sastojaka. Pomažu u poboljšanju komunikacije između ćelija kože. Doprinosi ujednačenijoj teksturi i smanjenju vidljivosti pora. Njeno dejstvo je podržavajuće i optimizuje efikasnost drugih sastojaka. Pogodna je za moderne formulacije. U ovoj formuli ima ulogu pojačavanja efekta. Hijaluronska kiselina (10 tipova) Hijaluronska kiselina deluje kao humektant koji vezuje vodu u koži. Različiti oblici omogućavaju hidrataciju na više nivoa. Doprinosi punijem i elastičnijem izgledu kože. Pomaže u smanjenju osećaja zatezanja. Njeno dejstvo je kompatibilno sa svim tipovima kože. U ovoj formuli ima ključnu hidratantnu ulogu. Niacinamid Niacinamid deluje na ujednačavanje tena i regulaciju sebuma. Pomaže u smanjenju vidljivosti pora i poboljšanju teksture. Doprinosi jačanju kožne barijere. Njegovo dejstvo je stabilno i dobro podnošljivo. Pogodan je za različite tipove kože. U ovoj formuli ima balansirajuću ulogu. Ceramidi Ceramidi su lipidi koji jačaju kožnu barijeru. Pomažu u sprečavanju gubitka vlage. Doprinosi otpornosti kože na spoljašnje faktore. Njihovo dejstvo je regenerativno i zaštitno. Pogodni su za osetljivu kožu. U ovoj formuli imaju ulogu obnove barijere. Dodaj u listu želja Dodaj u listu želja', 'Dr.nineteen PoreXsome V.Peptox Jelly Toner je hidratantni tonik gelaste teksture sa peptidima, exosome tehnologijom i hijaluronskim kompleksom koji cilja pore i gubitak elastičnosti. Deluje kroz kombinaciju dubinske hidratacije, jačanja barijere i stimulacije kolagena, čime doprinosi glađoj i zategnutijoj koži.', 'https://beauty-health.rs/wp-content/uploads/2026/04/Dr.nineteen-PoreXsome-V.Peptox-Jelly-Toner-4.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
