INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (3, 48, 'Dr. Althea Aqua Blue Hydration Mask', 'dr-althea-aqua-blue-hydration-mask', 'Ključne prednosti: Intenzivna hidratacija i osveženje: Pomaže u vraćanju vlage i smanjenju osećaja suvoće. Umirivanje i smanjenje iritacija: Doprinosi smirenijem i uravnoteženijem izgledu kože. Poboljšanje elastičnosti i tonusa: Koža deluje zategnutije i elastičnije nakon upotrebe. Kome je namenjen? Namenjena je svim tipovima kože, posebno dehidriranoj, osetljivoj i koži sklonoj crvenilu i oticanju. Pogodna je za trenutni oporavak kože nakon izlaganja spoljašnjim stresorima ili aktivnim tretmanima. Zašto volimo Dr. Althea Aqua Blue Hydration Mask? Ova maska je primer brzog i efikasnog rešenja kada koži treba trenutna hidratacija. Tekstura esencije je lagana, ali pruža vidljiv efekat osveženja. Koža nakon upotrebe deluje smirenije i mekše. Posebno se izdvaja materijal maske koji prijanja uz lice i omogućava bolju apsorpciju. Efekat smanjenja nadutosti dodatno doprinosi svežem izgledu. Boja potiče iz prirodnog sastojka, što je dodatni plus. Lako se uklapa kao povremeni tretman u rutini nege. Aktivni sastojci Azulen Azulen je sastojak dobijen iz kamilice sa izraženim umirujućim dejstvom. Pomaže u smanjenju crvenila i iritacija. Doprinosi stabilizaciji osetljive kože. Njegovo dejstvo je blago i pogodno za svakodnevnu negu. Često se koristi u formulacijama za smirivanje kože. U ovoj formuli ima ključnu umirujuću ulogu. Bambusova voda Bambusova voda je bogata aminokiselinama koje doprinose hidrataciji kože. Pomaže u održavanju optimalnog nivoa vlage. Doprinosi svežijem i elastičnijem izgledu kože. Njeno dejstvo je blago i osvežavajuće. Pogodna je za dehidriranu kožu. U ovoj formuli ima hidratantnu ulogu. Spirulina ekstrakt Spirulina ekstrakt deluje kao antioksidans i pomaže u zaštiti kože. Doprinosi poboljšanju tena i vitalnosti kože. Pomaže u smanjenju znakova umora. Njegovo dejstvo je podržavajuće i regenerativno. Pogodan je za različite tipove kože. U ovoj formuli ima ulogu revitalizacije. Ekstrakt plave agave Ekstrakt plave agave doprinosi poboljšanju elastičnosti kože. Pomaže u zadržavanju vlage i povećanju mekoće. Doprinosi zategnutijem izgledu kože. Njegovo dejstvo je blago i hidratantno. Pogodan je za svakodnevnu upotrebu. U ovoj formuli ima ulogu poboljšanja tonusa kože. Vitamin E (tokoferol) Vitamin E deluje kao antioksidans. Pomaže u zaštiti kože od spoljašnjih uticaja. Doprinosi očuvanju hidratacije i elastičnosti. Njegovo dejstvo je stabilno i zaštitno. Pogodan je za svakodnevnu negu. U ovoj formuli ima zaštitnu ulogu. Tanini iz drveta hrasta Tanini imaju blago adstringentno dejstvo. Pomažu u smanjenju nadutosti i zatezanju kože. Doprinosi boljem prijanjanju maske uz lice. Njihovo dejstvo je podržavajuće. Pogodni su za kratkotrajne tretmane. U ovoj formuli imaju ulogu poboljšanja efekta maske. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Aqua Blue Hydration Mask je hidratantna sheet maska sa azulenom, bambusovom vodom i spirulinom, formulisana za umirivanje i obnavljanje dehidrirane kože. Deluje kroz intenzivnu hidrataciju, smanjenje nadutosti i poboljšanje elastičnosti kože.', 'https://beauty-health.rs/wp-content/uploads/2026/04/Dr.-Althea-Aqua-Blue-Hydration-Mask-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
