INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (4, 113, 'Medi-Peel Peptide 9 Volume All in One Essence Pro', 'medi-peel-peptide-9-volume-all-in-one-essence-pro', 'Ključne prednosti: Poboljšanje čvrstine i elastičnosti: Doprinosi zategnutijem izgledu kože i ublažavanju bora. Intenzivna hidratacija i punoća: Pomaže u smanjenju dehidratacije i vraća koži volumen. Višeslojno delovanje na teksturu kože: Poboljšava tonus, ujednačava ten i podržava regeneraciju. Kome je namenjen? Namenjen je zreloj, dehidriranoj i koži sa izraženim znakovima starenja, uključujući gubitak tonusa i dubinu bora. Pogodan je i za kožu koja deluje umorno i bez sjaja, kojoj je potrebna intenzivna regenerativna nega. Zašto volimo Medi-Peel Peptide 9 Volume All In One Essence Pro? Ova esencija kombinuje više funkcija u jednom koraku, bez potrebe za složenom rutinom. Efekat pene nije samo vizuelan, već doprinosi boljoj raspodeli i apsorpciji proizvoda. Koža nakon nanošenja deluje hidrirano i elastičnije. Posebno se izdvaja peptidni kompleks koji cilja znakove starenja na više nivoa. Tekstura je lagana, ali ostavlja osećaj punije kože. Daje utisak zaglađenog i ujednačenog tena. Pogodna je za kontinuiranu upotrebu kada je cilj poboljšanje kvaliteta kože. Aktivni sastojci Peptidni kompleks (Matrixyl®3000) Peptidi deluju kao signalni molekuli koji utiču na regeneraciju kože. Pomažu u stimulaciji sinteze kolagena i elastina. Doprinosi smanjenju dubine bora i poboljšanju elastičnosti. Njihovo dejstvo je postepeno i zavisi od redovne upotrebe. Imaju i antioksidativna svojstva. U ovoj formuli imaju ključnu anti-age ulogu. Hidrolizovani kolagen Hidrolizovani kolagen deluje kao humektant i film-formirajući sastojak. Pomaže u zadržavanju vlage i poboljšava izgled kože. Doprinosi zaglađenijem i punijem izgledu. Njegovo dejstvo je pretežno površinsko. Pomaže u smanjenju osećaja suvoće. U ovoj formuli ima ulogu hidratacije. Volufilin Volufilin je biljni aktiv koji doprinosi vizuelnom povećanju volumena kože. Deluje kroz uticaj na lipidne procese u koži. Pomaže u poboljšanju punoće i tonusa. Njegovo dejstvo je postepeno. Često se koristi u formulacijama za volumen i elastičnost. U ovoj formuli ima ulogu poboljšanja kontura lica. Hijaluronska kiselina (4 tipa) Hijaluronska kiselina deluje kao snažan humektant. Pomaže u vezivanju vode i održavanju hidratacije. Različiti oblici deluju na više nivoa kože. Doprinosi punijem i elastičnijem izgledu. Njeno dejstvo je kompatibilno sa svim tipovima kože. U ovoj formuli ima ključnu hidratantnu ulogu. Niacinamid Niacinamid deluje na ujednačavanje tena i jačanje kožne barijere. Pomaže u smanjenju pigmentacija i regulaciji sebuma. Doprinosi elastičnosti i hidrataciji kože. Njegovo dejstvo je stabilno i dobro podnošljivo. Pogodan je za različite tipove kože. U ovoj formuli ima balansirajuću ulogu. Adenozin Adenozin deluje na poboljšanje elastičnosti i smanjenje bora. Pomaže u stimulaciji procesa obnove kože. Doprinosi zaglađenijem izgledu. Njegovo dejstvo je blago ali kontinuirano. Često se koristi u anti-age formulacijama. U ovoj formuli ima ulogu poboljšanja tonusa kože. Laktobacili Laktobacili deluju na balans mikrobioma kože i regeneraciju. Pomažu u smanjenju crvenila i poboljšanju hidratacije. Doprinosi zdravijem i otpornijem izgledu kože. Njihovo dejstvo je blago i stabilno. Pogodni su za osetljivu kožu. U ovoj formuli imaju ulogu podrške barijeri kože. Alantoin Alantoin deluje umirujuće i regenerativno. Pomaže u smanjenju iritacija i omekšavanju kože. Doprinosi hidrataciji i poboljšanju teksture. Njegovo dejstvo je blago i pogodno za osetljivu kožu. Često se koristi u umirujućim formulacijama. U ovoj formuli ima ulogu smirenja kože. Dodaj u listu želja Dodaj u listu želja', 'Medi-Peel Peptide 9 Volume All In One Essence Pro je multifunkcionalna esencija sa peptidima, kolagenom i hijaluronskom kiselinom koja cilja gubitak elastičnosti, bore i dehidrataciju. Deluje kroz kombinaciju biostimulacije, hidratacije i poboljšanja apsorpcije aktivnih sastojaka, uz karakterističan efekat kiseonične pene.', 'https://beauty-health.rs/wp-content/uploads/2026/04/medi-peel-peptide-9-volume-all-in-one-essence-pro1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
