INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (5, 68, 'GROWUS Damage Therapy Shampoo EX', 'growus-damage-therapy-shampoo-ex', 'Ključne prednosti: Čišćenje bez narušavanja vlasi: Uklanja nečistoće i naslage bez isušivanja kose i vlasišta. Obnova i jačanje strukture kose: Pomaže u smanjenju lomljenja i poboljšava elastičnost vlasi. Hidratacija i sjaj: Doprinosi mekšoj, zaglađenijoj i vizuelno zdravijoj kosi. Kome je namenjen? Namenjen je oštećenoj, suvoj i poroznoj kosi, posebno nakon farbanja ili čestog stilizovanja. Pogodan je i za osetljivo vlasište zahvaljujući blagim surfaktantima bez sulfata. Zašto volimo GROWUS Damage Therapy Shampoo EX? Ovaj šampon ide dalje od osnovnog čišćenja i uvodi koncept proteinske nege u svakodnevnu rutinu. Tekstura pene je blaga, ali efikasna u uklanjanju naslaga proizvoda. Kosa nakon pranja deluje mekše i manje krto. Posebno je koristan kod visoko porozne kose koja brzo gubi vlagu. Ne ostavlja osećaj težine niti otežava vlas. Dodatni benefiti za vlasište čine ga pogodnim za redovnu upotrebu. Lako se uklapa kao prvi korak u rutini obnove kose. Aktivni sastojci Kolagen (7 tipova) Kolagen u formulama za kosu deluje kao film-formirajući sastojak koji oblaže vlas. Pomaže u zadržavanju vlage i poboljšava elastičnost. Doprinosi zaglađenijem i sjajnijem izgledu kose. Njegovo dejstvo je pretežno površinsko. Pomaže u zaštiti vlasi od spoljašnjih uticaja. U ovoj formuli ima ulogu jačanja i zaštite. Aminokiseline (5 tipova) Aminokiseline su gradivni elementi keratina i doprinose obnovi kose. Pomažu u jačanju strukture vlasi i smanjenju lomljenja. Doprinosi većoj otpornosti kose na oštećenja. Njihovo dejstvo je usmereno na regeneraciju vlasi. Pogodne su za redovnu upotrebu. U ovoj formuli imaju ulogu obnove i jačanja. Salicilna kiselina S alicilna kiselina deluje na čišćenje vlasišta i uklanjanje viška sebuma. Pomaže u održavanju čistoće folikula dlake. Doprinosi zdravijem okruženju za rast kose. Njeno dejstvo je blago eksfolijantno. Pogodna je za vlasište sklono nakupljanju nečistoća. U ovoj formuli ima ulogu čišćenja vlasišta. Niacinamid Niacinamid deluje na balans vlasišta i regulaciju sebuma. Pomaže u smanjenju iritacija i poboljšanju barijerne funkcije kože. Doprinosi zdravijem izgledu vlasišta. Njegovo dejstvo je stabilno i dobro podnošljivo. Pogodan je za različite tipove vlasišta. U ovoj formuli ima ulogu balansiranja. Dekspantenol Dekspantenol deluje hidratantno i umirujuće. Pomaže u smanjenju suvoće vlasišta i poboljšava elastičnost kose. Doprinosi mekoći i sjaju vlasi. Njegovo dejstvo je blago i kontinuirano. Pogodan je za svakodnevnu upotrebu. U ovoj formuli ima ulogu hidratacije i zaštite. Ekstrakt bisera i himalajska ružičasta so Ovi sastojci obezbeđuju minerale i doprinose čišćenju kose i vlasišta. Pomažu u uklanjanju naslaga proizvoda i viška sebuma. Doprinosi svežem i čistom osećaju nakon pranja. Njihovo dejstvo je podržavajuće i blago. Pogodni su za kombinovanje sa hidratantnim sastojcima. U ovoj formuli imaju ulogu čišćenja i osveženja. Dodaj u listu želja Dodaj u listu želja', 'GROWUS Damage Therapy Shampoo EX je proteinski šampon za oštećenu kosu koji kombinuje kolagen, aminokiseline i blage surfaktante za čišćenje bez isušivanja. Deluje kroz uklanjanje nečistoća i istovremenu obnovu vlasi, čime pomaže u jačanju kose i vraćanju sjaja.', 'https://beauty-health.rs/wp-content/uploads/2026/04/GROWUS-Damage-Therapy-Shampoo-EX-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
