INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (6, 68, 'GROWUS Damage Therapy Treatment EX', 'growus-damage-therapy-treatment-ex', 'Ključne prednosti: Obnova oštećene kose: Pomaže u jačanju vlasi i smanjenju lomljenja. Dubinska hidratacija i mekoća: Vraća elastičnost i smanjuje suvoću kose. Zaglađivanje i sjaj bez otežavanja: Poboljšava izgled kose bez teškog sloja. Kome je namenjen? Namenjen je suvoj, oštećenoj i hemijski tretiranoj kosi sa izraženim ispucalim krajevima i gubitkom sjaja. Pogodan je i za kosu koja je izložena čestom stilizovanju i toploti. Zašto volimo GROWUS Damage Therapy Treatment EX? Ovaj tretman je dobar primer balansa između proteinske nege i hidratacije. Ne ostavlja kosu krutom, već zadržava mekoću i fleksibilnost. Tekstura se lako raspoređuje i brzo deluje, bez potrebe za dugim držanjem. Kosa nakon upotrebe deluje zaglađenije i urednije. Posebno je koristan kod ispucalih krajeva i kose bez života. Ne opterećuje vlas i ne ostavlja težak osećaj. Lako se uklapa u redovnu rutinu nege bez komplikacija. Aktivni sastojci Kolagen (niske i visoke molekularne mase) Kolagen u formulama za kosu deluje kao film-formirajući sastojak koji oblaže vlas. Pomaže u zadržavanju vlage i poboljšava elastičnost. Niskomolekularni oblici doprinose boljoj interakciji sa površinom vlasi. Doprinosi zaglađenijem i sjajnijem izgledu kose. Njegovo dejstvo je pretežno površinsko. U ovoj formuli ima ulogu jačanja i zaštite vlasi. Aminokiseline Aminokiseline su osnovni gradivni elementi keratina. Pomažu u obnovi oštećenih delova vlasi. Doprinosi jačanju strukture kose i smanjenju lomljenja. Njihovo dejstvo je usmereno na poboljšanje otpornosti vlasi. Pogodne su za redovnu negu. U ovoj formuli imaju ulogu regeneracije kose. Glicerin Glicerin deluje kao humektant koji privlači vlagu. Pomaže u hidrataciji kose i sprečava isušivanje. Doprinosi mekoći i fleksibilnosti vlasi. Njegovo dejstvo je stabilno i efikasno. Pogodan je za svakodnevnu upotrebu. U ovoj formuli ima osnovnu hidratantnu ulogu. Pantenol Pantenol deluje hidratantno i umirujuće na kosu i vlasište. Pomaže u povećanju elastičnosti i sjaja kose. Doprinosi lakšem raščešljavanju. Njegovo dejstvo je blago i kompatibilno sa svim tipovima kose. Često se koristi u proizvodima za obnovu kose. U ovoj formuli ima ulogu hidratacije i zaštite. Ekstrakt bisera Ekstrakt bisera doprinosi sjaju i zaglađenosti kose. Deluje tako što reflektuje svetlost i poboljšava vizuelni izgled vlasi. Pomaže u postizanju mekšeg i glađeg finiša. Njegovo dejstvo je pretežno estetsko. Pogodan je za proizvode za sjaj. U ovoj formuli ima ulogu poboljšanja izgleda kose. Kokosovo ulje Kokosovo ulje deluje kao emolijens koji omekšava i štiti vlas. Pomaže u smanjenju gubitka proteina iz kose. Doprinosi zaglađenju i sjaju. Njegovo dejstvo je hranljivo i zaštitno. Pogodno je za suvu i oštećenu kosu. U ovoj formuli ima ulogu nege i zaštite vlasi. Dodaj u listu želja Dodaj u listu želja', 'GROWUS Damage Therapy Treatment EX je proteinski tretman za kosu koji kombinuje kolagen, aminokiseline i hidratantne sastojke za obnovu oštećenih vlasi i poboljšanje elastičnosti. Deluje kroz nadoknadu izgubljenih proteina, zaglađivanje kutikule i povećanje mekoće i sjaja kose.', 'https://beauty-health.rs/wp-content/uploads/2026/04/GROWUS-Damage-Therapy-Treatment-EX-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
