INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (7, 12, 'APLB Collagen EGF Peptide Facial Toner', 'aplb-collagen-egf-peptide-facial-toner', 'Ključne prednosti: Obnova i poboljšanje elastičnosti: Doprinosi čvršćem i zategnutijem izgledu kože. Intenzivna hidratacija i osveženje: Pomaže u smanjenju suvoće i vraća koži punoću. Umirivanje i balans kože: Smanjuje iritacije i podržava stabilnu kožnu barijeru. Kome je namenjen? Namenjen je suvoj, dehidriranoj i koži sa znakovima umora i gubitka elastičnosti. Pogodan je i za osetljivu kožu kojoj je potrebna hidratacija i umirujuća nega bez iritirajućih sastojaka. Zašto volimo APLB Collagen EGF Peptide Facial Toner? Ovaj tonik ide korak dalje od klasične hidratacije i uvodi elemente regeneracije u svakodnevnu rutinu. Tekstura je lagana, ali ostavlja osećaj nahranjene kože. Koža nakon nanošenja deluje svežije i elastičnije. Posebno je zanimljiv spoj kolagena i peptida koji ciljaju tonus kože. Ne opterećuje kožu i lako se uklapa sa drugim aktivnim sastojcima. Dobar je izbor kada koži treba dodatni podsticaj bez agresivnih tretmana. Pogodan je za dugoročnu upotrebu kao deo rutine za održavanje kvaliteta kože. Aktivni sastojci Kolagen Kolagen u kozmetici deluje kao humektant i film-formirajući sastojak. Pomaže u zadržavanju vlage na površini kože. Doprinosi vizuelno punijem i zaglađenijem izgledu. Njegovo dejstvo je pretežno površinsko. Pomaže u smanjenju osećaja suvoće. U ovoj formuli ima ulogu hidratacije i poboljšanja teksture. EGF peptid EGF peptid deluje kao signalni molekul koji utiče na regenerativne procese kože. Pomaže u stimulaciji obnove i poboljšanju elastičnosti. Doprinosi ujednačenijem i zdravijem izgledu kože. Njegovo dejstvo je postepeno i zavisi od kontinuiteta upotrebe. Često se koristi u formulacijama za anti-age negu. U ovoj formuli ima ulogu regeneracije kože. Ekstrakt Centella Asiatica i Centella kompleks Centella deluje umirujuće i regenerativno. Pomaže u smanjenju iritacija i jačanju kožne barijere. Doprinosi većoj otpornosti kože na spoljašnje faktore. Njeno dejstvo je blago i stabilno. Pogodna je za osetljivu kožu. U ovoj formuli ima ulogu balansiranja i smirenja kože. Ekstrakt pirinča Ekstrakt pirinča deluje posvetljujuće i hidratantno. Pomaže u ujednačavanju tena i poboljšanju sjaja kože. Doprinosi mekšoj i glađoj teksturi. Njegovo dejstvo je blago i pogodno za svakodnevnu upotrebu. Često se koristi u formulacijama za osveženje kože. U ovoj formuli ima ulogu poboljšanja izgleda tena. Skvalan Skvalan je emolijens koji pomaže u očuvanju hidratacije kože. Deluje tako što smanjuje gubitak vlage. Doprinosi mekoći i elastičnosti kože. Njegovo dejstvo je blago i kompatibilno sa svim tipovima kože. Ne ostavlja težak osećaj. U ovoj formuli ima ulogu podrške barijeri kože. Glicerin Glicerin je humektant koji privlači i vezuje vodu u koži. Pomaže u održavanju hidratacije i smanjenju suvoće. Doprinosi glatkoći i elastičnosti kože. Njegovo dejstvo je stabilno i efikasno. Pogodan je za svakodnevnu upotrebu. U ovoj formuli ima osnovnu hidratantnu ulogu. Dodaj u listu želja Dodaj u listu želja', 'APLB Collagen EGF Peptide Facial Toner je hidratantni i regenerativni tonik sa kompleksom kolagena, EGF peptida i centelle, formulisan za poboljšanje elastičnosti i ujednačavanje teksture kože. Deluje kroz kombinaciju humektanata i signalnih molekula koji podržavaju hidrataciju, obnovu i otpornost kože.', 'https://beauty-health.rs/wp-content/uploads/2026/04/APLB-Collagen-EGF-Peptide-Facial-Toner-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
