INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (12, 132, 'Paula’s Choice CLEAR Pore Normalizing Cleanser', 'paula-s-choice-clear-pore-normalizing-cleanser', 'Ključne prednosti: Otčepljuje pore: Salicilna kiselina pomaže uklanjanju nečistoća koje dovode do nastanka akni. Čisti bez iritacije: Formula je razvijena da ne izaziva crvenilo i zatezanje kože. Osvežavajuća gel tekstura: Ostavlja kožu čistom, laganom i prijatnom. Kome je namenjen? Namenjen je masnoj i kombinovanoj koži, kao i koži sklonoj aknama, mitiserima i proširenim porama. Zašto volimo Paula’s Choice CLEAR Pore Normalizing Cleanser? Ovaj čistač je namenjen koži koja se suočava sa mitiserima, proširenim porama i aknama. Formula kombinuje efikasno čišćenje sa blagim pristupom koji ne narušava barijeru kože. Salicilna kiselina pomaže uklanjanju viška sebuma i nečistoća iz pora. Gel tekstura omogućava temeljno čišćenje uz osećaj svežine. Ne ostavlja tragove niti masni film nakon ispiranja. Redovnom upotrebom koža može izgledati ujednačenije i manje sklona nepravilnostima. Pogodan je za svakodnevnu upotrebu ujutru i uveče. Aktivni sastojci Salicylic Acid (BHA) Salicilna kiselina je beta-hidroksi kiselina koja prodire u pore i pomaže uklanjanju viška sebuma i nečistoća. Doprinosi smanjenju pojave mitisera i akni. Takođe pomaže u blagom uklanjanju mrtvih ćelija sa površine kože. Često se koristi u formulama za problematičnu i masnu kožu. Njeno delovanje doprinosi čistijem i ujednačenijem izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'Paula’s Choice CLEAR Pore Normalizing Cleanser je gel čistač formulisan sa salicilnom kiselinom za kožu sklonu nepravilnostima. Uklanja višak sebuma, nečistoće i ostatke šminke, dok istovremeno pomaže održavanju čistih pora bez isušivanja kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Paulas-Choice-CLEAR-Pore-Normalizing-Cleanser-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
