INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (19, 132, 'Paula&#8217;s Choice 10% Azelaic Acid Booster', 'paulas-choice-10-azelaic-acid-booster', 'Ključne prednosti: Smanjenje nepravilnosti i bubuljica: Deluje na zapušene pore i pomaže u redukciji upalnih promena. Ujednačavanje tena: Doprinosi smanjenju vidljivosti postakne fleka i neujednačenosti. Umirujuće delovanje: Pomaže u smanjenju crvenila i iritacija. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, kao i koži sklonoj aknama, crvenilu i neujednačenom tenu. Posebno odgovara osobama sa postinflamatornim hiperpigmentacijama, sitnim nepravilnostima i reaktivnom kožom. Zašto volimo Paula&#8217;s Choice 10% Azelaic Acid Booster? Ova formula kombinuje više mehanizama delovanja u jednom proizvodu bez agresivnog pristupa. Tekstura je lagana i lako se uklapa u postojeću rutinu, bilo samostalno ili u kombinaciji sa kremom ili serumom. Posebno se ističe po sposobnosti da istovremeno deluje na akne i neujednačen ten. Koža vremenom postaje smirenija, čistija i vizuelno ujednačenija. Dobra tolerancija omogućava redovnu upotrebu bez značajnog rizika od iritacije. Praktičan je izbor za kožu koja zahteva balans između tretmana i umirivanja. Pogodan je i za ciljanu primenu na problematičnim regijama. Aktivni sastojci Azelaična kiselina Azelaična kiselina je višenamenski sastojak koji deluje na više faktora odgovornih za nepravilnosti kože. Ima umirujuće dejstvo i pomaže u smanjenju crvenila i upalnih promena. Takođe utiče na ujednačavanje tena smanjujući vidljivost tamnih mrlja. Deluje antibakterijski i doprinosi čišćenju pora. Njeno delovanje je blago i pogodno za dugoročnu upotrebu. Posebno je korisna kod kože sklone aknama i rosacei. Salicilna kiselina Salicilna kiselina je beta-hidroksi kiselina koja prodire u pore i pomaže u njihovom čišćenju. Deluje tako što rastvara višak sebuma i uklanja mrtve ćelije kože. Pomaže u smanjenju nastanka mitisera i bubuljica. Doprinosi zaglađenijoj teksturi kože i smanjenju nepravilnosti. Njeno delovanje je ciljano na masnu i problematičnu kožu. Redovnom upotrebom poboljšava čistoću i izgled pora. Adenozin Adenozin je sastojak koji ima umirujuće i anti-age delovanje na kožu. Pomaže u smanjenju vidljivosti finih linija i poboljšanju elastičnosti. Deluje tako što podržava energetske procese u ćelijama kože. Doprinosi zaglađenijem i svežijem izgledu kože. Njegovo delovanje je blago i pogodno za svakodnevnu upotrebu. U ovoj formulaciji ima podržavajuću i balansirajuću ulogu. Dodaj u listu želja Dodaj u listu želja', 'Paula&#8217;s Choice 10% Azelaic Acid Booster je lagani tretman koji ciljano deluje na nepravilnosti, crvenilo i neujednačen ten, uz istovremeno umirujuće i balansirajuće dejstvo. Kombinacija azelaične kiseline, salicilne kiseline i adenozina doprinosi smanjenju bubuljica, postakne tragova i poboljšanju ukupne teksture kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Paulas-Choice-10-Azelaic-Acid-Booster-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
