INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (24, 132, 'Paula&#8217;s Choice Skin Perfecting 6% Mandelic Acid + 2% Lactic Acid Liquid Exfoliant', 'paulas-choice-skin-perfecting-6-mandelic-acid-2-lactic-acid-liquid-exfoliant', 'Ključne prednosti: Blaga eksfolijacija bez iritacije: Uklanja mrtve ćelije i poboljšava teksturu uz dobru toleranciju. Ujednačavanje tena: Doprinosi smanjenju neujednačenosti i blagih diskoloracija. Poboljšanje sjaja kože: Podstiče prirodni proces obnove i vraća svež izgled kože. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, kao i koži sklonoj blagim nepravilnostima i neujednačenom tenu. Posebno odgovara osobama koje žele nežniji pristup eksfolijaciji bez agresivnih kiselina. Zašto volimo Paula&#8217;s Choice Skin Perfecting 6% Mandelic Acid + 2% Lactic Acid Liquid Exfoliant? Ova formula predstavlja balans između efikasnosti i blagog pristupa koži. Tekstura je lagana i brzo se upija, bez osećaja težine. Mandelična kiselina deluje sporije i kontrolisanije, što smanjuje rizik od iritacije. Mlečna kiselina dodatno doprinosi hidrataciji i zaglađivanju kože. Koža postepeno postaje mekša, ujednačenija i vizuelno svetlija. Proizvod se lako uklapa u rutinu i pogodan je za dugoročnu upotrebu. Posebno je koristan kao uvod u svet kiselina ili za održavanje rezultata. Aktivni sastojci Mandelična kiselina Mandelična kiselina je alfa-hidroksi kiselina većeg molekula koja sporije prodire u kožu. Zbog toga pruža blagu, ali efikasnu eksfolijaciju uz manji rizik od iritacije. Pomaže u uklanjanju mrtvih ćelija i poboljšanju teksture kože. Doprinosi ujednačavanju tena i smanjenju nepravilnosti. Pogodna je za osetljivu i reaktivnu kožu. Njeno delovanje je postepeno i stabilno. Mlečna kiselina Mlečna kiselina je alfa-hidroksi kiselina koja deluje na površini kože uklanjanjem mrtvih ćelija. Pored eksfolijacije, ima i hidratantna svojstva jer pomaže u zadržavanju vlage. Doprinosi zaglađivanju kože i smanjenju finih linija uzrokovanih dehidratacijom. Pomaže u poboljšanju sjaja i ujednačenosti tena. Njeno delovanje je blago i pogodno za svakodnevnu upotrebu. Često se koristi kod suve i osetljive kože. Dodaj u listu želja Dodaj u listu želja', 'Paula&#8217;s Choice Skin Perfecting 6% Mandelic Acid + 2% Lactic Acid Liquid Exfoliant je blagi tečni eksfolijant koji uklanja mrtve ćelije sa površine kože uz minimalan rizik od iritacije. Kombinacija mandelične i mlečne kiseline doprinosi ujednačavanju tena, zaglađivanju teksture i poboljšanju sjaja kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Paulas-Choice-Skin-Perfecting-6-Mandelic-Acid-2-Lactic-Acid-Liquid-Exfoliant-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
