INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (33, 165, 'Tocobo Collagen Boosting Lip Mask', 'tocobo-collagen-boosting-lip-mask', 'Ključne prednosti: Intenzivna hidratacija i obnova: Maslinovo ulje i zaštitni sloj maske smanjuju suvoću i perutanje usana. Poboljšanje elastičnosti: Fermentisani kolagen doprinosi punijem i zaglađenijem izgledu. Umirivanje i zaštita: Biljni ekstrakti pomažu u smanjenju iritacija i jačanju barijere. Kome je namenjen? Namenjen je svim tipovima usana, posebno suvim, ispucalim i tankim usnama sa izraženim linijama. Pogodan je za svakodnevnu upotrebu kao noćni tretman ili dnevni balzam. Zašto volimo Tocobo Collagen Boosting Lip Mask? Ovaj proizvod pruža kombinaciju intenzivne nege i praktične upotrebe. Tekstura je bogata, ali ne ostavlja lepljiv osećaj, što omogućava prijatan osećaj tokom noći. Formira zaštitni sloj koji pomaže u očuvanju vlage. Usne nakon upotrebe deluju mekše i vizuelno zaglađenije. Može se koristiti i tokom dana kao balzam za dodatnu hidrataciju. Dobar je izbor za rutinu koja cilja obnovu i prevenciju suvoće. Pogodan je za kontinuiranu upotrebu bez opterećenja. Aktivni sastojci Fermentisani kolagen Fermentisani kolagen deluje kao hidratantni i film-formirajući sastojak koji pomaže u zadržavanju vlage. Doprinosi vizuelno punijem i zaglađenijem izgledu usana. Ne prodire duboko, ali poboljšava površinsku teksturu. Pomaže u smanjenju vidljivosti finih linija. Njegovo delovanje je trenutno i podržavajuće. Pogodan je za suve i tanke usne. Maslinovo ulje Maslinovo ulje je emolijens koji omekšava i hrani kožu usana. Deluje tako što formira zaštitni sloj koji sprečava gubitak vlage. Doprinosi smanjenju perutanja i ispucalosti. Pomaže u obnavljanju barijere usana. Njegovo delovanje je negujuće i zaštitno. Pogodno je za suve i osetljive usne. Ekstrakt lavande Ekstrakt lavande ima umirujuće i zaštitno delovanje. Pomaže u smanjenju iritacija i neprijatnog osećaja zatezanja. Doprinosi oporavku kože usana. Njegovo delovanje je blago i pogodno za osetljive usne. Često se koristi u formulacijama za regeneraciju. Doprinosi prijatnom osećaju tokom upotrebe. Dodaj u listu želja Dodaj u listu želja', 'Tocobo Collagen Boosting Lip Mask je noćna maska za usne formulisana za intenzivnu hidrataciju, poboljšanje elastičnosti i zaglađivanje finih linija. Formulacija sa fermentisanim kolagenom, maslinovim uljem i biljnim ekstraktima doprinosi mekšim, punijim i obnovljenim usnama.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Tocobo-Collagen-Boosting-Lip-Mask-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
