INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (34, 164, 'TIRTIR Matcha Skin Toner', 'tirtir-matcha-skin-toner', 'Ključne prednosti: Umirivanje crvenila i osetljivosti: Matcha-PDRN i alantoin pomažu u smanjenju iritacija i reaktivnosti kože. Obnova i jačanje barijere: Fermenti i hidratantni kompleks podržavaju mikrobiom i smanjuju gubitak vlage. Hidratacija i balans pH vrednosti: Blago kiseli pH doprinosi očuvanju prirodne ravnoteže kože. Kome je namenjen? Namenjen je svim tipovima kože, posebno osetljivoj, dehidriranoj i koži sklonoj crvenilu ili narušenoj barijeri. Pogodan je i za kožu koja reaguje na agresivne proizvode ili ima neujednačen ten. Zašto volimo TIRTIR Matcha Skin Toner? Ovaj toner se razlikuje po tome što ne služi samo kao priprema kože, već kao aktivan korak u obnovi barijere. Tekstura je lagana i brzo se upija bez lepljivog osećaja. Posebno je koristan nakon čišćenja kada je koža najosetljivija. Kombinacija polinukleotida i fermenta daje balans između umirenja i hidratacije. Koža nakon upotrebe deluje smirenije i elastičnije. Može se koristiti slojevito za dodatnu hidrataciju bez opterećenja. Dobar je izbor za rutine koje se fokusiraju na obnovu i stabilizaciju kože. Aktivni sastojci Matcha-PDRN Matcha-PDRN (polinukleotidi) deluju kao biološki aktivni molekuli koji podržavaju regeneraciju kože. Doprinosе smanjenju iritacija i poboljšanju opšteg stanja kože. Pomažu u jačanju otpornosti kože na spoljašnje faktore. Njihovo delovanje je umirujuće i obnavljajuće. Koriste se u dermatologiji za regenerativne procese. Pogodni su za osetljivu i reaktivnu kožu. Lactobacillus ferment Lactobacillus ferment je probiotski sastojak koji pomaže u održavanju ravnoteže mikrobioma kože. Deluje tako što podržava prirodnu odbranu kože. Doprinosi smanjenju osetljivosti i jačanju barijere. Pomaže u očuvanju hidratacije. Njegovo delovanje je blago i pogodno za svakodnevnu upotrebu. Pogodan je za kožu sklonu iritacijama. Alantoin Alantoin je umirujući sastojak koji pomaže u smanjenju iritacija i crvenila. Deluje tako što podržava regeneraciju površinskog sloja kože. Doprinosi mekšem i glađem osećaju kože. Pogodan je za osetljivu i oštećenu kožu. Njegovo delovanje je umirujuće i zaštitno. Često se koristi u dermatološkim formulacijama. Soja kompleks Soja kompleks doprinosi hidrataciji i nutritivnoj podršci kože. Deluje tako što pomaže u održavanju nivoa vlage i elastičnosti. Doprinosi ujednačenijem izgledu kože. Njegovo delovanje je blago i podržavajuće. Pogodan je za svakodnevnu upotrebu. Pomaže u očuvanju zdrave strukture kože. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Matcha Skin Toner je blago kiseli toner formulisan za hidrataciju, umirivanje crvenila i obnovu kožne barijere kroz kombinaciju Matcha-PDRN kompleksa i probiotskih sastojaka. Formulacija sa polinukleotidima, fermentima i umirujućim komponentama doprinosi boljoj hidrataciji, smanjenju reaktivnosti i ujednačenijem izgledu kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/TIRTIR-Matcha-Skin-Toner-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
