INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (35, 42, 'CP-1 Bright Complex Heat Protection Serum', 'cp-1-bright-complex-heat-protection-serum', 'Ključne prednosti: Zaštita od toplote: Formira zaštitni sloj koji smanjuje oštećenja pri feniranju i stilizovanju. Obnova i jačanje vlasi: Proteinski kompleks poboljšava elastičnost i otpornost kose. Kontrola frizza i sjaj: Biljna ulja i pantenol zaglađuju vlas i poboljšavaju izgled kose. Kome je namenjen? Namenjen je svim tipovima kose, posebno suvoj, oštećenoj, hemijski tretiranoj i kosi izloženoj čestoj upotrebi toplote. Pogodan je i za tanku kosu jer ne ostavlja težak sloj. Zašto volimo CP-1 Bright Complex Heat Protection Serum? Ovaj serum omogućava jednostavnu zaštitu kose bez komplikovane rutine. Tekstura je lagana i brzo se upija, što olakšava svakodnevnu upotrebu. Posebno je koristan pre stilizovanja jer pomaže u kontroli neposlušne kose. Kombinacija proteina i ulja daje balans između obnove i zaglađivanja. Kosa nakon upotrebe deluje mekše i lakša je za oblikovanje. Može se koristiti i na suvoj kosi za dodatni sjaj i kontrolu frizza. Dobar je izbor za održavanje zdravijeg izgleda kose uz redovno izlaganje toploti. Aktivni sastojci Proteinski kompleks Proteinski kompleks (keratin, svila, pirinač, soja, kolagen) pomaže u jačanju strukture vlasi. Deluje tako što popunjava oštećene delove i poboljšava elastičnost kose. Doprinosi smanjenju lomljenja i ispucalih krajeva. Njegovo delovanje je površinsko ali efikasno. Pogodan je za oštećenu i hemijski tretiranu kosu. Pomaže u poboljšanju otpornosti vlasi. Amino kiseline Amino kiseline su gradivni elementi proteina koji doprinose jačanju kose. Deluju tako što podržavaju strukturu vlasi i poboljšavaju njenu otpornost. Pomažu u očuvanju elastičnosti i fleksibilnosti. Doprinosе zdravijem izgledu kose. Njihovo delovanje je blago i kumulativno. Pogodne su za svakodnevnu upotrebu. Pantenol Pantenol (vitamin B5) deluje kao humektant koji zadržava vlagu u vlasima. Doprinosi hidrataciji i mekoći kose. Pomaže u smanjenju suvoće i krutosti. Daje kosi glatkiji i sjajniji izgled. Njegovo delovanje je trenutno i podržavajuće. Pogodan je za sve tipove kose. Biljna ulja Biljna ulja poput arganovog, bademovog, kokosovog i jojoba ulja hrane i štite kosu. Deluju tako što formiraju zaštitni sloj koji smanjuje gubitak vlage. Doprinosе glatkoći i sjaju kose. Pomažu u kontroli frizza i lakšem raščešljavanju. Njihovo delovanje je negujuće i zaštitno. Pogodna su za suvu i oštećenu kosu. Lecitin Lecitin doprinosi jačanju lipidne barijere vlasi. Deluje tako što pomaže u očuvanju vlage i zaštiti kose od spoljašnjih uticaja. Doprinosi mekšem i glatkijem osećaju kose. Njegovo delovanje je podržavajuće. Pogodan je za oštećenu kosu. Pomaže u održavanju zdravijeg izgleda vlasi. Dodaj u listu želja Dodaj u listu želja', 'CP-1 Bright Complex Heat Protection Serum je lagani serum za kosu koji pruža zaštitu od toplote uz istovremenu hidrataciju i poboljšanje strukture vlasi. Formulacija sa proteinima, aminokiselinama, pantenolom i biljnim uljima doprinosi jačanju kose, smanjenju lomljenja i poboljšanju sjaja bez otežavanja.', 'https://beauty-health.rs/wp-content/uploads/2026/03/CP-1-Bright-Complex-Heat-Protection-Serum-1.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
