INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (39, 51, 'DR.JART+ Cryo Rubber&#x2122; Moisturizing Face Mask', 'dr-jartcryo-rubber-moisturizing-face-mask', 'Ključne prednosti: Intenzivna hidratacija i zadržavanje vlage: Hijaluronska kiselina i zaštitni sloj maske smanjuju transepidermalni gubitak vode. Efekat hlađenja i umirivanja: Gumirana maska snižava temperaturu kože i pomaže kod crvenila i osetljivosti. Poboljšanje teksture i punoće kože: Peptidi i hidratantni kompleks daju zaglađen i svež izgled kože. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i dehidriranu kožu kojoj je potrebna brza obnova hidratacije. Posebno odgovara koži koja deluje umorno, zategnuto ili izloženo spoljašnjim stresorima. Zašto volimo Dr.Jart+ Cryo Rubber&#x2122; Moisturising Mask? Ovaj proizvod donosi kombinaciju tretmana i okluzije koja daje vidljiv rezultat u kratkom vremenu. Prvi korak priprema kožu i unosi visoku koncentraciju hidratantnih sastojaka. Drugi korak zatvara vlagu i pojačava njihovu apsorpciju kroz efekat hlađenja. Koža nakon tretmana deluje punije, mekše i vizuelno zaglađenije. Posebno se ističe osećaj smirenosti koji maska pruža tokom nošenja. Tekstura seruma je lagana i brzo se upija bez opterećenja. Pogodna je kao povremeni tretman kada je koži potrebna brza regeneracija i hidratacija. Aktivni sastojci Hijaluronska kiselina Hijaluronska kiselina je snažan humektant koji vezuje vodu i pomaže u održavanju hidratacije kože. Deluje tako što privlači vlagu i zadržava je u površinskim slojevima kože. Doprinosi povećanju punoće i elastičnosti kože. Pomaže u smanjenju vidljivosti finih linija uzrokovanih dehidratacijom. Njeno delovanje je trenutno i kumulativno. Pogodna je za sve tipove kože, uključujući osetljivu. Peptidi Peptidi su kratki lanci aminokiselina koji učestvuju u održavanju strukture kože. Deluju kao signalne molekule koje podržavaju procese obnove i čvrstine. Doprinosе zaglađenijem i elastičnijem izgledu kože. Njihovo delovanje je blago i pogodno za redovnu upotrebu. U kombinaciji sa hidratantnim sastojcima poboljšavaju ukupni izgled kože. Dugoročno doprinose stabilnijem stanju kože. Ekstrakt algi Ekstrakt algi ima hidratantno i zaštitno delovanje na kožu. Pomaže u smanjenju gubitka vlage i očuvanju hidratacije. Deluje umirujuće i doprinosi smanjenju iritacija. Bogat je mineralima koji podržavaju ravnotežu kože. U formulacijama maski ima ulogu okluzije i zaštite. Doprinosi mekšem i otpornijem izgledu kože. Prebiotski kompleks Prebiotski kompleks pomaže u održavanju ravnoteže mikrobioma kože. Deluje tako što podržava korisne mikroorganizme na površini kože. Doprinosi jačanju prirodne odbrane kože. Može pomoći u smanjenju osetljivosti i reaktivnosti. Njegovo delovanje je blago i pogodno za osetljivu kožu. Dugoročno doprinosi stabilnijem i zdravijem stanju kože. Dodaj u listu želja Dodaj u listu želja', 'Dr.Jart+ Cryo Rubber&#x2122; Moisturising Mask je dvostepeni tretman koji kombinuje ampulu sa hijaluronskom kiselinom i peptidima sa gumiranom maskom za intenzivnu hidrataciju i smanjenje gubitka vode. Formula sa hijaluronskom kiselinom, peptidima i ekstraktom algi doprinosi punijem izgledu kože, umirivanju i vidljivom poboljšanju hidratacije već nakon jedne upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Cryo-Rubber™-Moisturizing-Face-Mask-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
