INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (40, 43, 'd&#8217;Alba Double Serum All In One Multi Balm', 'dalba-double-serum-all-in-one-multi-balm', 'Ključne prednosti: Obnova hidratacije i barijere: Ceramidi i ši puter smanjuju gubitak vlage i štite kožu od isušivanja. Poboljšanje elastičnosti i teksture: Kolagen i antioksidansi doprinose zaglađenijem i punijem izgledu kože. Ujednačen i blistav ten: Vitamin C i glutation vizuelno posvetljuju i daju zdrav sjaj koži. Kome je namenjen? Namenjen je normalnoj, suvoj i zreloj koži kojoj je potrebna dodatna hidratacija, zaštita i poboljšanje elastičnosti. Posebno odgovara koži sa finim linijama, dehidratacijom i gubitkom sjaja. Zašto volimo d&#8217;Alba Double Serum All In One Multi Balm? Ovaj proizvod donosi praktičan pristup nezi kroz kombinaciju dva seruma u jednom pakovanju. Tekstura je čvrsta, ali se pri kontaktu sa kožom topi i lako razmazuje bez osećaja težine. Posebno je koristan kao dodatni sloj hidratacije tokom dana, čak i preko šminke. Formula je osmišljena tako da pruži trenutni efekat zaglađivanja uz postepeno poboljšanje kvaliteta kože. Kompaktno pakovanje omogućava jednostavnu upotrebu na različitim regijama lica i tela. Može se koristiti ciljano na suvim zonama ili finim linijama bez narušavanja ostatka rutine. Dobar je izbor za održavanje hidratacije u uslovima spoljašnjih uticaja i promena temperature. Aktivni sastojci Ekstrakt belog tartufa Ekstrakt belog tartufa je bogat antioksidansima koji pomažu u zaštiti kože od oksidativnog stresa. Deluje tako što podržava neutralizaciju slobodnih radikala koji doprinose prevremenom starenju. U kombinaciji sa vitaminom E formira stabilan antioksidativni kompleks. Doprinosi očuvanju vitalnosti i ujednačenog izgleda kože. Njegovo delovanje je zaštitno i preventivno. Pogodan je za svakodnevnu upotrebu u formulama koje ciljaju znakove starenja. Vitamin E Vitamin E je antioksidans koji pomaže u zaštiti ćelijskih struktura od oštećenja izazvanih spoljašnjim faktorima. Podržava očuvanje hidratacije i smanjuje gubitak vlage iz kože. Deluje umirujuće i doprinosi stabilnosti kožne barijere. U formulacijama često poboljšava toleranciju kože na aktivne sastojke. Doprinosi mekšem i elastičnijem izgledu kože. Njegovo delovanje je podržavajuće i dugoročno. Kolagen Kolagen u topikalnoj formi deluje kao film-former koji pomaže u zadržavanju vlage na površini kože. Doprinosi vizuelno punijem i zaglađenijem izgledu kože. Ne prodire duboko, ali ima važnu ulogu u poboljšanju površinske teksture. Posebno je koristan kod dehidrirane i umorne kože. Pomaže u smanjenju osećaja zatezanja. Doprinosi kratkoročnom i vizuelnom poboljšanju stanja kože. Ceramidi Ceramidi su ključne komponente kožne barijere koje pomažu u očuvanju hidratacije. Deluju tako što popunjavaju prostor između ćelija kože i sprečavaju gubitak vlage. Njihova uloga je posebno važna kod suve i osetljive kože. Doprinosе jačanju otpornosti kože na spoljašnje uticaje. Redovnom upotrebom poboljšavaju stabilnost barijere. Pomažu u smanjenju iritacija i osećaja suvoće. Vitamin C Vitamin C deluje kao antioksidans koji doprinosi ujednačavanju tena i poboljšanju sjaja kože. Pomaže u smanjenju vidljivosti neujednačenosti i beživotnog izgleda. Podržava procese obnove kože i doprinosi svežijem izgledu. Njegovo delovanje je postepeno i kumulativno. U formulacijama sa drugim antioksidansima daje sinergijski efekat. Pogodan je za svakodnevnu upotrebu. Glutation Glutation je antioksidans koji se koristi u formulama za ujednačavanje tena. Deluje tako što pomaže u smanjenju vidljivosti tamnih mrlja i neujednačenosti. Doprinosi svežijem i svetlijem izgledu kože. Njegovo delovanje je blago i pogodno za kontinuiranu upotrebu. Često se koristi u kombinaciji sa vitaminom C. Ima podržavajuću ulogu u formulacijama za posvetljivanje. Dodaj u listu želja Dodaj u listu želja', 'd&#8217;Alba Double Serum All In One Multi Balm je multifunkcionalni balzam sa dualnom strukturom seruma koji kombinuje hidrataciju, elastičnost i ujednačavanje tena kroz odnos 85:15. Formulacija sa ekstraktom belog tartufa, vitaminom E, kolagenom, ceramidima i vitaminom C doprinosi jačanju barijere, zaglađivanju kože i vizuelno blistavijem izgledu.', 'https://beauty-health.rs/wp-content/uploads/2026/03/dAlba-Double-Serum-All-In-One-Multi-Balm-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
