INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (42, 22, 'Beauty Of Joseon Daily Tinted Fluid Sunscreen SPF30 PA+++', 'beauty-of-joseon-daily-tinted-fluid-sunscreen-spf30-pa', 'Ključne prednosti: Ujednačavanje tena: Pruža blagu pokrivnu moć za prirodan izgled kože. Mineralna UV zaštita: Štiti kožu od UVA i UVB zračenja uz nežnu formulu. Balans i hidratacija: Održava kožu hidriranom bez viška sjaja. Kome je namenjen? Namenjen je svim tipovima kože, posebno osetljivoj, normalnoj i mešovitoj koži koja preferira mineralne filtere. Pogodan je za osobe koje žele prirodan izgled bez teškog pudera i dodatnu zaštitu od spoljašnjih uticaja. Zašto volimo Beauty Of Joseon Daily Tinted Fluid Sunscreen SPF30 PA+++? Ovaj proizvod spaja zaštitu, negu i blago ujednačavanje tena u jednom koraku. Tekstura je lagana i lako se razmazuje bez vidljivih prelaza. Završnica je prirodna, bez preteranog sjaja ili suvoće. Mineralni filter čini ga pogodnim i za osetljivu kožu. Koža izgleda svežije i ujednačenije bez efekta težine. Idealan je za svakodnevnu rutinu i brz izlazak iz kuće. Praktičan je izbor za minimaliste u nezi i šminki. Aktivni sastojci Cink oksid (20.90%) Cink oksid je mineralni UV filter koji pruža širokospektralnu zaštitu od UVA i UVB zračenja. Deluje reflektujući štetne zrake sa površine kože. Pogodan je za osetljivu kožu jer ima i blago umirujuće dejstvo. Doprinosi smanjenju crvenila i iritacija. Stabilan je i fotostabilan filter. Neophodan je za svakodnevnu zaštitu kože. Maslinovi lipidi Maslinovi lipidi deluju kao emolijensi koji pomažu u očuvanju hidratacije kože. Doprinosi jačanju kožne barijere i smanjenju gubitka vlage. Poboljšavaju mekoću i elastičnost kože. Njihovo delovanje je hranljivo i zaštitno. Pogodni su za svakodnevnu upotrebu. Podržavaju zdrav izgled kože. Artemisia capillaris ekstrakt Ovaj biljni ekstrakt ima umirujuće i antiinflamatorno dejstvo. Pomaže u smanjenju crvenila i iritacija. Doprinosi balansu kože i njenoj otpornosti na spoljašnje faktore. Njegovo delovanje je blago i pogodno za osetljivu kožu. Često se koristi u formulama za umirivanje. Podržava zdrav izgled kože. Mineralni pigmenti Mineralni pigmenti pružaju blagu pokrivnu moć i ujednačavaju ten. Doprinosi prirodnom izgledu kože bez maska efekta. Omogućavaju lagani “filter” efekat na koži. Njihovo delovanje je vizuelno i trenutno. Ne opterećuju kožu. Pogodni su za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Beauty Of Joseon Daily Tinted Fluid Sunscreen SPF30 PA+++ je tonirani fluid sa zaštitom od sunca koji kombinuje laganu pokrivnu moć, hidrataciju i UV zaštitu u jednom koraku. Formulacija sa cink oksidom, biljnim ekstraktima i lipidima doprinosi zaštiti kože, umirivanju i prirodnom, ujednačenom izgledu tena.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Beauty-Of-Joseon-Daily-Tinted-Fluid-Sunscreen-SPF30-PA-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
