INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (45, 164, 'Tirtir Banana BDRN Eye Serum', 'tirtir-banana-bdrn-eye-serum', 'Ključne prednosti: Osvetljava područje oko očiju: Niacinamid i ekstrakt pasionog voća doprinose ujednačenijem tonu kože. Smanjuje natečenost: Kofein pomaže osvežavanju područja oko očiju i smanjenju vidljivosti podočnjaka. Podrška elastičnosti kože: Adenozin pomaže smanjenju vidljivosti finih linija i poboljšanju izgleda kože. Kome je namenjen? Namenjen je osobama koje primećuju tamnije podočnjake, natečenost ili prve znake umora u području oko očiju. Pogodan je za sve tipove kože. Zašto volimo TIRTIR Banana BDRN Eye Serum? Ovaj serum za područje oko očiju koristi inovativni Banana BDRN sastojak koji se dobija iz kore banana i prirodnih tačkica na plodu. Ovaj pristup omogućava korišćenje aktivnih komponenti iz banana uz smanjenje otpada u proizvodnji. Formula je dopunjena kofeinom i niacinamidom koji doprinose svežijem i ujednačenijem izgledu kože. Ekstrakt pasionog voća pruža dodatnu antioksidativnu podršku i pomaže osvežavanju kože. Adenozin je sastojak koji se često koristi u kozmetici za negu kože sklone borama. Lagana tekstura seruma omogućava brzo upijanje bez osećaja težine na koži. Serum ima suptilan miris banane. Aktivni sastojci Banana BDRN Banana BDRN je patentirani sastojak dobijen iz kore i prirodnih šećernih tačkica banana sa ostrva Jeju. U kozmetičkim formulama koristi se za podršku regeneraciji i ujednačavanju tona kože. Pomaže smanjenju vidljivosti umora u području oko očiju. Takođe doprinosi hidrataciji i poboljšanju elastičnosti kože. Njegova primena u formulama povezana je i sa konceptom održive proizvodnje jer se koristi deo ploda koji bi inače bio otpad. Kafein Kofein je sastojak koji se često koristi u proizvodima za negu područja oko očiju. Pomaže smanjenju vidljivosti natečenosti i podočnjaka. Doprinosi osveženom izgledu kože. Takođe deluje kao antioksidans i pomaže zaštiti kože od spoljašnjih faktora. Njegovo delovanje može doprineti privremenom zatezanju kože oko očiju. Niacinamid Niacinamid je oblik vitamina B3 koji doprinosi ujednačavanju tona kože. Pomaže smanjenju vidljivosti tamnih podočnjaka i neujednačene pigmentacije. Takođe doprinosi jačanju kožne barijere. U kozmetičkim formulama često se koristi zbog svojih umirujućih i balansirajućih svojstava. Redovna upotreba može doprineti zdravijem i svetlijem izgledu kože. Adenozin Adenozin je sastojak koji se koristi u formulama namenjenim koži sklonoj borama. Pomaže smanjenju vidljivosti finih linija i poboljšanju elastičnosti kože. Takođe doprinosi glatkijem izgledu kože. U proizvodima za područje oko očiju često se koristi za podršku anti-age nezi. Passion Fruit Extract Ekstrakt pasionog voća sadrži antioksidanse koji pomažu zaštiti kože od spoljašnjih uticaja. Doprinosi osveženju i hidrataciji kože. Takođe može pomoći u poboljšanju izgleda tamnih podočnjaka. U formulama za negu područja oko očiju koristi se za podršku blistavijem izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Banana BDRN Eye Serum je serum za područje oko očiju formulisan sa inovativnim Banana BDRN sastojkom dobijenim iz banana sa ostrva Jeju. Pomaže osvežavanju umornog izgleda područja oko očiju, doprinosi ujednačenijem tonu kože i hidrataciji.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Tirtir-Banana-BDRN-Eye-Serum-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
