INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (46, 151, 'Shiseido Professional Sublimic Luminoforce Mask Colored Hair', 'shiseido-professional-sublimic-luminoforce-mask-colored-hair', 'Ključne prednosti: Očuvanje intenziteta boje: Pomaže usporavanju promene nijanse i održava svež izgled farbane kose. Dubinska hidratacija: Formula pruža veću hidrataciju u poređenju sa klasičnim tretmanima za kosu. Sjaj i mekoća kose: Doprinosi glatkoj teksturi i zdravom sjaju farbane kose. Kome je namenjena? Namenjena je osobama sa farbanom kosom koje žele da očuvaju intenzitet boje i poboljšaju sjaj kose. Posebno je pogodna za kosu koja nakon farbanja deluje suvo, kruto ili bez sjaja. Zašto volimo Shiseido Professional Sublimic Luminoforce Mask Colored Hair? Ova maska razvijena je za kosu koja je izložena čestim hemijskim tretmanima poput farbanja. Formula pomaže očuvanju intenziteta boje i smanjenju pojave neželjenog posvetljivanja ili promene tona. Aktivni sastojci pomažu obnovi strukture vlasi i pružaju dubinsku hidrataciju. Redovnom upotrebom kosa može izgledati mekše, glatkije i sjajnije. Maska pomaže smanjenju osećaja krutosti i suvoće koji se mogu javiti nakon ponovljenih farbanja. Tekstura omogućava lako nanošenje i ravnomerno raspoređivanje po dužini kose. Miris je inspirisan luksuznim notama retkih ruža. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Professional Sublimic Luminoforce Mask Colored Hair je maska za negu farbane kose razvijena kako bi pomogla očuvanju intenziteta boje i poboljšanju sjaja kose. Pruža intenzivnu hidrataciju i pomaže kosi da zadrži mekoću i elastičnost nakon farbanja.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Shiseido-Professional-Sublimic-Luminoforce-Mask-Colored-Hair-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
