INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (47, 151, 'Shiseido Professional Sublimic AdenoVital Hair Mask Thinning Hair', 'shiseido-professional-sublimic-adenovital-hair-mask-thinning-hair', 'Ključne prednosti: Povećanje volumena i elastičnosti kose: Formula pomaže kosi da izgleda punije i otpornije. Obnova oštećene kose: Aktivni sastojci pomažu popunjavanju strukture vlasi i smanjenju oštećenja. Negovana i sjajna kosa: Maska oblaže vlasi i pomaže postizanju glatkog i sjajnog izgleda. Kome je namenjena? Namenjena je osobama koje primećuju proređivanje kose, gubitak volumena ili oštećenja vlasi. Pogodna je za kosu koja deluje beživotno, slabo ili bez elastičnosti. Zašto volimo Shiseido Professional Sublimic AdenoVital Hair Mask Thinning Hair? Ova maska razvijena je kao intenzivan tretman za kosu koja pokazuje znakove slabljenja, gubitka volumena ili oštećenja. Formula deluje na vlasište, koren i dužinu kose kako bi pružila celovitu negu. Aktivni sastojci pomažu popunjavanju strukture vlasi i obnovi oštećenja iznutra. Istovremeno maska oblaže površinu vlasi i doprinosi glatkom i sjajnom izgledu kose. Redovnom upotrebom kosa može izgledati elastičnije i punije. Tekstura omogućava lako raspoređivanje po dužini kose bez otežavanja. Miris je kombinacija eukaliptusa, biljnih nota i slatke narandže. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Professional Sublimic AdenoVital Hair Mask Thinning Hair je maska za kosu razvijena za negu vlasišta, korena i dužine kose kako bi pomogla postizanju punijeg i elastičnijeg izgleda kose. Pomaže obnovi oštećene kose, poboljšava njen volumen i daje joj zdrav sjaj.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Shiseido-Professional-Sublimic-AdenoVital-Hair-Mask-Thinning-Hair.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
