INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (51, 143, 'Round Lab Camellia Deep Collagen Firming Sun Serum SPF50+ PA++++', 'round-lab-camellia-deep-collagen-firming-sun-serum', 'Ključne prednosti: Visoka zaštita od UV zračenja: SPF50+ PA++++ pomaže zaštiti kože od štetnog UVA i UVB zračenja. Poboljšanje elastičnosti kože: Kompleks kolagena i Camellia Collagenol&#x2122; pomažu koži da izgleda čvršće i punije. Osvežavajući efekat: Mikro rashlađujuće kapsule doprinose prijatnom osećaju hlađenja na koži. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu kožu kojoj je potrebna visoka zaštita od sunca uz dodatnu negu i hidrataciju. Zašto volimo Round Lab Camellia Deep Collagen Firming Sun Serum? Ovaj proizvod razvijen je kao kombinacija zaštite od sunca i aktivne nege kože. Lagana serum tekstura brzo se upija i ne ostavlja mastan trag. Mikro rashlađujuće kapsule pomažu smanjenju osećaja toplote na koži tokom izlaganja suncu. Camellia Collagenol&#x2122; kompleks sadrži ekstrakt kamelije i kolagenske sastojke koji doprinose elastičnosti kože. HPR retinoid pomaže poboljšanju izgleda pora i tonusa kože. Antioksidativni sastojci doprinose zaštiti kože od spoljašnjih faktora. Završnica je blago sjajna i može delovati kao podloga za šminku. Redovnom upotrebom koža može izgledati hidriranije, elastičnije i zaštićenije. Aktivni sastojci Camellia Collagenol&#x2122; Camellia Collagenol&#x2122; je kompleks koji kombinuje ekstrakt kamelije, kvercetin i kolagenske sastojke. Ekstrakt kamelije poznat je po antioksidativnim svojstvima. Pomaže zaštiti kože od spoljašnjih stresora. Kolagenski sastojci doprinose elastičnosti i punijem izgledu kože. Kvercetin dodatno podržava antioksidativnu zaštitu. Ovaj kompleks pomaže održavanju čvršćeg i zdravijeg izgleda kože. Low Molecular Collagen Kolagen niske molekulske mase koristi se za poboljšanje hidratacije i elastičnosti kože. Manja molekulska struktura omogućava lakšu interakciju sa površinom kože. Pomaže održavanju mekoće i elastičnosti kože. Takođe doprinosi punijem izgledu kože. Često se koristi u formulama namenjenim koži koja pokazuje znakove starenja. U ovom serumu ima ulogu podrške elastičnosti kože. HPR (Hydroxypinacolone Retinoate) HPR je derivat retinoične kiseline koji se koristi u kozmetičkim formulama za poboljšanje izgleda kože. Pomaže u poboljšanju teksture i tonusa kože. Takođe može doprineti smanjenju vidljivosti pora. Njegovo delovanje je blaže u poređenju sa nekim drugim retinoidima. Često se koristi u formulama za poboljšanje elastičnosti kože. U ovoj formuli ima ulogu podrške čvršćem i ujednačenijem izgledu kože. Micro-Cooling Capsules Mikro rashlađujuće kapsule razvijene su kako bi pružile osvežavajući efekat na koži. Pomažu smanjenju osećaja toplote tokom izlaganja suncu. Takođe doprinose prijatnijem osećaju tokom nanošenja proizvoda. Njihova funkcija je povećanje komfora kože. Posebno su korisne tokom toplih dana. U ovoj formuli imaju ulogu osvežavanja kože. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Camellia Deep Collagen Firming Sun Serum je zaštitni serum koji kombinuje negu kože i visoku UV zaštitu u jednoj formuli. Pruža SPF50+ PA++++ zaštitu uz sastojke koji pomažu hidrataciji, elastičnosti i osvežavajućem osećaju na koži.', 'https://beauty-health.rs/wp-content/uploads/2026/03/ROUND-LAB-SUN-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
