INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (56, 118, 'Missha Magic Cushion Cover Lasting', 'missha-magic-cushion-cover-lasting', 'Ključne prednosti: Dugotrajna pokrivenost: Formula pruža stabilnu pokrivnu moć i pomaže da makeup ostane postojan tokom dana. Prirodan polu-mat završetak: Tekstura ostavlja kožu ujednačenom bez osećaja suvoće. Zaštita od sunca: SPF50+ PA+++ pomaže zaštiti kože od štetnog UV zračenja. Kome je namenjen? Namenjen je osobama koje žele cushion puder sa dobrom pokrivnom moći i dugotrajnom postojanošću. Pogodan je za normalnu, mešovitu i masnu kožu koja zahteva ujednačen ten bez težine na koži. Zašto volimo Missha Magic Cushion Cover Lasting? Ovaj cushion puder razvijen je za osobe koje žele dobru pokrivenost uz prirodan izgled kože. Lagana formula se ravnomerno raspoređuje po koži i pomaže prikrivanju nepravilnosti. Tečna tekstura prilagođava se koži i stvara ujednačen ten. Završnica je polu-mat, pa koža izgleda sveže bez izraženog sjaja. Formula je osmišljena da pruži dugotrajan efekat i stabilnost tokom dana. Biljni ekstrakti u sastavu doprinose prijatnom osećaju hidratacije na koži. Redovnim korišćenjem makeup može izgledati uredno i prirodno tokom celog dana. Dostupne nijanse No.21 Neutral Light Beige Svetlija nijansa sa neutralnim podtonom pogodna za svetliji ten. No.23 Neutral Medium Beige Srednje svetla nijansa namenjena prirodnom i blago tamnijem tonu kože. Dodaj u listu želja Dodaj u listu želja', 'Missha Magic Cushion Cover Lasting je puder u jastučiću koji pruža visoku pokrivnu moć uz lagan osećaj na koži i polu-mat završnicu. Kombinuje dugotrajnu postojanost, zaštitu od sunca SPF50+ PA+++ i formulu koja se ravnomerno prilagođava koži.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Missha-Magic-Cushion-Cover-Lasting-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
