INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (58, 118, 'Missha 4D Mascara', 'missha-4d-mascara', 'Ključne prednosti: Precizno razdvajanje trepavica: 4D četkica pomaže da svaka trepavica bude jasno definisana i podignuta. Volumen bez grudvica: Formula sa biljnim voskom omogućava glatko nanošenje bez slepljivanja. Dugotrajno nošenje: Vodootporni zaštitni film pomaže sprečavanju razmazivanja tokom dana. Kome je namenjena? Namenjena je osobama koje žele definisane i voluminozne trepavice bez slepljivanja. Pogodna je za svakodnevni makeup i za osobe koje preferiraju prirodan, ali naglašen izgled trepavica. Zašto volimo Missha 4D Mascara? Ova maskara razvijena je sa ciljem da pruži čist i prirodan volumen uz preciznu definiciju trepavica. Četkica kvadratnog oblika omogućava zahvatanje svake trepavice od korena do vrha. Na taj način trepavice se ravnomerno oblažu pigmentom i izgledaju gušće i definisanije. Formula sa biljnim voskom pomaže da aplikacija bude glatka i ravnomerna. Zaštitni film koji se formira oko trepavica doprinosi dugotrajnijem efektu i smanjuje razmazivanje. Tekstura omogućava nanošenje više slojeva bez grudvica. Rezultat su trepavice koje izgledaju podignuto, uredno i naglašeno. Dodaj u listu želja Dodaj u listu želja', 'Missha 4D Mascara je maskara osmišljena da pruži čist volumen i definiciju svakoj trepavici bez slepljivanja. Missha 4D Mascara koristi četkicu specijalnog oblika i formulu sa biljnim voskom kako bi omogućila ravnomerno nanošenje i dugotrajan efekat.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Missha-4D-Mascara-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
