INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (59, 114, 'Medicube Pore Brush', 'medicube-pore-brush', 'Ključne prednosti: Temeljno čišćenje pora: Silikonske dlačice pomažu uklanjanju sebuma, nečistoća i ostataka iz pora. Precizno čišćenje problematičnih regija: Manji nastavak omogućava ciljano čišćenje nosa, brade i drugih delova lica. Višenamenski alat za negu kože: Može se koristiti za masažu kože, čišćenje pora i ravnomerno nanošenje maski. Kome je namenjen? Namenjen je osobama koje žele temeljno čišćenje pora i uklanjanje viška sebuma. Pogodan je za sve tipove kože, posebno za kožu sklonu proširenim porama, miteserima i nečistoćama. Zašto volimo Medicube Pore Brush? Ovaj alat razvijen je kao praktično rešenje za detaljno čišćenje kože tokom svakodnevne rutine. Mekane silikonske dlačice nežno uklanjaju višak sebuma i nečistoće iz pora. Širi nastavak pogodan je za čišćenje većih površina lica poput čela ili obraza. Manji nastavak omogućava preciznije čišćenje regija kao što su nos i brada. Treća površina može se koristiti za blagu masažu kože tokom čišćenja. Spatula vrh omogućava higijensko nanošenje maski ili sredstava za čišćenje. Redovnom upotrebom koža može izgledati čistije, glađe i ujednačenije. Dodaj u listu želja Dodaj u listu želja', 'Medicube Pore Brush je multifunkcionalni alat za čišćenje kože koji pomaže temeljnom uklanjanju sebuma, nečistoća i ostataka iz pora. Medicube Pore Brush ima trostrani silikonski nastavak i dodatni spatula vrh koji omogućavaju precizno čišćenje, masažu i ravnomerno nanošenje proizvoda za negu kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Medicube-Pore-Brush-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
