INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (63, 104, 'Laneige Glaze Craze Tinted Lip Serum', 'laneige-glaze-craze-tinted-lip-serum', 'Ključne prednosti: Intenzivna hidratacija usana: Poliglutaminska kiselina i hidratantni kompleks pomažu zadržavanju vlage do 12 sati. Vizuelno punije i glađe usne: Peptidi doprinose elastičnijem izgledu usana i smanjenju finih linija. Visoki sjaj sa blagom bojom: Lagana formula stvara „glazed“ efekat uz prirodno nadogradivu pigmentaciju. Kome je namenjen? Namenjen je svim tipovima usana, posebno usnama koje su sklone suvoći, perutanju i gubitku punoće. Pogodan je za osobe koje žele kombinaciju balzama, seruma i sjajnog lip proizvoda. https://www.youtube.com/watch?v=QliYn_9EJsU Zašto volimo Laneige Glaze Craze Tinted Lip Serum? Ovaj proizvod razvijen je kao spoj dekorativnog proizvoda i nege usana. Formula bogata hidratantnim sastojcima pomaže obnovi i zaštiti prirodne barijere usana. Lagana kremasta tekstura lako klizi po usnama i ravnomerno raspoređuje pigment. Reflektujući film daje izražen sjaj i vizuelno puniji izgled usana. Donut aplikator omogućava ravnomerno nanošenje proizvoda i prijatan osećaj tokom aplikacije. Boja je nadogradiva, pa se može postići suptilan ili izraženiji efekat. Redovnom upotrebom usne mogu izgledati glađe, hidriranije i zdravije. Aktivni sastojci Polipeptidi Peptidi su kratki lanci aminokiselina koji se koriste u formulama za negu kože i usana. U proizvodima za usne pomažu zaglađivanju površine i poboljšanju elastičnosti. Takođe doprinose vizuelno punijem izgledu usana. Njihovo delovanje je postepeno i zasniva se na redovnoj upotrebi proizvoda. Peptidi mogu pomoći smanjenju vidljivosti finih linija na usnama. U ovoj formuli imaju ulogu podrške elastičnosti i punoći usana. Ceramidi Ceramidi su lipidi koji čine važan deo zaštitne barijere kože i usana. U kozmetičkim formulama pomažu očuvanju vlage i sprečavanju dehidratacije. Argan ceramidi dodatno doprinose omekšavanju i zaštiti usana. Oni pomažu stabilnosti površinskog sloja kože. Takođe smanjuju osećaj suvoće i perutanja. U ovom proizvodu imaju važnu ulogu u zaštiti barijere usana. Poliglutaminska kiselina Poliglutaminska kiselina je snažan humektant koji pomaže vezivanju vode u koži. Može zadržati velike količine vlage i time doprinosi intenzivnoj hidrataciji. Pomaže da usne izgledaju punije i glađe. Takođe doprinosi smanjenju transepidermalnog gubitka vode. Njena sposobnost zadržavanja vlage pomaže dugotrajnoj hidrataciji usana. U ovoj formuli ima ključnu ulogu u održavanju vlažnosti. Skvalan Skvalan je lipid koji omekšava i zaglađuje površinu usana. Pomaže u smanjenju gubitka vlage i povećava komfor tokom nošenja proizvoda. Njegova lagana tekstura omogućava brzo upijanje bez masnog osećaja. Takođe poboljšava klizanje proizvoda tokom nanošenja. Skvalan doprinosi mekoći i fleksibilnosti usana. U ovoj formuli ima ulogu hidratacije i zaštite. Dodaj u listu želja Dodaj u listu želja', 'Laneige Glaze Craze Tinted Lip Serum je hidratantni serum za usne sa blagom bojom koji kombinuje negu usana i visok sjaj u jednoj formuli. Laneige Glaze Craze Tinted Lip Serum sadrži čak 95% sastojaka za negu kože, uključujući peptide, ceramide i poliglutaminsku kiselinu koji pomažu hidrataciji i zaštiti barijere usana.', 'https://beauty-health.rs/wp-content/uploads/2026/03/categoryslider_glazecraze_peach_95c1db9e-e0d9-4f31-b07d-581a0f14dc2c.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
