INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (65, 90, 'Jumiso Niacinamide 5+ Overnight Cream', 'jumiso-niacinamide-5-overnight-cream', 'Ključne prednosti: Ujednačavanje tena i smanjenje hiperpigmentacija: Niacinamid i traneksaminska kiselina pomažu smanjenju vidljivosti fleka i post-akni tragova. Obnova i jačanje kožne barijere: Ceramidi i pantenol doprinose stabilnosti zaštitne barijere kože. Prilagodljiva hidratacija: Gel i kapsule mogu se mešati u različitim odnosima u zavisnosti od tipa kože. Kome je namenjen? Namenjena je svim tipovima kože, posebno koži sa hiperpigmentacijama, post-akni tragovima i neujednačenim tenom. Pogodna je i za osetljivu kožu kojoj je potrebna hidratacija i podrška obnovi barijere. Zašto volimo Jumiso Niacinamide 5+ Overnight Cream? Ova noćna krema razvijena je kao kombinacija hidratantnog gela i kapsula sa aktivnim sastojcima. Kapsule oslobađaju sastojke tokom nanošenja i omogućavaju kontrolu količine hidratacije. Lagana tekstura omogućava koži da zadrži vlagu bez osećaja težine. Aktivni sastojci usmereni su na ujednačavanje tona kože i poboljšanje njene teksture. Ceramidi pomažu obnovi kožne barijere, dok hidratantni sastojci doprinose punijem i mekšem izgledu kože. Redovnom upotrebom koža može izgledati ujednačenije i glađe. Formula je razvijena bez parabena, alkohola, sulfata i veštačkih mirisa, što je čini pogodnom i za osetljivu kožu. Aktivni sastojci Niacinamid Niacinamid je oblik vitamina B3 koji doprinosi ujednačavanju tona kože i jačanju kožne barijere. Pomaže smanjenju vidljivosti diskoloracija i nepravilnosti. Takođe doprinosi regulaciji lučenja sebuma i stabilnosti kože. Njegovo antiinflamatorno delovanje može pomoći kod crvenila i iritacija. Redovnom upotrebom koža može izgledati ujednačenije i zdravije. U ovoj formuli ima ključnu ulogu u poboljšanju izgleda tena. Traneksaminska kiselina Traneksaminska kiselina koristi se u formulama za negu kože usmerenim na hiperpigmentacije. Deluje na procese povezane sa stvaranjem melanina. Time može pomoći u smanjenju vidljivosti fleka i post-akni tragova. Takođe doprinosi ujednačavanju tona kože. Njeno delovanje je postepeno i zahteva redovnu upotrebu proizvoda. U ovoj formuli ima ulogu podrške posvetljivanju tena. Ceramides Ceramidi su lipidi koji su prirodno prisutni u kožnoj barijeri. Oni pomažu u očuvanju integriteta zaštitnog sloja kože. Njihova funkcija je sprečavanje gubitka vlage i zaštita od spoljašnjih iritansa. Kada se dodaju u kozmetičke formulacije, doprinose obnovi oštećene barijere. Takođe pomažu u smanjenju osećaja suvoće i zatezanja. U ovoj kremi imaju ključnu ulogu u hidrataciji i zaštiti kože. Pantenol Pantenol je provitamin B5 poznat po umirujućim i hidratantnim svojstvima. Pomaže smanjenju iritacija i crvenila. Takođe doprinosi obnovi kožne barijere i zadržavanju vlage. Njegova sposobnost vezivanja vode pomaže koži da ostane mekša i elastičnija. Često se koristi u formulama namenjenim osetljivoj koži. U ovoj kremi ima ulogu umirenja i hidratacije. Skvalan Skvalan je lipid koji imitira prirodne komponente sebuma kože. Pomaže u sprečavanju gubitka vlage i povećava mekoću kože. Njegova lagana tekstura omogućava brzo upijanje bez masnog osećaja. Skvalan doprinosi fleksibilnosti i prijatnom osećaju na koži. Takođe pomaže stabilizaciji kožne barijere. U ovoj formuli ima ulogu dodatne hidratacije i zaštite kože. Dodaj u listu želja Dodaj u listu želja', 'Jumiso Niacinamide 5+ Overnight Cream je noćna krema formulisanа za ujednačavanje tena, hidrataciju i podršku regeneraciji kože tokom noći. Kombinuje niacinamid, traneksaminsku kiselinu, ceramide i pantenol u jedinstvenoj kapsulnoj teksturi koja omogućava prilagođavanje hidratacije različitim tipovima kože.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Jumiso-Niacinamide-5-Overnight-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
