INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (67, 87, 'Joocyee Pinky Shade Velvet Rouge', 'joocyee-pinky-shade-velvet-rouge', 'Ključne prednosti: Baršunasti mat efekat: Tekstura stvara mekan, zamućen mat završetak bez naglašavanja linija usana. Lagani osećaj na usnama: Formula je osmišljena da pruži mat izgled uz komfor tokom nošenja. Stabilna i ravnomerna pigmentacija: Pigmenti pružaju izraženu boju bez razmazivanja. Kome je namenjen? Namenjen je svim tipovima usana, posebno osobama koje žele mat završetak bez izraženog osećaja suvoće. Pogodan je za ljubitelje prirodnih pink i crvenih nijansi koje naglašavaju prirodan izgled usana. Zašto volimo Joocyee Pinky Shade Velvet Rouge? Ovaj ruž razvijen je kao balans između mat pigmentacije i prijatne teksture koja ne isušuje usne. Balzamasta baza omogućava da pigment klizi ravnomerno i prilagodi se površini usana. Baršunasti završetak vizuelno zaglađuje teksturu usana i stvara suptilan blur efekat. Formula je lagana i omogućava komfor tokom celog dana. Pigmentacija je izražena, ali nijanse imaju nižu zasićenost kako bi izgledale prirodnije na usnama. Boja ostaje stabilna bez razmazivanja tokom nošenja. Rezultat su glatke, definisane i baršunasto mat usne. Aktivni sastojci Emolijentna ulja Emolijentna ulja koriste se u formulama za ruževe kako bi omekšala površinu usana. Pomažu ravnomernom nanošenju pigmenta. Takođe doprinose prijatnom osećaju tokom nošenja proizvoda. Njihova uloga je da smanje osećaj suvoće koji se često javlja kod mat formula. Ulja pomažu stabilnosti teksture ruža. U ovoj formuli imaju ulogu komfora i zaglađivanja usana. Mat pigmentni kompleks Pigmentni kompleks obezbeđuje intenzivnu boju uz kontrolisani mat završetak. Pigmenti su ravnomerno raspoređeni kako bi prekrili površinu usana bez stvaranja grudvica. Njihova struktura omogućava postizanje blur efekta na usnama. Takođe doprinose stabilnosti boje tokom nošenja. Ovaj kompleks omogućava visoku reprodukciju boje uz prirodniji izgled. U ovoj formuli ima ključnu ulogu u pigmentaciji ruža. Film-formirajući sastojci Film-formirajući sastojci stvaraju tanak sloj na površini usana. Ovaj sloj pomaže stabilnosti pigmenta i smanjuje razmazivanje. Takođe doprinosi dugotrajnijem zadržavanju ruža na usnama. Film omogućava ravnomerno raspoređivanje pigmenta. Time se postiže stabilan i ujednačen završetak. U ovoj formuli imaju ulogu dugotrajnosti i stabilnosti proizvoda. Dodaj u listu želja Dodaj u listu želja', 'Joocyee Pinky Shade Velvet Rouge je baršunasti mat ruž za usne koji pruža intenzivnu boju uz lagani osećaj na usnama. Kremasto-balzamasta tekstura omogućava ravnomerno nanošenje pigmenta i stvara mekan, velvety završetak bez naglašene suvoće.', 'https://beauty-health.rs/wp-content/uploads/2026/03/T4284_eaa5086c-64c4-4cd0-8c4b-1eef3ffcfa0a.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
