INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (69, 87, 'Joocyee Moisturized Long-Lasting Glazed Rouge', 'joocyee-moisturized-long-lasting-glazed-rouge', 'Ključne prednosti: Dugotrajan sjaj i stabilnost boje: Inovativna oil-film tehnologija formira zaštitni sloj koji pomaže zadržavanju pigmenta. Hidratacija i zaštita usana: Skvalan i tokoferol doprinose mekoći i sprečavaju isušivanje usana. Prirodan MLBB efekat: Nijanse su osmišljene da naglase prirodnu boju usana uz suptilan sjaj. Kome je namenjen? Namenjen je svim tipovima usana koje traže kombinaciju sjaja, hidratacije i prirodne boje. Posebno je pogodan za osobe koje vole MLBB nijanse i prirodan izgled šminke. Zašto volimo Joocyee Moisturized Long-Lasting Glazed Rouge? Ovaj ruž razvijen je kao kombinacija hidratantnog balzama i sjajnog ruža koji pruža prirodan, ali izražen izgled usana. Kremasta tekstura lako klizi po usnama i ravnomerno raspoređuje pigment bez osećaja težine. Oil-film tehnologija formira tanak zaštitni sloj koji pomaže stabilnosti boje i smanjuje razmazivanje. Lagana struktura omogućava komfor tokom celog dana. Sjaj reflektuje svetlost i doprinosi vizuelno punijem izgledu usana. Formula je prilagođena svakodnevnom nošenju i lako se uklapa u različite makeup stilove. Rezultat su glatke, hidrirane i prirodno naglašene usne. Aktivni sastojci Skvalan Skvalan je lipid koji je kompatibilan sa prirodnim lipidima kože. U formulama za usne deluje kao emolijens koji omekšava i zaglađuje površinu usana. Pomaže u smanjenju transepidermalnog gubitka vode. Time doprinosi dugotrajnijoj hidrataciji i komforu. Takođe poboljšava klizanje proizvoda tokom nanošenja. U ovoj formuli ima ulogu hidratacije i zaštite usana. Vitamin E Tokoferol je antioksidans koji se često koristi u proizvodima za negu usana. Pomaže u zaštiti kože od oksidativnog stresa. Takođe doprinosi očuvanju mekoće i elastičnosti usana. Njegova emolijentna svojstva pomažu u smanjenju osećaja suvoće. U kozmetičkim formulama često se koristi za povećanje komfora tokom nošenja proizvoda. U ovoj formuli ima ulogu hidratacije i zaštite usana. Film-formirajući polimeri Film-formirajući sastojci stvaraju tanak sloj na površini usana. Ovaj sloj pomaže stabilnosti pigmenta i sjaja. Takođe doprinosi smanjenju prenosa boje i razmazivanja. Refleksija svetlosti na ovom sloju doprinosi izraženom sjaju. Film omogućava ravnomerno raspoređivanje pigmenta. U ovoj formuli imaju ključnu ulogu u dugotrajnosti proizvoda. Dodaj u listu želja Dodaj u listu želja', 'Joocyee Moisturized Long-Lasting Glazed Rouge je hidratantni sjajni ruž za usne koji pruža prirodan MLBB efekat uz dugotrajan sjaj i stabilnu boju. Kremasta formula obogaćena je skvalanom i tokoferolom kako bi usne ostale mekane, hidrirane i vizuelno punije tokom nošenja.', 'https://beauty-health.rs/wp-content/uploads/2026/03/JOOCYEE-lucent-glazed-rouge-light-linen_1024x1024.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
