INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (70, 87, 'Joocyee Lucent Glazed Rouge', 'joocyee-lucent-glazed-rouge', 'Ključne prednosti: Izražen staklasti sjaj: Diamond light-transmitting film reflektuje svetlost i naglašava volumen usana. Lagani hidratantni sloj: Formula sa visokim udelom ulja pruža komfor i mekoću tokom nošenja. Stabilnost boje i sjaja: Film-formirajuća tehnologija pomaže da se pigment zadrži bez razmazivanja. Kome je namenjen? Namenjen je svim tipovima usana, posebno usnama koje su sklone suvoći ili naglašenim linijama. Pogodan je za osobe koje žele kombinaciju hidratantnog ruža i visokog sjaja uz prirodan ili intenzivniji efekat boje. Zašto volimo Joocyee Lucent Glazed Rouge? Ovaj ruž razvijen je da kombinuje intenzivan sjaj i lagani osećaj na usnama. Visok udeo uljane esencije doprinosi glatkom nanošenju i prijatnom osećaju bez lepljivosti. Diamond light-transmitting film stvara refleks svetlosti koji daje usnama kristalni, gotovo staklasti izgled. Tekstura je vrlo tanka i omogućava ravnomerno raspoređivanje pigmenta bez naglašavanja linija na usnama. Boja je postepeno nadogradiva, pa se može postići suptilan ili izraženiji efekat. Ulje bergamota doprinosi osvežavajućem osećaju i dodatnoj hidrataciji. Rezultat su glatke, hidrirane i sjajne usne sa prirodnim refleksom svetlosti. Aktivni sastojci Bergamot Orange Oil Ulje bergamota je biljni sastojak poznat po osvežavajućim i aromatičnim svojstvima. U kozmetičkim formulama može doprineti prijatnom osećaju na koži i usnama. Takođe ima blago umirujuće delovanje. U proizvodima za usne koristi se kao deo emolijentne baze. Pomaže omekšavanju površine usana i poboljšava komfor tokom nošenja. U ovoj formuli ima ulogu hidratacije i senzornog efekta. Film-formirajući polimeri Film-formirajući sastojci stvaraju tanak sloj na površini usana. Ovaj sloj pomaže stabilnosti pigmenta i sjaja. Takođe smanjuje razmazivanje proizvoda tokom dana. Refleksija svetlosti na ovom sloju doprinosi izraženom sjaju. Film omogućava ravnomerno raspoređivanje pigmenta. U ovoj formuli ima ključnu ulogu u dugotrajnosti i vizuelnom efektu. Emolijentna ulja Emolijentna ulja su sastojci koji pomažu omekšavanju i zaglađivanju usana. Pomažu u zadržavanju vlage i smanjenju osećaja suvoće. Takođe poboljšavaju klizanje proizvoda tokom nanošenja. Njihova lagana tekstura doprinosi prijatnom osećaju na usnama. Ova ulja stvaraju zaštitni sloj koji pomaže stabilnosti formule. U ovom ružu imaju ulogu hidratacije i komfora. Dodaj u listu želja Dodaj u listu želja', 'Joocyee Lucent Glazed Rouge je sjajni ruž za usne koji pruža intenzivan, „glazed“ efekat sa izraženim refleksom svetlosti i laganom teksturom. Formula sa visokim udelom uljane esencije i dodatkom ulja bergamota pomaže da usne izgledaju glatko, hidrirano i vizuelno punije.', 'https://beauty-health.rs/wp-content/uploads/2026/03/JOOCYEE-lucent-glazed-rouge-hover_1024x1024.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
