INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (71, 87, 'Joocyee Long-Lasting Glossy Rouge', 'joocyee-long-lasting-glossy-rouge', 'Ključne prednosti: Glass-sjaj i efekat punijih usana: Specijalna Ice-Film tehnologija stvara glatki sjajni film koji reflektuje svetlost. Hidratacija i komfor tokom nošenja: Vitamin E pomaže očuvanju mekoće i zaštite usana. Dugotrajan sjaj i stabilnost boje: Film-formirajuća formula pomaže zadržavanju pigmenta i sjaja tokom više sati. Kome je namenjen? Namenjen je svim tipovima usana, posebno usnama koje su sklone suvoći ili naglašenim linijama. Pogodan je za osobe koje žele kombinaciju hidratantnog balzama i sjajnog ruža sa prirodnim ili intenzivnijim MLBB nijansama. Zašto volimo Joocyee Long-Lasting Glossy Rouge? Tekstura je izuzetno glatka i lako klizi po usnama. Formula pruža izražen sjaj bez osećaja težine ili lepljivosti. Boja se može nadograđivati u zavisnosti od željenog efekta. Usne izgledaju glađe i punije zahvaljujući refleksiji svetlosti. Proizvod se lako uklapa u minimalne dnevne ili naglašenije večernje makeup rutine. Predstavlja zanimljiv spoj balzama za usne i dekorativnog ruža. Aktivni sastojci Vitamin E Vitamin E je antioksidans koji se često koristi u formulama za negu usana. Pomaže zaštiti kože od spoljašnjih stresora i oksidativnog stresa. Takođe doprinosi očuvanju mekoće i hidratacije usana. Njegova emolijentna svojstva pomažu zaglađivanju površine kože. U proizvodima za usne često se koristi kako bi povećao komfor tokom nošenja. U ovoj formuli ima ulogu zaštite i hidratacije. Film-formirajući polimeri Film-formirajući sastojci stvaraju tanak zaštitni sloj na površini usana. Ovaj sloj pomaže stabilnosti pigmenta i sjaja tokom nošenja. Takođe doprinosi smanjenju prenosa boje i razmazivanja. Film omogućava ravnomerno raspoređivanje svetlosti na usnama. Time se postiže izražen „glass“ efekat. U ovoj formuli imaju ključnu ulogu u dugotrajnosti i sjaju proizvoda. Emolijentna ulja Emolijentna ulja su sastojci koji omekšavaju i zaglađuju površinu usana. Pomažu smanjenju osećaja suvoće i zatezanja. Takođe poboljšavaju klizanje proizvoda tokom nanošenja. Ova ulja stvaraju zaštitni sloj koji pomaže zadržavanju vlage. Njihova tekstura doprinosi prijatnom osećaju na usnama. U ovoj formuli imaju ulogu hidratacije i komfora. Dodaj u listu želja Dodaj u listu želja', 'Joocyee Long-Lasting Glossy Rouge je sjajni ruž za usne sa kremastom, balzamastom teksturom koja se topi pri kontaktu sa usnama i ostavlja izražen „glass lip“ efekat. Formula je razvijena da kombinuje intenzivan sjaj, lagan osećaj na usnama i hidrataciju uz pomoć vitamina E.', 'https://beauty-health.rs/wp-content/uploads/2026/03/500-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
