INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (73, 87, 'Joocyee Glazed Rouge 2.0 Ultra Shine Purple', 'joocyee-glazed-rouge-2-0-ultra-shine-purple', 'Ključne prednosti: Intenzivna pigmentacija sa visokim sjajem: Napredna pigmentna tehnologija omogućava bogatu boju uz izražen pearlescentni sjaj. Hidratacija i zaštita usana: Kombinacija peptida, skvalana i hijaluronske kiseline pomaže očuvanju vlage i mekoće usana. Vizuelni efekat punijih usana: Menthyl PCA pruža blagi osećaj hlađenja i doprinosi optičkom volumenu usana. Kome je namenjen? Namenjen je svim tipovima usana, posebno onima koje su sklone isušivanju i gubitku punoće. Pogodan je za osobe koje žele intenzivnu boju uz izražen sjaj i hidratantni efekat. Zašto volimo Joocyee Glazed Rouge 2.0 Ultra Shine Purple? Ovaj ruž razvijen je kao kombinacija boje, sjaja i hidratantne nege usana. Pigmenti nove generacije omogućavaju izražen ton boje uz pearlescentni refleks svetlosti koji naglašava volumen usana. Ulja u formuli stvaraju tanki zaštitni film koji pomaže stabilnosti pigmenta i smanjuje isušivanje usana tokom nošenja. Tekstura je mekana i lako klizi po usnama, ostavljajući ravnomeran sloj sa visokim sjajem. Hidratantni sastojci doprinose dugotrajnijem osećaju komfora. Kombinacija svetlucavih čestica i hidratantnih komponenti daje usnama puniji i zaglađen izgled. Rezultat je efekat sjajnih, glatkih i naglašenih usana bez težine na površini. Aktivni sastojci Peptidi Peptidi su kratki lanci aminokiselina koji se u kozmetici koriste zbog svog potencijala da podrže izgled glatke i elastične kože. U proizvodima za usne mogu doprineti poboljšanju površinske teksture. Pomažu da usne deluju mekše i glađe. Takođe doprinose održavanju hidratacije u površinskom sloju kože. Njihova uloga je uglavnom podržavajuća i usmerena na dugoročni komfor usana. U ovoj formuli doprinose zaglađenom i negovanom izgledu. Squalane Skvalan je stabilni lipid koji je kompatibilan sa prirodnim lipidima kože. U formulama za usne deluje kao emolijens koji omekšava i zaglađuje površinu usana. Pomaže u smanjenju transepidermalnog gubitka vode. Time doprinosi dugotrajnijoj hidrataciji i komforu. Takođe poboljšava klizanje proizvoda tokom nanošenja. U ovoj formuli ima ulogu omekšavanja i zaštite usana. Hyaluronic Acid Hijaluronska kiselina je molekul poznat po svojoj sposobnosti vezivanja vode. U proizvodima za usne pomaže održavanju hidratacije i punijeg izgleda. Doprinosi glatkoj i mekšoj površini usana. Njena sposobnost zadržavanja vlage pomaže u smanjenju osećaja suvoće. Takođe može doprineti optičkom volumenu usana. U ovoj formuli podržava hidrataciju i komfor tokom nošenja ruža. Menthyl PCA Menthyl PCA je derivat mentola koji pruža blagi osećaj hlađenja na usnama. Taj efekat može doprineti osećaju svežine tokom nošenja proizvoda. Takođe može stvoriti optički efekat blagog volumena usana. Njegovo delovanje je blago i kratkotrajno. U kozmetičkim formulama često se koristi za osvežavajući efekat. U ovom ružu ima ulogu senzornog i vizuelnog pojačanja volumena. Dodaj u listu želja Dodaj u listu želja', 'Joocyee Glazed Rouge 2.0 Ultra Shine Purple je sjajni ruž za usne formulisan da pruži intenzivnu pigmentaciju i visoki, gotovo staklasti sjaj uz istovremenu hidrataciju usana. Formula kombinuje pigmente nove generacije sa peptidima, skvalanom i hijaluronskom kiselinom kako bi usne izgledale punije, glađe i hidriranije.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Joocyee-Glazed-Rouge-2.0-Ultra-Shine-Purple-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
