INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (77, 58, 'Estee Lauder Advanced Night Repair Eye Supercharged Gel Creme', 'estee-lauder-advanced-night-repair-eye-supercharged-gel-creme', 'Ključne prednosti: Smanjenje vidljivosti tamnih kolutova: Formula je razvijena da deluje na različite tipove diskoloracija oko očiju i doprinese ujednačenijem tonu kože. Poboljšanje hidratacije i elastičnosti: Hijaluronska kiselina i hidratantni kompleks pomažu da koža oko očiju izgleda punije i odmornije. Zaštita od oksidativnog stresa: Antioksidativni sastojci pomažu neutralizaciju slobodnih radikala i podržavaju zdrav izgled kože. Kome je namenjena? Namenjena je svim tipovima kože, posebno osobama koje primećuju tamne kolutove, prve linije oko očiju i znakove umora. Pogodna je i za kožu kojoj je potrebna dodatna hidratacija i zaštita od spoljašnjih faktora. Zašto volimo Estee Lauder Advanced Night Repair Eye Supercharged Gel Creme? Koža oko očiju prirodno je tanja i osetljivija od ostatka lica, pa zahteva formulacije koje istovremeno hidriraju, štite i podržavaju njenu regeneraciju. Ova gel-krema razvijena je da deluje tokom dana i noći, prateći prirodni ritam obnove kože. Lagana tekstura brzo se upija i ne opterećuje osetljivo područje oko očiju. Kombinacija hidratantnih i antioksidativnih komponenti doprinosi svežijem i odmornijem izgledu pogleda. Redovnom upotrebom koža može delovati glađe i ujednačenije. Formula je testirana pod dermatološkim i oftalmološkim nadzorom kako bi bila pogodna za svakodnevnu upotrebu. Njen fokus je na dugoročnoj podršci koži, a ne samo na trenutnom estetskom efektu. Aktivni sastojci Night Peptide kompleks Night Peptide kompleks razvijen je kako bi podržao prirodne procese regeneracije kože. Peptidi deluju kao signalni molekuli koji pomažu komunikaciju između ćelija kože. U formulama za negu često se koriste za podršku elastičnosti i strukturi kože. Njihovo delovanje je postepeno i zasniva se na redovnoj primeni proizvoda. Pomažu da koža izgleda ujednačenije i otpornije. U ovoj kremi imaju centralnu ulogu u podršci noćnoj regeneraciji kože. Hyaluronic Acid Hijaluronska kiselina je humektant koji ima sposobnost da veže velike količine vode. U kozmetičkim formulama koristi se za intenzivnu hidrataciju površinskih slojeva kože. Doprinosi punijem i glađem izgledu kože. Posebno je važna za područje oko očiju gde je koža tanja i sklonija dehidrataciji. Pomaže smanjenju osećaja zatezanja i umora. U ovoj formuli ima ključnu ulogu u održavanju hidratacije. Vitamin E Vitamin E je antioksidans koji pomaže u neutralizaciji slobodnih radikala. Slobodni radikali mogu nastati pod uticajem UV zračenja, zagađenja ili plave svetlosti sa digitalnih uređaja. Antioksidansi pomažu u smanjenju oksidativnog stresa na koži. Takođe doprinose stabilnosti i zdravijem izgledu kože. Vitamin E ima i blago umirujuće delovanje. U ovoj kremi ima ulogu zaštite kože od spoljašnjih faktora. Dodaj u listu želja Dodaj u listu želja', 'Estee Lauder Advanced Night Repair Eye Supercharged Gel Creme je lagana gel-krema za područje oko očiju koja je formulisana sa Night Peptide kompleksom, hijaluronskom kiselinom i antioksidansima kako bi podržala hidrataciju, smanjila vidljivost tamnih kolutova i ublažila prve znake starenja. Formula je usmerena na osvežavanje umornog pogleda, poboljšanje elastičnosti kože oko očiju i zaštitu od oksidativnog stresa.', 'https://beauty-health.rs/wp-content/uploads/2026/03/Estee-Lauder-Advanced-Night-Repair-Eye-Supercharged-Gel-Creme-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
