INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (82, 84, 'Isntree Yam Root Milk Tone Up Sun Cream -sniženo', 'isntree-yam-root-milk-tone-up-sun-cream-outlet', 'Ključne prednosti: Visoka UV zaštita : Mineralni filteri pružaju efikasnu zaštitu od štetnih UV zraka, smanjujući rizik od oštećenja kože. Ujednačavanje tena : Bež ton kreme pruža blagi tonirajući efekat, dajući koži prirodan i blistav izgled. Hidratacija i jačanje barijere : Ekstrakt yam korena i pantenol održavaju optimalan nivo vlažnosti i jačaju zaštitnu barijeru kože. Kome je namenjen? Ova krema je idealna za sve tipove kože, uključujući osetljivu. Namenjena je osobama koje traže visoku UV zaštitu uz blagi tonirajući efekat i hidrataciju. Zašto volimo Isntree Yam Root Milk Tone Up Sun Cream? Kombinacija mineralnih filtera u ovoj kremi pruža pouzdanu zaštitu od štetnih UV zraka, čuvajući kožu od prevremenog starenja i oštećenja. Bež ton kreme delikatno ujednačava ten, dajući licu svež i prirodan izgled bez potrebe za dodatnim šminkanjem. Ekstrakt yam korena, poznat po visokom sadržaju mukina, intenzivno hidrira kožu, dok pantenol umiruje iritacije i jača zaštitnu barijeru. Ova sinergija sastojaka ne samo da štiti kožu od spoljašnjih faktora, već i poboljšava njenu elastičnost i vitalnost. Aktivni sastojci Cink oksid (Zinc Oxide) Cink oksid je mineralni UV filter koji pruža širok spektar zaštite od UVA i UVB zraka, štiteći kožu od štetnog sunčevog zračenja. Njegova antiinflamatorna svojstva pomažu u smirivanju iritacija i crvenila, što ga čini pogodnim za osetljivu kožu. Takođe, deluje kao blag adstringens, pomažući u sužavanju pora i kontroli proizvodnje sebuma. Cink oksid je poznat po svojoj nekomedogenosti, što znači da ne zapušava pore i smanjuje rizik od nastanka akni. Njegova otpornost na vodu pruža dugotrajnu zaštitu čak i tokom fizičkih aktivnosti ili izlaganja vodi. Ekstrakt korena jamsa (Dioscorea Japonica Root Extract) Ekstrakt korena jama bogat je amino kiselinama koje umiruju kožu i formiraju zaštitnu barijeru za zadržavanje vlage. Pomaže u poboljšanju teksture kože, čineći je glatkom i hidriranom. Takođe, poseduje antioksidativna svojstva koja štite kožu od slobodnih radikala i prevremenog starenja. Njegova antiinflamatorna svojstva pomažu u smanjenju crvenila i iritacija, što ga čini pogodnim za osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'Isntree Yam Root Milk Tone Up Sun Cream kombinuje visoku UV zaštitu sa laganim, prirodnim posvetljivanjem tena. Obogaćen ekstraktom jam-korena i pantenolom, ovaj veganski SPF umiruje, hidrira i ujednačava ten bez teškog osećaja ili belih tragova.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Isntree-Yam-Root-Milk-Tone-Up-Sun-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
