INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (84, 137, 'Purito Peel Shot Exfoliating Pad', 'purito-peel-shot-exfoliating-pad', 'Ključne prednosti: Čišćenje pora: Pomaže u uklanjanju viška sebuma i nagomilanih nečistoća. Ujednačavanje teksture: Zaglađuje neravnine i doprinosi svežijem izgledu kože. Priprema kože: Omogućava bolju apsorpciju narednih koraka nege. Kome je namenjen? Pogodan je za masnu i mešovitu kožu sa zapušenim porama, mitiserima i belim komedonima, kao i za ten koji deluje bez sjaja i grube teksture. Osetljiva koža može ga koristiti ređe, uz pažljivo praćenje reakcije. Ključni sastojci i njihova uloga Charcoal Powder Ugljeni prah deluje kao adsorbens koji pomaže u vezivanju viška sebuma i nečistoća sa površine kože. Doprinosi osećaju čistijih pora nakon ispiranja. Može pomoći u smanjenju masnog sjaja. Posebno je koristan kod kože sklone začepljenjima. Ne deluje agresivno kada je pravilno formulisan. Podržava vizuelno čistiji izgled tena. Glycolic Acid (AHA) + Salicylic Acid (BHA) Glikolna kiselina deluje na površini kože i pomaže u uklanjanju mrtvih ćelija. Salicilna kiselina je lipofilna i može prodirati u pore, gde doprinosi razgradnji sebuma. Kombinacija omogućava istovremeno zaglađivanje teksture i čišćenje pora. Redovnom, ali kontrolisanom upotrebom može doprineti smanjenju vidljivosti mitisera. Važno je izbegavati preterivanje i kombinovanje sa previše aktivnih sastojaka u istoj rutini. Uvek je preporučena dnevna zaštita od sunca. Enzimi (Papain, Bromelain, Protease, Lipase) Enzimi podržavaju blagu eksfolijaciju razgradnjom proteinskih veza između mrtvih ćelija. Deluju nežnije u odnosu na jače hemijske pilinge. Doprinosi glatkijem izgledu kože bez grubog mehaničkog trljanja. Pomažu u postepenom osvežavanju tena. Pogodni su za kombinovanje sa AHA i BHA u kontrolisanim formulacijama. Održavaju balans između efikasnosti i podnošljivosti. Pantenol + Allantoin Pantenol pomaže u održavanju hidratacije i podržava barijernu funkciju kože. Allantoin deluje umirujuće i smanjuje osećaj nelagodnosti nakon eksfolijacije. Zajedno doprinose očuvanju komfora. Pomažu da koža ostane mekana nakon tretmana. Podržavaju regenerativne procese. Smanjuju rizik od iritacije kada se proizvod koristi pravilno. Dodaj u listu želja Dodaj u listu želja', 'Purito Peel Shot Exfoliating Pad je eksfolijacioni tretman u obliku diska sa blagim „roll-off“ efektom, osmišljen za uklanjanje mrtvih ćelija sa površine kože i čišćenje pora. Namenjen je periodičnoj upotrebi kada je koži potreban reset teksture i vidljivo osveženje tena.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Purito-Peel-Shot-Exfoliating-Pad-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
