INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (85, 137, 'Purito Hypochlorous Acid Rescue Spray', 'purito-hypochlorous-acid-rescue-spray', 'Ključne prednosti: Antibakterijsko delovanje: Hipohlorasta kiselina pomaže u redukciji bakterija koje doprinose nastanku akni. Umirivanje i balans: 5% hamamelisa deluje adstringentno i pomaže u smanjenju crvenila i iritacije. Praktična primena: Sprej format omogućava jednostavno nanošenje u toku dana, čak i preko blage šminke. Kome je namenjen? Namenjen je masnoj, mešovitoj i problematičnoj koži sklonoj upalama, ali i osetljivoj koži kojoj je potrebna blaga, neiritirajuća podrška. Pogodan je za situacije kada koža dolazi u kontakt sa spoljašnjim faktorima poput znojenja, putovanja ili zajedničkog korišćenja opreme. Zašto volimo Purito Hypochlorous Acid Rescue Spray? Hipohlorasta kiselina je molekul koji se prirodno stvara u organizmu kao deo imunološkog odgovora, pa je koža uglavnom dobro toleriše. U niskim koncentracijama deluje pročišćavajuće bez agresivnog isušivanja. Hamamelis doprinosi kontroli sebuma i smanjenju vidljivosti pora, dok ružina voda i humektansi sprečavaju narušavanje barijere. Tekstura je lagana, bez lepljivog osećaja, što omogućava višestruku primenu tokom dana. Formulacija je bez dodatih alergena i osmišljena da pruži brz osećaj komfora. Praktično pakovanje podstiče redovnu, ciljanu upotrebu kod prvih znakova nepravilnosti. Aktivni sastojci Hypochlorous Acid Hipohlorasta kiselina deluje kao blagi oksidativni agens koji pomaže u smanjenju broja mikroorganizama na površini kože. Podržava čistoću kože bez narušavanja njenog prirodnog pH balansa. Može doprineti smanjenju crvenila povezanog sa nepravilnostima. U pravilno formulisanom proizvodu pokazuje dobru podnošljivost i nizak iritativni potencijal. Često se koristi u dermatološkim formulacijama za kožu sklonu aknama. Pomaže u održavanju zdravijeg okruženja na površini kože. Witch Hazel Extract (5%) Ekstrakt hamamelisa ima blago adstringentno i umirujuće dejstvo. Može pomoći u smanjenju viška sebuma i vizuelnom sužavanju pora. Deluje antiinflamatorno i doprinosi ublažavanju crvenila. U koncentraciji od 5% pruža balans između efikasnosti i podnošljivosti. Podržava osećaj svežine i čistoće kože. Posebno je koristan kod masne i kombinovane kože sklone nepravilnostima. Dodaj u listu želja Dodaj u listu želja', 'Purito Hypochlorous Acid Rescue Spray je praktičan umirujući sprej formulisan sa hipohlorastom kiselinom i 5% ekstrakta hamamelisa, namenjen koži sklonoj nepravilnostima i crvenilu. Kombinuje pročišćavajuće i umirujuće delovanje uz laganu, osvežavajuću teksturu pogodnu za upotrebu tokom dana.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Purito-Hypochlorous-Acid-Rescue-Spray-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
