INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (86, 119, 'Mixsoon Soondy Centella Asiatica Essence', 'mixsoon-soondy-centella-asiatica-essence', 'Ključne prednosti: Intenzivno umirivanje: Visoka koncentracija ekstrakta Centella Asiatica pomaže u smanjenju crvenila i osećaja peckanja. Podrška regeneraciji: Aktivne komponente centelle doprinose obnovi kože i jačanju njene otpornosti. Minimalistička formulacija: Jednokomponentni sastav smanjuje rizik od dodatne iritacije kod osetljive kože. Kome je namenjen? Namenjen je osetljivoj, reaktivnoj i upaljenoj koži koja pokazuje crvenilo, zatezanje ili nelagodnost. Pogodan je i za kožu oslabljene barijere nakon eksfolijacije, retinoida ili spoljašnjih stresora. Zašto volimo Mixsoon Soondy Centella Asiatica Essence? Formulacija sa jednim aktivnim sastojkom omogućava preciznu i kontrolisanu negu bez preopterećenja kože. Centella Asiatica je poznata po svojoj ulozi u modulaciji inflamatornih procesa i podršci regeneraciji. Vodena tekstura olakšava slojevito nanošenje u rutini bez osećaja težine. Kod dugoročne upotrebe koža postaje otpornija na spoljašnje faktore i manje sklona crvenilu. Minimalistički pristup čini proizvod pogodnim i za kombinovanje sa aktivnim sastojcima poput retinoida ili kiselina. Stabilnost biljnog ekstrakta u jednostavnoj bazi doprinosi dobroj toleranciji čak i kod vrlo osetljive kože. Aktivni sastojci Centella Asiatica Extract Centella Asiatica Extract ima funkciju umirivanja i podrške obnovi kože. Deluje putem bioaktivnih komponenti kao što su azijatikozid, madekasozid i azijatična kiselina, koje utiču na smanjenje inflamatornih medijatora. Na koži doprinosi ublažavanju crvenila, peckanja i osećaja zatezanja. Dugoročno podstiče sintezu kolagena i jača strukturu kože, čime poboljšava njenu otpornost. Ekstrakt je poznat po dobroj toleranciji i niskom iritativnom potencijalu. U jednostavnoj formulaciji bez dodatnih aktivnih supstanci omogućava čistu i ciljanu negu za reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Soondy Centella Asiatica Essence je esencija formulisanа sa 100% ekstraktom Centella Asiatica, namenjena umirivanju iritirane i reaktivne kože. Lagana, vodena tekstura omogućava brzo upijanje bez lepljivog završetka i pruža trenutni osećaj komfora kod kože pod stresom.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Mixsoon-Centella-Toner-Pad-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
