INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (87, 119, 'Mixsoon Centella Toner Pad', 'mixsoon-centella-toner-pad', 'Ključne prednosti: Intenzivno umirivanje: Ekstrakt centelle u kombinaciji sa alantoinom smanjuje osećaj nelagodnosti i crvenila. Podrška kožnoj barijeri: Ceramid NP i betain doprinose očuvanju lipidne strukture i smanjenju transepidermalnog gubitka vode. Višenamenska primena: Trostruka struktura jastučića omogućava upotrebu kao tonik, lokalna maska ili korekcija šminke. Kome su namenjeni? Pogodni su za suvu, osetljivu i reaktivnu kožu koja pokazuje znake narušene barijere i povremenog crvenila. Mogu biti koristni i kod kože sklone iritacijama nakon eksfolijacije, retinoida ili spoljašnjih faktora poput vetra i hladnoće. Zašto volimo Mixsoon Centella Toner Pad? Ovi jastučići nude balans između umirivanja i hidratacije bez preopterećivanja kože. Tekstura je mekana zahvaljujući trostrukoj strukturi od tencela i gaze, što omogućava ravnomernu distribuciju esencije. Centella Asiatica je poznata po podršci regenerativnim procesima kože, dok ceramidi doprinose stabilizaciji barijere na duži rok. Betain pomaže u održavanju optimalnog nivoa vlage bez osećaja lepljivosti. Mogućnost cepanja jastučića na dva dela čini proizvod praktičnim za ciljanu primenu. Dugoročnom upotrebom koža postaje otpornija na spoljašnje stresore i manje sklona osećaju zatezanja nakon čišćenja. Aktivni sastojci Centella Asiatica Extract Centella Asiatica Extract ima funkciju umirivanja i podrške regeneraciji kože. Deluje kroz stimulaciju sinteze kolagena i modulaciju inflamatornih procesa zahvaljujući komponentama poput azijatikozida i madekasozida. Na koži smanjuje crvenilo i osećaj peckanja, posebno kod osetljive i reaktivne kože. Dugoročno doprinosi jačanju strukture kože i poboljšanju njene otpornosti na spoljašnje faktore. Ekstrakt je poznat po dobroj toleranciji čak i kod kompromitovane barijere. U kombinaciji sa hidratantnim i lipidnim komponentama pokazuje sinergijski efekat u obnavljanju zaštitne funkcije kože. Ceramide NP Ceramide NP je lipid identičan onima koji se prirodno nalaze u rožnatom sloju kože i ima funkciju obnove barijere. Deluje tako što popunjava međučelijske prostore i smanjuje transepidermalni gubitak vode. Na koži doprinosi smanjenju suvoće, hrapavosti i osećaja zatezanja. Dugoročno jača otpornost kože i smanjuje reaktivnost na spoljašnje iritanse. Stabilan je u formulacijama i pokazuje dobru kompatibilnost sa humektansima poput betaina. U sinergiji sa umirujućim sastojcima doprinosi obnovi i održavanju zdrave kožne barijere. Allantoin Alantoin ima funkciju umirivanja i poboljšanja tolerancije kože. Deluje kroz stimulaciju regeneracije površinskih ćelija i ublažavanje iritacija. Na koži smanjuje crvenilo i doprinosi glađoj teksturi. Dugoročnom upotrebom podržava proces obnavljanja kože bez narušavanja njene zaštitne funkcije. Poznat je po visokoj stabilnosti i niskom potencijalu za iritaciju. U kombinaciji sa centelom i ceramidima pojačava efekat umirivanja i zaštite barijere. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Soondy Centella Asiatica Essence je esencija formulisanа sa 100% ekstraktom Centella Asiatica, namenjena umirivanju iritirane i reaktivne kože. Lagana, vodena tekstura omogućava brzo upijanje bez lepljivog završetka i pruža trenutni osećaj komfora kod kože pod stresom.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Mixsoon-Centella-Toner-Pad-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
