INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (88, 117, 'Mintree Scalp Shampoo', 'mintree-scalp-shampoo', 'Ključne prednosti: Ublažavanje simptoma opadanja: klinički potvrđeno smanjenje broja opalih vlasi doprinosi stabilnijem ciklusu rasta. Povećanje volumena u korenu: poboljšava podignutost i gustinu u zoni temena bez otežavanja kose. Anti-age nega temena: doprinosi hidrataciji, elastičnosti i očuvanju barijerne funkcije kože glave. Kome je namenjen? Namenjen je osobama sa pojačanim opadanjem kose, oslabljenim korenom i smanjenim volumenom u zoni temena. Pogodan je za masno ili kombinovano teme koje zahteva balansiranje bez dodatnog opterećenja silikonom. Zašto volimo Mintree Scalp Shampoo? Formulisan je kao funkcionalni proizvod sa jasno definisanim ciljem – podrška temenu u fazi pojačanog opadanja. Izostanak silikona omogućava da se teme ne opterećuje okluzivnim filmom. Fokus na volumenu u korenu daje vizuelno puniji izgled kose. Efekti hidratacije i elastičnosti ukazuju na rad na kvalitetu kože glave, a ne samo na dužini vlasi. Stabilno teme predstavlja osnovu za zdrav rast nove kose. Kontinuirana upotreba može doprineti boljoj otpornosti folikula na spoljašnje faktore. Posebno je značajan balans između čišćenja i očuvanja barijere temena. Aktivni sastojci Kompleks za ublažavanje opadanja Funkcionalni kompleks je osmišljen da podrži ciklus rasta kose i smanji broj opalih vlasi. Mehanizam delovanja zasniva se na poboljšanju mikrocirkulacije i jačanju okruženja folikula. Efekat uključuje stabilizaciju korena i smanjenje preuranjenog prelaska u fazu opadanja. Dugoročno može doprineti vidljivo gušćem izgledu kose. Njegova efikasnost potvrđena je kliničkim testiranjem u kontrolisanim uslovima. Stabilnost formule bez silikona omogućava bolju dostupnost aktivnih komponenti temenu. Hidratantno-elastični kompleks za teme Ovaj kompleks ima funkciju poboljšanja hidratacije i elastičnosti kože glave. Mehanizam uključuje zadržavanje vlage u površinskim slojevima temena. Efekat se ogleda u smanjenju osećaja suvoće i zategnutosti. Dugoročno doprinosi očuvanju gustine i fleksibilnosti kože glave. Bolje hidrirano teme može pružiti stabilniju osnovu za rast kose. Sinergija sa formulom bez silikona pomaže održavanju ravnoteže bez opterećenja. Dodaj u listu želja Dodaj u listu želja', 'Mintree Scalp Shampoo je funkcionalni šampon bez silikona formulisan za ublažavanje simptoma opadanja kose i poboljšanje stanja temena. Klinička ispitivanja navode smanjenje opadanja kose za 65% i povećanje volumena u korenu za 14%, uz efekte hidratacije, elastičnosti i gustine kože glave.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Mintree-Scalp-Shampoo-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
