INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (89, 117, 'Mintree Deep Damage Hair Pack', 'mintree-deep-damage-hair-pack', 'Ključne prednosti: Obnova proteinske strukture: mikro-proteini popunjavaju oštećena mesta u kutikuli i poboljšavaju otpornost vlasi na mehanička oštećenja. Intenzivna ishrana bez silikona: kombinacija biljnih ulja omekšava kosu i poboljšava sjaj bez stvaranja teškog filma. Poboljšana elastičnost: redovna upotreba doprinosi većoj zateznoj snazi i smanjenju pucanja vlasi. Kome je namenjen? Namenjen je suvoj, oštećenoj, poroznoj i hemijski tretiranoj kosi koja pokazuje znakove lomljenja i gubitka sjaja. Posebno je pogodan za kosu izloženu farbanju, blajhanju ili termičkoj obradi. Zašto volimo Mintree Deep Damage Hair Pack? Ova maska kombinuje proteinsku i lipidnu negu bez oslanjanja na silikone. Gusta, puterasta tekstura omogućava ravnomerno prijanjanje uz vlas. Mikro-proteini ciljano deluju na oslabljena mesta u kutikuli. Biljna ulja doprinose omekšavanju i smanjenju trenja pri češljanju. Redovnom upotrebom kosa može delovati kompaktnije i sjajnije. Formula ne ostavlja težak sloj, što je važno kod fine i porozne kose. Dugoročno se poboljšava upravljivost i otpornost na spoljašnje faktore. Aktivni sastojci Mikro-proteini (svila, kolagen, pšenica, kukuruz, grašak, soja, pirinač, kinoa, ječam, keratin) Mikro-proteini deluju kao građevinski elementi koji privremeno popunjavaju oštećena mesta u kutikuli vlasi. Njihov mehanizam zasniva se na vezivanju za negativno naelektrisana oštećena područja na površini dlake. Time se smanjuje poroznost i poboljšava glatkoća. Efekat na kosu uključuje povećanu čvrstinu i smanjeno lomljenje. Dugoročnom primenom mogu doprineti boljoj otpornosti na mehanička oštećenja. Njihova efikasnost zavisi od veličine molekula i sposobnosti vezivanja za keratinsku strukturu vlasi. Biljna ulja (argan, baobab, babasu, jojoba, suncokret, makadamija, slatki badem, kora pomorandže) Biljna ulja funkcionišu kao emolijensi koji omekšavaju i zaglađuju vlas. Njihov mehanizam uključuje formiranje zaštitnog lipidnog sloja na površini kose. Time se smanjuje gubitak vlage i trenje između vlasi. Efekat na kosu je povećan sjaj i bolja upravljivost. Dugoročnom upotrebom mogu doprineti smanjenju suvih i ispucalih krajeva. Stabilnost i efikasnost zavise od sastava masnih kiselina i kompatibilnosti sa proteinskim komponentama u formuli. Dodaj u listu želja Dodaj u listu želja', 'Mintree Deep Damage Hair Pack je intenzivna maska za kosu bez silikona formulisana sa 13 vrsta mikro-proteina i 8 biljnih ulja radi obnove oštećene strukture vlasi. Kombinacija proteina svile, kolagena, pšenice, kukuruza, graška, soje, pirinča, kinoe, ječma i keratina sa uljima argana, baobaba, babasua, jojobe, suncokreta, makadamije, slatkog badema i kore pomorandže usmerena je na jačanje, elastičnost i sjaj bez otežavanja kose.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Mintree-Deep-Damage-Hair-Pack-1.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
