INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (90, 114, 'Medicube Kojic Acid Turmeric Vita Capsule Cream', 'medicube-kojic-acid-turmeric-vita-capsule-cream', 'Ključne prednosti: Ujednačavanje tena: kojinska kiselina, niacinamid i vitamin C doprinose smanjenju vidljivosti tamnih mrlja i neujednačenosti. Umirenje i balans: ekstrakt kurkume i alantoin pomažu u smirivanju kože izložene spoljašnjim stresorima. Barijerna hidratacija: osam tipova hijaluronske kiseline i ceramid NP podržavaju zadržavanje vlage i jačanje zaštitnog sloja. Kome je namenjen? Namenjena je normalnoj, mešovitoj i suvoj koži sa neujednačenim tonom i vidljivim pigmentacijama. Posebno odgovara koži koja istovremeno pokazuje znake dehidratacije i oslabljenog barijernog sloja. Zašto volimo Medicube Kojic Acid Turmeric Vita Capsule Cream? Ova krema objedinjuje pristup posvetljivanju i očuvanju barijere bez agresivnog delovanja. Kapsulirana struktura omogućava stabilnije čuvanje aktivnih sastojaka u formuli. Kombinacija antioksidanasa i regulatora melanina deluje postepeno, bez naglih promena na koži. Prisustvo višestrukih oblika hijaluronske kiseline doprinosi dugotrajnijoj hidrataciji. Umirujući sastojci ublažavaju potencijalnu reaktivnost povezanu sa aktivnim supstancama za posvetljivanje. Dugoročno, koža može delovati ujednačenije i otpornije uz održavanje elastičnosti i glatkoće. Aktivni sastojci Kojična kiselina Kojična kiselina je sastojak poznat po inhibiciji enzima tirozinaze, koji učestvuje u sintezi melanina. Deluje tako što smanjuje proizvodnju pigmenta u epidermisu, čime utiče na izgled tamnih mrlja. Rezultat je postepeno ujednačavanje tona kože. Dugoročnom primenom može doprineti svetlijem i jasnijem tenu uz pravilnu zaštitu od sunca. Stabilnost joj zavisi od formulacije i kombinacije sa antioksidansima. U sinergiji sa niacinamidom i vitaminom C podržava kontrolu hiperpigmentacija. Ekstrakt kurkume Ekstrakt kurkume deluje kao antioksidans i umirujući sastojak. Njegov mehanizam uključuje neutralizaciju slobodnih radikala i smanjenje oksidativnog stresa. Pomaže u ublažavanju crvenila i neprijatnosti izazvanih spoljašnjim faktorima. Dugoročno može doprineti smanjenju reaktivnosti kože. Dobro se podnosi u kozmetičkim formulacijama kada je pravilno stabilizovan. U kombinaciji sa sastojcima za posvetljivanje pomaže u održavanju ravnoteže i tolerancije kože. Niacinamid Niacinamid je oblik vitamina B3 koji deluje na ujednačavanje tena i jačanje barijere. Mehanizam obuhvata smanjenje prenosa melanina ka površinskim slojevima kože. Takođe podstiče sintezu ceramida i poboljšava funkciju barijere. Dugoročnom upotrebom može doprineti smanjenju crvenila i regulaciji sebuma. Stabilan je u širokom rasponu pH vrednosti i dobro se kombinuje sa vitaminom C i hijaluronskom kiselinom. U ovoj formuli podržava sinergijsko delovanje sa kojinskom kiselinom. Vitamin C Vitamin C je antioksidans koji pomaže u zaštiti kože od oksidativnog oštećenja. Deluje inhibicijom oksidacije melanina i podržava sintezu kolagena. Efekat na koži uključuje poboljšanje blistavosti i smanjenje izgleda hiperpigmentacija. Dugoročno može doprineti čvršćoj i ujednačenijoj koži. Njegova stabilnost zavisi od oblika i formulacije u kojoj se nalazi. U kombinaciji sa niacinamidom i kojinskom kiselinom doprinosi sveobuhvatnom pristupu posvetljivanju. Hijaluronska kiselina (8 tipova) Hijaluronska kiselina deluje kao snažan humektans koji vezuje vodu u epidermisu. Različite molekulske mase omogućavaju hidrataciju površinskih i dubljih slojeva kože. Time se smanjuje osećaj zatezanja i poboljšava elastičnost. Dugoročno pomaže u očuvanju integriteta barijere i smanjenju linija dehidratacije. Stabilna je u vodenim i gel formulama. U sinergiji sa ceramidom NP i alantoinom doprinosi očuvanju ravnoteže vlage. Ceramid NP Ceramid NP je lipid identičan onima koji se prirodno nalaze u koži. Njegova funkcija je obnova i jačanje lipidne barijere. Deluje popunjavanjem prostora između ćelija rožnatog sloja i smanjenjem gubitka vlage. Dugoročno doprinosi otpornijoj i manje reaktivno', 'Medicube Kojic Acid Turmeric Vita Capsule Cream je kapsulirana gel-krema formulisana sa kojičnom kiselinom, ekstraktom kurkume, niacinamidom i vitaminom C radi ujednačavanja tena i poboljšanja blistavosti kože. Formula je obogaćena sa osam tipova hijaluronske kiseline, alantoinom i ceramidom NP kako bi istovremeno pružila hidrataciju i podršku kožnoj barijeri.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Medicube-Kojic-Acid-Turmeric-Vita-Capsule-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
