INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (93, 100, 'Kundal Honey & Macadamia Hair Treatment Blackberry Bay', 'kundal-honey-macadamia-hair-treatment-blackberry-bay', 'Ključne prednosti: Obnova oštećene strukture: ulje makadamije i proteini popunjavaju oštećene delove vlasi i zaglađuju kutikulu. Povećana elastičnost: proteinske komponente pomažu smanjenju lomljenja i poboljšavaju otpornost kose. Hidratacija i sjaj: kokosovo ulje doprinosi zadržavanju vlage i mekšem, ujednačenijem izgledu kose. Kome je namenjen? Namenjen je osobama sa suvom, hemijski tretiranom ili mehanički oštećenom kosom. Pogodan je i za kosu sa ispucalim krajevima, smanjenom elastičnošću i bez sjaja. Zašto volimo Kundal Honey & Macadamia Hair Treatment Blackberry Bay? Formula se oslanja na kombinaciju lipida i proteina koji deluju na površini i u korteksu vlasi. Ulje makadamije ima sastav sličan prirodnim lipidima kose, što doprinosi boljoj kompatibilnosti sa vlasima. Proteini pomažu privremenom popunjavanju mikropukotina u kutikuli. Kokosovo ulje je poznato po sposobnosti da smanji gubitak proteina iz dlake tokom pranja. Redovnom upotrebom kosa postaje zaglađenija i lakša za raščešljavanje. Mirisna kompozicija ostaje diskretno prisutna bez uticaja na funkcionalnost formule. Dugoročna primena ima za cilj očuvanje integriteta vlasi i smanjenje mehaničkog oštećenja. Aktivni sastojci Ulje makadamije Ulje makadamije ima funkciju emolijensa koji obnavlja lipidni sloj vlasi. Deluje tako što popunjava oštećene delove kutikule i smanjuje hrapavost površine dlake. Rezultat je glađa kosa sa manjim trenjem između vlasi. Dugoročno doprinosi smanjenju lomljenja i ispucalih krajeva. Stabilno je u formulama za ispiranje i dobro se kombinuje sa proteinskim komponentama. Njegova struktura bogata masnim kiselinama čini ga pogodnim za suvu i hemijski tretiranu kosu. Proteini Proteini u nezi kose imaju funkciju jačanja i privremene obnove strukture vlasi. Deluju vezivanjem za oštećene delove kutikule i korteksa. Time povećavaju otpornost kose na mehanička oštećenja. Dugoročno pomažu održavanju elastičnosti i smanjenju pucanja. Efikasnost zavisi od veličine molekula i stepena hidrolize. U sinergiji sa lipidima doprinose balansiranoj nezi bez preteranog otežavanja. Kokosovo ulje Kokosovo ulje ima funkciju hidratantnog i zaštitnog lipida. Deluje penetracijom u vlas zahvaljujući afinitetu prema proteinskoj strukturi kose. Smanjuje gubitak proteina tokom pranja i izlaganja spoljnim faktorima. Dugoročno doprinosi očuvanju čvrstoće i fleksibilnosti vlasi. Stabilno je u formulama za ispiranje i dobro podnosi kombinaciju sa drugim uljima i proteinima. Posebno je pogodno za suvu i oštećenu kosu kojoj je potrebna dodatna zaštita. Dodaj u listu želja Dodaj u listu želja', 'Kundal Honey & Macadamia Hair Treatment Blackberry Bay je regenerator namenjen suvoj i oštećenoj kosi, formulisan sa uljem makadamije, proteinima i kokosovim uljem radi jačanja i zaglađivanja vlasi. Fokusiran je na obnovu strukture dlake i poboljšanje elastičnosti bez otežavanja kose.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Kundal_Honey-Macadamia-Treatment-Blackberry-Bay-500ml.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
