INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (95, 100, 'Kundal Airy Volume Hyaluron Treatment', 'kundal-airy-volume-hyaluron-treatment', 'Ključne prednosti: Balans hidratacije i volumena: održava odnos vlage i prirodnih ulja bez otežavanja kose. Podrška temenu: AHA i PHA doprinose uklanjanju nečistoća i mrtvih ćelija. Jačanje vlasi: hidrolizovani proteini pomažu u obnovi oštećene strukture kose. Kome je namenjen? Namenjen je tankoj i spljoštenoj kosi sa masnim temenom i suvim krajevima. Pogodan je za kosu oštećenu stilizovanjem i gubitkom elastičnosti. Zašto volimo Kundal Airy Volume Hyaluron Treatment? Formula kombinuje hidratantne i proteinske komponente bez klasične teške teksture. Hijaluronska kiselina doprinosi očuvanju vlage u vlaknu dlake. Hidrolizovani proteini deluju na površini vlasi i privremeno popunjavaju oštećenja. Blage kiseline podržavaju čistoću temena bez agresivnog efekta. Niosomska tehnologija omogućava ravnomerniju raspodelu aktivnih sastojaka. Dugoročnom upotrebom može pomoći u održavanju podignutije i elastičnije kose bez masnog osećaja pri korenu. Aktivni sastojci Hijaluronska kiselina Hijaluronska kiselina ima funkciju humektansa koji vezuje vodu u vlaknu dlake i na površini temena. Deluje privlačenjem i zadržavanjem molekula vode. Njena primena doprinosi povećanju fleksibilnosti i mekoće kose. Dugoročno može pomoći u smanjenju osećaja suvoće i lomljenja. Stabilnost zavisi od molekulske mase i formulacije proizvoda. U sinergiji sa proteinima doprinosi boljem balansu hidratacije i strukturalne podrške. AHA i PHA kiseline AHA i PHA imaju funkciju blage hemijske eksfolijacije površine temena. Deluju razgradnjom veza između mrtvih ćelija i uklanjanjem naslaga. Njihova primena doprinosi čistijem i osveženijem osećaju temena. Dugoročno mogu pomoći u održavanju optimalnog okruženja za rast kose. PHA pokazuje bolju toleranciju zbog veće molekulske mase. U kombinaciji sa hidratantnim sastojcima omogućavaju kontrolisanu eksfolijaciju bez izraženog isušivanja. Hidrolizovani proteini (soja, pirinač, grašak, ječam, lešnik) Hidrolizovani proteini imaju funkciju jačanja i privremenog popunjavanja oštećenja u strukturi vlasi. Deluju vezivanjem za površinu dlake i formiranjem zaštitnog filma. Njihova primena doprinosi smanjenju lomljenja i poboljšanju elastičnosti. Dugoročno mogu pomoći u smanjenju mehaničkog oštećenja. Efikasnost zavisi od veličine proteinskih fragmenata i koncentracije u formuli. U sinergiji sa hijaluronskom kiselinom doprinose kombinovanom efektu hidratacije i strukturalne stabilnosti. Blue Marine Complex (Undaria, Laminaria, Ecklonia Cava) Ovaj kompleks algi ima funkciju nutritivne i antioksidativne podrške. Deluje isporukom minerala i polisaharida na površinu kose i temena. Njegova primena doprinosi vitalnijem izgledu vlasi. Dugoročno može pomoći u očuvanju otpornosti na spoljašnje uticaje. Stabilnost zavisi od pravilne ekstrakcije i formulacije. U kombinaciji sa drugim aktivnim sastojcima doprinosi sveobuhvatnoj nezi bez otežavanja. Dodaj u listu želja Dodaj u listu želja', 'Kundal Airy Volume Hyaluron Treatment sadrži hijaluronski kompleks, AHA i PHA za blagu eksfolijaciju temena, kao i hidrolizovane proteine za jačanje vlasi. Razvijen je za kosu sa masnim korenom i suvim krajevima koja gubi volumen i elastičnost.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Kundal-Airy-Volume-Hyaluron-Treatment-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
