INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (96, 100, 'Kundal Airy Volume Hyaluron Shampoo', 'kundal-airy-volume-hyaluron-shampoo', 'Ključne prednosti: Balans temena: pomaže u održavanju ravnoteže između vlage i sebuma. Blaga hemijska eksfolijacija: AHA i PHA uklanjaju nakupljene mrtve ćelije i nečistoće. Dubinska hidratacija: hijaluronska kiselina uz niosomsku tehnologiju doprinosi boljem zadržavanju vlage. Kome je namenjen? Namenjen je masnom ili mešovitom temenu sa suvim dužinama i kosom bez volumena. Pogodan je za tanku i spljoštenu kosu koja brzo gubi oblik nakon stilizovanja. Zašto volimo Kundal Airy Volume Hyaluron Shampoo? Formula je usmerena na zdravlje temena kao osnovu za volumen kose. Kombinacija blagih kiselina doprinosi uklanjanju nakupljenih ćelija bez agresivnog mehaničkog pilinga. Hijaluronska kiselina doprinosi očuvanju hidratacije temena. Niosomska tehnologija omogućava ravnomerniju distribuciju aktivnih sastojaka. Dermatološko testiranje na iritaciju pruža dodatnu sigurnost kod osetljivog temena. Dugoročnom upotrebom može pomoći u održavanju čistijeg temena i lakše, podignute kose. Aktivni sastojci Hijaluronska kiselina Hijaluronska kiselina ima funkciju humektansa i vezuje vodu u površinskim slojevima kože i vlasišta. Deluje privlačenjem i zadržavanjem molekula vode. Njena primena doprinosi povećanju nivoa hidratacije temena. Dugoročno može pomoći u smanjenju osećaja suvoće i zatezanja. Stabilnost zavisi od molekulske mase i formulacije. U kombinaciji sa niosomskom tehnologijom može doprineti efikasnijoj isporuci vlage. AHA kiseline AHA kiseline imaju funkciju hemijske eksfolijacije površinskog sloja kože. Deluju razgradnjom veza između mrtvih ćelija. Njihova primena doprinosi uklanjanju naslaga sa temena. Dugoročno mogu pomoći u smanjenju zagušenja folikula. Efikasnost zavisi od koncentracije i pH vrednosti formule. U kombinaciji sa PHA omogućavaju kontrolisaniju eksfolijaciju. PHA kiseline PHA kiseline su polihidroksi kiseline sa većom molekulskom masom. Deluju sporijom i blažom eksfolijacijom u poređenju sa AHA. Njihova primena doprinosi uklanjanju mrtvih ćelija uz manji rizik od iritacije. Dugoročno mogu pomoći u održavanju čistoće temena. Pokazuju bolju toleranciju kod osetljive kože. U sinergiji sa AHA omogućavaju balans između efikasnosti i podnošljivosti. Niosomska tehnologija Niosomi su vezikule koje omogućavaju inkapsulaciju aktivnih sastojaka. Njihova funkcija je kontrolisana i ravnomerna isporuka. Deluju tako što štite aktivne komponente do momenta primene. Mogu doprineti boljoj distribuciji hidratantnih sastojaka po temenu. Dugoročno omogućavaju stabilniju efikasnost formule. U kombinaciji sa hijaluronskom kiselinom doprinose produženom osećaju hidratacije. Dodaj u listu želja Dodaj u listu želja', 'Kundal Airy Volume Hyaluron Shampoo je šampon formulisan za održavanje ravnoteže vode i sebuma na temenu uz dodatak hijaluronske kiseline, AHA i PHA kiselina, uz primenu niosomske tehnologije za poboljšanu isporuku hidratacije. Dermatološki je testiran na iritaciju kože.', 'https://beauty-health.rs/wp-content/uploads/2026/02/kundal-airy-volume-hyaluron-shampoo-500ml-1-min.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
