INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (98, 84, 'Isntree Chestnut AHA 8% Clear Essence', 'isntree-chestnut-aha-8-clear-essence', 'Ključne prednosti: Hemijska eksfolijacija: 8% AHA uklanja mrtve ćelije i doprinosi glađoj površini kože. Otčepljivanje pora: glikolna i mlečna kiselina pomažu u razgradnji naslaga unutar pora. Umirujuća podrška: Centella kompleksi i ekstrakt kestena doprinose smanjenju iritacije tokom eksfolijacije. Kome je namenjen? Namenjena je normalnoj, suvoj i koži sklonoj aknama sa zapušenim porama i neravnom teksturom. Pogodna je za kožu koja pokazuje znake zadebljanja, sivkast ton i površinske nepravilnosti. Zašto volimo Isntree Chestnut AHA 8% Clear Essence? Formula kombinuje dve AHA kiseline u jasno definisanim koncentracijama od po 4%. Ovakva raspodela omogućava balans između efikasnosti i podnošljivosti. Glikolna kiselina deluje snažnije zbog manje molekulske mase, dok mlečna pruža dodatni hidratantni efekat. Ekstrakt kore kestena dodaje antioksidativnu i pročišćavajuću komponentu. Aqua Teca 1000T kompleks sa pet derivata Centella Asiatica smanjuje rizik od prekomerne iritacije. Dugoročnom upotrebom može doprineti ujednačenijem tenu i glađoj teksturi kože. Aktivni sastojci Glikolna kiselina (4%) Glikolna kiselina je alfa-hidroksi kiselina sa malom molekulskom masom. Deluje razgradnjom veza između mrtvih ćelija u rožnatom sloju. Ovaj mehanizam ubrzava proces eksfolijacije i obnove epidermisa. Rezultat je glađa i ujednačenija tekstura kože. Dugoročno može doprineti smanjenju površinskih nepravilnosti i sivog tona. Stabilnost i efikasnost zavise od koncentracije i pH vrednosti formulacije. Mlečna kiselina (4%) Mlečna kiselina je AHA koja deluje blaže u poređenju sa glikolnom. Razgrađuje korneocitne veze i podstiče uklanjanje mrtvih ćelija. Pored eksfolijacije, pokazuje i humektantna svojstva. Dugoročno može doprineti boljoj hidrataciji i elastičnosti kože. Pokazuje bolju toleranciju kod osetljivije kože u odnosu na jače kiseline. U sinergiji sa glikolnom omogućava sveobuhvatniji efekat eksfolijacije. Castanea Crenata Shell Extract Ekstrakt kore korejskog kestena ima funkciju antioksidativne i pročišćavajuće komponente. Deluje neutralizacijom slobodnih radikala i podrškom balansu kože. Njegova primena može doprineti čistijem i svežijem izgledu tena. Dugoročno može pomoći u održavanju ujednačenosti teksture. Stabilnost zavisi od pravilne formulacije i zaštite od oksidacije. U kombinaciji sa AHA kiselinama doprinosi kontrolisanijem i uravnoteženijem delovanju. Aqua Teca 1000T (kompleks Centella Asiatica ekstrakata) Aqua Teca 1000T predstavlja kombinaciju pet ekstrakata Centella Asiatica. Njihova funkcija je umirujuća i barijerna podrška tokom eksfolijacije. Deluju smanjenjem inflamatornih signala i podrškom regeneraciji. Mogu pomoći u smanjenju osećaja iritacije izazvane kiselinama. Dugoročno doprinose stabilnijoj i otpornijoj koži. U sinergiji sa AHA kiselinama omogućavaju balans između efikasnosti i tolerancije. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Honey Syrup Pack Cleanser je hibridni proizvod koji funkcioniše kao čistač i esencija, sa sirupastom teksturom meda i klinički testiranim sistemom blagog zagrevanja tokom masaže. Formulisan je sa 40% hidratantnih sastojaka, divljim medom, panthenolom i ceramidima radi temeljne, ali barijerno podržane nege.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Isntree-Chestnut-AHA-8-Clear-Essence-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
