INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (100, 81, 'ilso Super Melting Sebum Cleansing Oil', 'ilso-super-melting-sebum-cleansing-oil', 'Ključne prednosti: Efikasno uklanjanje nečistoća: rastvara šminku, mrtve ćelije i sebum bez agresivnog trljanja. Kontrola pora i sebuma: Blue Pore Complex i biljni kompleksi doprinose uravnoteženijem izgledu pora. Očuvanje hidratacije: panthenol i tokoferol pomažu u smanjenju osećaja suvoće nakon ispiranja. Kome je namenjen? Namenjen je mešovitoj i masnoj koži sa proširenim porama i viškom sebuma. Pogodan je i za suvlju kožu koja zahteva temeljno, ali neagresivno uklanjanje šminke i nečistoća. Zašto volimo ilso Super Melting Sebum Cleansing Oil? Ovaj proizvod je osmišljen kao prvi korak dvostrukog čišćenja sa naglaskom na balans između detoksikacije i nege. Ulje se lako razmazuje i rastvara nečistoće bez osećaja težine. U kontaktu sa vodom brzo emulguje i ispira se bez masnog filma. Kompleksi usmereni na pore doprinose urednijem izgledu kože. Prisustvo panthenola i tokoferola pruža dodatnu barijernu podršku tokom čišćenja. Dugoročnom upotrebom može pomoći u održavanju čistijih pora i stabilnijeg nivoa masnoće. Aktivni sastojci Blue Pore Complex Blue Pore Complex je kombinacija sastojaka usmerena na kontrolu viška sebuma i izgled pora. Deluje podrškom uravnoteženju lučenja ulja na površini kože. Njegova primena može doprineti smanjenju zapušenosti pora. Dugoročno može pomoći u održavanju čistijeg i glađeg izgleda. Stabilnost zavisi od formulacije i kompatibilnosti sa uljnom bazom. U kombinaciji sa biljnim kompleksima doprinosi sveobuhvatnijem pristupu nezi pora. Green Leaf Complex Green Leaf Complex predstavlja skup biljnih ekstrakata sa umirujućim i balansirajućim svojstvima. Deluje podrškom stabilnosti kože tokom procesa čišćenja. Može doprineti smanjenju osećaja iritacije. Dugoročnom primenom pomaže u održavanju ujednačenijeg izgleda kože. Stabilnost je obezbeđena pravilnom formulacijom u uljnoj bazi. U sinergiji sa panthenolom doprinosi očuvanju komfora kože. Pantenol Pantenol je provitamin B5 poznat po hidratantnim i umirujućim svojstvima. U koži se konvertuje u pantotensku kiselinu i podržava regenerativne procese. Deluje kao humektans i doprinosi očuvanju elastičnosti. Dugoročno može pomoći u jačanju barijerne funkcije. Pokazuje dobru toleranciju i kompatibilnost sa različitim formulacijama. U kombinaciji sa antioksidansima doprinosi zaštiti kože tokom čišćenja. Tokoferol Tokoferol je oblik vitamina E sa antioksidativnim svojstvima. Deluje neutralizacijom slobodnih radikala i podrškom zaštitnoj funkciji kože. Njegova primena može pomoći u smanjenju oksidativnog stresa izazvanog spoljnim faktorima. Dugoročno može doprineti zdravijem izgledu kože. Stabilnost zavisi od zaštite od svetlosti i vazduha u formulaciji. U sinergiji sa panthenolom doprinosi očuvanju hidratacije i komfora. Dodaj u listu želja Dodaj u listu želja', 'ilso Super Melting Sebum Cleansing Oil kombinuje emolijentnu bazu sa sastojcima za kontrolu sebuma i hidrataciju kako bi efikasno očistio pore i doprineo glađem izgledu kože. Namenjen je koži sa proširenim porama, viškom ulja i sklonošću ka zapušavanju, uključujući i suvlje tipove koji reaguju na agresivno čišćenje.', 'https://beauty-health.rs/wp-content/uploads/2026/02/ilso-Super-Melting-Sebum-Cleansing-Oil-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
