INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (101, 81, 'ilso Clean Up Wash-Off Mud', 'ilso-clean-up-wash-off-mud', 'Ključne prednosti: Dubinsko čišćenje pora: 250.000 ppm kaolina apsorbuje višak sebuma i uklanja nečistoće iz pora. Umirujuća nega: Centella Asiatica i Rock Samphire doprinose smanjenju osećaja iritacije tokom čišćenja. Očuvanje hidratacije: Ceramide NP i Sodium Hyaluronate pomažu u obnovi barijere i zadržavanju vlage nakon ispiranja. Kome je namenjena? Namenjena je mešovitoj i masnoj koži sa zapušenim porama i pojačanim lučenjem sebuma. Pogodna je i za kožu koja nakon dubinskog čišćenja pokazuje znake suvoće ili zatezanja. Zašto volimo ilso Clean Up Wash-Off Mud? Formula kombinuje intenzivno adsorptivno delovanje gline sa sastojcima za obnovu barijere. Tekstura je mekana i kremasta, bez tipičnog osećaja zatezanja karakterističnog za neke glinene maske. Visoka koncentracija kaolina omogućava efikasno uklanjanje viška ulja i nečistoća. Istovremeno, prisustvo ceramida i hijaluronata smanjuje rizik od post-čistilačke dehidratacije. Umirujući biljni ekstrakti dodatno doprinose komforu tokom upotrebe. Dugoročnom primenom može pomoći u održavanju čistijih pora i uravnoteženijeg nivoa masnoće kože. Aktivni sastojci Kaolin Kaolin je mineralna glina poznata po sposobnosti apsorpcije viška sebuma. Deluje vezivanjem ulja i površinskih nečistoća sa kože. Njegova primena doprinosi čišćem i matiranijem izgledu. Dugoročno može pomoći u smanjenju zapušenosti pora. U formulacijama sa dodatkom hidratantnih sastojaka pokazuje bolju toleranciju. U ovoj maski je prisutan u visokoj koncentraciji radi efikasnog, ali kontrolisanog čišćenja. Centella Asiatica Extract Centella Asiatica je biljni ekstrakt poznat po umirujućem i regenerativnom delovanju. Podržava sintezu kolagena i doprinosi jačanju barijere. Može pomoći u smanjenju osećaja iritacije nakon dubinskog čišćenja. Dugoročno doprinosi otpornijoj i stabilnijoj koži. Stabilnost zavisi od formulacije i koncentracije. U kombinaciji sa hidratantnim komponentama doprinosi očuvanju komfora tokom tretmana. Rock Samphire Rock Samphire je biljni ekstrakt poznat po osvežavajućim i umirujućim svojstvima. Deluje podrškom balansu kože tokom eksfolijacije. Može doprineti ujednačenijem izgledu i boljoj toleranciji. Dugoročno pomaže u održavanju stabilnog stanja kože. Njegova efikasnost zavisi od formulacije i sinergije sa drugim sastojcima. U ovoj maski dopunjuje delovanje gline i umirujućih komponenti. Ceramide NP Ceramide NP je koži identičan lipid koji učestvuje u strukturi zaštitne barijere. Deluje obnavljanjem lipidnog matriksa između ćelija. Njegova primena smanjuje transepidermalni gubitak vode. Dugoročno doprinosi jačanju otpornosti kože. Stabilan je u pravilno formulisanom pH opsegu. U sinergiji sa hijaluronatom pomaže očuvanju hidratacije nakon ispiranja. Sodium Hyaluronate Sodium Hyaluronate je oblik hijaluronske kiseline sa sposobnošću vezivanja vode. Deluje povećanjem nivoa hidratacije u površinskim slojevima kože. Njegova primena doprinosi osećaju mekoće i punoće. Dugoročno može pomoći u očuvanju elastičnosti kože. Stabilan je i kompatibilan sa većinom sastojaka. U kombinaciji sa ceramidima doprinosi obnovi hidratacione barijere nakon dubinskog čišćenja. Dodaj u listu želja Dodaj u listu želja', 'ilso Clean Up Wash-Off Mud je maska za ispiranje sa 250.000 ppm kaolina, formulisanа za dubinsko čišćenje pora uz očuvanje hidratacije kože. Obogaćena je ekstraktom Centella Asiatica, Rock Samphire, Ceramide NP i Sodium Hyaluronate radi umirujuće i barijerne podrške nakon detoksikacije.', 'https://beauty-health.rs/wp-content/uploads/2026/02/ilso-Clean-Up-Wash-Off-Mud-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
