INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (103, 70, 'HAUA Hyaluronic PDRN Orb Serum', 'haua-hyaluronic-pdrn-orb-serum', 'Ključne prednosti: Intenzivna i dugotrajna hidratacija: klinički je zabeleženo povećanje zadržavanja vlage tokom 24 sata i unapređenje nivoa hidratacije. Jačanje barijere: Hyaluronic PDRN doprinosi poboljšanju otpornosti kože i smanjenju gubitka vlage. Vidljiviji sjaj i elastičnost: kombinacija aktivnih sastojaka doprinosi glađem, zategnutijem i ujednačenijem izgledu kože. Kome je namenjen? Namenjen je suvoj, dehidriranoj i barijerno oslabljenoj koži koja pokazuje znake umora i gubitka sjaja. Pogodan je i za kožu sa finim linijama i neujednačenim tonom. Zašto volimo HAUA Hyaluronic PDRN Orb Serum? Ovaj serum koristi sferični sistem doziranja koji omogućava preciznu i higijensku upotrebu. Orb struktura štiti aktivne sastojke do trenutka nanošenja. Kompleks hijaluronske kiseline i PDRN-a formira mrežu vlage na i u površinskim slojevima kože. Klinička ispitivanja su pokazala povećanje zadržavanja vlage i unapređenje barijerne funkcije. Lagana tekstura formira providan, hidratantni sloj koji doprinosi jasnijem i svetlijem izgledu kože tokom dana. Dugoročnom upotrebom može doprineti stabilnijoj hidrataciji i otpornijoj kožnoj barijeri. Aktivni sastojci Hyaluronic PDRN (Salmon DNA PDRN + Hijaluronska kiselina) Hyaluronic PDRN predstavlja kombinaciju PDRN-a iz DNK lososa i hijaluronske kiseline povezanih u mrežu vlage. PDRN deluje kao sastojak za kondicioniranje kože koji podržava prirodne regenerativne procese. Hijaluronska kiselina vezuje vodu i povećava nivo hidratacije u rožnatom sloju. Zajedničko delovanje doprinosi jačanju hidratacione barijere. Dugoročnom primenom može pomoći u poboljšanju elastičnosti i otpornosti kože. Inkapsulacija u orb formi doprinosi stabilnosti i očuvanju efikasnosti do trenutka nanošenja. Glutation Glutation je antioksidans koji učestvuje u zaštiti kože od oksidativnog stresa. Deluje neutralizacijom slobodnih radikala. Njegova primena može doprineti ujednačenijem izgledu tena. Dugoročno može pomoći u smanjenju vidljivosti tamnih mrlja. Stabilnost zavisi od formulacije i zaštite od oksidacije. U kombinaciji sa hidratantnim kompleksima doprinosi svetlijem i zdravijem izgledu kože. Adenozin Adenozin je bioaktivna molekula koja se koristi zbog efekta na vidljivost finih linija. Deluje stimulacijom sinteze kolagena i poboljšanjem elastičnosti. Njegova primena može doprineti glađoj površini kože. Dugoročnom upotrebom može smanjiti vidljivost bora. Pokazuje dobru toleranciju u različitim tipovima kože. U sinergiji sa hidratantnim sastojcima doprinosi zategnutijem i svežijem izgledu. Dodaj u listu želja Dodaj u listu želja', 'HAUA Hyaluronic PDRN Orb Serum sadrži 30.000 ppm Hyaluronic PDRN kompleksa, kao i glutation i adenozin za dodatnu podršku posvetljavanju i smanjenju finih linija. Namenjen je koži sa oslabljenom barijerom, dehidratacijom i znakovima gubitka sjaja.', 'https://beauty-health.rs/wp-content/uploads/2026/02/HAUA-Hyaluronic-PDRN-Orb-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
