INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (105, 64, 'Fully Green Tomato Acid 20 Wash Off Peeling Serum', 'fully-green-tomato-acid-20-wash-off-peeling-serum', 'Ključne prednosti: Višeslojna eksfolijacija: kombinacija AHA, BHA i PHA uklanja mrtve ćelije sa površine i iz pora, doprinoseći glađoj teksturi. Kontrola sebuma i pora: Botanic Pore Complex i zeleni paradajz pomažu u regulaciji viška ulja i vizuelnom smanjenju proširenih pora. Ujednačavanje tena: redovnom primenom koža postaje mekša, svetlija i ujednačenijeg izgleda. Kome je namenjen? Namenjen je masnoj, mešovitoj i zadebljaloj koži sa izraženim porama i neravnom površinom. Pogodan je i za tretiranje keratoze pilaris i tamnijih regija na telu poput laktova, kolena i unutrašnje strane butina. Zašto volimo Fully Green Tomato Acid 20 Wash Off Peeling Serum? Ovaj piling serum kombinuje hemijsku eksfolijaciju sa kontrolom sebuma u jednoj formulaciji za ispiranje. Koncentracija od 21,9% AHA, BHA i PHA omogućava delovanje na više nivoa kože. Tekstura je serumasta i ravnomerno se raspoređuje bez osećaja težine. Mogućnost mešanja sa čistačem pruža fleksibilnost u intenzitetu primene. Prisustvo zelenog paradajza dodaje antioksidativnu i pore-rafinišuću komponentu. Dugoročnom upotrebom može doprineti smanjenju hrapavosti i ujednačenijem tonu kože na licu i telu. Aktivni sastojci Mlečna kiselina Mlečna kiselina je alfa-hidroksi kiselina koja deluje na površini kože razgrađujući veze između mrtvih ćelija. Njeno dejstvo podstiče ubrzanu deskuamaciju i obnavljanje epidermisa. Rezultat je glađa i mekša površina kože. Dugoročno može doprineti ujednačenijem tenu i smanjenju sitnih nepravilnosti. U poređenju sa jačim AHA kiselinama, pokazuje nešto bolju toleranciju. U kombinaciji sa drugim kiselinama omogućava višeslojni efekat eksfolijacije. Glikolna kiselina Glikolna kiselina je AHA sa malom molekulskom masom koja omogućava efikasnu penetraciju. Deluje razgradnjom korneocitnih veza i ubrzavanjem ćelijskog turnovera. Njena primena doprinosi zaglađivanju teksture i smanjenju zadebljanja. Dugoročno može poboljšati ujednačenost površine kože. Efikasnost zavisi od koncentracije i vremena kontakta sa kožom. U ovoj formuli deluje u sinergiji sa mlečnom kiselinom i PHA komponentom. Sukcinska kiselina Sukcinska kiselina je dikarboksilna kiselina sa blagim eksfolijativnim i seboregulacionim svojstvima. Deluje na površinske nepravilnosti i može doprineti smanjenju viška sebuma. Njena primena može pomoći u održavanju čistijih pora. Dugoročnom upotrebom doprinosi uravnoteženijem izgledu kože sklone nepravilnostima. Pokazuje relativno dobru toleranciju u formulacijama za ispiranje. U kombinaciji sa BHA i AHA kiselinama doprinosi sveobuhvatnijem delovanju na teksturu i pore. Glukonolakton Glukonolakton je poli-hidroksi kiselina koja pruža blagu eksfolijaciju uz hidratantni efekat. Deluje sporije od klasičnih AHA kiselina zbog veće molekulske mase. Pomaže u uklanjanju mrtvih ćelija bez izraženog iritativnog potencijala. Dugoročno može doprineti glađoj i hidriranijoj koži. Stabilan je i pogodan za osetljiviju kožu u odnosu na neke druge kiseline. U sinergiji sa AHA i BHA komponentama omogućava balans između efikasnosti i tolerancije. Zeleni paradajz Zeleni paradajz sadrži tomatidin i vitamin C koji deluju kao antioksidansi. Tomatidin se istražuje zbog potencijalne podrške otpornosti kože. Vitamin C doprinosi ujednačavanju tena i zaštiti od oksidativnog stresa. Njegovo prisustvo u formuli doprinosi vizuelnom smanjenju pora. Dugoročno može pomoći u poboljšanju teksture i elastičnosti. U kombinaciji sa kiselinama pruža dodatnu podršku obnovi kože. Dodaj u listu želja Dodaj u listu želja', 'Fully Green Tomato Acid 20 Wash Off Peeling Serum sadrži mlečnu, glikolnu, sukcinsku kiselinu i glukonolakton, kao i zeleni paradajz bogat tomatidinom i vitaminom C. Namenjen je koži sa proširenim porama, grubom teksturom, keratozom pilaris i hiperpigmentacijama na telu poput laktova i kolena.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Fully-Green-Tomato-Acid-20-Wash-Off-Peeling-Serum-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
