INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (106, 64, 'Fully Green Tomato Deep Bubble Mask', 'fully-green-tomato-deep-bubble-mask', 'Ključne prednosti: Dubinsko čišćenje pora: kombinacija tri vrste gline apsorbuje višak sebuma i površinske nečistoće bez izraženog isušivanja. Efekat mikro-mehurića: samopenjuća struktura pomaže uklanjanje ostataka iz pora uz smanjen rizik od iritacije. Ujednačavanje teksture: zeleni paradajz sa tomatidinom i vitaminom C doprinosi glađoj i vizuelno rafinisanijoj koži. Kome je namenjen? Namenjena je mešovitoj i masnoj koži sa proširenim porama i pojačanim lučenjem sebuma. Pogodna je i za kožu sklonu zadržavanju nečistoća i neravnomernoj teksturi. Zašto volimo Fully Green Tomato Deep Bubble Mask? Ova maska kombinuje klasičan princip glinene apsorpcije sa savremenim sistemom samopenjenja. Mehurići koji se formiraju nakon nanošenja doprinose osećaju temeljne, ali kontrolisane detoksikacije površine kože. Za razliku od nekih tradicionalnih glinenih maski, fokus je na čišćenju bez izraženog osećaja zatezanja. Zeleni paradajz donosi dodatnu komponentu usmerenu ka vizuelnom smanjenju pora i zaglađivanju teksture. Formula je osmišljena da balansira uklanjanje viška sebuma i očuvanje hidratacije. Dugoročnom upotrebom može doprineti urednijem izgledu pora i stabilnijem nivou masnoće kože. Aktivni sastojci Bentonit Bentonit je prirodna glina poznata po visokoj sposobnosti apsorpcije sebuma i nečistoća. Deluje vezivanjem viška ulja i zagađujućih čestica sa površine kože. Ovaj mehanizam pomaže u smanjenju zapušenosti pora. Redovnom primenom može doprineti uravnoteženijem izgledu masne kože. Njegova efikasnost zavisi od formulacije i kombinacije sa drugim hidratantnim komponentama. U ovoj maski je deo sistema sa kaolinom i hektoritom kako bi se ublažio potencijalni efekat isušivanja. Kaolin Kaolin je blaga glina koja ima sposobnost upijanja viška sebuma bez agresivnog delovanja. Deluje površinski, pomažući uklanjanje nečistoća iz pora. Njegova upotreba doprinosi čistijem i glađem izgledu kože. Dugoročno može pomoći u smanjenju vidljivosti pora kod masne kože. Poznat je po boljoj toleranciji u odnosu na jače adsorptivne gline. U kombinaciji sa drugim glinama omogućava balans između efikasnosti i komfora. Hektorite Hektorite je mineralna glina koja doprinosi stabilnosti formule i apsorpciji sebuma. Deluje kao adsorbens i pomaže uklanjanje površinskih nečistoća. Njegovo prisustvo doprinosi ravnomernoj teksturi maske i boljoj distribuciji po koži. Može pomoći u održavanju čistoće pora bez izraženog osećaja zatezanja. Stabilan je u vodenim sistemima i često se koristi za poboljšanje viskoznosti. U sinergiji sa bentonitom i kaolinom doprinosi efikasnom, ali kontrolisanom čišćenju. Zeleni paradajz (voda i sok) Zeleni paradajz je izvor tomatidina i vitamina C. Tomatidin je bioaktivno jedinjenje koje se istražuje zbog potencijalnih efekata na strukturu kože. Vitamin C deluje kao antioksidans i doprinosi ujednačenijem tenu. Kombinacija vode i soka omogućava prisustvo rastvorljivih fitonutrijenata. Dugoročnom primenom može doprineti glađem izgledu i boljoj teksturi kože. U ovoj formuli je proizveden patentiranom metodom radi očuvanja stabilnosti i kvaliteta aktivnih komponenti. Dodaj u listu želja Dodaj u listu želja', 'Fully Green Tomato Deep Bubble Mask je maska za dubinsko čišćenje pora koja formira guste mikro-mehuriće oko 30 sekundi nakon nanošenja, uz kombinaciju tri vrste gline i ekstrakta zelenog paradajza. Formulisana je da apsorbuje višak sebuma i nečistoće bez isušivanja, uz istovremeno očuvanje hidratacije kože.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Fully-Green-Tomato-Deep-Bubble-Mask-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
