INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (107, 51, 'Dr.Jart+ Ceramidin Skin Barrier Serum Toner', 'dr-jart-ceramidin-skin-barrier-serum-toner', 'Ključne prednosti: Jačanje kožne barijere: Ceramide NP i Panthenol doprinose smanjenju transepidermalnog gubitka vode i povećavaju otpornost kože. Intenzivna i dugotrajna hidratacija: klinički je zabeleženo povećanje hidratacije od 134% odmah nakon upotrebe i zadržavanje vlage do 24 sata. Poboljšanje teksture: redovnom primenom koža je glađa, mekša i ujednačenijeg osećaja na dodir. Kome je namenjen? Namenjen je svim tipovima kože, sa posebnim fokusom na suvu, dehidriranu i barijerno oslabljenu kožu. Preporučuje se osobama koje osećaju zatezanje, hrapavost ili nelagodnost nakon čišćenja lica. Zašto volimo Dr.Jart+ Ceramidin Skin Barrier Serum Toner? Ovaj proizvod spaja funkciju tonika i seruma u jednoj formulaciji bez kompromisa u efikasnosti. Tekstura je bogata, ali se ravnomerno raspoređuje i formira hidratantni bazni sloj. Klinička ispitivanja su pokazala povećanje hidratacije od 134% odmah nakon upotrebe i jačanje barijere za 34% nakon 8 sati. Dugotrajno zadržavanje vlage do 24 sata ukazuje na sposobnost formule da smanji gubitak vode. U potrošačkim ispitivanjima većina ispitanica je prijavila glađu i ujednačeniju teksturu kože nakon četiri nedelje redovne primene. Dermatološki je testiran, što dodatno potvrđuje fokus na toleranciju i bezbednost. Aktivni sastojci Ceramide NP Ceramide NP je koži identičan lipid koji ima ključnu ulogu u strukturi zaštitne barijere. Deluje tako što popunjava međučelijske prostore u rožnatom sloju i obnavlja lipidni matriks. Njegovo prisustvo doprinosi smanjenju transepidermalnog gubitka vode i povećanju otpornosti kože. Redovnom primenom jača strukturalni integritet barijere i smanjuje osećaj suvoće. Stabilan je u formulacijama sa odgovarajućim pH opsegom i dobro se kombinuje sa humektansima. U sinergiji sa Panthenolom doprinosi dugoročnom očuvanju hidratacije i funkcije kože. Pantenol Pantenol je provitamin B5 sa hidratantnim i umirujućim svojstvima. U koži se konvertuje u pantotensku kiselinu koja podržava regenerativne procese. Deluje kao humektans, vezuje vodu i doprinosi poboljšanju elastičnosti. Dugoročno može smanjiti osećaj iritacije i zatezanja kod suve kože. Pokazuje dobru toleranciju i pogodan je za osetljivu kožu. U kombinaciji sa ceramidima doprinosi jačanju barijerne funkcije i smanjenju gubitka vlage. Glicerin Glicerin je humektans koji privlači i zadržava vodu u površinskim slojevima kože. Deluje povećanjem sadržaja vlage u rožnatom sloju. Njegova sposobnost vezivanja vode doprinosi trenutnom osećaju mekoće. Dugotrajna primena može poboljšati funkciju barijere kroz održavanje optimalne hidratacije. Stabilan je i kompatibilan sa većinom aktivnih sastojaka u formulaciji. U sinergiji sa ceramidima i panthenolom omogućava uravnoteženu i postojanu hidrataciju. Dodaj u listu želja Dodaj u listu želja', 'Dr.Jart+ Ceramidin Skin Barrier Serum Toner je serum-tonik sa ceramidima NP i pantenolom formulisan da ojača kožnu barijeru, intenzivno hidrira i pripremi kožu za naredne korake nege. Namenjen je posebno suvoj i dehidriranoj koži sa oslabljenom barijernom funkcijom, uz klinički potvrđeno povećanje hidratacije i otpornosti kože.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Dr.Jart-Ceramidin-Skin-Barrier-Serum-Toner-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
