INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (109, 49, 'Dr.Ceuracle Glutathione & NMN Ampoule', 'dr-ceuracle-glutathione-nmn-ampoule', 'Ključne prednosti: Ciljana nega tamnih mrlja: Kombinacija glutationa, niacinamida i vitamina C deluje na procese formiranja melanina i doprinosi ujednačavanju tena. Antioksidativna revitalizacija: Sinergija NMN-a i glutationa podržava ćelijsku energiju i smanjuje uticaj oksidativnog stresa na kožu. Lagana oil-in-water tekstura: Omogućava brzu apsorpciju i stabilnost aktivnih sastojaka bez osećaja težine na koži. Kome je namenjena? Pogodna je za sve tipove kože, posebno za kožu sa tamnim flekama, postinflamatornim hiperpigmentacijama i neujednačenim tonom. Preporučuje se osobama koje primećuju gubitak sjaja, umoran izgled i prve znake starenja povezane sa oksidativnim oštećenjima. Zašto volimo Dr.Ceuracle Glutathione & NMN Ampoule? Formula je osmišljena tako da spoji antioksidativnu zaštitu i ciljano delovanje na pigmentacije u jednom koraku rutine. Tekstura je lagana, ali dovoljno hranljiva da koži pruži osećaj svežine bez lepljivog filma. Kombinacija glutationa i NMN-a ide dalje od klasičnog posvetljivanja i usmerena je na podršku ćelijskim procesima koji utiču na vitalnost kože. Dodatak niacinamida i stabilnih oblika vitamina C doprinosi postepenom ujednačavanju tena. Redovnom upotrebom koža deluje jasnije, odmornije i optički svetlije. Formula je dermatološki testirana, što je dodatna sigurnost za svakodnevnu primenu. Aktivni sastojci Glutation Glutation je snažan endogeni antioksidans koji učestvuje u neutralizaciji slobodnih radikala u koži. Njegova uloga u regulaciji melanogeneze zasniva se na uticaju na enzim tirozinazu i preusmeravanju sinteze melanina ka svetlijim oblicima. Na taj način doprinosi postepenom smanjenju vidljivosti tamnih mrlja i neujednačenog tona. Pored toga, štiti ćelijske strukture od oksidativnog oštećenja izazvanog UV zračenjem i zagađenjem. Dugoročno može doprineti jasnijem i svežijem izgledu kože. U ovoj formuli prisutan je u visokoj čistoći i deo je sinergijskog kompleksa za posvetljivanje. NMN (nikotinamid mononukleotid) NMN je prekursor koenzima NAD+, molekula ključnog za ćelijski energetski metabolizam. U koži doprinosi podršci procesima obnavljanja i otpornosti ćelija na stres. Povećanjem dostupnosti NAD+ indirektno utiče na antioksidativne mehanizme, uključujući ciklus regeneracije glutationa. Time podržava vitalnost i energiju kože koja deluje umorno i beživotno. Iako se NMN najčešće povezuje sa istraživanjima u oblasti starenja, u topikalnoj primeni ima ulogu podrške ćelijskim procesima. U kombinaciji sa drugim antioksidansima doprinosi svežijem i ujednačenijem izgledu tena. Niacinamid Niacinamid je oblik vitamina B3 poznat po sposobnosti da utiče na transfer melanina iz melanocita u keratinocite. Na taj način pomaže u smanjenju vidljivosti hiperpigmentacija i neujednačenog tona. Istovremeno jača kožnu barijeru podstičući sintezu ceramida i smanjujući transepidermalni gubitak vode. Ima i umirujuće dejstvo, što je važno kod kože sklone crvenilu i iritacijama. Redovnom primenom doprinosi glađoj teksturi i uravnoteženijem izgledu tena. U ovoj ampuli deo je Triple Glow Complex mešavine koja podržava efekat posvetljivanja. Vitamin C kompleks Vitamin C i njegovi stabilni derivati deluju kao antioksidansi koji neutralizuju slobodne radikale nastale pod uticajem UV zračenja. Učestvuju u inhibiciji tirozinaze, čime doprinose smanjenju formiranja tamnih mrlja. Takođe podstiču sintezu kolagena, što je značajno za očuvanje čvrstine i elastičnosti kože. Stabilni oblici u formulaciji omogućavaju bolju toleranciju i postepen efekat bez naglašene iritacije. Dugoročno doprinose svetlijem i ujednačenijem tenu. U kombinaciji sa glutationom deluju sinergijski na antioksidativnu zaštitu. Hippophae Rhamnoides Fruit Juice Ekstrakt ploda pasjeg trna bogat je vitaminima, flavonoidima i karotenoidima koji imaju antioksidativno dejstvo. Doprinosi zaštiti kože od oksidativnog stresa i podržava prirodni sjaj tena. Njeg', 'Dr.Ceuracle Glutathione & NMN Ampoule je koncentrisana ampula za posvetljivanje i revitalizaciju kože, formulisana sa 2% glutationa i NMN-a, uz 5% Triple Glow Complex mešavine koja uključuje niacinamid, vitamin C kompleks i ekstrakt ploda pasjeg trna. Namenjena je koži sa hiperpigmentacijama, neujednačenim tonom i izraženim sivkastim izgledom koji je posledica oksidativnog stresa i disbalansa melanina.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Dr.Ceuracle-Glutathione-NMN-Ampoule-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
