INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (110, 48, 'Dr. Althea 345 Relief Cream Mist', 'dr-althea-345-relief-cream-mist', 'Ključne prednosti: Dvoslojna hidratacija: kombinacija lagane esencije i kremastih emolijenata omogućava istovremeno osveženje i zadržavanje vlage bez osećaja težine. Umirujući efekat: madecassoside, aloe i centella doprinose smanjenju osećaja nelagodnosti i podržavaju oporavak osetljive kože. Praktična primena tokom dana: fina raspršena magla omogućava ravnomerno nanošenje pre ili posle šminke bez narušavanja tena. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, dehidriranu i mešovitu kožu sklonu crvenilu ili zatezanju. Posebno odgovara osobama koje provode mnogo vremena u klimatizovanom prostoru ili traže lagan oblik hidratacije bez dodatnog sloja teške kreme. Zašto volimo Dr. Althea 345 Relief Cream Mist? Formula je osmišljena tako da spoji negu i praktičnost u jednom koraku. Nakon mućkanja, dva sloja se pretvaraju u finu, ujednačenu maglu koja koži vraća osećaj svežine bez lepljivog traga. Kremasti deo pruža hranljive komponente koje pomažu zadržavanje vlage, dok vodeni deo daje trenutni osvežavajući efekat. Ovakva kombinacija je korisna kada koža tokom dana postane zategnuta ili umorna. Redovnom upotrebom doprinosi stabilnijoj hidrataciji i smanjenju prolazne osetljivosti. Lako se uklapa u postojeću rutinu, bilo kao tonik, priprema za šminku ili dodatni sloj nege preko dana. Predstavlja praktično rešenje za održavanje balansa kože bez komplikovane rutine. Aktivni sastojci Pirinčana voda (Oryza Sativa Rice Bran Water) Pirinčana voda je tradicionalno korišćen sastojak u nezi kože zbog visokog sadržaja vitamina, minerala i antioksidanasa. U kozmetičkim formulama deluje kao blagi hidratantni i negujući sastojak koji doprinosi mekšem i zaglađenijem izgledu kože. Sadrži aminokiseline i prirodne šećere koji pomažu očuvanju vlažnosti u površinskim slojevima epidermisa. Redovnom primenom može doprineti ujednačenijem i svežijem tenu. Posebno je pogodna za kožu koja deluje umorno ili beživotno. U ovoj formuli ima ulogu nutritivne osnove kremastog sloja. Hidrolizovana hijaluronska kiselina Hidrolizovana hijaluronska kiselina ima manju molekulsku masu u odnosu na klasičnu hijaluronsku kiselinu, što omogućava bolju raspodelu po površini kože. Deluje kao humektans, vezujući vodu i doprinoseći povećanju nivoa hidratacije. Pomaže u smanjenju osećaja zatezanja i suvoće. Redovnom upotrebom koža deluje elastičnije i mekše na dodir. Ne deluje okluzivno, već podržava prirodne mehanizme zadržavanja vlage. U kombinaciji sa drugim umirujućim sastojcima doprinosi uravnoteženom izgledu kože. Pantenol Pantenol, poznat i kao provitamin B5, ima izražena hidratantna i umirujuća svojstva. U koži se pretvara u pantotensku kiselinu, koja učestvuje u procesima regeneracije epidermisa. Doprinosi jačanju zaštitne barijere i smanjenju transepidermalnog gubitka vode. Koristan je kod kože sklone crvenilu i iritacijama. Redovnom primenom može poboljšati osećaj komfora i otpornost kože na spoljašnje uticaje. U ovoj formuli ima ključnu ulogu u podršci hidrataciji i smirivanju kože. Madecassoside Madecassoside je bioaktivna komponenta biljke Centella Asiatica, poznata po umirujućem i regenerativnom delovanju. Deluje tako što pomaže modulaciju inflamatornih procesa u koži. Doprinosi smanjenju vidljivog crvenila i osećaja iritacije. Podržava obnovu kožne barijere i poboljšava otpornost kože na spoljašnje stresore. Posebno je koristan kod osetljive i reaktivne kože. U ovoj dvoslojnoj formuli predstavlja ključni sastojak vodenog dela namenjenog umirenju. Ekstrakt lista centelle Ekstrakt lista centelle sadrži triterpene i druge bioaktivne supstance koje su povezane sa regenerativnim efektima na kožu. Podstiče procese obnove i doprinosi očuvanju integriteta kožne barijere. Može pomoći u smanjenju osećaja nelagodnosti kod kože sklone osetljivosti. Dugoročnom upotrebom doprinosi stabilnijem i uravnoteženijem izgledu tena. Često se koristi u formulama ', 'Dr. Althea 345 Relief Cream Mist je dvoslojni hidratantni sprej koji kombinuje kremasti sloj sa pirinčanom vodom, hijaluronskom kiselinom i pantenolom i vodeni sloj sa madecassoside-om, aloe verom i ekstraktom centelle za trenutno umirenje i podršku kožnoj barijeri. Formulisan je za kožu koja pokazuje znake dehidratacije, zatezanja i prolazne osetljivosti tokom dana, posebno u uslovima suvog vazduha i temperaturnih promena.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Dr.-Althea-345-Relief-Cream-Mist-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
