INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (111, 43, 'd&#8217;Alba Vita Toning Serum Toner', 'dalba-vita-toning-serum-toner', 'Ključne prednosti: Vidljivo ujednačavanje tena: Kombinacija vitamina C, glutationa i niacinamida deluje na tamne mrlje i neujednačen ton kože. Poboljšanje sjaja i svežine: Antioksidativna formula doprinosi svetlijem i zdravijem izgledu kože. Podrška elastičnosti: Aktivni sastojci pomažu očuvanju čvrstine i smanjenju vidljivosti finih linija. Kome je namenjen? Pogodan je za normalnu, suvu, kombinovanu i zrelu kožu sa znakovima umora, hiperpigmentacijama i neujednačenim tonom. Posebno odgovara osobama koje žele antioksidativnu zaštitu i postepeno posvetljivanje bez agresivnih kiselinskih tretmana. Zašto volimo d&#8217;Alba White Truffle Vita Toning Serum Toner? Tekstura balansira između tonika i seruma, pa pruža više od klasične hidratacije bez osećaja težine. Formula je usmerena na ciljano posvetljivanje, ali uz istovremenu podršku barijeri kože. Liposomski inkapsuliran glutation omogućava stabilniju isporuku antioksidansa u kožu. Kombinacija vitamina C i niacinamida doprinosi ujednačenijem tonu bez narušavanja komfora. Italijanski beli tartuf dodaje nutritivnu i antioksidativnu dimenziju formuli. Redovnom primenom koža deluje glađe, svežije i vizuelno uravnoteženije. Proizvod se lako uklapa u rutinu kao prvi aktivni korak nakon čišćenja. Aktivni sastojci Vitamin C (99% čist) Vitamin C je snažan antioksidans koji pomaže u neutralizaciji slobodnih radikala nastalih usled UV zračenja i zagađenja. Deluje na ujednačavanje tena tako što utiče na procese vezane za stvaranje melanina. Redovnom upotrebom može doprineti smanjenju vidljivosti tamnih mrlja i beživotnog izgleda kože. Podržava sintezu kolagena, što je važno za očuvanje čvrstine i elastičnosti. Takođe doprinosi svežijem i svetlijem izgledu tena. Njegovo delovanje je najefikasnije uz doslednu upotrebu i adekvatnu SPF zaštitu. Glutation (98% čist, liposomski inkapsuliran) Glutation je endogeni antioksidans poznat po ulozi u zaštiti ćelija od oksidativnog stresa. U kozmetičkim formulama koristi se zbog potencijala da doprinese posvetljivanju i ujednačavanju tena. Liposomska tehnologija omogućava bolju stabilnost i efikasniju isporuku sastojka u kožu. Deluje sinergijski sa vitaminom C, pojačavajući antioksidativnu zaštitu. Može pomoći u smanjenju vidljivosti hiperpigmentacija. Dugoročno doprinosi jasnijem i svetlijem izgledu kože. Niacinamid (2%) Niacinamid je oblik vitamina B3 poznat po sposobnosti da ujednači ton i poboljša funkciju kožne barijere. Deluje tako što pomaže u regulaciji prenosa melanina, čime doprinosi smanjenju tamnih mrlja. Takođe može pomoći u regulaciji sebuma kod kombinovane i masne kože. Podržava sintezu ceramida, što je važno za smanjenje gubitka vlage. Poboljšava teksturu kože i smanjuje vidljivost pora. U koncentraciji od 2% deluje blago i pogodan je za svakodnevnu upotrebu. Ekstrakt italijanskog belog tartufa Ekstrakt belog tartufa bogat je aminokiselinama i antioksidativnim jedinjenjima. U kozmetičkim formulama koristi se zbog nutritivnog i zaštitnog delovanja. Doprinosi poboljšanju vitalnosti i opšteg izgleda kože. Može pomoći u zaštiti kože od spoljašnjih stresora. Deluje kao podrška antioksidativnom sistemu formule. Dugoročno doprinosi očuvanju zdravog i svežeg tena. Dodaj u listu želja Dodaj u listu želja', 'd&#8217;Alba White Truffle Vita Toning Serum Toner je tonik-serum formulisan sa 99% čistim vitaminom C, 98% glutationom i 2% niacinamidom, uz dodatak italijanskog belog tartufa, sa ciljem posvetljivanja i ujednačavanja tena. Namenjen je koži koja deluje umorno, bez sjaja i sa vidljivim hiperpigmentacijama, uz potrebu za blagim poboljšanjem elastičnosti i teksture.', 'https://beauty-health.rs/wp-content/uploads/2026/02/dAlba-Vita-Toning-Serum-Toner-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
