INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (113, 32, 'Centellian24 Madeca Cream Time Reverse', 'centellian24-madeca-cream-time-reverse', 'Ključne prednosti: Podrška elastičnosti i čvrstini: Kombinacija retinola, adenozina i centella kompleksa doprinosi vidljivom poboljšanju tonusa i smanjenju pojave finih linija. Dugotrajna hidratacija i obnova barijere: Active-TECA&#x2122;, hijaluronska kiselina i kolagen pomažu očuvanju vlažnosti i jačanju otpornosti kože. Ujednačavanje i revitalizacija tena: Formula je usmerena na smanjenje vidljivosti tamnih mrlja i vraćanje zdravog, uravnoteženog izgleda kože. Kome je namenjena? Namenjena je svim tipovima kože koje pokazuju prve ili izraženije znake starenja, uključujući suvu, normalnu i kombinovanu kožu sa gubitkom elastičnosti. Posebno odgovara osobama sa finim linijama, opuštenom konturom lica i neujednačenim tenom, uključujući kožu izloženu hroničnom stresu i spoljašnjim uticajima. Zašto volimo Centellian24 Madeca Cream Time Reverse? Ova krema spaja dermatološku tradiciju i savremenu formulaciju u proizvod koji ne deluje agresivno, ali je jasno usmeren na strukturne promene kože. Tekstura je balans između kreme i losiona, dovoljno hranljiva za suvlje tipove, ali bez teškog osećaja na koži. Formula koristi liposomalnu tehnologiju kako bi aktivne supstance dospele dublje i ravnomernije, što je važno kod sastojaka poput retinola. Madeca&#x2122; kompleks sa više frakcija centelle daje dodatnu dimenziju umirujućeg i reparativnog efekta. Uz redovnu upotrebu koža deluje zategnutije, punije i ujednačenije, bez osećaja preopterećenosti. Posebno je dragocena kao centralni anti-age korak u rutini, bez potrebe za složenim kombinacijama više proizvoda. Aktivni sastojci Active-TECA&#x2122; (titrirani ekstrakt Centella asiatica) Active-TECA&#x2122; predstavlja visoko pročišćeni ekstrakt centelle standardizovan na ključne triterpene, uključujući asiaticoside, asiatic acid i madecassic acid. Ove supstance su poznate po sposobnosti da podstiču sintezu kolagena i doprinesu obnovi oštećene kože. Deluju tako što stimulišu fibroblaste i ubrzavaju procese reparacije u dermisu. Istovremeno pomažu u smanjenju inflamatornih reakcija, što je važno kod osetljive i reaktivne kože. Dugoročno doprinose boljoj otpornosti kože na spoljašnje faktore. U anti-age formulama imaju važnu ulogu u očuvanju čvrstine i smanjenju vidljivosti bora. Retinol Retinol je derivat vitamina A sa dokazanom ulogom u ubrzavanju ćelijske obnove i stimulaciji kolagena. Deluje na nivou epidermisa i dermisa, gde podstiče bržu smenu ćelija i smanjuje zadebljanja rožnatog sloja. Redovnom upotrebom može doprineti smanjenju finih linija, neravne teksture i hiperpigmentacija. Takođe utiče na regulaciju sebuma, što je korisno i kod kombinovane kože. Njegovo dejstvo je postepeno i zahteva doslednost u primeni. U ovoj formuli kombinovan je sa umirujućim sastojcima kako bi se smanjio rizik od iritacije. Hijlauronska kiselina Hijlauronska kiselina je humektant koji ima sposobnost vezivanja velike količine vode u odnosu na sopstvenu masu. Njena primarna funkcija je da poveća nivo hidratacije u površinskim slojevima kože. Hidrirana koža izgleda punije, a fine linije su manje izražene. Pomaže u očuvanju elastičnosti i smanjenju osećaja zatezanja. U kombinaciji sa reparativnim sastojcima doprinosi boljem oporavku kože. Njeno dejstvo je podržavajuće i ključno za održavanje barijerne funkcije. Kolagen Kolagen u topikalnim formulama deluje prvenstveno kao hidratantni i film-formirajući sastojak. Na površini kože stvara zaštitni sloj koji smanjuje transepidermalni gubitak vode. Time doprinosi privremenom efektu zategnutosti i zaglađenosti. Iako molekularno ne prodire duboko u dermis, njegova uloga u poboljšanju teksture i mekoće kože je značajna. U kombinaciji sa sastojcima koji stimulišu sopstvenu sintezu kolagena, ima komplementarnu funkciju. Pomaže da koža deluje punije i vizuelno ujednačenije. Adenozin Adenozin je bioaktivna supstanca poznata po svom delovanju na smanjenje vidljivosti bora. De', 'Centellian24 Madeca Cream Time Reverse je anti-age krema razvijena na farmaceutskoj osnovi, sa kombinacijom Active-TECA&#x2122;, Madeca&#x2122; kompleksa, retinola, hijaluronske kiseline i kolagena, sa ciljem da istovremeno deluje na elastičnost, hidrataciju i vidljive znake starenja. Formulisana je za kožu sa izraženim borama, opuštenošću i neujednačenim tonom, kojoj je potrebna obnova i jačanje barijere bez agresivnog pristupa.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Centellian24-Madeca-Cream-Time-Reverse-6.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
