INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (116, 18, 'Banila Co Clean It Zero Ceramide Cleansing Balm', 'banila-co-clean-it-zero-ceramide-cleansing-balm', 'Ključne prednosti Efikasno uklanjanje šminke u jednom koraku: Balzam se topi u ulje koje rastvara tešku šminku, SPF i višak sebuma bez agresivnog trljanja. Očuvanje kožne barijere tokom čišćenja: Ceramidi i biljna ulja pomažu da koža ostane meka i hidrirana nakon ispiranja. Prijatna šerbet tekstura bez iritacije: Mekana struktura prelazi u svilenkasto ulje i lako se emulguje vodom, ostavljajući kožu čistom bez masnog filma. Kome je namenjen? Namenjen je svim tipovima kože, posebno suvoj, osetljivoj i koži sa narušenom barijerom. Pogodan je i za osobe koje redovno koriste tešku šminku ili vodootporne proizvode i žele temeljno, ali nežno prvo čišćenje. Zašto volimo Banila Co Clean It Zero Ceramide Cleansing Balm? Ovaj balzam menja teksturu čim dođe u kontakt sa kožom i omogućava lako razlaganje šminke bez osećaja zatezanja. Koža nakon ispiranja ostaje čista, ali ne i ogoljena. Ceramidi u formuli daju dodatnu sigurnost da se barijera neće nepotrebno narušiti tokom svakodnevnog čišćenja. Biljna ulja doprinose klizavosti tokom masaže, što smanjuje trenje i iritaciju. Emulzija sa vodom je brza i ravnomerna, bez ostataka. Ambalaža je napravljena od ekološki prihvatljivih i biorazgradivih materijala, uz vegansku formulaciju koja ne sadrži sastojke životinjskog porekla. Aktivni sastojci Ceramidi Ceramidi su ključni lipidi prisutni u rožnom sloju kože i imaju centralnu ulogu u očuvanju barijerne funkcije. U formulama za čišćenje pomažu da se smanji gubitak vlage tokom ispiranja. Podržavaju strukturu međućelijskog lipidnog sloja. Njihovo prisustvo doprinosi osećaju mekoće i elastičnosti nakon čišćenja. Posebno su važni kod suve i osetljive kože. Dugoročnom upotrebom pomažu u održavanju stabilnije i otpornije barijere. Ulje semena jojobe Ulje jojobe je estarsko ulje slične strukture prirodnom sebumu kože. Deluje kao emolijens i pomaže u rastvaranju masnih nečistoća i šminke. Ne ostavlja težak, lepljiv trag nakon ispiranja. Doprinosi očuvanju mekoće kože tokom procesa čišćenja. Pogodno je i za osetljivu kožu jer se generalno dobro toleriše. U ovoj formuli ima ulogu rastvarača i omekšivača. Ulje noćurka Ulje noćurka bogato je esencijalnim masnim kiselinama, posebno gama-linolenskom kiselinom. Doprinosi očuvanju lipidne ravnoteže kože. Može pomoći u smanjenju osećaja suvoće i zatezanja. Podržava elastičnost i mekoću kože. Često se koristi u formulama namenjenim osetljivoj i suvoj koži. U kombinaciji sa ceramidima doprinosi boljoj toleranciji proizvoda. Glicerin Glicerin je humektant koji privlači vodu i pomaže u održavanju hidratacije kože. Tokom čišćenja smanjuje rizik od prekomernog isušivanja. Doprinosi osećaju glatkoće nakon ispiranja. Pogodan je za sve tipove kože, uključujući osetljivu. Podržava funkciju kožne barijere. U ovoj formuli pomaže da koža ostane prijatna i uravnotežena nakon uklanjanja šminke. Dodaj u listu želja Dodaj u listu želja', 'Banila Co Clean It Zero Ceramide Cleansing Balm sadrži ceramide, ulje semena jojobe, ulje noćurka i glicerin kako bi tokom čišćenja uklonio tešku šminku i SPF, a istovremeno podržao kožnu barijeru i zadržavanje vlage. Namenjen je suvoj, dehidriranoj i osetljivoj koži kojoj klasični čistači mogu ostaviti osećaj zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Banila-Co-Clean-It-Zero-Ceramide-Cleansing-Balm-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
