INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (117, 14, 'Arencia Red Smoothie Lotion 5', 'arencia-red-smoothie-lotion-5', 'Ključne prednosti Regulacija sebuma i ujednačavanje teksture: 5% niacinamida pomaže u kontroli viška sebuma i vidljivom zaglađivanju površine kože. Podrška elastičnosti i čvrstini: 9 tipova peptida i kolagen doprinose boljoj strukturi i otpornosti kože. Hidratacija bez lepljivog osećaja: Lagana mlečna tekstura sa ovsenim mlekom i humektantima pruža komfor i svilenkast završetak. Kome je namenjen? Namenjen je normalnoj, mešovitoj i masnijoj koži koja traži balans između hidratacije i regulacije sebuma. Pogodan je i za kožu sa blagim nepravilnostima u teksturi, sivkastim tonom i prvim znakovima gubitka elastičnosti. Zašto volimo Arencia Red Smoothie Lotion 5? Ova losion emulzija ima teksturu koja se lako razmazuje i brzo stapa sa kožom bez osećaja težine. Koža nakon nanošenja deluje mekše i vizuelno ujednačenije, bez masnog sjaja. Kombinacija niacinamida i peptida daje smislen pristup – istovremeno se radi na teksturi i podršci elastičnosti. Ekstrakt maline unosi antioksidativnu komponentu koja je korisna kod kože izložene spoljašnjim uticajima. Red Smoothie Milk Complex&#x2122; doprinosi kremastoj strukturi i osećaju komfora tokom dana. Lako se uklapa u jutarnju rutinu jer ne ostavlja lepljiv trag i ne utiče na nanošenje šminke. Aktivni sastojci Niacinamid 5% Niacinamid je oblik vitamina B3 koji ima višestruko delovanje na kožu. U koncentraciji od 5% pokazuje efikasnost u regulaciji lučenja sebuma i smanjenju vidljivosti pora. Doprinosi ujednačavanju tena i smanjenju blagih hiperpigmentacija. Podržava sintezu ceramida i jača zaštitnu barijeru kože. Može smanjiti pojavu crvenila i nepravilnosti kod reaktivne kože. Redovnom upotrebom koža deluje glađe i uravnoteženije. Ekstrakt maline Ekstrakt maline je bogat antioksidativnim jedinjenjima, uključujući polifenole i vitamine. Pomaže u neutralisanju slobodnih radikala koji nastaju usled spoljašnjih stresora. Doprinosi očuvanju svežeg i zdravog izgleda kože. Može imati blago umirujuće delovanje. Podržava ukupnu otpornost kože. U ovoj formuli ima ulogu dodatne zaštite i revitalizacije. 9 tipova peptida Peptidi su kratki lanci aminokiselina koji deluju kao signalne molekule u koži. U kozmetici se koriste za podršku elastičnosti i čvrstini. Kombinacija više tipova peptida omogućava širi spektar delovanja na površinskim slojevima kože. Mogu doprineti poboljšanju teksture i smanjenju izgleda finih linija. Podržavaju procese obnove i otpornosti kože. U sinergiji sa hidratantnim sastojcima pomažu u očuvanju mladolikog izgleda. Red Smoothie Milk Complex&#x2122; (kolagen i ovseno mleko) Kolagen u kozmetičkim formulama deluje kao hidratantni i film-formirajući sastojak. Pomaže u zadržavanju vlage na površini kože i doprinosi glatkoći. Ovseno mleko je poznato po umirujućim i zaštitnim svojstvima. Sadrži komponente koje podržavaju kožnu barijeru i smanjuju osećaj zatezanja. Zajedno daju kremastu teksturu i osećaj komfora. U ovoj formuli doprinose hidrataciji i mekoći kože bez težine. Dodaj u listu želja Dodaj u listu želja', 'Arencia Red Smoothie Lotion 5 kombinuje 5% niacinamida, antioksidativni ekstrakt maline, 9 tipova peptida i Red Smoothie Milk Complex&#x2122; sa kolagenom i ovsenim mlekom kako bi pružila hidrataciju, podržala barijeru i doprinela glađem, elastičnijem izgledu kože. Namenjena je koži sa neujednačenom teksturom, proširenim porama i pojačanim lučenjem sebuma kojoj je potrebna lagana, ali hranljiva nega.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Arencia-Red-Smoothie-Lotion-5-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
