INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (122, 138, 'Pyunkang Yul Ultimate Calming Solution Ampoule Outlet', 'pyunkang-yul-ultimate-calming-solution-ampoule-outlet', 'Ključne prednosti: Dubinski čisti i osvežava: Ekstrakt zelenog čaja sa Jejua uklanja nečistoće i višak sebuma, a istovremeno smiruje kožu. Ne isušuje kožu: Biljna ulja i glicerin održavaju prirodnu vlagu i elastičnost kože. Prirodna formula: Bez sulfata, parabena i veštačkih boja, pogodna i za osetljivu kožu. Kome je namenjen? Preporučuje se za problematičnu, osetljivu, masnu i kombinovanu kožu, kao i za one koji se bore sa povremenim iritacijama, aknama ili oslabljenom barijerom. Idealna je i posle tretmana (peeling, laser, microneedling) kada je koži potrebna regeneracija i smirenje. Zašto volimo Pyunkang Yul Ultimate Calming Solution Ampoule? Ova ampula je pravi „spasilac“ za problematičnu i osetljivu kožu — deluje umirujuće, regenerativno i balansirajuće. Zahvaljujući kompleksu biljnih ekstrakata i visokokoncentrovanom Cica kompleksu (Centella Asiatica, Madecassoside, Asiaticoside), vidljivo smanjuje crvenilo i ubrzava regeneraciju kože. Ulje i ekstrakt čajevca deluju antibakterijski i pročišćavaju pore, dok Houttuynia Cordata ima protivupalna svojstva i pomaže u obnavljanju kože posle bubuljica. Ceramide NP i Panthenol učvršćuju lipidnu barijeru, sprečavaju dehidrataciju i vraćaju elastičnost, dok Beta-glukan zadržava vlagu i ubrzava zarastanje mikropovreda. Rezultat je koža koja već posle nekoliko dana izgleda smirenije, čistije i otpornije. Aktivni sastojci Centella Asiatica Extract (umirujuće, regenerativno delovanje; bogata madecassoside-om i asiaticoside-om koji obnavljaju oštećenu kožu i smanjuju crvenilo) Melaleuca Alternifolia (Tea Tree) Extract & Oil (antibakterijsko, čisti pore i sprečava pojavu akni) Houttuynia Cordata Extract (protivupalno, smanjuje osip i iritacije, odličan za osetljivu i problematičnu kožu) Ceramide NP (obnavlja i jača zaštitni sloj kože, sprečava gubitak vlage) Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Ultimate Calming Solution Ampoule je koncentrisana ampula protiv iritacija i akni, formulisana sa patentiranom umirujućom formulom koja donosi vidljivo poboljšanje u samo 3 dana. Kombinuje Cica kompleks, ekstrakt čajevca i ceramide kako bi obnovila kožnu barijeru, smanjila crvenilo i upale, i vratila koži ravnotežu i čistoću. Tekstura je lagana, ali hranljiva — brzo se upija i ostavlja osećaj svežine bez lepljivog filma.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Pyunkang-Yul-Ultimate-Calming-Solution-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
