INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (123, 109, 'Manyo Pure Cleansing Oil', 'manyo-pure-cleansing-oil', 'Ključne prednosti Dubinsko čišćenje pora: Rastvara sebum, mitisere i nečistoće bez zapušavanja pora. Očuvanje hidratacije: Čisti kožu bez narušavanja njenog prirodnog lipidnog sloja. Balans pH vrednosti: Ostavlja kožu smirenom i pripremljenom za naredne korake nege. Kome je namenjeno? Namenjen je svim tipovima kože, uključujući masnu, mešovitu i kožu sklonu aknama. Pogodan je i za osetljivu kožu koja ne podnosi agresivne sredstva za čišćenje. Zašto volimo Manyo Pure Cleansing Oil? Ulje se pri kontaktu sa vodom pretvara u mlečnu emulziju koja efikasno uklanja šminku i nečistoće sa površine kože. Ovaj mehanizam omogućava temeljno čišćenje bez agresivnog trenja. Biljna ulja u formuli rastvaraju masne nečistoće koje se zadržavaju u porama, što doprinosi čišćem i ujednačenijem izgledu kože. Nakon ispiranja koža ostaje mekana i bez osećaja zatezanja. Formula je prilagođena svakodnevnoj upotrebi, uključujući i jutarnje čišćenje kod suvlje ili osetljive kože. Dugoročno doprinosi stabilnijem balansu kože i smanjenju nepravilnosti povezanih sa zapušenim porama. Aktivni sastojci Kompleks biljnih ulja (14 vrsta) Ovaj kompleks se sastoji od pažljivo odabranih biljnih ulja čija je uloga rastvaranje masnih nečistoća i viška sebuma. Ulja se vezuju za nečistoće u porama i omogućavaju njihovo uklanjanje bez narušavanja kožne barijere. Ovakav pristup čišćenju smanjuje potrebu za agresivnim surfaktantima. Koža nakon ispiranja ostaje mekana i uravnotežena. Dugoročno se smanjuje osećaj zatezanja nakon umivanja. Kompleks je prilagođen i osetljivoj koži. Arganovo ulje Arganovo ulje je bogato masnim kiselinama i antioksidansima koji doprinose očuvanju elastičnosti kože. Pomaže u regulaciji lučenja sebuma i sprečava prekomerno isušivanje tokom čišćenja. Njegova struktura omogućava lako ispiranje bez zaostajanja masnog filma. Doprinosi obnovi kože nakon uklanjanja šminke. Posebno je korisno kod kože koja reaguje isušivanjem na klasične čistače. U ovoj formuli ima nutritivnu i balansirajuću ulogu. Ulje semenki jojobe Ulje jojobe po strukturi podseća na prirodni sebum kože, zbog čega se dobro integriše u njenu lipidnu ravnotežu. Pomaže u održavanju hidratacije tokom procesa čišćenja. Smanjuje rizik od iritacija i osećaja zatezanja. Doprinosi glatkoći i mekoći kože nakon umivanja. Pogodno je za kožu sklonu nepravilnostima jer ne zapušava pore. U okviru ove formule deluje kao stabilizujući emolijens. Dodaj u listu želja Dodaj u listu želja', 'Manyo Pure Cleansing Oil je blago, ali efikasno ulje za čišćenje koje uklanja šminku, nečistoće i višak sebuma uz očuvanje prirodne ravnoteže kože. Manyo Pure Cleansing Oil koristi kombinaciju biljnih ulja kako bi se otopili mitiseri i nečistoće iz pora, dok se koža nakon ispiranja zadržava hidriranom i bez osećaja zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2026/02/Manyo-Pure-Cleansing-Oil-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
