INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (124, 168, 'UNOVE No-Wash Water Ampoule Treatment', 'unove-no-wash-water-ampoule-treatment', 'Ključne prednosti Reparacija bez ispiranja: Proteinski kompleks deluje na površinu vlasi i smanjuje vidljivost oštećenja bez potrebe za ispiranjem. Hidratacija i sjaj: Biljna ulja i biljni ekstrakti doprinose mekoći i boljoj refleksiji svetlosti. Zaštita od mehaničkog oštećenja: Pomaže u jačanju kutikule i smanjenju lomljenja i rascvetalih krajeva. Kome je namenjen? Namenjen je oštećenoj, suvoj i hemijski tretiranoj kosi, kao i kosi sklonoj rascvetalim krajevima. Pogodan je i za tanku kosu kojoj je potrebna zaštita bez dodatne težine. Zašto volimo Unove No-Wash Water Ampoule Treatment? Vodena tekstura omogućava ravnomerno nanošenje bez stvaranja teškog sloja na kosi. Proteini i amino-kiseline privremeno jačaju oštećene delove vlasi i poboljšavaju otpornost na češljanje i stilizovanje. Biljna ulja obezbeđuju fleksibilnost i sprečavaju isušivanje krajeva, što je posebno važno kod kose tretirane toplotom. Redovnom upotrebom kosa postaje mekša i manje sklona zapetljavanju. Površina vlasi dobija ujednačeniji izgled, što se vidi kroz povećan sjaj. Tretman je praktičan za svakodnevnu upotrebu jer se ne ispira i ne opterećuje kosu. Aktivni sastojci Kompleks proteina i amino-kiselina (25 vrsta) Ovaj kompleks sadrži različite proteinske fragmente i amino-kiseline koji se vezuju za oštećene delove kutikule. Njihova uloga je da privremeno popune neravnine na površini vlasi i smanje lomljenje. Time se poboljšava otpornost kose na mehanički stres tokom stilizovanja. Redovnom upotrebom kosa postaje elastičnija i manje sklona pucanju. Ovaj efekat je posebno važan kod kose tretirane toplotom i hemikalijama. Kompleks doprinosi i ujednačenijem izgledu vlasi duž cele dužine. Ulje semenki kamelije Ulje kamelije je lagani emolijens bogat masnim kiselinama koje omekšavaju površinu vlasi. Pomaže u smanjenju gubitka vlage i poboljšava fleksibilnost kose. Doprinosi glađem osećaju i boljoj klizavosti tokom raščešljavanja. Na vizuelnom nivou doprinosi jačem sjaju. Posebno je korisno za suve i porozne krajeve. U ovoj formuli je prilagođeno tako da ne opterećuje kosu. Arganovo ulje Arganovo ulje sadrži lipide koji jačaju zaštitni sloj vlasi i smanjuju isušivanje. Doprinosi elastičnosti i smanjuje hrapavost površine kose. Pomaže u kontroli friza i olakšava stilizovanje. Redovnom upotrebom kosa postaje mekša i otpornija na spoljašnje uticaje. Posebno je korisno kod kose izložene toploti i suncu. U kombinaciji sa proteinima daje balans između čvrstoće i mekoće. Ekstrakt algi (kelp) Ekstrakt algi je bogat mineralima i polisaharidima koji pomažu u hidrataciji vlasi. Doprinosi zadržavanju vlage i smanjenju suvoće dužine kose. Podržava zdraviji izgled kose kroz poboljšanje njene fleksibilnosti. Ima i zaštitnu ulogu protiv spoljašnjih stresora. Dugoročno doprinosi boljem kvalitetu površine vlasi. U ovoj formuli ima potpornu, hidratantnu funkciju. Dodaj u listu želja Dodaj u listu želja', 'Unove No-Wash Water Ampoule Treatment je vodena esencija za kosu bez ispiranja namenjena jačanju oštećenih vlasi, smanjenju lomljenja i poboljšanju sjaja. No-Wash Water Ampoule Treatment kombinuje kompleks od 25 proteina i amino-kiselina sa biljnim uljima i ekstraktom algi kako bi kosa bila hidrirana, zaglađena i vizuelno zdravija bez otežavanja.', 'https://beauty-health.rs/wp-content/uploads/2026/01/UNOVE-No-Wash-Water-Ampoule-Treatment-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
