INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (126, 168, 'Unove Deep Damage Repair Shampoo', 'unove-deep-damage-repair-shampoo', 'Ključne prednosti Obnova oštećene strukture vlasi: Proteini i amino-kiseline doprinose jačanju kutikule i smanjenju lomljenja i rascvetalih krajeva. Balans temena: Blago kiseli pH pomaže održavanju prirodne uljno-vlažne ravnoteže kože glave. Temeljno, ali blago čišćenje: Uklanja višak sebuma i nečistoće bez narušavanja zaštitnog sloja temena. Detaljan opis benefita Kome je namenjen Namenjen je suvoj, hemijski tretiranoj i mehanički oštećenoj kosi, uključujući kosu sklonu lomljenju i rascvetalim krajevima. Pogodan je i za osetljivo teme kojem je potrebna blaga, ali efikasna rutina čišćenja. Zašto volimo Unove Deep Damage Repair Shampoo Formula šampona je osmišljena da istovremeno čisti teme i pruža potporu oštećenoj kosi duž cele dužine. Visoka zastupljenost proteinskih komponenti pomaže u popunjavanju oštećenih delova kutikule, čime se smanjuje mehaničko oštećenje tokom češljanja i stilizovanja. Blago kiseli pH doprinosi zatvaranju kutikule, što se odražava na glađu i sjajniju površinu vlasi. Biljna ulja pružaju dodatnu fleksibilnost kosi bez teškog, masnog osećaja. Čišćenje temena je temeljno, ali ne agresivno, pa se smanjuje rizik od isušivanja i iritacija. Dugoročno, kosa postaje otpornija, mekša i lakša za oblikovanje. Aktivni sastojci Kompleks proteina i amino-kiselina (30 vrsta) Ovaj kompleks sadrži različite tipove proteinskih fragmenata i amino-kiselina koje učestvuju u jačanju strukture vlasi. Njihova uloga je da se vežu za oštećene delove kutikule i privremeno popune mikropukotine nastale hemijskim i mehaničkim oštećenjima. Time se smanjuje lomljenje i poboljšava otpornost kose na spoljašnje stresore. Redovnom upotrebom doprinosi se boljoj elastičnosti i smanjenju krhkosti vlasi. Kosa postaje ujednačenija na dodir i manje sklona zapetljavanju. Ovaj tip reparacije je posebno koristan kod kose tretirane farbama, blanširanjem ili toplotnim alatima. Biljna ulja Biljna ulja u formuli imaju ulogu omekšavanja i smanjenja gubitka vlage iz vlasi. Formiraju tanak zaštitni sloj koji pomaže da se očuva fleksibilnost kose bez otežavanja. Doprinosе smanjenju hrapavosti i poboljšanju klizavosti tokom pranja. Na taj način se smanjuje mehaničko trenje koje dodatno oštećuje kosu. Dugoročno pomažu u održavanju mekše i sjajnije strukture vlasi. U formuli su prilagođena tako da ne opterećuju teme. Blago kiseli pH sistem Blago kiseli pH pomaže zatvaranju kutikule nakon čišćenja, što je važno za očuvanje glatke površine kose. Ovakav pH doprinosi i stabilnosti mikrobioma temena. Smanjuje se rizik od isušivanja i iritacija koje mogu nastati kod alkalnih formulacija. Uravnoteženo teme stvara povoljnije uslove za zdrav rast kose. Dugoročno se smanjuje osećaj zatezanja i perutanja. Ovaj pristup je posebno značajan kod osoba sa osetljivim temenom. Dodaj u listu želja Dodaj u listu želja', 'Unove Deep Damage Repair Shampoo je blagi šampon namenjen obnovi oštećene kose i jačanju strukture vlasi uz očuvanje ravnoteže temena. Deep Damage Repair Shampoo kombinuje 30 vrsta proteina i amino-kiselina sa biljnim uljima i blago kiselim pH kako bi kosa bila nahranjena, otpornija na lomljenje i temeljno očišćena bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Unove-Deep-Damage-Repair-Shampoo-1.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
