INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (138, 138, 'Pyunkang Yul Mist Toner', 'pyunkang-yul-mist-toner', 'Ključne prednosti: Brzo osveženje: nežna maglica momentalno hladi i hidrira kožu. Umirujuće dejstvo: coptis japonica smanjuje crvenilo i iritacije. Dubinska hidratacija: hijaluronska kiselina veže vlagu i obnavlja elastičnost kože. Kome je namenjen? Idealan je za dehidriranu, osetljivu i normalnu kožu, kao i za sve koji žele lagani, višestruko upotrebljiv toner za dnevno osveženje. Pogodan je i za masnu kožu jer ne ostavlja masan trag. Zašto volimo Pyunkang Yul Mist Toner ? Mist toner je savršen za trenutke kada koži nedostaje svežine, bilo da se koristi kao tonik u rutini ili za brzo osveženje u toku dana. Ekstrakt coptis japonica bogat antioksidansima smiruje kožu i štiti je od spoljašnjih stresora, dok hijaluronska kiselina hidrira u dubini, čineći kožu glatkom i mekom. Formula je minimalistička, bez alkohola, veštačkih mirisa i iritansa, pa je pogodna i za osetljivu i reaktivnu kožu. Maglica se raspršuje ravnomerno i nežno, a dopunsko pakovanje čini ovaj set izuzetno praktičnim i ekološki svesnim izborom. Aktivni sastojci Ekstrakt korena coptis japonica Poznat po umirujućem i antiinflamatornom dejstvu, pomaže u smanjenju crvenila i upalnih procesa. Takođe jača barijeru kože i daje joj zdrav, odmoran izgled. Hijaluronska kiselina Vezivanjem velike količine vode, hijaluronska kiselina vraća koži punoću i elastičnost. Ostavlja kožu hidriranom i mekanom tokom celog dana. Glicerin Prirodni humektans koji privlači i zadržava vlagu u površinskim slojevima kože, sprečavajući isušivanje. Butylene Glycol Poboljšava upijanje aktivnih sastojaka i dodatno doprinosi glatkoj i hidratizovanoj površini kože. 1,2‑Hexanediol Blagi hidratant i stabilizator formule koji kožu čini mekanom i prijatnom na dodir. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Cleansing Foam je hipoalergenska pena za čišćenje sa laganom, vodenom teksturom koja koži pruža trenutno osveženje, nalet hidratacije i prijatan osećaj hlađenja. Formula sadrži EWG-verifikovane sastojke poput ekstrakta zlatnice (goldthread), butilen glikola i glicerina, koji pomažu u očuvanju optimalne vlažnosti i balansa kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Pyunkang-Yul-Mist-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
