INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (139, 138, 'Pyunkang Yul Cleansing Foam', 'pyunkang-yul-cleansing-foam', 'Ključne prednosti Efikasno uklanjanje nečistoća: gusta pena se vezuje za sebum i površinske nečistoće i omogućava njihovo lakše uklanjanje sa kože. Očuvanje hidratacije: koža nakon ispiranja ostaje prijatna na dodir, bez izraženog osećaja zatezanja. Umirujuće delovanje: prisustvo ekstrakta Centella Asiatica doprinosi smanjenju reaktivnosti kože tokom čišćenja. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i mešovitu kožu koja zahteva blago, ali temeljno čišćenje. Pogodan je za osobe koje imaju sklonost ka iritacijama, crvenilu ili osećaju zatezanja nakon umivanja. Zašto volimo Pyunkang Yul Cleansing Foam? Pena ima stabilnu i elastičnu strukturu koja omogućava ravnomernu raspodelu bez agresivnog trljanja kože. Dobro uklanja svakodnevne nečistoće i višak sebuma bez narušavanja prirodne barijere. Lako se ispira i ne ostavlja težak ili lepljiv osećaj na koži. Pogodna je za redovnu, dugoročnu upotrebu u jutarnjoj i večernjoj rutini. Koža nakon čišćenja ostaje mekana i vizuelno ujednačenija. Tolerancija je dobra čak i kod osetljivijih tipova kože. Aktivni sastojci Centella Asiatica Extract Ekstrakt Centella Asiatica poznat je po svom umirujućem i zaštitnom dejstvu na kožu. Njegova osnovna funkcija je smanjenje osećaja nelagodnosti i podrška stabilnosti epidermisa tokom izlaganja mehaničkom i hemijskom stresu. Mehanizam delovanja se zasniva na podršci prirodnim procesima obnove kože i očuvanju integriteta površinskog sloja. Koža nakon primene deluje smirenije i manje sklona reaktivnim reakcijama. Dugoročno doprinosi boljoj toleranciji kože na spoljašnje faktore i učestalu higijensku negu. U okviru ove formule deluje kao balansirajući sastojak koji ublažava potencijalni efekat isušivanja tokom čišćenja. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Cleansing Foam koristi ekstrakt Centella Asiatica kao ključni umirujući sastojak koji doprinosi smanjenju iritacija i stabilizaciji kože tokom pranja. Formula je usmerena na efikasno uklanjanje nečistoća uz očuvanje hidratacije i glatkoće površine kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Pyunkang-Yul-Cleansing-Foam-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
