INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (140, 137, 'Purito Oat PDRN Gentle Refining Toner', 'purito-oat-pdrn-gentle-refining-toner', 'Ključne prednosti Stabilizacija kožne barijere: doprinosi jačanju zaštitne funkcije kože i smanjenju transepidermalnog gubitka vlage. Dubinska hidratacija: obezbeđuje kontinuirano vezivanje vode u površinskim slojevima kože i smanjuje osećaj zatezanja. Ujednačavanje teksture: blago poboljšava površinski reljef kože bez iritacije. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i aknama sklonu kožu koja pokazuje sklonost ka dehidrataciji i reaktivnosti. Pogodan je za tinejdžere i odrasle osobe koje žele stabilan, nenametljiv hidratantni korak u svakodnevnoj rutini. Zašto volimo Purito Oat PDRN Gentle Refining Toner? Formula je izuzetno blaga i pogodna za dugoročnu svakodnevnu upotrebu bez rizika od preopterećenja kože. Lagan vodeni karakter omogućava brzo upijanje i lako slojevito nanošenje u rutini. Dobro se uklapa sa različitim tipovima seruma i krema bez konflikta u teksturi. Tolerancija je visoka čak i kod reaktivne i osetljive kože. Redovnom upotrebom doprinosi stabilnijem osećaju hidriranosti i smirenosti kože. Pogodan je kao osnovni balansirajući korak u minimalističkim i složenijim rutinama. Aktivni sastojci Oat Seed Water Voda iz semenki ovsa predstavlja biljni izvor rastvorljivih polisaharida i umirujućih komponenti. Njena osnovna funkcija je podrška površinskoj hidrataciji i smanjenju osećaja nelagodnosti na koži. Mehanizam delovanja se zasniva na vezivanju vode u rožastom sloju i stvaranju blagog zaštitnog filma. Koža nakon nanošenja dobija mekši i stabilniji osećaj komfora. Dugoročno doprinosi očuvanju uravnoteženog stanja kože sklone isušivanju i reaktivnosti. U ovoj formuli prisutna je u visokom udelu od 80%, što značajno utiče na hidratantni karakter proizvoda. Beta-Glucan Beta-glukan je polisaharid poznat po svojoj sposobnosti zadržavanja vlage i umirivanja kože. Njegova funkcija je jačanje površinske otpornosti kože i podrška hidrataciji. Mehanizam delovanja uključuje vezivanje vode i stabilizaciju mikrookruženja epidermisa. Koža postaje otpornija na spoljašnje iritanse i manje sklona osećaju zatezanja. Dugoročno doprinosi očuvanju barijerne funkcije i boljem oporavku površinskog sloja. U okviru ove formule deluje sinergijski sa vodom iz ovsa kako bi se pojačao efekat hidratacije. Oat PDRN Oat PDRN predstavlja polinukleotid biljnog porekla dobijen iz ovsa. Njegova funkcija je podrška stabilnosti i obnovi površinskih struktura kože. Mehanizam delovanja je vezan za interakciju sa ćelijskim procesima uključenim u regeneraciju epidermisa. Koža može pokazivati ujednačeniji i otporniji izgled pri redovnoj primeni. Dugoročno doprinosi boljoj adaptaciji kože na svakodnevne spoljašnje stresore. U ovoj formuli koristi se u visokoj čistoći kako bi se očuvala dobra tolerancija i kompatibilnost sa osetljivom kožom. Dodaj u listu želja Dodaj u listu želja', 'Purito Oat PDRN Gentle Refining Toner je lagani tonik namenjen svakodnevnoj hidrataciji, smirivanju i stabilizaciji kožne barijere, sa visokim udelom vode iz semenki ovsa i čistim oat PDRN-om. Formula je bez mirisa, veganska i prilagođena koži koja lako reaguje na spoljašnje uticaje.', 'https://beauty-health.rs/wp-content/uploads/2026/01/51DSpFP3USL._AC_SL1080_700x.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
