INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (148, 114, 'Medicube PDRN Pink Tone Up Sun Cream', 'medicube-pdrn-pink-tone-up-sun-cream', 'Ključne prednosti Širokospektralna UV zaštita: štiti kožu od UVA i UVB zračenja i pomaže u smanjenju fotostarenja i oštećenja izazvanih suncem. Ujednačen vizuelni ton: blaga pigmentacija doprinosi ujednačenijem izgledu tena bez teškog osećaja na koži. Podrška kožnoj barijeri: negujući sastojci pomažu očuvanju hidratacije i komfora tokom dana. Kome je namenjena? Namenjena je normalnoj, mešovitoj, suvoj i osetljivoj koži kojoj je potrebna svakodnevna zaštita od sunca uz blago ujednačavanje tona. Pogodan je za osobe koje žele jednostavan proizvod koji objedinjuje fotoprotekciju i osnovnu negu, bez osećaja težine. Zašto volimo Medicube PDRN Pink Tone Up Sun Cream? Tekstura se lako razmazuje i ravnomerno raspoređuje na koži. Tonirani efekat pruža diskretno ujednačavanje bez izraženog maskiranja prirodnog tena. Dobro se uklapa u jutarnju rutinu i može se koristiti samostalno ili kao podloga za šminku. Tolerancija je dobra kod osetljive kože kada se koristi u preporučenoj količini. Osećaj na koži ostaje prijatan i bez prekomerne masnoće. Pogodna je za dugoročnu, svakodnevnu primenu tokom cele godine. Aktivni sastojci PDRN PDRN je polinukleotid dobijen iz DNK porekla koji se u kozmetici koristi za podršku stabilnosti i obnovi površinskih struktura kože. Deluje kroz stimulaciju ćelijskih procesa povezanih sa regeneracijom epidermisa. Doprinosi očuvanju otpornosti kože izložene spoljašnjim faktorima, uključujući UV stres. Može pomoći u održavanju ujednačenijeg i stabilnijeg izgleda kože tokom vremena. Dugoročnom primenom podržava adaptivni kapacitet kože i njen opšti komfor. U ovoj formuli je uklopljen tako da bude kompatibilan sa svakodnevnom upotrebom pod zaštitnim faktorom. Glutation Glutation je antioksidans koji učestvuje u neutralizaciji slobodnih radikala na površini kože. Pomaže u smanjenju oksidativnog stresa izazvanog spoljašnjim uticajima, uključujući sunčevo zračenje i zagađenje. Doprinosi ujednačenijem vizuelnom tonu i svežijem izgledu tena. Učestvuje u podršci prirodnim mehanizmima zaštite ćelija. Dugoročno može doprineti stabilnijem kvalitetu kože i boljoj toleranciji na spoljašnje stresore. U okviru ove formule koristi se kao dopuna fotoprotektivnom sistemu. Niacinamid Niacinamid je oblik vitamina B3 koji učestvuje u regulaciji funkcije kožne barijere. Podstiče sintezu lipida u epidermisu i pomaže očuvanju hidratacije. Doprinosi ujednačavanju tona i smanjenju vizuelne neujednačenosti. Može pomoći u balansiranju lučenja sebuma kod mešovite i masnije kože. Dugoročnom upotrebom doprinosi stabilnijem i otpornijem stanju kože. U ovoj formuli je prilagođen svakodnevnoj upotrebi bez povećanog rizika od iritacije. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Tone Up Sun Cream je zaštitna krema sa tonirajućim efektom namenjena svakodnevnoj fotoprotekciji kože. Formulisana je sa SPF 50+ PA++++ zaštitom od UVA i UVB zračenja, uz dodatak PDRN-a, glutationa i niacinamida, kao i blago pigmentisanu, breskvastu nijansu koja vizuelno ujednačava ten.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Medicube-PDRN-Pink-Tone-Up-Sun-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
