INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (153, 111, 'Mary&May Spicule Retinol PDRN Cream', 'marymay-spicule-retinol-pdrn-cream', 'Ključne prednosti Poboljšanje teksture kože: spikule podstiču intenzivniji kontakt aktivnih sastojaka sa površinom kože i doprinose ujednačenijem reljefu. Podrška obnovi i elastičnosti: retinol u liposomskoj formi i PDRN doprinose stabilnijem izgledu kože i njenoj funkcionalnoj obnovi. Očuvanje barijere i tolerancije: pantenol, ceramidi i umirujući sastojci smanjuju rizik od iritacije tokom kontinuirane upotrebe. Kome je namenjena? Namenjena je normalnoj, mešovitoj i zrelijoj koži sa izraženim nepravilnostima teksture, proširenim porama i finim borama. Može se koristiti i kod osetljivije kože uz postepeno uvođenje i pažljivo praćenje reakcije. Zašto volimo Mary&May Spicule Retinol PDRN Cream? Ova krema kombinuje napredne tehnologije isporuke aktivnih sastojaka sa formulom koja ostaje kontrolisana i stabilna za dugoročnu upotrebu. Mikro-spikule omogućavaju drugačiji pristup obnovi površine kože bez mehaničkog pilinga. Retinol je inkapsuliran tako da se bolje podnosi i ravnomernije oslobađa. Umirujući i barijerni sastojci održavaju osećaj komfora tokom perioda adaptacije kože. Tekstura se ravnomerno raspoređuje i ne ostavlja težak sloj. Kontinuiranom primenom koža deluje ujednačenije i otpornije. Aktivni sastojci Spikule morskog porekla (2.000 ppm) Spikule su prirodne mikroskopske strukture morskog porekla čija je veličina manja od prečnika pora. Deluju tako što stvaraju mikro-kanale na površini kože i omogućavaju efikasniji kontakt aktivnih sastojaka sa epidermisom. Njihov mehanizam delovanja je fizički i ne uključuje hemijsku eksfolijaciju. Doprinosе ujednačenijoj teksturi i boljoj raspodeli formulacije. Dugoročnom upotrebom mogu doprineti stabilnijem izgledu pora i reljefa kože. U okviru formule imaju ključnu ulogu u optimizaciji apsorpcije. Nano Liposome Retinol (1.000 ppm) Nano-liposomski retinol je inkapsulirana forma vitamina A prilagođena boljoj stabilnosti i podnošljivosti. Deluje na regulaciju obnavljanja ćelija u površinskim slojevima kože. Njegov mehanizam omogućava postepeno oslobađanje aktivne supstance. Doprinosi ujednačenijoj teksturi i poboljšanju izgleda finih linija. Dugoročnom upotrebom podržava strukturalnu stabilnost kože. U formuli ima centralnu ulogu u regenerativnom efektu. CICA PDRN CICA PDRN je biološki aktivan sastojak povezan sa podrškom regenerativnim procesima kože. Deluje na poboljšanje funkcionalne obnove epidermisa nakon iritacije ili stresa. Njegov mehanizam uključuje podršku ćelijskoj aktivnosti i stabilizaciju barijere. Doprinosi smanjenju subjektivnog osećaja nelagodnosti. Dugoročnom primenom pomaže očuvanju ujednačenijeg i otpornijeg izgleda kože. U formuli ima balansirajuću i reparativnu ulogu. Pantenol (2%) Pantenol je provitamin B5 sa izraženim ovlaživačkim i umirujućim svojstvima. Deluje na povećanje sposobnosti kože da zadrži vodu. Njegov mehanizam doprinosi jačanju barijerne funkcije. Pomaže u smanjenju crvenila i osećaja zatezanja. Dugoročnom upotrebom podržava stabilan nivo hidratacije i komfora. U ovoj formuli ima ključnu ulogu u toleranciji aktivnih sastojaka. Ceramidi NP Ceramidi su prirodni lipidi koji čine osnovu zaštitne barijere kože. Deluju na popunjavanje međučelijskih lipidnih struktura u rožastom sloju. Njihov mehanizam doprinosi smanjenju transepidermalnog gubitka vode. Pomažu u očuvanju elastičnosti i otpornosti kože. Dugoročno podržavaju stabilniju funkciju barijere. U formuli imaju zaštitnu i stabilizujuću ulogu. HijaluronskaAcid Hijaluronska kiselina je humektans koji vezuje vodu u površinskim slojevima kože. Deluje na povećanje hidratacije i elastičnosti kože. Njeno prisustvo doprinosi smanjenju osećaja suvoće tokom tretmana sa aktivnim sastojcima. Mehanizam delovanja zasniva se na sposobnosti vezivanja molekula vode. Dugoročnom upotrebom podržava stabilan nivo vlažnosti kože. U okviru formule ima ulogu hidratantne podrške. Alantoin Alantoin je umirujući sastojak koji', 'Mary&May Spicule Retinol PDRN Cream sadrži prirodne spikule u koncentraciji od 2.000 ppm, liposomski retinol od 1.000 ppm, CICA PDRN i 2% pantenola, uz ceramid NP, hijaluronsku kiselinu i alantoin. Formula je usmerena na postepenu obnovu površinske strukture kože, podršku barijeri i smanjenje nepravilnosti bez agresivnog pristupa.', 'https://beauty-health.rs/wp-content/uploads/2026/01/MaryMay-Spicule-Retinol-PDRN-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
