INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (154, 111, 'Mary & May Blooming Glow Lip', 'mary-may-blooming-glow-lip', 'Ključne prednosti Intenzivna hidratacija: hijaluronski kompleks pomaže održavanju optimalnog nivoa vlage i smanjuje osećaj suvoće. Podrška elastičnosti: Vegan Pink Collagen i peptidi doprinose očuvanju čvrstoće i otpornosti kože usana. Zaštita i komfor: ceramidi i biljna ulja jačaju zaštitnu barijeru i smanjuju iritaciju. Kome je namenjen? Namenjen je svim tipovima kože usana, uključujući suve, osetljive i sklone ispucalosti. Pogodan je za svakodnevnu upotrebu kod osoba koje žele negu, blagi sjaj i prirodan izgled bez osećaja težine. Zašto volimo Mary & May Blooming Glow Lip? Ovaj proizvod ostavlja utisak urednih, negovanih usana već nakon prvog nanošenja. Tekstura se topi pod prstima i ravnomerno prijanja uz površinu usana, bez osećaja težine ili lepljivog filma. Hidratacija je postojana, što se posebno primećuje kod usana sklonih isušivanju tokom dana. Vizuelni efekat je suptilan, ali daje licu svežinu i prirodan sjaj bez prenaglašenosti. Formulacija je stabilna i prijatna za čestu upotrebu, čak i kod osetljive kože. Dugoročno, usne deluju ujednačenije, mekše i otpornije na spoljašnje uticaje. Aktivni sastojci Vegan Pink Collagen (Pink vitamini i biljni ekstrakt Tremella Fuciformis) Vegan Pink Collagen predstavlja biljni kolagenski kompleks namenjen poboljšanju elastičnosti kože usana. Deluje kroz zadržavanje vlage i podršku površinskoj strukturi kože. Njegov mehanizam delovanja zasniva se na poboljšanju hidriranosti i fleksibilnosti tkiva. Doprinosi ujednačenijem izgledu i prijatnijem osećaju na usnama. Dugoročnom upotrebom pomaže očuvanju čvrstoće i otpornosti kože usana. U okviru formule ima ključnu ulogu u održavanju elastičnosti. 8-Flower Complex (biljni cvetni ekstrakti) Cvetni kompleks predstavlja kombinaciju osam biljnih ekstrakata sa ciljanim negujućim delovanjem. Deluje na poboljšanje opšteg komfora i vitalnosti kože usana. Pomaže u smanjenju osećaja suvoće i nelagodnosti. Njegovo dejstvo je blago i prilagođeno osetljivoj koži. Dugoročnom upotrebom doprinosi ujednačenijoj teksturi i prirodnijem izgledu usana. U formuli ima potporuću ulogu u balansiranju i revitalizaciji. Hyaluronic Acid Complex Kompleks hijaluronske kiseline sadrži molekule različite molekulske mase radi višeslojne hidratacije. Deluje kao humektans koji vezuje vodu u površinskim slojevima kože usana. Pomaže u smanjenju osećaja zatezanja i hrapavosti. Njegov mehanizam delovanja omogućava održavanje elastičnosti i punoće. Dugoročnom upotrebom doprinosi stabilnijem nivou hidratacije. U ovoj formuli ima centralnu ulogu u očuvanju vlažnosti. Ceramidi Ceramidi su lipidi prirodno prisutni u zaštitnoj barijeri kože. Deluju na očuvanje integriteta površinskog sloja i smanjenje gubitka vlage. Njihovo prisustvo doprinosi otpornosti kože usana na spoljašnje faktore. Pomažu u održavanju mekoće i glatkoće površine. Dugoročnom upotrebom podržavaju stabilniji zaštitni sloj. U formuli imaju funkciju jačanja barijere. Peptidi Peptidi su kratki lanci aminokiselina koji deluju kao signalne molekule u koži. U ovoj formulaciji usmereni su na podršku strukturalnoj stabilnosti kože usana. Deluju postepeno kroz redovnu upotrebu proizvoda. Doprinosе očuvanju elastičnosti i otpornosti. Njihov efekat je blag i prilagođen osetljivoj regiji usana. U okviru formule imaju potporuću regenerativnu ulogu. Camellia Oil Ulje kamelije je bogato masnim kiselinama, vitaminom E i polifenolima. Deluje kao emolijens koji omekšava i štiti površinu usana. Pomaže u smanjenju transepidermalnog gubitka vode. Njegov mehanizam delovanja doprinosi očuvanju fleksibilnosti kože. Dugoročnom upotrebom podržava stabilan nivo komfora. U formuli ima zaštitnu i hranljivu ulogu. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Blooming Glow Lip je veganski balzam–ruž za usne sa visokim sjajem, formulisan za intenzivnu hidrataciju, očuvanje elastičnosti i zaštitu osetljive kože usana, uz transparentan i prirodan efekat boje.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Mary-May-Blooming-Glow-Lip-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
