INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (155, 109, 'Manyo Pure & Deep Cleansing Foam', 'manyo-pure-deep-cleansing-foam', 'Ključne prednosti Dubinsko čišćenje: fina pena uklanja nečistoće, višak sebuma i ostatke šminke bez agresivnog isušivanja. Očuvanje hidratacije: ceramidi i hijaluronska kiselina doprinose zadržavanju vlage tokom i nakon čišćenja. Balans i komfor kože: cvetni ekstrakti pomažu održavanju prijatnog osećaja i ujednačene teksture kože. Kome je namenjena? Namenjena je svim tipovima kože, uključujući normalnu, mešovitu i masniju kožu kojoj je potrebno temeljno, ali kontrolisano čišćenje. Pogodan je i za kožu sklonu osećaju zatezanja nakon umivanja, kao i za svakodnevnu upotrebu bez starosnih ograničenja. Zašto volimo Manyo Pure & Deep Cleansing Foam? Pena se lako razrađuje u fine, guste mehuriće koji omogućavaju ravnomerno čišćenje kože. Tokom upotrebe ne ostavlja izražen osećaj suvoće ili nelagodnosti. Formula je dovoljno blaga za svakodnevnu primenu, ali dovoljno efikasna za uklanjanje nakupljenih nečistoća. Dobro se uklapa u rutine koje uključuju aktivne sastojke jer ne narušava hidrolipidni balans kože. Nakon ispiranja koža ostaje čista, mekša i prijatna na dodir. Dugoročnom upotrebom doprinosi stabilnijem osećaju komfora tokom čišćenja. Aktivni sastojci Cvetni ekstrakti (Ylang Ylang Extract, Rose Extract i ostali cvetni ekstrakti) Cvetni ekstrakti predstavljaju biljni kompleks koji doprinosi revitalizaciji kože tokom čišćenja. Njihovo delovanje je usmereno na očuvanje prijatnog osećaja na koži uprkos uklanjanju nečistoća i sebuma. Pomažu u održavanju ravnoteže kože i sprečavanju preteranog isušivanja. Deluju blago i pogodni su za čestu upotrebu. Dugoročno doprinose ujednačenijoj teksturi i boljem subjektivnom osećaju kože. U formuli imaju ulogu balansirajućih i potpornih sastojaka. Ceramidi Ceramidi su lipidi prirodno prisutni u kožnoj barijeri. Njihova uloga je očuvanje integriteta epidermisa i smanjenje gubitka vlage tokom čišćenja. Deluju tako što popunjavaju lipidne prostore između ćelija rožastog sloja. Doprinosi smanjenju osećaja zatezanja nakon umivanja. Dugoročnom upotrebom podržavaju stabilniju i otporniju kožnu barijeru. U ovoj formuli imaju ključnu ulogu u očuvanju zaštitne funkcije kože. Hijaluronska kiselina Hijaluronska kiselina deluje kao humektans koji vezuje vodu u površinskim slojevima kože. Tokom čišćenja pomaže održavanju hidratacije i sprečava isušivanje. Njeno delovanje doprinosi elastičnosti i prijatnom osećaju na koži nakon ispiranja. Mehanizam delovanja zasniva se na privlačenju i zadržavanju molekula vode. Dugoročnom upotrebom doprinosi stabilnijem nivou vlažnosti kože. U okviru formule ima ulogu hidratantne podrške. Dodaj u listu želja Dodaj u listu želja', 'Manyo Pure & Deep Cleansing Foam je pena za čišćenje lica formulisana za temeljno uklanjanje nečistoća, viška sebuma i ostataka šminke, uz očuvanje hidratacije i komfora kože. Sadrži kompleks od deset prirodnih cvetnih ekstrakata, uključujući ylang-ylang i ružu, kao i ceramide i hijaluronsku kiselinu. Pena je usmerena na efikasno čišćenje pora, očuvanje vlažnosti i sprečavanje osećaja zatezanja nakon umivanja.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Manyo-Pure-Deep-Cleansing-Foam-.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
