INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (157, 85, 'iUNIK Centella Relief Sorbet Cream', 'iunik-centella-relief-sorbet-cream', 'Ključne prednosti Umirivanje i hlađenje kože: ekstrakt centelle i rashlađujući efekat doprinose smanjenju osećaja iritacije i pregrejanosti kože. Održavanje hidratacije: kombinacija ovlaživača pomaže stabilno zadržavanje vlage u površinskim slojevima kože. Podrška kožnoj barijeri: zaštitni film na površini kože smanjuje transepidermalni gubitak vode i doprinosi očuvanju balansa. Kome je namenjen? Namenjena je normalnoj, suvoj, dehidriranoj i osetljivoj koži, kao i koži sklonoj crvenilu i osećaju nelagodnosti. Posebno je pogodna za mlađu i srednju starosnu grupu, kao i za kožu koja slabije podnosi teške i okluzivne teksture. Zašto volimo iUNIK Centella Relief Sorbet Cream? Krema se lako razmazuje i brzo se prilagođava koži bez ostavljanja masnog ili lepljivog osećaja. Tekstura u obliku sorbeta omogućava prijatan osećaj hlađenja prilikom nanošenja, što je korisno kod osetljive i reaktivne kože. Formulacija je jednostavna, bez dodanih mirisa i potencijalno iritantnih supstanci. Može se koristiti kontinuirano, bez opterećenja kože i bez narušavanja njenog prirodnog balansa. Dobro se uklapa u rutine sa aktivnim sastojcima koji mogu isušivati ili iritirati kožu. Dugoročno doprinosi stabilnijem osećaju komfora i ujednačenijem izgledu kože. Aktivni sastojci Centella Asiatica Deluje umirujuće na kožu i doprinosi smanjenju osećaja iritacije i nelagodnosti. Njeni bioaktivni sastojci podržavaju prirodne reparativne procese u površinskim slojevima kože. Pomaže stabilizaciji kožne barijere i smanjenju reaktivnosti kože. Deluje povoljno na održavanje hidratacije kroz očuvanje integriteta epidermisa. Dugoročnom upotrebom doprinosi mirnijem i ujednačenijem izgledu kože. U okviru formule ima centralnu ulogu kao balansirajući i umirujući sastojak. Niacinamid Niacinamid je oblik vitamina B3 koji učestvuje u regulaciji funkcije kožne barijere. Deluje na poboljšanje sposobnosti kože da zadrži vlagu i smanji transepidermalni gubitak vode. Doprinosi ujednačenijem tonu i stabilnijoj teksturi kože. Njegov mehanizam delovanja uključuje podršku sintezi ceramida u epidermisu. Dugoročno može doprineti otpornijoj i uravnoteženijoj koži. U ovoj formuli ima ulogu multifunkcionalnog stabilizujućeg sastojka. Glyceryl Glucoside Glyceryl Glucoside deluje kao ovlaživač koji privlači i zadržava vodu u površinskim slojevima kože. Podržava prirodne mehanizme hidratacije kože. Pomaže u smanjenju osećaja zatezanja i suvoće. Njegovo delovanje je blago i pogodno za osetljivu kožu. Dugoročnom upotrebom doprinosi stabilnijem nivou hidratacije. U formuli ima ulogu podrške hidratantnoj ravnoteži. Hidrolizovana hijaluronska kiselina Hidrolizovana hijaluronska kiselina ima manju molekulsku masu koja omogućava ravnomernu raspodelu vlage na površini kože. Deluje kao snažan humektans koji vezuje vodu. Doprinosi elastičnosti i smanjenju osećaja suvoće. Njeno delovanje je usmereno na kratkoročnu i srednjoročnu hidrataciju. Redovnom upotrebom koža zadržava puniji i ujednačeniji izgled. U formuli ima ulogu ključnog hidratantnog sastojka. Betain Betain je prirodni osmolit koji pomaže ćelijama da održe ravnotežu vode. Deluje zaštitno na kožu izloženu spoljašnjim stresorima i isušivanju. Pomaže u smanjenju iritacije i osećaja nelagodnosti. Njegov mehanizam delovanja doprinosi stabilnosti ćelijskih membrana. Dugoročno podržava otpornost kože i njen komfor. U ovoj formuli ima ulogu balansirajućeg i zaštitnog ovlaživača. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Centella Relief Sorbet Cream je umirujuća hidratantna krema sa osvežavajućim efektom, namenjena koži kojoj je potreban balans između smirivanja, hidratacije i očuvanja barijere. Sadrži ekstrakt Centella Asiatica, niacinamid i kompleks ovlaživača koji doprinose stabilizaciji kože i održavanju vlažnosti. Tekstura je lagana, topi se na koži i prilagođena je svakodnevnoj upotrebi kod osetljive i reaktivne kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/iUNIK-Centella-Relief-Sorbet-Cream-.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
