INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (158, 85, 'iUNIK Beta-Glucan Lacto Barrier Milk Essence', 'iunik-beta-glucan-lacto-barrier-milk-essence', 'Ključne prednosti Jačanje kožne barijere: fermenti i peptidi doprinose stabilnijoj barijernoj funkciji kože. Dugotrajna hidratacija: beta-glukan i pantenol pomažu zadržavanje vlage u površinskim slojevima kože. Poboljšanje elastičnosti: peptidni kompleks i EGF podržavaju očuvanje čvrstoće i otpornosti kože. Kome je namenjena? Namenjena je svim tipovima kože, posebno suvoj, dehidriranoj i koži sa oslabljenom barijerom. Pogodna je i za osetljivu kožu koja ne podnosi teške teksture ili višeslojne rutine. Zašto volimo iUNIK Beta-Glucan Lacto Barrier Milk Essence? Ova esencija omogućava pojednostavljenu rutinu bez gubitka funkcionalnosti u nezi kože. Mlečna tekstura se ravnomerno razmazuje i brzo upija, bez osećaja težine ili masnog filma. Formulacija je stabilna i dobro podnošljiva, što je čini pogodnom za svakodnevnu i dugoročnu upotrebu. Lako se kombinuje sa drugim aktivnim sastojcima u rutini bez rizika od konflikta. Posebno prija koži sklonoj dehidrataciji i narušenoj barijeri, jer doprinosi osećaju komfora tokom dana. Kontinuiranom upotrebom koža zadržava ujednačeniji i otporniji izgled. Aktivni sastojci Beta-Glukan Beta-glukan je polisaharid poznat po svojoj sposobnosti vezivanja vode u koži. Deluje kao snažan ovlaživač koji pomaže održavanje hidratacije tokom dužeg vremenskog perioda. Njegov mehanizam delovanja zasniva se na jačanju površinskog sloja kože. Doprinosi smanjenju osećaja zatezanja i nelagodnosti. Dugoročnom upotrebom podržava otporniju i stabilniju kožnu barijeru. U ovoj formuli ima centralnu ulogu u očuvanju vlažnosti kože. Lactobacillus Ferment Lysate (68%) Ovaj ferment deluje kao sastojak za podršku mikrobiološkoj ravnoteži kože. Pomaže očuvanje prirodne barijerne funkcije i smanjenje osetljivosti. Njegovo delovanje je usmereno na jačanje otpornosti kože na spoljašnje faktore. Doprinosi boljoj toleranciji proizvoda kod reaktivne kože. Dugoročno pomaže stabilnijem izgledu i teksturi kože. U formuli ima ključnu ulogu kao barijerni i balansirajući sastojak. Peptidi (7 vrsta) Peptidi su kratki lanci aminokiselina koji deluju kao signalne molekule u koži. U ovoj formulaciji usmereni su na podršku elastičnosti i čvrstoće kože. Njihovo delovanje je postepeno i vezano za redovnu upotrebu. Pomažu očuvanje strukturalne stabilnosti kože. Dugoročno doprinose otpornijem i ujednačenijem izgledu. U formuli imaju potporuću ulogu u održavanju kvaliteta kože. EGF EGF je signalni protein koji se koristi u kozmetici za podršku prirodnim procesima obnavljanja kože. Deluje na poboljšanje opšteg kvaliteta kože bez agresivnog efekta. Njegovo prisustvo doprinosi ujednačenijem izgledu kože. Mehanizam delovanja je vezan za podršku ćelijskoj komunikaciji. Dugoročnom upotrebom može doprineti stabilnijoj teksturi kože. U ovoj formuli ima dopunsku regenerativnu ulogu. Bakučiol Bakuchiol je biljni sastojak koji se koristi kao alternativa retinoidima u blagim formulacijama. Deluje na poboljšanje teksture kože i njene elastičnosti. Njegovo delovanje je prilagođeno osetljivoj koži. Ne izaziva tipične neželjene efekte povezane sa jačim aktivima. Dugoročno doprinosi ujednačenijem izgledu kože. U formuli ima potporuću ulogu u očuvanju čvrstoće kože. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Beta-Glucan Lacto Barrier Milk Essence je mlečna esencija namenjena hidrataciji i podršci kožnoj barijeri, formulisana kao kombinacija tonera i esencije za svakodnevnu upotrebu. Sadrži beta-glukan, 68% Lactobacillus Ferment Lysate i kompleks peptida sa ciljem očuvanja hidratacije i stabilnosti kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/iUNIK-Beta-Glucan-Lacto-Barrier-Milk-Essence-3-scaled.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
