INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (159, 75, 'Hyaah Chamomile 80.9 All Day Essential Water', 'hyaah-chamomile-80-9-all-day-essential-water', 'Ključne prednosti Umirujuće delovanje: visok sadržaj kamilice doprinosi smanjenju osećaja nelagodnosti i iritacije na koži. Svakodnevna hidratacija: vodena tekstura omogućava održavanje vlažnosti kože tokom dana bez teškog osećaja. Dobra podnošljivost: formula je prilagođena čestoj upotrebi i pogodna za osetljivu kožu. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i reaktivnu kožu. Posebno odgovara osobama koje traže laganu hidrataciju i umirujući efekat u svakodnevnoj rutini, bez obzira na starosnu dob. Zašto volimo Hyaah Chamomile 80.9 All Day Essential Water? Zato što se lako uklapa u jutarnju i večernju rutinu bez rizika od preopterećenja kože. Tekstura je lagana i brzo se upija, što omogućava slojevitu negu. Proizvod se može koristiti kontinuirano tokom dužeg vremenskog perioda. Ne narušava prirodni balans kože i ne ostavlja lepljiv trag. Pogodan je kao osnovni hidratantni korak kod osetljive kože. Doprinosi stabilnijem i smirenijem izgledu kože kroz redovnu upotrebu. Aktivni sastojci Chamomile Water (80.9%) Predstavlja osnovu formule i glavni funkcionalni sastojak proizvoda. Deluje umirujuće na kožu i pomaže u smanjenju osećaja iritacije i nelagodnosti. Njegovo delovanje je usmereno na očuvanje prirodnog balansa kože tokom dana. Visok udeo u formulaciji omogućava dobru toleranciju kod osetljive kože. Dugoročnom upotrebom doprinosi stabilnijem i ujednačenijem izgledu kože. U okviru formule ima centralnu ulogu kao hidratantna i umirujuća baza. Dodaj u listu želja Dodaj u listu želja', 'Hyaah Chamomile 80.9 All Day Essential Water je lagani mist formulisan sa visokim udelom kamilice, namenjen svakodnevnoj nezi kože i održavanju njenog balansa tokom dana. Sadrži 80,9% vode kamileice kao ključnu bazu formule, sa fokusom na umirivanje i hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Hyaah-Chamomile-80.9-All-Day-Essential-Water-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
