INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (163, 69, 'Haruharu Wonder Black Rice Probiotics Barrier 2% NAD+ Serum Mist', 'haruharu-wonder-black-rice-probiotics-barrier-2-nad', 'Ključne prednosti Podrška kožnoj barijeri: pomaže u očuvanju lipidne strukture kože i smanjenju gubitka vlage. Održavanje hidratacije: doprinosi kontinuiranoj hidrataciji kože tokom dana bez lepljivog osećaja. Ujednačeniji izgled kože: pomaže koži da zadrži svež i stabilan izgled usled delovanja fermentisanih sastojaka. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, posebno koži sa narušenom barijerom i sklonom dehidrataciji. Pogodan je za osobe koje žele dodatnu negu tokom dana ili lagani hidratantni korak u rutini. Zašto volimo Haruharu Wonder Black Rice Probiotics Barrier 2% NAD+ Serum Mist? Ovaj proizvod ima jasnu ulogu kao prelaz između seruma i mista, bez kompromisa u funkcionalnosti. Format omogućava jednostavnu primenu bez dodirivanja kože, što je praktično tokom dana ili preko šminke. Sastav je usmeren na stabilnost i toleranciju, a ne na kratkotrajne efekte. Kombinacija ceramida i fermentisanih sastojaka daje smisao dugoročnoj upotrebi. Tekstura ostaje lagana i ujednačena bez zagušenja kože. Proizvod se lako uklapa u različite rutine nege. Aktivni sastojci NAD+ (Nicotinamide Adenine Dinucleotide) NAD+ je koenzim prisutan u ćelijama kože i učestvuje u metaboličkim procesima. Njegova funkcija u formuli je podrška ćelijskoj energiji i opštoj stabilnosti kože. Deluje tako što učestvuje u procesima obnove ćelija. Doprinosi očuvanju vitalnosti kože izložene spoljašnjim stresorima. Dugoročno pomaže u održavanju ujednačenijeg i otpornijeg izgleda kože. U ovoj formuli je prisutan u koncentraciji od 2%. 5 Ceramida Compleks(NP, NS, AP, EOS, EOP) Ceramidi su ključni lipidi kožne barijere. Njihova uloga je obnova i očuvanje strukture zaštitnog sloja kože. Deluju tako što smanjuju transepidermalni gubitak vode. Pomažu koži da zadrži vlagu i otpornost. Dugoročnom upotrebom doprinose stabilnijoj barijeri. Kompleks od pet ceramida obuhvata različite tipove prirodno prisutne u koži. Upcycled Black Rice Jigemi (Lees) Extract Ekstrakt crnog pirinča dobijen iz procesa fermentacije bogat je antioksidativnim jedinjenjima. Njegova funkcija je zaštita kože od oksidativnog stresa. Deluje umirujuće na kožu izloženu spoljašnjim faktorima. Doprinosi ujednačenijem tonu i teksturi kože. Dugoročno pomaže očuvanju zdravog izgleda kože. U formuli ima i ekološki aspekt zbog upotrebe nusproizvoda fermentacije. Galactomyces Ferment Filtrat Galactomyces ferment filtrat je probiotski sastojak dobijen fermentacijom kvasca. Pomaže u očuvanju hidratacije kože. Deluje tako što podržava ravnotežu kože i njenu teksturu. Doprinosi elastičnijem izgledu kože. Dugoročno može pomoći u stabilnijem i ujednačenijem izgledu tena. U ovoj formuli je uključen radi blage, ali kontinuirane nege. Bifida Ferment Filtrat Bifida ferment filtrat je probiotski sastojak poznat po delovanju na otpornost kože. Pomaže u smanjenju osetljivosti kože. Deluje tako što podržava regenerativne procese kože. Doprinosi boljoj toleranciji kože na spoljašnje stresore. Dugoročno pomaže u očuvanju ujednačene teksture kože. U formuli ima ulogu stabilizacije kožne barijere. Pantenol Pantenol je provitamin B5 sa hidratantnim i umirujućim svojstvima. Pomaže u zadržavanju vlage u koži. Deluje na smanjenje osećaja suvoće i nelagodnosti. Podržava obnovu kožne barijere. Dugoročno doprinosi elastičnijoj i otpornijoj koži. U ovoj formuli doprinosi boljoj podnošljivosti aktivnih sastojaka. Skvalan Skvalan je stabilan lipid sličan prirodnom sebumu kože. Njegova funkcija je omekšavanje i smanjenje gubitka vlage. Deluje bez zagušenja pora. Doprinosi glatkom i uravnoteženom osećaju na koži. Dugoročno pomaže očuvanju lipidne ravnoteže. U ovoj formuli je sertifikovan prema ECOCERT standardu. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Probiotics Barrier 2% NAD+ Serum Mist je dvoslojni serum-mist namenjen jačanju kožne barijere i očuvanju hidratacije, sa formulom koja kombinuje fermentisane sastojke, ceramide i NAD+ u praktičnom formatu za upotrebu tokom dana. Proizvod je razvijen kao lagana, kremasta maglica koja se ravnomerno nanosi na kožu bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Haruharu-Wonder-Black-Rice-Probiotics-Barrier-2-NAD-Serum-Mist-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
