INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (164, 65, 'Fwee Pocket Eye Palette', 'fwee-pocket-eye-palette', 'Ključne prednosti Kompaktna funkcionalnost: omogućava kreiranje više dnevnih make-up varijanti iz jedne male palete. Kontrolisana nadogradnja boje: senke se mogu postepeno nadograđivati bez stvaranja neujednačenog sloja. Široka tonalna prilagodljivost: obuhvata nijanse pogodne za različite podtonove kože. Kome je namenjen? Namenjena je svim tipovima kože i korisnicima koji traže praktičnu paletu za svakodnevnu šminku. Pogodna je za početnike i iskusne korisnike koji žele jednostavno, ali fleksibilno rešenje za šminkanje očiju. Zašto volimo Fwee Pocket Eye Palette? Ova paleta ima jasno definisanu svrhu – da pruži funkcionalan izbor nijansi u formatu koji je lako nositi sa sobom. Izbor boja omogućava kombinovanje osnovnih i naglašenih tonova bez potrebe za dodatnim proizvodima. Tekstura senki je prilagođena brzom nanošenju i korekciji tokom dana. Pakovanje je praktično i osmišljeno za svakodnevnu upotrebu van kuće. Paleta ne zahteva posebne alate i lako se uklapa u različite stilove šminke. Namenjena je realnoj upotrebi, a ne dekorativnom višku. Aktivni sastojci Pigmenti u prahu Pigmenti u prahu predstavljaju osnovu boje u senkama za oči. Njihova funkcija je da obezbede vidljivost i postojanost nijanse na koži kapaka. Deluju tako što se ravnomerno vezuju za površinu kože. Omogućavaju kontrolisanu intenzivnost boje u zavisnosti od načina nanošenja. Dugoročno ne utiču na strukturu kože već služe isključivo dekorativnoj nameni. U okviru ove palete prilagođeni su svakodnevnoj upotrebi bez izraženog taloženja. Svetlucave čestice Svetlucave čestice doprinose refleksiji svetlosti i vizuelnoj dimenziji šminke. Njihova uloga je da naglase pojedine delove kapka. Deluju površinski i ne prodiru u kožu. Omogućavaju kreiranje naglašenijih ili akcentnih izgleda. Dugoročno nemaju biološki efekat na kožu. U ovoj paleti koriste se u kombinaciji sa mat nijansama radi balansa. Vezivna baza senki Vezivna baza omogućava da se pigmenti ravnomerno rasporede i zadrže na koži. Njena funkcija je da poboljša prijanjanje proizvoda. Deluje tako što smanjuje rasipanje i mrvljenje senki. Doprinosi ujednačenijem izgledu tokom nošenja. Dugoročno nema aktivno dejstvo na kožu. U okviru formule prilagođena je osetljivoj regiji oko očiju. Dodaj u listu želja Dodaj u listu želja', 'Fwee Pocket Eye Palette je kompaktna paleta senki za oči namenjena svakodnevnoj šminki, dizajnirana za lako nošenje i brzu upotrebu u pokretu. Paleta sadrži pet pažljivo odabranih nijansi koje omogućavaju kreiranje jednostavnih i prilagodljivih make-up izgleda u toplim i hladnim tonovima.', 'https://beauty-health.rs/wp-content/uploads/2026/01/0_19e27a92-70a4-4409-a1ca-44c8d0f4a746.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
