INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (165, 62, 'Frudia Pomegranate Honey 3 In 1 Lip Balm', 'frudia-pomegranate-honey-3-in-1-lip-balm', 'Ključne prednosti Očuvanje hidratacije: pomaže u zadržavanju vlage i smanjenju isušivanja usana tokom dana. Zaštita kožne barijere: doprinosi jačanju površinskog zaštitnog sloja kože usana. Poboljšanje teksture: redovnom upotrebom usne deluju zaglađenije i ujednačenije. Kome je namenjen? Namenjen je svim tipovima kože usana, posebno suvim, dehidriranim i sklonim perutanju. Pogodan je za svakodnevnu upotrebu kod osoba koje žele osnovnu, ali kontinuiranu negu usana. Zašto volimo Frudia Pomegranate Honey 3 In 1 Lip Balm? Ovaj balzam ima jasno definisanu ulogu u rutini nege usana, bez preteranih zahteva ili dodatnih koraka. Tekstura je prilagođena čestoj upotrebi i ne ometa nošenje drugih proizvoda za usne. Proizvod se može koristiti tokom dana i po potrebi više puta, bez osećaja zagušenja. Fokusiran je na održavanje komfora i stabilnosti kože usana. Sastav je jednostavan i usmeren na dugoročnu upotrebu. Lako se uklapa u svakodnevnu rutinu nege. Aktivni sastojci Ekstrakt nara (Punica Granatum Extract) Ekstrakt nara je biljni sastojak bogat antioksidativnim jedinjenjima. Njegova uloga u balzamu je podrška očuvanju zdravog izgleda kože usana. Deluje tako što pomaže u zaštiti kože od oksidativnog stresa. Doprinosi ujednačenijem izgledu površine usana. Dugoročno pomaže u održavanju stabilnosti i otpornosti kože usana. U ovoj formuli ima ulogu dopunske nege i zaštite. Med (Honey Extract) Med deluje kao humektans koji privlači i zadržava vlagu u površinskim slojevima kože. Pomaže u smanjenju gubitka vlage sa kože usana. Doprinosi osećaju mekoće i komfora nakon nanošenja. Podržava prirodnu zaštitnu funkciju kože usana. Dugoročnom upotrebom pomaže u smanjenju perutanja. U ovoj formuli koristi se kao ključni hidratantni sastojak. Dodaj u listu želja Dodaj u listu želja', 'Frudia Pomegranate Honey 3 In 1 Lip Balm je balzam za usne namenjen svakodnevnoj nezi suvih, ispucalih i dehidriranih usana, sa fokusom na hidrataciju, zaštitu i poboljšanje površinske teksture usana.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Frudia-Pomegranate-Honey-3-In-1-Lip-Balm-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
