INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (177, 47, 'Dr. Reju-All Advanced Retino-Mela Serum', 'dr-reju-all-advanced-retino-mela-serum', 'Ključne prednosti Ujednačavanje tena: Deluje na različite faze procesa hiperpigmentacije i doprinosi ravnomernijem tonu kože. Poboljšanje teksture: Podržava obnavljanje površinskog sloja kože i smanjuje osećaj hrapavosti. Dobra podnošljivost: Formulisan je tako da umanji iritativni potencijal u odnosu na klasične oblike retinola. Kome je namenjen? Namenjen je koži sa hiperpigmentacijama, neujednačenim tonom i znakovima sporije obnove kože. Pogodan je za odrasle osobe koje uvode retinoidnu negu ili traže kontrolisan pristup tretiranju diskoloracija. Zašto volimo Dr. Reju-All Advanced Retino-Mela Serum? Formula je zasnovana na kombinaciji retinoida i sastojaka koji deluju na pigmentaciju kroz različite mehanizme. HPR omogućava retinoidno delovanje uz stabilniji profil i bolju podnošljivost. Visoka koncentracija niacinamida doprinosi barijernoj stabilnosti i ujednačenosti tena. Traneksaminska kiselina je uključena sa jasnom ulogom u kontroli nastanka tamnih mrlja. Alfa-bisabolol ima umirujuću funkciju u okviru aktivne formule. Serum je prilagođen dugoročnom korišćenju uz pravilnu zaštitu od sunca. Aktivni sastojci Hydroxypinacolone Retinoate (HPR) 0,1% Hydroxypinacolone Retinoate je retinoid koji se direktno vezuje za retinoidne receptore u koži. Deluje tako što podstiče obnovu epidermisa i ujednačavanje teksture kože. U ovoj formuli koristi se u koncentraciji od 0,1% prilagođenoj redovnoj upotrebi. Ne zahteva prethodnu enzimsku konverziju kao klasični retinol. Dugoročno doprinosi glađem i ujednačenijem izgledu kože. Njegova uloga je usmerena na kontrolisanu površinsku obnovu. Niacinamid 10% Niacinamid je aktivni oblik vitamina B3 koji utiče na više funkcija kože. Deluje tako što smanjuje prenos melanina ka površinskim slojevima kože. U ovoj koncentraciji doprinosi ujednačavanju tena i regulaciji lučenja sebuma. Istovremeno podržava funkciju kožne barijere. Ne izaziva eksfolijaciju niti ljuštenje. Dugoročno doprinosi stabilnijem tonu i teksturi kože. Traneksaminska kiselina (TXA) 4% Traneksaminska kiselina je sastojak koji se koristi za kontrolu hiperpigmentacija. Deluje tako što utiče na procese povezane sa prekomernom proizvodnjom melanina. U ovoj formuli koristi se u koncentraciji od 4%. Ne deluje kao eksfolijant i nema keratolitičko dejstvo. Pogodna je za kožu sklonu diskoloracijama. Dugoročno doprinosi smanjenju vidljivosti tamnih mrlja. Alfa-bisabolol 0,5% Alfa-bisabolol je umirujući sastojak biljnog porekla. Deluje tako što pomaže smanjenju crvenila i nelagodnosti kože. U ovoj formuli ima ulogu balansiranja potencijalne osetljivosti izazvane aktivnim sastojcima. Ne utiče direktno na pigmentaciju ili obnovu kože. Pogodan je za osetljivu i reaktivnu kožu. Dugoročno doprinosi boljoj podnošljivosti proizvoda. Dodaj u listu želja Dodaj u listu želja', 'Dr. Reju-All Advanced Retino-Mela Serum kombinuje Hydroxypinacolone Retinoate (HPR) u koncentraciji od 0,1%, niacinamid 10%, traneksaminsku kiselinu 4% i alfa-bisabolol 0,5% radi obnove površine kože i regulaciju procesa stvaranja melanina. Formula je osmišljena za kožu sa neujednačenim tonom, tamnim mrljama i vidljivim znakovima nepravilne teksture.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Dr.-Reju-All-Advanced-Retino-Mela-Serum-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
