INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (178, 47, 'Dr. Reju-All Advanced LC-Ceramide Barrier Cream', 'dr-reju-all-advanced-lc-ceramide-barrier-cream', 'Ključne prednosti Jačanje kožne barijere: Doprinosi stabilnijoj lipidnoj strukturi i otpornosti kože na spoljašnje uticaje. Dugotrajna hidratacija: Pomaže zadržavanje vlage u površinskim slojevima kože tokom dana i noći. Umirivanje osetljive kože: Smanjuje osećaj zatezanja, nelagodnosti i reaktivnosti kože. Kome je namenjen? Namenjen je suvoj, osetljivoj i oslabljenoj koži, uključujući kožu sklonu iritacijama i narušenoj barijeri. Pogodan je za odrasle osobe koje koriste aktivne tretmane ili imaju potrebu za dugoročnom barijernom negom. Zašto volimo Dr. Reju-All Advanced LC-Ceramide Barrier Cream? Formula je osmišljena oko dugolančanih ceramida koji su strukturno slični prirodnim lipidima kože. Tekstura je lagana, ali dovoljno nutritivna da pruži kontinuiranu podršku barijeri. Sastav je uravnotežen tako da omogući dobru toleranciju kod osetljive kože. Krema je pogodna za dugoročnu svakodnevnu upotrebu bez preopterećenja kože. Aktivni sastojci su jasno definisani i funkcionalno usmereni. Proizvod se lako uklapa u različite rutine nege. Aktivni sastojci PDRN (Polydeoxyribonucleotide) PDRN je biološki aktivan sastojak dobijen iz DNK lososa, poznat po svojoj ulozi u procesima obnove kože. Deluje tako što podržava ćelijsku regeneraciju i oporavak oštećenog kožnog tkiva. U ovoj formuli prisutan je u koncentraciji od 1.200 ppm, što omogućava stabilno i kontrolisano delovanje. Sastojak je pročišćen farmaceutskim postupcima kako bi se smanjio rizik od iritacija. Ne deluje agresivno i pogodan je za osetljivu i oslabljenu kožu. Dugoročno doprinosi poboljšanju strukture i otpornosti kože. Hidrolizovani kolagen Hidrolizovani kolagen je oblik kolagena razgrađen na manje molekule radi bolje kompatibilnosti sa kožom. Deluje prvenstveno na površinskom nivou, gde doprinosi osećaju elastičnosti i zaglađenosti. U ovoj formuli ima ulogu podrške strukturi kože. Ne stimuliše sopstvenu sintezu kolagena, već deluje kao pomoćni sastojak u nezi. Doprinosi boljoj teksturi i komforu kože. Njegovo dejstvo je stabilno i pogodno za svakodnevnu upotrebu. Hidrolizovani hijaluronat Hidrolizovani hijaluronat je hijaluronska kiselina smanjene molekulske mase. Deluje tako što poboljšava zadržavanje vode u površinskim i plićim slojevima kože. U ovoj formuli doprinosi dugotrajnijem osećaju hidratacije. Ne stvara težak ili lepljiv film na koži. Pogodan je za kožu sklonu dehidrataciji. Dugoročno pomaže očuvanju elastičnosti i glatkoće kože. Niacinamid Niacinamid je aktivni oblik vitamina B3 sa višestrukim funkcijama u nezi kože. Deluje na jačanje kožne barijere i poboljšanje ujednačenosti tena. U ovoj formuli koristi se u koncentraciji prilagođenoj svakodnevnoj upotrebi. Pomaže u regulaciji lučenja sebuma i smanjenju neujednačene teksture. Ne izaziva isušivanje niti ljuštenje kože. Dugoročno doprinosi stabilnijem i otpornijem stanju kože. Dodaj u listu želja Dodaj u listu želja', 'Dr. Reju-All Advanced LC-Ceramide Barrier Cream sadrži dugolančane ceramide u koncentraciji od 1%, pantenol, niacinamid i beta-sitosterol, sa ciljem stabilizacije barijerne funkcije i smanjenja transepidermalnog gubitka vode. Namenjena je koži koja pokazuje znake suvoće, iritacije, narušene barijere i neujednačenog tona.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Dr.-Reju-All-Advanced-LC-Ceramide-Barrier-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
