INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (180, 46, 'Derma:B Ultra Moisture Body Cream', 'dermab-ultra-moisture-body-cream', 'Ključne prednosti Dugotrajna hidratacija: Doprinosi kontinuiranom održavanju vlažnosti kože tokom dužeg vremenskog perioda. Jačanje kožne barijere: Pomaže očuvanju lipidne strukture kože i njene otpornosti na spoljašnje uticaje. Dobra podnošljivost: Formulisana je bez parabena, fenoksietanola, mineralnih ulja, boja i etanola. Kome je namenjena? Namenjena je suvoj, veoma suvoj i osetljivoj koži tela. Pogodna je za osobe sa narušenom kožnom barijerom, kao i za dugotrajnu svakodnevnu negu bez obzira na uzrast. Zašto volimo Derma:B Ultra Moisture Body Cream? Formula je osmišljena sa jasnim fokusom na obnovu lipida i dugoročnu stabilizaciju hidratacije kože. Kombinacija biljnih butera i emolijenasa pruža nutritivnu negu bez agresivnog delovanja. Pantenol ima ulogu balansiranja i poboljšanja tolerancije kože. Krema je pogodna za večernju i kontinuiranu upotrebu kod izrazito suve kože. Dermatološki je testirana i prilagođena osetljivim tipovima kože. Namenjena je održavanju kvaliteta kože, a ne trenutnim, prolaznim efektima. Aktivni sastojci Ši buter Ši buter je biljni lipid bogat masnim kiselinama koji doprinosi obnavljanju zaštitnog lipidnog sloja kože. Deluje tako što smanjuje gubitak vode iz kože i povećava njenu mekoću. U ovoj formuli ima ulogu intenzivne nutritivne podrške suvoj koži. Ne deluje iritativno i pogodan je za osetljive tipove kože. Dugoročno doprinosi elastičnijem i otpornijem izgledu kože. Njegova uloga je centralna u obnovi barijerne funkcije. Kakao buter Kakao buter je emolijens koji doprinosi omekšavanju i zaglađivanju površine kože. Deluje stvaranjem zaštitnog lipidnog filma koji pomaže u zadržavanju vlage. U ovoj formuli ima ulogu dopune delovanja ši butera. Ne utiče na aktivne procese u koži već pruža pasivnu zaštitu. Dugoročno doprinosi smanjenju osećaja suvoće i hrapavosti. Njegova funkcija je stabilizujuća i zaštitna. Ulje semenki grožđa Ulje semenki grožđa je lagani emolijens bogat linolnom kiselinom. Deluje tako što pomaže održavanju fleksibilnosti kožne barijere. U ovoj formuli doprinosi boljoj razmazivosti i lakšem upijanju kreme. Ne ostavlja težak ili mastan sloj na koži. Dugoročno pomaže u očuvanju ujednačene teksture kože. Njegova uloga je balans između hranljivosti i komfora. Pantenol Pantenol je provitamin B5 koji se koristi zbog svog hidratantnog i umirujućeg dejstva. Deluje tako što pomaže vezivanje vode u površinskim slojevima kože. U ovoj formuli doprinosi smanjenju osećaja zatezanja i nelagodnosti. Podržava regeneraciju kože nakon isušivanja. Dugoročno doprinosi boljoj toleranciji kože na spoljašnje uticaje. Njegova uloga je stabilizujuća i zaštitna. Dodaj u listu želja Dodaj u listu želja', 'Derma:B Ultra Moisture Body Cream sadrži ši buter, kakao buter, ulje semenki grožđa i pantenol, koji doprinose obnavljanju lipidne ravnoteže i smanjenju transepidermalnog gubitka vode. Namenjena je koži sklonoj hroničnoj suvoći, zatezanju i spoljašnjim iritacijama, uz formulaciju bez potencijalno iritirajućih sastojaka.', 'https://beauty-health.rs/wp-content/uploads/2026/01/DermaB-Ultra-Moisture-Body-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
