INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (182, 37, 'Colorgram Pin Point Eyeshadow Palette', 'colorgram-pin-point-eyeshadow-palette', 'Ključne prednosti Kontrolisano nanošenje boje: Omogućava postepeno građenje intenziteta bez naglašenog taloženja u pregibima kapka. Raznovrsnost nijansi i završnica: Sadrži mat, sjajne i šimeraste tonove za kompletan izgled očiju. Lako blendanje: Tekstura omogućava ravnomerno stapanje boja bez praškastog ili kredastog efekta. Kome je namenjen? Namenjena je svim tipovima kože kapaka, uključujući osetljive. Pogodna je za početnike i iskusnije korisnike koji žele praktičnu paletu za svakodnevnu ili putnu upotrebu. Zašto volimo Colorgram Pin Point Eyeshadow Palette? Paleta je osmišljena sa jasnom logikom rasporeda nijansi koje se međusobno nadopunjuju. Kombinacija baza, srednjih tonova, tamnijih nijansi i akcenata omogućava jednostavno formiranje celovitog izgleda. Tekstura je prilagođena dugotrajnom nošenju bez naglašenog rasipanja. Pigmentacija je umerena i omogućava kontrolu intenziteta. Paleta je dostupna u toplim i hladnim varijantama, što olakšava izbor prema podtonu kože. Namenjena je dugoročnoj upotrebi bez osećaja težine na kapcima. Aktivni sastojci Pigmenti Pigmenti su osnovni nosioci boje u senkama za oči. Deluju tako što se ravnomerno raspoređuju po površini kapka tokom nanošenja. U ovoj paleti omogućavaju postepeno građenje intenziteta bez naglih prelaza. Njihov uticaj je isključivo vizuelan i ne menja stanje kože. Dugoročno ne utiču na strukturu kapka. Specifičnost formule je u ujednačenoj raspodeli pigmenta bez izraženog rasipanja. Mika Mika je mineralni sastojak koji doprinosi refleksiji svetlosti u senkama. Deluje tako što daje sjaj i dubinu boje bez metalnog efekta gde nije predviđen. U ovoj paleti koristi se u šimerastim i sjajnim nijansama. Ne utiče na hidrataciju ili osetljivost kože. Dugoročno nema kumulativno dejstvo na kapke. Njena uloga je precizno kontrolisana u skladu sa završnicom nijanse. Vezivni emolijensi Vezivni emolijensi omogućavaju da se pigmenti ravnomerno vežu za kožu kapka. Deluju tako što poboljšavaju klizanje proizvoda tokom nanošenja. U ovoj formuli smanjuju praškasti osećaj i olakšavaju blendanje. Ne ostavljaju masan trag na kapcima. Dugoročno doprinose stabilnosti teksture proizvoda. Njihova specifičnost je u balansu između postojanosti i komfora. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Pin Point Eyeshadow Palette kombinuje pigmente različite intenzivnosti i teksture kako bi omogućila ujednačeno nanošenje i lako blendanje bez praškastog efekta. Namenjena je postizanju definisanog, ali prirodno kontrolisanog izgleda kapaka, uz minimalno rasipanje proizvoda.', 'https://beauty-health.rs/wp-content/uploads/2026/01/colorgram-PIN-POINT-EYESHADOW-PALETTE-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
