INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (183, 37, 'Colorgram Fruity Glass Tint Mini Duo Set', 'colorgram-fruity-glass-tint-mini-duo-set', 'Ključne prednosti Hidratacija usana: Pomaže u održavanju stabilnog nivoa vlažnosti usana tokom nošenja. Sjajna završnica: Obezbeđuje ujednačen, staklasti izgled površine usana. Praktično mini pakovanje: Omogućava lako nošenje i zamenu nijansi u toku dana. Kome je namenjen? Namenjen je svim tipovima usana, uključujući normalne i suve. Pogodan je za osobe koje žele hidratantni sjaj za svakodnevnu upotrebu ili za kombinovanje različitih nijansi u manjem pakovanju. Zašto volimo Colorgram Fruity Glass Tint Mini Duo Set? Set je osmišljen tako da omogući fleksibilnost u izboru nijansi bez potrebe za punim pakovanjem proizvoda. Mini format olakšava nošenje i ponovnu aplikaciju tokom dana. Formula je fokusirana na komfor usana, bez stvaranja lepljivog filma. Prisustvo hidratantnih sastojaka doprinosi stabilnom osećaju tokom nošenja. Proizvodi se mogu koristiti samostalno ili u kombinaciji sa drugim proizvodima za usne. Namenjeni su redovnoj upotrebi bez opterećenja usana. Aktivni sastojci Glicerin Glicerin je humektans koji privlači i zadržava vodu na površini usana. Deluje tako što smanjuje isušivanje tokom nošenja proizvoda. U ovoj formuli doprinosi osećaju mekoće i glatkoće. Ne utiče na boju niti sjaj, već ima isključivo hidratantnu funkciju. Dugoročno pomaže u očuvanju komfora usana. Njegova uloga je stabilna i pogodna za svakodnevnu primenu. Skvalan Skvalan je emolijens koji doprinosi očuvanju glatke površine usana. Deluje tako što smanjuje transepidermalni gubitak vlage. U ovoj formuli pomaže u sprečavanju osećaja zatezanja. Ne ostavlja težak ili mastan sloj. Dugoročno doprinosi elastičnosti usana. Njegova funkcija je podrška barijeri usana. Pigmenti Pigmenti su odgovorni za boju i vizuelni efekat proizvoda. Deluju tako što ravnomerno prekrivaju površinu usana u tankom sloju. U ovoj formuli omogućavaju prozirnu do blago izraženu nijansu. Ne utiču na hidrataciju ili strukturu usana. Dugoročno ne menjaju stanje usana. Njihova uloga je isključivo estetska. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Fruity Glass Tint Mini Duo Set sadrži dva Fruity Glass Tint proizvoda u mini pakovanju, sa glicerinom i skvalanom kao ključnim hidratantnim sastojcima. Namenjen je održavanju vlažnosti usana i postizanju sjajne završnice bez lepljivog osećaja, uz mogućnost kombinovanja nijansi.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Colorgram-Fruity-Glass-Tint-Mini-Duo-Set.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
