INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (184, 37, 'Colorgram Fruity Glass Tint Milk', 'colorgram-fruity-glass-tint-milk', 'Ključne prednosti Produžena hidratacija: Pomaže u očuvanju vlažnosti usana tokom nošenja i smanjuje osećaj zatezanja. Stabilna mlečna boja: Obezbeđuje svetlu i ujednačenu nijansu koja ne potamnjuje kako vreme prolazi. Visok sjaj bez lepljivosti: Daje sjajnu završnicu uz zadržavanje komfora na usnama. Kome je namenjen? Namenjen je svim tipovima usana, posebno suvim i normalnim. Pogodan je za osobe koje žele nežne, mlečne nijanse sa sjajem, bez osećaja težine ili isušivanja. Zašto volimo Colorgram Fruity Glass Tint Milk? Formula je osmišljena tako da kombinuje boju, sjaj i negu u jednom proizvodu. Mlečna pigmentacija je pažljivo balansirana kako bi izgled ostao svetao i čist tokom nošenja. Tekstura je prilagođena čestoj upotrebi bez osećaja nelagodnosti. Proizvod se ponaša stabilno na usnama i ne stvara neprijatan film. Može se koristiti samostalno ili kao dopuna jednostavnoj rutini nege usana. Namenjen je dugoročnoj upotrebi uz očuvanje prirodnog izgleda usana. Aktivni sastojci Emolijentna baza Emolijentna baza omogućava glatko nanošenje proizvoda po površini usana. Deluje tako što smanjuje trenje i olakšava ravnomerno raspoređivanje boje. U ovoj formuli doprinosi prijatnom osećaju tokom nošenja. Ne stvara težak ili mastan sloj na usnama. Dugoročno pomaže očuvanju mekoće površine usana. Njena uloga je ključna za komfor i stabilnost proizvoda. Hidratantni agensi Hidratantni agensi pomažu u zadržavanju vlage na površini usana. Deluju tako što smanjuju isparavanje vode tokom nošenja proizvoda. U ovoj formuli doprinose osećaju nalik balzamu za usne. Ne ometaju prijanjanje pigmenta. Dugoročno pomažu u sprečavanju osećaja suvoće. Njihova funkcija je podrška komforu tokom cele primene. Mlečni pigmenti Mlečni pigmenti su odgovorni za svetlu, meku nijansu proizvoda. Deluju tako što pružaju boju bez prekrivanja prirodne boje usana. U ovoj formuli omogućavaju ujednačen izgled bez potamnjivanja tokom vremena. Ne utiču na hidrataciju usana. Dugoročno zadržavaju stabilan vizuelni efekat. Njihova uloga je isključivo estetska i kontrolisana. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Fruity Glass Tint Milk koristi emolijentnu bazu, hidratantne komponente i mlečne pigmente kako bi obezbedio ujednačenu boju, sjaj i smanjen osećaj suvoće. Namenjen je usnama koje lako gube vlagu i kod kojih klasični tintevi mogu delovati isušujuće ili potamniti tokom vremena.', 'https://beauty-health.rs/wp-content/uploads/2026/01/02-Apricot-Dew-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
