INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (185, 37, 'Colorgram Fruity Glass Gloss', 'colorgram-fruity-glass-gloss', 'Ključne prednosti Sjajna završnica: Doprinosi vizuelno zaglađenom i punijem izgledu usana. Komfor tokom nošenja: Ne ostavlja lepljiv ili težak sloj na usnama. Fleksibilna primena: Može se koristiti samostalno ili preko proizvoda u boji. Kome je namenjen? Namenjen je svim tipovima usana, posebno normalnim i suvim. Pogodan je za osobe koje preferiraju sjajnu završnicu i nenametljivu pigmentaciju u svakodnevnoj upotrebi. Zašto volimo Colorgram Fruity Glass Gloss? Formula je osmišljena tako da obezbedi sjaj bez osećaja težine ili lepljivosti. Tekstura se ravnomerno raspoređuje i ne naglašava suve delove usana. Proizvod se lako kombinuje sa drugim proizvodima za usne bez narušavanja njihove teksture. Sjaj ostaje ujednačen tokom nošenja bez stvaranja nepravilnog filma. Pogodan je za ponovnu aplikaciju tokom dana. Namenjen je dugoročnoj upotrebi bez narušavanja komfora usana. Aktivni sastojci Emolijentna baza Emolijentna baza omogućava glatko klizanje proizvoda po površini usana. Deluje tako što smanjuje trenje prilikom nanošenja. U ovoj formuli doprinosi ujednačenom sjaju bez naglašavanja teksture usana. Ne stvara mastan ili težak osećaj. Dugoročno doprinosi prijatnom osećaju tokom nošenja. Njena uloga je tehnička i senzorna. Film-formirajući sastojci Film-formirajući sastojci omogućavaju stabilnost sjaja na usnama. Deluju tako što formiraju tanak sloj koji zadržava proizvod na mestu. U ovoj formuli doprinose postojanijem izgledu bez lepljivosti. Ne utiču na hidrataciju usana. Dugoročno obezbeđuju ujednačen vizuelni efekat. Njihova funkcija je isključivo funkcionalna. Pigmenti Pigmenti su odgovorni za boju proizvoda i njen intenzitet. Deluju tako što pružaju transparentnu do blago izraženu nijansu. U ovoj formuli omogućavaju ujednačenu boju bez prekrivanja prirodne boje usana. Ne utiču na hidrataciju. Dugoročno ne menjaju stanje usana. Njihova uloga je estetska i stabilna. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Fruity Glass Gloss pruža prozirnu do blago pigmentovanu boju i sjajnu završnicu koja vizuelno naglašava punoću usana. Namenjen je suvim i normalnim usnama kojima je potreban dodatni komfor i ujednačen izgled površine, bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Colorgram-Fruity-Glass-Gloss-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
