INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (186, 37, 'Colorgram Nude Blur Tint', 'colorgram-nude-blur-tint', 'Ključne prednosti Efekat zamućenja: Vizuelno ujednačava površinu usana i smanjuje naglašenost sitnih linija. Postojana mat boja: Pigment se ravnomerno vezuje za usne i zadržava stabilan izgled tokom nošenja. Lagano prijanjanje: Formula se lako razmazuje i ne stvara osećaj težine ili zatezanja. Kome je namenjen? Namenjen je svim tipovima usana, uključujući normalne i blago suve. Pogodan je za osobe koje preferiraju mat završnicu sa prirodnijim izgledom i bez izraženog osećaja suvoće. Zašto volimo Colorgram Nude Blur Tint? Formula je osmišljena tako da balansira između pigmentacije i komfora tokom nošenja. Tekstura omogućava ravnomerno nanošenje bez naglih prelaza boje. Mat završnica je kontrolisana i ne deluje isušujuće pri pravilnoj primeni. Proizvod se može koristiti u tankom sloju za suptilan efekat ili slojevito za izraženiju boju. Može se prilagoditi različitim stilovima šminke. Namenjen je dugoročnoj upotrebi bez narušavanja stanja usana. Aktivni sastojci Pigmenti Pigmenti su odgovorni za boju i vizuelni efekat proizvoda na usnama. Deluju tako što se ravnomerno raspoređuju po površini usana prilikom nanošenja. U ovoj formuli prilagođeni su mat završnici sa efektom zamućenja. Ne utiču na hidrataciju niti strukturu usana. Dugoročno ne menjaju stanje usana. Njihova uloga je isključivo estetska i stabilna u okviru formule. Emolijentna baza Emolijentna baza omogućava glatko razmazivanje proizvoda po usnama. Deluje tako što smanjuje trenje tokom nanošenja. U ovoj formuli doprinosi mekom osećaju uprkos mat završnici. Ne stvara težak ili mastan sloj. Dugoročno pomaže održavanju komfora tokom nošenja. Njena uloga je funkcionalna i usmerena na prijanjanje boje. Film-formirajući sastojci Film-formirajući sastojci omogućavaju da se boja stabilno zadrži na usnama. Deluju tako što formiraju tanak sloj koji vezuje pigment. U ovoj formuli doprinose postojanosti bez osećaja zatezanja. Ne utiču na hidrataciju usana. Dugoročno omogućavaju ujednačen izgled boje. Njihova funkcija je tehnička i nega nije primarna. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Nude Blur Tint koristi pigmentnu bazu i laganu emolijentnu formulu kako bi obezbedio ravnomerno prijanjanje boje i mekan, mat izgled bez osećaja isušivanja. Namenjen je postizanju prirodno definisanih usana sa kontrolisanom postojanošću i bez naglašavanja linija.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Colorgram-Nude-Blur-Tint-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
