INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (187, 37, 'Colorgram Fruity Water Tint', 'colorgram-fruity-water-tint', 'Ključne prednosti Dugotrajan ton boje: Pigment se postepeno fiksira na usnama i zadržava boju bez razmazivanja. Prirodan izgled usana: Prozirna pigmentacija omogućava svež i nenametljiv efekat boje. Lagano i neljepljivo nošenje: Vodena tekstura ne ostavlja težak ili lepljiv sloj. Kome je namenjen? Namenjen je svim tipovima usana, uključujući suve i normalne. Pogodan je za osobe koje žele diskretan, svakodnevni izgled usana sa postojanom bojom. Zašto volimo Colorgram Fruity Water Tint? Formula je osmišljena tako da kombinuje jednostavnu primenu sa stabilnom pigmentacijom. Vodena tekstura omogućava ravnomerno nanošenje bez nakupljanja proizvoda. Pigment se vezuje za usne bez potrebe za čestim popravljanjem. Proizvod ne stvara zatamnjen ili zagušen izgled usana. Pogodan je za slojevito nanošenje u zavisnosti od željenog intenziteta. Namenjen je dugoročnoj upotrebi bez narušavanja komfora usana. Aktivni sastojci Vodena baza Vodena baza omogućava laganu i ravnomernu raspodelu pigmenta po površini usana. Deluje tako što brzo isparava, ostavljajući boju vezanu za usne. U ovoj formuli doprinosi osećaju svežine tokom nanošenja. Ne stvara film niti opterećuje usne. Dugoročno ne utiče na strukturu usana. Njena uloga je funkcionalna i stabilizujuća. Pigmenti rastvorljivi u vodi Pigmenti su prilagođeni vodenoj teksturi kako bi se ravnomerno vezivali za usne. Deluju tako što ostavljaju transparentan sloj boje koji se postepeno fiksira. U ovoj formuli omogućavaju prirodan i čist izgled usana. Ne stvaraju težak ili neujednačen završetak. Dugoročno ne utiču na hidrataciju usana. Njihova funkcija je isključivo estetska. Hidratantni agensi Hidratantni agensi prisutni u formuli pomažu u smanjenju osećaja suvoće tokom nošenja proizvoda. Deluju tako što privremeno vezuju vlagu na površini usana. U ovoj formuli doprinose prijatnom osećaju nakon nanošenja. Ne ometaju vezivanje pigmenta. Dugoročno pomažu očuvanju komfora usana. Njihova uloga je podržavajuća. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Fruity Water Tint pruža prozirnu, vodenu pigmentaciju koja se ravnomerno vezuje za usne i zadržava boju tokom dana. Namenjen je ujednačavanju boje usana i diskretnom osveženju izgleda, bez isušivanja ili naglašenog filma na površini.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Colorgram-Fruity-Water-Tint-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
