INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (188, 37, 'Colorgram Fruity Glass Tint', 'colorgram-fruity-glass-tint', 'Ključne prednosti Hidratacija usana: Pomaže u zadržavanju vlage i smanjenju osećaja suvoće tokom nošenja. Ujednačen izgled površine: Vizuelno zaglađuje teksturu usana i smanjuje naglašavanje sitnih linija. Lagano nošenje: Obezbeđuje sjajnu završnicu bez lepljivog ili teškog osećaja na usnama. Kome je namenjen? Namenjen je svim tipovima usana, posebno suvim i dehidriranim. Pogodan je za svakodnevnu upotrebu kod osoba koje žele sjaj i boju uz očuvanje komfora usana. Zašto volimo Colorgram Fruity Glass Tint? Formula je osmišljena sa fokusom na ravnotežu između boje, sjaja i nege usana. Prisustvo ovlaživača omogućava nošenje proizvoda bez dodatnog isušivanja. Tekstura se ravnomerno raspoređuje i ne stvara neprijatan film na usnama. Nijansa 08 Lovely Raspberry je prilagođena različitim podtonovima kože, što omogućava lakše uklapanje u svakodnevni izgled. Proizvod se može nanositi samostalno ili preko olovke za usne. Namenjen je dugoročnom, ponovljivom korišćenju bez narušavanja stanja usana. Aktivni sastojci Glicerin Glicerin je humektans koji privlači i zadržava vodu u površinskim slojevima usana. Deluje tako što smanjuje gubitak vlage tokom nošenja proizvoda. U ovoj formuli doprinosi osećaju mekoće i elastičnosti. Ne utiče na boju niti sjaj, već ima isključivo negujuću ulogu. Dugoročno pomaže u sprečavanju isušivanja usana. Njegova funkcija je stabilna i pogodna za svakodnevnu upotrebu. Skvalan Skvalan je emolijens koji pomaže u očuvanju glatkoće površine usana. Deluje tako što smanjuje transepidermalni gubitak vode. U ovoj formuli doprinosi prijatnom osećaju tokom nošenja. Ne stvara težak ili masan sloj. Dugoročno pomaže održavanju elastičnosti usana. Njegova uloga je podrška barijeri usana. Pigmenti u nijansi 08 Lovely Raspberry Pigmenti su odgovorni za boju i vizuelni efekat proizvoda. Deluju tako što ravnomerno prekrivaju površinu usana bez naglašavanja nepravilnosti. U ovoj nijansi daju malinasto crvenu boju prilagođenu toplim i hladnim podtonovima. Ne utiču na hidrataciju usana. Dugoročno ne menjaju stanje usana. Njihova uloga je isključivo estetska i stabilna u okviru formule. Dodaj u listu želja Dodaj u listu želja', 'Colorgram Fruity Glass Tint sadrži glicerin i skvalan koji doprinose održavanju vlažnosti usana i sprečavaju osećaj suvoće. Namenjen je poboljšanju izgleda suvih i dehidriranih usana kroz sjajnu završnicu i ravnomerno raspoređenu boju, bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Colorgram-Fruity-Glass-Tint-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
