INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (189, 36, 'CNP Laboratory Propolis Energy Active Ampule', 'cnp-laboratory-propolis-energy-active-ampule', 'Ključne prednosti Umirivanje osetljive kože: Doprinosi smanjenju crvenila i subjektivnog osećaja iritacije. Održavanje hidratacije: Pomaže u obnavljanju i stabilizaciji nivoa vlage u koži. Podrška kožnoj barijeri: Doprinosi očuvanju otpornosti kože na spoljašnje faktore. Kome je namenjena? Namenjena je svim tipovima kože, posebno osetljivoj, dehidriranoj i koži sklonoj crvenilu. Pogodan je za svakodnevnu upotrebu kod osoba čija koža reaguje na spoljašnje uticaje ili aktivne tretmane. Zašto volimo CNP Laboratory Propolis Energy Active Ampule? Formula je osmišljena sa jasnim fokusom na toleranciju i balans kože. Kombinacija umirujućih i hidratantnih sastojaka omogućava redovnu i dugoročnu upotrebu bez narušavanja barijere. Tekstura je lagana i brzo se upija, što olakšava uklapanje u različite rutine nege. Proizvod ne ostavlja lepljiv trag i ne opterećuje kožu. Može se koristiti samostalno ili u kombinaciji sa drugim serumima. Namenjen je stabilizaciji stanja kože, a ne kratkotrajnim vizuelnim efektima. Aktivni sastojci Propolis Propolis je sastojak koji se u kozmetici koristi zbog svojih umirujućih i zaštitnih svojstava. Deluje tako što doprinosi smanjenju vidljivog crvenila i osećaja nelagodnosti na koži. U ovoj formuli ima ulogu podrške koži izloženoj spoljašnjim stresorima. Ne deluje isušujuće niti agresivno. Dugoročno doprinosi stabilnijem i ujednačenijem izgledu kože. Njegova uloga je usmerena na očuvanje ravnoteže kože. Beta-glukan Beta-glukan je polisaharid koji pomaže zadržavanje vlage u koži. Deluje kroz podršku barijernoj funkciji i smanjenje transepidermalnog gubitka vode. U ovoj ampuli doprinosi osećaju smirenosti i komfora. Ne utiče na eksfolijaciju niti izaziva peckanje. Dugoročno pomaže boljoj toleranciji kože. Njegovo delovanje je blago i pogodno za osetljivu kožu. Madecassoside Madecassoside je aktivna komponenta dobijena iz biljke Centella asiatica. Deluje tako što doprinosi smirivanju iritirane i reaktivne kože. U ovoj formuli ima ulogu stabilizacije i podrške oporavku kože. Ne deluje agresivno niti izaziva ljuštenje. Dugoročno doprinosi boljoj otpornosti kože. Njegova funkcija je usmerena na dugoročnu toleranciju. Hijaluronska kiselina Hijaluronska kiselina deluje kao humektans koji veže vodu u površinskim slojevima kože. Doprinosi poboljšanju hidratacije i elastičnosti kože. U ovoj ampuli ima ulogu održavanja optimalnog nivoa vlažnosti. Ne ostavlja težak ili lepljiv osećaj. Dugoročno pomaže stabilnijem izgledu kože. Njeno delovanje je kompatibilno sa svim tipovima kože. Dodaj u listu želja Dodaj u listu želja', 'CNP Laboratory Propolis Energy Active Ampule kombinuje propolis, beta-glukan, madecassoside i hijaluronsku kiselinu kako bi pružila koži podršku u trenucima kada joj je potrebna dodatna smirenost, elastičnost i svež izgled. Formula je lagana, brzo se upija i ne ostavlja lepljiv trag, što je čini pogodnom za svakodnevnu upotrebu i slojevito nanošenje u rutini.', 'https://beauty-health.rs/wp-content/uploads/2026/01/PropolisEnergyActiveAmpule_grande.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
