INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (195, 45, 'Dear, Klairs Supple Preparation Unscented Toner', 'dear-klairs-supple-preparation-unscented-toner', 'Ključne prednosti Obnova hidratacije: Pomaže koži da povrati vlagu izgubljenu tokom čišćenja i priprema je za naredne korake nege. Podrška kožnoj ravnoteži: Doprinosi održavanju prirodnog pH nivoa kože, što je važno za očuvanje barijerne funkcije. Umirivanje osetljive kože: Sadrži sastojke koji smanjuju subjektivni osećaj iritacije i nelagodnosti. Kome je namenjen? Namenjen je normalnoj, suvoj, mešovitoj i osetljivoj koži, uključujući kožu sklonu crvenilu i reakcijama na mirise. Posebno je pogodan za osobe koje traže toner bez eteričnih ulja, kao i za one sa narušenom hidratacijom kože. Zašto volimo Dear, Klairs Supple Preparation Unscented Toner? Formula je osmišljena tako da pruži osnovnu hidratantnu i umirujuću negu bez sastojaka koji mogu dodatno opteretiti osetljivu kožu. Izostavljanje eteričnih ulja smanjuje rizik od iritacija kod reaktivnih tipova kože. Tekstura je lagana i omogućava slojevito nanošenje bez osećaja težine. Sastav je prilagođen svakodnevnoj i dugoročnoj upotrebi. Toner se lako uklapa u različite rutine nege, bez konflikta sa drugim aktivnim sastojcima. Fokus formule je na održavanju balansa, a ne na agresivnim korektivnim efektima. Aktivni sastojci Hijaluronska kiselina Hijaluronska kiselina deluje kao humektans koji privlači i zadržava vodu u površinskim slojevima kože. Njeno prisustvo doprinosi smanjenju osećaja suvoće nakon čišćenja. U ovoj formuli pomaže u očuvanju elastičnosti i uglađenosti kože. Ne utiče na eksfolijaciju niti menja strukturu kože, već deluje isključivo hidratantno. Dugoročno doprinosi stabilnijem nivou vlažnosti kada se koristi redovno. Njena uloga je podržavajuća i kompatibilna sa većinom aktivnih sastojaka u rutini. Beta-glukan Beta-glukan je polisaharid poznat po svojoj sposobnosti da umiri kožu i podrži njenu barijernu funkciju. Deluje tako što pomaže smanjenju transepidermalnog gubitka vode. U formulaciji doprinosi osećaju komfora nakon nanošenja. Njegovo dejstvo je blago i pogodno za osetljivu kožu. Dugoročno može doprineti boljoj toleranciji kože na spoljne uticaje. U kombinaciji sa hijaluronskom kiselinom pojačava ukupni hidratantni efekat. Centella asiatica Centella asiatica je biljni ekstrakt koji se koristi zbog svojih umirujućih svojstava. Deluje tako što pomaže smanjenju subjektivnog osećaja iritacije i crvenila. U ovoj formuli ima ulogu podrške koži nakon čišćenja. Ne deluje eksfolijativno niti aktivno stimuliše regeneraciju. Dugoročno doprinosi boljoj podnošljivosti proizvoda kod osetljive kože. Njeno prisustvo je usmereno na stabilnost i smirenost kože. Phyto-Oligo Phyto-Oligo predstavlja kompleks biljnih ugljenih hidrata koji pomažu u hidrataciji kože. Deluje tako što doprinosi zadržavanju vode u površinskim slojevima epidermisa. U formuli ima ulogu dodatne podrške osnovnim humektansima. Ne menja pH vrednost kože, već deluje u skladu sa njenom prirodnom ravnotežom. Dugoročno može doprineti smanjenju osećaja perutanja kod suve kože. Njegova funkcija je komplementarna ostalim hidratantnim sastojcima. Amino kiseline pšenice Amino kiseline pšenice učestvuju u održavanju prirodnog hidratantnog faktora kože. Deluju tako što podržavaju vezivanje vode u rožastom sloju. U ovoj formulaciji doprinose smanjenju osećaja zatezanja. Njihovo dejstvo je blago i pogodno za svakodnevnu upotrebu. Dugoročno pomažu očuvanju mekoće kože. U kombinaciji sa drugim umirujućim sastojcima doprinose stabilnosti formule. Dodaj u listu želja Dodaj u listu želja', 'Dear, Klairs Supple Preparation Unscented Toner sadrži hijaluronsku kiselinu, beta-glukan i biljne ekstrakte koji doprinose hidrataciji i umirivanju kože nakon umivanja. Namenjen je ublažavanju osećaja zatezanja, dehidratacije i iritacije, uz očuvanje fiziološke ravnoteže kože.', 'https://beauty-health.rs/wp-content/uploads/2026/01/Dear-Klairs-Supple-Preparation-Unscented-Toner-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
