INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (196, 175, 'WHIPPED Vegan Juicy Hand & Body Wash', 'whipped-vegan-juicy-hand-body-wash', 'Nežno čišćenje bez isušivanja: Uklanja nečistoće sa kože dok istovremeno čuva njen zaštitni sloj. Podrška kožnoj barijeri: Ceramide NP pomaže očuvanju hidratacije i otpornosti kože. Senzorni doživljaj mirisa: Sofisticirani fig-woodi miris pruža osećaj opuštanja tokom i nakon pranja. Kome je namenjen? Namenjen je svim tipovima kože, uključujući normalnu, suvu i osetljivu kožu. Posebno odgovara osobama koje često peru ruke ili žele nežan, ali efikasan proizvod za svakodnevno tuširanje. Zašto volimo WHIPPED Vegan Juicy Hand & Body Wash? Ovaj gel za pranje formulisan je tako da se može koristiti svakodnevno, čak i kod češćeg pranja ruku ili tuširanja. Tekstura se lako peni i ravnomerno raspoređuje po koži, omogućavajući efikasno čišćenje bez osećaja zatezanja. Biljni ekstrakti doprinose prijatnom osećaju svežine i mekoće nakon ispiranja. Ceramidi u formuli pomažu u očuvanju kožne barijere, što je posebno važno kod suve i osetljive kože. Miris je razvijen u saradnji sa parfemskim stručnjacima iz Francuske i ostaje suptilno prisutan na koži. Proizvod je veganski i prilagođen svakodnevnoj upotrebi. Namenjen je onima koji žele balans između funkcionalne nege i prijatnog rituala. Aktivni sastojci Ficus Carica (Fig) Fruit Extract Ekstrakt smokve poznat je po svom hidrirajućem i omekšavajućem delovanju na kožu. Pomaže u održavanju vlažnosti i doprinosi glatkijem osećaju nakon pranja. Sadrži prirodne šećere i antioksidanse koji podržavaju svež izgled kože. Deluje blago i pogodan je za osetljive tipove kože. Doprinosi prijatnom senzornom iskustvu proizvoda. U ovoj formuli ima ulogu hidratantne i balansirajuće komponente. Gardenia Florida Fruit Extract Ekstrakt gardenije doprinosi umirujućem efektu i prijatnom mirisnom profilu proizvoda. Pomaže koži da ostane mekana i glatka nakon ispiranja. Ima blago kondicionirajuće dejstvo. Pogodan je za svakodnevnu upotrebu bez rizika od isušivanja. Podržava osećaj komfora na koži. U kombinaciji sa drugim sastojcima doprinosi celokupnom balansu formule. Ceramide NP Ceramide NP su prirodni lipidi koji imaju ključnu ulogu u očuvanju kožne barijere. Pomažu u sprečavanju gubitka vlage tokom i nakon pranja. Doprinosе otpornosti kože na spoljašnje faktore. Posebno su važni kod kože sklone suvoći. Njihovo delovanje je dugoročno i stabilno. U ovom gelu doprinose osećaju hidrirane i zaštićene kože. Dodaj u listu želja Dodaj u listu želja', 'WHIPPED Vegan Juicy Hand & Body Wash je blagi, ali temeljni gel za ruke i telo koji čisti kožu bez narušavanja njene prirodne ravnoteže i ostavlja dugotrajan, umirujući miris. Vegan Juicy Hand & Body Wash u varijanti Muhwabutter kombinuje biljne ekstrakte smokve i gardenije sa Ceramide NP kako bi se koža očistila, hidrirala i zaštitila od isušivanja tokom svakodnevnog pranja.', 'https://beauty-health.rs/wp-content/uploads/2025/12/WHIPPED-Vegan-Juicy-Hand-Body-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
