INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (198, 174, 'VT Cica Exosome Ampoule Box', 'vt-cica-exosome-ampoule-box', 'Ključne prednosti: Ciljana nega po potrebi kože: Omogućava izbor ampule u skladu sa trenutnim stanjem kože bez preopterećenja rutine. Sinergijsko delovanje cica egzozoma: Pomaže bolju apsorpciju aktivnih sastojaka uz istovremeno umirujuće dejstvo. Kompletna rutina u jednom setu: Pokriva hidrataciju, smirivanje, posvetljivanje, jačanje barijere i elastičnost. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, problematičnu i reaktivnu kožu. Posebno odgovara osobama koje imaju promenljive potrebe kože, poput akni, dehidratacije, crvenila ili gubitka sjaja. Zašto volimo VT Cica Exosome Ampoule Box? Ovaj set je koncipiran kao modularna rutina nege koja se prilagođava koži iz dana u dan. Cica egzozomi služe kao nosači aktivnih sastojaka, omogućavajući efikasniju isporuku u kožu uz smanjenje rizika od iritacije. Svaka ampula ima jasno definisanu ulogu, što eliminiše potrebu za složenim kombinovanjem proizvoda. Formule su osmišljene tako da se mogu koristiti pojedinačno ili naizmenično, u zavisnosti od potreba kože. Posebna prednost je balans između aktivnih i umirujućih komponenti. Set omogućava dugoročno unapređenje kvaliteta kože bez agresivnog pristupa. Namenjen je kontinuiranoj i promišljenoj nezi. Aktivni sastojci Azelaična kiselina Azelaična kiselina deluje na regulaciju lučenja sebuma i smanjenje zapaljenskih procesa u koži. Poznata je po sposobnosti da umiri crvenilo i doprinese čistijem izgledu kože. Pomaže u smanjenju nepravilnosti i vidljivosti pora. Deluje blago, ali efikasno, što je čini pogodnom i za osetljivu kožu. U ovoj formuli je podržana umirujućim biljnim ekstraktima. Namenjena je dugoročnoj kontroli problematične kože. PDRN PDRN je biološki aktivna komponenta koja doprinosi regeneraciji i poboljšanju elastičnosti kože. Deluje tako što podržava obnovu ćelija i poboljšava ukupni kvalitet kože. Posebno je koristan kod umorne i oslabljene kože. Doprinosi zdravijem i punijem izgledu tena. U ovoj formuli potiče iz biljnog izvora. Namenjen je postepenom jačanju strukture kože. Glutation Glutation je snažan antioksidans koji doprinosi ujednačavanju tena i povećanju sjaja kože. Deluje na smanjenje vidljivosti sivila i umornog izgleda. Pomaže koži da izgleda svetlije i svežije. Njegovo delovanje je postepeno i nenametljivo. Posebno je koristan kod neujednačenog tona. U ampuli je formulisan tako da bude stabilan i efikasan. Hijaluronska kiselina Hijaluronska kiselina obezbeđuje dubinsku hidrataciju i doprinosi punijem izgledu kože. Vezuje vodu u koži i pomaže u smanjenju osećaja zatezanja. Poboljšava elastičnost i glatkoću površine kože. U liposomskoj formi omogućava dugotrajnije dejstvo. Pogodna je za svakodnevnu upotrebu. Doprinosi zdravom i hidriranom izgledu tena. Skvalan Skvalan je lipid sličan prirodnim komponentama kože koji jača zaštitnu barijeru. Pomaže u sprečavanju gubitka vlage i održavanju ravnoteže ulja i vode. Ne ostavlja težak ili mastan osećaj. Posebno je koristan kod suve i osetljive kože. Doprinosi smirenijem i otpornijem stanju kože. Biljnog je porekla i dobro se podnosi. Dodaj u listu želja Dodaj u listu želja', 'VT Cica Exosome Ampoule Box je pažljivo osmišljen set ampula koji omogućava ciljanu negu kože kroz pet različitih aktivnih formula zasnovanih na cica egzozomima. Exosome Ampoule Box kombinuje azelaičnu kiselinu, PDRN, glutation, hijaluronsku kiselinu i skvalan kako bi se istovremeno odgovorilo na probleme akni, dehidratacije, narušene barijere, gubitka elastičnosti i neujednačenog tena.', 'https://beauty-health.rs/wp-content/uploads/2025/12/VT-Cica-Exosome-Ampoule-Box-6.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
