INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (199, 171, 'VDL Lumilayer Primer', 'vdl-lumilayer-primer', 'Ključne prednosti: Vizuelno osvetljavanje i ujednačavanje tena: Kombinacija crvene i plave svetlosti doprinosi svetlijem, čistijem i uravnoteženijem izgledu kože. Zaglađivanje teksture kože: Pomaže da površina kože deluje glađe i pripremljenije za nanošenje pudera. Dewy završnica bez masnog efekta: Daje koži suptilan sjaj koji izgleda prirodno i negovano. Kome je namenjen? Namenjen je svim tipovima kože, posebno koži bez sjaja, sivkastog tona ili neujednačene teksture. Pogodan je za osobe koje žele blistav, ali kontrolisan i prirodan završni efekat ispod pudera. Zašto volimo VDL Lumilayer Primer? Ovaj prajmer je osmišljen kao korak koji poboljšava način na koji se šminka ponaša na koži, ali i izgled kože i bez dodatnih proizvoda. Violet Lumilayer pigmenti reflektuju svetlost na način koji ublažava sivilo i neujednačenost tena. Crvena komponenta doprinosi toplijem i zdravijem izgledu, dok plava daje efekat čistoće i svežine. Tekstura se lako razmazuje i ravnomerno stapa sa kožom. Ne ostavlja težak sloj niti naglašava pore i fine linije. Posebno je pogodan za postizanje prirodnog, „glass skin“ efekta. Namenjen je svakodnevnoj upotrebi u makeup rutini. Aktivni sastojci Violet Lumilayer pigmenti Ovi pigmenti su razvijeni kombinovanjem crvene i plave svetlosti kako bi se postigao balansiran efekat osvetljavanja tena. Crvena komponenta doprinosi svetlijem i zdravijem izgledu kože. Plava komponenta vizuelno čisti ten i ublažava neujednačenosti. Zajedno reflektuju svetlost na način koji daje prirodan sjaj. Ne prekrivaju kožu, već je optički ulepšavaju. Imaju ključnu ulogu u dewy završnici prajmera. Dodaj u listu želja Dodaj u listu želja', 'VDL Lumilayer Primer je iluminirajući prajmer namenjen ujednačavanju tena, zaglađivanju teksture kože i vizuelnom osvetljavanju lica pre nanošenja pudera. Lumilayer Primer koristi specifične Violet Lumilayer pigmente, nastale kombinacijom crvene i plave svetlosti, kako bi koža delovala svežije, čistije i prirodno blistavije, bez teškog ili prenaglašenog sjaja.', 'https://beauty-health.rs/wp-content/uploads/2025/12/VDL-Lumilayer-Primer-.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
