INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (200, 170, 'Vaseline Lip Therapy Stick', 'vaseline-lip-therapy-stick', 'Ključne prednosti: Dugotrajna hidratacija i zaštita: Pomaže u zadržavanju vlage i sprečava isušivanje usana. Umirujuće i negujuće dejstvo: Aloe vera i kokosovo ulje smiruju suve i osetljive usne. Praktičan format za svakodnevnu upotrebu: Stick pakovanje omogućava lako nanošenje u pokretu. Kome je namenjen? Namenjen je svim tipovima kože, posebno osobama sa suvim, ispucalim i osetljivim usnama. Pogodan je za svakodnevnu upotrebu tokom cele godine, uključujući decu i odrasle. Zašto volimo Vaseline Lip Therapy Stick? Ovaj balzam je osmišljen kao pouzdana svakodnevna nega za usne koje su sklone suvoći i nelagodnosti. Vazelin formira zaštitni sloj koji sprečava gubitak vlage, dok kokosovo ulje doprinosi mekoći i prijatnom osećaju na usnama. Aloe vera umiruje i ublažava osećaj zatezanja, a vitamin E pruža dodatnu negu i podršku kožnoj barijeri. Tekstura je lagana i prijatna, bez lepljivog osećaja. Balzam se lako nanosi i može se koristiti više puta tokom dana. Namenjen je kontinuiranoj nezi, posebno u uslovima vetra, hladnoće ili suvog vazduha. Diskretan miris kokosa dodatno doprinosi prijatnom iskustvu korišćenja. Aktivni sastojci Vaseline Jelly Vazelin je poznat po svojoj sposobnosti da zadrži vlagu u koži. Formira zaštitni sloj koji sprečava isušivanje usana. Pomaže u obnavljanju mekoće. Smanjuje osećaj zatezanja i ispucalosti. Deluje površinski, ali veoma efikasno. Pogodan je za čestu upotrebu. Coconut Oil Kokosovo ulje ima hranljivo i omekšavajuće dejstvo. Pomaže u obnavljanju suvih usana. Doprinosi glatkoj teksturi usana. Pruža prijatan osećaj nakon nanošenja. Podržava svakodnevnu negu. Daje blag, prijatan miris. Aloe Vera Aloe vera deluje umirujuće i osvežavajuće. Pomaže u smanjenju nelagodnosti kod suvih i osetljivih usana. Doprinosi osećaju mekoće. Podržava oporavak kože. Deluje blago i stabilno. Pogodna je za svakodnevnu primenu. Vitamin E Vitamin E deluje kao antioksidans i sastojak za negu kože. Pomaže u zaštiti usana od spoljašnjih uticaja. Doprinosi održavanju zdravog izgleda. Podržava hidrataciju. Učestvuje u očuvanju kožne barijere. Pogodan je za dugoročnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Vaseline Lip Therapy Stick je balzam za usne namenjen dugotrajnoj hidrataciji, zaštiti i umirenju suvih i ispucalih usana, formulisan za svakodnevnu i praktičnu upotrebu. Lip Therapy Stick, proizveden u Koreji, kombinuje vazelin, kokosovo ulje, aloe veru i vitamin E kako bi usne ostale mekane, glatke i zaštićene tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Vaseline-Lip-Therapy-Stick-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
