INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (203, 164, 'TIRTIR Matcha Calming Cream', 'tirtir-matcha-calming-cream', 'Ključne prednosti: Dugotrajno umirenje i anti-redness efekat: Deluje na smanjenje crvenila i nelagodnosti kod osetljive i reaktivne kože. Jačanje kožne barijere: Matcha-PDRN pomaže koži da postane otpornija na spoljne iritanse. Poboljšanje elastičnosti i čvrstoće: Peptidi i veganski kolagen doprinose punijem i zategnutijem izgledu kože. Kome je namenjena? Namenjen je svim tipovima kože, posebno osetljivoj, reaktivnoj i koži sklonoj crvenilu. Pogodan je za kožu sa oslabljenom barijerom, dehidriranu kožu i kožu izloženu spoljnim stresorima. Zašto volimo TIRTIR Matcha Calming Cream? Ova krema je osmišljena za kožu kojoj je potrebna stabilnost, a ne agresivni aktivni sastojci. Matcha-PDRN deluje zaštitno i umirujuće, dok peptidni kompleks podržava strukturu kože i njen oporavak. Pudingasta tekstura se prijanja uz kožu i stvara zaštitni sloj koji sprečava gubitak vlage. Krema pruža osećaj hlađenja i smirenja bez težine ili masnog traga. Namenjena je svakodnevnoj upotrebi, posebno kod kože sklone crvenilu i iritacijama. Redovnom primenom koža deluje stabilnije, mekše i vidno ujednačenije. Formula je hipoalergenski testirana i prilagođena osetljivoj koži. Aktivni sastojci Matcha-PDRN Matcha-PDRN kombinuje umirujuća svojstva zelenog čaja sa regenerativnim potencijalom PDRN-a. Pomaže u jačanju kožne barijere. Deluje umirujuće na crvenilo i iritacije. Podržava obnovu kože. Doprinosi stabilnijem i otpornijem stanju kože. Pogodan je za osetljivu kožu. Veganski kolagen Veganski kolagen doprinosi poboljšanju elastičnosti kože. Pomaže u očuvanju glatke i pune teksture. Podržava hidrataciju površinskih slojeva kože. Daje koži mekši i ujednačeniji izgled. Deluje kao potporni sastojak u anti-age nezi. Dobro se podnosi i kod osetljive kože. Peptidi (13 vrsta) Peptidi imaju važnu ulogu u očuvanju strukture kože. Doprinose čvrstoći i elastičnosti. Podržavaju regenerativne procese. Deluju sinergijski sa kolagenom. Pomažu koži da izgleda zategnutije. Namenjeni su dugoročnom poboljšanju kvaliteta kože. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Matcha Calming Cream je umirujuća i učvršćujuća krema za lice, formulisana za smanjenje crvenila, jačanje kožne barijere i poboljšanje elastičnosti kod osetljive i iritirane kože. Matcha Calming Cream kombinuje Matcha-PDRN, veganski kolagen i trinaest vrsta peptida u jedinstvenoj „puding“ teksturi koja pruža dugotrajnu hidrataciju, stabilnost i osećaj komfora.', 'https://beauty-health.rs/wp-content/uploads/2025/12/TIRTIR-Matcha-Calming-Cream-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
