INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (204, 164, 'Tirtir Ice-Cooling Water Drop Serum', 'tirtir-ice-cooling-water-drop-serum', 'Ključne prednosti: Trenutni efekat hlađenja i smirivanja: Brzo snižava temperaturu kože i ublažava nelagodnost izazvanu toplotom. Dubinska hidratacija i učvršćivanje: Kapsulisani peptidi i hijaluronska kiselina doprinose elastičnijem i punijem izgledu kože. Balansiranje sebuma i pora: Pomaže u privremenom smanjenju pora proširenih usled toplote i viška sebuma. Kome je namenjen? Namenjen je svim tipovima kože, posebno masnoj, kombinovanoj i koži sklonoj pregrevanju, crvenilu i proširenim porama. Pogodan je i za dehidriranu kožu kojoj je potrebna hidratacija bez težine. Zašto volimo Tirtir Ice-Cooling Water Drop Serum? Ovaj serum je osmišljen kao brz odgovor kože na toplotni stres. Dual-Cool Sync&#x2122; sistem pruža dvostruki efekat hlađenja – trenutno osveženje i sprečavanje ponovnog porasta temperature kože. Lagana, vodena tekstura se brzo upija i ne ostavlja težak osećaj na koži. Plave kapsule u serumu sadrže 22K Capsule Spicules koje omogućavaju stabilnu i efikasnu isporuku aktivnih sastojaka. Redovnom upotrebom koža deluje smirenije, hidriranije i vizuelno čvršće. Posebno je pogodan u letnjem periodu ili nakon boravka na suncu. Lako se uklapa u svakodnevnu rutinu bez opterećenja. Aktivni sastojci Dual-Cool Sync&#x2122; kompleks Ovaj kompleks je osmišljen da obezbedi trenutno i produženo hlađenje kože. Pomaže u snižavanju temperature površine kože. Sprečava nagli povratak toplote nakon izlaganja suncu. Doprinosi osećaju komfora i smirenosti. Posebno je koristan kod kože pod toplotnim stresom. Deluje brzo i efikasno. Ice Heart Leaf i ostrvska glečerska voda Ice heart leaf deluje umirujuće i balansirajuće na kožu. Pomaže u smanjenju nelagodnosti izazvane spoljnim uticajima. Glečerska voda doprinosi osveženju i hidrataciji. Zajedno podržavaju stabilnost kože. Daju osećaj čistoće i svežine. Pogodni su za osetljivu kožu. 22K Capsule Spicules sa Pepta-HA6 kompleksom Ove kapsule omogućavaju preciznu isporuku peptida i šest vrsta hijaluronske kiseline. Peptidi doprinose učvršćivanju i elastičnosti kože. Hijaluronska kiselina obezbeđuje dubinsku hidrataciju. Pomažu koži da izgleda punije i zategnutije. Deluju sinergijski za vidljivo poboljšanje teksture. Imaju ključnu ulogu u dugoročnom efektu seruma. Dodaj u listu želja Dodaj u listu želja', 'Tirtir Ice-Cooling Water Drop Serum je osvežavajući serum formulisan za trenutno hlađenje kože izložene toploti, suncu ili pojačanom lučenju sebuma, uz istovremenu dubinsku hidrataciju i učvršćivanje. Water Drop Serum kombinuje Dual-Cool Sync&#x2122; tehnologiju, ledenu biljku srcolist (heart leaf), ostrvsku glečersku vodu i kapsulisane spikule sa peptidima i hijaluronskom kiselinom kako bi koža bila smirena, hidrirana i vidno zategnutija.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Tirtir-Ice-Cooling-Water-Drop-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
