INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (205, 164, 'Tirtir 5 Actives Power Serums Kit', 'tirtir-5-actives-power-serums-kit', 'Ključne prednosti: Sveobuhvatna nega u jednom setu: Pet različitih seruma omogućava kombinovanje i prilagođavanje rutine prema potrebama kože. Ciljani aktivni sastojci: Svaki serum je formulisan za konkretan problem poput dehidratacije, neujednačenog tena, pora, nepravilnosti ili teksture. Mini pakovanja za fleksibilnu upotrebu: Idealno za testiranje, putovanja ili rotaciju aktivnih sastojaka bez preopterećenja kože. Kome je namenjen? Namenjen je svim tipovima kože, uključujući kombinovanu i problematičnu, kao i osobama koje žele ciljanu negu za više kožnih problema. Pogodan je za one koji žele da testiraju različite aktivne sastojke pre uvođenja u stalnu rutinu. Zašto volimo Tirtir 5 Actives Power Serums Kit? Ovaj set je zamišljen kao funkcionalna kolekcija seruma koji se mogu koristiti pojedinačno ili u kombinaciji, u zavisnosti od potreba kože. SOS Serum pruža brzu hidrataciju i smirenje, dok Niacinamide 20% Serum cilja pore i neujednačen ten. Pure Vitamin C24 Serum fokusiran je na sjaj i elastičnost, dok PHA 15% Serum pomaže u zaglađivanju teksture kože. Azelaic Acid 12% Serum namenjen je balansiranju kože sklone crvenilu i nepravilnostima. Set omogućava postepeno upoznavanje sa jačim aktivima bez potrebe za kupovinom proizvoda u punoj veličini. Namenjen je svesnoj i prilagodljivoj nezi. Posebno je praktičan za promene rutine tokom godine. Aktivni sastojci Polyglutamic Acid i Centella Extract (SOS Serum) Poliglutaminska kiselina je snažan ovlaživač koji pomaže koži da zadrži vlagu. Doprinosi punijem i hidriranijem izgledu kože. Ekstrakt centelle deluje umirujuće i podržava stabilnost kožne barijere. Zajedno pomažu kod dehidrirane i osetljive kože. Serum se brzo upija i ne opterećuje kožu. Pogodan je za svakodnevnu upotrebu. Niacinamide 20% (Niacinamide 20% Serum) Visoka koncentracija niacinamida deluje na vidljivost pora i ujednačavanje tena. Pomaže u regulaciji sebuma i poboljšanju teksture kože. Doprinosi jačanju kožne barijere. U kombinaciji sa drugim sastojcima podržava sjajniji izgled kože. Deluje postepeno i ciljano. Namenjen je iskusnijim korisnicima aktivnih sastojaka. Pure Vitamin C 24% (Pure Vitamin C24 Serum) Čisti vitamin C u visokoj koncentraciji deluje na posvetljivanje tena i elastičnost kože. Pomaže u smanjenju neujednačenog tona i beživotnog izgleda. Podržava sintezu kolagena. Doprinosi zdravijem sjaju kože. Namenjen je kratkotrajnim ili ciljanim kurama. Zahteva pažljivo uklapanje u rutinu. PHA 15% (PHA 15% Serum) PHA kiselina pruža blagu, ali efikasnu eksfolijaciju uz dodatnu hidrataciju. Deluje na zaglađivanje neravne teksture kože. Pogodna je i za osetljiviju kožu u poređenju sa AHA kiselinama. Pomaže u osvežavanju tena. Deluje postepeno bez agresivnog efekta. Namenjena je redovnoj, kontrolisanoj upotrebi. Azelaic Acid 12% (Azelaic Acid 12% Serum) Azelaična kiselina pomaže u balansiranju kože sklone crvenilu i nepravilnostima. Deluje umirujuće i podržava ujednačen izgled tena. U kombinaciji sa cinkom i pantenolom pomaže u regulaciji sebuma. Doprinosi smanjenju vidljivosti tragova nepravilnosti. Pogodna je za problematičnu kožu. Deluje stabilno i dugoročno. Dodaj u listu želja Dodaj u listu želja', 'Tirtir 5 Actives Power Serums Kit je set od pet mini seruma osmišljen da pruži ciljanu negu za različite potrebe kože – od hidratacije i smirivanja, preko posvetljivanja i nege pora, do eksfolijacije i balansiranja sebuma. 5 Actives Power Serums Kit sadrži pet seruma od po 10 ml koji omogućavaju upoznavanje sa različitim aktivnim formulama i njihovo prilagođavanje rutini u skladu sa trenutnim stanjem kože.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Tirtir-5-Actives-Power-Serums-Kit-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
