INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (206, 158, 'Sulwhasoo White Ginseng Radiance Refining Mask Mini', 'sulwhasoo-white-ginseng-radiance-refining-mask-mini', 'Ključne prednosti: Posvetljivanje i ujednačavanje tena: Beli ginseng doprinosi blistavijem i svežijem izgledu kože. Blaga eksfolijacija i zaglađivanje: Uklanja mrtve ćelije kože i poboljšava njenu teksturu bez agresivnog efekta. Hranjenje i hidratacija: Ekstrakt meda pomaže koži da ostane meka, glatka i prijatna na dodir. Kome je namenjen? Namenjen je svim tipovima kože, posebno koži bez sjaja, sa neujednačenom teksturom i znakovima umora. Pogodan je za osobe koje žele blagi piling i posvetljivanje bez agresivnih formulacija. Zašto volimo Sulwhasoo White Ginseng Radiance Refining Mask Mini? Ova maska je osmišljena kao kratki, ali efikasan tretman za kožu kojoj je potrebna obnova sjaja i zaglađivanje. Gelasta tekstura sa finim česticama belog ginsenga omogućava nežnu masažu i uklanjanje površinskih nečistoća. Istovremeno, aktivni biljni sastojci deluju na poboljšanje elastičnosti i opšteg kvaliteta kože. Maska se lako uklapa u rutinu, čak i tokom tuširanja, bez osećaja zatezanja nakon ispiranja. Koža nakon upotrebe deluje mekše, čistije i vidno ujednačenije. Namenjena je redovnoj, ali kontrolisanoj upotrebi. Pogodna je kao dodatni korak za osveženje tena. Aktivni sastojci Panax Ginseng Root Extract i White Ginseng Powder Beli ginseng je tradicionalni biljni sastojak poznat po revitalizujućem delovanju. Pomaže u posvetljivanju tena i poboljšanju njegovog sjaja. Podržava prirodnu obnovu kože. Doprinosi boljoj elastičnosti i čvrstoći. U obliku praha omogućava blagu mehaničku eksfolijaciju. Deluje postepeno i stabilno. Honey Extract Ekstrakt meda pruža koži hranjenje i hidrataciju. Pomaže u omekšavanju i zaglađivanju površine kože. Sprečava osećaj suvoće nakon ispiranja. Doprinosi prijatnom, elastičnom osećaju kože. Podržava prirodnu barijeru kože. Daje koži zdrav i negovan izgled. Dodaj u listu želja Dodaj u listu želja', 'Sulwhasoo White Ginseng Radiance Refining Mask Mini je maska za ispiranje sa dvostrukim dejstvom, formulisana za posvetljivanje tena, poboljšanje teksture kože i podsticanje njene vitalnosti. Radiance Refining Mask Mini kombinuje ekstrakt i prah belog ginsenga sa ekstraktom meda u gelastoj teksturi koja istovremeno deluje kao maska i blagi piling, pružajući koži svež, ujednačen i negovan izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Sulwhasoo-White-Ginseng-Radiance-Refining-Mask-Mini-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
