INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (207, 158, 'Sulwhasoo Overnight Vitalizing Mask Mini', 'sulwhasoo-overnight-vitalizing-mask-mini', 'Ključne prednosti: Dubinska noćna regeneracija: Tokom sna intenzivno hrani kožu i pomaže njen prirodni proces obnove. Jačanje hidratantne barijere: Sprečava gubitak vlage tokom noći i ostavlja kožu mekanom i elastičnom ujutru. Vitalnost i ujednačena tekstura: Doprinosi punijem, zaglađenijem i odmornijem izgledu kože. Kome je namenjen? Namenjen je svim tipovima kože, posebno suvoj, dehidriranoj i umornoj koži kojoj je potrebna dodatna noćna nega. Pogodan je i za kožu koja pokazuje prve znake gubitka vitalnosti i elastičnosti. Zašto volimo Sulwhasoo Overnight Vitalizing Mask Mini? Ova noćna maska je osmišljena kao završni korak večernje rutine, sa fokusom na dugotrajnu negu dok koža miruje. Lagana, ali hranljiva tekstura se lako raspoređuje i ne opterećuje kožu tokom sna. Nutritive RED Elixir&#x2122; kompleks obezbeđuje bogatu nutritivnu podršku i pomaže koži da zadrži optimalan nivo hidratacije. Ekstrakt ginsenga doprinosi osećaju revitalizacije i svežine već nakon prve upotrebe. Redovnom primenom koža deluje odmornije i otpornije. Namenjena je kontinuiranoj noćnoj nezi. Ujutru koža izgleda negovanije i punije. Aktivni sastojci Panax Ginseng Root Extract Ekstrakt korena panaks ginsenga poznat je po svom revitalizujućem delovanju. Pomaže u poboljšanju energije i vitalnosti kože. Doprinosi čvršćem i otpornijem izgledu. Podržava prirodne procese obnove tokom noći. Deluje dugoročno na opšti kvalitet kože. Često se koristi u formulama za anti-age negu. Nutritive RED Elixir&#x2122; (Ziziphus Jujuba Fruit Extract i Punica Granatum Fruit Extract) Ovaj kompleks obezbeđuje bogatu nutritivnu podršku koži. Ekstrakt žižule pomaže u hidrataciji i omekšavanju kože. Ekstrakt nara doprinosi antioksidativnoj zaštiti. Zajedno podržavaju zdrav i ujednačen izgled tena. Pomažu koži da zadrži vlagu tokom noći. Daju koži puniji i svežiji izgled. Dodaj u listu želja Dodaj u listu želja', 'Sulwhasoo Overnight Vitalizing Mask Mini je noćna maska za intenzivnu regeneraciju i negu kože, formulisana sa tradicionalnim korejskim biljnim ekstraktima kako bi koža tokom sna bila nahranjena, hidrirana i vidno revitalizovana. Vitalizing Mask Mini kombinuje ekstrakt korena panaks ginsenga sa Nutritive RED Elixir&#x2122; kompleksom na bazi žižule i nara, pružajući koži energiju, elastičnost i zdrav sjaj do jutra.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Sulwhasoo-Overnight-Vitalizing-Mask-Mini-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
