INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (208, 154, 'SKIN1004 Madagascar Centella Tea-Trica Mild Peeling Gel', 'skin1004-madagascar-centella-tea-trica-mild-peeling-gel', 'Ključne prednosti: Blaga eksfolijacija bez iritacije: Uklanja mrtve ćelije, mitisere i bele tačkice bez narušavanja kožne barijere. Pročišćavanje pora i nepravilnosti: Salicilni derivati pomažu u uklanjanju nečistoća iz pora i sprečavaju njihovo ponovno začepljenje. Hidratacija i umirenje nakon pilinga: Hijaluronska kiselina, pantenol i alantoin sprečavaju isušivanje i osećaj zatezanja. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, kao i koži sklonoj mitiserima, belim tačkicama i neujednačenoj teksturi. Posebno odgovara osobama koje žele blagi piling bez agresivnih kiselina i grubih čestica. Zašto volimo SKIN1004 Madagascar Centella Tea-Trica Mild Peeling Gel? Ovaj piling gel je osmišljen kao kombinacija mehaničke i hemijske eksfolijacije prilagođene svakodnevnoj koži, a ne agresivnim tretmanima. Celuloza fizički uklanja površinske nečistoće, dok salicilni derivati deluju unutar pora. Tea-Trica kompleks sa čajevcem doprinosi održavanju čiste i uravnotežene kože. Glukonolakton i jantarna kiselina osvežavaju ten i poboljšavaju njegovu ujednačenost. Formula se lako ispira i ne ostavlja osećaj težine ili zatezanja. Koža nakon upotrebe deluje glađe, čistije i vidno smirenije. Namenjen je redovnoj, kontrolisanoj eksfolijaciji. Aktivni sastojci Ekstrakt lista čajevca Ekstrakt lista čajevca pomaže u održavanju čiste kože i balansu lučenja sebuma. Ima blago pročišćavajuće delovanje bez isušivanja. Podržava kožu sklonu nepravilnostima. Deluje umirujuće kod iritacija. Doprinosi svežijem izgledu tena. Pogodan je i za osetljive tipove kože. Celuloza Celuloza omogućava mehaničko uklanjanje mrtvih ćelija kože bez grebanja. Deluje nežno i kontrolisano. Pomaže u zaglađivanju površine kože. Poboljšava ujednačenost teksture. Ne narušava kožnu barijeru. Pogodna je za redovnu upotrebu. Salicilna kiselina Ovi sastojci deluju unutar pora i pomažu u uklanjanju mitisera i belih tačkica. Podržavaju čistiji izgled kože. Deluju ciljano, ali blago. Smanjuju sklonost ka začepljenju pora. Pogodni su za problematičnu kožu. Ne ostavljaju kožu isušenom. Glukonolakton i sukcinska kiselina Glukonolakton kao PHA kiselina pruža blagu eksfolijaciju pogodnu za osetljivu kožu. Jantarna kiselina doprinosi osvežavanju i revitalizaciji tena. Zajedno poboljšavaju teksturu kože. Deluju postepeno i stabilno. Podržavaju zdrav izgled kože. Ne izazivaju agresivne reakcije. Hijaluronska kiselina Ovi sastojci obezbeđuju hidrataciju i umirenje nakon pilinga. Smanjuju rizik od iritacije. Podržavaju obnovu kožne barijere. Održavaju elastičnost i mekoću kože. Sprečavaju osećaj zatezanja. Čine završni efekat prijatnim i balansiranim. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Tea-Trica Mild Peeling Gel je blagi piling-gel namenjen uklanjanju mitisera, belih tačkica i mrtvih ćelija kože, uz istovremenu hidrataciju i umirujuće delovanje. Tea-Trica Mild Peeling Gel kombinuje mehaničku i hemijsku eksfolijaciju uz sastojke koji smiruju kožu i čine ga pogodnim i za osetljive tipove.', 'https://beauty-health.rs/wp-content/uploads/2025/12/SKIN1004-Madagascar-Centella-Tea-Trica-Mild-Peeling-Gel-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
