INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (210, 146, 'S.NATURE Aqua Squalane Serum', 's-nature-aqua-squalane-serum', 'Ključne prednosti: Intenzivna hidratacija i zaštita od isušivanja: Skvalan i osam vrsta hijaluronske kiseline obnavljaju nivo vlage i sprečavaju gubitak hidratacije. Umirivanje i jačanje kožne barijere: Pantenol i alantoin pomažu u smanjenju iritacija i jačanju otpornosti kože. Balansiranje pora i sebuma: Ekstrakt hamamelisa doprinosi sužavanju pora i kontroli prekomernog sjaja. Kome je namenjen? Namenjen je suvoj, dehidriranoj i osetljivoj koži, kao i koži sklonoj iritacijama i disbalansu sebuma. Odgovara i mešovitoj koži kojoj je potrebna hidratacija bez težine. Zašto volimo S.NATURE Aqua Squalane Serum? Ovaj serum ima bogatu, ali laganu teksturu koja se brzo upija i ne ostavlja mastan trag. Skvalan pomaže u obnavljanju lipidne barijere kože i održavanju njene mekoće. Višeslojna hijaluronska hidratacija deluje na različitim nivoima epidermisa, pružajući dugotrajan osećaj komfora. Betaine dodatno podržava zadržavanje vlage i štiti kožu od dehidratacije. Umirujući sastojci smanjuju reakcije izazvane spoljašnjim faktorima, čineći serum pogodnim za svakodnevnu upotrebu. Formula je blaga i dizajnirana da odgovara i osetljivoj koži. Ovo je obnovljena verzija proizvoda sa unapređenim pakovanjem, dok je formula ostala ista. Aktivni sastojci Skvalan Skvalan je lipid sličan prirodnim uljima kože. Pomaže u obnavljanju zaštitne barijere i sprečava gubitak vlage. Čini kožu mekom i elastičnom. Ne zapušava pore i dobro se podnosi. Doprinosi zdravom izgledu tena. Pogodan je za sve tipove kože. Hijaluronska kiselina (8 vrsta) Različite molekulske mase omogućavaju hidrataciju na više nivoa. Pomažu koži da zadrži vlagu tokom dana. Smanjuju osećaj zatezanja. Doprinosе punoći i glatkoći. Podržavaju elastičnost kože. Osnovni su element dugotrajne hidratacije. Betaine Betaine deluje kao ovlaživač i zaštitni sastojak. Pomaže u sprečavanju dehidratacije. Poboljšava toleranciju kože na spoljašnje uticaje. Doprinosi mekoći kože. Podržava hidratacioni balans. Pogodan je za osetljivu kožu. Panthenol Panthenol umiruje kožu i jača barijernu funkciju. Pomaže u smanjenju crvenila i nelagodnosti. Podržava regeneraciju kože. Doprinosi boljem zadržavanju vlage. Poboljšava opšti komfor kože. Često se koristi u formulama za osetljivu kožu. Allantoin Allantoin ima umirujuće i zaštitno dejstvo. Pomaže u smanjenju iritacija. Podržava obnovu kože. Doprinosi glatkoći teksture. Čini kožu otpornijom. Pogodan je za svakodnevnu upotrebu. Ekstrakt hamamelisa (Witch Hazel) Hamamelis pomaže u sužavanju pora i kontroli sebuma. Ima blago adstringentno dejstvo. Doprinosi uravnoteženom izgledu kože. Umiruje kožu sklonu reakcijama. Pomaže u održavanju svežeg tena. Koristan je za mešovitu i masniju kožu. Dodaj u listu želja Dodaj u listu želja', 'S.NATURE Aqua Squalane Serum je hidrirajući i umirujući serum namenjen obnavljanju vlažnosti kože i jačanju njenog zaštitnog sloja. Aqua Squalane Serum kombinuje skvalan, višeslojnu hijaluronsku hidrataciju i umirujuće sastojke kako bi koža ostala elastična, uravnotežena i zaštićena od svakodnevnih iritacija, bez osećaja težine ili lepljivosti.', 'https://beauty-health.rs/wp-content/uploads/2025/12/S.NATURE-Aqua-Squalane-Serum-1.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
