INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (212, 142, 'Rohto Mentholatum 50 Megumi Lifting Face Cream', 'rohto-mentholatum-50-megumi-lifting-face-cream', 'Ključne prednosti: Vidljivo zaglađivanje finih linija i bora: Kombinacija kolagena, hijaluronske kiseline i vitamina deluje na bore nastale usled suvoće. Poboljšanje čvrstoće i elastičnosti: „Baby collagen“ i lifting sastojci doprinose punijem i zategnutijem izgledu kože. Dugotrajna hidratacija i komfor: Formula zaključava vlagu i sprečava osećaj zatezanja tokom dana. Kome je namenjen? Namenjena je suvoj, normalnoj i zreloj koži, kao i koži koja pokazuje znake gubitka elastičnosti, suvoće i finih linija. Posebno odgovara osobama koje žele intenzivnu hidrataciju i osećaj zategnutije, punije kože. Zašto volimo Rohto Mentholatum 50 Megumi Lifting Face Cream? Ova krema je osmišljena kao višenamenski proizvod koji objedinjuje funkciju seruma, kreme i maske u jednom koraku. Tekstura je bogata i hranljiva, ali se lako razmazuje i ne ostavlja lepljiv osećaj na koži. Zahvaljujući visokom udelu hidratantnih sastojaka, koža ostaje meka i glatka tokom dužeg vremenskog perioda. Kolagenski kompleks deluje pre svega na poboljšanje površinske teksture i osećaj punoće kože. Koenzim Q10 i vitamini pružaju antioksidativnu podršku i doprinose zdravijem izgledu tena. Krema je pogodna za redovnu upotrebu ujutru i uveče. Formula ne sadrži veštačke mirise, boje, mineralna ulja ni alkohol. Aktivni sastojci Kolagenski kompleks (3 vrste kolagena) Hidrolizovani kolagen, vodorastvorni kolagen i sukcinoil atelokolagen deluju kao snažni ovlaživači. Pomažu u zadržavanju vlage na površini kože. Doprinosе punijem i zaglađenijem izgledu. „Baby collagen“ tipa III podržava elastičnost koja se s godinama smanjuje. Deluju pre svega na poboljšanje teksture. Imaju ključnu ulogu u hidrataciji i komforu kože. Hijaluronska kiselina (natrijum hijaluronat) Hijaluronska kiselina vezuje vlagu i sprečava dehidrataciju. Pomaže u smanjenju finih linija izazvanih suvoćom. Doprinosi elastičnijem i glatkijem izgledu kože. Deluje brzo i efikasno. Održava kožu mekanom i punom. Pogodna je za svakodnevnu upotrebu. Koenzim Q10 (ubihinon) Koenzim Q10 je snažan antioksidans koji podržava energiju ćelija. Pomaže u zaštiti kože od oksidativnog stresa. Doprinosi čvršćem i zdravijem izgledu kože. Ima ulogu u prevenciji preranog starenja. Podržava regeneraciju kože. Deluje stabilno i dugoročno. Vitamin A Vitamin A doprinosi obnovi površinskog sloja kože. Pomaže u zaglađivanju fine teksture. Podržava ujednačeniji izgled kože. Deluje blago i kontrolisano u ovoj formuli. Ima ulogu u anti-age nezi. Pogodan je za svakodnevnu primenu. Vitamin E Vitamin E je antioksidans koji pomaže u zaštiti kože od spoljašnjih uticaja. Doprinosi očuvanju vlažnosti i mekoće. Deluje umirujuće na suvu kožu. Podržava barijernu funkciju. Pomaže u očuvanju elastičnosti. Ima potporni efekat u nezi zrele kože. Dodaj u listu želja Dodaj u listu želja', 'Rohto Mentholatum 50 Megumi Lifting Face Cream je bogata lifting krema namenjena smanjenju znakova starenja izazvanih suvoćom, gubitkom elastičnosti i opuštanjem kože. 50 Megumi Lifting Face Cream kombinuje čak 50 hidratantnih sastojaka, uključujući tri vrste kolagena, hijaluronsku kiselinu, koenzim Q10, vitamine A i E, kako bi koži pružila dugotrajnu hidrataciju, puniji izgled i vidljivo zaglađene fine linije.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Rohto-Mentholatum-50-Megumi-Lifting-Face-Cream-.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
