INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (216, 127, 'O.TWO.O Zero Pores Makeup Primer', 'o-two-o-zero-pores-makeup-primer', 'Ključne prednosti: Vizuelno smanjenje pora: Ublažava izgled proširenih pora i čini površinu kože ujednačenijom. Zaglađivanje fine teksture: Pomaže u omekšavanju sitnih linija i nepravilnosti pre šminke. Kontrola sjaja i sebuma: Doprinosi mat završnici i smanjuje prosijavanje tokom dana. Kome je namenjen? Namenjen je svim tipovima kože, posebno masnoj i kombinovanoj, kao i koži sa vidljivim porama i izraženim sjajem. Pogodan je za osobe koje žele dugotrajniju i ujednačeniju šminku sa mat efektom. Zašto volimo O.TWO.O Zero Pores Makeup Primer? Ovaj prajmer je formulisan kao pripremni korak koji poboljšava način na koji se šminka ponaša na koži. Njegova tekstura se lako razmazuje i brzo stapa sa kožom, bez osećaja težine ili lepljivosti. Nakon nanošenja, koža deluje glađe i ujednačenije, što omogućava ravnomernije nanošenje pudera ili BB kreme. Deluje pre svega vizuelno, fokusirajući se na izgled pora i teksture. Pomaže da se šminka duže zadrži na mestu, posebno kod masnije ili kombinovane kože. Namenjen je svakodnevnoj upotrebi pre make-upa. Ne menja boju tena i lako se uklapa u različite rutine šminkanja. Aktivni sastojci Sebum-kontrolni kompleks Sastojci za kontrolu sebuma pomažu u smanjenju prosijavanja tokom dana. Deluju tako što apsorbuju višak masnoće sa površine kože. Doprinosе matiranom finišu. Pomažu da šminka duže ostane postojana. Smanjuju potrebu za čestim popravljanjem. Imaju ključnu ulogu kod masnije kože. Zaglađujući polimeri Zaglađujući polimeri formiraju tanak, ujednačen sloj na koži. Vizuelno ublažavaju pore i fine linije. Pomažu ravnomernije nanošenje pudera. Daju koži glatki osećaj na dodir. Ne opterećuju kožu. Imaju estetsku, ali vrlo funkcionalnu ulogu. Dodaj u listu želja Dodaj u listu želja', 'O.TWO.O Zero Pores Makeup Primer je prajmer namenjen vizuelnom smanjenju pora, zaglađivanju teksture kože i kontroli sjaja pre nanošenja šminke. Zero Pores Makeup Primer deluje tako što stvara ujednačenu, glatku podlogu koja pomaže da puder izgleda postojanije, ravnomernije i matirano tokom dana.', 'https://beauty-health.rs/wp-content/uploads/2025/12/O.TWO_.O-Zero-Pores-Makeup-Primer-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
