INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (219, 123, 'Neogen Surmedic Azulene Soothing Peptide Ampoule', 'neogen-surmedic-azulene-soothing-peptide-ampoule', 'Ključne prednosti: Trenutno umirivanje i smanjenje crvenila: Visoko koncentrovani azulen deluje protiv iritacija i vraća koži osećaj komfora. Jačanje barijere i elastičnosti: Peptidi i ceramidi podržavaju otpornost kože i njen zdraviji izgled. Zaštita i revitalizacija kože: Centella asiatica kompleks pomaže koži da se lakše nosi sa spoljašnjim stresorima. Kome je namenjen? Namenjena je svim tipovima kože, posebno osetljivoj, reaktivnoj i dehidriranoj koži, kao i koži sklonoj crvenilu i iritacijama. Pogodna je za umornu kožu izloženu spoljašnjim uticajima poput zagađenja i klimatskih promena. Zašto volimo Neogen Surmedic Azulene Soothing Peptide Ampoule? Ampula je formulisana kao ciljano rešenje za kožu koja je pod stresom, reaktivna ili sklona crvenilu. Plave kapsule sa azulenom se razgrađuju tokom nanošenja, omogućavajući ravnomernu raspodelu aktivnih sastojaka. Peptidni kompleks deluje postepeno na poboljšanje strukture i elastičnosti kože, dok ceramidi pomažu u očuvanju barijerne funkcije. Centella asiatica sastojci dodatno smiruju i podržavaju regeneraciju. Tekstura je lagana, ali hranljiva, i brzo se upija bez lepljivog osećaja. Ampula je namenjena svakodnevnoj upotrebi, posebno u periodima kada je koži potrebna dodatna stabilnost. Fokusirana je na dugoročno poboljšanje otpornosti i ravnoteže kože. Aktivni sastojci Azulen Azulen je aktivni sastojak poznat po snažnom umirujućem delovanju. Pomaže u smanjenju crvenila i iritacija. Deluje protivupalno i stabilizujuće. Posebno je koristan za osetljivu i reaktivnu kožu. Doprinosi osećaju smirenosti i komfora. Ima ključnu ulogu u ovoj ampuli. Peptidi (10 vrsta) Peptidi su signalni molekuli koji podržavaju prirodne procese obnove kože. Doprinosе poboljšanju elastičnosti i čvrstoće. Pomažu u jačanju kožne barijere. Deluju postepeno i bez iritacije. Pogodni su za dugoročnu negu. Imaju potporni anti-age efekat. Ceramidi Ceramidi su lipidi prirodno prisutni u koži. Pomažu u obnavljanju i jačanju zaštitne barijere. Smanjuju gubitak vlage. Doprinosе otpornijoj i hidriranoj koži. Umiruju osećaj zategnutosti. Posebno su važni kod osetljive kože. Centella asiatica kompleks (5 sastojaka) Kompleks sastojaka iz Centella asiatica deluje umirujuće i regenerativno. Pomaže u smanjenju crvenila i nelagodnosti. Podržava obnovu kože. Jača otpornost kože na spoljašnje uticaje. Doprinosi ravnoteži kože. Pogodan je za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Neogen Surmedic Azulene Soothing Peptide Ampoule je umirujuća i regenerativna ampula namenjena smanjenju iritacija, jačanju kožne barijere i vraćanju ravnoteže umornoj i osetljivoj koži. Peptide Ampoule kombinuje visoku koncentraciju azulena, deset vrsta peptida, ceramide i kompleks sastojaka iz Centella asiatica kako bi kožu intenzivno umirila, hidrirala i zaštitila od spoljašnjih agresora.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Neogen-Surmedic-Azulene-Soothing-Peptide-Ampoule-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
