INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (221, 123, 'Neogen Dermalogy High R Exosome Cream', 'neogen-dermalogy-high-r-exosome-cream', 'Ključne prednosti: Jačanje kožne barijere i otpornosti: Resveratrol i egzozomi iz centelle pomažu koži da se bolje brani od spoljašnjih stresora. Umirenje i zaglađivanje teksture: Cica-egzozomi deluju na iritacije i grubu teksturu, čineći kožu mekšom i ujednačenijom. Dubinska i višeslojna hidratacija: Osam tipova hijaluronske kiseline obezbeđuje dugotrajnu hidrataciju bez lepljivog osećaja. Kome je namenjena? Namenjena je svim tipovima kože, uključujući osetljivu, dehidriranu i kožu sa oslabljenom barijerom. Posebno odgovara koži sklonoj iritacijama, neujednačenoj teksturi i gubitku elastičnosti. Zašto volimo Neogen Dermalogy High R Exosome Cream? Krema je formulisana kao „all-in-one“ rešenje za svakodnevnu negu kože kojoj je potrebna stabilnost, hidratacija i obnova. Lagana tekstura se brzo upija i ne ostavlja mastan ili lepljiv film, što je čini pogodnom za različite tipove kože i različite rutine. Egzozomi iz centelle ciljano deluju na smirivanje i obnovu kože, dok resveratrol doprinosi jačanju barijerne funkcije. Voluform i peptidi podržavaju elastičnost i poboljšavaju izgled kože tokom vremena. Hijaluronska kiselina u više molekulskih težina omogućava hidrataciju i površinskih i dubljih slojeva kože. Formula je osmišljena za svakodnevnu upotrebu bez opterećenja. Fokusirana je na dugoročno poboljšanje otpornosti i kvaliteta kože. Aktivni sastojci Egzozomi iz Centella asiatica Egzozomi poreklom iz centelle su napredni sastojci koji prenose signalne molekule koži. Doprinosе umirivanju iritacija i obnovi kože. Podržavaju prirodne procese regeneracije. Pomažu u zaglađivanju grube teksture. Deluju stabilizujuće na osetljivu kožu. Imaju ključnu ulogu u jačanju kvaliteta kože. Resveratrol Resveratrol je snažan antioksidans koji pomaže u zaštiti kože od spoljašnjih agresora. Doprinosi jačanju kožne barijere. Podržava otpornost i elastičnost kože. Deluje preventivno protiv oksidativnog stresa. Poboljšava ukupni izgled kože. Pogodan je za dugoročnu svakodnevnu upotrebu. Voluform Voluform je sastojak namenjen poboljšanju tona i teksture kože. Doprinosi punijem i ujednačenijem izgledu. Podržava elastičnost kože. Deluje postepeno i stabilno. Ne izaziva iritacije. Ima potporni efekat u anti-age nezi. Peptidi (SYN-AKE, SYN-COLL, SYN-STAR) Ovi peptidi deluju sinergijski na poboljšanje elastičnosti i čvrstoće kože. Podržavaju zaglađivanje finih linija. Doprinosе vitalnijem izgledu kože. Deluju postepeno bez agresivnih reakcija. Pogodni su za osetljivu kožu. Imaju dugoročnu potporu u anti-age rutini. Hijaluronska kiselina (8 tipova) Osam tipova hijaluronske kiseline različitih molekulskih težina omogućava višeslojnu hidrataciju. Vezuje vlagu i zadržava je u koži. Smanjuje suvoću i osećaj zategnutosti. Poboljšava elastičnost i glatkoću. Deluje brzo i dugotrajno. Ključna je za svakodnevnu hidrataciju. Dodaj u listu želja Dodaj u listu želja', 'Neogen Dermalogy High R Exosome Cream je lagana, ali funkcionalna hidratantna krema namenjena jačanju kožne barijere, umirivanju iritacija i poboljšanju ukupnog kvaliteta kože. Dermalogy High R Exosome Cream kombinuje egzozome poreklom iz centelle, resveratrol, Voluform, peptide i osam tipova hijaluronske kiseline kako bi koži pružila ravnotežu, otpornost i ujednačeniji, blistav izgled bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Neogen-Dermalogy-High-R-Exosome-Cream.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
