INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (226, 115, 'Meditherapy Retinal Skin Booster Serum', 'meditherapy-retinal-skin-booster-serum', 'Ključne prednosti: Vidljivo zaglađivanje bora i finih linija: Retinal podstiče sintezu kolagena i doprinosi ujednačenijoj teksturi kože. Jačanje kožne barijere: Cica Biome i probiotički derivati iz centelle pomažu u stabilizaciji i otpornosti kože. Umirujuće delovanje uz visoku toleranciju: Formula je prilagođena osetljivoj i problematičnoj koži, bez iritacija i zapušavanja pora. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i aknama sklonu, kao i koži sa prvim znacima starenja. Posebno je pogodan za osobe koje žele da uvedu retinal u rutinu na blag i kontrolisan način. Zašto volimo Meditherapy Retinal Skin Booster Serum? Serum je osmišljen kao „skin booster“ koji deluje na više aspekata kvaliteta kože istovremeno. Retinal u liposomskoj formi omogućava stabilnije i kontrolisanije oslobađanje aktivnog sastojka, čime se smanjuje rizik od iritacije. Deluje efikasnije od retinola uz manju potrebu za višestepenom konverzijom u koži. Cica Biome kompleks podržava mikrobiom kože i doprinosi njenoj ravnoteži. Tekstura je lagana i brzo se upija, bez masnog ili lepljivog osećaja. Serum ne opterećuje kožu i ne doprinosi pojavi komedona. Namenjen je dugoročnoj upotrebi radi postepenog poboljšanja elastičnosti i ukupnog izgleda kože. Aktivni sastojci Retinal (liposomski oblik) Retinal je direktni prethodnik retinoične kiseline i deluje efikasnije od retinola uz bržu biološku aktivaciju u koži. U liposomskom obliku omogućava stabilnije i postepeno oslobađanje, čime se smanjuje rizik od iritacije. Podstiče proizvodnju kolagena i ubrzava obnavljanje ćelija. Doprinosi smanjenju bora i finih linija. Poboljšava teksturu i tonus kože. Namenjen je kontrolisanom, dugoročnom anti-age delovanju. Cica Biome kompleks Cica Biome predstavlja kombinaciju sastojaka koji podržavaju ravnotežu kožnog mikrobioma. Doprinosi jačanju barijerne funkcije kože. Pomaže u smanjenju osetljivosti i reaktivnosti. Podržava oporavak kože tokom aktivnih tretmana. Deluje umirujuće i stabilizujuće. Posebno je značajan u formulama sa aktivnim sastojcima poput retinala. Probiotici poreklom iz centelle Probiotički derivati iz centelle podržavaju zdravlje i otpornost kože. Doprinosе smanjenju crvenila i nelagodnosti. Jačaju prirodne odbrambene mehanizme kože. Pomažu u očuvanju hidratacije i barijere. Deluju balansirajuće na problematičnu kožu. Pogodni su za osetljive tipove kože. Centella asiatica derivati Derivati centelle poznati su po svom umirujućem i regenerativnom delovanju. Podržavaju obnovu kože i smanjuju iritacije. Doprinosе jačanju kožne barijere. Pomažu koži da bolje toleriše aktivne sastojke. Deluju blago, ali stabilno. Imaju potporni efekat u anti-age formulama. Dodaj u listu želja Dodaj u listu želja', 'Meditherapy Retinal Skin Booster Serum je serum sa retinalom namenjen poboljšanju teksture kože, smanjenju finih linija i jačanju kožne barijere, uz istovremeno umirujuće delovanje. Skin Booster Serum kombinuje retinal u liposomskom obliku sa Cica Biome kompleksom i probioticima poreklom iz centelle kako bi pružio anti-age efekte uz visoku toleranciju, čak i kod osetljive i aknama sklone kože.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Meditherapy-Retinal-Skin-Booster-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
