INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (227, 113, 'Medi-Peel Eazy Filler Cream', 'medi-peel-eazy-filler-cream', 'Ključne prednosti: Poboljšanje čvrstoće i elastičnosti: Peptidni kompleksi i faktori rasta podržavaju sintezu kolagena i elastina. Smanjenje vidljivosti bora: Argirelin i bakarni peptidi deluju na mimičke i statične bore, zaglađujući mikroreljef kože. Intenzivna hidratacija i zaštita barijere: Hijaluronska kiselina, glikozaminoglikani i biljni kompleksi sprečavaju suvoću i osećaj zategnutosti. Kome je namenjena? Namenjen je normalnoj, kombinovanoj i suvoj koži, posebno koži sa vidljivim borama, gubitkom elastičnosti i suvoćom. Pogodan je za osobe koje žele intenzivniju anti-age negu i učvršćujući efekat u svakodnevnoj rutini. Zašto volimo Medi-Peel Eazy Filler Cream? Krema ima gustu, hranljivu teksturu koja se ravnomerno raspoređuje po koži i pruža dugotrajan osećaj komfora. Deluje kao vizuelni filer, zaglađujući površinu kože i čineći je punijom i mekšom na dodir. Peptidni kompleksi ciljano deluju na gubitak tonusa i elastičnosti, dok faktori rasta podržavaju prirodne procese obnove kože. Glukonolakton omogućava blagu eksfolijaciju bez iritacije, doprinoseći ujednačenijem mikroreljefu. Biljni i fermentisani kompleksi dodatno štite kožu od dehidratacije i spoljašnjih stresora. Redovnom upotrebom koža deluje zategnutije, glađe i zdravijeg sjaja. Formula je osmišljena za dugoročnu negu i očuvanje kvaliteta kože. Aktivni sastojci Matrixyl®3000 (Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7) Matrixyl®3000 je peptidni kompleks matrikina koji stimuliše proizvodnju sopstvenog kolagena u koži. Deluje na poboljšanje čvrstoće i elastičnosti. Doprinosi smanjenju dubine bora i zaglađivanju teksture. Podržava regeneraciju kože tokom vremena. Njegovo dejstvo je postepeno i stabilno. Posebno je koristan kod zrele kože. Copper Tripeptide-1 Bakarni peptid ima snažno regenerativno i anti-age delovanje. Pomaže u poboljšanju čvrstoće i elastičnosti kože. Deluje antiinflamatorno i podržava zdravlje ćelija. Učestvuje u procesima obnove oštećene kože. Doprinosi zaglađivanju površine kože. Pogodan je za dugoročnu negu. Argirelin (Acetyl Hexapeptide-8) Argirelin je peptid poznat po efektu relaksacije mimičkih mišića. Pomaže u smanjenju vidljivosti mimičkih bora. Sprečava njihovo dalje produbljivanje. Deluje lokalno i neinvazivno. Njegovo dejstvo je postepeno. Koristan je za područje čela i oko očiju. EGF kompleks (Oligopeptide-32, Oligopeptide-29, Rice sh-Oligopeptide-1) EGF peptidi stimulišu rast i obnovu ćelija kože. Podržavaju proizvodnju kolagena i elastina. Doprinosе zategnutijem i glađem izgledu kože. Deluju regenerativno i jačaju strukturu kože. Biljni faktor rasta iz pirinča dodatno smiruje kožu. Njihovo dejstvo je dugoročno. Glukonolakton Glukonolakton je PHA kiselina sa velikim molekulima, pogodna za osetljivu kožu. Omogućava blagu eksfolijaciju bez iritacije. Uklanja odumrle ćelije i ujednačava mikroreljef. Doprinosi svetlijem i svežijem izgledu kože. Ne narušava kožnu barijeru. Pogodan je za redovnu upotrebu. RiFerm® kompleks RiFerm® je fermentisani kompleks na bazi saharomiceta. Intenzivno hidrira kožu i poboljšava njen reljef. Doprinosi smanjenju vidljivosti bora. Povećava elastičnost kože. Podržava zdrav izgled tena. Deluje umirujuće i balansirajuće. Blue Complex Blue Complex je biljni kompleks lavande, različka, kamilice, giacinta, boraga i žalfije. Pruža antioksidativnu zaštitu. Umiruje i hidrira kožu. Sprečava perutanje i suvoću. Doprinosi osećaju komfora. Pogodan je za osetljivu kožu. Hijaluronska kiselina (5 tipova) Više tipova hijaluronske kiseline omogućava hidrataciju različitih slojeva kože. Vezuje vlagu i zadržava je u epidermisu. Smanjuje osećaj zategnutosti. Poboljšava elastičnost i gipkost kože. Doprinosi punijem izgledu. Ključna je za svakodnevnu hidrataciju. Hidrolizovani glikozaminoglikani Glikozaminoglikani su deo prirodne zaštitne barijere kože. Pomažu u obnovi oštećenja. Smanjuju suvoću i iritacije. Podržavaju hidrat', 'Medi-Peel Eazy Filler Cream je učvršćujuća krema-filer namenjena poboljšanju elastičnosti, čvrstoće i gustine kože, sa fokusom na smanjenje vidljivosti bora i usporavanje starosnih promena u predelu čela, oko očiju i nazolabijalnih nabora. Filler Cream kombinuje višestruke peptidne komplekse, faktore rasta, PHA kiselinu, hijaluronsku kiselinu u više oblika i regenerativne lipide kako bi koža bila glađa, elastičnija i vidljivo revitalizovana.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Medi-Peel-Eazy-Filler-Cream-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
