INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (228, 111, 'Mary & May Spicule Collagen PDRN Cream', 'mary-may-spicule-collagen-pdrn-cream', 'Ključne prednosti: Poboljšanje elastičnosti i čvrstoće: Kombinacija kolagena i peptidnih mehanizama pomaže koži da izgleda zategnutije i punije. Podsticanje obnove kože: Spikule omogućavaju efikasniju isporuku aktivnih sastojaka i podržavaju prirodne procese regeneracije. Umirenje i jačanje barijere: Pantenol i PDRN iz centelle pomažu u smanjenju iritacija i jačanju zaštitne funkcije kože. Kome je namenjena? Namenjen je svim tipovima kože, uključujući osetljivu, posebno koži sa smanjenom elastičnošću, umornim izgledom i narušenom barijernom funkcijom. Pogodan je za zrelu kožu, ali i za mlađe osobe koje žele preventivnu negu i poboljšanje teksture. Zašto volimo Mary & May Spicule Collagen PDRN Cream? Zato što kombinuje regenerativne i umirujuće sastojke u jasno definisanoj, funkcionalnoj formuli. Spikule omogućavaju da aktivni sastojci imaju realan efekat bez agresivnog pristupa. Krema pruža osećaj obnovljene, otpornije kože bez preopterećenja. Posebno je pogodna kao noćna nega ili periodični intenzivni tretman. Ne sadrži mirise i lako se uklapa u rutine osetljive kože. Fokusirana je na dugoročno poboljšanje kvaliteta kože, a ne na kratkotrajni efekat. Aktivni sastojci Spikule (1000 ppm) Spikule su mikroskopske igličaste strukture koje deluju kao mehanički nosači aktivnih sastojaka. One omogućavaju njihovu ravnomerniju distribuciju u površinskim slojevima kože. Njihovo delovanje je kontrolisano i usmereno na podsticanje obnove kože. Spikule mogu doprineti poboljšanju teksture i glatkoće. Deluju bez agresivnog oštećenja kože. Njihova uloga je funkcionalna i potporna u celokupnoj formuli. Kolagen (3000 ppm) Kolagen je ključni strukturni protein kože koji doprinosi njenoj čvrstoći. U topikalnim formulama pomaže u zadržavanju vlage i zaglađivanju površine kože. Doprinosi punijem i elastičnijem izgledu. Njegovo dejstvo je vizuelno i hidratantno. Posebno je koristan kod kože sa smanjenim tonusom. U ovoj kremi ima ulogu potpore elastičnosti. PDRN iz centelle PDRN je sastojak poznat po svojoj ulozi u procesima obnove kože. Dobijen iz centelle, dodatno doprinosi umirujućem efektu. Podržava regeneraciju i poboljšanje kvaliteta kože. Pomaže kod oslabljene barijere. Deluje postepeno i stabilno. Posebno je pogodan za osetljivu i reaktivnu kožu. Pantenol (2%) Pantenol je provitamin B5 koji pomaže u smanjenju iritacija i jačanju kožne barijere. Doprinosi hidrataciji i elastičnosti kože. Umiruje kožu tokom regenerativnih procesa. Poboljšava osećaj komfora. Pogodan je za svakodnevnu upotrebu. Njegova uloga je stabilizujuća i zaštitna. Centella asiatica Centella asiatica je poznata po umirujućem i balansirajućem delovanju. Pomaže u smanjenju crvenila i nelagodnosti. Podržava obnovu kože. Doprinosi jačanju barijere. Pogodna je za osetljivu kožu. U formuli ima potporni i zaštitni efekat. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Spicule Collagen PDRN Cream je ciljana regenerativna krema namenjena poboljšanju čvrstoće, elastičnosti i teksture kože, sa fokusom na obnavljanje oslabljenog i umornog tena. Collagen PDRN Cream kombinuje mikroskopske spikule, kolagen visoke koncentracije, PDRN iz centelle, pantenol i umirujuće sastojke kako bi koža postala otpornija, zaglađenija i vidljivo svežija.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Mary-May-Spicule-Collagen-PDRN-Cream-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
