INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (234, 104, 'Laneige Bouncy & Firm Eye Sleeping Mask', 'laneige-bouncy-firm-eye-sleeping-mask', 'Ključne prednosti: Smanjenje otoka i umornog izgleda: Kofein pomaže u hlađenju kože i ublažavanju natečenosti ispod očiju. Poboljšana čvrstina i elastičnost: Kompleks božura, kolagena i peptida doprinosi zategnutijem izgledu i smanjenju finih linija. Lagano hlađenje bez lepljivosti: Gelasta tekstura pruža osvežavajući osećaj i brzo se upija. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, posebno osobama koje imaju problem sa jutarnjim otocima, umornim izgledom očiju i gubitkom čvrstine u regiji oko očiju. Pogodan je i za one koji žele preventivnu anti-age negu ovog područja. Zašto volimo Laneige Bouncy & Firm Eye Sleeping Mask? Zato što deluje dok spavaš. Tekstura je lagana, rashlađujuća i izuzetno prijatna za večernju rutinu. Ne ostavlja mastan ni lepljiv osećaj. Koža oko očiju ujutru izgleda zaglađenije i svežije. Formula je fokusirana na realne potrebe ovog osetljivog područja. Idealan je kao poslednji korak večernje nege. Aktivni sastojci Kofein Kofein pomaže u smanjenju natečenosti i umornog izgleda oko očiju. Deluje blago drenirajuće. Doprinosi osveženju kože tokom noći. Pomaže u vizuelnom ublažavanju tamnih podočnjaka. Ima rashlađujući efekat. Pogodan je za svakodnevnu noćnu upotrebu. Peony & Collagen Complex&#x2122; Ovaj kompleks kombinuje kolagen, ekstrakt božura i peptide. Podržava elastičnost i čvrstinu kože. Doprinosi zaglađivanju finih linija. Poboljšava hidriranost osetljive regije oko očiju. Deluje postepeno i stabilno. Namenjen je dugoročnoj nezi. Kolagen Kolagen doprinosi elastičnijem i punijem izgledu kože. Pomaže u ublažavanju sitnih bora. Podržava strukturu kože tokom noćne regeneracije. Daje koži mekši i zaglađeniji izgled. Njegovo dejstvo je vizuelno i potporno. Posebno je koristan kod umorne kože. Peptidi Peptidi pomažu u održavanju čvrstine kože. Podržavaju prirodne procese obnove. Doprinosе ujednačenijem izgledu. Deluju sinergijski sa kolagenom. Pogodni su za osetljivu regiju oko očiju. Imaju stabilno, dugoročno dejstvo. Dodaj u listu želja Dodaj u listu želja', 'Laneige Bouncy & Firm Eye Sleeping Mask je noćna maska za područje oko očiju namenjena smanjenju otoka, zaglađivanju finih linija i poboljšanju čvrstine kože tokom sna. Bouncy & Firm Eye Sleeping Mask kombinuje kofein sa Peony & Collagen Complex&#x2122; kako bi se koža oko očiju hidrirala, osvežila i izgledala odmornije i zategnutije već narednog jutra.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Laneige-Bouncy-Firm-Eye-Sleeping-Mask-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
