INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (235, 92, 'K-SECRET Advanced Shot Retinal Liposome 12% + Black Rice', 'k-secret-advanced-shot-retinal-liposome-12-black-rice', 'Ključne prednosti: Intenzivna anti-age korekcija: Deluje na bore, gubitak elastičnosti i opuštenu teksturu kože. Poboljšanje teksture i pora: Ujednačava površinu kože i smanjuje vidljivost proširenih pora. Ujednačen i blistav ten: Pomaže kod hiperpigmentacija i sivog, umornog izgleda kože. Kome je namenjen? Namenjen je zreloj koži i osobama koje imaju izražene znake starenja, bore, gubitak čvrstine, neujednačenu teksturu i pigmentacije. Preporučuje se korisnicima sa iskustvom u upotrebi retinoida. Zašto volimo K-SECRET Advanced Shot Retinal Liposome 12% + Black Rice? Zato što je formulisan kao ciljano rešenje za vidljive promene na koži. Visoka koncentracija retinala je stabilizovana liposomskom tehnologijom, što omogućava snažno, ali kontrolisano delovanje. Tekstura je koncentrisana, ali se ravnomerno raspoređuje. Fokus je na stvarnim, dugoročnim rezultatima, a ne na trenutnom efektu. Idealan je kao noćni tretman za obnovu kože. Namenjen je rutini koja ima jasan anti-age cilj. Aktivni sastojci Retinal Liposome 12% Retinal je direktni prethodnik retinoične kiseline i deluje brže od klasičnog retinola. Liposomska tehnologija omogućava stabilnije i ujednačenije otpuštanje aktivnog sastojka u koži. Podstiče obnovu ćelija i sintezu kolagena. Doprinosi zaglađivanju bora i poboljšanju čvrstine. Deluje na neujednačenu teksturu i pore. Namenjen je naprednoj anti-age nezi. Ekstrakt crnog pirinča Crni pirinač je bogat antioksidansima koji štite kožu od oksidativnog stresa. Pomaže u očuvanju elastičnosti kože. Doprinosi jačanju kožne barijere. Podržava regeneraciju kože tokom noći. Deluje zaštitno i obnavljajuće. U ovoj formuli ima ulogu stabilizacije i podrške retinalu. Hidrolizovane spikule Spikule prirodnog porekla pomažu boljoj apsorpciji aktivnih sastojaka. Stimulacijom mikrocirkulacije podstiču prirodnu obnovu kože. Doprinose ujednačenijoj teksturi. Deluju ciljano u zonama nepravilnosti. Njihovo dejstvo je usmereno i kontrolisano. Koriste se u malim, funkcionalnim količinama. Niacinamid Niacinamid pomaže u ujednačavanju tena i jačanju kožne barijere. Doprinosi smanjenju vidljivosti pora. Podržava balans kože tokom retinoidne rutine. Deluje umirujuće. Pomaže u kontroli neujednačenog tona. U formuli ima stabilizujuću ulogu. Panthenol Panthenol pomaže u očuvanju hidratacije kože. Doprinosi smanjenju iritacija. Jača zaštitnu barijeru kože. Podržava regeneraciju tokom noćne nege. Daje osećaj komfora. Posebno je važan u formulama sa jakim aktivnim sastojcima. Dodaj u listu želja Dodaj u listu želja', 'K-SECRET Advanced Shot Retinal Liposome 12% + Black Rice je visoko koncentrovani noćni tretman namenjen intenzivnoj korekciji znakova starenja i neujednačene teksture kože. Kombinuje liposomski retinal visoke jačine sa ekstraktom crnog pirinča kako bi se poboljšala elastičnost, zagladila koža, smanjila vidljivost bora, pora i pigmentacija, uz kontrolisano i stabilno delovanje.', 'https://beauty-health.rs/wp-content/uploads/2025/12/K-SECRET-Advanced-Shot-Retinal-Liposome-12-Black-Rice-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
