INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (237, 99, 'Kose Softymo Cleansing Oil', 'kose-softymo-cleansing-oil', 'Ključne prednosti: Temeljno uklanjanje šminke i nečistoća: Rastvara čak i postojanu šminku i maskaru bez agresivnog trljanja. Očuvana hidratacija kože: Čisti kožu bez isušivanja i neprijatnog zatezanja. Jednostavna i brza rutina čišćenja: Omogućava efikasno čišćenje bez potrebe za dvostrukim pranjem. Kome je namenjen? Namenjen je svim tipovima kože, posebno suvoj i dehidriranoj koži kojoj je potrebno blago, ali efikasno čišćenje. Pogodan je i za osetljivu kožu, kao i za osobe koje nose ekstenzije trepavica. Zašto volimo Kose Softymo Cleansing Oil? Zato što kombinuje snagu uljanog čišćenja i osećaj čiste kože bez ostataka. Tekstura se lako razmazuje i brzo emulguje u kontaktu sa vodom. Koža nakon ispiranja ostaje mekana i glatka. Ne ostavlja masni trag i ne opterećuje pore. Pogodan je za svakodnevnu upotrebu. Omogućava brzu i jednostavnu rutinu čišćenja. Aktivni sastojci Maslinovo ulje Maslinovo ulje pomaže u rastvaranju šminke i nečistoća. Doprinosi očuvanju hidratacije kože. Deluje hranljivo i zaštitno. Sprečava isušivanje tokom čišćenja. Pogodno je za suvu i osetljivu kožu. U ovom proizvodu ima ulogu osnovnog negujućeg ulja. Jojobino ulje Jojobino ulje je slično prirodnom sebumu kože. Pomaže u balansiranju masnoće. Doprinosi mekoći i elastičnosti kože. Ne začepljuje pore. Deluje blago i stabilno. Pogodno je za svakodnevnu upotrebu. Susamovo ulje Susamovo ulje ima hranljiva i zaštitna svojstva. Pomaže u uklanjanju nečistoća iz pora. Doprinosi glatkoći kože. Deluje antioksidativno. Podržava barijernu funkciju kože. U proizvodu ima potpornu ulogu. Safflower ulje Ulje šafranike pomaže očuvanju vlage u koži. Doprinosi mekoći i ujednačenom izgledu. Deluje lagano i ne ostavlja težak osećaj. Pogodno je za suvu i normalnu kožu. Pomaže u smanjenju osećaja zatezanja. Ima ulogu hidratantne podrške. Shea puter Shea puter pruža dodatnu negu tokom čišćenja. Pomaže u sprečavanju isušivanja kože. Doprinosi glatkom i nahranjenom osećaju nakon ispiranja. Deluje umirujuće. Pogodan je za osetljivu kožu. U ovom proizvodu ima zaštitnu i negujuću ulogu. Dodaj u listu želja Dodaj u listu želja', 'Kose Softymo Cleansing Oil je uljani čistač namenjen efikasnom uklanjanju šminke, viška sebuma i nečistoća bez isušivanja kože. Cleansing Oil sadrži kombinaciju pet biljnih ulja, uključujući maslinovo, jojobino i susamovo ulje, kao i shea puter, kako bi koža nakon čišćenja ostala mekana, hidrirana i čista, bez masnog filma.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Kose-Softymo-Cleansing-Oil.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
