INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (238, 97, 'Klavuu Lip Sleeping Pack Boosting Kit', 'klavuu-lip-sleeping-pack-boosting-kit', 'Ključne prednosti: Intenzivna noćna hidratacija: Stvara zaštitni uljni sloj koji sprečava gubitak vlage. Obnova i mekoća usana: Pomaže regeneraciju suvih i ispucalih usana. Praktičan mini format: Tri varijante u putnom pakovanju za različite potrebe i ukuse. Kome je namenjen? Namenjen je svima koji imaju suve, dehidrirane ili ispucale usne, uključujući osetljivu kožu. Pogodan je za svakodnevnu upotrebu, naročito u periodima hladnoće, suvoće vazduha ili čestog korišćenja ruževa. Zašto volimo Klavuu Lip Sleeping Pack Boosting Kit? Zato što nudi ciljanu negu usana kroz tri različite, ali komplementarne formule. Teksture su bogate, ali prijatne i ne razlivaju se tokom noći. Usne su ujutru mekše, glađe i vidljivo hidrirane. Mini pakovanja su praktična za nošenje i isprobavanje različitih varijanti. Formula je hipoalergena i testirana na iritacije. Idealan je izbor za kontinuiranu negu usana bez komplikacija. Aktivni sastojci Biljna ulja za hidrataciju i zaštitu Biljna ulja u formulama pomažu stvaranje zaštitnog sloja na usnama. Sprečavaju isušivanje i gubitak vlage tokom noći. Doprinose mekoći i elastičnosti usana. Deluju hranljivo i regenerativno. Njihovo dejstvo je dugotrajno i stabilno. Pogodna su i za osetljivu kožu. Jojoba, slatki badem i ulje noćurka (Vanilla) Ova kombinacija ulja intenzivno hidrira i umiruje usne. Pomaže u obnovi suve i oštećene kože usana. Doprinosi glatkom i negovanom izgledu. Deluje blago i bez iritacija. Posebno je pogodna za svakodnevnu upotrebu. U Vanilla varijanti ima dominantnu negujuću ulogu. Berry Complex, Rose Hip Oil i Vitamin Tree Fruit Oil (Berry) Berry kompleks doprinosi osveženju i vitalnosti usana. Ulje šipka i ulje ploda vitamin-drveta pomažu u očuvanju vlage. Daju usnama puniji i živahniji izgled. Deluju antioksidativno. Podržavaju regeneraciju usana tokom noći. Ova kombinacija pruža balans nege i svežine. Kokosovo i avokado ulje (Coconut) Kokosovo i avokado ulje poznati su po snažnim hranljivim svojstvima. Pomažu omekšavanje grubih i suvih usana. Doprinosе dugotrajnoj hidrataciji. Deluju zaštitno i obnavljajuće. Idealni su za veoma suve usne. U Coconut varijanti imaju centralnu ulogu. Dodaj u listu želja Dodaj u listu želja', 'Klavuu Lip Sleeping Pack Boosting Kit je set od tri mini noćne maske za usne namenjen intenzivnoj hidrataciji, obnovi i zaštiti usana tokom noći. Lip Sleeping Pack Boosting Kit kombinuje tri različite formule – Vanilla, Berry i Coconut – kako bi usne bile mekše, nahranjene i vidljivo zaglađenije, čak i kod osetljive kože.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Klavuu-Lip-Sleeping-Pack-Boosting-Kit.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
