INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (241, 88, 'Judydoll Volume & Curling Mascara Duo', 'judydoll-volume-curling-mascara-duo', 'Ključne prednosti: Vidljiv volumen i uvijenost: Prajmer podiže i razdvaja trepavice, dok maskara daje punoću i oblik. Precizna definicija svake trepavice: Fini češalj i zakrivljena četkica omogućavaju detaljnu aplikaciju bez slepljivanja. Dugotrajan efekat: Mikro-vlakna pomažu da trepavice ostanu guste i izražene tokom dana. Kome je namenjena? Namenjena je osobama koje žele naglašene, uvijene i voluminozne trepavice uz kontrolisanu aplikaciju. Pogodna je i za one sa kraćim, ravnijim ili ređim trepavicama, kao i za precizno naglašavanje donjih trepavica. Zašto volimo Judydoll Volume & Curling Mascara Duo? Zato što nudi kompletan pristup trepavicama u jednom proizvodu. Prajmer priprema trepavice i razdvaja ih bez opterećenja. Maskara se lako nadograđuje i ne stvara grudvice. Zakrivljena četkica omogućava rad i na unutrašnjim i spoljašnjim uglovima oka. Rezultat je izražen, ali uredan izgled trepavica. Idealna je za svakodnevnu šminku, ali i za intenzivniji efekat. Karakteristike formule Prajmer sa igličastim češljem Prajmer razdvaja svaku trepavicu pojedinačno. Pomaže podizanju i uvijanju trepavica. Olakšava ravnomerno nanošenje maskare. Sprečava slepljivanje. Pogodan je i za donje trepavice. Daje osnovu za dugotrajniji efekat. Maskara sa mikro-vlaknima Mikro-vlakna doprinose vizuelnom produžavanju trepavica. Pomažu postizanju gušćeg izgleda. Ravnomerno se raspoređuju duž trepavica. Ne stvaraju težinu. Efekat je postojan tokom dana. Trepavice deluju punije i definisanije. Zakrivljena četkica Zakrivljeni oblik prati liniju oka. Omogućava preciznu aplikaciju od korena do vrhova. Posebno je korisna za unutrašnje i spoljašnje uglove. Pomaže u stvaranju prirodno gustog izgleda. Olakšava kontrolu prilikom nanošenja. Pogodna je za slojevito nanošenje. Dodaj u listu želja Dodaj u listu želja', 'Judydoll Volume & Curling Mascara Duo je dvostrana maskara sa prajmerom i maskarom, osmišljena za postizanje izraženog volumena, dužine i uvijenosti trepavica. Mascara Duo kombinuje razdvajajući prajmer sa igličastim češljem i maskaru sa mikro-vlaknima kako bi svaka trepavica bila definisana, podignuta i vizuelno gušća.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Judydoll-Volume-Curling-Mascara-Duo-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
