INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (242, 88, 'Judydoll Slim Liquid Eyeliner', 'judydoll-slim-liquid-eyeliner', 'Ključne prednosti: Ekstremna preciznost: Ultra-tanki vrh omogućava iscrtavanje vrlo tankih i urednih linija bez napora. Dugotrajna postojanost: Vodootporna i otporna na znoj formula ne razmazuje se tokom dana. Prirodan, čist finiš: Ravnomerna pigmentacija daje mek i uredan izgled bez grudvica. Kome je namenjen? Pogodan je za početnike, ali i za iskusne korisnike koji žele maksimalnu kontrolu. Idealan je za svakodnevnu šminku, diskretne linije uz trepavice, ali i precizne grafičke detalje. Zašto volimo Judydoll Slim Liquid Eyeliner? Zato što omogućava „gotovo u jednom potezu“. Tekstura je glatka i podatna, ne presušuje brzo i ne preskače pri nanošenju. Linija ostaje postojana tokom dana, bez razlivanja ili pucanja. Savršen je kada želiš uredan, čist pogled bez popravljanja. Karakteristike formule Ultra-fini četkasti vrh (0,014 mm) Omogućava potpunu kontrolu pokreta. Idealan je za tanke linije uz trepavice. Pogodan za precizne detalje. Olakšava nanošenje bez grešaka. Prilagođava se pritisku ruke. Daje profesionalni rezultat i kod kućne upotrebe. Meka i ravnomerna pigmentacija Boja se nanosi glatko i ujednačeno. Ne ostavlja tragove ili praznine. Ne stvara grudvice. Omogućava prirodan ili izražen izgled u zavisnosti od slojevitosti. Linija izgleda čisto i uredno. Pogodna je i za suptilan dnevni make-up. Vodootporna i sweat-proof formula Otporna je na vlagu, znoj i razmazivanje. Ne bledi tokom dana. Pogodna je za duže nošenje. Održava liniju postojanom i preciznom. Ne preslikava se na kapak. Idealna za aktivan dan ili duže večernje prilike. Dodaj u listu želja Dodaj u listu želja', 'Judydoll Slim Liquid Eyeliner je precizan tečni ajlajner namenjen svima koji žele čistu, tanku i kontrolisanu liniju bez razmazivanja. Slim Liquid Eyeliner dolazi sa ultra-tankim četkastim vrhom od svega 0,014 mm, što omogućava izuzetnu preciznost i lakoću nanošenja – čak i ako ajlajner inače nije tvoja jača strana.', 'https://beauty-health.rs/wp-content/uploads/2025/12/3_b6c9fcc4-f30a-43d0-a3b7-90544397a999.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
