INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (243, 78, 'Isntree Mugwort Calming Clay Mask', 'isntree-mugwort-calming-clay-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Uklanja višak sebuma, nečistoće i nakupljene ostatke iz pora bez isušivanja kože. Umirujuće delovanje: Smanjuje crvenilo, iritacije i osećaj nelagodnosti, posebno kod problematične kože. Balans i svež izgled kože: Pomaže u regulaciji lučenja sebuma i ostavlja kožu mekanom i osveženom. Kome je namenjena? Namenjena je masnoj, mešovitoj i nečistoj koži, kao i koži sklonoj zapušenim porama i iritacijama. Pogodna je i za osetljivu kožu zahvaljujući blagoj, ali efikasnoj formuli bez alkohola, mirisa i eteričnih ulja. Zašto volimo Isntree Mugwort Calming Clay Mask? Zato što pruža balans između temeljitog čišćenja i umirujuće nege. Tekstura je kremasta i prijatna, ne zateže kožu tokom upotrebe. Može se koristiti redovno bez straha od isušivanja. Koža nakon ispiranja deluje čistije, smirenije i ujednačenije. Posebno je korisna kod proširenih pora i povremenih nepravilnosti. Idealna je kao deo rutine za održavanje čiste i stabilne kože. Aktivni sastojci Ganghwa Artemisia (Mugwort) ekstrakt 5% Mugwort je poznat po snažnom umirujućem i antiseptičkom delovanju. Pomaže u smanjenju crvenila i iritacija. Doprinosi boljem balansu vlage u koži. Reguliše prekomerno lučenje sebuma. Deluje blago, ali efikasno. Posebno je pogodan za problematičnu i osetljivu kožu. Šest vrsta gline Kaolin, bentonit, ilit, montmorilonit, kalcit i kanadska koloidna glina deluju sinergijski na čišćenje pora. Upijaju višak sebuma i nečistoće. Pomažu u uklanjanju mitisera. Doprinose zaglađenijoj teksturi kože. Čiste bez agresivnog isušivanja. Pogodne su za redovnu upotrebu. Crveni pasulj i prah lista artemisije Biljni prahovi omogućavaju blagu mehaničku eksfolijaciju. Pomažu u uklanjanju mrtvih ćelija kože. Doprinose čistijem i ujednačenijem izgledu tena. Deluju nežno i ne iritiraju kožu. Poboljšavaju teksturu kože tokom vremena. Idealni su za kožu sklonu zapušenim porama. Panthenol i beta-glukan Ovi sastojci umiruju kožu tokom i nakon čišćenja. Pomažu u očuvanju hidratacije. Smanjuju mogućnost iritacija. Jačaju zaštitnu barijeru kože. Daju osećaj prijatnosti nakon ispiranja maske. Pogodni su i za osetljivu kožu. Biljni antioksidansi Ekstrakti zelenog čaja, vrbe i ovsa pružaju antioksidativnu zaštitu. Pomažu u smirivanju kože. Podržavaju prirodnu ravnotežu kože. Doprinose zdravijem izgledu tena. Deluju blago i stabilizuju kožu. Daju dodatnu negu tokom čišćenja. Dodaj u listu želja Dodaj u listu želja', 'Isntree Mugwort Calming Clay Mask je umirujuća glinena maska namenjena dubinskom čišćenju pora, regulaciji sebuma i smirivanju osetljive, reaktivne i nečiste kože. Calming Clay Mask kombinuje šest vrsta gline, 5% ekstrakta ganghwa mugworta i biljne prahove kako bi temeljno očistila kožu, a pritom očuvala njenu hidrataciju i ravnotežu.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Isntree-Mugwort-Calming-Clay-Mask.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
