INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (246, 69, 'Haruharu Wonder Rose PDRN Soothing Serum', 'haruharu-wonder-rose-pdrn-soothing-serum', 'Ključne prednosti: Umirivanje crvenila i iritacija: Pomaže smanjenju reaktivnosti kože i vraća joj balans. Podsticanje regeneracije kože: Podržava prirodnu obnovu i poboljšava elastičnost. Dubinska hidratacija bez opterećenja: Održava kožu hidriranom i mekom bez lepljivog osećaja. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu i reaktivnu, kao i koži sklonoj crvenilu, dehidrataciji i neujednačenom tenu. Posebno odgovara umornoj koži kojoj je potrebna obnova i smirenje bez agresivnih aktivnih sastojaka. Zašto volimo Haruharu Wonder Rose PDRN Soothing Serum? Zato što nudi regeneraciju i umirenje u jednoj, izuzetno balansiranoj formuli. Tekstura je kremasta, ali lagana i brzo se upija bez osećaja težine. Serum se lako uklapa u svakodnevnu rutinu i ne narušava kožnu barijeru. Deluje postepeno, ali dosledno, čineći kožu smirenijom, hidriranijom i ujednačenijom. Formula je pažljivo osmišljena tako da odgovara i najosetljivijoj koži. Aktivni sastojci Rose PDRN Biljni PDRN dobijen iz damaščanske ruže poznat je po svom regenerativnom delovanju. Podržava obnovu kože i podstiče procese ćelijske regeneracije. Doprinosi poboljšanju elastičnosti i opštem zdravlju kože. Deluje umirujuće i pomaže koži da se oporavi od spoljašnjih stresora. Pogodan je i za osetljivu kožu. Njegovo delovanje je postepeno i stabilno. Azelaična kiselina Azelaična kiselina deluje umirujuće i pomaže u smanjenju crvenila i iritacija. Doprinosi ujednačavanju tena i poboljšanju teksture kože. Poznata je po blagom, ali efikasnom delovanju. Pogodna je za kožu sklonu nepravilnostima i hiperpigmentacijama. Ne izaziva agresivne reakcije. Idealan je izbor za svakodnevnu upotrebu. Sodium PCA Sodium PCA je snažan humektant koji pomaže koži da zadrži vlagu. Doprinosi elastičnosti i jačanju kožne barijere. Pruža dugotrajnu hidrataciju bez osećaja težine. Posebno je koristan kod dehidrirane kože. Održava kožu mekom i glatkom. Podržava prirodnu ravnotežu vlažnosti. Pantenol Pantenol umiruje kožu i pomaže u obnavljanju zaštitne barijere. Doprinosi smanjenju iritacija i crvenila. Pruža osećaj komfora i hidratacije. Pogodan je za osetljivu i reaktivnu kožu. Poboljšava ukupni izgled kože. Deluje blago, ali efikasno. Skvalan Skvalan pomaže u omekšavanju kože i sprečava gubitak vlage. Jača kožnu barijeru i doprinosi dugotrajnoj hidrataciji. Ne opterećuje kožu i brzo se upija. Pogodan je za sve tipove kože. Održava kožu glatkom i elastičnom. Daje prijatan, negujući završetak. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Rose PDRN Soothing Serum je umirujući i regenerativni serum namenjen koži koja pokazuje znake umora, crvenila i neujednačenog tona. Formulisan je da podstakne obnovu kože, poboljša njenu elastičnost i pruži dugotrajnu hidrataciju bez iritacije. Sadrži biljni PDRN dobijen iz Damask ruže sa azelaičnom kiselinom, pantenolom i skvalanom kako bi koža bila smirenija, ujednačenija i vidljivo zdravija, čak i kod osetljivih tipova kože.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Haruharu-Wonder-Rose-PDRN-Soothing-Serum-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
