INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (251, 40, 'Cosrx The Peptide Collagen Lifting Glow Hydrogel Mask', 'cosrx-the-peptide-collagen-lifting-glow-hydrogel-mask', 'Ključne prednosti: Poboljšanje čvrstine i elastičnosti: Pomaže koži da izgleda zategnutije i kompaktnije uz redovnu upotrebu. Vidljivo zaglađivanje linija i bora: Doprinosi smanjenju izraženosti finih linija i umorne teksture kože. Intenzivna hidratacija i sjaj: Hidrogelska struktura zadržava vlagu i ostavlja kožu glatkom, hidriranom i blistavom. Kome je namenjen? Namenjen je koži koja pokazuje znake gubitka tonusa, elastičnosti i svežine, uključujući normalnu, suvu i zrelu kožu. Posebno odgovara osobama koje primećuju opuštenost, fine bore ili umoran izgled tena. Zašto volimo Cosrx The Peptide Collagen Lifting Glow Hydrogel Mask? Zato što pruža trenutni osećaj zategnutosti, ali i dugoročnu podršku kvalitetu kože. Hidrogel savršeno prijanja uz lice i omogućava ravnomerno oslobađanje aktivnih sastojaka. Tokom upotrebe maska postaje providna, što ukazuje na to da se esencija apsorbuje u kožu. Koža nakon skidanja izgleda punije, glatkije i osveženije. Pogodna je i kao povremena intenzivna nega i kao deo redovne rutine. Posebno prija koži kojoj je potreban vidljiv „lifting“ efekat bez agresivnih metoda. Aktivni sastojci Peptidi (6 tipova) Peptidi su signalni molekuli koji imaju važnu ulogu u očuvanju čvrstine i strukture kože. U ovoj maski kombinovano je više tipova peptida kako bi se obuhvatilo više aspekata starenja kože. Oni pomažu poboljšanje elastičnosti i ukupnog kvaliteta kože. Redovnom upotrebom koža može delovati zategnutije i otpornije. Peptidi takođe doprinose zaglađivanju teksture. Njihovo delovanje je postepeno i usmereno na dugoročne promene. Kolagen niske molekulske mase Kolagen u ovom obliku pomaže poboljšanju izgleda elastičnosti i punoće kože. Iako ne zamenjuje prirodni kolagen, doprinosi hidrataciji i glatkoći površine kože. Koža nakon upotrebe deluje mekše i kompaktnije. Niska molekulska masa omogućava bolju interakciju sa kožom. Posebno je koristan kod kože sa vidljivim znakovima opuštenosti. Daje trenutni efekat svežine i zaglađenosti. Niacinamid Niacinamid doprinosi ujednačavanju tena i poboljšanju teksture kože. Pomaže koži da izgleda svetlije i odmornije. Takođe podržava funkciju kožne barijere. U kombinaciji sa peptidima doprinosi zdravijem izgledu kože. Njegovo delovanje je blago i dobro podnošljivo. Pogodan je i za osetljiviju kožu. N-acetil glukozamin (NAG) NAG je sastojak koji podržava ujednačenost tena i kvalitet kože. Deluje sinergijski sa niacinamidom. Doprinosi glađem i ujednačenijem izgledu kože. Posebno je koristan kod umorne i beživotne kože. Njegovo delovanje je postepeno i nenametljivo. U ovoj maski ima potporni efekat na sjaj i teksturu. Pantenol (Vitamin B5) Pantenol pomaže u smirivanju i hidrataciji kože. Podržava osećaj komfora tokom i nakon upotrebe maske. Doprinosi boljoj toleranciji aktivnih sastojaka. Posebno je važan kod kože sklone osetljivosti. Pomaže koži da ostane meka i hidrirana. Njegovo dejstvo je umirujuće i balansirajuće. Alantoin Alantoin je poznat po svom umirujućem dejstvu. Pomaže smanjenju nelagodnosti i osećaja zatezanja. Doprinosi prijatnijem osećaju na koži tokom nošenja maske. Posebno je pogodan za osetljivu i reaktivnu kožu. Njegovo delovanje je blago i podržavajuće. U ovoj formuli ima smirujuću ulogu. Dodaj u listu želja Dodaj u listu želja', 'Cosrx The Peptide Collagen Lifting Glow Hydrogel Mask je hidrogelska maska za intenzivnu negu kože sa gubitkom čvrstine, elastičnosti i sjaja. Sadrži 6 tipova peptida i kolagen niske molekulske mase kako bi koži pružila vidljivo zatezanje, puniji izgled i svež, ujednačen ten, dok se sama maska tokom delovanja postepeno pretvara u providnu.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Cosrx-The-Peptide-Collagen-Lifting-Glow-Hydrogel-Mask-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
