INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (253, 40, 'Cosrx Skin Barrier Moisturizing Cream', 'cosrx-skin-barrier-moisturizing-cream', 'Ključne prednosti: Jačanje i obnova kožne barijere: Pomaže obnovu oslabljenog zaštitnog sloja kože i smanjuje gubitak vlage. Dugotrajna, dubinska hidratacija: Klinički potvrđena hidratacija koja traje do 100 sati bez osećaja težine. Umirenje i poboljšanje teksture: Omekšava grube, perutave delove i smanjuje osećaj zatezanja. Kome je namenjena? Namenjena je normalnoj do suvoj koži, kao i koži sklonoj perutanju, osetljivosti i narušenoj barijeri. Posebno je pogodna za kožu koja nakon tuširanja ili umivanja deluje zategnuto, neprijatno ili dehidrirano. Zašto volimo Cosrx Skin Barrier Moisturizing Cream? Zato što pruža osećaj komfora odmah nakon nanošenja, ali i dugoročno poboljšava stanje kože. Tekstura je hranljiva, ali se brzo upija i ne ostavlja mastan film. Krema se lako uklapa u svakodnevnu rutinu, ujutru i uveče. Posebno je korisna kod kože koja često reaguje na spoljašnje uticaje. Dugoročno doprinosi stabilnijoj, otpornijoj i mekšoj koži. Praktična je i za lice i za suvlje delove tela. Aktivni sastojci 5-Ceramide Complex (Ceramide NP, NS, AP, AS, EOP) Ceramidi su ključni lipidi prirodno prisutni u kožnoj barijeri. U ovoj formuli deluju tako što imitiraju prirodnu strukturu kože i pomažu njenoj obnovi. Smanjuju transepidermalni gubitak vode i povećavaju otpornost kože. Doprinosе stabilnijoj i otpornijoj barijeri. Posebno su važni kod suve i osetljive kože. Njihovo delovanje je dugoročno i kumulativno. Holesterol i masne kiseline Ovi lipidi su sastavni deo zdrave kožne barijere. Pomažu obnovu elastičnosti i fleksibilnosti kože. U kombinaciji sa ceramidima stvaraju uravnotežen lipidni sloj. Doprinosе boljem zadržavanju vlage. Koža postaje otpornija na spoljašnje uticaje. Njihova uloga je ključna kod oštećene barijere. Fitospingozin i skvalan Fitospingozin ima umirujuće i balansirajuće dejstvo. Skvalan pomaže zadržavanje vlage i sprečava isušivanje. Zajedno doprinose smanjenju iritacija i osećaja nelagodnosti. Poboljšavaju mekoću i glatkoću kože. Njihovo delovanje je blago i pogodno za osetljivu kožu. Pomažu održavanje zdravog izgleda kože. Višemolekulska hijaluronska kiselina (5 tipova) Različite molekulske mase omogućavaju hidrataciju na više nivoa kože. Deluju površinski i dublje, bez osećaja težine. Pomažu koži da ostane puna i elastična. Sprečavaju dehidrataciju tokom dana. Doprinose prijatnom, hidriranom osećaju. Posebno su korisne kod suve i zategnute kože. Pantenol (vitamin B5) i NMF Pantenol smiruje crvenilo i iritacije i pomaže zadržavanje vlage. NMF obnavlja prirodne hidratantne komponente kože. Zajedno doprinose dugotrajnoj hidrataciji i mekoći. Jačaju toleranciju kože na spoljašnje faktore. Poboljšavaju ukupni osećaj komfora. Pogodni su za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Cosrx Skin Barrier Moisturizing Cream je bogata, ali brzo upijajuća krema namenjena jačanju kožne barijere i dugotrajnoj hidrataciji, čak i kod osetljive i reaktivne kože. Sadrži višeslojnu hijaluronsku hidrataciju sa kompleksom ceramida, lipidima sličnim prirodnim komponentama kože i umirujućim sastojcima kako bi koža ostala mekana, elastična i zaštićena tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Cosrx-Skin-Barrier-Moisturizing-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
