INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (255, 40, 'Cosrx PDRN EXOSOME Skinplaning Glaze Mask', 'cosrx-pdrn-exosome-skinplaning-glaze-mask', 'Ključne prednosti: Zaglađivanje teksture i ujednačen izgled: Pomaže u uklanjanju površinskih nečistoća i nepravilnosti, ostavljajući kožu glatkom i ujednačenom. Vidljiv sjaj i efekat „glazed glow“: Povećava prirodni sjaj kože i smanjuje sivilo i umoran izgled. Hidratacija i efekat punoće: Zadržava vlagu u koži i doprinosi čvršćem, punijem izgledu lica. Kome je namenjena? Namenjena je svim tipovima kože, posebno onima sa neravnom teksturom, gubitkom sjaja i prvim znacima starenja. Odgovara i suvoj i osetljivoj koži kojoj je potreban sjaj i zaglađivanje bez klasičnog pilinga. Zašto volimo Cosrx PDRN EXOSOME Skinplaning Glaze Mask? Zato što pruža efekat „skinplaninga“ bez iritacije i bez mehaničkog uklanjanja. Tekstura se lako nanosi, ravnomerno se suši i uklanja u jednom komadu. Koža nakon upotrebe deluje zaglađeno, hidrirano i vidljivo sjajnije. Masku je lako uklopiti u večernju rutinu, ali i koristiti kao povremeni tretman za brzi „glow“. Posebno je praktična kada koži treba instant osveženje i bolji izgled. Efekat je vidljiv, ali ne agresivan. Aktivni sastojci PDRN (polideoksiribonukleotid) PDRN je sastojak dobijen iz DNK, poznat po svojoj kompatibilnosti sa kožom. Deluje tako što podržava prirodne procese obnove i regeneracije. Pomaže poboljšanje elastičnosti i opšteg kvaliteta kože. Doprinosi zdravijem i ujednačenijem izgledu tena. Posebno je koristan kod umorne i oslabljene kože. U ovoj maski ima ulogu revitalizacije i jačanja kože. Egzozomi (Lactobacillus i Centella porekla) Egzozomi su mikroskopske vezikule koje služe kao prenosioci korisnih signala i nutrijenata. U ovoj formuli dobijeni su iz laktobacila i centelle. Pomažu bolju isporuku aktivnih sastojaka koži. Doprinosе smirivanju, jačanju i poboljšanju sjaja kože. Deluju sinergijski sa PDRN-om. Njihova uloga je podrška vitalnosti i otpornosti kože. Kolagen i peptidi Kolagen i peptidi doprinose zaglađenijem i čvršćem izgledu kože. Na površini pomažu zadržavanje vlage i osećaj punoće. Peptidi podržavaju elastičnost i tonus. Ova kombinacija utiče na vizuelno smanjenje znakova umora. Koža deluje zategnutije i negovanije. Posebno su korisni kod ranih znakova starenja. Niacinamid i glutation Niacinamid pomaže ujednačavanje tena i jačanje kožne barijere. Glutation doprinosi smanjenju sivila i poboljšanju sjaja kože. Zajedno deluju na ujednačen i svež izgled tena. Njihovo delovanje je postepeno i stabilno. Pogodni su i za osetljivu kožu. U maski imaju ulogu toniranja i osvetljavanja. Pantenol, alantoin i hijaluronska kiselina Ova kombinacija ima snažnu hidratantnu i umirujuću funkciju. Pantenol i alantoin smiruju kožu i pomažu obnovu barijere. Hijaluronska kiselina zadržava vlagu i sprečava isušivanje. Koža nakon upotrebe ostaje mekana i prijatna. Posebno su važni kod suve i dehidrirane kože. Daju osećaj komfora nakon skidanja maske. Dodaj u listu želja Dodaj u listu želja', 'Cosrx PDRN EXOSOME Skinplaning Glaze Mask je peel-off maska nove generacije, osmišljena da u jednom koraku zagladi teksturu kože, pojača sjaj i pruži efekat zaglađene kože. Sadrži PDRN i egzozome sa kolagenom, peptidima i umirujućim sastojcima kako bi koža nakon samo jedne upotrebe izgledala glađe, punije i odmornije.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Cosrx-PDRN-EXOSOME-Skinplaning-Glaze-Mask-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
