INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (256, 40, 'Cosrx 5 PDRN Collagen Intense Vitalizing Serum', 'cosrx-5-pdrn-collagen-intense-vitalizing-serum', 'Ključne prednosti: Podrška regeneraciji i čvrstini kože: Pomaže koži da se brže oporavi, deluje na gubitak elastičnosti i jača kožnu strukturu. Ujednačavanje tena i poboljšanje sjaja: Doprinosi smanjenju tamnih mrlja i neujednačenog tona, čineći kožu vidljivo svežijom. Dubinska hidratacija i umirenje: Intenzivno hidrira, smiruje osetljivu kožu i jača zaštitnu barijeru. Kome je namenjen? Namenjen je svim tipovima kože, posebno koži koja deluje umorno, beživotno i sklona gubitku čvrstine. Odgovara i osetljivoj koži, kao i koži sa neujednačenim tonom, pigmentacijama i prvim ili izraženijim znakovima starenja. Zašto volimo Cosrx 5 PDRN Collagen Intense Vitalizing Serum? Zato što kombinuje napredne regenerativne sastojke u laganoj, brzo upijajućoj teksturi. Serum ne opterećuje kožu, ali pruža osećaj dubinske nege i elastičnosti. Dobro se uklapa u različite rutine i slojeve nege. Posebno se ističe balansom između hidratacije, umirenja i vidljivog poboljšanja kvaliteta kože. Namenjen je dugoročnoj upotrebi, sa fokusom na jačanje i stabilnost kože. Rezultat je koža koja izgleda odmornije, punije i zdravije. Aktivni sastojci 5 PDRN kompleks PDRN je sastojak poznat po ulozi u regeneraciji i podršci prirodnim procesima obnove kože. U ovom serumu koristi se kombinacija PDRN-a dobijenog iz pet različitih izvora, uključujući losos, centelu, pirinač, laktobacile i morske alge. Deluje tako što pomaže oporavak oslabljene kože i podržava njenu strukturu. Doprinosi poboljšanju elastičnosti i smanjenju znakova oštećenja. Posebno je koristan kod kože koja je izložena stresu ili iritacijama. Njegovo delovanje je usmereno na jačanje i stabilnost kože na duže staze. Kolagen niske molekulske mase (200 Da) Kolagen u ovom obliku ima izraženu hidratantnu i zaglađujuću ulogu. Na površini kože pomaže zadržavanje vlage i poboljšava osećaj punoće. Vizuelno doprinosi čvršćem i elastičnijem izgledu kože. Ne deluje kao zamena za prirodni kolagen, već kao podrška kožnoj strukturi. Redovnom upotrebom pomaže koži da izgleda zaglađenije i svežije. Posebno je koristan kod kože koja gubi tonus. Niacinamide i alfa-arbutin Niacinamid doprinosi jačanju kožne barijere i ujednačavanju tena. U kombinaciji sa alfa-arbutinom pomaže u smanjenju vidljivosti tamnih mrlja i neujednačenog tona. Ova kombinacija deluje postepeno i stabilno, bez agresivnog posvetljivanja. Podržava zdrav izgled kože i njen prirodni sjaj. Takođe pomaže regulaciju sebuma. Pogodna je i za osetljivu kožu. Osam tipova hijaluronske kiseline Kombinacija hijaluronskih kiselina različite molekulske mase omogućava višeslojnu hidrataciju. Deluju na površinskim i dubljim slojevima kože. Pomažu u zadržavanju vlage i sprečavanju dehidratacije. Koža postaje punija i elastičnija na dodir. Hidratacija doprinosi i boljoj otpornosti kože. Ovaj kompleks je ključan za dugotrajan osećaj prijatnosti. Pantenol i alantoin Pantenol i alantoin imaju umirujuću i zaštitnu ulogu. Pomažu smanjenje iritacija i jačanje oslabljene kožne barijere. Posebno su korisni kod osetljive i reaktivne kože. Doprinosе bržem oporavku i većoj toleranciji kože. Njihovo delovanje je blago, ali efikasno. U serumu imaju važnu balansirajuću funkciju. Dodaj u listu želja Dodaj u listu želja', 'Cosrx 5 PDRN Collagen Intense Vitalizing Serum je intenzivni regenerativni serum namenjen koži kojoj nedostaje vitalnost, čvrstina i ujednačen ton. Sadrži kompleks pet različitih PDRN izvora, kolagen niske molekulske mase, niacinamid i višeslojnu hijaluronsku hidrataciju kako bi podržao oporavak kože, poboljšao elastičnost i vratio zdrav sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Cosrx-5-PDRN-Collagen-Intense-Vitalizing-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
