INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (257, 176, 'Wishtrend Mandelic Acid Dark Spot Correcting Serum', 'wishtrend-mandelic-acid-dark-spot-correcting-serum', 'Ključne prednosti: Postepeno posvetljivanje tamnih mrlja: Deluje na hiperpigmentacije različitog porekla i pomaže ujednačavanju tena. Blaga eksfolijacija bez iritacije: Podstiče obnavljanje kože i zaglađuje teksturu bez osećaja peckanja. Lagana, nekomedogena formula: Ne opterećuje kožu i pogodna je za svakodnevnu rutinu. Kome je namenjen? Namenjen je svim tipovima kože, uključujući osetljivu, kao i koži sklonoj hiperpigmentacijama, neujednačenom tenu i postakne flekama. Posebno odgovara osobama koje žele blagi, ali dosledan pristup korekciji tamnih mrlja. Zašto volimo Wishtrend Mandelic Acid Dark Spot Correcting Serum? Zato što nudi vidljive rezultate bez agresivnog pristupa. Tekstura je lagana, hidrirajuća i brzo se upija, bez lepljivog osećaja. Serum se lako uklapa u postojeću rutinu i ne remeti kožnu barijeru. Postepeno poboljšava sjaj i ujednačenost tena, umesto da „šokira“ kožu. Formula je osmišljena tako da bude sigurna i za osetljivu kožu. Idealan je izbor za one koji žele dugoročno čistiji i ujednačeniji izgled kože. Aktivni sastojci Mandelična kiselina Mandelična kiselina je AHA kiselina dobijena iz badema, poznata po većoj molekulskoj strukturi i sporijem prodiranju u kožu. Upravo zbog toga pruža blagu, ali efikasnu eksfolijaciju bez izražene iritacije. Podstiče obnavljanje ćelija i pomaže u uklanjanju površinskih nepravilnosti. Redovnom upotrebom doprinosi smanjenju tamnih mrlja i ujednačenijem tenu. Pogodna je i za osetljivu kožu. Deluje postepeno, ali stabilno. Niacinamid Niacinamid pomaže u ujednačavanju tena i jačanju kožne barijere. Doprinosi smanjenju vidljivosti hiperpigmentacija i nepravilnosti. Takođe pomaže u regulaciji lučenja sebuma, što je važno kod problematične kože. Poboljšava ukupni izgled i teksturu kože. Dobro se kombinuje sa kiselinama u blagim formulama. Pruža dodatnu stabilnost i balans serumu. Glutation Glutation je snažan antioksidans koji se često koristi u formulama za posvetljivanje tena. Deluje tako što pomaže u smanjenju vidljivosti tamnih mrlja. Doprinosi ujednačenijem i svežijem izgledu kože. Njegovo delovanje je postepeno i nenametljivo. Posebno je koristan kod neujednačenog tona. U ovom serumu deo je kapsulirane formule za ciljano delovanje. Derivati vitamina C Stabilni oblici vitamina C pomažu u osvetljavanju tena i poboljšanju njegovog sjaja. Doprinosе ujednačenijem tonu bez iritacije koju može izazvati čisti vitamin C. Podržavaju antioksidativnu zaštitu kože. Deluju sinergijski sa glutationom. Pogodni su za svakodnevnu upotrebu. Njihova uloga je ujednačavanje i osveženje tena. Ekstrakt korena kurkume Kurkuma je poznata po svom umirujućem i antioksidativnom delovanju. Pomaže u smanjenju vidljivosti nepravilnosti i doprinosi ujednačenijem izgledu kože. Njeno delovanje je blago i pogodno za osetljivu kožu. Podržava balans i smirenost kože tokom eksfolijacije. Doprinosi zdravijem izgledu tena. U ovom serumu ima potporni, balansirajući efekat. Dodaj u listu želja Dodaj u listu želja', 'Wishtrend Mandelic Acid Dark Spot Correcting Serum je blagi serum za ujednačavanje tena, formulisan da postepeno smanji tamne mrlje i poboljša teksturu kože bez agresivnog delovanja. Kombinuje mandeličnu kiselinu dobijenu iz badema sa niacinamidom, glutationom i biljnim ekstraktima kako bi koža postala čistija, sjajnija i ujednačenija, čak i kod osetljivih tipova.', 'https://beauty-health.rs/wp-content/uploads/2025/12/MandelicAcidDarkSpotCorrectingSerum-thumbnail-01-product.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
