INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (260, 15, 'Aromatica Serene Body Wash Lavender & Marjoram', 'aromatica-serene-body-wash-lavender-marjoram', 'Ključne prednosti: Opuštanje tela i uma: Pomaže u smanjenju osećaja stresa i napetosti tokom tuširanja. Aromaterapijski efekat: Lavanda i majoran doprinose smirenju raspoloženja i emocionalnom balansu. Nežno čišćenje bez isušivanja: Gelasta tekstura sa bogatom penom čisti kožu uz očuvanje mekoće. Kome je namenjen? Namenjen je svim tipovima kože kao deo svakodnevne higijene tela. Posebno odgovara osobama koje žele da tuširanje koriste kao ritual opuštanja i mentalnog resetovanja nakon napornog dana. Zašto volimo Aromatica Serene Body Wash Lavender & Marjoram? Ovaj gel za tuširanje pretvara svakodnevnu rutinu u smirujući, gotovo meditativni trenutak. Topla voda oslobađa biljne, tople i blago cvetne note koje deluju opuštajuće na čula. Tekstura stvara bogatu penu koja se lako ispira i ne ostavlja osećaj zatezanja na koži. Miris ostaje suptilan i nenametljiv, bez preopterećenja. Koža nakon upotrebe ostaje čista, mekana i prijatna na dodir. Formula je pogodna za redovnu upotrebu, bez osećaja težine ili lepljivosti. Aktivni sastojci Eterično ulje lavande Poznato je po svom umirujućem i balansirajućem mirisu koji pomaže smanjenju napetosti. U aromaterapiji se često koristi za opuštanje i poboljšanje raspoloženja. Tokom tuširanja doprinosi osećaju topline i smirenosti. Lavanda pomaže u stvaranju prijatne, opuštajuće atmosfere. Njeno delovanje je blago i pogodno za svakodnevnu upotrebu. U ovom gelu ima primarno senzornu i umirujuću ulogu. Eterično ulje majorana Ima topao, blago biljni miris koji se povezuje sa osećajem stabilnosti i unutrašnje snage. U aromaterapiji se koristi za smanjenje mentalne preopterećenosti. Majoran doprinosi emocionalnom balansu i osećaju prizemljenosti. Njegov miris pomaže u oslobađanju od viška napetih misli. U kombinaciji sa lavandom daje harmoničan i zaokružen mirisni profil. Deluje umirujuće, ali bez sedativnog efekta. Dodaj u listu želja Dodaj u listu želja', 'Aromatica Serene Body Wash Lavender & Marjoram je gel za tuširanje koji čisti kožu dok istovremeno deluje umirujuće na čula zahvaljujući aromaterapijskoj kombinaciji lavande i majorana. Formulisan je sa etarskim uljima dobijenim parnom destilacijom kako bi pružio svakodnevno čišćenje uz osećaj opuštanja, emotivne stabilnosti i blage hidratacije kože.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Aromatica-Serene-Body-Wash-Lavender-Marjoram-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
