INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (261, 15, 'Aromatica Rosemary Scalp Scaling Shampoo', 'aromatica-rosemary-scalp-scaling-shampoo', 'Ključne prednosti: Nežna eksfolijacija kože glave: Pomaže uklanjanju viška mrtvih ćelija i nečistoća bez iritacije. Balans i nega temena: Biljni kompleks doprinosi osećaju čistoće, svežine i stabilnosti kože glave. Sjaj i jačina kose: Biotin i pantenol pomažu da kosa deluje jače, mekše i vidljivo sjajnije. Kome je namenjen? Namenjen je svim tipovima kose, posebno osobama sa masnijim ili opterećenim temenom, perutanjem ili nakupljanjem proizvoda na koži glave. Pogodan je i za osetljivu kožu glave zahvaljujući hipoalergenoj, blagoj formuli bez sulfata i silikona. Zašto volimo Aromatica Rosemary Scalp Scaling Shampoo? Ovaj šampon donosi balans između temeljne higijene i nežne nege temena. Ne stvara agresivan osećaj zatezanja, već ostavlja kožu glave osveženom i umirenom. Biljni mirisi daju prirodan, čist senzorski doživljaj tokom pranja. Kosa nakon upotrebe deluje lakše, urednije i bez osećaja težine. Formula je prilagođena redovnoj upotrebi, čak i kod osetljivog temena. Posebno je praktičan kao deo rutine za dugoročno održavanje zdravlja kože glave. Aktivni sastojci LHA (lipohidroksi kiselina) Deluje kao blaga eksfolijativna kiselina koja pomaže uklanjanju mrtvih ćelija sa površine kože glave. Njena prednost je postepeno i kontrolisano delovanje bez nagle iritacije. LHA pomaže u održavanju čistoće folikularnih otvora. Time doprinosi zdravijem okruženju kože glave. Posebno je pogodna za osetljivo teme. U ovom šamponu ima ulogu nežnog, ali efikasnog pilinga. Scalp Enhancer Formula&#x2122; (biljni ekstrakti) Ova biljna kombinacija uključuje ruzmarin, bor, đumbir, bhringraj, bosiljak, korijander i origano. Ekstrakti su pažljivo odabrani zbog svog osvežavajućeg i balansirajućeg delovanja. Njihova uloga je da neguju kožu glave i doprinesu osećaju vitalnosti. Biljna osnova formule pomaže očuvanju prirodne ravnoteže temena. Delovanje je blago i prilagođeno redovnoj upotrebi. Kompleks doprinosi dugoročnom zdravlju kože glave. Biotin U nezi kose koristi se kao sastojak koji doprinosi jačini i otpornosti vlasi. Pomaže da kosa izgleda urednije i snažnije. Njegovo delovanje je usmereno na dugoročnu podršku kvalitetu kose. Ne deluje trenutno, ali doprinosi stabilnosti rutine nege. Često se koristi kod oslabljene kose. U ovom šamponu ima potporni efekat. Pantenol Deluje kao humektant koji pomaže zadržavanje vlage u kosi. Doprinosi mekoći i sjaju vlasi nakon pranja. Pomaže u smanjenju osećaja suvoće temena i kose. Kosa nakon upotrebe deluje podatnije i lakša za stilizovanje. Pantenol je poznat po dobroj podnošljivosti. U ovoj formuli ima ulogu hidratacije i zaglađivanja. Dodaj u listu želja Dodaj u listu želja', 'Aromatica Rosemary Scalp Scaling Shampoo je blagi, ali efikasan šampon namenjen čišćenju i balansiranju kože glave uz istovremenu negu kose. Kombinuje nežnu LHA eksfolijaciju, biljne ekstrakte i hidratantne sastojke kako bi uklonio višak mrtvih ćelija sa temena, osvežio kožu glave i ostavio kosu sjajnom i zdravog izgleda.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Aromatica-Rosemary-Scalp-Scaling-Shampoo-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
