INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (265, 15, 'Aromatica Embrace Neroli & Patchouli Body Wash', 'aromatica-embrace-neroli-patchouli-body-wash', 'Ključne prednosti: Blago i efikasno čišćenje: Uklanja nečistoće sa kože bez isušivanja i narušavanja njenog prirodnog balansa. Aromaterapijski efekat: Mirisi nerolija i pačulija doprinose smirenju uma i stvaranju osećaja opuštenosti tokom tuširanja. Pogodan za svakodnevnu upotrebu: Gelasta tekstura je prijatna za kožu i prilagođena redovnom korišćenju kod svih tipova kože. Kome je namenjen? Namenjen je svim tipovima kože kao proizvod za svakodnevnu higijenu tela. Posebno odgovara osobama koje žele da tuširanje pretvore u smirujući ritual i umanje osećaj napetosti tokom dana. Zašto volimo Aromatica Embrace Neroli & Patchouli Body Wash? Ovaj gel za tuširanje ne ostaje samo na funkciji čišćenja, već donosi i senzorno iskustvo koje menja doživljaj svakodnevne rutine. Topla voda oslobađa mirisne note koje se postepeno razvijaju na koži i u prostoru, stvarajući osećaj privatnog spa trenutka. Kombinacija cvetnog nerolija i zemljanog pačulija deluje umirujuće, ali istovremeno stabilizujuće. Tekstura se lako peni i ispira, bez osećaja zatezanja nakon tuširanja. Miris se zadržava diskretno i nenametljivo. Proizvod je veganski i formulisan bez sastojaka životinjskog porekla. Aktivni sastojci Eterično ulje nerolija Poznato je po svom blagom, cvetnom mirisu koji deluje umirujuće na čula. Njegova aromatična komponenta doprinosi smanjenju osećaja napetosti i emocionalne uznemirenosti. Neroli se u aromaterapiji povezuje sa osećajem smirenosti i pozitivnog raspoloženja. Tokom tuširanja pomaže stvaranju opuštajuće atmosfere. Njegovo delovanje je suptilno, ali primetno kroz celokupno iskustvo korišćenja proizvoda. U ovom gelu za tuširanje neroli ima primarno senzornu i umirujuću ulogu. Eterično ulje pačulija Ima karakterističan, zemljani miris koji deluje stabilizujuće i prizemljujuće. U aromaterapijskom smislu povezuje se sa osećajem sigurnosti i prisutnosti u trenutku. Pačuli doprinosi balansu mirisne kompozicije, sprečavajući da cvetne note budu previše dominantne. Njegov miris ostavlja dugotrajniji, topao trag na koži. Pomaže u stvaranju osećaja mentalne stabilnosti i opuštanja. U kombinaciji sa nerolijem daje harmoničan i zaokružen mirisni profil. Dodaj u listu želja Dodaj u listu želja', 'Aromatica Embrace Neroli & Patchouli Body Wash je gel za tuširanje koji čisti kožu dok istovremeno deluje umirujuće na čula zahvaljujući pažljivo odabranoj aromaterapijskoj kombinaciji nerolija i pačulija. Namenjen je svakodnevnoj upotrebi i pruža blago, ali efikasno čišćenje uz mirisni doživljaj koji pomaže opuštanju i mentalnom balansu.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Aromatica-Embrace-Neroli-Patchouli-Body-Wash-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
