INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (266, 14, 'Arencia Honey Glazed Collagen Lip Mask', 'arencia-honey-glazed-collagen-lip-mask', 'Ključne prednosti: Dubinska hidratacija i omekšavanje: Pruža produženu vlažnost i smanjuje osećaj suvoće i zatezanja usana. Podrška elastičnosti i punoći: Poboljšava glatkoću i vizuelno zaglađuje teksturu usana. Jačanje zaštitne barijere: Pomaže u sprečavanju gubitka vlage zahvaljujući ceramidima. Kome je namenjena? Namenjen je svim tipovima usana, posebno suvim, ispucalim i usnama sklonim gubitku vlažnosti. Odgovara osobama koje žele negu sa vizuelno zaglađujućim i sjajnim efektom, bez potrebe za klasičnim balzamom ili sjajem za usne. Zašto volimo Arencia Honey Glazed Collagen Lip Mask? Tekstura maske je bogata, ali prijatna, i ostavlja efekat negovanih, sjajnih usana bez lepljivog osećaja. Formula je osmišljena da deluje višeslojno, hidrira površinu i istovremeno pomaže zadržavanje vlage u dubljim slojevima kože usana. Redovnom upotrebom usne deluju mekše, glađe i otpornije na spoljašnje uticaje. Sjajna, blago ružičasta nijansa daje prirodan izgled bez izražene boje. Proizvod je namenjen i dnevnoj i noćnoj nezi, u zavisnosti od potreba. Posebno je koristan tokom perioda pojačane suvoće, kao što su hladno vreme ili klimatizovani prostori. Aktivni sastojci Ekstrakt meda Deluje kao prirodni humektant koji privlači i zadržava vlagu u koži usana. Njegova uloga je da smanji osećaj suvoće i doprinese dugotrajnijem osećaju prijatnosti. Med pomaže u očuvanju mekoće i elastičnosti kože usana. Takođe doprinosi zaštiti površine usana od spoljašnjih uticaja. Njegovo delovanje je blago i pogodno za svakodnevnu upotrebu. U formulaciji maske med ima ulogu hranljivog i zaštitnog sastojka. Kolagen U kozmetičkim formulama ima primarno hidratantnu i zaglađujuću ulogu. Na površini usana stvara tanak film koji pomaže zadržavanje vlage i smanjuje hrapavost. Doprinosi vizuelno punijem i glađem izgledu usana. Ne prodire duboko u kožu, ali značajno utiče na osećaj mekoće. Redovnom upotrebom pomaže da usne izgledaju negovanije i ujednačenije. Njegova prisutnost je ključna za efekat glatkih i elastičnih usana. Ceramidi (5 tipova) Ceramidi su lipidi prirodno prisutni u kožnoj barijeri i imaju važnu ulogu u njenom očuvanju. U ovoj maski pomažu jačanje zaštitnog sloja usana i smanjenje transepidermalnog gubitka vode. Njihovo delovanje doprinosi dugotrajnijoj hidrataciji, čak i nakon što se proizvod ukloni. Ceramidi pomažu obnavljanje oštećene barijere kod suvih i ispucalih usana. Formulacija sa više tipova ceramida omogućava potpuniju podršku barijernoj funkciji. Ovo je posebno važno kod usana koje su često izložene vetru, hladnoći ili čestim mat ruževima. Dodaj u listu želja Dodaj u listu želja', 'Arencia Honey Glazed Collagen Lip Mask je hranljiva maska za usne formulisana da intenzivno hidrira, omekša i vizuelno poboljša punoću suvih i ispucalih usana. Kombinuje med, kolagen i pet tipova ceramida kako bi unapredila elastičnost, ojačala barijeru usana i obezbedila dugotrajnu vlažnost uz prirodno sjajnu završnicu.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Arencia-Honey-Glazed-Collagen-Lip-Mask-5.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
