INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (269, 114, 'Medicube Exosome Cica Toner', 'medicube-exosome-cica-toner', 'Ključne prednosti: Intenzivno umirenje iritacija: nano-Exosome Cica deluje 5.3× snažnije od klasične cice i brzo smanjuje crvenilo, osetljivost i neprijatnost. Dugotrajna hidratacija: ektoin i pantenol zaključavaju vlagu i obnavljaju narušenu barijeru. Poboljšanje teksture kože: tonik utiče na regulaciju sebuma, smanjuje broj i izraženost pora i doprinosi glađoj, ujednačenijoj površini kože. Kome je namenjen? Idealno za osetljivu, reaktivnu, iritiranu, masnu, kombinovanu i kožu sklonu crvenilu. Savršen izbor za osobe koje žele da umire kožu nakon aktivnih sastojaka, tretmana ili spoljašnjih stresora, ali i za one kojima je potrebna snažnija barijerna podrška uz kontrolu sebuma. Zašto volimo Medicube Exosome Cica Toner? Zato što je ovo jedan od najnaprednijih Cica tonera — nano-Exosome kompleks je mikroskopski sitan (1/510 veličine pore), pa deluje dublje i brže od klasične cice. Kombinacija 12 Cica derivata, ektoina i pantenola pruža vidljivo smirenje u roku od nekoliko minuta. Formula je neverovatno nežna, bez mirisa i bez iritansa, a rezultat je koža koja izgleda hidrirano, bistro, sveže i stabilizovano. Aktivni sastojci Exosome Cica Napredna, nano-veličine cica koja je 5.3× snažnija od standardne — brzo smanjuje crvenilo, osetljivost i iritacije, dok obnavlja kožnu barijeru. 12 vrsta Cica kompleksa Asiatic acid, madecassic acid, centella ekstrakti i njihovi derivati rade zajedno da smire kožu, ojačaju barijeru i ubrzaju regeneraciju. Ektoin Molekul koji štiti ćelije od stresa, balansira vlagu i pojačava otpornost kože u izazovnim uslovima (vetar, UV, suva klima). Panthenol Umiruje, hidrira i obnavlja barijeru, smanjuje osećaj zatezanja i pomaže oporavku iritacija. Tea Tree Leaf Water Daje nežno balansiranje sebuma i dodatno umiruje kožu bez isušivanja. Dodaj u listu želja Dodaj u listu želja', 'Medicube Exosome Cica Toner je umirujući, lagan i visoko efikasan tonik formulisan sa čak 12 vrsta Cica ekstrakata, nano-Exosome Cica kompleksom, ektoinom i pantenolom. Ovaj toner trenutno hidrira, umiruje i obnavlja kožu, dok smanjuje sebum, poboljšava teksturu i jača barijernu funkciju. Idealno rešenje za osetljivu, iritiranu ili reaktivnu kožu kojoj je potrebno brzo i dubinsko smirenje — bez parfema i bez iritansa.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Medicube-Exosome-Cica-Toner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
