INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (270, 118, 'Missha Time Revolution Night Repair Ampoule Mask', 'missha-time-revolution-night-repair-ampoule-mask', 'Ključne prednosti: Intenzivna anti-age regeneracija: 77,2% Extreme Biome&#x2122; jača kožu, podstiče oporavak i poboljšava otpornost. Vidljivo odmorna koža: ublažava znake umora i vraća svež, „well-rested“ izgled. Poboljšava 10 različitih znakova starenja: uključujući elastičnost, čvrstinu, teksturu, fine linije i bore. Kome je namenjena? Idealna je za kožu koja deluje umorno, dehidrirano, bez sjaja ili sa izraženim znacima starenja. Preporučuje se svim tipovima kože kojima je potrebna snažna regeneracija, veća elastičnost i glatkija tekstura. Zašto volimo Missha Time Revolution Night Repair Ampoule Mask? Zato što objedinjuje moć fermenta i luksuznu, bogatu esenciju u maski koja daje trenutne i vidljive rezultate. Koža izgleda odmornije, punije i zategnutije, kao da ste prespavali dodatnih 8 sati. Maska nudi sve benefite kultne Time Revolution ampule – u formi jednostavne, jednokratne obloge. Aktivni sastojci Extreme Biome&#x2122; (77,2%) Kompleks od 10 fermentisanih sastojaka koji jačaju barijeru, podstiču regeneraciju i poboljšavaju elastičnost kože. Extreme Ferment α&#x2122; tehnologija Poboljšava stabilnost, penetraciju i efikasnost svih aktivnih sastojaka, omogućavajući brže i vidljivije rezultate. Hidratantni kompleksi iz fermenta Dubinski obnavljaju nivo vlage i pružaju dugotrajan osećaj punoće. Dodaj u listu želja Dodaj u listu želja', 'Missha Time Revolution Night Repair Ampoule Mask je intenzivna anti-age sheet maska obogaćena sa 77,2% Extreme Biome&#x2122; kompleksa – snažne mešavine 10 fermentisanih sastojaka koji dubinski hidriraju, obnavljaju i revitalizuju kožu. Zahvaljujući višeslojnoj strukturi maske, esencija ostaje zaključana unutar vlakana i ravnomerno se oslobađa, pružajući koži vidljivo odmoran, elastičan i zaglađen izgled već nakon jedne upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/12/Missha-Time-Revolution-Night-Repair-Ampoule-Mask.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
