INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (276, 154, 'Skin1004 Madagascar Centella Hyalu-Cica Gentle Cleansing Milk', 'skin1004-madagascar-centella-hyalu-cica-gentle-cleansing-milk', 'Ključne prednosti: Efikasno uklanjanje šminke i nečistoća: mlečna tekstura rastapa prljavštinu i mrtve ćelije bez trljanja. Dubinska hidratacija i umirenje: panthenol i beta-glukan obnavljaju vlagu i smanjuju osećaj zategnutosti. Jačanje kožne barijere: ceramidi, biljni proteini-peptidi i vitamin E čuvaju vlažnost i otpornost kože. Kome je namenjen? Ovaj čistač je idealan za normalnu, suvu, kombinovanu i osetljivu kožu kojoj je potrebno nežno čišćenje bez isušivanja. Preporučuje se osobama sa osetljivom barijerom, kožom sklonom crvenilu, dehidrataciji, kao i onima koji žele da održe mekoću i hidriran izgled nakon čišćenja. Zašto volimo Skin1004 Madagascar Centella Hyalu-Cica Gentle Cleansing Milk? Zato što pruža savršen balans između efikasnosti i nežnosti — uklanja sve što koži ne treba, dok joj istovremeno vraća vlagu i udobnost. Zahvaljujući mlečnoj, glatkoj teksturi, koža se čisti bez napora i bez osećaja zategnutosti. Ceramidi, vitamin E i peptidi ojačavaju barijeru, a panthenol i beta-glukan smiruju crvenilo. Rezultat je čista, mekana i dubinski nahranjena koža već nakon jednog pranja. Aktivni sastojci Pantenol Pruža snažno umirujuće i hidratantno dejstvo, smanjuje iritacije i obnavlja kožnu barijeru. Odličan je za osetljivu i reaktivnu kožu kojoj je potrebna dodatna zaštita. Beta-glukan Intenzivno vezuje vodu, smanjuje crvenilo i poboljšava elastičnost kože. Deluje kao snažan „skin soother“ koji vraća osećaj komfora. Ceramidi Obnavljaju lipidnu barijeru, sprečavaju transepidermalni gubitak vode i čine kožu jačom, otpornijom i dugotrajno hidriranom. Biljni proteini – peptidi Podržavaju kožnu strukturu, poboljšavaju tonus i doprinose glatkoći. Jačaju kožu tokom čišćenja i sprečavaju oštećenja barijere. Vitamin E Antioksidans koji štiti od spoljašnjih stresora, hrani kožu i sprečava isušivanje. Doprinosi mekoći i elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Hyalu-Cica Gentle Cleansing Milk je nežno, mlečno sredstvo za čišćenje koje uklanja nečistoće, šminku i mrtve ćelije bez narušavanja prirodne vlažnosti kože . Obogaćeno ceramidima, peptidima, beta-glukanom i vitaminom E, ovo mleko za čišćenje istovremeno neguje, umiruje i jača barijeru, ostavljajući kožu mekom, hidriranom i vidljivo smirenom. Idealno je za osetljivu kožu kojoj je potrebna maksimalna nežnost uz potpuno čišćenje.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Skin1004-Madagascar-Centella-Hyalu-Cica-Gentle-Cleansing-Milk-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
