INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (277, 154, 'Skin1004 Madagascar Centella Probio-Cica Nourishing Mask', 'skin1004-madagascar-centella-probio-cica-nourishing-mask', 'Ključne prednosti: Dubinska hidratacija i obnova: bogata esencija vraća vlagu i pruža dugotrajnu mekoću. Podrška čvrstoći kože: 9-peptidni kompleks vidljivo poboljšava elastičnost. Jačanje kožne barijere: ceramidi sprečavaju transepidermalni gubitak vode. Kome je namenjena? Ova maska je odlična za suvu, normalnu, kombinovanu i osetljivu kožu kojoj nedostaje hidratacija, punoća i umirenje. Idealna je za kožu koja je nadužena vetrom, hladnoćom, iritacijama, preteranim korišćenjem aktivnih sastojaka ili jednostavno izgleda umorno i beživotno. Zašto volimo Skin1004 Madagascar Centella Probio-Cica Nourishing Mask? Zato što kombinuje sve što je neophodno za “instant oporavak” kože: fermentisana centela smanjuje reaktivnost i poboljšava upijanje, ceramidi obnavljaju barijeru, a 9-peptidni kompleks vraća mladalačku elastičnost. Esencija je bogata, ali ne lepljiva, a sheet je mekan i izuzetno prijatan. Rezultat je vidljivo smirenija, hidriranija i čvršća koža već nakon jednog korišćenja. Aktivni sastojci Fermentisana Centella Asiatica Extract Proces fermentacije povećava biodostupnost centelle, što omogućava dublju apsorpciju i snažnije umirenje. Pomaže u smanjenju crvenila, iritacija i oštećenja barijere, dok istovremeno podržava regeneraciju kože. Ceramidi Neophodni lipidi koji jačaju zaštitnu barijeru kože, sprečavaju gubitak vlage i doprinose mekoći, otpornosti i dugotrajnoj hidrataciji. 9-Peptidni kompleks Snažna kombinacija peptida koji stimulišu elastičnost, poboljšavaju tonus i podržavaju gladak, čvrst i revitalizovan izgled kože. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Probio-Cica Nourishing Mask je dubinski hranljiva sheet maska koja kombinuje fermentisanu madagaskarsku centelu , ceramide i 9-peptidni kompleks kako bi koži pružila intenzivnu hidrataciju, obnovu i poboljšanje elastičnosti. Zahvaljujući ultra-mekanoj tkanini, maska prijanja uz lice i omogućava optimalnu apsorpciju aktivnih sastojaka čak i kod najosetljivije kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Skin1004-Madagascar-Centella-Probio-Cica-Nourishing-Mask-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
