INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (278, 143, 'Round Lab Soybean Panthenol Cleanser', 'round-lab-soybean-panthenol-cleanser', 'Ključne prednosti: Temeljno, a nežno čišćenje: efikasno uklanja SPF, nečistoće i sebum bez narušavanja barijere. Dubinska hidratacija: pantenol u niosome prodire dublje i sprečava osećaj suvoće posle umivanja. Očvršćavanje barijere: ceramidi, holesterol i masne kiseline obnavljaju zaštitni lipidni sloj. Kome je namenjen? Ovaj čistač je idealan za osetljivu, suvu, normalnu i mešovitu kožu kojoj smetaju agresivni surfaktanti ili osećaj zatezanja posle pranja. Pogodan je za kožu sa narušenom barijerom, sklonu iritacijama, crvenilu, perutanju ili preteranoj suvoći. Odličan je i za jutarnje i za večernje čišćenje. Zašto volimo Round Lab Soybean Panthenol Cleanser? Zato što kombinuje visok nivo hidratacije sa izuzetnom nežnošću: pantenol u niosomima prodire dublje od standardnog panthenola, dok ekstrakt crnog sočiva omogućava dodatnu smirenost i balans. Formula bogata lipidima održava barijeru jakom čak i nakon čišćenja, što je retko kod pena za umivanje. Tekstura je meka, kremasta i formira penu koja čisti bez isušivanja — idealno za svakodnevnu upotrebu. Aktivni sastojci Pantenol u niosomima Niosomi su ultra-male lipidne kapsule koje „nose“ pantenol dublje u kožu, pa se on efikasnije apsorbuje, sporije oslobađa i manje iritira. Zahvaljujući ovoj tehnologiji, pantenol duže ostaje u koži, jača barijeru i bolje umiruje osetljivu ili oštećenu kožu. Ekstrakt crnog sočiva (Glycine Max Seed Extract) Bogato antioksidantima i aminokiselinama, umiruje kožu, pruža anti-stres efekat, hidrira i pomaže u obnovi povređene barijere. Ceramidi, holesterol i masne kiseline Rekonstruišu lipidnu barijeru kože, sprečavaju gubitak vode i poboljšavaju otpornost kože na spoljne iritanse. Niska pH pena Održava optimalnu acidnu ravnotežu kože, minimizuje iritaciju i ne narušava zaštitni sloj kože. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Soybean Panthenol Cleanser je izuzetno nežan, hidratantan čistač namenjen osetljivoj koži kojoj je potrebna maksimalna zaštita tokom čišćenja. Kombinuje pantenol u niosomima (nano-veličine za bolju apsorpciju), ekstrakt crnog sočiva i barijerne lipide kako bi temeljno uklonio SPF, nečistoće i višak sebuma — bez isušivanja i zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-Soybean-Panthenol-Cleanser-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
