INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (279, 143, 'Round Lab Camellia Deep Collagen Jelly Mask Cleanser', 'round-lab-camellia-deep-collagen-jelly-mask-cleanser', 'Ključne prednosti: Čišćenje + elastičnost u jednom koraku: uklanja nečistoće, šminku i fini prašak, dok istovremeno poboljšava tonus kože. Blagi piling bez iritacije: konjac scrub i pahuljice cveta kamelije uklanjaju mrtve ćelije i zaglađuju teksturu. Intenzivna hidratacija: visok procenat elasticirajućih i ovlažujućih sastojaka sprečava isušivanje. Kome je namenjen? Ovaj čistač je idealan za sve koji žele dubinsko, ali nežno čišćenje uz dodatnu anti-age i hidratantnu negu. Preporučuje se za normalnu, suvu, mešovitu i umornu kožu kojoj nedostaju elastičnost, sjaj i ujednačena tekstura. Pogodan je i za osetljivu kožu zbog blagih eksfolijantnih komponenti. Zašto volimo Round Lab Camellia Deep Collagen Jelly Mask Cleanser? Zato što spaja tri koraka — čišćenje, piling i podmlađivanje — u jednoj luskuznoj, želatinastoj teksturi. Kamalijin kompleks, konjac scrub i hidratantni ekstrakti čine da koža bude čista, mekana i zategnuta, bez osećaja zatezanja ili suvog filma. Efekat nakon ispiranja je kao da ste uradili laganu masku za elastičnost. Aktivni sastojci Camellia Colagenol™ (ekstrakt cveta kamelije, kvercetin, inozitol) Kompleks koji jača elastičnost kože, podržava sintezu kolagena i poboljšava čvrstoću i punoću kože. Konjac jelly scrub Prirodni, ultra nežni piling koji uklanja mrtve ćelije i zaglađuje površinu kože bez iritacije. Camelia Japonica Flower flakes Cvetne pahuljice koje dodatno omekšavaju, hidriraju i neguju kožu tokom čišćenja. Hidratantno-elastični sastojci (86%) Kompleks sastojaka dizajniran da spreči isušivanje, poboljša mekoću i održi elastičnost kože čak i nakon ispiranja. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Camellia Deep Collagen Jelly Mask Cleanser je inovativni gel-čistač sa želatinastom teksturom koji kombinuje čišćenje, blagi piling i anti-age negu u jednom koraku. Sa čak 86% elastičnih i hidratantnih sastojaka, ovaj proizvod uklanja nečistoće, fini prašak i šminku, dok istovremeno jača elastičnost kože i ostavlja je hidriranom i svežom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-Camellia-Deep-Collagen-Jelly-Mask-Cleanser-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
