INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (280, 143, 'Round Lab 1025 Dokdo Cleansing Balm', 'round-lab-1025-dokdo-cleansing-balm', 'Ključne prednosti: Temeljno čišćenje pora: uklanja blackhead-e, whitehead-e, sebum i vodootpornu šminku. Hidratantna zaštita kože: 5 ceramida i biljna ulja sprečavaju isušivanje i jačaju barijeru. Hemijska + fizička glatkoća: LHA i PHA uklanjaju mrtve ćelije i zaglađuju teksturu. Kome je namenjen? Ovaj balzam je savršen za sve tipove kože, naročito za one koji žele da temeljno uklone šminku i nečistoće bez isušivanja. Preporučuje se kod kombinovane, masnije, dehidrirane i osetljive kože, kao i za sve koji imaju nepravilnosti i začepljene pore. Zašto volimo Round Lab 1025 Dokdo Cleansing Balm? Zato što spaja vrhunsku efikasnost i izuzetnu nežnost. Ova formula zadržava vlagu zahvaljujući ceramidima i biljnim uljima (suncokret, noćurak), dok istovremeno čisti pore modernim eksfolijantima (LHA + PHA). Sorbe-tekstura se topi savršeno glatko i ostavlja kožu čistom, mekanom i nahranjenom — bez masnog filma i bez težine. Aktivni sastojci Dubinska morska voda Bogata mineralima, pomaže u održavanju optimalne hidratacije i umiruje kožu. 5 vrsta ceramida Ojačavaju kožnu barijeru, sprečavaju transepidermalni gubitak vode i povećavaju elastičnost kože. Biljna ulja (suncokret, ulje noćurka i dr.) Nježno otapaju šminku i sebum, dok istovremeno hrane i omekšavaju kožu. LHA (Capryloyl Salicylic Acid) Nežan eksfolijant koji čisti pore i poboljšava teksturu bez iritacije. PHA Dodatno uklanja mrtve ćelije, čini kožu glatkijom i pogodniji je za osetljive tipove. HATHING EX-07 kompleks Formula za glatkoću i obnovu kože koja podržava efikasno čišćenje. Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Cleansing Balm je nežan, ali izuzetno efikasan balzam za čišćenje koji se topi na koži i uklanja čak i vodootpornu šminku, nečistoće, blackhead-e i višak sebuma — a sve to bez isušivanja i bez začepljenja pora. Obogaćen je dubinskom morskom vodom, biljnim uljima i snažnim hidratantno-umirujućim kompleksima, što ga čini idealnim za svakodnevnu upotrebu, pa čak i za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-1025-Dokdo-Cleansing-Balm-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
