INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (281, 143, 'Round Lab Pine Calming Cica Cleanser', 'round-lab-pine-calming-cica-cleanser', 'Ključne prednosti: Nežno, efikasno čišćenje: lagana, kremasta pena uklanja nečistoće bez narušavanja barijere kože. LHA + salicilna kiselina: blago eksfoliraju, čiste pore i sprečavaju nakupljanje sebuma. Intenzivno smirivanje: centella, asiatic acid i madecassic acid ublažavaju crvenilo i iritacije. Hidratacija na više nivoa: hijaluronske kiseline različitih molekula dubinski pune vlagom. Bez mirisa, bez iritacije: idealno za osetljivu, suvu i narušenu kožu. Kome je namenjen? Ovaj čistač je savršen za osetljivu, reaktivnu, suvu ili kombinovanu kožu, kao i za sve koji žele blagi dnevni čistač koji kontroliše sebum bez isušivanja. Preporučuje se osobama sklonim zapušenim porama, crvenilu, dehidrataciji ili narušenoj kožnoj barijeri. Zašto volimo Round Lab Pine Calming Cica Cleanser? Zato što pruža retku kombinaciju: temeljno čišćenje i istovremenu hidrataciju. Pena je meka, bogata i ne isušuje kožu; LHA deluje sporije i nežnije od AHA/BHA, što ga čini savršenim za svakodnevnu upotrebu. Centella i zeleni čaj odmah smiruju, dok hijaluronske kiseline ostavljaju kožu punom, elastičnom i svežom. Aktivni sastojci Glicerin Ovlaživač koji vezuje vlagu i sprečava isušivanje tokom čišćenja. Camellia Sinensis (zeleni čaj) Leaf Extract Snažan antioksidans koji umiruje, smanjuje oksidativni stres i pomaže kod crvenila. Salicilna kiselina + LHA (Capryloyl Salicylic Acid) BHA duo koji nežno otčepljuje pore, uklanja višak sebuma i zaglađuje teksturu kože. Centella Asiatica Leaf Extract Smiruje iritacije, regeneriše kožu i ubrzava oporavak osetljivih zona. Asiatic Acid & Madecassic Acid Dva najaktivnija derivata centelle — ublažavaju crvenilo, jačaju barijeru i smanjuju nadraženost. Hyaluronic Acid (različite molekulske težine) Hidrira u više slojeva kože, ostavljajući je punijom, mekšom i bez osećaja zatezanja. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Pine Calming Cica Cleanser je nežna pena koja kombinuje LHA i salicilnu kiselinu za blago uklanjanje mrtvih ćelija i održavanje čistih pora, dok centella, zeleni čaj i hijaluronske kiseline pružaju hidrataciju i smiruju crvenilo. Idealno za svakodnevnu upotrebu, posebno kod osetljive i reaktivne kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-Pine-Calming-Cica-Cleanser-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
