INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (282, 143, 'Round Lab Soybean Cleansing Oil', 'round-lab-soybean-cleansing-oil', 'Ključne prednosti: Nežno uklanjanje šminke i SPF-a: otapa i najotpornije formule bez trenja i povlačenja kože. Biljna ulja visoke tolerancije: avokado, grožđe, noćurak i meadowfoam pružaju umirujući efekat i lipidnu podršku. Dubinska hidratacija: glicerin i ceramid NP sprečavaju isušivanje i jačaju kožnu barijeru. Podrška protiv crnih tačkica: formulacija pomaže razlaganje sebuma u porama i smanjuje nakupljanje nečistoća. Antimikrobno i antioksidativno dejstvo: ruzmarinovo ulje čisti i štiti kožu od iritacija. Kome je namenjen? Ulje je idealno za sve tipove kože, uključujući suvu, dehidriranu i osetljivu kožu koja lako reaguje na agresivna sredstva za čišćenje. Preporučuje se i osobama koje se bore sa crnim tačkicama, začepljenim porama ili osećajem zatezanja nakon umivanja — kao i svima koji žele bogato, ali nemasno čišćenje. Zašto volimo Round Lab Soybean Cleansing Oil? Zato što uspeva da spoji dve stvari koje retko idu zajedno: dubinsko čišćenje i izuzetnu njegu. Ulja prirodnog porekla istovremeno otapaju nečistoće i hrane kožu, dok ceramid NP jača barijeru i sprečava isušivanje. Tekstura je lagana, lako se emulzifikuje i ne ostavlja masni film — samo mek, gladak i umiren ten. Aktivni sastojci Avokadovo, ulje koštica grožđa, ulje noćurka i meadowfoam ulje Mešavina biljnih ulja bogatih esencijalnim masnim kiselinama i antioksidansima. Umiruju iritacije, hrane kožu i balansiraju sebum, dok doprinose lakšem otapanju šminke i nečistoća. Helianthus Annuus (Sunflower) Seed Oil Stvara srednje tešku lipidnu barijeru koja sprečava gubitak vlage i čini kožu mekšom i otpornijom. Glicerin Humektant koji privlači i zadržava vlagu u koži, sprečava isušivanje i obnavlja hidrataciju čak i nakon ispiranja. Ceramide NP Ojačava kožnu barijeru, smanjuje osetljivost i pomaže koži da zadrži vlagu i otpornost na spoljašnje agresore. Rosmarinus Officinalis (Rosemary) Leaf Oil Ima antioksidativna, antimikrobna i umirujuća svojstva. Pomaže u ublažavanju iritacija, štiti kožu i doprinosi čišćoj, uravnoteženoj površini. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Soybean Cleansing Oil je nežno, hranljivo ulje za čišćenje koje uklanja SPF, šminku i dubinske nečistoće bez zatezanja kože i bez narušavanja njene prirodne barijere. Formulisano je sa pažljivo biranim biljnim uljima, ceramidom i glicerinom koji koži pružaju hidrataciju, elastičnost i zaštitu tokom čišćenja. Idealan je za svakodnevnu upotrebu — posebno za one koji žele temeljno čišćenje uz maksimalnu udobnost.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-Soybean-Cleansing-Oil-4.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
