INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (283, 143, 'Round Lab Dokdo Cleansing Oil', 'round-lab-dokdo-cleansing-oil', 'Ključne prednosti: Temeljno, a nežno čišćenje: uklanja sve tipove šminke, SPF i nečistoće bez iritacije i zatezanja. Mineralna hidratacija i balans: dubinska morska voda bogata magnezijumom, kalcijumom i cinkom vraća koži prirodni balans i vlagu. Zaštita barijere: ceramid NP obnavlja lipidni sloj i sprečava gubitak vlage. Kome je namenjen? Ovo ulje je idealno za sve tipove kože, uključujući osetljivu, reaktivnu i dehidriranu kožu. Preporučuje se osobama koje žele nežno, ali potpuno uklanjanje šminke i SPF-a, kao i onima koji imaju narušen balans kože, začepljene pore, povremene iritacije ili sklonost ka suvoći nakon čišćenja. Zašto volimo Round Lab 1025 Dokdo Cleansing Oil? Zato što kombinuje vrhunsko čišćenje sa mineralnom negom i zaštitom barijere — što je retkost kod klasičnih ulja za čišćenje. Ne ostavlja film, ne pecka oči i daje osećaj lagane, čiste i hidrirane kože. Savršena je prva faza duplog čišćenja i jedan od najprodavanijih proizvoda brenda upravo zbog svoje efikasnosti i prijatne, balansirane formule. Aktivni sastojci Dubinska morska voda (72 prirodna minerala) Prirodna voda sa ostrva Dokdo bogata magnezijumom, kalcijumom i cinkom. Održava nivo vlage, umiruje kožu i poboljšava njen zaštitni mehanizam. Mineralni balans doprinosi elastičnosti, boljem tonusu i blistavijem izgledu. Ceramide NP Ključni lipid koji jača kožnu barijeru i sprečava transepidermalni gubitak vode. Pomaže koži da zadrži vlagu, čini je otpornijom i smanjuje osetljivost nakon čišćenja. Ulje noćurka (Evening Primrose Oil) Bogato gama-linolenskom kiselinom, izuzetno umirujuće i antioksidativno. Ublažava suvoću, iritacije i crvenilo, naročito kod osetljive kože. Bergamot ulje Pročišćava kožu, deluje antiseptično i pomaže u regulaciji sebuma. Odlčno za blago problematičnu kožu i ujednačavanje teksture. Ulje žalfije (Sage Oil) Smiruje nadraženost i balansira masnoću, dok antibakterijska svojstva doprinose čistijoj i ujednačenijoj koži. Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Cleansing Oil je lagano, luksuzno ulje za čišćenje koje potpuno uklanja šminku, SPF, višak sebuma i dubinske nečistoće, a pritom čuva kožnu barijeru zahvaljujući bogatstvu minerala i hidratantnih sastojaka. Formulisan je sa dubinskom morskom vodom sa ostrva Dokdo, ceramidima i biljnim uljima koja ne iritiraju i ne ostavljaju masan trag. Prilikom kontakta sa vodom, pretvara se u mlečnu emulziju koja temeljno čisti i hidrira kožu bez zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/1025-dokdo-cleansing-oil-round-lab-2_d7899cc8-a87c-4002-8770-38492e1f5e51.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
