INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (284, 143, 'Round Lab 1025 Dokdo Sleeping Pack', 'round-lab-1025-dokdo-sleeping-pack', 'Ključne prednosti: Noćna obnova i hidratacija: intenzivno nadoknađuje vlagu i smiruje upaljenu ili iziritiranu kožu tokom sna. Blaga PHA eksfolijacija: uklanja višak sebuma i odumrle ćelije za glatkiju i puniju teksturu kože. Ravnoteža kože zahvaljujući mineralima: dubinska morska voda pomaže u održavanju stabilnog odnosa vode i ulja. Kome je namenjen? Ova noćna maska je pogodna za sve tipove kože, uključujući osetljivu i dehidriranu. Posebno se preporučuje osobama sa iritacijama, crvenilom, površinskom dehidratacijom, neravnom teksturom ili viškom sebuma, kao i onima koji preferiraju jednostavniju rutinu — jedan proizvod koji hidrira, umiruje i blago eksfolira. Zašto volimo Round Lab 1025 Dokdo Sleeping Pack? Zato što omogućava kvalitetnu noćnu hidrataciju bez težine, istovremeno pružajući blagi piling koji ne iritira čak ni reaktivnu kožu. Minerali iz dubinske morske vode doprinose balansu kože, a pantenol i glicerin pružaju dubinsku vlagu i mekoću do jutra. Derma-CLOCK&#x2122; tehnologija dodatno podržava prirodni ritam kože, što rezultira odmornim, čistijim i svežijim tenom. Gelasta tekstura se brzo upija, ne lepi se i može se rashladiti u frižideru za jači umirujući efekat. Aktivni sastojci Pantenol (provitamin B5) Pantenol prodire u površinske slojeve kože gde se pretvara u pantotensku kiselinu, ključnu za očuvanje barijere. Pomaže smanjenju iritacija i crvenila, istovremeno jačajući zadržavanje vlage. Poboljšava elastičnost i umiruje kožu izloženu spoljašnjim stresorima. Redovnom upotrebom doprinosi glatkijem i stabilnijem tenu. Posebno je koristan za osetljivu i reaktivnu kožu. Pomaže u sprečavanju transepidermalnog gubitka vode tokom noći. Glicerin Glicerin je snažan humektans koji privlači vlagu iz dubljih slojeva kože i okoline, čineći kožu mekšom i elastičnijom. U ovoj formuli doprinosi održavanju hidratacije tokom celog noćnog ciklusa. Stvara zaštitni sloj bez težine i masnog osećaja. Poboljšava glatkoću i otpornost kože. Posebno je efikasan kada se kombinuje sa pantenolom i mineralima. Pomаže da se koža probudi hidrirana i umirena. Kirilowii root extract Ekstrakt korena ove tradicionalne biljke koristi se zbog svojih umirujućih i antioksidativnih svojstava. Pomaže u smanjenju crvenila i iritacija nastalih usled spoljašnjih uticaja. Podržava prirodne procese obnavljanja kože tokom sna. Doprinosi čistijem i balansiranijem tenu. Blagotvorno utiče na osetljivu kožu sklonu inflamaciji. Uz hidratantne komplekse, pojačava ukupni efekat umirivanja. Dubinska morska voda (Dokdo Island) Ova voda je bogata mineralima koji pomažu u održavanju optimalnog odnosa ulja i vode u koži. Minerali podržavaju metaboličke procese kože i jačaju njenu otpornost. Deluje osvežavajuće i umirujuće. Dugoročno doprinosi hidrataciji i stabilnijem balansu tena. Umiruje osetljivu i reaktivnu kožu. Pomaže koži da se regeneriše tokom noći. PHA (polihidroksi kiseline) PHA kiseline imaju veće molekule od AHA, što ih čini znatno blažim i pogodnim za osetljivu kožu. Ovaj sastojak uklanja mrtve ćelije i višak sebuma bez iritacije. Poboljšava teksturu i čini kožu glađom do jutra. Pomaže u smanjenju sitnih neravnina na površini kože. U rutini doprinosi postepenom, nežnom piling efektu. Omogućava blistav i ujednačen izgled po buđenju.‚ Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Sleeping Pack je umirujuća i intenzivno hidratantna noćna maska koja se nanosi kao poslednji korak rutine, a deluje tokom sna da obnovi vlagu, uravnoteži kožu i umanji iritacije. Formulisana je sa pantenolom, glicerinom, ekstraktom korena kirilowii biljke i blagim PHA kiselinama, što omogućava istovremenu negu, hidrataciju i vrlo blago noćno eksfoliranje za glatku i blistavu kožu ujutru.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-1025-Dokdo-Sleeping-Pack-1-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
