INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (285, 143, 'Round Lab 1025 Dokdo Bubble Foam', 'round-lab-1025-dokdo-bubble-foam', 'Ključne prednosti: Temeljno, ali nežno čišćenje: uklanja prljavštinu, sebum i mrtve ćelije bez narušavanja barijere. Mineralna hidratacija: dubinska morska voda doprinosi održavanju optimalnog nivoa vlažnosti. Umirivanje i zaštita: biljni ekstrakti smanjuju iritacije i održavaju mekoću kože posle čišćenja. Kome je namenjen? Ovaj čistač je odličan izbor za sve tipove kože, uključujući osetljivu, dehidriranu, kombinovanu i kožu sklonu blagim iritacijama. Preporučuje se osobama koje žele nežno čišćenje bez isušivanja, kao i onima koji primenjuju višestepenu rutinu. Zašto volimo Round Lab 1025 Dokdo Bubble Foam? Zato što kombinuje efikasno čišćenje i blag pristup — formula uklanja sve nečistoće, ali koža ostaje smirena, hidrirana i bez osećaja „škripanja“. Dubinska morska voda obogaćuje kožu mineralima, dok aminokiselinski surfaktanti minimizuju transepidermalni gubitak vode. Ekstrakti zelenog čaja, centelle i bergamota čine ovaj čistač idealnim za svakodnevnu rutinu, jer doprinose umirenju, hidrataciji i svežem, mekanom osećaju nakon upotrebe. Aktivni sastojci Dubinska morska voda sa ostrva Ulleungdo Ova voda prirodno je bogata mineralima poput kalcijuma, magnezijuma i kalijuma, koji doprinose održavanju zdrave barijere kože. Ravnoteža minerala omogućava dodatnu hidrataciju i smanjuje osećaj zategnutosti posle čišćenja. Podržava funkciju kože u borbi protiv spoljašnjih stresora. Deluje umirujuće na iritiranu i reaktivnu kožu. Dugoročno doprinosi mekšoj, punijoj i uravnoteženijoj koži. Zahvaljujući blagim karakteristikama, pogodna je i za svakodnevnu upotrebu. Aminokiselinski surfaktanti Ovi blagi tenzidi čiste kožu bez narušavanja lipidnog sloja, što je ključno za održavanje hidratacije. Aminokiselinska osnova smanjuje rizik od iritacije i pruža nežno penušanje koje efikasno uklanja sebum i prljavštinu. Istovremeno minimalizuju transepidermalni gubitak vode. Idealni su za reaktivnu i osetljivu kožu. Pomažu u održavanju mekoće i glatkoće posle čišćenja. U rutini doprinose stabilnijem i hidratizovanom tenu. Ekstrakt zelenog čaja Bogat antioksidansima, ekstrakt zelenog čaja štiti kožu od oksidativnog stresa i umiruje crvenilo. Pomaže u regulaciji sebuma, što doprinosi čistijem tenu. Deluje osvežavajuće i smanjuje osećaj nadraženosti. Dugoročno doprinosi ravnoteži masnoće i hidratacije. Podržava regenerativne procese kože. Čini površinu kože mekšom i glađom. Centella asiatica Poznata po umirujućim svojstvima, centella asiatica pomaže regeneraciju kože i smanjuje iritacije. Jača barijeru i podržava prirodnu otpornost kože. Posebno je pogodna za kožu koja je sklona crvenilu i osetljivosti. Poboljšava elastičnost i doprinosi bržem oporavku kože. Pomaže u održavanju hidratacije. Redovnom upotrebom koža postaje vidljivo mirnija i uravnoteženija. Ekstrakt bergamota Ekstrakt bergamota doprinosi osveženju i umirivanju kože, pružajući lagan hidratantni efekat. Sadrži prirodne sastojke koji pomažu u održavanju čiste kože bez isušivanja. Pruža nežan tonizirajući efekat. Smiruje blaže iritacije. Poboljšava osećaj svežine nakon čišćenja. Koži daje nežan, prirodno blistav izgled. Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Bubble Foam koristi mineralno bogatu dubinsku morsku vodu i aminokiselinske surfaktante da efikasno ukloni nečistoće, dok ekstrakti zelenog čaja, centelle asiatice i bergamota umiruju i hidriraju kožu. Pogodan je za svakodnevnu upotrebu i za sve tipove kože, uključujući osetljivu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Round-Lab-1025-Dokdo-Bubble-Foam-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
