INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (290, 119, 'Mixsoon Collagen Cleansing Balm', 'mixsoon-collagen-cleansing-balm', 'Ključne prednosti: Efikasno uklanjanje šminke i SPF-a: rastvara čak i dugotrajnu šminku i otporne formule bez trljanja. Balzam koji ne isušuje: kolagen i PDRN sprečavaju osećaj zatezanja i ostavljaju kožu hidriranom. Napredna tekstura 3 u 1: balm se topi u ulje, a zatim pretvara u mlečnu emulziju za temeljno, ali nežno čišćenje. Kome je namenjen? Balzam je idealan za sve koji traže efikasno, ali nežno prvo čišćenje — posebno za one sa suvom, dehidriranom, osetljivom ili zrelim tipom kože. Odličan je izbor ako ti je važna jaka hidratacija, mekoća posle čišćenja i formula koja neće narušiti barijeru. Pogodan je i za kožu koja reaguje na uobičajene uljne čistače ili lako ostaje isušena posle čišćenja. Zašto volimo Mixsoon Collagen Cleansing Balm? Zato što spaja savršen osećaj luksuzne teksture, praktičnost i visoku efikasnost. Grinder sistem je jedan od najhigijenskijih na tržištu, a balzam se topi u dodiru sa kožom i uklanja sve — od vodootporne šminke do čestica zagađenja — bez agresivnog efekta. Kolagen i PDRN čine da koža posle čišćenja bude vidno mekša, elastičnija i nahranjena, što retko koji balzam postiže. Savršeno rešenje za svakodnevno čišćenje koje balansira između snažne efikasnosti i nežne nege. Aktivni sastojci Kolagen malog molekula Francuski kolagen koji lako prodire u površinske slojeve kože, poboljšava elastičnost, jača barijeru i sprečava isušivanje tokom čišćenja. PDRN (Polydeoxyribonucleotide) Obnavlja kožu, podstiče regeneraciju i daje ujednačen, blistav izgled. Pomaže koži da se oporavi i zadrži vlagu posle čišćenja. Biljna ulja za topljenje nečistoća Rastvaraju šminku i sebum bez masnog filma, obezbeđuju glatko klizanje i doprinose mekoći. Umirujući kompleksi Smanjuju rizik od iritacije i čuvaju osetljivu kožu tokom masaže. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Collagen Cleansing Balm je nežan, ali izuzetno efikasan balzam za čišćenje koji kombinuje mali molekul kolagena i PDRN kako bi uklonio šminku, SPF, nečistoće i višak sebuma uz maksimalnu hidrataciju i bez osećaja zatezanja. Luksuzna tekstura se topi u dodiru sa kožom, pretvara u svileni uljani film, a zatim u mlečnu emulziju koja obezbeđuje temeljno, ali nežno čišćenje.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Mixsoon-Collagen-Cleansing-Balm-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
