INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (291, 114, 'Medicube Zero Pore Pad Mild', 'medicube-zero-pore-pad-mild', 'Ključne prednosti: Nežno, ali temeljno eksfoliranje: uklanja mrtve ćelije i višak sebuma, bez peckanja i crvenila. Vidljivo čistije i zategnutije pore: smanjuju začepljenja i poboljšavaju izgled problematičnih zona. Umirenje i smanjenje iritacija: formula nežna prema koži, pogodna i za osetljiv ten. Kome je namenjen? Jastučići su idealni za sve koji se bore sa proširenim porama, viškom sebuma, miteserima ili grubom površinom kože, a žele nežniji pristup eksfolijaciji. Posebno su korisni za osetljivu kožu, kože sklonu crvenilu, kao i za one koji tek uvode kiseline u rutinu i žele siguran, kontrolisan piling. Zašto volimo Medicube Zero Pore Pad Mild? Zato što kombinuju efikasnost i nežnost u jednom koraku: salicilna kiselina prodire duboko u pore i uklanja sebum, dok PHA radi površinski piling koji ne narušava barijeru. Jastučići su praktični, dvostruko teksturirani i dovoljni za celu rutinu nakon čišćenja — reljefna strana radi posao pilinga, a glatka hidrira i umiruje. Rezultat je koža koja deluje čistije, mekše, osveženije i vidno balansiranija već nakon nekoliko korišćenja. A ono najbolje — potpuno su prilagođeni osetljivoj koži, bez crvenila i neprijatnosti. Aktivni sastojci Salicilna kiselina (BHA) Prodire u pore, rastvara sebum i dubinski čisti, pomaže u smanjenju mitesera i sprečava nova začepljenja. PHA (glukonolakton) Nežan eksfolijant koji uklanja mrtve ćelije, hidrira kožu i poboljšava barijeru, idealan za osetljiv ten. Sodium Hyaluronate Humektant koji vezuje vlagu i održava kožu hidriranom nakon eksfolijacije. Allantoin Umiruje osetljivu kožu, smanjuje crvenilo i podstiče oporavak. Panthenol (provitamin B5) Jača barijeru kože, smanjuje transepidermalni gubitak vode i doprinosi mekoći. Ekstrakt čajevca Pruža antibakterijski efekat, smanjuje nepravilnosti i pomaže koži sklonoj upalama. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore Pad Mild su nežni, ali izuzetno efikasni tonik jastučići formulisani za sve kojima su pore, sebum i osetljivost najveći izazov. Kombinuju salicilnu kiselinu i PHA kompleks koji uklanja mrtve ćelije, omekšava kožu, smanjuje crvenilo i vidljivo poboljšava teksturu — a sve to uz minimalan rizik od iritacija. Dvostrana struktura jastučića omogućava istovremeno eksfoliranje i hidratantni završetak, čineći kožu čistijom, glađom i ujednačenijom iz dana u dan.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Zero-Pore-Pad-Mild-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
