INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (292, 114, 'Medicube Super Cica Deep Cleansing Balm', 'medicube-super-cica-deep-cleansing-balm', 'Ključne prednosti: Temeljno uklanjanje šminke i SPF-a: topi i najizraženiji makeup, uključujući vodootporne formule. Čišćenje pora i nežna eksfolijacija: LHA i uljna baza uklanjaju sebum, mitisere i odumrle ćelije bez iritacije. Umirujući efekat: centela asiatica, madecassoside i biljna ulja ublažavaju crvenilo i iritaciju. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože — normalnu, suvu, masnu, kombinovanu i osetljivu. Posebno je koristan za kožu sklonu crvenilu, miteserima, zapušenim porama ili narušenoj barijeri. Odličan izbor za sve koji nose SPF svakodnevno ili šminku jačeg intenziteta. Zašto volimo Medicube Super Cica Deep Cleansing Balm? Zato što pruža dvostruki efekat: temeljno topljenje nečistoća + snažno umirivanje. Formula je bogata centelom i madecassoside-om, što ga čini sigurnim za osetljivu kožu, dok LHA nežno čisti pore. Tekstura je luksuzno kremasta, ali se u dodiru sa kožom pretvara u svileno ulje koje omogućava masažu bez iritacije. Koža ostaje čista, hidrirana i glatka — savršen uvod u dvostruko čišćenje. Aktivni sastojci Centella Asiatica Bogata asiaticoside-om, madecassoside-om i asiatic acid-om, ova biljka deluje snažno umirujuće, smanjuje crvenilo i pomaže u obnavljanju narušene barijere. Idealna je za osetljivu, reaktivnu i iritiranu kožu. Madecassoside Koncentrisani komponent centelle koji smanjuje inflamaciju, pospešuje regeneraciju i pruža antioksidativnu zaštitu. Pomaže koži da bude stabilnija i otpornija. Matricaria (Chamomile) Flower Oil Deluje protivupalno, umiruje i omekšava kožu, pomaže ublažavanju crvenila i iritacija. LHA (Capryloyl Salicylic Acid) Lipo-hidroksilna kiselina slična BHA, ali nežnija. Otapa sebum u porama, pomaže kod mitesera i nežno eksfolira bez rizika od iritacije. Biljna ulja & emolijenti Održavaju kožu hidriranom i sprečavaju osećaj zategnutosti nakon čišćenja. Dodaj u listu želja Dodaj u listu želja', 'Medicube Super Cica Deep Cleansing Balm je veganski, dubinski čistač u balzamu koji kombinuje centelu, madecassoside i biljna ulja kako bi istovremeno uklonio i najuporniji makeup, istopio sebum iz pora i smirio iritiranu kožu. Sorbet tekstura se topi u svilenkasto ulje već pri dodiru sa kožom, pružajući temeljno, ali nežno čišćenje bez isušivanja — idealno za sve tipove kože, uključujući i osetljivu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Super-Cica-Deep-Cleansing-Balm-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
