INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (293, 114, 'Medicube Retinol NMN Boosting Serum', 'medicube-retinol-nmn-boosting-serum', 'Ključne prednosti: Ciljano sužavanje i učvršćivanje pora: vidljivo smanjuje izgled proširenih i opuštenih pora. Obnova i posvetljavanje tena: kapsulirani retinol ubrzava ćelijsku obnovu i vraća koži sjaj. Zaglađivanje teksture: ublažava neravnine i poboljšava ujednačenost kože. Podrška elastičnosti i tonusa: NMN i peptidi jačaju kožu i deluju protiv prvih znakova starenja. Ne iritira i ne zapušava pore: formula je testirana na nekomedogenost i osetljivost. Kome je namenjen? Serum je idealan za sve koji žele da smanje pore, poboljšaju teksturu, posvetle ten ili targetiraju rane i umerene znake starenja. Posebno je koristan za kožu sa grubim površinskim neravninama, sivim tenom, blagim opuštanjem, postupalnim tragovima ili izraženijim porama. Pogodan je za većinu tipova kože — uključujući i osetljiviju — uz postepeno uvođenje. Zašto volimo Medicube Retinol NMN Boosting Serum? Zato što spaja najmoćnije anti-age i pore-refining tehnologije: kapsulirani retinol, koji omogućava dublju penetraciju uz smanjenu iritaciju, NMN, koji povećava ćelijsku energiju i poboljšava čvrstoću, i peptide, koji umiruju i podstiču elastičnost. Tekstura je kremasto-serumska, luksuzno glatka i brzo se upija bez lepljivosti. Rezultati subržiji nego kod klasičnih retinola, a serum ostaje nežan i stabilan, što je idealno za dužu i redovnu upotrebu. Aktivni sastojci Kapsulirani retinol (1.9%) Retinol „zarobljen“ u zaštitnim kapsulama koje omogućavaju dublje prodiranje, sporije otpuštanje i značajno smanjenu iritaciju. Efikasno pospešuje obnovu kože, utiče na pore, bore, tonus i pigmentaciju, uz veću stabilnost i veću podnošljivost. NMN (99% čistoće) Molekul koji povećava nivo NAD⁺ u ćelijama, ključan za obnovu i mladalačku funkciju kože. Jača barijeru, poboljšava čvrstoću i vraća koži zdravi sjaj. Peptidi Kompleks peptida koji umiruje iritacije, podržava sintezu kolagena i doprinosi elastičnosti. Uz retinol, pružaju balans i pomažu da koža ostane hidrirana i smirena. Hidratantno-umirujući kompleksi Smanjuju osećaj suvoće i zatezanja, dopunjuju oštećenu barijeru i povećavaju komfor tokom korišćenja retinola. Dodaj u listu želja Dodaj u listu želja', 'Medicube Retinol NMN Boosting Serum je snažan, ali izuzetno pažljivo formulisani retinol serum koji kombinuje 1.9% kapsuliranog retinola, NMN i peptide kako bi smanjio vidljivost pora, zagladio teksturu i ojačao tonus kože. Zahvaljujući kapsulaciji, retinol deluje dublje i efikasnije, uz značajno manji rizik od iritacije, što ga čini pogodnim i za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Retinol-NMN-Boosting-Serum-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
