INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (294, 114, 'Medicube Red Erasing Cream 2.0', 'medicube-red-erasing-cream-2-0', 'Ključne prednosti: Smanjuje crvenilo i iritacije: umirujući kompleksi ublažavaju vidljivu reaktivnost i jačaju osetljivu kožu. Poboljšava teksturu kože: blagi eksfolijacioni efekat doprinosi ravnijoj, mekšoj i glađoj površini. Jača barijeru i zaključava vlagu: formira hidratantni zaštitni sloj koji sprečava isušivanje i štiti od spoljašnjih iritansa. Kome je namenjena? Formulisana je za osetljivu, reaktivnu, crvenilu sklonu kožu. Pogodna je za sve koji imaju postupalne fleke, nadraženu kožu, neujednačen ten ili oslabljen zaštitni sloj. Idealna je za svakodnevnu rutinu i odlično se slaže sa minimalističkim i slojevitim režimima nege. Zašto volimo Medicube Red Erasing Cream 2.0? Zato što pruža upravo ono što osetljiva koža najviše traži — trenutno smirenje, prijatnu hidrataciju i postepeno ujednačavanje tena. Kombinuje umirujuće i obnavljajuće sastojke bez težine ili masnoće. Koža postaje manje reaktivna, ravnomernija i otpornija, a postupalne fleke bledе brže uz kontinuiranu upotrebu. Krema se lako uklapa u bilo koju rutinu, čak i kada su prisutni aktivni sastojci u drugim proizvodima. Aktivni sastojci Alantoin Snažan umirujući sastojak koji smanjuje iritacije i crvenilo, podstiče regeneraciju i pomaže koži da brže zaceli. Posebno je koristan kod osetljive kože i kože koja se oporavlja od upalnih procesa. Ekstrakt portulake (Purslane / Portulaca Oleracea Extract) Bogata antioksidansima i umirujućim komponentama, portulaka smanjuje reaktivnost kože, ublažava crvenilo i pomaže u vraćanju osećaja balansa. Odlična je za osetljivu, iritacijama sklonu kožu. Ekstrakt paradajza (Tomato Extract) Prirodni izvor likopena — moćnog antioksidansa koji štiti kožu od spoljašnjih stresora i doprinosi ravnomernijem, blistavijem tenu. Takođe pomaže u smanjenju postupalnih tragova i poboljšava tonus kože. Jojoba ulje (Jojoba Seed Oil) Sebumu sličan emolijent koji hrani kožu bez začepljivanja pora. Obnavlja lipidni sloj, sprečava gubitak vlage i daje koži mek, elastičan osećaj. Posebno je korisno za kožu koja lako postaje dehidrirana ili nadražena. Dodaj u listu želja Dodaj u listu želja', 'Medicube Red Erasing Cream 2.0 smanjuje crvenilo, ublažava postupalne tragove, jača barijeru i nežno zaglađuje kožu zahvaljujući alantoinu, ekstraktu portulake, ekstraktu paradajza i jojoba ulju. Idealna je za osetljivu kožu kojoj je potrebna smirenost, obnova i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Red-Erasing-Cream-2.0-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
