INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (295, 114, 'Medicube Red Acne Body Peeling Shot', 'medicube-red-acne-body-peeling-shot', 'Ključne prednosti: Efikasno smanjenje akni i mitesera: kombinacija kiselina uklanja višak sebuma, otčepljuje pore i sprečava nove upalne promene. Ujednačena i glađa tekstura kože: redovnom upotrebom koža postaje glatkija, sa manje neravnina i grubih područja. Umirujuće delovanje bez isušivanja: formula sa umirujućim agensima smanjuje crvenilo i iritacije, čuvajući hidrataciju kože. Kome je namenjen? Ovaj piling je idealan za osobe koje imaju akne na telu, posebno na leđima, ramenima, grudima i nadlakticama. Pogodan je za masnu, kombinovanu i kožu sklonu zapušavanju pora, kao i za sve koji žele glađu, čistiju i zdraviju kožu tela. Zašto volimo Medicube Red Acne Body Peeling Shot 2.0? Zato što nudi sve što je potrebno za borbu protiv akni na telu u jednom koraku — hemijski piling, fizičko zaglađivanje i umirujuću negu. AHA kiseline uklanjaju površinske nepravilnosti, BHA prodire duboko u pore i razgrađuje višak sebuma, dok PHA nežno exfolira i hidrira, što ga čini pogodnim i za osetljiviju kožu. Rezultat je vidljivo čistija koža, manje bubuljica i značajno poboljšana tekstura. Redovnom upotrebom koža postaje mekša, jasnija i otpornija na nove upalne promene. Aktivni sastojci AHA (Glikolna kiselina) Alfa-hidroksi kiselina koja uklanja mrtve ćelije sa površine kože i ubrzava obnavljanje epidermisa. Pomaže u smanjenju neravnina, zaglađuje grublje delove kože i poboljšava ukupnu ujednačenost tena na telu. BHA (Slicilna kiselina) Beta-hidroksi kiselina koja prodire duboko u pore, razgrađuje višak sebuma i sprečava nastanak akni i mitesera. Idealan sastojak za masnu i problematičnu kožu koja zahteva čišćenje u dubljim slojevima. PHA Polihidroksi kiselina poznata po nežnoj eksfolijaciji i hidratantnom efektu. Zbog svoje molekularne veličine deluje površinski, osvežava kožu, smanjuje perutanje i čini je mekanijom, bez rizika od iritacija. Umirujući agensi Kompleks sastojaka koji smanjuju crvenilo i upalu nakon eksfolijacije. Pomažu koži da zadrži vlagu, ublažuju osećaj zategnutosti i doprinose bržem smirivanju upalnih procesa. Dodaj u listu želja Dodaj u listu želja', 'Medicube Red Acne Body Peeling Shot 2.0 je napredni piling za telo formulisan za ciljano uklanjanje akni na leđima, grudima, ramenima i nadlakticama. Kombinuje AHA, BHA i PHA kiseline koje sinergijski uklanjaju mrtve ćelije, otčepljuju pore, smanjuju višak sebuma i ublažavaju upalne procese — bez isušivanja kože. Zahvaljujući formuli koja spaja hemijski i fizički piling, ovaj proizvod pruža efikasno, ali nežno čišćenje i vidljivo poboljšava teksturu kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Red-Acne-Body-Peeling-Shot-2.0-1.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
