INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (296, 114, 'Medicube PDRN Peptide Glossy Lip Balm', 'medicube-pdrn-peptide-glossy-lip-balm', 'Ključne prednosti: Regeneracija i popravka oštećenih usana: PDRN potpomaže obnavljanje tkiva, jača barijeru i vidno smanjuje suvoću i ispucalost. Puniji, zategnutiji izgled: peptidi stimulišu sintezu kolagena i poboljšavaju elastičnost tankog sloja kože usana. Dubinska i dugotrajna hidratacija: shea buter i biljna ulja obezbeđuju zaštićenu i negovanu površinu sa postojanim osećajem prijatnosti. Kome je namenjen? Balzam je idealan za sve koji imaju suve, osetljive, ispucale ili dehidrirane usne. Preporučuje se osobama koje žele regeneraciju, puniji izgled i prirodan sjaj bez lepljenja. Odličan je i kao podloga za ruž, kao i za noćnu, intenzivniju negu. Zašto volimo Medicube PDRN Peptide Glossy Lip Balm? Ovaj balzam kombinuje efekte skincare-a i make-up-a: regeneriše, štiti i vizuelno poboljšava izgled usana uz elegantan sjaj. PDRN pruža snažnu reparativnu podršku i ubrzava oporavak ispucalih usana, dok peptidi doprinose elastičnosti i mladalačkom volumenu. Shea buter i ulja stvaraju zaštitni film koji zaključava vlagu tokom celog dana, a završni efekat je „candy gloss“ sjaj koji nikada nije lepljiv. Lako se nanosi, prijatno se topi na usnama i pruža trenutan osećaj udobnosti. Aktivni sastojci PDRN (Polydeoxyribonucleotide) Biomolekul dobijen iz lososove DNA, poznat po regenerativnom delovanju. Podstiče obnavljanje ćelija, ubrzava zaceljivanje i jača kožnu barijeru. Na usnama smanjuje osećaj zategnutosti, hidrira i daje blago popunjen izgled, čineći ih mekšim i otpornijim na spoljne uticaje. Peptidi Kompleks kratkih aminokiselina koji stimulišu sintezu kolagena, poboljšavaju elastičnost i doprinose punijem, glađem izgledu usana. Pomažu u smanjenju finih linija i održavanju čvrstoće tankog epidermalnog sloja. Shea Butter Prirodni emolijent bogat masnim kiselinama koji dubinski neguje, omekšava i štiti kožu usana. Stvara barijeru koja sprečava gubitak vlage i štiti od pucanja i isušivanja. Biljna ulja Dodaju hranljivost i doprinose dugom osećaju hidratacije. Pomažu u zaglađivanju površine usana i dodatno štite od spoljnog stresa. Silver Pearl Mineralni sastojak koji daje diskretan, svetlucav sjaj i prirodnu, osvetljenu završnicu. Poboljšava vizualni efekat „glossy“ usana bez lepljivosti. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Peptide Glossy Lip Balm je napredni balzam za usne koji kombinuje regenerativnu snagu dermokozmetike sa efektom sjaja. Formulisan sa PDRN-om, peptidima i njegujućim uljima, ovaj balzam hidrira, obnavlja i vizuelno popunjava usne, čineći ih mekšim, zaglađenijim i prirodno sjajnijim. Tekstura se topi na dodir i ostavlja glossy efekat bez lepljenja, dok istovremeno jača barijeru i smanjuje suvoću.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-PDRN-Peptide-Glossy-Lip-Balm-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
