INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (297, 114, 'Medicube Kojic Acid Turmeric Pad', 'medicube-kojic-acid-turmeric-pad', 'Ključne prednosti: Ciljano delovanje na tamne fleke i neujednačen ten: kojic kiselina postepeno posvetljuje tamne mrlje, postupalne tragove i sivilo tena. Umirivanje kože i antioksidativna zaštita: kurkuma smanjuje crvenilo, iritacije i štiti od agresora iz okoline. Glatka, rafinirana tekstura kože: 3% glikolne kiseline uklanja odumrle ćelije i zadebljanja, ostavljajući kožu mekšom, glađom i blistavijom. Kome su namenjeni? Ovi jastučići su pogodni za sve tipove kože, uključujući i osetljivu. Posebno se preporučuju osobama koje se bore sa tamnim flekama, postupalnim tragovima, mitiserima, grubom teksturom, sivim tenom ili viškom sebuma. Pogodni su i za telo — nadlaktice, torzo, leđa — gde pore i hiperpigmentacije mogu biti češće prisutne. Zašto volimo Medicube Kojic Acid Turmeric Pad? Ovi jastučići nude idealan balans: dovoljno snažni da deluju na fleke, sivilo i nepravilnosti, a istovremeno dovoljno nežni da umire iritacije i ojačaju izgled kože. Kurkuma dodaje antioksidativnu podršku i vidno smanjuje crvenilo, dok glikolna kiselina 3% obezbeđuje blagu, ali efikasnu eksfolijaciju bez agresije. Kojic kiselina ciljano deluje na postupalne tragove i mrlje, što jastučiće čini odličnim izborom posle tretiranja bubuljica. Rezultat je koža koja izgleda čistije, sjajnije i ujednačenije — uz teksturu koja je vidno zaglađena već nakon dve nedelje redovne upotrebe. Aktivni sastojci Kojic Acid Deluje tako što inhibira sintezu pigmenta melanina, postupno ublažava tamne fleke i postupalne tragove, smanjuje sivilo i daje koži ujednačeniji ton. Posebno je efikasna kod kože koja se bavi flekama koje ostaju nakon bubuljica. Doprinosti blistavijem, ravnomernijem tenu tokom vremena. Turmeric (Kurkuma) Prirodni antioksidans bogat kurkuminom koji smiruje kožu, smanjuje vidljivo crvenilo, umiruje iritacije i jača kožu protiv štetnih uticaja spoljašnje sredine. Pomaže koži da se oporavi nakon bubuljica i doprinosi “healthy glow” efektu. Glycolic Acid 3% AHA kiselina male molekularne strukture koja nežno uklanja odumrle ćelije i zadebljanja, rafinira pore i poboljšava glatkoću površine kože. Redovnom upotrebom smanjuje nepravilnosti, umanjuje izgled pora i poboljšava sjaj kože bez agresivnog guljenja. Dodaj u listu želja Dodaj u listu želja', 'Medicube Kojic Acid Turmeric Pad kombinuju antioksidativnu moć kurkume, posvetljujuće dejstvo kojic kiseline i blagu eksfolijaciju glikolne kiseline (3%) kako bi poboljšali ton kože, smanjili postupalne fleke i zagladili teksturu. Jastučići su pogodni za lice i telo, naročito kod ljudi sa neujednačenim tenom, sivilo kože ili tragovima nakon bubuljica.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Kojic-Acid-Turmeric-Pad-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
