INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (298, 114, 'Medicube Kojic Acid Turmeric Niacinamide serum', 'medicube-kojic-acid-turmeric-niacinamide-serum', 'Ključne prednosti: Ciljano posvetljivanje i ujednačavanje tena: kojic kiselina i kurkuma vidljivo utiču na tamne mrlje i postupalne tragove. Antioksidativna zaštita i smirenje kože: kurkuma i vitamin E štite od oksidativnog stresa i umiruju iritacije. Poboljšanje teksture i jačanje barijere: niacinamid zaglađuje površinu kože, smanjuje crvenilo i pojačava otpornost epidermisa. Kome je namenjen? Ovaj serum je pogodan za sve tipove kože, uključujući i osetljivu. Posebno je koristan za osobe sa hiperpigmentacijama, postupalnim flekama, neujednačenim tenom, umornim i sivim izgledom kože, kao i kod blagih nepravilnosti i akni. Idealan je za sve koji žele vidljiv sjaj, poboljšanje teksture i antioksidativnu zaštitu. Zašto volimo Medicube Kojic Acid Turmeric Niacinamide Serum? Ovaj serum spaja klinički potvrđene posvetljujuće sastojke sa antioksidativno bogatim kompleksom kurkume i vitaminom E. Kapsule u formuli pomažu bržoj apsorpciji i jačem efektu, pa rezultati postaju primetni već nakon dve nedelje — ujednačeniji ten, smanjene fleke i glasnije, blistavije lice. Tekstura je lagana, nemasna i prijatna, što omogućava lako uklapanje u bilo koju rutinu, bez rizika od iritacije ili težine. Aktivni sastojci Kojic kiselina Inhibira sintezu melanina, deluje ciljano na hiperpigmentacije, tamne fleke i neujednačen ten, posvetljuje postupalne tragove i doprinosi ujednačenoj boji kože. Ekstrakt kurkume Bogata kurkuminoidima koji smanjuju oksidativni stres, umiruju upalne procese, podržavaju regeneraciju kože i daju prirodan, zdrav sjaj. Niacinamid Ujednačava ton kože, smanjuje vidljivost pora, ublažava crvenilo, reguliše lučenje sebuma i jača zaštitnu barijeru kože. Vitamin E Štiti kožu od slobodnih radikala, smanjuje oštećenja izazvana UV i spoljašnjim faktorima, pomaže u očuvanju hidratacije i daje glatkiji izgled kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube Kojic Acid Turmeric Niacinamide Serum kombinuje moćne antioksidanse i posvetljujuće sastojke za tretiranje pigmentacija, postupalnih fleka i umornog tena. Kapsulirana formula poboljšava isporuku aktivnih komponenti, pa koža brže dobija svež i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Kojic-Acid-Turmeric-Niacinamide-serum-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
