INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (299, 114, 'Medicube Hyaluronic Moisturizing Capsule Cream', 'medicube-hyaluronic-moisturizing-capsule-cream', 'Ključne prednosti: Dubinska i dugotrajna hidratacija: višestruko umrežena hijaluronska kiselina zadržava vlagu do 120 sati. Obnova i jačanje barijere: ceramidi zaključavaju vlagu i štite kožu od isušivanja i osetljivosti. Umirivanje i balansiranje: pantenol, betain i alantoin smanjuju crvenilo i umiruju toplotno iziritiranu kožu. Kome je namenjena? Ova krema je pogodna za sve tipove kože, uključujući osetljivu. Posebno se preporučuje koži koja je suva, dehidrirana, sklona perutanju, zatezanju ili crvenilu. Idealna je i za one koji žele laganu, ali izrazito efikasnu hidrataciju, kao i za korisnike K-beauty rutine koji žele “glass skin” efekat. Zašto volimo Medicube Hyaluronic Moisturizing Capsule Cream? Ovo je jedna od najkompletnijih hidratantnih krema u svojoj kategoriji — spaja gelastu lakoću sa snažnim efektom kapsulirane hijaluronske kiseline. Formula se trenutno upija, ali pruža dugotrajan osećaj udobnosti i mekoće. Ceramidi jačaju barijeru, dok pantenol i alantoin smiruju iritacije, pa je odličan izbor za umornu, dehidriranu i osetljivu kožu. Redovnom upotrebom koža deluje punije, glađe i vidno odmornije, bez masnog ili lepljivog traga. Aktivni sastojci Všeslojna hijaluronska kiselina Višestruke molekularne veličine omogućavaju hidrataciju u svim slojevima kože: veliki molekuli formiraju zaštitni film i sprečavaju isparavanje vode, srednji molekuli obezbeđuju punoću i elastičnost, dok mali molekuli ulaze dublje i intenzivno navlače vlagu iznutra. Ovaj kompleks daje “plump” efekat i smanjuje hrapavost površine kože. Ceramidi Ceramidi su ključni lipidi koji čine dobar deo kožne barijere. Oni popunjavaju mikropukotine u lipidnom sloju, jačaju otpornost kože, sprečavaju transepidermalni gubitak vode i smanjuju osetljivost izazvanu spoljnim faktorima. Redovnom primenom koža postaje manje reaktivna, meka i vidljivo otpornija. Pantenol (Pro-Vitamin B5) Deluje snažno umirujuće i obnavljajuće. Povećava zadržavanje vode u koži, smanjuje iritacije, crvenilo i osećaj zatezanja, i ubrzava obnavljanje oštećene barijere. Idealno za osetljivu, dehidriranu i istanjenu kožu. Betain Prirodni osmolit koji održava balans vlage unutar ćelija i sprečava isušivanje. Čini kožu mekšom i elastičnijom, bez osećaja težine. Alantoin Smanjuje iritacije, omekšava površinski sloj kože i podstiče regeneraciju. Posebno koristan kod kože sklone crvenilu, perutanju i osetljivosti. Dodaj u listu želja Dodaj u listu želja', 'Medicube Hyaluronic Moisturizing Capsule Cream je hidratantna kapsul-krema sa višestrukim oblicima hijaluronske kiseline i inkapsuliranim aktivnim sastojcima koji obnavljaju vlagu, jačaju barijeru i pružaju dugotrajan “glass skin” efekat. Sadrži hijaluronsku kiselinu, ceramide, pantenol i niacinamid za dubinsku hidrataciju, umirenje i poboljšanje teksture kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Hyaluronic-Moisturizing-Capsule-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
