INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (300, 114, 'Medicube Collagen Milk Toning Wrapping Mask', 'medicube-collagen-milk-toning-wrapping-mask', 'Ključne prednosti: Trenutni “glazed” efekat: maska pruža vidljivo sjajniji i hidriran ten već nakon 20 minuta, idealno za pripremu kože pre šminke. Ultra-niskomolekularni kolagen (130Da): prodire dublje, pomaže zatezanje kože i poboljšava glatkoću. Posvetljivanje i ujednačavanje tena: niacinamid i glutation zajedno deluju na sivilo kože i neravnomeran ton. Kome je namenjena? Ova maska je pogodna za sve tipove kože kojima nedostaje zdravi sjaj, hidratacija i punoća. Preporučuje se svima koji žele brzi “glow-up” tretman, ujednačen ten, glatku površinu i trenutni efekat zaglađivanja – bez potrebe za noćnim delovanjem. Zašto volimo Medicube Collagen Milk Toning Wrapping Mask? Maska kombinuje četiri ključna sastojka koji ciljano deluju na hidrataciju, glatkoću i blistavost. Zahvaljujući ultra-niskomolekularnom kolagenu, koža postaje vidno zategnutija, dok mlečni proteini daju mekoću i elastičnost. Niacinamid podiže tonus, smanjuje sivilo i doprinosi ujednačenju teksture, a glutation pomaže da koža izgleda osvetljeno i odmorno. Formula nema lepljiv osećaj, lako se nanosi i formira tanki “wrapping” sloj koji omogućava efikasniji učinak za kratko vreme. Idealna je za jutra kada želiš savršen “canvas” za šminku, ali i kao SOS tretman kada koži treba brza regeneracija. Aktivni sastojci 130Da kolagen Ultra-niskomolekularni kolagen koji lakše prodire u kožu, pomaže zaglađivanje finih linija i pruža osećaj čvršće teksture. Daje trenutni efekat punije i svežije kože. Niacinamid Deluje na ujednačavanje tona, poboljšava teksturu i doprinosi jačanju kožne barijere. Smanjuje vidljivost sivila i umornog izgleda kože. Mlečni proteini Bogati aminokiselinama koje omekšavaju kožu i pružaju dubinsku hidrataciju. Ovaj sastojak daje koži nežnu glatkoću i mekši osećaj pod prstima. Glutation Snažan antioksidans koji posvetljuje kožu, umanjuje tupost tena i doprinosi celokupnom sjaju lica. Pomaže koži da izgleda osvetljeno i revitalizovano. Dodaj u listu želja Dodaj u listu želja', 'Medicube Collagen Milk Toning Wrapping Mask je maska za trenutan “glazed glow” efekat — vidljiv već nakon 20 minuta. Formulisana je tako da hidrira, posvetli i zagladi ten uz pomoć ultra-niskomolekularnog kolagena, niacinamida, mlečnih proteina i glutationa. Idealan je izbor za jutarnju pripremu kože pre šminke ili kao večernja intenzivna maska za dodatnu punoću i blistavost. Tekstura se lako nanosi, nije lepljiva i ostavlja kožu mekom, punijom i sjajnom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Collagen-Milk-Toning-Wrapping-Mask-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
