INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (301, 114, 'Medicube Azelaic Acid Niacinamide Clear Toner', 'medicube-azelaic-acid-niacinamide-clear-toner', 'Ključne prednosti: Ujednačavanje tena i blaga eksfolijacija: azelaična kiselina pomaže u smanjenju pigmentacija, postupalnih tragova i površinskih nepravilnosti. Balans masnoće i hidratacije: formula pomaže da se stabilizuje kombinovana koža i smanji pojava upala i crvenila. Poboljšanje teksture i pora: koža deluje zaglađenije, sa manje vidljivim porama i stabilnijom barijerom. Kome je namenjen? Tonik je pogodan za sve tipove kože, uključujući osetljivu, posebno za osobe sa kombinovanom ili aknoznom kožom, neujednačenim tonom, upalama i postupalnim pigmentacijama. Koristan je i za kožu sklonu crvenilu i narušenoj barijeri koja zahteva istovremeno i blag piling i umirivanje. Zašto volimo Medicube Azelaic Acid Niacinamide Clear Toner? Tonik kombinuje hidrirajuću i umirujuću bazu sa aktivnim sastojcima koji istovremeno ciljaju višak sebuma, crvenilo i nepravilnosti. Azelaična kiselina pruža blagi keratolitički efekat bez iritacije, dok niacinamid dodatno umiruje kožu i doprinosi ujednačenijem tonu. Tekstura je laka, nekomedogena i brzo se upija, što ga čini odličnim prvim korakom u rutini za sve koji žele jasniji, stabilniji i vizuelno glađi ten. Redovnom upotrebom koža deluje smirenije, mekše i ujednačenije, sa vidljivim smanjenjem nepravilnosti i poboljšanom barijernom funkcijom. Aktivni sastojci Azelaična kiselina (4%) Azelaična kiselina deluje tako da uklanja višak odumrlih ćelija i pomaže u čišćenju pora, što je važno kod kože sklone aknama. Pomaže u smanjenju postupalnih mrlja i neravnomerne pigmentacije, doprinoseći svetlijem i ujednačenijem tenu. Istovremeno deluje protivupalno i ublažava crvenilo, što je čini pogodnom i za osetljive tipove kože. Doprinosi zaglađivanju površine kože i poboljšanju njene teksture. Redovnom upotrebom ten deluje čistije i stabilnije. Ovaj sastojak je poznat po multifunkcionalnom efektu bez izazivanja iritacije. Niacinamid Niacinamid podržava jačanje zaštitne barijere kože i smanjuje gubitak vlage. Pomaže u ujednačavanju tona, smanjenju tamnih mrlja i crvenila. Reguliše proizvodnju sebuma, što doprinosi smanjenju pojave akni i proširenih pora. Umiruje kožu i smanjuje reaktivnost nakon izlaganja stresorima. Poboljšava celokupnu teksturu kože čineći je mekšom. Pogodan je za osetljivu i reaktivnu kožu. Hidratantna baza tonera Tonik ima hidratantnu formulu koja podržava prirodni nivo vlažnosti kože i sprečava isušivanje nakon čišćenja. Pomaže koži da ostane umirena i stabilna, što je važno kod tena sklonog aknama i iritacijama. Hidratantni sastojci podržavaju elastičnost i mekoću kože. Brzo se upija i ostavlja kožu pripremljenom za naredne korake nege. Ovaj tip baze posebno prija koži koja je osetljiva na agresivnije pilinge. Doprinosi poboljšanoj udobnosti i otpornosti kože tokom dana. Dodaj u listu želja Dodaj u listu želja', 'Medicube Azelaic Acid Niacinamide Clear Toner je tonik namenjen ujednačavanju tena, smanjenju nepravilnosti i jačanju barijere kože, formulisanim sa 4% azelaične kiseline i niacinamidom. Ovaj tonik pruža blagu eksfolijaciju, hidrira i pomaže u smanjenju crvenila, dok istovremeno podržava prirodnu zaštitnu funkciju kože i smanjuje transepidermalni gubitak vode.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Azelaic-Acid-Niacinamide-Clear-Toner-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
