INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (302, 114, 'Medicube Azelaic Acid 16 BB Calming Serum', 'medicube-azelaic-acid-16-bb-calming-serum', 'Ključne prednosti: Smanjenje fleka i nepravilnosti: visok procenat azelaične kiseline pomaže u ublažavanju tamnih mrlja, postupalnih tragova i aktivnih nepravilnosti. Regulacija sebuma i ujednačavanje tena: niacinamid podržava barijeru, balansira masnoću i poboljšava celokupan ton kože. Umirenje osetljive kože: biljni umirujući kompleks hidrira i smanjuje crvenilo, što serum čini pogodnim za reaktivnu kožu. Kome je namenjen? Ovaj serum je idealan za masnu, mešovitu, aknoznu i osetljivu kožu. Preporučuje se osobama koje se bore sa crvenilom, miteserima, postupalnim flekama, grubom teksturom i nepravilnim tonom. Pogodan je i za kožu koja lako reaguje ili se iritira drugim aktivnim sastojcima. Zašto volimo Medicube Azelaic Acid 16 BB Calming Serum? Ovaj serum objedinjuje tri glavne potrebe problematične kože: smanjenje upala, izbistravanje tena i regulaciju sebuma. Azelaična kiselina u 16% koncentraciji deluje efikasno, ali istovremeno nežno, dok niacinamid dodatno umiruje, posvetljuje i jača kožnu barijeru. Biljni umirujući sastojci smanjuju rizik od iritacija i doprinose stabilnijem, hidriranom tenu. Tekstura se lako upija, ne ostavlja težinu i može se uklopiti u rutinu i ujutru i uveče. Redovnom upotrebom koža postaje čistija, svetlija i vidljivo smirenija. Aktivni sastojci Azelaic Acid 16% Pomaže u posvetljavanju tamnih fleka i postupalnih tragova, smanjuje nepravilnosti, umiruje crvenilo i deluje antibakterijski. Poboljšava ton i teksturu kože. Niacinamid Podržava kožnu barijeru, balansira proizvodnju sebuma i doprinosi ujednačenijem i blistavijem tenu. Umirujući biljni kompleks (centella asiatica, alantoin i dr.) Smanjuje crvenilo, iritacije i osećaj nelagodnosti. Pruža hidrataciju i pomaže osetljivoj koži da ostane stabilna i smirena. Dodaj u listu želja Dodaj u listu želja', 'Medicube Azelaic Acid 16 BB Calming Serum je snažan, ali izuzetno nežan serum formulisan sa visokih 16% azelaične kiseline kako bi ciljano delovao na nepravilnosti, crvenilo i hiperpigmentacije. Uz dodatak niacinamida i umirujućeg biljnog kompleksa, serum pomaže u regulaciji sebuma, poboljšava teksturu kože i doprinosi čistijem, blistavijem tenu. Istovremeno jača kožnu barijeru i hidrira, što ga čini pogodnim i za osetljivu i aknoznu kožu sklonu iritacijama.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Azelaic-Acid-16-BB-Calming-Serum-1.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
