INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (304, 103, 'Lagom White Moisture Cream', 'lagom-white-moisture-cream', 'Ključne prednosti: Dvostruka funkcija: istovremena hidratacija kože i vidljivo ujednačavanje tona. Kompleks aktivnih sastojaka: pirinač, biljni proteini, ulje narandže i niacinamid doprinose posvetljivanju i poboljšanju teksture. Dubinska hidratacija: ši puter, urea i biljna ulja obnavljaju vlagu i jačaju barijeru kože. Kome je namenjena? Krema je pogodna za normalnu, suvu i mešovitu kožu kojoj nedostaje hidratacija, ujednačen ton i mekoća. Preporučuje se osobama koje se bore sa sivim tenom, blagim pigmentacijama, grubom teksturom ili osećajem zategnutosti. Zašto volimo Lagom White Moisture Cream? Ova krema kombinuje efikasne sastojke za hidrataciju i ujednačavanje tena u laganoj, ali bogatoj formuli. Stvara zaštitni “Silky Finisher Film” koji zaključava vlagu i čini kožu mekšom i otpornijom. Zahvaljujući niacinamidu i ekstraktu pirinča, ten postaje svetliji i blistaviji kroz vreme. Tekstura se lepo razmazuje, ne ostavlja masni trag i odlična je kao završni korak u rutini. Aktivni sastojci Ekstrakt pirinča Pomaže u posvetljivanju tena, zaglađivanju nepravilnosti i održavanju mekoće kože. Ulje narandže Doprinosi osvežavanju tena, blago posvetljava i pruža prijatan osećaj na koži. Hidrolizovani biljni proteini Podržavaju zaglađivanje površine kože i poboljšavaju elastičnost. Niacinamid Efikasan sastojak za ujednačavanje tena i smanjenje vidljivosti diskoloracija. Ši puter Dubinski hidrira i omekšava kožu, obnavlja lipide i jača barijeru. Urea Snažan humektans koji privlači i zadržava vlagu, idealan za suvu i dehidriranu kožu. Biljna ulja Pomažu u zaključavanju vlage i formiranju zaštitnog filma koji sprečava isušivanje. Dodaj u listu želja Dodaj u listu želja', 'Lagom White Moisture Cream je hidratantna krema sa dvostrukom funkcijom — istovremeno rešava dehidrataciju kože i utiče na ujednačavanje tena. Formulisana sa sedam aktivnih sastojaka za posvetljivanje i poboljšanje tonusa, dok kombinacija biljnog ulja, uree i ši putera obezbeđuje dubinsku, dugotrajnu hidrataciju i zaštitu barijere kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Lagom-White-Moisture-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
