INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (305, 114, 'Medicube Azelaic Acid Exosome Shot 2000', 'medicube-azelaic-acid-exosome-shot-2000', 'Ključne prednosti: Dubinska isporuka aktivnih sastojaka: mikroskopski sitne spikule omogućavaju brzu apsorpciju i jači efekat azelaične kiseline, niacinamida i egzoma. Ciljano delovanje na nepravilnosti i mrlje: smanjuje blemishe, zaglađuje teksturu i ujednačava ton kože vidljivog porekla. Jačanje barijere i regeneracija: egzozomi doprinose obnavljanju kože, smanjenju crvenila i poboljšanju ukupnog zdravlja kože. Kome je namenjen? Ova ampula je pogodna za sve tipove kože, uključujući i osetljivu. Posebno se preporučuje osobama koje imaju pigmentacije, akne i postupalne tragove, sivilo tena, proširene pore, višak sebuma ili neujednačenu površinu kože. Korisna je i za kožu kojoj je potrebna dodatna regeneracija i jačanje barijere. Zašto volimo Medicube Azelaic Acid Exosome Shot 2000? Ovaj proizvod spaja tri visokoefikasne komponente — azelaičnu kiselinu, niacinamid i egzozome — sa tehnologijom mikroskopskih spikula koja omogućava da svaki sastojak prodre dublje i deluje brže. Rezultat je specifičan “booster” efekat: brže smanjenje crvenila, upala, mrlja i nepravilnosti. Tekstura se momentalno upija, a koža nakon nanošenja deluje smirenije i zategnutije bez težine ili masnog filma. Exosome tehnologija dodatno pospešuje regeneraciju i jača otpornost kože, što je posebno važno kod tena sklonog izbijanjima i oštećenjima barijere. Redovnom upotrebom ten postaje jasniji, glađi i vidljivo ujednačen. Aktivni sastojci Azelaična kiselina Pomaže u uklanjanju odumrlih ćelija i viška sebuma, smanjuje upalne procese, umiruje kožu i ublažava hiperpigmentacije i porekla nepravilnosti. Niacinamid Ujednačava ten, smanjuje vidljivost tamnih mrlja i postupalnih tragova, reguliše masnoću i doprinosi jačanju kožne barijere. Egzozomi Podstiču ćelijsku regeneraciju, jačaju prirodnu odbranu kože i pomažu u obnovi oštećene barijere, doprinoseći zdravijem i otpornijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Medicube Azelaic Acid Exosome Shot 2000 je intenzivna ampula inspirisana principima mikroiglica, formulisana tako da prodre dublje u kožu i isporuči maksimalnu količinu aktivnih sastojaka. Sadrži mikroskopski sitne spikule, 13 puta manje od prosečne pore, što omogućava efikasniji prolaz azelaične kiseline, niacinamida i egzozoma direktno u kožu. Ampula ciljano deluje na mrlje, nepravilnosti, proširene pore, neujednačen ton i oštećenu barijeru, ostavljajući kožu čistijom, smir', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-Azelaic-Acid-Exosome-Shot-2000-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
