INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (306, 92, 'K-Secret Sun Pine Tree + Ceramide', 'k-secret-sun-pine-tree-ceramide', 'Ključne prednosti: Širokospektralna zaštita SPF 50+ PA++++: kombinacija 4 UV hemijska filtera obezbeđuje stabilnu, dugotrajnu i pouzdanu zaštitu od UVA i UVB zraka, bez belog traga. Umirivanje i smanjenje crvenila: ekstrakt bora pomaže da se smanje iritacija, svrab i upala, pružajući osećaj svežine i ravnoteže. Jačanje kožne barijere: ceramidi doprinose sprečavanju transepidermalnog gubitka vlage i poboljšavaju otpornost kože. Kome je namenjen? Ovaj SPF je pogodan za sve tipove kože, uključujući osetljivu, mešovitu i masnu kožu koja želi laganu formulaciju bez belog traga. Preporučuje se osobama sa crvenilom, iritacijama ili osetljivom kožom sklonom reakcijama na oštre filtere. Idealno za svakodnevnu upotrebu tokom cele godine. Zašto volimo K-Secret Sun Pine Tree + Ceramide? SPF kombinuje zaštitu i negu kože bez kompromisa. Lagana tekstura se brzo upija i ostavlja prirodan glowy finish koji ne izgleda masno. Ekstrakt bora pruža umirujući efekat kod crvenila, dok ceramidi pomažu da se barijera ojača i ostane stabilna tokom izlaganja suncu. Formulacija je bez alkohola, parabena, sulfata i veštačkih boja, što je čini izuzetno pogodnom za osetljive tenove. Uz snažnu zaštitu i prijatan osećaj na koži, ovo je SPF koji se koristi bez razmišljanja — svakog dana. Aktivni sastojci Ekstrakt bora Prirodni sastojak poznat po svojim antiinflamatornim svojstvima. Pomaže u smanjenju crvenila, iritacije i osećaja svraba. Blagotvorno deluje na osetljive tenove i doprinosi uravnoteženijem izgledu kože. Doprinosi boljem oporavku kože u uslovima spoljne izloženosti. Ceramidi Doprinosе jačanju kožne barijere i očuvanju hidratacije, čineći kožu otpornijom tokom dana. Pomažu u smanjenju osetljivosti i sprečavaju gubitak vlage. Redovnom upotrebom koža postaje stabilnija i mekša. Hemijski UV filteri (4 tipa) Stabilni i efikasni filteri obezbeđuju pouzdanu i dugotrajnu zaštitu od štetnih UVA i UVB zraka. Obezbeđuju glatko nanošenje bez belog filma i bez zasićenja kože. Pogodni su i za tamnije tonove kože. Dodaj u listu želja Dodaj u listu želja', 'K-Secret Sun Pine Tree + Ceramide je hemijski SPF pruža širokospektru zaštitu SPF 50+ PA++++ bez belog traga, uz dodatnu negu zahvaljujući ekstraktu bora i ceramidima. Formulisan je da umiri iritiranu kožu, ojača barijeru i pruži lagan, glowy završetak. Bez iritansa i neželjenih sastojaka, čini zaštitu jednostavnom i prijatnom čak i za najosetljiviju kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/K-Secret-Sun-Pine-Tree-Ceramide-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
