INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (308, 92, 'K-secret Boosting Serum Collagen Complex 7 + Red Ginseng', 'k-secret-boosting-serum-collagen-complex-7-red-ginseng', 'Ključne prednosti: Intenzivno zatezanje i elastičnost: 7 tipova kolagena pomažu da se koži vrati čvrstina i prirodna punoća. Revitalizacija sa crvenim ginsengom: ekstrakt crvenog ginsenga podstiče regeneraciju i poboljšava tonus kože. Jačanje barijere kože: ceramide i skvalan štite od gubitka vlage i čuvaju kožu otpornom. Kome je namenjen? Serum je idealan za normalnu, suvu i mešovitu kožu koja gubi elastičnost, punoću i sjaj. Preporučuje se osobama koje primećuju prve bore, suvoću, neravnu teksturu ili koži žele zdrav i čvršći izgled. Odličan je i za kožu koja izgleda umorno, sivkasto ili dehidrirano. Zašto volimo K-secret Boosting Serum Collagen Complex 7 + Red Ginseng? Ovaj serum kombinuje sedam tipova kolagena kako bi pružio multidimenzionalnu elastičnost — deluje na površinske i dublje slojeve kože, dajući trenutan osećaj punoće. Crveni ginseng dodatno energizuje kožu i poboljšava njen ton. Tekstura je lagana, ali hranljiva, što ga čini izuzetno prijatnim za svakodnevnu upotrebu, čak i ispod šminke. Redovnom upotrebom koža postaje primetno zategnutija, glatka i sjajnija. Aktivni sastojci Collagen Complex 7 Kompleks sačinjeno od sedam različitih vrsta kolagena (rastvorljiv kolagen, hidrolizovani kolagen, kolagenske aminokiseline, elastin, ceramidni kolagen, liposolubilni kolagen i mikro-kolagen) koji zajedno pomažu u povećanju elastičnosti i punoće kože. Pruža osećaj čvrstine i dugotrajne hidratacije. Ekstrakt crvenog ginsenga Bogati antioksidantski sastojci crvenog ginsenga revitalizuju umornu kožu, poboljšavaju cirkulaciju i ujednačavaju ton. Pomaže u smanjenju sitnih linija i vraća prirodni sjaj. Ceramide NP Ojačava lipidnu barijeru, sprečava gubitak vlage i doprinosi otpornijoj i hidratizovanoj koži. Skvalan Hranljivi emolijens koji omekšava, zaglađuje i sprečava transepidermalni gubitak vode, ostavljajući kožu nežnom i elastičnom. Adenozin Jedan od najefikasnijih sastojaka za negu finih linija — poboljšava teksturu kože i doprinosi ujednačenijem, glatkom izgledu. Dodaj u listu želja Dodaj u listu želja', 'K-secret Boosting Serum Collagen Complex 7 + Red Ginseng je snažan serum za jačanje kože koji kombinuje čak sedam tipova kolagena sa ekstraktom crvenog ginsenga kako bi koži vratio punoću, elastičnost i zdraviji, zategnutiji izgled. Formulisan da poboljša teksturu, smanji vidljivost bora i pruži prirodan sjaj bez masnog finiša.', 'https://beauty-health.rs/wp-content/uploads/2025/11/K-secret-Boosting-Serum-Collagen-Complex-7-Red-Ginseng-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
