INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (309, 92, 'K-Secret Essence Snail Mucin 97% + Rice', 'k-secret-essence-snail-mucin-97-rice', 'Ključne prednosti: Regeneracija i obnova kože: 97% puževe sluzi pomaže u smirivanju iritacija, poboljšanju teksture i jačanju otpornosti kože. Posvetljivanje i ujednačavanje tena: fermenti i derivati pirinča doprinose blistavijem, zdravijem i ujednačenom tenu. Intenzivna hidratacija bez težine: lagana formula se brzo upija i pruža dugotrajnu mekoću i punoću. Kome je namenjena? Esencija je idealna za normalnu, suvu, mešovitu i osetljivu kožu kojoj nedostaje hidratacija, ujednačen ten i vidljiva regeneracija. Preporučuje se osobama sa grubom teksturom, sivim tenom, postinflamatornim promenama, dehidratacijom i smanjenom elastičnošću kože. Zbog lagane formule pogodna je i za masnu kožu kojoj je potrebna hidratacija bez zasićenja. Zašto volimo K-Secret Essence Snail Mucin 97% + Rice? Esencija objedinjuje najbolje od puževe sluzi i pirinčanih fermenta: intenzivnu regeneraciju i vidljivo posvetljivanje. Puževa sluz pomaže u smirivanju kože i poboljšanju njene teksture, dok pirinčani derivati daju ten koji izgleda probuđeno, mekše i zdravije. Formulacija se upija izuzetno brzo i ne ostavlja lepljiv trag, što je čini savršenim prvim hidratantnim korakom posle tonera. Redovnom upotrebom ten dobija ujednačen sjaj, površina postaje glađa, a koža jače i otpornija. Aktivni sastojci Puževa sluz (97%) Visoka koncentracija puževe sluzi pruža moćno regenerativno dejstvo, pomaže u smanjenju iritacija, poboljšanju teksture i održavanju hidratacije. Doprinosi elastičnosti i mekoći kože, čineći je glatkom i odmornijom. Posebno korisna kod narušene barijere, suvih delova i tenova sklonih oporavku nakon oštećenja. Ekstrakt pirinča Bogati nutritivni ekstrakti pirinča doprinose posvetljivanju i ujednačavanju tena. Ovaj sastojak tradicionalno se koristi za omekšavanje kože i poboljšanje njenog prirodnog sjaja. Pomaže u smanjenju sivila i potpunijem izgledu kože. Fermenti pirinča Fermentisani derivati pirinča pružaju dublju hidrataciju i doprinose obnovi površinskog sloja kože. Pomažu u poboljšanju teksture, čineći kožu glatkijom i vizuelno blistavijom. Idealni su za tenove sa neujednačenim sjajem ili grubim delovima. Dodaj u listu želja Dodaj u listu želja', 'K-Secret Essence Snail Mucin 97% + Rice je esencija kombinuje visokih 97% puževe sluzi sa nutritivnim derivatima pirinča kako bi istovremeno regenerisala, hidrirala i posvetlila ten. Puževa sluz omekšava kožu, umanjuje iritacije i obnavlja oštećenu teksturu, dok ekstrakti i fermenti pirinča doprinose blistavijem, ujednačenijem i hidriranom izgledu kože. Lagan, brzo upijajući fluid pruža svakodnevnu dozu hidratacije bez težine.', 'https://beauty-health.rs/wp-content/uploads/2025/11/K-Secret-Essence-Snail-Mucin-97-Rice-4.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
