INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (310, 90, 'Jumiso Waterfull Hyaluronic Acid Cleansing Foam', 'jumiso-waterfull-hyaluronic-acid-cleansing-foam', 'Ključne prednosti: Dubinska hidratacija tokom čišćenja: 3-kompleks hijaluronske kiseline dopunjava i zadržava vlagu u koži dok se pore temeljno oslobađaju nečistoća. Jačanje kožne barijere: ceramidi obnavljaju i ojačavaju zaštitni sloj kože, sprečavajući dehidrataciju. Blago čišćenje pora: LHA i sodium bicarbonate nežno uklanjaju višak masnoće, mrtve ćelije i znoj, ostavljajući kožu mekom i glatkom. Kome je namenjen? Ova pena je pogodna za normalnu, mešovitu, masnu i dehidriranu kožu koja želi temeljno čišćenje bez osećaja zatezanja. Idealna je za one koji žele hidratantno sredstvo za umivanje koje uklanja sebum i nečistoće, a pritom ne narušava kožnu barijeru. Dobra je opcija i za osetljivu kožu zbog blagih eksfolijativnih i umirujućih svojstava LHA. Zašto volimo Jumiso Waterfull Hyaluronic Acid Cleansing Foam? Ova pena je pravi balans nežnosti i efikasnosti — uklanja sve nečistoće koje se nakupe tokom dana, ali kožu ostavlja vidno hidriranom i mekanom. Zahvaljujući hijaluronskoj kiselini koža ne gubi vlagu tokom čišćenja, dok ceramidi pomažu da se barijera dodatno osnaži. LHA je izuzetno blaga kiselina, savršena za svakodnevnu upotrebu, jer čisti pore bez iritacije. Tekstura je kremasta i svilena, pretvara se u mekanu, bogatu penu i ne ostavlja nikakav lepljiv ili težak film. Nakon umivanja ten izgleda osveženo, glatko i pripremljeno za dalju rutinu. Aktivni sastojci 3-kompleks hijaluronske kiseline Hidrira kožu na više nivoa, povećava elastičnost i sprečava isušivanje tokom čišćenja. Održava kožu mekom i punom. Ceramidi Ojačavaju oštećenu ili oslabljenu kožnu barijeru, smanjuju gubitak vlage i povećavaju otpornost kože. LHA Blaga eksfolijativna kiselina koja uklanja mrtve ćelije i čisti pore bez iritacije. Idealna za svakodnevnu upotrebu. Sodium Bicarbonate Pomaže u uklanjanju viška masnoće, znoja i površinskih nečistoća, ostavljajući kožu glatkom i čistom. Dodaj u listu želja Dodaj u listu želja', 'Jumiso Waterfull Hyaluronic Acid Cleansing Foam je nežna, kremasta pena za čišćenje koja kombinuje 3-kompleks hijaluronske kiseline, ceramide, LHA i sodu bikarbonu kako bi istovremeno dubinski očistila pore i zadržala vlagu u koži. Formulacija uklanja nečistoće i višak sebuma bez isušivanja, jača barijeru i ostavlja kožu glatkom i hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Jumiso-Waterfull-Hyaluronic-Acid-Cleansing-Foam-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
