INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (311, 90, 'Jumiso D-Panthenol Barrier Soothing Serum', 'jumiso-d-panthenol-barrier-soothing-serum', 'Ključne prednosti: Intenzivno umirenje i obnova: Dexpanthenol (vitamin B5) trenutno smiruje iritaciju, hidrira i ubrzava oporavak kože oštećene spoljnim faktorima. Dubinska hidratacija: kompleks od 10 vrsta hijaluronske kiseline puni kožu vlagom na više nivoa i vraća joj elastičnost. Blaga eksfolijacija i čiste pore: BHA nežno uklanja mrtve ćelije i pomaže u sprečavanju zapušavanja pora. Kome je namenjen? Serum je odličan izbor za osetljivu, dehidriranu, masnu ili kombinovanu kožu koja se lako iritira, crveni, ima narušenu barijeru ili povremene nepravilnosti. Idealan je za osobe koje traže laganu teksturu bez lepljenja, ali snažan efekat umirenja i hidratacije. Pogodan i za kožu koja se oporavlja od tretmana ili razdražujućih aktivnih sastojaka. Zašto volimo Jumiso D-Panthenol Barrier Soothing Serum? Ovaj serum kombinuje umirujuće, hidratantne i pročišćavajuće benefite u formuli koja je izuzetno nežna čak i za najosetljiviju kožu. Dexpanthenol i TECA liposomi jačaju barijeru i smanjuju crvenilo, dok hijaluronske kiseline pune kožu vlagom bez otežavanja. Dodati cink PCA pomaže u kontroli sebuma i održavanju kože čistom, dok blaga doza BHA održava nežnu glatkoću površine. Tekstura je vodena i lagana, odmah se upija i ostavlja osvežavajući osećaj bez masnog sjaja. Dermatološki je testiran i pogodan čak i za osobe koje inače teško nalaze proizvode koji ne izazivaju reakcije. Redovnom upotrebom koža postaje mirnija, stabilnija, mekša i vidljivo hidriranija. Aktivni sastojci Dexpanthenol (vitamin B5) Klinički dokazano umiruje kožu, smanjuje crvenilo i ubrzava oporavak oštećene barijere. Pomaže koži da bolje zadrži vlagu i vraća joj mekoću. Posebno efikasan kod osetljive i iritirane kože. 10 vrsta hijaluronske kiseline Kompleks različitih molekulskih veličina omogućava višeslojnu hidrataciju — od površine do dubljih slojeva kože. Povećava punoću kože i smanjuje osećaj zategnutosti i dehidratacionih linija. BHA (salicilna kiselina) Blago eksfolira i uklanja mrtve ćelije koje narušavaju teksturu, dok pomaže u pročišćavanju pora i sprečava pojavu nepravilnosti. Idealna za masnu i kombinovanu kožu. TECA liposome (Centella Asiatica kompleks) Potencirana forma centelle koja jača kožnu barijeru, smanjuje crvenilo, poboljšava otpornost kože i pruža dugotrajnu hidrataciju. Odlična za izbalansiranu i umirenu kožu. Cink PCA Reguliše višak sebuma, smanjuje pojavu bubuljica i održava kožu čistom. Istovremeno hidrira zahvaljujući PCA komponenti. Dodaj u listu želja Dodaj u listu želja', 'Jumiso D-Panthenol Barrier Soothing Serum je lagani, umirujući serum formulisan za osetljivu, masnu i narušenu kožu sklonu crvenilu. Kombinuje Dexpanthenol za intenzivnu hidrataciju i obnavljanje barijere, 10 vrsta hijaluronskih kiselina za dubinsko zadržavanje vlage, BHA za blago uklanjanje mrtvih ćelija i pročišćavanje pora, kao i TECA liposome (Centella kompleks) i cink PCA za balans sebuma, umirenje i jaču kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Jumiso-D-Panthenol-Barrier-Soothing-Serum-7-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
