INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (312, 90, 'Jumiso D-Panthenol Barrier Soothing Cream', 'jumiso-d-panthenol-barrier-soothing-cream', 'Ključne prednosti: D-pantenol za dubinsku hidrataciju: povećava nivo vlage u koži i jača prirodnu zaštitnu barijeru, smanjujući osećaj zategnutosti i neprijatnosti. Madekasoasid i asiaticosid: umiruju zapaljenske procese, podržavaju regeneraciju kože i doprinose boljoj elastičnosti jačanjem kolagenske strukture. Balansirajuća formula: lagana, osvežavajuća tekstura pomaže u uspostavljanju balansa vode i ulja bez lepljenja, idealna za oporavak oštećene barijere. Kome je namenjen? Krema je idealna za normalnu, suvu, masnu, mešovitu i naročito osetljivu kožu. Namenjena je svima koji imaju narušenu barijeru, crvenilo, iritacije, dehidrataciju ili sklonost ka perutanju. Odgovara osobama koje žele umirujuću, neljepljivu i nemasnu hidrataciju — odlična i za kožu koja reaguje na jače aktivne sastojke. Zašto volimo Jumiso D-Panthenol Barrier Soothing Cream? Ova krema pruža snažnu kombinaciju umirenja i oporavka bez osećaja težine na koži. D-pantenol odmah donosi osećaj olakšanja i hidratacije, dok istovremeno učvršćuje barijeru kako bi se sprečio gubitak vode. Madekasoasid i asiaticosid, dva visoko cenjena sastojka iz centelle, smanjuju iritacije i doprinose smirivanju osetljive i upaljene kože, uz dodatnu prednost podsticanja elastičnosti kroz bolju regeneraciju. Tekstura je izuzetno prijatna — osvežavajuća, neljepljiva i pogodna za sve koji žele hidriranu, mirnu i stabilnu kožu tokom celog dana. Krema se razmazuje lako, brzo se upija i pruža savršen završetak rutine bez okluzivnog osećaja. Dermatološki testirana, predstavlja pouzdan izbor za osetljivu kožu i svakodnevnu upotrebu. Aktivni sastojci D-pantenol (provitamin B5) Jača kožnu barijeru, povećava hidrataciju i umiruje iritacije. Smanjuje crvenilo i doprinosi mekoći kože, pružajući dugoročnu stabilnost i otpornost. Madekasoasid Snažan umirujući i regenerativni sastojak koji smanjuje inflamaciju i podržava reparaciju kože. Poboljšava elastičnost kroz efekat na kolagensku strukturu. Asiaticosid Komponenta centelle poznata po efektima na zaceljivanje, jačanje i smirivanje kože. Pomaže u obnavljanju oštećene barijere i poboljšanju tonusa. Dodaj u listu želja Dodaj u listu želja', 'Jumiso D-Panthenol Barrier Soothing Cream je umirujuća barijerna krema formulisana da istovremeno hidrira, jača i obnavlja kožu. Obogaćena je D-pantenolom, madekasoasidom, asiaticosidom i laganom teksturom koja smanjuje crvenilo, umiruje iritacije i pomaže u oporavku narušene zaštitne barijere. Dermatološki je testirana, pogodna i za najosetljiviju kožu, a posebno za tenove sklone upalama, suvoći i osetljivosti.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Jumiso-D-Panthenol-Barrier-Soothing-Cream-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
