INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (313, 90, 'Jumiso D-Panthenol Barrier Soothing Cleansing Milk', 'jumiso-d-panthenol-barrier-soothing-cleansing-milk', 'Ključne prednosti: D-pantenol za jačanje barijere: intenzivno umiruje kožu, smanjuje crvenilo i sprečava dehidrataciju tokom čišćenja. Multi-ceramidi: pomažu zadržavanje vlage u koži i obnavljaju zaštitni sloj, smanjujući osećaj zatezanja posle umivanja. Azulen i ulje lana: ublažavaju iritacije i pružaju dodatnu negu osetljivoj koži sklonoj crvenilu. Kome je namenjen? Ovaj čistač je idealan za normalnu, suvu, osetljivu i masnu kožu koja traži blago čišćenje bez skidanja prirodnih lipida. Pogodan je za kožu sklonu crvenilu, iritacijama, dehidrataciji i narušenoj barijeri. Masnoj koži odgovara jer formula nije masna, ne ostavlja film i ne izaziva težinu. Zašto volimo Jumiso D-Panthenol Barrier Soothing Cleansing Milk? Ovo mlečno sredstvo za čišćenje pruža potpuno drugačiji osećaj od klasičnih gelova i balzama. Tekstura je kremasta i bogata, ali se ispira lako bez ikakvog masnog filma. D-pantenol deluje kao hitna pomoć za kožu – umiruje, omekšava i poboljšava teksturu već tokom samog čišćenja. Multi-ceramidi dopunjuju lipidni sloj i sprečavaju transepidermalni gubitak vode, pa koža ostaje hidrirana i posle umivanja. Azulen je dodatni bonus za sve koji se bore sa crvenilom, osetljivošću ili reaktivnom kožom. Ono što ga izdvaja je osećaj nežnosti: uklanja SPF i svakodnevnu šminku bez trljanja i bez osećaja isušivanja. Savršen je za jutarnje i večernje čišćenje, kao i za sve koji žele da očuvaju barijeru dok uklanjaju nečistoće. Dermatološki testiran i bez veštačkih mirisa i boja – pravi “skin barrier safe” izbor. Aktivni sastojci D-pantenol (provitamin B5) Deluje umirujuće, smanjuje crvenilo i pomaže zadržavanje vlage. Poboljšava mekoću kože i doprinosi smanjenju sitnih linija izazvanih dehidratacijom. Multi-ceramidi Podržavaju prirodnu kožnu barijeru, jačaju lipidni sloj i sprečavaju gubitak vode, što čini kožu otpornijom i hidriranijom. Azulen Sastojak poznat po snažnom anti-inflamatornom delovanju. Ublažava iritacije i smanjuje vidljivo crvenilo. Ulje lana Bogato omega masnim kiselinama koje umiruju, hrane i omekšavaju kožu, posebno korisno kod osetljive i suve kože. Nemastan mlečni kompleks Kombinacija hidratantnih i umirujućih komponenti koje omogućavaju temeljno čišćenje bez ispiranja prirodne zaštitne barijere. Dodaj u listu želja Dodaj u listu želja', 'Jumiso D-Panthenol Barrier Soothing Cleansing Milk je nežno, mlečno sredstvo za čišćenje koje uklanja SPF i svakodnevnu šminku dok istovremeno jača kožnu barijeru. Formulisano je sa D-pantenolom, multi-ceramidima, uljem lana i azulenom, pa kožu čini mekom, umirenom i hidriranom – bez osećaja masnoće i zatezanja. Namenjeno je i najosetljivijoj i masnoj koži kojoj treba nežno, ali efikasno čišćenje bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Jumiso-D-Panthenol-Barrier-Soothing-Cleansing-Milk-1.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
