INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (315, 69, 'Haruharu Wonder Black Rice Hyaluronic Anti-Wrinkle Serum', 'haruharu-wonder-black-rice-hyaluronic-anti-wrinkle-serum', 'Ključne prednosti: Podrška elastičnosti: fermentisani crni pirinač i sojin lecitin doprinose otpornijoj i čvršćoj koži. Intenzivna hidratacija: hijaluronska kiselina u 2.000 ppm pomaže u zadržavanju vode i omekšavanju površine kože. Umanjenje finih linija: adenozin i tokoferol sinergijski utiču na zaglađeniji izgled kože. Kome je namenjen? Serum je pogodan za normalnu, suvu i mešovitu kožu kojoj nedostaje elastičnost, hidratacija i ujednačen ton. Preporučuje se posebno osobama koje primećuju prve ili već prisutne linije, sivilo tena i manjak punoće. Zašto volimo Haruharu Wonder Black Rice Hyaluronic Anti-Wrinkle Serum? Formula pruža slojevitu hidrataciju koja stabilizuje površinu kože i poboljšava njenu glatkoću tokom vremena. Fermentisani crni pirinač deluje kao snažan antioksidativni izvor, što doprinosi zaštiti od spoljašnjih oštećenja koja ubrzavaju pojavu bora. Fermentisani izdanci bambusa doprinose ujednačenijem tonu i umirenju kože, što je posebno korisno kod osetljivih i reaktivnih tipova. Hijaluronska kiselina povećava sposobnost kože da zadrži vlagu i čini je zategnutijom i mekšom. Tokoferol doprinosi dodatnoj barijernoj zaštiti i pomaže u očuvanju lipida kože. Sojin lecitin omogućava bolju apsorpciju aktivnih sastojaka i doprinosi elastičnosti, dok adenozin podržava zaglađivanje finih linija kroz redovnu upotrebu. Aktivni sastojci Fermentisani crni pirinač (10.000 ppm) Ovaj sastojak je bogat antioksidativnim komponentama koje podržavaju odbranu kože od svakodnevnih spoljašnjih uticaja. Proces fermentacije povećava biodostupnost hranljivih jedinjenja, što doprinosi boljem upijanju i efikasnijem delovanju na kožu. Redovnom primenom pomaže u vraćanju vitalnosti i ujednačenijeg izgleda tena. Takođe doprinosi nutritivnoj obnovi, što je korisno za zrelu i umornu kožu. Njegov prirodni antioksidativni kapacitet utiče na smanjenje vidljivih znakova starenja i doprinosi blistavijem izgledu kože. Fermentisani izdanci bambusa (2.000 ppm) Ovaj ekstrakt deluje umirujuće i pruža podršku koži sklone crvenilu i iritacijama. Fermentacija olakšava prolazak aktivnih komponenti kroz površinske slojeve kože, što poboljšava njihovu efikasnost. Redovna upotreba doprinosi ujednačenijem tenu i zdravijem izgledu. Zbog svojih umirujućih svojstava posebno pogoduje osetljivim tipovima kože. Pomaže u stvaranju mekše i glatkije teksture kože. Hijaluronska kiselina (2.000 ppm) Ovaj humektant privlači i zadržava vlagu, čime direktno povećava hidrataciju površinskih i dubljih slojeva kože. Pomaže u umekšavanju teksture i smanjenju osećaja zategnutosti karakterističnog za suvu kožu. Dugotrajnom primenom doprinosi elastičnijem i punijem izgledu. Poboljšava otpornost kože i omogućava efikasniju funkciju barijere. Njeno hidratantno dejstvo čini kožu vizuelno zaglađenijom. Tokoferol (vitamin E) Poznat je po antioksidativnom delovanju koje podržava stabilnost lipida u koži. Doprinosi zaštiti od oksidativnih oštećenja i podržava proces obnavljanja. Pomaže u umanjenju suvoće i poboljšanju osećaja mekoće. Redovnom upotrebom doprinosi zaglađenijem izgledu kože. Ovaj vitamin je posebno koristan kod zrele kože koja je izložena spoljašnjim stresorima. Sojin lecitin Lecitin poboljšava penetraciju aktivnih sastojaka i doprinosi njihovom ujednačenom raspoređivanju u koži. Deluje hidratantno i emolijentno, što je korisno za kožu kojoj nedostaje fleksibilnost i elastičnost. Njegova antioksidativna svojstva pomažu u očuvanju vitalnosti kože. Može doprineti smanjenju osećaja suvoće i poboljšanju opšteg tonusa. Produžava osećaj udobnosti na koži i podržava funkciju barijere. Adenozin Adenozin funkcioniše kao sastojak koji podržava ujednačenost i glatkoću površine kože. Deluje na vidljive linije tako što poboljšava ukupni tonus kože tokom vremena. Posebno je koristan u rutini za zrelu kožu zbog svoje sposobnosti da poboljša izgled finih linija. Pomaže u održavanju svežijeg ', 'Haruharu Wonder Black Rice Hyaluronic Anti-Wrinkle Serum kombinuje fermentisani crni pirinač, hijaluronsku kiselinu i tokoferol kako bi obezbedio hidrataciju i antioksidativnu podršku zreloj i umornoj koži. Ovaj serum ciljano deluje na suvoću, neujednačenu teksturu i vidljive fine linije zahvaljujući koncentrisanim biljnim ekstraktima i funkcionalnim aktivnim molekulima.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Haruharu-Wonder-WONDER-Black-Rice-Hyaluronic-Anti-Wrinkle-Serum-3.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
