INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (334, 11, 'Anua Azelaic Acid 3 Cica Skin Clarifying Toner', 'anua-azelaic-acid-3-cica-skin-clarifying-toner', 'Ključne prednosti: Umirivanje crvenila: Cica kompleks i glicirizinska kiselina smanjuju osetljivost i podržavaju regeneraciju kože. Rafiniranje teksture: azelaična kiselina pomaže u uklanjanju mrtvih ćelija i smanjuje vidljivost nepravilnosti. Regulisanje sebuma: biljke bogate antioksidansima i cink PCA doprinose balansiranju masnijih delova kože. Kome je namenjen? Najbolje odgovara mešovitoj, masnoj i problematičnoj koži, kao i koži sklonoj crvenilu, osetljivosti i povremenim nepravilnostima. Pogodan je i za kožu kojoj treba blago poboljšanje teksture bez jačih kiselina. Zašto volimo Anua Azelaic Acid 3 Cica Skin Clarifying Toner? Ovaj tonik sadrži 3% azelaične kiseline, sastojka koji blago eksfolira, smanjuje osetljivost i pomaže u otpušavanju pora bez agresivnog delovanja na kožnu barijeru. Njegova formula kombinuje više oblika Centelle Asiatice, uključujući ekstrakt lista, korena i ključne bioaktivne komponente, čime doprinosi umirivanju kože sklone crvenilu i reaktivnosti. Cica kompleks deluje kao podrška regeneraciji, posebno kod kože koja reaguje na toplotu ili spoljne stresore. Prisustvo glicirizinske kiseline ciljano umiruje lokalne nepravilnosti i doprinosi ravnomernijem tenu. Hijaluronska kiselina i poliglutaminska kiselina zadržavaju vlagu, dok biljni ekstrakti poput nim ulja, čajevca i ruzmarina doprinose osećaju svežine i čistoće. Tekstura tonika brzo se upija, ostavljajući kožu osveženom, mekšom i stabilnijom, pogodnom za naredne korake rutine. Aktivni sastojci Azelaična kiselina (3%) Utiče na smanjenje crvenila i umirivanje iritacija zahvaljujući svom blagom protivupalnom efektu. Pomaže u uklanjanju mrtvih ćelija kože i doprinosi ravnijoj, glađoj površini. Doprinosi regulisanju viška sebuma i pomaže kod začepljenih pora, bez agresivnog isušivanja. Smanjuje vidljivost lokalnih nepravilnosti koje nastaju usled prekomerne osetljivosti. Blaga je prema koži i pogodna za svakodnevnu upotrebu. Na duže staze doprinosi ujednačenom, smirenom tenu i boljim barijernim funkcijama. Cica kompleks (Centella asiatica – ekstrakt lista, korena, asiaticoside, madecassoside) Umiruje reaktivnu kožu i smanjuje osećaj zagrejanosti nastao usled suvoće ili spoljnog stresa. Pomaže regeneraciji epidermisa i jačanju zaštitne barijere. Poboljšava hidrataciju i smanjuje površinske iritacije. Doprinosi boljoj elastičnosti i otpornosti kože. Stabilizuje kožu sklonu crvenilu. Redovnom primenom ten deluje skladnije i smirenije. Glicirizinska kiselina Deluje snažno umirujuće i posebno je korisna kod lokalnih crvenila i osetljivih delova kože. Pomaže u ravnomernijem izgledu kože i doprinosi većem komforu pri dodiru. Smanjuje površinske reakcije izazvane suvoćom. Obezbeđuje osećaj smirene, stabilne kože tokom dana. Njeno dejstvo se pojačava u kombinaciji sa Centellom. Redovnom upotrebom koža izgleda odmornije i ravnomernije. Dodaj u listu želja Dodaj u listu želja', 'Anua Azelaic Acid 3 Cica Skin Clarifying Toner kombinuje 3% azelaične kiseline i Cica kompleks kako bi smanjio crvenilo, ublažio osetljivost i poboljšao površinsku teksturu kože. Namenjen je regulisanju viška sebuma, umirivanju iritacija i održavanju balansirane i čistije kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Anua-Azelaic-Acid-3-Cica-Skin-Clarifying-Toner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
