INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (340, 114, 'Medicube AGE-R Booster Pro Head Case Pink', 'medicube-age-r-booster-pro-head-case-pink', 'Ključne prednosti: Zaštita i higijena: Čvrsta struktura i meka unutrašnjost štite uređaj od prašine, vlage i udara. Precizno oblikovana unutrašnjost: Prostor je tačno prilagođen obliku AGE-R Booster Pro uređaja i njegovih nastavaka. Praktično i elegantno rešenje: Kompaktan dizajn i nežna pink boja čine navlaku pogodnom za putovanja i svakodnevno korišćenje. Kome je namenjen? Predviđena je za korisnike Medicube AGE-R Booster Pro uređaja koji žele da produže vek trajanja svog aparata i održe njegov higijenski standard. Idealna za profesionalce i kućnu upotrebu. Zašto volimo Medicube AGE-R Booster Pro Head Case Pink? Ova navlaka omogućava bezbedno odlaganje i transport Medicube uređaja, sprečavajući oštećenja tokom putovanja ili svakodnevne upotrebe. Gornji sloj je izrađen od vodootpornog materijala koji štiti od spoljašnjih uticaja, dok unutrašnji sloj od mikrofibera sprečava ogrebotine. Dodatni unutrašnji pretinci omogućavaju čuvanje kabla za punjenje i nastavaka. Dodaj u listu želja Dodaj u listu želja', 'Medicube AGE-R Booster Pro Head Case Pink je zaštitna navlaka posebno dizajnirana za AGE-R Booster Pro uređaj, napravljena da obezbedi sigurno i higijensko čuvanje uređaja. Izrađena je od izdržljivog i laganog materijala sa unutrašnjom podlogom koja sprečava ogrebotine i oštećenja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Medicube-AGE-R-Booster-Pro-Head-Case-Pink.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
