INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (342, 3, '9wishes Centella PDRN Calm Ampule', '9wishes-centella-pdrn-calm-ampule', 'Ključne prednosti: Smiruje osetljivu kožu: Trenutno ublažava crvenilo, svrab i iritacije. Regeneriše i jača: Podstiče obnavljanje ćelija i obnavlja zaštitnu funkciju kože. Balansira i hidrira: Pruža laganu, ali dubinsku hidrataciju bez težine ili masnoće. Kome je namenjen? Pogodan za sve tipove kože, naročito za osetljivu, reaktivnu, dehidriranu ili kožu sklonu crvenilu i aknama. Idealan posle tretmana, pilinga ili izlaganja suncu. Zašto volimo 9wishes Centella PDRN Calm Ampule Formulisan da pruži trenutno olakšanje koži pod stresom, ovaj serum kombinuje PDRN i peptide koji deluju regenerativno, uz ekstrakte centelle i biljnih proteina koji umiruju i vraćaju balans. PDRN (polinukleotidi iz lososove DNK) stimulišu ćelijsku obnovu i sintezu kolagena, dok peptidi jačaju strukturu kože i smanjuju mikro-upale. Centella asiatica (poznata kao Cica) deluje protivupalno i pomaže zaceljivanje, dok Centiger Bean ekstrakt doprinosi elastičnosti i mekoći kože. Rezultat je umirena, glatka i osnažena koža otpornija na spoljašnje stresore. Aktivni sastojci Centella Asiatica Extract (Cica) Biljni ekstrakt poznat po svom izuzetnom umirujućem i reparativnom dejstvu. Bogat asiaticosidom i madecassosidom koji pospešuju zarastanje rana, smanjuju iritacije i jačaju kapilare. Deluje protivupalno i pomaže u regeneraciji oštećene kože. Centella PDRN Polinukleotid (PDRN) ekstrahovan iz DNK lososa poznat je po moćnim regenerativnim svojstvima. Ubrzava obnavljanje ćelija, stimuliše proizvodnju kolagena i elastina, poboljšava mikrocirkulaciju i vraća koži zdravu strukturu. Doprinosi elastičnosti i smanjenju finih linija. Cica Peptide Complex Kombinacija peptida koji podržavaju regeneraciju kože i jačaju njen zaštitni sloj. Pomažu u smanjenju osetljivosti i crvenila, dok istovremeno poboljšavaju elastičnost i hidrataciju. Centiger Bean Extract Biljni ekstrakt bogat proteinima i aminokiselinama koji obnavljaju i omekšavaju kožu. Doprinosi jačanju barijere i vraća elastičnost, čineći površinu kože glatkom i ujednačenom. Hyaluronic Acid Pruža dubinsku hidrataciju i zadržava vlagu u koži, čineći je punijom i svežijom. U kombinaciji sa PDRN-om i Cica kompleksom, dodatno smanjuje suvoću i osećaj zatezanja. Dodaj u listu želja Dodaj u listu želja', 'Umirujući serum koji kombinuje snagu prirodnih ekstrakata i biotehnologije kako bi obnovio osetljivu, iziritiranu ili upaljenu kožu. Zahvaljujući kompleksu Centella PDRN, Centiger Bean i Cica Peptide, ovaj serum intenzivno smanjuje crvenilo, ubrzava regeneraciju i jača kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2025/11/9wishes-Centella-PDRN-Calm-Ampule-.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
