INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (345, 164, 'Tirtir Mask Fit Red Foundation', 'tirtir-mask-fit-red-foundation', 'Ključne prednosti: Puna pokrivenost sa prirodnim finišem: ujednačava ten i prikriva nepravilnosti bez osećaja težine. Dugotrajna postojanost: ostaje besprekorno i do 72 sata, bez razmazivanja i oksidacije. Nega kože unutar formule: antioksidansi i biljni ekstrakti čuvaju hidrataciju i blistavost kože. Kome je namenjena? Preporučuje se osobama koje žele potpunu pokrivenost, ali bez težine na koži. Idealna je za normalnu, kombinovanu i suvu kožu, kao i za one koje žele efekt „besprekornog tena“ koji traje ceo dan. Zašto volimo TIRTIR Mask Fit Red Foundation? Ova podloga pruža savršenu ravnotežu između šminke i nege kože. Njena lagana tekstura se stapa sa kožom i ostavlja satenski finiš koji ne izgleda maskasto. Zahvaljujući niacinamidu, poboljšava tonus kože i smanjuje crvenilo, dok astaksantin i crveni biljni ekstrakti deluju kao antioksidativna zaštita tokom dana. Rezultat je ujednačen, blistav ten koji izgleda prirodno i postojano. Aktivni sastojci Niacinamid Niacinamid (vitamin B3) ujednačava ton kože, smanjuje crvenilo i jača zaštitnu barijeru. Pomaže u regulaciji sebuma i održavanju kože uravnoteženom, čime doprinosi prirodnom, zdravom sjaju. Astaksantin Astaksantin je snažan antioksidans koji štiti ćelije kože od oksidativnog stresa i prevremenog starenja. Pomaže koži da zadrži elastičnost i smanji vidljivost umora, dajući joj svež i vitalan izgled. Ekstrakt crvenog hibiskusa Ekstrakt crvenog hibiskusa poznat je po svom revitalizujućem delovanju — stimuliše cirkulaciju, poboljšava tonus kože i vraća joj prirodnu blistavost. Crveni propolis Bogata prirodna smola sa antioksidativnim i umirujućim svojstvima. Pomaže u obnavljanju kože i smanjuje osetljivost, što podlogu čini pogodnom i za reaktivnu kožu. Biljni ekstrakti Kombinacija crvenih biljaka pruža dodatnu zaštitu, smanjuje upale i poboljšava hidrataciju kože, čineći je otpornijom i glađom tokom dana. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit Red Foundation je luksuzni tečni puder koji kombinuje savršenu pokrivenost i negu kože. Formula sadrži niacinamid, astaksantin i ekstrakte crvenih biljaka, koji ne samo da ulepšavaju ten već i jačaju kožnu barijeru i pružaju zaštitu od spoljašnjih uticaja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/TIRTIR-Mask-Fit-Red-Foundation.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
