INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (346, 163, 'Timeless Matrixyl® 3000 Peptide Complex Serum', 'timeless-matrixyl-3000-w', 'Ključne prednosti: Povećava čvrstinu kože: Stimuliše proizvodnju kolagena i elastina za vidljivo zategnutiji izgled. Ublažava bore i fine linije: Redovnom upotrebom koža postaje glatkija i ujednačenija. Intenzivno hidrira: Hijaluronska kiselina vraća vlagu i poboljšava elastičnost. Kome je namenjen? Preporučuje se osobama sa vidljivim znacima starenja, gubitkom čvrstine i elastičnosti, kao i onima koji žele preventivno da očuvaju mladolik izgled. Idealno za suvu, zrelu i normalnu kožu. Zašto volimo Timeless Matrixyl® 3000 Peptide Complex Serum? Ovaj serum koristi naučno dokazanu kombinaciju peptida i ovlaživača za potpunu regeneraciju kože. Matrixyl® 3000 deluje kao signalni peptid – stimuliše fibroblaste da proizvode više kolagena, elastina i hijaluronske kiseline, što doprinosi čvrstoći i volumenu kože. Hijaluronska kiselina obezbeđuje dugotrajnu hidrataciju, dok aloe vera umiruje i obnavlja barijeru kože. Tekstura je lagana, nemasna i brzo se upija, čineći serum pogodnim za svakodnevnu upotrebu i ujutru i uveče. Aktivni sastojci Matrixyl® 3000 Matrixyl® 3000 je kompleks peptida (Palmitoyl Tripeptide-1 i Palmitoyl Tetrapeptide-7) koji dokazano stimuliše sintezu kolagena i elastina u dermisu. Deluje na ćelijskom nivou, pomažući koži da se regeneriše iznutra, čime se smanjuju bore i poboljšava čvrstina. Redovnim korišćenjem vraća se mladalačka struktura kože, a površina postaje glađa, zategnutija i blistavija. Matrixyl® 3000 je poznat kao jedna od najefikasnijih neinvazivnih alternativa estetskim tretmanima za zatezanje kože. Aloe Barbadensis Leaf Extract Ekstrakt aloe vere bogat je polisaharidima, aminokiselinama i vitaminima koji smiruju i regenerišu kožu. Deluje protivupalno i pomaže u obnavljanju barijerne funkcije, što je posebno važno kod kože izložene stresu, UV zračenju ili dehidraciji. Uz to, aloe vera poboljšava apsorpciju peptida, pojačavajući njihovo dejstvo i doprinosi glatkoj, hidriranoj koži. Hyaluronic Acid Hijaluronska kiselina (Sodium Hyaluronate) je snažan humektant koji vezuje do 1000 puta više vode od svoje težine, zadržavajući vlagu u dubljim slojevima kože. Održava optimalan nivo hidratacije, smanjuje osećaj zategnutosti i čini kožu elastičnom. Njena prisutnost u formuli podržava regenerativni efekat Matrixyl® 3000, pa zajedno pružaju sinergijsko delovanje – dubinska hidratacija i podmlađivanje u jednom koraku. Glycerin Prirodni ovlaživač koji privlači vlagu iz spoljašnje sredine i zadržava je u koži, čineći je mekšom i otpornijom. Poboljšava teksturu i doprinosi glatkom, sjajnom finišu seruma. Aqua (Water) i Dehydroacetic Acid Voda služi kao čista, neutralna baza za aktivne sastojke, dok Dehydroacetic Acid deluje kao blagi konzervans koji čuva stabilnost formule bez iritacije kože. Dodaj u listu želja Dodaj u listu želja', 'Timeless Matrixyl® 3000 Peptide Complex Serum je anti-age serum koji obnavlja tonus i elastičnost kože, čineći je zategnutijom, glatkijom i otpornijom na starenje. Ključni sastojak, Matrixyl® 3000, dokazano stimuliše sintezu kolagena i elastina, dok hijaluronska kiselina i aloe vera pružaju dubinsku hidrataciju i smiruju iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Timeless-Matrixyl®-3000-W.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
