INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (347, 163, 'Timeless Dark Circle Peptide Complex Eye Cream', 'timeless-dark-circle-eye-cream', 'Ključne prednosti: Smanjuje tamne kolutove: Haloxyl&#x2122; posvetljuje podočnjake jačanjem kapilara i razgradnjom pigmentacija. Ublažava natečenost: Eyeliss&#x2122; poboljšava limfnu drenažu i smanjuje otoke ispod očiju. Vraća elastičnost i sjaj: Hijaluronska kiselina i biljni ekstrakti hidriraju i štite kožu od isušivanja. Kome je namenjena? Preporučuje se osobama sa tamnim podočnjacima, vidljivim borama, umornim izgledom i gubitkom elastičnosti kože. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Timeless Dark Circle Peptide Complex Eye Cream? Ova krema deluje višeslojno – poboljšava mikrocirkulaciju, jača tonus kože i smanjuje vidljivost umora. Peptidni kompleksi Haloxyl&#x2122; i Eyeliss&#x2122; zajednički obnavljaju strukturu kože, smanjujući tamne kolutove i fine bore. Hijaluronska kiselina pruža intenzivnu hidrataciju, dok ekstrakti algi i lubenice štite od oksidativnog stresa i umiruju osetljivo područje. Redovnom upotrebom, koža oko očiju postaje čvršća, svetlija i elastičnija, sa vidljivo smanjenim znacima starenja i umora. Aktivni sastojci Haloxyl&#x2122; Haloxyl&#x2122; je kompleks peptida koji ciljano deluje na tamne kolutove i gubitak tonusa kože oko očiju. Pomaže u jačanju kapilara i ubrzava razgradnju pigmenata koji uzrokuju sivkast ton ispod očiju. Istovremeno poboljšava elastičnost kože i smanjuje podočnjake, čineći pogled odmornijim i svetlijim. Redovnom primenom Haloxyl&#x2122; može dugoročno ujednačiti ton kože i ublažiti znake zamora. Eyeliss&#x2122; Eyeliss&#x2122; je napredni kompleks od tri aktivne supstance koje sinergijski smanjuju upalu i podočnjake. Deluje tako što jača zidove kapilara, podstiče limfnu drenažu i ublažava zadržavanje tečnosti. Ovaj sastojak je poznat po svom učinku na „anti-puffiness“ efekat — vidljivo smanjuje natečenost i fine linije, dok kožu čini zategnutijom i glađom. Posebno je efikasan kod osoba koje pate od jutarnjih otoka i umornog izgleda očiju. Hyaluronic Acid Hijaluronska kiselina je ključni humektant koji privlači i zadržava vlagu, čime hidrira tanku kožu oko očiju i smanjuje pojavu sitnih linija uzrokovanih dehidratacijom. Povećava glatkoću i elastičnost, pa područje oko očiju postaje meko, puno i osveženo. Njena prisutnost u formuli pomaže i u boljoj apsorpciji peptida, čineći kremu efikasnijom u borbi protiv starenja. Algae Extract Ekstrakt algi bogat je antioksidansima, mineralima i polisaharidima koji štite kožu od oksidativnog stresa i ojačavaju njenu zaštitnu barijeru. Doprinosi boljem tonusu, smanjuje osetljivost i pruža umirujući efekat. Takođe poboljšava mikrocirkulaciju, što pomaže u smanjenju tamnih kolutova i sivkastog podtona kože. Dodaj u listu želja Dodaj u listu želja', 'Timeless Dark Circle Peptide Complex Eye Cream je ciljano formulisana krema za područje oko očiju koja ublažava tamne kolutove, natečenost i bore. Kombinuje hijaluronsku kiselinu, peptide Haloxyl&#x2122; i Eyeliss&#x2122;, kao i biljne antioksidanse iz algi i ekstrakta lubenice, pružajući osvežen, odmoran i zategnut izgled kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Timeless-Dark-Circle-Eye-Cream.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
