INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (348, 163, 'Timeless Argan Oil 100% Pure', 'timeless-argan-oil-100-pure', 'Ključne prednosti: Dubinska hidratacija kože: umiruje i omekšava suvu, dehidriranu i grubu kožu, vraćajući joj elastičnost. Regeneracija kose: hrani oštećene vlasi, smanjuje ispucale krajeve i vraća prirodan sjaj. Nega noktiju: jača slabe nokte i hidrira suve zanoktice. Kome je namenjeno? Za sve tipove kože osim izrazito osetljive. Posebno preporučljiv osobama sa neujednačenim tonom, pigmentacijama, borama ili sivim tenom bez sjaja. Idealan za one koji žele snažan anti-age efekat i zaštitu od oksidativnog stresa. Zašto volimo Timeless Argan Oil 100% Pure? Ovo čisto arganovo ulje dobijeno je hladnim presovanjem jezgra arganovog oraha, što mu čuva maksimalnu koncentraciju hranljivih sastojaka. Vitamin E i omega 6 i 9 masne kiseline obnavljaju lipidnu barijeru kože, čineći je mekšom, otpornijom i blistavom. Na kosi sprečava suvoću i gubitak sjaja, dok redovnom upotrebom jača vlasi i olakšava oblikovanje. Zahvaljujući laganoj teksturi, brzo se upija i ne ostavlja masan trag, pa je idealno i za lice i za telo. Aktivni sastojci Argania Spinosa Kernel Oil (100% čisto arganovo ulje) Prirodni izvor vitamina E i masnih kiselina koji regenerišu, hrane i štite kožu, kosu i nokte. Dodaj u listu želja Dodaj u listu želja', 'Timeless Argan Oil 100% Pure je luksuzno, nerafinirano arganovo ulje poreklom iz Maroka – poznato kao „tečno zlato“ zbog svoje izuzetne sposobnosti da hidrira, regeneriše i omekša kožu, kosu i nokte. Bogato vitaminom E i esencijalnim masnim kiselinama, ovo ulje pruža intenzivnu negu i prirodan sjaj bez masnog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Timeless-Argan-Oil-100-Pure.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
