INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (349, 163, 'Timeless Coenzyme Q10+Peptides Serum', 'timeless-coenzyme-q10-serum', 'Ključne prednosti: Zaštita od starenja: Koenzim Q10 štiti ćelije od oksidativnog stresa i pomaže u očuvanju energije kože. Jača tonus i elastičnost: Matrixyl® 3000 podstiče sintezu kolagena i elastina za čvršću i glađu kožu. Dubinska hidratacija: Hijaluronska kiselina intenzivno hidrira i čini kožu mekom i elastičnom. Kome je namenjen? Preporučuje se osobama sa prvim znacima starenja, smanjenom elastičnošću i beživotnim tonom kože. Idealan je za zrelu, suvu ili umornu kožu kojoj nedostaje sjaj i čvrstina. Zašto volimo Timeless Coenzyme Q10 + Peptides Serum? Ovaj serum pruža koži energiju potrebnu za regeneraciju i obnavljanje. Koenzim Q10 deluje kao snažan antioksidans koji usporava proces starenja i pomaže u očuvanju čvrstoće kože. Matrixyl® 3000, napredni kompleks peptida, stimuliše sintezu kolagena, čime se smanjuju bore i fine linije. Hijaluronska kiselina vezuje vlagu i sprečava isušivanje, čineći kožu glatkom i hidriranom tokom celog dana. Laka, nemasna formula bez mirisa brzo se upija i pogodna je za sve tipove kože, uključujući osetljivu. Aktivni sastojci Coenzyme Q10 (ubikinon) Antioksidans koji podstiče obnavljanje ćelija i štiti kožu od slobodnih radikala. Matrixyl® 3000 (Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7) Peptidni kompleks koji stimuliše sintezu kolagena i elastina. Hyaluronic Acid Ovlaživač koji vezuje vlagu i obezbeđuje dugotrajnu hidrataciju. Dodaj u listu želja Dodaj u listu želja', 'Coenzyme Q10 + Peptides Serum je antioksidativni serum koji revitalizuje umornu, beživotnu kožu i vidljivo smanjuje znake starenja. Kombinuje koenzim Q10, Matrixyl® 3000 peptide i hijaluronsku kiselinu kako bi ojačao strukturu kože, povećao elastičnost i održao optimalan nivo hidratacije.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Timeless-Coenzyme-Q10-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
