INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (352, 151, 'Shiseido Tsubaki Premium Volume & Repair Shampoo & Conditioner Set', 'shiseido-tsubaki-premium-volume-repair-shampoo-conditioner-set', 'Ključne prednosti: Dubinska obnova: Aktivni sastojci prodiru u unutrašnju strukturu vlasi i popravljaju oštećenja izazvana suvoćom i toplotom. Volumen i elastičnost: Kosa postaje vidno gušća, podatna i lepršava, sa prirodnim pokretom. Ogledalski sjaj i mekoća: Ulje kamelije i skvalan obnavljaju lipidni sloj, dajući kosi glatkoću i zdravi sjaj. Kome je namenjen? Set je idealan za osobe sa tankom, beživotnom, suvom ili oštećenom kosom kojoj nedostaje volumen, elastičnost i sjaj. Pogodan za svakodnevnu upotrebu, naročito kod kose izložene UV zracima, toploti i urbanom zagađenju. Zašto volimo Shiseido Tsubaki Premium Volume & Repair Shampoo & Conditioner Set? Ovaj luksuzni japanski set koristi tehnologiju inspirisanu tretmanima iz profesionalnih salona, poznatu kao &#8220;0-second salon care&#8221;, koja omogućava trenutan prodor hranljivih sastojaka u jezgro vlasi. Šampon nežno uklanja nečistoće i višak sebuma, istovremeno hidrira i jača tanku i oštećenu kosu. Regenerator obnavlja kutikulu vlasi, vraća elastičnost i popunjava oštećene delove, čineći kosu otpornijom i punijom. Zajedno, oni daju kosi prirodan volumen, lakoću i “salonski” završetak bez potrebe za dodatnim tretmanima. Cveto-voćni miris kamelije pruža prijatan osećaj svežine i elegancije tokom celog dana. Aktivni sastojci Camellia Japonica (ulje semena japanske kamelije) Jedan od najcenjenijih japanskih sastojaka, poznat po moći regeneracije i zaštite kose. Dubinski hrani, omekšava i štiti vlas od isušivanja, čineći kosu svilenkastom i blistavom. Royal Jelly Extract (matični mleč) Prirodni izvor aminokiselina i vitamina koji obnavljaju oštećenu kosu i vraćaju joj elastičnost. Jača strukturu vlasi i sprečava lomljenje. Glycine Soja (ekstrakt soje) Pruža biljne proteine koji obnavljaju vlakna kose i čine je otpornijom. Poboljšava punoću i teksturu, dajući kosi živost i snagu. Aminokiseline Jačaju keratinsku strukturu vlasi, pomažući kosi da povrati gustinu i otpornost. Obnavljaju oštećene delove i vraćaju prirodni sjaj. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Volume & Repair set kombinuje šampon i regenerator koji zajedno pružaju kompletnu negu kose — čiste, hidriraju i obnavljaju kosu od korena do krajeva, vraćajući joj elastičnost, punoću i prirodan sjaj. Obogaćeni uljem japanske kamelije, matičnim mlečom, aminokiselinama i sojinim ekstraktom, ovi preparati čine kosu svilenkastom, mekom i punom života već nakon prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Volume-Repair-Conditioner-4.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
