INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (353, 175, 'WHIPPED Vegan Pack Cleanser Jumbo Muhwabutter', 'whipped-vegan-pack-cleanser-jumbo-muhwabutter', 'Ključne prednosti: Regeneracija barijere kože: Kombinacija ceramida NP i niacinamida jača zaštitni sloj i smanjuje transepidermalni gubitak vode. Dubinska hidratacija: Ekstrakt smokve i hijaluronska kiselina zadržavaju vlagu i vraćaju elastičnost koži. Zaštita i obnova: Kakao puter i ekstrakt kakaa hrane kožu i deluju antioksidativno, štiteći je od spoljašnjih stresora. Kome je namenjen? Preporučuje se svim tipovima kože, posebno suvoj, osetljivoj i dehidriranoj koži koja traži blago, ali efikasno čišćenje bez narušavanja prirodne barijere. Idealno za one koji žele čistu, nahranjenu i blistavu kožu bez osećaja suvoće. Zašto volimo WHIPPED Vegan Pack Cleanser Jumbo Muhwabutter? Ovaj jedinstveni čistač ima bogatu, „whipped“ teksturu koja se pretvara u kremastu penu i temeljno uklanja nečistoće, višak sebuma i ostatke šminke, bez isušivanja kože. Ekstrakt smokve obogaćuje kožu vitaminima i prirodnim šećerima koji poboljšavaju zadržavanje vlage, dok kakao puter omekšava i obnavlja suve delove. Ceramid NP i niacinamid deluju sinergijski – prvi obnavlja lipidni sloj, a drugi umiruje upale i ujednačava ton kože. Zahvaljujući hijaluronskoj kiselini, koža ostaje hidrirana i elastična i nakon umivanja, bez osećaja zatezanja. Pogodan je za svakodnevnu upotrebu, čak i kod osetljive kože. Aktivni sastojci Ficus Carica (ekstrakt smokve) Prirodni izvor antioksidanasa i voćnih šećera koji zadržavaju vlagu u epidermu. Umiruje i revitalizuje kožu, vraćajući joj mekoću i zdrav sjaj. Theobroma Cacao (kakao puter) Bogata biljna mast koja obnavlja lipidnu barijeru i sprečava isušivanje. Čini kožu elastičnom i štiti je od spoljašnjih iritacija. Cocoa Extract (ekstrakt kakaa) Sadrži polifenole i flavonoide koji deluju antioksidativno i protivupalno. Pomaže u očuvanju kolagena i elastičnosti kože. Hyaluronic Acid (hijaluronska kiselina) Ovlaživač koji zadržava vodu u dubljim slojevima kože, čineći je zategnutom i hidriranom. Poboljšava elastičnost i smanjuje osećaj suvoće nakon čišćenja. Dodaj u listu želja Dodaj u listu želja', 'WHIPPED Vegan Pack Cleanser Jumbo Muhwabutter je veganski kremasti čistač koji istovremeno čisti i neguje kožu, pružajući osećaj svilenkaste mekoće i dubinske hidratacije. Formulisan sa ekstraktom smokve, kakao puterom i hijaluronskom kiselinom, ovaj proizvod obnavlja i jača barijeru kože, čineći je otpornijom i vidno hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/WHIPPED-Vegan-Pack-Cleanser-Jumbo-Muhwabutter.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
