INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (354, 151, 'Shiseido Tsubaki Premium EX Repair Hair Mask', 'shiseido-tsubaki-premium-ex-repair-hair-mask', 'Ključne prednosti: Trenutna regeneracija: Obnavlja oštećenu kosu i vraća joj vitalnost već nakon prvog nanošenja. Dubinska ishrana: Tsubaki ulje i biljni proteini jačaju strukturu vlasi iznutra. Profesionalni efekat kod kuće: Kosa postaje svilenkasta, glatka i blistava kao posle frizerskog tretmana. Kome je namenjena? Idealna za suvu, oštećenu, farbanu ili često stilizovanu kosu kojoj nedostaje sjaj, elastičnost i mekoća. Preporučuje se i za kosu izloženu toplotnim aparatima ili spoljašnjim oštećenjima. Zašto volimo Shiseido Tsubaki Premium EX Repair Hair Mask? Ova maska koristi inovativnu tehnologiju koja omogućava trenutnu apsorpciju hranljivih sastojaka — bez čekanja i bez potrebe za dugim držanjem. Formula obogaćena uljem kamelije (Tsubaki), keratinskim proteinima i hidratantnim komponentama dubinski regeneriše oštećene delove kose i popunjava praznine u njenoj strukturi. Rezultat je kosa koja je vidno mekša, gušća i podatna, ali bez osećaja težine. Maska istovremeno štiti od isušivanja izazvanog toplotom i UV zračenjem, čineći kosu otpornijom na svakodnevna oštećenja. Njena bogata, ali lagana tekstura obavija vlas i zaključava vlagu, a raskošan miris kamelije daje osećaj luksuza tokom upotrebe. Aktivni sastojci Tsubaki (Camellia Japonica) ulje Bogato omega-9 masnim kiselinama i antioksidansima, ovo ulje dubinski hrani kosu, vraća joj elastičnost i sprečava lomljenje. Popravlja oštećene kutikule i daje prirodan, zdravi sjaj. Keratinski proteini Pomažu u rekonstrukciji unutrašnje strukture kose, popunjavaju oštećenja i čine vlas otpornijom na toplotu i mehanička oštećenja. Kosa postaje jača i manje sklona pucanju. Glicerin i pantenol Obezbeđuju vlagu i mekoću, štiteći kosu od dehidratacije. Zajedno pomažu u zadržavanju vode unutar vlasi, čineći je hidriranom i glatkom. Biljni proteini Regenerišu površinu kose, zaglađujući je i smanjujući statički elektricitet. Daju baršunast osećaj i olakšavaju oblikovanje. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium EX Repair Hair Mask je intenzivna japanska maska za kosu koja pruža salonski efekat duboke obnove već nakon jedne upotrebe. Zahvaljujući tehnologiji „zero waiting time“, aktivni sastojci prodiru trenutno u unutrašnjost vlasi, vraćajući kosi elastičnost, mekoću i ogledalski sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/11/shiseido-tsubaki-maska.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
