INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (355, 151, 'Shiseido Tsubaki Premium Volume & Repair Shampoo', 'shiseido-tsubaki-premium-volume-repair-shampoo', 'Ključne prednosti: Volumen i elastičnost: Podiže kosu od korena i daje joj prirodnu punoću i lakoću pokreta. Dubinska hidratacija: Ulepšava teksturu i vraća vlagu kosi koja je suva ili oštećena UV zracima. Prirodni sjaj i mekoća: Ulje kamelije obavija svaku vlas i čini kosu glatkom, sjajnom i podatnom. Kome je namenjen? Idealan je za tanku, slabu i beživotnu kosu kojoj nedostaju volumen, hidratacija i sjaj. Preporučuje se osobama čija je kosa oštećena suvoćom, UV zračenjem ili toplotnim tretmanima. Zašto volimo Shiseido Tsubaki Premium Volume & Repair Shampoo? Tsubaki Premium Volume & Repair šampon koristi jedinstvenu tehnologiju inspirisanu japanskim salonima koja omogućava aktivnim sastojcima da odmah prodiru u jezgro vlasi – bez čekanja. Formulisan sa uljem japanske kamelije, poznatim po svojim regenerativnim svojstvima, ovaj šampon vraća elastičnost i sjaj kosi, dok aminokiseline jačaju vlakna i smanjuju lomljenje. Uz redovnu upotrebu, kosa postaje lepršava, lagana i puna života, bez osećaja težine. Posebna formula obnavlja vlagu i elastičnost vlasi, čineći je otpornijom na spoljašnje uticaje i toplotu. Cvetni miris kamelije obavija kosu nežnim, luksuznim tonovima koji bude osećaj čistoće i ženstvenosti. Aktivni sastojci Camellia Japonica (ulje semena japanske kamelije) Tradicionalni japanski sastojak poznat po sposobnosti da regeneriše kosu, vraća joj elastičnost i sjaj. Dubinski hidrira vlas, štiti od isušivanja i čini kosu glatkom bez otežavanja. Aminokiseline Jačaju keratinsku strukturu kose, smanjuju lomljenje i obnavljaju elastičnost. Daju kosi zdrav izgled i otpornost na oštećenja. Glycine Soja (ekstrakt semena soje) Bogat proteinima koji hrane i jačaju koren kose. Poboljšava teksturu i čini kosu gušćom i punijom. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Volume & Repair Shampoo pruža luksuznu negu kose od korena do krajeva, čineći je punijom, sjajnijom i elastičnijom već nakon prve upotrebe. Obogaćen uljem semena japanske kamelije, ovaj šampon dubinski hidrira, jača i obnavlja kosu, dajući joj prirodan volumen i mekoću uz prepoznatljiv salonski efekat.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Volume-Repair-Shampoo.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
