INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (356, 151, 'Shiseido Tsubaki Premium Volume & Repair Conditioner', 'shiseido-tsubaki-premium-volume-repair-conditioner', 'Ključne prednosti: Obnova i jačanje: Ulepšava teksturu kose i obnavlja oštećene delove vlasi zahvaljujući biljnim proteinima i matičnom mleču. Volumen i elastičnost: Kosa dobija punoću, lako se oblikuje i deluje gušće i življe. Prirodni sjaj i mekoća: Ulje kamelije vraća glatkoću i pruža zlatni odsjaj koji podseća na zdravu, negovanu kosu. Kome je namenjen? Preporučuje se osobama sa tankom, beživotnom, suvom ili oštećenom kosom koja je izgubila prirodni volumen i elastičnost. Idealno za kosu oslabljenu čestim feniranjem, bojenjem ili spoljnim stresorima. Zašto volimo Shiseido Tsubaki Premium Volume & Repair Conditioner? Inspirisan japanskim ritualima lepote, ovaj regenerator koristi ulje Tsubaki kamelije poznato po svojoj sposobnosti da regeneriše i neguje kosu još od antičkih vremena. Ekstrakt matičnog mleča hrani vlas proteinima i aminokiselinama, dok sojin ekstrakt poboljšava otpornost i elastičnost. Zahvaljujući naprednoj „0-second salon“ tehnologiji, aktivni sastojci trenutno prodiru u unutrašnjost vlasi i popravljaju oštećenja izazvana toplotom, UV zračenjem ili bojenjem. Kosa nakon upotrebe postaje punija, mekša i vidno zdravija, sa laganim, prirodnim volumenom i dugotrajnim sjajem. Cvetno-voćni miris kamelije donosi osećaj svežine i ženstvenosti tokom celog dana. Aktivni sastojci Camellia Japonica (ulje semena kamelije) Tradicijski japanski eliksir za kosu koji sadrži omega masne kiseline i antioksidanse. Dubinski hrani vlas, obnavlja oštećene kutikule i čini kosu sjajnom i glatkom, bez otežavanja. Royal Jelly Extract (matični mleč) Prirodni izvor proteina, vitamina i minerala koji revitalizuju kosu. Ojačava vlakna i obnavlja elastičnost, smanjujući lomljenje i suvoću. Glycine Soja (ekstrakt soje) Bogata aminokiselinama, soja hidrira i popravlja oštećenu kosu, povećavajući njenu otpornost i gustinu. Vraća prirodnu elastičnost i sjaj. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Volume & Repair Conditioner kombinuje tradicionalnu japansku negu sa savremenom tehnologijom „salonskog tretmana bez čekanja“. Zahvaljujući ulju semena kamelije, ekstraktu matičnog mleča i soje, ovaj regenerator prodire duboko u vlas i regeneriše je iznutra, dajući kosi volumen, elastičnost i postojan sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Volume-Repair-Conditioner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
