INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (357, 151, 'Shiseido Tsubaki Premium Moist & Repair Shampoo', 'shiseido-tsubaki-premium-moist-repair-shampoo', 'Ključne prednosti: Dubinska obnova: Aminokiseline i biljni ekstrakti regenerišu kosu i jačaju njenu strukturu od korena do vrhova. Hidratacija i zaštita: Skvalan i ulje kamelije zadržavaju vlagu, sprečavajući suvoću i oštećenja. Ogledalski sjaj: Kosa postaje glatka, meka i reflektuje svetlost poput “glass hair” efekta. Kome je namenjen? Idealan za suvu, oštećenu, farbanu ili često stilizovanu kosu kojoj nedostaje hidratacija, elastičnost i sjaj. Posebno je preporučljiv osobama čija je kosa izložena UV zracima, toploti i urbanom zagađenju. Zašto volimo Shiseido Tsubaki Premium Moist & Repair Shampoo? Ovaj luksuzni japanski šampon koristi naprednu tehnologiju koja omogućava aktivnim sastojcima da prodru u unutrašnju strukturu vlasi i regenerišu je iznutra. Aminokiseline doprinose jačanju korena i pospešuju zdrav rast kose, dok ulje kamelije dubinski hrani i obnavlja oštećene delove. Skvalan vraća vlagu i sprečava dehidrataciju izazvanu spoljašnjim faktorima i UV zračenjem. Rezultat je kosa koja izgleda negovano, elastično i glatko poput svile, sa prirodnim “glass hair” sjajem. Šampon se lako ispira, ne opterećuje kosu i ostavlja prepoznatljiv miris kamelije koji unosi osećaj čistoće i luksuza. Aktivni sastojci Camellia Japonica (ulje semena kamelije) Prirodni izvor omega masnih kiselina i antioksidanasa, ovo ulje obnavlja površinu vlasi, daje joj glatkoću i prirodan sjaj, dok istovremeno štiti od isušivanja i UV oštećenja. Aminokiseline Neophodne za jačanje keratinske strukture kose, pomažu u rekonstrukciji vlasi i smanjenju lomljenja. Daju kosi čvrstinu, elastičnost i vitalnost. Skvalane Lipid koji hidrira kosu i zadržava vlagu unutar vlasi, vraćajući joj mekoću i sjaj. Štiti od spoljašnjih oštećenja i održava prirodni balans vlage. Biljni proteini Pomažu u popunjavanju oštećenih delova vlasi i obnavljaju njenu glatku površinu, čineći kosu otpornijom i svilenkastom. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Moist & Repair šampon dubinski obnavlja kosu od korena do krajeva i vraća joj prirodnu glatkoću, elastičnost i ogledalski sjaj. Zahvaljujući aminokiselinama, skvalanu i ulju kamelije, ovaj šampon čisti, hidrira i regeneriše kosu bez isušivanja, ostavljajući je svilenkastom i sjajnom već nakon prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Moist-Repair-Shampoo.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
