INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (358, 151, 'Shiseido Tsubaki Premium Moist & Repair Conditioner', 'shiseido-tsubaki-premium-moist-repair-conditioner', 'Ključne prednosti: Dubinska hidratacija: Prodire u unutrašnju strukturu kose i vraća vlagu od korena do krajeva. Regeneracija oštećene vlasi: Biljni ekstrakti i skvalan obnavljaju kosu oštećenu UV zracima i suvoćom. Prirodni sjaj i mekoća: Kosa postaje glatka, lagana i elastična, sa postojanim cvetnim mirisom kamelije. Kome je namenjen? Namenjen je osobama sa suvom, oštećenom, farbanom ili hemijski tretiranom kosom kojoj nedostaje vlaga, elastičnost i sjaj. Posebno je koristan u uslovima izloženosti suncu, vetru ili suvom vazduhu. Zašto volimo Shiseido Tsubaki Premium Moist & Repair Conditioner? Ovaj regenerator koristi naprednu japansku tehnologiju koja omogućava aktivnim sastojcima da prodru duboko u vlas i deluju iznutra. Ulja semena kamelije bogata omega masnim kiselinama hrane i obnavljaju kosu, dok ekstrakt soje i skvalan vraćaju izgubljenu vlagu i elastičnost. Rezultat je kosa koja izgleda hidrirano i zdravo, sa prirodnim volumenom i mekoćom. Regenerator obavija svaku vlas zaštitnim slojem koji sprečava isušivanje i gubitak sjaja, čineći kosu otpornijom na spoljašnje faktore poput UV zračenja i toplote. Miris kamelije pruža osećaj čistoće i ženstvene elegancije koji traje tokom dana. Aktivni sastojci Camellia Japonica (ulje semena kamelije) Ovo dragoceno ulje bogato antioksidansima, vitaminom E i omega-9 masnim kiselinama prodire duboko u vlas, jača je iznutra i sprečava lomljenje. Pruža kosi sjaj i glatkoću bez otežavanja, a istovremeno je štiti od isušivanja i UV oštećenja. Glycine Soja (ekstrakt semena soje) Biljni protein koji obnavlja i jača oštećenu strukturu kose. Sojini peptidi pomažu u rekonstrukciji vlakana i vraćaju elastičnost i otpornost, čineći kosu zdravijom i punijom. Squalane Prirodni emolijent koji obnavlja lipidni sloj kose i zadržava vlagu unutar vlasi. Poboljšava mekoću i elastičnost, štiteći kosu od spoljašnjih faktora i oksidativnog stresa. Biljni proteini Popunjavaju oštećene delove vlasi, čineći je gušćom i glađom na dodir. Deluju kao zaštitni film koji sprečava dalje pucanje kose. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Moist & Repair regenerator intenzivno hidrira i obnavlja suvu i oštećenu kosu zahvaljujući kombinaciji ulja semena kamelije, ekstrakta soje i skvalana. Već nakon prve upotrebe kosa postaje sjajna, elastična i podatna, sa prirodnim, zdravim izgledom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Moist-Repair-Conditioner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
