INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (360, 151, 'Shiseido Tsubaki Premium Treatment Hair Water', 'shiseido-tsubaki-premium-treatment-hair-water', 'Ključne prednosti: Dubinska hidratacija: Prodire u unutrašnju strukturu vlasi i obnavlja je iznutra, pružajući elastičnost i sjaj. Zaštita od spoljašnjih uticaja: Balansira nivo vlage i štiti kosu od isušivanja i vlage iz okruženja. Uravnotežena mekoća i sjaj: Umanjuje suvoću, kovrdžavost i neposlušnost kose, čineći je glatkom i lako upravljivom. Kome je namenjen? Idealan za suvu, oštećenu, talasastu ili hemijski tretiranu kosu kojoj nedostaje sjaj i hidratacija. Preporučuje se za svakodnevnu upotrebu, naročito u uslovima suvog vazduha ili visoke vlažnosti. Zašto volimo Shiseido Professional Sublimic Aqua Intensive Mask? Ovaj sprej koristi naprednu formulu koja omogućava da aktivni sastojci prodru duboko u vlakno kose, obnavljajući oštećene delove i vraćajući prirodnu elastičnost. Tsubaki ulje i hidratantni kompleksi održavaju optimalan nivo vlage čak i u uslovima povećane vlažnosti vazduha, čime sprečavaju pojavu frizza i suvoće. Kosa dobija zategnut, elastičan izgled i živahan sjaj, dok lagana tekstura omogućava svakodnevnu upotrebu bez otežavanja vlasi. Sprej deluje trenutno, ostavljajući kosu mekom i glatkom na dodir. Miris kamelije sa cvetnim notama pruža suptilan osećaj svežine i elegancije. Aktivni sastojci Tsubaki (Camellia Japonica) ulje Prirodno bogato omega masnim kiselinama i antioksidansima, ovo ulje obnavlja oštećene delove kose, vraća elastičnost i sprečava lomljenje. Poboljšava strukturu vlasi, čineći je glatkom i sjajnom. Hidratantni kompleks Kombinacija humektanata koji zadržavaju vlagu unutar vlasi i održavaju optimalnu hidrataciju. Sprečava isušivanje izazvano toplotom i spoljnim uslovima, čineći kosu mekom i otpornom. Proteinski derivati Rekonstruišu oštećena vlakna, ojačavaju strukturu kose i vraćaju joj čvrstinu i otpornost na mehanička oštećenja. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Treatment Hair Water je lagani sprej za kosu koji dubinski hidrira i obnavlja oštećenu vlas od korena do krajeva. Već nakon prve upotrebe kosa postaje glatka, sjajna i podatna, a neukrotivi pramenovi lakši za oblikovanje.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Shiseido-Tsubaki-Premium-Treatment-Hair-Water.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
