INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (362, 142, 'Hada Labo Gokujyun Premium Cream', 'hada-labo-gokujyun-premium-hyaluronic-cream', 'Ključne prednosti: Višeslojna hidratacija: Osam tipova hijaluronske kiseline prodiru u različite slojeve kože i zadržavaju vlagu iznutra. Obnova barijere: Jača hidrolipidni sloj i smanjuje transepidermalni gubitak vode. Elastičnost i zaštita: Krema vraća koži čvrstinu i štiti je od isušivanja i spoljašnjih uticaja. Kome je namenjena? Preporučuje se osobama sa suvom, zrelom i dehidriranom kožom, kao i svima koji osećaju gubitak elastičnosti i zategnutost. Idealna je za upotrebu tokom zimskih meseci ili u suvim klimatskim uslovima. Zašto volimo Hada Labo Gokujyun Premium Hyaluronic Cream? Ova krema predstavlja intenzivnu hidratantnu negu koja deluje kao zaštitni omotač za kožu. Zahvaljujući kombinaciji hijaluronskih oblika različitih molekulskih veličina, Gokujyun Premium Hyaluronic Cream obezbeđuje vlagu u svim slojevima epidermisa i sprečava njeno isparavanje. Tekstura je bogata, ali neljepljiva i brzo se upija, pružajući osećaj dubinske regeneracije. Koža postaje primetno punija, glatkija i otpornija, dok se površinske linije izazvane dehidratacijom vidljivo ublažavaju. Formulacija je bez mirisa, alkohola i parabena, pogodna i za osetljivu kožu. Aktivni sastojci Sodium Hyaluronate Sodium Hyaluronate je klasičan oblik hijaluronske kiseline koji efikasno hidrira površinske slojeve kože. Vezivanjem vode stvara zaštitni sloj koji sprečava isušivanje i čini kožu mekom i glatkom. Poboljšava elastičnost i otpornost epiderma. Redovnim korišćenjem doprinosi postepenom smanjenju finih linija izazvanih suvoćom. Njegov efekat je trenutan, ali i kumulativan, čineći kožu hidriranom tokom celog dana. Hydrolyzed Hyaluronic Acid Hydrolyzed Hyaluronic Acid poseduje nižu molekulsku masu i prodire u dublje slojeve kože. Obnavlja unutrašnju hidrataciju i doprinosi čvrstini i glatkoći. Doprinosi elastičnosti i smanjenju osećaja zatezanja. Povećava prirodnu sposobnost kože da zadrži vlagu, čineći je punijom i otpornijom. Rezultat je vidno hidriranija i svežija koža. Crosspolymer Hyaluronic Acid Ovaj umreženi oblik hijaluronske kiseline stvara trodimenzionalnu mrežu koja zadržava vlagu duže nego standardni hijaluronat. Deluje kao rezervoar hidratacije koji oslobađa vlagu postepeno tokom dana. Daje dugotrajan osećaj mekoće i smanjuje grubu teksturu kože. Posebno je efikasan u sprečavanju dehidratacije u suvim okruženjima. Njegova elastična struktura doprinosi regeneraciji površinskog sloja kože. Fermentisana Hijaluronska kiselina Fermentisana hijaluronska kiselina dobijena procesom biofermentacije mlečne kiseline poseduje veću čistoću i bolju apsorpciju. Povećava nivo hidratacije i učvršćuje barijeru kože. Fermentacija poboljšava biodostupnost aktivnih molekula, čime se pojačava efekat hidratacije i elastičnosti. Obezbeđuje prirodni balans vlage i doprinosi smirenom, zdravom tenu. Dugotrajnom upotrebom, koža postaje otpornija i mekša. Dodaj u listu želja Dodaj u listu želja', 'Hada Labo Gokujyun Premium Hyaluronic Cream je izuzetno bogata japanska krema formulisana sa čak osam vrsta hijaluronske kiseline koje obezbeđuju dubinsku i dugotrajnu hidrataciju. Namenjena je obnovi suve, zrele i osetljive kože, vraćajući joj elastičnost, mekoću i prirodan sjaj bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Hada-Labo-Gokujyun-Premium-Hyaluronic-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
