INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (366, 142, 'Hada Labo Super Hyaluronic Acid Cleansing Oil', 'hada-labo-super-hyaluronic-acid-cleansing-oil', 'Ključne prednosti: Temeljno čišćenje: Efikasno rastvara šminku, sebum i SPF bez narušavanja hidrolipidne barijere. Dubinska hidratacija: Hijaluronska kiselina održava optimalan nivo vlage i sprečava osećaj zatezanja. Negujuće biljno ulje: Kombinacija maslinovog, makadamijinog, jojobinog i ulja šipka obnavlja i štiti kožu tokom čišćenja. Kome je namenjeno? Preporučuje se za sve tipove kože, uključujući suvu, osetljivu i zrelu kožu. Posebno je pogodan za one koji koriste SPF i šminku svakodnevno, jer temeljno, a nežno čisti bez iritacije ili osećaja suvoće. Zašto volimo Hada Labo Super Hyaluronic Acid Cleansing Oil? Ovo ulje pruža iskustvo čišćenja koje kombinuje efikasnost i nežnost – uklanja i vodootpornu šminku, a nakon ispiranja koža ostaje čista, mekana i hidrirana. Formula je izuzetno blaga, pogodna čak i za osetljivu kožu, jer ne sadrži alkohol, parabene ni mirise. Zahvaljujući hijaluronskoj kiselini, koža ne gubi vlagu tokom čišćenja, dok biljna ulja obnavljaju njen lipidni sloj. Tekstura se lako ispira, ne ostavlja mastan trag i priprema kožu za sledeće korake nege. Aktivni sastojci Maslinovo ulje (Olea Europaea Oil) Maslinovo ulje bogato je antioksidansima, posebno vitaminom E i polifenolima, koji štite kožu od oksidativnog stresa. Efikasno rastvara šminku i nečistoće dok istovremeno hrani i umiruje kožu. Njegova prirodna masna kiselina slična je lipidima kože, pa se lako apsorbuje i ne zapušava pore. Omekšava kožu i doprinosi njenom glatkom, elastičnom izgledu. Pruža zaštitu od isušivanja i spoljašnjih iritacija. Makadamijino ulje (Macadamia Integrifolia Seed Oil) Makadamijino ulje bogato je oleinskom i palmitoleinskom kiselinom koje pomažu regeneraciju kože. Vraća elastičnost i jača prirodnu barijeru kože. Pruža osećaj mekoće i sprečava transepidermalni gubitak vode. Deluje umirujuće, što ga čini pogodnim za osetljivu i suvu kožu. Zahvaljujući svojoj teksturi, lako se ispira bez masnog ostatka. Jojobino ulje (Simmondsia Chinensis Seed Oil) Jojobino ulje ima sastav sličan prirodnom sebumu kože, pa balansira lučenje ulja i održava hidriranost. Deluje antibakterijski i pomaže u sprečavanju pojave nečistoća. Omekšava kožu i poboljšava njenu teksturu. Sadrži vitamin E i sterole koji umiruju upalne procese. Daje koži svilenkast izgled bez začepljenja pora. Ulje šipka (Rosa Canina Fruit Oil) Ulje šipka bogato je esencijalnim masnim kiselinama i vitaminom C koji pospešuju regeneraciju kože. Pomaže u smanjenju ožiljaka i neujednačenosti tena. Doprinosi sintezi kolagena i održava kožu glatkom i elastičnom. Ima antioksidativno dejstvo i štiti od uticaja slobodnih radikala. U kombinaciji sa drugim uljima, poboljšava tonus i vitalnost kože. Dodaj u listu želja Dodaj u listu želja', 'Hada Labo Gokujyun Super Hyaluronic Acid Cleansing Oil je lagano, ali izuzetno efikasno ulje za čišćenje lica koje temeljno uklanja šminku, SPF i nečistoće, a pritom održava prirodnu hidrataciju kože. Formulisano sa četiri biljna ulja – maslinovim, makadamijinim, jojobinim i uljem šipka – i hijaluronskom kiselinom, ovo ulje čisti bez isušivanja i ostavlja kožu glatkom i elastičnom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Hada-Labo-Super-Hyaluronic-Acid-Cleansing-Oil.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
