INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (368, 142, 'Hada Labo Gokujyun Hyaluronic Acid Cream', 'hada-labo-gokujyun-hyaluronic-acid-cream', 'Ključne prednosti: Dubinska hidratacija: Četiri vrste hijaluronske kiseline obezbeđuju vlagu u svim slojevima kože i sprečavaju dehidrataciju. Obnova barijere: Ceramidi i glicerin jačaju lipidni sloj kože i sprečavaju gubitak vode. Glatkoća i elastičnost: Formula vraća koži mekoću, elastičnost i prirodni sjaj bez osećaja težine. Kome je namenjena? Preporučuje se osobama sa suvom, osetljivom ili dehidriranom kožom, kao i onima koje žele da povrate mekoću i prirodni balans vlažnosti. Pogodna je i za zrelu kožu kojoj je potrebna dugotrajna hidratacija i zaštita od spoljašnjih uticaja. Zašto volimo Hada Labo Gokujyun Hyaluronic Acid Cream? Krema je namenjena svakodnevnoj nezi kože kojoj nedostaje hidratacija i elastičnost. Njena tekstura bogata, ali neljepljiva, čini je idealnom i za dnevnu i za noćnu upotrebu. Zahvaljujući kombinaciji hijaluronskih oblika koji prodiru u različite slojeve epiderma, koža postaje hidrirana iznutra i zaštićena spolja. Krema ne sadrži alkohol, mirise ni parabene, pa ne iritira ni najosetljiviju kožu. Redovnom upotrebom, ten postaje ujednačeniji, a koža mekša, elastičnija i vidno osvežena. Aktivni sastojci Sodium Hyaluronate (Na-2 Hyaluronate) Sodium Hyaluronate je so hijaluronske kiseline koja prodire dublje u epiderm, vezuje vodu i obezbeđuje intenzivnu hidrataciju. Deluje kao snažan humektant koji privlači vlagu iz okoline, čineći kožu punijom i elastičnijom. Ovaj oblik hijalurona smanjuje osećaj zatezanja i suvoće, dok istovremeno obnavlja površinski sloj kože. Redovnim korišćenjem doprinosi glatkijem izgledu i povećava prirodni sjaj kože. Njegova uloga u očuvanju vlažnosti čini ga ključnim u anti-age formulacijama. Acetylated Sodium Hyaluronate Ovaj stabilizovani oblik hijalurona stvara zaštitni sloj na površini kože koji sprečava gubitak vode. Njegova molekularna struktura omogućava dugotrajnu hidrataciju čak i u suvim uslovima. Daje koži svilenkast osećaj i smanjuje grubu teksturu. Pruža dodatnu zaštitu osetljivoj i dehidriranoj koži. Održava mekoću i elastičnost tokom celog dana. Dodaj u listu želja Dodaj u listu želja', 'Hada Labo Gokujyun Hyaluronic Acid Cream je bogata, ali lagano upijajuća hidratantna krema koja obnavlja i zadržava vlagu u koži, čineći je glatkom, elastičnom i otpornom na spoljašnje uticaje. Formulacija sa četiri tipa hijaluronske kiseline različite molekulske težine pruža višeslojnu hidrataciju i dugotrajan osećaj mekoće, dok ceramidi i glicerin doprinose obnovi kožne barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Hada-Labo-Gokujyun-Hyaluronic-Acid-Cream.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
