INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (374, 128, 'Ongredients Skin Barrier Calming Lotion', 'ongredients-skin-barrier-calming-lotion', 'Ključne prednosti: Jača zaštitnu barijeru: Patentirani NB P-Complex i 9 peptida obnavljaju oštećenu barijeru kože i povećavaju njenu otpornost. Smiruje i hidrira: Centella Asiatica i Coptis Japonica trenutno ublažavaju crvenilo i iritaciju. Lagane teksture: Esencijalni losion se brzo upija, ostavljajući kožu glatkom i hidriranom bez težine. Kome je namenjen? Skin Barrier Calming Lotion je idealan za osobe sa suvom, osetljivom i iritiranom kožom, kao i za one čija je kožna barijera narušena usled preteranog čišćenja, spoljašnjih faktora ili upotrebe aktivnih sastojaka. Pogodan je i za vegane i sve tipove kože kojima je potrebna dugotrajna hidratacija i smirenje. Zašto volimo Ongredients Skin Barrier Calming Lotion? Ovaj losion kombinuje naprednu formulaciju i čiste biljne ekstrakte kako bi koži pružio dugotrajnu udobnost i otpornost. Patentirani NB P-Complex sadrži kombinaciju hidratantnih i ojačavajućih elemenata koji obnavljaju lipidnu strukturu kože, čime se smanjuje osetljivost i sprečava gubitak vlage. Kompleks 9 peptida deluje regenerativno, stimulišući sintezu kolagena i poboljšavajući elastičnost kože. Zahvaljujući Centella Asiatica i Coptis Japonica ekstraktima, koža se umiruje i vraća u ravnotežu, što ga čini idealnim izborom za suvu, reaktivnu i oštećenu kožu. Njegova tekstura, slična esenciji, brzo se upija i ne ostavlja film, već pruža osećaj svilenkaste hidratacije i svežine. Aktivni sastojci NB P-Complex NB P-Complex je patentirani kompleks razvijen da ojača prirodnu barijeru kože i spreči transepidermalni gubitak vlage. Deluje kao „zaštitni štit“ koji pomaže u obnovi lipidnog sloja, dok istovremeno održava optimalan nivo hidratacije. Smanjuje osetljivost kože i štiti je od spoljašnjih iritansa. Ovaj kompleks podržava ravnotežu mikrobioma kože i čini je otpornijom na stresne uslove okoline. Redovnom upotrebom, koža postaje zdravija, elastičnija i dugotrajno hidrirana. 9-Peptide Complex Kompleks od devet peptida obnavlja strukturu kože i stimuliše fibroblaste da proizvode više kolagena i elastina. Pomaže u smanjenju finih linija, vraćajući čvrstinu i tonus koži. Peptidi jačaju ćelijsku komunikaciju i podstiču regeneraciju tkiva, što doprinosi jačoj i otpornijoj barijeri. Njihovo sinergijsko delovanje s NB P-Complexom stvara balans između hidratacije i regeneracije. Rezultat je mekana, zategnuta i revitalizovana koža. Dodaj u listu želja Dodaj u listu želja', 'Ongredients Skin Barrier Calming Lotion je hipoalergeni, veganski losion koji obnavlja, hidrira i smiruje osetljivu kožu. Formulisan je sa patentiranim NB P-Complex sastojkom i kompleksom 9 peptida koji zajedno jačaju kožnu barijeru i poboljšavaju zadržavanje vlage. Obogaćen ekstraktima Centella Asiatica i Coptis Japonica korena, deluje umirujuće na suvu i iritiranu kožu, vraćajući joj osećaj udobnosti i prirodne elastičnosti. Njegova lagana, esencijalna tekstura ostavlja kož', 'https://beauty-health.rs/wp-content/uploads/2025/11/Ongredients-Skin-Barrier-Calming-Lotion.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
