INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (376, 118, 'MISSHA Atelo Collagen 500 Power Plumping Ampoule', 'missha-atelo-collagen-500-power-plumping-ampoule', 'Ključne prednosti: Dubinska regeneracija: atelokolagen stimuliše sintezu kolagena i popravlja strukturu kože iznutra. Efekat “plump” kože: koži vraća punoću i elastičnost, smanjuje vidljivost bora i finih linija. Brza apsorpcija: lagana tekstura se odmah upija i ostavlja osećaj svilenkaste glatkoće. Kome je namenjena? Idealna je za kožu koja pokazuje znake starenja — gubitak elastičnosti, fine linije, suvoću i neujednačen ton. Pogodna je za sve tipove kože, naročito za zrelu, suvu i umornu kožu kojoj je potrebna obnova i volumen. Zašto volimo MISSHA Atelo Collagen 500 Power Plumping Ampoule? Ova napredna anti-age ampula sadrži visoko prečišćen atelokolagen sa molekulskom masom od samo 500 Da, što mu omogućava da prodre i u dublje slojeve kože, gde podstiče sintezu prirodnog kolagena i elastina. Redovnom upotrebom, koža postaje elastičnija, gušća i otpornija na opuštanje. Ampula takođe sadrži niacinamid i adenozin, koji zajedno ujednačavaju ten, poboljšavaju teksturu i smanjuju bore. Savršeno se uklapa u svakodnevnu rutinu kao korak između tonera i kreme, dajući koži “plump” efekat — ona izgleda odmorno, zategnuto i blistavo. Formula ne ostavlja lepljiv trag i pogodna je i za osetljivu kožu. Aktivni sastojci Atelokolagen (500 Da) Atelokolagen je visoko prečišćen oblik kolagena sa uklonjenim antigenim segmentima, što omogućava bolju podnošljivost i dublju penetraciju u kožu. Zahvaljujući svojoj niskoj molekulskoj masi od 500 Da, lako prolazi kroz epidermalnu barijeru i aktivno stimuliše fibroblaste da proizvode novi kolagen i elastin. Njegova struktura bliska prirodnom kolagenu kože vraća joj čvrstinu i elastičnost. Redovnom upotrebom, smanjuje pojavu bora i opuštenosti kože, dok poboljšava njen tonus i glatkoću. Ovaj tip kolagena deluje kao trostruki mehanizam – hidrira, učvršćuje i regeneriše. Koža postaje vizuelno punija, mekša i otpornija na znakove starenja. Dodaj u listu želja Dodaj u listu želja', 'MISSHA Atelo Collagen 500 Power Plumping Ampoule je visokokoncentrisana anti-age ampula sa atelokolagenom koji prodire duboko u kožu, povećava elastičnost i vraća volumen. Zahvaljujući patentiranoj formuli sa 500 Da kolagenom, koža postaje čvršća, hidrirana i vidno zategnuta već nakon nekoliko dana redovne upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/11/MISSHA-Atelo-Collagen-500-Power-Plumping-Ampoule.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
