INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (382, 113, 'Medi-peel Peptide 9 Aqua Essence Toner', 'medi-peel-peptide-9-aqua-essence-toner', 'Ključne prednosti: Povećava elastičnost: kompleks od 9 peptida stimuliše sintezu kolagena i obnavlja čvrstoću kože. Dubinski hidrira: hijaluronska kiselina i akvaporini obnavljaju nivo vlage i sprečavaju dehidrataciju. Regeneriše i umiruje: kolagen i alantoin pomažu u obnovi površinskog sloja kože i smanjuju iritacije. Kome je namenjen? Tonik je idealan za normalnu, suvu i zrelu kožu kojoj nedostaje elastičnost i tonus. Pogodan je i za dehidriranu i osetljivu kožu jer ne sadrži alkohol ni parabene, a tekstura je dovoljno blaga za svakodnevnu upotrebu. Zašto volimo MEDI-PEEL Peptide 9 Aqua Essence Toner? Ova esencija u formi tonika sadrži visokokoncentrovane peptide koji deluju na dublje slojeve kože, podstičući prirodnu proizvodnju kolagena i elastina. Njena lagana, ali bogata tekstura ostavlja osećaj trenutne hidriranosti bez lepljivog sloja. Zahvaljujući Aqua Seal tehnologiji, vlaga se zadržava unutar kože duže vreme, dok dodatak kolagena poboljšava tonus i čini kožu mekšom i punijom. Pri redovnoj upotrebi, ten postaje ujednačeniji, a koža vidno glatkija i otpornija na spoljašnje faktore starenja. Aktivni sastojci Peptidni kompleks (9 peptida) Peptidi su kratki lanci aminokiselina koji služe kao signalne molekule i stimulišu fibroblaste da proizvode kolagen i elastin. U ovom toniku kombinovano je devet vrsta peptida različite molekulske mase koji deluju sinergijski – poboljšavaju čvrstinu, smanjuju pojavu finih linija i ubrzavaju regeneraciju kože. Rezultat je zategnuta, glatkija i otpornija koža. Hijaluronska kiselina Molekul koji privlači i zadržava vodu u ćelijama, čime poboljšava hidrataciju i elastičnost kože. U ovoj formuli koristi se niskomolekulska hijaluronska kiselina koja prodire dublje u epiderm i dugoročno smanjuje transepidermalni gubitak vlage. Kolagen Obezbeđuje strukturalnu podršku koži i pomaže u njenom zatezanju. Hidrolizovani kolagen u formuli jača kožnu barijeru, čineći kožu gušćom i otpornijom. U kombinaciji sa peptidima, podstiče regeneraciju i vraća mladalački izgled. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Peptide 9 Aqua Essence Toner je tonik-esencija visokih performansi koji kombinuje devet različitih peptida sa hijaluronskom kiselinom i kolagenom za vidljivo čvršću, hidriranu i elastičnu kožu. Namenjen je kao prvi korak nakon čišćenja, kada koži vraća vlagu, poboljšava tonus i priprema je za sledeće korake nege.', 'https://beauty-health.rs/wp-content/uploads/2025/11/medi-peel-peptide-9-aqua-essence-toner2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
