INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (388, 92, 'K-Secret Glow Serum Niacinamide 15% + Yuja', 'k-secret-glow-serum-niacinamide-15-yuja', 'Ključne prednosti: Vidno posvetljuje ten: visok procenat niacinamida i vitamin C iz Yuja voća ujednačavaju boju kože i smanjuju fleke. Jača barijeru i hidrira: pantenol, skvalan i hijaluronske komponente obnavljaju zaštitni sloj kože i zadržavaju vlagu. Vraća prirodni sjaj: glutation i biljna ulja osvežavaju kožu i čine je ujednačenom, glatkom i punom svetlosti. Kome je namenjen? Serum je namenjen osobama koje žele da posvetle kožu, smanje fleke i neujednačen ton, kao i onima koje osećaju dehidrataciju ili umoran izgled lica. Pogodan je za normalnu, mešovitu i masnu kožu, a može se koristiti i kod suve kože ako se kombinuje sa bogatijom kremom. Zašto volimo K-SECRET Glow Serum Niacinamide 15% + Yuja? Serum ima laganu, svilenkastu teksturu i prozirne mikrokapsule koje oslobađaju vitamin C i ulja tokom nanošenja. Formulisan je tako da deluje dublje — ublažava neujednačen ten, sitne nesavršenosti i tragove posle akni, dok istovremeno jača barijeru kože. Glutation i pantenol doprinose obnovi, a Yuja ekstrakt i niacinamid vraćaju koži svežinu i zdrav sjaj. Prvi utisak je hidrirana, glatka koža; dugoročno, ten postaje svetliji, odmorniji i stabilniji. Aktivni sastojci Niacinamid (15 %) Visoka koncentracija ovog oblika vitamina B3 smanjuje pigmentne nepravilnosti, poboljšava elastičnost i jača barijeru kože. Pomaže u regulisanju sebuma i vraća koži zdrav, ujednačen ton. Redovnom upotrebom, lice izgleda svežije i blistavije, a pore su vizuelno sužene. Citrus Yuja Fruit Oil Prirodni izvor vitamina C i antioksidanasa koji revitalizuju kožu i podstiču sintezu kolagena. Osvežava ten i smanjuje sivilo, dok lagano ulje hrani bez osećaja težine. Njegov citrusni miris dodatno doprinosi osećaju čistoće i vitalnosti kože. Glutation Snažan antioksidans koji deluje na tamne mrlje i neujednačen ten. Pomaže u neutralisanju slobodnih radikala i doprinosi svežem, „odmornom” izgledu kože. U kombinaciji sa niacinamidom i Yuja ekstraktom daje koži blistav, prirodan sjaj. Pantenol Poznat kao provitamin B5, deluje umirujuće, hidrira i podržava regeneraciju kože. Ublažava osećaj suvoće i iritacije, ostavljajući kožu mekom i elastičnom. Zbog svog blagog, ali dugotrajnog dejstva, odličan je za svakodnevnu upotrebu. Skvalan Biljni lipid koji nadoknađuje prirodna ulja kože i štiti je od dehidratacije. Ne zapušava pore i daje koži svilenkast osećaj. U ovoj formuli doprinosi uravnoteženju kože i pojačava sposobnost zadržavanja vlage. Dodaj u listu želja Dodaj u listu želja', 'K-SECRET Glow Serum Niacinamide 15 % + Yuja je intenzivni serum koji kombinuje visoku koncentraciju niacinamida i vitamin C iz ploda Yuja kako bi posvetlio, zagladio i revitalizovao kožu. Zahvaljujući jedinstvenoj formuli sa 15 % niacinamida, glutationom, pantenolom i biljnim uljima, ovaj serum ujedno deluje i kao tretman za neujednačen ten i kao svakodnevna doza energije za umornu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/K-SECRET-Glow-Serum-Niacinamide-15-Yuja.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
