INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (390, 96, 'Kisocare Vitamin C 35% Serum', 'kisocare-vitamin-c-35-serum', 'Ključne prednosti: Trenutna apsorpcija i visoka efikasnost: čisti vitamin C deluje direktno na kožu, ubrzava sintezu kolagena i smanjuje vidljivost fleka. Podrška prirodnoj regeneraciji: ekstrakt ječma sa Hokaida obogaćuje formulu aminokiselinama, vitaminima i mineralima koji hrane kožu. Biljna esencijalna ulja: pažljivo odabrana ulja lavande, ylang-ylanga, citrusa i geranijuma umiruju, osvežavaju i štite kožu. Kome je namenjen? Serum je namenjen osobama sa normalnom, mešovitom ili zrelom kožom, kao i onima koje žele da ublaže posledice UV-izlaganja, neujednačen ten ili gubitak sjaja. Za suvu i osetljivu kožu preporučuje se slabija koncentracija (KISOCare VC30 30 %), dok je ova varijanta idealna za kožu naviknutu na visoke doze aktivnih sastojaka. Zašto volimo KISOCare Vitamin C 35% Serum? Ovaj serum je razvijen za one koji žele snažno, ali sofisticirano dejstvo vitamina C. Zahvaljujući visokoj koncentraciji, deluje brzo – poboljšava tonus, smanjuje neujednačen pigment i vraća koži blistav, zdrav izgled. Tekstura je lagana, a formula sadrži pažljivo balansirane biljne komponente koje ublažavaju moguću iritaciju čiste askorbinske kiseline. Ekstrakt ječma sa Hokaida obogaćuje kožu vitaminima B-grupe i mineralima, dok mešavina osam esencijalnih ulja pruža prijatan miris i dodatni efekat umirenja. Redovnom upotrebom koža postaje glađa, čvršća i vidno svetlija, dok se površinske nepravilnosti postepeno ublažavaju. Aktivni sastojci Čisti vitamin C (Askorbinska kiselina) Ovaj moćni antioksidans deluje direktno u koži, stimuliše stvaranje kolagena i sprečava oštećenja izazvana UV-zračenjem i slobodnim radikalima. Za razliku od derivata, odmah se apsorbuje i pruža brze, vidljive rezultate. Redovnim korišćenjem posvetljuje tamne mrlje, ujednačava ten i vraća koži čvrstoću. Zbog svoje prirode može izazvati blago peckanje, što je uobičajeno kod proizvoda sa visokom koncentracijom čistog vitamina C. Ekstrakt ječma sa Hokaida (Coix Lacryma-Jobi Seed Extract) Dobijen iz organskog, lokalno uzgajanog ječma, ovaj ekstrakt je bogat proteinima, vlaknima i vitaminima B-grupe. Hidrira i omekšava kožu, pomaže u održavanju njene otpornosti i ravnoteže, a u kombinaciji sa vitaminom C ublažava potencijalnu iritaciju. Njegova hranljiva svojstva doprinose mekoći i zdravijem izgledu kože. Ulje kore pomorandže Osvežava ten i pruža blagi efekat posvetljivanja, dok svojom aromom umiruje i podiže raspoloženje. Bogato je antioksidansima i vitaminom C, što dodatno pojačava efekat seruma. Ulje lavande Deluje umirujuće i balansira kožu, naročito ako je sklona crvenilu. Takođe pomaže u regeneraciji epidermisa i doprinosi prijatnom osećaju tokom upotrebe. Ulje ylang-ylanga Reguliše lučenje sebuma, smanjuje napetost kože i doprinosi njenoj mekoći. Njegov prirodni, cvetni miris pruža aromaterapijski efekat i relaksaciju tokom nanošenja. Dodaj u listu želja Dodaj u listu želja', 'KISOCare Vitamin C 35% Serum je visoko koncentrovani serum sa 35 % čistog vitamina C, osmišljen da vidljivo posvetli ten, učvrsti kožu i podstakne prirodnu proizvodnju kolagena. Za razliku od derivata, ovaj serum sadrži čisti, neizmenjeni oblik vitamina C koji se direktno apsorbuje u kožu i brzo ispoljava efekte – od ujednačenijeg tena do primetne glatkoće i blistavosti.', 'https://beauty-health.rs/wp-content/uploads/2025/11/KISOCare-Vitamin-C-35-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
