INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (394, 82, 'Innisfree Retinol Green Tea PDRN Skin Booster Ampoule Gel Mask', 'innisfree-retinol-green-tea-pdrn-skin-booster-ampoule-gel-mask', 'Ključne prednosti: Regeneracija i anti-age efekat: Retinol ubrzava obnavljanje ćelija i smanjuje vidljivost bora. Dubinska hidratacija i popravka barijere: PDRN stimuliše regeneraciju i jača otpornost kože. Umiruje i štiti: Ekstrakt zelenog čaja smanjuje crvenilo i deluje antioksidativno. Kome je namenjena? Za sve tipove kože osim izrazito osetljive. Idealna za zrelu, umornu i dehidriranu kožu, kao i za kožu sa neujednačenom teksturom i gubitkom tonusa. Zašto volimo Innisfree Retinol Green Tea PDRN Skin Booster Ampoule Gel Mask? Ova inovativna hidrogel maska funkcioniše kao profesionalni “skin booster” tretman u jednoj upotrebi. Kombinacija retinola (vitamina A) i PDRN-a (polideoksiribonukleotida) deluje sinergijski: retinol podstiče obnavljanje ćelija i sintezu kolagena, dok PDRN pospešuje regeneraciju tkiva i smanjuje upalne procese. Ekstrakt zelenog čaja umiruje i štiti kožu od oksidativnog stresa, dok niacinamid i adenozin dodatno ujednačavaju ten i vraćaju elastičnost. Gel tekstura stvara efekat hlađenja, trenutno smanjuje osećaj zategnutosti i ostavlja kožu mekom, osveženom i vidljivo regenerisanom. Aktivni sastojci Retinol (vitamin A) Stimuliše sintezu kolagena, pospešuje obnovu ćelija i smanjuje fine linije i pore. PDRN (polideoksiribonukleotid) Biološki aktivan kompleks iz DNK lososa koji regeneriše i revitalizuje kožu na ćelijskom nivou. Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Snažan antioksidans koji smiruje upale i štiti kožu od stresa i zagađenja. Niacinamid (vitamin B3) Ujednačava ten, smanjuje hiperpigmentacije i poboljšava elastičnost kože. Adenozin Poboljšava tonus i glatkoću kože, smanjujući vidljivost bora. Dodaj u listu želja Dodaj u listu želja', 'Innisfree Retinol Green Tea PDRN Skin Booster Ampoule Gel Mask je intenzivna gel maska koja kombinuje retinol, PDRN i zeleni čaj za potpunu regeneraciju i osveženje kože. Namenjena je onima koji žele vidljivo glađu, čvršću i blistaviju kožu — već nakon jedne upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Innisfree-Retinol-Green-Tea-PDRN-Skin-Booster-Ampoule-Gel-Mask.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
