INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (397, 82, 'Innisfree My Body & Hair Mist Black Tea', 'innisfree-my-body-hair-mist-black-tea', 'Ključne prednosti: Oživljava telo i kosu: Trenutno osvežava i neutrališe neprijatne mirise bez lepljenja. Sofisticiran miris crnog čaja: Topao, nežno drvenast i elegantan ton koji traje satima. Bez iritacija: Dermatološki testirana formula, pogodna i za osetljivu kožu. Kome je namenjen? Za sve tipove kože i kose. Idealno za one koji žele laganu, osvežavajuću alternativu parfemu ili vole da osveže kosu i telo u pokretu. Zašto volimo innisfree My Body & Hair Mist Black Tea? Ova nežna maglica za telo i kosu spaja miris luksuza i svakodnevnu praktičnost. Formulisana tako da ne isušuje kosu i kožu, već im pruža lagani sloj svežine. Miris Black Tea odiše toplinom, elegancijom i blagom slatkoćom, što ga čini idealnim za one koji vole suptilne, ali prepoznatljive note. Formula je dermatološki testirana, bez sastojaka koji izazivaju iritacije, pa se može koristiti više puta dnevno. Savršena za osveženje nakon tuširanja, tokom dana ili kao završni dodir nakon vežbanja. Dodaj u listu želja Dodaj u listu želja', 'Innisfree My Perfumed Body & Hair Mist Black Tea donosi sofisticiran, topli miris crnog čaja koji osvežava kosu i kožu bez isušivanja. Lagana formula obavija telo nežnim aromatičnim slojem koji traje satima, ostavljajući suptilan trag elegancije i čistoće.', 'https://beauty-health.rs/wp-content/uploads/2025/11/innisfree-My-Body-Hair-Mist-Black-Tea.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
