INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (400, 67, 'Ginza Stefany Tokyo EUTHYMOL Whitening Purple Toothbrush', 'ginza-stefany-tokyo-euthymol-whitening-purple-toothbrush', 'Ključne prednosti: Efekat izbeljivanja: Specijalna vlakna pomažu u uklanjanju mrlja od kafe, čaja i duvana. Precizno čišćenje: Uži vrh četkice dopire do međuzubnih prostora i teško dostupnih mesta. Zaštita gleđi: Mekana, elastična vlakna čiste bez trenja i iritacije desni. Estetski dizajn: Luksuzna ljubičasta boja i ergonomska forma spajaju eleganciju i funkcionalnost. Kome je namenjena? Preporučuje se svima koji žele belje zube bez hemijskih sredstava i temeljno čišćenje sa blagim abrazivnim efektom. Pogodna za svakodnevnu upotrebu, uključujući osobe sa osetljivim desnima. Zašto volimo Ginza Stefany Tokyo EUTHYMOL Regular Toothbrush? EUTHYMOL Whitening Purple Toothbrush kombinuje tradicionalnu japansku preciznost i moderan pristup oralnoj higijeni. Vlakna različite gustine uklanjaju površinske mrlje, nežno poliraju zube i vraćaju im prirodan sjaj, dok mekani rubovi sprečavaju iritaciju desni. Zahvaljujući uskom i zakrivljenom vrhu, četkica omogućava temeljno čišćenje svakog zuba, čak i u teško dostupnim delovima usne duplje. Drška je lagana, neklizajuća i ergonomski oblikovana za udobno držanje i maksimalnu kontrolu pokreta. U kombinaciji sa Euthymol pastom, pruža osećaj profesionalne svežine i dugotrajnog čistoće. Dodaj u listu želja Dodaj u listu želja', 'EUTHYMOL Whitening Purple Toothbrush je elegantna japanska četkica za zube dizajnirana za efikasno uklanjanje površinskih mrlja i posvetljivanje zuba bez oštećenja gleđi. Njena fina, ali čvrsta vlakna poliraju zubnu površinu i doprinose beljem, glađem osmehu uz svakodnevnu upotrebu.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Ginza-Stefany-Tokyo-EUTHYMOL-Whitening-Purple-Toothbrush.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
