INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (401, 80, 'Illiyoon Fresh Moisture Lotion', 'illiyoon-fresh-moisture-lotion', 'Ključne prednosti: Dubinska hidratacija: Glicerin i skvalan obnavljaju vlagu i sprečavaju isušivanje kože. Ujednačen i osvežen ton kože: Niacinamid vraća blistavost i pomaže da koža izgleda odmornije i življe. Prirodna zaštita i energija kože: Ekstrakt yuja citrusa bogat antioksidansima revitalizuje kožu i smanjuje znakove umora. Lagani finiš bez masnoće: Formula se brzo upija, ostavljajući samo svež, svilenkast osećaj. Kome je namenjen? Za sve tipove kože, uključujući osetljivu, dehidriranu i kombinovanu. Pogodan za svakodnevnu upotrebu kod osoba koje žele hidrataciju bez težine i masnog filma. Zašto volimo Illiyoon Fresh Moisture Lotion? Ovaj losion donosi savršenu ravnotežu između lagane teksture i dubinske nege. Zahvaljujući niacinamidu, ten kože postaje ravnomerniji i sjajniji, dok glicerin i skvalan trenutno obnavljaju vlagu i omekšavaju površinu kože. Ekstrakt yuja citrusa, bogat vitaminom C i antioksidansima, vraća energiju umornoj koži i pomaže u regeneraciji površinskih oštećenja. Formulisan je bez mineralnih ulja i sintetičkih boja, a njegova prirodna boja potiče od ekstrakta gardenije i kakaoa. Nakon nanošenja, koža postaje meka, hidrirana i mirisno osvežena, bez masnog sloja. Savršen je za svakodnevnu upotrebu tokom cele godine, naročito u toplijim mesecima kada teže formule mogu biti previše. Aktivni sastojci Niacinamid (Vitamin B3) Ujednačava ton kože, smanjuje sivilo i vraća prirodan sjaj. Podržava zaštitnu barijeru i pomaže da koža ostane elastična i otporna na dehidrataciju. Skvalan (Squalane) Lagani emolijens koji oponaša prirodna ulja kože, sprečava gubitak vlage i čini kožu glatkom i mekom bez osećaja težine. Glicerin (Glycerin) Prirodni ovlaživač koji privlači i zadržava vlagu u koži, trenutno ublažava osećaj suvoće i doprinosi dugotrajnoj hidrataciji. Ekstrakt yuja citrusa (Citrus Junos Fruit Extract) Bogat antioksidansima i vitaminom C, revitalizuje umornu i sivu kožu, vraća joj energiju i zdrav sjaj. Ekstrakt gardenije i kakaoa (Gardenia Florida Fruit Extract, Theobroma Cacao Extract) Prirodni izvori boje i antioksidanasa; čine formulu stabilnom i doprinose svežem, prijatnom mirisu. Dodaj u listu želja Dodaj u listu želja', 'Illiyoon Fresh Moisture Lotion je lagani losion koji pruža intenzivnu, ali nekomedogenu hidrataciju, idealan za svakodnevnu negu kože lica i tela. Zahvaljujući niacinamidu, skvalanu i ekstraktu citrusa, obnavlja zaštitnu barijeru i održava kožu hidriranom tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Illiyoon-Fresh-Moisture-Lotion.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
