INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (403, 57, 'Eqqualberry Hyaltoin Flooding Serum', 'eqqualberry-hyaltoin-flooding-serum', 'Ključne prednosti: Dubinska hidratacija: Hijaluronska kiselina i alantoin obnavljaju vlagu u svim slojevima kože i umiruju iritacije. Trenutno hlađenje: 100.000 ppm ledeničke vode pruža osvežavajući efekat i sprečava isušivanje. Zaštita barijere: 5 tipova ceramida ojačavaju prirodni zaštitni sloj kože i zaključavaju vlagu. Efekat sjajne kože: Koža postaje glatka, elastična i osvežena — bez lepljivog osećaja. Kome je namenjen? Za sve tipove kože, naročito osetljivu, dehidriranu i reaktivnu kožu. Idealno za umirenje nakon izlaganja suncu, vetru, tretmanima ili pilinga. Zašto volimo EQQUALBERRY Hyaltoin Flooding Serum? Formulisan sa 50.000 ppm Hyaltoin kompleksa (hijaluronska kiselina + alantoin), serum istovremeno hidrira i smiruje kožu, pomažući u regeneraciji zaštitne barijere. Ectoin, prirodna molekula zaštite ćelija, čuva vlagu i štiti kožu od spoljašnjih agresora poput zagađenja i UV zračenja. Zahvaljujući 100.000 ppm ledeničke vode, pruža trenutno hlađenje i svežinu, dok 5 tipova ceramida (NP, AP, AS, NS, EOP) obnavljaju lipidni sloj i zadržavaju vlagu duboko u epidermu. Panthenol i beta-glukan dodatno smiruju i jačaju osetljivu kožu, a niacinamid ujednačava ten i daje zdrav sjaj. Tekstura se brzo upija, bez osećaja težine, ostavljajući kožu mekom i blistavom. Aktivni sastojci Hyaltoin (Hyaluronic Acid + Allantoin kompleks, 50.000 ppm) Dubinski hidrira i umiruje kožu, ubrzava regeneraciju ćelija i jača zaštitnu barijeru. Ektoin Prirodna aminokiselina koja čuva vlagu i štiti kožu od stresa, UV zračenja i zagađenja. Ledenička voda 100.000 ppm Osvežava i hladi kožu, smanjuje osećaj zatezanja i povećava sposobnost zadržavanja vlage. 5-Ceramide Complex (Ceramide NP, AP, AS, NS, EOP) Obnavlja lipidnu barijeru kože, zaključava vlagu i štiti od spoljašnjih uticaja. Pantenol (Provitamin B5) Dubinski hidrira, smiruje i pomaže regeneraciju kože. Niacinamid (Vitamin B3) Ujednačava ten, smanjuje sitne nepravilnosti i poboljšava elastičnost kože. Dodaj u listu želja Dodaj u listu želja', 'EQQUALBERRY Hyaltoin Flooding Serum pruža trenutni talas hidratacije zahvaljujući kombinaciji hijaluronske kiseline, alantoina i ektoina, uz dodatak ledeničke vode koja hladi i osvežava kožu. Ovaj lagani gel-serum jača barijeru kože uz 5 tipova ceramida, čineći je elastičnom, umirenom i dugotrajno hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2025/11/EQQUALBERRY-Hyaltoin-Flooding-Serum.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
