INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (405, 52, 'Dr.Melaxin Peel Shot Exfoliant Black Rice Ampoule', 'dr-melaxin-peel-shot-exfoliant-black-rice-ampoule', 'Ključne prednosti: Trojni piling efekat: nežno uklanja mrtve ćelije, višak sebuma i nečistoće. Obnova i blistavost: crni pirinač i fermenti vraćaju sjaj i elastičnost kože. Bez iritacije: PHA kiseline i pantenol čine formulu pogodnom i za osetljivu kožu. Kome je namenjen? Preporučuje se svim tipovima kože, posebno umornoj, sivkastoj, neujednačenoj i koži sa grubom teksturom. Pogodna i za osetljivu kožu zahvaljujući blagim PHA kiselinama. Zašto volimo Dr.Melaxin Peel Shot Exfoliant Black Rice Ampoule? Ova ampula predstavlja profesionalni piling tretman u jednoj bočici, razvijen tako da deluje efikasno, ali blago. Ekstrakt crnog pirinča bogat je antioksidansima i aminokiselinama koji pomažu regeneraciju kože, dok PHA kiseline (glukonolakton) odstranjuju mrtve ćelije bez izazivanja crvenila. U kombinaciji sa enzimima fermentisanog pirinča i voća, koža se nežno čisti, pore postaju manje vidljive, a ten ujednačeniji. Niacinamid i adenozin doprinose posvetljivanju i umanjenju finih linija, dok pantenol i alantoin umiruju i jačaju barijeru. Rezultat je glatka, mekana i revitalizovana koža koja bolje upija naredne korake nege. Ampula se može koristiti kao blagi eksfolijant nekoliko puta nedeljno, bez potrebe za dodatnim pilingom. Aktivni sastojci Ekstrakt crnog pirinča (Oryza Sativa Black Rice Extract) Prirodni antioksidans bogat antocijaninima koji štite kožu od oksidativnog stresa i stimulišu regeneraciju. Pomaže u zaglađivanju i ujednačavanju tena. PHA kiseline (Gluconolactone, Lactobionic Acid) Blago eksfoliraju površinski sloj kože, poboljšavaju teksturu i hidraciju, bez izazivanja iritacija. Idealne za osetljivu kožu. Fermentisani ekstrakti (Rice Ferment Filtrate, Lactobacillus Ferment) Obnavljaju mikrobiom kože, poboljšavaju njenu otpornost i daju zdrav, sjajan izgled. Niacinamid (Vitamin B3) Ujednačava ten, smanjuje tamne fleke i stimuliše sintezu ceramida, jačajući barijeru kože. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin Peel Shot Exfoliant Black Rice Ampoule je visokoefikasna piling-ampula koja kombinuje enzimski, hemijski i mehanički efekat uz pomoć ekstrakta crnog pirinča, PHA kiselina i fermentisanih sastojaka. Koža postaje glatka, sjajna i vidno pročišćena bez iritacije — već posle prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.Melaxin-Peel-Shot-Exfoliant-Black-Rice-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
