INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (406, 57, 'Eqqualberry Deep Cera Bakuchiol Plumping Capsule Cream', 'eqqualberry-deep-cera-bakuchiol-plumping-capsule-cream', 'Ključne prednosti: Prirodni retinol efekat: bakuciol stimuliše proizvodnju kolagena i ublažava bore bez nadražaja. Intenzivna hidratacija i elastičnost: ceramidi i hijaluronska kiselina jačaju barijeru i vraćaju vlagu. Efekat punije kože: mikro kapsule sa kolagenom i uljima trenutno zaglađuju površinu i vraćaju sjaj. Kome je namenjena? Za sve tipove kože, uključujući osetljivu. Posebno preporučena za kožu sa prvim znacima starenja, gubitkom čvrstine i dehidratacijom. Zašto volimo EQQUALBERRY Deep Cera Bakuchiol Plumping Capsule Cream? Ova moderna “capsule cream” formula spaja biljni bakuciol, poznat kao prirodna alternativa retinolu, sa hranljivim ceramidima i kolagen kapsulama koje se pri nanošenju otapaju i oslobađaju aktivne sastojke direktno u kožu. Bakuciol podstiče regeneraciju i sintezu kolagena, smanjuje vidljivost bora i poboljšava tonus, dok ceramidi i beta-glukan jačaju zaštitnu barijeru i sprečavaju gubitak vlage. Hijaluronska kiselina pruža trenutnu i dugotrajnu hidrataciju, a biljni ekstrakti poput moringe i goji bobica doprinose antioksidativnoj zaštiti. Tekstura je bogata, ali lagana i brzo se upija, ostavljajući kožu mekom, zategnutom i punijom. Već nakon nekoliko dana, lice izgleda odmornije i elastičnije, sa prirodnim sjajem. Aktivni sastojci Bakuciol (Bakuchiol) Biljna alternativa retinolu – podstiče sintezu kolagena, poboljšava elastičnost kože i ujednačava ten, bez iritacije tipične za retinoide. Ceramidi (Ceramide NP, Ceramide AP) Jačaju kožnu barijeru, sprečavaju transepidermalni gubitak vode i štite od spoljašnjih agresora. Kolagen kapsule (Collagen Microcapsules) Topljive mikrokapsule koje obnavljaju strukturu kože i vraćaju joj zategnut, puniji izgled. Hijaluronska kiselina (Sodium Hyaluronate) Dubinski hidrira, zaglađuje površinu i daje koži svež, elastičan izgled. Beta-Glukan Prirodni polisaharid koji jača imunitet kože i smanjuje crvenilo, pružajući dodatnu zaštitu osetljivoj koži. Ekstrakt moringe i goji bobica (Moringa Oleifera Seed Extract, Lycium Barbarum Fruit Extract) Bogati antioksidansima koji neutrališu slobodne radikale i doprinose zdravom, blistavom tenu. Dodaj u listu želja Dodaj u listu želja', 'EQQUALBERRY Bakuchiol Plumping Capsule Cream kombinuje biljni retinol – bakuciol – sa ceramidima i kolagen kapsulama koje vidljivo zatežu i regenerišu kožu. Savršena za one koji žele efekat retinola, ali bez iritacije – pruža elastičnost, hidrataciju i prirodan “plump” izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/11/EQQUALBERRY-Deep-Cera-Bakuchiol-Plumping-Capsule-Cream.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
