INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (407, 52, 'Dr.Melaxin BP Spicule Plumping Lip Shot', 'dr-melaxin-bp-spicule-plumping-lip-shot', 'Ključne prednosti: Efekat punijih usana: BP spikule aktiviraju cirkulaciju i stimulišu prirodnu regeneraciju. Regeneracija i hidratacija: hijaluronska kiselina i pantenol vraćaju vlagu i elastičnost usana. Anti-age efekat: peptidi i kolagen poboljšavaju teksturu i smanjuju fine linije oko usana. Kome je namenjen? Idealno za sve koji žele prirodno punije, hidrirane i negovane usne. Posebno preporučljivo kod suvih, ispucalih ili starenjem istanjenih usana. Zašto volimo Dr.Melaxin BP Spicule Plumping Lip Shot? Ovaj napredni serum koristi BP spikule — mikroskopske biološke iglice morskog porekla koje prodiru u površinski sloj kože usana i aktiviraju prirodne procese obnavljanja. Za razliku od običnih “tingle” sjajeva, formula deluje u dubljim slojevima, podstičući mikrocirkulaciju i sintezu kolagena. Usne postaju prirodno punije, čvršće i glatkije već nakon nekoliko dana korišćenja. Hijaluronska kiselina obezbeđuje dubinsku hidrataciju, dok pantenol i peptidi regenerišu i omekšavaju ispucalu kožu. Uz redovnu upotrebu, kontura usana postaje izraženija, a fine bore vidno ublažene. Tekstura seruma je lagana, nelepljiva i može se koristiti samostalno ili kao baza pre ruža. Aktivni sastojci BP Spicule (biološke mikroiglice) Mikroskopske iglice morskog porekla koje prodiru u površinski sloj kože i stimulišu mikrocirkulaciju, čime pospešuju regeneraciju i povećavaju volumen usana. Hijaluronska kiselina (Hyaluronic Acid) Dubinski hidrira, popunjava sitne linije i vraća elastičnost, dajući usnama glatkoću i pun izgled. Pantenol (Panthenol) Umiruje, obnavlja i omekšava kožu usana, sprečavajući isušivanje i pucanje. Kolagen (Collagen) Poboljšava čvrstinu i elastičnost tkiva, doprinosi punijem i glatkijem izgledu usana. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin BP Spicule Plumping Lip Shot je inovativni serum za usne koji koristi mikroskopske BP spikule (mikroiglice) kako bi aktivirao mikrocirkulaciju, pospešio regeneraciju i stvorio efekat prirodnog volumena. Usne postaju glatkije, punije i bolje hidrirane — bez potrebe za invazivnim tretmanima.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.Melaxin-BP-Spicule-Plumping-Lip-Shot-.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
