INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (408, 51, 'Dr.Jart+ Cryo Rubber Soothing Mask Set', 'dr-jart-cryo-rubber-soothing-mask-set', 'Ključne prednosti: Trenutno umiruje: alantoin i pantenol smanjuju osećaj zatezanja i iritacije. Efekat hlađenja: inovativna gumena maska hladi i ublažava crvenilo kože. Dubinska hidratacija: ekstrakti algi i biljnih ulja obnavljaju kožnu barijeru i vraćaju elastičnost. Kome je namenjena? Preporučuje se osetljivoj, dehidriranoj, iritiranoj ili koži sklonoj crvenilu. Idealan izbor za sve tipove kože kojima je potrebna regeneracija i umirenje nakon spoljašnjih stresora. Zašto volimo Dr.Jart+ Cryo Rubber Soothing Mask Set? Maska koristi Cryo tehnologiju inspirisanu dermatološkim tretmanima hlađenja kože kako bi smanjila upalne procese i stres na koži. Prvi korak, ampula sa alantoinom i biljnim ekstraktima, obezbeđuje trenutnu hidrataciju i umirenje, dok drugi korak – gumena maska – pojačava efekat hlađenja i zaključava vlagu u epidermu. Tokom tretmana, maska formira blagi okluzivni sloj koji povećava apsorpciju aktivnih sastojaka i smanjuje transepidermalni gubitak vode. Nakon upotrebe, koža postaje mekša, elastičnija i vidno smirenija. Ovaj tretman je posebno koristan nakon izlaganja suncu, vetru, suvom vazduhu ili agresivnim kozmetičkim procedurama. Aktivni sastojci Alantoin (Allantoin) Poznat po snažnom umirujućem i regenerativnom dejstvu. Ubrzava obnovu ćelija, smanjuje iritacije i vraća osećaj udobnosti osetljivoj koži. Pantenol (Provitamin B5) Djeluje hidratantno i umirujuće, jača zaštitnu barijeru i pomaže koži da zadrži vlagu. Poboljšava mekoću i elastičnost kože. Ekstrakt morskih algi (Seaweed Extract) Bogate mineralima i antioksidansima, alge obnavljaju i jačaju kožu, smanjujući oštećenja izazvana stresom i spoljnim faktorima. Ekstrakt kamilice (Chamomile Extract) Djeluje protivupalno i antimikrobno, ublažava crvenilo i osvežava ten. Idealna za kožu sklonu iritacijama. Hijaluronska kiselina (Hyaluronic Acid) Zadržava vlagu u dubljim slojevima kože i poboljšava njen tonus. Daje koži glatkoću i hidrirani, puniji izgled. Dodaj u listu želja Dodaj u listu želja', 'Dr. Jart+ Cryo Rubber Soothing Mask pruža trenutno umirenje, hlađenje i regeneraciju kože zahvaljujući formuli sa alantoinom i biljnim ekstraktima. Ovaj dvostepeni tretman hidrira, smanjuje crvenilo i vraća koži osećaj svežine i udobnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.Jart-Cryo-Rubber-Soothing-Mask-Set.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
