INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (409, 51, 'Dr. Jart+ Cryo Rubber Firming Mask Set', 'dr-jart-cryo-rubber-firming-mask-set', 'Ključne prednosti: Efekat hlađenja i zatezanja: pruža trenutno osveženje i poboljšava tonus kože. Dubinska hidratacija: glicerol i biljni ekstrakti povećavaju vlagu i elastičnost kože. Profesionalni efekat kod kuće: inovativna gumena maska obezbeđuje bolju apsorpciju aktivnih sastojaka. Kome je namenjena? Idealna za vrlo suvu, oštećenu i osetljivu kožu, kao i za kožu sa narušenom barijerom usled hladnog vremena, agresivnih tretmana ili dehidratacije. Pogodna i za osobe sa atopijskom ili zrelom kožom koja traži dubinsku regeneraciju. Zašto volimo Dr. Jart+ Cryo Rubber Firming Mask Set? Ova inovativna maska u dva koraka koristi Cryo tehnologiju inspirisanu profesionalnim tretmanima hlađenja kože. Prvi korak — ampula sa visokom koncentracijom glicerola, kolagena i biljnih ekstrakata — dubinski hidrira i priprema kožu. Drugi korak — gumena maska obogaćena algama i ekstraktom bobica — obavija lice, hladi kožu i “zaključava” vlagu, čime pojačava dejstvo aktivnih sastojaka. Efekat je trenutno zategnuta, osvežena i punija koža, sa poboljšanom elastičnošću i tonusom. Redovnim korišćenjem, ten postaje čvršći, glatkiji i blistaviji. Aktivni sastojci Glicerol (Glycerin) Prirodni ovlaživač koji vezuje i zadržava vlagu u epidermu. Omekšava kožu, povećava elastičnost i sprečava isušivanje, ostavljajući kožu glatkom i punijom. Hidrolizovani kolagen (Hydrolyzed Collagen) Podstiče sintezu prirodnog kolagena u koži i poboljšava njenu strukturu. Doprinosi čvrstini i tonusu kože, smanjuje pojavu finih linija i bora. Ekstrakt morskih algi (Seaweed Extract) Bogate mineralima i antioksidansima, alge hrane i revitalizuju kožu, jačaju barijeru i štite od spoljašnjih stresora. Deluju umirujuće i doprinose ujednačenom tenu. Ekstrakt bobica (Berry Extract) Prirodni izvor vitamina C i polifenola koji deluju antioksidativno. Štiti kožu od oštećenja slobodnim radikalima i poboljšava njen sjaj i svežinu. Alantoin (Allantoin) Poznat po umirujućem i regenerativnom dejstvu. Ubrzava obnovu ćelija i smanjuje iritacije, čineći kožu mekom i otpornom. Dodaj u listu želja Dodaj u listu želja', 'Dr. Jart+ Cryo Rubber Firming Mask je profesionalni tretman u dve faze koji kombinuje koncentrovanu ampulu sa glicerolom i gumenu masku za efekat hlađenja, zatezanja i osveženja kože. Formula hidrira i učvršćuje kožu, dok gumena maska “zaključava” aktivne sastojke, sprečavajući isparavanje vlage.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.-Jart-Cryo-Rubber-Firming-Mask-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
