INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (410, 51, 'Dr. Jart+ Cicapair Intensive Soothing Repair Treatment Lotion', 'dr-jart-cicapair-intensive-soothing-repair-treatment-lotion', 'Ključne prednosti: Trenutno umiruje: Centella Asiatica i alantoin ublažavaju crvenilo i iritacije. Jača i obnavlja barijeru kože: ceramidi i niacinamid obnavljaju lipidni sloj i sprečavaju gubitak vlage. Lagano, ali efikasno delovanje: vodena formula hladi, hidrira i čini kožu glatkijom bez masnog filma. Kome je namenjen? Preporučuje se osetljivoj, suvoj, iritiranoj ili reaktivnoj koži, kao i koži kojoj je potrebna regeneracija nakon dermatoloških tretmana, pilinga ili izlaganja stresnim uslovima. Pogodan je i za masnu i kombinovanu kožu jer ne ostavlja masni trag. Zašto volimo Dr. Jart+ Cicapair Intensive Soothing Repair Treatment Lotion? Ovaj losion predstavlja ključni korak u Cicapair&#x2122; rutini za regeneraciju i umirenje kože. Formula kombinuje Centella Asiatica kompleks (asiaticoside, madecassoside, asiatic acid, madecassic acid) koji obnavlja oštećenu kožu i smanjuje mikroupale, uz pantenol i alantoin koji trenutno smiruju osećaj neprijatnosti. Zahvaljujući dodatku ceramida i niacinamida, losion ojačava barijeru, poboljšava elastičnost i održava vlagu u epidermu. Lagana tekstura omogućava brzo upijanje i priprema kožu za sledeće korake nege — serum i kremu. Koža postaje vidno hidrirana, elastična i otpornija na spoljašnje faktore. Idealno rešenje za svakodnevno umirivanje kože sklone crvenilu i iritacijama. Aktivni sastojci Centella Asiatica Complex (asiaticoside, madecassoside, asiatic acid, madecassic acid) Biljni kompleks koji ubrzava regeneraciju kože, smanjuje inflamaciju i crvenilo, i jača mikrocirkulaciju. Obnavlja tkivo i vraća koži prirodnu otpornost. Alantoin Umiruje, omekšava i štiti osetljivu kožu. Podstiče obnovu ćelija i jača barijeru, sprečavajući gubitak vlage. Niacinamid (vitamin B3) Reguliše sebum, smanjuje upale i posvetljuje neujednačen ten. Deluje sinergijski sa ceramidima u obnovi zaštitne funkcije kože. Ceramide NP Lipid koji jača zaštitni sloj kože, obnavlja teksturu i sprečava isušivanje. Povećava elastičnost i otpornost kože na stresore. Pantenol (provitamin B5) Hidratantni agens koji umiruje, obnavlja i ublažava osećaj zatezanja. Idealno deluje kod dehidrirane i iritirane kože. Dodaj u listu želja Dodaj u listu želja', 'Dr. Jart+ Cicapair Intensive Soothing Repair Treatment Lotion je lagani tretman koji kombinuje ekstrakte Centella Asiatica biljke, alantoin i ceramide kako bi smirio, hidrirano i ojačao osetljivu kožu. Njegova tečna, ali hranljiva tekstura obnavlja zaštitnu barijeru i vraća koži osećaj balansa i otpornosti.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.-Jart-Cicapair-Intensive-Soothing-Repair-Treatment-Lotion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
