INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (411, 51, 'Dr. Jart+ Cicapair Intensive Soothing Repair Serum', 'dr-jart-cicapair-intensive-soothing-repair-serum', 'Ključne prednosti: Umiruje i hladi kožu: Centella Asiatica i R-Protector peptid ublažavaju iritacije i trenutno smanjuju crvenilo. Jača barijeru kože: alantoin i ceramidi povećavaju otpornost i smanjuju osetljivost kože na spoljašnje faktore. Lagano, ali efikasno delovanje: brzo se upija i pruža intenzivnu hidrataciju bez lepljivog osećaja. Kome je namenjen? Preporučuje se osobama sa osetljivom, iritiranom, suvom ili reaktivnom kožom, kao i onima koji žele da ojačaju barijeru posle dermatoloških tretmana. Pogodan je za sve tipove kože, uključujući masnu i kombinovanu. Zašto volimo Dr. Jart+ Cicapair Intensive Soothing Repair Serum? Serum je deo Cicapair™ linije i dizajniran je za kožu sklonu crvenilu, iritacijama i upalama. Njegova formula sadrži visoku koncentraciju Centella Asiatica kompleksa (asiaticoside, madecassoside, asiatic acid i madecassic acid), koji pomažu koži da se regeneriše i umiri već nakon prvog nanošenja. R-Protector Peptid deluje kao biološki “štit”, smanjujući osetljivost kože i jačajući ćelijsku otpornost na stres. Alantoin dodatno smiruje i ubrzava oporavak, dok ceramidi i niacinamid učvršćuju barijeru i poboljšavaju elastičnost. Tekstura seruma je vodenkasta i brzo se upija, ostavljajući kožu mekom, hidriranom i osveženom. Idealan je kao svakodnevna podrška koži koja reaguje na promene temperature, vlagu ili tretmane. Aktivni sastojci Centella Asiatica Complex (asiaticoside, madecassoside, asiatic acid, madecassic acid) Obnavlja i umiruje osetljivu kožu, stimuliše sintezu kolagena i ubrzava zaceljivanje mikropovreda. Deluje protivupalno i smanjuje vidljivo crvenilo. R-Protector Peptide Peptid sa intenzivnim umirujućim dejstvom koji jača otpornost kože na spoljašnje stresore i smanjuje preosetljivost. Alantoin Jača zaštitnu barijeru kože, umiruje iritacije i doprinosi regeneraciji oštećenog tkiva. Poboljšava elastičnost i zadržava vlagu. Niacinamid (vitamin B3) Posvetljuje ten, smanjuje upale i doprinosi obnovi lipidne barijere. Poboljšava otpornost kože i ujednačava teksturu. Ceramide NP Lipid koji sprečava gubitak vlage i jača kožnu barijeru, čineći kožu otpornijom i hidriranijom. Pantenol (provitamin B5) Hidratantni i umirujući sastojak koji obnavlja površinu kože i ublažava osećaj suvoće i zatezanja. Dodaj u listu želja Dodaj u listu želja', 'Dr. Jart+ Cicapair Intensive Soothing Repair Serum pruža trenutno olakšanje osetljivoj, reaktivnoj i nadraženoj koži zahvaljujući kombinaciji Centella Asiatica ekstrakata, alantoina i R-Protector peptida. Ovaj lagani, ali snažni serum obnavlja barijeru kože, smanjuje crvenilo i vraća ravnotežu bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.-Jart-Cicapair-Intensive-Soothing-Repair-Serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
