INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (413, 51, 'Dr. Jart+ Ceramidin Ultra Moisturizing Cream', 'dr-jart-ceramidin-ultra-moisturizing-cream', 'Ključne prednosti: Dubinska obnova barijere: sedmostruki kompleks ceramida jača i regeneriše zaštitni sloj kože. Dugotrajna hidratacija: biljna ulja i pantenol zadržavaju vlagu i sprečavaju isušivanje. Zaštita i elastičnost: bogata, ali umirujuća formula štiti kožu od spoljašnjih stresora i vraća joj otpornost. Kome je namenjena? Idealna za vrlo suvu, oštećenu i osetljivu kožu, kao i za kožu sa narušenom barijerom usled hladnog vremena, agresivnih tretmana ili dehidratacije. Pogodna i za osobe sa atopijskom ili zrelom kožom koja traži dubinsku regeneraciju. Zašto volimo Dr. Jart+ Ceramidin Ultra Moisturizing Cream? Ova krema predstavlja najintenzivniju verziju čuvene Ceramidin™ linije, formulisanu za kožu kojoj nedostaje lipida i vlage. Zahvaljujući kompleksu od sedam različitih ceramida, koža dobija snažnu lipidnu podršku koja obnavlja oštećenu barijeru i sprečava dehidraciju. Tekstura je bogata, ali se brzo topi pri kontaktu s kožom, stvarajući zaštitni film koji sprečava isparavanje vode. Pantenol i beta-glukan dodatno umiruju iritacije i poboljšavaju elastičnost, dok biljna ulja i skvalan omekšavaju i hrane epiderm. Redovnom upotrebom, koža postaje glatka, meka i vidno revitalizovana, čak i u ekstremnim uslovima poput hladnoće, vetra ili suvog vazduha. Krema je dermatološki testirana i ne sadrži veštačke mirise ni parabene, što je čini pogodnom i za osetljivu kožu. Aktivni sastojci Ceramidi Lipidi koji jačaju i obnavljaju kožnu barijeru, sprečavaju gubitak vlage i povećavaju otpornost kože. Rekonstruišu međustanične veze u epidermu i čine kožu elastičnijom i otpornijom na spoljašnje stresore. Holesteroli Ključni lipidi i prekursori koji doprinose regeneraciji i stabilnosti barijere. Holesterol sinergijski deluje sa ceramidima, obnavljajući strukturu lipidnog sloja i povećavajući njegovu fleksibilnost i otpornost. Pantenol (provitamin B5) Obnavlja i smiruje osetljivu kožu, jača zaštitni sloj i sprečava isušivanje. Deluje protivupalno i doprinosi mekoj, elastičnoj teksturi kože. Beta-glukan Umiruje iritiranu kožu i ubrzava regeneraciju. Deluje kao zaštitni polisaharid koji poboljšava otpornost kože i održava optimalnu hidrataciju. Skvalan Prirodni emolijent koji obnavlja lipidnu ravnotežu i poboljšava mekoću kože. Štiti od isušivanja i daje koži svilenkast osećaj. Ulje makadamije (Macadamia Integrifolia Seed Oil) Hranljivo biljno ulje bogato masnim kiselinama i antioksidansima. Obnavlja lipidni sloj, poboljšava elastičnost i smanjuje osećaj zatezanja. Dodaj u listu želja Dodaj u listu želja', 'Dr. Jart+ Ceramidin Ultra Moisturizing Cream je izuzetno hranljiva krema formulisana sa sedam vrsta ceramida i biljnim uljima za intenzivnu hidrataciju i obnovu suve, osetljive kože. Njena gustа, zaštitna tekstura obnavlja barijeru kože, smanjuje transepidermalni gubitak vode i vraća osećaj mekoće i elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/11/Dr.-Jart-Ceramidin-Ultra-Moisturizing-Cream-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
