INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (416, 40, 'Cosrx One Step Original Clear Pad', 'cosrx-one-step-original-clear-pad', 'Ključne prednosti: Kontrola sebuma i pora: BHA kiselina čisti pore i sprečava njihovo zapušavanje. Umirivanje kože: ekstrakt vrbine i alantoin ublažavaju crvenilo i iritacije. Hidratacija i ravnoteža: hijaluronska kiselina i alantoin održavaju vlagu i mekoću kože nakon eksfolijacije. Kome je namenjen? Preporučuju se osobama sa masnom, kombinovanom ili problematičnom kožom sklonoj zapušavanju pora, mitiserima i povremenim aknama. Pogodni su i za početnike u upotrebi BHA kiselina jer pružaju blagi, ali efikasan efekat bez iritacija. Zašto volimo COSRX One Step Original Clear Pad? Ovi praktični jastučići namenjeni su svakodnevnom održavanju čiste, uravnotežene kože. Formula sadrži prirodni derivat salicilne kiseline iz ekstrakta kore vrbe (Salix Alba Bark Extract), koji deluje kao blagi eksfolijant i čisti pore bez izazivanja iritacija. Uklanja višak sebuma, ostatke šminke i mrtve ćelije, dok istovremeno održava pH kože u optimalnom rasponu. Umirujući sastojci poput alantoina i pantenola ublažavaju crvenilo, dok hijaluronska kiselina zadržava vlagu i sprečava osećaj suvoće. Redovnim korišćenjem ten postaje čistiji, pore deluju manje, a površina kože glađa i ujednačenija. Svaki jastučić ima dve strane — reljefnu za blagu fizičku eksfolijaciju i glatku za toniranje i umirivanje kože. Idealni su za brzo osveženje kože ujutru, posle vežbanja ili kao korak pre seruma i kreme. Aktivni sastojci Salix Alba (Willow) Bark Extract Prirodni izvor salicilne kiseline (BHA) koji blago eksfolira kožu, čisti pore i pomaže u regulisanju sebuma. Deluje antibakterijski i protuupalno, čineći ga idealnim za problematičnu i masnu kožu. Salicylic Acid Beta-hidroksi kiselina koja prodire u pore, uklanja višak sebuma i sprečava pojavu akni. Ublažava upalne procese i doprinosi čistijoj i glatkijoj površini kože. Alantoin Umiruje osetljivu kožu, smanjuje crvenilo i podržava regeneraciju nakon eksfolijacije. Obezbeđuje prijatan osećaj mekoće i pomaže koži da se brže oporavi. Hijaluronska kiselina Zadržava vlagu u koži i sprečava isušivanje nakon hemijskog pilinga. Održava elastičnost i doprinosi glatkom, hidriranom izgledu tena. Pantenol (provitamin B5) Jača barijeru kože, umiruje upale i pomaže u obnavljanju oštećenih površinskih slojeva. Daje koži osećaj osveženja i smanjuje iritacije koje mogu nastati posle eksfolijacije. Dodaj u listu želja Dodaj u listu želja', 'COSRX One Step Original Clear Pad su jastučići natopljeni blagom formulom sa salicilnom kiselinom (BHA) i ekstraktom vrbe, namenjeni za svakodnevno čišćenje i prevenciju nepravilnosti. Efikasno uklanjaju višak sebuma, čiste pore i smanjuju pojavu akni bez isušivanja kože.', 'https://beauty-health.rs/wp-content/uploads/2025/11/COSRX-One-Step-Original-Clear-Pad.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
