INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (417, 40, 'Cosrx Master Patch Intensive', 'cosrx-master-patch-intensive', 'Ključne prednosti: Brže zaceljivanje: hidrokoloidni materijal apsorbuje tečnost i stvara optimalno vlažno okruženje za regeneraciju kože. Zaštita od bakterija i dodirivanja: deluju kao fizička barijera koja sprečava kontaminaciju i mehaničko oštećenje kože. Diskretan izgled i snažno prijanjanje: ultratanki, prozirni flasteri ostaju neprimetni i dobro prijanjaju tokom dana ili noći. Kome je namenjen? Preporučuje se osobama sa povremenim ili upalnim aknama, kao i onima koji žele da spreče dodirivanje kože i ubrzaju proces zarastanja bez isušivanja. Pogodni su za sve tipove kože, uključujući osetljivu. Zašto volimo COSRX Master Patch Intensive? Flasteri su osmišljeni za brzo i efikasno tretiranje pojedinačnih akni, bez potrebe za agresivnim preparatima. Hidrokoloidna osnova u kombinaciji sa film-former komponentama apsorbuje tečnost iz upalnog područja i formira zaštitnu barijeru koja sprečava dalje širenje bakterija. Salicilna kiselina deluje eksfolijantno i pročišćava pore, dok ulje čajevca ima antibakterijsko i umirujuće dejstvo, smanjujući otok i crvenilo. Polimeri i emolijensi poput Polyisobutene i Hydrogenated Poly(C6-20 Olefin) obezbeđuju savršeno prijanjanje uz kožu, a istovremeno sprečavaju isušivanje. Flasteri su gotovo nevidljivi, izuzetno tanki i prilagođeni upotrebi tokom dana ili noći. Redovnim korišćenjem dolazi do bržeg sazrevanja i povlačenja akni, a rizik od ožiljaka i tamnih mrlja je minimalan. Ova formulacija je posebno efikasna kod upalnih i zatvorenih akni, bez agresivnog efekta na okolnu kožu. Aktivni sastojci Cellulose Gum Zgušnjivač koji stabilizuje teksturu i povećava viskoznost formulacije. Obezbeđuje elastičnost hidrokoloidnog sloja i omogućava ravnomerno oslobađanje aktivnih sastojaka tokom nošenja flastera. Hydrogenated Poly(C6-20 Olefin) Emolijent koji formira zaštitni film i čini flaster fleksibilnim. Poboljšava elastičnost materijala i smanjuje isušivanje tretiranog područja, čuvajući vlažnost kože. Polyisobutene Film-former koji poboljšava prijanjanje flastera na kožu i osigurava da aktivni sastojci ostanu na mestu delovanja. Daje stabilnost i otpornost na vlagu, čineći flaster dugotrajnijim i udobnim. Styrene/Isoprene Copolymer Polimer koji pruža fleksibilnost i čvrstoću strukturi flastera. Omogućava da flaster ostane zalepen i na pokretnim delovima kože, dok održava optimalno vlažno okruženje za zarastanje. Salicylic Acid (BHA kiselina) Beta-hidroksi kiselina koja prodire duboko u pore, rastvara višak sebuma i sprečava pojavu novih akni. Deluje protuupalno i pomaže u uklanjanju mrtvih ćelija, čime ubrzava regeneraciju kože i smanjuje rizik od postupalnih mrlja. Melaleuca Alternifolia (Tea Tree) Leaf Oil Prirodno antibakterijsko ulje koje pomaže u suzbijanju bakterija koje izazivaju akne. Umiruje upaljena područja, smanjuje crvenilo i doprinosi bržem povlačenju upalnih promena bez iritacije. Dodaj u listu želja Dodaj u listu želja', 'COSRX Master Patch Intensive su prozirni hidrokoloidni flasteri koji ubrzavaju zaceljivanje aktivnih akni i sprečavaju njihovo dalje pogoršanje. Deluju tako što apsorbuju višak sebuma i tečnosti, štite kožu od spoljašnjih iritacija i bakterija, i smanjuju rizik od stvaranja ožiljaka.', 'https://beauty-health.rs/wp-content/uploads/2025/11/COSRX-Master-Patch-Intensive.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
