INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (422, 27, 'Bioheal Boh Probioderm 3D Lifting Ampoule', 'bioheal-boh-probioderm-3d-lifting-ampoule', 'Ključne prednosti: Efekat podizanja i zatezanja: peptidi i kolagen poboljšavaju čvrstinu i elastičnost kože. Obnova mikrobiote: probiotski kompleks jača prirodnu zaštitnu funkciju kože i smanjuje osetljivost. Dubinska hidratacija: hijaluronska kiselina i ceramidi obnavljaju vlagu i čine kožu glatkom i punijom. Kome je namenjena? Preporučuje se za kožu koja pokazuje prve znakove gubitka tonusa, elastičnosti i vitalnosti, kao i za osetljivu kožu kojoj je narušena barijera. Pogodna je za osobe starije od 30 godina ili za svakoga ko želi preventivnu anti-age negu zasnovanu na probiotičkoj obnovi i hidrataciji. Zašto volimo BIOHEAL BOH Probioderm 3D Lifting Ampoule? Ova koncentrisana ampula deluje višeslojno – kombinuje probiotičku negu za mikrobiotu kože sa sastojcima koji stimulišu sintezu kolagena i obnavljaju elastičnost. Kompleks Probioderm™ – mešavina bifidobakterija, laktobacila i fermentisanih ekstrakata – pomaže koži da ojača sopstvenu barijeru, smanji reaktivnost i održi zdravu ravnotežu mikroorganizama. Peptidi i hidrolizovani kolagen poboljšavaju tonus i elastičnost kože, pružajući vidljiv efekat zatezanja i poboljšanu definiciju kontura lica. Hijaluronska kiselina i ceramidi obezbeđuju dugotrajnu hidrataciju i sprečavaju isušivanje, dok niacinamid doprinosi ujednačenijem tenu. Ampula ima laganu, elastičnu teksturu koja se brzo upija bez lepljivosti, ostavljajući osećaj zategnutosti i mekoće. Redovnom upotrebom koža postaje čvršća, hidriranija i otpornija na spoljašnje stresore. Aktivni sastojci Probioderm™ kompleks (Bifida Ferment Lysate, Lactobacillus Ferment, Lactococcus Ferment Lysate) Sinergijska mešavina fermentisanih probiotika koji podržavaju mikrobiom kože i poboljšavaju njenu otpornost. Ojačava prirodnu barijeru, pomaže u smanjenju inflamacije i crvenila te doprinosi boljoj hidrataciji. Fermentisani sastojci stimulišu regeneraciju i pružaju koži uravnotežen, zdrav izgled. Peptidi (Acetyl Hexapeptide-8, Palmitoyl Pentapeptide-4) Biološki aktivni lanci aminokiselina koji stimulišu sintezu kolagena i elastina u dubljim slojevima kože. Doprinosе smanjenju finih linija i jačanju dermalne strukture, uz vidljiv efekat zatezanja. Kod redovne upotrebe poboljšavaju tonus i vraćaju konture lica. Hidrolizovani kolagen Oblik kolagena male molekulske mase koji prodire u površinske slojeve kože i obnavlja elastičnost. Pruža trenutno puniji i glatkiji izgled, a u kombinaciji sa peptidima doprinosi dugoročnom učvršćivanju. Hijaluronska kiselina Prirodni ovlaživač koji privlači vlagu i zadržava je u koži, čime se smanjuje dehidratacija i poboljšava elastičnost. Obezbeđuje osećaj mekoće i hidriranosti bez masnog sloja. Dodaj u listu želja Dodaj u listu želja', 'BIOHEAL BOH Probioderm 3D Lifting Ampoule sadrži kompleks probiotika i peptida koji pomaže u jačanju kožne mikrobiote i obnavljanju elastičnosti kože. Namenjena je koži koja je izgubila tonus, vlagu i čvrstinu, pružajući efekat zategnutosti i svežine bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/11/BIOHEAL-BOH-Probioderm-3D-Lifting-Ampoule.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
