INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (424, 119, 'Mixsoon Collagen Hydrogel Eye Patch', 'mixsoon-collagen-hydrogel-eye-patch', 'Ključne prednosti: Povećava elastičnost kože: Kolagen niske molekularne mase (300 Da) prodire dublje u kožu i jača njenu strukturu, smanjujući vidljivost finih linija i bora. Hidrira i revitalizuje: Kompleks od 17 aminokiselina i peptidi obnavljaju vlagu i hranljive materije, vraćajući svežinu umornoj koži oko očiju. Posvetljuje i ujednačava ton: Niacinamid i adenosin deluju sinergijski na umanjenje tamnih podočnjaka i poboljšanje tonusa kože, čineći pogled odmornijim i mlađim. Kome je namenjen? Jastučići su namenjeni svim tipovima kože, posebno osobama sa znakovima umora, tamnim kolutovima i izraženim finim borama oko očiju. Pogodni su i za osetljivu kožu koja traži umirujući i osvežavajući tretman. Zašto volimo Mixsoon Collagen Hydrogel Eye Patch? Ovi hidrogelski jastučići pružaju trenutni efekat hlađenja i osveženja koji ublažava znake umora i natečenost. Hidrolizovani kolagen obnavlja elastičnost kože, pomaže zadržavanje vlage i vraća punoću tankom sloju kože ispod očiju. Niacinamid deluje na posvetljivanje i ujednačavanje tena, dok ekstrakti zelenog čaja i kamilice smiruju kožu i sprečavaju osećaj zatezanja. Zahvaljujući polutransparentnoj, gelastoj teksturi, jastučići prijanjaju uz kožu bez klizanja, oslobađajući aktivne sastojke postepeno tokom primene. Redovnim korišćenjem smanjuju se fine bore i suve linije, a područje oko očiju postaje vizuelno odmornije, hidriranije i mekše. Savršeni su kao brzi tretman pre šminke ili kao deo večernje rutine regeneracije kože. Aktivni sastojci Hidrolizovani kolagen Kolagen male molekulske mase koji prodire u površinske slojeve kože i pomaže u zadržavanju vlage. Pruža elastičnost i čvrstinu koži oko očiju, čineći je vizuelno zategnutijom i punijom. Deluje kao podrška prirodnoj sintezi kolagena i doprinosi svežem, glatkom izgledu kože. Niacinamid (vitamin B3) Višefunkcionalni aktivni sastojak koji posvetljuje tamne kolutove, smanjuje crvenilo i poboljšava izgled kože. Jača barijeru i pomaže u smanjenju transepidermalnog gubitka vode. U kombinaciji s kolagenom daje koži odmoran, ravnomeran ton. Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Bogat polifenolima i antioksidansima, pomaže u zaštiti kože od slobodnih radikala i smanjuje natečenost. Doprinosi osveženju i umirenju kože, naročito kod umora i iritacija. Ekstrakt kamilice (Chamomilla Recutita Flower Extract) Umiruje i hidrira osetljivu kožu, pomaže u smanjenju nadraženosti i crvenila. Daje osećaj prijatne hlađenosti i doprinosi smanjenju podočnjaka uz redovnu upotrebu. Beta-glukan Prirodni polisaharid poznat po sposobnosti da intenzivno hidrira i umiri kožu. Pomaže u jačanju zaštitne barijere i regeneraciji, čineći kožu oko očiju otpornijom i mekšom. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Collagen Hydrogel Eye Patch jastučići sadrže hidrolizovani kolagen, niacinamid i ekstrakte biljaka koji intenzivno hidriraju, smanjuju natečenost i vraćaju elastičnost tankoj koži oko očiju. Namenjeni su nezi umornog, dehidriranog i opuštenog područja očiju, uz efekat trenutnog osveženja i blistavijeg pogleda.', 'https://beauty-health.rs/wp-content/uploads/2025/10/Mixsoon-Collagen-Hydrogel-Eye-Patch.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
