INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (425, 119, 'Mixsoon Bean Travel Kit', 'mixsoon-bean-travel-kit', 'Set sadrži: Bean Shampoo Bar 25g Bean Conditioner Bar 25g Bean Face & Body Bar 25g Ključne prednosti: Potpuna rutina u kompaktnom formatu: tri sapuna pružaju negu kose i kože bez potrebe za tečnim preparatima i plastičnom ambalažom. Fermentisani biljni sastojci: ekstrakt zrna soje i gljive čage hrane i revitalizuju kosu i kožu, čineći ih glatkima i otpornima. Ekološki i praktičan izbor: čvrst format olakšava pakovanje i smanjuje otpad, dok formulacije ne sadrže sulfate ni parabene. Kome je namenjen? Ovaj set je pogodan za sve tipove kože i kose, naročito za one koji žele prirodnu, održivu negu bez tečnih formula. Idealan je za putovanja, kampovanja ili svakodnevnu upotrebu kod osoba koje žele jednostavniju, ali kvalitetnu rutinu. Zašto volimo Mixsoon Bean Travel Kit? Mixsoon Bean Travel Kit donosi tri pažljivo formulisana sapuna koji zamenjuju osnovne korake nege kose i kože u praktičnom, kompaktnom formatu. Šampon sapun nežno čisti kosu i teme, uklanja nečistoće bez isušivanja i čini vlasi elastičnijim i sjajnijim. Regenerator sapun obnavlja i omekšava kosu, olakšava raščešljavanje i vraća prirodnu glatkoću. Sapun za telo i lice čisti kožu bez narušavanja pH ravnoteže i ostavlja osećaj svežine i mekoće. Fermentisani ekstrakt soje i gljive čage imaju regenerativno i antioksidativno dejstvo, dok shea puter i biljna ulja dodatno hrane i štite kožu i kosu. Proizvodi se lako penušaju, brzo ispiraju i ne ostavljaju težak sloj, što ih čini savršenim izborom za putovanja, sport ili svakodnevnu minimalističku rutinu. Aktivni sastojci Fermentisani ekstrakt zrna soje (Glycine Max Seed Extract) Ekstrakt soje bogat je aminokiselinama i proteinima koji jačaju kosu i poboljšavaju elastičnost kože. Fermentacijom se povećava biodostupnost hranljivih sastojaka, što doprinosi mekšoj, glatkijoj koži i otpornijoj kosi. Takođe umiruje teme i smanjuje osećaj suvoće. Ekstrakt gljive čage (Inonotus Obliquus Extract) Poznata po antioksidativnom i regenerativnom dejstvu, čaga pomaže u zaštiti kože i vlasišta od oksidativnog stresa i spoljašnjih uticaja. Pomaže u održavanju zdravog mikrookruženja na koži i kosi, uz smanjenje iritacija i crvenila. Niacinamid (vitamin B3) Niacinamid poboljšava funkciju zaštitne barijere, ujednačava ton kože i doprinosi zdravijem izgledu kose. Redovnom upotrebom pomaže u smanjenju perutanja, prekomerne masnoće i sivkastog tona kože. Biotin (vitamin B7) Biotin podržava sintezu keratina i jačanje vlasi, što doprinosi otpornijoj i gušćoj kosi. U formulaciji sapuna pomaže i u jačanju kože temena i smanjenju lomljenja dlake. Shea puter (Butyrospermum Parkii Butter) Shea puter hidrira i omekšava, štiti od spoljašnjih faktora i doprinosi svilenkastom osećaju kože i kose. Posebno je važan u regeneratoru, jer vraća elastičnost i sjaj bez otežavanja vlasi. Prah koštice kajsije (Prunus Armeniaca Seed Powder) Prirodni mikropiling sastojak koji se nalazi u sapunu za telo i lice. Nežno uklanja mrtve ćelije kože, čineći površinu glatkom i svežom, bez osećaja zatezanja nakon pranja. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Bean Travel Kit sadrži tri čvrsta sapuna – šampon, regenerator i sapun za telo i lice, formulisana sa fermentisanim zrnom soje i biljnim ekstraktima koji hrane, omekšavaju i revitalizuju kosu i kožu. Ovaj set je idealan za putovanja, minimaliste i ljubitelje prirodne, održive nege.', 'https://beauty-health.rs/wp-content/uploads/2025/10/Mixsoon-Bean-Travel-Kit.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
