INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (426, 73, 'Heveblue Salmon Caring Centella Special Travel Kit Bag', 'heveblue-salmon-caring-centella-special-travel-kit-bag', 'Set sadrži: Salmon Caring Centella Bubble Cleanser (30 ml) Salmon Caring Centella Toner (25 ml) Salmon Caring Centella Ampoule (13 ml) Salmon Caring Centella Cream (13 ml) Ključne prednosti: Kompletna rutina negovanja kože: set obuhvata korake čišćenja, toniranja, ampule i kreme — sve u putnim veličinama. Umirenje i jačanje kože: formulacija sa polinukleotidima i Centella Asiatica pomaže u smanjenju iritacija, jačanju barijere i vraćanju vitalnosti kože. Pogodno za putovanja i testiranje linije: proizvodi su u mini verzijama koje omogućavaju isprobavanje i primenu u uslovima kada standardne pune veličine nisu praktične. Kome je namenjen? Ovaj komplet je idealan za korisnike svih tipova kože koji su u pokretu ili putuju. Posebno je pogodan za kožu koja je dehidrirana, sklona iritacijama ili kojoj je potrebna podrška barijere — na primer nakon stresa, promena sredine ili kada ten izgleda umorno. Zašto volimo HEVEBLUE Salmon Caring Centella Special Travel Kit Bag? Ovaj travel-kit omogućava da bez kompromisa održite negu kože i kada ste van kuće: postupci su jasno definisani — čišćenje, toniranje, ampula i krema — čime se stvara sinergija između koraka. Zahvaljujući polinukleotidima u kombinaciji sa ekstraktom Centella Asiatica, koža oseća smirenje i podršku barijeri — što je naročito važno kada je izložena stresu, putovanju ili promenama okoline. Humektanti i lipidi u formuli pomažu u vraćanju vlage i omekšavanju teksture kože, dok redovna primena može doprineti svežem, odmornijem izgledu tena. Teksture proizvoda su prilagođene mini formatu — laganije, brzo upijajuće i praktične — a komplet pruža mogućnost sveobuhvatnog tretmana bez potrebe da nosite pune bočice. Iako ne pruža instant “čudo”, set donosi vrlo dobru podršku za kožu koja traži obnovu i stabilizaciju nakon perioda stresa ili dehidratacije. Na taj način, radi se o praktičnom i efektivnom rešenju za korisnike koji žele kvalitetnu, ali kompaktnu negu. Aktivni sastojci Polinukleotidi (PDRN) Polinukleotidi su fragmenti DNK (npr. iz riba ili lososa) koji se koriste u kozmetici kao sastojci za regeneraciju i podršku kože. Oni mogu da stimulišu procese obnavljanja kože, podrže barijeru i imaju potencijalno povoljan uticaj na elastičnost i tonus kože. U formulacijama linije oni doprinose osećaju „revitalizovane” kože, posebno nakon promena ili izazova sredine. Centella Asiatica Leaf Water / Extract Ekstrakt Centella Asiatica deluje umirujuće, antioksidativno i regenerativno – pomaže u obnavljanju barijere kože, smanjenju iritacija i poboljšanju teksture. U visokoj koncentraciji u ovom setu daje koži osećaj smirenja i fleksibilnosti. Dodaj u listu želja Dodaj u listu želja', 'Komplet HEVEBLUE Salmon Caring Centella Special Travel Kit Bag sadrži četiri proizvoda formulisana sa polinukleotidima i Centella Asiatica kako bi umirili kožu, obezbedili vlagu i ojačali zaštitnu barijeru. Idealno je rešenje za negu lica u pokretu ili kao uvođenje u liniju, kada koža ima potrebu za regeneracijom i smirenjem.', 'https://beauty-health.rs/wp-content/uploads/2025/10/HEVEBLUE-Salmon-Caring-Centella-Special-Travel-Kit-Bag.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
