INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (427, 123, 'Neogen Real Bakuchiol Firming Serum', 'neogen-dermalogy-real-bakuchiol-firming-serum', 'Ključne prednosti: Učvršćivanje kože: Bakuchiol i peptidi stimulišu sintezu kolagena i elastina, čime doprinose zategnutijem i elastičnijem izgledu kože. Ujednačen ten i glatkija tekstura: Vitamin C i niacinamid deluju sinergijski u posvetljavanju i ujednačavanju tena. Zaštita i hidratacija: Skvalan i hijaluronska kiselina pomažu u očuvanju vlage i jačanju barijere kože. Kome je namenjen? Serum je namenjen osobama sa normalnim, mešovitim i suvim tipom kože koje žele anti-age negu bez upotrebe retinola. Pogodan je i za one koji imaju blagu osetljivost kože. Zašto volimo NEOGEN Real Bakuchiol Firming Serum? Ovaj serum deluje nežno i efikasno — bakuchiol pokreće regenerativne procese u koži, peptidi pojačavaju efekat učvršćivanja, dok vitamin C i niacinamid doprinose svežem i blistavom tenu. Zahvaljujući skvalanu i hijaluronskoj kiselini, koža ostaje hidrirana i stabilna, što ovaj tretman čini pogodnim i za osetljiviju kožu. Tekstura seruma je lagana i brzo se upija, ostavljajući kožu glatkom i prijatno hidriranom. Redovnom upotrebom, konture lica mogu postati definisanije, a ten ujednačeniji i svežiji. Aktivni sastojci Bakuchiol Bakuchiol je biljni aktivni sastojak koji pruža slične benefite kao retinol, ali bez tipičnih nuspojava poput perutanja ili crvenila. Stimuliše sintezu kolagena, usporava razgradnju vezivnog tkiva i doprinosi zategnutijem i elastičnijem izgledu kože. Deluje antioksidativno, smanjuje vidljive znake starenja i poboljšava teksturu kože. Posebno je pogodan za osetljiviju kožu i one koji žele dugoročno poboljšanje bez naglih reakcija. Lupin Peptide Lupin peptid ima ciljano učvršćujuće dejstvo i deluje tako što pomaže u “zatezanju” kože koja gubi tonus i elastičnost. Aktivira procese u dermisu koji podstiču stvaranje strukturnih proteina, čime doprinosi vidljivijem lifting efektu i definisanijim konturama lica. Posebno je efikasan kod kože sa izraženijim opuštanjem donje trećine lica ili umornim izgledom kože. Rezultat je čvršća, kompaktnija i vizuelno zategnutija koža. Collagen Boosting Peptide Ovaj peptid podstiče sintezu kolagena u dubljim slojevima kože, čime doprinosi poboljšanju elastičnosti i smanjenju vidljivosti finih linija i bora. Deluje kao signalni molekul — “aktivira” fibroblaste da proizvode više kolagena, što pomaže koži da duže zadrži čvrstinu i glatkoću. Uz redovnu upotrebu, koža postaje otpornija i ima puniji, zdraviji izgled. Hydrolyzed Lupine Protein Hidrolizovani lupin protein pojačava efekat poboljšanja elastičnosti kože. Zahvaljujući manjoj molekularnoj težini, prodire u površinske slojeve kože i podržava sposobnost kože da zadrži čvrstinu i vlagu. Deluje kao podrška peptidima, čineći učvršćujući efekat stabilnijim i dugotrajnijim. Ovaj sastojak doprinosi i prijatnijem, elastičnijem osećaju kože nakon nanošenja. Dodaj u listu želja Dodaj u listu želja', 'NEOGEN Real Bakuchiol Firming Serum je koncentrisani serum koji kombinuje biljni aktivni sastojak bakuchiol sa peptidima, vitaminom C, niacinamidom i skvalanom kako bi poboljšao čvrstinu, tonus i otpornost kože. Namenjen je osobama koje žele vidljivo učvršćivanje i osveženje kože bez potencijalnih iritacija koje retinol ponekad izaziva.', 'https://beauty-health.rs/wp-content/uploads/2025/10/NEOGEN-Real-Bakuchiol-Firming-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
