INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (434, 90, 'Jumiso Snail Mucin + Peptide Facial Toner', 'jumiso-snail-mucin-peptide-facial-toner', 'Ključne prednosti: Dubinska hidratacija: puževa sluz obnavlja kožu i zadržava vlagu u dubljim slojevima. Podrška regeneraciji: peptidi podstiču sintezu kolagena i elastina. Ujednačen ten: tonik pomaže u poboljšanju teksture i osvežavanju tena. Kome je namenjen? Ovaj tonik kombinuje regenerativnu moć filtrata puževe sluzi i peptida kako bi koži pružio intenzivnu negu već u prvom koraku rutine. Tekstura je lagana, ali izuzetno hranljiva, brzo se upija i ostavlja prijatan osećaj hidriranosti bez lepljivog sloja. Već nakon prvih korišćenja koža deluje mekše, elastičnije i zdravije. Dugoročno, tonik jača epidermalnu barijeru, poboljšava tonus kože i vraća joj prirodni sjaj. Posebno je efikasan u ublažavanju tragova dehidratacije i prvih znakova starenja, čineći kožu otpornijom i uravnoteženijom. Zahvaljujući umirujućim svojstvima, pogodan je i za kožu sklonu iritacijama ili oštećenu nakon tretmana. Zašto volimo Jumiso Snail Mucin + Peptide Facial Toner? Ovaj tonik deluje kao ključni prvi korak u rutini nege kože, pomažući da sledeći proizvodi prodiru dublje i deluju efikasnije. Njegova tekstura je osvežavajuća i nelepljiva, što ga čini pogodnim za svakodnevnu upotrebu. Redovnim korišćenjem koža postaje hidrirana, elastična i vidno revitalizovana. Aktivni sastojci Snail Secretion Filtrate (filtrat puževe sluzi) Ovaj sastojak je poznat po snažnim regenerativnim svojstvima. Bogat je mukopolisaharidima, hijaluronskom kiselinom i prirodnim enzimima koji pomažu u zadržavanju vlage, pospešuju zarastanje i umiruju iritacije. Podržava prirodni proces obnove kože i doprinosi mekšem i zaglađenijem tenu. Peptidi Peptidi su kratki lanci aminokiselina koji stimulišu proizvodnju kolagena i elastina u koži. Doprinosе povećanju čvrstoće i elastičnosti, smanjenju finih linija i poboljšanju tonusa kože. Redovnom upotrebom jačaju strukturu kože i čine je otpornijom na spoljne uticaje. Dodaj u listu želja Dodaj u listu želja', 'Jumiso Snail Mucin + Peptide Facial Toner je tonik lagane, ali bogate teksture, koji kombinuje filtrat puževe sluzi i peptide kako bi obezbedio intenzivnu hidrataciju i regeneraciju kože. Namenjen je jačanju barijerne funkcije kože, poboljšanju elastičnosti i ublažavanju prvih znakova starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/10/Jumiso-Snail-Mucin-Peptide-Facial-Toner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
