INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (435, 17, 'Axis-Y CALAMINE Pore Control Capsule Serum', 'axis-y-calamine-pore-control-capsule-serum', 'Ključne prednosti: Kontrola sebuma: smanjuje višak masnoće i održava pore čistima. Umirujuće dejstvo: kalamin i biljni ekstrakti ublažavaju crvenilo i iritacije. Poboljšanje teksture: redovnom upotrebom koža postaje glađa i ujednačenija. Kome je namenjen? Ovaj serum je idealan za masnu, kombinovanu i kožu sklonu aknama ili proširenim porama. Pogodan je i za osobe sa osetljivom kožom koje se bore sa crvenilom i iritacijama. Zašto volimo Axis-Y CALAMINE Pore Control Capsule Serum? Ovaj serum se izdvaja po jedinstvenim kapsulama koje oslobađaju kalamin direktno prilikom nanošenja, čime se obezbeđuje svežina i efikasnost aktivnih sastojaka. Tekstura je lagana i brzo se upija, bez lepljivog osećaja, što ga čini pogodnim i za masnu i za kombinovanu kožu. Redovnim korišćenjem smanjuje vidljivost pora, reguliše lučenje sebuma i doprinosi zdravijem i balansiranijem tenu. Posebno je vredan jer kombinuje umirujuće i matirajuće dejstvo, što ga izdvaja u nezi kože sklone upalama i proširenim porama. Aktivni sastojci Centella Asiatica Extract (ekstrakt azijske centelе) Deluje umirujuće i podstiče prirodni proces obnavljanja kože. Pomaže u smanjenju crvenila i iritacija, dok istovremeno jača kožnu barijeru i ubrzava zarastanje sitnih oštećenja. Mugwort (ekstrakt pelina) Poznat po antiinflamatornom dejstvu, pomaže u hlađenju i smirivanju upaljene kože. Doprinosi elastičnosti i zdravijem, blistavom izgledu tena. Broccoli (ekstrakt brokolija) Bogata izvorima vitamina C i E, ova komponenta pomaže u zaštiti kože od oksidativnog stresa i ujednačavanju tena. Redovnom upotrebom doprinosi smanjenju hiperpigmentacija. Bromelain (enzim iz ananasa) Prirodni enzim dobijen iz stabljike ananasa koji blago uklanja mrtve ćelije kože. Pruža nežan efekat eksfolijacije bez iritacije, ostavljajući kožu glatkom i osveženom. Blue Iris (plava perunika) Deluje umirujuće i hidrira kožu, a istovremeno doprinosi smanjenju proširenih pora. Posebno je cenjena zbog efekta zatezanja i jačanja kože. Witch Hazel (hamamelis) Poznat po snažnom umirujućem dejstvu, pomaže u smanjenju upalnih procesa i iritacija. Pruža osećaj svežine i čistoće, dok istovremeno pomaže u sužavanju pora. Dodaj u listu želja Dodaj u listu želja', 'Axis-Y Calamine Pore Control Capsule Serum je lagani, ali koncentrisani serum koji kombinuje kalamin i biljne ekstrakte kako bi pomogao u smirivanju kože, kontroli sebuma i sužavanju pora. Zahvaljujući formuli obogaćenoj kapsulama kalamina i prirodnim sastojcima, serum deluje višeslojno – istovremeno umiruje upale, hidrira i jača kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Axis-Y-CALAMINE-Pore-Control-Capsule-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
