INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (436, 161, 'The Ordinary Vitamin C Suspension 23% + HA Spheres 2%', 'ordinary-vitamin-c-suspension-23-ha-spheres-2', 'Ključne prednosti: Smanjenje hiperpigmentacija: ublažava tamne mrlje i posvetljuje neujednačen ten. Antioksidativna zaštita: neutralizuje slobodne radikale i štiti od prevremenog starenja. Hidratacija i zaglađivanje: hijaluronske sfere privlače vlagu i poboljšavaju teksturu kože. Kome je namenjen? Najpogodniji je za kožu sa hiperpigmentacijama, znakovima umora, neujednačenim tonom i prvim znacima starenja. Preporučuje se osobama koje žele snažan i efikasan proizvod sa vitaminom C, ali nije idealan za veoma osetljivu kožu zbog moguće iritacije. Zašto volimo Ordinary Vitamin C Suspension 23% + HA Spheres 2%? Ova formula se izdvaja svojom sirovom snagom – zahvaljujući 23% čistog vitamina C u prahu koji ostaje stabilan jer nije rastvoren u vodi. Tekstura je granulasta zbog prisustva askorbinske kiseline u direktnom obliku, a sitne čestice se rastvaraju u kontaktu sa kožom. Zbog toga može izazvati blagi osećaj peckanja, posebno kod osetljive kože. Redovnom upotrebom koža postaje vidno osvetljena, elastičnija i dobija prirodan sjaj. Posebnost ove formulacije je sinergija vitamina C i hijaluronskih sfera koje deluju na hidrataciju, pa ten izgleda punije i zdravije. Aktivni sastojci Askorbinska kiselina (Vitamin C 23%) Askorbinska kiselina je najčistiji i najistraženiji oblik vitamina C. Deluje kao snažan antioksidans, neutrališe slobodne radikale i štiti kožu od oksidativnog stresa izazvanog UV zračenjem i zagađenjem. Podstiče sintezu kolagena, čime se koža učvršćuje i postaje elastičnija. Takođe inhibira enzim tirozinazu, što rezultira smanjenjem stvaranja melanina i ublažavanjem tamnih mrlja. Redovnom primenom ten postaje vidno ujednačen i blistav. Zbog visoke koncentracije, može izazvati osećaj peckanja kod osetljivijih tipova kože, ali upravo ta snaga donosi brze i uočljive rezultate. Hijaluronske sfere (HA Spheres 2%) Hijaluronske sfere u ovoj formuli nisu klasičan hijaluronski serum, već dehidrirane čestice koje, kada dođu u dodir sa vlagom na koži, bubre i stvaraju efekat popunjavanja bora i sitnih linija. Ovaj mehanizam daje trenutan vizuelni efekat zategnute i hidrirane kože. Pored estetskog momenta, one doprinose zadržavanju vlage u epidermu, čime poboljšavaju dugoročnu hidrataciju. U kombinaciji sa vitaminom C, hijaluronske sfere umanjuju osećaj suvoće koji visoka koncentracija askorbinske kiseline može izazvati. Dodaj u listu želja Dodaj u listu želja', 'The Ordinary Vitamin C Suspension 23% + HA Spheres 2% je intenzivan tretman koji kombinuje visoku koncentraciju čistog askorbinske kiseline (vitamin C) i hijaluronske sfere za trenutnu i dugotrajnu revitalizaciju kože. Formulisan bez vode i silikona, pruža direktan kontakt vitamina C sa kožom, obezbeđujući snažan antioksidativni efekat i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Ordinary-Vitamin-C-Suspension-23-HA-Spheres-2.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
