INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (437, 159, 'Sungboon Editor Green Tomato Pore Zero Ampoule', 'sungboon-editor-green-tomato-pore-zero-ampoule', 'Ključne prednosti: Smanjenje pora: vidljivo sužava proširene pore i poboljšava njihov tonus. Regulacija sebuma: pomaže u kontroli prekomernog lučenja sebuma, čineći kožu čistijom i manje masnom. Povećanje elastičnosti: biljni kompleksi i kolagen jačaju strukturu kože i vraćaju joj čvrstinu. Kome je namenjena? Najpogodnija je za masnu i kombinovanu kožu sa proširenim porama, viškom sebuma i gubitkom elastičnosti. Preporučuje se osobama koje žele dugoročno poboljšanje teksture kože i uravnoteženiji ten, uključujući i one sa osetljivom kožom sklonoj aknama. Zašto volimo SUNGBOON EDITOR Green Tomato Pore Zero Ampoule? Ova ampula se ističe teksturom koja se brzo upija i ostavlja kožu svežom, bez lepljivosti. Redovnom upotrebom koža postaje ujednačenija, pore deluju suženo, a površina glatkija. Posebna formulacija „Vertical Pore Lifting“ radi na elastičnosti pora iznutra, što doprinosi zdravijem i kompaktnijem izgledu kože. Zahvaljujući kombinaciji antioksidanasa i umirujućih biljnih ekstrakata, proizvod deluje i preventivno protiv upalnih procesa, pa je odličan dodatak rutini za problematičnu kožu. Aktivni sastojci Ekstrakt zelenog paradajza Zeleni paradajz je bogat vitaminom C, polifenolima i prirodnim kiselinama koje deluju adstrigentno – stežu pore i osvežavaju kožu. Sadrži likopen u sirovom obliku, koji ima snažna antioksidativna svojstva i štiti kožu od oštećenja slobodnih radikala. Osim toga, doprinosi regulaciji sebuma, što je ključno kod masne kože sklone začepljenim porama. Njegova blaga kiselost pomaže u uklanjanju viška mrtvih ćelija sa površine kože, dok istovremeno podstiče njen prirodni sjaj. Dodatno, zahvaljujući mineralima, jača barijernu funkciju kože i smanjuje osetljivost. Dugoročnim korišćenjem, ekstrakt zelenog paradajza daje koži svež i revitalizovan izgled. Niacinamid Niacinamid, poznat i kao vitamin B3, višeslojno deluje na kožu – smanjuje crvenilo i upale, reguliše proizvodnju sebuma i poboljšava barijeru kože. Njegova uloga u sintezi ceramida doprinosi očuvanju vlage, što kožu čini otpornijom i hidratizovanijom. Klinički je potvrđeno da niacinamid ublažava pojavu proširenih pora i čini ih manje vidljivim. Takođe deluje na ujednačavanje tena, smanjujući hiperpigmentacije i fleke nastale od akni. Zahvaljujući antioksidativnim svojstvima, štiti kožu od oksidativnog stresa izazvanog spoljnim faktorima. Dugoročno, ten postaje blistaviji, a tekstura kože zaglađena i elastična. Biljni kompleksi (triple patented pore care blend) Formula sadrži kombinaciju biljnih ekstrakata posebno odabranih za zatezanje pora i jačanje kože. Ovi kompleksi deluju tako što obezbeđuju umirujući efekat, sprečavaju iritacije i istovremeno stimulišu sintezu kolagena. Njihov antioksidativni potencijal štiti ćelije kože od preranog starenja i degradacije elastičnih vlakana. Biljna baza doprinosi i balansu mikrobioma, čime se smanjuje rizik od nastanka akni. Osim elastičnosti, ovi kompleksi obezbeđuju i blagu hidrataciju, što doprinosi mekoći kože. Sinergija više biljnih sastojaka čini ih pouzdanim saveznikom u nezi kože sa problemom proširenih pora. Dodaj u listu želja Dodaj u listu želja', 'SUNGBOON EDITOR Green Tomato Pore Zero Ampoule Plus je koncentrovana ampula formulisana za smanjenje proširenih pora, regulaciju sebuma i poboljšanje elastičnosti kože. Sadrži ekstrakt zelenog paradajza, niacinamid i patentirane biljne komplekse koji deluju na zatezanje i ujednačavanje teksture kože.', 'https://beauty-health.rs/wp-content/uploads/2025/09/SUNGBOON-EDITOR-Green-Tomato-Pore-Zero-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
