INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (438, 126, 'Numbuzin No.9 NAD+ PDRN Glow Boosting Toner', 'numbuzin-no-9-nad-pdrn-glow-boosting-toner', 'Ključne prednosti: Regeneracija kože: PDRN podstiče obnovu ćelija i poboljšava elastičnost kože. Intenzivna hidratacija: NAD+ i peptidi dubinski hrane i jačaju kožnu barijeru. Ujednačen i blistav ten: formula osvetljava kožu i daje joj staklasti sjaj. Kome je namenjen? Posebno je pogodan za umornu, dehidriranu i zrelu kožu, kao i za one koji žele da preduprede znakove starenja. Idealan je za osobe koje žele dodatnu regeneraciju nakon estetskih tretmana ili perioda stresa. Zašto volimo Numbuzin No.9 NAD+ PDRN Glow Boosting Toner? Ovaj tonik se ističe svojom laganom, ali hranljivom teksturom koja brzo prodire u kožu, ostavljajući osećaj svežine bez lepljivosti. U rutini deluje kao moćan prvi korak za jačanje kože i pripremu za sledeće proizvode, čime se povećava njihova efikasnost. Redovnom upotrebom koža postaje mekša, čvršća i vidljivo revitalizovana. Njegova formula sa PDRN-om stimuliše prirodne procese obnove kože, dok NAD+ doprinosi energiji ćelija i usporava znake starenja. Zahvaljujući peptidima, tonik pruža podršku u očuvanju elastičnosti i smanjenju finih linija, što doprinosi mladalačkom izgledu. Dugotrajna hidratacija pomaže u očuvanju kožne barijere i sprečava osećaj zatezanja, a blistavost tena postaje uočljivija već nakon nekoliko nedelja korišćenja. Upravo zbog kombinacije regenerativnog i hidratantnog dejstva, ovaj tonik je odličan izbor za sve koji žele temeljnu pripremu kože i primetan “glass skin” efekat. Aktivni sastojci PDRN (Polydeoxyribonucleotide) PDRN je bioaktivni kompleks izolovan iz lososove DNK, poznat po svojoj sposobnosti da podstakne regeneraciju ćelija i ubrza prirodne procese obnavljanja kože. Poboljšava elastičnost, smanjuje vidljivost oštećenja i daje koži zdraviji, revitalizovan izgled. Redovnom upotrebom smanjuje bore i jača kožnu barijeru, čineći kožu otpornijom na spoljne faktore. NAD+ (Nikotinamid adenin dinukleotid) NAD+ je koenzim ključan za ćelijsku energiju i zdravlje kože. Njegovo prisustvo u formuli pomaže u jačanju metaboličkih procesa kože, ubrzava oporavak i poboljšava vitalnost. Rezultat je vidljivo osvežena i revitalizovana koža sa zdravim sjajem. Peptidi Devet različitih peptida deluju sinergijski kako bi stimulisali sintezu kolagena i elastina, čime doprinose zatezanju i jačanju strukture kože. Peptidi takođe jačaju kožnu barijeru, smanjuju upalne procese i čuvaju kožu od prevremenog starenja. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.9 NAD+ PDRN Glow Boosting Toner je napredni tonik formulisan sa 1000 ppm čistog lososovog PDRN-a i NAD+, uz dodatak 9 peptida. Namenjen je obnavljanju, hidrataciji i vraćanju blistavog izgleda kože, uz jasno vidljivo poboljšanje teksture i tonusa.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.9-NAD-PDRN-Glow-Boosting-Toner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
