INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (443, 118, 'MISSHA Bee Pollen Renew Cream', 'missha-bee-pollen-renew-cream', 'Ključne prednosti: Dubinska hidratacija: pčelin polen i hijaluronska kiselina intenzivno obnavljaju nivo vlage u koži. Regeneracija kože: bogata antioksidansima i vitaminima, krema pomaže u obnovi oštećene kože i smanjenju znakova umora. Jačanje barijere: prirodni ekstrakti i polen poboljšavaju otpornost kože na spoljne agresore i zadržavaju vlažnost. Kome je namenjena? Krema je idealna za osobe sa suvom, osetljivom i umornom kožom, kao i za one koje žele dodatnu zaštitu i regeneraciju u uslovima urbanog stresa ili nakon oštećenja kože. Posebno pogodna za zrelu i dehidriranu kožu kojoj nedostaje energije i svežine. Zašto volimo MISSHA Bee Pollen Renew Cream? Krema ima punu, ali brzo upijajuću teksturu, ostavljajući kožu mekom i zaštićenom bez osećaja težine ili masnog filma. Njena formulacija ciljano deluje na iscrpljenu kožu kojoj nedostaje hranljivih materija, vraćajući joj vitalnost i zdrav sjaj. Redovnom upotrebom koža postaje otpornija, elastičnija i vidno blistavija. Aktivni sastojci Pčelin polen Pčelin polen je izuzetno bogat vitaminima, mineralima, aminokiselinama i antioksidansima. On obezbeđuje koži esencijalne hranljive materije, podstiče regeneraciju i jača prirodnu zaštitnu barijeru. Zahvaljujući antioksidativnim komponentama, polen štiti ćelije kože od oksidativnog stresa, dok istovremeno poboljšava elastičnost i otpornost kože. Redovnim korišćenjem pomaže umornoj koži da povrati vitalnost i ujednačen izgled. Hijaluronska kiselina Hijaluronska kiselina deluje kao moćan humektant, privlačeći i zadržavajući vlagu u koži. Na taj način poboljšava hidrataciju, smanjuje osećaj zategnutosti i doprinosi glatkoći kože. Osim trenutnog efekta hidriranja, ona pomaže i u dugoročnoj prevenciji gubitka vode iz kože. Održavanjem optimalne vlažnosti, koža deluje punije i elastičnije, sa smanjenim vidljivim znacima umora. Dodaj u listu želja Dodaj u listu želja', 'Missha Chogongjin Geumsul Jin Eye Cream je bogata krema za negu područja oko očiju, formulisana da smanji bore, osvetli tamne kolutove i vrati elastičnost tankoj koži kapaka. Inspirisana tradicionalnom korejskom herbalnom medicinom, ova krema kombinuje snagu ginsenga, carskog jeleja i zlatnih čestica za intenzivnu revitalizaciju i jačanje kože.', 'https://beauty-health.rs/wp-content/uploads/2025/09/MISSHA-Bee-Pollen-Renew-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
