INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (445, 109, 'Manyo Panthetoin Cream', 'manyo-panthetoin-cream', 'Ključne prednosti: Dubinska hidratacija: kompleks hijaluronske kiseline i patentirani Panthetoin&#x2122; brzo vraćaju vlažnost i sprečavaju gubitak vode iz kože. Obnova barijere: ceramidi i provitamin B5 jačaju kožnu barijeru i čine kožu otpornijom na spoljašnje faktore. Umirujući efekat: formula ublažava crvenilo i nelagodnost, posebno kod suve i osetljive kože. Kome je namenjena? Preporučuje se svim tipovima kože, a posebno suvoj, dehidriranoj i osetljivoj koži sklonoj crvenilu i iritacijama. Pogodna je i za one koji žele jačanje barijere i dugotrajnu hidrataciju bez teškog osećaja na licu. Zašto volimo Manyo Panthetoin Cream? Krema deluje na više nivoa – odmah po nanošenju umiruje i hidrira, dok pri redovnoj upotrebi obnavlja strukturu kože i jača njen zaštitni sloj. Tekstura je lagana, bez osećaja lepljivosti, a zahvaljujući patentiranom sastojku Panthetoin&#x2122; hidratacija traje duže nego kod standardnih formula. Koža postaje elastičnija, mekša i vidno otpornija na isušivanje i spoljne nadražaje. Aktivni sastojci Panthetoin&#x2122; Panthetoin&#x2122; je patentirani kompleks koji kombinuje dekspantenol (provitamin B5) i alantoin. Dekspantenol prodire duboko u kožu, gde se metaboliše u pantotensku kiselinu, ključnu za regeneraciju ćelija. Pomaže zarastanje mikropukotina i iritacija, dok alantoin umiruje i štiti kožu od inflamacije. Zajedno omogućavaju dugotrajnu hidrataciju i jačanje barijere, produžavajući efikasnost u odnosu na standardne hidratantne sastojke. Hijaluronska kiselina (nisko-molekularna) Hijaluronska kiselina sa niskom molekularnom masom prodire dublje u epiderm, gde vezuje vodu i popunjava međuprostore između ćelija. Time povećava elastičnost i vraća koži punoću. Za razliku od visoko-molekularne hijaluronske kiseline, koja deluje površinski, nisko-molekularna formula obezbeđuje dugotrajniji efekat hidratacije i smanjenje finih linija izazvanih dehidratacijom. Ceramidi (U-Oliosome tehnologija) Ceramidi su lipidi koji prirodno postoje u koži, a u ovoj formuli su predstavljeni u mikročesticama manjim od pora. Takva struktura omogućava dubinsko prodiranje i jačanje zaštitne barijere. Redovnom upotrebom smanjuju transepidermalni gubitak vode, čuvaju kožu od spoljašnjih nadražaja i doprinose osećaju elastičnosti i mekoće. Dodaj u listu želja Dodaj u listu želja', 'Manyo Panthetoin Cream kombinuje patentirani kompleks Panthetoin&#x2122; sa hijaluronskom kiselinom i ceramidima kako bi koži pružila intenzivnu i dugotrajnu hidrataciju. Namenjena je obnovi oštećene barijere, ublažavanju osećaja zatezanja i zaštiti kože od spoljašnjih iritansa.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Manyo-Panthetoin-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
