INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (449, 50, 'Dr.G &#8211; R.E.D Blemish Clear Soothing Toner', 'dr-g-r-e-d-blemish-clear-soothing-toner', 'Ključne prednosti: Umiruje iritacije: kompleksom Centella Asiatica ekstrakata smanjuje crvenilo i osetljivost. Jača barijeru: pantenol i alantoin obnavljaju i štite kožu od spoljašnjih agresora. Hidrira i osvežava: lagana vodena tekstura pruža trenutnu vlagu i mekoću. Kome je namenjen? Preporučuje se osobama sa osetljivom, crvenom ili problematičnom kožom, sklonom aknama i inflamacijama. Pogodan je i za one koji žele lagan, umirujući tonik koji će hidratizovati i pripremiti kožu za sledeće korake rutine. Zašto volimo Dr.G &#8211; R.E.D Blemish Clear Soothing Toner? Tonik je razvijen kao prvi korak u nezi kože sklonoj iritacijama, crvenilu i upalama. Njegova formula sadrži pet različitih komponenti Centella Asiatica ekstrakta – madecassoside, asiaticoside, asiatic acid, madecassic acid i sam ekstrakt biljke – koji sinergijski smanjuju crvenilo i umiruju inflamacije. Pantenol i alantoin dodatno pomažu u regeneraciji kože i jačanju njene zaštitne barijere, što je ključno kod osetljive kože. Laka, gotovo vodena tekstura brzo se upija i ostavlja osećaj svežine, bez lepljivosti. Redovnim korišćenjem, koža postaje otpornija, hidrirana i vidno smirenija, a ten ujednačeniji. Tonik je dermatološki testiran i dovoljno nežan za svakodnevnu upotrebu. Aktivni sastojci Centella Asiatica kompleks Centella Asiatica, poznata i kao tigrova trava, već vekovima se koristi zbog svojih umirujućih i regenerativnih svojstava. U ovom toniku koristi se kompleks od pet derivata – madecassoside, asiaticoside, asiatic acid, madecassic acid i ekstrakt lista. Oni deluju zajedno kako bi umanjili crvenilo, smirili upalu i ubrzali zarastanje iritacija. Takođe stimulišu sintezu kolagena, što dugoročno doprinosi jačoj i elastičnijoj koži. Redovnom primenom, Centella Asiatica čini kožu otpornijom i zdravijom. Posebno je pogodna za osetljivu i aknama sklonu kožu. Pantenol Pantenol, poznat i kao provitamin B5, snažan je hidratant i obnavljajući sastojak. On vezuje vlagu i prodire duboko u kožu, čineći je mekšom i otpornijom. Takođe deluje umirujuće na iritiranu kožu, smanjujući osećaj zatezanja i svrab. Pantenol podržava regeneraciju epidermisa, pa doprinosi bržem oporavku kože nakon upalnih procesa. Njegovo dejstvo je ključno kod svakodnevne upotrebe jer kožu čini hidriranom i otpornom na spoljašnje faktore. U ovom toniku ima ulogu balansiranja vlage i smirivanja osetljivosti. Alantoin Alantoin je poznat po svom umirujućem i regenerativnom delovanju. On podstiče obnavljanje ćelija i smanjuje iritacije, što je naročito korisno kod osetljive kože. Deluje i kao blagi emolijens, ostavljajući kožu mekom i glatkom. Alantoin pomaže u jačanju barijerne funkcije, pa koža postaje otpornija na spoljne agresore. Njegov efekat je posebno značajan kod osoba sa crvenilom i suvom, nadraženom kožom. U kombinaciji sa pantenolom i Centella Asiatica kompleksom, pruža sinergijsko umirujuće dejstvo. Dodaj u listu želja Dodaj u listu želja', 'Dr.G R.E.D Blemish Clear Soothing Toner je hidratantni i umirujući tonik obogaćen kompleksom Centella Asiatica ekstrakata i pantenolom. Formulisan je za osetljivu i problematičnu kožu sklonu crvenilu, iritacijama i upalama, pružajući joj ravnotežu i osveženje.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Dr.G-R.E.D-Blemish-Clear-Soothing-Toner.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
