INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (450, 43, 'd&#8217;Alba Professional Reparing Hair Perfume Serum', 'dalba-professional-reparing-hair-perfume-serum', 'Ključne prednosti: Obnavlja i jača: hranljivi proteini i beli tartuf popravljaju strukturu oštećenih vlasi. Hidrira i omekšava: prirodna ulja hrane kosu i smanjuju suvoću i lomljivost. Ostavlja mirisni trag: parfemska formula pruža dugotrajan osećaj svežine i luksuza. Kome je namenjen? Serum je namenjen svim tipovima kose, a posebno suvoj, lomljivoj i oštećenoj kosi kojoj je potrebna dodatna hidratacija i zaštita. Pogodan je i za osobe koje žele kosu koja izgleda negovano i miriše luksuzno bez dodatnog parfema. Zašto volimo d&#8217;Alba Professional Reparing Hair Perfume Serum? Serum kombinuje negu i luksuz u jednoj formuli – dok aktivni sastojci popravljaju i hrane kosu, parfemske note ostavljaju prijatan miris koji traje satima. Ekstrakt belog tartufa, bogat antioksidansima i mineralima, jača kosu i vraća joj prirodnu elastičnost. Arganovo ulje obnavlja ispucale i suve krajeve, čini kosu mekom i sjajnom. Proteini deluju tako da popune oštećene delove vlasi, čime kosa postaje otpornija na spoljne faktore i toplinsko oblikovanje. Formula je lagana, ne masti i ne otežava kosu, pa je pogodna i za svakodnevnu upotrebu. Redovnim korišćenjem kosa postaje glatka, svilenkasta i lakša za oblikovanje, dok parfemski deo formule pruža osećaj svežine tokom celog dana. Aktivni sastojci Beli tartuf Beli tartuf je bogat mineralima, aminokiselinama i antioksidansima koji intenzivno hrane kosu. On jača folikule, obnavlja elastičnost i pomaže u sprečavanju lomljenja. Deluje i kao zaštita od spoljašnjih faktora poput zagađenja i UV zraka. Prisustvo belog tartufa doprinosi i revitalizaciji kose, čineći je otpornijom i punijom. Njegov antioksidativni efekat pomaže i u očuvanju zdravog vlasišta. Kosi vraća luksuzan sjaj i mekoću. Arganovo ulje Arganovo ulje je jedno od najcenjenijih prirodnih ulja za negu kose, poznato po visokom sadržaju vitamina E i masnih kiselina. U ovoj formuli obnavlja ispucale krajeve, smanjuje suvoću i vraća mekoću. Doprinosi i zaštiti kose od toplote i spoljašnjih oštećenja. Lako prodire u vlas i pruža dugotrajan efekat hidratacije. Kosu čini svilenkastom i sjajnom, bez otežavanja. Njegovo dejstvo je posebno vidljivo kod oštećene i suve kose. Proteini Proteini u serumu deluju tako da popunjavaju oštećena vlakna kose, obnavljajući strukturu i čvrstinu. Oni povećavaju elastičnost i čine kosu otpornijom na pucanje. Pored toga, proteini poboljšavaju teksturu kose, čineći je glađom i mekšom na dodir. Deluju i kao zaštitni sloj, smanjujući štetu od svakodnevnog stilizovanja. Njihovo redovno prisustvo u nezi pomaže da kosa postane zdravija i sjajnija. U kombinaciji sa uljima, daju optimalne rezultate u reparaciji i negovanju vlasi. Dodaj u listu želja Dodaj u listu želja', 'd’Alba Professional Repairing Hair Perfume Serum je hranljiv serum za kosu koji kombinuje luksuznu negu i prijatan miris. Obogaćen je belim tartufom, biljnim uljima i proteinima, a njegova lagana formula istovremeno obnavlja oštećenu kosu, vraća joj sjaj i ostavlja diskretan parfemski trag.', 'https://beauty-health.rs/wp-content/uploads/2025/09/dAlba-Professional-Reparing-Hair-Perfume-Serum.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
