INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (451, 42, 'CP-1 Keratin Concentrate Ampoule', 'cp-1-keratin-concentrate-ampoule', 'Ključne prednosti: Obnavlja strukturu kose: keratin popunjava oštećenja i jača vlakna dlake. Pruža hidrataciju: pantenol veže vlagu i čini kosu mekšom i elastičnijom. Vraća sjaj i glatkoću: proteini svile zaglađuju kutikulu i čine kosu svilenkastom. Šampon je namenjen osobama koje se suočavaju sa pojačanim opadanjem kose, slabljenjem vlasi ili problemima sa iritacijom temena. Pogodan je za sve tipove kose, uključujući i osetljivo teme sklono svrabu i crvenilu. Kome je namenjen? Preporučuje se osobama sa oštećenom, suvom, hemijski tretiranom ili često stilizovanom kosom. Pogodna je i za tanku kosu kojoj je potrebna dodatna snaga i zaštita bez otežavanja. Zašto volimo CP-1 Keratin Concentrate Ampoule? Ova ampula namenjena je kosi koja je oštećena hemijskim tretmanima, toplinom ili svakodnevnim stilizovanjem. Hidrolizovani keratin deluje tako da se veže za oštećene delove vlasi i popunjava praznine u njenoj strukturi, čime vraća snagu i otpornost. Proteini svile zaglađuju kutikulu i daju kosi svilenkast osećaj, dok istovremeno smanjuju statički elektricitet i lomljenje. Pantenol hidrira kosu, čineći je elastičnijom i sjajnijom. Tekstura ampule je lagana, brzo se upija i ne ostavlja osećaj težine, pa je pogodna i za tanku kosu. Redovnom upotrebom kosa postaje vidno mekša, glatkija i lakša za oblikovanje. Aktivni sastojci Hidrolizovani keratin Keratin je osnovni protein kose, a kada je kosa oštećena, njegova količina značajno opada. Hidrolizovani keratin sastoji se od manjih molekula koji lako prodiru u vlas i popunjavaju oštećene delove. Na taj način obnavlja strukturu i vraća kosi snagu i otpornost. Redovnom upotrebom kosa postaje otpornija na lomljenje i spoljne faktore. Keratin takođe pomaže da se kutikula zagladi, čineći kosu mekšom i sjajnijom. Njegovo dejstvo je posebno korisno kod kose tretirane farbanjem ili izlaganjem toploti. Proteini svile Proteini svile imaju sposobnost da formiraju zaštitni film oko vlasi, čime je štite od spoljašnjih oštećenja. Pored zaštite, oni zaglađuju površinu kose, dajući joj svilenkastu glatkoću i sjaj. Zbog higroskopskih svojstava, pomažu u očuvanju vlage u kosi, što je čini elastičnijom i manje podložnom lomljenju. Njihovo dejstvo poboljšava teksturu i smanjuje neposlušnost vlasi. U kombinaciji sa keratinom, stvaraju sinergijski efekat jačanja i obnavljanja kose. Rezultat je kosa koja izgleda zdravije i mekše već nakon nekoliko upotreba. Pantenol Pantenol, poznat i kao provitamin B5, ima snažna hidratantna svojstva. Prodirući u vlas, vezuje vlagu i održava optimalan nivo hidratacije. Na taj način kosa postaje mekša, glatkija i lakša za oblikovanje. Pantenol takođe smanjuje iritacije temena i jača elastičnost kose. Njegova uloga je i da umanji lomljenje i pojavu ispucalih krajeva. Kontinuiranom upotrebom, kosa stiče zdraviji izgled i postaje sjajnija i otpornija. Dodaj u listu želja Dodaj u listu želja', 'CP-1 Keratin Concentrate Ampoule je intenzivni tretman za oštećenu i lomljivu kosu, formulisan sa hidrolizovanim keratinom, proteinima svile i pantenolom. Njegova svrha je da popuni oštećene delove vlasi, obnovi strukturu i vrati kosi glatkoću i sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/09/CP-1-Keratin-Concentrate-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
