INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (452, 52, 'Dr.Melaxin Necklinephalt Neck Cream', 'dr-melaxin-necklinephalt-neck-cream', 'Ključne prednosti: Zateže i učvršćuje: peptidi stimulišu proizvodnju kolagena i poboljšavaju tonus kože. Hidrira i omekšava: hijaluronska kiselina obezbeđuje dugotrajnu vlagu i punoću kože. Smanjuje bore: kolagen popunjava sitne linije i vraća elastičnost tankoj koži vrata. Kome je namenjena? Preporučuje se osobama koje žele da ojačaju i obnove kožu vrata i dekoltea, posebno kod prvih znakova opuštanja i bora. Pogodna je za sve tipove kože, uključujući i zreliju i suvu kožu kojoj nedostaje čvrstina. Zašto volimo Dr.Melaxin Necklinephalt Neck Cream? Koža vrata i dekoltea je tanja i brže gubi elastičnost od kože lica, pa je sklona borama i opuštanju. Ova krema pruža ciljanu negu zahvaljujući kombinaciji peptida, kolagena i hijaluronske kiseline. Peptidi stimulišu sintezu kolagena i elastina, što vremenom doprinosi vidljivom zatezanju i učvršćivanju kože. Hidrolizovani kolagen obnavlja strukturu i popunjava fine bore, dok hijaluronska kiselina hidrira u dubini i čini kožu punijom. Tekstura kreme je bogata, ali se brzo upija, bez masnog osećaja, pa je pogodna i za dnevnu i za noćnu negu. Redovnom primenom koža postaje glatkija, elastičnija i vizuelno mlađa, dok se izgled “nabora” na vratu i dekolteu ublažava. Aktivni sastojci Peptidi Peptidi su kratki lanci aminokiselina koji šalju signal ćelijama da pojačaju proizvodnju kolagena i elastina. Oni pomažu u obnavljanju strukture kože i smanjenju bora. Dodatno jačaju kožnu barijeru i povećavaju otpornost na spoljne faktore. Redovnom primenom, koža postaje elastičnija i čvršća. Njihovo dejstvo je posebno značajno kod tanke kože vrata i dekoltea, gde se bore javljaju ranije. Kolagen Hidrolizovani kolagen prodire u površinske slojeve kože i popunjava praznine u njenoj strukturi. On pomaže u smanjenju bora i vraća koži čvrstinu i elastičnost. Osim estetskog efekta, kolagen poboljšava zadržavanje vlage u koži. Vremenom doprinosi koži koja izgleda punije i mlađe. U kombinaciji sa peptidima, pruža vidljiv i dugotrajan anti-age efekat. Hijaluronska kiselina Hijaluronska kiselina je snažan humektant koji vezuje vodu i hidrira kožu u više slojeva. Time vraća punoću i smanjuje vidljivost finih linija. Koža postaje mekša, glatkija i otpornija na isušivanje. Redovnim korišćenjem poboljšava elastičnost i svež izgled. Posebno je dragocena u nezi vrata i dekoltea, gde koža brže gubi vlagu. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin Necklinephalt Neck Cream je specijalizovana krema za negu kože vrata i dekoltea, formulisana sa peptidima, kolagenom i hijaluronskom kiselinom. Namenjena je za jačanje elastičnosti, smanjenje bora i hidrataciju tanke i osetljive kože ovog područja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Dr.Melaxin-Necklinephalt-Neck-Cream.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
