INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (453, 6, 'Abib PDRN retinal eye patch Glow jelly', 'abib-pdrn-retinal-eye-patch-glow-jelly', 'Ključne prednosti: Smanjuje bore: retinal podstiče obnovu ćelija i zaglađuje fine linije. Regeneriše i jača: PDRN stimuliše oporavak kože i poboljšava elastičnost. Osvežava pogled: gelasta tekstura hladi i ublažava natečenost, dok posvetljuje tamne kolutove. Kome su namenjeni? Pogodni su za sve tipove kože, a posebno za osobe sa tankom i osetljivom kožom oko očiju, izraženim finim linijama, tamnim kolutovima i znakovima umora. Preporučuju se i za preventivnu anti-age negu kod osoba koje žele da očuvaju svež i odmoran izgled. Zašto volimo Abib PDRN retinal eye patch Glow jelly? Ovi jastučići kombinuju savremenu tehnologiju i aktivne sastojke kako bi pružili ciljanu negu jednom od najosetljivijih područja na licu – koži oko očiju. Retinal, snažan derivat vitamina A, ubrzava obnavljanje ćelija, smanjuje fine linije i poboljšava teksturu kože. PDRN, poznat po svojim regenerativnim svojstvima, jača kožu i pospešuje njenu otpornost, što rezultira elastičnijim i mladolikijim izgledom. Hidrogel baza obezbeđuje efekat hlađenja i trenutno smanjuje otok, dok istovremeno omogućava optimalnu penetraciju aktivnih sastojaka. Redovnom upotrebom koža postaje mekša, glađa i svetlija, a pogled odmorniji i svežiji. Idealni su i kao brzi tretman pred važan događaj ili kada je potrebna dodatna hidratacija i osveženje. Aktivni sastojci PDRN PDRN (polydeoxyribonucleotide) je bioaktivni kompleks koji se koristi u regenerativnoj medicini zbog svoje sposobnosti da stimuliše obnavljanje ćelija i tkiva. U kozmetici deluje tako što poboljšava elastičnost kože i ubrzava proces regeneracije. Jača barijernu funkciju kože, čineći je otpornijom na spoljne uticaje i oštećenja. Pored toga, poboljšava mikrocirkulaciju i pomaže u smanjenju znakova umora, kao što su tamni kolutovi i sivilo. Njegovo delovanje daje dugoročne rezultate – koža postaje čvršća, hidrirana i zdravijeg izgleda. U kombinaciji sa retinalom, PDRN pruža snažnu anti-age sinergiju. Retinal Retinal (retinaldehid) je moćan oblik vitamina A i preteča retinoične kiseline, koji se odlikuje visokim anti-age potencijalom. On ubrzava obnovu ćelija i sintezu kolagena, što rezultira smanjenjem bora i poboljšanjem teksture kože. Efikasniji je od retinola, ali pritom blaži od čistog tretinoina, pa je pogodan za osetljivo područje oko očiju. Retinal takođe deluje na tamne kolutove i umornu kožu, vraćajući svežinu i osvetljavajući predeo ispod očiju. Njegov učinak vidljiv je već nakon nekoliko nedelja redovne upotrebe, a dugoročno doprinosi mladolikom i zategnutom izgledu. Kada je inkorporiran u hidrogel jastučiće, oslobađa se postepeno i bez iritacija. Dodaj u listu želja Dodaj u listu želja', 'Abib PDRN Retinal Eye Patch Glow Jelly kombinuje PDRN i retinal sa hidratantnim i umirujućim sastojcima kako bi ublažio bore i tamne kolutove ispod očiju. Jastučići hlade i osvežavaju, dok aktivni sastojci regenerišu i vraćaju sjaj tankoj koži oko očiju.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Abib-PDRN-retinal-eye-patch-Glow-jelly.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
