INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (456, 6, 'Abib Glow collagen mask Glutathiosome film', 'abib-glow-collagen-mask-glutathiosome-film', 'Ključne prednosti: Posvetljava i ujednačava ten: glutation i niacinamid smanjuju vidljivost tamnih mrlja i crvenila. Povećava elastičnost: kolagen male molekulske mase prodire u kožu i vraća joj punoću. Umiruje i osvežava: lagana hidrogel struktura hidrira i trenutno hladi kožu. Kome je namenjena? Pogodna je za sve tipove kože, uključujući osetljivu. Idealna je za one koji se bore sa tamnim mrljama, neujednačenim tonom, sivilom i prvim znacima starenja. Zašto volimo Abib Glow collagen mask Glutathiosome film? Ova inovativna maska koristi tehnologiju providnog filma sa 99% čistog glutationa, što omogućava intenzivan efekat posvetljivanja i ublažavanja hiperpigmentacija. Niacinamid dodatno ujednačava ton kože i jača barijeru, dok vitamin C derivati pružaju antioksidativnu zaštitu. Ultra-niskomolekularni kolagen (300 Da) prodire dublje u kožu, povećava elastičnost i smanjuje vidljivost finih linija. Zahvaljujući jedinstvenoj hidrogel teksturi, maska prijanja uz lice i omogućava optimalnu apsorpciju aktivnih sastojaka. Koža nakon upotrebe izgleda hidrirano, blistavo i osveženo, sa vidljivim poboljšanjem ujednačenosti tena. Redovnom upotrebom koža postaje mekša, zategnutija i otpornija na spoljašnje faktore. Aktivni sastojci Glutation Glutation je jedan od najvažnijih antioksidanata u ljudskom telu, a u kozmetici se koristi zbog svoje sposobnosti da inhibira sintezu melanina. Deluje tako što smanjuje oksidativni stres u ćelijama kože i usporava procese koji dovode do nastanka tamnih mrlja i diskoloracija. Ujedno doprinosi posvetljivanju postojećih fleka, čime ten postaje ujednačeniji i osvetljeniji. Redovnom primenom glutation pomaže u sprečavanju novih oštećenja izazvanih UV zracima i spoljnim stresorima. Njegovo dejstvo se ne svodi samo na estetiku – on jača ćelijsku otpornost i podržava zdrav izgled kože. Zahvaljujući kombinaciji sa hidrogel filmom, glutation u ovoj maski ima optimalnu isporuku i dublje dejstvo. Kolagen male molekulske mase Kolagen je strukturni protein ključan za čvrstoću i elastičnost kože, ali sa godinama njegova proizvodnja opada. Hidrolizovani kolagen male molekulske mase koristi se jer može bolje da prodre u epiderm i obezbedi koži potrebnu elastičnost. On pomaže u smanjenju finih linija, vraćanju punoće i boljem tonusu. Pored estetskog efekta, doprinosi i očuvanju vlažnosti jer poboljšava sposobnost kože da zadrži vodu. Njegov kontinuirani unos putem ovakvih maski može doprineti dugoročnom jačanju strukture kože. U kombinaciji sa glutationom, kolagen ne deluje samo na elastičnost već i na svežinu i zdrav izgled kože, čineći je punijom i vitalnijom. Dodaj u listu želja Dodaj u listu želja', 'Abib Glow Collagen Mask Glutathione Film je dvodelna providna hidrogel maska obogaćena glutationom, niacinamidom i kolagenom ultra-niske molekulske mase. Deluje na tamne fleke, sivilo i gubitak elastičnosti, ostavljajući kožu osvetljenom i zategnutom.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Abib-Glow-collagen-mask-Glutathiosome-film.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
