INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (458, 174, 'VT Cosmetics PDRN Capsule Cream 100', 'vt-cosmetics-pdrn-capsule-cream-100', 'Ključne prednosti: Regeneracija kože: PDRN podstiče obnavljanje ćelija i poboljšava elastičnost. Obnova barijere: ceramidi vraćaju zaštitnu funkciju kože i smanjuju gubitak vlage. Višeslojna hidratacija: deset hijaluronskih kiselina vlaže različite slojeve kože i daju joj punoću. Kome je namenjena? Krema je idealna za normalnu do suvu i osetljivu kožu kojoj nedostaje elastičnost, hidratacija i zaštita. Posebno pogodna za kožu sa narušenom barijerom ili posle tretmana koji izazivaju suvoću i crvenilo. Zašto volimo VT Cosmetics PDRN Capsule Cream 100? Krema sa kapsulama ima bogatu, ali prijatnu teksturu koja se topi pri dodiru sa kožom, oslobađajući aktivne sastojke iz mikrokapsula. PDRN u visokoj koncentraciji podržava regeneraciju kože i čini je otpornijom na spoljne agresore. Ceramidi obnavljaju lipidnu barijeru i pomažu da koža zadrži vlagu, smanjujući suvoću i iritacije. Kompleks od deset hijaluronskih kiselina osigurava dubinsku i dugotrajnu hidrataciju, čineći kožu elastičnijom i punijom. Pantenol dodatno umiruje i obnavlja, dok niacinamid doprinosi ujednačenom tenu i zdravom sjaju. Zahvaljujući ovoj kombinaciji, koža postaje glatkija, mekša i vidno revitalizovana. Aktivni sastojci PDRN (100 000 ppm) Podstiče regeneraciju ćelija, poboljšava sintezu kolagena i vraća elastičnost i punoću kože. Ceramidi (NP, NS, AP, AS, EOP) Obnavljaju zaštitnu barijeru kože, sprečavaju gubitak vlage i jačaju otpornost. Hijaluronska kiselina (10 tipova) Deluju u različitim slojevima kože, obezbeđuju dubinsku i površinsku hidrataciju i daju koži punoću. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics PDRN Capsule Cream 100 kombinuje 100 000 ppm PDRN-a sa pet vrsta ceramida i deset tipova hijaluronske kiseline kako bi obnovila barijeru kože, umirila i intenzivno hidrirala. Kapsule u kremi oslobađaju koncentrisane aktivne sastojke pri nanošenju, pružajući dugotrajan efekat punoće i elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/09/VT-Cosmetics-PDRN-Capsule-Cream-100.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
