INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (459, 159, 'Sungboon Editor Deep Collagen Retinol Tension Boost Up Mask', 'sungboon-editor-deep-collagen-retinol-tension-boost-up-mask', 'Ključne prednosti: Zatezanje i učvršćivanje: retinol i Volufiline vraćaju tonus koži i smanjuju opuštenost. Smanjenje bora: hidrolizovani kolagen pomaže da koža postane punija i glatkija. Poboljšanje sjaja i teksture: maska vraća blistavost, ujednačava ton i osvežava lice. Kome je namenjena? Maska je namenjena koži koja pokazuje znake umora, opuštenosti ili izraženijih bora. Posebno pogodna za normalnu do suvu kožu koja traži brzo osveženje i učvršćivanje. Zašto volimo SUNGBOON EDITOR Deep Collagen Retinol Tension Boost Up Mask? Dvodelna fleksibilna maska od heksagonalne mreže oblikovana je tako da savršeno prijanja uz lice i deluje intenzivno na svim zonama. Retinol stimuliše obnavljanje ćelija, učvršćuje kožu i deluje protiv znakova starenja. Volufiline dodatno podiže i daje osećaj zategnutosti, dok hidrolizovani kolagen vraća punoću, popunjava fine linije i čini kožu čvršćom. Zahvaljujući hidratantnim komponentama, koža ostaje nahranjena i meka, bez osećaja zatezanja nakon skidanja maske. Rezultat je trenutni “boost” u elastičnosti i svežini tena, uz vidljivo glađu i blistaviju kožu. Aktivni sastojci Retinol Podstiče obnovu ćelija, učvršćuje kožu i smanjuje bore, istovremeno poboljšavajući teksturu i tonus. Volufiline Biljni sastojak (iz korena Anemarrhena asphodeloides) koji daje efekat zatezanja i vraća punoću koži, čineći je elastičnijom. Hidrolizovani kolagen Obnavlja vlagu i elastičnost, popunjava fine linije i vraća glatkoću koži. Dodaj u listu želja Dodaj u listu želja', 'SUNGBOON EDITOR Deep Collagen Retinol Tension Boost Up Mask koristi retinol, hidrolizovani kolagen i Volufiline da učvrsti kožu, poveća elastičnost i smanji vidljivost bora. Dvodelna fleksibilna maska savršeno prijanja licu i vraća mu osvežen, zategnut i zdrav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/09/SUNGBOON-EDITOR-Deep-Collagen-Retinol-Tension-Boost-Up-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
