INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (462, 124, 'Nine Less Molecule-Clear 5% Glycolic Acid Serum', 'nine-less-molecule-clear-5-glycolic-acid-serum', 'Ključne prednosti: Poboljšava teksturu: glikolna kiselina uklanja mrtve ćelije i zaglađuje kožu. Pročišćava pore: smanjuje začepljenja i pojavu nepravilnosti. Posvetljuje ten: ujednačava boju kože i vraća prirodan sjaj. Kome je namenjen? Preporučuje se za normalnu, kombinovanu i masnu kožu sa grubom teksturom, proširenim porama i neujednačenim tonom. Nije pogodan za vrlo osetljivu ili izrazito reaktivnu kožu. Zašto volimo Nine Less Molecule-Clear 5% Glycolic Acid Serum? Serum deluje kao hemijski piling u kućnoj rutini, uklanjajući površinske mrtve ćelije i omogućavajući bolju apsorpciju aktivnih sastojaka iz narednih koraka nege. Glikolna kiselina, zahvaljujući svojoj maloj molekulskoj masi, prodire dublje u epiderm i podstiče obnavljanje ćelija, čime koža postaje glađa i osveženija. Redovnim korišćenjem smanjuje se pojava mitesera i sitnih nepravilnosti, dok ten postaje ujednačeniji i blistaviji. Uz glikolnu kiselinu, formula sadrži i umirujuće i hidratantne sastojke koji smanjuju rizik od iritacija i održavaju ravnotežu kože. Tekstura je lagana, brzo se upija i lako se uklapa u večernju rutinu. Rezultat je koža koja izgleda pročišćeno, glatko i osvetljeno. Aktivni sastojci Glikolna kiselina (5%) AHA kiselina koja deluje eksfolijantno, uklanja mrtve ćelije i podstiče obnavljanje kože. Smanjuje začepljene pore, poboljšava teksturu i vraća sjaj tenu. Hijaluronska kiselina Hidrira i održava vlažnost tokom eksfolijacije. Ublažava osećaj zatezanja i doprinosi elastičnosti. Beta-glukan Umiruje i štiti kožu od iritacija. Pomaže u regeneraciji i jača barijeru kože. Alantoin Deluje umirujuće i obnavljajuće. Pruža koži mekoću i smanjuje rizik od iritacija. Dodaj u listu želja Dodaj u listu želja', 'Nine Less Molecule-Clear 5% Glycolic Acid Serum koristi glikolnu kiselinu u optimalnoj koncentraciji kako bi uklonio mrtve ćelije kože, smanjio začepljenje pora i posvetlio neujednačen ten. Namenjen je koži sa grubom teksturom, sitnim nepravilnostima i umornim izgledom.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Nine-Less-Molecule-Clear-5-Glycolic-Acid-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
