INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (463, 124, 'Nine Less Molecule-Clear 5% Lactic Acid Serum', 'nine-less-molecule-clear-5-lactic-acid-serum', 'Ključne prednosti: Blaga eksfolijacija: mlečna kiselina uklanja mrtve ćelije i podstiče obnavljanje kože. Hidratacija i punoća: zbog svojih humektantnih svojstava mlečna kiselina i hijaluronska kiselina vraćaju vlagu. Posvetljivanje tena: ujednačava boju kože i daje zdrav sjaj. Kome je namenjen? Preporučuje se za normalnu, suvu, kombinovanu i blago osetljivu kožu kojoj je potrebna blaga, ali efikasna eksfolijacija. Idealan je za kožu sa diskoloracijama, grubom teksturom i prvim znacima starenja. Zašto volimo Nine Less Molecule-Clear 5% Lactic Acid Serum? Serum sa 5% mlečne kiseline osmišljen je da pruži balans između efikasne eksfolijacije i nežne nege, pa je pogodan i za osetljiviju kožu. Mlečna kiselina uklanja mrtve ćelije sa površine, podstiče prirodnu obnovu i vraća glatkoću tenu. Za razliku od glikolne kiseline, deluje blaže, ali i dodatno hidrira, što ga čini idealnim za suvlju ili dehidriranu kožu. U kombinaciji sa hijaluronskom kiselinom i beta-glukanom, serum sprečava osećaj zatezanja i iritacija, ostavljajući kožu hidriranom i umirenom. Redovnom upotrebom smanjuje sitne nepravilnosti, posvetljuje tamne fleke i vraća koži svežinu. Tekstura je lagana i brzo se upija, što ga čini jednostavnim za uključivanje u večernju rutinu. Aktivni sastojci Mlečna kiselina (5%) AHA kiselina koja nežno uklanja mrtve ćelije i podstiče obnavljanje kože. Deluje blaže od glikolne kiseline, a pritom zadržava vlagu u epidermu. Hijaluronska kiselina Pruža višeslojnu hidrataciju i održava elastičnost kože. Ublažava osećaj zatezanja nakon eksfolijacije. Beta-glukan Umiruje i jača barijeru kože. Deluje antioksidativno i pomaže u regeneraciji. Alantoin Daje mekoću i smanjuje rizik od iritacija. Podržava proces obnove kože. Dodaj u listu želja Dodaj u listu želja', 'Nine Less Molecule-Clear 5% Lactic Acid Serum kombinuje mlečnu kiselinu, hijaluronsku kiselinu i umirujuće sastojke kako bi zagladio površinu kože, ujednačio ten i istovremeno zadržao vlagu. Namenjen je koži sa grubom teksturom, sitnim nepravilnostima i znakovima umora.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Nine-Less-Molecule-Clear-5-Lactic-Acid-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
