INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (464, 124, 'Nine Less Molecule-Clear Salicylic Acid Serum', 'nine-less-molecule-clear-salicylic-acid-serum', 'Ključne prednosti: Dubinsko čišćenje pora: salicilna kiselina prodire u pore, uklanja sebum i mrtve ćelije. Balans i hidratacija: glicerin, betain i hijaluronska kiselina vraćaju vlagu i štite kožu od dehidratacije. Umirujući efekat: pantenol i alantoin smanjuju crvenilo i podržavaju regeneraciju kože. Kome je namenjen? Idealno rešenje za masnu, kombinovanu i kožu sklonu aknama. Posebno koristan kod proširenih pora, mitesera i kože sa viškom sebuma. Zašto volimo Nine Less Molecule-Clear Salicylic Acid Serum? Ovaj serum je formulisán kao efikasan tretman protiv zapušenih pora i akni. Salicilna kiselina (BHA) prodire duboko u pore, rastvara višak sebuma i uklanja mrtve ćelije, čime sprečava nastanak novih nepravilnosti. Istovremeno, hidratantni kompleksi – glicerin, betain i hijaluronska kiselina – obnavljaju vlažnost i čuvaju elastičnost kože, pa ne dolazi do isušivanja. Pantenol i alantoin deluju umirujuće i regenerativno, smanjujući osećaj iritacije ili zatezanja. Zahvaljujući pažljivoj formulaciji, serum čisti i balansira kožu, a pri tom ostaje blag i pogodan za svakodnevnu rutinu. Rezultat je čistija, ujednačenija i zdravija koža sa manje nepravilnosti. Aktivni sastojci Salicilna kiselina (BHA) Hemijski eksfolijant koji rastvara višak sebuma i otčepljuje pore. Deluje protivupalno i pomaže u smanjenju akni i mitisera. Glicerin Ovlaživač koji vezuje vlagu i čuva hidrataciju kože tokom tretmana kiselinama. Ostavlja kožu mekom i glatkom. Betain Prirodni osmolit koji hidrira i štiti ćelije kože od dehidratacije. Poboljšava otpornost kože na spoljašnje faktore. Dodaj u listu želja Dodaj u listu želja', 'Nine Less Molecule-Clear Salicylic Acid Serum kombinuje 2% salicilne kiseline sa hidratantnim i umirujućim sastojcima poput pantenola, glicerina i betaina. Namenjen je masnoj i koži sklonoj aknama, jer uklanja višak sebuma, čisti pore i smanjuje upale bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Nine-Less-Molecule-Clear-Salicylic-Acid-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
