INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (467, 126, 'Numbuzin No.2 Rose PDRN Collagen Plumping Serum', 'numbuzin-no-2-rose-pdrn-collagen-plumping-serum', 'Ključne prednosti: Povećava punoću: 62% kolagenske vode obnavlja tonus i daje koži čvrst izgled. Regeneracija i obnova: 5% Rose PDRN stimuliše regeneraciju ćelija i jača kožnu barijeru. Anti-age efekat: 6 peptida smanjuju fine linije i podstiču sintezu kolagena i elastina. Kome je namenjen? Preporučuje se koži koja je izgubila punoću, elastičnost i ima prve znake bora. Pogodan je za normalnu, suvu i kombinovanu kožu kojoj nedostaje hidratacija i čvrstina. Zašto volimo Numbuzin No.2 Rose PDRN Collagen Plumping Serum? Ovaj serum deluje kao intenzivna podrška koži koja gubi elastičnost i volumen. Kolagenska voda u visokoj koncentraciji vraća punoću i učvršćuje strukturu kože, dok Rose PDRN (5%) podstiče regeneraciju i jača barijeru, čineći ten otpornijim i zdravijim. Kompleks od 6 peptida sinergijski deluje na sintezu kolagena i elastina, što vidljivo smanjuje sitne bore i vraća koži čvrstinu. Tekstura seruma je bogata, ali se brzo upija i ostavlja osećaj hidrirane i mekane kože. Klinička testiranja pokazala su poboljšanje volumena u zonama čela, obraza i nazolabijalnih linija već nakon dve nedelje upotrebe. Rezultat je elastičnija, zategnutija i blistava koža. Aktivni sastojci Rose PDRN (5%) Podstiče regeneraciju i obnovu ćelija, jača barijeru kože i vraća joj otpornost. 62% Collagen Water Vraća elastičnost i punoću, učvršćuje tonus i smanjuje vidljivost finih linija. 6 peptida Podržavaju sintezu kolagena i elastina, doprinoseći smanjenju bora i jačanju strukture kože. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.2 Rose PDRN Collagen Plumping Serum kombinuje Rose PDRN, kolagensku vodu i peptide kako bi popunio kožu i vratio joj mladalačku elastičnost. Namenjen je koži sa prvim znacima starenja, opuštenim konturama i sitnim borama.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.2-Rose-PDRN-Collagen-Plumping-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
