INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (468, 126, 'Numbuzin No.2 Rose PDRN Collagen 2X Plumping Serum', 'numbuzin-no-2-rose-pdrn-collagen-2x-plumping-serum', 'Ključne prednosti: Intenzivno popunjavanje: kolagen i peptidi vraćaju čvrstinu i punoću tenu. Regeneracija i obnova: Rose PDRN stimuliše obnovu ćelija i jača kožnu barijeru. Anti-age efekat: smanjuje vidljivost finih linija i doprinosi mladalačkom sjaju. Kome je namenjen? Preporučuje se koži koja je izgubila elastičnost i punoću, kao i kod prvih znakova starenja. Pogodan je za normalnu do suvu kožu kojoj nedostaje hidratacija i sjaj. Zašto volimo Numbuzin No.2 Rose PDRN Collagen 2X Plumping Serum? Ovaj serum osmišljen je kao koncentrisani tretman za umornu, opuštenu i dehidriranu kožu. Dvostruka doza kolagena deluje direktno na punoću i tonus kože, dok 15 različitih peptida stimulišu sintezu kolagena i elastina, čineći kožu čvršćom i otpornijom. Rose PDRN u koncentraciji od 10% podstiče regeneraciju ćelija, ubrzava proces oporavka i jača barijeru, što doprinosi zdravijem izgledu kože. Formula je obogaćena i hidratantnim sastojcima koji sprečavaju osećaj zatezanja i vraćaju glatkoću. Tekstura je bogata, ali se brzo upija, ostavljajući kožu mekom i elastičnom. Redovnim korišćenjem vidljivo se smanjuju fine linije, a ten postaje zategnutiji i osvežen. Aktivni sastojci Rose PDRN (10%) Biotehnološki derivat koji podstiče regeneraciju ćelija i obnovu kože. Jača barijeru i poboljšava elastičnost. Kolagen shot (2X koncentracija) Vraća punoću i elastičnost, smanjuje sitne bore i doprinosi zategnutom tenu. 15 peptida Deluju sinergijski u stimulaciji sinteze kolagena i elastina. Jačaju strukturu kože i smanjuju znakove starenja. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.2 Rose PDRN Collagen 2X Plumping Serum kombinuje kolagen, PDRN i peptide kako bi pružio efekat zategnute i hidrirane kože. Namenjen je koži koja je izgubila punoću i elastičnost, sa izraženim prvim znacima starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.2-Rose-PDRN-Collagen-2X-Plumping-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
