INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (469, 126, 'Numbuzin No.4 Ceramide AHA Glazed Skin Prep Serum', 'numbuzin-no-4-ceramide-aha-glazed-skin-prep-serum', 'Ključne prednosti: Blaga eksfolijacija: glikolna kiselina i PHA uklanjaju mrtve ćelije i zaglađuju teksturu kože. Obnova barijere: 5 ceramida jačaju kožu i smanjuju transepidermalni gubitak vlage. Hidratacija i punoća: serum održava vlažnost i čini kožu mekom i otpornom. Kome je namenjen? Preporučuje se masnoj i kombinovanoj koži sa proširenim porama, mitiserima i neravnomernim tonom. Pogodan je i za one koji žele uvesti retinol u rutinu, jer formula pruža balans između efikasnosti i podnošljivosti. Zašto volimo Numbuzin No.4 Ceramide AHA Glazed Skin Prep Serum? Serum spaja delotvornost AHA i PHA kiselina sa zaštitnim svojstvima ceramida, nudeći balans između pilinga i obnove kože. Glikolna kiselina (3%) prodire u površinske slojeve kože i uklanja mrtve ćelije, dok PHA kiseline rade blaže, ali dodatno pružaju hidrataciju. Ova kombinacija pomaže da se poboljša tekstura i ujednači ten bez preterane iritacije. Kompleks od 5 ceramida obnavlja lipidnu barijeru, smanjuje gubitak vlage i čini kožu otpornijom na spoljašnje faktore. Zahvaljujući ovoj sinergiji, serum je dovoljno snažan da osveži kožu, a dovoljno blag da se koristi redovno. Aktivni sastojci Glikolna kiselina (3%) AHA kiselina koja uklanja mrtve ćelije i poboljšava teksturu kože. Pomaže u posvetljivanju i ravnomernom tenu. PHA (3%) Blage hidroksi kiseline koje eksfoliraju uz dodatni hidratantni efekat. Idealne su za osetljiviju kožu. 5 ceramida Obnavljaju lipidnu barijeru, sprečavaju transepidermalni gubitak vlage i jačaju otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.4 Ceramide AHA Glazed Skin Prep Serum je serum sa 3% glikolne kiseline, 3% PHA koje uklanjaju mrtve ćelije i sa kompleksom od 5 ceramida, koji obnavljaju zaštitnu barijeru. Namenjen je koži kojoj je potrebna eksfolijacija bez isušivanja i gubitka elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.4-Ceramide-AHA-Glazed-Skin-Prep-Serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
