INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (470, 126, 'Numbuzin No.2 Rose PDRN Collagen Plumping Sheet Mask', 'numbuzin-no-2-rose-pdrn-collagen-plumping-sheet-mask', 'Ključne prednosti: Instant hidratacija: maska dubinski vlaži i smanjuje osećaj zategnutosti. Povećava elastičnost: PDRN, kolagen i peptidi jačaju strukturu kože i vraćaju joj punoću. Brzi osvežavajući efekat: trenutno poboljšava izgled tena i čini ga blistavim. Kome je namenjena? Preporučuje se svim tipovima kože kojima nedostaje hidratacija, elastičnost i blistavost. Posebno pogodna za umornu i dehidriranu kožu sa prvim znacima starenja. Zašto volimo Numbuzin No.2 Rose PDRN Collagen Plumping Sheet Mask? Ova sheet maska je praktičan tretman koji u kratkom roku daje vidljive rezultate. Rose PDRN stimuliše regeneraciju i pomaže koži da se brže oporavi od spoljašnjih stresora, dok kolagen vraća punoću i elastičnost. Kompleks peptida podstiče sintezu kolagena i elastina, smanjujući sitne linije i umorni izgled kože. Zahvaljujući bogatom serumu kojim je maska natopljena, koža postaje hidrirana, mekša i osvežena već nakon jedne upotrebe. Idealna je kao brzi “boost” pred važan događaj ili kada koži treba dodatna nega i sjaj. Aktivni sastojci Rose PDRN Podstiče obnavljanje ćelija i jača kožnu barijeru, doprinoseći regeneraciji i otpornosti kože. Kolagen Povećava elastičnost i punoću kože, smanjujući vidljivost finih linija. Peptidi Podstiču sintezu kolagena i elastina, jačaju strukturu i čvrstinu kože. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.2 Rose PDRN Collagen Plumping Sheet Mask pruža trenutni efekat punoće i hidriranosti zahvaljujući kombinaciji PDRN-a, kolagena i peptida. Namenjena je koži kojoj je potrebna brza regeneracija, elastičnost i sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.2-Rose-PDRN-Collagen-Plumping-Sheet-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
