INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (472, 126, 'Numbuzin No.9 NAD+ Collagen Under Eye Patches', 'numbuzin-no-9-nad-collagen-under-eye-patches', 'Ključne prednosti: Obnova i energija: NAD+ podstiče regeneraciju i vitalnost kože oko očiju. Povećava elastičnost: kolagen i peptidi vraćaju čvrstinu i smanjuju bore. Osvežava pogled: hidratacija i hlađenje ublažavaju umoran izgled i natečenost. Kome su namenjeni? Preporučuje se svima koji žele ciljanu negu područja oko očiju, posebno kod znakova umora, prvih bora i gubitka elastičnosti. Pogodni su za sve tipove kože, uključujući i osetljivu. Zašto volimo Numbuzin No.9 NAD+ Collagen Under Eye Patches? Jastučići su bogato natopljeni serumom koji ciljano deluje na najosetljiviju regiju lica – područje oko očiju. NAD+ (nikotinamid adenin dinukleotid), poznat kao molekul dugovečnosti, pomaže ćelijama kože da obnove energiju i ubrzaju procese regeneracije. Kolagen doprinosi vraćanju elastičnosti i čvrstine, dok peptidi stimulišu prirodnu sintezu kolagena i elastina. Hidratantni kompleksi i umirujući sastojci smanjuju osećaj suvoće i zategnutosti, dok hladna hidrogel tekstura trenutno osvežava i ublažava otečenost. Redovnom upotrebom koža oko očiju postaje glatkija, odmornija i blistavija, a bore i tamni kolutovi manje vidljivi. Aktivni sastojci NAD+ Koenzim ključan za regeneraciju i energiju ćelija, poznat po anti-age efektima i podršci prirodnim procesima obnove kože. Kolagen Povećava čvrstinu i elastičnost kože, smanjuje bore i vraća punoću. Peptidi Podstiču sintezu kolagena i elastina, jačaju strukturu kože i čine je otpornijom. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.9 NAD+ Collagen Under Eye Patches pružaju intenzivnu hidrataciju i elastičnost tankoj koži oko očiju. Zahvaljujući NAD+, kolagenu i peptidima, pomažu u smanjenju finih linija, natečenosti i tamnih kolutova.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Numbuzin-No.9-NAD-Collagen-Under-Eye-Patches.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
