INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (473, 135, 'Purcell Pixcell Biom™ Hyaluronic Collagen Splash Cream', 'purcell-pixcell-biom-hyaluronic-collagen-splash-cream', 'Ključne prednosti: Intenzivna hidratacija: hijaluronska kiselina i pantenol obnavljaju nivo vlage i smanjuju osećaj zatezanja. Jačanje barijere: Pixcell Biom™ i ceramidi štite kožu i čine je otpornijom na spoljne faktore. Ujednačen ten: kolagen i niacinamid vraćaju koži elastičnost i prirodan sjaj. Kome je namenjena? Preporučuje se svima &#8211; posebno kod znakova umora, prvih bora i gubitka elastičnosti. Pogodni su za sve tipove kože, uključujući i osetljivu. Zašto volimo Purcell Pixcell Biom™ Hyaluronic Collagen Splash Cream? Krema je formulisana da pruži koži dugotrajnu hidrataciju i obnavljanje uz istovremenu zaštitu od isušivanja i iritacija. Kompleks hijaluronske kiseline vezuje vlagu i čini kožu punijom i mekšom, dok kolagen doprinosi vraćanju elastičnosti i smanjenju vidljivosti finih linija. Niacinamid u formuli deluje kao aktivni posvetljivač i antioksidans, ujednačava ton kože i poboljšava njen sjaj. Pantenol smiruje i jača barijeru, dok Pixcell Biom™ sa probiotičkim ekstraktima Lactobacillus Bifida podržava zdrav mikrobiom kože. Tekstura je lagana, ali bogata, brzo se upija i ostavlja osećaj svežine, bez lepljivog sloja. Redovnom upotrebom koža postaje vidljivo hidrirana, mekša, otpornija i mladalačkijeg izgleda. Aktivni sastojci Hijaluronska kiselina Višeslojno hidrira kožu i zadržava vlagu, dajući joj punoću i mekoću. Kolagen Obnavlja elastičnost i vraća koži čvrstinu, smanjujući vidljivost bora. Niacinamid (vitamin B3) Ujednačava ten, posvetljuje hiperpigmentacije i jača barijeru kože. Pantenol (provitamin B5) Deluje umirujuće, smanjuje crvenilo i podržava regeneraciju kože. Lactobacillus Bifida (Pixcell Biom™) Probiotički kompleks koji jača mikrobiom, balansira kožu i povećava njenu otpornost na spoljne stresore. Dodaj u listu želja Dodaj u listu želja', 'Purcell Pixcell Biom™ Hyaluronic Collagen Splash Cream kombinuje hijaluronsku kiselinu, kolagen i ceramide sa vitaminom B3 i provitaminom B5, pružajući koži dubinsku hidrataciju i zaštitu. Namenjena je koži kojoj nedostaje elastičnost, sjaj i otpornost na spoljašnje stresore.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Purcell-Pixcell-Biom™-Hyaluronic-Collagen-Splash-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
