INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (474, 138, 'Pyunkang Yul Calming Moisture Repair Balm', 'pyunkang-yul-calming-moisture-repair-balm', 'Ključne prednosti: Intenzivna hidratacija: četvoro-pet vrsta hijaluronskih jedinjenja + skvalane + shea puter vraćaju vlagu i sprečavaju isušivanje. Umirenje i regeneracija: ekstrakti kao što su centella i ulje čajevca smanjuju crvenilo, oslabljenu kožu vraćaju u stabilno stanje. Obnova barijere i jača elastičnost: peptidi i masne komponente hrane kožu i čine je otpornijom na spoljašnje stresore. Kome je namenjena? Balzam je posebno koristan za osetljivu, nadraženu i dehidriranu kožu kojoj nedostaje hidratacija i elastičnost. Pogodan je i za kožu sklonu spoljnim stresorima (vetar, hladnoća, UV), jer pruža obnovu barijere i umirujuće dejstvo. Zašto volimo Pyunkang Yul Calming Moisture Repair Balm? Ovaj balzam je dizajniran da deluje kao zaštitni štit: prvo umiruje iritacije i crvenilo zahvaljujući cica-ekstraktu (Centella Asiatica), ekstraktu tea tree-a i cveta orlovih noktiju. Dok vlaga nestaje iz kože — što zna da bude problem kod nadraženih zona — sastojci poput pantenola, glicerina i hijaluronskih jedinjenja privlače i zadržavaju vodu, što čini kožu mekšom i gipkijom. Squalane i shea puter hrane kožu i vraćaju joj snagu, bez osećaja težine ili zapušavanja pora. Peptidi pomažu u podsticanju regeneracije i jačanju elastičnosti kože, što povlači linije i čini kožu čvršćom. Formulacija je bez mirisa, bez jakih alkohola i agresivnih dodataka, što je čini pogodnom i za vrlo osetljivu ili reaktivnu kožu. Redovnom upotrebom koža postaje bolja u izgledu, zaštitena i manje sklona iritacijama. Aktivni sastojci Skvalane Prirodni lipid koji je vrlo kompatibilan sa kožom, hidrira i vraća mekoću bez zapušavanja pora. Centella Asiatica (cica-ekstrakt) Umiruje kožu, smanjuje crvenilo i podržava proces regeneracije kože. Pantenol (provitanin B5) Neguje, umiruje i pomaže u brzom oporavku kožne barijere. Hijaluronske kiseline (višestruke forme: Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Crosspolymer i drugi) Povećavaju vlagu u koži, vezuju vodu i čine kožu punijom i mekom. Peptidi (npr. Acetyl Hexapeptide-8, Palmitoyl Tripeptide-5 i sl.) Stimuliraju sintezu kolagena, poboljšavaju čvrstinu i vraćaju integritet kože. Shea puter (Butyrospermum Parkii Butter) Bogata mast koja hrani i štiti kožu, vraćajući joj glatkoću i elastičnost. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Calming Moisture Repair Balm kombinuje hijaluronske kiseline, skvalan, cica-ekstrakt i peptide kako bi pružio dubinsku hidrataciju, umirio iritacije i ojačao zaštitnu barijeru kože. Namenjen je koži sklonoj crvenilu, oštećenjima od spoljašnjih faktora i gubitku vlage.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Pyunkang-Yul-Calming-Moisture-Repair-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
