INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (476, 137, 'Purito Wonder Releaf Centella Spot Patch', 'purito-wonder-releaf-centella-spot-patch', 'Ključne prednosti: Smiruje i obnavlja: aktivne komponente centelle ublažavaju upalu i ubrzavaju regeneraciju kože. Zaštitna barijera: hidrokoloidni sloj sprečava dodirivanje i kontaminaciju, čime se smanjuje rizik od novih iritacija. Diskretan izgled: ultra tanak i providan, lako se nosi tokom dana, čak i ispod šminke. Kome su namenjeni? Namenjen osobama koje imaju upalne bubuljice, sitne iritacije ili crvenilo i žele brzo, nežno rešenje. Posebno koristan kod kože sklone aknama i kod onih koji žele da spreče nastanak ožiljaka od stalnog dodirivanja. Zašto volimo Purito Oat In Gentle Exfoliating Face Cleanser? Flaster stvara zaštitni sloj koji čuva problematična mesta od prljavštine, bakterija i mehaničkih dodira, dok istovremeno upija višak sekreta iz bubuljice. Zahvaljujući ekstraktu centelle, koža se smiruje i vraća u balans, a crvenilo postaje manje izraženo. Madecassoside i madecasična kiselina ubrzavaju procese obnove i jačaju prirodnu barijeru kože, dok asiatična kiselina deluje antioksidativno i pruža dodatnu zaštitu. Hidrokoloidni sloj održava vlažnu mikroklimu, što pomaže koži da zaceli bez isušivanja i ljuštenja. Flaster je tanak i prijanja uz kožu, pa se lako nosi i danju i noću, bez osećaja nelagodnosti. Aktivni sastojci Ekstrakt centelle (Centella Asiatica Extract) Poznat po svom umirujućem i regenerativnom dejstvu, smanjuje crvenilo i ubrzava zaceljivanje kože. Madecassoside Aktivna komponenta centelle sa snažnim antiinflamatornim i antioksidativnim efektom; podstiče obnavljanje tkiva. Madecasična kiselina (Madecassic Acid) Pruža antiupalno i regenerativno delovanje, jača barijeru kože i smanjuje osetljivost. Asiatična kiselina (Asiatic Acid) Doprinosi smirivanju iritacija i deluje zaštitno na kožu, jačajući njenu otpornost. Hidrokoloidna matrica Specijalni polimer koji upija višak sekreta i održava vlažno okruženje, ubrzavajući prirodno zarastanje bez stvaranja krasti. Dodaj u listu želja Dodaj u listu želja', 'Purito Wonder Releaf Centella Spot Patch su hidrokoloidni flasteri obogaćeni ekstraktom centelle i njenim aktivnim komponentama, osmišljeni da smire upaljena mesta i ubrzaju proces obnavljanja kože.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Purito-Wonder-Releaf-Centella-Spot-Patch.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
