INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (477, 137, 'Purito Oat In Gentle Exfoliating Face Cleanser', 'purito-oat-in-gentle-exfoliating-face-cleanser', 'Ključne prednosti: Blaga, ali efikasna eksfolijacija: piling od ovasa nežno uklanjaju mrtve ćelije i čine teksturu kože glatkijom. Hidratacija i umirenje: voda ovsenog semena, pantenol i glicerin održavaju vlagu i umiruju kožu tokom čišćenja. Jačanje barijere kože: sastojci poput pantenola, skvalana i ulja semenki suncokreta pomažu u zaštiti kože od isušivanja i iritirajućih spoljašnjih uticaja. Kome je namenjen? Pogodan je za sve tipove kože, a posebno za suvu, osetljivu i kombinovanu kožu koja ima grubu, perutavu ili neujednačenu teksturu. Dobro je rešenje za one koji žele blagu svakodnevnu eksfolijaciju bez agresivnih kiselina ili grubih pilinga. Zašto volimo Purito Oat In Gentle Exfoliating Face Cleanser? Ovaj čistač deluje kao idealna kombinacija blagog pilinga i hidratantne nege. Voda ovsenog semena u visokom procentu hidrira kožu i umiruje moguće iritacije, dok zobene čestice nežno uklanjaju površinske nečistoće i mrtve ćelije bez agresivnog trljanja. Pantenol doprinosi brzom osećaju olakšanja, uklanja osećaj suvoće i jača zaštitnu barijeru kože. Prisutni su i emolijenti poput ulja semenki suncokreta i skvalana, koji daju koži mekoću i izbegavaju osećaj zategnutosti nakon ispiranja. Tekstura je kremasta sa blagim abrazivnim efektom, što dopušta da se koristi i kao svakodnevni proizvod, ali i relativno redovno blagi piling. Dugoročno, koža bude ujednačenija, mekša, sa smanjenim osećajem grube površine i zdravijim sjajem. Aktivni sastojci Voda ovsenog semena (Avena Sativa Seed Water, ~ 92 000 ppm) Snažno hidrira i umiruje kožu jer je dobiveno iz zrna zobi otpornog tipa; pomaže u obnovi vlažnog balansa kože i smanjenju iritacija. Ovsene čestice / ovseno brašno (Oat Kernel Flour, Oat Seed Meal) Fizički eksfolijant u dve veličine; nežno uklanjaju mrtvu kožu i izravnavaju teksturu bez prevelikog iritiranja. Dodaj u listu želja Dodaj u listu želja', 'Purito Oat In Gentle Exfoliating Face Cleanser koristi vodu ovsenog semena i fine čestice ovasa kako bi glatko i bez oštećenja uklonio suve i grube delove kože. Namenjen je svima koji žele svakodnevno čišćenje uz blagi piling, bez osećaja zatezanja ili iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Purito-Oat-In-Gentle-Exfoliating-Face-Cleanser.jpeg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
