INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (478, 143, 'Round Lab 1025 Dokdo Cleansing Milk', 'round-lab-1025-dokdo-cleansing-milk', 'Ključne prednosti: Nežno čišćenje: uklanja svetlu šminku, SPF i nečistoće bez agresivnog trljanja ili iritacije. Hidratacija i zaštita barijere: ceramidi i hijaluronske kiseline vraćaju vlagu i podržavaju prirodnu zaštitu kože. Umirujući efekti: sastojci poput alantoina i pantenola umanjuju crvenilo i osećaj nelagodnosti. Kome je namenjena? Krema je namenjena osobama sa suvom, osetljivom ili dehidriranom kožom, uključujući i one sa narušenom kožnom barijerom. Pogodna je i za masnu i kombinovanu kožu kojoj je potrebna balansirana, nemasna hidratacija bez opterećenja. Zašto volimo Round Lab 1025 Dokdo Cleansing Milk? Cleansing Milk ima mlečnu, kremastu teksturu koja se lako razmazuje i ne “vuče” kožu. Kada se nanese na suvu kožu i emulzifikovano sa malo vode, pretvara se u blagu emulziju koja nežno topi šminku i podele zaštite od sunca. Ceramidi NP, NS, AP, AS i EOP zajedno sa hijaluronskom kiselinom (raznim oblicima) obnavljaju lipide kože i vraćaju vlagu, sprečavajući osećaj zategnutosti koji često dolazi posle čišćenja. Sastojci poput glicerina, dipotassium glycyrrhizate, alantoina i pantenola deluju umirujuće, što ga čini pogodnim i za osetljivu kožu. Morska voda (“sea water”) dodaje minerale koji mogu pomoći u jačanju kože i pružanju osećaja svežine. Redovna upotreba ostavlja kožu glatkom, mekom i hidriranom, sa poboljšanom elastičnošću i manje vidljivim nepravilnostima. Aktivni sastojci Dubinska morska voda sa ostrva Dokdo Ova voda se crpi sa dubine od 5.000 metara ispod ostrva Dokdo i poznata je po visokom sadržaju prirodnih minerala, uključujući kalcijum, magnezijum i cink. Minerali igraju ključnu ulogu u održavanju optimalne funkcije ćelija kože, poboljšavajući prirodnu hidrataciju i otpornost. Njihovo delovanje pomaže u balansiranju nivoa pH i jačanju kožne barijere, posebno kod osoba sa oslabljenom ili iritiranom kožom. Ova voda takođe deluje umirujuće i obnavljajuće, što je čini pogodnom za svakodnevnu upotrebu. Za razliku od obične vode koja isparava i može isušiti kožu, dubinska voda iz Dokda ostavlja zaštićen sloj koji sprečava gubitak vlage. U kombinaciji sa ostalim aktivnim sastojcima, pruža sveobuhvatnu negu kože. Ceramidi i skvalan Ceramidi su ključni lipidi koji čine do 50% zaštitne barijere kože. Njihova prisutnost u formuli pomaže u obnavljanju oštećenih slojeva kože i sprečavanju transepidermalnog gubitka vlage. Skvalan , prirodni emolijent, dodatno omekšava kožu i poboljšava njen izgled bez začepljivanja pora. Zajedno, ovi sastojci jačaju otpornost kože, čineći je glatkijom, elastičnijom i manje reaktivnom. Skvalan takođe ima antioksidativna svojstva i pomaže u neutralisanju štetnih uticaja iz okoline. Njihovo dejstvo je sinergijsko i idealno za suvu i reaktivnu kožu kojoj je potrebna dubinska obnova. Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Cleansing Milk kombinuje hijaluronsku kiselinu, ceramide i morsku vodu iz Dokdo oblasti kako bi temeljno čistio, ali i negovao kožu bez isušivanja. Namenjen je za sve tipove kože, posebno onu osetljivu i dehidriranu, koja zahteva blagu ali efektivnu negu.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Round-Lab-1025-Dokdo-Cleansing-Milk.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
