INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (480, 156, 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Treatment', 'some-by-mi-cica-peptide-anti-hair-loss-derma-scalp-treatment', 'Ključne prednosti: Čišćenje i pročišćavanje: salicilna kiselina uklanja višak sebuma i mrtve ćelije sa vlasišta. Hranjenje i jačanje kose: peptidi i biotin podržavaju strukturu dlake, smanjuju lomljenje i opadanje. Umirenje vlasišta: centella i biljni ekstrakti smanjuju iritacije i crvenilo. Kome je namenjen? Preporučuje se osobama sa problemom opadanja kose, posebice ako je vlasište masno, zapušeno, sklono peruti, svrbu ili iritacijama. Takođe dobro funkcioniše za one koji imaju slabu, lomljivu kosu i žele da je ojačaju i poboljšaju njen izgled. Zašto volimo Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Treatment? Tretman ima kremastu, hranljivu teksturu, prilagođenu da neguje i vlasište i dlaku od korena do vrha. Salicilna kiselina deluje kao blagi eksfolijant koji pročišćava pore vlasišta, otklanja naslage sebuma i sprečava začepljenja folikula što često doprinosi opadanju kose. Peptidi i biotin ojačavaju koren dlake, poboljšavaju strukturu vlasi i smanjuju lomljenje, pa je kosa vidno čvršća i otpornija. Biljni proteini (kukuruzni, sojini, pšenični) dodatno hrane dlaku, daju joj sjaj i pomažu u obnovi oštećenja. Cica-ekstrakt (Centella Asiatica) zajedno sa ostalim biljnim ekstraktima pruža umirujući i regenerativni efekat, smanjuje osećaj iritacije ili nelagodnosti na vlasištu. Redovnom upotrebom vlasište postaje zdravije, opadanje kose može se smanjiti, a kosa izgleda gušće, mekše i živopisnije. Aktivni sastojci Salicilna kiselina BHA kiselina koja prodire u dubinu folikula vlasišta, uklanja mrtve ćelije i višak sebuma; pomaže u sprečavanju začepljenja i peruti. Biotin (vitamin B7) Podržava rast zdrave dlake, jača strukturu vlasi i smanjuje lomljenje. Peptidi (ukupno 11 vrsta) Male proteinske sekvence koje stimulišu regeneraciju, podržavaju sintezu keratina i ostalih proteina dlake, čineći je jačom. Cica-ekstrakt (Centella Asiatica)** Poznat po umirujućim i antiinflamatornim svojstvima, smanjuje iritacije i crvenilo, regeneriše kožu vlasišta. Dodaj u listu želja Dodaj u listu želja', 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Treatment kombinuje salicilnu kiselinu, biotin, biljke i peptide da očisti i ojača koren dlake, dok cica smiruje vlasište. Namenjen je osobama sa problemom opadanja kose, svraba ili masnog i izazvanog vlasišta, a cilj je vratiti zdrav izgled i vitalnost kosi.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Some-By-Mi-Cica-Peptide-Anti-Hair-Loss-Derma-Scalp-Treatment.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
