INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (481, 156, 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Tonic', 'some-by-mi-cica-peptide-anti-hair-loss-derma-scalp-tonic', 'Ključne prednosti: Dubinsko čišćenje vlasišta: salicilna kiselina pomaže da se očiste zapušeni folikuli i smanji stvaranje sebuma. Umirenje i zdravstveni balans: cica-ekstrakt, mentol i peptidi smanjuju crvenilo, iritacije i osećaj nelagodnosti. Podrška rastu i jačanje kose: kombinacija 11 peptida i biotin stimuliše koren, poboljšava elastičnost i smanjuje lomljenje kose. Kome je namenjen? Preporučuje se osobama sa masnim, kombinovanim ili problematičnim vlasištem, onima koji imaju zapušene folikule, perut ili osećaj neprijatnosti i svraba. Takođe je pogodan za one kojima kosa opada, tanji je ili slabi, i koji žele preventivnu negu da očuvaju volumen i zdravlje kose. Zašto volimo Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Tonic? Tonik ima laganu, vodenu teksturu, što omogućava da se ravnomerno rasprši po vlasištu. Salicilna kiselina (BHA) deluje tako što uklanja mrtve ćelije i višak sebuma iz folikula, sprečavajući zapušenja koja mogu doprineti gubitku kose. Mentol pruža osećaj osveženja i može pomoći u ublažavanju zatezanja vlasišta. Cica-ekstrakt i sastojci iz centella kompleksa (madecassoside, etc.) umiruju iritacije i jačaju zaštitnu funkciju kože glave, čineći je otpornijom. Kompleks peptida i proteina (soja, kukuruz, pšenica) zajedno sa biotinom pruža hranljive supstance korenu kose, što doprinosi jačanju, smanjenju lomljenja i održavanju gustine. Uz redovnu upotrebu, vlasište deluje čistije, koža glave bolje reaguje i kosa izgleda zdravije, manje ispada i sa boljom teksturom. Aktivni sastojci Salicilna kiselina (BHA) Eksfolijant koji prodire u pore vlasišta, uklanja sebum i mrtve ćelije, sprečava zapušenja i može umanjiti nastanak peruti i iritacija. Cica-ekstrakt (Centella Asiatica) Biljni sastojak sa umirujućim i regenerativnim osobinama; smanjuje upale, crvenilo i pomaže u obnavljanju barijere kože glave. 11 vrsta peptida Mali proteinski fragmenti koji stimulišu sintezu kolagena i drugih strukturalnih proteina; jačaju koren kose, poboljšavaju elastičnost i smanjuju lomljenje. Mentol Pruža osećaj hlađenja, umiruje i osvežava vlasište; može pomoći u osećaju toplote ili napetosti glave. Biotin Vitamin koji podržava strukturu dlačica, pomaže u jačanju i zdravijem rastu kose. Dodaj u listu želja Dodaj u listu želja', 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Tonic kombinuje salicilnu kiselinu (BHA), mentol i cica-ekstrakt s kompleksom peptida da ukloni višak sebuma, umiri iritacije i podrži folikule kose. Namenjen je za vlasište koje je sklono zapušenju, iritacijama, kao i kod problema s opadanjem kose.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Some-By-Mi-Cica-Peptide-Anti-Hair-Loss-Derma-Scalp-Tonic.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
