INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (482, 156, 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Shampoo', 'some-by-mi-cica-peptide-anti-hair-loss-derma-scalp-shampoo', 'Ključne prednosti: Tretman vlasišta: salicilna kiselina i PHA čiste pore vlasišta, smanjujući začepljenje folikula. Hlađenje i osveženje: mentol i biljni ekstrakti (menta, zelen čaj) umiruju i daju prijatan osećaj hlađenja nakon pranja. Jačanje i podrška rastu: peptidi, proteini i biotin hrane koren, jačaju kosu i smanjuju stanjivanje vlasi. Kome je namenjen? Preporučuje se osobama sa masnim ili kombinovanim vlasištem, sa problemom zapušenih folikula, svrabom ili osećajem nelagodnosti na skalpu. Takođe je koristan za kosu koja se stanji zbog faktora stresa, tretmana ili neadekvatne nege. Zašto volimo Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Shampoo? Ovaj šampon ima formulu prilagođenu za vlasište koje treba negu: nežne surfaktante koji čiste bez agresivnog isušivanja, u kombinaciji sa salicilnom kiselinom i gluconolactonom koji rade blagi hemijski piling vlasišta, uklanjajući mrtve ćelije i otvarajući zapušene folikule. Mentol pridonosi osećaju svežine i umirenja, posebno kod vlasišta koje svrbi ili oseća napetost. Kompleks od peptida (uključujući više vrsta peptida u veoma malim koncentracijama) zajedno sa proteinima (kukuruzni, soy, pšenica) i biotinom pomaže u jačanju korena, pojačanju rasta i smanjenju oštećenja vlasi. Cica-ekstrakt (Centella asiatica) i drugi biljni ekstrakti umiruju vlasište, smanjuju iritacije i podržavaju barijeru kože glave. Redovnim pranjem kosa i vlasište dobijaju zdraviji izgled, volumen se može povećati, dok se osećaj “opterećenog” vlasišta smanjuje. Aktivni sastojci Salicilna kiselina (BHA) Prodire u pore vlasišta, čisti zapušene folikule i uklanja višak sebuma i mrtve ćelije; pomaže u sprečavanju peruti i začepljenja. Gluconolactone (PHA) Blaga hemijska eksfolijacija koja uklanja površinske mrtve ćelije sa manje rizika od iritacija nego snažne kiseline; doprinosi ujednačenijoj i glatkijoj teksturi vlasišta. Peptidi (više vrsta: Palmitoyl Pentapeptide-4, Tripeptide-1, Hexapeptide-9 i dr.) Podržavaju strukturu vlasišta, stimulišu sintezu proteina kose i jačaju folikule; pomažu u smanjenju stanjivanja i gubitka kose. Dodaj u listu želja Dodaj u listu želja', 'Some By Mi Cica Peptide Anti Hair Loss Derma Scalp Shampoo kombinuje salicilnu kiselinu (BHA), PHA (glukonolakton), mentol i peptidne komplekse kako bi odstranio višak sebuma, razgradio mrtve ćelije i stimulisao zdrav rast kose. Namenjen je vlasištu koje je sklono zapušenim folikulama, iritacijama i osećaju zapušenosti.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Some-By-Mi-Cica-Peptide-Anti-Hair-Loss-Derma-Scalp-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
