INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (483, 143, 'Round Lab Pine Calming Cica Cream', 'round-lab-pine-calming-cica-cream', 'Ključne prednosti: Umirenje i zaštita: Pine iglice i centella smiruju upalu i jačaju barijeru kože. Hidratacija i punoća: hijaluronska kiselina kroz više oblika vraća vlagu i daje koži mekan i „napunjen“ osećaj. Blaga, ali efikasna eksfolijacija: LHA pomaže u uklanjanju mrtvih ćelija i regulaciji sebuma bez agresije. Kome je namenjena? Preporučuje se za osetljivu, reaktivnu kožu, kožu sa crvenilom ili nadraženošću, kao i za kombinovane tipove kože kojima je potrebna hidratacija i umirenje bez težine. Takođe dobra opcija za one koji žele blagu eksfolijaciju bez iritacija. Zašto volimo Round Lab Pine Calming Cica Cream? Formula koja čini značajan deo proizvoda — Pine Cica Activ (42 %) — zasnovana je na ekstraktu bora, biljnoj proteina/glicoproteinu i pet „cica“ sastojaka (kao što su madecassoside, asiatic acid, madecassic acid), koji zajedno podržavaju obnavljanje kože. Hijaluronske komponente (obični HA, hidrolizovani HA, natrijum hijaluronat) doprinose zadržavanju vlage u različitim slojevima kože, čineći je mekšom i elastičnijom. Blaga eksfolijacija putem LHA (capryloyl salicilne kiseline) pomaže da se očiste pore i ublaže fine sitne nepravilnosti bez iritirajućeg efekta “svetle kiseline”. Balansirana tekstura gel-kreme omogućava da se proizvod brzo upije, ostavljajući kožu hidriranom, ali ne masnom. Kod redovne upotrebe, koža izgleda smirenije, sa ujednačenijom teksturom i zdravijim sjajem. Aktivni sastojci Pinus Densiflora Leaf Extract (ekstrakt iglica bora) Daje antioksidativna svojstva, pomaže u zaštiti od slobodnih radikala i smanjuje oksidativni stres; istovremeno ima umirujući efekat na nadraženu kožu. Centella Asiatica Extract (Cica-ekstrakt) Poznata po antiinflamatornim i regenerativnim svojstvima; smanjuje crvenilo, podstiče zaceljivanje mikrooštećenja i jača barijeru kože. Hijaluronska kiselina / Natrijum hijaluronat / Hidrolizovana hijaluronska kiselina Vežu i zadržavaju vlagu u koži, čineći je punijom, glatkijom i hidriranom; različiti oblici omogućavaju da vlaga dopire do dubljih slojeva. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Pine Calming Cica Cream kombinuje 42 % Pine Cica Activ-kompleksa, hijaluronsku kiselinu i c apryloyl salicilnu kiselinu (LHA) kako bi umirila iritacije, hidratizovala i blago izgladila površinu kože. Namenjena je koži koja je sklona crvenilu, osetljivosti i neravnomernoj teksturi.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Round-Lab-Pine-Calming-Cica-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
