INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (484, 114, 'Medicube Zero Pore SA Clear Capsule Cleansing Foam', 'medicube-zero-pore-sa-clear-capsule-cleansing-foam', 'Ključne prednosti: Dubinsko čišćenje pora: salicilna kiselina prodire u pore i uklanja višak masnoće. Blaga eksfolijacija: mikro-kapsule nežno uklanjaju mrtve ćelije i poboljšavaju teksturu kože. Ujednačen ten: niacinamid smanjuje crvenilo, fleke i jača barijeru kože. Kome je namenjen? Preporučuje se osobama sa masnom i kombinovanom kožom, proširenim porama i sklonošću ka aknama. Pogodan je i za kožu sa neravnomernom teksturom kojoj je potrebna kontrola sebuma. Zašto volimo Medicube Zero Pore SA Clear Capsule Cleansing Foam? Ovaj čistač formira bogatu penu koja temeljno uklanja šminku, sebum i zagađivače iz pora. Salicilna kiselina deluje dubinski, čisteći pore i sprečavajući nastanak akni, dok kapsule za mikro-piling pružaju dodatnu eksfolijaciju bez iritacije. Niacinamid doprinosi ujednačenju tena i jačanju barijere, pa koža nakon pranja ne deluje nadraženo. Formula je osmišljena da kontroliše višak sebuma, ali bez osećaja zatezanja ili suvoće. Redovnim korišćenjem smanjuje se vidljivost pora, koža postaje glađa i čistija, sa svežim i mat izgledom. Aktivni sastojci Salicilna kiselina (BHA) Dubinski čisti pore i uklanja višak sebuma. Pomaže u prevenciji akni i smanjuje upale. Mikro-kapsule Sadrže blage eksfolijante koji uklanjaju mrtve ćelije i nečistoće. Poboljšavaju glatkoću i osvežavaju ten. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore SA Clear Capsule Cleansing Foam kombinuje salicilnu kiselinu, AHA i PHA kiseline kao i kapsule za mikro-piling kako bi uklonio višak sebuma, mrtve ćelije i nečistoće iz pora. Namenjen je masnoj i kombinovanoj koži sklonoj proširenim porama i nepravilnostima.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-Zero-Pore-SA-Clear-Capsule-Cleansing-Foam-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
