INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (485, 114, 'Medicube Red Acne Body 2.0 Wash', 'medicube-red-acne-body-2-0-wash', 'Ključne prednosti: Kontrola akni: salicilna kiselina, PHA & AHA kompleksi sprečavaju začepljenje pora i pojavu novih nepravilnosti. Obnavljanje kože: eksfolijacija pomaže u uklanjanju mrtvih ćelija i poboljšava teksturu kože. Umirujuće dejstvo: biljni ekstrakti smanjuju crvenilo i iritacije, ostavljajući kožu čistom i svežom. Kome je namenjen? Preporučuje se osobama sa masnom i problematičnom kožom tela, naročito onima koje se bore sa aknama na leđima, grudima i ramenima. Pogodan je i za kožu sklonu začepljenim porama i neravnomernoj teksturi. Zašto volimo Medicube Red Acne Body 2.0 Wash? Formulisan posebno za kožu tela sklonu aknama, ovaj gel kombinuje AHA i BHA kiseline koje deluju u sinergiji – površinski uklanjaju mrtve ćelije i dubinski pročišćavaju pore. Salicilna kiselina smanjuje upale i pomaže u lečenju postojećih akni, dok redovna upotreba sprečava njihovo ponovno pojavljivanje. Biljni ekstrakti poput čajevca i centelle asiatice umiruju nadraženu kožu i doprinose njenoj ravnoteži. Tekstura gela stvara blagu penu koja efikasno uklanja višak sebuma i nečistoće bez isušivanja. Rezultat je čistija, glađa i zdravija koža leđa, ramena i drugih problematičnih zona. Aktivni sastojci Salicilna kiselina (BHA) Prodire duboko u pore i uklanja višak sebuma i mrtve ćelije. Smanjuje upale i rizik od novih akni. AHA kompleksi Površinski eksfolijanti koji uklanjaju mrtve ćelije i poboljšavaju glatkoću kože. Doprinose ujednačenijem tenu i teksturi. Ekstrakt čajevca Prirodni antiseptik koji umiruje kožu i pomaže u smanjenju crvenila. Deluje antibakterijski i doprinosi čistijoj koži. Centella Asiatica Umiruje nadraženu kožu i podstiče regeneraciju. Smanjuje iritacije i crvenilo. Niacinamid Ujednačava ton i jača barijeru kože. Pomaže u smanjenju post-akni fleka i poboljšava otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube Red Acne Body 2.0 Wash sadrži salicilnu kiselinu, AHA i BHA komplekse, kao i biljne ekstrakte koji efikasno uklanjaju mrtve ćelije, pročišćavaju pore i smanjuju pojavu akni na telu. Namenjen je osobama sa problematičnom kožom leđa, ramena i grudi.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-Red-Acne-Body-2.0-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
