INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (486, 114, 'Medicube PDRN Pink Caffeine Night Wrapping Mask', 'medicube-pdrn-pink-caffeine-overnight-wrapping-mask', 'Ključne prednosti: Regeneracija i učvršćivanje: PDRN stimuliše obnavljanje ćelija i jača kožnu barijeru. Smanjuje otoke i umor: kofein podstiče mikrocirkulaciju i osvežava ten. Dubinska hidratacija: hijaluronska kiselina vezuje vlagu i vraća punoću koži. Kome je namenjena? Preporučuje se za umornu, sivu, dehidriranu i kožu sklonu gubitku elastičnosti. Idealna je i za zrelu kožu kojoj je potrebna dodatna regeneracija. Zašto volimo Medicube PDRN Pink Caffeine Overnight Wrapping Mask? Ova noćna maska koristi vreme dok spavaš da pruži koži intenzivnu obnovu i energiju. PDRN pomaže u regeneraciji i jačanju barijere, čineći kožu otpornijom i elastičnijom. Kofein deluje stimulativno – poboljšava mikrocirkulaciju, smanjuje natečenost i osvežava ten, naročito kod umorne kože. Hijaluronska kiselina u kombinaciji sa hidratantnim kompleksom osigurava da koža ostane hidrirana i glatka do jutra. Tekstura maske formira zaštitni sloj koji sprečava gubitak vlage tokom noći i omogućava optimalno delovanje aktivnih sastojaka. Ujutru koža izgleda odmorno, osveženo i zategnuto. Aktivni sastojci PDRN (Polideoksiribonukleotid) Obnavlja i jača kožnu barijeru, stimuliše regeneraciju ćelija i povećava elastičnost. Pomaže u smanjenju vidljivih znakova starenja. Kofein Podstiče cirkulaciju i smanjuje natečenost. Daje osvežen izgled i ublažava umor kože. Hijaluronska kiselina Vezuje vlagu u koži i obezbeđuje višeslojnu hidrataciju. Ostavlja kožu punijom i mekšom. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Caffeine Overnight Wrapping Mask kombinuje regenerativni PDRN, kofein i hijaluronsku kiselinu kako bi revitalizovala i hidrirala kožu preko noći. Namenjena je umornoj, dehidriranoj i koži sa znakovima gubitka tonusa.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-PDRN-Pink-Caffeine-Overnight-Wrapping-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
