INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (487, 114, 'Medicube PDRN Pink Niacinamide Whip Cleanser', 'medicube-pdrn-pink-niacinamide-whip-cleanser', 'Ključne prednosti: Temeljno čišćenje: bogata pena uklanja sebum, šminku i nečistoće bez isušivanja. Regeneracija i obnova: PDRN pomaže u jačanju barijere i obnovi kože. Posvetljivanje tena: niacinamid smanjuje diskoloracije i ujednačava ten. Kome je namenjena? Pogodan je za sve tipove kože, a posebno za normalnu, kombinovanu i kožu sa neujednačenim tonom. Preporučuje se i kod kože sklone dehidrataciji koja traži čistač koji ne isušuje. Zašto volimo Medicube PDRN Pink Niacinamide Whip Cleanser? Pink whip cleanser ima bogatu, kremastu penu koja efikasno uklanja nečistoće i višak masnoće, a istovremeno ostaje blaga prema koži. PDRN deluje regenerativno i podržava obnovu kože, čineći je otpornijom i elastičnijom nakon svakog pranja. Niacinamid posvetljuje i ujednačava ton, smanjujući sitne nepravilnosti i tamne fleke. Hijaluronska kiselina i pantenol dodaju hidrataciju i sprečavaju osećaj zatezanja. Zahvaljujući nežnoj formuli, koža nakon čišćenja deluje čisto, osveženo i hidrirano, bez narušavanja prirodne barijere. Redovnom upotrebom doprinosi zdravijem i ujednačenijem tenu. Aktivni sastojci PDRN (Polideoksiribonukleotid) Podstiče regeneraciju ćelija i jačanje barijere kože. Održava kožu otpornom i elastičnom. Niacinamid Posvetljuje kožu, smanjuje tamne fleke i crvenilo. Jača barijeru i ujednačava ten. Hijaluronska kiselina Pruža intenzivnu hidrataciju i sprečava isušivanje kože. Čini kožu mekom i glatkom. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Niacinamide Whip Cleanser kombinuje regenerativni PDRN, niacinamid i hidratantne komplekse kako bi očistio pore, posvetlio ten i umirio kožu. Namenjen je svakodnevnom čišćenju svih tipova kože, uključujući i osetljivu.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-PDRN-Pink-Niacinamide-Whip-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
