INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (488, 114, 'Medicube PDRN Pink Niacinamide Milky Toner', 'medicube-pdrn-pink-niacinamide-milky-toner', 'Ključne prednosti: Obnova i jačanje: PDRN stimuliše regeneraciju ćelija i jača barijeru kože. Posvetljivanje tena: niacinamid smanjuje diskoloracije i ujednačava ton. Dubinska hidratacija: hijaluronska kiselina i mlečna tekstura ostavljaju kožu mekom i punom. Kome je namenjena? Preporučuje se za normalnu, suvu i kombinovanu kožu kojoj nedostaje hidratacija i ujednačen ton. Posebno je koristan kod kože sklone hiperpigmentacijama i prvih znakova starenja. Zašto volimo Medicube PDRN Pink Niacinamide Milky Toner? Pink Niacinamide Milky tonik ima kremastu, mlečnu teksturu koja kombinuje osveženje tonika i hranljivost esencije. PDRN pomaže u obnavljanju ćelija i jačanju kože, čineći je otpornijom i elastičnijom. Niacinamid u visokoj koncentraciji posvetljuje kožu, smanjuje neujednačen ton i doprinosi zdravom sjaju. Hijaluronska kiselina obezbeđuje vlagu i vraća punoću, dok biljni ekstrakti umiruju i neguju osetljivu kožu. Formulacija je nežna, brzo se upija i ne ostavlja lepljiv trag, pa je pogodna za svakodnevnu upotrebu u svim rutinama. Redovnim korišćenjem koža postaje hidrirana, ujednačena i vidno osvežena. Aktivni sastojci PDRN (Polideoksiribonukleotid) Obnavlja kožu na ćelijskom nivou, jača barijeru i poboljšava elastičnost. Pomaže u regeneraciji i smanjenju oštećenja. Niacinamid Posvetljuje kožu, ujednačava ten i smanjuje tamne fleke. Jača barijeru kože i poboljšava elastičnost. Hijaluronska kiselina Vezuje vlagu i obezbeđuje dugotrajnu hidrataciju. Ostavlja kožu punijom, mekšom i glađom. Ekstrakt ruže Doprinosi smirenju kože, hidrira i daje blistav izgled. Pantenol Umiruje iritacije i obnavlja kožnu barijeru. Doprinosi osećaju komfora i hidratacije. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Niacinamide Milky Toner kombinuje regenerativni PDRN, niacinamid i hijaluronsku kiselinu kako bi obezbedio vlagu, ujednačio ton i ojačao barijeru kože. Namenjen je koži koja je dehidrirana, umorna ili sklona diskoloracijama.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-PDRN-Pink-Niacinamide-Milky-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
