INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (489, 114, 'Medicube PDRN Hydrating Gel Cleanser', 'medicube-pdrn-hydrating-gel-cleanser', 'Ključne prednosti: Nežno čišćenje: uklanja sebum, šminku i nečistoće bez narušavanja barijere. Dubinska hidratacija: PDRN i hijaluronska kiselina obnavljaju i zadržavaju vlagu u koži. Umirivanje kože: pantenol i alantoin smanjuju crvenilo i iritacije. Kome je namenjen? Preporučuje se svim tipovima kože, a posebno suvoj, osetljivoj i dehidriranoj koži koja traži čistač koji neće narušiti njenu prirodnu barijeru. Pogodan je i za kožu sklonu iritacijama ili nakon dermatoloških tretmana. Zašto volimo Medicube PDRN Hydrating Gel Cleanser? Ovaj gel čistač je razvijen tako da istovremeno obezbedi temeljno, a blago čišćenje i intenzivnu hidrataciju. PDRN, poznat po regenerativnim svojstvima, pomaže u obnavljanju kože i jačanju njene zaštitne barijere. Hijaluronska kiselina u više formi obezbeđuje vlagu i čini da koža nakon čišćenja ostane hidrirana i meka. Pantenol i alantoin doprinose umirujućem efektu, što je posebno korisno kod kože sklone iritacijama. Tekstura gela lako se transformiše u blagu penu koja temeljno uklanja šminku, sebum i nečistoće iz pora bez osećaja zatezanja. Redovnim korišćenjem koža postaje čista, osvežena i otpornija na spoljašnje faktore. Aktivni sastojci PDRN (Polideoksiribonukleotid) Regenerativni sastojak koji stimuliše obnavljanje ćelija i jača barijeru kože. Pomaže u smanjenju oštećenja i vraća elastičnost. Hijaluronska kiselina Humektant koji vezuje vlagu i održava kožu hidriranom nakon čišćenja. Sprečava isušivanje i vraća punoću. Pantenol (Provitamin B5) Umiruje i obnavlja kožu, smanjuje crvenilo i iritacije. Podržava regeneraciju kože. Alantoin Pruža dodatni umirujući i zaštitni efekat. Održava kožu mekom i otpornom. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Hydrating Gel Cleanser kombinuje PDRN, hijaluronsku kiselinu i pantenol kako bi nežno uklonio nečistoće i šminku, a istovremeno očuvao vlagu kože. Namenjen je svim tipovima kože, posebno onoj sklonoj suvoći i iritacijama.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-PDRN-Hydrating-Gel-Cleanser-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
