INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (490, 114, 'Medicube Hypochlorous Acid Daily Facial Spray', 'medicube-hypochlorous-acid-daily-facial-spray', 'Ključne prednosti: Umiruje i štiti: smanjuje iritacije, crvenilo i podržava prirodne mehanizme kože. Antimikrobno delovanje: hipohlorusna kiselina pomaže u održavanju čiste kože sklonе aknama. Lagana hidratacija: formula osvežava i vlaži bez težine ili lepljivog osećaja. Kome je namenjen? Pogodan je za sve tipove kože, uključujući osetljivu i reaktivnu. Posebno se preporučuje koži sklonoj aknama, iritacijama ili crvenilu. Zašto volimo Medicube Hypochlorous Acid Daily Facial Spray? Ovaj sprej koristi moć hipohlorusne kiseline – prirodnog sastojka koji se često povezuje sa procesom samoodbrane kože – kako bi smanjio rizik od upala i pojave novih nepravilnosti. Njegovo blago antimikrobno dejstvo pomaže u održavanju čistoće kože, što je posebno korisno kod osoba sklonih aknama i iritacijama. Lagan i osvežavajući, sprej brzo umiruje crvenilo i pruža osećaj komfora, a istovremeno obezbeđuje blagu hidrataciju. Može se koristiti više puta tokom dana, čak i preko šminke, kao dodatni sloj zaštite i osveženja. Redovnim korišćenjem, koža postaje stabilnija, čistija i manje sklona upalama. Aktivni sastojci Hipohlorusna kiselina Prirodni spoj koji pomaže u borbi protiv bakterija i smanjenju iritacija. Jača odbrambenu funkciju kože i doprinosi čistijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Medicube Hypochlorous Acid Daily Facial Spray sadrži hipohlorusnu kiselinu koja pomaže u smanjenju iritacija, crvenila i nepravilnosti, dok istovremeno podržava prirodnu odbranu kože. Namenjen je svim tipovima kože, uključujući osetljivu i problematičnu.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-Hypochlorous-Acid-Daily-Facial-Spray.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
