INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (491, 114, 'Medicube Deep Lifting Age Repair Cream', 'medicube-deep-lifting-age-repair-cream', 'Ključne prednosti: Učvršćivanje kože: peptidi i kolagen jačaju strukturu kože i smanjuju opuštenost. Smanjenje bora: aktivni kompleksi zaglađuju fine linije i ublažavaju duboke bore. Dubinska hidratacija: hijaluronska kiselina i hranljivi emolijensi vraćaju vlagu i mekoću. Kome je namenjena? Preporučuje se za zrelu kožu sa borama, gubitkom tonusa i elastičnosti. Pogodna je za normalnu do suvu kožu kojoj je potrebna regeneracija i intenzivna nega. Zašto volimo Medicube Deep Lifting Age Repair Cream? Ova krema osmišljena je kao sveobuhvatan tretman za kožu koja pokazuje znake starenja – opuštenost, gubitak elastičnosti i izražene bore. Peptidni kompleks stimuliše sintezu kolagena i elastina, čime jača dermis i poboljšava čvrstinu kože. Hidrolizovani kolagen dodatno učvršćuje i vraća punoću, dok hijaluronska kiselina obezbeđuje dubinsku hidrataciju i smanjuje osećaj suvoće i zatezanja. Hranljiva ulja i antioksidansi pomažu u obnavljanju barijere kože i štite od oksidativnog stresa. Tekstura je bogata, ali se lako razmazuje i brzo upija, što je čini pogodnom i za dnevnu i za noćnu rutinu. Redovnom upotrebom koža postaje čvršća, glađa i vidno pomlađena. Aktivni sastojci Peptidi Stimulišu sintezu kolagena i elastina, pomažući koži da povrati čvrstinu i elastičnost. Smanjuju vidljivost bora i doprinose mladalačkom izgledu. Kolagen Hidrolizovani oblik kolagena učvršćuje i povećava punoću kože. Podržava strukturu dermisa i vraća glatkoću. Hijaluronska kiselina Pruža višeslojnu hidrataciju i vezuje vlagu u koži. Ublažava suvoću i vraća osećaj mekoće i punoće. Niacinamid Ujednačava ton kože, smanjuje diskoloracije i jača barijeru. Doprinosi svežem i blistavom tenu. Antioksidansi (vitamin E, biljni ekstrakti) Štite od slobodnih radikala i oksidativnog stresa. Pomažu u regeneraciji i očuvanju zdravog izgleda kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Lifting Age Repair Cream kombinuje peptide, kolagen i hijaluronsku kiselinu kako bi koži vratio čvrstinu, hidrataciju i zdrav izgled. Namenjena je zreloj koži sa izraženim borama i gubitkom tonusa.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-Deep-Lifting-Age-Repair-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
