INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (492, 114, 'Medicube Deep Vita C Glutathione Brightening Mask', 'medicube-deep-vita-c-glutathione-brightening-mask', 'Ključne prednosti: Posvetljivanje i ujednačavanje tena: vitamin C i glutation ciljano deluju na tamne fleke i siv ten. Antioksidativna zaštita: snažni antioksidansi štite od slobodnih radikala i prevremenog starenja. Intenzivna hidratacija: hijaluronska kiselina i biljni ekstrakti obezbeđuju vlagu i vraćaju koži punoću. Kome je namenjena? Preporučuje se za umornu, sivu i kožu sa hiperpigmentacijama ili neujednačenim tonom. Pogodna je za sve tipove kože, uključujući i kombinovanu i normalnu. Zašto volimo Medicube Deep Vita C Glutathione Brightening Mask? Maska je osmišljena kao „boost“ tretman za kožu kojoj nedostaje sjaj i ravnoteža. Stabilni derivat vitamina C i glutation deluju sinergijski – smanjuju vidljivost hiperpigmentacija, osvetljavaju sivilo i doprinose blistavom tenu. Niacinamid dodatno podržava ravnomeran ton i jača barijeru kože, dok hijaluronska kiselina hidrira i smanjuje osećaj zatezanja. Lagana tkanina maske odlično prianja uz lice i omogućava efikasnu apsorpciju aktivnih sastojaka. Nakon upotrebe koža deluje osveženo, glatko i mekano, sa vidljivim poboljšanjem ujednačenosti tena. Redovnim korišćenjem ten postaje svetliji, a koža otpornija na spoljašnje stresore. Aktivni sastojci Vitamin C (stabilni derivati) Deluje kao snažan antioksidans koji posvetljuje ten, smanjuje fleke i stimuliše sintezu kolagena. Pomaže koži da izgleda osveženo i mlađe. Glutation Poznat kao „master antioksidans“, štiti ćelije od oksidativnog stresa i doprinosi posvetljivanju tena. U sinergiji sa vitaminom C pruža snažan efekat protiv sivila i neujednačenosti. Niacinamid Podržava jačanje barijere kože, posvetljuje i ujednačava ton. Smanjuje crvenilo i poboljšava teksturu. Hijaluronska kiselina Dubinski hidrira i vraća koži punoću. Sprečava dehidrataciju i održava elastičnost. Biljni ekstrakti (aloe vera, kamilica, zeleni čaj) Umiruju i neguju kožu. Daju dodatnu antioksidativnu zaštitu i podržavaju zdrav izgled. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Vita C Glutathione Brightening Mask kombinuje stabilni vitamin C, glutation i niacinamid kako bi posvetlila hiperpigmentacije, ujednačila ten i osvežila izgled kože. Namenjena je koži kojoj nedostaje sjaj, punoća i ravnomeran ton.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Medicube-Deep-Vita-C-Glutathione-Brightening-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
