INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (493, 92, 'K-Secret Boosting Ball Collagen 100%', 'ksecret-boosting-ball-collagen-100', 'Ključne prednosti: Intenzivna regeneracija: čisti kolagen podstiče obnovu i jačanje strukture kože. Elastičnost i punoća: vraća koži čvrstinu i smanjuje vidljivost finih linija. Dubinska hidratacija: poboljšava zadržavanje vlage i vraća mekoću i sjaj. Kome je namenjen? Preporučuje se za zrelu, suvu i kožu sa znacima starenja, kao i za sve tipove kože kojima nedostaje elastičnost i hidratacija. Idealno za osobe koje žele ciljanu i intenzivnu anti-age negu. Zašto volimo KSECRET Boosting Ball Collagen 100%? Kolagen u obliku kuglice predstavlja koncentrisani tretman koji se koristi u kombinaciji sa hidratantnim esencijama ili serumima. Hidrolizovani kolagen lako prodire u kožu, popunjavajući mikropukotine i pomažući u jačanju vezivnog tkiva. Rezultat je elastičnija, gušća i otpornija koža sa manje vidljivim borama i finim linijama. Tekstura kože postaje glađa, a ten ujednačeniji i svežiji. Posebnost ovog proizvoda je što se koristi kao personalizovana kura – kuglica se rastvara i dodaje u rutinu, čime koža dobija visoko koncentrovanu dozu kolagena. Redovnom upotrebom vraća se prirodna punoća i mladalački izgled kože. Aktivni sastojci Hidrolizovani kolagen (100%) Čista i visoko koncentrovana forma kolagena koja se lako apsorbuje. Jača strukturu kože, podstiče elastičnost i smanjuje vidljivost bora. Poboljšava zadržavanje vlage i vraća koži punoću i glatkoću. Dodaj u listu želja Dodaj u listu želja', 'KSECRET Boosting Ball Collagen 100% sadrži čisti, hidrolizovani kolagen u visokoj koncentraciji koji se aktivira u kontaktu sa esencijom ili serumom. Namenjen je koži kojoj nedostaje elastičnost, punoća i glatkoća.', 'https://beauty-health.rs/wp-content/uploads/2025/09/KSECRET-Boosting-Ball-Collagen-100-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
