INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (494, 93, 'Kahi Wrinkle Bounce Multi Balm', 'kahi-wrinkle-bounce-multi-balm', 'Ključne prednosti: Smanjuje bore i fine linije: PDRN i kolagen stimulišu obnovu kože i poboljšavaju elastičnost. Hidratacija tokom dana: ulja i emolijensi stvaraju zaštitni sloj koji sprečava gubitak vlage. Praktičnost: balzam u stiku omogućava brzu i laku primenu, čak i preko šminke. Kome je namenjen? Preporučuje se osobama sa suvom kožom, prvim znacima starenja ili kožom sklonom gubitku elastičnosti. Idealan je za one koji žele praktičan proizvod koji spaja anti-age i hidratantni efekat. Zašto volimo Kahi Wrinkle Bounce Multi Balm? Ovaj multifunkcionalni balzam je zamišljen kao „instant osveženje“ za kožu u pokretu. Lososov kolagen i PDRN deluju sinergijski – stimulišu sintezu kolagena, ubrzavaju regeneraciju ćelija i smanjuju vidljivost bora. Fermentisana ulja (jojoba, argan, suncokret) i shea puter hrane i štite kožu, dok niacinamid doprinosi ujednačenijem tenu. Tekstura je lagana, nelepljiva i brzo se topi u dodiru sa kožom, pa se može nanositi i preko šminke bez razmazivanja. Osim lica i vrata, može se koristiti i na usnama, oko očiju ili na suvim delovima kože. Redovnim korišćenjem, koža postaje hidriranija, glađa i vidno osvežena. Aktivni sastojci PDRN (Polideoksiribonukleotid) Podstiče regeneraciju i obnavljanje ćelija, smanjuje mikrooštećenja i jača kožnu barijeru. Doprinosi elastičnosti i smanjenju bora. Lososov kolagen Pomaže u zadržavanju vlage i jačanju strukture kože. Vraća elastičnost i smanjuje vidljivost finih linija. Fermentisana biljna ulja (jojoba, argan, suncokret) Hranljiva i bogata antioksidansima, pružaju dugotrajnu hidrataciju i zaštitu. Omekšavaju kožu i smanjuju osećaj suvoće. Niacinamid Posvetljuje i ujednačava ten. Deluje protiv crvenila i doprinosi zdravijem izgledu kože. Shea puter Dubinski hrani, umiruje i čuva vlažnost kože. Ostavlja je glatkom i mekom. Dodaj u listu želja Dodaj u listu želja', 'Kahi Wrinkle Bounce Multi Balm kombinuje lososov kolagen, PDRN i fermentisana ulja kako bi poboljšao elastičnost, smanjio fine linije i obezbedio dugotrajnu hidrataciju. Pogodan je za svakodnevnu upotrebu na licu, vratu i suvim zonama, bilo kada i bilo gde.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Kahi-Wrinkle-Bounce-Multi-Balm-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
