INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (496, 92, 'K-Secret Advanced Regenerating Eye Gel Patches Retinol', 'ksecret-advanced-regenerating-eye-gel-patches-retinol', 'Ključne prednosti: Zaglađivanje bora: retinol i peptidi stimulišu proizvodnju kolagena i vraćaju elastičnost. Hidratacija i osveženje: hijaluronska kiselina obnavlja vlagu i smanjuje osećaj suvoće. Posvetljivanje podočnjaka: niacinamid ujednačava ten i ublažava tamne kolutove. Kome su namenjeni? Preporučuju se osobama koje žele da smanje bore, posvetle tamne kolutove i osveže umorno područje oko očiju. Pogodni su za sve tipove kože, posebno kod prvih znakova starenja. Zašto volimo KSECRET Advanced Regenerating Eye Gel Patches Retinol? Hidrogel jastučići pružaju ciljanu i intenzivnu negu tankoj koži oko očiju. Retinol u formuli stimuliše obnovu ćelija i proizvodnju kolagena, čime ublažava bore i fine linije. Peptidi jačaju strukturu kože i pomažu da područje oko očiju izgleda čvršće i elastičnije. Hijaluronska kiselina zadržava vlagu i vraća koži mekoću, dok niacinamid posvetljuje podočnjake i ujednačava ton. Zahvaljujući hidrogel teksturi, jastučići prijatno hlade i trenutno smanjuju otečenost. Redovnom upotrebom pogled postaje odmorniji, koža zaglađenija i otpornija na znakove starenja. Aktivni sastojci Retinol Potiče regeneraciju ćelija i sintezu kolagena. Smanjuje bore i vraća čvrstinu koži. Peptidi Jačaju strukturu kože i povećavaju elastičnost. U kombinaciji sa retinolom pružaju izražen anti-age efekat. Hijaluronska kiselina Vezuje vlagu i održava hidrataciju. Ublažava suvoću i vraća punoću tankoj koži oko očiju. Niacinamid Ujednačava ton, posvetljuje podočnjake i jača barijeru kože. Pruža osvežen izgled. Biljni ekstrakti (aloe vera, zeleni čaj, kamilica) Umiruju iritacije i deluju antioksidativno. Smanjuju crvenilo i otečenost. Shea puter Dubinski hrani, umiruje i čuva vlažnost kože. Ostavlja je glatkom i mekom. Dodaj u listu želja Dodaj u listu želja', 'KSECRET Advanced Regenerating Eye Gel Patches Retinol kombinuju retinol, peptide i niacinamid kako bi smanjili fine linije, tamne kolutove i umor oko očiju. Hidrogel jastučići pružaju trenutno rashlađujući i umirujući efekat, uz intenzivnu hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2025/09/KSECRET-Advanced-Regenerating-Eye-Gel-Patches-Retinol.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
