INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (497, 84, 'Isntree Gim PDRN Deep Sleep Mask', 'isntree-gim-pdrn-deep-sleep-mask', 'Ključne prednosti: Regeneracija tokom sna: PDRN podstiče obnovu ćelija i jača kožnu barijeru. Dubinska hidratacija: hijaluronska kiselina i morski ekstrakti zadržavaju vlagu u koži. Osvežen i odmoran izgled: ujutru koža izgleda punije, glatkije i elastičnije. Kome je namenjena? Preporučuje se za suvu, dehidriranu, umornu i oštećenu kožu kojoj je potrebna regeneracija i dodatna nega. Pogodna je i za zrelu kožu sa prvim znacima starenja. Zašto volimo Isntree Gim PDRN Deep Sleep Mask? PDRN, poznat po snažnom regenerativnom delovanju, pomaže u reparaciji ćelija i jačanju barijere kože. Ekstrakti morskih algi i gim (nori alge) bogati mineralima i antioksidansima hrane kožu i štite je od oksidativnog stresa. Hijaluronska kiselina u više oblika dubinski hidrira i održava elastičnost. Tekstura maske je bogata, ali se lako upija i ne ostavlja lepljiv trag, što je čini pogodnom i za svakodnevnu noćnu rutinu. Ujutru koža izgleda odmorno, hidrirano i zdravije. Aktivni sastojci PDRN (Polideoksiribonukleotid) Bioregulator koji stimuliše obnovu ćelija i jača kožnu barijeru. Ubrzava regeneraciju, popravlja mikrooštećenja i daje koži otpornost i elastičnost. Ekstrakt gim algi (nori) Bogate vitaminima, mineralima i antioksidansima. Štite kožu od oksidativnog stresa i jačaju njenu prirodnu otpornost. Pomažu u hidrataciji i vraćaju koži vitalnost. Hijaluronska kiselina Humektant koji veže vlagu u koži i održava je hidriranom tokom cele noći. Smanjuje osećaj suvoće i vraća koži punoću. Biljni ekstrakti (centella asiatica, zeleni čaj, kamilica) Umiruju, smanjuju crvenilo i iritacije, pružajući dodatnu zaštitu osetljivoj koži. Dodaj u listu želja Dodaj u listu želja', 'Isntree Gim PDRN Deep Sleep Mask kombinuje PDRN (polideoksiribonukleotid), hijaluronsku kiselinu i ekstrakte morskih algi kako bi tokom noći obnovila kožnu barijeru i vratila elastičnost. Namenjena je umornoj, dehidriranoj i oslabljenoj koži kojoj je potrebna dubinska obnova.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Isntree-Gim-PDRN-Deep-Sleep-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
