INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (498, 90, 'Jumiso Niacinamide 20 Serum', 'jumiso-niacinamide-20-serum', 'Ključne prednosti: Posvetljivanje tena: niacinamid i vitamin C smanjuju hiperpigmentacije i ujednačavaju ten. Kontrola sebuma: cink reguliše lučenje masnoće i pomaže kod problematične kože. Anti-age efekat: jača barijeru kože, smanjuje fine linije i poboljšava elastičnost. Kome je namenjen? Preporučuje se osobama sa hiperpigmentacijama, neujednačenim tonom i masnom ili kombinovanom kožom. Pogodan je i za kožu sa proširenim porama i tragovima akni. Zašto volimo JUMISO Niacinamide 20 Serum? Serum je formulisan za ciljanu negu kože sa izraženim nepravilnostima, hiperpigmentacijama i masnim sjajem. Visoka koncentracija niacinamida (20%) deluje višeslojno – posvetljuje ten, smanjuje pojavu tamnih mrlja i ublažava crvenilo, dok u isto vreme jača barijeru kože. U kombinaciji sa cinkom, serum pomaže u regulaciji lučenja sebuma i smanjuje rizik od novih nepravilnosti. Derivati vitamina C doprinose dodatnom posvetljivanju i antioksidativnoj zaštiti, štiteći kožu od oksidativnog stresa i starenja. Tekstura je lagana, brzo se upija i ne ostavlja lepljiv trag, pa je pogodna za svakodnevnu upotrebu. Redovnim korišćenjem koža postaje čistija, svetlija i ujednačenija, sa manje vidljivih pora i nepravilnosti. Aktivni sastojci Niacinamid (20%) Vitamin B3 u visokoj koncentraciji koji deluje na posvetljivanje tena, smanjenje crvenila i kontrolu sebuma. Jača kožnu barijeru i smanjuje pojavu bora i finih linija. Cink PCA Reguliše lučenje sebuma i umiruje upale. Koristan za kožu sklonu aknama i masnom sjaju. Vitamin C (Derivati) Pruža antioksidativnu zaštitu, posvetljuje ten i smanjuje pojavu tamnih fleka. Doprinosi zdravijem i svežijem izgledu kože. Arbutin Poznat po svom učinku na smanjenje hiperpigmentacija. Pomaže u ujednačavanju tena i prevenciji novih tamnih mrlja. Dodaj u listu želja Dodaj u listu želja', 'JUMISO Niacinamide 20 Serum kombinuje visoku koncentraciju niacinamida sa cinkom i vitaminom C kako bi posvetlio hiperpigmentacije, regulisao sebum i poboljšao elastičnost kože. Namenjen je koži sa tamnim flekama, neujednačenim tonom i proširenim porama.', 'https://beauty-health.rs/wp-content/uploads/2025/09/JUMISO-Niacinamide-20-Serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
