INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (499, 85, 'iUNIK Argan Nourishing Hair Oil', 'iunik-argan-nourishing-hair-oil', 'Ključne prednosti: Dubinska ishrana: prirodna ulja hrane i jačaju kosu od korena do krajeva. Sjaj i mekoća: vraća glatkoću i prirodan sjaj bez lepljivosti i otežavanja. Zaštita od oštećenja: stvara zaštitni sloj koji štiti kosu od toplote i spoljašnjih faktora. Kome je namenjeno? Preporučuje se za suvu, oštećenu, farbanu ili kosu sklonu lomljenju. Pogodan je za sve tipove kose kojima je potrebna dodatna hidratacija i zaštita. Zašto volimo iUNIK Argan Nourishing Hair Oil? Ovo ulje pruža bogatu, ali laganu negu kosi kojoj nedostaje vitalnost. Arganovo ulje je poznato po visokom sadržaju vitamina E i masnih kiselina, koje hrane vlas iznutra i pomažu u smanjenju ispucalih krajeva. Ulje jojobe i suncokreta dodatno obezbeđuju hidrataciju i zaglađuju kutikulu, čineći kosu podatnijom i lakšom za oblikovanje. Tekstura je lagana i nelepljiva, pa ne opterećuje dlaku i pogodna je i za tanku kosu. Može se koristiti pre feniranja kao zaštita od toplote ili kao završni korak za dodatni sjaj. Redovnom upotrebom kosa postaje mekša, sjajnija i zdravijeg izgleda. Aktivni sastojci Arganovo ulje Bogato vitaminom E i esencijalnim masnim kiselinama, dubinski hrani kosu. Jača vlas, smanjuje ispucale krajeve i vraća elastičnost. Ulje jojobe Balansira vlažnost kose i vlasišta, čini kosu glatkom i mekom. Sprečava isušivanje i doprinosi zdravijem izgledu. Ulje suncokretovog semena Lagano ulje koje pruža hidrataciju i obnavlja kutikulu. Pomaže u zaštiti od spoljašnjih oštećenja i dodaje sjaj. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Argan Nourishing Hair Oil kombinuje arganovo ulje, ulje jojobe i ekstrakt semena suncokreta kako bi kosi pružio hranljive materije i sjaj bez otežavanja. Namenjeno je suvoj, oštećenoj i beživotnoj kosi kojoj nedostaje elastičnost i mekoća.', 'https://beauty-health.rs/wp-content/uploads/2025/09/iUNIK-Argan-Nourishing-Hair-Oil-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
