INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (500, 84, 'Isntree Ultra-Low Molecular Hyaluronic Acid Zinc Aqua Cream', 'isntree-ultra-low-molecular-hyaluronic-acid-zinc-aqua-cream', 'Ključne prednosti: Dubinska hidratacija: ultra-niske molekule hijaluronske kiseline obezbeđuju vlagu i punoću kože. Balans sebuma: cink pomaže u regulisanju masnoće i održavanju čistih pora. Umirenje i jačanje barijere: niacinamid i biljni ekstrakti smiruju iritacije i podržavaju otpornost kože. Kome je namenjena? Preporučuje se za kombinovanu, masnu i kožu sklonu aknama, kao i za sve koji žele laganu hidrataciju bez opterećivanja kože. Pogodna je i za osetljivu kožu zahvaljujući umirujućoj formuli. Zašto volimo IsNtree Ultra-Low Molecular Hyaluronic Acid Zinc Aqua Cream? Formulisana da pruži koži hidrataciju i balans, Aqua Cream kombinuje više tipova hijaluronske kiseline različite molekulske mase kako bi vlažnost dospela i u površinske i u dublje slojeve kože. Rezultat je mekša, punija i elastičnija koža koja ostaje hidrirana tokom celog dana. Cink i biljni kompleksi pomažu u regulaciji sebuma, smanjuju sjaj i umiruju kožu sklonu nepravilnostima. Niacinamid dodatno ujednačava ton i jača barijeru kože, dok pantenol i alantoin obnavljaju i pružaju osećaj komfora. Tekstura je lagana i brzo se upija, ne ostavljajući mastan trag, što je čini pogodnom za svakodnevnu upotrebu, ujutru i uveče. Redovnom upotrebom koža postaje uravnotežena, hidrirana i vidno zdravija. Aktivni sastojci Ultra-Low Molecular Hyaluronic Acid Hijaluronske kiseline različite molekulske mase prodiru do različitih slojeva kože. Sitnije čestice hidriraju dublje slojeve, dok veće formiraju zaštitni film na površini i smanjuju gubitak vlage. Cink (Zinc PCA) Reguliše lučenje sebuma i doprinosi smanjenju upala. Pomaže kod kože sklone nepravilnostima i daje mat izgled T-zoni. Niacinamid Ujednačava ten, posvetljuje i jača barijeru kože. Deluje umirujuće i doprinosi zdravijem i čistijem tenu. Pantenol i alantoin Umiruju iritacije i pomažu regeneraciju. Održavaju kožu mekanom, otpornom i smanjuju osećaj zatezanja. Biljni ekstrakti (centella asiatica, hamamelis, kurkuma) Doprinose umirenju i antioksidativnoj zaštiti. Podržavaju zdravlje kože i pomažu u smanjenju crvenila i nepravilnosti. Dodaj u listu želja Dodaj u listu želja', 'IsNtree Ultra-Low Molecular Hyaluronic Acid Zinc Aqua Cream kombinuje kompleks hijaluronskih kiselina i cink kako bi koži pružila vlagu u dubljim slojevima, a pritom regulisala lučenje sebuma i smanjila vidljivost pora. Namenjena je masnoj, kombinovanoj i problematičnoj koži koja traži hidrataciju bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/09/IsNtree-Ultra-Low-Molecular-Hyaluronic-Acid-Zinc-Aqua-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
