INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (501, 84, 'Isntree Onion Newpair Spot Patch Skin Fit', 'isntree-onion-newpair-spot-patch-skin-fit', 'Ključne prednosti: Efikasno upijanje: hidro­koloidni sloj izvlači vlagu i nečistoće iz bubuljice, ubrzavajući proces zarastanja. Umirivanje: niacinamid i ekstrakt luka smanjuju iritacije i crvenilo. Diskretan izgled: ultra tanak i providan flaster prianja uz kožu, praktican i skriven tokom nošenja i šminke. Kome su namenjeni? Idealan je za osobe koje povremeno imaju bubuljice i žele brzo rešenje bez agresivnih tretmana. Takođe je dobar izbor za osetljivu i reaktivnu kožu, jer sastav ne sadrži snažne iritanse i flaster ne opterećuje kožu. Zašto volimo Isntree Onion Newpair Spot Patch Skin Fit? Kada bubuljica izviri, ovaj flaster pruža štit – sprečava ulazak bakterija i dodirivanje, što često pogoršava stanje. Hidro­koloidni materijal brzo upija gnoj i višak tečnosti, čime smanjuje otok i bol. Ekstrakt Muan luka i niacinamid igraju ulogu umirivanja kože – smiruju crvenilo i iritacije, pa lice ne izgleda nadraženo. Tanak dizajn omogućava nošenje i danju, ispod šminke, bez da se vidi ili oseća neprijatno. Kada flaster postane beo, znači da je upio sadržaj – tada ga pažljivo ukloniti i zameniti novim po potrebi. Redovnom upotrebom bubuljice se povlače brže, crvenilo postaje blaže, a ožiljci i tamne mrlje nakon upale manje vidljivi. Aktivni sastojci Ekstrakt Muan luka (Onion Bulb Extract) Prirodni sastojak poznat po anti-inflamatornim i antibakterijskim svojstvima. Pomaže kod smanjenja otoka i crvenila, ublažava bol bubuljice i ubrzava smirivanje kože. Niacinamid Vitamin koji ujednačava ton kože, smanjuje hiper­pigmentaciju i iritacije. Doprinosi jačanju barijere kože i smanjenju upalnih markera. Hidro­koloidna pločica Materijal koji upija gnoj i višak tečnosti, štiti bubuljicu od spoljašnjih uticaja. Obezbeđuje vlažno okruženje koje podržava prirodni proces zaceljivanja. Dodaj u listu želja Dodaj u listu želja', 'Ovi flasteri sadrže ekstrakt Muan luka i niacinamid koji umiruju upalne procese i smanjuju crvenilo, dok hidro­koloidni sloj apsorbuje gnoj i štiti od spoljašnjih iritacija. Tanak i transparentan dizajn omogućava da se flaster nosi danju ili noću, neprimetan i udoban za kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Isntree-Onion-Newpair-Spot-Patch-Skin-Fit.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
