INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (502, 84, 'Isntree Chestnut BHA 2% Clear Liquid', 'isntree-chestnut-bha-2-clear-liquid', 'Ključne prednosti: Pročišćava pore: salicilna kiselina uklanja višak sebuma i sprečava pojavu mitisera. Poboljšava teksturu: eksfolijacijom smanjuje hrapavost i čini kožu glatkom. Reguliše masnoću: ekstrakt kestena balansira sebum i podržava zdrav izgled kože. Kome je namenjen? Preporučuje se za masnu, kombinovanu i kožu sklonu začepljenim porama i aknama. Nije namenjen veoma osetljivoj koži zbog prisustva kiseline. Zašto volimo Isntree Chestnut BHA 2% Clear Liquid? BHA (salicilna kiselina) prodire duboko u pore i rastvara višak sebuma, pomažući u prevenciji mitisera i akni. Ekstrakt kore kestena ima adstringentno i antioksidativno dejstvo – učvršćuje pore, smanjuje njihovu vidljivost i poboljšava opšti tonus kože. Tekstura je lagana, brzo se upija i ne ostavlja lepljiv trag, pa se lako uklapa u rutinu. Redovnom upotrebom koža postaje čistija, glađa i ujednačenija, dok pore izgledaju manje izražene. Aktivni sastojci Salicilna kiselina (2%) Lipofilna kiselina koja prodire u pore i rastvara višak sebuma. Eksfolijacijom uklanja mrtve ćelije i pomaže u smanjenju mitisera i upalnih procesa. Poboljšava teksturu i čini kožu čistijom i glađom. Ekstrakt kore kestena Prirodni sastojak bogat taninima i antioksidansima. Doprinosi sužavanju pora i jačanju barijere kože. Reguliše masnoću i umiruje upalne procese. Hijaluronska kiselina Pruža hidrataciju i smanjuje rizik od isušivanja kože tokom upotrebe BHA kiseline. Održava elastičnost i mekoću. Dodaj u listu želja Dodaj u listu želja', 'Isntree Chestnut BHA 2% Clear Liquid sadrži 2% salicilne kiseline i ekstrakt kore kestena za uklanjanje mrtvih ćelija, regulisanje sebuma i smanjenje začepljenih pora. Redovnim korišćenjem pomaže koži da postane čistija, ujednačenija i glatkija.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Isntree-Chestnut-BHA-2-Clear-Liquid.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
