INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (504, 84, 'Isntree Aloe Soothing Gel Fresh Type', 'isntree-aloe-soothing-gel-fresh-type', 'Ključne prednosti: Umiruje i hladi: aloe vera smanjuje crvenilo i iritacije nakon izlaganja suncu ili spoljnim stresorima. Lagana hidratacija: obezbeđuje vlagu bez masnog ili teškog osećaja. Višenamenska upotreba: pogodan za lice i telo, kao SOS nega ili svakodnevna hidratacija. Kome je namenjeni? Pogodan je za sve tipove kože, naročito za osetljivu, dehidriranu i kožu sklonu iritacijama. Preporučuje se kao SOS tretman posle sunčanja, brijanja ili u periodima pojačanog isušivanja. Zašto volimo Isntree Aloe Soothing Gel Fresh Type? Blagotvorno deluje na crvenilo i iritacije, bilo da su nastale usled sunca, brijanja, depilacije ili spoljašnjih faktora. Njegova lagana, vodenasta tekstura brzo se upija i ne ostavlja lepljiv trag, što ga čini pogodnim i za lice i za telo. Uz hidratantne komponente, održava vlagu u koži i smanjuje osećaj zatezanja. Redovnom upotrebom koža postaje mekša, elastičnija i otpornija. Zbog svoje svežine i čistoće formule, idealan je izbor i za osetljivu kožu. Aktivni sastojci Aloe vera (80%) Prirodni sastojak poznat po umirujućim i hidratantnim svojstvima. Smanjuje upale i crvenilo, ubrzava oporavak kože i vraća osećaj svežine. Pruža laganu, ali dugotrajnu hidrataciju. Alantoin Umirujući sastojak koji smanjuje iritacije i štiti kožu. Podstiče regeneraciju i jača prirodnu barijeru kože. Ekstrakti biljaka (krastavac, kamilica, centella asiatica – zavisi od verzije) Dodatno umiruju i hidriraju, pružajući antioksidativnu zaštitu i pomažući u obnavljanju kože. Dodaj u listu želja Dodaj u listu želja', 'Isntree Aloe Soothing Gel Fresh Type koristi visok procenat ekstrakta aloe vere kako bi trenutno umirio i osvežio kožu. Formula hidrira bez lepljivog osećaja i pomaže kod crvenila, iritacija i dehidratacije.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Isntree-Aloe-Soothing-Gel-Fresh-Type.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
