INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (507, 56, 'Elizavecca Cer-100 Collagen Coating Hair A Muscle Curl Cream', 'elizavecca-cer-100-collagen-coating-hair-a-muscle-curl-cream', 'Ključne prednosti: Hidrolizovani kolagen obnavlja vlakno dlake, čini je čvršćom i otpornijom na lomljenje, dok proteini i biljna ulja doprinose jačanju i mekoći. Zahvaljujući laganoj, ali hranljivoj teksturi, krema se lako raspoređuje, definiše kovrdže i sprečava neuredan izgled. Daje kosi prirodan sjaj i mekoću, a istovremeno smanjuje friz efekat i pruža dugotrajan oblik. Redovnom upotrebom kosa postaje zdravija, elastičnija i lakša za stilizovanje. Kome je namenjena? Preporučuje se za kovrdžavu, talasastu i hemijski tretiranu kosu kojoj nedostaje elastičnost, sjaj i hidratacija. Pogodna je i za suvu i lomljivu kosu koja se lako mrsi i puca. Zašto volimo Elizavecca Cer-100 Collagen Coating Hair A Muscle Curl Cream? Peptidi jačaju kožnu strukturu i doprinose smanjenju bora i finih linija. Niacinamid posvetljuje tamne podočnjake i daje koži odmorniji izgled, dok hijaluronska kiselina obezbeđuje dugotrajnu hidrataciju. Umirujući biljni ekstrakti smanjuju osećaj napetosti i otečenosti, pružajući osećaj svežine. Tekstura seruma je svilenkasta i brzo se upija, pa se lako uklapa u jutarnju i večernju rutinu. Redovnom upotrebom koža oko očiju postaje elastičnija, glatkija i odmornija. Aktivni sastojci Hidrolizovani kolagen Prodire u strukturu dlake i jača je iznutra. Vraća kosi elastičnost i čvrstinu, smanjujući lomljenje i oštećenja. Daje mekoću i prirodan sjaj. Proteini Pomažu u obnavljanju oštećene kose i jačanju keratinske strukture. Čine kosu otpornijom i punijom. Posebno korisni kod kose oslabljene toplotnim i hemijskim tretmanima. Biljna ulja Neguju kosu, vraćaju vlagu i sprečavaju isušivanje. Omekšavaju dlaku i olakšavaju oblikovanje. Smanjuju friz efekat i doprinose glatkoći i sjaju. Dodaj u listu želja Dodaj u listu želja', 'Elizavecca Cer-100 Collagen Coating Hair A Muscle Curl Cream kombinuje hidrolizovani kolagen, biljna ulja i proteine kako bi kosi pružila elastičnost, jačinu i sjaj. Krema istovremeno oblikuje kovrdže, hrani i štiti kosu bez otežavanja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Elizavecca-Cer-100-Collagen-Coating-Hair-A-Muscle-Curl-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
