INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (508, 40, 'Cosrx Hyaluronic Acid Hydra Power Essence', 'cosrx-hyaluronic-acid-hydra-power-essence', 'Ključne prednosti: Intenzivna hidratacija: hijaluronska kiselina dubinski hidrira i smanjuje osećaj zatezanja. Zaštita i obnova: ekstrakt johe jača kožnu barijeru i umiruje iritacije. Elastičnost i punoća: redovnom upotrebom koža postaje mekša, punija i vidno osvežena. Kome je namenjena? Pogodna je za sve tipove kože, posebno za suvu i dehidriranu kožu, kao i za osetljivu kožu kojoj je potrebna dodatna nega i umirenje. Preporučuje se i onima koji žele prevenciju prvih znakova starenja kroz dubinsku hidrataciju. Zašto volimo COSRX Hyaluronic Acid Hydra Power Essence? Ova esencija osmišljena je da pruži intenzivnu hidrataciju i pomogne koži da duže zadrži vlagu. Hijaluronska kiselina deluje kao snažan humektant – privlači i vezuje vodu u dubljim slojevima kože, čineći je mekšom i elastičnijom. Ekstrakt planinske korejanske johe dodatno umiruje, hidrira i podržava regeneraciju barijere kože. Tekstura je lagana i brzo se upija, ne ostavljajući lepljiv trag, što je čini pogodnom za upotrebu ujutru i uveče, kao i u slojevitim rutinama. Redovnim korišćenjem koža postaje glatkija, ujednačenija i otpornija na spoljašnje uticaje. Aktivni sastojci Hijaluronska kiselina Jedan od najsnažnijih humektanata koji privlači vlagu i vezuje je u koži. Smanjuje osećaj suvoće i zatezanja, vraća elastičnost i punoću. Dugotrajno održava hidrataciju i doprinosi zdravom i glatkom tenu. Ekstrakt planinske johe (Hippophae Rhamnoides Water / Betula Platyphylla Japonica Juice) Prirodni ekstrakt bogat aminokiselinama i mineralima. Umiruje iritacije i podržava regeneraciju kože. Pomaže u jačanju zaštitne barijere i smanjenju transepidermalnog gubitka vode. Doprinosi svežini i ujednačenom tenu. Dodaj u listu želja Dodaj u listu želja', 'COSRX Hyaluronic Acid Hydra Power Essence kombinuje hijaluronsku kiselinu i ekstrakt johe da intenzivno hidrira i zadrži vlagu u koži. Namenjena je dehidriranoj i umornoj koži kojoj je potrebna punoća, elastičnost i zdravi sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/09/COSRX-Hyaluronic-Acid-Hydra-Power-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
