INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (509, 40, 'Cosrx Peptide 132 Ultra Perfect Hair Bonding Treatment', 'cosrx-peptide-132-ultra-perfect-hair-bonding-treatment', 'Ključne prednosti: Dubinska obnova: peptidi i proteini rekonstruišu vlakno dlake i popravljaju oštećenja. Jačanje i elastičnost: ceramidi i hidratantni kompleksi vraćaju čvrstinu i fleksibilnost. Sjaj i mekoća: tretman zaglađuje kutikulu i čini kosu svilenkastom i glatkom. Kome je namenjen? Preporučuje se za oštećenu, lomljivu, hemijski tretiranu ili suvu kosu kojoj nedostaje snaga i elastičnost. Pogodan je za sve tipove kose, posebno za one koji žele dubinsku regeneraciju. Zašto volimo COSRX Peptide 132 Ultra Perfect Hair Bonding Treatment? Ovaj tretman je razvijen kao korak dubinske obnove kose kojoj je potrebna dodatna nega. Peptidi i proteini prodiru u vlakno dlake i popravljaju oštećenja iznutra, čineći kosu jačom i otpornijom. Ceramidi pomažu u obnovi lipidnog sloja, čuvaju vlagu i sprečavaju dalje isušivanje. Biljni ekstrakti i hidratantni sastojci dodatno hrane kosu i umiruju vlasište, doprinoseći zdravijem rastu. Tekstura tretmana obavija svaku vlas, zaglađuje kutikulu i smanjuje friz efekat. Redovnim korišćenjem kosa postaje sjajnija, mekša i manje sklona lomljenju. Aktivni sastojci Peptidi Deluju na unutrašnju strukturu dlake, jačaju keratinska vlakna i smanjuju lomljenje. Obnavljaju kosu iznutra i daju joj veću otpornost na spoljašnje faktore. Proteini Popunjavaju oštećene delove vlasi i vraćaju joj punoću. Pomažu u elastičnosti i čine kosu mekšom i podatnijom. Ceramidi Pomažu u obnavljanju lipidnog sloja kose. Sprečavaju gubitak vlage i čine kosu otpornijom i glatkijom. Biljni ekstrakti i ovlaživači Hidriraju i neguju kosu, obezbeđujući dugotrajan osećaj mekoće. Umiruju vlasište i daju kosi zdrav izgled. Dodaj u listu želja Dodaj u listu želja', 'COSRX Peptide 132 Ultra Perfect Hair Bonding Treatment kombinuje peptide, proteine i ceramide koji obnavljaju unutrašnju strukturu dlake, smanjuju lomljenje i vraćaju kosi elastičnost i sjaj. Namenjen je kosi oštećenoj farbanjem, toplotnim tretmanima ili spoljašnjim faktorima.', 'https://beauty-health.rs/wp-content/uploads/2025/09/COSRX-Peptide-132-Ultra-Perfect-Hair-Bonding-Treatment.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
