INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (510, 40, 'Cosrx Peptide 132 Ultra Perfect Hair Bonding Shampoo', 'cosrx-peptide-132-ultra-perfect-hair-bonding-shampoo', 'Ključne prednosti: Obnova i jačanje: peptidi i proteini jačaju strukturu dlake i smanjuju oštećenja. Njegovana i mekana kosa: ceramidi i biljni ekstrakti hidriraju i vraćaju elastičnost. Blago čišćenje: formula uklanja nečistoće bez narušavanja prirodne barijere vlasišta. Kome je namenjen? Preporučuje se za oštećenu, lomljivu i hemijski tretiranu kosu kojoj je potrebna obnova i jačanje. Pogodan je za sve tipove kose, uključujući i tanku, jer ne otežava. Zašto volimo COSRX Peptide 132 Ultra Perfect Hair Bonding Shampoo? Ovaj šampon je osmišljen za kosu kojoj je potrebna istovremena obnova i nežno čišćenje. Zahvaljujući peptidima i proteinima, jača vlakno dlake i pomaže u smanjenju lomljenja i ispucalih krajeva. Ceramidi obnavljaju lipidnu barijeru vlasi i zadržavaju vlagu, čineći kosu elastičnom i otpornom na oštećenja. Biljni ekstrakti umiruju vlasište i doprinose zdravijem rastu kose. Pena je bogata, ali blaga, pa šampon temeljno uklanja nečistoće i višak sebuma bez osećaja isušivanja. Redovnom upotrebom kosa postaje mekša, sjajnija i lakša za oblikovanje. Aktivni sastojci Peptidi Pomažu u jačanju keratinske strukture dlake. Podstiču elastičnost i otpornost na spoljašnje faktore. Vremenom obnavljaju oštećenja i smanjuju lomljenje. Proteini Popunjavaju oštećene delove vlasi i vraćaju kosi punoću. Povećavaju mekoću i olakšavaju raščešljavanje. Posebno korisni kod kose oslabljene farbanjem i toplotnim tretmanima. Ceramidi Obnavljaju lipidni sloj vlasi, sprečavaju gubitak vlage i jačaju otpornost kose. Doprinosi glatkoći i zdravijem izgledu. Biljni ekstrakti Umiruju vlasište i obezbeđuju antioksidativnu zaštitu. Podržavaju prirodan balans i doprinose zdravijem rastu kose. Dodaj u listu želja Dodaj u listu želja', 'COSRX Peptide 132 Ultra Perfect Hair Bonding Shampoo kombinuje peptide, proteine i ceramide kako bi ojačao kosu, smanjio lomljenje i obnovio njen prirodni sjaj. Lagana formula čisti vlasište bez isušivanja i vraća elastičnost kosi.', 'https://beauty-health.rs/wp-content/uploads/2025/09/COSRX-Peptide-132-Ultra-Perfect-Hair-Bonding-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
