INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (511, 40, 'Cosrx Peptide 132 Ultra Perfect Hair Bonding Oil Serum', 'cosrx-peptide-132-ultra-perfect-hair-bonding-oil-serum', 'Ključne prednosti: Obnova vlakna dlake: peptidi i ceramidi jačaju kosu iznutra i smanjuju lomljenje. Sjaj i mekoća: biljna ulja zaglađuju kutikulu i vraćaju prirodni sjaj kosi. Zaštita od spoljašnjih faktora: stvara barijeru protiv toplote, UV zraka i zagađenja. Kome je namenjen? Preporučuje se za suvu, oštećenu i hemijski tretiranu kosu, kao i za kosu sklonu lomljenju i ispucalim krajevima. Pogodan je za sve tipove kose koji traže obnovu i dodatnu zaštitu. Zašto volimo COSRX Peptide 132 Ultra Perfect Hair Bonding Oil Serum? Peptide 132 Ultra Perfect Hair Bonding Oil serum deluje kao intenzivna terapija za kosu sklonu lomljenju i oštećenjima. Zahvaljujući kombinaciji peptida, ceramida i prirodnih ulja, jača vlakno dlake i obnavlja njegovu unutrašnju strukturu. Smanjuje ispucale krajeve i daje kosi mekoću i elastičnost. Formula je lagana i nelepljiva, brzo se upija i ne otežava kosu, što ga čini pogodnim i za tanku dlaku. Osim što zaglađuje i dodaje sjaj, serum štiti kosu od toplote i spoljašnjih agresora. Redovnim korišćenjem kosa postaje otpornija, sjajnija i zdravijeg izgleda. Aktivni sastojci Peptidi Podstiču sintezu keratina i jačaju kosu iznutra. Obnavljaju strukturu vlasi i smanjuju njeno lomljenje. Redovnim korišćenjem doprinose elastičnijoj i otpornijoj kosi. Ceramidi Obnavljaju lipidnu barijeru vlasi, čuvaju vlagu i sprečavaju isušivanje. Čine kosu glatkom i otpornom na spoljašnje oštećenje. Posebno korisni za hemijski tretiranu i lomljivu kosu. Biljna ulja Ulje argana, suncokreta i kokosa hrane i hidriraju kosu. Vraćaju joj sjaj, smanjuju friz efekat i olakšavaju raščešljavanje. Ujedno formiraju zaštitni sloj koji štiti kosu od toplote i zagađenja. Dodaj u listu želja Dodaj u listu želja', 'COSRX Peptide 132 Ultra Perfect Hair Bonding Oil Serum kombinuje peptide, ceramide i biljna ulja kako bi popravio oštećenu strukturu dlake, smanjio lomljenje i vratio elastičnost. Laganom formulom hidrira, obnavlja i štiti kosu od spoljašnjih oštećenja bez otežavanja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/COSRX-Peptide-132-Ultra-Perfect-Hair-Bonding-Oil-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
