INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (513, 14, 'Arencia Rice Mucin Cleanser', 'arencia-rice-mucin-cleanser', 'Ključne prednosti: Nežno čišćenje: uklanja prljavštinu, višak sebuma i ostatke šminke bez osećaja zatezanja. Hidratacija i obnova: mucin i pirinač zadržavaju vlagu i umiruju kožu. Sjajnija i mekša koža: poboljšava teksturu i vraća prirodan sjaj tenu. Kome je namenjen? Preporučuje se za sve tipove kože, a naročito za normalnu, suvu i osetljivu kožu kojoj nedostaje vlažnost i sjaj. Idealan je za svakodnevnu upotrebu, ujutru i uveče. Zašto volimo Arencia Rice Mucin Cleanser? Ovaj čistač je osmišljen da bude više od običnog gela – njegova formula kombinuje pirinač, bogat vitaminima i mineralima, sa mucinom koji pomaže regeneraciju i hidrataciju kože. Prilikom umivanja stvara bogatu, kremastu penu koja uklanja nečistoće i višak sebuma, a da pritom ne oduzima koži prirodnu vlažnost. Pirinač posvetljuje ten i ujednačava boju kože, dok mucin jača barijeru i ubrzava oporavak. Redovnim korišćenjem koža postaje nežnija na dodir, glatkija i vidno svežija. Zahvaljujući hidratantnim svojstvima, pogodna je i za osetljive tipove kože. Aktivni sastojci Ekstrakt pirinča Prirodni izvor vitamina, minerala i antioksidanata. Posvetljuje kožu, pomaže u ujednačavanju tena i vraća prirodan sjaj. Deluje umirujuće i hidrira, čineći kožu mekom i osveženom. Mucin Poznat po snažnim regenerativnim i hidratantnim svojstvima. Pomaže u obnovi kože, jača zaštitnu barijeru i smanjuje iritacije. Zadržava vlagu i doprinosi elastičnosti i glatkoći kože. Hijaluronska kiselina Dodatno vezuje vlagu u koži, čineći je hidriranom tokom celog dana. Sprečava isušivanje i doprinosi mekoći i elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Arencia Rice Mucin Cleanser kombinuje ekstrakt pirinča i mucin za nežno, ali efikasno čišćenje kože. Održava prirodnu barijeru, sprečava isušivanje i ostavlja kožu mekom i osveženom nakon svakog umivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Arencia-Rice-Mucin-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
