INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (514, 14, 'Arencia Rice LHA Pore Control Rice Cake Cleanser', 'arencia-rice-lha-pore-control-rice-cake-cleanser', 'Ključne prednosti: Dubinsko čišćenje: uklanja višak sebuma i otčepljuje pore, sprečavajući nastanak nepravilnosti. Blaga eksfolijacija: LHA i salicilna kiselina uklanjaju mrtve ćelije bez iritacije. Hidratacija i umirenje: ekstrakti pirinča neguju i obnavljaju kožu, vraćajući joj sjaj. Kome je namenjen? Preporučuje se za masnu, mešovitu i kožu sklonu nepravilnostima, ali je dovoljno blag da ga mogu koristiti i osetljivi tipovi. Idealan je za svakodnevnu upotrebu ujutru i uveče. Zašto volimo Arencia Rice LHA Pore Control Rice Cake Cleanser? Ovaj penušavi gel pruža balans između efikasnog čišćenja i nežne nege. LHA i salicilna kiselina ciljano deluju na pore, uklanjaju višak sebuma i smanjuju mitisere, dok pritom ne izazivaju osećaj zatezanja. Ekstrakti pirinča i fermentisanog pirinčanog taloga bogati vitaminima i mineralima umiruju i hidriraju kožu, čineći je glatkom i osveženom. Tekstura se pretvara u finu, bogatu penu koja lako uklanja nečistoće i šminku. Klinički testovi pokazuju da značajno smanjuje višak masnoće, poboljšava teksturu kože i ostavlja ten vidno čistijim. Redovnim korišćenjem pore izgledaju manje vidljive, a koža zdravija i blistavija. Aktivni sastojci Ekstrakt pirinča Prirodno bogat vitaminima i aminokiselinama, umiruje i hidrira kožu. Vraća svežinu i posvetljuje ten, dok ujedno jača barijeru kože. Rice Lees Extract (fermentisani pirinčani talog) Dodatno pročišćava pore, balansira pH kože i pomaže u vraćanju zdravog mikrobioma. Daje koži mekoću i elastičnost. Salicilna kiselina Deluje dubinski na pore, rastvara višak sebuma i sprečava stvaranje mitisera i akni. Posebno efikasna kod masne i problematične kože. LHA (Capryloyl Salicylic Acid) Blaža varijanta salicilne kiseline koja radi polako i postepeno, pružajući eksfolijaciju bez iritacija. Zahvaljujući manjoj kiselosti pogodna je i za osetljive tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Arencia Rice LHA Pore Control Rice Cake Cleanser sadrži ekstrakt fermentisanog pirinča, salicilnu i LHA kiselinu koje čiste pore, uklanjaju višak masnoće i umiruju kožu. Pogodan je za svakodnevnu upotrebu jer uklanja nečistoće bez isušivanja, ostavljajući kožu mekom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Arencia-Rice-LHA-Pore-Control-Rice-Cake-Cleanser-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
