INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (515, 14, 'Arencia Red Collagen Jello Mask', 'arencia-red-collagen-jello-mask', 'Ključne prednosti: Povećava elastičnost: kolagen i peptidi učvršćuju kožu i vraćaju joj punoću. Antioksidativna zaštita: crveno voće bogato vitaminima neutralizuje slobodne radikale i posvetljuje ten. Dubinska hidratacija: gelasta tekstura osvežava, hladi i ostavlja kožu mekom i glatkom. Kome je namenjena? Maska je pogodna za sve tipove kože, naročito za dehidriranu, umornu i kožu koja gubi elastičnost. Idealna je za one koji žele dodatnu hidrataciju i prevenciju prvih znakova starenja. Zašto volimo Arencia Red Collagen Jello Mask? Ova maska kombinuje blagodeti kolagena i antioksidativnih ekstrakata crvenog voća kako bi koži pružila sveobuhvatnu negu. Hidrolizovani kolagen prodire u površinske slojeve kože, poboljšava elastičnost i smanjuje pojavu finih linija. Ekstrakti nara, jagode i maline bogati su vitaminima i polifenolima koji štite kožu od oksidativnog stresa i vraćaju joj svežinu. Gelasta tekstura hladi i osvežava, što masku čini posebno prijatnom za kožu koja je umorna ili izložena spoljnim faktorima. Nakon upotrebe, koža je hidrirana, glatka i ujednačenog tona. Redovnim korišćenjem ten postaje vidljivo čvršći i blistaviji. Aktivni sastojci Hidrolizovani kolagen Poboljšava elastičnost kože i vraća joj čvrstinu. Veže vlagu u površinskim slojevima i čini kožu punijom i mekšom. Redovnom primenom doprinosi smanjenju vidljivosti finih linija i bora. U ovoj formuli predstavlja ključni sastojak za učvršćivanje kože. Ekstrakt nara Bogat antioksidansima i vitaminima, štiti kožu od slobodnih radikala. Podstiče regeneraciju i vraća koži svežinu. Deluje posvetljujuće i daje ujednačen ten. Posebno je koristan kod kože sklone umoru i sivkastom tonu. Ekstrakt jagode Prirodni izvor vitamina C i polifenola. Pomaže u posvetljivanju kože i vraća joj zdrav sjaj. Doprinosi regeneraciji i smanjenju znakova starenja. Njeguje kožu i čini je mekom. Ekstrakt maline Deluje umirujuće i antioksidativno. Štiti kožu od spoljašnjih faktora i poboljšava njenu otpornost. Pomaže u održavanju hidratacije i mekoće kože. U ovoj maski doprinosi osvežavajućem efektu i jačanju barijere kože. Dodaj u listu želja Dodaj u listu želja', 'Arencia Red Collagen Jello Mask sadrži hidrolizovani kolagen, ekstrakte nara, jagode i maline, koji hrane kožu, vraćaju joj punoću i prirodan sjaj. Maska osvežava, hidrira i pomaže u ublažavanju prvih znakova starenja, ostavljajući kožu glatkom i zategnutijom.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Arencia-Red-Collagen-Jello-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
