INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (516, 12, 'APLB Spicule Collagen Shot 300 Serum', 'aplb-spicule-collagen-shot-300-serum', 'Ključne prednosti: Stimulacija obnavljanja: spikule mikrostimulacijom podstiču obnovu ćelija i prodiranje aktivnih sastojaka. Čvrstoća i elastičnost: kolagen i peptidi poboljšavaju strukturu kože i smanjuju pojavu finih linija. Dubinska hidratacija: dodatni ovlaživači smiruju kožu i održavaju je mekom i gipkom. Kome je namenjen? Preporučuje se osobama sa suvom, umornom i zrelom kožom kojoj nedostaje elastičnost i sjaj. Pogodan je i za one koji žele preventivnu negu protiv starenja kože tela. Zašto volimo APLB Spicule Collagen Shot 300 Serum? Ovaj serum donosi naprednu tehnologiju korišćenja spikula, mikroskopskih iglica iz morskih sunđera, koje mehanički stimulišu kožu i omogućavaju aktivnim sastojcima da prodru dublje. Time se pokreće proces prirodne regeneracije, a koža se podstiče da proizvodi sopstveni kolagen i elastin. Dodati hidrolizovani kolagen i peptidi pomažu u poboljšanju čvrstoće i elastičnosti kože, dok umirujući i hidratantni sastojci ublažavaju potencijalno crvenilo. Rezultat je koža koja deluje zategnutije, glađe i hidriranije. Tekstura je lagana, brzo se upija i lako se uklapa u dnevnu i noćnu rutinu. Redovnim korišćenjem ten postaje ujednačeniji, a bore manje primetne. Aktivni sastojci Spikule (morske mikročestice) Deluju kao mikroskopske iglice koje prodiru u kožu, stvarajući blagu stimulaciju i podstičući prirodnu obnovu ćelija. Omogućavaju aktivnim sastojcima da se bolje apsorbuju i pojačavaju efekat seruma. Ovaj proces doprinosi glatkijoj, čvršćoj i zdravijoj koži. Hidrolizovani kolagen Pruža koži potrebnu vlagu i podržava elastičnost. Doprinosi smanjenju sitnih linija i čini kožu mekšom i punijom. Njegova struktura omogućava brzu apsorpciju i efikasan rad u površinskim slojevima kože. Peptidi Podstiču proizvodnju kolagena i elastina, što doprinosi dugoročnom učvršćivanju kože. Jačaju barijeru kože i smanjuju znake umora. Redovnom primenom koža postaje glađa i otpornija na spoljne faktore. Hijaluronska kiselina Deluje kao snažan humektant – privlači i zadržava vlagu u koži. Pomaže u očuvanju elastičnosti i smanjenju osećaja suvoće. U ovoj formuli podržava efekat hidratacije i mekoće. Dodaj u listu želja Dodaj u listu želja', 'APLB Spicule Collagen Shot 300 Serum koristi mikroskopske spikule iz morskih sunđera koje prodiru u kožu i stimulišu prirodnu regeneraciju, dok kolagen i peptidi obezbeđuju čvrstoću i hidrataciju. Namenjen je koži kojoj nedostaje elastičnost, ujednačenost i zdrav sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/09/APLB-Spicule-Collagen-Shot-300-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
