INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (517, 11, 'Anua Triple Acid Spot Care Microdart Patch', 'anua-triple-acid-spot-care-microdart-patch', 'Ključne prednosti: Ciljano delovanje: mikroiglice oslobađaju aktivne sastojke duboko u kožu, tačno na mestu nepravilnosti. Trostruki efekat kiselina: AHA, BHA i PHA uklanjaju višak sebuma, čiste pore i pospešuju obnovu kože. Umirivanje i zaštita: centella asiatica i madecassoside ublažavaju iritacije i jačaju barijeru kože. Kome je namenjen? Preporučuje se osobama koje imaju akne, upaljene bubuljice ili povremene nepravilnosti koje žele da tretiraju ciljano i diskretno. Pogodan je za sve tipove kože, uključujući i osetljivu. Zašto volimo Anua Triple Acid Spot Care Microdart Patch? Ovi flasteri predstavljaju praktičan i diskretan način da se tretiraju nepravilnosti bez agresivnih proizvoda. Mikroiglice sadrže preciznu dozu aktivnih kiselina koje otpuštaju sastojke u dublje slojeve kože, gde deluju na začepljene pore i upalne procese. Trostruka kombinacija AHA, BHA i PHA kiselina uklanja mrtve ćelije, oslobađa pore i sprečava stvaranje novih nesavršenosti. Istovremeno, centella i madecassoside umiruju crvenilo i pomažu regeneraciju kože, dok hijaluronska kiselina sprečava isušivanje. Flaster je tanak, gotovo nevidljiv i udoban, pa se može nositi tokom dana ili noći bez osećaja neprijatnosti. Redovnim korišćenjem koža postaje čistija, mirnija i ujednačenija. Aktivni sastojci AHA, BHA i PHA kiseline Ova kombinacija deluje višeslojno: AHA (glikolna, mlečna) uklanja mrtve ćelije sa površine kože, BHA (salicilna) prodire u pore i uklanja višak sebuma, dok PHA nežno eksfolira i hidrira kožu. Zajedno doprinose čistijoj, glađoj i zdravijoj koži, smanjujući rizik od novih nepravilnosti. Centella Asiatica Poznata po umirujućem dejstvu, pomaže kod crvenila i iritacija. Podržava regeneraciju kože i jača zaštitnu barijeru, čineći kožu otpornijom. Madecassoside Aktivna komponenta centelle koja dodatno smanjuje upale i ubrzava zarastanje kože. Pomaže da koža brže povrati miran i zdrav izgled. Hijaluronska kiselina Osigurava da koža ostane hidrirana i elastična čak i tokom tretmana kiselinama. Smanjuje osećaj suvoće i doprinosi prijatnosti tokom nošenja flastera. Dodaj u listu želja Dodaj u listu želja', 'Anua Triple Acid Spot Care Microdart Patch kombinuje AHA, BHA i PHA kiseline sa umirujućim ekstraktima centelle i madecassoside-a. Zahvaljujući mikroiglicama koje sadrže aktivne sastojke, flaster deluje direktno na problematična mesta, smanjujući crvenilo i ubrzavajući smirivanje kože.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Anua-Triple-Acid-Spot-Care-Microdart-Patch-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
