INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (518, 9, 'Acwell Licorice pH Balancing Advance Serum', 'acwell-licorice-ph-balancing-advance-serum', 'Ključne prednosti: Balans i smirenje: održava optimalan pH kože i umiruje crvenilo. Blistaviji ten: posvetljuje tamne fleke i vraća koži ujednačen izgled. Dubinska hidratacija: obezbeđuje vlagu bez osećaja težine i lepljivosti. Kome je namenjen? Serum je pogodan za sve tipove kože, a posebno za one koji se bore sa sivim tenom, tamnim flekama, dehidratacijom ili osetljivošću. Odlično rešenje za svakodnevnu negu kože kojoj nedostaje ravnoteža i sjaj. Zašto volimo Acwell Licorice pH Balancing Advance Serum? Ovaj serum deluje kao nežni, ali efikasni saveznik kože kojoj nedostaje balans. Sladić umiruje i ublažava crvenilo, dok u isto vreme podržava prirodnu sposobnost kože da zadrži vlagu. Niacinamid i glutation zajedno rade na smanjenju diskoloracija i vraćanju sjaja, čineći ten ujednačenijim i zdravijim. Hijaluronska kiselina i glicerin zadržavaju vodu i pružaju dugotrajan osećaj punoće i mekoće. Tekstura je lagana, brzo se upija i ne ostavlja lepljiv trag, pa se lako uklapa i u jutarnju i u večernju rutinu. Redovnim korišćenjem koža izgleda smirenije, hidriranije i osveženije. Aktivni sastojci Ekstrakt sladića Poznat po umirujućem dejstvu, pomaže u smanjenju crvenila i iritacija. Istovremeno deluje na posvetljavanje tena i daje koži zdraviji izgled. Podržava očuvanje vlage i čini kožu mekšom. Blag je i dobro podnošljiv, pa je pogodan i za osetljive tipove kože. U ovom serumu služi kao ključni sastojak za vraćanje balansa i ujednačenog tona. Niacinamid i glutation Niacinamid smanjuje vidljivost tamnih fleka, ujednačava ton i jača barijeru kože. Glutation deluje antioksidativno i doprinosi zdravom sjaju. Zajedno deluju sinergijski, pomažući koži da izgleda svežije i odmornije. Ovi sastojci su nežni, ali dovoljno moćni za svakodnevnu upotrebu. Redovnim korišćenjem pomažu u smanjenju diskoloracija i umornog izgleda kože. Hijaluronska kiselina i glicerin Dva klasična, ali efikasna hidratanta. Hijaluronska kiselina privlači vlagu, dok glicerin pomaže da se ona zadrži u koži. Rezultat je koža koja je meka, elastična i hidrirana tokom celog dana. Ova kombinacija pruža osećaj punoće bez težine i ne ostavlja mastan film. Posebno je korisna za kožu koja je sklona dehidrataciji. Dodaj u listu želja Dodaj u listu želja', 'Acwell Licorice pH Balancing Advance Serum spaja ekstrakt sladića, niacinamid i glutation kako bi posvetlio ten, smanjio iritacije i održao zdrav balans kože. Idealan je za sivkastu, umornu i neujednačenu kožu kojoj je potrebna dodatna svežina.', 'https://beauty-health.rs/wp-content/uploads/2025/09/Acwell-Licorice-pH-Balancing-Advance-Serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
