INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (519, 43, 'd’Alba Piedmont White Truffle First Aromatic Spray Serum', 'd-alba-piedmont-white-truffle-first-aromatic-spray-serum', 'Ključne prednosti: Trenutna hidratacija: koža postaje osvežena i mekana već nakon prvog raspršivanja. Zaštita i elastičnost: Trufferol™ (beli tartuf + vitamin E) jača barijeru i smanjuje prve bore. Praktičnost: sprej-forma omogućava upotrebu bilo kad – kod kuće, u kancelariji ili tokom putovanja. Kome je namenjen? Prikladan je za sve tipove kože, uključujući i osetljivu. Posebno će prijati umornoj, dehidriranoj i sivkastoj koži koja traži brz način da povrati sjaj i svežinu. Zašto volimo d’Alba Piedmont White Truffle First Aromatic Spray Serum? Ovaj sprej-serum je osmišljen da pruži koži sve što joj je potrebno u jednom koraku – vlagu, zaštitu i sjaj. Patentirani kompleks Trufferol™, koji spaja beli tartuf i vitamin E, deluje kao snažan antioksidans, pomaže koži da se izbori sa stresom i zagađenjem i vraća joj elastičnost. Biljna ulja hrane i omekšavaju, dok ekstrakti biljaka poput centelle i kamilice umiruju iritacije. Hijaluronska kiselina dodatno puni kožu vlagom i smanjuje osećaj suvoće. Tekstura je ultralagana i ne ostavlja masni trag, pa se može koristiti i kao fiksator šminke. Redovnom upotrebom koža postaje ujednačenija, mekša i vizuelno odmornija. Aktivni sastojci Trufferol™ (beli tartuf + vitamin E) Jedinstveni kompleks sa snažnim antioksidativnim dejstvom. Štiti ćelije od oksidativnog stresa, smanjuje znakove umora i pomaže koži da zadrži elastičnost. Vitamin E dodatno neguje i smiruje, dok tartuf daje luksuzni nutritivni efekat. U kombinaciji deluju kao štit protiv prevremenog starenja i daju koži blistav izgled. Biljna ulja i ekstrakti Kombinacija osam ulja (avokado, makadamija, kamelija…) i jedanaest biljnih ekstrakata (centella, neven, kamilica…) hrani kožu i obnavlja njenu barijeru. Umiruju crvenilo i iritacije, vraćaju mekoću i elastičnost. Redovnim korišćenjem doprinose ujednačenijem i zdravijem tenu. Hijaluronska kiselina Jedan od najsnažnijih humektanata, vezuje vodu i daje koži punoću i glatkoću. Pomaže u smanjenju dehidratacionih linija i vraća komfor. U ovoj formuli podržava dugotrajnu hidrataciju i svež izgled kože. Dodaj u listu želja Dodaj u listu želja', 'd’Alba White Truffle First Spray Serum kombinuje antioksidativni kompleks belog tartufa i vitamina E sa biljnim uljima i ekstraktima kako bi koži vratio vlagu, elastičnost i zdrav sjaj. Lagani mist osvežava ten tokom dana i može se nanositi i preko šminke.', 'https://beauty-health.rs/wp-content/uploads/2025/08/dAlba-Piedmont-White-Truffle-First-Aromatic-Spray-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
