INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (520, 172, 'Vichy Capital Soleil vodeni fluid u spreju SPF30+', 'vichy-capital-soleil-vodeni-fluid-u-spreju-spf30', 'Ključne prednosti: Zaštita širokog spektra: štiti od UVB, UVA i dugih UVA zraka. Osvežavajuća tekstura: lagana, vodena formula koja se brzo upija i ne ostavlja bele tragove. Hidratacija i otpornost: hijaluronska kiselina i termalna voda vraćaju vlažnost i jačaju barijeru kože. Kome je namenjena? Preporučuje se za sve tipove kože, uključujući osetljivu. Idealan je za osobe koje traže laganu, nemasnu i praktičnu zaštitu sa SPF 30 za svakodnevno izlaganje suncu. Zašto volimo Vichy Capital Soleil vodeni fluid u spreju SPF30+? Ovaj vodeni fluid u spreju pruža pouzdanu zaštitu od sunca u laganom i osvežavajućem formatu, idealnom za svakodnevnu upotrebu. Formulacija sa UV filterima štiti kožu od opekotina, fotostarenja i dugoročnih oštećenja. Hijaluronska kiselina hidrira i smanjuje osećaj suvoće, dok termalna voda bogata mineralima jača barijeru i pomaže koži da održi otpornost. Tekstura je lagana poput vode, brzo se upija i ne ostavlja masne niti bele tragove, pa je pogodna i za lice i za telo. Sprej format omogućava jednostavno i ravnomerno nanošenje. Dermatološki je testiran i hipoalergen, pogodan i za osetljivu kožu. Aktivni sastojci UV filteri širokog spektra Obezbeđuju zaštitu od UVB, UVA i dugih UVA zraka. Sprečavaju nastanak opekotina i oštećenja kože na ćelijskom nivou. Stabilni su i fotostabilni, otporni na spoljne uslove. Sigurni su za svakodnevnu upotrebu i osetljivu kožu. U ovoj formuli pružaju laganu, ali pouzdanu zaštitu. Ključni su za prevenciju fotostarenja. Hijaluronska kiselina Prirodni humektant koji privlači i zadržava vodu, obezbeđujući dubinsku hidrataciju. Sprečava suvoću i osećaj zatezanja kože tokom boravka na suncu. Vraća koži elastičnost i punoću. Pogodna je za sve tipove kože, uključujući osetljivu. Dobro se kombinuje sa mineralima iz termalne vode. U ovoj formuli daje koži osećaj svežine i hidratacije. Vichy vulkanska termalna voda Bogata sa 15 minerala, jača prirodnu barijeru kože i smanjuje osetljivost. Umiruje, osvežava i podržava regeneraciju. Pruža antioksidativnu zaštitu i smanjuje iritacije. Pogodna je i za najosetljivije tipove kože. U ovoj formuli dopunjuje dejstvo UV filtera i hijaluronske kiseline. Daje koži dugotrajan osećaj komfora i svežine. Dodaj u listu želja Dodaj u listu želja', 'Vichy Capital Soleil vodeni fluid SPF30 kombinuje UV filtere širokog spektra, hijaluronsku kiselinu i Vichy vulkansku termalnu vodu za zaštitu od sunca i očuvanje hidratacije. Namenjen je osobama koje žele laganu, osvežavajuću i nemasnu zaštitu tokom svakodnevnog izlaganja suncu.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Vichy-Capital-Soleil-vodeni-fluid-u-spreju-SPF30.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
