INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (522, 172, 'Vichy Capital Soleil Solar Protective Water SPF 50', 'vichy-capital-soleil-solar-protective-water-spf-50', 'Ključne prednosti: Visoka zaštita: širokospektralni UV filteri štite od UVB, UVA i dugih UVA zraka. Lagani osećaj: tekstura poput vode brzo se upija, ne ostavlja tragove i pogodna je za lice i telo. Podrška tenu: beta-karoten daje blistavost i pomaže u ujednačavanju tena. Kome je namenjena? Pogodna je za sve tipove kože, uključujući osetljivu. Idealan izbor za one koji žele visoku zaštitu uz laganu, neljepljivu formulu i suptilan efekat osvetljenja tena. Zašto volimo Vichy Capital Soleil Solar Protective Water SPF 50? Solar Protective Water pruža naprednu zaštitu od sunca uz osvežavajuću, laganu teksturu. Njena dvostruka faza kombinuje efikasne UV filtere sa negujućim i osvetljavajućim sastojcima. Beta-karoten blago naglašava prirodan ton kože i doprinosi ujednačenom tenu, dok hijaluronska kiselina obnavlja vlažnost i sprečava isušivanje. Vichy vulkanska termalna voda bogata mineralima jača prirodnu barijeru i smiruje kožu. Formula se brzo upija, ne lepi se i ne ostavlja bele tragove, pogodna je i za osetljive tipove kože. Može se koristiti za lice, telo i tokom boravka na otvorenom, a mirna tekstura pogodna je i za svakodnevnu upotrebu. Aktivni sastojci UV filteri širokog spektra Kombinacija naprednih filtera štiti od UVB, UVA i dugih UVA zraka. Sprečavaju opekotine, fotostarenje i oštećenja na ćelijskom nivou. Formulisani su tako da budu postojani i pod vodom ili znojenjem. Pogodni su i za osetljivu kožu i testirani na toleranciju. U ovoj formuli su prilagođeni laganom, vodenom spreju za lako nanošenje. Osiguravaju pouzdanu zaštitu tokom celog dana. Beta-karoten Prirodni pigment koji blago naglašava ten i daje koži zdrav, osunčan sjaj. Ima antioksidativno dejstvo i pomaže u zaštiti ćelija od oksidativnog stresa izazvanog UV zracima. Blago ujednačava ton i doprinosi vizuelno lepšoj teksturi kože. Bezbedan je i blag za svakodnevnu upotrebu. U ovoj formuli radi sinergijski sa UV filterima za lepši izgled kože. Posebno koristan kod letnje nege. Vichy vulkanska termalna voda Bogata sa 15 minerala, jača prirodnu barijeru kože i podstiče otpornost. Umiruje iritacije i štiti kožu od spoljašnjih faktora. Hidrira i daje osećaj svežine. Pogodna je i za najosetljivije tipove kože. U ovoj formuli pojačava zaštitni efekat UV filtera. Osigurava osećaj komfora čak i pri visokim temperaturama. Hijaluronska kiselina Privlači i zadržava vlagu, smanjuje osećaj suvoće i zatezanja. Pomaže koži da ostane meka i elastična tokom izlaganja suncu. Smanjuje fine linije uzrokovane dehidratacijom. Dobro se kombinuje sa antioksidansima i UV filterima. Blaga je i pogodna za svakodnevnu upotrebu. U ovoj formuli čini ključni hidratantni deo zaštitne vodice. Dodaj u listu želja Dodaj u listu želja', 'Vichy Capital Soleil Solar Protective Water SPF 50 kombinuje napredne UV filtere, vulkansku termalnu vodu, hijaluronsku kiselinu i beta-karoten kako bi istovremeno štitila, hidrirala i posvetlila ten. Namenjena je svima koji žele laganu, neljepljivu zaštitu uz dodatni sjaj i osveženje kože.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Vichy-Capital-Soleil-Solar-Protective-Water-SPF-50-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
