INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (525, 113, 'Medi-peel Eazy Filler Ampoule', 'medi-peel-eazy-filler-ampoule', 'Ključne prednosti: Efekat popunjavanja: hijaluronska kiselina i kolagen vraćaju volumen i hidrataciju. Lifting i tonus: peptidi stimulišu sintezu kolagena i učvršćuju kožu. Brzi rezultati: lagana, koncentrisana formula vidljivo zaglađuje bore. Kome je namenjena? Preporučuje se osobama koje žele brze i vidljive rezultate u smanjenju bora i vraćanju punoće. Pogodna je za sve tipove kože, uključujući i zrelu i umornu kožu. Zašto volimo MEDI-PEEL Eazy Filler Ampoule? Eazy Filler Ampoule pruža intenzivan i vidljiv efekat zahvaljujući pažljivo odabranoj kombinaciji peptida i hidratantnih sastojaka. Hijaluronska kiselina veže vlagu i daje trenutnu punoću, dok kolagen i peptidi rade dugoročno, jačajući strukturu kože i podstičući sintezu elastina. Ova formula je dizajnirana da brzo smanji vidljivost finih linija i mimičkih bora, posebno oko očiju i usana. Tekstura je lagana, brzo se upija i ne ostavlja lepljiv trag, što je čini pogodnom i za dnevnu rutinu ispod šminke. Biljni ekstrakti i antioksidansi dodatno umiruju i štite kožu od spoljašnjih faktora. Redovnom upotrebom koža postaje čvršća, elastičnija i vidno zaglađenija. Aktivni sastojci Peptidni kompleks Peptidi šalju signal ćelijama da pojačaju proizvodnju kolagena i elastina, čime jačaju tonus i smanjuju bore. U ovoj ampuli deluju brzo i ciljano na problematične regije. Podstiču regeneraciju i povećavaju otpornost kože. Kombinacija više peptida omogućava višeslojni efekat – površinsko zaglađivanje i dubinsko jačanje. Pogodni su i za osetljivu kožu. Redovnim korišćenjem doprinose vidljivijem lifting efektu. Hijaluronska kiselina Humektant koji privlači i zadržava vodu, povećavajući hidrataciju i punoću kože. Odmah nakon nanošenja koža izgleda osveženo i elastično. Smanjuje osećaj zatezanja i sitne linije nastale suvoćom. Blaga je i pogodna za sve tipove kože. Kombinovana sa peptidima i kolagenom daje efekat glatke i meke teksture. U ovoj ampuli hijaluronska kiselina čini osnovu brzog volumizirajućeg efekta. Kolagen Topikalni kolagen poboljšava glatkoću i vlažnost kože. Deluje kao film koji sprečava gubitak vlage i vraća punoću. U kombinaciji sa hijaluronom i peptidima pomaže da koža izgleda čvršće i mlađe. Posebno koristan kod suve i zrele kože. Bezbedan je i blag. U ovoj formuli daje koži dodatnu elastičnost i podržava dugoročan efekat učvršćivanja. Biljni ekstrakti i antioksidansi Smanjuju iritacije i štite kožu od slobodnih radikala. Podržavaju proces obnove i pružaju dodatnu negu. Posebno korisni kod kože izložene spoljnim stresorima. Blagi su i kompatibilni sa aktivnim sastojcima u formuli. U ovoj ampuli dopunjuju i jačaju anti-age efekat. Daju osećaj umirenja i balansa. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Eazy Filler Ampoule kombinuje peptide, hijaluronsku kiselinu i kolagen za ciljano smanjenje bora, vraćanje punoće i poboljšanje elastičnosti kože. Namenjena je koži kojoj nedostaje volumen i glatkoća, kao i onima koji žele brze i vidljive rezultate u nezi protiv starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Eazy-Filler-Ampoule-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
