INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (526, 113, 'Medi-Peel Hyal Kombucha Tea-Tox Cream', 'medi-peel-hyal-kombucha-tea-tox-cream', 'Ključne prednosti: Dubinska hidratacija: hijaluronska kiselina obezbeđuje višeslojnu vlagu i smanjuje osećaj suvoće. Obnova i zaštita: kombuha i biljni fermenti jačaju kožu i štite od spoljašnjih agresora. Osvežen i ujednačen ten: antioksidansi i vitamini poboljšavaju sjaj i elastičnost. Kome je namenjena? Preporučuje se za normalnu, suvu i mešovitu kožu kojoj nedostaje hidratacija, sjaj i zaštita. Pogodna je i za umornu, sivkastu kožu ili kožu izloženu spoljašnjim stresorima. Zašto volimo Medi-Peel Hyal Kombucha Tea-Tox Cream? Hyal Kombucha Tea-Tox Cream je krema koja kombinuje fermentisane sastojke i hidratantne komplekse za osvežavanje i jačanje kože. Fermentisani ekstrakt kombuhe bogat je probioticima i vitaminima, pomaže u balansiranju mikrobioma kože, jača barijeru i vraća vitalnost. Kompleks od više tipova hijaluronske kiseline puni kožu vlagom, smanjuje osećaj zatezanja i finih linija uzrokovanih dehidratacijom. Biljni ekstrakti i antioksidansi dodatno štite od oksidativnog stresa i daju zdrav sjaj. Tekstura je lagana, nelepljiva, lako se upija i pogodna je i za dnevnu i za noćnu negu. Redovnim korišćenjem koža postaje mekša, elastičnija i vizuelno odmornija. Aktivni sastojci Fermentisani ekstrakt kombuhe Kombuha je fermentisani čaj bogat probioticima, vitaminima i antioksidansima. Pomaže u jačanju zaštitne barijere i balansiranju mikrobioma kože. Poboljšava vitalnost, osvežava ten i vraća sjaj. Deluje umirujuće i smanjuje iritacije. Blaga je i pogodna za sve tipove kože. U ovoj kremi čini osnovu revitalizujućeg dejstva. Hijaluronska kiselina Humektant koji privlači i zadržava vodu, pružajući dugotrajnu hidrataciju. Pomaže u smanjenju suvoće i finih linija. Vraća punoću i mekoću, čini kožu elastičnijom. Dobro se kombinuje sa fermentisanim i biljnim sastojcima. Pogodna je za sve tipove kože, uključujući i osetljive. U ovoj kremi daje dugotrajan osećaj svežine. Biljni fermenti i antioksidansi Mešavina biljnih ekstrakata i fermentisanih sastojaka dodatno hrani i štiti kožu. Pruža antioksidativnu zaštitu od slobodnih radikala i spoljašnjih agresora. Umiruje i smanjuje crvenilo, dok pomaže u održavanju elastičnosti. Posebno korisni kod kože izložene stresu i zagađenju. Kompatibilni su sa ostalim aktivnim komponentama u formuli. U ovoj kremi doprinose osveženom i zdravom tenu. Vitamini i hranljivi kompleksi Dopunjuju hidrataciju, poboljšavaju teksturu i ton kože. Podržavaju regeneraciju i pomažu u zaštiti od spoljašnjih faktora. Blagi su i bezbedni za svakodnevnu upotrebu. Deluju u sinergiji sa kombuhom i hijaluronom. U ovoj kremi doprinose jačanju i obnovi kože. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Hyal Kombucha Tea-Tox Cream kombinuje ekstrakt fermentisanog čaja kombuhe, kompleks hijaluronskih kiselina i biljne antioksidanse kako bi obnovila vlagu, ojačala barijeru i poboljšala izgled umorne kože. Namenjena je koži kojoj nedostaje vlažnost, svežina i zaštita od spoljašnjih faktora.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Medi-Peel-Hyal-Kombucha-Tea-Tox-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
