INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (527, 113, 'Medi-Peel Eazy Filler Multi Care Kit', 'medi-peel-eazy-filler-multi-care-kit', 'Set sadrži: Krema (50 g) – učvršćuje, zateže i hrani kožu, smanjuje vidljivost bora, poboljšava tonus i elastičnost, ima efekat liftinga i daje sjaj. Ampula (30 ml) – popunjava fine linije, jača barijeru, hidrira i nežno ljušti za ujednačen reljef, posebno deluje na čelo, okoloočno područje i nazolabijalne bore. Toner (30 ml) – vraća vlagu posle čišćenja, priprema kožu i obnavlja balans vode i lipida. Emulzija (30 ml) – dubinski hidrira i hrani, stimuliše sintezu kolagena i elastina, smanjuje osećaj suvoće. Ključne prednosti: Kompletna rutina: četiri proizvoda ciljaju hidrataciju, tonus i smanjenje bora. Efekat liftinga i popunjavanja: Matrixyl®3000, Argirelin i EGF deluju na mišiće i ćelije za vidljivo čvršću kožu. Obnova i zaštita: RiFerm®, Blue Complex i hijaluronske kiseline vraćaju vlagu, štite i smiruju. Kome je namenjen? Set je idealan za zrelu kožu sa vidljivim borama i gubitkom elastičnosti, kao i za preventivnu negu nakon 30. godine. Pogodan za normalnu, suvu i mešovitu kožu. Zašto volimo Medi-Peel Eazy Filler Multi Care Kit? Eazy Filler Multi Care Kit predstavlja kompletnu negu kože koja je izgubila elastičnost, čvrstinu i sjaj. Svi proizvodi deluju sinergijski: toner vraća vlagu i priprema kožu, ampula intenzivno popunjava fine linije i jača unutrašnju strukturu, emulzija dubinski hidrira i hrani, dok krema učvršćuje i zateže kožu. Kompleks Matrixyl®3000 i Argirelin deluju kao mišićni relaksanti, smanjujući mimičke bore i sprečavajući nastanak novih. EGF iz pirinča i RiFerm® poboljšavaju regeneraciju, gustinu i elastičnost, dok Blue Complex pruža antioksidativnu zaštitu i umiruje kožu. Pet tipova hijaluronske kiseline i glikozaminoglikani održavaju optimalnu vlažnost i štite od iritacija. Redovnom upotrebom lice postaje glatko, zategnuto i blistavo. Aktivni sastojci Matrixyl®3000 (peptidni kompleks) Matrixyl®3000 je kombinacija peptida-matrikina koja pokreće proizvodnju sopstvenog kolagena. Pomaže u smanjenju dubine bora i ujednačava teksturu. Poboljšava tonus i elastičnost lica, čineći kožu čvršćom. Radi na dubljim slojevima kože za dugoročan efekat. Siguran je i efikasan za sve tipove kože. U ovom setu koristi se kao ključni anti-age sastojak. Argirelin (Acetyl Hexapeptide-8) Peptid poznat po efektu sličnom botoksu, opušta mimične mišiće i smanjuje napetost. Sprečava formiranje novih bora i ublažava postojeće. Posebno deluje na čelo, okoloočnu zonu i nazolabijalne bore. Daje lice odmornijeg izgleda. Blag je i dobro podnošljiv. U ovoj formuli pojačava lifting efekat kreme i ampule. EGF (epidermalni faktor rasta) Dobijen iz zrna pirinča, stimuliše rast i obnavljanje ćelija. Povećava proizvodnju kolagena i elastina, čineći kožu čvršćom i glađom. Podstiče zgušnjavanje epidermisa i smanjuje vidljive znake starenja. Pogodan za umornu i zrelu kožu. Blag i siguran za svakodnevnu upotrebu. U setu doprinosi bržoj regeneraciji i tonusu. RiFerm® kompleks (na bazi saharomiceta) Intenzivno hidrira i smanjuje vidljivost bora. Jača otpornost kože i čini je elastičnijom. Vraća ujednačen reljef i mekoću. Radi sinergijski sa hijaluronom i peptidima. Blag i efikasan i za osetljivu kožu. U ovoj liniji doprinosi svežini i punoći. Blue Complex (lavanda, različak, kamilica, giacint, boraga, žalfija) Biljni kompleks koji smiruje, hidrira i štiti kožu od spoljašnjih faktora. Daje antioksidativnu zaštitu i smanjuje iritacije. Pruža osećaj komfora i elastičnosti. Smanjuje perutanje i suvoću. Pogodan za osetljivu kožu. U setu podržava regenerativno i umirujuće dejstvo ostalih sastojaka. 5 vrsta hijaluronske kiseline Različite molekulske mase hijalurona obezbeđuju višeslojnu hidrataciju. Privlače i zadržavaju vlagu u koži, smanjujući osećaj suvoće i zategnutosti. Pomažu u održavanju elastičnosti i gipkosti. Deluju kao zaštitni sloj protiv spoljašnjih uticaja. Pogodne su za sve tipove kože. U ovom setu ključne su za osećaj mekoće i punog tena. H', 'Medi-Peel Eazy Filler Multi Care Kit sadrži kremu, ampulu, toner i emulziju, formulisan je za kožu kojoj nedostaje elastičnost, sjaj i hidratacija. Set kombinuje peptide, biljne faktore rasta i hijaluronske komplekse kako bi smanjio bore, ojačao barijeru i podstakao proizvodnju kolagena.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Medi-Peel-Eazy-Filler-Multi-Care-Kit-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
