INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (532, 113, 'Medi-peel Phyto Cica-nol B5 Calming Wrapping Mask', 'medi-peel-phyto-cica-nol-b5-calming-wrapping-mask', 'Ključne prednosti: Umirenje i zaštita: centela i pantenol smanjuju crvenilo i jačaju barijeru kože. Dubinska hidratacija: biljni kompleksi i hijaluronska kiselina vraćaju vlagu i mekoću. Regeneracija i otpornost: obnavlja oštećenu kožu i poboljšava toleranciju na spoljašnje faktore. Kome je namenjena? Preporučuje se osobama sa osetljivom, reaktivnom, suvom ili iritiranom kožom. Pogodna je i kao SOS tretman posle estetskih procedura, kod crvenila ili dehidratacije. Zašto volimo MEDI-PEEL Phyto Cica-nol B5 Calming Wrapping Mask? Phyto Cica-nol B5 Calming Wrapping Mask je tretman dizajniran za trenutni efekat umirenja i oporavka kože. Centella Asiatica i derivati cice poznati su po umirujućim i protivupalnim svojstvima, dok pantenol obnavlja i jača barijeru kože, smanjujući osećaj peckanja i zatezanja. Biljni kompleksi i hijaluronska kiselina vraćaju vlagu i elastičnost, dok posebni polimerni film na površini kože stvara zaštitni sloj koji zadržava aktivne sastojke i vlagu. Maska smanjuje crvenilo, pomaže kod iritacija nakon pilinga, laserskih tretmana ili izlaganja suncu. Laka je za korišćenje, brzo se upija i ne ostavlja težak osećaj. Redovnom primenom koža postaje stabilnija, hidriranija i spremna za druge korake nege. Aktivni sastojci Centella Asiatica (Cica) Biljni ekstrakt poznat po umirujućem i regenerativnom delovanju. Pomaže u smanjenju crvenila, iritacija i ubrzava obnavljanje oštećene kože. Deluje i kao antioksidans, štiti od slobodnih radikala i spoljašnjih agresora. Blag je i pogodan i za najosetljivije tipove kože. U ovoj maski radi sinergijski sa pantenolom za jači efekat umirenja. Dugotrajno jača otpornost kože. Pantenol (Vitamin B5) Sastojak poznat po sposobnosti da zadrži vlagu i ubrza proces regeneracije. Smanjuje suvoću, ljuštenje i osećaj zatezanja. Jača zaštitnu barijeru kože i čini je otpornijom na spoljašnje faktore. Dobro se podnosi i kod iritirane ili osetljive kože. U ovoj formuli pomaže da se koža umiri i oporavi brže. Daje mek, elastičan osećaj i poboljšava celokupni izgled kože. Biljni kompleksi i antioksidansi Sadrže kombinaciju biljnih ekstrakata sa umirujućim, antiinflamatornim i zaštitnim dejstvom. Pomažu u smanjenju crvenila i jačanju prirodne odbrane kože. Posebno korisni kod osetljive kože ili posle tretmana. U ovoj formuli pojačavaju efekat cice i pantenola. Antioksidansi štite od spoljašnjih faktora i usporavaju oštećenja. Blagi su i kompatibilni sa drugim aktivnim sastojcima. Hijaluronska kiselina Privlači i zadržava vodu u slojevima kože, daje punoću i mekoću. Smanjuje osećaj suvoće i zatezanja. Pomaže da koža ostane elastična i hidrirana duže vreme. Lako se kombinuje sa umirujućim sastojcima. U ovoj maski doprinosi trenutnom osveženju i komforu. Posebno važna za obnovu nakon stresa kože. Polimerni film-formeri Stvaraju lagani zaštitni sloj na površini kože koji pomaže da aktivni sastojci ostanu duže u kontaktu sa kožom. Sprečavaju isparavanje vlage. Ovaj sloj daje osećaj zaštite i komfora. Blag je, neiritirajući i lako se uklanja. Posebno koristan kod osetljive ili reaktivne kože. U ovoj maski produžava efekat hidratacije i umirenja. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Phyto Cica-nol B5 Calming Wrapping Mask kombinuje centelu (Cica), pantenol (B5), biljne komplekse i umirujuće polimere za trenutni osećaj smirenosti i intenzivnu regeneraciju kože. Namenjena je osetljivoj, iritiranoj i dehidriranoj koži kojoj je potrebna zaštita i balans.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Phyto-Cica-nol-B5-Calming-Wrapping-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
