INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (533, 113, 'Medi-peel Peptide 9 Volume Lifting Pro All In One Podo Ampoule', 'medi-peel-peptide-9-volume-lifting-pro-all-in-one-podo-ampoule', 'Ključne prednosti: Učvršćivanje i lifting: peptidni kompleks stimuliše sintezu kolagena i elastina. Hidratacija i punoća: hijaluronska kiselina i kolagen vraćaju vlagu i elastičnost. Zaštita i umirenje: biljni ekstrakti i antioksidansi smanjuju iritacije i štite kožu. Kome je namenjena? Preporučuje se osobama koje žele da zategnu kožu, smanje bore i vrate punoću, posebno posle 30. godine. Pogodna je za sve tipove kože, uključujući i osetljive, ali uz postepeno uvođenje kod reaktivne kože. Zašto volimo MEDI-PEEL Peptide 9 Volume Lifting Pro All In One Podo Ampoule? Peptide 9 Volume Lifting Pro All In One Podo Ampoule je napredna formula osmišljena da cilja najizraženije znakove starenja. Devet peptida stimulišu prirodnu obnovu kože, podstiču sintezu kolagena i elastina, čineći kožu čvršćom i zategnutijom. Hijaluronska kiselina pruža višeslojnu hidrataciju, dok kolagen vraća punoću i mekoću, ublažavajući fine linije uzrokovane dehidratacijom. Biljni ekstrakti i antioksidansi smanjuju crvenilo, umiruju i štite od spoljašnjih faktora. Tekstura je lagana i brzo se upija, što je čini pogodnom za jutarnju i večernju rutinu. Redovnom upotrebom ten postaje ujednačeniji, elastičniji i svežiji. Aktivni sastojci Peptidni kompleks (9 peptida) Peptidi deluju kao signalne molekule koje podstiču proizvodnju kolagena i elastina. Kombinacija devet različitih peptida osigurava višeslojni efekat – od površinskog učvršćivanja do dubinske obnove. Smanjuju bore, poboljšavaju tonus i otpornost kože. Sinergijski rade sa ostalim aktivnim sastojcima za jači anti-age rezultat. Bezbedni su za većinu tipova kože i dobro podnošljivi. U ovoj formuli daju efekat zatezanja i podmlađivanja. Kolagen Kolagen vraća elastičnost i punoću koži, poboljšava glatkoću i ublažava znakove umora. Kada se nanosi topikalno, hidrira i poboljšava teksturu površinskog sloja. Radi u kombinaciji sa peptidima i hijaluronom za optimalne rezultate. Posebno koristan kod kože koja je izgubila tonus. Bezbedan je i blag, pa se može koristiti svakodnevno. U ovoj formuli daje osećaj zategnutosti i svežine. Hijaluronska kiselina Humektant koji vezuje vodu i obezbeđuje dubinsku hidrataciju. Pomaže u smanjenju finih linija nastalih dehidratacijom. Poboljšava mekoću i elastičnost kože. U kombinaciji sa peptidima i kolagenom održava balans između hidratacije i čvrstine. Pogodna je i za osetljive tipove kože. U ovoj formuli daje dugotrajan osećaj punoće i osveženja. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Peptide 9 Volume Lifting Pro All In One Podo Ampoule kombinuje devet peptida, kolagen, hijaluronsku kiselinu i biljne komplekse kako bi poboljšala tonus, smanjila bore i vratila volumen licu. Namenjena je koži kojoj nedostaje elastičnost, čvrstina i hidratacija.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Peptide-9-Volume-Lifting-Pro-All-In-One-Podo-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
