INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (534, 113, 'Medi-peel Bio-Intense Glutathione White Ampoule 2.0', 'medi-peel-bio-intense-glutathione-white-ampoule-2-0', 'Ključne prednosti: Ujednačen ten: glutation i niacinamid smanjuju hiperpigmentacije i vraćaju blistavost. Jačanje strukture: peptidi i kolagen poboljšavaju tonus i elastičnost. Hidratacija i zaštita: hijaluronska kiselina i antioksidansi čuvaju vlagu i štite od oksidativnog stresa. Kome je namenjena? Preporučuje se osobama sa neujednačenim tenom, tamnim mrljama, znakovima umora ili sivkastim tonom kože. Pogodna za sve tipove kože, uključujući i osetljive, uz pravilno uvođenje. Zašto volimo MEDI-PEEL Bio-Intense Glutathione White Ampoule 2.0? Bio-Intense Glutathione White Ampoule 2.0 je kreirana da pruži vidljivo osveženje i posvetljivanje tena. Glutation, snažan antioksidans, deluje na smanjenje tamnih fleka i oštećenja od UV zračenja, dok niacinamid umiruje, ujednačava i jača barijeru kože. Peptidi i kolagen pomažu u vraćanju elastičnosti i smanjenju finih linija, dok hijaluronska kiselina hidrira i daje punoću. Antioksidansi dodatno štite ćelije od slobodnih radikala, čuvajući mladalački izgled kože. Tekstura je lagana, brzo se upija i pogodna je za jutarnju i večernju rutinu. Redovnom upotrebom ten postaje svetliji, ujednačeniji i vizuelno odmorniji. Aktivni sastojci Glutation Glutation je snažan antioksidans koji neutralizuje slobodne radikale i štiti ćelije kože. Pomaže u smanjenju melaninske sinteze, čime posvetljuje tamne mrlje i ujednačava ten. Deluje i kao zaštita od oksidativnog stresa uzrokovanog UV zracima i zagađenjem. Poboljšava celokupnu vitalnost i sjaj kože. Blag je i dobro podnošljiv za većinu tipova kože. U ovoj formuli daje primetan efekat posvetljivanja i osveženja. Niacinamid Oblik vitamina B3 poznat po svojoj sposobnosti da jača barijeru, smiruje upale i smanjuje crvenilo. Posvetljuje kožu, ujednačava ton i smanjuje vidljivost fleka. Deluje protivupalno i poboljšava hidrataciju. Pogodan je i za osetljive tipove kože. U kombinaciji sa glutationom pojačava efekat posvetljivanja. U ovoj formuli doprinosi glatkom i zdravom tenu. Peptidni kompleks Peptidi stimulišu sintezu kolagena i elastina, poboljšavaju čvrstinu i elastičnost kože. Pomažu u smanjenju bora i finih linija. Jačaju barijeru i ubrzavaju regeneraciju. U ovoj formuli rade u sinergiji sa antioksidansima i hidratantima. Pogodni su za većinu tipova kože, uključujući i osetljive. Doprinosi mladalačkom i zategnutijem tenu. Kolagen Kolagen podržava strukturu kože, vraća joj elastičnost i punoću. Kada se nanosi topikalno, hidrira i omekšava površinu. Pomaže u smanjenju vidljivosti linija i vraća koži glatkiji izgled. U kombinaciji sa peptidima i hijaluronom daje sinergijski efekat. Siguran je i dobro podnošljiv. Doprinosi zdravijem, otpornijem tenu. Hijaluronska kiselina Humektant koji privlači i zadržava vodu u koži, čineći je hidriranom i punijom. Pomaže u smanjenju dehidratacionih bora. Daje osećaj mekoće i svežine. U kombinaciji sa antioksidansima štiti kožu od stresa i suvoće. Pogodna je za sve tipove kože. U ovoj formuli održava dugotrajnu vlažnost i elastičnost. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Bio-Intense Glutathione White Ampoule 2.0 kombinuje glutation, niacinamid i peptide za ujednačavanje tena, smanjenje tamnih mrlja i vraćanje sjaja. Namenjena je koži kojoj nedostaje svežina, ravnomeran ton i elastičnost.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Bio-Intense-Glutathione-White-Ampoule-2.0-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
