INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (535, 113, 'MEDI-PEEL Peptide 9 Vitanol Ampoule Pro', 'medi-peel-peptide-9-vitanol-ampoule-pro', 'Ključne prednosti: Smanjenje bora: retinoidni kompleks i peptidi stimulišu obnovu i podstiču sintezu kolagena. Učvršćivanje i tonus: devet peptida jačaju strukturu kože i vraćaju elastičnost. Hidratacija i balans: hijaluronska kiselina vraća vlagu i smanjuje osećaj suvoće. Kome je namenjena? Preporučuje se osobama posle 30. godine koje žele da smanje bore i poprave tonus, ali i onima koji žele preventivnu anti-age negu. Pogodna je za normalnu, mešovitu i suvu kožu, osim izrazito osetljive (uz oprezno uvođenje). Zašto volimo MEDI-PEEL Peptide 9 Vitanol Ampoule Pro? Peptide 9 Vitanol Ampoule Pro je napredna formula za vidljive znake starenja, posebno bore i gubitak čvrstine. Stabilizovani retinoidi (Vitanol) podstiču obnavljanje ćelija, zaglađuju teksturu i ujednačavaju ten, dok devet peptida šalje signal za pojačanu proizvodnju kolagena i elastina. Hijaluronska kiselina hidrira i ublažava moguće isušivanje uzrokovano retinoidima, dajući koži mekoću i punoću. Formula je obogaćena antioksidansima i biljnim ekstraktima koji umiruju i štite kožu. Tekstura je lagana, brzo se upija i pogodna je za noćnu rutinu. Uz redovnu upotrebu, koža postaje glađa, čvršća i svetlija, uz smanjenje vidljivosti bora i nepravilnosti. Aktivni sastojci Vitanol (retinoidni kompleks) Stabilizovani oblik retinoida koji ubrzava obnavljanje ćelija i poboljšava teksturu kože. Pomaže u smanjenju bora, ujednačavanju tena i smanjenju hiperpigmentacija. Stabilan je i podnošljiviji od čistog retinola, pa je pogodniji i za osetljiviju kožu. Radi na dubljim slojevima, stimulišući sintezu kolagena i elastina. Potrebno ga je uvoditi postepeno kako bi se izbegla iritacija. U ovoj formuli kombinuje se sa umirujućim i hidratantnim sastojcima za balans. Peptidni kompleks (9 peptida) Devet različitih peptida deluje sinergijski da poveća čvrstinu i elastičnost kože. Podstiču sintezu kolagena, poboljšavaju tonus i smanjuju vidljivost bora. Ojačavaju kožnu barijeru i čine je otpornijom. Bezbedni su za većinu tipova kože i kompatibilni sa retinoidima u nižim dozama. U ovoj formuli daju dodatnu potporu u borbi protiv starenja. Redovnim korišćenjem doprinose mlađem, svežijem izgledu kože. Hijaluronska kiselina Pruža intenzivnu hidrataciju, privlači i zadržava vodu u slojevima kože. Pomaže u smanjenju osećaja zatezanja i suvoće koji mogu pratiti upotrebu retinoida. Čini kožu mekšom i punijom, smanjuje fine linije uzrokovane dehidratacijom. Kombinovana sa peptidima i retinoidima održava balans između efikasnosti i komfora. Pogodna je i za osetljiviju kožu. U ovoj formuli doprinosi dugotrajnijoj elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Peptide 9 Vitanol Ampoule Pro kombinuje devet peptida, stabilizovane retinoide (Vitanol kompleks) i hijaluronsku kiselinu kako bi zagladila bore, poboljšala tonus i ujednačila ten. Namenjena je koži kojoj nedostaje elastičnost, punoća i sjaj, a potrebna joj je snažna, ali kontrolisana regeneracija.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Peptide-9-Vitanol-Ampoule-Pro.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
