INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (536, 113, 'Medi-Peel Premium Golden Camellia Wrinkle Essence', 'medi-peel-premium-golden-camellia-wrinkle-essence', 'Ključne prednosti: Anti-age efekat: peptidi stimulišu sintezu kolagena i smanjuju vidljivost bora. Dubinska hidratacija: hijaluronska kiselina i kolagen vraćaju vlagu i punoću. Zaštita i hranljivost: ulje zlatne kamelije štiti od oksidativnog stresa i obnavlja lipide. Kome je namenjena? Preporučuje se zreloj, umornoj i dehidriranoj koži sa izraženim borama i gubitkom elastičnosti. Pogodna je i za preventivnu anti-age negu nakon 30. godine života. Zašto volimo Medi-Peel Premium Golden Camellia Wrinkle Essence? Premium Golden Camellia Wrinkle Essence osmišljena je kao bogata, ali lagana esencija koja kombinuje intenzivnu hidrataciju i anti-age dejstvo. Peptidni kompleks šalje signal ćelijama da povećaju proizvodnju kolagena i elastina, što smanjuje fine linije i poboljšava tonus kože. Ulje zlatne kamelije, bogato antioksidansima i masnim kiselinama, vraća lipidnu ravnotežu i štiti kožu od slobodnih radikala. Hijaluronska kiselina hidrira u različitim slojevima kože, dajući osećaj punoće i glatkoće. Kolagen dodatno učvršćuje i vraća elastičnost. Tekstura esencije brzo se upija i priprema kožu za dalju negu, a redovnom upotrebom ten postaje blistav, čvrst i negovan. Aktivni sastojci Peptidni kompleks Peptidi podstiču sintezu kolagena i elastina, što dovodi do zategnutije i elastičnije kože. Njihova višeslojna aktivnost pomaže i u prevenciji nastanka bora. Deluju kao signalne molekule, stimulišući prirodne procese obnove kože. Blagi su i kompatibilni sa osetljivim tipovima kože. U ovoj formuli doprinosi lifting efektu i smanjenju linija. Dugoročno daju koži mladalačkiji izgled. Ulje zlatne kamelije Biljno ulje bogato nezasićenim masnim kiselinama, vitaminima i polifenolima. Dubinski hrani i jača barijeru kože. Doprinosi očuvanju mekoće i smanjuje transepidermalni gubitak vode. Štiti od slobodnih radikala i oksidativnog stresa. Blago je i pogodno i za osetljive tipove kože. U ovoj esenciji daje koži baršunast osećaj i dodatnu hranljivost. Hijaluronska kiselina Molekul koji vezuje vodu i obezbeđuje višeslojnu hidrataciju. Pomaže da koža postane mekša, glatkija i punija. Smanjuje pojavu finih linija uzrokovanih dehidratacijom. Blaga je i sigurna i za osetljive tipove kože. Kombinovana sa peptidima i uljem kamelije daje koži vitalnost i sjaj. U ovoj formuli pruža trenutno osveženje i dugotrajan osećaj hidratacije. Kolagen Protein koji daje strukturu i otpornost koži. Kada se primenjuje topikalno, hidrira i popravlja površinsku glatkoću. Pomaže u smanjenju bora i vraća elastičnost. U kombinaciji sa hijaluronom daje koži punoću i zdrav izgled. Posebno koristan za umornu i zrelu kožu. Doprinosi dugoročnom osećaju čvrstine i tonusa. Dodaj u listu želja Dodaj u listu želja', 'Medi-Peel Premium Golden Camellia Wrinkle Essence kombinuje ulje zlatne kamelije, peptidni kompleks i hijaluronsku kiselinu za jačanje barijere, poboljšanje tonusa i smanjenje bora. Namenjena je koži kojoj nedostaje čvrstina, sjaj i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/08/medi-peel-premium-golden-camellia-wrinkle-essence2-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
