INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (537, 113, 'Medi-peel Peptide 9 Golden Camellia Wrinkle Cream', 'medi-peel-peptide-9-golden-camellia-wrinkle-cream', 'Ključne prednosti: Obnova i zatezanje: peptidni kompleks stimuliše proizvodnju kolagena i elastina za čvršću kožu. Hranljivost i zaštita: ulje zlatne kamelije štiti od oksidativnog stresa i obnavlja lipide. Dubinska hidratacija: hijaluronska kiselina i kolagen vraćaju punoću i glatkoću tenu. Kome je namenjen? Krema je idealna za zrelu i umornu kožu koja pokazuje znakove bora, gubitka elastičnosti i suvoće. Pogodna je i kao preventivna nega od 30. godine života za održavanje tonusa i otpornosti kože. Zašto volimo MEDI-PEEL Peptide 9 Golden Camellia Wrinkle Cream? Peptide 9 Golden Camellia Wrinkle Cream je luksuzna krema kreirana za kožu koja pokazuje prve i izraženije znakove starenja. Devet različitih peptida stimulišu sintezu kolagena i elastina, što doprinosi zategnutijem i elastičnijem tenu. Ulje zlatne kamelije, bogato antioksidansima, masnim kiselinama i vitaminima, štiti od slobodnih radikala i jača barijeru kože. Kolagen i hijaluronska kiselina vraćaju vlagu i punoću, smanjujući fine linije uzrokovane dehidratacijom. Tekstura kreme je bogata, ali nelepljiva, brzo se upija i pruža osećaj mekoće. Redovnom upotrebom koža postaje glatkija, otpornija i blistavija. Aktivni sastojci Peptidni kompleks (9 peptida) Peptidi su signalne molekule koje podstiču sintezu kolagena i elastina, čime koža postaje čvršća i zategnutija. Kombinacija devet različitih peptida u ovoj formuli obezbeđuje višeslojno dejstvo – od površinskog učvršćivanja do dublje obnove. Pomažu u smanjenju bora i finih linija, ali i u prevenciji gubitka tonusa. Deluju i na jačanje zaštitne barijere, pa koža postaje otpornija na spoljne uticaje. Bezbedni su i dobro podnošljivi za većinu tipova kože. Redovnim korišćenjem doprinose dugoročnom anti-age efektu. Ulje zlatne kamelije Biljno ulje bogato nezasićenim masnim kiselinama, vitaminom E i antioksidansima. Hidrira i hrani kožu, vraćajući joj mekoću i elastičnost. Smanjuje oksidativni stres i štiti od preranog starenja izazvanog UV zracima i zagađenjem. Obnavlja lipidnu barijeru i smanjuje transepidermalni gubitak vlage. Lako se upija i ne ostavlja mastan trag. U ovoj formuli daje kremi luksuznu teksturu i dodatnu hranljivost. Kolagen Strukturni protein koji daje koži čvrstinu i elastičnost. Topikalno deluje kao hidratant i poboljšava glatkoću površinskog sloja. Pomaže u smanjenju bora nastalih zbog gubitka elastičnosti i vlage. Radi u kombinaciji sa peptidima za sinergijski anti-age efekat. Posebno je koristan za zrelu i dehidriranu kožu. U ovoj kremi doprinosi osećaju punoće i otpornosti. Hijaluronska kiselina Molekul koji može vezati i do 1000 puta više vode od svoje težine, čime obezbeđuje intenzivnu hidrataciju. Smanjuje fine linije uzrokovane dehidratacijom i vraća elastičnost. Deluje površinski i u dubljim slojevima kože, dajući osećaj punoće. Pogodna je za sve tipove kože, uključujući i osetljive. U kombinaciji sa kolagenom i uljem kamelije jača hidratantni i regenerativni efekat kreme. Rezultat je mekša, glatkija i osvežena koža. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Peptide 9 Golden Camellia Wrinkle Cream kombinuje kompleks od devet peptida, ulje zlatne kamelije i kolagen za vidljivo smanjenje bora, jačanje tonusa i dubinsku hidrataciju. Namenjena je koži kojoj nedostaje čvrstina, ujednačenost i punoća.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Peptide-9-Golden-Camellia-Wrinkle-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
