INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (539, 101, 'La Roche-Posay Anthelios UVMune 400 Hydrating Cream SPF 50+', 'la-roche-posay-anthelios-uvmune-400-hydrating-cream-spf-50', 'Ključne prednosti: Najsavremenija UV zaštita: Mexoryl 400 i patentirani XL-PROTECT sistem štite od vrlo dugih UVA zraka. Hidratacija i umirenje: glicerin i termalna voda pružaju vlagu i komfor. Postojana i sigurna formula: otporna na vodu, znoj i pesak, pogodna i za osetljivu kožu. Kome je namenjen? Preporučuje se svim tipovima kože kojima je potrebna visoka zaštita od UVA/UVB zraka, uključujući osetljivu i kožu sklonu reakcijama. Pogodna je za odrasle i decu stariju od 3 godine, za lice i telo, tokom cele godine. Zašto volimo La Roche-Posay Anthelios UVMune 400 Hydrating Cream SPF 50+? Anthelios UVMune 400 Hydrating Cream SPF 50+ pruža naprednu zaštitu kože od štetnih sunčevih zraka zahvaljujući patentiranom sistemu filtera. Novi Mexoryl 400 posebno je dizajniran da blokira vrlo duge UVA zrake koji ubrzavaju starenje i oštećuju DNK. Kombinovan sa Tinosorb S, Uvinul i drugim filterima, ovaj sistem štiti od širokog spektra UVA i UVB zraka. Dodati antioksidansi i La Roche-Posay termalna voda pomažu u neutralisanju slobodnih radikala i umiruju osetljivu kožu. Glicerin obnavlja vlagu, jača barijeru i smanjuje osećaj suvoće, pa je koža meka i zaštićena. Formula je otporna na vodu i pesak, lagana je, nemasna i nekomedogena, pogodna za svakodnevno korišćenje. Aktivni sastojci Mexoryl 400 Novi patentirani filter koji pruža zaštitu od najdužih UVA zraka, ključnih u prevenciji fotostarenja i oštećenja DNK. Stabilan je, otporan na razgradnju i kompatibilan sa drugim filterima. U ovoj formuli daje dodatni sloj sigurnosti, posebno za osetljivu i svetlu kožu. Pruža potpuniju zaštitu nego prethodne generacije filtera. Radi u sinergiji sa Tinosorb S i Mexoryl XL za maksimalni efekat. Bezbedan za svakodnevnu upotrebu i potvrđen dermatološkim testovima. Tinosorb S Širokospektralni UV filter koji štiti od UVA i UVB zraka. Fotostabilan je i daje dugotrajnu zaštitu. Doprinosi smanjenju rizika od opekotina i pigmentnih mrlja. Blag je prema osetljivoj koži i kompatibilan sa drugim filterima. Poboljšava ravnomernost i pouzdanost zaštite. U ovoj kremi dopunjuje dejstvo Mexoryl 400 i Mexoryl XL. Mexoryl XL Poznat patentirani filter koji štiti od UVA i UVB zraka i pomaže u sprečavanju fotostarenja. Stabilan je i pruža pouzdanu zaštitu čak i pri dugotrajnom izlaganju suncu. Radi u kombinaciji sa Mexoryl 400 kako bi pokrio širi spektar UVA zraka. Pogodan je za sve tipove kože i ne izaziva iritacije. Pomaže u očuvanju mladalačkog izgleda kože. Bezbedan je za svakodnevnu upotrebu. La Roche-Posay termalna voda Prirodni izvor minerala i selena poznat po umirujućim i antioksidativnim svojstvima. Smanjuje osećaj peckanja i nelagodnosti, jača kožnu barijeru. Daje osećaj svežine i mekoće pri nanošenju. Bezbedna je za lice, telo i osetljivu kožu. Pomaže u održavanju komfora čak i kod reaktivnih tipova kože. U ovoj kremi podržava dejstvo filtera i hidratantnih komponenti. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Anthelios UVMune 400 Hydrating Cream SPF 50+ sadrži novi filter Mexoryl 400, širokospektralne UV filtere i antioksidanse za pouzdanu zaštitu od UVA/UVB zraka i oksidativnog stresa. Hidratantna formula sa glicerinom i termalnom vodom jača barijeru, smanjuje osećaj zatezanja i čuva mekoću kože tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/08/16516.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
