INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (540, 101, 'La Roche-Posay Anthelios Hydrating Lotion SPF 50+', 'la-roche-posay-anthelios-hydrating-lotion-spf-50', 'Ključne prednosti: Širokospektralna zaštita: Mexoryl XL i Tinosorb S štite od UVA i UVB zraka, sprečavaju fotostarenje i oštećenja. Hidratacija i komfor: glicerin i termalna voda pružaju vlagu i smanjuju osećaj zatezanja. Otporna formula: postojana na vodi i znoju, pogodna za lice i telo. Kome je namenjen? Preporučuje se osobama svih tipova kože kojima je potrebna visoka zaštita od sunca uz hidrataciju, uključujući i osetljivu kožu. Pogodna za odrasle i decu stariju od 3 godine, kao i za lice i telo. Zašto volimo La Roche-Posay Anthelios Hydrating Lotion SPF 50+? Anthelios Hydrating Lotion SPF 50+ pruža visoku zaštitu uz negu kože, što ga čini pogodnim za svakodnevnu upotrebu, posebno tokom sunčanih dana. Patentirani XL-PROTECT sistem kombinuje stabilne filtere i antioksidante kako bi neutralisao slobodne radikale i sprečio oštećenja uzrokovana UV zračenjem i zagađenjem. Hidratantna baza sa glicerinom i La Roche-Posay termalnom vodom održava vlagu i smiruje kožu, dok lagana tekstura omogućava brzo upijanje bez masnih tragova. Formula je otporna na vodu i znoj, pa je idealna za aktivne dane i boravak napolju. Pogodna je za lice i telo, uključujući i osetljivu kožu. Redovnom primenom pomaže u prevenciji fotostarenja i održavanju zdravog izgleda kože. Aktivni sastojci Mexoryl XL Patentirani UV filter koji pruža efikasnu zaštitu od UVA i UVB zraka. Stabilan je i otporan na razgradnju pod sunčevim zracima, što produžava zaštitu. Posebno je koristan u prevenciji fotostarenja i tamnih mrlja. Dobro se podnosi, ne izaziva iritacije i bezbedan je za osetljive tipove kože. U ovoj formuli kombinuje se sa drugim filterima radi šire pokrivenosti. Doprinosi zaštiti ćelija od oštećenja izazvanih UV zracima. Tinosorb S Širokospektralni filter koji štiti od UVA i UVB zraka visoke energije. Fotostabilan je, pa obezbeđuje dugotrajnu zaštitu. Posebno pomaže u zaštiti od oštećenja DNK i prevenciji preuranjenog starenja. Pogodan je za osetljivu kožu i ne izaziva iritacije. Radi u sinergiji sa Mexoryl XL-om za bolju efikasnost. U ovoj formuli doprinosi transparentnoj i udobnoj teksturi. Vitamin E (Tokoferol) Snažan antioksidans koji neutralizuje slobodne radikale. Pomaže u smanjenju oksidativnog stresa i jača zaštitnu barijeru kože. Umiruje i smanjuje iritacije izazvane spoljnim faktorima. Radi zajedno sa UV filterima na prevenciji oštećenja. Bezbedan je za svakodnevnu upotrebu. Daje dodatni sloj zaštite i negovan izgled kože. Glicerin Humektant koji privlači i zadržava vlagu u površinskim slojevima kože. Sprečava suvoću i održava mekoću i elastičnost. Posebno koristan tokom izlaganja suncu kada koža gubi vlagu. Dobro se kombinuje sa antioksidantima i UV filterima. Bezbedan je za sve tipove kože, uključujući i osetljive. U ovoj formuli daje osećaj hidratacije tokom celog dana. La Roche-Posay termalna voda Prirodno bogata selenom i mineralima, poznata po umirujućim i antioksidativnim svojstvima. Smanjuje osećaj peckanja i iritacije. Jača prirodnu odbranu kože. Pruža osećaj svežine i mekoće tokom nošenja. Bezbedna je i za najosetljiviju kožu. U ovoj formuli podržava smirujući i hidrirajući efekat losiona. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Anthelios Hydrating Lotion SPF 50+ kombinuje UV filtere širokog spektra (Mexoryl XL, Tinosorb S) i antioksidanse sa hidratantnim sastojcima kako bi istovremeno štitila i negovala kožu. Namenjena je koži kojoj je potrebna pouzdana zaštita od UVA/UVB zraka uz dodatnu hidrataciju i jačanje barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Anthelios-Hydrating-Lotion-SPF-50.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
