INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (542, 113, 'Medi-peel Bakuchiol Miracle Firming Ampoule', 'medi-peel-bakuchiol-miracle-firming-ampoule', 'Ključne prednosti: Biljni retinol: bakučiol pruža efekat sličan retinolu, ali je blag i pogodan za osetljivu kožu. Učvršćivanje i zaglađivanje: peptidi i antioksidansi stimulišu sintezu kolagena i poboljšavaju tonus. Dubinska hidratacija: hijaluronska kiselina vraća vlagu i punoću, čineći kožu mekšom. Kome je namenjena? Preporučuje se osobama koje žele da ublaže prve i izraženije znakove starenja, poput gubitka čvrstine i bora, ali imaju osetljivu ili suvu kožu koja loše reaguje na retinol. Pogodna je za sve tipove kože, uključujući i reaktivne. Zašto volimo MEDI-PEEL Bakuchiol Miracle Firming Ampoule? Bakuchiol Miracle Firming Ampoule pruža prednosti retinola bez iritacija koje on može izazvati. Bakučiol podstiče proizvodnju kolagena i elastina, pomažući koži da bude čvršća i glađa, a istovremeno deluje antioksidativno i ublažava znakove fotostarenja. Peptidni kompleks dodatno stimuliše obnovu tkiva, dok hijaluronska kiselina hidrira i smanjuje pojavu finih linija uzrokovanih suvoćom. Ova formula je pogodna i za osetljive tipove kože jer ne izaziva perutanje ni crvenilo, već ostavlja kožu mekom i negovanom. Tekstura je lagana, brzo se upija i lako se uklapa u jutarnju i večernju rutinu. Redovnom upotrebom koža deluje elastičnije, svetlija je i vizuelno odmornija. Aktivni sastojci Bakuchiol Biljni anti-age sastojak poznat kao „biljni retinol“ koji stimuliše sintezu kolagena i elastina. Deluje antioksidativno, štiti od slobodnih radikala i ublažava oštećenja nastala sunčevim zračenjem. Za razliku od retinola, blag je i ne izaziva ljuštenje ni iritacije, pa je pogodan i za osetljive tipove kože. Pomaže u smanjenju bora i finih linija, ujednačava ton i poboljšava elastičnost. U ovoj formuli je stabilan i efikasan u kombinaciji sa peptidima. Redovnom upotrebom čini ten ujednačenijim i odmornijim. Peptidni kompleks Peptidi su kratki lanci aminokiselina koji služe kao „gradivni blokovi“ proteina poput kolagena i elastina. Podstiču obnovu ćelija i zatezanje kože, smanjujući vidljivost bora. Povećavaju otpornost kože i doprinose njenoj punoći. Dodatno pomažu u regeneraciji nakon oštećenja izazvanih spoljnim faktorima. U ovoj formuli rade sinergijski sa bakučiolom za bolji anti-age efekat. Bezbedni su i dobro podnošljivi za većinu tipova kože. Hijaluronska kiselina Humektant koji privlači i zadržava vodu u koži, vraćajući joj vlažnost i punoću. Pomaže da koža deluje glatko i elastično, smanjujući pojavu finih linija izazvanih suvoćom. Radi u površinskim i dubljim slojevima, čime pruža višeslojnu hidrataciju. Posebno važna kod anti-age formula jer sprečava osećaj zatezanja i suvoće. Dobro se kombinuje sa bakučiolom i peptidima, pojačavajući osećaj mekoće. U ovoj ampuli doprinosi trenutnom osveženju tena. Dodaj u listu želja Dodaj u listu želja', 'MEDI-PEEL Bakuchiol Miracle Firming Ampoule koristi bakučiol – biljni retinol – u kombinaciji sa peptidima i hijaluronskom kiselinom za vidljivo učvršćivanje i zaglađivanje kože. Namenjena je koži kojoj nedostaje elastičnost, punoća i ujednačen ten, a želi blagi, ali efikasan anti-age tretman.', 'https://beauty-health.rs/wp-content/uploads/2025/08/MEDI-PEEL-Bakuchiol-Miracle-Firming-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
