INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (543, 101, 'La Roche-Posay Lipikar Balm APM', 'la-roche-posay-lipikar-balm-apm', 'Ključne prednosti: Obnova barijere kože: prebiotički kompleks i ši buter jačaju mikrobiom i hidriraju kožu. Umirujuće dejstvo: niacinamid smanjuje iritacije i svrabež. Pogodan za celu porodicu: bez mirisa, bez parabena, siguran za bebe, decu i odrasle. Kome je namenjen? Balzam je namenjen suvoj, veoma suvoj, osetljivoj i atopijskoj koži. Preporučuje se bebama, deci i odraslima koji se bore sa suvoćom, svrabom ili crvenilom. Zašto volimo La Roche-Posay Lipikar Balm APM? Lipikar Balm AP+M je bogata, ali lagana krema koja brzo donosi olakšanje suvoj i iritiranoj koži. Aqua Posae Filiformis, patentirani prebiotički sastojak, pomaže u vraćanju ravnoteže mikrobioma i jačanju otpornosti kože. Niacinamid smiruje svrab, crvenilo i osećaj neprijatnosti, dok ši buter nadoknađuje lipide i čini kožu mekšom. Formulisan je tako da ne ostavlja mastan trag i lako se razmazuje, što ga čini pogodnim i za decu. Dermatološki je testiran i pogodan i za kožu sklonu atopiji i ekcemima. Redovnom upotrebom produžava periode stabilnosti kože i smanjuje učestalost iritacija. Aktivni sastojci Aqua Posae Filiformis Patentirani prebiotički kompleks koji vraća ravnotežu mikrobioma i jača prirodnu zaštitu kože. Pomaže u smanjenju učestalosti suvih epizoda i svraba. Stabilizuje kožu i doprinosi dugoročnom osećaju komfora. Posebno važan kod atopijskog dermatitisa i kože sklone iritacijama. Radi u sinergiji sa ostalim sastojcima za bolju toleranciju. Dugotrajno jača otpornost kože. Niacinamid Vitamin B3 poznat po umirujućem i protivupalnom delovanju. Smanjuje crvenilo i iritacije, jača barijeru i povećava toleranciju kože. Doprinosi hidrataciji i poboljšava elastičnost. Blag je i pogodan i za osetljive tipove kože. U ovoj formuli pomaže da balzam bude efikasan, ali blag. Pruža zaštitu od spoljašnjih faktora i ubrzava oporavak kože. Ši butera Prirodni emolijent bogat lipidima koji hrani i omekšava kožu. Obnavlja zaštitni sloj i sprečava gubitak vlage. Daje osećaj mekoće i smanjuje hrapavost. Siguran je za bebe i osetljivu kožu. Posebno koristan kod ispucale ili grube kože. U ovoj formuli doprinosi bogatoj, ali nelepljivoj teksturi. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Lipikar Balm AP+M obnavlja i jača zaštitnu barijeru kože zahvaljujući prebiotičkom kompleksu Aqua Posae Filiformis, niacinamidu i maslacu od ši butera. Formulisan je da umiri suvoću, svrabež i sklonost iritacijama, čineći kožu mekom i otpornom.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Lipikar-Syndet-AP-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
