INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (545, 101, 'La Roche-Posay Pure Vitamin C12 Serum', 'la-roche-posay-pure-vitamin-c12-serum', 'Ključne prednosti: Visoka koncentracija vitamina C: posvetljuje, ujednačava i stimuliše sintezu kolagena. Eksfolijacija i obnova: salicilna kiselina otvara pore i zaglađuje teksturu. Umirivanje kože: neurosensin smanjuje osećaj nelagodnosti i jača barijeru. Kome je namenjen? Serum je idealan za osobe sa prvim znacima starenja, sivim ili umornim tenom, neujednačenom teksturom i umerenom osetljivošću kože. Pogodan je za odrasle svih tipova kože, uključujući i osetljive, osim onih koji teško podnose kiseline. Zašto volimo La Roche-Posay Pure Vitamin C12 Serum? Pure Vitamin C12 Serum je osmišljen da odgovori na prve znakove starenja i neujednačen ten. Visoka koncentracija čistog vitamina C (askorbinske kiseline) deluje kao antioksidans, posvetljuje kožu i stimuliše proizvodnju kolagena za čvršći i zategnutiji izgled. Salicilna kiselina, u manjoj koncentraciji, nežno eksfolira, uklanja mrtve ćelije i pomaže prodiranju vitamina C u dublje slojeve. Neurosensin smiruje osetljivost i ublažava crvenilo, što formulu čini pogodnom i za reaktivne tipove kože. Tekstura je lagana i brzo se upija, pa je serum pogodan za jutarnju rutinu i može se koristiti ispod kreme ili šminke. Redovnom upotrebom ten postaje svetliji, ujednačeniji, a bore i fine linije manje vidljive. Aktivni sastojci Vitamin C (12% askorbinska kiselina) Vitamin C je snažan antioksidans koji neutralizuje slobodne radikale, štiteći kožu od oksidativnog stresa izazvanog UV zracima i zagađenjem. Pospješuje sintezu kolagena, što doprinosi čvrstoći i elastičnosti kože. Posvetljuje ten i ublažava neujednačenost, tamne mrlje i umoran izgled. Deluje površinski i u dubljim slojevima kože, pa su efekti vidljivi i kratkoročno i dugoročno. Osetljiv je na svetlost i vazduh, pa se koristi u stabilizovanoj formuli kako bi zadržao efikasnost. U koncentraciji od 12% daje odličan balans između rezultata i podnošljivosti. Salicilna kiselina Beta-hidroksi kiselina koja deluje eksfolijativno, otapa višak sebuma i uklanja mrtve ćelije. Pomaže u otpušavanju pora i smanjuje nepravilnosti, dok istovremeno zaglađuje površinu kože. Poboljšava ujednačenost tena i pojačava dejstvo drugih aktivnih sastojaka, posebno vitamina C. Ima i blago protuupalno dejstvo, što je važno kod kože sklone crvenilu. Deluje dovoljno nežno u ovoj formuli da se koristi svakodnevno. Obezbeđuje čistiju, glatkiju i prozračniju kožu. Neurosensin Peptid koji smiruje osetljivost i iritacije. Deluje na nervne završetke u koži, smanjujući osećaj neprijatnosti, peckanja ili crvenila. Podržava barijernu funkciju i povećava toleranciju kože na aktivne sastojke. Zbog blagosti i efikasnosti pogodan je i za osetljive i reaktivne tipove kože. U kombinaciji sa vitaminom C i salicilnom kiselinom daje formuli balans efikasnosti i komfora. Dugoročno doprinosi mirnijem, otpornijem tenu. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Pure Vitamin C12 Serum kombinuje 12% čistu askorbinsku kiselinu (vitamin C) sa salicilnom kiselinom i neurosensinom kako bi posvetlio ten, ublažio bore i umirio osetljivost. Namenjen je koži kojoj nedostaje sjaj, elastičnost i ujednačenost.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Pure-Vitamin-C12-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
