INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (547, 101, 'La Roche-Posay Hyalu B5 Serum', 'la-roche-posay-hyalu-b5-serum', 'Ključne prednosti: Dubinska hidratacija: hijaluronske kiseline zadržavaju vlagu i smanjuju dehidratacione linije. Obnova i smirenje: vitamin B5 i madecassoside pomažu u regeneraciji i jačanju barijere kože. Lagani osećaj: gel-serum tekstura brzo se upija, pogodna za sve tipove kože. Kome je namenjen? Serum je idealan za osobe koje primećuju prve bore, dehidrataciju ili gubitak punoće, kao i za one sa osetljivom i reaktivnom kožom. Pogodan je za sve tipove kože, uključujući masnu i kombinovanu. Zašto volimo La Roche-Posay Hyalu B5 Serum? Hyalu B5 Serum je osmišljen da odgovori na prve znake umora i starenja kože. Dve vrste hijaluronske kiseline različite molekulske mase obezbeđuju hidrataciju na površini i u dubljim slojevima, čineći kožu punijom i glađom. Vitamin B5 umiruje, smanjuje osećaj zatezanja i podržava procese obnove kože, dok madecassoside stimuliše fibroblaste i pomaže u oporavku od spoljašnjih stresora. Tekstura je lagana, osvežavajuća i brzo se upija, pa se serum lako uklapa u dnevnu i noćnu rutinu. Redovnom upotrebom koža deluje hidrirano, elastično i osvetljeno, a sitne linije postaju manje primetne. Dermatološki je testiran i pogodan i za osetljivu kožu. Aktivni sastojci Hijaluronska kiselina (visoke i niske molekulske mase) Ova kombinacija pruža višeslojnu hidrataciju – molekuli veće mase zadržavaju vlagu na površini, dok manji prodiru dublje. Smanjuje pojavu finih linija nastalih zbog suvoće. Povećava elastičnost i daje koži puniji izgled. Prirodno vezuje vodu, čineći kožu mekom i glatkom. Efikasna je i kod osetljivih tipova kože. Ključni je sastojak za osvežavanje i „plump“ efekat. Pantenol (Vitamin B5) Poznat po svom umirujućem i obnavljajućem dejstvu. Pomaže u zadržavanju vlage i jačanju zaštitne barijere. Ublažava iritacije i crvenilo, pa je odličan za osetljivu kožu. Doprinosi oporavku kože nakon izlaganja spoljnim faktorima. Čini kožu mekom, elastičnom i otpornijom. U ovoj formuli deluje u sinergiji sa hijaluronskom kiselinom za maksimalan efekat. Madecassoside Ekstrakt biljke Centella asiatica poznat po regenerativnom dejstvu. Umiruje i podržava obnavljanje kože, naročito kada je pod stresom ili izložena spoljnim agresorima. Stimuliše fibroblaste, pa doprinosi boljoj elastičnosti i otpornosti kože. Ublažava crvenilo i osetljivost. Blag je i dobro podnošljiv čak i kod reaktivne kože. U kombinaciji sa B5 i hijaluronom čini serum efikasnijim i sveobuhvatnijim. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Hyalu B5 Serum intenzivno hidrira i vraća punoću koži zahvaljujući kombinaciji dve vrste hijaluronske kiseline, vitamina B5 i madecassoside-a. Formulisan je da umiri, obnovi i učini kožu elastičnijom i svežijom, bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2020/08/3-3337875583626-la-roche-posay-hyalu-b5-serum-protiv-bora-osetljiva-koza.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
