INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (548, 101, 'La Roche-Posay Effaclar Duo+ SPF 30', 'la-roche-posay-effaclar-duo-spf-30', 'Ključne prednosti: Dvostruko dejstvo: tretira nepravilnosti i sprečava nastanak novih akni. UV zaštita: širokospektralni filteri (SPF 30) štite od sunca i sprečavaju tamnjenje fleka. Lagana tekstura: brzo se upija, matira i pogodna je za svakodnevnu upotrebu. Kome je namenjena? Namenjena je masnoj, kombinovanoj i problematičnoj koži, sklonoj aknama i tamnim flekama. Pogodna za adolescente i odrasle, posebno tokom dana kada je neophodna zaštita od sunca. Zašto volimo La Roche-Posay Effaclar A.Z. gel-krema? Effaclar Duo+ SPF 30 je namenjen masnoj i problematičnoj koži kojoj je potrebna i zaštita od sunca. Kombinuje aktivne sastojke za tretman nepravilnosti i posvetljivanje postupalnih tragova sa UV filterima koji sprečavaju njihovo dodatno tamnjenje. Niacinamid i procerad smiruju upale i ojačavaju barijeru kože, dok LHA i salicilna kiselina otpušavaju pore i poboljšavaju teksturu tena. Krema pomaže u smanjenju crvenila i neravnomernog tena, a SPF 30 pruža zaštitu od UVA i UVB zraka, ključnu za prevenciju ožiljaka i fleka. Tekstura je lagana, nemasna, brzo se upija i pogodna je i kao podloga za šminku. Redovnom upotrebom koža postaje čistija, ujednačenija i otpornija na spoljne faktore. Aktivni sastojci Niacinamid Vitamin B3 smanjuje crvenilo, umiruje iritacije i jača prirodnu barijeru kože. Reguliše lučenje sebuma i pomaže u obnavljanju oštećenja nastalih upalama. Deluje protivupalno i antioksidativno, štiti kožu od spoljašnjih faktora. U ovoj formuli pomaže i u smanjenju vidljivosti postupalnih tragova. Pogodan je za osetljivu kožu i dobro se kombinuje sa UV filterima. Dugoročno doprinosi ujednačenijem tenu. Procerad Keramidni derivat koji pomaže u obnovi i jačanju barijere kože. Smanjuje sklonost ka flekama i posvetljuje postojeće tragove. Pruža zaštitu od spoljašnjih stresora i poboljšava elastičnost kože. U kombinaciji sa niacinamidom daje koži otpornost i zdrav izgled. Posebno važan za kožu sklonu nepravilnostima i hiperpigmentacijama. Deluje nežno i pogodan je za svakodnevnu upotrebu. LHA (Lipohidroksi kiselina) Derivat salicilne kiseline koji deluje eksfolijativno i otvara pore. Daje blagi, kontrolisani piling bez iritacije. Pomaže u smanjenju nepravilnosti i zaglađuje teksturu kože. Poboljšava prodiranje drugih aktivnih sastojaka. Posebno je pogodan za masnu kožu sklonu aknama. U ovoj formuli pruža čist ten bez agresivnog delovanja. SPF filteri (Mexoryl XL i dr.) Širokospektralni filteri koji štite kožu od UVA i UVB zraka. Sprečavaju tamnjenje postupalnih fleka i preuranjeno starenje kože. Formulisani su tako da budu lagani i nekomedogeni, pa ne začepljuju pore. Važni su za dnevnu negu kože sklone nepravilnostima jer UV zračenje pogoršava tragove od akni. Obezbeđuju pouzdanu zaštitu tokom celog dana. Lako se uklapaju u rutinu i kao podloga za šminku. https://www.youtube.com/watch?v=3XcBAR_DWWQ&ab_channel=LaRoche-PosaySrbija Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Effaclar Duo+ SPF 30 istovremeno tretira nepravilnosti i štiti kožu od UV zraka. Sadrži niacinamid, procerad, LHA i SPF filtere koji smanjuju pojavu akni i postupalnih fleka, ujednačavaju ten i štite od oštećenja izazvanih suncem.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Effaclar-Duo-SPF-30.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
