INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (549, 101, 'La Roche-Posay Effaclar A.Z. gel-krema', 'la-roche-posay-effaclar-a-z-gel-krema', 'Ključne prednosti: Ciljano delovanje na akne: pomaže u smanjenju bubuljica i mitesera. Umirivanje i obnova: niacinamid i pantenol smanjuju crvenilo i štite osetljivu kožu. Lagana formula: brzo se upija, matira i ne ostavlja masni trag. Kome je namenjena? Namenjena je masnoj, kombinovanoj i problematičnoj koži, sklonoj aknama i povremenim iritacijama. Prikladna je za tinejdžere i odrasle, uključujući i one sa osetljivom kožom. Zašto volimo La Roche-Posay Effaclar A.Z. gel-krema? Ova gel-krema je osmišljena za kožu koja ima nepravilnosti, ali je istovremeno osetljiva i sklona isušivanju. Niacinamid umiruje i smanjuje crvenilo, dok pantenol vraća vlagu i ubrzava regeneraciju kože. Eksfolijanti – salicilna kiselina i LHA – otpušavaju pore, smanjuju začepljenja i zaglađuju površinu kože. Tekstura je lagana, neljepljiva i brzo se upija, pa je pogodna i za jutarnju rutinu i za kombinovanje sa šminkom. Redovnom upotrebom smanjuje nepravilnosti, ujednačava ten i čini kožu otpornijom na spoljne uticaje. Pogodna je i kao dopuna terapijama protiv akni, jer istovremeno neguje i smiruje. Aktivni sastojci Niacinamid Vitamin B3 smanjuje crvenilo i umiruje iritacije, jačajući prirodnu barijeru kože. Pomaže u regulisanju lučenja sebuma i ubrzava obnavljanje ćelija. Deluje protivupalno i antioksidativno, što koži daje otpornost. Odličan je za umirivanje kože tokom tretmana protiv akni. U ovoj formuli doprinosi da koža izgleda mirnije i ujednačenije. Pogodan je i za osetljive tipove kože. Pantenol (Vitamin B5) Poznat po regenerativnim i hidratantnim svojstvima. Umiruje iritacije, smanjuje osećaj zatezanja i suvoće. Pomaže u bržem obnavljanju kože nakon tretmana. Daje osećaj mekoće i komfora, što je posebno važno kod reaktivne kože. U kombinaciji sa niacinamidom jača ukupni efekat smirenja i obnove. Dobro se podnosi kod svakodnevne upotrebe. Salicilna kiselina Beta-hidroksi kiselina koja čisti pore i uklanja višak sebuma. Ima protuupalna svojstva i pomaže u smanjenju bubuljica i mitesera. Deluje na površinu i unutar pora, smanjujući pojavu novih nepravilnosti. Pogodna je za masnu i problematičnu kožu. Ova koncentracija je blaga i prilagođena za redovnu upotrebu bez preterane iritacije. U ovoj formuli uparena je sa LHA za širi efekat pilinga. LHA (Lipohidroksi kiselina) Derivat salicilne kiseline sa sporijim otpuštanjem, koji blago eksfolira površinu kože. Poboljšava teksturu, smanjuje sitne nepravilnosti i omogućava dublje prodiranje drugih aktivnih sastojaka. Daje ten koji je glađi i ujednačeniji. Blag je i dobro podnošljiv čak i kod osetljive kože. Pomaže u kontroli sebuma i sprečavanju novih izbijanja. U ovoj formuli doprinosi da efekat pilinga bude postepen i siguran. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Effaclar A.Z. gel-krema smanjuje nepravilnosti, umiruje i hidrira kožu bez osećaja težine. Kombinacija niacinamida, pantenola i eksfolijanata (salicilna kiselina i LHA) čisti pore, smanjuje crvenilo i jača barijeru kože.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Effaclar-A.Z.-gel-krema-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
