INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (550, 101, 'La Roche-Posay Cicaplast B5 Spray', 'la-roche-posay-cicaplast-b5-spray', 'Ključne prednosti: Brzo umirivanje: smanjuje osećaj peckanja, suvoće i neprijatnosti na koži. Obnova kože: pantenol podržava regeneraciju i jača barijeru. Praktična primena: sprej format za lako nanošenje i osvežavanje tokom dana. Kome je namenjen? Preporučuje se za osetljivu, nadraženu ili dehidriranu kožu, kao i kod stanja koja zahtevaju dodatnu negu posle dermatoloških procedura. Pogodan je za odrasle, decu i bebe starije od 3 meseca. Zašto volimo La Roche-Posay Cicaplast B5 Spray? Cicaplast B5 Spray je idealno rešenje za trenutke kada koži treba brzo smirenje i zaštita. Pantenol (5%) umiruje i hidrira, dok termalna voda La Roche-Posay donosi antioksidativnu zaštitu i smanjuje osetljivost. Sprej formula omogućava higijensko nanošenje bez dodirivanja kože, što ga čini pogodnim i za nadražene, osetljive ili postproceduralne regije. Osim lica, može se koristiti na telu, pa čak i kod blažih iritacija izazvanih spoljnim faktorima poput vetra, hladnoće ili trljanja. Brzo se upija, ne ostavlja trag i može se nanositi više puta dnevno. Redovnom upotrebom, koža postaje hidrirana, umirena i otpornija na spoljne agresore. Aktivni sastojci Pantenol (Vitamin B5) Deluje umirujuće, smanjuje iritacije i nelagodnosti na koži. Istovremeno poboljšava hidrataciju, čime koži vraća mekoću i elastičnost. Pantenol ubrzava prirodne procese regeneracije, pa je odličan kod kože koja se oporavlja nakon spoljašnjih stresova ili dermatoloških tretmana. Stabilizuje barijeru, smanjujući transepidermalni gubitak vode. Blag je i dobro podnošljiv, što ga čini pogodnim za svakodnevnu upotrebu. U ovoj formuli prisutan je u koncentraciji koja omogućava intenzivno smirivanje kože. Termalna voda La Roche-Posay Bogata mineralima i selenom, pruža antioksidativnu zaštitu i pomaže koži da se bori protiv slobodnih radikala. Umiruje osetljivost i smanjuje osećaj peckanja. Osim toga, doprinosi hidrataciji, čineći kožu prijatnijom i otpornijom. Deluje sinergijski sa pantenolom u obnovi i smirivanju kože. Posebno pogodna kod reaktivne i nadražene kože. Koristi se i kod dermatoloških stanja zbog svog umirujućeg efekta. Madecassoside Aktivni molekul iz biljke Centella Asiatica poznat po regenerativnom dejstvu. Pomaže u obnavljanju kože i smanjuje znakove upale. Ubrzava zarastanje i doprinosi jačanju barijere kože. Blag i efikasan, posebno kod osetljive kože sklone iritacijama. Pruža dodatnu zaštitu od spoljašnjih stresora. U kombinaciji sa pantenolom stvara optimalno okruženje za oporavak kože. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Cicaplast B5 Spray smiruje iritacije i pomaže obnovu kože zahvaljujući pantenolu (vitamin B5) i termalnoj vodi La Roche-Posay. Laka tekstura u spreju hidrira, osvežava i obnavlja barijeru kože bez lepljivog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Cicaplast-B5-Spray.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
