INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (551, 101, 'La Roche-Posay Effaclar Ultra koncentrisani serum', 'la-roche-posay-effaclar-ultra-koncentrisani-serum', 'Ključne prednosti: Trostruki eksfolijant: glikolna, salicilna i LHA kiselina ciljano otklanjaju mrtve ćelije i otpušene pore. Smanjenje nepravilnosti: vidljivo utiče na akne, postupalne fleke i neujednačen ten. Umirujuće i balansirajuće dejstvo: niacinamid ublažava crvenilo i jača barijeru kože. Kome je namenjen? Serum je namenjen masnoj, kombinovanoj i problematičnoj koži, sklonoj aknama i neujednačenoj teksturi. Pogodan je za odrasle i tinejdžere koji žele ciljanu negu protiv nepravilnosti i proširenih pora. Zašto volimo La Roche-Posay Effaclar Ultra koncentrisani serum? Ovaj serum je razvijen za kožu sa upornim nepravilnostima i potrebom za efikasnim pilingom, ali bez agresivnog pristupa. Trostruka kombinacija kiselina – glikolne, salicilne i LHA – deluje na površinu i dublje slojeve kože, uklanja mrtve ćelije i smanjuje začepljenja. Ten postaje ujednačeniji, pore deluju manje vidljive, a površinske fleke blede. Niacinamid ublažava potencijalne iritacije, pomaže u smirivanju crvenila i jača odbrambenu funkciju kože. Tekstura je lagana, brzo se upija i ne ostavlja mastan trag, što ga čini pogodnim i za dnevnu i za noćnu rutinu. Redovnom upotrebom koža postaje čistija, glađa i vidljivo zdravija. Aktivni sastojci Glikolna kiselina (3 %) Alfa-hidroksi kiselina koja nežno uklanja mrtve ćelije sa površine kože. Pomaže u posvetljivanju tena i smanjenju sitnih ožiljaka. Podstiče obnavljanje ćelija i zaglađuje teksturu. Blaga koncentracija od 3 % pogodna je i za osetljiviju kožu uz pravilno korišćenje. Redovnom upotrebom doprinosi blistavijem i ujednačenijem tenu. U sinergiji sa drugim kiselinama pojačava efekat čišćenja. Salicilna kiselina (1,5 %) Beta-hidroksi kiselina koja prodire u pore i uklanja višak sebuma i začepljenja. Smanjuje pojavu akni i mitesera. Deluje protuupalno, ublažava crvenilo i umiruje. Pogodna za masnu i kombinovanu kožu, naročito sklonu nepravilnostima. Redovna upotreba pomaže u prevenciji novih izbijanja. U ovoj formuli je balansirana tako da ne isušuje preterano kožu. LHA (0,45 %) Lipohidroksi kiselina je derivat salicilne kiseline sa sporijim, kontrolisanim delovanjem. Daje blagi, ali postojan piling i posvetljava površinu kože. Pomaže u ujednačavanju tena i smanjenju sitnih nepravilnosti. Dobro se podnosi i kod osetljivijih tipova kože. Poboljšava prodiranje drugih aktivnih sastojaka u dublje slojeve. U kombinaciji sa salicilnom kiselinom pruža širi spektar dejstva. Niacinamid Vitamin B3 poznat po svojim višestrukim benefitima – smanjuje crvenilo, ujednačava ton i jača barijeru kože. Pomaže u smirivanju iritacija izazvanih kiselinama. Reguliše lučenje sebuma i umanjuje vidljivost pora. Pruža antioksidativnu zaštitu i čini ten otpornijim na spoljne faktore. U kombinaciji sa kiselinama smanjuje rizik od preosetljivosti. Dugoročno doprinosi zdravijem i uravnoteženijem tenu. https://www.youtube.com/watch?v=Qa4CDmwHD2g&ab_channel=LaRoche-PosaySrbija Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Effaclar Ultra Koncentrisani serum kombinuje snažnu, ali nežnu formulu sa 3% glikolne, 1,5% salicilne i 0,45% LHA kiseline za piling i pročišćavanje kože. Deluje na začepljene pore, neravnu teksturu i postupalne fleke, uz dodatak niacinamida koji umiruje i jača barijeru kože.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Effaclar-Ultra-koncentrisani-serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
