INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (552, 101, 'La Roche-Posay Effaclar Gel', 'la-roche-posay-effaclar-gel', 'Ključne prednosti: Dubinsko čišćenje: uklanja višak masnoće i nečistoće bez narušavanja barijere kože. Umirujuće dejstvo: termalna voda smanjuje osećaj nelagodnosti i crvenilo. Prilagođen osetljivoj koži: formula bez sapuna i parabena, pogodna za svakodnevnu upotrebu. Kome je namenjen? Ovaj gel je idealan za masnu, kombinovanu i osetljivu kožu, sklonu nesavršenostima. Pogodan je za tinejdžere i odrasle koji žele efikasno, ali blago čišćenje. Zašto volimo La Roche-Posay Effaclar Gel? Effaclar Gel je formulisan tako da odgovara koži koja se lako masti, a istovremeno je osetljiva. Čisti temeljno, ali nežno – uklanja nečistoće i višak sebuma, ne ostavljajući osećaj zatezanja. Termalna voda iz La Roche-Posay izvora bogata je mineralima i antioksidansima, pa smiruje iritacije i jača kožnu barijeru. Surfaktanti su pažljivo odabrani kako bi efikasno očistili pore, a da ne naruše prirodnu ravnotežu kože. Tekstura je lagana, pravi blagu penu i lako se ispira, što čišćenje čini jednostavnim i prijatnim. Redovnom upotrebom koža deluje svežije, čišće i spremnije za dalju negu. Aktivni sastojci Termalna voda La Roche-Posay Prirodna termalna voda bogata je selenom i mineralima koji umiruju i štite kožu. Doprinosi smanjenju crvenila i nelagodnosti, posebno kod osetljive kože. Ima antioksidativno dejstvo koje pomaže u zaštiti od spoljašnjih stresora. Redovnim korišćenjem jača prirodnu odbrambenu funkciju kože. Pruža osećaj osveženja i hidriranosti nakon čišćenja. Ključna je za održavanje balansa kod svakodnevnog umivanja. Blagi surfaktanti Formulisani da uklanjaju nečistoće i višak masnoće bez iritacije. Ne sadrže sapune niti agresivne deterdžente, što ih čini pogodnim i za osetljivu kožu. Održavaju prirodan pH kože, što je važno za očuvanje barijere. Sprečavaju osećaj suvoće i zatezanja nakon pranja. Omogućavaju temeljno, a blago čišćenje čak i kod čestog korišćenja. Daju gelu prijatnu, blagu penu koja se lako ispira. Cink PCA (u nekim formulacijama) Poznat po svom matirajućem i antibakterijskom dejstvu, cink PCA pomaže u kontroli sebuma. Smanjuje sjaj i sprečava začepljenje pora. Doprinosi čistijem i ujednačenijem tenu. Ima i blagi umirujući efekat na kožu sklonu nepravilnostima. Pogodan je za masnu i kombinovanu kožu. U kombinaciji sa surfaktantima pojačava efekat čišćenja bez isušivanja. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Effaclar Gel nežno uklanja višak sebuma i nečistoće, a da ne isušuje kožu. Obogaćen termalnom vodom La Roche-Posay i pažljivo odabranim blagim surfaktantima, čisti pore, umiruje i ostavlja osećaj svežine.', 'https://beauty-health.rs/wp-content/uploads/2025/08/La-Roche-Posay-Effaclar-Gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
