INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (554, 109, 'Manyo Panthetoin Essence Toner', 'manyo-panthetoin-essence-toner', 'Ključne prednosti: Umirivanje: Panthenol i madecassoside deluju sinergijski na smanjenje crvenila i iritacija. Obnova barijere: Pomaže koži da se oporavi nakon upotrebe agresivnih proizvoda, naročito korisno za retinol rutine. Hidratacija + zaštita: Obezbeđuje sloj hidratacije koji zadržava vlagu i štiti kožu od spoljnih stresora. Kome je namenjena? Osetljivoj, dehidriranoj i reaktivnoj koži; savršen je i za kožu narušene barijere, nakon kiselina, retinola ili prekomernog sunčanja. Zašto volimo Manyo Panthetoin Essence Toner? Manyo Panthetoin Essence Toner nudi blagu, ali funkcionalnu negu za kožu kojoj je potrebna obnova i smirenje. Njegova tekstura je između tonika i esencije, što omogućava efikasnije prodiranje aktivnih sastojaka u epiderm. Zbog prisustva sastojaka koji imaju sinergijsko delovanje na obnovu barijere, posebno je koristan u rutini nakon kiselina, retinoida ili fizičkih oštećenja kože. Koža postaje otpornija, manje reaktivna i vizuelno smirenija već nakon nekoliko dana upotrebe. Formulacija je minimalistička, ali klinički promišljena – oslanja se na dokazane sastojke bez iritativnih dodataka. Aktivni sastojci Pantenol (vitamin B5) Pantenol je provitamin B5, poznat po svojoj sposobnosti da veže i zadrži vlagu u koži. U epidermu se pretvara u pantotensku kiselinu, čime pospešuje prirodni proces zarastanja i regeneracije. Ima umirujući efekat i brzo ublažava crvenilo, peckanje i osećaj zatezanja. Takođe deluje kao barijerni ojačivač, podstičući sintezu lipida u rožnatom sloju. Efikasan je i kod manjih upala i iritacija izazvanih mehaničkim ili hemijskim stresorima. Njegovo delovanje je dokazano u kliničkim studijama kod tretmana kože sklone dermatološkim poremećajima. Madecassoside Madecassoside je bioaktivna komponenta iz Centella Asiatica biljke koja ima izražena antiinflamatorna i antioksidativna svojstva. Deluje ciljano na smanjenje inflamatornih markera u koži, ublažavajući iritacije i sprečavajući oštećenja izazvana slobodnim radikalima. Uspostavlja balans u osetljivoj koži i poboljšava toleranciju na aktivne sastojke. Klinički je potvrđeno da povećava sintezu kolagena tipa I, čime doprinosi regeneraciji i elastičnosti kože. Posebno je koristan kod stanja kao što su rozacea, dermatitis ili opekotine od sunca. Alantoin Alantoin je derivat urinske kiseline koji se koristi zbog svojih keratolitičkih i umirujućih svojstava. Promoviše regeneraciju epidermalnog tkiva, smanjuje svrab i iritacije, i ubrzava proces zarastanja. Ujedno ima blagi eksfolijativni efekat koji pomaže uklanjanju mrtvih ćelija sa površine kože, čineći je mekšom i svetlijom. Posebno je vredan u negi osetljive i suve kože, kao i nakon agresivnih kozmetičkih procedura. Dodaj u listu želja Dodaj u listu želja', 'Manyo Panthetoin Essence Toner je bogat, obnavljajući tonik koji kombinuje panthenol i madecassoside kako bi umirio, nahranio i zaštitio osetljivu i oslabljenu kožu. Njegova tekstura je gušća od klasičnih tonera, skoro kao esencija, što ga čini savršenim za dubinsku hidrataciju bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Manyo-Panthetoin-Essence-Toner-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
