INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (555, 85, 'iUNIK Calendula Balancing Foam Gel Cleanser', 'iunik-calendula-balancing-foam-gel-cleanser', 'Ključne prednosti: Temeljno, a nežno čišćenje: uklanja ostatke šminke, sebum i nečistoće bez isušivanja. Umiruje i osvežava: neven i centela deluju protiv crvenila i osećaja nelagodnosti. Lagani gel koji se pretvara u pjenu: pogodan za svakodnevnu upotrebu čak i kod osetljive kože. Kome je namenjen? Preporučuje se za mešovitu, masnu, osetljivu i reaktivnu kožu. Pogodan je za svakodnevnu upotrebu, naročito za one koji žele da smanje višak sebuma i crvenilo, a pritom očuvaju barijernu funkciju kože. Zašto volimo iUNIK Calendula Balancing Foam Gel Cleanser? Gelasta formula ovog čistača prilikom kontakta sa vodom stvara nežnu pjenu koja lako klizi preko kože, temeljno je čisteći bez narušavanja njene prirodne zaštite. Kiseline (AHA, BHA i PHA) pomažu u uklanjanju mrtvih ćelija i čišćenju pora, dok istovremeno ne izazivaju iritacije zahvaljujući prisustvu nevena i centele. Ova kombinacija pruža balans između efikasnosti i nežnosti, ostavljajući kožu glatkom, osveženom i bez osećaja zatezanja. Idealna je za one koji žele čist ten bez kompromisa po pitanju komfora i hidratacije. Aktivni sastojci Ekstrakt nevena (Calendula Officinalis) Poznat po svojim umirujućim i regenerativnim svojstvima, neven pomaže u smanjenju crvenila i upalnih procesa. Doprinosi osećaju udobnosti i mekoće nakon čišćenja. Ekstrakt centele asiatice Pomaže u regeneraciji kože, ublažava iritacije i doprinosi jačanju zaštitne barijere. Posebno koristan za osetljivu i oslabljenu kožu. AHA, BHA i PHA kiseline U sinergiji deluju na uklanjanje mrtvih ćelija, čišćenje pora i obnavljanje kože. AHA hidrira i ujednačava ten, BHA prodire dublje i čisti pore, dok je PHA posebno blaga, pogodna i za osetljivu kožu. Hijaluronske kiseline različite veličine molekula Obezbeđuju dubinsku i površinsku hidrataciju, ostavljajući kožu elastičnom i prijatnom na dodir. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Calendula Balancing Foam Gel Cleanser kombinuje AHA, BHA i PHA kiseline sa ekstraktom nevena i centele. Efikasno uklanja nečistoće i višak sebuma, dok istovremeno umiruje kožu i pomaže u sprečavanju iritacija.', 'https://beauty-health.rs/wp-content/uploads/2025/08/iUNIK-Calendula-Balancing-Foam-Gel-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
