INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (556, 160, 'The Face Shop Smile Foot Peeling Mask', 'the-face-shop-smile-foot-peeling-mask', 'Ključne prednosti: Postepeno ljuštenje: bezbedno i bez bola uklanja zadebljanja sa kože stopala. Mekoća i glatkoća: otkriva nežnu, glatku kožu nakon samo jedne upotrebe. Praktičan tretman kod kuće: dovoljno je da obuješ čarapice i pustiš da maska odradi svoje. Kome je namenjena? Savršena je za one koji se bore sa zadebljalom, suvom i ispucalom kožom stopala. Pogodna je i za osobe koje mnogo stoje, nose tesnu obuću ili žele da osveže stopala pred sezonu sandala. Zašto volimo The Face Shop Smile Foot Peeling Mask? Maska funkcioniše kao tretman u dva koraka: prvo se obuju čarapice natopljene aktivnim sastojcima, a zatim se koža prirodno obnavlja tokom narednih dana. Proces ljuštenja započinje oko 4–6 dana nakon korišćenja i traje do dve nedelje. Kiselinski kompleks (AHA i BHA) razgrađuje mrtve ćelije i zadebljanja, dok biljni ekstrakti umiruju kožu i ubrzavaju regeneraciju. Bez trljanja, grebanja ili napora – samo čista, mekana koža na stopalima. Posebno prija tokom toplijih meseci, kada otvorena obuća zahteva lepo negovana stopala. Aktivni sastojci Mlečna i glikolna kiselina (AHA) Ove kiseline nežno omekšavaju kožu i pomažu prirodno ljuštenje mrtvih ćelija, čineći stopala glatkima bez grubog pilinga. Salicilna kiselina (BHA) Prodire dublje u kožu, razgrađuje zadebljanja i deluje protiv upala koje se ponekad javljaju na stopalima. Ekstrakt kamilice Umiruje i štiti kožu tokom procesa ljuštenja, posebno ako su stopala osetljiva ili ispucala. Ekstrakt lavande Pruža prijatan, osvežavajući osećaj i doprinosi regeneraciji, a pri tom deluje antibakterijski. Ekstrakt čempresa Prirodni antiseptik koji pomaže koži da brže zaraste i smanjuje rizik od neprijatnih mirisa. Dodaj u listu želja Dodaj u listu želja', 'The Face Shop Smile Foot Peeling maska u obliku čarapica pruža jednostavan način da svojoj koži na stopalima vratiš mekoću i glatkoću – bez turpija, grubih pilinga ili odlaska na pedikir. Deluje postepeno, ali temeljno, uklanjajući zadebljalu kožu i otkrivajući nežna stopala.', 'https://beauty-health.rs/wp-content/uploads/2025/08/The-Face-Shop-Smile-Foot-Peeling-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
