INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (558, 160, 'The Face Shop Quick Hair Puff', 'the-face-shop-quick-hair-puff', 'Ključne prednosti: Gušći izgled kose za par sekundi: popunjava tanke i proređene delove bez tragova. Bez osećaja težine: prah je lagan, ne ulepljuje kosu i ne stvara “prašasti” izgled. Diskretan i praktičan: dolazi sa ogledalom i jastučićem – staje u torbu i koristi se kad god zatreba. Kome je namenjen? Odličan za svakoga ko želi da prikrije tanje delove kose ili naglasi konture frizure. Posebno koristan ženama i muškarcima koji često vezuju kosu, imaju izražen razdeljak ili se bore sa proređenim područjima. Pogodan za sve tipove kože glave. Zašto volimo THE FACE SHOP Quick Hair Puff ? Ako ti se razdeljak čini širim nego ranije, kosa ti je tanja oko slepoočnica ili jednostavno želiš uredniji izgled pri zategnutim frizurama – ovaj proizvod radi posao. Pigmenti se stope s tvojom bojom kose i ne preslikavaju se, čak ni tokom toplih dana. Matira i upija višak sebuma, što je posebno korisno za masnije teme. Dodatni biljni ekstrakti umiruju kožu glave, pa je prijatan i za svakodnevnu upotrebu. Nije zamena za farbu, ali za tren oka daje efekat punije, stilizovane kose. Aktivni sastojci Mineralni pigmenti Postojani pigmenti u prahu prilagođeni tonovima kose, ne preslikavaju se i pružaju prirodan efekat popunjene kose. Ekstrakt ginsenga Doprinosi jačanju kože glave, umiruje i osvežava, posebno kod iritacija usled vezivanja kose. Ekstrakt soje Pomaže u očuvanju zdravlja kože glave, ublažava osećaj zatezanja i deluje umirujuće. Dodaj u listu želja Dodaj u listu želja', 'THE FACE SHOP Quick Hair Puff koristi nežan puder sa pigmentima koji se stapa sa tvojom bojom kose i trenutno prekriva praznine. Umiruje kožu glave, upija višak sebuma i ostavlja prirodnu, mat završnicu.', 'https://beauty-health.rs/wp-content/uploads/2025/08/THE-FACE-SHOP-Quick-Hair-Puff.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
