INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (559, 155, 'Skinfood Honey Sugar Food Mask', 'skinfood-honey-sugar-food-mask', 'Ključne prednosti: Prirodni piling: crni šećer uklanja mrtve ćelije i omekšava hrapavu površinu kože. Dubinska ishrana: med i propolis intenzivno hrane i hidriraju kožu, ostavljajući je elastičnom i blistavom. Obnavljanje teksture: fermentisani sastojci i prirodna ulja podstiču obnovu kože i umanjuju vidljivost sitnih nepravilnosti. Kome je namenjena? Najviše će prijati suvoj, dehidriranoj i umornoj koži kojoj nedostaje sjaj i glatkoća. Takođe je pogodna i za normalnu i kombinovanu kožu, posebno kada je potrebna dodatna mekoća i osveženje. Zašto volimo Skinfood Honey Sugar Food Mask? Ova maska je mnogo više od klasičnog pilinga. Zahvaljujući sitnim, ali nežnim zrncima šećera, mehanički uklanja nečistoće bez oštećenja kože. Med – posebno manuka i akacija – deluju kao prirodni omekšivači, zadržavaju vlagu i ubrzavaju regeneraciju kože. Fermentisani ekstrakti dodatno umiruju i ujednačavaju ten. Ulja makadamije i semenki biljke meadowfoam obogaćuju formulu bez osećaja težine na licu. Koža nakon upotrebe izgleda osveženo, glatko i vidljivo zdravije – kao da je resetovana. Aktivni sastojci Crni šećer Prirodni piling sastojak bogat mineralima koji nežno uklanja mrtve ćelije, posvetljuje ten i poboljšava teksturu kože. Njegova granulacija je dovoljno blaga za lice, a istovremeno efikasna u čišćenju pora. Manuka i akacija med Ove dve vrste meda poznate su po svom bogatom sastavu i moćnim regenerativnim svojstvima. Vraćaju vlagu, omekšavaju i pomažu u smirivanju iritacija, dok istovremeno hrane i jačaju kožnu barijeru. Propolis ekstrakt Prirodni zaštitnik kože koji deluje antibakterijski i antiinflamatorno. Ubrzava regeneraciju i smanjuje crvenilo, idealan za umirenje i dodatnu negu nakon pilinga. Makadamija ulje Bogato masnim kiselinama koje koža prirodno prepoznaje i lako upija. Pruža dugotrajnu mekoću i elastičnost bez zapušavanja pora. Fermentisani ekstrakti Podstiču obnovu kože, izjednačavaju ten i povećavaju otpornost kože na spoljne faktore. Posebno korisni kod umorne i neujednačene kože. Dodaj u listu želja Dodaj u listu želja', 'Skinfood Honey Sugar maska kombinuje prirodni crni šećer i dve vrste meda u bogatu pastu koja nežno uklanja mrtve ćelije i vraća koži prirodnu mekoću i sjaj. Ova maska istovremeno čisti i neguje, ostavljajući kožu nahranjenom i glatkom kao posle tretmana u salonu.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Skinfood-Honey-Sugar-Food-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
