INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (562, 122, 'Needly Daily Toner', 'needly-daily-toner', 'Ključne prednosti: Blago čišćenje pora: salicilna kiselina dubinski uklanja višak sebuma i sprečava nastanak nepravilnosti. Obnavljanje površinskog sloja: PHA nežno eksfolira kožu, posvetljuje ten i ujednačava teksturu. Umirujuća hidratacija: biljni ekstrakti pružaju olakšanje osetljivoj koži i vraćaju joj balans. Kome je namenjen? Idealan je za masnu, kombinovanu, problematičnu i osetljivu kožu. Prikladan je i za one koji žele svakodnevnu eksfolijaciju bez isušivanja, kao i za sve koji žele da poboljšaju teksturu i tonus kože. Zašto volimo Needly Daily Toner? Ovaj toner je formulisan za one koji žele osvežen i zdrav ten, bez agresivnih sastojaka. PHA deluje na površini kože, uklanjajući odumrle ćelije bez iritacije, dok salicilna kiselina ulazi u pore i sprečava upale. Kombinacija ekstrakata centelle asiatice, artemisije i čajevca smanjuje crvenilo, deluje antibakterijski i umiruje nadraženost. Zahvaljujući glicerinu i hijaluronskoj kiselini, koža ostaje hidrirana i elastična tokom celog dana. Tekstura je osvežavajuće vodenasta, brzo se upija i ne ostavlja lepljiv trag. Aktivni sastojci Glukonolakton (PHA) Ova blaga kiselina eksfolira površinu kože bez izazivanja iritacija. Osim što uklanja mrtve ćelije, deluje i kao antioksidans i hidratantni agens, pa je posebno pogodna za osetljivu kožu. Salicilna kiselina (BHA) Prodire duboko u pore i otklanja višak sebuma, pomaže kod mitisera i akni, a pritom smanjuje crvenilo i upalu. Ekstrakt centelle asiatice Biljni sastojak poznat po svojim umirujućim i regenerativnim svojstvima. Pomaže u jačanju zaštitne barijere kože i obnavlja oštećena područja. Ekstrakt artemisije Bogata antioksidansima, ova biljka smanjuje upale i pomaže u regulaciji preosetljive i iziritirane kože. Ekstrakt čajevca Prirodni antibakterijski sastojak koji čisti pore, smanjuje mogućnost izbijanja nepravilnosti i balansira lučenje sebuma. Dodaj u listu želja Dodaj u listu želja', 'Needly Daily Toner je lagani, tečni toner koji kombinuje blage eksfolijatore i umirujuće biljne ekstrakte kako bi koži pružio svežinu, čistoću i dubinsku hidrataciju bez iritacije. Namenjen je svakodnevnoj upotrebi i posebno je prilagođen osetljivoj, masnoj i problematičnoj koži.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Needly-Daily-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
