INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (563, 119, 'Mixsoon Melting Collagen Neck & Forehead Film', 'mixsoon-melting-collagen-neck-forehead-film', 'Ključne prednosti: Ciljana čvrstina: film se topi na koži i direktno prenosi kolagen u problematične zone. Hidratacija bez ostataka: hijaluronska kiselina zaključava vlagu bez lepljivosti ili osećaja težine. Sjaj i ujednačenost: glutation vraća koži svežinu, ton i blistav izgled. Kome je namenjen? Savršen je za sve koji žele da poboljšaju tonus čela i vrata, bilo da se bore sa opuštenom kožom, izraženim borama ili jednostavno žele brzi lifting bez igle. Pogodan za sve tipove kože, uključujući i osetljivu. Zašto volimo Mixsoon Melting Collagen Neck & Forehead Film? Ova neobična traka izgleda kao papir, ali se pri kontaktu sa vlažnom kožom pretvara u aktivni sloj koji se stapa sa epidermom. Efekat? Vidljivo zaglađene linije, elastičnija i čvršća koža već nakon nekoliko minuta. Kolagen ispunjava bore i zateže kožu, dok hijaluronska kiselina dubinski hidrira i ostavlja kožu nežnom i svežom. Glutation posvetljuje tamne fleke i vraća zdrav sjaj. Tretman ne zahteva ispiranje, ne ostavlja tragove i idealan je za trenutne rezultate – naročito pred važan događaj. Aktivni sastojci Kolagen Prisutnost čak 74% kolagena doprinosi vidljivoj regeneraciji, zatezanju i popunjavanju bora. Pomaže koži da povrati elastičnost i čvrstoću. Hidrolizovani kolagen Zahvaljujući manjoj molekulskoj veličini, prodire dublje u kožu i stimuliše prirodnu proizvodnju kolagena. Hijaluronska kiselina Osigurava višeslojnu hidrataciju, poboljšava elastičnost i čini kožu punijom i blistavijom. Glutation Prirodni antioksidans koji ujednačava ton kože, smanjuje hiperpigmentacije i pruža osvetljavajući efekat. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Melting Collagen Neck & Forehead Film je maska koja se bukvalno topi na koži i unosi svežinu i čvrstinu tačno tamo gde je najpotrebnije – na vratu i čelu. Visoka koncentracija kolagena pretvara ovu tanku traku u moćni tretman protiv bora.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Mixsoon-Melting-Collagen-Neck-Forehead-Film.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
