INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (564, 119, 'Mixsoon H.C.T. Bubble Cleanser', 'mixsoon-h-c-t-bubble-cleanser', 'Ključne prednosti: Dubinsko čišćenje pora: salicilna kiselina otpušava pore i smanjuje mitisere. Smiruje i osvežava: ekstrakti čajnog drveta i centelle ublažavaju crvenilo i iritacije. Ne isušuje kožu: zahvaljujući hidratantnim komponentama, koža ostaje meka i elastična. Kome je namenjen? Preporučuje se osobama sa masnom, kombinovanom i problematičnom kožom, naročito onima sklonim mitiserima, proširenim porama ili povremenim upalama. Pogodna je i za osetljivu kožu koja ne podnosi agresivne čistače. Zašto volimo Mixsoon H.C.T. Bubble Cleanser? Ova pena ima laganu teksturu koja se brzo transformiše u bogatu, ali nežnu penu prilikom dodira sa vodom. Deluje osvežavajuće na kožu, uklanja višak sebuma i ostatke šminke, ali ne narušava prirodnu zaštitnu barijeru. Salicilna kiselina pomaže u borbi protiv mitisera i akni, dok kombinacija biljnih sastojaka poput houttuynie i centele umiruje upale i smanjuje osećaj zategnutosti. Idealan je izbor za one koji žele temeljno, ali nežno čišćenje koje ne narušava balans kože. Koža ostaje čista, hidrirana i bez osećaja iritacije. Aktivni sastojci Salicilna kiselina Beta-hidroksi kiselina poznata po svojoj sposobnosti da prodre duboko u pore i razgradi višak sebuma. Redovnom upotrebom smanjuje mitisere i sprečava nastanak akni, a koži daje čist i gladak izgled. Mlečna kiselina AHA kiselina koja pomaže u uklanjanju mrtvih ćelija sa površine kože, poboljšava teksturu i omogućava bolju apsorpciju drugih proizvoda iz rutine. Blaga je, pa ne iritira čak ni osetljivu kožu. Ekstrakt čajnog drveta Deluje antibakterijski i protivupalno, smanjuje crvenilo i pomaže u prevenciji novih nesavršenosti. Posebno koristan kod kože sklone aknama. Houttuynia cordata ekstrakt Biljni sastojak poznat po svojim umirujućim i detoksikujućim svojstvima. Pomaže u smanjenju iritacija i osnažuje prirodni odbrambeni mehanizam kože. Centella asiatica Poznata i kao cica, ovaj ekstrakt umiruje osetljivu kožu, podstiče regeneraciju i pomaže u jačanju barijere. Redovnim korišćenjem doprinosi zdravijem i otpornijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon H.C.T. Bubble Cleanser sadrži salicilnu i mlečnu kiselinu, kao i visoke koncentracije biljnih ekstrakata čajnog drveta, houttuynie i centele. Namenjena je efikasnom, ali nežnom uklanjanju nečistoća i sebuma, uz dodatno umirenje i balansiranje problematične kože.', 'https://beauty-health.rs/wp-content/uploads/2025/08/Mixsoon-H.C.T.-Bubble-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
