INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (565, 118, 'Missha Super Aqua Ultra Hyalron Cleansing Oil Wipes', 'missha-super-aqua-ultra-hyalron-cleansing-oil-wipes', 'Ključne prednosti: Brzo i efikasno čišćenje: rastvaraju šminku i sebum bez trljanja kože. Intenzivna hidratacija: ten ostaje vlažan i mekan zahvaljujući hijaluronskoj kiselini. Prijateljske prema koži: blaga, neiritirajuća formula pogodna za osetljive tipove. Kome su namenjene? Namenjena je osobama sa suvom, grubom, dehidriranom kožom. Posebno prija u hladnijim mesecima ili kada je koži potrebna dodatna zaštita i obnova. Zašto volimo Missha Super Aqua Ultra Hyalron Cleansing Oil Wipes? Ove maramice deluju poput uljnog čišćenja u formatu bez nereda — dovoljno je preći preko lica da biste uklonili šminku i nečistoće. Ulje od kokosa brzo i nežno rastvara i tvrdokornu šminku, dok se tokom masiranja formira mlečna emulzija. Koža ne ostaje zategnuta — naprotiv, oseća se hidrirano zahvaljujući deset tipova hijaluronske kiseline, koje zadržavaju vlagu i štite od isušivanja. U formuli takođe ima blago osvežavajućih biljnih ulja poput bergamota i narandžine kore, dajući tenu prijatan sjaj i prijatnost nakon upotrebe. Aktivni sastojci ﻿ Kokosovo ulje (biljnog porekla) Delikatno rastvara šminku i nečistoće, a istovremeno omekšava površinu kože bez zapušavanja pora. Hijaluronska kiselina (10 vrsta) Pomaže da koža zadrži vlagu na više slojeva, vraća osećaj punine i sprečava zatezanje. Biljna ulja (bergamot, narandža) Blago tonirajući, osvežavajući efekat koji ostavlja lagan miris i prijatnost nakon čišćenja. Pantenol i glicerin Umiruju i vezuju vlagu, čineći kožu mekom bez osećaja težine. Dodaj u listu želja Dodaj u listu želja', 'Missha Super Aqua Ultra Hyalron Cleansing Oil Wipes su nežne maramice za lice natopljene uljem dobijenim iz kokosa i bogate formulom sa čak deset vrsta hijaluronske kiseline. Osmišljene su da brzo, ali bez agresije uklone šminku, SPF i nečistoće, a istovremeno neguju i hidriraju kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Super-Aqua-Ultra-Hyalron-Cleansing-Oil-Wipes-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
