INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (567, 118, 'Missha Talks Vegan Squeeze Pocket Sleeping Mask', 'missha-talks-vegan-squeeze-pocket-sleeping-mask', 'Ključne prednosti: Noćna regeneracija: intenzivno hrani i obnavlja kožu dok spavate. Veganska i nežna formula: pogodna i za osetljivu kožu, bez iritacija. Praktično pakovanje: savršena za putovanja, brzo osveženje ili kao dodatak redovnoj rutini. Kome je namenjena? Preporučuje se svim tipovima kože, posebno dehidriranoj, umornoj i osetljivoj koži. Idealna je za one koji žele brzu i jednostavnu negu bez komplikovanih koraka. Zašto volimo Missha Talks Vegan Squeeze Pocket Sleeping Mask? Ova maska se koristi kao završni korak u večernjoj nezi – nanosi se na lice i ostavlja da deluje preko noći. Njena lagana, ali bogata tekstura ne opterećuje kožu i ne ostavlja mastan trag. Zahvaljujući biljnim sastojcima, pomaže koži da se regeneriše, osveži i probudi sa više sjaja i elastičnosti. Maska je dostupna u više varijanti, koje ciljaju različite potrebe kože – od hidratacije, preko smanjenja crvenila, do vraćanja vitalnosti. Svako pakovanje može se iskoristiti za više primena. Aktivni sastojci Ekstrakt bundeve Prirodno bogat vitaminima i enzimima koji pospešuju obnavljanje kože. Doprinosi ujednačenijem tenu i pomaže u smanjenju vidljivih znakova umora. Ekstrakt crvenog pasulja Sadrži antioksidanse koji štite kožu od spoljašnjih uticaja, dok istovremeno umanjuju crvenilo i iritacije. Ekstrakt nonija Poznat po svojim regenerativnim svojstvima – pomaže koži da zadrži vlagu i vraća joj vitalnost. ﻿ Dodaj u listu želja Dodaj u listu želja', 'Missha Talks Vegan Squeeze Pocket Sleeping Mask sadrži hranljive biljne ekstrakte poput bundeve, crvenog pasulja i nonija, koji revitalizuju kožu tokom noći. Formula umiruje, hrani i pruža koži zdraviji, osvežen izgled do jutra.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Talks-Vegan-Squeeze-Pocket-Sleeping-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
