INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (568, 118, 'Missha Super Aqua Ultra Hyalron Cleansing Water Wipes', 'missha-super-aqua-ultra-hyalron-cleansing-water-wipes', 'Ključne prednosti: Efikasno čišćenje: brzo uklanja nečistoće, šminku i višak sebuma bez potrebe za trljanjem. Dubinska hidratacija: hijaluronske kiseline različitih veličina dopiru u više slojeva kože. Praktična upotreba: idealne za putovanja, teretanu ili brzinsko osveženje tokom dana. Kome su namenjene? Preporučuje se svima koji žele jednostavno rešenje za čišćenje, posebno osobama sa suvom, osetljivom ili dehidriranom kožom. Idealne su i za one koji često putuju ili vode aktivan stil života. Zašto volimo Missha Super Aqua Ultra Hyalron Cleansing Water Wipes? Ove maramice su savršeno rešenje za sve koji žele temeljno, ali nežno čišćenje bez upotrebe vode. Zahvaljujući micelama, lako rastvaraju nečistoće i šminku, dok istovremeno hidriraju kožu. Posebno su pogodne za suvu i osetljivu kožu jer ne izazivaju zatezanje. Deset tipova hijaluronske kiseline različite molekulske mase omogućavaju višeslojnu hidrataciju – od površinskog osveženja do dubinskog efekta punoće. Nakon korišćenja, koža ostaje glatka, osvežena i prijatna na dodir. Praktično pakovanje čini ih savršenim saputnikom u svakoj torbi. Aktivni sastojci Hijaluronska kiselina (10 tipova) Ova kombinacija obuhvata molekule različite veličine koje prodiru u različite slojeve kože. Manji molekuli pružaju dubinsku hidrataciju, dok veći ostaju na površini i sprečavaju isparavanje vlage. Koža deluje punije, elastičnije i osveženije. Panthenol Poznat kao provitamin B5, panthenol pomaže u obnavljanju zaštitne barijere kože i pruža umirujući efekat. Smanjuje crvenilo, iritacije i osećaj zatezanja. Alantoin Ima regenerativno i umirujuće dejstvo. Pomaže u zaceljivanju mikropovreda i doprinosi mekoći kože. Dodaj u listu želja Dodaj u listu želja', 'Missha Super Aqua Ultra Hyalron Cleansing Water Wipes sadrže deset različitih vrsta hijaluronske kiseline koje dubinski hidriraju kožu dok uklanjaju šminku i ostatke SPF-a. Namenjene su svima koji žele brz i efikasan način za čišćenje lica bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Super-Aqua-Ultra-Hyalron-Cleansing-Water-Wipes-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
