INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (569, 118, 'Missha 3D Mascara', 'missha-3d-mascara', 'Ključne prednosti: Precizna trostrana četkica: ravnomerno razmazuje maskaru od korena do vrha, bez grudvica. Otporna tekstura: vodootporna zaštitna formula štiti volumen i uvijanje bez razmazivanja. Hranljivi efekat: glicerin i vitamin E neguju i umiruju osetljivo područje očiju. Kome je namenjena? Predviđena je za sve tipove kože i očiju, uključujući osetljive i kontaktna sočiva. Posebno je pogodna za one koji traže dnevni, ali izražajan izgled oka bez komplikovane aplikacije i rizika od razmazivanja. Zašto volimo Missha 3D Mascara? Četkica jedinstvene trostrane forme nežno razdvaja i definiše svaku trepavicu, dok biljni voskovi obezbeđuju mekotanim slojem koji duže zadržava oblik. Maskara stvara zaštitni film koji zadržava uvijanje i intenzitet boje bez razlivanja. Glicerin hidratizira i omekšava trepavice, a vitamin E deluje kao antioksidans koji štiti i smiruje. Sve to bez osećaja težine, brljanja ili ljepljenja. Trepavice ostaju savršene do večeri bez potrebe za popravkama. https://www.youtube.com/watch?v=K3rCDcrpngQ&ab_channel=TesterKorea Aktivni sastojci Karnauba i kandeliova voska Prirodni voskovi koji omekšavaju trepavice, daju im oblik i intenzitet bez otežavanja ili grudvanja. Glicerin Hidratantni sastojak koji neguje i štiti trepavice, čini ih mekšim i otpornijim. Vitamin E (tokoferil acetat) Antioksidans koji umanjuje iritacije i pomaže u zaštiti ćelija trepavica od oštećenja. Film-formirajući polimeri Stvaraju stabilan zaštitni sloj koji zadržava volumen, toplinu i pigment čak i u vlažnim uslovima. Dodaj u listu želja Dodaj u listu želja', 'Missha 3D Mascara je maskara koja daje trepavicama volumen, dužinu i nežno uvijanje – sve to bez grudvica i razmazivanja. Jedinstvena trostrana četkica savršeno obavija svaku dlačicu, obezbeđujući preciznu aplikaciju bez preterivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-3D-Mascara.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
