INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (570, 118, 'Missha Pure Source Pocket Pack Shea Butter', 'missha-pure-source-pocket-pack-shea-butter', 'Ključne prednosti: Intenzivna nega tokom sna: hrani i obnavlja kožu dok spavate. Ublažava suvoću i zatezanje: vraća vlagu i omekšava ten. Praktično pakovanje: idealno za putovanja i brzu negu bez komplikacija. Kome je namenjena? Namenjena je osobama sa suvom, grubom, dehidriranom kožom. Posebno prija u hladnijim mesecima ili kada je koži potrebna dodatna zaštita i obnova. Zašto volimo Missha Pure Source Pocket Pack Shea Butter? Ova maska ima bogatu, ali prijatno razmazivu teksturu, koja se lako nanosi i ne ostavlja mastan trag. Shea maslac deluje kao prirodni omotač koji zadržava vlagu i štiti kožu od spoljašnjih uticaja, dok ceramidi obnavljaju barijeru kože i sprečavaju dodatno isušivanje. Biljna ulja dopunjuju efekte, pružajući koži elastičnost i osećaj ugodnosti. Ujutru lice izgleda odmorno, mekano i blistavo. Pogodna je i za hitnu negu lica posle hladnog vetra, grejanja ili stresa. Aktivni sastojci Shea maslac Bogat prirodnim masnim kiselinama i vitaminima, shea maslac hrani i omekšava kožu. Pomaže u obnavljanju zaštitne barijere i zadržava vlagu, čineći ten mekšim i otpornijim. Ceramid NP Ovaj lipid ojačava prirodnu barijeru kože, sprečava isparavanje vlage i štiti od spoljnih iritacija. Posebno je važan za osetljivu i dehidriranu kožu. Glicerin Deluje kao ovlaživač – privlači i zadržava vodu u koži, pomažući da ona ostane glatka i hidrirana tokom celog dana. Biljna ulja (makadamija, argan, maslina) Ova ulja dodatno hrane kožu, obnavljaju njen zaštitni sloj i čine je mekom i elastičnom bez osećaja težine. Adenozin Poznat po svom umirujućem i ujednačujućem efektu, pomaže u smanjenju finih linija i vraća koži svežinu. Dodaj u listu želja Dodaj u listu želja', 'Missha Pure Source Pocket Pack Shea Butter je maska koja sadrži shea puter, ceramide i biljna ulja koji obnavljaju suvu i osetljivu kožu. Tokom noći deluje kao hranljivi balzam, vraćajući licu mekoću i elastičnost.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Pure-Source-Pocket-Pack-Shea-Butter-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
