INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (571, 118, 'Missha Pure Source Pocket Pack Honey', 'missha-pure-source-pocket-pack-honey', 'Ključne prednosti: Dubinska hidratacija: med i glicerin pomažu koži da zadrži vlagu i ostane meka i elastična. Regeneracija tokom noći: propolis i ceramidi jačaju barijeru i podstiču obnovu. Praktično pakovanje: džepni format omogućava jednostavno korišćenje i nošenje, idealno i za putovanja. Kome je namenjena? Preporučuje se osobama sa suvom, dehidriranom i osetljivom kožom. Odlična je za one koji žele dodatnu negu tokom noći bez osećaja težine. Zašto volimo Missha Pure Source Pocket Pack Honey? Ova lagana, ali hranljiva maska koristi prirodne sastojke poput meda i propolisa kako bi koži obezbedila potrebnu negu dok spavate. Med deluje umirujuće i protivupalno, dok propolis pomaže u obnavljanju kože i borbi protiv spoljnih iritacija. Glicerin i ceramid NP dodatno hidrira i učvršćuju kožnu barijeru, čineći je otpornijom na gubitak vlage. Tekstura je blago lepljiva, ali se lepo upija i ostavlja osećaj negovane i hidrirane kože. Ujutru je koža vidno mekša, nahranjena i blistavija. Aktivni sastojci Med Prirodni ovlaživač bogat vitaminima i antioksidansima. Umiruje kožu, hrani je i pomaže u zadržavanju vlage, čineći ten mekšim i elastičnijim. Propolis Sastojak poznat po antibakterijskom i regenerativnom delovanju. Jača kožnu barijeru, ubrzava obnovu i umanjuje upalne procese. Glicerin Humektant koji privlači i zadržava vlagu u koži, doprinosi mekoći i sprečava isušivanje. Ceramid NP Lipid koji obnavlja zaštitni sloj kože, jača otpornost i sprečava gubitak vlage. Adenosin Pomaže u borbi protiv finih linija, poboljšava elastičnost i daje koži zategnutiji izgled. Dodaj u listu želja Dodaj u listu želja', 'Missha Pure Source Pocket Pack Honey sadrži med i propolis koji hrane kožu, umiruju iritacije i vraćaju zdrav izgled. Tokom noći deluje kao intenzivni tretman koji pruža vlagu i jača kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Pure-Source-Pocket-Pack-Honey-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
