INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (572, 118, 'Missha Mascure Nutrition Solution Sheet Mask Propolis', 'missha-mascure-nutrition-solution-sheet-mask-propolis', 'Ključne prednosti: Regeneriše i štiti: propolis ima snažna antiinflamatorna i antibakterijska svojstva. Hidrira u dubinu: hijaluronska kiselina i glicerin zadržavaju vlagu i vraćaju elastičnost. Jača barijeru: ceramid NP i adenosin obnavljaju kožnu barijeru i poboljšavaju strukturu kože. Kome je namenjena? Preporučuje se suvoj, osetljivoj i nadraženoj koži, kao i koži koja se suočava sa upalama, crvenilom ili spoljašnjim stresom. Idealna je i za one koji žele dodatnu hidrataciju i regeneraciju posle dužeg izlaganja suncu ili vetru. Zašto volimo Missha Mascure Nutrition Solution Sheet Mask Propolis? Ova maska je pravo spa osveženje za kožu kojoj je potrebna dodatna nega i obnova. Propolis umiruje crvenilo, deluje protiv bakterija i ubrzava regeneraciju kože. Ceramid NP jača prirodnu zaštitu kože i sprečava gubitak vlage, dok hijaluronska kiselina intenzivno hidrira i omekšava ten. Adenosin pomaže u zaglađivanju finih linija i poboljšava elastičnost. Tkanina maske je tanka i prijatna, pa savršeno prijanja bez pomeranja, omogućavajući sastojcima da deluju bez ometanja. Posle upotrebe, koža je meka, osvežena, smirena i vidljivo nahranjena. Aktivni sastojci Propolis Propolis je prirodni sastojak koji proizvode pčele, poznat po snažnim antibakterijskim i antiinflamatornim svojstvima. Umiruje upaljene delove, ubrzava zarastanje i štiti kožu od spoljašnjih uticaja. Daje koži zdravi sjaj i jača njenu otpornost. Ceramid NP Ceramid NP je lipid koji se prirodno nalazi u koži i igra ključnu ulogu u očuvanju barijere. Obnavlja zaštitni sloj kože, sprečava gubitak vlage i čini kožu otpornijom na spoljašnje iritanse. Hijaluronska kiselina Moćan ovlaživač koji privlači i zadržava vodu u koži, pružajući dugotrajnu hidrataciju i punoću. Redovnom upotrebom čini kožu glatkom i elastičnom. Adenosin Prirodni sastojak koji poboljšava elastičnost kože i deluje protiv bora. Podstiče proizvodnju kolagena i doprinosi ujednačenijoj i čvršćoj koži. Dodaj u listu želja Dodaj u listu želja', 'Missha Mascure Nutrition Solution Sheet Mask Propolis sadrži ekstrakt propolisa, ceramid NP, hijaluronsku kiselinu i adenosin. Deluje tako što umiruje kožu, obnavlja oštećenu barijeru i pruža dubinsku hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Mascure-Nutrition-Solution-Sheet-Mask-Propolis.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
