INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (574, 109, 'Manyo Pure Cleansing Oil Deep Clean', 'manyo-pure-cleansing-oil-deep-clean', 'Ključne prednosti: Temeljno čišćenje pora: uklanja i tvrdokornu šminku, SPF i sebum bez isušivanja kože. Balansirana nega: fermentisana biljna ulja neguju kožu i pomažu u očuvanju zaštitne barijere. Pogodno za osetljivu kožu: nekomedogena formula bez iritansa, idealna i za one sklone aknama. Kome je namenjeno? Preporučuje se osobama sa kombinovanom i masnom kožom, ali i svima koji koriste šminku i SPF svakodnevno. Posebno prija koži sklonoj zapušenim porama, mitiserima i aknama, jer čisti bez agresivnog delovanja. Zašto volimo Manyo Pure Cleansing Oil Deep Clean ? Ovo ulje se lako razmazuje po suvoj koži, otapa šminku i nečistoće, a kada dođe u kontakt s vodom pretvara se u mlečnu emulziju koja se bez napora ispira. Nakon upotrebe, koža ostaje glatka i osvežena, bez masnog sloja. Fermentisano suncokretovo ulje donosi bogatstvo nutrijenata i smiruje crvenilo, dok ulje crnog kima deluje antibakterijski i balansira masnoću. Ulje lešnika i grožđa dodatno omekšavaju i regenerišu kožu. Redovnom upotrebom pomaže u smanjenju mitisera i vidljivosti pora, dok ten postaje blistaviji i ujednačeniji. Aktivni sastojci Suncokretovo ulje (fermentisano) Bogato esencijalnim masnim kiselinama i antioksidansima, ovo ulje dubinski čisti, umiruje i neguje kožu. Fermentacijom se povećava njegova stabilnost i sposobnost prodiranja u dublje slojeve kože. Ulje crnog kima (nigella) Ima antibakterijska i antiinflamatorna svojstva. Reguliše lučenje sebuma i umanjuje upalne procese na koži bez izazivanja iritacija. Ulje lešnika Lagano i brzo upijajuće ulje koje omekšava i hidrira kožu, pomaže u obnavljanju lipidne barijere i sprečava isušivanje nakon čišćenja. Ulje koštica grožđa Blago adstringentno delovanje pomaže u sužavanju pora, dok visoki sadržaj vitamina E pruža antioksidativnu zaštitu. Skvalan Prirodni sastojak koji se već nalazi u koži. Pomaže u očuvanju vlage, obnavlja barijeru i smanjuje osećaj zatezanja. Pantenol i biljni ekstrakti Doprinose dodatnom umirivanju i obnavljanju kože, naročito nakon svakodnevnog izlaganja spoljnom stresu i šminki. Dodaj u listu želja Dodaj u listu želja', 'Manyo Pure Cleansing Oil Deep Clean je nežno, ali efikasno ulje za čišćenje koje temeljno uklanja šminku, SPF, višak sebuma i nečistoće iz pora. Formulacija se oslanja na moć biljnih ulja i fermentisanih sastojaka koji čiste i neguju kožu bez narušavanja njene prirodne barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Manyo-Pure-Cleansing-Oil-Deep-Clean-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
