INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (577, 109, 'Manyo Bifida Biome Concentrate Eye Cream', 'manyo-bifida-biome-concentrate-eye-cream', 'Ključne prednosti: Regeneriše barijeru kože: pomaže koži da se zaštiti od spoljašnjih agresora i gubitka vlage. Smanjuje podočnjake: posvetljuje tamnu regiju ispod očiju i ublažava umoran izgled. Zateže i hidrira: vraća elastičnost tankoj koži oko očiju i čini je punijom. Kome je namenjena? Preporučuje se svim tipovima kože, posebno osobama sa tankom, dehidriranom i umornom kožom oko očiju. Pogodna je i za one koji žele prevenciju prvih bora ili negu već izraženih znakova starenja. Zašto volimo Manyo Bifida Biome Concentrate Eye Cream ? Ova krema ima svilenkastu, lako razmazivu teksturu koja ne ostavlja mastan film. Pogodna je za svakodnevnu negu, čak i kod osetljive kože. Bifida ferment lysate deluje umirujuće i regenerišuće, a zajedno sa probiotskim derivatima obnavlja mikrofloru kože. Niacinamid posvetljuje i ujednačava ton, dok hijaluronska kiselina intenzivno hidrira i pruža efekat zategnutosti. Peptidi stimulišu proizvodnju kolagena i elastina, čineći kožu glatkom i elastičnom. Ekstrakti centelle i biljnih ulja dodatno umiruju i hrane, pa je ovo idealan preparat za one koji žele da kombinuju njegu protiv starenja sa blagim i efikasnim delovanjem. Aktivni sastojci Bifida ferment lysate Fermentisani sastojak bogat hranljivim materijama koji poboljšava regeneraciju, jača barijeru kože i štiti od spoljašnjih uticaja. Posebno delotvoran kod osetljive i umorne kože oko očiju. Lactobacillus/pumpkin ferment filtrate Probiotski sastojak koji pomaže u očuvanju zdrave mikroflore kože, umiruje i jača otpornost kože na spoljne stresore. Niacinamid Deluje na posvetljivanje tamnih kolutova, ujednačavanje tona kože i smanjenje crvenila. Istovremeno poboljšava elastičnost i jača barijeru. Peptidi Kompleks peptida stimuliše sintezu kolagena i elastina, smanjuje vidljivost bora i vraća koži čvrstoću. Hijaluronska kiselina Dubinski hidrira sve slojeve kože i zadržava vlagu, čineći kožu oko očiju punijom i mekšom. Centella asiatica Biljni ekstrakt poznat po svojim umirujućim i regenerišućim svojstvima. Ublažava crvenilo i doprinosi bržem oporavku kože. Dodaj u listu želja Dodaj u listu želja', 'Manyo Bifida Biome Concentrate Eye Cream je koncentrovana krema za negu osetljive regije oko očiju, sa visokim udelom bifida fermenta i probiotskim kompleksima koji jačaju kožnu barijeru, posvetljuju podočnjake i smanjuju bore.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Manyo-Bifida-Biome-Concentrate-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
