INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (581, 82, 'Innisfree No‑Sebum AC Powder', 'innisfree-no-e2-80-91sebum-ac-powder', 'Ključne prednosti: Kontrola sebuma: upija višak masnoće i sprečava neželjen sjaj tokom dana. Vizuelno zaglađivanje: smanjuje vidljivost pora i čini ten ujednačenijim. Podrška koži sklonoj aknama: sadrži umirujuće i antibakterijske sastojke. Kome je namenjen? Najviše odgovara osobama sa masnom, kombinovanom i problematičnom kožom, kao i onima koji žele da produže postojanost šminke ili matiraju ten bez osećaja težine. Posebno koristan tokom vlažnih ili toplih dana. Zašto volimo Innisfree No‑Sebum AC Powder? Ovaj puder u prahu je savršen saveznik za one sa masnom, kombinovanom ili aknama sklonom kožom. Njegova lagana tekstura se lako nanosi i ne ostavlja beli trag, a uz pomoć minerala iz prirodnih izvora pruža efekat trenutne svežine. Zahvaljujući prisustvu salicilne kiseline, nežno pomaže u čišćenju pora i sprečavanju novih nepravilnosti. Biljni ekstrakti, uključujući centelu, umiruju crvenilo i iritacije, dok dodatak hijaluronske kiseline održava vlagu u koži kako bi se sprečilo isušivanje. Puder ne zapušava pore i idealan je za svakodnevnu upotrebu, čak i tokom letnjih dana kada se koža brže masti. Aktivni sastojci Silika Prirodni mineral koji upija višak sebuma, matira kožu i ostavlja glatki, suvi završetak bez sjaja. Salicilna kiselina Blagi beta-hidroksi kiselinski sastojak koji dubinski čisti pore, sprečava zapušenja i smanjuje pojavu akni. Ekstrakt centelle Deluje protivupalno i regenerativno – umiruje crvenilo i pospešuje obnavljanje oštećene kože. Hijaluronska kiselina Pomaže koži da zadrži vlagu, održava prirodni balans i sprečava dehidrataciju koja može biti izazvana matiranjem. Ekstrakt kamilice Doprinosi smanjenju iritacija, umiruje kožu i daje osećaj prijatnosti pri nanošenju. Mineralni puder Zahvaljujući ultra finim česticama, pruža nežan efekat zamućenja i ujednačava teksturu kože. Dodaj u listu želja Dodaj u listu želja', 'Innisfree No‑Sebum AC Powder je fini mineralni puder u prahu koji matira kožu, smanjuje višak sebuma i pruža nežnu negu koži sklonoj nepravilnostima. Ova verzija poznatog pudera dodatno sadrži umirujuće sastojke koji pomažu kod akni i crvenila, ostavljajući kožu glatkom, suvom na dodir i ujednačenom.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Innisfree-No‑Sebum-AC-Powder.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
