INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (582, 82, 'Innisfree Green Tea Hyaluronic Glow Eye & Face Ball', 'innisfree-green-tea-hyaluronic-glow-eye-face-ball', 'Ključne prednosti: Višeslojna hidratacija: hijaluronska kiselina različitih molekulskih veličina zadržava vlagu u svim slojevima kože. Smanjuje natečenost: kofein i metalni aplikator trenutno osvežavaju i umanjuju umoran izgled. Ujednačen i blistav ten: niacinamid i zeleni čaj pomažu u posvetljavanju kože i jačanju barijere. Kome je namenjena? Proizvod je idealan za sve tipove kože, a naročito koristan za one koji se bore sa natečenošću, tamnim kolutovima, finim linijama i dehidriranom kožom. Pogodan je i za osetljivu kožu. Zašto volimo Innisfree Green Tea Hyaluronic Glow Eye & Face Ball? Lagani gel se nanosi direktno metalnom kuglicom koja pruža prijatno hlađenje i blagu masažu. Ovaj efekat odmah deluje protiv nadutosti, dok hijaluronska kiselina veže vlagu u koži, ostavljajući je punijom i glatkom. Ekstrakt zelenog čaja umiruje i štiti, dok niacinamid ujednačava ten i pomaže kod tamnih podočnjaka. Kofein stimuliše cirkulaciju i osvežava izgled, a skvalan dodatno neguje bez težine. Zahvaljujući ovoj kombinaciji, koža deluje osveženo, odmorno i prirodno blistavo. Aktivni sastojci Ekstrakt zelenog čaja Bogat antioksidansima i aminokiselinama, umiruje iritacije, hidrira i štiti kožu od spoljašnjih uticaja. Hijaluronska kiselina (5 vrsta) Vezuje vlagu u površinskim i dubljim slojevima kože, poboljšava elastičnost i vraća punoću. Niacinamid Vitamin B3 koji ujednačava ten, jača barijeru kože i pomaže u osvetljavanju tamnih podočnjaka. Kofein Stimulativni sastojak koji podstiče mikrocirkulaciju, smanjuje nadutost i osvežava izgled kože. S ﻿ kvalan Prirodni emolijens koji omekšava, hidrira i štiti kožu bez osećaja težine ili masnoće. Adenozin Pomaže u zaglađivanju finih linija i doprinosi elastičnosti kože. Dodaj u listu želja Dodaj u listu želja', 'Innisfree Green Tea Hyaluronic Glow Eye & Face Ball je osvežavajući roll-on serum za područje oko očiju i lice, koji kombinuje moć biljnih ekstrakata sa pet vrsta hijaluronske kiseline. Zahvaljujući metalnoj kuglici za nanošenje, pruža i blagi masažni efekat koji dodatno umanjuje natečenost i umor.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Innisfree-Green-Tea-Hyaluronic-Glow-Eye-Face-Ball.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
