INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (583, 78, 'I’m From Rice Whip Facial Cleanser 30 ml', 'i-m-from-rice-whip-facial-cleanser', 'Ključne prednosti: Nežno čišćenje: efikasno uklanja nečistoće i višak sebuma bez isušivanja. Poboljšava ton kože: ujednačava ten i vraća prirodni sjaj. Podržava barijeru: hidrira i smanjuje osećaj zategnutosti nakon umivanja. Kome je namenjena? Pogodan je za sve tipove kože, uključujući i osetljivu. Preporučuje se osobama koje žele temeljno, ali nežno čišćenje, kao i onima sa neujednačenim tenom, začepljenim porama ili kožom sklonom dehidrataciji. Zašto volimo I’m From Rice Whip Facial Cleanser? Ovaj čistač stvara laganu, ali gustu penu koja prijatno obavija kožu, razlažući nečistoće i ostatke šminke bez trljanja. Ekstrakt pirinča deluje umirujuće, sadrži prirodne enzime i antioksidanse koji pomažu u obnavljanju kože. Niacinamid doprinosi ujednačavanju tena i jačanju zaštitne barijere, dok glicerin sprečava isušivanje. Zahvaljujući dodatku blagih kiselina, ovaj proizvod istovremeno čisti i nežno eksfolira, poboljšavajući teksturu i sjaj kože bez iritacije. Nakon ispiranja, lice ostaje mekano, osveženo i spremno za nastavak nege. Aktivni sastojci Ekstrakt pirinča Blagotvorno deluje na umirivanje kože, posvetljuje ten i sadrži prirodne enzime koji nežno uklanjaju mrtve ćelije. Niacinamid Vitamin B3 koji pomaže u regulaciji sebuma, smanjuje fleke i poboljšava strukturu kože. Glicerin Prirodni ovlaživač koji vezuje vlagu i štiti kožu od isušivanja nakon čišćenja. AHA, BHA, PHA, LHA Blagi eksfolijansi koji pomažu u obnavljanju površinskog sloja kože i otčepljuju pore, bez iritacije. Blagi surfaktanti biljnog porekla Omogućavaju bogatu penu i temeljno čišćenje bez narušavanja prirodne barijere kože. Dodaj u listu želja Dodaj u listu želja', 'I’m From Rice Whip Facial Cleanser je penušavi čistač sa ekstraktom korejskog pirinča iz Yeojua, poznatog po visokom sadržaju vitamina i minerala. Namenjen je temeljnom, ali nežnom čišćenju kože bez isušivanja, uz dodatne benefite za ujednačen ten i zdrav sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Rice-Whip-Facial-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
