INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (584, 78, 'I’m From Honey Glow Cream', 'i-m-from-honey-glow-cream', 'Ključne prednosti: Obnavlja kožnu barijeru: pčelinji sastojci jačaju otpornost kože i štite je od spoljašnjih uticaja. Hidrira i omekšava: bogata tekstura obnavlja suvu i grubu kožu, vraćajući joj glatkoću. Daje blistavost: koža izgleda zdravije, ujednačenije i osveženo već nakon nekoliko dana korišćenja. Kome je namenjena? Preporučuje se suvoj, dehidriranoj, osetljivoj i reaktivnoj koži, kao i onima sa oslabljenom barijerom. Pogodna je i za zrelu kožu kojoj nedostaje čvrstina i sjaj. Zašto volimo I’m From Honey Glow Cream? Ova krema ima kremastu, gotovo balzamastu teksturu koja se topi na koži, ostavljajući prijatan film koji ne masti već hrani. Idealna je za večernju rutinu, posebno u hladnijim mesecima, jer zaključava vlagu i štiti kožu tokom noći. Kompleks 7 pčelinjih sastojaka deluje sinergijski – propolis i matični mleč umiruju i regenerišu, dok med i pčelinji vosak zadržavaju vlagu. Redovnim korišćenjem, koža postaje primetno mekša, elastičnija i vidno zdravija. Crvenilo i iritacije su umanjene, a lice dobija prirodan, ujednačen sjaj. Posebno se preporučuje kada je koži potreban oporavak – nakon izlaganja vetru, suncu, ili preteranom čišćenju. Aktivni sastojci Med Prirodni ovlaživač koji hidrira, omekšava i pospešuje regeneraciju kože. Ima antibakterijska svojstva i pomaže u ublažavanju upala. Propolis Smiruje iritacije, deluje antimikrobno i ubrzava oporavak kože. Posebno koristan kod crvenila i akni. Matični mleč Bogata hranljiva supstanca koja stimuliše regeneraciju ćelija i deluje protiv starenja. Pčelinji vosak Stvara zaštitni sloj koji zadržava vlagu i štiti kožu od isušivanja, bez da je opterećuje. Polen i ekstrakt saća Hrane i revitalizuju kožu zahvaljujući visokom sadržaju vitamina i antioksidanasa. Medna voda Dodatni izvor vlage i umirujućih sastojaka koji podržava prirodnu barijeru kože. Dodaj u listu želja Dodaj u listu želja', 'I’m From Honey Glow Cream je bogata, hranljiva krema koja koristi kompleks od 7 pčelinjih sastojaka kako bi dubinski nahranila, umirila i osnažila kožu. Formulisana je za oporavak osetljive, suve i beživotne kože, vraćajući joj zdrav sjaj i otpornost.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Honey-Glow-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
