INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (585, 78, 'I’m From Ginseng Serum', 'i-m-from-ginseng-serum', 'Ključne prednosti: Poboljšava elastičnost: podstiče proizvodnju kolagena i učvršćuje konture lica. Revitalizuje i osvežava: koži vraća zdravu boju i sjaj. Smanjuje bore: ublažava fine linije i poboljšava teksturu kože. Kome je namenjen? Preporučuje se suvoj, zreloj i umornoj koži, kao i svima koji primete gubitak tonusa ili elastičnosti. Odličan je izbor u periodima stresa, promena vremena, ili kada koži treba dodatna podrška i snaga. Zašto volimo I’m From Ginseng Serum? Ovaj serum pruža luksuzni osećaj nege zahvaljujući gustoj, hranljivoj formuli i toploj, zemljanoj aromi žen-šena. Već nakon nekoliko dana korišćenja, koža izgleda odmornije i zategnutije, kao da je dobila novu energiju. Ekstrakt crvenog žen-šena deluje kao biljni tonik koji stimuliše mikrocirkulaciju, što pomaže u detoksikaciji i boljoj ishrani ćelija. Uz dodatak adenosina, koji pomaže u borbi protiv bora, i hijaluronske kiseline, koja zadržava vlagu, serum pruža potpunu negu za kožu kojoj je potrebna regeneracija i tonus. Ne ostavlja masni film, već se upija brzo, ostavljajući lice mekšim i vizuelno punijim. Aktivni sastojci Crveni žen-šen (Panax Ginseng Root Extract) Tradicionalni biljni sastojak poznat po snažnom antioksidativnom delovanju. Povećava cirkulaciju, poboljšava tonus kože i podstiče prirodnu regeneraciju. Posebno cenjen kod zrele kože kojoj je potrebna dodatna energija i čvrstina. Hijaluronska kiselina Dubinski hidrira kožu i zadržava vlagu u dubljim slojevima, čineći je punijom, mekšom i otpornijom na spoljne faktore. Adenosin Prirodni sastojak sa dokazanim anti-age efektom – smanjuje dubinu bora i poboljšava teksturu kože redovnim korišćenjem. Ekstrakt sladića Deluje umirujuće i ujednačava ton kože, pomaže u borbi protiv hiperpigmentacija i iritacija. Ekstrakt korena peonije i kore vrbe Daju dodatni antiinflamatorni efekat, pomažu kod crvenila i upalnih procesa, dok nežno pročišćavaju pore. Fermentisani biljni kompleks Podržava balans kože i pomaže boljoj apsorpciji ostalih sastojaka, čineći serum efikasnijim. Dodaj u listu želja Dodaj u listu želja', 'I’m From Ginseng Serum kombinuje ekstrakt fermentisanog crvenog žen-šena, hijaluronsku kiselinu i adenosin kako bi dubinski nahranio kožu, ujednačio ten i poboljšao elastičnost. Namenjen je koži koja izgleda umorno, beživotno ili opušteno.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Ginseng-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
