INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (586, 78, 'I’m From Fig Cleansing Balm', 'i-m-from-fig-cleansing-balm', 'Ključne prednosti: Trostruka tekstura: balzam se topi u ulje, pa prelazi u mleko – omogućava lako i efikasno čišćenje. Dubinsko uklanjanje nečistoća: fig ekstrakt otapa sebum i čisti pore bez iritacije. Zaštita i umirenje: kurkuma i biljni sastojci smanjuju crvenilo i umiruju osetljivu kožu. Kome je namenjen? Pogodan je za sve tipove kože, uključujući i osetljivu. Idealno rešenje za one koji žele da temeljno uklone nečistoće bez agresivnog osećaja na koži, naročito kod kombinovane, suve i dehidrirane kože. Zašto volimo I’m From Fig Cleansing Balm? Tekstura balzama je glatka i podseća na sorbet – čim ga nanesete, topi se u nežno ulje koje lako klizi po koži. Masiranjem otapa čak i vodootpornu šminku i SPF, a uz dodatak vode pretvara se u mlečnu emulziju koja se jednostavno ispira bez ostavljanja masnog sloja. Ekstrakt smokve bogat je antioksidansima i prirodnim šećerima koji pomažu da se koža očisti, osveži i istovremeno zadrži vlagu. Kurkuma doprinosi ublažavanju upala i crvenila, dok biljni ekstrakti poput neem-a i algi dodatno hrane i štite. Nakon ispiranja, koža je čista, glatka i uravnotežena – bez zatezanja ili osećaja suvoće. Aktivni sastojci Ekstrakt smokve (7,8%) Prirodni antioksidans koji rastvara sebum, hidrira kožu i nežno pročišćava pore. Deluje protiv starenja i osvetljava ten. Kurkumin ekstrakt Smiruje iritacije, ublažava crvenilo i deluje protivupalno. Posebno koristan kod osetljive i reaktivne kože. Neem i alge Biljni sastojci bogati mineralima i antimikrobnim jedinjenjima. Štite kožu i pomažu njenoj regeneraciji. Caprylic/Capric Triglyceride Emolijens koji hidrira i omekšava kožu, čini balzam lakim za nanošenje i skida se bez osećaja težine. Pantenol (provitamin B5) Hidrira, umiruje i obnavlja zaštitnu barijeru kože. Sorbitan sesqui-oleat Omogućava transformaciju balzama u mlečnu emulziju, što olakšava ispiranje bez ostataka. Dodaj u listu želja Dodaj u listu želja', 'I’m From Fig Cleansing Balm je balzam za čišćenje lica koji nežno, ali temeljno uklanja šminku, SPF i nečistoće nakupljene tokom dana. Njegova bogata tekstura se pri kontaktu sa kožom topi u ulje, a potom u mlečnu emulziju koja se lako ispira, ostavljajući kožu mekom, čistom i hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Fig-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
