INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (588, 68, 'Growus Damage Therapy Scalp Scaling Ampoule', 'growus-damage-therapy-scalp-scaling-ampoule', 'Ključne prednosti: Dubinsko čišćenje: salicilna kiselina nežno uklanja mrtve ćelije i sprečava začepljenja folikula. Obnova i jačanje barijere: kolagen i ceramidi pomažu u regeneraciji kože glave. Umirenje i hidratacija: pantenol i ekstrakt bisera smiruju crvenilo i neprijatan osećaj zatezanja. Kome je namenjen? Preporučuje se osobama koje imaju problematično teme: sklono perutanju, svrabom, prekomernim mašćenjem ili zategnutošću. Posebno koristan za one koji često koriste proizvode za stilizovanje kose ili imaju osetljivo teme koje burno reaguje na promene vremena i stresa. Zašto volimo Growus Damage Therapy Scalp Scaling Ampoule? Ova ampula ima teksturu sličnu serumu, brzo se upija i ne ostavlja mastan trag. Prilikom nanošenja pruža osvežavajući osećaj hlađenja koji trenutno ublažava svrab i iritaciju. Salicilna kiselina i njen derivat capryloyl salicylate rade kao blagi piling koji čisti pore na temenu i sprečava njihovo ponovno zapušenje. Istovremeno, niacinamid balansira lučenje sebuma, dok pantenol i ceramid NP jačaju kožnu barijeru i obnavljaju vlažnost. Komplekse proteina i kolagena dodatno neguju kožu glave, što vremenom doprinosi zdravijem rastu kose i manjoj osetljivosti temena. Aktivni sastojci Salicilna kiselina i capryloyl salicylate Hemijski eksfolijanti koji uklanjaju višak mrtvih ćelija, smanjuju rizik od začepljenja folikula i pomažu kod peruti bez isušivanja kože. Niacinamid Reguliše proizvodnju sebuma, umanjuje crvenilo i doprinosi oporavku kožne barijere. Pantenol Poznat po umirujućim i regenerativnim svojstvima – pomaže u hidrataciji kože i smanjenju nelagodnosti. Ekstrakt bisera i morski minerali Daju koži dodatne hranljive materije, osvežavaju i pružaju osećaj čistoće i mekoće. Kolagen i biljni proteini Ojačavaju strukturu kože glave, poboljšavaju njenu elastičnost i podstiču zdraviji izgled kose. Ceramid NP Vraća koži elastičnost, sprečava isušivanje i štiti od spoljnih iritacija. Dodaj u listu želja Dodaj u listu želja', 'Growus Damage Therapy Scalp Scaling Ampoule kombinuje morske minerale, biserni ekstrakt, salicilnu kiselinu, niacinamid i kompleks kolagena kako bi umirio teme, uklonio višak sebuma i obnovio kožnu barijeru. Deluje osvežavajuće, lagano i istovremeno dubinski hranljivo.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Growus-Damage-Therapy-Scalp-Scaling-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
