INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (589, 49, 'Dr. Ceuracle AC Spot Healer', 'dr-ceuracle-ac-spot-healer', 'Ključne prednosti: Smiruje upale: pomaže da bubuljice brže splasnu i postanu manje bolne. Podstiče obnavljanje kože: ubrzava zarastanje bez ožiljaka ili perutanja. Sprečava tragove: redovnom upotrebom smanjuje rizik od tamnih fleka posle akni. Kome je namenjen? Odličan je za kožu sklonu aknama, bez obzira na uzrast. Može ga koristiti i tinejdžer kome je prva bubuljica probila rutinu, i odrasla osoba koja želi diskretno, ali efikasno rešenje za povremene nepravilnosti. Pogodan je i za osetljivu kožu jer ne koristi agresivne sastojke. Zašto volimo Dr. Ceuracle AC Spot Healer ? Ovaj uređaj je idealan za one situacije kada „osećaš da se nešto sprema“. Deluje brzo, nežno i bez ikakvog dodira sa hemijskim supstancama. Plava svetlost ima antibakterijsko dejstvo i pomaže da se koža pročisti, dok infracrveni talasi prodiru dublje i stimulišu prirodnu regeneraciju. Veoma je jednostavan za upotrebu – dovoljno je 10–15 sekundi po promeni. Praktičan je i za kućnu upotrebu i za torbicu, jer izgleda kao olovka, ali radi ozbiljan posao. Redovnim korišćenjem možeš sprečiti da se manja bubuljica pretvori u upaljeno crvenilo koje ne prolazi danima. Kako deluje? Plava svetlost Ciljano deluje na bakterije koje uzrokuju akne i pomaže u regulaciji sebuma, što znači manje novih bubuljica. Infracrvena svetlost Deluje dublje – podstiče prirodno zarastanje i regeneraciju, i tako smanjuje rizik od ožiljaka i mrlja. Dodaj u listu želja Dodaj u listu želja', 'Dr. Ceuracle AC Spot Healer kombinuje plavu i infracrvenu svetlost kako bi smanjio upale, umirio crvenilo i ubrzao zarastanje kože. Dovoljno je da ga prisloniš na problematično mesto na par sekundi – i pustiš svetlost da radi svoj posao.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Dr.-Ceuracle-AC-Spot-Healer-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
