INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (590, 57, 'Eqqualberry Swimming Pool Ampoule', 'eqqualberry-swimming-pool-ampoule', 'Ključne prednosti: Višeslojna hidratacija: različite vrste hijaluronske kiseline hidriraju površinske i dublje slojeve kože. Umirena i jača kožna barijera: Cica kompleks obnavlja i štiti osetljivu i reaktivnu kožu. Regulisanje sebuma: biljni kompleks pomaže u smanjenju viška sebuma i poboljšava izgled pora. Kome je namenjena? Pogodna za sve tipove kože, posebno suvu, kombinovanu i osetljivu. Ampula pruža intenzivnu hidrataciju, umiruje crvenilo i iritacije. Zašto volimo Eqqualberry Swimming Pool Ampoule? Ova ampula donosi osećaj osveženja već pri prvom nanošenju – tekstura je vodenasta, ali kožu ostavlja dubinski hidriranom i zategnutom. Hijaluronski kompleks vezuje vlagu u više slojeva kože, čime se postiže elastičniji, puniji izgled. Ekstrakti Centella asiatica i njeni aktivni derivati poput madecassoside-a i asiaticoside-a ubrzavaju obnavljanje kože i smanjuju crvenilo. Specijalni biljni kompleks, poznat kao Anti Sebum P, dodatno pomaže u kontroli masnoće i zateže pore. Serum ne ostavlja lepljiv trag i brzo se upija, što ga čini odličnim izborom i za dnevnu i za noćnu rutinu, naročito ako voliš lagane, ali efikasne formule. Aktivni sastojci Hyal 8 Complex (hijaluronska kiselina različitih veličina molekula) Omogućava višeslojnu hidrataciju – manje molekule prodiru u dublje slojeve, dok veće ostaju na površini i sprečavaju isparavanje vlage. Rezultat je koža koja izgleda punije, mekše i elastičnije. Cica kompleks (Centella asiatica, asiaticoside, madecassoside, asiatic acid, madecassic acid) Umiruje upalne procese, pomaže zaceljivanje mikrooštećenja i jača kožnu barijeru. Posebno delotvorno kod reaktivne i osetljive kože. Anti Sebum P kompleks (biljni ekstrakti) Biljna mešavina koja reguliše prekomerno lučenje sebuma, sužava pore i poboljšava opšti izgled kože, bez isušivanja. Adenozin Prirodni sastojak koji deluje na fine linije i doprinosi glatkijem, zategnutijem izgledu kože, stimulišući ćelijsku aktivnost. Skvalan, pantenol, arginin Umiruju, omekšavaju i štite kožu od iritacija, bez masnog filma – savršen balans hidratacije i udobnosti. ﻿ Dodaj u listu želja Dodaj u listu želja', 'Eqqualberry Swimming Pool Ampoule koristi hijaluronsku kiselinu različitih molekulskih veličina da prodre duboko u kožu, dok ekstrakti Centella asiatica i patentirani kompleks biljaka umiruju, jačaju barijeru i pomažu pri regulaciji sebuma. Idealan je za kožu kojoj je potrebna dubinska hidratacija bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Eqqualberry-Swimming-Pool-Ampoule-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
