INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (591, 49, 'Dr. Ceuracle Vegan Kombucha Tea Lip Balm', 'dr-ceuracle-vegan-kombucha-tea-lip-balm', 'Ključne prednosti: Dubinska hidratacija: skvalan i shea puter zadržavaju vlagu i sprečavaju isušivanje. Obnova barijere: ceramid NP pomaže da usne ostanu zaštićene i glatke. Prirodna udobnost: lagana, nelepljiva tekstura pogodna za svaku priliku. Kome je namenjen? Idealan je za sve koji imaju suve, osetljive ili sklone pucanju usne, ali i za one koji žele svakodnevnu, vegansku negu bez viška. Posebno prija tokom vetrovitih dana, hladnih meseci, ili kada jednostavno želiš da tvoje usne izgledaju i osećaju se zdravo. Zašto volimo Dr. Ceuracle Vegan Kombucha Tea Lip Balm ? Ovaj balzam je kao nežan, ali dosledan prijatelj tvoje kože. Kombuča čaj pruža snažno antioksidativno dejstvo i štiti usne od spoljašnjih uticaja. Skvalan, biljni lipid sličan prirodnim uljima kože, prodire duboko i omekšava suvu površinu, dok shea puter pomaže u zaceljivanju ispucalih delova. Ceramid NP deluje kao štit koji obnavlja i jača zaštitnu barijeru usana. Ono što ga izdvaja jeste osećaj lakoće — ne ostavlja masni trag, ne lepi se i ne sija, već ostavlja usne mekim, nahranjenim i spremnim za osmeh. Sjajno funkcioniše i kao podloga za šminku, ali i kao samostalni saveznik u svakoj torbi. Aktivni sastojci Kombuča čaj (fermentisani ekstrakt čaja) Prirodni izvor antioksidanasa koji pomaže u zaštiti i revitalizaciji usana, poboljšava tonus i teksturu. Skvalan Biljno ulje koje imitira prirodne lipide kože, hidrira i omekšava bez osećaja težine. Ceramid NP Obnavlja zaštitni sloj kože usana i sprečava gubitak vlage, posebno kod izražene suvoće. Shea puter Dubinski neguje, umiruje i pomaže u regeneraciji osetljive i ispucale kože. Dodaj u listu želja Dodaj u listu želja', 'Dr. Ceuracle Vegan Kombucha Tea Lip Balm sadrži kombuča čaj bogat antioksidansima, biljni skvalan, shea puter i ceramid NP koji zajedno dubinski hrane, obnavljaju i štite osetljivu kožu usana. Savršen je izbor za suve, ispucale usne koje traže nežnu, ali efikasnu negu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Dr.-Ceuracle-Vegan-Kombucha-Tea-Lip-Balm-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
