INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (592, 49, 'Dr. Ceuracle AC Cure Solution Pink Gel', 'dr-ceuracle-ac-cure-solution-pink-gel', 'Ključne prednosti: Dubinsko čišćenje pora: razgrađuje nečistoće i višak sebuma unutar pora. Nežni piling: uklanja mrtve ćelije i osvetljava ten bez iritacije. Balans i hidratacija: umiruje kožu i jača njenu prirodnu zaštitnu funkciju. Kome je namenjena? Ovaj gel je idealan za masnu, mešovitu i aknoznu kožu, ali se može koristiti i kod osetljive kože koja reaguje na klasične čistače. Posebno je koristan u tinejdžerskom i postpubertetskom periodu, kao i kod osoba koje traže efikasno čišćenje bez agresivnih sastojaka. Zašto volimo Dr. Ceuracle AC Cure Solution Pink Gel? Gel ima blago kiselu pH vrednost i formulisan je tako da ne narušava prirodnu ravnotežu kože. Salicilna kiselina prodire u pore i razgrađuje sebum, što pomaže u borbi protiv mitisera i upala. PHA i AHA kiseline nežno uklanjaju mrtve ćelije sa površine kože, čineći ten ujednačenijim i glatkijim. Ceramidi i hijaluronska kiselina istovremeno vlaže i obnavljaju kožnu barijeru, čineći kožu otpornijom na spoljašnje uticaje. Biljni ekstrakti, poput centelle i zelenog čaja, dodatno umiruju crvenilo i iritacije. Redovnim korišćenjem, ten postaje čistiji, pore su vidljivo sužene, a koža je osvežena i mekana. Aktivni sastojci Salicilna kiselina BHA kiselina koja prodire duboko u pore, razgrađuje višak sebuma i pomaže u sprečavanju novih nepravilnosti. Deluje antibakterijski i smanjuje zapaljenja. Mlečna kiselina (AHA) Blagi eksfolijant koji uklanja površinske mrtve ćelije i osvetljava ten, uz dodatnu hidrataciju i poboljšanje teksture kože. Glukonolakton (PHA) Piling sastojak nove generacije koji pruža eksfolijaciju bez iritacije, idealan za osetljivu kožu. Takođe deluje kao antioksidans. Ceramidi Obnavljaju lipidnu barijeru kože, štiteći je od isušivanja i spoljašnjih iritacija. Posebno korisni kod osetljive i narušene kože. Hijaluronska kiselina Veže vlagu i pomaže da koža ostane hidrirana, elastična i puna. Daje osećaj svežine i prijatnosti nakon umivanja. Dodaj u listu želja Dodaj u listu želja', 'Dr. Ceuracle AC Cure Solution Pink Gel kombinuje salicilnu kiselinu (BHA), mlečnu kiselinu (AHA) i glukonolakton (PHA) sa ceramidima, hijaluronskom kiselinom i biljnim ekstraktima. Doprinosi čistijem tenu, smanjenju nepravilnosti i očuvanju zdrave barijere kože.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Dr.-Ceuracle-AC-Cure-Solution-Pink-Gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
