INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (596, 42, 'CP‑1 Bright Complex Intense Nourishing Shampoo', 'cp-e2-80-911-bright-complex-intense-nourishing-shampoo', 'Ključne prednosti: Obnavlja i jača vlas: proteinski kompleks prodire u strukturu dlake i čini je elastičnijom i otpornijom. Pruža hidrataciju i sjaj: prirodna ulja i ceramidi omekšavaju kosu i poboljšavaju njen izgled bez otežavanja. Umiruje i balansira teme: ekstrakt sladića i pantenol pomažu kod iritacija i održavaju zdrav mikrobiom kože glave. Kome je namenjen? Preporučuje se za suvu, hemijski tretiranu, oštećenu i lomljivu kosu, kao i za osobe sa osetljivim temenom. Odličan je izbor i za one koji žele svakodnevnu negu bez agresivnih sastojaka. Zašto volimo CP‑1 Bright Complex Intense Nourishing Shampoo? Ovaj šampon je odličan izbor za kosu kojoj nedostaje snage, elastičnosti i vitalnosti. Zahvaljujući složenom proteinskom kompleksu, on popunjava oštećenja u strukturi vlasi i smanjuje njenu lomljivost. Ceramidi pomažu da se sačuva vlažnost i ojača zaštitna barijera, dok prirodna ulja obavijaju vlas i čine je glatkom i sjajnom. Istovremeno, pantenol deluje umirujuće na teme i poboljšava hidrataciju kože glave. Ekstrakt sladića ima protivupalno dejstvo, pa je posebno koristan ako je teme nadraženo ili sklono perutanju. Tekstura šampona je prijatna, lako se nanosi i ispira, ostavljajući kosu čistom, laganom i zdravog izgleda. Aktivni sastojci Hidrolizovani keratin, kolagen, elastin, svila i proteini soje Ova kombinacija obnavlja oštećenu strukturu vlasi, povećava njenu otpornost i elastičnost. Čini kosu glatkom i otpornijom na spoljašnje uticaje i mehanička oštećenja. Ceramidi i aminokiseline Pomažu u očuvanju vlažnosti dlake, jačaju njenu spoljašnju barijeru i smanjuju dehidrataciju. Dlaka postaje glatkija i manje porozna. Prirodna ulja (argan, jojoba, kokos, kamelija) Omekšavaju kosu, čine je sjajnom i lakšom za oblikovanje. Ne otežavaju vlas niti ostavljaju mastan trag, već joj daju elastičnost i mekoću. Ekstrakt sladića Umiruje kožu glave, deluje protivupalno i pomaže kod osećaja zatezanja, svraba ili perutanja. Balansira stanje temena i doprinosi zdravijem rastu kose. Pantenol (provitamin B5) Obnavlja i hidrira i kosu i teme, poboljšava elastičnost dlake i pomaže u očuvanju prirodne vlažnosti kože glave. Dodaj u listu želja Dodaj u listu želja', 'CP‑1 Bright Complex Intense Nourishing Shampoo sadrži kombinaciju hidrolizovanih proteina (keratin, svila, kolagen, elastin i soja), ceramida, prirodnih ulja i ekstrakta sladića. Njegova formula jača dlaku iznutra, hidrira i vraća prirodan sjaj, dok istovremeno umiruje teme.', 'https://beauty-health.rs/wp-content/uploads/2025/07/CP‑1-Bright-Complex-Intense-Nourishing-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
