INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (597, 42, 'CP‑1 Bright Complex Intense Nourishing Conditioner', 'cp-e2-80-911-bright-complex-intense-nourishing-conditioner', 'Ključne prednosti: Obnova strukture dlake: proteini popunjavaju oštećenja i čine vlas elastičnijom i otpornijom. Hidratacija i zaštita: ceramidi i biljna ulja pomažu u zadržavanju vlage i stvaranju zaštitnog sloja. Nežna nega temena: ekstrakt sladića i pantenol umiruju skalp i sprečavaju iritacije. Kome je namenjen? Preporučuje se osobama sa suvom, hemijski tretiranom, farbanom ili lako lomljivom kosom. Pogodan je i za one sa osetljivim temenom, kao i za svakodnevnu negu kose kojoj je potrebna obnova bez otežavanja. Zašto volimo CP‑1 Bright Complex Intense Nourishing Conditioner? Ovaj regenerator je osmišljen za one kojima je kosa postala lomljiva, suva i teško se oblikuje. Zahvaljujući kompleksu proteina – uključujući keratin, kolagen, svilu i elastin – vlakna kose postaju jača, otpornija na pucanje i fleksibilnija. Ceramidi i aminokiseline pomažu da se obnovi zaštitna barijera vlasi, zadržava se vlaga i smanjuje se poroznost. Prirodna ulja, poput arganovog, jojobinog i kokosovog, hrane kosu i obavijaju je tankim, nelepljivim slojem koji daje sjaj i glatkoću. Pantenol dodatno umiruje teme i deluje regenerativno, dok ekstrakt sladića ima protivupalno dejstvo, što je posebno korisno za osetljiva ili nadražena temena. ﻿ Aktivni sastojci Hidrolizovani keratin, kolagen, elastin, svila i proteini pšenice Ova kombinacija proteina prodire u vlas i obnavlja je iznutra. Čine kosu jačom, otpornijom na pucanje i elastičnijom, dok joj istovremeno vraćaju prirodnu glatkoću i sjaj. Ceramidi i aminokiseline Pomažu u očuvanju vlažnosti i jačaju spoljašnju zaštitnu barijeru vlasi. Takođe doprinose zaglađivanju površine dlake, smanjujući naelektrisanost i raspršen izgled. Arganovo, jojobino i kokosovo ulje Prirodni emolijensi koji neguju i hrane kosu, omekšavaju je i olakšavaju oblikovanje. Ne ostavljaju mastan trag, već daju zdravi sjaj i mekoću. Ekstrakt sladića Poznat po svom umirujućem i protivupalnom delovanju, posebno je koristan kod osetljivog ili iritiranog temena. Pomaže u balansiranju lučenja sebuma i umanjuje svrab. Dodaj u listu želja Dodaj u listu želja', 'CP‑1 Bright Complex Intense Nourishing Conditioner kombinuje hidrolizovane proteine pšenice, svile, kolagena i elastina sa prirodnim uljima i ceramidima. Njegova formula jača oštećene vlasi, hidrira ih i olakšava raščešljavanje.', 'https://beauty-health.rs/wp-content/uploads/2025/07/CP‑1-Bright-Complex-Intense-Nourishing-Conditioner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
