INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (598, 42, 'CP-1 Aquaxyl Complex Intense Moisture Shampoo', 'cp-1-aquaxyl-complex-intense-moisture-shampoo', 'Ključne prednosti: Hidratacija bez isušivanja: Aquaxyl kompleks zadržava vlagu unutar vlasi i jača njenu otpornost. Obnova strukture kose: proteini i ceramidi popunjavaju oštećenja, čineći kosu jačom i otpornijom na lomljenje. Nežna formula: bez sulfata, pogodna i za osetljivo teme, ne izaziva svrab ni zatezanje. Kome je namenjen? Preporučuje se osobama sa suvom, oštećenom, farbanom ili hemijski tretiranom kosom, kao i onima koji žele šampon bez agresivnih sastojaka. Pogodan je i za svakodnevnu upotrebu kod osetljivog temena. Zašto volimo CP‑1 Aquaxyl Complex Intense Moisture Shampoo? Ovaj šampon je formulisan kao balans između temeljnog čišćenja i nežne nege. Zahvaljujući Aquaxyl kompleksu (glukoza i ksilitol), zadržava vlagu u vlasi, sprečava isušivanje i pruža dugotrajnu elastičnost. Hidrolizovani proteini svile, keratina, kolagena i elastina deluju kao „ispuna“ za napukle i oštećene delove dlake. Ceramidi dodatno jačaju spoljašnji sloj vlasi i štite je od spoljašnjih uticaja. Prirodna ulja, poput arganovog i jojobinog, obavijaju dlaku tankim slojem, vraćaju sjaj i olakšavaju raščešljavanje. Redovnom upotrebom kosa postaje vidljivo mekša, punija, elastičnija i zdravijeg izgleda. https://www.youtube.com/watch?v=24PUk8FAQcE&ab_channel=ICONMARKET Aktivni sastojci Aquaxyl kompleks (glukoza + ksilitol) Ovaj kompleks hidrira vlasi iznutra, smanjuje gubitak vode i obnavlja prirodnu ravnotežu vlage, čime se sprečava dehidratacija i suvoća kose. Hidrolizovani keratin, kolagen, svila i elastin Ovi proteini prodiru u vlas, popravljaju mikrooštećenja i čine kosu otpornijom, glatkijom i sjajnijom. Ceramidi Obnavljaju zaštitni sloj kose, jačaju njenu barijeru i smanjuju osetljivost na spoljni stres, poput toplote, hemikalija i UV zračenja. Ulje argana i jojobe Hrane kosu, omekšavaju je i daju prirodan sjaj bez otežavanja. Idealni su za suve i ispucale krajeve. Ekstrakt smeđe alge (fucoidan) Deluje umirujuće i antioksidativno, štiti vlas od slobodnih radikala i smanjuje perutanje temena. Dodaj u listu želja Dodaj u listu želja', 'CP-1 Aquaxyl Complex Intense Moisture Shampoo sadrži patentirani Aquaxyl kompleks, hidrolizovane proteine, ceramide i biljna ulja koji zajedno jačaju kosu, sprečavaju isušivanje i vraćaju prirodan sjaj. Idealan je za one koji žele nežno čišćenje bez oduzimanja prirodne vlage iz vlasi.', 'https://beauty-health.rs/wp-content/uploads/2025/07/CP-1-Aquaxyl-Complex-Intense-Moisture-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
