INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (601, 42, 'CP‑1 3 Seconds Hair Ringer Hair Fill‑up Ampoule', 'cp-e2-80-911-3-seconds-hair-ringer-hair-fill-e2-80-91up-ampoule', 'Ključne prednosti: Brza transformacija: u dodiru s vodom ampula prelazi u hranljivu kremu koja se lako nanosi i brzo deluje. Dubinska obnova: proteini i ceramidi popunjavaju oštećenja i jačaju kosu iznutra. Mekoća i sjaj: kosa postaje svilenkasta, podatna i lakša za oblikovanje. Kome je namenjena? Ova ampula je idealna za sve tipove kose koji su oštećeni feniranjem, peglanjem, farbanjem ili izbjeljivanjem. Posebno je korisna za tanku, poroznu, suvu i lomljivu kosu kojoj nedostaje snaga i sjaj. Zašto volimo CP‑1 3 Seconds Hair Ringer Hair Fill‑up Ampoule? Ovaj tretman je formulisan tako da deluje brzo, ali temeljno – već pri prvom kontaktu s vodom, ampula se pretvara u kremastu masku koja prodire duboko u vlas. Keratin i ostali proteini popunjavaju porozna mesta i učvršćuju strukturu kose, dok ceramidi stvaraju zaštitni sloj koji sprečava dalje oštećenje. Svila i kolagen doprinose mekoći i elastičnosti, dok pantenol hidrira i umiruje vlasište. Rezultat je kosa koja izgleda zdravije, sjajnije i znatno glađe – čak i kod izrazito oštećene i suve kose. Aktivni sastojci Hidrolizovani keratin Popunjava oštećene delove vlasi i jača njenu strukturu, čineći kosu otpornijom i manje sklonom lomljenju. Hidrolizovani kolagen i elastin Povećavaju elastičnost i fleksibilnost kose, doprinoseći njenoj vitalnosti i zdravijem izgledu. Hidrolizovana svila Zadržava vlagu u dlaci, čineći je glatkom, sjajnom i lakšom za oblikovanje. Ceramidi Pomažu u obnovi zaštitnog sloja kose, štite od spoljašnjih uticaja i smanjuju isušivanje. Pantenol (provitamin B5) Hidrira kosu i vlasište, umiruje iritacije i doprinosi mekoći i punom izgledu vlasi. Mentol Daje blagi osećaj svežine i pomaže u smirivanju vlasišta, naročito posle termičke obrade. Dodaj u listu želja Dodaj u listu želja', 'CP‑1 3 Seconds Hair Ringer Hair Fill‑up Ampoule sadrži hidrolizovani keratin, kolagen, elastin, svilu, ceramide i pantenol koji zajedno dubinski obnavljaju vlas, vraćaju elastičnost i štite kosu od daljeg lomljenja. Tretman daje vidljiv rezultat već nakon prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/07/CP‑1-3-Seconds-Hair-Ringer-Hair-Fill‑up-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
