INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (603, 23, 'Belif Super Knights Multi Vitamin Mask', 'belif-super-knights-multi-vitamin-mask', 'Ključne prednosti: Blistav i ujednačen ten: vitamini posvetljuju i osvetljavaju siv i umoran ten. Dubinska hidratacija: glicerin i maslinovo ulje obezbeđuju vlagu bez masnog osećaja. Jačanje barijere: kombinuju se antioksidansi i umirujući biljni ekstrakti za zaštitu zdravlja kože. Kome je namenjena? Ova maska je idealna za sve tipove kože, naročito za umornu, beživotnu ili dehidriranu kožu kojoj treba dodatna nega tokom noći. Posebno je pogodna za one koji žele da imaju blistav i ujednačen ten bez napora. Zašto volimo Belif Super Knights Multi Vitamin Mask? Ova maska deluje poput snažnog, hranljivog poklona za umornu kožu – dok ti spavaš, ona intenzivno hidrira i pojačava prirodni sjaj tena. Formula je kremasta, ali se brzo razmazuje i ne ostavlja težinu ni ujutru. Niacinamid i vitamin C rade na ujednačavanju tena i smanjenju diskoloracija koje donosi stres i umor. Vitamin B12 jača barijeru kože, dok vitamin E pruža antioksidativnu zaštitu. Biljni ekstrakti poput zobi, kamilice i drugih omekšavaju i smiruju kožu, dok glicerin i ulje suncokreta obezbeđuju dugotrajnu vlagu. Aktivni sastojci Niacinamid (vitamin B3) Ujednačava ten, smanjuje diskoloracije i pojačava barijeru kože. Kojži rezultuje glatkijom, blistavijom i jasnijom površinom. Vitamin C (askorbinska kiselina) Osvežava i posvetljuje ten, pomaže u neutralisanju oksidativnog stresa i doprinosi zdravoj energiji kože. Vitamin B12 (cijanokobalamin) Snažno podržava funkciju barijere kože i pomaže u obnovi oštećenih zona. Doprinosi ravnomernijem i energičnijem izgleda lica. Vitamin E (tokoferol) Hrana i štiti kožu kao antioksidans, smanjuje iritacije i stvara prijatan osećaj hidracije. Biljni ekstrakti (zob, kamilica, malina, list breze i druge biljke) Umiruju i regenerišu kožu, smanjuju crvenilo i dodatno povećavaju osećaj komfora. Dodaj u listu želja Dodaj u listu želja', 'Belif Super Knights Multi Vitamin Mask je bogata kremasta noćna maska koja kombinuje vitamin B3 (niacinamid), vitamin C, vitamin E i vitamin B12 s ciljem da koži pruži intenzivnu negu tokom sna. Namenjena je umornoj, sivkastoj koži kojoj nedostaje sjaj i energija.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Belif-Super-Knights-Multi-Vitamin-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
