INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (605, 11, 'Anua PDRN 100 Hyaluronic Acid Glow Pad', 'anua-pdrn-100-hyaluronic-acid-glow-pad', 'Ključne prednosti: Intenzivna hidratacija: hijaluronska kiselina u više oblika puni kožu vlagom i daje joj elastičnost. Obnova i zatezanje: PDRN i peptidi stimulišu kolagen i obnavljaju tonus. Blagi piling: tekstura jastučića uklanja mrtve ćelije i osvežava ten. Kome su namenjeni? Idealni su za sve tipove kože kojima nedostaje hidratacija, sjaj i elastičnost. Savršeni su za umornu, sivkastu kožu ili kada želiš instant efekat svežine pre šminke. Zašto volimo Anua PDRN 100 Hyaluronic Acid Glow Pad? Ovi jastučići su kao mini maske koje koži u samo par minuta vraćaju život. Gelasta strana bogato hidrira i hrani, dok meka strana blago uklanja nečistoće i ravnomerno raspoređuje esenciju. PDRN podstiče obnavljanje ćelija i vraća koži čvrstinu, dok peptidni kompleks daje efekt zatezanja i zaglađivanja. Hijaluronska kiselina u više molekularnih oblika prodire u različite slojeve kože i zadržava vlagu, ostavljajući kožu punijom i sjajnijom. Biljni ekstrakti umiruju crvenilo i štite kožu od spoljašnjih iritacija. Već nakon jednog korišćenja lice izgleda svežije i odmornije. Aktivni sastojci PDRN (lososova DNK) Stimuliše regeneraciju i sintezu kolagena, obnavlja kožu i poboljšava njenu elastičnost. Hijaluronska kiselina Višeslojno hidrira, popunjava sitne linije i sprečava gubitak vlage, čineći kožu glatkom i punijom. Peptidni kompleks Podstiče obnovu ćelija, zateže i učvršćuje kožu, vraćajući joj mladalački izgled. Niacinamid Ujednačava ten, smanjuje crvenilo i vraća koži prirodan sjaj. Biljni ekstrakti Deluju umirujuće, štite kožu od iritacija i pružaju antioksidativnu zaštitu. Dodaj u listu želja Dodaj u listu želja', 'Anua PDRN 100 Hyaluronic Acid Glow Pad su dvostrani jastučići natopljeni esencijom sa hijaluronskom kiselinom, PDRN‑om (kolagen iz lososove DNK) i peptidima. Namenjeni su za trenutnu hidrataciju, osvetljavanje i zatezanje kože, uz blagi piling efekat.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Anua-PDRN-100-Hyaluronic-Acid-Glow-Pad-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
