INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (606, 4, 'A’pieu Honey & Milk Lip Oil', 'a-pieu-honey-milk-lip-oil', 'Ključne prednosti: Hidratacija i mekoća: med i mlečni proteini čine usne glatkim i nahranjenim. Zaštita i elastičnost: vitamin E štiti usne i pruža im zdrav izgled. Sjaj bez osećaja ulja: tekstura je gusto sjajna, ne klizi i prijatno prianja. Kome je namenjen? Ovaj proizvod je idealan za sve sa suvim ili ispucalim usnama koji žele hranjenje uz prijatnu teksturu, bez lepljenja. Odgovara svima koji traže negu usana u pokretu, posebno u hladnijim mesecima. Zašto volimo A’PIEU Honey & Milk Lip Oil? Ovaj proizvod kombinuje kremastu teksturu balzama i sjajna efekta – ali ne ostaje klizav kao ulje. Kada ga naneseš, odmah osetiš mekoću i udobnost zahvaljujući medu i mlečnim proteinima. Vitamin E štiti osetljivu kožu usana i umanjuje osećaj neprijatnosti. Iako ima sjajnu završnicu, ne lepi izrazito i neće kliziti kada pričaš ili piješ vodu. Može se koristiti samostalno ili preko mat ruža da doda finu vlažnost i blagi odsjaj. Aktivni sastojci Mlečni proteini Dubinski hidratišu i omekšavaju usne, vraćajući im elastičnost i osveženo barširast izgled. Ekstrakt meda Prirodni humektant koji privlači vlagu, smiruje i hrani osetljivu kožu usana dok donosi blag i prijatan miris. Vitamin E (tokoferil acetat) Antioksidans koji štiti od spoljašnjih uticaja i pomaže u regeneraciji osetljive kože usana. Emolijenti (npr. polybutene, hydrogenated polyisobutene) Čine formulu gušćom, formiraju zaštitni film na usnama i sprečavaju gubitak vlage, bez osećaja težine – formula ne sadrži prave ulja. Dodaj u listu želja Dodaj u listu želja', 'A’PIEU Honey & Milk Lip Oil je sjaj za usne koji izgleda kao ulje, ali se oseća i ponaša kao gusti balzam – sa ekstraktom meda, mlečnih proteina i vitaminom E. Namenjen je da dubinski hidrira, zaštiti i pruži prirodni sjaj bez grebanja ili težine.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APIEU-Honey-Milk-Lip-Oil-PEACH-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
