INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (607, 4, 'A’pieu Honey Milk Lip Scrub', 'a-pieu-honey-milk-lip-scrub', 'Ključne prednosti: Nežna eksfolijacija: fine čestice ljuske oraha uklanjaju mrtve ćelije bez iritacije. Dubinska nega: med i mlečni proteini hrane usne i čine ih glatkijima. Zaštita i hidratacija: vitamin E i skvalan štite od isušivanja i vraćaju mekoću. Kome je namenjen? Idealan je za sve koji imaju problem sa suvim, ispucalim ili grubim usnama i žele nežnu, ali efikasnu negu. Zašto volimo A’PIEU Honey Milk Lip Scrub? Ovaj piling deluje kao mali spa tretman za usne. Dok lagano masiraš usne, fine čestice uklanjaju suve delove, a med i mlečni proteini pružaju bogatu hidrataciju i ishranu. Skvalan i vitamin E formiraju zaštitni sloj, sprečavajući da se vlaga izgubi, dok glicerin dodatno zadržava vlagu. Formula je dovoljno blaga za redovnu upotrebu i ne ostavlja osećaj peckanja ili zatezanja. Posle korišćenja, usne izgledaju mekano, glatko i spremne su za balzam ili ruž. Aktivni sastojci Ljuska oraha Deluje kao prirodni piling, uklanja mrtve ćelije bez oštećenja nežne kože usana. Med Prirodni humektant koji privlači vlagu, hrani i regeneriše usne. Mlečni proteini Pomažu da usne postanu mekane i hidrirane, vraćajući im elastičnost. Vitamin E Štiti usne od spoljašnjih uticaja, omekšava ih i ubrzava regeneraciju. Skvalan Stvara zaštitni film koji čuva vlagu i čini usne glatkima. Glicerin Hidrira i zadržava vlagu unutar kože, pružajući dugotrajan osećaj mekoće. Dodaj u listu želja Dodaj u listu želja', 'A’PIEU Honey Milk Lip Scrub je nežni piling za usne obogaćen medom, mlečnim proteinima i vitaminom E. Njegova kremasta formula sa finim česticama uklanja mrtve ćelije kože, omekšava i ostavlja usne glatkim i hidriranim.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APIEU-Honey-Milk-Lip-Scrub.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
