INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (610, 174, 'VT Cosmetics Glucamune Mask', 'vt-cosmetics-glucamune-mask', 'Ključne prednosti: Brza hidratacija: biljni mukin i skvalan obnavljaju vlažnost i čine kožu glatkom. Umiruje iritacije: pantenol i alantoin smanjuju crvenilo i nelagodnost. Blistav izgled: formula vraća sjaj i osvežava ten bez lepljivog osećaja. Kome su namenjeni? Maska je idealna za sve tipove kože, posebno za suvu, dehidriranu i osetljivu kožu sklonu crvenilu. Odlična je i za regeneraciju kože nakon izlaganja vetru, suncu ili stresa. Zašto volimo VT Cosmetics Glucamune Mask? Ova maska je poput hladnog napitka za žednu kožu – već nakon jednog nanošenja koža postaje mekša i smirenija. Glucamune, biljni mukin koji potiče iz snežne gljive, poznat je po tome što zadržava vlagu bolje čak i od hijaluronske kiseline. Pantenol i alantoin dodatno umiruju nadraženost i pomažu koži da se brže oporavi. Skvalan sprečava gubitak vlage i daje osećaj svilenkastog finiša. Tekstura esencije u maski je lagana, ne lepi se i brzo se upija, a nakon korišćenja lice izgleda odmorno i osveženo. Aktivni sastojci Glucamune (biljni mukin) Prirodni humektant koji dubinski hidrira i štiti kožu, čineći je mekom i elastičnom. Stvara zaštitni sloj koji čuva vlagu tokom celog dana. Pantenol (provitamin B5) Umiruje, smanjuje iritacije i ubrzava proces regeneracije kože, pružajući dugotrajan osećaj komfora. Alantoin Poznat po blagom umirujućem dejstvu, pomaže da se koža oporavi i ostane glatka i mekana. Skvalan Hidrirajući sastojak koji oponaša prirodne lipide kože i sprečava isušivanje, ostavljajući kožu svilenkastom. Beta-glukan Doprinosi smanjenju crvenila i obnavlja prirodnu zaštitnu barijeru kože. Ekstrakt snežne gljive Daje koži dodatnu vlagu i blistavost, dok umiruje i štiti od spoljašnjih faktora. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Glucamune Mask je sheet maska, natopljena bogatom esencijom sa biljnim mukinom (glucamune), pantenolom, skvalanom i alantoinom. Dizajnirana je da trenutno umiri i intenzivno hidrira kožu, vraćajući joj mekoću i osećaj svežine.', 'https://beauty-health.rs/wp-content/uploads/2025/07/VT-Cosmetics-Glucamune-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
