INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (611, 174, 'VT Cosmetics Garlic AC Reedle Shot Spot Cream', 'vt-cosmetics-garlic-ac-reedle-shot-spot-cream', 'Ključne prednosti: Ciljano delovanje: krema se nanosi direktno na bubuljicu i ubrzava njeno smirivanje. Umiruje i štiti: kombinacija čajevca i centelle smanjuje crvenilo i sprečava širenje upale. Lagana i nemasna: brzo se upija i ne ostavlja lepljiv trag. Kome je namenjena? Ova krema je savršena za kožu sklonu bubuljicama, crvenilu i upalnim promenama. Pogodna je za masnu, kombinovanu i problematičnu kožu kojoj je potrebna brza i nežna pomoć. Zašto volimo VT Cosmetics Garlic AC Reedle Shot Spot Cream? Spot krema deluje kao lokalni tretman koji brzo ublažava bol i crvenilo na mestima gde se pojavljuju upaljene promene. Ekstrakt belog luka poznat je po svom antiseptičkom dejstvu i pomaže da se spreči rast bakterija, dok čajevac dodatno čisti i umiruje. Niacinamid posvetljuje tragove i smanjuje vidljivost ožiljaka, a pantenol i alantoin obezbeđuju hidrataciju i smiruju nadraženost. Lagana tekstura omogućava da se krema koristi čak i ispod šminke, a nevidljivi finiš čini je praktičnom za dan i noć. Redovnim korišćenjem koža postaje mirnija i manje sklona novim upalama. Aktivni sastojci Ekstrakt belog luka Prirodni antibakterijski sastojak koji deluje na uzrok upala i ubrzava smirivanje problematičnih mesta. Ne iritira kožu i ne ostavlja miris belog luka. Čajevac Poznat po svom snažnom antiseptičkom dejstvu, čajevac pomaže u smirivanju crvenila i smanjenju upalnih procesa. Centella asiatica Biljni ekstrakt koji ubrzava regeneraciju i jača kožnu barijeru, smanjujući rizik od ožiljaka. Niacinamid Pomaže u ujednačavanju tena i smanjenju tragova od bubuljica, dok istovremeno jača zaštitnu funkciju kože. Salicilna kiselina Pročišćava pore, uklanja višak sebuma i deluje preventivno na nastanak novih bubuljica. Pantenol i alantoin Umiruju, hidriraју i štite kožu od iritacija, ostavljajući je glatkom i mekom. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Garlic AC Reedle Shot Spot Cream je ciljana krema koja deluje direktno na upaljene bubuljice i crvene tačkice. Njena lagana gelasta tekstura umiruje kožu, smanjuje iritacije i ubrzava zaceljivanje, bez isušivanja okolnih delova lica.', 'https://beauty-health.rs/wp-content/uploads/2025/07/VT-Cosmetics-Garlic-AC-Reedle-Shot-Spot-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
