INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (612, 174, 'VT Cosmetics Garlic AC Reedle Shot Point Patch', 'vt-cosmetics-garlic-ac-reedle-shot-point-patch', 'Ključne prednosti: Brza pomoć: flaster ublažava bol i upalu na mestu gde se bubuljica razvija. Ciljano delovanje: mikroskopske iglice pomažu da aktivni sastojci prođu direktno do mesta upale. Diskretno nošenje: flaster je tanak, neprimetan na koži i odlično prianja, čak i tokom noći. Kome su namenjeni? Ovi flasteri su savršeni za kožu sklonu aknama, upalama i bolnim bubuljicama koje želiš da umiriš brzo i diskretno. Pogodni su za sve tipove kože, uključujući i osetljivu. Zašto volimo VT Cosmetics Garlic AC Reedle Shot Point Patch? Patch se postavlja na bubuljicu i deluje kao nevidljivi štit, dok mikroskopske iglice otpuštaju umirujuće i antibakterijske sastojke direktno u kožu. Ekstrakt belog luka poznat je po svom antiseptičkom dejstvu, dok čajevac i centella smanjuju crvenilo i ubrzavaju zaceljivanje. Pantenol i alantoin dodatno umiruju kožu, sprečavajući iritaciju. Za razliku od klasičnih flastera koji samo pokrivaju bubuljicu, ovaj aktivno radi na njenom uklanjanju i sprečava da ostane crvena ili ožiljena. Tanak je i čvrsto stoji na koži, pa ga možeš nositi čak i tokom dana ispod šminke. Aktivni sastojci Ekstrakt belog luka Deluje antibakterijski, smanjuje širenje bakterija koje izazivaju bubuljice i pomaže u smirivanju upala. Čajevac Jedan od najpoznatijih prirodnih sastojaka za problematičnu kožu, čajevac deluje protiv bakterija i smanjuje crvenilo. Centella asiatica Biljni ekstrakt koji ubrzava regeneraciju, smanjuje iritacije i vraća koži balans. Pantenol Poznat kao provitamin B5, pantenol umiruje kožu, pomaže u zaceljivanju i hidrira. Mikroiglice (reedle tehnologija) Izuzetno sitne iglice od prirodnog materijala koje otvaraju put aktivnim sastojcima do dubljih slojeva kože za efikasnije delovanje. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Garlic AC Reedle Shot Point Patch su mali flasteri koji deluju kao SOS pomoć za bubuljice u nastajanju. Postavljaju se direktno na problematično mesto i, zahvaljujući mikroskopskim iglicama i aktivnim sastojcima, smiruju upalu i ubrzavaju nestajanje bubuljica, bez agresivnog sušenja .', 'https://beauty-health.rs/wp-content/uploads/2025/07/VT-Cosmetics-Garlic-AC-Reedle-Shot-Point-Patch-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
