INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (615, 156, 'Some By Mi Real Honey Luminous Care Mask', 'some-by-mi-real-honey-luminous-care-mask', 'Ključne prednosti: Hranljivost i sjaj: med intenzivno hrani i vraća prirodan sjaj tenu. Hidratacija bez težine: hijaluronska kiselina puni kožu vlagom, a ne ostavlja lepljiv trag. Umirenje i zaštita: pantenol i biljni ekstrakti smanjuju crvenilo i jačaju kožnu barijeru. Kome je namenjena? Ova maska je savršena za suvu, umornu i dehidriranu kožu kojoj je potrebno trenutno osveženje i doza sjaja. Odlična je i kao SOS tretman posle stresnog dana ili izlaganja suncu. Zašto volimo SOME BY MI Real Honey Luminous Care Mask? Ova maska deluje kao instant tretman za umornu kožu. Med je poznat po svom antioksidativnom i umirujućem dejstvu – hrani i omekšava lice, dok hijaluronska kiselina zadržava vlagu i vraća punoću. Pantenol dodatno smiruje i obnavlja kožu, dok ekstrakti biljaka poput breze i portulaka deluju osvežavajuće i štite od spoljašnjih agresora. Sama esencija je svilenkasta i brzo se upija, pa lice ostaje hidrirano, ali bez masnog filma. Već posle jedne upotrebe, koža izgleda odmorno i zdravije. Aktivni sastojci Med Med dubinski hrani, omekšava i obnavlja kožu. Njegova antioksidativna svojstva štite od prevremenog starenja, dok antibakterijski efekat pomaže da koža ostane čista i zdrava. Hijaluronska kiselina Deluje kao magnet za vlagu, čineći kožu punijom i glatkom. Daje osećaj svežine i mekoće, uz dugotrajnu hidrataciju. Dodaj u listu želja Dodaj u listu želja', 'SOME BY MI Real Honey Luminous Care maska je nežna maska koja koži vraća život zahvaljujući pravom medu, hijaluronskoj kiselini i pantenolu. Prija licu kao umirujući oblog, hrani ga i ostavlja baršunasto mekim i sjajnim.', 'https://beauty-health.rs/wp-content/uploads/2025/07/SOME-BY-MI-Real-Honey-Luminous-Care-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
