INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (616, 156, 'Some By Mi Galactomyces Glutathione Glow Milky Toner', 'some-by-mi-galactomyces-glutathione-glow-milky-toner', 'Ključne prednosti: Intenzivna hidratacija: galaktomices i hijaluronska kiselina pune kožu vlagom i vraćaju elastičnost. Posvetljivanje tena: glutation i niacinamid umanjuju pigmentaciju i neujednačen ton. Jačanje barijere: ceramidi i vitamini štite i obnavljaju kožu. Kome je namenjen? Ovaj toner je odličan za kožu koja je sklona suvoći, neujednačenom tonu i gubitku sjaja. Pogodan je za sve tipove kože, posebno za umornu i beživotnu kožu kojoj je potrebna dodatna energija i hidratacija. Zašto volimo SOME BY MI Galactomyces Glutathione Glow Milky Toner? Toner ima kremastu, mlečnu teksturu koja se topi na koži i trenutno daje osećaj svežine i punoće. Fermentisani galaktomices, bogat aminokiselinama i vitaminima, pomaže u obnovi prirodne barijere i daje koži glatkoću. Glutation, moćan antioksidans, zajedno sa niacinamidom, deluje na tamne mrlje i umoran izgled, čineći ten ujednačenijim. Hijaluronska kiselina zadržava vlagu u dubljim slojevima kože, dok ceramidi dodatno jačaju zaštitni sloj. Zahvaljujući balansiranoj formuli, koža postaje mekša, vidno nahranjena i sjajna bez osećaja težine. Aktivni sastojci Galactomyces ferment filtrat (86 %) Fermentisani galaktomices je bogat vitaminima, aminokiselinama i mineralima koji obnavljaju i dubinski hrane kožu. Doprinosi elastičnosti i mekšem osećaju na dodir, dok smanjuje neujednačenu teksturu. Poboljšava upijanje ostalih aktivnih sastojaka i čini kožu sjajnijom. Glutation Glutation je snažan antioksidans koji smanjuje pigmentacijske mrlje i osvetljava sivkast ten. Štiti kožu od oksidativnog stresa i doprinosi zdravijem izgledu. Niacinamid Niacinamid ujednačava boju kože, smanjuje nepravilnosti i jača prirodnu zaštitnu barijeru. Deluje i na kontrolu sebuma, pa je pogodan i za mešovitu kožu. Hijaluronska kiselina Poznata po svojoj sposobnosti da zadržava vodu, hijaluronska kiselina hidrira i popunjava kožu iznutra, dajući joj glatkoću i volumen. Dodaj u listu želja Dodaj u listu želja', 'SOME BY MI Galactomyces Glutathione Glow Milky Toner je blagi mlečni toner sa čak 86 % fermentisanog galaktomicesa, glutationom i niacinamidom, osmišljen da intenzivno hidrira, posvetli i ujednači ten. Njegova hranljiva formula čini kožu mekom, elastičnom i vidno blistavijom.', 'https://beauty-health.rs/wp-content/uploads/2025/07/SOME-BY-MI-Galactomyces-Glutathione-Glow-Milky-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
