INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (618, 154, 'Skin1004 Madagascar Centella Hyalu‑Cica Brightening Toner', 'skin1004-madagascar-centella-hyalu-e2-80-91cica-brightening-toner', 'Ključne prednosti: Nežna eksfolijacija: AHA i LHA uklanjaju površinske nečistoće bez iritacija. Dubinska hidratacija: hijaluronski kompleks u više oblika vezuje vlagu i popunjava kožu. Umirivanje i posvetljivanje: centella voda smanjuje upalu, a niacinamid ujednačava ten. Kome je namenjen? Ovaj proizvod je idealan za zrelu, dehidriranu ili kožu sklone gubitku elastičnosti. Preporučuje se osobama od 30+ godina koje žele podići tonus i ujednačiti teksturu kože. Zašto volimo SKIN1004 Madagascar Centella Hyalu‑Cica Brightening Toner? Ovaj toner deluje kao temelj za osveženje i regeneraciju — zbog visoke koncentracije centelle voda deluje izuzetno umirujuće, dok blage kiseline uklanjaju mrtve ćelije i sprečavaju začepljene pore. Hijaluronski kompleks u tri oblika prodire dublje, zadržava vlagu i vraća koži puniji, gipkiji izgled. Niacinamid pomaže da se ten ujednači i daje koži sjajniji ton, a ceramid NP jača prirodnu barijeru i štiti od isušivanja. Tekstura je vodena i brzo se upija, ostavljajući svetlucav i svež finiš bez osećaja težine. Redovnim korišćenjem, koža postaje glađa, čvršća i manje sklona upalama. Aktivni sastojci Voda listova centella asiatice (74 %) Ovaj ekstrakt ima snažna umirujuća i regenerativna svojstva zahvaljujući madekaskozidu i azijatiosidu koji stimulišu sintezu kolagena i ubrzavaju zaceljivanje. Deluje protiv upala i povećava otpornost kože na stresore. Pomaže u smanjenju crvenila i nežno umiruje nadražene zone. Visoka koncentracija omogućava trenutni osećaj olakšanja i hidratacije. Doprinosi dugoročnom jačanju zaštitne barijere. Hijaluronska kiselina (trostruki oblik) Kombinacija natrijum hijaluronata, hidrolizovane i klasične hijaluronske kiseline omogućava višeslojnu hidrataciju. Svaki oblik cilja određeni sloj kože — površinski ili dublje u dermis — pružajući trenutni osjećaj glatkoće i dugotrajne elastičnosti. Preko njih se koža puni vlagom i zateže sitne linije. Niacinamid Vitamin B3 u ovom toniku deluje višeslojno: ujednačava pigmentaciju, smanjuje crvene mrlje i reguliše lučenje sebuma. Takođe poboljšava sintezu ceramida, jačajući barijeru i sprečavajući gubitak vlage. Doprinosi blažom i ujednačenijem izgledu kože, uz minimiziranje pora. Pomaže i kod upalnih procesa i akni kao antiinflamatorni sastojak. Dugoročnim korišćenjem ten dobija zdraviji sjaj. Citrična kiselina (AHA) Blago ljušti površinski sloj kože, uklanjajući mrtve ćelije i zaglađujući teksturu. Ne isušuje zahvaljujući formulaciji s pH vrednošću prilagođenom osetljivoj koži. Pomaže pri posvetljivanju tena i podstiče obnavljanje ćelija. Povećava efekt hidratacije jer površinski sloj bolje primaju vlagu. Ne iritira čak ni kod kombinovane kože. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Hyalu‑Cica Brightening Toner je osvežavajući tonik sa 74 % vode listova centelle asiatice, hijaluronskom kiselinom, niacinamidom, keramidom i blagim AHA/LHA kiselinama. Namenjen je da nežno eksfoliše, hidrira i posvetljuje ten, dok umiruje osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/SKIN1004-Hyalu‑Cica-Brightening-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
