INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (620, 143, 'Round Lab Birch Juice Moisturizing Pad', 'round-lab-birch-juice-moisturizing-pad', 'Ključne prednosti: Intenzivna hidratacija: sok breze i Aquaxyl obnavljaju nivo vlage i jačaju barijeru kože. Umirenje i svežina: pantenol i alantoin smanjuju iritacije i crvenilo. Brza apsorpcija: lagana, vodena tekstura sa niskim pH vrednostima brzo prodire u kožu i osvežava je bez lepljivog osećaja. Kome je namenjen? Pogodni su za sve tipove kože, posebno za dehidriranu, umornu i osetljivu kožu koja traži dodatnu negu. Odlični su i za korišćenje nakon izlaganja suncu ili vetru, kao i za kožu koja gubi sjaj i tonus. Zašto volimo ROUND LAB Birch Juice Moisturizing Pad ﻿ Ovi jastučići rade kao višefunkcionalna mini‑maska koja trenutno vraća vlagu i olakšava osećaj suvoće. Sok breze bogat mineralima i aminokiselinama hladi i smiruje nadraženost, dok Aquaxyl, kombinacija ksilitola i glukoze, pomaže da se voda duže zadrži u koži i poboljšava njenu elastičnost. Hijaluronska kiselina dodatno popunjava fine linije i pruža osećaj punoće i mekoće. Pantenol i alantoin štite i umiruju, dok nežna formula bez alkohola i iritansa čini proizvod pogodnim i za osetljivu kožu. Redovnom upotrebom, koža postaje glatka, ujednačena i vidno osvežena. Aktivni sastojci Sok breze Sok breze je bogat aminokiselinama, vitaminima i mineralima koji umiruju kožu, ublažavaju crvenilo i pomažu regeneraciju. Deluje kao prirodan izvor vlage i elastičnosti. Aquaxyl Patentirani kompleks ksilitola i glukoze koji optimizuje zadržavanje vode u koži, jača barijeru i sprečava isušivanje, pružajući dugotrajan osećaj hidriranosti. Hijaluronska kiselina Deluje na više slojeva kože, privlači i zadržava vodu, popunjava sitne bore i ostavlja kožu mekom i elastičnom. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Birch Juice Moisturizing Pad su toneri‑jastučići koji intenzivno hidriraju, umiruju i osvežavaju kožu zahvaljujući soku breze bogatom aminokiselinama i patentiranom sastojku Aquaxyl. Njihova lagana, vodena tekstura brzo se upija i ostavlja prijatan, osvežavajući završetak.', 'https://beauty-health.rs/wp-content/uploads/2025/07/ROUND-LAB-Birch-Juice-Moisturizing-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
