INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (622, 138, 'Pyunkang Yul Calming Line Gift Set', 'pyunkang-yul-calming-line-gift-set', 'Set sadrži: Calming Moisture Toner (150 ml): lagani toner koji hidrira, smiruje i priprema kožu za dalju negu. Calming Moisture Serum (30 ml): serum sa hijaluronskom kiselinom i centelom koji dubinski hidrira i ublažava crvenilo. Calming Moisture Barrier Cream (50 ml): barijerna krema sa ceramidima i shea puterom koja zaključava vlagu i jača zaštitni sloj kože. Ključne prednosti: Smirivanje iritacija: centella asiatica i čajevac ublažavaju crvenilo i zapaljenja. Dubinska hidratacija: hijaluronska kiselina i pantenol vraćaju vlagu i elastičnost. Obnova barijere: ceramidi i shea puter jačaju lipidni sloj i sprečavaju isušivanje. Kome je namenjen? Ovaj set je idealan za masnu, kombinovanu i osetljivu kožu sklonu aknama, kao i za sve kojima je potrebna hidratacija i umirenje. Pogodan je i za osobe koje žele jednostavnu, ali efektivnu rutinu tokom promene godišnjih doba. Zašto volimo Pyunkang Yul Calming Line Gift Set? Set pruža kompletnu negu u tri koraka: toner uklanja površinske nečistoće, obnavlja pH i priprema kožu za naredne korake; serum prodire duboko, donoseći vlagu i umirujući aktivne upale, dok krema zaključava hidrataciju i štiti od spoljašnjih faktora. Kombinacija centelle, kamelije i čajevca deluje kao prirodni štit protiv crvenila i osetljivosti, dok hijaluronski kompleks i pantenol obezbeđuju dugotrajnu mekoću. Ceramidi i squalane dodatno jačaju barijeru i čine kožu glatkom i otpornom. Redovnom upotrebom, koža postaje svežija, ujednačenija i manje sklona iritacijama. Aktivni sastojci Centella asiatica Centella sadrži bioaktivne komponente koje ubrzavaju regeneraciju kože i smanjuju crvenilo. Deluje umirujuće, jača mikrocirkulaciju i ubrzava obnavljanje barijere, što kožu čini manje reaktivnom i osetljivom. Hijaluronska kiselina Kombinacija pet vrsta hijaluronske kiseline prodire u različite slojeve kože, veže vodu i sprečava gubitak vlage. Daje trenutni osećaj punije i glatkije kože. Ceramidi Ceramidi čine važan deo zaštitnog sloja kože, pomažu u zadržavanju vlage i jačanju barijere. U ovoj formuli doprinose dugotrajnoj elastičnosti i otpornosti. Pantenol Provitamin B5 smiruje upale, ublažava osećaj zategnutosti i pomaže koži da brže zaceli. Posebno je koristan kod suve i iritirane kože. Čajevac Ulje čajevca ima antibakterijska svojstva i pomaže kod problematične i masne kože. Smanjuje upale i pomaže u regulaciji sebuma. Ekstrakt japanske kamelije Kamelija je bogata antioksidansima koji štite kožu od spoljašnjih stresora i daju prirodan sjaj. Takođe doprinosi mekoći i elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Calming Line Gift Set je pažljivo osmišljeni set od tri proizvoda – umirujućeg tonika (150 ml), seruma (30 ml) i barijerne kreme (50 ml) – namenjen da smiri nadraženu, dehidriranu i aknama sklonu kožu. Formule su lagane, ali bogate aktivnim sastojcima koji jačaju zaštitnu barijeru i pružaju dugotrajnu hidrataciju bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Calming-Line-Gift-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
