INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (623, 138, 'Pyunkang Yul Black Tea Time Reverse Eye Patch', 'pyunkang-yul-black-tea-time-reverse-eye-patch', 'Ključne prednosti: Dubinska hidratacija: višeslojna hijaluronska kiselina puni kožu vlagom i smanjuje osećaj zategnutosti. Podmlađivanje i elastičnost: fermentisani crni čaj i peptidi stimulišu obnovu i zatežu sitne bore. Ublažavanje tamnih krugova: niacinamid i ekstrakti pirinča i crnog pasulja posvetljuju i umanjuju tragove umora. Kome je namenjen? Ovi jastučići su pogodni za sve tipove kože, a naročito za osobe sa tamnim krugovima, suvoćom i vidljivim znacima umora oko očiju. Preporučuju se svima koji žele dodatnu hidrataciju i umirenje, posebno od 25. godine nadalje. Zašto volimo Pyunkang Yul Black Tea Time Reverse Eye Patch? Ovi hidrogel jastučići pružaju trenutni osećaj svežine i olakšanja, naročito nakon neprospavane noći ili dugog dana pred ekranom. Fermentisani crni čaj deluje kao snažan antioksidant koji štiti i revitalizuje kožu, dok peptidi i adenosin podstiču prirodnu sintezu kolagena, čineći kožu oko očiju čvršćom i glatkom. Hijaluronska kiselina veže vlagu i sprečava isušivanje, dok niacinamid ujednačava ton i smanjuje vidljivost tamnih krugova. Ekstrakti pirinča i crnog pasulja dodatno hrane i umiruju, vraćajući mekoću i blistavost. Gel tekstura jastučića savršeno prijanja, ostajući na mestu bez klizanja, pa su praktični i za jutarnje i večernje rutine. Uz redovnu upotrebu, područje oko očiju postaje odmorno, osveženo i vizuelno mlađe. Aktivni sastojci Fermentisani crni čaj (Kombucha) Kombucha je poznata po visokom sadržaju antioksidanata koji neutralizuju slobodne radikale i štite kožu od prevremenog starenja. Proces fermentacije oslobađa dodatne vitamine i minerale koji pospešuju regeneraciju i osvežavaju umoran izgled kože. Doprinosi elastičnosti i ublažava sitne bore, dok njegova blaga priroda smanjuje iritaciju i oticanje. Pruža dugotrajan osećaj glatkoće i čini kožu oko očiju mekšom i sjajnijom. Idealno je rešenje za kožu koja je izložena stresu i nedostatku sna. Niacinamid Niacinamid (vitamin B3) deluje kao multifunkcionalni saveznik – posvetljuje tamne krugove, ujednačava ten i smanjuje crvenilo. Jača zaštitnu barijeru kože, pomažući joj da duže zadrži vlagu i izgleda zdravije. Takođe smanjuje sitne nepravilnosti i poboljšava elastičnost tankog područja oko očiju. Redovnom upotrebom, efekat posvetljivanja i zaglađivanja postaje vidljiv već nakon nekoliko dana. Hijaluronska kiselina Hijaluronska kiselina veže i do 1000 puta više vode od svoje težine, što je čini izuzetnim humektansom. Pruža trenutno popunjavanje i ublažava izgled sitnih bora uz osećaj mekoće i elastičnosti. Višeslojna formula različitih molekularnih veličina hidrira i površinski i duboko u koži. Peptidi i adenosin Peptidi podstiču proizvodnju kolagena i elastina, vraćajući čvrstoću i elastičnost. Adenosin deluje regenerativno i smanjuje vidljivost sitnih bora, a zajedno pružaju vidljiv anti-age efekat bez iritacije. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Black Tea Time Reverse Eye Patch su nežni hidrogel jastučići koji osvežavaju i regenerišu područje oko očiju, zahvaljujući fermentisanom crnom čaju (kombucha), niacinamidu, hijaluronskoj kiselini i peptidima. Njihov cilj je da ublaže tamne krugove, smanje sitne bore i pruže koži oko očiju odmoran i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Black-Tea-Time-Reverse-Eye-Patch.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
