INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (625, 126, 'Numbuzin No.5+ Glutation Vitamin Concentrate Sheet Mask', 'numbuzin-no-5-vitamin-spotlight-sheet-mask', 'Ključne prednosti: Posvetljuje ten: Niacinamid i vitamin C pomažu u smanjenju tamnih fleka i sivog tona. Revitalizuje kožu: Vitaminska formula daje zdrav i blistav izgled. Dubinska hidratacija: Hidratantni kompleksi omekšavaju kožu i vraćaju joj elastičnost. Kome je namenjena? Namenjena je svim tipovima kože, naročito umornoj, sivkastoj i koži sa neujednačenim tonom ili flekama. Zašto volimo Numbuzin No.5+ Vitamin Spotlight Sheet Mask? Maska deluje kao brzinska vitaminska infuzija za umornu i beživotnu kožu. Vitamin C i niacinamid zajedno rade na posvetljavanju, dok ostali aktivni sastojci pružaju intenzivnu hidrataciju i antioksidativnu zaštitu. Nakon upotrebe koža je mekša, elastičnija i spremna za šminku ili noćnu negu. Redovnim korišćenjem smanjuje vidljivost sitnih nesavršenosti i doprinosi svežijem, mladolikom tenu. Aktivni sastojci Niacinamid Ujednačava ten, posvetljuje tamne fleke i jača kožnu barijeru. Vitamin C (derivat) Deluje antioksidativno, smanjuje sivilo i daje koži prirodan sjaj. Vitamin E Štiti kožu od oksidativnog stresa i podržava regeneraciju. Pantenol Umiruje, hidrira i jača otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.5+ Vitamin Spotlight Sheet Mask je posvetljujuća i revitalizujuća maska obogaćena vitaminskim kompleksom i niacinamidom, kreirana da koži vrati svežinu, blistavost i ujednačen ten. Njen ultra-tanki materijal savršeno prijanja uz lice, omogućavajući duboku apsorpciju hranljivih sastojaka bez lepljivog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Numbuzin-No.5-Vitamin-Spotlight-Sheet-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
