INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (626, 138, 'Pyunkang Yul Oil', 'pyunkang-yul-oil', 'Ključne prednosti: Dubinska hidratacija: regeneriše lipide i obnavlja barijeru kože bez težine. Antioksidativna zaštita: neutrališe slobodne radikale i usporava starenje kože. Umirenje i balansiranje: eterična ulja geranijuma i ruzmarina ublažavaju crvenilo i smiruju iritacije. Kome je namenjen? Ovaj proizvod je posebno efikasan za dehidriranu, zrelu, ali i osetljivu kožu sklonu crvenilu. Pogodan je za osobe koje žele izlged zdravije kože bez teškog sjaja — bilo da je u pitanju jutarnja ili večernja rutina. Zašto volimo Pyunkang Yul Oil? Kada se Pyunkang Yul Oil redovno koristi, ulazi duboko u kožu i obnavlja njen hidrolipidni omotač. Jojoba i shea puter nadoknađuju lipide, dok suncokretovo ulje bogato vitaminom E doprinosi mekanoj i elastičnoj strukturi kože. Formula je dovoljno lagana da se brzo upije, a opet hranljiva da spreči isušivanje, čak i tokom zime. Antioksidanti iz ruzmarina i geranijuma štite od spoljašnjih uticaja i smanjuju pojavu finih linija. Jedinstvena kombinacija čini razliku u rutini: koža postaje ujednačena, osvežena i otpornija na nadražaje. Bez sintetičkih mirisa i konzervansa, prirodni profil ulja čini proizvod idealnim za svakodnevnu primenu u veče ili kao dodatak hidratantnu kremu. Kako se upotrebljava pre ili posle seruma, pomaže drugim proizvodima da deluju efikasnije i smanjuje potrebu za većim količinama kreme. Aktivni sastojci Jojoba ulje (Simmondsia Chinensis Seed Oil) Jojoba ulje ima strukturu voska koja je vrlo slična prirodnom sebumu, pa se koža lako privikava na njega. Deluje kao prirodni emolijens koji umiruje suvu kožu i pomaže u regulaciji sebuma, što čini formulu pogodnom i za masniji tip kože. Bogato je vitaminom E, koji deluje snažno antioksidativno i štiti kožu od oksidativnih oštećenja. Zahvaljujući antibakterijskim svojstvima, tradicionalno se koristi kod tretmana manjih oštećenja i zaceljenja. Suncokretovo ulje (Helianthus Annuus Seed Oil) Suncokretovo ulje je bogat izvor linolne kiseline i vitamina E, koji značajno jačaju strukturu kožnog zida i ubrzavaju regenerativne mehanizme. Deluje umirujuće, naročito nakon izlaganja spoljnim stresorima poput sunca i vetra. Ima antiinflamatorna svojstva koja mogu pomoći kod crvenila i sitnih iritacija. Pridonosi mekoći i glatkoći kože, sprečavajući dehidrataciju. Shea puter (Butyrospermum Parkii Butter) Shea puter stvara zaštitni lipidni film na površini kože koji zadržava vlagu i dugotrajno hidrira. Njegova sposobnost smanjenja upalnih procesa pomaže kod suve i iritirane kože, pružajući osećaj udobnosti i ukupne nege. Sadrži vitamine A i E, kao i fitosterole, koji doprinose obnove kože i održavanju glatke teksture. Zahvaljujući antioksidativnom potencijalu, shea puter takođe štiti od prevremenog starenja i oštećenja od spoljašnjih faktora. ﻿ Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Oil je lagana, biljna uljna formula koja kombinuje jojoba, suncokretovo ulje, shea puter i eterična ulja geranijuma, ruzmarina, lavande i bergamota kako bi pružila intenzivnu hidrataciju i antioksidativnu zaštitu bez osećaja maske ili suvišnog sjaja. Namenjen je za negu dehidrirane, umorne ili iritirane kože.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Oil-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
