INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (627, 138, 'Pyunkang Yul Low pH Mild Body Wash', 'pyunkang-yul-low-ph-mild-body-wash', 'Ključne prednosti: Blaga eksfolijacija: Mineralne soli uklanjaju mrtve ćelije i čine kožu mekšom i čistijom. Umirujući biljni ekstrakti: Ekstrakt korena sladića, cveta zove i kamilice smanjuju iritacije i crvenilo. Održavanje pH ravnoteže: Niska pH vrednost čuva prirodnu barijeru kože i sprečava isušivanje. Kome je namenjen? Namenjen je svim tipovima kože, posebno suvoj i osetljivoj, koja je sklona iritacijama i potrebi za blagim, ali efikasnim čišćenjem. Zašto volimo Pyunkang Yul Low pH Mild Body Wash? Ovaj gel za tuširanje pruža prijatan osećaj svežine dok čisti i neguje kožu bez agresivnog delovanja. Zahvaljujući mineralnim solima, pomaže u uklanjanju sitnih nepravilnosti na površini kože i održava je mekanom. Umirujući biljni ekstrakti smanjuju osetljivost i jačaju prirodnu otpornost kože, što ga čini pogodnim i za svakodnevnu upotrebu kod svih tipova kože. Aktivni sastojci Mineralne soli Nežno uklanjaju mrtve ćelije kože, pročišćavaju pore i čine površinu kože glatkom. Ekstrakt korena sladića (Glycyrrhiza Glabra Root Extract) Deluje umirujuće, smanjuje iritacije i osvetljava siv ton kože. Ekstrakt cveta zove (Lonicera Japonica Flower Extract) Ima protivupalno dejstvo i štiti kožu od spoljašnjih iritacija. Ekstrakt kamilice (Matricaria Flower Extract) Ublažava crvenilo, pruža antioksidativnu zaštitu i smiruje nadraženu kožu. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Low pH Mild Body Wash je blagi gel za tuširanje sa niskom pH vrednošću, obogaćen mineralnim solima koje nežno uklanjaju mrtve ćelije i nečistoće, ostavljajući kožu glatkom i osveženom. Biljni ekstrakti deluju umirujuće i čine ovaj gel idealnim za svakodnevnu negu i osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Low-pH-Mild-Body-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
