INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (628, 138, 'Pyunkang Yul Intensive Ceramide Lotion', 'pyunkang-yul-intensive-ceramide-lotion', 'Ključne prednosti: Višeslojna hidratacija: Pet vrsta hijaluronske kiseline hidrira kožu na površini i u dubljim slojevima. Biljna ulja za elastičnost: Maslinovo ulje i shea buter hrane i omekšavaju kožu. Zaštita barijere: Ceramidi zaključavaju vlagu i jačaju otpornost kože na spoljne faktore. Kome je namenjen? Namenjen je suvoj, osetljivoj, ispucaloj i dehidriranoj koži, kao i osobama koje žele dubinsku, a laganu negu bez masnog sloja. Zašto volimo Pyunkang Yul Intensive Ceramide Lotion? Ovaj losion pruža lagani, nelepljivi završetak, ali sa intenzivnom moći regeneracije i ishrane. Koža postaje elastičnija, glatka i zaštićena od spoljašnjih faktora poput hladnoće i suvoće. Zahvaljujući minimalnoj listi sastojaka i fokusiranim aktivnim komponentama, idealan je za svakodnevnu upotrebu, pa čak i kod kože sklone atopiji ili ekcemu. Redovnom upotrebom jača otpornost kože i sprečava iritacije. Aktivni sastojci Pet vrsta hijaluronske kiseline Rade sinergijski da hidrira različite slojeve kože, pružajući dugotrajnu i intenzivnu vlažnost. Maslinovo ulje Bogat izvor antioksidanata i esencijalnih masnih kiselina koje hrane i omekšavaju kožu. Shea buter Dubinski hrani, obnavlja i stvara zaštitni sloj koji sprečava gubitak vlage. Ceramidi Obnavljaju lipidnu barijeru kože, jačaju zaštitu i smanjuju transepidermalni gubitak vode. Vitamin E Daje antioksidativnu zaštitu, štiti od slobodnih radikala i pospešuje regeneraciju kože. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Intensive Ceramide Lotion je bogati, ali lagani losion bez mirisa, formulisan za intenzivnu hidrataciju i jačanje kožne barijere. Sadrži kombinaciju pet vrsta hijaluronske kiseline, biljna ulja i ceramide, pružajući dugotrajnu vlažnost i mekoću koži nakon svakog nanošenja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Intensive-Ceramide-Lotion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
