INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (629, 138, 'Pyunkang Yul Deep Nourishing Multi Balm', 'pyunkang-yul-deep-nourishing-multi-balm', 'Ključne prednosti: Dubinska ishrana: Biljna ulja i shea buter obnavljaju suvu i hrapavu kožu. Višenamenska zaštita: Formira zaštitni film koji čuva vlagu i sprečava isušivanje. Pogodan za osetljive zone: Bez iritacija, idealan za usne, ruke, zanoktice i suve delove tela. Kome je namenjen? Namenjen je osobama sa suvom, ispucalom i osetljivom kožom, kao i onima koji traže praktičan proizvod za ciljanu negu i zaštitu tokom dana. Zašto volimo Pyunkang Yul Deep Nourishing Multi Balm? Balzam pruža osećaj trenutnog olakšanja suvoj i zategnutoj koži, dok je redovnom upotrebom čini mekšom i elastičnijom. Njegova kompaktna, čvrsta tekstura topi se na dodir, stvarajući lagani sloj koji štiti od vetra, hladnoće i drugih agresivnih spoljašnjih faktora. Zahvaljujući minimalističkoj formuli, balzam je pogodan i za osetljivu kožu, pa ga mogu koristiti svi članovi porodice. Aktivni sastojci Shea buter Dubinski hrani i omekšava kožu, vraćajući joj elastičnost i glatkoću. Pčelinji vosak Stvara zaštitni film koji sprečava gubitak vlage i štiti kožu od spoljašnjih uticaja. Suncokretovo i makadamijino ulje Bogat izvor esencijalnih masnih kiselina i vitamina koji obnavljaju suve delove kože. Skvalan Lagano ulje koje hidrira, poboljšava mekoću i ne ostavlja masni trag. Vitamin E Snažan antioksidans koji štiti kožu i pomaže u regeneraciji. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Deep Nourishing Multi Balm je višenamenski balzam za intenzivnu negu suve i ispucale kože, obogaćen biljnim uljima, pčelinjim voskom i shea buterom. Kreiran je za suve regije poput usana, zanoktica, laktova i kolena, a istovremeno štiti kožu od spoljašnjih uticaja i zadržava vlagu tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Pyunkang-Yul-Deep-Nourishing-Multi-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
