INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (630, 135, 'Purcell Pixcell Biom Glow Barrier Serum', 'purcell-pixcell-biom-glow-barrier-serum', 'Ključne prednosti: Jača barijeru kože: Ceramidi i lipidi obnavljaju zaštitni sloj i štite od gubitka vlage. Obnavlja prirodan sjaj: Biom kompleksi i antioksidanti vraćaju zdrav i blistav izgled. Umiruje i hidrira: Pantenol i biljni ekstrakti smanjuju crvenilo i pružaju dugotrajnu vlažnost. Kome je namenjen? Namenjen je suvoj, osetljivoj i dehidriranoj koži, kao i koži kojoj je narušena barijera ili nedostaje prirodan sjaj. Zašto volimo PURCELL Pixcell Biom Glow Barrier Serum? Serum funkcioniše kao „štit i hrana“ za kožu – jača njenu strukturu, smanjuje osećaj zategnutosti i vraća vitalnost. Zahvaljujući kombinaciji ceramida, peptida i probiotskih kompleksa, pomaže koži da se brže oporavi od iritacija i spoljašnjih oštećenja. Tekstura je svilenkasta i brzo se upija, ostavljajući kožu mekom, hidriranom i vidljivo blistavijom. Redovnom upotrebom ten postaje ujednačen, sa znatno smanjenom reaktivnošću na spoljne faktore. Aktivni sastojci Biom kompleks (probiotici i prebiotici) Obnavlja mikrobiom kože, jača otpornost i smanjuje reaktivnost. Ceramidi Obnavljaju lipidni sloj kože i sprečavaju gubitak vlage. Pantenol Umiruje i hidrira kožu, smanjujući osećaj iritacije. Peptidi Poboljšavaju elastičnost kože i pomažu u regeneraciji ćelija. Ekstrakti biljaka (zeleni čaj, kamilica) Deluju antioksidativno, štite od slobodnih radikala i smiruju kožu. Dodaj u listu želja Dodaj u listu želja', 'PURCELL Pixcell Biom Glow Barrier Serum je serum za jačanje barijere kože i obnavljanje prirodnog sjaja, kreiran sa inovativnim biom kompleksima, ceramidima i probioticima. Formulacija intenzivno hidrira, smanjuje osetljivost i čini kožu elastičnijom i otpornijom na spoljne stresore.', 'https://beauty-health.rs/wp-content/uploads/2025/07/PURCELL-Pixcell-Biom-Glow-Barrier-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
