INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (631, 118, 'Missha Mascure Calming Sheet Mask Guaiazulene', 'missha-mascure-calming-sheet-mask', 'Ključne prednosti: Brzo umirenje: Guaiazulene smanjuje crvenilo, ublažava osećaj peckanja i iritacije. Obnova kožne barijere: Pantenol i alantoin pomažu u regeneraciji kože i vraćaju mekoću. Lagano prijanjanje: Tanki materijal maske omogućava optimalnu apsorpciju esencije bez opterećenja za kožu. Kome je namenjena? Namenjena je osetljivoj, nadraženoj i crvenoj koži, kao i koži sklonoj upalama i površinskim iritacijama. Zašto volimo Missha Mascure Calming Sheet Mask? Maska deluje kao trenutni SOS tretman za kožu izloženu stresu, vremenskim promenama ili agresivnim kozmetičkim preparatima. Zahvaljujući guaiazulene-u, prirodnom pigmentu plave boje iz ulja kamilice, koža je vidno smirenija i manje crvena nakon samo jedne upotrebe. Tekstura esencije je lagana, ali dovoljno hidratantna da ostavi kožu mekom i zaštićenom. Pogodna je i kao tretman posle izlaganja suncu ili nakon pilinga, kada je koži potrebna dodatna nežnost i obnova. Aktivni sastojci Guaiazulene Prirodni derivat iz etarskog ulja kamilice, poznat po svom snažnom protivupalnom i umirujućem dejstvu. Smanjuje crvenilo i ubrzava regeneraciju kože. Pantenol (Provitamin B5) Hidrira i smiruje kožu, jačajući njenu otpornost i pomažući zarastanje mikropovreda. Alantoin Pruža zaštitu osetljivoj koži, smanjuje iritacije i daje osećaj glatkoće i mekoće. Dodaj u listu želja Dodaj u listu želja', 'Missha Mascure Calming Sheet Mask Guaiazulene je umirujuća maska od ultra tanke celuloze natopljena esencijom sa guaiazulene-om, poznatim po svom snažnom protivupalnom dejstvu. Namenjena je smirivanju crvenila, iritacija i vraćanju balansa reaktivnoj i osetljivoj koži.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Mascure-Calming-Sheet-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
