INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (632, 118, 'Missha Airy Fit Sheet Mask Honey', 'missha-airy-fit-sheet-mask-honey', 'Ključne prednosti: Dubinska ishrana: Med i biljni ekstrakti hrane kožu i vraćaju joj mekoću. Obnavljanje barijere: Prirodni šećeri i minerali iz meda jačaju zaštitni sloj kože. Osvežen i zdrav sjaj: Koža dobija elastičnost i zdravu punoću već nakon jedne upotrebe. Kome je namenjena? Namenjena je svim tipovima kože, posebno osetljivoj, umornoj ili koži sklonoj crvenilu i iritacijama. Pogodna za svakodnevnu upotrebu. Zašto volimo Missha Airy Fit Sheet Mask Honey ? Maska pruža osećaj poput hranljive komprese – posle skidanja, koža izgleda odmorno i meko kao posle dubinske njege. Esencija meda deluje umirujuće, posebno kod suve i perutave kože. Redovnom upotrebom, ten postaje ujednačeniji, dok sitne linije uzrokovane suvoćom postaju manje vidljive. Maska ne ostavlja lepljiv trag i pogodna je i za upotrebu pre šminkanja. Aktivni sastojci Med (Honey Extract) Prirodni humektant koji zadržava vlagu u koži, hrani je vitaminima i mineralima, i čini je mekšom i otpornijom. Beta-glukan Intenzivno hidrira, smiruje iritacije i jača zaštitnu barijeru kože. Alantoin Ublažava crvenilo i iritacije, pomaže koži da postane glatkija i elastičnija. Dodaj u listu želja Dodaj u listu želja', 'Missha Airy Fit Sheet Mask Honey je ultra tanka maska od prirodne celuloze, natopljena hranljivom esencijom sa medom koji intenzivno hrani i omekšava kožu. Njena lagana tekstura omogućava koži da upije maksimalnu količinu aktivnih sastojaka, ostavljajući je glatkom, elastičnom i blistavom.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Airy-Fit-Sheet-Mask-Honey.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
