INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (633, 124, 'Nine Less A-Control Mini Kit', 'nine-less-a-control-mini-kit', 'Set sadrži: Heartleaf & BHA Cleanser (30 ml): Blagi gel čistač sa ekstraktom heartleafa i BHA za temeljno čišćenje pora. Azelaic Acid Toner (30 ml): Toner sa azelaičnom kiselinom za blagu eksfolijaciju i osvetljavanje kože. 10% Azelaic Acid Serum (10 ml): Serum koji ujednačava ton kože i smanjuje nesavršenosti. Azelaic Acid Cream (10 ml): Hidratantna krema sa umirujućim i regenerativnim efektom. Ključne prednosti: Blaga eksfolijacija: Azelaična kiselina i BHA pročišćavaju pore i pomažu u smanjenju nepravilnosti. Umirujuća nega: Heartleaf i zeleni čaj smiruju crvenilo i iritacije. Praktičan format: Četiri ključna proizvoda u mini pakovanjima savršena su za putovanja i test rutinu. Kome je namenjen? Namenjen je osetljivoj, masnoj i kombinovanoj koži, posebno onima koji se bore sa začepljenim porama, sitnim nepravilnostima i crvenilom. Zašto volimo Missha Mascure Rescue Solution Sheet Mask Madecassoside? Ovaj set pruža kompletnu rutinu u četiri koraka – od dubinskog čišćenja pora, preko blage eksfolijacije, do hidratacije i ujednačavanja tena. Azelaična kiselina pomaže u smanjenju tamnih fleka i nesavršenosti, dok biljni ekstrakti smiruju kožu i vraćaju joj svežinu. Idealno je rešenje za masnu, problematičnu i reaktivnu kožu koja traži balansiranu rutinu bez agresivnih sastojaka. Aktivni sastojci Azelaična kiselina Pomaže u smanjenju nepravilnosti, ujednačava ten i ima antibakterijsko dejstvo. Deluje protiv hiperpigmentacija i nežno čisti pore. Heartleaf ekstrakt Prirodni antiinflamatorni sastojak koji smanjuje crvenilo i iritacije, idealan za osjetljivu kožu. Ekstrakt zelenog čaja Snažan antioksidans koji štiti kožu od oksidativnog stresa i istovremeno je umiruje. BHA (salicilna kiselina) Prodire u pore, rastvara višak sebuma i sprečava pojavu mitisera i bubuljica. Dodaj u listu želja Dodaj u listu želja', 'NINELESS A-Control Mini Kit je praktičan set od 4 proizvoda u mini pakovanjima iz A-Control linije, namenjen smirivanju osetljive i aknama sklone kože, uz istovremeno pročišćavanje pora i ujednačavanje tena. Set je idealan za putovanja ili testiranje cele rutine u manjoj veličini.', 'https://beauty-health.rs/wp-content/uploads/2025/07/NINE-LESS-A-Control-Mini-Kit.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
