INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (634, 118, 'Missha Mascure Rescue Solution Sheet Mask Madecassoside', 'missha-mascure-rescue-solution-sheet-mask-madecassoside', 'Ključne prednosti: Umirenje i regeneracija: Madecassoside ublažava crvenilo i pospešuje obnavljanje kože. Zaštita i jačanje barijere: Centella Asiatica jača otpornost kože i smanjuje reaktivnost. Lagano prijanjanje: Ultra tanka celulozna maska ravnomerno oslobađa umirujuću esenciju bez opterećenja. Kome je namenjena? Namenjena je osetljivoj, crvenoj i reaktivnoj koži, kao i koži kojoj je potrebna dodatna regeneracija posle pilinga, sunčanja ili izlaganja hladnoći. Zašto volimo Missha Mascure Rescue Solution Sheet Mask Madecassoside? Ova maska deluje kao trenutno olakšanje za kožu izloženu stresu, vremenskim uslovima ili agresivnim tretmanima. Nakon korišćenja, koža je smirena, hidrirana i vidljivo manje crvena. Formulacija je nežna i pogodna i za najosetljiviju kožu, jer pruža hidrataciju i zaštitu bez izazivanja iritacija. Redovnom primenom pomaže koži da postane stabilnija i otpornija na spoljne faktore. Aktivni sastojci Madecassoside Snažan umirujući i regenerativni sastojak iz Centelle koji smanjuje iritacije, pomaže u obnovi kože i jača njenu otpornost. Centella Asiatica ekstrakt Deluje protivupalno i ubrzava regeneraciju oštećene kože, dok pruža antioksidativnu zaštitu. Pantenol Poznat po hidratantnim i umirujućim svojstvima, pomaže u smanjenju osećaja zatezanja i peckanja. Beta-glukan Pruža intenzivnu hidrataciju i jača barijeru kože, smanjujući suvoću i reaktivnost. Dodaj u listu želja Dodaj u listu želja', 'Missha Mascure Rescue Solution Sheet Mask Madecassoside je umirujuća sheet maska koja sadrži visokokoncentrisani madecassoside i ekstrakt Centelle Asiatice. Kreirana je da trenutno smiri nadraženu, crvenu i oslabljenu kožu, vraćajući joj osećaj udobnosti i balans.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Mascure-Rescue-Solution-Sheet-Mask-Madecassoside.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
