INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (636, 118, 'Missha Mascure Hyaluronic Acid Sheet Mask', 'missha-mascure-hyaluronic-acid-sheet-mask', 'Ključne prednosti: Dubinska hidratacija: Hijaluronska kiselina u više molekularnih težina hidrira površinske i dublje slojeve kože. Brzo osveženje: Pruža koži osećaj punoće i mekoće već nakon jedne upotrebe. Jačanje barijere: Pantenol i alantoin štite kožu i smanjuju osećaj suvoće. Kome je namenjena? Namenjena je svim tipovima kože, naročito suvoj, dehidriranoj i osetljivoj koži kojoj nedostaje vlažnost i sjaj. Zašto volimo Missha Mascure Hyaluronic Acid Sheet Mask? Maska deluje poput hidratantne infuzije koja vraća energiju i svežinu umornoj, dehidriranoj koži. Posebno je pogodna za negu u zimskom periodu, nakon putovanja ili boravka u klimatizovanim prostorijama kada koža gubi vlagu. Redovnom upotrebom pomaže u smanjenju finih linija izazvanih dehidratacijom i vraća koži elastičnost. Ne ostavlja masan film, već prijatan, negovan osećaj. Aktivni sastojci Hijaluronska kiselina Pruža snažnu hidrataciju jer vezuje vodu u epidermu, čineći kožu glatkom i punijom. Pantenol (Provitamin B5) Umiruje i obnavlja kožnu barijeru, smanjujući osećaj iritacije i suvoće. Alantoin Deluje umirujuće i poboljšava mekoću i elastičnost kože. Dodaj u listu želja Dodaj u listu želja', 'Missha Mascure Hyaluronic Acid Sheet Mask je ultra-hidratantna maska sa hijaluronskom kiselinom koja trenutno vraća vlagu i osvežava kožu. Lagana celulozna maramica omogućava ravnomerno upijanje esencije, ostavljajući kožu punijom, mekšom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Mascure-Hyaluronic-Acid-Sheet-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
