INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (637, 118, 'Missha Mascure Whitening Glutathione Sheet Mask', 'missha-mascure-whitening-glutathione-sheet-mask', 'Ključne prednosti: Posvetljuje i ujednačava: Glutation i niacinamid deluju sinergijski na smanjenje tamnih mrlja i sivkastog tona. Revitalizuje kožu: Vitamin kompleksi i biljni ekstrakti vraćaju osvetljenost i elastičnost. Hidrira bez opterećenja: Lagana esencija obnavlja vlažnost i daje koži zdrav sjaj. Kome je namenjena? Namenjena je svim tipovima kože, posebno umornoj i neujednačenoj, kao i koži sa vidljivim flekama ili sivkastim tonom. Zašto volimo Missha Mascure Whitening Glutathione Sheet Mask? Maska radi poput intenzivne kućne terapije za kožu koja je izgubila sjaj i ujednačenost. Nakon samo jedne upotrebe, koža je osvežena, blistava i meka na dodir. Redovnim korišćenjem doprinosi ublažavanju fleka nastalih od sunca ili postupalnih promena, dok ten postaje ravnomerniji. Njena formula ne izaziva osećaj zatezanja niti ostavlja mastan film, već daje lagan i hidriran osećaj. Aktivni sastojci Glutation Snažan antioksidans koji pomaže u posvetljavanju i ujednačavanju tena. Deluje na slobodne radikale i doprinosi zaštiti ćelija od oksidativnog stresa. Niacinamid Poboljšava elastičnost kože, ujednačava ten i smanjuje vidljivost fleka i nepravilnosti. Vitamin kompleksi (C i E) Deluju antioksidativno i revitalizuju kožu, pružajući zdrav i svež izgled. Ekstrakt kamilice i centelle Umiruju i obnavljaju kožu, sprečavajući iritacije i crvenilo. Dodaj u listu želja Dodaj u listu želja', 'Missha Mascure Whitening Glutathione Sheet Mask je posvetljujuća maska za lice obogaćena glutationom i niacinamidom, koja pomaže u ublažavanju tamnih fleka i neujednačenog tena. Njena lagana celulozna struktura omogućava koži da maksimalno upije hranljive sastojke i dobije osvežen, ujednačen sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Mascure-Whitening-Glutathione-Sheet-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
