INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (638, 118, 'Missha Airy Fit Sheet Mask Green Tea', 'missha-airy-fit-sheet-mask-green-tea', 'Ključne prednosti: Umiruje i osvežava: Ekstrakt zelenog čaja trenutno smanjuje osećaj zategnutosti, crvenilo i umor kože. Hidrira bez masnog sjaja: Laka esencijalna formula obnavlja vlagu, a ne ostavlja lepljiv trag. Poboljšava otpornost kože: Antioksidansi iz zelenog čaja štite ćelije od oksidativnog stresa i održavaju kožu svežom i elastičnom. Kome je namenjena? Namenjena je svim tipovima kože, posebno osetljivoj, umornoj ili koži sklonoj crvenilu i iritacijama. Pogodna za svakodnevnu upotrebu. Zašto volimo Missha Airy Fit Sheet Mask Green Tea? Ova maska donosi iskustvo nežne i osvežavajuće nege koja traje i nakon skidanja. Koža deluje odmornije, meka je na dodir i ima prirodni sjaj, čak i posle dugog dana ili naporne nedelje. Njena tanana tekstura i brzo delovanje čine je savršenim izborom za jutarnju ili večernju rutinu kad želite brz efekat &#8220;restarta&#8221; za umornu kožu. Ne opterećuje ten i odlična je i kao SOS maska pred važan događaj. Aktivni sastojci Ekstrakt zelenog čaja Prirodni antioksidans bogat polifenolima koji štiti kožu od slobodnih radikala, smanjuje crvenilo i deluje umirujuće. Takođe pomaže u regulaciji sebuma i osvežava umoran ten. Beta-glukan Podstiče regeneraciju kože, poboljšava elastičnost i pruža dubinsku hidrataciju, čineći je otpornijom na spoljne stresore. Alantoin Smiruje iritacije, omekšava površinu kože i podstiče zarastanje sitnih oštećenja. Dodaj u listu želja Dodaj u listu želja', 'Missha Airy Fit Sheet Mask Green Tea je lagana, tanko sečena maska natopljena esencijom od zelenog čaja koja pruža umirujuću i antioksidativnu negu koži izložene stresu i spoljnim uticajima. Zahvaljujući prozračnom materijalu od prirodne celuloze, savršeno prijanja i omogućava duboku apsorpciju aktivnih sastojaka bez opterećenja za kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Missha-Airy-Fit-Sheet-Mask-Green-Tea.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
