INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (642, 86, 'JMsolution Marine Luminous Pearl Sun Spray Pearl', 'jmsolution-marine-luminous-pearl-sun-spray-pearl', 'Ključne prednosti: Zaštita od sunca: Visok SPF štiti od UVA i UVB zraka bez osećaja težine na koži. Biserna svetlost: Fini biserni prah pruža zdrav sjaj i osvežava umoran ten. Hidratacija u pokretu: Morski kolagen i hijaluronska kiselina osvežavaju i hidriraju kožu tokom dana. Kome je namenjen? Namenjen je svim tipovima kože, uključujući masnu i osetljivu, naročito onima koji traže praktično i osvežavajuće rešenje za zaštitu tokom dana. Zašto volimo JMsolution Marine Luminous Pearl Sun Spray Pearl? Ovaj SPF sprej je kao morska izmaglica za tvoje lice – ultra lagan, ne ostavlja lepljiv trag i pruža blistav, negovan izgled. Idealno rešenje za sve koji žele brzo i praktično obnavljanje zaštite, bilo da si na plaži ili usred gradske gužve. Njegova formula sa ekstraktima morskih algi i bisera pomaže da koža izgleda odmorno i hidrirano, dok osvežavajući efekat hlađenja čini da je upotreba ovog spreja pravi mali ritual uživanja. Aktivni sastojci Biserni prah Reflektuje svetlost i daje koži zdrav, prirodan sjaj bez šljokica. Hijaluronska kiselina Održava hidrataciju i sprečava isušivanje tokom izlaganja suncu. Morski kolagen Poboljšava elastičnost i čini kožu glatkom i blistavom. Ekstrakt morskih algi i morske vode Umiruju, revitalizuju i osvežavaju kožu uz dodatni antioksidativni efekat. Dodaj u listu želja Dodaj u listu želja', 'JMsolution Marine Luminous Pearl Sun Spray Pearl je lagani, osvežavajući SPF u spreju koji pruža visoku zaštitu od UV zračenja (SPF50+ PA++++), dok u isto vreme daje suptilan sjaj koži zahvaljujući bisernom prahu. Savršen je za osveženje tokom dana, čak i preko šminke.', 'https://beauty-health.rs/wp-content/uploads/2025/07/JMsolution-Marine-Luminous-Pearl-Sun-Spray-Pearl.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
