INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (644, 84, 'Isntree C-Niacin Toning Cream', 'isntree-c-niacin-toning-cream', 'Ključne prednosti: Vidljivo posvetljuje: Niacinamid smanjuje pojavu tamnih fleka i umanjuje sivilo tena. Povećava elastičnost: Adenozin i biljni ekstrakti čine kožu čvršćom i glađom. Lagane teksture: Krema se brzo upija i ne ostavlja mastan trag, pogodna i kao podloga za šminku. Kome je namenjena? Namenjena je koži sa neujednačenim tonom, hiperpigmentacijama, sivim i umornim tenom. Prikladna za normalnu, mešovitu i suvu kožu, kao i osetljivu. Zašto volimo Isntree C-Niacin Toning Cream? Ova krema je kao osvežavajući poslednji korak u rutini – daje koži &#8220;dewy&#8221; završnicu bez sjaja koji izgleda kao masnoća. Njena kombinacija niacinamida i prirodnog izvora vitamina C iz morske pasje ruže pomaže u osvetljavanju pigmentacija, dok hidratantni sastojci omekšavaju i umiruju kožu. Idealna je za one koji žele nežan, svakodnevni efekat posvetljavanja bez iritacije. Ujedno, krema jača kožnu barijeru i može se koristiti tokom cele godine, čak i kod osetljivije kože. Aktivni sastojci Ekstrakt morske pasje ruže (Rosa Canina Fruit Extract) Prirodni izvor vitamina C, deluje antioksidativno i posvetljuje kožu. Niacinamid (5%) Deluje na hiperpigmentacije, poboljšava teksturu kože i osvetljava ten. Adenozin Ublažava fine linije i poboljšava elastičnost kože. Skvalan i pantenol Hidriraju i obnavljaju zaštitni sloj kože bez opterećenja. Dodaj u listu želja Dodaj u listu želja', 'Isntree C-Niacin Toning Cream je osvetljujuća krema obogaćena niacinamidom i ekstraktom morske pasje ruže, osmišljena da ujednači ten, posvetli kožu i pruži blistav, hidriran izgled bez osećaja težine. Namenjena je svima koji žele da postignu zdrav i ujednačen sjaj kože na prirodan način.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Isntree-C-Niacin-Toning-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
