INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (645, 84, 'Isntree C-Niacin Toning Ampoule', 'isntree-c-niacin-toning-ampoule', 'Ključne prednosti: Ujednačava ten: Niacinamid pomaže u smanjenju tamnih fleka, hiperpigmentacija i sivog tona kože. Posvetljuje i revitalizuje: Ekstrakt morske pasje ruže bogat vitaminom C osvežava kožu i poboljšava njen prirodni sjaj. Lagano i brzo upijajuće: Tekstura je lagana i nelepljiva, idealna za slojevito nanošenje i sve tipove kože. Kome je namenjena? Namenjena je koži sa neujednačenim tenom, hiperpigmentacijama, sivkastim tonom ili umornim izgledom. Prikladna je i za osetljivu kožu koja traži blage posvetljujuće formulacije. Zašto volimo Isntree C-Niacin Toning Ampoule? Ova ampula je kao vitaminski šut za kožu – odmah osvežava ten i daje zdraviji izgled već nakon nekoliko dana korišćenja. Zahvaljujući kombinaciji prirodnog vitamina C iz morske pasje ruže i stabilnog oblika niacinamida, podstiče sintezu kolagena, umanjuje fleke i preventivno deluje na pojavu novih diskoloracija. Koža postaje vidno blistavija, ujednačena i elastična. Pogodna je i za kožu sa znakovima stresa, iscrpljenosti ili izloženosti zagađenju. Redovnom upotrebom vraća koži osvetljenost i zdrav ton bez agresivnih kiselina. Aktivni sastojci Ekstrakt morske pasje ruže (Rosa Canina Fruit Extract, 69%) Prirodni izvor vitamina C koji posvetljuje ten, deluje antioksidativno i osvežava kožu. Niacinamid (2%) Proveren i stabilan sastojak za ujednačavanje tena, smanjenje tamnih fleka i jačanje kožne barijere. Adenozin Smanjuje pojavu finih linija i ima anti-age efekat, čineći kožu glatkom i zategnutom. Pantenol i beta-glukan Umiruju i hidriraju kožu, čineći ovu ampulu pogodnom i za osetljivije tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Isntree C-Niacin Toning Ampoule je koncentrisani serum sa 69% ekstrakta morske pasje ruže i 2% niacinamida, formulisan da posvetli ten, ujednači boju kože i vrati zdrav sjaj umornoj i beživotnoj koži. Bezbedan je čak i za osetljivu kožu zahvaljujući nežnoj, ali efikasnoj formuli bez iritansa.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Isntree-C-Niacin-Toning-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
