INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (646, 84, 'Isntree Aloe Soothing Toner', 'isntree-aloe-soothing-toner', 'Ključne prednosti: Intenzivno umirenje: Aloe vera deluje protiv crvenila, iritacija i osećaja zatezanja odmah nakon čišćenja. Obnova vlažnosti: Tonik brzo vraća vlagu i štiti kožu od isušivanja zahvaljujući beta-glukanu i hijaluronskoj kiselini. Lagana, nelepljiva tekstura: Toner se brzo upija i ostavlja osećaj svežine bez masnog filma. Kome je namenjen? Namenjen je svim tipovima kože, uključujući veoma osetljivu, crvenu, dehidriranu ili nadraženu kožu kojoj je potrebno trenutno umirenje i lagana hidratacija. Zašto volimo Isntree Aloe Soothing Toner? Ovaj tonik se ponaša kao nežan reset za kožu – posebno nakon agresivnog čišćenja, izlaganja suncu, vetru ili suvom vazduhu. Aloe vera smanjuje crvenilo i pruža osećaj prijatne svežine. Hijaluronska kiselina i pantenol obnavljaju vlagu i čine da koža deluje mekše i smirenije. Njegova tekstura je osvežavajuće vodenasta, bez lepljivosti, što ga čini idealnim i za slojevito nanošenje (tzv. 7-skin metoda). Redovnom upotrebom koža postaje manje reaktivna, otpornija i hidrirana tokom celog dana. Aktivni sastojci Aloe Vera (Aloe Barbadensis Leaf Extract, 80%) Moćan prirodni sastojak poznat po umirujućem i regenerativnom dejstvu. Smanjuje iritacije, crvenilo i opekotine, dok ujedno hidrira i osvežava. Beta-glukan Pruža koži dubinsku hidrataciju i štiti je od štetnih faktora iz spoljašnje sredine. Jača barijernu funkciju kože i umanjuje upalne procese. Pantenol (Provitamin B5) Pomaže u obnavljanju oštećene kože, pospešuje zarastanje i smanjuje iritacije. Deluje kao snažan humektant. Hijaluronska kiselina Privlači i zadržava vlagu u koži, čineći je elastičnom i svežom. Doprinosi boljoj apsorpciji narednih proizvoda. Dodaj u listu želja Dodaj u listu želja', 'Isntree Aloe Soothing Toner je nežan, ali izuzetno efikasan tonik sa 80% aloe vera ekstrakta koji trenutno umiruje, hidrira i pomaže koži da povrati balans nakon čišćenja. Savršen je kao prvi korak posle umivanja za umirivanje iritacija i pripremu kože za dalje korake nege.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Isntree-Aloe-Soothing-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
