INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (647, 84, 'Isntree Plum Peptide Plumping Gel Mask', 'isntree-plum-peptide-plumping-gel-mask', 'Ključne prednosti: Efekat popunjenosti: Peptidi i hijaluronska kiselina vraćaju koži volumen i elastičnost. Dubinska hidratacija: Kompleks šljive i vlažećih sastojaka intenzivno hidrira i umiruje kožu. Gel tekstura bez lepljenja: Rashlađujuća, neiritirajuća formula savršeno prijanja bez osećaja težine. Kome je namenjena? Namenjena je svim tipovima kože, uključujući i osetljivu, posebno osobama sa dehidriranom, umornom, beživotnom i opuštenom kožom kojoj je potrebna elastičnost i osvežen izgled. Zašto volimo Isntree Plum Peptide Plumping Gel Mask? Maska se ponaša kao brzinska infuzija za umornu i dehidriranu kožu. Ekstrakt šljive bogat antioksidansima poboljšava tonus i pomaže u borbi protiv prvih znakova starenja, dok peptidi stimulišu prirodne procese obnove i učvršćuju kožu. Hijaluronska kiselina u više molekularnih veličina hidrira površinski i dublje slojeve kože, vraćajući joj glatkoću i gipkost. Nakon upotrebe, koža izgleda odmorno, blistavo i blago zategnuto – bez osećaja zatezanja. Maska je idealna pre šminkanja, nakon putovanja ili kad god koži treba osveženje. Aktivni sastojci Ekstrakt japanske šljive (Prunus Mume Fruit Extract) Prirodni antioksidans koji osvežava, ujednačava ten i ima blag anti-age efekat. Poboljšava elastičnost i pruža koži zdrav sjaj. Peptidni kompleks Sadrži više različitih peptida koji stimulišu proizvodnju kolagena i učvršćuju kožu. Deluju protiv opuštenosti i gubitka tonusa. Hijaluronska kiselina (u više molekula) Zadržava vlagu u koži, hidrira u dubinu i omekšava fine linije izazvane dehidratacijom. Beta-glukan i alantoin Umiruju i obnavljaju kožu, sprečavaju iritacije i pojačavaju barijernu funkciju. Dodaj u listu želja Dodaj u listu želja', 'Isntree Plum Peptide Plumping Gel Mask je bogata gel maska koja hidrira, zateže i revitalizuje kožu zahvaljujući moćnoj kombinaciji japanske šljive, peptida i hijaluronske kiseline. Maska pruža trenutni efekat osveženja i dugoročno poboljšava elastičnost i punoću kože.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Isntree-Plum-Peptide-Plumping-Gel-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
