INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (649, 73, 'Heveblue Salmon Caring Centella Bubble Cleanser', 'heveblue-salmon-caring-centella-bubble-cleanser', 'Ključne prednosti: Umirujuće čišćenje: Centella Asiatica smanjuje crvenilo i ublažava iritacije već tokom čišćenja. Obnova i regeneracija: DNK iz lososa podstiče regeneraciju kože i jača njenu otpornost. Balansirana pH pena: Blaga, kremasta pena sa fiziološkim pH vrednostima održava ravnotežu i čini kožu hidriranom i nežnom na dodir. Kome je namenjen? Preporučuje se osobama sa osetljivom, iritiranom, dehidriranom ili tretiranoj koži (npr. nakon kiseline, retinola, lasera), kao i svima koji žele blag, ali efikasan čistač. Zašto volimo HEVEBLUE Salmon Caring Centella Bubble Cleanser? Za razliku od uobičajenih čistača koji isušuju, ovaj proizvod istovremeno čisti i neguje. Centella umiruje površinske upale, dok lososov ekstrakt doprinosi obnovi kolagena i smanjenju mikrooštećenja na koži. Tekstura pene je meka i bogata, lako se raspoređuje i ne ostavlja zatezanje. Redovnom upotrebom, koža postaje glađa, ujednačenija i otpornija na spoljašnje uticaje. Idealno je rešenje za jutarnje i večernje čišćenje, naročito za osobe koje koriste aktivne sastojke u rutini i žele blagu, ali efikasnu osnovu. Posebno prija koži koja je sklona crvenilu, suvoći ili površinskim oštećenjima. Aktivni sastojci Centella Asiatica (ekstrakt, madecassoside) Poznata po svojim umirujućim i antiinflamatornim svojstvima. Deluje protiv crvenila, iritacija i mikroupala, ubrzava zarastanje sitnih oštećenja i ojačava zaštitnu barijeru kože. Nežna i efikasna za sve tipove kože, čak i najreaktivnije. Lososov DNK (PDRN) Polideoksiribonukleotid iz lososa stimuliše regeneraciju tkiva, podstiče proizvodnju kolagena i poboljšava elastičnost kože. Ima duboko regenerativno dejstvo i koristi se i u dermatološkim tretmanima zbog svoje sposobnosti da obnavlja oštećenu kožu. Glicerin i betain Humektansi koji vlaže kožu i sprečavaju isušivanje tokom čišćenja. Zadržavaju vodu u epidermu i ostavljaju kožu mekom, bez osećaja zategnutosti. Dodaj u listu želja Dodaj u listu želja', 'HEVEBLUE Salmon Caring Centella Bubble Cleanser je penušavi čistač lica koji kombinuje regenerativna svojstva lososove DNK i umirujuće dejstvo azijske centelе, kreiran za osetljivu i oslabljenu kožu kojoj je potrebna nega, a ne samo čišćenje. Njegova blaga, ali efikasna formula uklanja nečistoće bez narušavanja kožne barijere i ostavlja osećaj svežine i mekoće.', 'https://beauty-health.rs/wp-content/uploads/2025/07/HEVEBLUE-Salmon-Caring-Centella-Bubble-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
