INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (651, 52, 'Dr.Melaxin Cemenrete Calcium Dark Spot Eye Cream', 'dr-melaxin-cemenrete-calcium-dark-spot-eye-cream', 'Ključne prednosti: Ublažava tamne kolutove: Aktivne supstance deluju ciljano na pigmentaciju i sivkasti ton ispod očiju. Jača i zaglađuje: Kalcijum i peptidi obnavljaju kožnu barijeru i čine tanku kožu otpornijom na spoljne uticaje. Lagano i brzo upijajuće: Tekstura se odmah upija bez lepljivosti, idealna za dnevnu i noćnu rutinu. Kome je namenjena? Preporučuje se osobama koje imaju tamne kolutove, izražene kapilare oko očiju, suvu i tanku kožu u toj regiji, kao i onima koji žele preventivnu anti-age negu. Zašto volimo Dr.Melaxin Cemenrete Calcium Dark Spot Eye Cream? Ova krema ne deluje samo na površinske nepravilnosti – njen efekat se vremenom produbljuje, pružajući koži stabilniji ton i jaču strukturu. Pomaže u smanjenju natečenosti i sivila koje nastaje zbog umora, genetike ili preteranog naprezanja očiju. U isto vreme, podstiče sintezu kolagena i jača strukturu kože, čineći je glatkijom i elastičnijom. Efekat je postepen, ali trajan – nakon nekoliko nedelja korišćenja, područje oko očiju izgleda budnije, osvetljenije i odmornije. Ne izaziva osećaj peckanja i prilagođena je i osetljivim korisnicima. Aktivni sastojci Cemenrete™ kompleks sa kalcijumom Ova patentirana kombinacija sadrži kalcijum i specifične lipide koji učvršćuju tanku kožu oko očiju. Kalcijum učestvuje u ćelijskoj obnovi i jača međučelijsku komunikaciju, dok lipidna komponenta poboljšava barijernu funkciju. Pomaže u sprečavanju gubitka vlage i štiti osetljivu regiju od nadražujućih faktora iz spoljašnje sredine. Dugoročno, ovaj kompleks čini kožu otpornijom, zategnutijom i manje podložnom borama. Peptidni kompleks Sadrži više vrsta signalnih peptida koji stimulišu sintezu kolagena i elastina. Deluju kao gradivni blokovi koji obnavljaju strukturu kože i umanjuju vidljivost bora. Takođe pomažu u umanjenju podočnjaka izazvanih oslabljenom mikrocirkulacijom. Redovnom upotrebom, područje oko očiju postaje zategnutije i glađe, sa manje finih linija. Niacinamid Višenamenski sastojak koji posvetljuje tamne kolutove, poboljšava tonus kože i umanjuje crvenilo. Niacinamid je poznat po svojoj sposobnosti da ojača barijeru kože i stimuliše prirodnu sintezu ceramida. Daje koži zdraviji, ujednačen izgled i pojačava sjaj. Ne izaziva iritacije i prilagođen je i osetljivom području ispod očiju. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin Cemenrete Calcium Dark Spot Eye Cream je specijalizovana krema za predeo oko očiju namenjena ublažavanju tamnih kolutova, diskoloracija i prvih znakova starenja. Kombinacijom kalcijuma, peptida i biljnih ekstrakata, ova krema pomaže u posvetljavanju, zaglađivanju i obnavljanju tanke kože kapaka.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Dr.Melaxin-Cemenrete-Calcium-Dark-Spot-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
