INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (654, 48, 'Dr. Althea 15% Niacinamide Purity Serum', 'dr-althea-15-niacinamide-purity-serum', 'Ključne prednosti: Intenzivno posvetljivanje tena: Visoka koncentracija niacinamida deluje na fleke, postupalne tragove i sivi ton kože, pružajući osvetljen, ujednačen izgled. Regulacija sebuma i pora: Cink PCA pomaže u kontroli masnoće i sprečava zapušavanje pora, što je ključno za masnu i kombinovanu kožu. Umirujuće i zaštitno dejstvo: Melacut kompleks iz fermentisanog pirinča i lekovitih biljaka umiruje crvenilo, iritacije i jača prirodnu otpornost kože. Kome je namenjen? Preporučuje se osobama sa masnom, kombinovanom i neujednačenom kožom, posebno onima koji se bore sa hiperpigmentacijom, proširenim porama i povremenim upalama. Takođe je odličan izbor za kožu koja gubi sjaj usled stresa, hormonalnih promena ili posledica akni. Zašto volimo Dr. Althea 15% Niacinamide Purity Serum? Serum ima laganu, ali hranljivu teksturu koja se brzo upija, ostavljajući kožu glatkom i nahranjenom bez masnog filma. Učinak nije samo trenutan – vremenom se primećuje smanjenje hiperpigmentacija, stabilizacija lučenja sebuma i zategnutiji izgled pora. Koža postaje ujednačenija, smirenija i manje reaktivna. Zahvaljujući sinergiji niacinamida i cinka, ovaj serum ne samo da poboljšava estetski izgled kože, već i utiče na uzrok nepravilnosti. Redovnom upotrebom, ten deluje svežije, dok se crvenilo i upalne promene povlače. Pogodan je čak i za osetljivu kožu jer ne sadrži alkohol, veštačke boje ni parfeme. Aktivni sastojci Niacinamid (15%) Niacinamid je oblik vitamina B3 koji je izuzetno efikasan u posvetljavanju kože i ujednačavanju tena. U ovoj formuli nalazi se u visokoj koncentraciji od 15%, što ga čini moćnim saveznikom u borbi protiv fleka, sivog tona i postupalnih tragova. Deluje tako što inhibira transfer melanina i smanjuje proizvodnju sebuma. Takođe jača barijeru kože, čime pomaže u zadržavanju vlage. Redovnom upotrebom smanjuje crvenilo i reaktivnost kože. Njegovo dejstvo je snažno, ali u ovoj formuli uravnoteženo umirujućim komponentama. Cink PCA Cink PCA kombinuje mineralni cink i prirodnu hidratantnu komponentu PCA, koji zajedno regulišu lučenje sebuma. Ovaj sastojak je posebno koristan kod masne i aknozne kože jer pomaže u smanjenju pojave bubuljica i sjaja. Pored toga, ima blago antibakterijsko i protivupalno dejstvo, koje pomaže u prevenciji novih nesavršenosti. Ujedno štiti kožu od oksidativnog stresa i doprinosi uravnoteženijem mikrobiomu. Cink PCA ne isušuje kožu, već joj pomaže da zadrži vlagu dok ostaje matirana. Deluje ciljano i bez agresivnog efekta. Melacut kompleks Melacut je biljni kompleks koji kombinuje fermentisanu pirinčanu vodu, ekstrakt portulake, vinove loze i Saururus chinensis biljke. Ova kombinacija deluje sinergijski na smanjenje iritacija, crvenila i mikroupala. Fermentisana voda iz pirinča bogata je mineralima i aminokiselinama koji poboljšavaju osvetljenost kože. Portulaka i vinova loza imaju antioksidativno dejstvo i štite kožu od negativnog uticaja sredine. Ekstrakt Saururus chinensis dodatno umiruje i deluje protivpigmentacijski. Ovaj kompleks čini formulu pogodnom čak i za osetljivu kožu pod stresom. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea 15% Niacinamide Purity Serum je visokoefikasni serum formulisan sa 15% niacinamida, cink PCA i Melacut kompleksom. Namenjen je za regulaciju sebuma, posvetljivanje tena i smanjenje proširenih pora, uz dodatni umirujući efekat na nadraženu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Dr.-Althea-15-Niacinamide-Purity-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
