INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (655, 43, 'd’Alba White Truffle Return Oil Cream Cleanser', 'd-alba-white-truffle-return-oil-cream-cleanser', 'Ključne prednosti: Dve teksture za optimalan učinak: Uljana krema topi šminku i nečistoće, a pena temeljno čisti pore bez isušivanja. Povećava elastičnost i sjaj: Kolagen male molekulske mase i ekstrakt belog tartufa poboljšavaju tonus i osvežavaju ten. Štiti barijeru i umiruje: Skvalan, ceramidi i biljni ekstrakti štite kožu od gubitka vlage i pružaju osećaj udobnosti. Kome je namenjen? Idealan je za sve tipove kože, uključujući suvu i osetljivu, kao i za one koji žele jedno sredstvo koje efikasno uklanja šminku, SPF i nečistoće, a pri tom i neguje. Zašto volimo d’Alba White Truffle Return Oil Cream Cleanser? Ovaj dvofazni čistač nudi spa osećaj već pri prvom koraku rutine. Njegova bogata tekstura u dodiru sa suvom kožom postaje mekana, kao tretmanska maska koja otapa šminku, SPF i višak sebuma. Kada se doda voda, formula se transformiše u nežnu penu koja temeljno uklanja ostatke, bez osećaja zatezanja. Beli tartuf pruža koži antioksidativnu zaštitu i podstiče obnavljanje, dok kolagen i skvalan vraćaju elastičnost i punoću. Biljna ulja i ceramidi dodatno hidriraju i umiruju, pa je koža nakon umivanja mekana, glatka i osvežena, spremna za dalju negu. Aktivni sastojci Beli tartuf Prirodni antioksidans bogat mineralima i amino-kiselinama koji pospešuje obnavljanje kože, vraća joj sjaj i čini je otpornijom na spoljašnje uticaje. Kolagen niske molekulske mase Pomaže koži da zadrži elastičnost, smanjuje sitne linije i pruža efekat zategnutosti i glatkoće. Skvalan Biljni lipid koji hidrira i omekšava, a pritom podržava prirodnu zaštitnu barijeru kože. Ne zapušava pore i pogodan je za osetljivu kožu. Biljna ulja (avokado, maslina, makadamija) Bogata masnim kiselinama i vitaminima, ova ulja obnavljaju, hrane i štite kožu tokom čišćenja. Ceramidi Pomažu u obnavljanju lipidnog sloja kože i sprečavaju transepidermalni gubitak vode, što je ključno za zdravu kožnu barijeru. Biljni ekstrakti (centella, kamilica, zeleni čaj) Deluju protivupalno i umirujuće, pomažući da se koža oporavi nakon izlaganja stresu, šminki ili zagađenju. Dodaj u listu želja Dodaj u listu želja', 'd’Alba White Truffle Return Oil Cream Cleanser je jedinstveni čistač koji se na suvoj koži ponaša kao bogata maska uljane teksture, a u kontaktu s vodom prerasta u nežnu i efikasnu penu. Sadrži niskomolekularni kolagen, italijanski beli tartuf i hranljiva ulja, i namenjen je koži koja želi temeljno čišćenje bez osećaja zatezanja ili isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/08/dAlba-White-Truffle-Return-Oil-Cream-Cleanser-65ml-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
