INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (656, 26, 'Biodance Vita Niacinamide Gel Toner Pads', 'biodance-vita-niacinamide-gel-toner-pads', 'Ključne prednosti: Instant osveženje i toniranje: Hidratantna gel baza hladi i omekšava kožu nakon čišćenja. Ujednačavanje tena: Niacinamid smanjuje crvenilo, hiperpigmentacije i pojačava elastičnost kože. Lagana njega bez lepila: Gel struktura se lako upija i ne ostavlja masan trag, čineći jastučiće idealnim i za masnu kožu. Kome je namenjen? Ovaj proizvod se preporučuju osobama sa masnom, kombinovanom ili dehidriranom kožom, kao i onima koji žele jednostavan i higijenski tretman osveženja nakon treninga, putovanja ili tokom dana. Zašto volimo Biodance Vita Niacinamide Gel Toner Pads? Jastučići kombinuju praktičnost i efikasnost — već posle par minuta koža deluje ujednačenije i vidno osvežena. Gel-tonik umiruje i hladi, pripremajući kožu za serume i kreme. Niacinamid deluje na smanjenje pora, smiruje crvenilo i posvetljuje ten bez agresije. Humektanti poput glicerina i hijaluronske kiseline vežu vlagu za površinu kože, što sprečava osećaj zatezanja. Upotreba redovno održava barijeru kože jakom i otpornom na spoljašnje stresove. Aktivni sastojci Niacinamid (5 %) Reguliše lučenje sebuma, smanjuje proširene pore i pomaže u ravnoteži tena. Blagotvoran je za sve tipove kože, čak i osetljivu, jer stimuliše obnovu barijere i utiče na smanjenje crvenila. Hijaluronska kiselina Humektant koji veže vlagu i pruža osećaj podatnosti i svežine. Čini površinu kože glatkom i elastičnom. Glicerin Prirodni emolijent koji zadržava vlagu i daje ten mekanim bez masnog osećaja. Doprinosi dugotrajnoj hidrataciji. Biljni kompleks (npr. zeleni čaj, aloe, centella)* Umiruje kožu, smanjuje upale i pruža antioksidativnu zaštitu. Doprinosi pozitivnom osećaju na licu, čak i nakon napornog dana. Blagi konzervansi i stabilizatori gel baze Zadržavaju svežinu formule u pojedinačnim jastučićima i sprečavaju kontaminaciju, čineći upotrebu higijenskom i jednostavnom. Dodaj u listu želja Dodaj u listu želja', 'Biodance Vita Niacinamide Gel Toner Pads su praktični jastučići natopljeni 5 % niacinamida, biljnim kompleksom i hidratantnim humektantima, koji revitalizuju, toniraju i ujednačavaju ten bez iritacija. Namenjeni su koži koja traži brz i efikasan tretman osveženja i regeneracije.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Biodance-Vita-Niacinamide-Gel-Toner-Pads.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
