INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (657, 26, 'Biodance Collagen Cleansing Oil', 'biodance-collagen-cleansing-oil', 'Ključne prednosti: Dubinsko čišćenje bez isušivanja: Kombinacija biljnih ulja nežno uklanja nečistoće, šminku i SPF, ne menjajući prirodni nivo vlage. Obnavlja elastičnost i sjaj: 243 Da ultra-nizak molekul kolagena prodire duboko i pomaže u jačanju i zaglađivanju tena. Ne-masna i ne-zapušava pore: Dermatološki je testiran – bez PEG-a i sintetičkih ulja, ostavlja kožu čistom, bez zapušivanja i masnog traga. Kome je namenjeno? Preporučuje se osobama svih tipova kože, naročito onima koje često koriste SPF, šminku ili imaju izražen T-zon. Idealno rešenje za kožu sklone osipima, koja traži efikasno, ali nežno čišćenje bez osećaja zatezanja. Zašto volimo Biodance Collagen Cleansing Oil? Tekstura gustom ulja klizi po koži i na dodir otapa nečistoće, pretvarajući se u mlečnu emulziju kada dodate vodu – što omogućava bezbedno i efektnog ispiranje. Jojoba, grožđe, suncokret i moringa ulja sinergijski razgrađuju nečistoće, a istovremeno hrane i umiruju kožu, ostavljajući ten osveženim i mekanim. Ultra-niske molekulske težine kolagena prodire dublje u kožu, pojačavajući elastičnost i doprinosi glatkijem tonu. Brza emulzifikacija čini čišćenje lakim i praktičnim, bez masnog ili lepljivog osećaja. Dermatološka potvrda nekomedogenosti znači da ne izaziva nepravilnosti niti zapušava pores. Nakon nanošenja i ispiranja, koža ostaje prijatno glatka, čista, nežna i spremna za naredne korake nege. Aktivni sastojci Biljna ulja (jojoba, grožđe, suncokret, moringa) Lagani prirodni emolijenti koji oponašaju prirodni sebum kože, olakšavaju otapanje šminke i SPF-a, a pritom hrane i štite barijeru kože. Ne zapušavaju pore i odgovaraju svim tipovima kože. Ultra-niska molekulska kolagena Prodire dublje u kožu od tradicionalnog kolagena, stimulišući čvrstoću i elastičnost. Pomaže u obnavljanju tonusa i daje ten mekoću bez osećaja težine. Peptidi (Acetyl Hexapeptide‑8, Copper Tripeptide‑1 i dr.) Podržavaju regeneraciju kože, smanjuju vidljivost sitnih linija i jačaju elastičnost. Kombinuju anti-aging dejstvo sa efektom umirenja i hrane. Dodaj u listu želja Dodaj u listu želja', 'Biodance Collagen Cleansing Oil je nežno ulje za čišćenje sa kolagenom i prirodnim biljnim uljima (jojoba, grožđe, suncokret, moringa), koje otapa šminku, SPF i višak sebuma bez narušavanja prirodne hidriranosti kože. Namenjeno je svim tipovima kože, uključujući osetljivu, jer održava barijeru kože i sprečava zatezanje.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Biodance-Collagen-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
