INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (658, 26, 'Biodance Collagen Mask To Foam Cleanser', 'biodance-collagen-mask-to-foam-cleanser', 'Ključne prednosti: Dva efekta u jednom: Deluje kao tretmanska maska i penušavi čistač, istovremeno hraneći i osvežavajući kožu. Kolagen za elastičnost: Kolagen male molekulske mase prodire dublje, poboljšava tonus i vraća koži glatkoću. Bez osećaja zatezanja: Hidrirajuća baza i blagi surfaktanti štite kožnu barijeru i ostavljaju kožu mekom. Kome je namenjen? Preporučuje se normalnoj, suvoj i kombinovanoj koži, kao i osobama koje žele nežno, ali temeljno čišćenje uz dodatnu negu u jednoj fazi. Odličan izbor za kožu kojoj nedostaje elastičnost, sjaj ili osećaj svežine. Zašto volimo Biodance Collagen Mask To Foam Cleanser? Ovaj inovativni čistač započinje kao bogata, umirujuća maska koja se prijanja uz kožu, omekšava nečistoće i priprema pore za dublje čišćenje. U dodiru sa vodom, formula se pretvara u penu koja uklanja ostatke šminke, SPF-a i sebuma, a da pritom ne oštećuje prirodnu zaštitnu barijeru kože. Kolagen male molekulske mase poboljšava elastičnost i obnavlja kožu iznutra, dok dodatni humektanti poput glicerina i squalana sprečavaju dehidrataciju. Nakon ispiranja, koža ostaje osvežena, blistava i vidno mekša — spremna za tonik i dalje korake u rutini. Aktivni sastojci Kolagen niske molekulske mase Zahvaljujući svojoj veličini, prodire dublje u kožu i pruža jaču podršku strukturi kože. Vraća elastičnost, popunjava fine linije i pomaže u održavanju čvrstoće i jedrine. Squalane Biljni lipid koji hidrira, omekšava i pomaže u jačanju zaštitne barijere kože. Ne zapušava pore i ne ostavlja mastan trag, ali čini kožu prijatno podatnom. Glicerin Snažan humektant koji vezuje vodu za površinu kože, pruža dugotrajan osećaj hidriranosti i sprečava isušivanje tokom čišćenja. Blagi surfaktanti Bez sulfata i iritansa, ovi sastojci stvaraju finu penu koja efikasno uklanja nečistoće, ali zadržava prirodnu vlažnost kože. Biljni ekstrakti Dodati radi umirivanja i osvežavanja kože. Doprinose osećaju čistoće bez crvenila, zatezanja i neprijatnosti posle umivanja. Beta-glukan Pomaže u smirivanju kože, regeneraciji mikrooštećenja i jačanju otpornosti kože na spoljne faktore. Dodaj u listu želja Dodaj u listu želja', 'Biodance Collagen Mask To Foam Cleanser je dvofazni čistač koji u dodiru sa kožom funkcioniše kao hranljiva maska, a zatim se pretvara u bogatu penu koja efikasno uklanja nečistoće. Formulisan sa niskomolekularnim kolagenom i hidratantnim sastojcima, namenjen je koži kojoj je potrebno temeljno, ali nežno čišćenje bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Biodance-Collagen-Mask-To-Foam-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
