INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (659, 26, 'Biodance Collagen Cream', 'biodance-collagen-cream', 'Ključne prednosti: Povećava elastičnost i zateže ten: Kremu čini bogata količina kolagena koji vraća zategnutost i čvrstinu. Obnavlja i neguje kožu: Peptidi stimulišu regeneraciju ćelija i podržavaju barijeru kože. Dugotrajna hidratacija bez težine: Glicerini i ulja hrane kožu i pružaju dugotrajnu vlažnost bez okluzivnog osećaja. Kome je namenjena? Preporučuje se osobama srednjeg i zrelijeg uzrasta, kao i svima kojima je koža dehidrirana, umorna ili naglo izgubljena na volumenu. Pogodna je i za one koji žele bogatu negu bez masnog filma. Zašto volimo Biodance Collagen Cream? Biodance Collagen Cream ima bogatu, ali lako razmazivu kremastu teksturu koja se brzo upija i ostavlja kožu mekanom, glatkom i podatnom. Niskomolekulski kolagen prodire dublje kako bi popunio sitne linije i povećao čvrstinu, dok peptidi pospešuju obnovu kože i osnažuju njenu barijeru. Glicerin, squalane i lagana biljna ulja pružaju dubinsku hidrataciju i elastičnost, a istovremeno čine kožu nežnom na dodir. Redovnim korišćenjem ten izgleda blistavije, mirnije i osveženo, bez osećaja težine. Krema je savršena kao završni sloj nege u dnevnoj ili noćnoj rutini i pruža savršenu podlogu za šminku. Aktivni sastojci Kolagen niske molekulske težine Prodire dublje u kožu i pomaže u popunjavanju sitnih linija te vraća strukturalnu čvrstinu. Poboljšava elastičnost i zaglađuje ten već nakon nekoliko dana primene. Pomaže u očuvanju prirodne barijere i smanjuje osećaj zatezanja. Peptidi Sinergijski potiču regeneraciju i sintezu strukturalnih proteina kože. Poboljšavaju tonus, elastičnost i glatkoću zahvaljujući stimulaciji kolagena. Osnažuju otpornost kože protiv stresa i spoljašnjih uticaja. Glicerini i squalane Dubinski hrane i vezuju vlagu u koži, sprečavajući njen gubitak. Glicerin privlači vlagu, a squalane simulira prirodni sebum, pružajući mekan i satenski efekat bez težine. Lagano biljno ulje Dodaje ravnotežu hidrataciji, hrani kožu i obogaćuje kremu hranljivim masnim kiselinama. Omekšava, elastično i povećava sjaj bez okluzivnog osećaja. Dodaj u listu želja Dodaj u listu želja', 'Biodance Collagen Cream je hranljiva krema bogata kolagenom niskog molekulske težine i peptidima, namenjena dubinskoj hidrataciji, zatezanju i revitalizaciji kože. Idealna je za kožu koja traži mekoću, elastičnost i mladalački sjaj bez osećaja masnoće.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Biodance-Collagen-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
