INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (661, 25, 'Benton Ceramide Calming Ato Body Lotion', 'benton-ceramide-calming-ato-body-lotion', 'Ključne prednosti: Obnavlja zaštitnu barijeru: Pet različitih ceramida jača i učvršćuje kožnu barijeru, sprečavajući gubitak vlage. Umiruje iritacije: DIC Benton Calming Complex—a biljni miks kao što su zelen čaj i Heartleaf—smanjuje crvenilo i ublažava svrabež izazvan spoljašnjim faktorima. Ne ostavlja lepljiv trag: Blaga emulziona tekstura se brzo upija, bez belog sloja ili osećaja težine. Kome je namenjen? Savršen je za osetljivu, suvu ili atopijsku kožu koja često oseća zatezanje, svrabež ili crvenilo, ali odgovara i bilo kom tipu kože kojem je potrebna izbalansirana i efikasna hidratacija. Zašto volimo Benton Ceramide Calming Ato Body Lotion? Ovaj losion pruža brzo olakšanje od suvoće, zatezanja i svraba. Kombinacija ceramida pomaže u dugotrajnoj obnovi oštećene kožne barijere, dok panthenol i biljni kompleks umiruju kožu i smanjuju crvenilo. Posebno se preporučuje u periodima kada je koža izložena hladnoći, vetru ili toploti, jer stvara zaštitni sloj bez masnog osećaja. Redovnom upotrebom koža postaje vidno mekša, elastičnija i manje reaktivna na spoljašnje faktore. Zahvaljujući laganoj formuli, može se koristiti više puta dnevno, čak i kod osoba koje ne vole osećaj &#8220;teških&#8221; krema. Aktivni sastojci Pet vrsta ceramida Ceramidi NP, NS, AS, EOP i AP jačaju kožnu barijeru i sprečavaju isparavanje vlage. Posebno su važni kod suve i osetljive kože jer vraćaju elastičnost i smanjuju osećaj zatezanja. U sinergiji deluju dublje i efikasnije nego pojedinačno. Pantenol (provitamin B5) Pomaže u regeneraciji kože, smanjuje iritacije i ublažava neprijatan osećaj suvoće. Daje osećaj hlađenja i umirenosti, posebno nakon tuširanja ili izlaganja suncu i vetru. DIC Calming Complex Biljna mešavina zelenog čaja, srčane trave i kamilice koja deluje protivupalno i smanjuje svrab. Umiruje kožu koja je reaktivna na temperaturne promene ili kontaktne iritacije. Beta-glukan Prirodni umirujući polisaharid koji hidrira i poboljšava sposobnost kože da zadrži vlagu. Takođe podržava regeneraciju i pruža osećaj mekoće. Dodaj u listu želja Dodaj u listu želja', 'Benton Ceramide Calming Ato Body Lotion je lagani, ali dubinski hidratantni losion sa pet vrsta ceramida i biljnim kompleksom koji trenutno umiruje, štiti i popravlja osetljivu kožu. Namenjen je svim tipovima kože, pa posebno suvoj, sklono svrabu i iritiranoj, pružajući dugotrajnu zaštitu i udobnost.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Benton-Ceramide-Calming-Ato-Body-Lotion-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
