INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (662, 12, 'APLB Retinol Vitamin C Vitamin E Ampoule Serum', 'aplb-retinol-vitamin-c-vitamin-e-ampoule-serum', 'Ključne prednosti: Zateže i zaglađuje kožu: Retinol podstiče proizvodnju kolagena i obnavlja površinski sloj kože. Ujednačava ten i posvetljuje: Vitamin C smanjuje tamne fleke i vraća svežinu umornoj koži. Štiti i obnavlja barijeru: Vitamin E i umirujući biljni ekstrakti pomažu u očuvanju vlažnosti i elastičnosti kože. Kome je namenjen? Preporučuje se osobama sa znakovima starenja, neujednačenim tenom i zrelijom ili umornom kožom. Idealan je za one koji traže intenzivan, ali balansiran serum protiv bora, fleka i gubitka tonusa. Zašto volimo APLB Retinol Vitamin C Vitamin E Ampoule Serum? Serum pruža trostruku funkciju – anti-age, posvetljujuću i zaštitnu. Retinol deluje postepeno, ali efikasno: zaglađuje površinu kože i smanjuje fine linije. Vitamin C dodatno posvetljuje i ujednačava ten, dok vitamin E pruža antioksidativnu podršku, pomažući koži da se oporavi od svakodnevnog stresa. Biljni ekstrakti i hijaluronska kiselina ublažavaju potencijalnu iritaciju i hidriraju, čineći ovaj serum pogodnim i za one koji retinol uvode prvi put. Redovnim korišćenjem, koža postaje čvršća, glađa i vidno osvežena. Aktivni sastojci Retinol Proveren sastojak u borbi protiv bora koji stimuliše sintezu kolagena i ubrzava obnavljanje ćelija. Deluje na fine linije i grubu teksturu, čineći kožu zategnutijom i ujednačenijom. U ovoj formuli je prisutan u koncentraciji od 0,3 %, što je efikasna, ali nežna doza pogodna i za osetljiviju kožu. Redovnim korišćenjem koža dobija glatkiji, svetliji i puniji izgled. Vitamin C Poznat po svojim posvetljujućim i antioksidativnim efektima, pomaže u smanjenju hiperpigmentacija i vraća koži zdrav sjaj. Takođe stimuliše sintezu kolagena i štiti ćelije od oštećenja izazvanih slobodnim radikalima. Stabilizovani oblik u serumu omogućava efikasnost bez oksidacije i iritacije. Vitamin E Deluje kao zaštitni antioksidans, umanjujući štetu izazvanu UV zračenjem i zagađenjem. Ujedno omekšava kožu, jača njenu otpornost i povećava efikasnost vitamina C u formuli. Pruža osećaj elastičnosti i sprečava gubitak vlage. Dodaj u listu želja Dodaj u listu želja', 'APLB Retinol Vitamin C Vitamin E Ampoule Serum je koncentrisani noćni serum sa 0,3 % retinola, stabilizovanim vitaminom C i vitaminom E, kreiran da poboljša teksturu, ujednači ten i smanji vidljivost bora. Njegova formula kombinuje anti-age efekte sa antioksidativnom zaštitom i hidratacijom, bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Retinol-Vitamin-C-Vitamin-E-Ampoule-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
