INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (663, 12, 'APLB Glutathione Niacinamide Cleansing Oil', 'aplb-glutathione-niacinamide-cleansing-oil', 'Ključne prednosti: Dublje čišćenje bez isušivanja: Kombinacija ulja i emulgatora otapa šminku i nečistoće, a hidrirajuće ulje sprečava osećaj zatezanja. Posvetljuje i ujednačava ten: Glutation i niacinamid deluju na smanjenje tamnih mrlja i hiperpigmentacije od samog početka nege. Umiruje i štiti barijeru: Biljna ulja i antioksidansi deluju protivupalno i štite kožu od oksidativnog stresa tokom čišćenja. Kome je namenjeno? Preporučuje se svima koji koriste šminku, SPF, ili lagane makeup formule i traže nežan, ali efikasan način da uklone tragove tokom dana. Dobro funkcioniše i za dehidriranu, hrapavu ili umornu kožu kojoj je potrebno osveženje i sjaj bez osećaja suvoće. Zašto volimo APLB Glutathione Niacinamide Cleansing Oil? Tekstura spoja ulja i emulgatora lako se razmazuje, otapa nečistoće bez trljanja, a pretvara se u mlečni emulzijat kada se dođe u dodir s vodom, ostavljajući kožu čistom i mekom. Glutation kao snažan antioksidans pomaže da koža ostane bistrija i da pigmentacija nakon UV izlaganja postepeno bledi. Niacinamid dodatno posvetljuje i umiruje ten, sprečavajući crvenilo. Biljna ulja poput suncokretovog i pšeničnog pačulija hrane i štite barijeru kože tokom tretmana, pa ne ostavlja osećaj zatezanja. Održava prirodni balans, pa je pogodna čak i za kombinovanu kožu kojoj često nedostaje elastičnosti nakon čišćenja. Nakon upotrebe, koža ostaje vlažna, mekana i spremna za dalji nastavak nege. Aktivni sastojci Glutation Moćan antioksidans koji štiti kožu od slobodnih radikala i usporava oksidativne procese. Deluje na posvetljivanje ten, posebno kod postupalnih hiperpigmentacija. Pomaže u balansiranju oksidativnog stresa tokom čišćenja. Postepeno učvršćuje i umiruje kožu. U ovoj formuli ostaje stabilan zbog zaštite unutar ulja. Idealna polazna nega za ekološki i osveženi izgled kože. Niacinamid (5 %) Deluje na regulaciju sebum-a, posvetljivanje i umirenje ten. Pojačava efekte glutationa i doprinosi vidljivo ujednačenom tenu. Blagotvoran je za barijeru kože i podržava njenu strukturu. Koristan je i za kožu sklonu aknama jer deluje antiinflamatorno. Bez agresije i uobičajenih iritacija. Čini da čišćenje bude više od samog uklanjanja nečistoće – tretman ujutru i uveče. Suncokretovo i pšenično ulje Prirodna biljna ulja bogata vitaminom E i masnim kiselinama. Deluju emolijentno, hrane kožu i jačaju njenu zaštitu. Sprečavaju isušivanje i povoljne su za osetljive i reaktivne tipove. Pomažu glatkoću i elastičnost odmah nakon čišćenja. Ne ostavljaju masni trag zahvaljujući formulaciji emulgujućeg sistema. Dodaj u listu želja Dodaj u listu želja', 'APLB Glutathione Niacinamide Cleansing Oil je uljasti čistač obogaćen glutationom i 5 % niacinamida, koji nežno otapa nečistoće, šminku i SPF bez isušivanja. Namenjen je koži koja traži dubinsko čišćenje, a istovremeno umiruje i osvetljava ten.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Glutathione-Niacinamide-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
