INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (665, 12, 'APLB Glutathione Niacinamide Mist Essence', 'aplb-glutathione-niacinamide-mist-essence', 'Ključne prednosti: Brza hidratacija i osveženje: Bistra vodena formula osvežava i obnavlja vlagu bez čekanja i lepljenja. Ujednačava ten i posvetljuje: Glutation i niacinamid deluju na hiperpigmentacije i umiruju crvenilo. Štiti i jača barijeru kože: Ceramidi i antioksidanti iz bilja štite od agresora i smanjuju zategnutost. Kome je namenjen? Savršen je za sve tipove kože, posebno ako provodiš vreme u klimatizovanim prostorima i želiš osveženje. Takođe je odličan u gimnastičkoj torbici, tokom putovanja ili na poslu – kad god ti je potrebna pratnja nege. Zašto volimo APLB Glutathione Niacinamide Mist Essence? Ovaj sprej trenutno osvežava kožu, oslobađa osećaj zatezanja i vraća vlagu. Glutation pruža zaštitu od slobodnih radikala dok nežno izjednačava ten. Niacinamid dodatno pomaže pri smirivanju iritacija i poboljšanju teksture. Ceramidi i biljni ekstrakti čuvaju kožnu barijeru, pružajući dugotrajan osećaj udobnosti. Formula ne ostavlja tragove, pa može da se koristi i preko šminke. Nakon nekoliko dana redovne upotrebe lice ostaje glatko i sveže. Aktivni sastojci Glutation Snažan antioksidans koji štiti kožu od štetnog dejstva slobodnih radikala i jača njen osvetljujući kapacitet. Pomaže u održavanju bistrine i svežine tona. U ovoj formuli deluje blagim, dnevnim učinkom bez iritacija. Stabilan je u vodenoj bazi tonika. Doprinosi osećaju zaštićene i obnovljene kože. Idealna podrška ujutru i uveče. Niacinamid (5 %) Vitamin B3 koji posvetljuje i balansira ten, smanjuje crvenilo i vidljivost pora. Pomaže uspostaviti ravnotežu sebuma i umiruje, čineći kožu glatkijom. Jača kožnu barijeru i smanjuje iritacije. Blagotvoran je i za osetljive tipove kože. Uz glutation, daje efekat ujednačenijeg i čistijeg tena. Ne izaziva peckanje ni sušenje. Dodaj u listu želja Dodaj u listu želja', 'APLB Glutathione Niacinamide Mist Essence je osvežavajući sprej sa glutationom i 5 % niacinamida, koji hidrira, umiruje i posvetljava ten odmah nakon nanošenja. Namenjen je brizi tokom dana kada ti koža treba trenutna hidratacija i balans.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Glutathione-Niacinamide-Mist-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
