INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (666, 12, 'APLB Glutathione Niacinamide Facial Toner', 'aplb-glutathione-niacinamide-facial-toner', 'Ključne prednosti: Osvežava i priprema kožu: Bistra tekstura momentalno hladi i omekšava kožu, čineći je spremnom za serume i kreme. Posvetljuje i smanjuje tamne mrlje: Glutation i niacinamid deluju zajedno na blagu regulaciju pigmentacije i osvetljenje tena. Balansira i umiruje barijeru: Ceramidi i biljni ekstrakti umanjuju osećaj zatezanja i štite kožu od iritacija. Kome je namenjen? Pogodan je za sve tipove kože, a posebno za one koji u ranoj fazi žele hidraciju, osveženje i smirenje tena. Takođe je odličan za masnu, kombinovanu ili dehidriranu kožu kojoj nedostaje bistrine i balansa. Zašto volimo APLB Glutathione Niacinamide Facial Toner? Ovaj tonik donosi osećaj svežine, bez lepljivog ili težeg filma. Glutation pruža antioksidativnu podršku i deluje na osvetljenje postojećih tragova. Niacinamid dodatno radi na ujednačavanj ﻿ u tena i redukciji crvenila. Ceramidi i biljni ekstrakti štite barijernu funkciju i sprečavaju zatezanje, čak i posle umivanja. Pogodan je kao korak nakon čišćenja, jer priprema kožu za bolje upijanje aktivnih sastojaka. Redovnom upotrebom ten postaje bistriji, mirniji i vizuelno zdraviji. Aktivni sastojci Glutation Snažan antioksidans koji štiti kožu od štetnog dejstva slobodnih radikala i jača njen osvetljujući kapacitet. Pomaže u održavanju bistrine i svežine tona. U ovoj formuli deluje blagim, dnevnim učinkom bez iritacija. Stabilan je u vodenoj bazi tonika. Doprinosi osećaju zaštićene i obnovljene kože. Idealna podrška ujutru i uveče. Niacinamid (5 %) Vitamin B3 koji posvetljuje i balansira ten, smanjuje crvenilo i vidljivost pora. Pomaže uspostaviti ravnotežu sebuma i umiruje, čineći kožu glatkijom. Jača kožnu barijeru i smanjuje iritacije. Blagotvoran je i za osetljive tipove kože. Uz glutation, daje efekat ujednačenijeg i čistijeg tena. Ne izaziva peckanje ni sušenje. Ceramidi Prirodni lipidi koji obnavljaju zaštitnu barijeru i sprečavaju gubitak vlage. Obezbeđuju osećaj mekoće bez težine. Posebno su važni posle čišćenja jer štite od spoljašnjih iritacija. U kombinaciji sa niacinamidom predstavljaju snažnu podršku otpornosti kože. Ne ostavljaju masni trag na koži. Pomažu u sprečavanju isušivanja tokom dana. Dodaj u listu želja Dodaj u listu želja', 'APLB Glutathione Niacinamide Facial Toner je lagani tonik sa glutationom i 5 % niacinamida, koji pruža osveženje, posvetljenje i balans kože bez osećaja zatezanja. Namenjen je svima koji traže nežan početak nege i ujednačeniji ten.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Glutathione-Niacinamide-Facial-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
