INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (667, 12, 'APLB Collagen EGF Peptide Facial Cream', 'aplb-collagen-egf-peptide-facial-cream', 'Ključne prednosti: Povećava elastičnost i zateže fine linije: Kolagen i peptidi podstiču obnovu strukturalnih proteina kože i daju instant osećaj napetosti. Podstiče regeneraciju ćelija: EGF peptid podržava obnovu i brz oporavak kože, čineći ten blistavijim. Intenzivno hidrira bez opterećivanja: Hijaluronska kiselina doprinosi dugotrajnoj hidrataciji i mekoći, bez osećaja masnoće. Kome je namenjena? Krema je idealna za osobe zrele kože ili one koji žele sprečiti prve znake starenja, a kojima je potrebna hranljiva i negovana formula. Dobro funkcioniše i za kožu koja je dehidrirana, umorna ili traži dodatni „boost” elastičnosti. Zašto volimo APLB Collagen EGF Peptide Facial Cream? Ova bogata, ali lako razmaziva krema dobro se upija i ostavlja ten mekanim i punim. Kolagen pomaže koži da zadrži vlagu i pruža strukturalnu potporu, što odmah daje osećaj zategnutosti. EGF peptid podstiče obnovu ćelija i regenerativne procese, redukujući sitne linije i vraćajući sjaj. Hijaluronska kiselina veže vlagu u višim i dubljim slojevima kože, čineći teksturu glatkom i podatnom. Redovnom upotrebom koža postaje otpornija, elastičnija i vidljivo odmornija. Krema je pogodna za dnevnu i noćnu negu, služeći kao snažna podrška u borbi protiv starenja. Aktivni sastojci Kolagen (hidrolizovani) Mali proteinski fragmenti koji prodiru u kožu i pomažu u nadoknadi vlage i volumena. Vraća ten čvršćim i elastičnijim već nakon nekoliko dana primene. Povećava barijernu funkciju kože i smanjuje osećaj zatezanja. Korisno je i za kožu izloženu stresu i zagađivanju. U ovoj formuli pomaže da ostane mekana i podatna. Idealna baza za anti-age negu bez osećaja težine. EGF peptid (SH‑Oligopeptid‑1) Faktor rasta koji stimuliše ćelijsku regeneraciju i sintezu kolagena i elastina. Pospešuje obnovu strukture kože i revitalizuje umoran ten. Pomaže u smanjenju sitnih linija i obnavlja površinsku napetost. Dodatno poboljšava sjaj kože i daje mladalački izgled. Ne izaziva crvenilo — čak i kod osetljivih tipova kože. Deluje celovito na teksturu, ton i podatnost kože. Hijaluronska kiselina (višestruke molekulske težine) ﻿ Snažno privlači i zadržava vlagu na površini i unutar kože. Popunjava sitne linije i omogućava dugotrajnu hidrataciju. Davanjem mladenačke punoće kože, ovaj sastojak omogućava „glass skin” efekat. Brzo se upija i ne ostavlja masni trag. U kombinaciji sa kolagenom i EGF-om potpomaže revitalizaciju kože. Dodaj u listu želja Dodaj u listu želja', 'APLB Collagen EGF Peptide Facial Cream kombinuje kolagen, EGF peptide i hijaluronsku kiselinu za dubinsku hidrataciju, regeneraciju i zaglađivanje kože. Namenjena je svim tipovima kože koje žele poboljšanje elastičnosti, smanjenje sitnih linija i očuvanje mladalačkog izgleda.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Collagen-EGF-Peptide-Facial-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
