INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (668, 12, 'APLB Bakuchiol Propolis Facial Cream', 'aplb-bakuchiol-propolis-facial-cream', 'Ključne prednosti: Poboljšava izgled bora i fine linije: Bakuchiol podstiče sintezu kolagena i poboljšava elastičnost bez ljuskanja. Obnavlja i umiruje kožu: Propolis ima antibakterijska i umirujuća dejstva te smanjuje crvenilo i upalu. Obezbeđuje intenzivnu hidrataciju: Hijaluronska kiselina, ceramidi i glicerin čine kožu mekanom i gipkom, bez osećaja ulja ili težine. Kome je namenjena? Preporučuje se osobama koje primećuju prve znake starenja, žele glatkiju i zdraviju kožu, ali ne podnose retinol. Takođe je odličan izbor za suvu i osetljivu kožu kojoj je potrebna umirujuća i regenerativna nega. Zašto volimo APLB Bakuchiol Propolis Facial Cream? Krema ima bogatu, ali lako razmazivu teksturu koja se brzo upija i ostavlja kožu mekom i negovanom. Bakuchiol deluje kao blaga, biljka alternativa retinolu – bez iritacija i ljuštenja, a efikasno smanjuje linije i ujednačava ton. Propolis dodatno umiruje i jača odbrambene mehanizme kože, posebno kod reaktivnih ili oštećenih tipova. Kombinovani sastojci obnavljaju barijeru, dubinski hidriraju te vraćaju elastičnost i prirodan sjaj. Redovnom upotrebom koža postaje glatka na dodir, a ten zdravo blistav. Kreiranje fine satenske završnice pruža osećaj komfora i mekoće, bez masnog filma. Aktivni sastojci Bakuchiol (1 %) : Prirodna alternativa retinolu dobivena iz biljke babchi, koja stimuliše produkciju kolagena i elastina. Ne izaziva crvenilo, suvoću ni perutanje, što ga čini pogodnim za osetljivu kožu. Ublažava borice i daje koži ujednačen izgled, bez iritacija. Deluje postepeno, ali vidno, nakon više nedelja upotrebe. Takođe poboljšava strukturu i sjaj kože. Idealna je zamena za retinol u dnevnoj i noćnoj rutini. Propolis (25 %) : Prirodni pčelinji ekstrakt bogat flavonoidima i fenolima s antibakterijskim i umirujućim efektima. Pomaže u smanjenju crvenila i obnovi oštećenja uzrokovanih aknama i stresom. Njegova prepoznatljiva sposobnost zaceljivanja podržava barijeru kože i štiti od spoljašnjih faktora. U većoj koncentraciji deluje snažno, a formula ostaje lagana i prijatna. Daje koži zdrav sjaj i mekoću. Idealna za one koji traže prirodan cell-balans tretman. Hijaluronska kiselina : Humektant koji vezuje vlagu iz okoline i zadržava je u koži, što rezultira prikladno hidriranom i elastičnom teksturom. Deluje tako što čini sitne bore manje vidljivim te podiže nivo vlage više dana nakon nanošenja. U ovoj kremi omogućava osećaj „glass skin” bez težine. Pomaže da se koža oseća podatnije i napetije na dodir. Ključna je za balans između efekta regeneracije i komfora. Dodaj u listu želja Dodaj u listu želja', 'APLB Bakuchiol Propolis Facial Cream kombinuje 1 % bakuchiola i 25 % propolisa kako bi nežno regenerisao, hidratizirao i osnažio kožu, bez iritacije. Namenjen je svima koji žele anti-age rezultate i bolju teksturu kože, a izbegavaju retinol.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Bakuchiol-Propolis-Facial-Cream-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
