INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (669, 12, 'APLB Azelaic Acid Peptide Ampoule Serum', 'aplb-azelaic-acid-peptide-ampoule-serum', 'Ključne prednosti: Ublažava akne i osvetljava ten: Azelaična kiselina deluje protivupalno i antibakterijski, dok peptidi posvetljuju i poboljšavaju ton kože. Podstiče regeneraciju kože: Faktori rasta i centella asiatica podržavaju zarastanje, umiruju i smanjuju crvenilo. Hidrira i jača zaštitnu barijeru: Hijaluronska kiselina, beta-glukan, ceramidi i squalane obezbeđuju vlažnost i otpornost kože. Kome je namenjen? Serum je idealan za osobe sa masnom, kombinovanom ili osetljivom kožom sklonom nepravilnostima, pigmentacijama i površinskim ožiljcima. Pogodan je i za one koji žele da postepeno poboljšaju tonus i teksturu kože bez agresivnih sastojaka. Zašto volimo APLB Azelaic Acid Peptide Ampoule Serum ? Ovaj lagani serum kombinuje delovanje azelaične kiseline sa regenerišućim peptidima i umirujućim biljnim ekstraktima. Deluje tako što postepeno smanjuje vidljivost fleka, crvenila i nepravilnosti, a pritom ne isušuje niti iritira kožu. Sadrži i SH-oligopeptid-1 (EGF), koji podstiče obnovu ćelija i pomaže u zaglađivanju sitnih linija. Uz dodatak beta-glukana, hijaluronske kiseline i squalana, serum obezbeđuje dugotrajnu hidrataciju i osećaj mekoće. Prilikom nanošenja lako klizi po koži i ostavlja baršunasti finiš bez lepljivosti. Već nakon nekoliko dana koža izgleda ujednačenije, smirenije i elastičnije. Aktivni sastojci Dodaj u listu želja Dodaj u listu želja', 'APLB Azelaic Acid Peptide Ampoule Serum je serum sa azelaičnom kiselinom, peptidima i ekstraktom centelle koji umiruje, posvetljuje ten i poboljšava teksturu kože. Namenjen je osobama sa sklonim aknama, hiperpegmentacijom ili hrapavim tenom, pružajući balans između eksfolijacije, hidratacije i regeneracije.', 'https://beauty-health.rs/wp-content/uploads/2025/07/APLB-Azelaic-Acid-Peptide-Ampoule-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
