INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (670, 11, 'Anua Niacinamide 5 TXA Brightening Pad', 'anua-niacinamide-5-txa-brightening-pad', 'Ključne prednosti: Ujednačavanje tena i osvetljavanje: Niacinamid i traneksaminska kiselina deluju sinergijski na smanjenje pigmentacije i fleka, čineći ten bistrijim. Umirivanje i obnova barijere: Cica ekstrakt, alantoin i panthenol štite i popravljaju zaštitu kože, smanjujući crvenilo i neugodnost. Hidratacija i glatkija koža: Hijaluronska kiselina u kombinaciji s betainom osigurava mekoću, otežanost i svež “glass” izgled bez lepljenja. Kome su namenjeni? Idealni su za osobe sa neujednačenim tenom, pigmentnim mrljama i suvom ili osetljivom kožom. Posebno pogodni za kožu koja reaguje nakon izlaganja suncu, tretmana ili stresnih uslova. Zašto volimo Anua Niacinamide 5 TXA Brightening Pad? Jastučići su prirodno natopljeni laganom otopinom koja se brzo upija i pruža osećaj osveženja već nakon nanošenja. Niacinamid i traneksaminska kiselina posvetljavaju ten i ujednačavaju boju kože bez iritacija. Hijaluroni omekšavaju površinu i zadržavaju vlagu, dok cica ekstrakt i panthenol smiruju i regenerišu barijeru kože. Redovnom upotrebom multiplikuje se osećaj blistavosti i otpornosti kože. Idealni su kao deo jutarnje nege da bi koža izgledala odmorno i ravnomerno, ali i za večernju obnovu jer sprečavaju isušivanje i podstiču zdrav izgled. Aktivni sastojci Niacinamid (5 %) Deluje na posvetljivanje tena i smanjenje crvenila regulacijom melaninske sinteze. Poboljšava čvrstinu kože i smanjuje pojavu proširenih pora. Jača zaštitnu barijeru i balansira sebum. Koristan je i kod pigmentnih mrlja nakon bubuljica. Daje zdrav i ujednačen izgled tena uz minimalan rizik od iritacije. Traneksaminska kiselina Antipigmentni sastojak koji inhibira važne enzime vezane za stvaranje melanina. Ubrzava postepeno posvetljivanje fleka i sprečava ponovno tamnjenje. Doprinosi boljoj otpornosti kože na spoljne agresore. Efikasna i nežna, pogodna za redovnu upotrebu. Daje postojan efekt bistrine i zaglađuje ten. Cica kompleks (Centella asiatica) Jabuka azijatska umiruje i pospešuje regeneraciju kože. Smanjuje upale i crvenilo zahvaljujući sastojcima poput asiaticosida. Jača zaštitnu barijeru i djeluje smirujuće nakon izlaganja suncu ili aktivnim tretmanima. Pojačava regenerativni odgovor strukture kože. Čini kožu mekšom i otpornijom. Hijaluronska kiselina Veže vlagu na različitim nivoima epidermisa, pružajući dugotrajnu hidrataciju. Popunjava sitne linije i vraća zaglađen izgled. Ne masni kožu i brzo se upija. Podržava osećaj glatkosti i sjaja. Doprinosi transparentnosti tena i osećaju elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Anua Niacinamide 5 TXA Brightening Pad su umirujući i posvetljujući jastučići sa 5 % niacinamida i traneksaminskom kiselinom koji ciljano rade na ujednačavanju tena i smanjenju tamnih mrlja. Namenjeni su koži koja želi brzo osveženje, smanjeno crvenilo i dugotrajni sjaj bez agresivnih aktivnih sastojaka.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Anua-Niacinamide-5-TXA-Brightening-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
