INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (672, 11, 'Anua Azelaic 10 Hyaluron Redness Soothing Pad', 'anua-azelaic-10-hyaluron-redness-soothing-pad', 'Ključne prednosti: Umiruje crvenilo i iritaciju: Azelaična kiselina deluje protivupalno i balansira reaktivnu kožu bez perutanja ili peckanja. Dubinski hidrira i omekšava: Tri vrste hijaluronske kiseline deluju na različitim nivoima kože, vraćajući joj elastičnost i sjaj. Jača kožnu barijeru: Kompleks od sedam cica ekstrakata, ceramidi i squalane obnavljaju kožu i čine je otpornijom na svakodnevni stres. Kome su namenjeni? Idealni su za osobe sa osetljivom, suvom ili crvenilom sklonom kožom, uključujući i one koje koriste aktivne sastojke poput retinola, kiselina ili vitamina C. Mogu se koristiti i kao SOS tretman kod reaktivnosti ili nelagodnosti nakon sunca, vetra ili dehidracije. Zašto volimo Anua Azelaic 10 Hyaluron Redness Soothing Pad ? Jastučići su mekani, rastegljivi i natopljeni bogatim umirujućim kompleksom koji trenutno hladi i hidrira kožu. Već nakon prvog korišćenja koža deluje mirnije, manje zategnuto i blistavije. Formulacija je bez mirisa, alkohola i iritativnih dodataka, što ih čini pogodnim i za veoma osetljivu kožu. Mogu se koristiti na specifičnim regijama – kao mini maska za obraze, čelo ili bradu – ili kao kompletna nega za celo lice. Redovnom upotrebom jača se kožna barijera i smanjuje sklonost ka crvenilu, a tekstura kože postaje glađa i hidriranija. Jastučići su praktični za putovanja, jutarnju negu ili kao deo večernje rutine oporavka. Aktivni sastojci Azelaična kiselina (10 %) Moćan protivupalni sastojak koji deluje umirujuće, smanjuje crvenilo i utiče na ujednačavanje tena. Reguliše višak sebuma i može pomoći kod blažih oblika akni, bez agresivnog isušivanja. Dovoljno blag za svakodnevnu upotrebu, ali efikasan čak i kod upalnih procesa. Posebno koristan kod rozaceje, osipa i iritacija izazvanih hemijskim pilingom ili vremenskim uslovima. Hijaluronska kiselina (tri molekulske težine) Deluje na više slojeva kože – veže vlagu na površini, srednjem i dubljem nivou epiderma. Rezultat je dugotrajna hidratacija, osećaj punije kože i smanjenje zatezanja. U kombinaciji sa umirujućim sastojcima dodatno pojačava elastičnost i sjaj. Kompleks cica ekstrakata (7 vrsta) Centella asiatica i njeni derivati pomažu u regeneraciji, umiruju kožu i jačaju prirodnu otpornost. Posebno su korisni kod crvenila, svraba i osetljivosti, jer snižavaju nivo inflamacije. Doprinosi ujednačenijem, zdravijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Anua Azelaic 10 Hyaluron Redness Soothing Pad su umirujući jastučići sa 10 % azelaične kiseline i hijaluronskom kiselinom namenjeni koži sklonoj crvenilu, perutanju i iritacijama. U jednom koraku ublažavaju osećaj neprijatnosti, obnavljaju vlagu i pomažu da koža brže povrati smiren, ujednačen izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Anua-Azelaic-10-Hyaluron-Redness-Soothing-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
