INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (673, 114, 'Medicube TXA Niacinamide Capsule Cream', 'medicube-txa-niacinamide-capsule-cream', 'Ključne prednosti: Ujednačava ten i smanjuje fleke: Traneksaminska kiselina i niacinamid ciljano deluju na pigmentaciju i doprinose svetlijem, bistrijem tenu. Jača barijeru i zadržava vlagu: Hijaluronska kiselina i ceramidi obnavljaju površinski sloj kože i pružaju dugotrajnu hidrataciju. Prilagodljiva tekstura po potrebi kože: Mešanjem kapsula i gela, lako se doziraju bogatstvo i laganost prema sezoni ili tipu kože. Kome je namenjena? Ova krema je namenjena osobama sa hiperpigmentacijama, postupalnim ožiljcima i sivkastim, neujednačenim tenom. Pogodna je i za masnu i za suvu kožu zahvaljujući mogućnosti prilagođavanja gustine kreme. Zašto volimo Medicube TXA Niacinamide Capsule Cream? Kapsulirana formula omogućava da aktivni sastojci ostanu stabilni do trenutka nanošenja, čime se postiže veća efikasnost i manji rizik od iritacije. Prilikom mešanja sa baznim gelom, kapsule se otapaju u bogatu emulziju koja se lako razmazuje i brzo upija. Traneksaminska kiselina deluje na enzime uključene u proizvodnju melanina, dok niacinamid dodatno posvetljuje i umiruje ten. Hidratantna komponenta sa hijaluronskom kiselinom i ceramidima pomaže da se koža oporavi i ostane zaštićena tokom dana. Krema ne ostavlja mastan sloj i ne sadrži parfeme, što je čini pogodnom za osetljivu kožu. Već nakon nekoliko nedelja redovne upotrebe, ten deluje ujednačenije, a koža mekša i vidljivo mirnija. Aktivni sastojci Traneksaminska kiselina : Aktivni sastojak koji inhibira sintezu melanina u koži, čime doprinosi posvetljavanju tamnih fleka i sprečava nastanak novih diskoloracija. Posebno je koristan kod melazme, postupalnih hiperpigmentacija i kože izložene UV stresu. Deluje lokalno, bez izbeljivanja zdravog pigmenta. U ovoj formuli koristi se u čistom i stabilizovanom obliku unutar kapsule. Efekti su vidljivi postepeno, bez naglih reakcija. Pogodna je za svakodnevnu upotrebu i kombinovanje sa ostalim posvetljujućim tretmanima. Niacinamid (5 %) : Višestruko koristan sastojak koji u ovoj koncentraciji deluje na posvetljivanje, regulaciju sebuma i jačanje barijere kože. Smanjuje crvenilo, poboljšava teksturu kože i doprinosi ujednačenijem tenu. Njegova blagotvorna dejstva čine ga pogodnim čak i za osetljivu i reaktivnu kožu. U sinergiji sa traneksaminskom kiselinom pojačava efekat osvetljenja bez iritacije. Pomaže i kod umirivanja kože nakon izlaganja suncu ili upalnih procesa. Daje koži glatkiji, bistriji i zdraviji izgled. Hijaluronska kiselina : Molekul koji vezuje vlagu i pomaže koži da ostane hidrirana tokom dana. Prisutan u više molekulskih težina koje deluju i na površini i u dubljim slojevima kože. Ublažava osećaj zatezanja, popunjava sitne linije i doprinosi elastičnosti. Ne opterećuje kožu, pa se može koristiti i na masnijem tenu. U ovoj kremi pruža osnovnu vlažnost koja prati efekat posvetljivanja. Ključan je za balans između tretmana i komfora. Dodaj u listu želja Dodaj u listu želja', 'Medicube TXA Niacinamide Capsule Crea m je intenzivna posvetljujuća krema koja kombinuje traneksaminsku kiselinu i 5 % niacinamida u kapsulama koje se aktiviraju pri nanošenju. Namenjena je koži sa tamnim flekama, neujednačenim tenom i površinskim ožiljcima, pružajući istovremeno osvetljenje, hidrataciju i obnavljanje barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Medicube-TXA-Niacinamide-Capsule-Cream-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
