INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (675, 11, 'Anua PDRN Hyaluronic Acid 100 Moisturizing Cream', 'anua-pdrn-hyaluronic-acid-100-moisturizing-cream', 'Ključne prednosti: Dubinska hidratacija i podizanje ten: Sinergija PDRN‑a, hijaluronske kiseline i kolagena intenzivno hidrira i daje koži volumen bez masnog filma. Obnavlja zaštitnu barijeru kože: Kombinacija sastojaka pomaže zadržavanje vlage i jača otpornost protiv spoljnog stresa, čineći kožu elastičnijom. Čini ten svetlijim i baršunastim: Redovnom upotrebom, tekstura kože postaje ujednačenija, meka na dodir i prirodno sjajna. Kome je namenjena? Preporučuje se osobama sa normalnom do suvom kožom kojoj nedostaje sjaj, elastičnost i dugotrajna hidracija. Takođe je pogodan za one sa dehidriranom ili stresiranom kožom koja traži regeneraciju i mekoću. Zašto volimo Anua PDRN Hyaluronic Acid 100 Moisturizing Cream? Krema ostavlja prirodno baršunast osećaj, bez opterećenja. PDRN, koji potiče iz lososove DNK, pomaže obnavljanju tkiva i ubrzava regeneraciju ćelija, dok hijaluronska kiselina i kolagen popunjavaju fine linije i daju voluminozan efekt. U kombinaciji, sastojci obnavljaju i hrane kožu, poboljšavaju njenu ceovu barijeru i otpornost na spoljne uticaje. Nakon nanosa, tekstura izgleda vizuelno zaglađena i zdravo, a hidriranost traje satima, čak i ukoliko je u toku naporan dan. Bez masnog sloja, krema je praktična za slojevite rutine i nanosi se lako – idealna kao završni sloj nakon seruma. Aktivni sastojci PDRN (Polydeoxyribonucleotide) Sastojak izveden iz DNK lososa čija je uloga u stimulaciji regeneracije tkiva i obnavljanju ćelijske funkcije. Koristi se i u lekarskim tretmanima za brže zarastanje rana. U ovoj formuli, zahvaljujući tehnološkim kapsulama, prodire u dublje slojeve kože, pomažući u njenom oporavku. Povećava elastičnost i daje osećaj zategnutijeg tena. Doprinosi dugotrajnoj hidrataciji, jer obnavlja barijeru kože. Postepeno uočljivi efekti uključuju meki i zdravi izgled kože. Hijaluronska kiselina (više molekulskih težina) Humektant koji donosi vlagu na površinski i srednji nivo kože. Više molekula deluje paralelno – neki trenutno hidriraju površinu, drugi ostaju unutar dubljih slojeva kože radi dugotrajnosti. Time se postiže osećaj punijeg tena i glatkije teksture. Deluje u sinergiji sa kolagenerima da učvrsti kožu iznutra. Veoma brzo se upija, čineći kremu pogodnom za dnevno nošenje. Kolagen (hidrolizovani) Niz manjih fragmenata proteina koji se bolje apsorbuju i podržavaju strukturu kože. Uz hijaluronsku kiselinu, ojačava tonus i čini kožu „punijom“. Pomaže u smanjenju znakova umora i starenja, dajući elastičnost. Funkcioniše kao „unutrašnji punjač“ kojim se revitalizuje ten. U ovom proizvodu pomaže da rezultati budu dugoročniji. Dodaj u listu želja Dodaj u listu želja', 'Anua PDRN Hyaluronic Acid 100 Moisturizing Cream je lagana krema koja kombinuje PDRN, različite molekulske forme hijaluronske kiseline i kolagen. Na taj način dubinski hrani, &#8220;popunjava&#8221; kožu i stvara takozvani „glass skin“ efekat. Namenjen je osobama sa suvom, dehidriranom ili umornom kožom kojima je potrebna obnova elastičnosti i sjaja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Anua-PDRN-Hyaluronic-Acid-100-Moisturizing-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
