INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (678, 111, 'Mary & May Niacinamide Chaenomeles Sinensis Serum', 'mary-may-niacinamide-chaenomeles-sinensis-serum', 'Ključne prednosti: Posvetljuje ten i ublažava fleke: Niacinamid u koncentraciji od 2 % deluje na ujednačavanje boje kože i ublažavanje hiperpigmentacija. Smiruje i štiti kožu: Ekstrakt kineske dunje bogat je antioksidansima koji umiruju iritacije i jačaju prirodnu barijeru kože. Reguliše višak masnoće: Pomaže u kontroli sebuma, čineći kožu manje sjajnom, a pore vidno suženim. Kome je namenjen? Preporučuje se osobama sa masnom, mešovitom ili osetljivom kožom koja pokazuje znake neujednačenog tena, proširenih pora i crvenila. Prikladan je i za one koji ne podnose jače aktivne sastojke, ali žele postepeno posvetljenje i balans. Zašto volimo Mary & May Niacinamide Chaenomeles Sinensis Serum? Serum se ističe izuzetno čistom i minimalističkom formulom – bez parfema, alkohola ili potencijalno iritirajućih dodataka. Njegova lagana tekstura se brzo upija, bez lepljivog osećaja, i odmah donosi osećaj svežine. Kod redovne upotrebe, ten postaje ujednačeniji, manje sjajan, a koža vizuelno čistija. Efekti niacinamida dolaze postepeno, ali pouzdano – smanjuju se flekice od akni, pore su manje vidljive, a koža izgleda zdravije. Ekstrakt kineske dunje deluje umirujuće, posebno kod crvenila i reaktivnosti, i dodatno štiti kožu od oksidativnog stresa. Zbog blagosti formule, pogodan je i za osobe koje prvi put uvode aktivne sastojke u negu. Aktivni sastojci Niacinamid Stabilni oblik vitamina B3 u koncentraciji od 2 % koji dokazano utiče na regulaciju lučenja sebuma i ujednačavanje tena. Pomaže u posvetljavanju tamnih mrlja i u smanjenju crvenila, posebno kod kože sklone aknama. Takođe jača zaštitnu barijeru kože, čineći je otpornijom na spoljne uticaje. Blagotvorno deluje na pore, čineći ih manje vidljivim. Pogodan je i za osetljivu kožu jer retko izaziva iritacije u ovako blagoj formulaciji. Njegovo dejstvo se pokazuje postepeno, ali je stabilno i bezbedno za svakodnevnu upotrebu. Ekstrakt Chaenomeles Sinensis (kineska dunja) Biljni ekstrakt bogat vitaminom C i antioksidansima koji pomažu u umirivanju iritacija i zaštiti kože od slobodnih radikala. U ovoj formuli čini čak 93 % ukupnog sadržaja, što ga svrstava među dominantne aktivne komponente. Deluje adstringentno, što doprinosi sužavanju pora i ujednačenju površine kože. Posebno je koristan kod crvenila i osetljivosti, jer ima protivupalno dejstvo. Pomaže koži da zadrži vlažnost i doprinosi prirodnom sjaju bez masnog osećaja. Doprinosi dugoročnom zdravlju i elastičnosti kože. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Niacinamide Chaenomeles Sinensis Serum je nežni, vodeni serum kombinuje 2 % niacinamida i visokih 93 % ekstrakta kineske dunje (Chaenomeles Sinensis) kako bi posvetlio ten, umanjio pore i smirio kožu sklonu crvenilu. Namenjen je svima koji žele ujednačen, čist ten i bolju kontrolu sebuma bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Mary-May-Niacinamide-Chaenomeles-Sinensis-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
