INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (679, 114, 'Medicube Collagen Firming Sun Cream', 'medicube-collagen-firming-sun-cream', 'Ključne prednosti: Zaštita i nega u jednom: Visok zaštitni faktor štiti od štetnog UVA i UVB zračenja, dok aktivni sastojci obnavljaju kožu i sprečavaju znakove starenja. Lagana tekstura bez masnog sjaja: Kremasta formula se lako upija, ne ostavlja beli film i prijatna je za svakodnevnu upotrebu. Vidljivo čvršća i hidrirana koža: Kolagen i hijaluronska kiselina pomažu da koža izgleda punije, elastičnije i svežije iz dana u dan. Kome je namenjena? Ova krema je odličan izbor za sve tipove kože, uključujući i osetljivu. Preporučuje se svima koji žele jednostavan, ali efikasan proizvod koji u jednom koraku štiti, hidrira i neguje kožu tokom celog dana. Zašto volimo Medicube Collagen Firming Sun Cream? Collagen Firming Sun Cream kombinuje negu i zaštitu u jednoj elegantnoj formuli. Lagano se nanosi, brzo se upija i ne ostavlja težak ili lepljiv osećaj na licu. Koži pruža trenutan osećaj mekoće i hidratacije, a redovnim korišćenjem doprinosi boljoj elastičnosti i ujednačenijem tenu. Kolagen pomaže u očuvanju čvrstoće kože, dok hijaluronska kiselina zadržava vlagu i sprečava isušivanje. Ceramidi dodatno jačaju kožnu barijeru, čineći je otpornijom na spoljne uticaje. Krema ostavlja blagi, prirodan sjaj, bez masnog finiša – idealna i kao podloga za šminku. Aktivni sastojci Kolagen doprinosi elastičnosti i punoći kože. Pomaže u ublažavanju finih linija i vraća koži mladalački izgled. Hijaluronska kiselina hidrira u dubljim slojevima kože i pomaže da se vlažnost zadrži tokom celog dana. Koža postaje mekša, glađa i vidno osvežena. Ceramidi jačaju zaštitnu funkciju kože, sprečavaju gubitak vlage i pomažu u smanjenju iritacija, crvenila i suvoće. Niacinamid ujednačava ten, smanjuje sitne nesavršenosti i pomaže da koža deluje zdravo i negovano. Dodaj u listu želja Dodaj u listu želja', 'Medicube Collagen Firming Sun Cream je dnevna krema sa zaštitnim faktorom SPF50+ PA++++, obogaćena kolagenom, hijaluronskom kiselinom i ceramidima. Istovremeno štiti kožu od sunca i neguje je, pružajući čvrstinu, vlagu i blistav izgled bez težine i belog traga.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Medicube-Collagen-Firming-Sun-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
