INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (680, 151, 'Shiseido Fino Premium Touch Penetration Essence Hair Oil', 'shiseido-fino-premium-touch-penetration-essence-hair-oil', 'Ključne prednosti: Obnavlja i jača kosu: Ulje prodire u dubinu dlake, jača je iznutra i sprečava lomljenje i suve krajeve. Prirodan sjaj bez masnog osećaja: Kosa dobija zdrav sjaj, ali ostaje lagana i lepršava, bez slepljivanja. Čini kosu glatkom i lakšom za oblikovanje: Pramenovi su mekši, nežniji i lakše se oblikuju, bez naelektrisanja. Kome je namenjeno? Savršeno je za tanku, suvu, tretiranu i beživotnu kosu kojoj treba dodatna nega, ali bez težine. Posebno će prijati onima koji žele da im kosa izgleda sjajno i negovano svaki dan, bez osećaja da su stavili „previše proizvoda“. Zašto volimo Shiseido Fino Premium Touch Penetration Essence Hair Oil? Fino ulje donosi ono što mnoge kose traže – svežinu, elastičnost i sjaj, ali bez da izgubi lagan, prirodan izgled. Već pri prvom korišćenju oseća se kako kosa postaje mekša, svilenkasta i lakša za oblikovanje. Suvi i oštećeni krajevi deluju zaglađeno, a kosa izgleda negovanije i zdravije. Posebna prednost ovog ulja je u tome što ne ostavlja nikakav težak ili mastan trag – idealno je za svakodnevnu upotrebu, bilo da ga nanosiš pre sušenja, posle pranja, ili kao dodatni sjaj kroz dan. Uz blagi, prijatan miris, postaje ritual koji se raduješ da ponoviš. Aktivni sastojci Ulje šafranike omekšava dlaku, neguje suve krajeve i vraća mekoću bez otežavanja. Pomaže da kosa izgleda zdravije i prirodnije. Skvalan je lagan, prirodan hidratant koji štiti kosu od isušivanja i daje joj glatku, elastičnu teksturu bez osećaja masnoće. Vitamin E deluje kao snažna zaštita od spoljašnjih uticaja – vetra, sunca i toplote. Pomaže kosi da ostane jaka, sjajna i otporna. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Fino Premium Touch Penetration Essence Hair Oil je lagano, a moćno ulje koje dubinski prodire u dlaku, obnavlja oštećenja i vraća kosi besprekoran sjaj – bez osećaja masnoće. Tekstura je izuzetno prozračna, ali kosa nakon upotrebe izgleda i oseća se kao „svilena oaza“.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Shiseido-Fino-Premium-Touch-Penetration-Essence-Hair-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
