INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (681, 114, 'Medicube PDRN Pink Collagen Toning Gel Toner Pad', 'medicube-pdrn-pink-collagen-toning-gel-toner-pad', 'Ključne prednosti: Fermentisani crni pirinač (Jinda): bogat antioksidansima i antocijanima, reguliše masnoću, posvetljuje ten i štiti kožu od oksidativnog stresa. Hidratacija i elastičnost: hijaluronska kiselina i betain zadržavaju vlagu u dubini epidermisa, za puniji i nežniji izgled. Blagi piling efekti: AHA kiseline nežno uklanjaju mrtve ćelije, pročišćavaju pore i pripremaju kožu za dalje proizvode. Kome je namenjen? Ovi gel-jastučići su odličan izbor za one koji žele da postignu hidriran, ujednačen i zdrav izgled kože u par jednostavnih koraka. Namenjeni su svim tipovima kože, a posebno korisni su za umornu, dehidriranu i beživotnu kožu kojoj je potreban brz efekat osveženja i zategnutosti. Zašto volimo Medicube PDRN Pink Collagen Toning Gel Toner Pad? Već pri prvom kontaktu s kožom, osetićete prijatnu svežinu i vlagu koju ostavlja gelasta esencija. Lagani, nežni jastučići natopljeni su formulom bogatom PDRN-om i kolagenom koji pomažu koži da se obnovi i povrati volumen i sjaj. Ova formulacija podstiče regeneraciju, hidrira u dubinu i priprema kožu za dalju negu. Efekat je gotovo trenutni – koža postaje glatka, zategnuta i blistava, dok niacinamid deluje na ujednačavanje tena i smanjenje crvenila. Praktičan format omogućava jednostavno korišćenje, bilo kod kuće, na putu ili pred važan događaj. Svaki jastučić je poput male, luksuzne maske za kožu. Aktivni sastojci PDRN (polideoksiribonukleotid iz lososove DNK) je snažan regenerativni agens koji stimuliše obnovu kože, poboljšava elastičnost i pomaže pri zaceljivanju mikroupa. Idealan je za oslabljenu, osetljivu i zrelu kožu jer povećava otpornost i vraća mladalački sjaj. Ultra-niskomolekulski kolagen (200 Da) ima sposobnost da prodre u dublje slojeve kože i zadrži vlagu iznutra, poboljšavajući tonus i elastičnost. Zahvaljujući ovoj formi, efekti su brže vidljivi u odnosu na standardni kolagen. Niacinamid deluje na smanjenje pigmentacija, ujednačavanje tena i poboljšanje zaštitne funkcije kože. Njegovo dejstvo doprinosi blistavijem, zdravijem izgledu lica. Madecassoside (izvučen iz centelle asiatice) umiruje upale, jača barijeru kože i deluje protiv crvenila i iritacija, posebno korisno kod osetljive i reaktivne kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Collagen Toning Gel Toner Pad je tonirajući gel-tonik u obliku nežno natopljenih jastučića, koji kombinuje PDRN (DNK iz lososa) i ultra-niskomolekulski kolagen za intenzivnu hidrataciju, elastičnost i osvežen ton kože. Savršen je za sve koji žele trenutan “glass skin” efekat uz umirujuće i regenerišuće dejstvo.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Medicube-PDRN-Pink-Collagen-Toning-Gel-Toner-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
