INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (682, 78, 'I’m From Mugwort Gel Cleanser', 'i-m-from-mugwort-gel-cleanser', 'Ključne prednosti: Visok procenat mugworta (60 %): intenzivno smiruje iritacije i crvenilo, zahvaljujući antiinflamatornim i antibakterijskim svojstvima. Nežno čišćenje sa formiranjem pene: gel se pretvara u finu penu koja dubinski uklanja nečistoće i sitne čestice okoline bez isušivanja. Vegan i bez iritanasa: formulisan bez sulfata, parabena, silikona i veštačkih mirisa, pogodan i za osetljivu kožu. Kome je namenjen? Idealna je za sve tipove kože, posebno kombinovanu, masnu i sklonu aknama, ali i za one sa osetljivom i dehidriranom kožom kojoj su potrebna dodatna nega i smirenje. Zašto volimo I’m From Mugwort Gel Cleanser? Redovnom upotrebom koža postaje čistija, sjajnija i dugotrajnije hidrirana – bez osećaja zatezanja. Mugwort postiže sinergiju sa neemom i kurkumom, jačajući prirodnu barijeru kože i smanjujući epizode crvenila i iritacije. Blaga pena temeljno uklanja makijaž i SPF, čak i finu prašinu, a ostavlja kožu svežom i blistavom. Čak i pri dvostrukom čišćenju, radiće kao nežna, a efikasna završnica, ulepšavajući jutarnji ritual i osvežavajući kožu pred odmor. Aktivni sastojci Artemisia Princeps (Mugwort) ekstrakt Čini čak 60 % formule i donosi snažan antiinflamatorni i antibakterijski efekat. Sadrži antioksidante, vitamine i flavonoide koji umanjuju crvenilo i ublažavaju akne, istovremeno jačajući prirodni zaštitni sloj kože. Ekstrakt se dobija hladnom metodom, čuvajući optimalan nivo aktivnih supstanci. Primenom reguliše sebum i sprečava blokadu pora, čime dugo traje osećaj svežine i čistoće. Pogodan je i za atopične i osetljive tipove kože. Curcuma longa (kurkuma) ekstrakt Dodaje antioksidativnu moć i pomaže protiv mrlja i hiperpigmentacija. Dodaj u listu želja Dodaj u listu želja', 'I’m From Mugwort Gel Cleanser kombinuje 60 % čistog ekstrakta mugworta sa nežnom gel formulom koja efektno uklanja nečistoće, šminku i SPF, dok istovremeno umiruje, hidrira i balansira sebum.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Mugwort-Gel-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
