INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (683, 78, 'I&#8217;m from Black Rice Toner', 'im-from-black-rice-toner', 'Ključne prednosti: Fermentisani crni pirinač (Jinda): bogat antioksidansima i antocijanima, reguliše masnoću, posvetljuje ten i štiti kožu od oksidativnog stresa. Hidratacija i elastičnost: hijaluronska kiselina i betain zadržavaju vlagu u dubini epidermisa, za puniji i nežniji izgled. Blagi piling efekti: AHA kiseline nežno uklanjaju mrtve ćelije, pročišćavaju pore i pripremaju kožu za dalje proizvode. Kome je namenjen? Idealno za sve tipove kože, naročito masnu, mešovitu i sklona aknama — prija kao osvežavajući ritual posle čišćenja lica i pre seruma. Zašto volimo I&#8217;m from Black Rice Toner? Svakim nanošenjem tonik ostvaruje osećaj svežine i fine baršunaste teksture kože. Fermentisani pirinač prodiruje duboko, obnavlja elastičnost i štiti strukturu kože. Niacinamid dodatno gradi barijeru, ublažava vidljive pore i ujednačava ten. Hidratacija je ravnomerna — bez osećaja mastnog filma, dok AHA nežno otklanja nečistoće skroz do površine. Taj savršeni balans hidratacije i kontrole sebuma čini ga nezaobilaznim u svakodnevnom ritualu. Koža ostaje čista, blistava i spremna za kremu ili serum. Aktivni sastojci Fermentisani crni pirinač Sadrži pojačane koncentracije antocijanina (2,4× više) zahvaljujući 100-dnevnom procesu fermentacije. Antocijanini deluju kao snažni antioksidansi — neutralizuju slobodne radikale, umanjuju upalne procese i doprinose posvetljivanju tena. Osim što smanjuju masnoću, pomažu u jačanju barijere kože, održavajući je otpornijom na spoljne uticaje. Hijaluronska kiselina AMoćan humektant koji privlači i zadržava vlagu iz okoline unutar slojeva epiderma. U ovoj formuli, ona popunjava sitne linije i stvara dugotrajnu mekoću i osećaj punijeg tena. Njena prisutnost u kombinaciji sa fermentisanim pirinčem omogućava brži transfer vlage dublje u kožu, što rezultuje svežinom bez osećaja težine. Niacinamid Vitamin B3 ojačava funkciju zaštitne barijere, smanjuje crvenilo i vidno ujednačava ten. Djeluje na proširene pore i tamne fleke, istovremeno jačajući kožu protiv iritacija. Njegov blagi učinak u sprečavanju začepljenja pora čini tonik pogodnim i za aknasti tip kože. Adenozin & AHA Lagano stimulišu obnovu ćelija poboljšavajući teksturu i zaglađivanje površine kože. Adenozin dodatno doprinosi elastičnosti i smanjenju sitnih bora, dok AHA glatkaju i pripremaju kožu. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Black Rice Toner je luksuzni tonik za lice koji kombinuje fermentisani crni pirinač iz Jinda (100 dana) sa blagim AHA i niacinamidom, pružajući dubinsku hidrataciju, izbalansiran sjaj i suzbijanje viška sebuma.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Im-From-Black-Rice-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
