INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (685, 106, 'Lion Pair Acne Cream W', 'lion-pair-acne-cream-w', 'Ključne prednosti: Brzo delovanje na bubuljice: Izopropil metil-fenol efikasno uništava bakterije odgovorne za akne, ubrzavajući smanjenje upalnih promena već nakon prvih dana primene. Umirujuće delovanje na crvenilo: Glicirizinska kiselina i ekstrakt od sladića umanjuju iritaciju, olakšavaju peckanje i vraćaju ten u ravnotežu. Balansiranje masnoće kože: Formulacija reguliše lučenje sebuma i sprečava pojavu novih nepravilnosti, a pritom ne isušuje kožu niti narušava njenu prirodnu barijeru. Kome je namenjena? Ova krema je idealna za tinejdžere i odrasle koje muči akutne, upalne akne uz prisustvo crvenila i nepravilnosti. Njena pažljivo oblikovana receptura čini je pogodnom i za osetljivu kožu koja ne podnosi agresivne tretmane. Zašto volimo Lion Pair Acne Cream W? Pair Acne Cream W je efektna, ali nežna alternativa agresivnim preparatima za akne. Ugodna tekstura lako se razmazuje, brzo se upija i ostavlja ten svežim bez masnog sjaja. Antibakterijska svojstva ciljano deluju na upalne lezije, dok umirujući sastojci otklanjaju crvenilo i sprečavaju ožiljke. Regulacijom sebuma sprečava ponovnu pojavu bubuljica, a koža ostaje hidrirana i elastična. Ovaj proizvod se lako uklapa u svakodnevnu rutinu, pružajući osećaj čistoće i učvršćujući kožu iz dana u dan. Redovnim korišćenjem, ten postaje uravnoteženiji, bistre linije i dugoročnije otporniji na oscilacije kože. Aktivni sastojci Izopropil metil-fenol Snažan antibakterijski sastojak koji deluje protiv P. acnes bakterija – odgovorne za većinu upalnih akni. Učinak je brz i precizan, a bez iritacija, jer ne remeti lipidni sloj kože. Glicirizinska kiselina (ekstrakt sladića) Prirodni antiinflamator koji umiruje crvenilo, pojačava regeneraciju i smanjuje peckanje. Odličan je saveznik kod akutnih bubuljica i blagih osipa. Salicilna kiselina (niska koncentracija) Nežno pročišćava pore i reguliše sebum, sprečavajući nastanak novih nepravilnosti. Pomaže u održavanju ten-a čistim i glatkijim. Niacinamid Pojačava barijernu funkciju kože i uravnotežava pigmentaciju, pružajući ujednačeniji i blistaviji izgled. Biljni ekstrakti (aloe vera, zelenog čaja) Podržavaju proces smirivanja, hidracije i zaštite kože od spoljnjih iritacija. Dodaj u listu želja Dodaj u listu želja', 'Lion Pair Acne Cream W je napredna krema iz Japana koja ciljano rešava bubuljice i upalne promene na koži, koristeći snažne antibakterijske komponente poput izopropil metil-fenola i glicirizinske kiseline. Formulisana je da nežno umiruje kožu, reguliše sebum i ubrzano pospešuje zaceljivanje bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Lion-Pair-Acne-Cream-W.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
