INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (686, 154, 'Skin1004 Madagascar Centella Retinol 0.2 Boosting Shot Ampoule', 'skin1004-madagascar-centella-retinol-0-2-boosting-shot', 'Ključne prednosti: Efikasna anti-age korekcija bez iritacije: Retinol i retinal deluju u tandemu kako bi smanjili bore, poboljšali elastičnost i ujednačili teksturu, bez uobičajenog osećaja zatezanja ili suvoće. Napredno prodiranje aktivnih sastojaka: Mikro-spikuli pomažu da formula prodre duboko u kožu, čime se pojačava dejstvo i skraćuje vreme do vidljivih rezultata. Umirujuća i zaštitna nega: Visok procenat centelle iz Madagaskara i panthenol obnavljaju i jačaju barijeru, čineći proizvod pogodnim i za osetljivu kožu. Kome je namenjena? Ova ampula je idealna za sve koji žele uvesti retinol u svoju rutinu na kontrolisan, ali delotvoran način – bilo da je reč o prevenciji prvih bora, popravljanju teksture ili povratku čvrstoće koži. Zašto volimo Skin1004 Madagascar Centella Retinol 0.2 Boosting Shot ? Već nakon nekoliko nanošenja, koža postaje primetno glađa, zategnutija i osvežena. Retinol i retinal, pažljivo dozirani u koncentraciji od 0,2%, ciljaju fine linije i gubitak tonusa, dok centella, poznata po svom umirujućem efektu, neutrališe potencijalnu iritaciju. Inovativna struktura mikro-spikula otvara put aktivnim sastojcima do dubljih slojeva kože, bez narušavanja barijere. Panthenol i skvalan dodatno umiruju i hrane, ostavljajući kožu mekom i izbalansiranom. Tekstura ampule je svilenkasta, lako se razmazuje i upija, ostavljajući kožu prijatnom na dodir. Ovo nije običan anti-age proizvod – ovo je luksuzan prvi korak ka transformaciji kože. Aktivni sastojci Retinol i Retinal (0,2%) Deluju kao snažni stimulatori proizvodnje kolagena, obnavljajući strukturu kože iznutra. Retinal, kao direktni prekursor retinoične kiseline, brže donosi rezultate uz manje iritacije, dok retinol deluje sporije ali stabilno, pružajući dugoročne efekte. Madagaskarska Centella Asiatica (50%) Umiruje i obnavlja kožu, delujući antiinflamatorno i ubrzavajući prirodne procese regeneracije. Idealna je za balansiranje potencijalnog crvenila koje može izazvati retinol. Spikule Sitne prirodne iglice koje omogućavaju kontrolisani mikropiling. Nežno otvaraju mikrokanale na površini kože kako bi aktivni sastojci lakše prodrli do dubljih slojeva. Ne uzrokuju oštećenje niti iritaciju, već samo pojačavaju efekat cele rutine. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Retinol 0.2 Boosting Shot ampula kombinuje kliničku efikasnost retinola sa umirujućom snagom centelle, pružajući koži vidljivo poboljšanje čvrstoće, ujednačenosti i teksture. Savršen balans aktivnih sastojaka i nežne isporuke kroz mikro-spikule čini ovaj proizvod idealnim čak i za one koji se prvi put susreću sa retinoidima.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Skin1004-Madagascar-Centella-Retinol-0.2-Boosting-Shot.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
