INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (689, 151, 'Shiseido Tsubaki Premium EX Damage Care & Repair Shampoo', 'shiseido-tsubaki-premium-ex-damage-care-and-repair-shampoo', 'Ključne prednosti: Dubinska regeneracija vlasi: Tsubaki ulje prodire do unutrašnje strukture dlake, obnavljajući oštećenja izazvana tretmanima i toplotom. Mešani učinak zaštite i sjaja: Biljni lipidni kompleksi i amino-kiseline hrane i zaglađuju kutikulu, vraćajući kosi sočan sjaj i svilenkast osećaj. Lagana tekstura, bez osećaja otežanosti: Posebna formula omogućava brzo upijanje, balansira prirodnu masu kose i ostavlja je glatkom i lako upravljivom. Kome je namenjena? Savršen je za sve koji se suočavaju s posledicama čestog feniranja, peglanja, farbanja ili UV izloženosti. Idealno rešenje za kosu kojoj su potrebne jačanje, mekoća i zdrav izgled bez viška proizvoda. Zašto volimo Shiseido Tsubaki Premium EX Damage Care & Repair Shampoo? Već pri prvom korišćenju, kosa dobija osećaj lakoće i obnove – Tsubaki ulje temeljno hrani čak i najugroženije dlake. Formula pročišćava kožu glave nežno, ali efikasno, bez isušivanja. Amino-kiseline stimulišu prirodnu strukturu vlasi, čineći je otpornijom i elastičnijom. S vremenom, kosa postaje vidno mekša, sjajnija i podatnija – uredna i lako oblikovana. Posebno je prijatan osećaj nakon pranja: uz diskretan, ali luksuzan miris, pranja postaje trenutak opuštanja. Kao rezultat, kosa izgleda zdravije, iskustvo uređivanja postaje uživanje, a svakodnevna rutina deluje posvećeno i stručna. Aktivni sastojci Ulje kamelije (Tsubaki) Bogato je omega-9 masnim kiselinama i vitaminima, koje dubinski hrane i štite dlaku. Prodire do srži vlasi, obnavljajući njenu strukturu i sprečavajući lomljenje bez otežavanja kose. Pruža zaštitu od dejstva UV zraka i toplotnih uređaja, zadržavajući prirodan sjaj. Njegova suptilnost čini kosu glatkom, laka je za raščešljavanje i daje zdrav izgled. Amino-kiseline Popunjavaju oštećene delove kutikule, jačajući strukturu kose iznutra i obezbeđujući elastičnost. One štite kosu od budućih oštećenja, sprečavaju lomljenje i pružaju osećaj mekoće. U sinergiji s lipidima, dobijate ravnotežu između oporavka i lakoće. Takva kombinacija daje jaču, uredniju i harmonizovanu strukturu kose. Lipidni kompleksi i prirodni lipidi Hrane i štite spoljašnji sloj dlake, ugladivši površinu i smanjujući statičnost. Pomažu u zadržavanju vlage te sprečavaju dehidraciju nakon pranja. Zajedno sa aminokiselinama, pružaju dugotrajan sjaj i sprečavaju isušivanje. Kosa nakon upotrebe izgleda zdravo, meko i sjajno – spremna za oblikovanje i svakodnevnu negu. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium EX Damage Care & Repair Shampoo je izuzetno regenerativna nega za oštećenu i umornu kosu, osnažena čistim Tsubaki uljem i naprednom tehnologijom za duboko obnavljanje. Ovaj luksuzni šampon vraća snagu, elastičnost i sjaj čak i najdehidridiranim i lomljivim vlasima, pretvarajući rutinu pranja u negujući ritual lepote.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Shiseido-Tsubaki-Premium-EX-Damage-Care-Repair-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
