INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (691, 142, 'Hada Labo Rohto Mentholatum Gokujyun Premium Lotion', 'rohto-mentholatum-hada-labo-gokujyun-premium-lotion', 'Ključne prednosti: Bogata hijaluronska hidratacija: kombinacija laganih i teških molekula hijalurona prodiru duboko u kožu lica, ali i na njenu površinu, “pumpajući” i revitalizujući ten. Obnova barijere i elastičnosti: urea i fermentisani sastojci pomažu zadržavanje vlage i stimuluju prirodnu regeneraciju kože, čineći je snažnijom i čvršćom. Nežno za osetljivu kožu: bez mirisa, boja i alkohola–formulacija je pristupačna i koži sklonoj iritacijama, pa deluje smirujuće i umirujuće. Kome je namenjen? Predstavlja idealan izbor za suv i dehidriran ten koji traži dugotrajnu hidrataciju i zdrav izgled, kao i za mešovitu i osetljivu kožu kojoj je potrebna dodatna vlaga bez masnog osećaja. Zašto volimo Hada Labo Rohto Mentholatum Gokujyun Premium Lotion? Ovaj losion deluje kao serum: gušće teksture, brzo se upija i transformiše kožu iznutra. Hijaluronski kompleksi prodiru do dubljih slojeva, obnavljaju strukturu i vraćaju mladalačku čvrstinu. Urea zadržava vlagu u ćeliji, dok fermentisani HA umiruje i podržava regeneraciju. Rezultat je ten koji odiše zdravljem – pun sjaja, nežan na dodir i dugotrajno nahranjen. Formula je kompaktna i svestrana – pogodna isključivo za lice, uz dodatak prve stanice svakodnevnog rituala nege kože. Aktivni sastojci Hijaluronska kiselina (različite molekularne težine) Garantuje višeslojnu hidrataciju: nano-HA prodire duboko, super‑HA održava vlagu duže, a 3D‑HA stvara vidljivu mrežu površinske zaštite. Ovaj jedinstveni miks “pumpa” kožu, zateže fine linije i vraća elastičnost. Hydroxyethyl urea Ima ključnu ulogu u sprečavanju isparavanja vode, čime održava dugotrajnu mekanost kože i odstranjuje osećaj zatezanja – ten postaje baršunast i hidriran u svakom trenutku. Bifida/Lactococcus ferment Stimuliše obnovu oštećene barijere, umiruje kožu koja se lako crveni i povećava njenu otpornost na spoljašnje faktore – idealan je za kožu koja traži umirujući dodir i dodatnu zaštitu. Dodaj u listu želja Dodaj u listu želja', 'Rohto Mentholatum Hada Labo Gokujyun Premium Lotion intenzivno hidrira kožu lica zahvaljujući kompleksu više vrsta hijaluronskih kiselina i uree, istovremeno jačajući zaštitnu barijeru i ostavljajući ten blistavim, mekim i elastičnim.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Rohto-Mentholatum-Hada Labo-Gokujyun-Premium-Lotion-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
