INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (692, 151, 'Shiseido Tsubaki Premium EX Damage Care & Repair Conditioner', 'shiseido-tsubaki-premium-ex-damage-care-repair-conditioner-treatment', 'Ključne prednosti: Dubinska regeneracija oštećene kose: napredna ion-repair formula prodirući u srž vlakna popravlja oštećenja izazvana farbanjem, peglanjem i UV zračenjem. Glatkoća i sjaj bez osećaja mase: ulje kamelije i squalane hrane i zaglađuju dlaku, ostavljajući je svilenkastom i lakom za raščešljavanje. Podrška elastičnosti i prevencija lomljenja: pčelinje mleko, sojini proteini i amino kiseline jačaju strukturu vlasi i štite je od dalje štete. Kome je namenjena? Regenerator je idealan za osobe sa hemijski tretiranom, toplinski izloženom ili suvom i lomljivom kosom kojoj je potrebna obnova i podatnost. Preporučuje se svima koji žele sjaj, mekoću i lakoću oblikovanja kao rezultat svakodnevne nege. Zašto volimo Shiseido Tsubaki Premium EX Damage Care & Repair Conditioner Treatment? Ovaj regenerator pruža osećaj profesionalne nege već kod prve primene – kosa postaje mekša, sjajnija i lakša za raščešljavanje. Ion-repair tehnologija dopunjava vlagu unutar vlasi, a termički oštećeni delovi se revitalizuju. Ulje kamelije hrani i štiti kutikulu, dok squalane zaključava vlagu i sprečava isušivanje. Pčelinje mleko i sojini proteini doprinose elastičnosti i otpornosti kose, čime se smanjuje lomljenje. Formula formira zaštitni sloj na površini dlake koji održava rizik od oštećenja tokom stilizovanja. Aktivni sastojci Ulje kamelije (Camellia japonica seed oil) Bogato je omega-6 i omega-9 kiselinama koje dubinski hrane i obnavljaju strukturu kose. Lako se upija, ne otežava kosu i čini je svilenom. Štiti od UV zraka i spoljašnje agresije, dok poboljšava elastičnost. Doprinosi sjaju bez masnog traga, idealno za svaki tip kose. Tradicionalno se koristi za negu suve i lomljive kose, što ga čini ključnim u formulišnom profilu ovog proizvoda. Pčelinje mleko i sojini proteini Hranljivi su kompleksi amino kiselina i vitamina koji jačaju strukturu vlasi iznutra. Pomažu u popunjavanju oštećenih mesta, smanjujući ispucale krajeve i lomljenje. Pčelinje mleko regeneriše i stimuliše metabolizam u folikulama, dok sojini proteini povećavaju volumen i gustinu kose. Njihova kombinacija donosi podatnost i vitalnost. Idealni su za kosu izloženu čestim tretmanima i preteranoj stilizaciji. Squalane: Lagani lipid biljnog porekla koji oponaša svojstva prirodnih lipida u kosi. Zaključava vlagu i zatvara kutikulu uredno i nežno. Sprečava frizz i statičnost, ostavljajući kosu glatkom i lakom za raščešljavanje. Ne masti kosu, ali obezbeđuje dugotrajnu zaštitu od spoljašnjih faktora. Njegova struktura pomaže očuvanju vlage i sjaja bez otežavanja vlasi. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium EX Damage Care & Repair Conditioner Treatment je luksuzni regenerator koji obnavlja oštećenu, beživotnu kosu dubinskom negom baziranom na ulju kamelije, pčelinjem mleku i fermentisanim proteinima. Zahvaljujući inovativnoj &#8220;ion-repair&#8221; tehnologiji i bogatoj formuli, kosa postaje svilenkasta, gipka i otpornija već nakon prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Shiseido-Tsubaki-Premium-EX-Damage-Care-Repair-Conditioner-Treatment.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
