INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (693, 151, 'Shiseido Tsubaki Premium Repair Mask – Pink Camellia', 'shiseido-tsubaki-premium-repair-mask', 'Ključne prednosti: Dubinska obnova strukture: Tehnologija visoke penetracije otvara i reparira CMC sloj, omogućavajući aktivnim sastojcima da dospeju do srca vlasi. Hidratacija i sjaj: Kombinacija ulja kamelije, squalana i glicerin obezbeđuje intenzivnu vlagu i prirodni sjaj bez otežavanja vlasi. Zaštita i zatvaranje krajeva: Dualni amino-kiselični kompleks efikasno popravlja ispucale krajeve i pomaže u sprečavanju daljoj šteti. Kome je namenjena? Ova maska je idealna za kosu koja je oslabljena termičkim stilizovanjem, hemijskom obradom ili sklona pucanju i bezvoljnom izgledu. Posebno odgovara suvoj, beživotnoj kosi koja zahteva snažnu negu i obnovu. Zašto volimo Shiseido Tsubaki Premium Repair Mask? Tsubaki Premium EX set pruža iskustvo salonske nege kod kuće. Šampon nežno, ali temeljno čisti, dok regenerator obavija svaku vlas, čineći je podatnom i otpornom na lomljenje. Ulje tsubaki prodire duboko u strukturu dlake i revitalizuje je iznutra, dok squalane i peptidi deluju na površini, zaglađujući kosu i štiteći je od spoljašnjih uticaja. Kosa već nakon prvog korišćenja postaje mekša, sjajnija i lakša za oblikovanje. Miris je prijatan i suptilan, a tekstura proizvoda luksuzna i prijatna pod prstima. Ovaj set se ne zaustavlja samo na estetici – on jača kosu, poboljšava njenu teksturu i dugoročno je obnavlja. Kroz kontinuitet korišćenja, kosa postaje vidno zdravija i elastičnija, bez potrebe za dodatnim tretmanima. Aktivni sastojci Ulje kamelije (Camellia Japonica Seed Oil) Igra ključnu ulogu u zaštiti i regeneraciji – bogato je mononezasićenim masnim kiselinama koje jačaju kutikulu, vraćaju vlagu i daju kosi prirodan sjaj. Brzo se upija i ne opterećuje vlasi, što ga čini idealnim za sve tipove kose. Pčelinje mleko (Royal Jelly Extract) Sadrži aminokiseline i vitamine B kompleksa, podstiče obnavljanje strukture vlasi i poboljšava elastičnost. Deluje kao regenerativni serum koji revitalizuje vitalnost kose. Skvalan Simulira prirodni lipidski sloj kose te zaključava vlagu, sprečavajući isušivanje. Doprinosi mekoći i otpornosti kose, a koristi se u dermokosmetici zbog svoje sposobnosti da obnovi oštećenu barijeru. Sodium Acetylated Hyaluronate Pruža dugotrajnu dubinsku hidraciju – veže vlagu unutar stukture vlasi, što rezultira glađom i manje lomljivom kosom. Soy Protein Prodire u oštećene krajeve, puni ih hranljivim materijama i jača iznutra. Kosa postaje vizuelno deblja i otpornija na dalji stres. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium Repair Mask je luksuzna maska za kosu bogata uljem kamelije, pčelinjim mlekom i proteinima, dizajnirana da u trenutku regeneriše oštećene i suve vlasi, ostavljajući ih svilenkasto mekim i sjajnim. Intenzivno obnavlja strukturu kose, rešavajući konkretne probleme poput ispucalih krajeva i krhkih vlasi.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Shiseido-Tsubaki-Premium-Repair-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
