INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (694, 151, 'Shiseido Tsubaki Premium EX Damage Care & Repair Shampoo & Conditioner Set', 'shiseido-tsubaki-premium-ex-damage-care-repair-set', 'Ključne prednosti: Obnavlja strukturu dlake iznutra: Ulje kamelije prodire u vlakno dlake i popravlja oštećenja uzrokovana hemijskim i toplotnim tretmanima. Pruža glatkoću i sjaj: Regenerator zaglađuje kutikulu, olakšava raščešljavanje i ostavlja kosu svilenkastom i podatnom. Brzi rezultati bez otežavanja: Inovativna tehnologija omogućava trenutnu apsorpciju aktivnih sastojaka, bez osećaja težine ili masnoće. Kome je namenjen? Ovaj set je idealan za sve koji se bore sa posledicama farbanja, feniranja, peglanja ili izloženosti suncu i zagađenju. Posebno je koristan osobama sa suvom, beživotnom i lomljivom kosom kojoj je potrebna nega koja daje i trenutno olakšanje i dugoročnu obnovu. Zašto volimo Shiseido Tsubaki Premium EX Damage Care & Repair Set? Tsubaki Premium EX set pruža iskustvo salonske nege kod kuće. Šampon nežno, ali temeljno čisti, dok regenerator obavija svaku vlas, čineći je podatnom i otpornom na lomljenje. Ulje tsubaki prodire duboko u strukturu dlake i revitalizuje je iznutra, dok squalane i peptidi deluju na površini, zaglađujući kosu i štiteći je od spoljašnjih uticaja. Kosa već nakon prvog korišćenja postaje mekša, sjajnija i lakša za oblikovanje. Miris je prijatan i suptilan, a tekstura proizvoda luksuzna i prijatna pod prstima. Ovaj set se ne zaustavlja samo na estetici – on jača kosu, poboljšava njenu teksturu i dugoročno je obnavlja. Kroz kontinuitet korišćenja, kosa postaje vidno zdravija i elastičnija, bez potrebe za dodatnim tretmanima. Aktivni sastojci Ulje tsubaki (Camellia japonica) Ovo luksuzno biljno ulje bogato je omega-9 masnim kiselinama i vitaminima koji hrane i štite kosu. Njegova snaga leži u sposobnosti da prodre duboko u dlaku i obnovi oštećene slojeve, ostavljajući kosu jačom i elastičnijom. Ne masti, ne otežava i ne opterećuje kosu, već pruža osećaj lakoće i mekoće. Posebno deluje na suvu i beživotnu kosu, kojoj vraća vitalnost i prirodan sjaj. Zahvaljujući antioksidativnim svojstvima, pomaže i u zaštiti kose od UV zračenja i zagađenja. Njegova prisutnost u ovom setu čini svako pranje korakom ka oporavku kose. Skvalane Lagani lipid biljnog porekla koji štiti i omekšava vlas bez masnog traga. On obnavlja zaštitnu barijeru kose i čuva vlagu unutar vlakna, čime se smanjuje suvoća i perutanje. Squalane je posebno koristan kod osetljive i hemijski oštećene kose jer deluje umirujuće i obnavljajuće. Pomaže u vraćanju prirodne gipkosti i sjaja, dok istovremeno štiti od svakodnevnog stresa i toplotnog stilizovanja. Kosa postaje glađa, podatnija i prijatnija na dodir. Njegova diskretna moć transformiše kosu bez efekta težine. Peptidi i amino kiseline Ove komponente deluju kao gradivni blokovi koji popravljaju oštećenu strukturu vlasi i poboljšavaju njenu snagu i elastičnost. Podstiču regeneraciju dlake iznutra, čineći je otpornijom i manje sklonom pucanju. Njihova sinergija sa ostalim sastojcima daje balans između obnove i zaštite. Doprinose očuvanju boje, zdravijem izgledu i boljoj teksturi. Posebno su važni za kosu koja prolazi kroz česte tretmane i koja traži stabilnu, ali nežnu obnovu. Rezultat je snažna, gipka i vizuelno punija kosa. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Tsubaki Premium EX Damage Care & Repair set , koji sadrži šampon i regenerator , osmišljen je za dubinsku negu suve, oštećene i tretirane kose. Zahvaljujući moćnoj kombinaciji ulja tsubaki , peptida i skvalana, ovaj set istovremeno jača, hidrira i vraća kosi izgubljeni sjaj i elastičnost.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Shiseido-Tsubaki-Premium-EX-Damage-Care.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
