INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (695, 111, 'Mary & May Silicone Brush Large', 'mary-may-silicone-brush-large', 'Mary&May silikonska četkica za lice osmišljena je da unese red, preciznost i uživanje u vašu rutinu nege. Zahvaljujući glavi od visokokvalitetnog, nežnog silikona i elegantnoj drvenoj dršci, četkica savršeno leži u ruci i omogućava ravnomerno nanošenje maski bez rasipanja proizvoda i nepotrebnog kontakta sa kožom. Njena fleksibilna i blago zakošena forma prilagođava se svim delovima lica – od šireg čela do nežnih kontura oko nosa i vilice. Materijal je nežan i pogodan za osetljivu kožu, dok sama površina četkice ne upija proizvod, što omogućava potpunu iskorišćenost svakog sloja maske. Osim praktičnosti, ova četkica dodaje osećaj elegancije i reda u vašu rutinu. Pretvara običan čin nanošenja maske u mali kućni ritual – trenutak kada ste posvećeni sebi. Bilo da započinjete dan svežinom ili ga završavate opuštanjem, Mary & May silikonska četkica postaje nezamenjiv deo vaše nege. Jednostavna za održavanje – brzo se čisti toplom vodom i blagim sapunom, spremna za narednu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Silicone Brush Large za negu lica je neophodan alat za svaku rutinu nege! Ova silikonska četkica omogućava ravnomerno i higijensko nanošenje maski, pretvarajući svakodnevnu negu u umirujući, luksuzan ritual.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Mary-May-Silicone-Brush-Large.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
