INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (698, 119, 'Mixsoon Natural Bean Lip Mask Balm', 'mixsoon-natural-bean-lip-mask-balm', 'Ključne prednosti: Dubinska regeneracija: ekstrakt prirodnog pasulja podržava obnovu keratinocita i zaceljivanje ispucalih područja, vraćajući usnama mek i obnovljen izgled. Hidratacija uz zaštitni sloj: biljni voskovi i shea puter formiraju barijeru koja sprečava isparavanje vlage, održavajući usne mekim satima. Lagani, prozračni finiš: bogata formula se lako razmazuje i brzo upija, ne ostavljajući osećaj težine niti sjaja, idealna i za svakodnevnu upotrebu. Kome je namenjena? Savršena je za sve koji imaju osetljive ili suve usne sklone pucanju, posebno u hladnim i suvim uslovima. Pogodna je za osobe koje traže prirodan, ali efikasan balzam bez sintetičkih mirisa i nepotrebnih dodataka. Zašto volimo Mixsoon Natural Bean Lip Mask Balm? Lip Mask Balm kombinuje snagu tradicionalnih biljnih sastojaka i modernih nutrijenata koji hrane kožu usana tokom noćne i dnevne nege. Tekstura više podseća na balzam-masku nego na klasični vosak, što omogućava ravnomerno i prijatno nanošenje. Proteini iz pasulja doprinose elastinu i hidrataciji, umanjujući duboke pukotine i obnavljajući površinu usana. Biljni voskovi i shea puter štite usne i sprečavaju isušivanje, dok ne izazivaju lepljivost. Diskretan minimalistički dizajn tube čini ga jednostavnim i praktičnim za nošenje bilo gde. Sve to čini ovaj balzam odličnim izborom za svakodnevnu rutinu – bez sjaja, ali sa maksimalnom negom. Aktivni sastojci Ekstrakt prirodnog pasulja: Pasulj je izvor proteina, vlakana i antioksidanata koji podržavaju regeneraciju kože usana. Njegovi fitonutrijenti stimulišu obnavljanje ćelija i ublažavaju sitne pukotine. Deluje umirujuće i pospešuje teksturu kože. Prirodnog je porekla i pogodan za vegane. Ne sadrži sintetičke konzervanse ili mirise, pa je bezbedan za osetljivu kožu usana. Biljni voskovi i shea puter: Ovi sastojci stvaraju zaštitni sloj koji sprečava gubitak vlage i štiti usne od spoljnih uticaja. Shea puter hrani i omekšava, dok voskovi održavaju ravnotežu teksture balzama. Formula pruža zaštitu bez osećaja teške filmske barijere. Dugotrajan je saveznik tokom hladnih i vetrovitih dana. Pogodan je i za osetljive osobe – ne iritira ni osjetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Natural Bean Lip Mask Balm je negujući balzam za usne sa ekstraktom pasulja bogatog proteinima i biljnim voskovima, kreiran da intenzivno hidrira i regeneriše ispucale usne. Njegova bogata, ali prozračna tekstura obnavlja osetljivu kožu usana i pruža dugotrajnu udobnost bez lepljenja.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Mixsoon-Natural-Bean-Lip-Mask-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
