INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (701, 6, 'Abib PDRN Collagen Overnight Mask', 'abib-pdrn-collagen-overnight-mask', 'Ključne prednosti: Regenerativna nega tokom noći: PDRN i kolagen sinergijski deluju dok spavate, poboljšavajući tonus kože i podstičući obnavljanje ćelija za osvežen izgled ujutru. Povećanje elastičnosti i sjaja: peptidi i kolagen pomažu u vraćanju punoće, dok niacinamid i panthenol ujednačavaju ton kože i čine je glatkom i sjajnom. Dubinska hidratacija bez osećaja težine: žele tekstura osvežava, hidrira i zaključava vlagu, bez lepljivog filma ili zagušivanja pora. Kome je namenjena? Ova maska je idealna za osobe sa beživotnom, dehidriranom i opuštenom kožom kojoj je potrebna intenzivna noćna regeneracija. Posebno je korisna za one koji primećuju gubitak elastičnosti, neujednačen ton i prve znake starenja. Zašto volimo Abib PDRN Collagen Overnight Mask? PDRN Collagen Overnight Mask je formulisana tako da intenzivno deluje tokom noći – kada je koža najaktivnija u procesu regeneracije. Njena lagana žele struktura odmah osvežava ten, dok visokokoncentrovani aktivni sastojci produbljuju efekat revitalizacije. Koža ujutru izgleda odmorno, napeto i osvetljeno, kao posle dobrog tretmana u salonu. PDRN, derivat DNK iz biljnih izvora, stimuliše prirodno obnavljanje kože i umanjuje vidljive znake starenja. Kolagen niske molekulske mase brzo prodire u dublje slojeve, povećavajući elastičnost, dok kompleks od 9 peptida podstiče sintezu kolagena iznutra. Dodatni benefiti uključuju smanjenje suvoće, ujednačavanje tena i osnaživanje kožne barijere. Aktivni sastojci PDRN biljnog porekla Regenerativna komponenta koja stimuliše obnavljanje ćelija i pomaže u smanjenju finih linija i opuštenosti kože. Potiče sintezu kolagena i ubrzava zarastanje mikrooštećenja, čime vraća zdrav izgled i otpornost kože. Njegovo delovanje naročito je efikasno tokom noćne regeneracije kada se prirodni procesi obnove kože pojačavaju. Kolagen (300 Da) Niskomolekularni kolagen omogućava dublju penetraciju i brže vidljive rezultate. Obnavlja elastičnost, poboljšava čvrstoću kože i daje efekat punoće. Ovaj tip kolagena idealan je za zrelu i umornu kožu kojoj nedostaje tonus i glatkoća. Kompleks 9 peptida Podstiče sintezu kolagena i elastina, poboljšavajući strukturu kože iznutra. Deluje na bore i gubitak elastičnosti, ali i na prevenciju novih znakova starenja. Pruža efekat zatezanja i osvežava površinu kože. Dodaj u listu želja Dodaj u listu želja', 'Abib PDRN Collagen Overnight Mask je noćna gel maska formulisana za revitalizaciju kože tokom sna, s ciljem da povrati elastičnost, čvrstinu i prirodan sjaj. Snažni sastojci poput biljnih PDRN jedinjenja, kolagena niske molekulske mase i peptidnog kompleksa deluju dubinski kako bi koža bila zategnutija, hidrirana i blistava ujutru.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Abib-PDRN-Collagen-Overnight-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
