INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (702, 40, 'Cosrx BHA Blackhead Power Liquid', 'cosrx-bha-blackhead-power-liquid', 'Ključne prednosti: Dubinsko čišćenje pora: BHA (betain salicilat) prodire kroz slojeve sebuma i eliminiše nečistoće iznutra, čime efikasno uklanja i sprečava nastanak mitisera i zapušenih pora. Smanjenje nepravilnosti i postupalnih tragova: zahvaljujući niacinamidu i umirujućim biljnim sastojcima, ten postaje svetliji, a tragovi od bubuljica postupno blede. Regulacija masnoće bez isušivanja: lagana formulacija balansira proizvodnju sebuma i istovremeno hidrira, ostavljajući kožu čistom, ali ne zategnutom. Kome je namenjen? Preporučuje se osobama s masnom, mešovitom i problematičnom kožom sklonom miteserima, aknama i proširenim porama. Pogodan je i za osetljivu kožu koja traži efikasnu eksfolijaciju bez rizika od crvenila i peckanja. Zašto volimo Cosrx BHA Blackhead Power Liquid? Već nakon nekoliko nedelja redovne upotrebe, tekstura kože postaje glađa, a pore vizuelno manje. BHA u obliku betain salicilata deluje nežnije od klasične salicilne kiseline, ali s jednakim efektom dubinskog čišćenja. Formula s 67,8% vode kore vrbe dodatno pomaže u umirivanju upala i smanjenju crvenila. Niacinamid osvetljava ten i ujednačava ton kože, dok betain i pantenol obezbeđuju potrebnu hidrataciju. Proizvod nije lepljiv, brzo se upija i odlično se uklapa u večernju rutinu nege. Redovna upotreba pomaže u prevenciji novih nepravilnosti i održava kožu čistom i uravnoteženom. Aktivni sastojci Betain salicilat (4%) Derivat salicilne kiseline rastvorljiv u ulju, deluje unutar pora gde razgrađuje višak sebuma i mrtve ćelije. Za razliku od klasične salicilne kiseline, betain salicilat je blaži, ali jednako efikasan, čime pruža eksfolijaciju bez iritacije i suvoće. Idealan je za osetljivu, ali masnu kožu. Salix Alba (Willow Bark) voda (67,8%) Prirodni izvor salicilata, deluje protivupalno i umirujuće. Pomaže u ublažavanju crvenila i sprečava prekomerno lučenje sebuma. Ujedno osvežava kožu i podržava barijernu funkciju kože. Niacinamid (2%) Aktivni oblik vitamina B3, poznat po sposobnosti da ujednači ten, posvetli tragove od akni i poboljša elastičnost kože. Takođe pomaže u kontroli sebuma i smanjenju upala, čineći ga idealnim u borbi protiv nepravilnosti. Dodaj u listu želja Dodaj u listu želja', 'COSRX BHA Blackhead Power Liquid je nežan, ali snažan eksfolijant na bazi betain salicilata koji dubinski čisti pore, uklanja mitisere i balansira lučenje sebuma. Namenjen je onima koji se bore s proširenim porama, nepravilnostima i masnijom T-zonom, a žele glatku, pročišćenu i ujednačenu kožu bez iritacija.', 'https://beauty-health.rs/wp-content/uploads/2025/07/Cosrx-BHA-Blackhead-Power-Liquid.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
