INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (703, 169, 'Uodo Moisturizing Light Foundation for Dry Skin', 'uodo-moisturizing-light-foundation-for-dry-skin', 'Ključne prednosti: Hidratantna i nežna formula: obogaćena sastojcima koji zadržavaju vlagu, podloga neguje kožu i sprečava isušivanje. Prirodno ujednačen ten: lagano prekrivanje vizuelno smanjuje nepravilnosti i pore, ostavljajući kožu glatkom i svežom. Postojana i laka za nadogradnju: ne skuplja se u linijama i ne stvara osećaj maske, već omogućava slojevito nanošenje bez zatezanja. Kome je namenjena? Podloga je idealna za osobe sa suvom, osetljivom ili beživotnom kožom koje traže nežnu, hidratantnu šminku koja neće naglasiti suve delove. Pogodna je i za svakodnevnu upotrebu onima koji preferiraju prirodan izgled i udoban osećaj na licu. Zašto volimo UODO Moisturizing Light Foundation for Dry Skin? Ova podloga se lako stapa s kožom, dajući ujednačen, svilenkast finiš bez osećaja težine. Formulisana sa hidratantnim sastojcima, ona pruža vlagu tokom celog dana, što je posebno važno za suvu i zategnutu kožu. Prekrivanje je blago, ali dovoljno da ublaži crvenilo, diskretne nepravilnosti i umor, dok licu ostavlja prirodan sjaj. Tekstura je tanka, ali ne prozirna, i može se nadograđivati bez stvaranja slojeva ili „cakey“ efekta. Ne naglašava suve delove, ne uvlači se u fine linije i ostaje postojana čak i u uslovima niske vlažnosti ili dužeg nošenja. Nakon nanošenja, koža izgleda osveženo, blistavo i negovano – kao da nosite samo dobru hidratantnu kremu s primesom boje. Aktivni sastojci Glicerin i Butylene Glycol: deluju kao humektanti – privlače i zadržavaju vlagu u koži, čime obezbeđuju osećaj mekoće i hidriranosti tokom dana. Silikonski derivati (Cyclopentasiloxane, Dimethicone): omekšavaju površinu kože, olakšavaju nanošenje i daju baršunasti efekat bez težine. Takođe pomažu da se podloga ravnomerno rasporedi i smanje vidljivost pora. Fermentisani biljni ekstrakti: umiruju kožu, poboljšavaju njen prirodni balans i podstiču regeneraciju. Deluju kao nežni saveznici kože sklonoj dehidrataciji i osetljivosti. Biljna ulja (npr. kalofilum i tuberoza): neguju i štite, bez masnog osećaja. Pomažu u zadržavanju vlage i pružaju koži prirodnu elastičnost i mekoću. Dodaj u listu želja Dodaj u listu želja', 'UODO Moisturizing Light Foundation for Dry Skin je lagana, hidratantna podloga namenjena suvoj i dehidriranoj koži, koja ujednačava ten i daje prirodan, osvežen izgled bez osećaja težine. Zahvaljujući nežnoj teksturi i blagom prekrivanju, koži pruža zdrav sjaj i udobnost tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/06/UODO-Moisturizing-Light-Foundation-for-Dry-Skin.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
