INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (706, 41, 'Coyu 10000 ppm Copper Peptide Ultimate Moisturizing Essence', 'coyu-10000-ppm-copper-peptide-ultimate-moisturizing-essence', 'Ključne prednosti: 10.000 ppm bakarnih peptida: podstiču prirodnu sintezu kolagena i elastina, obnavljajući strukturu kože i smanjujući bore. Napredna nano-kapsulacija: omogućava dubinsku isporuku aktivnih sastojaka bez gubitka efikasnosti, pružajući osećaj svilenkaste hidratacije. Višeslojna hidratacija i posvetljivanje: hijaluronska kiselina i niacinamid zajedno obnavljaju vlagu, ujednačavaju ten i jačaju barijeru kože. Kome je namenjena? Ova esencija idealna je za zrelu, dehidriranu, umornu ili osetljivu kožu kojoj nedostaje čvrstina i prirodan sjaj. Posebno je pogodna za one koji traže efikasan, ali nežan anti-age tretman bez agresivnih sastojaka. Zašto volimo Coyu 10000 ppm Copper Peptide Ultimate Moisturizing Essence? Esencija dolazi u sterilnim ampulama koje čuvaju svežinu i stabilnost formule. Nakon nanošenja, koža momentalno upija teksturu, ostavljajući osećaj mekoće i vidne punoće. Bakarni peptidi ciljano obnavljaju kožu, povećavaju elastičnost i umanjuju fine linije. Višestruki oblici hijaluronske kiseline prodiru u dublje slojeve kože, intenzivno je hidriraju i čine je gipkom. Niacinamid dodatno deluje protiv neujednačenog tona, umanjuje vidljivost pora i pruža zdrav sjaj. Rezultati su primetni već nakon sedam dana – koža je čvršća, punija i svežijeg izgleda. Aktivni sastojci GHK-Cu (bakarni tripeptid-1, 10.000 ppm) Snažan aktivni sastojak poznat po stimulaciji sinteze kolagena, elastina i hijalurona. Pomaže u obnavljanju strukture kože, smanjenju bora i poboljšanju elastičnosti, a istovremeno umiruje i jača kožnu barijeru. U ovoj formuli je stabilizovan i enkapsuliran za maksimalnu efikasnost bez iritacija. Daje rezultate slične retinoidima, ali sa znatno manjim rizikom od neželjenih reakcija. Idealno je rešenje za dugoročno poboljšanje čvrstine i mladalačkog izgleda kože. Višeslojna hijaluronska kiselina Kombinuje molekule različitih veličina koje deluju u svim slojevima kože. Manje molekule prodiru duboko i pune kožu iznutra, dok veće formiraju zaštitni film koji sprečava gubitak vlage. Rezultat je dugotrajna hidratacija, ublažene fine linije i koža koja deluje punije i zdravije. Hijaluronska kiselina takođe poboljšava teksturu i čini ten glatkim i osveženim. Niacinamid (vitamin B3) Deluje višestruko: posvetljuje tamne mrlje, smanjuje crvenilo, reguliše lučenje sebuma i jača zaštitnu barijeru kože. Zahvaljujući antioksidativnim svojstvima, umiruje kožu izloženu stresu i pomaže u njenoj obnovi. Njegova prisutnost u formuli doprinosi postizanju ujednačenog, blistavog tena i poboljšanju ukupnog tonusa kože. Kolagen iz meduza Ovaj kolagen sadrži visok procenat prirodnih aminokiselina koje obnavljaju elastičnost i čine kožu mekšom i čvršćom. Njegovo prisustvo u sinergiji s peptidima i hijaluronom pomaže u revitalizaciji i dugotrajnom zadržavanju vlage. Posebno deluje na regijama gde je koža sklona opuštanju i borama. Dodaj u listu želja Dodaj u listu želja', 'Coyu 10000 ppm Copper Peptide Ultimate Moisturizing Essence je visokoefikasna japanska esencija u ampulama, obogaćena nanokapsuliranim bakarnim peptidima, hijaluronskom kiselinom i niacinamidom, koja hidrira, zateže i revitalizuje kožu. Namenjena je svima koji žele vidljive anti-age efekte bez iritacija i invazivnih tretmana.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Coyu-10000-ppm-Copper-Peptide-Ultimate-Moisturizing-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
