INSERT INTO inventory (id, product_variant_id, store_location_id, quantity, created_at, updated_at) VALUES (2133, 711, 3, 12, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (712, 110, 'Marshique Wrinkle Repair Hydrogel Eye Patch', 'marshique-wrinkle-repair-hydrogel-eye-patch', 'Ključne prednosti: Snažna hidratacija i zatezanje: Kolagen i hijaluron popunjavaju i omekšavaju tanku kožu ispod očiju, redukujući bore već nakon jednog tretmana. Čvrsto prijanjanje bez klizanja: elastični hidrogel se savršeno prilagođava konturama lica, ostajući na mestu i tokom spavanja i omogućavajući aktivnim sastojcima da deluju 30+ minuta. Niacinamid i kofein za osveženje: uz antioksidativna i tonirajuća svojstva, smanjuju podočnjake, natečenost i umiruju kapilare – ten oko očiju postaje svetliji i svežiji. Kome je namenjen? Ovaj proizvodje prava prilika za sve koji žele instant osveženje, zauzeti su i nemaju vremena za maske koje cure ili zahtevaju ležeći tretman. Posebno je koristan za one sa tankom, naboranom kožom oko očiju, koja pokazuje prve znake starenja ili jutarnju otečenost. Zašto volimo Marshique Wrinkle Repair Hydrogel Eye Patch? Flasteri deluju kao mini spa tretman: prianjaju uz kožu i ostaju na mestu zahvaljujući svojoj strukturi, dopuštajući da aktivni sastojci deluju dubinski. Kolagen i hijaluronski derivati “popunjavaju” fine linije dok ih navlažuju, a niacinamid i kofein pojačavaju mikro‑cirkulaciju i smanjuju tamne podočnjake. U isto vreme, adenosin i antioksidansi revitalizuju i podmlađuju regiju oko očiju. Nakon samo 30 minuta, koža deluje zategnutije, ten je osvežen, a izgled odmorniji – čak moguće i nakon aljkavog jutra. Korisnici ističu da patch ne klizi ni ako ga nosite dok obavljate kućne poslove ili pre spavanja . Redovnom upotrebom, područje oko očiju postaje čvršće i spretnije se bori protiv bora i umora. Aktivni sastojci Hidrolizovani kolagen Ovi proteinski sastojci deluju dubinski, popunjavaju fine linije i povećavaju elastičnost. Njihova mala molekulska struktura omogućava lako prodiranje u kožu, pružajući osećaj zategnutosti i glatkoće već posle prvog tretmana. Kombinujući se sa hidrogel matricom, daju dugotrajan efekat baršunaste kože. Formula omogućava trenutni „skin lift“ finish bez crvenila ili naprezanja. Idealni su za nežnu zonu oko očiju i tretman bora smejalica. Prirodan osećaj koji ostavljaju zadovoljava kao instant korekciju i osveženje. Sodium Hyaluronate Crosspolymer & Sodium Hyaluronate Popularni humektanti koji vežu vlagu duboko u kožu, čineći je puniom i gipkijom. Kriopolimerska verzija održava hijaluronski efekat i pruža blagi filler-like osećaj. Smiruju suvu i tanku kožu, ostavljajući je mekom i hidriranom. Njihove molekule polako oslobađaju vlagu tokom noći, pružajući dugovečnost efekta. U kombinaciji sa kolagenom, pružaju sinergiju hidratacije i zatezanja. Efekat je mekša, elastičnija i vidno negovana koža oko očiju. Niacinamid Vitamin B3 koji izjednačava ten, redukuje crvenilo i podočnjake i štiti barijeru kože. Njegovo antioksidativno dejstvo jača otpornost kože na stres i umor. U ovoj formuli pomaže u brzoj obnovi površine, čime područje oko očiju izgleda sveže i odmorno. Često se ističe kao bezbedan i efikasan sastojak za svakodnevnu upotrebu, čak i na osetljivoj koži. Povećava elastičnost kože i suptilno podmlađuje regiju. Njegova prisutnost garantuje vidljiv „brightening“ efekat posle 30+ minuta nošenja patcha. Kofein Podstiče cirkulaciju, smanjuje otečenost i pruža trenutni “wake-up” efekat. Deluje brzo, a koža ispod očiju postaje napetija i svežija. Pogodan je za jutarnje tretmane kada treba brzo osveženje. Njegova kombinacija sa niacinamidom dodatno pojačava osvetljenje tamnijih delova. Mnogi korisnici navode smanjenje natečenosti već posle faze nošenja patcha. Idealna je podrška za dan ispunjen aktivnostima i umoru lica. Adenozin Peptid koji stimuliše sintezu kolagena i elastičnih vlakana. Deluje zatezno i podmlađujuće, smanjujući vidljivost izraženih bora. Klinički je dokazano da poboljšava čvrstinu kože i dugoročno doprinosi glatkoj teksturi. U kombinaciji sa kolagenom i hijaluronom, jača regenerative mehanizme kože. Pogodan je za upotrebu u zoni oko očiju, g', 'Marshique Wrinkle Repair Hydrogel Eye Patch je hidrogel flaster bogat kolagenom, hijaluronom, niacinamidom i kofeinom, dizajniran da osveži i zategne područje oko očiju. Njegova elastična, “skin‑like” tekstura prijanja uz kožu, tako da ostaje na mestu čak i tokom noćnog korišćenja, a daje trenutno umirenje i vidno smanjenje sitnih bora i natečenosti.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Marshique-Wrinkle-Repair-Hydrogel-Eye-Patch.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
