INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (714, 164, 'Tirtir Hydro UV Shield Sunscreen', 'tirtir-hydro-uv-shield-sunscreen', 'Ključne prednosti: SPF 50+ PA++++ zaštita: hibridni filteri (homosalate, octocrylene, avobenzone i drugi) efikasno štite od UVA i UVB zraka, sprečavajući ožiljke, fotostarenje i hiperpigmentacije. Trostruka hijaluronska kiselina + fitokolagen: dubinski hidrira, popunjava i održava kožu elastičnom, ostavljajući je punom i baršunastom. Aloe vera i pantenol: umiruju, smanjuju crvenilo i regenerišu, posebno korisno za osetljivu i sklona iritacijama kožu. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože – posebno masnu, mešovitu, dehidriranu ili osetljivu – koji traže snažnu UV zaštitu bez težine i bele maske. Pogodan je za svakodnevnu upotrebu ispod šminke ili kao završni korak jutarnje rutine zbog glatkog, nevidljivog efekta. Zašto volimo TIRTIR Hydro UV Shield Sunscreen? Drugačiji od klasičnih krema, ova formula se oseća lagano kao voda i brzo se upija, ostavljajući kožu svilenkasto glatkom. Dok UV filteri čine zaštitni zid, hijaluron i fitokolagen hrane i popunjavaju kožu, održavajući vlagu tokom celog dana. Aloe i pantenol rade u pozadini, umirujući čak i osetljive delove i smanjujući crvenilo nakon izlaganja suncu. Ne ostavlja trag, što ga čini savršenim za sve boje i tipove kože – čak i tamnije, bez bele maske ili tragova. Tekstura je osvežavajuća, idealna za tople dane i aktivan život, a ipak dovoljno nežna za svakodnevno korišćenje. Korisnici ističu da je poput hidratantnog seruma s UV zaštitom – koža izgleda blistavo i zdravo. Aktivni sastojci Trostruka hijaluronska kiselina (HA, hidroizolovana HA, natrijum hijaluronat) Obezbeđuje višeslojnu hidrataciju – mala molekulska težina prodire duboko, dok veće molekule zadržavaju vlagu na površini. Ovaj moćan trio brzo popunjava fine linije, učvršćuje kožu i stvara dugotrajan osećaj vlage. Formula je posebno osmišljena za svakodnevnu upotrebu, pružajući dugotrajnu vlažnost i mekoću, čak i u suvim uslovima. Fitokolagen (iz gljiva) Podržava elastičnost kože i utiče na njenu čvrstinu. On nadopunjuje hijaluronsku mrežu, pomažući da koža izgleda punije i svežije. U kombinaciji sa HA, fitokolagen omekšava teksturu, a dugoročno usporava pojavu sitnih bora. Njegovo prirodno poreklo iz biljaka ga čini pogodnim za osetljivu kožu. Redovnim korišćenjem koža postaje gipkija i vidno revitalizovana. Aloe Barbadensis Leaf Extract Savetlost i osveženje unosi u formulu kroz umirujući i protivupalni efekat. Bogat je vitaminima i antioksidansima koji sprečavaju iritacije i ubrzavaju regeneraciju. Pomaže u smanjenju crvenila i osećaja zatezanja. U kombinaciji sa pantenolom, čini proizvod izuzetno blag i prijatan. Često se navodi kao ključna komponenta kod onih koji imaju lako reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Hydro UV Shield Sunscreen je lagana SPF 50+ PA++++ vodena krem‑gel formula, obogaćena trostrukom hijaluronskom kiselinom, fitokolagenom i aloa verom, koja pouzdano štiti od UV zraka i dubinski hidrira kožu. Bezbeležna i ne lepljiva, pruža glatku i osveženu kožu – kao da koristiš krema-serum za svakodnevnu zaštitu.', 'https://beauty-health.rs/wp-content/uploads/2025/06/TIRTIR Hydro UV Shield Sunscreen-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
