INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (715, 104, 'Laneige Lip Glowy Balm', 'laneige-lip-glowy-balm', 'Ključne prednosti: Dubinska hidratacija biljnim puterima: kombinacija shea i murumuru putera obezbeđuje trenutan osećaj meke, nahranjene kože usana bez teškog sloja. Ogodan gel-tekstura i suptilan sjaj: formula se lako nanosi, brzo upija i stvara glossy finiš – bez osećaja lepljivosti ni neugodnih tragova. Lagan miris i diskretan ton: balzam dolazi u različitim blagim mirisima voća i ukusima, koji naglašavaju prirodnu boju usana, bez agresivnih tonova. Kome je namenjen? Odličan je za sve tipove usana, posebno one koje su suve, ispucale ili traže dnevnu negu bez komplikacija. Idealna opcija za osobe koje preferiraju prirodan sjaj i laganu zaštitu, posebno u toplijim ili aktivnim danima. Zašto volimo Laneige Lip Glowy Balm? Ovaj balzam ostavlja usne glatkima i osveženima, s osećajem kao da ste upravo naneli hidratantni gel. Njegovne glatka tekstura čini ga savršenim osloncem ispod karmina ili kao samostalni „moisture boost“. Sadrži antioksidanse iz voćnih ekstrakata koji dodatno štite i neguju kožu. Njegove voćne varijante – poput berry ili grapefruit – pružaju divan, suptilan miris bez jakih parfema. Balzam nije lepljiv, pa je udoban za nošenje tokom rada, vožnje ili dragih trenutaka. Većina korisnica primećuje da usne izgledaju punije i blaže sjajne, mada je potrebna češća aplikacija nakon jela ili pića. Redovnim nanošenjem kože usana ostaju hidrirane i meke, ostavljajući prirodan sjaj bez ostećenja ili sušenja. Aktivni sastojci Shea puter (Butyrospermum Parkii Butter) je bogat izvor masnih kiselina i vitamina A, koji intenzivno hrane iskorišćenu i ispucalu kožu usana. Stvara zaštitnu barijeru koja zadržava vlagu i sprečava isušivanje, dok vitamin A pomaže u regeneraciji površinskih slojeva. Pruža dugotrajnu elastičnost, čineći usne vidno zdravijim. U ovoj formuli podržava glossy finiš bez osećaja težine. Redovno korišćenje smanjuje perutanje i hrapavost. Murumuru puter (Astrocaryum Murumuru Seed Butter) prozračan je i brzoupijajući emolijent, bogat esencijalnim masnim kiselinama. On dopunjava shea puter u pružanju glatkoće, ali sa manje težine. Efikasno obnavlja barijeru i sprečava trans-epidermalni gubitak vode. Osigurava osjećaj hidratacije bez lepljivosti. U kombinaciji sa drugim puterima daje prirodnu baršunastu teksturu usnama. Voćni ekstrakti (malina, borovnica, brusnica, jagoda itd.) su izvor antioksidanata i laganog mirisa koji hranljivo deluje na usne. Oni pružaju zaštitu od slobodnih radikala i potpomažu regeneraciju oštećene kože. Tanični komponente u malini doprinose blagom posvetljavanju i toniziranju usana. Redovno korišćenje podržava zdrav i sjajan izgled. Ekstrakti voća čine formulu prijatnijom za korišćenje tokom celog dana. Dodaj u listu želja Dodaj u listu želja', 'Laneige Lip Glowy Balm je lagani, sjajni balzam obogaćen shea i murumuru puterima, koji bez lepljenja hidrira i čini usne glatkima. Pruža suptilan sjaj i boju – idealan za one koji žele prirodan, negovan izgled tokom dana.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Laneige-Lip-Glowy-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
