INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (718, 116, 'Meditime Botalinum Ampoule', 'meditime-botalinum-ampoule', 'Ključne prednosti: 50 % hijaluronske kiseline: intenzivno hidrira i popunjava kožu, povećavajući elastičnost i smanjujući osećaj zategnutosti. Peptidi s botulinum‑efektom: blokiraju kontrakcije sitnih mišića lica (Acetyl Hexapeptide‑8 i botulinum‑peptidi), ublažavajući mimičke bore i zatežući oval lica. Niacinamid + adenozin + centella: toniraju, umiruju i regenerišu, posvetljujući kožu i jačajući barijeru uz antioksidativno dejstvo. Kome je namenjen? Predviđen je za sve tipove kože koji pokazuju znakove starenja – fine linije, gubitak čvrstine i neujednačen ten. Idealna je za one koji žele profesionalno anti‑age dejstvo bez agresivnih tretmana. Zašto volimo Meditime Botalinum Ampoule? Ova ampula deluje kao koktel za mladolikost – hijaluronska kiselina momentalno hidrira slojeve kože, dok peptidi i botulinum‑peptidi ciljano opuštaju fine mimicke bore. Niacinamid i adenozin podržavaju obnavljanje ćelija, posvećuju ten i deluju anti‑upalno, dok centella i ekstrakti biljaka umiruju i štite od oksidativnog stresa. Redovnim nanošenjem postaje vidljivo zaglađene teksture, poboljšan tonus i zategnutiji kontur lica, sve bez iritacija. Formula bez vode (&#8220;purified water 0 %&#8221;) bogata je aktivnim supstancama što povećava koncentraciju efektnog delovanja. Aktivni sastojci Sodium Hyaluronate (≈50 %) deluje kao humektant velike moći vezivanja vode, popunjava bore iznutra i intenzivno hidrira kožu. Stabilniji je i kompaktniji od obične hijaluronske kiseline, omogućavajući dublje prodiranje u epiderm. Zahvaljujući 50 % koncentraciji, već nakon prvog nanošenja koža postaje nahranjena, elastična i vidno punija. Acetyl Hexapeptide‑8 & Botulinum‑peptidi – poznati kao „botoks‑like“ sastojci, oni ciljano smanjuju kontrakcije mišića povezanih s mimikom lica. Kada se koriste redovno, smanjuju dubinu i broj finih linija, posebno oko očiju i usana. Klinički dokazano deluju preventivno na formiranje novih bora, dajući koži odmoren i zategnut izgled. Niacinamid (≈4 %) jača barijeru kože, povećava sintezu ceramida, reguliše melaninski ciklus i posvećuje ten. Ima i antiinflamatorno dejstvo, smanjuje iritacije i ublažava promene poput akni i crvenila. Adenozin stimuliše ćelijsko obnavljanje i sintezu kolagena, pomažući u smanjivanju „dubokih bora“. Deluje anti‑upalno i regenerativno, što je podržano kliničkim ispitivanjima. Dodaj u listu želja Dodaj u listu želja', 'Meditime Botalinum Ampoule je anti‑age serum s visokim procentom hijaluronske kiseline (oko 50 %) i peptidima s botulinum efektom, dizajniran da zagladi bore i zategne kožu. Uz to, sadrži niacinamid, centellu i adenozin – pruža hidrataciju, regeneraciju i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Meditime-Botalinum-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
