INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (720, 36, 'CNP Laboratory Propolis Lipcerin', 'cnp-laboratory-propolis-lipcerin', 'Ključne prednosti: Propolis ekstrakt + manuka med: Prirodni antioksidansi i antibakterijsko dejstvo hrane, umiruju i štite suve usne od pucanja, jačajući njihovu zaštitnu barijeru. Ekstremna hidratacija do 12 sati: Klinički potvrđeno zadržava vlagu u usnama tokom cele noći, ostavljajući ih dugotrajno mekim i zaštićenim. PHA i peptidi za blagi piling i elastičnost: Uklanjaju mrtve ćelije, dok peptidi i ceramidi regenerišu teksturu i čine usne punijim i glatkijim. Kome je namenjen? Namenjen je osobama sa veoma suvim, ispucalim i osetljivim usnama koje su sklone perutanju i zatezanju. Pogodan je za svakodnevnu negu, kako noću tako i kao podloga pre nanošenja karmina. Zašto volimo CNP Laboratory Propolis Lipcerin? Lipcerin dolazi u praktičnom pakovanju sa twist-dozatorom, iz kog izlazi gelasta, bogata tekstura spremna za direktnu upotrebu. Formira zaštitni sloj koji sprečava isušivanje, dok PHA kiseline blago uklanjaju mrtve ćelije bez nadražaja. Peptidi, ceramidi i skvalan dubinski hrane usne i povećavaju njihovu elastičnost. Tekstura podseća na med – prijatna, nelepljiva i pogodna za noćnu upotrebu. Usne nakon buđenja ostaju hidrirane, meke i glatke, a redovnom upotrebom postaju otpornije na spoljne uticaje. Iako nije izuzetno teška kao neke maske, dovoljno je bogata da pruži celonoćnu negu. Mnogi korisnici je koriste i tokom dana za dodatnu negu i zaštitu. Aktivni sastojci Propolis ekstrakt ima snažno antioksidativno i antibakterijsko dejstvo. Doprinosi regeneraciji ispucale kože i formira zaštitnu barijeru koja sprečava gubitak vlage. U formulaciji je zastupljen u optimalnoj koncentraciji koja obezbeđuje efikasnost bez iritacija. Posebno je koristan kod čestih iritacija i ranica na usnama. Njegovo dejstvo je potvrđeno i tradicionalno korišćeno za obnavljanje kože. U ovom proizvodu omogućava brži oporavak oštećenih usana. Manuka med bogat je enzimima, vitaminima i antioksidansima koji dubinski hrane i umiruju. Deluje kao prirodni emolijent, pomaže u zaceljivanju i omekšavanju kože. Njegova prijatna, blaga aroma doprinosi ugodnosti prilikom korišćenja. Pogodan je za svakodnevnu primenu, čak i kod osetljivih korisnika. U kombinaciji sa propolisom pruža snažan efekat obnavljanja. Zaslužan je za efekat glatkih, nahranjenih usana bez lepljenja. Dodaj u listu želja Dodaj u listu želja', 'CNP Laboratory Propolis Lipcerin je hibrid između balzama i maske za usne, formulisan s propolisom i manuka medom, koji pruža intenzivnu, do 12-časovnu hidrataciju i umirivanje bez masnog osećaja. Idealno obnavlja ispucalu i suhu kožu usana, čineći ih mekim, zaglađenim i elastičnim.', 'https://beauty-health.rs/wp-content/uploads/2025/06/FruityCNPLaboratoryPropolisLipcerin15ml.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
