INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (721, 88, 'Judydoll 3D Curling Eyelash Iron Mascara', 'judydoll-3d-curling-eyelash-iron-mascara', 'Ključne prednosti: Metalni aplikator (curling-iron dizajn): Precizno uvija trepavice tokom nanošenja, eliminirajući potrebu za klasičnim uvijačem i produžujući rezultat. Dugotrajna formula: Sadrži vlakna koja produžavaju i definisu trepavice, zadržavajući volumen i boju i do 9 sati, čak i tokom suza ili vlažnih uslova. Vodootporna i otporna na razmazivanje: Brojni korisnici navode da ostaje netaknuta čitavog dana bez razmazivanja, mrvljenja ili klizanja, čak i u zahtevnim uslovima. Kome je namenjena? Savršen je za osobe sa pravim ili spuštenim trepavicama koje traže dugotrajno uvijanje bez dodatnih koraka. Posebno pogodan za one koji žele prirodniji izgled s produženim efektom i otpornošću na vlagu, kao što su studenti, sportisti ili zaposlene osobe. Zašto volimo Judydoll 3D Curling Eyelash Iron Mascara? Ova maskara proizvodi impresivan “lash lift” efekat zahvaljujući metalnom aplikatoru koji uvija i oblikuje trepavice tokom nanošenja. Formula sa vlaknima prirodno produžava i definiše svaki pramen, bez zgrudnjavanja ni nakon višeslojnih slojeva. Vodootpornost i postojanost omogućavaju da izgled ostane netaknut čak i pri suzama ili znoju. Aktivni sastojci Pantenol : prisutan je kao glavni hidratantni sastojak, omekšava trepavice i poboljšava njihovu elastičnost bez dodavanja težine. Njegova svojstva pomažu u jačanju i smanjuju lomljenje. Waxes i voskovi (npr. microcrystalline wax, ceraesin): oni formiraju postojan film oko trepavica, omogućavajući dugotrajan i otporan izgled bez razmazivanja. Sintetičke smole i silikoni (trimethylsiloxysilicate): doprinose formuli koja je dugotrajna, vodootporna i otporna na tragove, održavajući definiciju i oblik tokom dana. Dodaj u listu želja Dodaj u listu želja', 'Judydoll 3D Curling Eyelash Iron Mascara koristi inovativni metalni aplikator i formulu koja uvija i definiše trepavice bez potrebe za uvijačem. Idealan je za sve koji žele da postignu efekt “otvorenih očiju” sa vodootpornim, postojanim rezultatima tokom čitavog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Judydoll-3D-Curling-Eyelash-Iron-Mascara.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
