INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (722, 57, 'Eqqualberry Vitamin Illuminating Serum', 'eqqualberry-vitamin-illuminating-serum', 'Ključne prednosti: 40 % Acerola voda – moćan vitamin C izvor: bogata antioksidansima koji smanjuju pigmentacijske mrlje i štite od slobodnih radikala, dok je dovoljno blaga za osetljivu kožu . Niacinamid 4 % + Arbutin 2 % za intenzivno posvetljivanje: smanjuju nastanak melanina i ujednačuju ten kroz višefaznu tehnologiju kontrole pigmentacije. 8 tipova hijaluronske kiseline + pantenol: obezbeđuju višeslojnu hidrataciju i jačaju barijeru, ostavljajući kožu gipkom i otporom na spoljašnje uticaje. Kome je namenjen? Serum je namenjen svim tipovima kože, a naročito onima sa nepravilnostima tona, hiperpigmentacijom i prvih znaka starenja. Idealna je opcija za one koji traže učinkovit, ali neagresivan proizvod sa posvetljujućim i antioksidativnim dejstvom. Zašto volimo EQQUALBERRY Vitamin Illuminating Serum? Ovaj vitamin C serum inovativno kombinuje visok deo acerola ekstrakta – 40 %! – koji je prepoznat po superiornim antioksidativnim sposobnostima u odnosu na limun. Njegov snažan potencijal posvetljivanja podržavaju niacinamid i arbutin koji sprečavaju stvaranje i migraciju melanina, tretirajući postojeće mrlje i sprečavajući nove. Peptidi (13 vrsta) deluju kao anti-age komponenta, jačajući strukturu kože i sprečavajući pojavu finih linija. Dodatak ceramida i hijalurona omogućava dubinsku hidrataciju i zaštitu barijere, dok pantenol umiruje i neguje kožu. Aktivni sastojci Acerola Fruit Water (40 %) dolazi iz acerola trešnje, poznate kao kraljica vitamina C. Ova koncentracija obezbeđuje antioksidativnu zaštitu i posvetljivanje bez rizika iritacije. Sadrži mnogo više vitamina C nego limun – čak 8 puta jači izvor – što je potkrepljeno podacima brenda. Niacinamid 4 % (vitamin B3) reguliše sintezu melanina, jača barijeru kože i ima protuupalno dejstvo. Klinički dokazano smanjuje tamne mrlje, bledi pore i balansira ten. Arbutin 2 % inhibira enzim tirozinazu, čime usporava nastanak melanin pigmentacije. Deluje u sinergiji sa niacinamidom i acerola za celovitu negu pigmentacije, blage i neiritantne prirode. Traneksamična kiselina & Ferulična kiselina dopunjuju posvetljivanje i antioksidaciju – traneksamična kiselina deluje umirujuće i posvetljujuće, dok ferulična stabilizuje vitamin C i štiti od UV oštećenja. 8-tipova hijalurona + Panthenol + Ceramide NP čine hijaluronsko-hidrirajuću kompletnu mrežu, koja dubinski hidrirа, popunjava linije i jača strukturu kože. Panthenol smiruje eventualne iritacije i potiče zaceljivanje. Peptidi (13 vrsta) stimulišu proizvodnju kolagena, podstiču obnovu kože i sprečavaju pojavu finih linija i gubitak elastičnosti. Ovaj kompleks pruža anti-age efekat u isto vreme dok posvetljuje i neguje ten. Dodaj u listu želja Dodaj u listu želja', 'EQQUALBERRY Vitamin Illuminating Serum sadrži 40 % acerola vodu, zajedno sa 4 % niacinamida, 2 % arbutinom i peptidima, što snažno posvetljuje ten, smanjuje tamne mrlje i intenzivno hidrira bez iritacija. Ovaj lagani, neljepljivi serum aktivno ujednačava pigmentaciju i daje blistav, zdrav izgled čak i osetljivoj koži.', 'https://beauty-health.rs/wp-content/uploads/2025/06/EQQUALBERRY-Vitamin-Illuminating-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
