INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (723, 104, 'Laneige Lip Sleeping Mask', 'laneige-lip-sleeping-mask', 'Ključne prednosti: Kokosovo + murumuru + shea puter za bogatu hidrataciju: ovi biljni masni sastojci formiraju polu-okluzivni sloj koji zadržava vlagu i sprečava isušivanje usana tokom noći. Berry Fruit Complex + vitamin C: visoki nivo antioksidanata štiti od spoljašnjih oštećenja i podstiče zaglađivanje, dok vitamin C pomaže u neutralisanju slobodnih radikala. Provereni laboratorijski rezultati: studija na 32 žene pokazala je 135 % povećanja hidracije nakon 8 sati i preko 90 % ispitanica potvrdilo mekoću, čvršće i zdravije usne. Kome je namenjen? Ovaj proizvod je idealan za osobe sa suvim, ispucalim ili hrapavim usnama, kao i one koji žele sigurnu i nežnu negu bez osećaja težine. Pogodan je za korišćenje tokom cele godine – naročito tokom hladnih zimskih ili sušnih letnjih uslova. Zašto volimo Laneige Lip Sleeping Mask? Maska za usne Laneige stapa se sa kožom usana i gradi zaštitni sloj koji sprečava gubitak vlage, dok se u pozadini odvija dubinska regeneracija. Antioksidansi iz bobičastog kompleksa i vitamina C štite usne od spoljašnjih faktora, poput vetra i hladnoće, olakšavajući oporavak. Masne komponente – murumuru i shea – obezbeđuju dugotrajnu elastičnost i sprečavaju perutanje, ostavljajući usne baršunastim na dodir. Tekstura nije lepljiva, već pruža luksuzan osećaj, a pogodnost je u tome što maska ostaje neprimetna tokom sna. Može se koristiti i u toku dana kao dodatna zaštita ili deo šminke, dajući blagi sjaj. Redovnom upotrebom usne postaju primetno mekše, zaglađenije i otpornije na spoljne nepogode. https://www.youtube.com/watch?v=GjKAuswKluk&ab_channel=LANEIGEUS Aktivni sastojci Berry Fruit Complex Osnova formule bogata antioksidansima iz voćnih ekstrakata poput bobica aronije i maline. Ovi sastojci deluju na regeneraciju i smanjenje hrapavosti, uz vidno mekšu teksturu usana. Formulacija uključuje višestruke ekstrakte voća koji podstiču blistavost i glatkoću. Kliničkom upotrebom potvrđeno je smanjenje mrtvih ćelija kože za oko 40 % nakon 8 sat Murumuru Seed Butter Potiče iz amazonske palme i predstavlja izuzetno bogat izvor masnih kiselina. Njegova polu-okluzivna svojstva pomažu zadržavanje vlage bez začepljenja pora. Ovaj butter umanjuje osetljivost i pruža dugotrajnu mekoću bilo da je to tokom hladnog ili suvlјeg vremena. Popularan je zbog svoje sposobnosti da obnavlja čak i duboko napucale usne. U kombinaciji sa shea puterom i kokosovim mirisom, stvara prijatan i umirujući noćni tretman. Dokazano je da, uz redovnu noćnu upotrebu, produžava osećaj hidratacije i elastičnosti. Vitamin C (askorbil-glukozid) Deluje kao antioksidans koji štiti usne od UV zračenja i zagađenja. Neutralizuje slobodne radikale, usporavajući oštećenja i starenje kože usana. Pomaže u postizanju ujednačenije i svetlije nijanse usana smanjujući tamne mrlje. Njegova kombinacija sa Berry Complex pojačava zaštitnu i regenerativnu ulogu formule. Stabilna verzija C obezbeđuje efekt bez iritacija. Korisnici često beleže lepši, „sjajniji“ izgled usana već nakon jedne nedelje. Dodaj u listu želja Dodaj u listu želja', 'Laneige Lip Sleeping Mask je intenzivna noćna maska za usne bogata antioksidansima – kombinacija Berry Fruit Complex, murumuru i shea putera, kokosovog ulja i vitamina C duboko hidrira i omekšava usne tokom sna. Njena hranljiva i tekstura bez lepljenja čini usne glatkima, mekim i ujednačenim već nakon jednog nošenja.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Laneige-Lip-Sleeping-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
