INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (725, 154, 'Skin1004 Madagascar Centella Hyalu‑Cica Sleeping Pack', 'skin1004-madagascar-centella-hyalu-cica-sleeping-pack', 'Ključne prednosti: Dubinska hidratacija petostrukom hijaluronskom kiselinom: mala, srednja i velika molekulska težina HA prodire u različite slojeve kože, obezbeđujući dugotrajnu vlažnost i puniji izgled ujutru. Umirujuća formula sa centellom i ceramidima: centella stimuliše regeneraciju i jača kožni zid, a nano-ceramidi obnavljaju barijeru i zadržavaju vlagu. Antioksidativni melatonin i biljni ekstrakti: štite od slobodnih radikala, poboljšavaju tonus tena i pomažu oporavku kože tokom spavanja. Kome je namenjen? Ovaj sleeping pack je idealan za sve koji imaju osetljivu, suvu ili kombinovanu kožu sa tendencijom dehidracije i crvenila. Posebno je koristan osobama koje traže gel‑lagane, nekomedogene formulacije s efektom „glass skin“. Zašto volimo Skin1004 Madagascar Centella Hyalu‑Cica Sleeping Pack? Centella Asiatica znana ﻿ je po sposobnosti da regeneriše kožu, smanjuje iritacije i podržava sintezu kolagena. Kombinujući pet vrsta hijaluronske kiseline, maska obezbeđuje višeslojnu hidrataciju – brzo ublažava osećaj zategnutosti i ostavlja ten blistavim i mekim na dodir. Nano‑ceramidi ciljano „zaključavaju“ vlagu, jačajući prirodnu zaštitu kože. Melatonin deluje kao snažan antioksidans koji pomaže u borbi protiv slobodnih radikala dok spavamo, a biljni ekstrakti (kao što su ekstrakti iz kruške i melona) nežno hlade i osvežavaju. Lagan, osvežavajući gel brzo se upija, ne lepi se, pa možete slobodno koristiti masku i tokom dana kao dodatnu hidrataciju ili spot tretman. Redovnom upotrebom tokom noći, koža dobija ujednačeniji ten, umanjen osećaj zategnutosti i zdraviji balans. Aktivni sastojci Azelaična kiselina (12 %) Centella Asiatica Leaf Water Izuzetan koncentrat (oko 39 %) bogat madekasičnom i aziatikozidima, pokazuje umirujuća, antiupalna i regenerativna dejstva. Podstiče proizvodnju kolagena i ubrzava zaceljivanje oštećenja poput crvenila i sitnih ožiljaka, čime vraća zdravu elastičnost koži. Hijaluronska kiselina (3‑formule) Pet oblika hijalurona (sodium hyaluronate, hydrolyzed HA, HA) kombinuje različite molekulske težine za slojevitu hidrataciju. Zadržava vlagu unutar epidermisa, povećava fleksibilnost i doprinosi osećaju „punijeg“ lica ujutru. Ceramide NP Lipidi koji oponašaju prirodne ceramide kože. U nano‑oblicima prodire duboko i obnavlja barijeru, štiti od gubitka vlage i stimulira ravnotežu vlage tokom noći. Melatonin Snažan antioksidant koji neutralizuje štetu od slobodnih radikala nastalu tokom dana. Podržava kožu tokom noći, neguje i doprinosi svežem, ujednačenom izgledu prati by smanjenje znakova umora. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Hyalu‑Cica Sleeping Pack kombinuje visok koncentrat Centella Asiatica (oko 39 %) i pet vrsta hijaluronske kiseline s melatoninom i ceramidima, što tokom noći intenzivno hidrira, umiruje i ujednačava ten.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Madagascar-Centella-Hyalu‑Cica-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
