INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (726, 114, 'Medicube Hyaluronic Multi Peptide Serum', 'medicube-hyaluronic-multi-peptide-serum', 'Ključne prednosti: Intezivna hidratacija i popunjavanje: Višeslojna hijaluronska kiselina prodire duboko i zadržava vlagu do 144 sata, čineći kožu glatkom i elastičnom. Očvršćivanje i podmlađivanje tena: Kompleks 13 peptida stimuliše proizvodnju kolagena i elastina, smanjujući bore i poboljšavajući tonus kože. Obnova barijere i posvetljivanje: PDRN i niacinamid ujednačavaju ten, jačaju barijeru i umanjuju crvenilo i fleke. Kome je namenjen? Pogodan za sve tipove kože, posebno za zrelu, umornu, dehidriranu ili kožu sa znakovima starenja i hiperpigmentacijom. Zašto volimo Medicube Hyaluronic Multi Peptide Serum? Hyaluronic Multi Peptide Serum donosi efekat profesionalne nege u svakodnevnoj rutini. Njegova dvostruka formula — vodeni i uljani sloj — omogućava brzo prodiranje i dugotrajno zadržavanje hidratacije. Koža postaje elastičnija, glatkija i blistavija, a fine linije i nabori vidno ublaženi. Zahvaljujući snažnim regenerativnim sastojcima kao što su peptidi i PDRN, serum obnavlja kožnu barijeru, poboljšava tonus i smanjuje znake umora. Ne izaziva iritacije, ne zapušava pore i pogodan je za svakodnevnu upotrebu, čak i kod osetljive kože. Lagana tekstura se brzo upija i savršeno funkcioniše kao podloga za kremu ili šminku. Aktivni sastojci Sodium Hyaluronate i hijaluronski kompleksi Višemolekularna hijaluronska kiselina pruža slojevitu hidrataciju – deluje u površinskom i dubljem sloju kože, zadržava vlagu i popunjava fine linije. Ova kombinacija hidrira do 144 sata i pruža osećaj punoće bez masnog filma. Peptidi (Acetyl Hexapeptide‑8, Palmitoyl Pentapeptide‑4, Copper Tripeptide‑1 i drugi) Peptidni kompleks stimuliše regeneraciju ćelija, sintezu kolagena i elastina, poboljšava čvrstinu i elastičnost kože. Deluje protiv bora i doprinosi mladolikijem izgledu kože. PDRN (Polydeoxyribonucleotide) Potiče regeneraciju ćelija, obnavlja kožnu barijeru, smanjuje crvenilo i posvetljuje ten. Ovaj molekul se dobija iz DNK lososa i poznat je po snažnim antiinflamatornim i reparativnim svojstvima. Niacinamide Ujednačava ton kože, osvetljava tamne fleke i umanjuje pojavu proširenih pora. Takođe poboljšava barijernu funkciju kože i smanjuje znake starenja. Panthenol Daje koži dodatnu vlagu, ublažava iritacije i pospešuje regeneraciju. Umiruje kožu i čini je mekšom i otpornijom. Dodaj u listu želja Dodaj u listu želja', 'Medicube Hyaluronic Multi Peptide Serum je jedinstveni dvoslojni serum koji kombinuje 0,5 % visokočiste hijaluronske kiseline, 13 anti-age peptida i PDRN (salmon DNA) za intenzivnu hidrataciju, popunjavanje bora i regeneraciju kože. Idealno rešenje za jačanje barijere i vraćanje elastičnosti koži bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Medicube-Hyaluronic-Multi-Peptide-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
