INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (728, 164, 'Tirtir Azelaic Acid 12% Serum', 'tirtir-azelaic-acid-12-serum', 'Ključne prednosti: Visoka koncentracija azelaične kiseline (12 %): efikasno redukuje akne, crvenilo i pigmentacione mrlje delujući blago, bez iritacija, čak i na osetljivoj koži. Regulacija sebuma uz Zinc PCA: smanjuje sjaj i prekomernu masnoću kože, pomažući u održavanju optimalnog balansa bez osećaja zatezanja. Dubinska hidratacija i barijerna zaštita: kombinacija pantenola, ceramida, humektanata i antioksidanata jača kožni zaštitni sloj i smiruje upale. Kome je namenjen? Formulisano za masnu, mešovitu i aknama skloni ten sa tendencijom hiperpigmentacija koji zahteva snažan, ali nežan tretman. Takođe idealno za osetljivu kožu koja zahteva pažljivu negu bez agresivnih sastojaka. Zašto volimo TIRTIR Azelaic Acid 12% Serum? Ovaj serum donosi sinergiju učinkovite azelaične kiseline sa umirujućim i hidratantnim komponentama, čime postiže dugoročne rezultate. Blokirajući bakterije P. acnes i ciljano delujući na melanin, pomaže smanjenju akni i mrlja dok ten postaje glatkiji. Prirodni balans sebuma doprinosi matiranom izgledu, bez zatezanja. Pantenol smanjuje osetljivost i crvenilo, ceramidi obnavljaju barijernu strukturu, a antioksidansi jačaju otpornost kože. Formula bez alkohola i mirisa dodatno povećava toleranciju i sigurnost za svakodnevnu primenu. Aktivni sastojci Azelaična kiselina (12 %) Dikarboksilna kiselina sa antibakterijskim i antiinflamatornim dejstvom. Cilja P. acnes bakterije i razbija keratinske čepove u porama, uklanja hiperpigmentacione mrlje i reguliše keratinizaciju. Blago pH delovanje osigurava nežan piling bez iritacija, što je odlično za osetljivu kožu. Koncentracija od 12 % pruža visoku efikasnost bez agresije. Redovna upotreba rezultira čistijom, glatkijom i ujednačenom površinom tena. Zinc PCA Reguliše rad lojnih žlezda i smanjuje lučenje sebuma, što direktno utiče na grejanje i izgled kože. Kao humektant privlači vlagu, te zajedno sa azelaičnom kiselinom deluje protiv akni i crvenila. Zbog antibakterijskog efekta, smanjuje upale i potpomaže čišćenje kože. Tehnološki je dokazano da formulu čini stabilnijom i boljom za masnu kožu. Pantenol (provitamin B5) Dubinski hidrira i obnavlja zaštitnu barijeru, smanjujući osetljivost i crvenilo. Pospešuje regeneraciju epidermalnog sloja i deluje umirujuće, čineći seru blagodaran za suvu i iritiranu kožu. Povećava elasticitet i daje osećaj mekoće, omogućavajući neagresivan tretman. Ceramide NP Oponaša prirodne lipide kože i jača zaštitnu barijeru. Smanjuje transepidermalni gubitak vlage i poboljšava elastičnost, što je posebno važno nakon tretmana azelaičnom kiselinom. Ceramidi povećavaju otpornost kože na spoljašnje faktore i doprinose ujednačenom i hidriranom izgledu tena. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Azelaic Acid 12% Serum je snažan, a ipak nežan tretman koji rešava problem akni, hiperpigmentacije i viška sebuma. Sadrži 12 % azelaične kiseline koja otvara pore i ujednačava ten, dok cink, ceramidi i pantenol umiruju i hrane kožu bez isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/06/TIRTIR-Azelaic-Acid-12-Serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
