INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (731, 48, 'Dr.Althea Pore Refresh Grinding Cleansing Balm', 'dr-althea-pore-refresh-grinding-cleansing-balm', 'Ključne prednosti: Dubinsko čišćenje bez iritacije: Efikasno uklanja čak i vodootpornu šminku i SPF, bez zatezanja kože ili narušavanja njene prirodne barijere. Smanjuje vidljivost pora: Biljni ekstrakti i ulja pomažu u otpušavanju i pročišćavanju pora, čineći ten vidno čistijim i ujednačenim. Higijenska i praktična upotreba: Inovativna ambalaža omogućava doziranje svežeg balzama svakim okretanjem, bez potrebe za spatulom. Kome je namenjen? Ovaj balzam je idealan za osobe sa mešovitom do masnom kožom, sklonom proširenim porama i nakupljanju nečistoća. Posebno se preporučuje osobama koje traže nežno, ali temeljno čišćenje bez isušivanja i iritacija. Zašto volimo Dr.Althea Pore Refresh Grinding Cleansing Balm? Pore Refresh Grinding Cleansing Balm donosi novu dimenziju čišćenja kože – formulisan kao čvrst balzam koji se transformiše u svilenkasti uljni sloj pri kontaktu s kožom. Već nakon prvog korišćenja, ten postaje osvežen, a pore vidno čistije. Zahvaljujući ekstraktu zelenog čaja, kontroliše se prekomerno lučenje sebuma, dok ulje soje i jojobe obnavljaju lipidni balans kože. Balzam ne ostavlja mastan film, već kožu čini glatkom i osveženom. S obzirom na to da je dermatološki testiran za osetljivu i aknama sklonu kožu, pogodan je i za svakodnevnu upotrebu. Jedinstveni sistem doziranja eliminiše rizik od kontaminacije proizvoda, omogućavajući higijensko i dugotrajno korišćenje. Aktivni sastojci Camellia Sinensis Leaf Extract (Zeleni čaj) Ovaj snažni antioksidans pomaže u kontroli viška sebuma i smanjenju upalnih procesa, što ga čini idealnim za masnu i problematičnu kožu. Njegova umirujuća svojstva pomažu u ublažavanju crvenila i iritacija, dok istovremeno deluje protiv slobodnih radikala. Redovnom upotrebom koža postaje čistija, matirana i otpornija na spoljašnje uticaje. Ekstrakt zelenog čaja takođe pomaže u prevenciji nastanka novih nepravilnosti i pruža ujednačen ton kože. Soybean Oil (Ulje soje): Bogato esencijalnim masnim kiselinama, ulje soje pruža duboku hidrataciju i obnavlja kožnu barijeru. Deluje umirujuće i pomaže u očuvanju vlažnosti, posebno nakon čišćenja. Njegova antiinflamatorna svojstva pomažu u ublažavanju iritacija i crvenila, a istovremeno čuvaju prirodnu elastičnost kože. Idealno je za negu osetljive i suve kože nakon skidanja šminke. Sodium Guaiazulene Sulfonate Poznat po snažnim antiinflamatornim svojstvima, ovaj sastojak umiruje kožu, smanjuje crvenilo i pruža osećaj olakšanja kod iritacija. Posebno je koristan kod osjetljive i upaljene kože, jer ublažava neprijatnosti bez dodatnog opterećenja. Pruža zaštitu od spoljnih iritansa i podržava regeneraciju kože. Jojobino ulje (Simmondsia Chinensis Seed Oil) Jojobino ulje se prirodno prilagođava tipu kože zahvaljujući svojoj strukturi sličnoj sebumu. Pomaže u otapanju nečistoća iz pora, dok istovremeno hidrira i balansira kožu bez izazivanja akni. Doprinosi mekoći i elastičnosti, bez osećaja masnoće. Rice Bran Oil (Ulje pirinčanih mekinja) Ovo lagano, ali bogato ulje je prirodan izvor vitamina E i ferulične kiseline, poznatih po antioksidativnim i anti-age svojstvima. Hidrira kožu i pomaže u zaštiti od oštećenja izazvanih UV zračenjem i zagađenjem. Posebno korisno kod umorne i beživotne kože kojoj je potrebna revitalizacija. Dodaj u listu želja Dodaj u listu želja', 'Dr.Althea Pore Refresh Grinding Cleansing Balm je balzam za čišćenje lica u formi sorbeta koji efikasno uklanja šminku, SPF i nečistoće iz pora bez iritacije kože. Formulisan s prirodnim uljima i biljnim ekstraktima, pruža temeljno čišćenje i umiruje kožu, ostavljajući je hidriranom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Dr.Althea-Pore-Refresh-Grinding-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
