INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (734, 45, 'Dear, Klairs Fundamental Eye Awakening Gel', 'dear-klairs-fundamental-eye-awakening-gel', 'Ključne prednosti: Smanjenje natečenosti i podočnjaka: Kofein topikalno poboljšava mikrocirkulaciju i steže krvne sudove, čime vraća bistrinu i budan izgled oči. Hidracija bez masnog sjaja: Kombinacija glicerina, jojoba ulja i arganovog ulja prodire duboko, ostavljajući kožu zaglađenom i elastičnom bez lepljivog osećaja. Antioksidativna zaštita i umirenje: Antioksidansi iz zelenog čaja i niacinamid štite osetljivo područje od oksidativnog stresa i upala. Kome je namenjen? Idealno je rešenje za sve koji se suočavaju sa jutarnjim otocima, tamnim kolutovima ili umornim izgledom, posebno za masnu, mešovitu i normalnu kožu koja traži brzo upijanje. Zašto volimo Dear Klairs Fundamental Eye Awakening Gel? Ovaj gel osvaja svojim trenutnim osvežavajućim efektom zahvaljujući hlađenju kojeg donosi lagana tekstura. Već nakon prvog nanošenja oči izgledaju odmornije i sjajnije. Redovna upotreba donosi smanjenje natečenosti i efekat učvršćivanja zahvaljujući sinergiji kofeina i peptida. Antioksidansi iz biljnih ekstrakta (zeleni čaj, crvena pasulja, itd.) štite kožu od slobodnih radikala i dodatno joj vraćaju tonus. Ulja argana i jojobe, uz niacinamid i tocoferol, neguju i jačaju hidrolipidni sloj, a brzo upijanje i neostavljanje masnih tragova omogućava udobno nanošenje i ispod šminke. Pogodan za jutarnju rutinu, ali i kao brzi „pick‑me‑up“ tokom dana — očima vraća energiju i svežinu. Aktivni sastojci Kofein Deluje kao snažan stimulator mikrocirkulacije, ubrzava limfnu drenažu i pomaže u smanjenju natečenosti i tamnih krugova. Dodatno pospešuje tonus kapilara, smanjujući pojavu crvenila i edema. Zahvaljujući antioksidativnim svojstvima, kožu štiti od oksidativnog stresa. U laganoj gel formuli bolje se apsorbuje, aktivno deluje već pri jutarnjoj upotrebi i ne ostavlja osećaj masnoće. Još jedna prednost je njegovo umirujuće dejstvo na otečene oči nakon nedovoljnog sna. Kofein je klinički priznat za brzo osveženje osjetljive kože oko očiju. Acetyl Hexapeptide‑8 i Copper Tripeptide‑1 Ova kombinacija peptida stimuliše sintezu kolagena i elastina, čineći kožu zategnutijom i otpornijom. Acetyl Hexapeptid‑8 radi na glatkoj teksturi i prevenciji finih linija, dok Copper Tripeptid‑1 ubrzava regeneraciju i jača hidrolipidni sloj. Dolaze u stabilnoj formi, pogodni za osetljivu kožu, ne izazivaju iritacije. Upotreba zajedno sa antioksidansima pojačava njihovo proaktivno delovanje, poboljšavajući celokupan tonus i barijeru kože. Peptidi su dermatološki testirani i često se koriste u sredstvima za anti-aging negu kože oko očiju. Simmondsia Chinensis (jojoba) Oil i Argania Spinosa Seed Oil Ulje jojobe balansira proizvodnju sebuma, dok argan obezbeđuje bogatu i stabilnu lipidnu zaštitu. Obe komponente su bogate esencijalnim masnim kiselinama i vitaminom E, podržavajući prirodnu barijeru kože. Deluju sinergijski: jojoba daje lepu glatkoću, a argan hrani i regeneriše kožu. Zajedno poboljšavaju elastičnost i mekoću površinskog sloja, ali ne zapušavaju pore. Njihova lagana formulacija savršeno se uklapa u jutarnju rutinu bez osećaja masnoće. Dodaj u listu želja Dodaj u listu želja', 'Dear Klairs Fundamental Eye Awakening Gel je lagani, osvežavajući gel za negu očnog područja koji ujedinjuje blagotvorni efekat kofeina i antioksidanata iz crvenog pasulja. Animira i hidrira umornu kožu, uspešno smanjujući natečenost i podočnjake već od prvih nanošenja.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Dear-Klairs-Fundamental-Eye-Awakening-Gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
