INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (735, 92, 'K-Secret Collagen Vita Secret Multi Balm', 'k-e2-80-91secret-collagen-vita-secret-multi-balm', 'Ključne prednosti: Antioksidativna energija 15 % vitamina C: smanjuje hiperpigmentacije, posvetljuje ten i čini kožu blistavom. Instant zaglađivanje sa kolagenom: fleksibilna molekulska struktura kolagena pomaže obnavljanju barijere, zatezanju kože i mekom, nezišćnom finishu. Peptidna sinergija za dugoročnu mladolikost: kompleks od 5 peptida fokusiranih na revitalizaciju i podsticanje proizvodnje kolagena, ciljajući bore i opuštenost. Kome je namenjen? Balzam je kreiran za sve tipove kože – posebno za zrelu, dehidriranu ili ten s nepravilnostima – koji traže brzu anti-age negu i savršen izgled u trenutku, bez dodatnih procedura. Zašto volimo K‑Secret Collagen Vita Secret Multi Balm? Tekstura stika omogućava precizno nanošenje na ključne zone bora – krajnje praktično, bez šminke, masnoće ili dodatne ambalaže. Tu noću poprima ulogu intenzivne regeneracije: vitamin C posvetljuje fleke, kolagen vraća elastičnost, a peptidi doprinose obnovi strukture kože. Tokom dana osvežava umoran ten, ostavljajući zdrav sjaj bez lepljivog osećaja. Redovnom upotrebom bore su mekše, pore su ujednačene, a ten izgleda svežije i odmornije – gotovo kao da je koža „obnovljena iznutra“. Aktivni sastojci Vitamin C (askorbinska kiselina, 15 %) Jak antioksidant koji neutralizuje slobodne radikale, blokira sintezu melanina i podstiče kolagenogenezu—rezultat je vidno svetliji ten i smanjenje hiperpigmentacija. Visoka koncentracija garantuje efikasnost, dok je oblikirano tako da ne iritira. Hidrolizovani kolagen Omogućava bolje zadržavanje vlage i popravku barijere kože. Mali molekuli prodiru dublje i pomažu vezivanju vlage, što povećava elastičnost i smanjuje osjećaj zatezanja, čineći kožu prijatno mekanom. Peptidni kompleks (Acetyl hexapeptide-8, Palmitoyl pentapeptide-4, Copper tripeptide-1 i ostali) Signališu koži da poveća vlastitu proizvodnju kolagena i elastina, što pomaže u smanjenju bora i vidljivom zatezanju kože tokom vremena. Pantenol (provitamin B5) Hidratantno-humektantna komponenta, ostavlja kožu mekom i olakšava zarastanje mikro oštećenja – idealna za regeneraciju noću i zaštitu tokom dana. Vitamin E (tocopheryl acetate) Dodatno štiti od oksidativnog stresa, ublažava upale i pojačava antioksidativni kapacitet formule, čineći je pogodnom i za osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'K‑Secret Collagen Vita Secret Multi Balm je inovativni balzam-stik kombinuje 15 % čistu vitamin C i hidrolizovani kolagen za intenzivno zaglađivanje bora i ujednačavanje tena – idealan za trenutne popravke i dugoročnu detoksikaciju kože. Kompaktni format omogućava jednostavnu upotrebu u pokretu, bilo da ste na poslu, u teretani ili tokom putovanja.', 'https://beauty-health.rs/wp-content/uploads/2025/06/K‑Secret-Collagen-Vita-Secret-Multi-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
