INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (736, 56, 'Elizavecca Cer‑100 Hair Muscle Essence Oil', 'elizavecca-cer-e2-80-91100-hair-muscle-essence-oil', 'Ključne prednosti: Dubinska hidratacija i sjaj: kombinacija arganovog, makadamija i avokado ulja obnavlja vlagu, ostavljajući kosu mekšu, sjajniju i bez statičkog efekta. Ojačavanje strukture kose: kolagen, ceramid i gami-linolenska masna kiselina iz šafranika doprinose elastičnosti i smanjuju lomljenje vlasi. Zaštita bez masnog sloja: silikoni (cyclopentasiloxane, dimethicone) formiraju zaštitni sloj koji zaglađuje i štiti bez otežavanja ili masnog osećaja. Kome je namenjeno? Idealno za sve tipove kose, posebno tanku, beživotnu ili oštećenu bojenjem i toplinskom obradom. Takođe odličan izbor za one koji žele kontrolu kovrdža uz lakoću i sjaj. Zašto volimo Elizavecca Cer‑100 Hair Muscle Essence Oil? Ovaj proizvod predstavlja savršeno spojila lagane, silki teksture i ultra-nutritivne formule. Biljna ulja prodiru u kosu, hraneći je iznutra i sprečavajući isušivanje pri feniranju ili UV zračenju. Kolagen &#8220;prekriva&#8221; svaku vlas, dajući joj veću čvrstinu i elastičnost, dok silikoni zaglađuju površinu i zadržavaju vlagu. Efekat je primetan već nakon prvog korišćenja — mekša, sjajnija i lakše rasčešljiva kosa. Pri redovnoj upotrebi se smanjuje lomljenje vrhova, kosa postaje otpornija i ima zdraviji izgled. Lagan, ne masti kosu i ostavlja osvežavajući, suptilan miris zahvaljujući esencijalnim uljima. Aktivni sastojci Cyclopentasiloxane i Dimethicone Silikoni koji kosu čine svilenkastom i glatkom. Oni formiraju nevidljivi zaštitni film koji sprečava gubitak vlage i smanjuje trenje. Znatno poboljšavaju rasčešljavanje i sprečavaju razdeljene vrhove, a pri tome ne ostavljaju osećaj masnoće. Ovaj neojasten osećaj čini ih idealnima za lako svakodnevno korišćenje. Argania Spinosa (argan) ulje Bogato je antioksidantima i vitaminom E, koji štite kosu i vlasište od slobodnih radikala. Dodatno kontroliše lučenje loja bez začepljenja pora, zateže pukotine u dlaci i doprinosi sjajnom, zdravom izgledu. Macadamia Ternifolia ulje Sadrži oleinsku i retku palmitoleinsku kiselinu, koja obnavlja prirodnu masnoću dlake. Dubinski hidrira i hrani iznutra, dajući kosi elastičnost i mekoću s &#8216;cushiony&#8217; efektom, dok pomaže u smirivanju ispucalih vlasi. Persea Gratissima (avokado) ulje Humektant bogat vitaminima A, D i E, često povezan s jačanjem kolagenskih vlakana. Doprinosi barijeri koja zadržava vlagu, smanjuje upale i poboljšava strukturu kose. Oenothera Biennis (šafranik) ulje Obogaćeno gamma-linolenskom kiselinom (GLA), poznato po umirujućem i regenerativnom delovanju. Stvara zaštitni film preko vlasi, čime sprečava prekomerni gubitak vlage i održava barijeru vlasišta. Tocopherol (vitamin E) deluje kao snažan antioksidant, štiteći kosu od foto oštećenja. Uz to usporava starenje dlake, podržava prokrvljenost vlasišta i povoljno utiče na zdravlje celokupne dlake. Dodaj u listu želja Dodaj u listu želja', 'Elizavecca Cer‑100 Hair Muscle Essence Oil je lagana esencija ulja obogaćena kolagenom i spektrom hranljivih biljnih ulja dubinski neguje, zaglađuje i pojačava sjaj kose bez osećaja težine, istovremeno jačajući vlasište i sprečavajući razdeljene vrhove.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Elizavecca-Cer‑100-Hair-Muscle-Essence-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
