INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (737, 116, 'Meditime Botalinum Concentrate Care Cream', 'meditime-botalinum-concentrate-care-cream', 'Ključne prednosti: Lifting i popunjavanje bora: Botilinum peptidi i acetil‑hexapeptid deluju na mimiku kože, opuštaju njene kontrakcije i smanjuju dubine bora. Obnova i jačanje barijere: Centella asiatica (madecassoside, asiaticoside) i niacinamid umiruju crvenilo, vraćaju elastičnost i izjednačavaju ten. Dubinska hidratacija bez masnog osećaja: Humektanti (betaine, panthenol, xylitylglucoside) privlače vodu. Skvalan i kolagen zaključavaju vlažnost u dubljim slojevima kože. Kome je namenjena? Ovaj proizvod je idealan za zrelu, dehidriranu i osetljivu kožu kojoj su potrebni vidljivi efekti zatezanja i jačina barijere bez iritacija. Takođe je dobar izbor za osobe koje se oporavljaju nakon profesionalnih tretmana poput mikrodermoabrazije ili laser terapije. Zašto volimo Meditime Botalinum Concentrate Care Cream? Ovaj bogati, ali lako razmazivi krem pruža vidljive rezultate već nakon nekoliko nedelja redovne upotrebe. Koža dobija čvršći konturisan izgled, fine linije na čelu i oko očiju postaju diskretnije, a ten deluje ujednačeno i sija zdravljem. Napredna TDDS tehnologija omogućava dublju i precizniju isporuku aktivnih sastojaka. Redukcija transepidermalnog gubitka vode čini kožu otpornijom na spoljašnji stres, dok antioksidantna zaštita umanjuje fotooštećenja. Aktivni sastojci Botilinum peptidi (botulinum-derived peptides) Patentirani peptidi koji ciljano smanjuju mišićne kontrakcije kože bez injekcija, stvaraju efikasni lifting efekat i smanjuju vidljivost boranja, približavajući izgled rezultatu minimalno invazivnih tretmana. Niacinamid (1,9–2,9 %) Pojačava sintezu ceramida, jača prirodnu barijeru kože i smanjuje gubitak vlage, dok istovremeno umanjuje hiperpigmentacije, reguliše sebum i deluje antiinflamatorno – idealan za smirivanje i toniranje tena. Centella asiatica (madecassoside i asiaticoside) Jača mikrocirkulaciju, podstiče regeneraciju barijere, umiruje crvenilo i podržava sintezu kolagena, posebno efikasni u obnavljanju nakon agresivnih tretmana. Acetil‑hexapeptid‑8 i sh-polypeptide‑1 peptidi koji stimulišu proizvodnju kolagena i elastina, umanjuju bore i povećavaju elastičnost kože, dok ujedno zadržavaju vlagu u epidermisu i preveniraju pucanje površinskih slojeva. Dodaj u listu želja Dodaj u listu želja', 'Meditime Botalinum Concentrate Care Cream je intenzivni anti‑age tretman baziran na „biljnom botoksu“ – botilinum peptidu – koji zateže kožu, smanjuje vidljivost bora i istovremeno dubinski hidrira i umiruje ispucalu i osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Meditime-Botalinum-Concentrate-Care-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
