INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (738, 143, 'Round Lab Camellia Deep Collagen Firming Cream', 'round-lab-camellia-deep-collagen-firming-cream', 'Ključne prednosti: Dubinska hidratacija bez masnog filma: Kombinacija glicerina, propanediola i ulja semena kamelije pruža dugotrajnu vlažnost, a lagana tekstura se brzo upija. Vidljivo učvršćivanje s trostrukim kolagenom: Hidrolizovani, biljni i niskomolekulski kolagen pomažu popunjavanju finih linija i povratku elastičnosti kože. Obnavljanje i zaštita barijere: Niacinamid, HPR (hidroksipinakolonska retinoidna kiselina) i adenosin rade zajedno na smanjenju pora, stimulaciji kolagena i zaštiti od oksidativnog stresa. Kome je namenjena? Krema je dizajnirana za odrasle osobe sa vidljivim znacima starenja, gubitkom elastičnosti i neujednačenim tenom. Idealan je izbor za kombinovanu, normalnu i suvu kožu kojoj je potrebna snažna, ali lagana anti-age njega. Zašto volimo Round Lab Camellia Deep Collagen Firming Cream? Ovaj proizvod pruža trenutni efekat „juice glow“ zahvaljujući brzo upijajućoj teksturi koja ne ostavlja lepljiv trag. Redovnom upotrebom trostruki kolagen vraća volumen i zateže konture lica, dok retinoidna komponenta HPR blago stimuliše sintezu kolagena bez iritacija. Niacinamid dodatno ujednačava ten i smanjuje pore, a antioxidantna snaga kamelije i kvercetina štiti kožu od spoljašnjih agresora. Pantenol, hijaluronska kiselina i cink-glicirizinat umiruju i jačaju kožnu barijeru, što ukupno dovodi do bistrije, otpornije i sjajnije kože tokom vremena. Aktivni sastojci Camellia Japonica Flower Extract & Camellia Collagenol™ Ekstrakt kamelije ručno je sakupljen na Jeju ostrvu i izdvojen niskotemperaturnom metodom da bi zadržao antioksidativna i hranljiva svojstva. Zajedno sa inozitolom i kvercetinom, formira kompleks koji hrani, štiti od slobodnih radikala i pruža meku hidrataciju. Ovaj sastav značajno jača barijeru kože i podstiče njenu elastičnost. Njegov blagi, ali vidljiv efekat učvršćivanja čini ga idealnim za nadopunu kolagena. Hidrolizovani kolagen (trostruki kolagen) Hidrolizovana forma pomaže u popunjavanju tankih linija i vraćanju volumena odmah vidljivim efektom. Biljna i niskomolekulska verzija deluju na više nivoa kože — površinski i dublje — čime obnavljaju strukturu i elastičnost. Ovaj kolagenski spoj podstiče zategnutiji izgled lica i doprinosi dugotrajnom osećaju čvrste kože. Hydroxypinacolone Retinoate (HPR) Naredna generacija retinoida koja bez iritacija stimuliše sintezu kolagena i prirodnu ćelijsku obnovu. Poboljšava glatkoću površine kože i smanjuje pojavu proširenih pora. HPR je stabilniji i blaži od tradicionalnih tretinoida, što ga čini pogodnim i za osetljivu kožu. Niacinamid Multifunkcionalan vitamin B3 koji jača barijeru kože, smanjuje hiperpigmentacije i pročišćuje pore. Deluje antiinflamatorno i balansira ten, pružajući blistav i ujednačen izgled. Podstiče sintezu ceramida i kolagena, čineći kožu otpornijom i hidriranijom. Alantoin i Dipotassium Glycyrrhizate Ovi sastojci umiruju i regenerišu kožu, smanjuju iritacije i crvenilo. Allantoin deluje na zaceljivanje sitnih oštećenja, dok glicirizinat pokreće antioksidativnu reakciju i umiruje toplotne osećaje. Zajedno pružaju prijatan i umirujući završni osećaj. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Camellia Deep Collagen Firming Cream &#8211; otkrij moć mladalačke čvrstoće uz gel-kremu koja kombinuje trostruki kolagen i ekskluzivni Camellia Collagenol™ kompleks. Njena svilenkasta tekstura dubinski hidrira, vraća elastičnost i pruža blistav „plump“ efekat koji vidno osvežava i učvršćuje kožu iz dana u dan.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Round-Lab-Camellia-Deep-Collagen-Firming-Cream-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
