INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (741, 159, 'Sungboon Editor Deep Collagen Retinol Power Boosting Capsule Cream', 'sungboon-editor-deep-collagen-retinol-power-boosting-capsule-cream', 'Ključne prednosti: Kapsulirana formula sa kolagenom i retinolom: Dva puta jače delovanje – peptidi i retinol prodiru duboko, obnavljaju i čine kožu zategnutijom. Efekat mikroiglica bez bola: Sitne spikule omogućavaju da aktivni sastojci bolje prodru, što značajno poboljšava elastičnost i sjaj kože. Dubinska hidratacija: Gel‑baza sa hijaluronskom kiselinom hidrira bez masnog filma, ostavljajući kožu glatkom i svežom. Kome je namenjena? Savršen za zrelu, umornu ili dehidriranu kožu koja traži sveobuhvatno podmlađivanje, pojačanu elastičnost i glatki “glass skin” izgled bez iritacije. Zašto volimo Sungboon Editor Deep Collagen Retinol Power Boosting Capsule Cream? Ova krema spaja kapsulirani kolagen i retinol unutar nežnog gela, obezbeđujući brzo vidljive rezultate poput zategnutije i hidriranije kože. Zahvaljujući mikroiglicama, aktivni sastojci prodiru dublje, pospešujući regeneraciju i obnavljanje. Gel‑baza hidrira bez ostavljanja masnog tragova i pospešuje prirodni sjaj. Pre i posle fotografije pokazuju jasne rezultate: fine linije su ublažene, lice izgleda glađe i zdravije. Mogu ga koristiti i osobe osetljive na retinol jer kapsule oslobađaju aktivne sastojke postepeno, što sprečava iritaciju. Idealno za noćnu rutinu, ali i za upotrebu na vratu i dekolteu. Aktivni sastojci Kolagen (200 Da kolagen) Protein male molekulske težine omogućava prodor duboko u kožu, obnavlja i zateže strukturu lica. Daje elastičnost, smanjuje fine linije i podržava prirodne procese regeneracije. Efekat je vidljiv već posle nekoliko korišćenja, jer povećava čvrstinu i elastičnost. Idealno za kožu koja je izgubila tonus i vlagu. Retinol Jak anti-age sastojak koji ubrzava obnavljanje ćelija, potiče proizvodnju kolagena i smanjuje vidljive bore. U kapsuliranoj formi postepeno oslobađa aktivan oblik, pa je manje iritantan. Pomaže pri ujednačavanju tena i teksture kože. Efikasno blago koriguje pigmentacije i daje mladalački sjaj. Peptidi (9 različitih peptida) Male molekule koje stimulišu sintezu kolagena, povećavaju čvrstinu kože i smanjuju bore. U kombinaciji s retinolom, pojačavaju anti-age efekat. Nežno deluju, bez iritacija, čak i na osetljivoj koži. Čine kožu elastičnijom i otpornijom. Hijaluronska kiselina Veže vodu, dubinski hidrira i popunjava kožu. Obnavlja vlagu i daje dugotrajan &#8220;plumping&#8221; efekat. Čini kožu glatkom i svežom, bez osećaja težine. Spikule Sitne, netopive igličaste strukture koje deluju kao mikroiglice, omogućavajući bolji prodor aktivnih sastojaka i povećavajući apsorpciju za 30–40 %. Ne iritiraju, ali pojačavaju efikasnost retinola i kolagena. Gel baza Lagana, svilenkasta tekstura koja se brzo upija, ne zamašćuje kožu i omogućava momentalni osećaj svežine. Idealna za noćnu negu, ostavlja hidriran osećaj bez masnog sjaja. Dodaj u listu želja Dodaj u listu želja', 'Sungboon Editor Deep Collagen Retinol Power Boosting Capsule Cream je moćna anti-age krema u kapsulama koja vidljivo zateže, hidrira i podmlađuje kožu već nakon nekoliko korišćenja. Kombinacija retinola, niskomolekularnog kolagena i peptida pruža puniji, glađi i blistaviji ten bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/06/SUNGBOON-EDITOR-Deep-Collagen-Retinol-Power-Boosting-Capsule-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
