INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (742, 82, 'Innisfree No-Sebum Mineral Pact', 'innisfree-no-sebum-mineral-pact', 'Ključne prednosti: Efikasna kontrola sebuma: Upija višak masnoće i pruža mat završnicu bez isušivanja kože. Prirodni sastojci sa ostrva Jeju: Minerali i menta osvežavaju, umiruju i pomažu da koža ostane uravnotežena. Višenamenska upotreba: Fiksira šminku, deluje kao blot papir i smanjuje sjaj u T‑zoni tokom dana. Kome je namenjen? Idealno za osobe sa masnom i kombinovanom kožom, kao i za sve koji žele dugotrajan mat izgled bez čestih popravki. Pogodan i za osetljivu kožu jer ne sadrži parabene ni veštačke mirise. Zašto volimo Innisfree No-Sebum Mineral Pact? No-Sebum Mineral Pact je lagani kompaktni puder koji savršeno kontroliše masnoću, ostavljajući kožu glatkom, svežom i bez sjaja. Formula bazirana na prirodnim mineralima sa Jeju ostrva i menti pruža osveženje, dok istovremeno umiruje kožu i sprečava preterano mašćenje. Zahvaljujući sitno mlevenoj teksturi, ravnomerno se nanosi, ne ostavlja tragove i ne naglašava pore. Idealan je za popravke tokom dana jer se lako nanosi i preko šminke. Savršen je za letnje dane, dugačke radne sate i situacije kada koža mora ostati besprekorna i pod kontrolom. Aktivni sastojci Minerali sa ostrva Jeju (Jeju Natural Minerals) Minerali iz vulkanskog tla ostrva Jeju, poput kalcijuma i magnezijuma, pomažu u prirodnoj regulaciji sebuma i održavanju ravnoteže kože. Deluju matirajuće bez isušivanja, čineći kožu glatkom i svežom tokom celog dana. Njihova blaga priroda ih čini pogodnim i za osetljivu kožu, jer ne izazivaju zapušenost pora ni iritacije. U ovoj formuli, minerali apsorbuju višak ulja i fiksiraju šminku bez težine. Idealni su za svakodnevnu upotrebu, posebno u uslovima povećanog znojenja ili masne kože. Dodatno, pružaju osvežavajući osećaj i prirodnu čistoću kože. Ekstrakt mente (Mint Extract) Menta ima prirodna antiseptička i osvežavajuća svojstva koja hlade i umiruju kožu. Doprinosi smanjenju crvenila i osećaja težine, posebno u T-zoni. Pomaže u kontroli viška sebuma i doprinosi matiranju kože bez zatezanja. U formulama za masnu i kombinovanu kožu, menta se koristi zbog svog antibakterijskog efekta i sposobnosti da suzi pore. Takođe poboljšava tonus kože i daje instant osećaj čistoće. U ovoj formuli, pruža lagani osvežavajući miris i učvršćuje efekat matiranja. Silika (Silica) Silika je mineralni prah poznat po svojoj sposobnosti da upija višak masnoće i poboljša teksturu kože. Ostavlja baršunasti osećaj i pomaže u ujednačenju tena, bez težine ili nagomilavanja proizvoda. Takođe doprinosi postojanosti šminke, jer smanjuje sjaj tokom dana. Ne začepljuje pore i ne izaziva iritacije, što je čini idealnom i za osetljivu kožu. U ovoj formuli, silika pruža glatku završnicu i produžava svež izgled šminke. Posebno je korisna tokom toplijih meseci kada se koža više masti. Dodaj u listu želja Dodaj u listu želja', 'Innisfree No-Sebum Mineral Pact je kompaktni puder koji trenutno matira lice, kontroliše višak sebuma i fiksira šminku tokom celog dana. Sa mineralima sa ostrva Jeju i prirodnom mentom, ostavlja kožu glatkom, bez sjaja i bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Innisfree-No-Sebum-Mineral-Pact.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
