INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (743, 1, '2aN Easy Off Mascara Remover', '2an-easy-off-mascara-remover', 'Ključne prednosti: Skida i najotporniju maskaru: Fleksibilna spiralna četkica omogućava preciznu i brzu primenu kako bi se maskara rastvorila i uklonila za 10 sekundi. Hipoalergenska i bez iritacija: Testiran za osetljive oči, bez mirisa, alkohola i silikona – nežan prema koži i sluzokoži. Nega trepavica tokom čišćenja: Sadrži kokosovo ulje i aloe veru koja hrane i jačaju vlasi, sprečavajući lom i ispadanje. Kome je namenjen? Namenjen je osobama koje nose vodootpornu ili postojanu maskaru, a traže nežan i brz način skidanja bez uvlačenja silikona, alkohola ili agresivnih mirisa. Idealno za korisnike osetljivih očiju i one koji žele negu trepavica uz čišćenje. Zašto volimo 2aN Easy Off Mascara Remover? Easy Off Mascara Remover uklanja čak i najuporniju vodootpornu maskaru za samo deset sekundi, bez masnih tragova. Spiralna četkica omogućava preciznu primenu od korena do vrha trepavica, bez trljanja. Zahvaljujući kokosovom ulju i aloe veru, formula neguje i hidratizira, sprečavajući lom trepavica. Produkt je hipoalergenski, bez alkohola, parfema i parabena, što ga čini pogodnim i za najosetljivije oči. Nakon skidanja šminke, oko je osveženo, bez osećaja težine ili uljnog filma. Brz, praktičan i efikasan – savršen za večernju rutinu i putovanja. Aktivni sastojci Isododekan je ključan za lako otapanje šminke bez isušivanja kože. Omogućava brzo uklanjanje maskare bez oštećenja trepavica. Mineralno ulje omekšava maskaru i štiti kožu od trenja. Ostavlja kožu glatkom i bez iritacija. Gliceril kaprilat hidrira i štiti područje oko očiju, sprečava isušivanje i dodatno neguje trepavice. Aloe vera (ekstrakt) umiruje kožu, sprečava crvenilo i pruža osvežavajući osećaj nakon čišćenja. Kokosovo ulje neguje vlasi trepavica i štiti ih od lomljenja prilikom skidanja šminke. Dodaj u listu želja Dodaj u listu želja', '2aN Easy Off Mascara Remover je praktičan i nežan odstranjivač maskare koji skida i najpostojaniju, vodootpornu maskaru za samo 10 sekundi – bez trljanja i bez iritacije. Zahvaljujući hranljivoj formuli, neguje trepavice dok ih čisti, ostavljajući kožu oko očiju svežom i bez osećaja masnoće.', 'https://beauty-health.rs/wp-content/uploads/2025/06/2aN-Easy-Off-Mascara-Remover-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
