INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (744, 125, 'Novo Summer Aromatic Roll-On Deodorant', 'novo-summer-aromatic-roll-on-deodorant', 'Ključne prednosti: Antiperspirant formula: Aluminijum‑hlorohidrat pouzdano reguliše znojenje i sprečava neprijatan miris. Biljna nega kože: Ekstrakti hamamelisa i dendrobium officinale umiruju i štite osetljivu kožu ispod pazuha. Lagana i nemasna tekstura: Vodena baza brzo se upija, ostavlja kožu suvom i osveženom, bez tragova na odeći. Kome je namenjen? Idealan je za sve koji žele pouzdanu antiperspirant zaštitu tokom toplih letnjih dana, a istovremeno traže nežnu formulu bez osećaja težine. Pogodan je za muškarce i žene koji preferiraju blage i sveže mirise. Zašto volimo NOVO Summer Aromatic Roll-On Deodorant? NOVO Summer Aromatic Roll-On Deodorant kombinuje efikasnu antiperspirant zaštitu i osvežavajuću negu. Aluminijum‑hlorohidrat smanjuje znojenje, dok biljni ekstrakti umiruju kožu i štite od iritacije. Nova, vodena tekstura omogućava ugodno nanošenje i brzu apsorpciju. Mirisi su diskretni, nežno osvežavaju i ostavljaju osećaj čistoće tokom celog dana. Proizvod je neostrašiv prema osetljivoj i depiliranoj koži, a zahvaljujući laganom završetku, idealan je uz svakodnevno nošenje i tokom sportskih aktivnosti. Aktivni sastojci Aluminijum‑hlorohidrat deluje kao antiperspirant blokirajući pore i smanjujući znojenje, čime sprečava razmnožavanje bakterija koje izazivaju neprijatan miris. Ekstrakt hamamelisa (witch hazel) tonira i umiruje kožu, smanjuje crvenilo i iritacije nakon depilacije. Dendrobium officinale ekstrakt je orijentalna biljka bogata antioksidansima, hidrira i štiti kožu od slobodnih radikala. Vodena baza omogućava brzu upijanje, čini proizvod laganim i nemasnim, bez belih tragova na odeći. Prijatni mirisi – tri osvežavajuća leta: cvetna, voćna i zelena nota – doprinose osećaju svežine i dugotrajne udobnosti. Bez ulja – prozračna tekstura koja ne ostavlja masne tragove, što je posebno važno leti. Dodaj u listu želja Dodaj u listu želja', 'NOVO Summer Aromatic Roll‑On Deodorant pruža zaštitu od znojenja i neprijatnog mirisa uz laganu, osvežavajuću formulu koja hladi kožu i ostavlja dugotrajan miris. Sadrži i kineske biljne ekstrakte koji umiruju i obnavljaju kožu, a dolazi u 3 mirisne varijante: cvetna, voćna i biljna.', 'https://beauty-health.rs/wp-content/uploads/2025/06/NOVO-Summer-Aromatic-Roll‑On-Deodorant-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
