INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (745, 114, 'Medicube One Day Exosome Shot Pore Ampoule 25000', 'medicube-one-day-exosome-shot-pore-ampoule-25000', 'Ključne prednosti: 25.000 ppm egzozoma: Dubinski obnavljaju kožu, zatežu pore i vraćaju glatku teksturu. Efekat mikroiglica bez bola: Spikule prirodnog porekla poboljšavaju upijanje sastojaka i čine kožu čvršćom. Ujednačava i osvetljava ten: Niacinamid i blage kiseline čiste pore, smanjuju fleke i vraćaju prirodni sjaj. Kome je namenjen? Za osobe sa proširenim porama, masnijom T-zonom, neujednačenom teksturom i kožom koja gubi elastičnost. Pogodan za masnu, mešovitu i osetljivu kožu koja traži vidljive promene uz minimalnu iritaciju. Zašto volimo Medicube One Day Exosome Shot Pore Ampoule 25000? One Day Exosome Shot Pore Ampoule 25000 koristi naprednu tehnologiju egzozoma i mikroskopskih spikula da brzo i precizno deluje u dubljim slojevima kože. Klinički je potvrđeno da smanjuje vidljivost pora i poboljšava barijernu funkciju kože već nakon jedne primene. Niacinamid osvetljava ten i reguliše masnoću, dok peptidi i ceramidi jačaju kožu i vraćaju elastičnost. Tretman je snažan, ali nežan – nema crvenila ni perutanja. Ujednačava teksturu, čini lice glađim i sjajnijim, a efekat se vidi već narednog dana. Idealan je za korisnike koji žele rezultate slične salonu, ali kod kuće. Aktivni sastojci Egzozomi Bioaktivne čestice koje prenose signale među ćelijama i pokreću regeneraciju kože. Pomažu da se koža brže obnavlja, zateže i postaje glađa. Niacinamid Vitamin koji ujednačava ten, smanjuje crvenilo i kontroliše lučenje sebuma. Vraća koži svež i zdrav izgled. Peptidi Podstiču sintezu kolagena i smanjuju fine linije. Jačaju strukturu kože i održavaju njen tonus. Spikule Sitne prirodne iglice koje otvaraju kožu za bolju apsorpciju. Pojačavaju efekat aktivnih sastojaka bez potrebe za iglama. Betain salicilat i glukonolakon Uklanjaju mrtve ćelije i čiste pore bez iritacije. Koža postaje čistija i glađa. Ceramidi Jačaju zaštitni sloj kože, zadržavaju vlagu i štite od spoljašnjih faktora. Dodaj u listu želja Dodaj u listu želja', 'Medicube One Day Exosome Shot Pore Ampoule 25000 je intenzivni serum koji brzo smanjuje proširene pore, zateže kožu i poboljšava teksturu već nakon prve upotrebe. Sadrži 25.000 ppm egzozoma koji podstiču regeneraciju i vraćaju koži ujednačen i zdrav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Medicube-One-Day-Exosome-Shot-Pore-Ampoule-25000.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
