INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (746, 174, 'VT Cosmetics Azelaic A1 Calming Ampoule', 'vt-cosmetics-azelaic-a1-calming-ampoule', 'Ključne prednosti: Reguliše višak sebuma i sužava pore: Azelaična kiselina deluje na koren problema – sprečava upalne procese i balansira masnoću. Umiruje kožu i smanjuje crvenilo: CICA kompleks i Madecassoside obnavljaju kožnu barijeru i ublažavaju iritacije. Ujednačava ten i smanjuje tragove od akni: Aktivni sastojci rade na posvetljavanju fleka i poboljšanju teksture kože. Kome je namenjen? Serum je formulisan za masnu, kombinovanu i problematičnu kožu, ali ga mogu koristiti i osobe sa osetljivom kožom sklonom iritacijama i upalama. Posebno se preporučuje za kožu sa postupalnim flekama, proširenim porama i rosaceom. Zašto volimo VT Cosmetics Azelaic A1 Calming Ampoule? Ova ampula koristi 10% azelaične kiseline, dermatološki priznate komponente koja smanjuje upale, balansira lučenje sebuma i vidljivo umanjuje postupalne fleke i teksturalne nepravilnosti. Zahvaljujući dodatku Cica Exosome kompleksa, ekstrakta centelle i madecassosidea, serum ne samo da deluje antiinflamatorno, već i obnavlja kožu i jača njenu prirodnu barijeru. Tekstura je lagana, nekomedogena i pogodna za svakodnevnu upotrebu. Idealna je zamena za agresivnije kiseline i savršeno se uklapa u večernju negu, posebno kod kože koja ne podnosi retinoide. Aktivni sastojci Azelaična kiselina (10%) Multifunkcionalna kiselina koja smanjuje upale, sprečava nastanak mitisera i akni, ujednačava ten i pomaže u posvetljavanju hiperpigmentacija. Odlična je alternativa za osetljivu kožu koja ne podnosi AHA/BHA. CICA Exosome kompleks Sadrži visoko stabilne oblike centelle asiatice koji prodiru dublje u kožu i umiruju iritacije, dok istovremeno podstiču regeneraciju. Niacinamid Posvetljuje ten, smanjuje vidljivost pora i jača kožnu barijeru. Hijaluronska kiselina Višeslojno hidrira kožu, obezbeđuje dugotrajnu vlagu i poboljšava elastičnost bez osećaja težine. Vitamin E (Tocopherol) Doprinosi antioksidativnoj zaštiti, pomaže koži da se izbori sa spoljašnjim stresorima i ubrzava oporavak. Madecassoside Smanjuje crvenilo i pomaže koži u obnovi nakon oštećenja, što ga čini odličnim za kožu sklonu iritacijama. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Azelaic A1 Calming Ampoule je koncentrovani serum sa 10% azelaične kiseline koji umiruje upale, reguliše lučenje sebuma i posvetljuje ten. Namenjen je osetljivoj i problematičnoj koži sklonoj aknama, crvenilu i flekama.', 'https://beauty-health.rs/wp-content/uploads/2025/06/VT-Cosmetics-Azelaic-A1-Calming-Ampoule-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
