INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (747, 57, 'Eqqualberry Bakuchiol Plumping Serum', 'eqqualberry-bakuchiol-plumping-serum', 'Ključne prednosti: Prirodni “retinol-alternativ” bez iritacija: Bakuchiol stimuliše obnavljanje kože, smanjuje fine linije i daje glatkiji izgled bez crvenila i perutanja. Dubinska hidratacija i puniji izgled: Hijaluronske kiseline različitih molekularnih težina pune kožu vlagom, zatežu je i čine mekšom. Antioksidativna zaštita: Ekstrakti bobica (npr. šafranice i goji) neutralizuju slobodne radikale i ojačavaju otpornost na stres iz okoline. Kome je namenjen? Serum je pogodan za sve tipove kože, a posebno preporučljiv za zrelu, umornu kožu, kožu sa finim borama ili dehidriranom teksturom. Idealna zamena za retinol kod osetljive kože. Zašto volimo Eqqualberry Bakuchiol Plumping Serum? Eqqualberry serum sadrži bakuchiol, biljni sastojak koji deluje kao retinol bez izazivanja iritacija – stimuliše obnovu ćelija, zaglađuje fine linije i poboljšava tonus kože. Hijaluronske kiseline različitih molekularnih veličina pružaju višeslojnu hidrataciju – od površine do dubljih slojeva, ostavljajući kožu glatkom i punom. Sirupi ekstrakata bobica doprinose antioksidativnoj zaštiti, smanjuju efekat zagađenja i UV oštećenja, dok aminokiseline i biljni peptidi dodatno jačaju elastičnost. Tekstura je lagana, brzo se upija i ne ostavlja osećaj masnoće, čime se savršeno uklapa u dnevnu i večernju rutinu. Aktivni sastojci Bakuchiol Biljna supstitucija retinola koja stimuliše sintezu kolagena, smanjuje pigmentacijske mrlje i fine linije, a pri tom ne izaziva iritaciju ni perutanje. Hijaluronske kiseline (niska i visoka molekularna težina) Vezuju vlagu u više slojeva kože: niže molekule deluju dubinski, a veće ostaju na površini i doprinose dugotrajnoj hidrataciji i punom izgledu. Ekstrakti superbobica (goji, aronija) Snažni antioksidansi koji neutralizuju slobodne radikale i štite kožu od oksidativnog stresa. Aminokiseline i biljni peptidi Podupiru obnovu tkiva i poboljšavaju elastičnost kože prirodnim putem. Tocopherol (vitamin E) Doprinosi zaštiti ćelija od oksidativnog stresa i pojačava efekat antioksidativnih ekstrakata. Dodaj u listu želja Dodaj u listu želja', 'Eqqualberry Bakuchiol Plumping Serum je veganski serum sa bakuchiolom, hijaluronom i antioksidansima, koji stimuliše proizvodnju kolagena, vraća elastičnost i dubinski hidrira kožu bez iritacije. Idealan je za sve koji žele prirodan podmlađivač kože, ali ne podnose retinol.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Eqqualberry-Bakuchiol-Plumping-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
