INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (751, 11, 'Anua Heartleaf 70% Soothing Cream', 'anua-heartleaf-70-soothing-cream', 'Ključne prednosti: Intenzivno umiruje upale i crvenilo: Zahvaljujući 70% ekstrakta Houttuynia Cordata, krema pruža brzo olakšanje iritiranoj i osetljivoj koži. Obnavlja kožnu barijeru: Kombinacija ceramida, panthenola i niacinamida pomaže u obnovi zaštitne funkcije kože i zadržavanju vlage. Hidrira bez osećaja težine: Formulacija bogata humektantima omogućava dubinsku hidrataciju bez masnog filma, pogodna i za masniju i za dehidriranu kožu. Kome je namenjena? Namenjena je osobama sa osetljivom, iritiranom, reaktivnom kožom, kao i onima koji se bore sa crvenilom, nepravilnostima i slabljenjem barijerne funkcije. Posebno je pogodna za korišćenje nakon izlaganja suncu, dermatoloških tretmana ili u stresnim uslovima (vetar, klima, zagađenje). Zašto volimo Anua Heartleaf 70% Soothing Cream? Krema kombinuje tradicionalno korišćeni ekstrakt Houttuynia Cordata – poznat po svojim antibakterijskim i umirujućim svojstvima – sa savremenim dermatološkim sastojcima koji štite i jačaju kožu. Tekstura je lagana i prijatna, brzo se upija i ne ostavlja osećaj težine. Efekti su vidljivi kroz smanjenje crvenila, blaži osećaj kože i bolju otpornost na spoljne iritanse. Redovnim korišćenjem, koža postaje vizuelno ujednačenija, mekša i manje reaktivna. Aktivni sastojci Houttuynia Cordata ekstrakt (70%) Ova biljka ima snažan antiinflamatorni, antibakterijski i antioksidativni efekat. Pomaže u ublažavanju iritacija, upala i crvenila, posebno kod kože sklone aknama i osipu. Njeni prirodni flavonoidi jačaju kožnu otpornost i poboljšavaju tonus. Centella Asiatica ekstrakt Doprinosi regeneraciji kože, ubrzava zarastanje mikropovreda, stimuliše sintezu kolagena i deluje umirujuće. Posebno je koristan kod osetljive kože koja pokazuje znake oštećenja. Ceramide NP Esencijalni lipid koji obnavlja i jača kožnu barijeru, sprečava gubitak vlage i štiti od iritacija izazvanih spoljnim faktorima poput UV zračenja i zagađenja. Pantenol (provitamin B5) Umiruje, hidrira i pospešuje regeneraciju površinskog sloja kože. Posebno efikasan kod iritacija izazvanih čišćenjem, vetrom ili upotrebom aktivnih sastojaka. Niacinamid Pomaže u posvetljavanju tamnih mrlja, smanjuje hiperpigmentacije, jača barijernu funkciju i doprinosi ujednačenom tenu. Dodaj u listu želja Dodaj u listu želja', 'Anua Heartleaf 70% Soothing Cream je lagana, ali bogato formulisana krema koja umiruje, hidrira i jača kožu zahvaljujući visokom udelu ekstrakta biljke Houttuynia Cordata (70%). Idealan je izbor za one koji traže efikasnu dnevnu negu za reaktivnu, osetljivu i crvenilu sklonu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/06/Anua-Heartleaf-70-Soothing-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
