INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (752, 174, 'VT Cosmetics Cica Cream Plus', 'vt-cosmetics-cica-cream-plus', 'Ključne prednosti: Umiruje i regeneriše: Centella asiatica u više oblika i propolis zajednički deluju protiv upala i iritacija, ubrzavajući oporavak kože. Obnavlja i jača barijeru: Ceramide NP, beta-glukan i panthenol obnavljaju lipidni sloj kože i štite je od isušivanja i spoljašnjih agresora. Lagana hidratacija bez masnog finiša: Hijaluronska kiselina i glicerin pružaju višeslojnu vlagu bez težine, čineći kožu elastičnom i osveženom. Kome je namenjena? Krema je namenjena osobama sa osetljivom, reaktivnom, suvom, kombinovanom i masnom kožom sklonom crvenilu, iritacijama i narušenoj barijeri. Pogodna i za kožu nakon dermatoloških tretmana ili u stresnim uslovima (vetar, hladnoća, sunce). Zašto volimo VT Cosmetics Cica Cream Plus? Cica Cream Plus spaja dermatološki dokazanu negu sa modernom teksturom pogodnom za svakodnevnu upotrebu. Patentirani CICALIAO kompleks koristi sinergiju četiri oblika Centelle Asiatice i zelenog propolisa kako bi umirio upaljenu, osetljivu i stresiranu kožu. CICAHYALON dodaje višeslojnu hidrataciju zahvaljujući kombinaciji hijaluronske kiseline i biljnih ekstrakata. Ceramidi i panthenol pomažu u jačanju oslabljene barijere i obnavljaju suva, nadražena područja. Krema ima teksturu između gela i mlečne emulzije, lako se razmazuje i brzo upija, bez osećaja težine ili sjaja. Dugoročno, koža postaje ujednačenija, otpornija i vizuelno smirenija. Aktivni sastojci CICALIAO™ kompleks CICALIAO™ je kombinacija četiri aktivna oblika biljke Centella Asiatica (madekasosid, azijatikozid, asiatic acid, madecassic acid) u kombinaciji sa zelenim propolisom. Ova sinergija donosi snažan antiinflamatorni efekat i pomaže u obnavljanju kože oštećene upalama, aknama ili spoljnim stresom. Centella stimuliše sintezu kolagena i ubrzava zarastanje mikropovreda, dok propolis dodatno štiti od bakterija i pruža antioksidativnu podršku. Zajedno jačaju prirodnu barijeru kože i doprinose smanjenju crvenila, osećaja peckanja i suvoće. CICAHYALON™ kompleks Ovaj kompleks kombinuje različite molekularne težine hijaluronske kiseline sa biljnim ovlaživačima kako bi se obezbedila višeslojna hidratacija. Molekuli niske mase prodiru duboko i pune kožu vlagom iznutra, dok oni veće mase ostaju na površini i formiraju zaštitni film koji sprečava isparavanje vode. Rezultat je elastična, mekana koža koja ne oseća zatezanje. CICAHYALON pomaže u održavanju balansa vlažnosti čak i kod osetljivih i dehidriranih tipova kože. Ceramide NP Ceramidi su esencijalni lipidi koji čine barijerni sloj kože. Ceramide NP, specifično, jača strukturu epidermisa i pomaže u očuvanju integriteta kožne barijere, naročito kod osoba sa suvom, oslabljeno hidriranom ili narušenom kožom. Oni deluju kao „cement” između ćelija kože, sprečavajući gubitak vlage i štiteći od iritacija izazvanih spoljnim faktorima poput vetra, UV zračenja i zagađenja. Panthenol (provitamin B5) Panthenol deluje kao snažan umirujući i obnavljajući agens, smanjujući svrab, crvenilo i nelagodnost kod osetljive kože. Pomaže koži da zadrži vlagu, poboljšava elastičnost i ubrzava regeneraciju nakon stresa ili mikrooštećenja. Takođe, smanjuje negativne reakcije koje mogu nastati prilikom korišćenja aktivnih sastojaka u drugim koracima nege. Beta-glukan Prirodni polisaharid ekstrahovan iz zobi ili gljiva koji ima imunomodulatorni i regenerativni efekat na kožu. Beta-glukan stimuliše proizvodnju kolagena, smanjuje reaktivnost kože i pomaže u obnavljanju nakon iritacija ili upala. Takođe pruža dubinsku hidrataciju i jača otpornost kože na spoljne stresore. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica Cream Plus je umirujuća gel-krema namenjena jačanju kožne barijere, smanjenju crvenila i dubinskoj hidrataciji – bez masnog osećaja i iritacija. Formulisana s patentiranim CICALIAO i CICAHYALON kompleksima, idealna je za svakodnevnu upotrebu kod osetljive i problematične kože.', 'https://beauty-health.rs/wp-content/uploads/2025/06/VT-Cosmetics-Cica-Cream-Plus.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
