INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (753, 155, 'Skinfood Acorn Pore Peptide Daily Mask', 'skinfood-acorn-pore-peptide-daily-mask', 'Ključne prednosti: Uklanja nečistoće iz pora. Ekstrakt žira i fini peptidi rade u sinergiji kako bi nežno otpuštili pore i uklonili višak sebuma, sprečavajući nastanak mitisera. Vraća elastičnost i ujednačuje teksturu kože. Peptidi podstiču obnovu kolagena, smanjuju prosijavanje i zatežu kožu, čineći je mekom i ujednačenom. Hidratacija bez težine. Formula sa hijaluronskom kiselinom i glicerinom obezbeđuje vlagu, vraćajući elastičnost bez ostavljanja masnog sloja. Kome je namenjena? Idealna je za kombinovanu, masnu i normalnu kožu sa proširenim porama i nesavršenim tenom. Takođe pogodna za one koji žele svakodnevno osveženje i čistoću bez agresivnih sastojaka. Zašto volimo SKINFOOD Acorn Pore Peptide Daily Mask? Ova maska kombinuje snagu žira, bogatog taninima i antioksidansima, sa blagim peptidima za finu, ali efikasnu negu. Kada se nanese, tanka krema prodiru u pore, otpuštajući sebum i nečistoće, a zatim se lako skida ili ispira. Peptidi deluju nakon čišćenja, vraćajući elastičnost i znatno smanjujući osećaj grube kože. Hidratantni sastojci sprečavaju isušivanje, pa koža ostaje elastična i prijatna na dodir. Bez prejakih čestica ili snažnih kiselina, ova maska je nežna i može se koristiti svakodnevno – pružajući osećaj svežine i čistog tena bez osećaja zatezanja. Aktivni sastojci Ekstrakt žira (Acorn) Prirodni tanini i antioksidansi čine ovaj sastojak idealnim za čišćenje pora i smanjenje viška sebuma, dok ujedno deluje antiinflamatorno. Peptidi Podstiču sintezu kolagena i elastina, poboljšavaju tonus kože i zatežu fine bore i hrapavost. Hijaluronska kiselina Veže vodu u površanim i dubokim slojevima kože, pružajući osećaj punije i elastičnije kože. Glicerin Doprinosi dugoj i stabilnoj hidrataciji, štiteći kožu od osećaja suvoće nakon upotrebe. Beta-glukan Umiruje i regeneriše kožu, uz nikakvu iritaciju – primereno i za najosetljivije tipove kože. Dodaj u listu želja Dodaj u listu želja', 'SKINFOOD Acorn Pore Peptide Daily Mask je svakodnevna maska obogaćena ekstraktom žira i peptidima, koja nežno čisti pore i hidrira kožu bez zatezanja. Uz blagu piling formulu, čini ten čistijim, glatkijim i ujednačenim.', 'https://beauty-health.rs/wp-content/uploads/2025/06/SKINFOOD-Acorn-Pore-Peptide-Daily-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
