INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (754, 143, 'Round Lab 1025 Dokdo Cleanser', 'round-lab-1025-dokdo-cleanser', 'Ključne prednosti: Dubinsko, a blago čišćenje. Kremasta pena drži kožu bez zataljenosti i prekomernog oslobađanja prirodnih ulja. Obogaćen mineralnim kompleksom. Minerali s Dokdo vulkanskih mesta održavaju ravnotežu i jačaju kožu protiv spoljašnjih uticaja. Hidratacija i obnavljanje. Hijaluronska kiselina i glicerin ostavljaju kožu mekom, hidriranom i elastičnom nakon pranja. Kome je namenjen? Najbolji je izbor za sve tipove kože, ali posebno za kombinovanu i normalnu kožu koja traži čistoću bez isušivanja. Idealno rešenje za osetljivu i lako iritiranu kožu kojoj ne odgovaraju agresivni sapuni. Zašto volimo Round Lab 1025 Dokdo Cleanser? Dokdo Cleanser kombinuje snagu vulkanskog minerala i nežne teksture – rezultujući čistom, hidriranom i osveženom kožom bez osećaja zatezanja. Zahvaljujući blagoj formuli, efikasno uklanja meku šminku i zagađenje iz okoline, bez narušavanja kožne barijere. Formula je pažljivo izbalansirana, čime se štiti prirodni pH kože i sprečava preterano izlučivanje sebuma. Penu karakteriše fin mehurić koji klizi kožom i ostavlja prirodan osećaj čistoće, dok hijaluronska kiselina čuva vlagu i elastičnost. Ne sadrži jake deterdžente, parfeme ili boje – što ga čini savršenim za svakodnevnu upotrebu, čak i za najosetljiviju kožu. Redovnom upotrebom, koža postaje ujednačena, blaža i otpornija na spoljašnje faktore. Aktivni sastojci Mineralni kompleks s Dokdo ostrva Bogat vulkanskim mineralima koji hrane kožu, jačaju njenu strukturu i osnažuju je protiv spoljašnjih uticaja. Hijaluronska kiselina Veže vlagu i ostavlja kožu hidriranom, glatkom i mekom, bez osećaja težine. Glicerin Prirodni ovlaživač koji održava elastičnost i sprečava osećaj suvoće nakon pranja. Biljni amino‑kompleks Umiruje, hrani i regeneriše kožu, sprečavajući iritacije. Beta‑glukan Hidrira i podstiče prirodnu obnovu ćelija, jačajući otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Round Lab 1025 Dokdo Cleanser je nežna, ali efikasna pH‑uravnotežena pena za lice, obogaćena mineralima s Dokdo ostrva i hijaluronskom kiselinom, koja temeljno uklanja nečistoće i šminku uz trenutni osećaj svežine i pročišćenja.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Round-Lab-1025-Dokdo-Cleansing-Gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
