INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (755, 12, 'APLB Glutathione Niacinamide Eye Cream', 'aplb-glutathione-niacinamide-eye-cream', 'Ključne prednosti: Ublažava vidljivost podočnjaka. Glutation i niacinamid u visokoj koncentraciji deluju na ujednačavanje boje kože i posvetljavanje tamnih kolutova. Smanjuje fine linije i hidrira. Peptidi i hijaluronska kiselina obnavljaju strukturu kože i povećavaju nivo vlage u tankoj zoni oko očiju. Jača barijeru i štiti kožu. Ceramidi, betain i pantenol umiruju kožu i sprečavaju gubitak vlage, čineći je otpornijom. Kome je namenjena? Ova krema je namenjena osobama sa tamnim podočnjacima, izraženim umorom oko očiju, dehidriranom i osetljivom kožom u toj zoni. Preporučuje se i za preventivnu negu protiv prvih znakova starenja. Zašto volimo APLB Glutathione Niacinamide Eye Cream? Krema koristi 27,4% aktivnog kompleksa Lipo Gluta Niac&#x2122; koji kombinuje glutation – snažan antioksidans poznat po posvetljujućem efektu – i niacinamid koji ujednačava ton i smanjuje pigmentacije. Dodatak peptida pomaže u obnavljanju strukture kože i ublažavanju sitnih bora, dok hijaluronska kiselina hidrira i smanjuje zategnutost. Ceramidi, pantenol i betain pomažu u jačanju barijere kože, čime se sprečava dodatna iritacija i isušivanje. Tekstura je lagana i brzo se upija, bez lepljivosti. Nakon redovne upotrebe, koža oko očiju postaje svetlija, glatkija i manje podložna umoru. Aktivni sastojci Glutation Antioksidans koji pomaže u posvetljavanju kože i smanjenju tamnih kolutova ispod očiju. Niacinamid Deluje protiv hiperpigmentacija, ujednačava ton kože i jača barijeru. Peptidi Stimulišu sintezu kolagena i pomažu u obnavljanju elastičnosti tanke kože oko očiju. Hijaluronska kiselina Vezuje vlagu u koži, smanjuje dehidriran izgled i doprinosi glatkosti. Panthenol i betain Smiruju i hidrira kožu, štiteći je od spoljnih iritacija. Ceramidi Obnavljaju lipidnu barijeru i sprečavaju transepidermalni gubitak vlage. Dodaj u listu želja Dodaj u listu želja', 'APLB Glutathione Niacinamide Eye Cream je pametno formulisana krema za područje oko očiju koja istovremeno deluje protiv umora, tamnih podočnjaka i prvih bora. Sa čak 27,4% Lipo Gluta Niac Complexa, ova formula osvežava pogled i vraća koži elastičnost i svetlost.', 'https://beauty-health.rs/wp-content/uploads/2025/06/APLB-Glutathione-Niacinamide-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
