INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (757, 164, 'Tirtir Waterism Glow Tint', 'tirtir-waterism-glow-tint', 'Ključne prednosti: Hidratacija koja traje: Zahvaljujući moćnoj kombinaciji prirodnih ulja i squalana, usne ostaju mekane, nahranjene i glatke satima – bez isušivanja. Sjaj koji izgleda skupo, a ne lepljivo: Glow finiš koji hvata svetlost, ali ne lepi – za sofisticiran, zdrav izgled usana svaki dan. Boja koja se stapa s tobom: Nijanse koje se prirodno uklapaju s tonom tvojih usana – od suptilnog dnevnog tona do izražajnijeg večernjeg efekta. Kome je namenjen? Za sve koji žele da im usne izgledaju lepo i budu zaista negovane. Idealno za suve, dehidrirane, nežne usne koje ne trpe teške formule. Zašto volimo TIRTIR Waterism Glow Tint? Waterism Glow Tint je kao skincare za tvoje usne – samo što pritom izgleda kao savršeni ruž. Njegova formula je puna hidratantnih sastojaka koji prodiru u kožu usana i ostavljaju ih glatkima i punima, bez perutanja ili zatezanja. S jednim potezom daješ usnama prirodan sjaj, a sa dva – izražajnu boju koja ne gubi intenzitet tokom dana. Ne osećaš ga dok ga nosiš, ali vidiš razliku. Bez lepljivosti, bez osećaja težine – samo pun, mekan, blistav izgled. Aktivni sastojci Squalane Obnavlja zaštitni sloj kože usana i sprečava isušivanje, pružajući dugotrajnu mekoću. Maslinovo ulje Deluje kao prirodni antioksidans – omekšava i štiti od spoljnih agresora. Jojobino ulje Dubinski hidrira i pomaže usnama da zadrže vlagu bez masnog sloja. Ulje semenki grožđa Lagano i hranljivo, brzo se upija i ostavlja usne svilenkastima. Peptidi Daju usnama puniji, zdraviji izgled kroz svakodnevnu regeneraciju. Dodaj u listu želja Dodaj u listu želja', 'Zaboravi na suve, lepljive i teške sjaje – TIRTIR Waterism Glow Tint donosi novu eru za tvoje usne: negu kao balzam, boju kao ruž i sjaj kao staklo. Uz lagani osećaj i postojan finiš, ovaj tint je sve što tvoje usne žele – i ništa što im smeta.', 'https://beauty-health.rs/wp-content/uploads/2025/05/TIRTIR-Waterism-Glow-Tint-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
