INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (758, 48, 'Dr. Althea Jelly Seal Repair Mask', 'dr-althea-jelly-seal-repair-mask', 'Ključne prednosti: Dubinska hidratacija: Kompleks od 10 vrsta hijaluronske kiseline obezbeđuje višeslojno ovlaživanje – iznutra i spolja. Regeneracija i umirenje: Pantenol i madecassoside popravljaju kožnu barijeru i smiruju upale i iritacije. Poboljšan tonus i osvežen izgled: Lotus i polimerna baza zatežu i osvetljavaju kožu, dajući joj zdrav, sjajan finiš. Kome je namenjena? Maska je idealna za suvu, dehidriranu, reaktivnu i umornu kožu kojoj treba trenutni oporavak. Odlična i za sve tipove kože posle izlaganja suncu, vetru, ili kada ti jednostavno treba osveženje. Zašto volimo Dr. Althea Jelly Seal Repair Mask? Jelly Seal Repair Mask je više od obične sheet maske – njen dvoslojni gel materijal prijanja poput druge kože, omogućavajući aktivnim sastojcima da deluju precizno i efikasno. Hijaluronski kompleks dubinski puni kožu vlagom, bez masnog filma ili zagušivanja pora. Panthenol i madecassoside ne samo da smiruju crvenilo već ubrzavaju regeneraciju kože nakon stresa, izlaganja suncu ili dehidratacije. Ekstrakt lotosa osvetljava ten, dok jedinstvena tekstura maske hladi i opušta lice tokom upotrebe. Maska pruža osećaj trenutne svežine, ali i vidljiv efekat zaglađene, zategnute i zdrave kože koji traje. Aktivni sastojci HyalDeca Complex Sadrži deset vrsta hijaluronske kiseline koje prodiru u različite slojeve kože i obezbeđuju višedimenzionalnu hidrataciju – površinski i dubinski. Panthenol (Provitamin B5) Jača kožnu barijeru, smanjuje crvenilo i iritacije, hidrira i pomaže koži da zadrži vlagu. Madecassoside Derivat Centelle Asiatice – snažno deluje protiv upala, regeneriše i umiruje čak i vrlo osetljivu kožu. Ekstrakt lotosa Pruža antioksidativnu zaštitu, osvetljava ten i smanjuje sivilo kože uz efekat prirodnog sjaja. Allantoin Umiruje, omekšava i obnavlja kožu, idealan za osetljive i suve tipove. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Jelly Seal Repair Mask je premium sheet maska u gel formi koja pruža ozbiljan tretman hidratacije i obnove kože – kao mini spa za lice. Zahvaljujući slojevitoj formuli sa hijaluronskom kiselinom i umirujućim sastojcima, ova maska trenutno vraća koži elastičnost, vlagu i sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Dr.-Althea-Jelly-Seal-Repair-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
