INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (759, 81, 'Ilso Super Melting Sebum Softener', 'ilso-super-melting-sebum-softener', 'Ključne prednosti: Rastvara mitisere bez ceđenja: Aktivna formula omekšava i otpušta začepljenja u porama – bez bola, crvenila i oštećenja. Smiruje i balansira: Centella, kamilica i gljiva Ganoderma umiruju kožu dok čiste – bez zatezanja i perutanja. Čista i glatka koža bez stresa: Enzimi rade posao pilinga bez grubih čestica – tvoja koža ostaje mekana, ujednačena i zdrava. Kome je namenjen? Idealan za masnu, kombinovanu i problematičnu kožu sklonu mitiserima, začepljenim porama i preteranom sjaju. Pogodno čak i za osetljivu kožu – formula čisti, a ne iritira. Zašto volimo Ilso Super Melting Sebum Softener? Zaboravi na agresivne tretmane i cediće – Ilso je nova generacija nege pora. Njegova jedinstvena formula topi oksidirani sebum i mitisere kao da nikada nisu postojali. Enzimi papaje nežno skidaju mrtve ćelije, dok biljni ekstrakti obnavljaju i smiruju kožu. Skvalan i glicerin dodaju hidrataciju tamo gde je najpotrebnija, pa koža ostaje mekana i uravnotežena. Posle samo jedne upotrebe, tvoje pore su čistije, lice je osveženo, a ten blistav i gladak. Bez stresa, bez bola, bez iritacije – samo čista i zadovoljna koža. Aktivni sastojci Ekstrakt gljive Ganoderma Lucidum Poznat po svojim antioksidativnim i umirujućim svojstvima, ovaj ekstrakt pomaže u smanjenju upala i crvenila, dok istovremeno jača prirodnu barijeru kože, čineći je otpornijom na spoljašnje uticaje. Ekstrakt kore bele vrbe (Salix Alba) Prirodni izvor salicilne kiseline, ovaj ekstrakt deluje kao blagi eksfolijant, pomažući u uklanjanju mrtvih ćelija kože i otpušavanju pora, što rezultira čistijim i glatkijim tenom. Ekstrakt Centella Asiatica Poznat po svojim regenerativnim i umirujućim svojstvima, ovaj ekstrakt pomaže u obnavljanju oštećene kože, smanjenju upala i poboljšanju elastičnosti kože. Ekstrakt papaje (Carica Papaya) i papain Ovi sastojci deluju kao prirodni enzimi koji pomažu u razgradnji mrtvih ćelija kože i sebuma, omogućavajući njihovo lakše uklanjanje i sprečavajući začepljenje pora. Dodaj u listu želja Dodaj u listu želja', 'Ilso Super Melting Sebum Softener je spa tretman za tvoje pore – uklanja mitisere i višak sebuma bez cedenja i iritacija. Sa enzimima papaje i umirujućim biljkama, ostavlja kožu čistom, smirenom i osveženom, spremnom za sve.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Ilso-Super-Melting-Sebum-Softener.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
