INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (760, 56, 'Elizavecca CER-100 Collagen Coating Hair Muscle Shampoo', 'elizavecca-cer-100-collagen-coating-hair-muscle-shampoo', '﻿ Ključne prednosti: Dubinska regeneracija i jačanje kose. Zahvaljujući kombinaciji hidrolizovanog kolagena i biljnih proteina, šampon obnavlja oštećenu strukturu vlasi, povećava elastičnost i smanjuje lomljenje. Poboljšanje zdravlja kože glave. Ceramidi i prirodni ekstrakti umiruju kožu glave, smanjujući iritacije i perutanje, dok istovremeno jačaju folikule i podstiču rast zdrave kose. Povećanje volumena i sjaja. Formula bogata proteinima dodaje volumen tankoj i beživotnoj kosi, ostavljajući je mekom, sjajnom i lako upravljivom. Kome je namenjen? Ovaj šampon je idealan za osobe sa suvom, oštećenom, hemijski tretiranom ili beživotnom kosom. Takođe je pogodan za one koji žele da poboljšaju zdravlje kože glave i podstaknu rast jače i zdravije kose. Zašto volimo Elizavecca CER-100 Collagen Coating Hair Muscle Shampoo? CER-100 Collagen Coating Hair Muscle Shampoo pruža sveobuhvatnu negu kose i kože glave. Njegova bogata formula sa hidrolizovanim kolagenom i biljnim proteinima dubinski hrani i obnavlja oštećene vlasi, vraćajući im elastičnost i sjaj. Ceramidi jačaju zaštitnu barijeru kože glave, smanjujući iritacije i perutanje, dok prirodni ekstrakti poput propolisa i biljnih fermentisanih sastojaka dodatno umiruju i revitalizuju kožu. Redovnom upotrebom, kosa postaje vidljivo zdravija, jača i otpornija na spoljašnje uticaje, dok koža glave ostaje čista i uravnotežena. Aktivni sastojci Hidrolizovani kolagen Ovaj protein prodire duboko u vlas, obnavljajući oštećene delove i povećavajući elastičnost kose. Pomaže u zadržavanju vlage, čineći kosu mekom i sjajnom. Takođe štiti kosu od daljih oštećenja izazvanih hemijskim tretmanima i toplotom. Ceramide NP Prirodni lipid koji jača zaštitnu barijeru kože glave, sprečava gubitak vlage i štiti od spoljašnjih iritacija. Pomaže u obnavljanju oštećenih delova vlasišta i smanjuje perutanje. Biljni proteini (soja, pšenica, kukuruz, ovas) Ovi proteini hrane i jačaju kosu, povećavajući njen volumen i otpornost. Pomažu u obnavljanju oštećenih vlasi i poboljšavaju teksturu kose. Propolis ekstrakt Prirodni sastojak poznat po svojim antibakterijskim i umirujućim svojstvima. Pomaže u održavanju zdravlja kože glave i sprečava iritacije. Beta-glukan Polisaharid koji hidrira i umiruje kožu glave, smanjujući crvenilo i iritacije. Takođe jača otpornost kože na spoljašnje stresore. Dodaj u listu želja Dodaj u listu želja', 'Elizavecca CER-100 Collagen Coating Hair Muscle Shampoo je hranljivi šampon formulisan da revitalizuje oštećenu i hemijski tretiranu kosu. Obogaćen kolagenom, ceramidima i biljnim proteinima, ovaj šampon jača vlas od korena do vrhova, pružajući dubinsku hidrataciju i obnavljanje.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Elizavecca-CER-100-Collagen-Coating-Hair-Muscle-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
