INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (762, 164, 'Tirtir Mask Fit Make Up Fixer', 'tirtir-mask-fit-make-up-fixer', 'Ključne prednosti: 24h postojanosti: Ne mrda tokom celog dana – čak ni pod maskom. Vodootporna formula: Otporna na znoj, vlagu i dodire. Mikro-mist tehnologija: Ultra fina maglica ravnomerno prekriva lice bez mrlja. Kome je namenjen? Savršen za sve tipove kože, naročito za one koji traže dugotrajan makeup i minimalno popravljanje tokom dana. Zašto volimo TIRTIR Mask Fit Make Up Fixer? Mask Fit Make Up Fixer predstavlja savršen završni korak u rutini šminkanja, obezbeđujući dugotrajnu postojanost bez kompromisa po pitanju udobnosti i izgleda kože. Njegova formula stvara nevidljivi sloj koji štiti šminku od razmazivanja i prenosa, čak i pri nošenju maski. Obogaćen ekstraktom Centella Asiatica, pruža umirujući efekat i dodatnu hidrataciju, ostavljajući kožu svežom i bez osećaja lepljivosti. Fina maglica ravnomerno prekriva lice, ostavljajući mat završnicu bez osećaja težine ili lepljivosti, pogodnu za sve tipove kože. Aktivni sastojci Centella Asiatica ekstrakt Biljka poznata po svom antiinflamatornom i regenerativnom delovanju. Pomaže u smirivanju crvenila i iritacija, dok istovremeno podstiče prirodnu proizvodnju kolagena. Poboljšava elastičnost kože i jača njenu otpornost na spoljašnje uticaje. Zahvaljujući bogatstvu aktivnih komponenti, doprinosi zdravijem i smirenijem tenu. Idealan je za osetljivu i reaktivnu kožu. Ujedno pruža zaštitu od stresa i zagađenja iz okoline. Pentilen glikol Hidratantni agens koji deluje kao humektant – privlači vlagu iz okoline i zadržava je u koži. Omogućava dugotrajnu hidrataciju i povećava osećaj prijatnosti na koži. Takođe poboljšava efikasnost i raspodelu ostalih aktivnih sastojaka. Blag i neiritirajući, čest je u formulama za osetljivu kožu. Poboljšava ravnomerno nanošenje spreja bez isušivanja. Podržava barijernu funkciju kože. Butilen glikol Ovlaživač koji pomaže u vezivanju vlage i održavanju mekoće kože. Deluje sinergijski sa ostalim hidratantnim komponentama. Omogućava bolju apsorpciju i stabilnost formule. Prikladan je za svakodnevnu upotrebu i za sve tipove kože. Pruža dodatnu vlažnost bez masnog osećaja. Podržava kožu da ostane glatka i zaštićena. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit Make Up Fixer je fiksator šminke koji obezbeđuje dugotrajnu postojanost šminke do 24 sata , čak i pri nošenju zaštitnih maski. Obogaćen ekstraktom Centella Asiatica , pruža umirujući efekat i dodatnu hidrataciju, ostavljajući kožu svežom i bez osećaja lepljivosti.', 'https://beauty-health.rs/wp-content/uploads/2025/05/TIRTIR-Mask-Fit-Make-Up-Fixer.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
