INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (763, 174, 'VT Cosmetics Reedle Shot Cleanser', 'vt-cosmetics-reedle-shot-cleanser', 'Ključne prednosti: Dubinsko čišćenje i osveženje: CICA Reedle&#x2122; tehnologija pročišćava pore i poboljšava apsorpciju aktivnih sastojaka. Blaga svakodnevna eksfolijacija: PHA i LHA nežno uklanjaju mrtve ćelije bez iritacije, poboljšavajući teksturu kože. Umirujuće dejstvo: Centella asiatica i propolis umiruju crvenilo, jačaju barijeru i pružaju osećaj svežine. Kome je namenjen? Ovaj čistač je namenjen osobama sa kombinovanom, masnom ili osetljivom kožom koje traže efikasno, ali nežno sredstvo za čišćenje. Idealan je za svakodnevnu upotrebu, posebno kod kože sklone zapušenim porama i iritacijama. Zašto volimo VT Cosmetics Reedle Shot Cleanser? Reedle Shot Cleanser je formulisan za kožu kojoj je potrebno više od običnog čišćenja. CICA Reedle&#x2122; mikroskopski minerali prodiru u kožu – pojačavaju efekat dubinskog čišćenja i stimulišu obnovu kože. PHA i LHA uklanjaju nečistoće i mrtve ćelije, bez narušavanja prirodne barijere. Centella asiatica umiruje kožu i pomaže u regeneraciji, dok propolis deluje protivupalno i antibakterijski. Zahvaljujući nežnoj peni, koža nakon upotrebe ostaje čista, glatka i bez osećaja zatezanja. Aktivni sastojci CICA Reedle&#x2122; tehnologija Inovativna struktura bazirana na prirodnim mineralima u obliku mikroiglica koje prodiru u kožu i pojačavaju efikasnost čišćenja i apsorpcije aktivnih sastojaka. Podstiče mikrocirkulaciju i blagu regeneraciju. Ne oštećuje kožu niti izaziva neprijatnost. Idealna za poboljšanje teksture i efikasniji učinak drugih sastojaka. Posebno korisna kod kože sa proširenim porama. Pruža osećaj laganog pilinga bez trenja. PHA (polihidroksi kiselina) Blaga kiselina koja uklanja mrtve ćelije sa površine kože, bez izazivanja iritacija. Deluje hidratantno, čineći kožu mekom i elastičnom. Idealna za svakodnevnu upotrebu, čak i kod osetljive kože. Poboljšava tonus i osvetljava ten. Podržava glatku teksturu kože. Ne narušava kožnu barijeru. LHA (lipohidroksi kiselina) Derivat salicilne kiseline koji deluje lokalizovano i nežno, prodire duboko u pore i pomaže u njihovom čišćenju. Kontroliše lučenje sebuma i sprečava nastanak akni. Pogodan za reaktivnu i osetljivu kožu. Deluje protivupalno i umanjuje crvenilo. Doprinosi vidno čistijoj koži. Utiče na bolju teksturu i sjaj. Ekstrakt centelle asiatice Umiruje, obnavlja i jača kožnu barijeru. Stimuliše proizvodnju kolagena i ubrzava zaceljivanje. Smanjuje upale i iritacije, idealan za crvenilo i osetljivost. Deluje antioksidativno i poboljšava otpornost kože. Ostavlja kožu hidriranom i zaštićenom. Podržava zdrav izgled tena. Propolis Pruža antibakterijsku zaštitu i pospešuje oporavak kože. Deluje protivupalno i pomaže u balansiranju mikrobioma kože. Hidrira i daje koži ujednačen izgled. Pogodan je za svakodnevnu upotrebu i osetljivu kožu. Smanjuje izraženost nepravilnosti. Povećava prirodnu otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Reedle Shot Cleanser je gel čistač koji kombinuje CICA Reedle&#x2122; tehnologiju sa blagim PHA i LHA kiselinama za dubinsko, ali nežno čišćenje. Uklanja višak sebuma i mrtve ćelije, ostavljajući kožu čistom, smirenom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/05/VT-Cosmetics-Reedle-Shot-Cleanser-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
