INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (764, 174, 'VT Cosmetics Cica Mild Foam Cleanser', 'vt-cosmetics-cica-mild-foam-cleanser', 'Ključne prednosti: Temeljno čišćenje bez isušivanja: Formulacija stvara bogatu, kremastu penu koja uklanja višak sebuma i ostatke šminke bez zatezanja ili suvoće nakon ispiranja. Umiruje i obnavlja osetljivu kožu: Zahvaljujući prisustvu Centella Asiatica i biljnih ekstrakata, deluje antiinflamatorno, smanjuje crvenilo i jača zaštitnu funkciju kože. Idealna za svakodnevnu upotrebu: Blaga pH uravnotežena formula pogodna je za svakodnevno čišćenje, bez iritacija, čak i kod osetljive ili problematične kože. Kome je namenjena? Ova pena za čišćenje namenjena je osobama svih tipova kože , uključujući osetljivu, kombinovanu i masnu kožu sklonu upalama. Idealna je za one koji žele dubinsko, ali blago čišćenje koje ne narušava prirodnu ravnotežu kože. Zašto volimo VT Cosmetics Cica Mild Foam Cleanser? Cica Mild Foam Cleanser je razvijen da kombinuje efikasno čišćenje i dermalnu negu. Njegova bogata pena omogućava dubinsko uklanjanje nečistoća i sebuma, dok nežna formulacija štiti kožu od isušivanja. Ekstrakt Centella Asiatica deluje kao snažan umirujući agens. Pomaže u smanjenju upalnih procesa i regeneraciji kože. Hijaluronska kiselina zadržava vlagu, dok glicerin dodatno omekšava i hidrira kožu. Biljni ekstrakti doprinose svežem i zdravom izgledu kože, ostavljajući je glatkom, čistom i bez osećaja zatezanja. Aktivni sastojci Centella Asiatica ekstrakt Biljka poznata po umirujućim i obnavljajućim svojstvima. Deluje protiv upala i iritacija, stimuliše sintezu kolagena i ubrzava regeneraciju oštećenih delova kože. Posebno korisna kod crvenila, akni i osetljive kože. Jača kožnu barijeru i povećava otpornost na spoljašnje stresore. Njeni aktivni molekuli (asiaticoside, madecassoside) dokazano poboljšavaju elastičnost i teksturu kože. Hijaluronska kiselina Prirodni ovlaživač koji privlači i zadržava vlagu u koži. Pruža trenutnu i dugotrajnu hidrataciju, smanjujući osećaj zatezanja nakon čišćenja. Pomaže u očuvanju glatkoće i elastičnosti kože. Deluje i kao zaštitni sloj koji sprečava transepidermalni gubitak vode. Posebno korisna za suvu, dehidriranu ili osetljivu kožu. Ostavlja kožu punijom i osveženom nakon svake upotrebe. Propolis ekstrakt Prirodni antibakterijski i antiinflamatorni agens. Pomaže u borbi protiv akni i iritacija, dok istovremeno podržava regeneraciju kože. Bogat antioksidansima koji štite kožu od oksidativnog stresa. Doprinosi očuvanju zdravlja i svežine kože. Umiruje upale i ubrzava zaceljivanje oštećenih delova. Koristan za problematičnu i masnu kožu. Biljni ekstrakti (lavanda, nana, ruzmarin, kamilica, frezija) Kombinacija biljaka sa antiseptičkim, antiinflamatornim i osvežavajućim efektima. Deluju sinergijski na smirivanje iritacija i osvežavanje tena. Lavanda i nana pomažu u balansiranju sebuma, dok kamilica umiruje i hladi. Ruzmarin deluje kao antioksidans i poboljšava mikrocirkulaciju. Frezija osvežava kožu i doprinosi prijatnom mirisu. Ova kombinacija je savršen dodatak blago formulisanoj peni. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica Mild Foam Cleanser je blaga, ali efikasna pena za umivanje lica koja temeljno uklanja nečistoće bez narušavanja prirodne barijere kože. Obogaćena ekstraktom Centella Asiatica i hijaluronskom kiselinom, pruža umirujući efekat i dubinsku hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2025/05/VT-Cosmetics-Cica-Mild-Foam-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
