INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (766, 174, 'VT Cosmetics Cica No Sebum UV Powder', 'vt-cosmetics-cica-no-sebum-uv-powder', 'Ključne prednosti: Kontrola sebuma i mat efekat: Silika i skrob apsorbuju višak ulja i ostavljaju kožu glatkom, bez sjaja. Umirivanje i hidratacija: Centela asiatica i hijaluronska kiselina umiruju iritacije i hidriraju kožu tokom dana. Blaga UV zaštita: Cink oksid pruža SPF20 PA++ zaštitu od UVA i UVB zraka bez iritacije. Kome je namenjen? Ovaj puder je idealan za osobe sa masnom, kombinovanom ili osetljivom kožom koje žele da kontrolišu sjaj i dobiju laganu UV zaštitu. Pogodan je i za višestruku upotrebu – na licu, usnama, kosi i telu. Zašto volimo VT Cosmetics Cica No Sebum UV Powder? Cica No Sebum UV Powder je lagan i neprimetan proizvod koji kombinuje negu i funkcionalnost. Zahvaljujući silici i prirodnim skrobovima, trenutno matira kožu i smanjuje vidljivost pora bez osećaja težine. Umirujući ekstrakti centele asiatice pomažu u smanjenju crvenila, dok hijaluronska kiselina održava kožu hidriranom i elastičnom. Cink oksid pruža pouzdanu, ali blagu UV zaštitu, idealnu za svakodnevnu upotrebu, čak i kod osetljive kože. Tekstura pudera omogućava višestruku primenu – preko šminke, na golu kožu ili čak na koren kose. Redovnom upotrebom, koža ostaje sveža, matirana i zaštićena. Aktivni sastojci Silika Upija višak sebuma, matira kožu i pruža baršunasti osećaj. Smanjuje sjaj i produžava trajanje šminke. Pogodna za osetljivu kožu jer ne zapušava pore. Pomaže u održavanju svežeg izgleda tokom dana. Daje glatku i besprekornu završnicu. Ne izaziva iritacije. Cink oksid Mineralni UV filter koji reflektuje UVA i UVB zrake. Ima protivupalna svojstva i pogodan je za osetljivu kožu. Štiti kožu od oštećenja izazvanih suncem. Pruža trenutnu fizičku barijeru bez čekanja. Ne sadrži hemikalije koje mogu izazvati reakcije. Stabilan i efikasan čak i pri znojenju. Ekstrakt centele asiatice Umiruje crvenilo i iritacije, obnavlja kožnu barijeru i stimuliše sintezu kolagena. Pruža antiinflamatorni efekat. Idealna za osetljivu i reaktivnu kožu. Jača otpornost kože na stres. Deluje i kao antioksidans. Održava kožu u ravnoteži. Hijaluronska kiselina Intenzivno hidrira i vezuje vodu u koži, čineći je elastičnom i glatkom. Ne zateže niti isušuje. Kombinuje se sa drugim aktivnim sastojcima za dublje delovanje. Idealna za upotrebu u suvoj zoni lica.Doprinosi osveženom i punijem izgledu kože. Prikladna za sve tipove kože. Niacinamid (vitamin B3) Pomaže u ujednačavanju tena, smanjenju hiperpigmentacija i crvenila. Jača kožnu barijeru i smanjuje gubitak vlage. Ima protivupalni efekat i smanjuje pojavu akni. Pogodan je za svakodnevnu upotrebu.Ubrzava regeneraciju i poboljšava tonus kože. Idealna komponenta u proizvodima za negu kože sklone nepravilnostima. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica No Sebum UV Powder je puder u prahu sa SPF20 PA++ zaštitom, namenjen za kontrolu sebuma, umirivanje kože i pružanje blage UV zaštite. Kombinuje ekstrakt centele asiatice, hijaluronsku kiselinu i niacinamid kako bi pružio mat efekat, smanjio vidljivost pora i ujedno negovao kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/05/VT-Cosmetics-Cica-No-Sebum-UV-Powder.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
