INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (768, 174, 'VT Cosmetics Reedle Shot Vita-Light EyeCream', 'vt-cosmetics-reedle-shot-vita-light-eyecream', 'Ključne prednosti: Ublažava tamne kolutove i osvetljava ten: Niacinamid i vitamin C posvetljuju područje oko očiju i ujednačavaju ton kože. Poboljšava elastičnost i smanjuje bore: Retinol, adenosin i glutathione deluju sinergijski na fine linije i opuštenost kože. Dubinska hidratacija i umirenje: Skvalan, pantenol i centella asiatica umiruju kožu i obnavljaju njenu barijernu funkciju. Kome je namenjena? Ova krema je namenjena osobama sa izraženim znakovima umora oko očiju – tamnim kolutovima, borama i opuštenošću. Pogodna je za sve tipove kože, uključujući i osetljivu, zahvaljujući blagoj i efikasnoj formuli. Zašto volimo VT Cosmetics Reedle Shot Vita-Light EyeCream? Reedle Shot Vita-Light Eye Cream koristi CICA Reedle&#x2122; tehnologiju – mikročestice prirodnog porekla koje deluju kao mikrostimulatori za bolju apsorpciju aktivnih sastojaka. Zahvaljujući visokoj koncentraciji niacinamida i stabilnog oblika vitamina C, koža postaje svetlija i ujednačenija. Pantenol, squalane i ekstrakt centelle asiatice deluju umirujuće i obnavljaju zaštitnu barijeru, dok adenosin i retinol ciljano deluju na smanjenje bora i poboljšanje elastičnosti. Metalna masažna glava sa mikrosoničnim vibracijama dodatno poboljšava cirkulaciju i ubrzava efekat. Redovnom upotrebom, područje oko očiju postaje osveženo, zategnuto i revitalizovano. Aktivni sastojci Niacinamid (vitamin B3) Posvetljuje kožu, smanjuje pojavu tamnih kolutova i ujednačava ten. Deluje protivupalno i jača barijeru kože. Ublažava fleke i poboljšava elastičnost. Pogodan za svakodnevnu upotrebu. Pruža ujednačen, osvetljen izgled kože. Posebno efikasan kod hiperpigmentacija. Vitamin C (askorbinska kiselina) Antioksidans koji posvetljuje ten i stimuliše sintezu kolagena. Smanjuje znakove starenja i štiti kožu od oksidativnog stresa. Poboljšava blistavost kože. Koristi se za osvetljavanje područja ispod očiju. Smanjuje hiperpigmentaciju i podstiče svež izgled. Pantenol (provitamin B5) Hidrirajući i umirujući sastojak koji pomaže u regeneraciji kože. Poboljšava elastičnost i štiti od iritacija. Sprečava isušivanje i crvenilo. Pruža osećaj udobnosti i hidratacije. Doprinosi glatkoj teksturi kože. Idealan za osetljivo područje oko očiju. Ekstrakt centelle asiatice Umiruje, regeneriše i štiti kožu. Pomaže u zaceljivanju mikrooštećenja i jača barijernu funkciju. Smanjuje upale i crvenilo. Doprinosi otpornosti kože. Poboljšava tonus i ublažava osetljivost. Idealan za svakodnevnu negu. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Reedle Shot Vita-Light EyeCream osvetljava i podmlađuje predeo oko očiju uz CICA Reedle&#x2122; tehnologiju, vitamine i anti-age komplekse. Metalni aplikator s mikrovibracijama pojačava efekat – za svež, blistav i odmoran pogled.', 'https://beauty-health.rs/wp-content/uploads/2025/05/VT-Cosmetics-Reedle-Shot-Vita-Light-EyeCream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
