INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (769, 174, 'VT Cosmetics Cica Collagen Cream', 'vt-cosmetics-cica-collagen-cream', 'Ključne prednosti: Povećava elastičnost kože: Niskomolekularni kolagen (300 Da) prodire duboko u kožu, poboljšavajući njenu čvrstoću i smanjujući fine linije. Intenzivna hidratacija: Kompleks hijaluronske kiseline u tri oblika osigurava višeslojnu hidrataciju, čineći kožu mekom i elastičnom. Umirujuće dejstvo: Ekstrakt centele asiatice i ceramidi pomažu u smanjenju crvenila i iritacija, jačajući prirodnu zaštitnu barijeru kože. Kome je namenjena? Ova krema je idealna za osobe sa suvom, osetljivom ili zrelom kožom, kao i za one koji žele da poboljšaju elastičnost i hidrataciju kože. Pogodna je za svakodnevnu upotrebu i sve tipove kože zahvaljujući svojoj blagoj i hranljivoj formuli. Zašto volimo VT Cosmetics Cica Collagen Cream ? Cica Collagen Cream kombinuje efikasne sastojke kako bi pružila sveobuhvatnu negu kože. Niskomolekularni kolagen (300 Da) iz aljaške ribe omogućava duboku apsorpciju, poboljšavajući elastičnost i čvrstoću kože. Kompleks hijaluronske kiseline u tri oblika pruža višeslojnu hidrataciju, dok ekstrakt centele asiatice umiruje iritacije i crvenilo. Ceramidi jačaju kožnu barijeru, štiteći je od spoljašnjih agresora. Redovnom upotrebom, koža postaje vidljivo hidrirana, elastična i zdravijeg izgleda. Aktivni sastojci Hidrolizovani kolagen (300 Da) Niskomolekularni kolagen omogućava duboku apsorpciju u kožu, poboljšavajući njenu elastičnost i čvrstoću. Pomaže u smanjenju vidljivosti finih linija i bora, čineći kožu glatkom i zategnutom. Redovnom upotrebom, koža postaje čvršća i mladalačkog izgleda. Kompleks hijaluronske kiseline Sastoji se od tri oblika hijaluronske kiseline koji pružaju višeslojnu hidrataciju. Pomaže u zadržavanju vlage u koži, čineći je mekom i elastičnom. Takođe poboljšava teksturu kože i smanjuje osećaj zategnutosti. Ekstrakt centele asiatice Poznat po svojim umirujućim i regenerativnim svojstvima, pomaže u smanjenju crvenila i iritacija. Takođe podstiče sintezu kolagena, poboljšavajući elastičnost kože. Pogodan je za osetljivu i reaktivnu kožu. Ceramidi (NP, NS, AS, EOP, AP) Ovi lipidi jačaju prirodnu zaštitnu barijeru kože, štiteći je od spoljašnjih agresora. Pomažu u zadržavanju vlage i sprečavaju isušivanje kože. Takođe poboljšavaju teksturu i otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica Collagen Cream je hidratantna krema koja kombinuje niskomolekularni kolagen (300 Da) i ekstrakt centele asiatice za poboljšanje elastičnosti kože i umirivanje iritacija. Formulisana je za dubinsku hidrataciju, jačanje kožne barijere i vidljivo smanjenje znakova starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/05/VT-Cosmetics-Cica-Collagen-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
