INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (771, 159, 'Sungboon Editor Deep Collagen Power Boosting Mask', 'sungboon-editor-deep-collagen-power-boosting-mask', 'Ključne prednosti: Intenzivna hidratacija i elastičnost: Kombinacija hijaluronske kiseline i peptida pruža dubinsku hidrataciju, poboljšava elastičnost kože i smanjuje vidljivost finih linija. Poboljšanje teksture i tonusa kože: Kolagen niske molekulske mase prodire dublje u kožu, pomažući u obnavljanju strukture kože i poboljšanju njenog tonusa. Umirujući efekat i osveženje: Ekstrakti mente pružaju trenutni osećaj hlađenja, umiruju kožu i smanjuju crvenilo. Kome je namenjena? Ova maska je idealna za osobe sa suvom, dehidriranom kožom, kao i za one koji primećuju prve znake starenja, poput finih linija i gubitka elastičnosti. Takođe je pogodna za sve tipove kože, uključujući i osetljivu, zahvaljujući svojoj blagoj formuli. Zašto volimo Sungboon Editor Deep Collagen Power Boosting Mask? Deep Collagen Power Boosting Mask pruža intenzivnu negu zahvaljujući visokoj koncentraciji kolagena niske molekulske mase, koji prodire dublje u kožu, poboljšavajući njenu strukturu i elastičnost. Devet različitih peptida stimulišu prirodnu proizvodnju kolagena, dok hijaluronska kiselina zadržava vlagu, čineći kožu hidriranom i glatkom. Ekstrakti mente pružaju osvežavajući efekat, smanjujući crvenilo i iritacije. Redovnom upotrebom, koža postaje vidljivo čvršća, glatkija i blistavija, sa smanjenim vidljivim porama i finim linijama. Aktivni sastojci Kolagen niske molekulske mase (2.160.000 ppb) Ovaj tip kolagena ima manju molekulsku masu, što omogućava dublje prodiranje u kožu, poboljšavajući njenu elastičnost i čvrstoću. Pomaže u smanjenju finih linija i bora, dajući koži mladalački izgled. Hijaluronska kiselina Prirodni ovlaživač koji zadržava vlagu u koži, pružajući dubinsku hidrataciju. Pomaže u održavanju glatke i elastične kože, smanjujući suvoću i perutanje. Peptidi (9 tipova) Ovi mali proteinski fragmenti stimulišu proizvodnju kolagena i elastina, poboljšavajući strukturu kože. Deluju anti-age, smanjujući vidljivost bora i poboljšavajući tonus kože. Niacinamid (Vitamin B3) Poznat po svojim svojstvima ujednačavanja tena i smanjenja hiperpigmentacija. Takođe poboljšava barijernu funkciju kože i smanjuje upale. Ekstrakti mente (Mentha Piperita, Mentha Viridis, Mentha Rotundifolia) Pružaju osvežavajući i umirujući efekat, smanjujući crvenilo i iritacije. Takođe imaju blago antiseptičko dejstvo, pomažući u održavanju čiste kože. Dodaj u listu želja Dodaj u listu želja', 'Sungboon Editor Deep Collagen Power Boosting Mask je hidrogel maska obogaćena sa 2.160.000 ppb kolagena niske molekulske mase, 9 tipova peptida i hijaluronskom kiselinom, za dubinsku hidrataciju i poboljšanje elastičnosti kože. Namenjena je svima koji žele da umanje fine linije, poboljšaju tonus kože i postignu efekat &#8220;staklene kože&#8221;.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Sungboon-Editor-Deep-Collagen-Power-Boosting-Mask-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
