INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (772, 164, 'Tirtir Hydro Boost Enzyme Powder Wash', 'tirtir-hydro-boost-enzyme-powder-wash', 'Ključne prednosti: Efikasna, a blaga eksfolijacija: Enzimi i PHA kiseline otklanjaju mrtve ćelije i pročiste pore bez narušavanja barijere kože. Ujednačavanje i osvežavanje tena: Ekstrakti mungo pasulja i pirinča pomažu u smanjenju mitisera, posvetljavanju kože i poboljšanju teksture. Očuvanje hidratacije i jačanje barijere: Probiotici, manitol i alantoin pomažu u očuvanju vlažnosti i otpornosti kože. Kome je namenjen? Ovaj čistač je namenjen osobama sa masnom, kombinovanom ili osetljivom kožom , kao i svima koji žele svakodnevnu, ali nežnu eksfolijaciju. Pogodan je i za kožu sklonu mitiserima i neujednačenom tenu, jer ne isušuje niti iritira. Zašto volimo TIRTIR Hydro Boost Enzyme Powder Wash? Hydro Boost Enzyme Powder Wash predstavlja ravnotežu između temeljne čistoće i očuvanja prirodne hidratacije. Njegova jedinstvena praškasta formula se aktivira vodom, pri čemu se oslobađaju enzimi i PHA kiseline koji nežno uklanjaju mrtve ćelije i višak sebuma. Ekstrakti mungo pasulja i pirinča dodatno posvetljuju i omekšavaju kožu. Probiotici doprinose zdravoj mikroflori kože. Alantoin i manitol pomažu u smanjenju crvenila i iritacija, pružajući umirujući efekat. Redovnom upotrebom, ten postaje svežiji, pore čistije, a tekstura glađa. Proizvod ne sadrži sulfate ni agresivne sastojke, što ga čini pogodnim za svakodnevnu upotrebu. Aktivni sastojci Gluconolakton (PHA) Pruža nežnu eksfolijaciju bez iritacije, uklanjajući mrtve ćelije sa površine kože. Pomaže u hidrataciji i jačanju zaštitne barijere. Pogodan je za osetljivu kožu zahvaljujući svom blagom delovanju. Ima antioksidativna svojstva i pomaže u ujednačavanju tena. Održava kožu glatkom i zdravom. Idealan je za svakodnevnu upotrebu. Papain Enzim iz papaje koji razgrađuje mrtve ćelije kože i pomaže u njihovom uklanjanju. Poboljšava teksturu kože i smanjuje mitisere. Deluje blago i ne izaziva iritacije, čak ni kod osetljive kože. Ima i umirujuće osobine. Ostavlja kožu čistom i svežom. Koristi se za nežno, ali efikasno čišćenje. Bromelain Enzim iz ananasa koji razgrađuje proteine mrtvih ćelija, pomažući u njihovom uklanjanju. Ima protivupalna svojstva i smanjuje crvenilo. Pomaže u osvežavanju i izjednačavanju tona kože. Blag je i pogodan za svakodnevnu upotrebu. Smanjuje otoke i poboljšava teksturu. Ostavlja kožu glatkom i pročišćenom. Alantoin Umiruje kožu, smanjuje crvenilo i pomaže u obnavljanju oštećenih slojeva. Podstiče regeneraciju i hidrataciju. Blag je i prikladan za sve tipove kože. Štiti kožu od spoljašnjih iritansa. Održava kožu glatkom i otpornom. Koristi se u nezi osetljive kože zbog svoje podnošljivosti. Ekstrakt pirinča (Oryza Sativa) Bogat antioksidansima i mineralima koji posvetljuju kožu i poboljšavaju njenu teksturu. Umiruje i obnavlja osetljivu kožu. Ujednačava ten i čini ga svetlijim. Hidrira i omekšava površinu kože. Tradicionalno se koristi u azijskoj kozmetici zbog svojih blagotvornih efekata. Pogodan za redovnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Hydro Boost Enzyme Powder Wash je enzimski čistač u prahu koji se u kontaktu s vodom pretvara u bogatu penu, omogućavajući nežno, ali temeljno čišćenje. Obogaćen enzimima, PHA kiselinama, probioticima i prirodnim ekstraktima mungo pasulja i pirinča, ovaj proizvod efikasno uklanja mrtve ćelije, mitisere i nečistoće bez iritacije kože.', 'https://beauty-health.rs/wp-content/uploads/2025/05/TIRTIR-Hydro-Boost-Enzyme-Powder-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
