INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (774, 154, 'Skin1004 Madagascar Centella Tone Brightening Cleansing Gel Foam', 'skin1004-madagascar-centella-tone-brightening-cleansing-gel-foam', 'Ključne prednosti: Ujednačava ton kože i pruža osvetljavajući efekat: MADEWHITE&#x2122; tehnologija deluje ciljano na tamne fleke, neujednačen ten i sivilo kože, čineći ten svetlijim i blistavijim. Umiruje i jača kožnu barijeru: Ekstrakt centelle asiatice iz Madagaskara obnavlja kožu, smanjuje crvenilo i deluje protivupalno. Blaga formula bez iritacija: Gel pena je pH-balansirana, ne sadrži sulfate i pogodna je za svakodnevnu upotrebu i osetljivu kožu. Kome je namenjen? Ovaj proizvod je idealan za osobe koje imaju umoran, neujednačen ten, tamne fleke i hiperpigmentacije , kao i za one sa osetljivom i reaktivnom kožom . Pogodan za sve tipove kože, uključujući masnu i kombinovanu. Zašto volimo Madagascar Centella Tone Brightening Cleansing Gel Foam? Tone Brightening Cleansing Gel Foam pruža više od običnog čišćenja – njegova formulacija istovremeno neguje i osvetljava kožu. Zahvaljujući ekskluzivnoj tehnologiji MADEWHITE&#x2122; , gel pomaže u smanjenju pigmentacija i vraća prirodnu blistavost tena. Centella asiatica umiruje kožu, dok nežna pH 5.5 formula ne narušava zaštitnu barijeru. Pri kontaktu s vodom pretvara se u bogatu, svilenkastu penu koja temeljno uklanja zagađenja i ostatke SPF-a, a da pri tom ne izaziva osećaj zatezanja. Redovnim korišćenjem, koža postaje osvežena, glatka i vidljivo ujednačenija. Idealan je kao prvi korak ujutru i uveče za one koji žele čist ten bez iritacija. Aktivni sastojci Centella Asiatica Centella Asiatica je poznata po svojoj sposobnosti da regeneriše i umiruje kožu. U ovom čistaču koristi se visokopurifikovani ekstrakt sa Madagaskara koji obnavlja oštećenu barijeru, smanjuje crvenilo i štiti kožu od spoljašnjih stresora. Deluje protivupalno i pomaže u zarastanju mikrooštećenja, što ga čini pogodnim i za osetljivu i aknoznu kožu. MADEWHITE&#x2122; (Patentirana tehnologija) MADEWHITE&#x2122; je ekskluzivni patentirani sastojak izveden iz centelle asiatice, specifično formulisan za osvetljavanje tena. Ciljano deluje na tamne fleke i znakove hiperpigmentacije, sprečavajući dalje formiranje melanina. Njegovo dejstvo je postepeno, ali izuzetno efikasno uz redovnu upotrebu. Niacinamid Niacinamid, poznat i kao vitamin B3, deluje kao multifunkcionalni sastojak koji poboljšava teksturu kože, smanjuje vidljivost pora i ujednačava ten. U ovoj formuli dodatno pojačava efekat MADEWHITE&#x2122; kompleksa, dajući koži blistav i zdrav izgled. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Tone Brightening Gel Foam je pH-uravnotežen čistač koji nežno uklanja nečistoće i osvetljava ten. Zahvaljujući centelli sa Madagaskara i MADEWHITE&#x2122; tehnologiji, umiruje kožu i ostavlja je svežom i blistavom – bez osećaja zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2025/05/SKIN1004-Madagascar-Centella-Tone-Brightening-Cleansing-Gel-Foam.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
