INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (775, 159, 'Sungboon Editor Active Marine Astaxanthin Capsule Serum', 'sungboon-editor-active-marine-astaxanthin-capsule-serum', 'Ključne prednosti: Smanjenje hiperpigmentacija i ujednačavanje tena: Kombinacija astaksantina, glutationa, niacinamida i traneksaminske kiseline deluje sinergijski na smanjenje tamnih fleka i ujednačavanje boje kože. Dubinska hidratacija i obnova barijere kože: Hijaluronska kiselina, beta-glukan, ceramidi i glicerin pružaju intenzivnu hidrataciju, poboljšavajući elastičnost i čvrstoću kože. Antioksidativna zaštita i anti-age efekat: Astaksantin, vitamin E i ferulična kiselina štite kožu od oksidativnog stresa, usporavajući proces starenja i poboljšavajući ukupni izgled kože. Kome je namenjen? Ovaj serum je idealan za osobe sa neujednačenim tenom, tamnim flekama, melazmom ili znakovima starenja, kao i za one sa suvom, osetljivom ili dehidriranom kožom. Zašto volimo Sungboon Editor Active Marine Astaxanthin Capsule Serum? Active Marine Astaxanthin Capsule Serum koristi naprednu tehnologiju kapsuliranja kako bi osigurao stabilnost i efikasnost svojih aktivnih sastojaka. Astaksantin, snažan antioksidans, štiti kožu od slobodnih radikala i smanjuje oksidativni stres. Glutation i niacinamid deluju na posvetljivanje kože i smanjenje hiperpigmentacija. Traneksaminska kiselina dodatno pomaže u inhibiciji sinteze melanina, čime se postiže ujednačeniji ten. Hijaluronska kiselina, beta-glukan i ceramidi obnavljaju i jačaju kožnu barijeru, pružajući dubinsku hidrataciju i poboljšavajući elastičnost kože. Redovnom upotrebom, koža postaje vidljivo svetlija, hidrirana i revitalizovana, sa smanjenim znakovima starenja i poboljšanom teksturom. Aktivni sastojci Astaksantin Astaksantin je snažan antioksidans dobijen iz morskih algi, poznat po svojoj sposobnosti da neutralizuje slobodne radikale do 6.000 puta efikasnije od vitamina C. Ovaj sastojak pomaže u zaštiti ćelija kože od oksidativnog stresa i UV oštećenja, čime usporava proces starenja. Redovnom primenom, astaksantin doprinosi poboljšanju elastičnosti i tonusa kože. Takođe smanjuje crvenilo i inflamaciju, čineći ga pogodnim i za osetljivu kožu. Astaksantin u kapsulama zadržava stabilnost do trenutka nanošenja, što omogućava maksimalnu efikasnost. Glutation Glutation je prirodni antioksidans koji ima snažno delovanje u posvetljavanju kože i smanjenju tamnih fleka. Deluje tako što inhibira enzim tirozinazu, čime smanjuje sintezu melanina i doprinosi ujednačenijem tenu. U kombinaciji sa astaksantinom i niacinamidom, pojačava efekat protiv hiperpigmentacija. Glutation takođe štiti ćelije kože od toksina i oštećenja izazvanih UV zračenjem. Ima regenerativno dejstvo, poboljšava oporavak kože i čini je vidno blistavijom. Niacinamid (Vitamin B3) Niacinamid je multifunkcionalni aktivni sastojak koji smanjuje vidljivost pora, ujednačava ten i poboljšava teksturu kože. Deluje protiv upala, što ga čini pogodnim za kožu sklonu aknama i iritacijama. Niacinamid inhibira prenos melanina u gornje slojeve kože, čime doprinosi posvetljavanju hiperpigmentacija. Osim toga, jača kožnu barijeru i povećava sintezu ceramida, čime se poboljšava hidratacija. Traneksaminska kiselina Traneksaminska kiselina deluje tako što blokira mehanizme u koži odgovorne za hiperpigmentaciju, posebno u slučajevima melazme. Sprečava aktivaciju melanocita izazvanu UV zračenjem i upalnim procesima. Njena sposobnost da inhibira sintezu melanina čini je izuzetno efikasnom u ujednačavanju tona kože. Dodatno, pomaže u smanjenju crvenila i osetljivosti kože. Ovaj sastojak je klinički dokazan kao sigurna i efikasna opcija za tretman neujednačene pigmentacije. Dodaj u listu želja Dodaj u listu želja', 'Sungboon Editor Active Marine Astaxanthin Capsule Serum sadrži 78% ekstrakta pasjeg trna, astaksantin, niacinamid i glutation za posvetljivanje tena, ujednačavanje boje kože i dubinsku hidrataciju. Moćna formula za posvetljivanje tena, smanjenje hiperpigmentacija i dubinsku hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Sungboon-Editor-Active-Marine-Astaxanthin-Capsule-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
