INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (776, 154, 'Skin1004 Madagascar Centella Tea-Trica Spot Cream', 'skin1004-madagascar-centella-tea-trica-spot-cream', 'Ključne prednosti: Brzo smiruje upaljena i bolna mesta: Aktivni biljni ekstrakti ublažavaju crvenilo i otoke bez isušivanja kože. Antibakterijsko delovanje koje sprečava ponovni nastanak akni: Tea-Trica kompleks uništava bakterije koje izazivaju akne i čisti pore. Ciljana nega bez iritacije i ljuštenja: Formulacija je nežna i pogodna i za osetljivu kožu, bez agresivnih sastojaka. Kome je namenjena? Ova spot krema je idealna za osobe sa lokalnim nepravilnostima , posebno upalnim aknama, mitiserima i bolnim potkožnim bubuljicama. Preporučuje se svim tipovima kože, uključujući osetljivu i reaktivnu , jer ne izaziva iritacije ni ljuštenje. Zašto volimo SKIN1004 Madagascar Centella Tea-Trica Spot Cream? Tea-Trica Spot Cream pruža snažnu, ali balansiranu negu za problematične regije na licu. Umiruje upale već nakon prve upotrebe zahvaljujući visokom sadržaju centelle asiatice sa Madagaskara , dok čajevac deluje antibakterijski i pročišćava pore. Specijalna Tea-Trica formula dodatno poboljšava efikasnost tretmana, a ekstrakti biljnih kiselina pomažu nežno uklanjanje mrtvih ćelija sa površine kože. Kremasta, nemasna tekstura lako se nanosi i brzo upija bez ostavljanja tragova, što je čini idealnom i za upotrebu tokom dana. Praktičan aplikator omogućava precizno i higijensko nanošenje. Dugoročnim korišćenjem, koža postaje čistija, glatkija i manje sklona aknama. Aktivni sastojci Centella Asiatica Centella Asiatica je ključni sastojak ove kreme, poznat po svojim snažnim regenerativnim i umirujućim efektima. Deluje protiv crvenila, ubrzava zarastanje rana i smanjuje rizik od ožiljaka. U ovoj formuli koristi se visokokoncentrovani ekstrakt sa Madagaskara, bogat aktivnim komponentama kao što su madecassoside i asiaticoside. Idealna je za kožu koja je osetljiva i sklona iritacijama, jer ne izaziva dodatna oštećenja. Čajevac (Melaleuca Alternifolia) Čajevac je prirodni antiseptik koji efikasno deluje protiv bakterija odgovornih za akne. Umiruje kožu, čisti pore i smanjuje lučenje sebuma, bez izazivanja suvoće. Njegova sposobnost da neutrališe upalne procese čini ga neizostavnim sastojkom za ciljanu negu. Tea-Trica kompleks Tea-Trica je vlasnička kombinacija ekstrakta čajevca, centelle i biljnih kiselina koje deluju sinergijski – umiruju, čiste i balansiraju kožu. Ovaj kompleks je posebno efikasan u sprečavanju širenja infekcija i formiranja novih akni, dok istovremeno štiti kožnu barijeru. Salicilna kiselina (BHA) Salicilna kiselina pomaže da se pore temeljno očiste iznutra i da se smanji rizik od nastanka komedona. Ima blago eksfolijativno delovanje, ali u ovoj formuli je u niskoj koncentraciji kako bi ostala pogodna i za osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Tea-Trica Spot Cream je ciljana krema za akne i iritacije, sa centellom, čajevcem i blagim eksfolijantima. Umiruje, čisti i ubrzava nestanak nepravilnosti bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/05/SKIN1004-Madagascar-Centella-Tea-Trica-Spot-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
