INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (779, 154, 'Skin1004 Madagascar Centella Tone Brightening Glow Mask', 'skin-1004-madagascar-centella-tone-brightening-glow-mask', 'Ključne prednosti: Ujednačava ten i umanjuje tamne fleke: Aktivni sastojci kao što su niacinamid i traneksaminska kiselina deluju sinergijski na smanjenje pigmentacija i fleka. Umiruje osetljivu kožu zahvaljujući centelli: Ekstrakt Centella Asiatica pruža antiinflamatorni efekat i pomaže u oporavku oštećene kože. Lagani materijal maske bez zagušenja pora: Proizvedena od prozračnih mikrofibera, maska se savršeno prilagođava konturama lica. Kome je namenjena? Ova maska je idealna za osobe sa tamnim flekama, neujednačenim tenom i beživotnom kožom , kao i za one koji žele blistav i osvežen izgled bez opterećujućih sastojaka. Namenjena je i osetljivoj koži koja ne podnosi agresivne posvetljujuće tretmane. Zašto volimo SKIN 1004 Madagascar Centella Tone Brightening Glow Mask? Glow Mask kombinuje posvetljujuću negu sa umirujućim svojstvima centelle, pružajući balansiran pristup nezi kože. Inovativna ampula formulacija obogaćena ekstraktom centelle sa Madagaskara deluje kao antiinflamatorni štit za reaktivnu kožu, dok niacinamid i traneksaminska kiselina ciljano utiču na nepravilnosti u tonu kože. Maska nežno posvetljuje, vraća elastičnost i hidrira, bez izazivanja crvenila ili osećaja težine. Mikrofiber tkanina čvrsto prijanja uz kožu i omogućava bolju penetraciju aktivnih sastojaka, dok blago kisela pH vrednost doprinosi očuvanju prirodne barijere kože. Nakon upotrebe, koža izgleda osveženo, ujednačeno i blistavo, sa vidljivim smanjenjem umora i sivila. Aktivni sastojci Ekstrakt Centella Asiatica Centella Asiatica je lekovita biljka poznata po svojim regenerativnim i umirujućim svojstvima. U ovoj formuli koristi se visokokoncentrovani ekstrakt sa Madagaskara, bogat aktivnim komponentama kao što su madekasosid, azijatikosid i azijatska kiselina. Deluje protivupalno, stimuliše sintezu kolagena i ubrzava zaceljivanje mikropovreda. Posebno je efikasan kod osetljive kože sklone crvenilu i iritacijama. Njegovo prisustvo doprinosi stabilnosti kožne barijere i otpornosti na spoljašnje faktore. Niacinamid Niacinamid (vitamin B3) je moćan osvetljivač kože koji ujednačava ten, smanjuje tamne mrlje i poboljšava elastičnost. Deluje i kao antioksidans, štiti od slobodnih radikala i reguliše proizvodnju sebuma. Pored efekta posvetljavanja, pomaže u zatvaranju pora i poboljšava teksturu kože. Njegova blagost ga čini pogodnim za svakodnevnu upotrebu i za osetljivu kožu. Traneksaminska kiselina Traneksamska kiselina je aktivni sastojak poznat po svojoj sposobnosti da inhibira sintezu melanina, čime se smanjuju tamne mrlje i hiperpigmentacija. Koristi se kao alternativa agresivnijim posvetljujućim tretmanima, jer ne izaziva iritacije. Idealna je za kožu sa postupalnim flekama ili melazmom. U sinergiji sa niacinamidom i centellom, omogućava vidljiv efekat posvetljavanja bez opterećivanja kože. 3-O-Ethyl Ascorbic Acid 3-O-Ethyl Ascorbic Acid je stabilizovani derivat vitamina C sa snažnim antioksidativnim i posvetljujućim svojstvima. Ova forma vitamina C ne oksidira lako i deluje efikasno bez izazivanja iritacija. Stimuliše sintezu kolagena, smanjuje pigmentacije i vraća koži prirodan sjaj. Pruža dodatnu zaštitu od UV oštećenja i slobodnih radikala. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Tone Brightening Glow Mask osvetljava i umiruje kožu uz pomoć centelle, niacinamida i traneksamske kiseline. Lagana sheet maska koja pruža hidrataciju bez iritacija, za blistav i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/05/SKIN-1004-Madagascar-Centella-Tone-Brightening-Glow-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
