INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (780, 154, 'Skin1004 Madagascar Centella Probio-Cica Bakuchiol Eye Cream', 'skin1004-madagascar-centella-probio-cica-bakuchiol-eye-cream', 'Ključne prednosti: Anti-age efekat bez iritacija zahvaljujući bakuchiolu: Prirodna alternativa retinolu podstiče sintezu kolagena, smanjuje fine linije i poboljšava elastičnost bez rizika od crvenila ili suvoće. Umiruje i jača kožu oko očiju uz Probio-Cica kompleks: Sinergija fermentisane centelle i probiotika pomaže u obnovi kožne barijere i smanjenju nadraženosti u ovoj delikatnoj zoni. Vidljivo osvežava pogled i smanjuje tamne kolutove: Aktivni posvetljujući sastojci ujednačavaju ton kože i umanjuju znakove umora. Kome je namenjena? Ova krema je idealna za osobe sa osetljivom kožom oko očiju, vidljivim borama, tamnim kolutovima i gubitkom čvrstoće. Namenjena je i onima koji žele preventivnu i regenerativnu negu bez iritirajućih sastojaka kao što su tradicionalni retinoidi. Zašto volimo SKIN1004 Madagascar Centella Probio-Cica Bakuchiol Eye Cream? Probio-Cica Bakuchiol Eye Cream donosi inovativan pristup anti-age nezi područja oko očiju, kombinujući regenerativne prednosti centelle iz Madagaskara sa blagim, ali snažnim delovanjem bakuchiola. Umorna i suva koža oko očiju postaje elastičnija i hidriranija, a fine linije vidno umanjene. Fermentisani ekstrakt centelle deluje na obnavljanje kožne barijere, dok probiotici podržavaju mikrobiotsku ravnotežu kože. Kremasta, ali lagana tekstura brzo se upija, ostavljajući kožu glatkom i osveženom. Redovnom upotrebom, područje oko očiju postaje svetlije, odmornije i otpornije na stresne faktore i znakove starenja. Aktivni sastojci Centella Asiatica Centella Asiatica sa Madagaskara je poznata po visokom sadržaju madekasosida i azijatikozida – komponenti koje pomažu u regeneraciji kože i zaceljivanju mikropovreda. Ova biljka smanjuje upale i ojačava kapilare, što je ključno za delikatnu zonu oko očiju. Takođe poboljšava elastičnost kože i podstiče sintezu kolagena, što doprinosi smanjenju bora. Njen efekat umirivanja je izuzetno koristan kod natečenosti i crvenila. U ovoj kremi koristi se fermentisani oblik centelle koji omogućava bolju apsorpciju i efikasnost. Bakuchiol Bakuchiol je biljna alternativa retinolu, koja ima slične anti-age efekte ali bez potencijalnih nuspojava poput perutanja i suvoće. Stimuliše proizvodnju kolagena i obnavlja strukturu kože, čineći je glatkom i čvrstom. Deluje na smanjenje bora i poboljšava teksturu, dok ujedno posvetljuje i ujednačava ton. Bezbedan je za upotrebu tokom dana i noći, čak i za osetljivu kožu. Njegova prisutnost u ovoj kremi čini je pogodnom za korisnike koji žele efekte retinola bez kompromisa po pitanju nežnosti. Probio-Cica kompleks Probio-Cica kompleks predstavlja kombinaciju fermentisanih komponenti centelle i probiotika, koji zajednički deluju na obnavljanje zaštitne barijere i mikrobiotske ravnoteže kože. Ovaj kompleks smanjuje reaktivnost kože i pomaže joj da se brže oporavi od oštećenja. Poboljšava otpornost kože na stres, UV faktore i zagađenje. Takođe povećava sposobnost kože da zadrži vlagu i smanjuje iritacije. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Probio-Cica Bakuchiol Eye Cream je nežna, ali efikasna okoloočna krema koja spaja umirujuću centellu i biljni retinol – bakuchiol. Smanjuje fine bore, tamne kolutove i natečenost, dok istovremeno jača barijeru kože i vraća svežinu umornom pogledu.', 'https://beauty-health.rs/wp-content/uploads/2025/05/SKIN1004-Madagascar-Centella-Probio-Cica-Bakuchiol-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
