INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (783, 143, 'Round Lab Mugwort Calming Serum', 'round-lab-mugwort-calming-serum', 'Ključne prednosti: Umiruje upale i iritacije kože: Zahvaljujući pelinu bogatom flavonoidima i antioksidansima, serum efikasno smanjuje crvenilo, svrab i osećaj zatezanja. Jača prirodnu barijeru kože: Podstiče regeneraciju i otpornost kože, štiteći je od zagađenja, UV stresa i dehidratacije. Lagana gelasta tekstura bez lepljivosti: Brzo se upija i ne opterećuje kožu, ostavljajući je osveženom, umirenom i spremnom za naredne korake u rutini. Kome je namenjen? Serum je formulisan za osetljivu, iritiranu, reaktivnu i kombinovanu kožu koja je sklona crvenilu, upalama i dehidrataciji. Idealan je i za kožu pogođenu aknama, stresom ili čestim spoljašnjim uticajima poput zagađenja i vremenskih promena. Zašto volimo Round Lab Mugwort Calming Serum? Mugwort Calming Serum je odgovor na potrebe savremene kože koja je svakodnevno izložena stresorima – bilo da je reč o UV zračenju, zagađenju ili preteranoj upotrebi agresivnih proizvoda. Svojim snažnim umirujućim delovanjem, pelin odmah smanjuje osećaj nelagodnosti, dok ostali biljni sastojci sinergijski rade na obnovi oštećenih slojeva kože. Rezultat je vidljivo ujednačeniji i zdraviji ten, bez osećaja peckanja, perutanja ili masnog filma. Serum se brzo upija i savršeno se uklapa u dnevnu i noćnu rutinu. Aktivni sastojci Ekstrakt pelina (Artemisia Capillaris Extract) Pelin je poznat u tradicionalnoj korejskoj medicini po svom protivupalnom, antibakterijskom i detoksikacionom delovanju. U ovom serumu koristi se visokokoncentrovani ekstrakt korejskog pelina iz regije Ganghwa, koji umiruje i obnavlja osetljivu kožu bez izazivanja iritacija. Bogat je flavonoidima i vitaminima koji pomažu u zaštiti kože od oksidativnog stresa. Takođe sadrži prirodne sastojke koji deluju protiv bakterija i akni, što ga čini pogodnim za problematičnu i upaljenu kožu. Madecassoside Madecassoside je aktivna komponenta biljke Centella Asiatica, poznata po svom regenerativnom i umirujućem efektu. Efikasno smanjuje upalne procese u koži, stimuliše proizvodnju kolagena i ubrzava zarastanje oštećenja. U kombinaciji sa pelinom, pojačava efekat umirivanja i obnavljanja, posebno kod crvenila, osipa i mikropovreda. Dodatno, jača funkciju kožne barijere i pomaže koži da zadrži vlagu. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Mugwort Calming Serum smiruje, hidrira i štiti osetljivu kožu uz moć korejskog pelina. Bogat antiinflamatornim sastojcima, pomaže regeneraciju i vraća balans koži izloženoj spoljašnjim stresorima.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Round-Lab-Mugwort-Calming-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
