INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (784, 143, 'Round Lab Birch Moisturizing Sheet Mask', 'round-lab-birch-moisturizing-sheet-mask', 'Ključne prednosti: Dubinska hidratacija zahvaljujući soku breze: Prirodni sok bele breze bogat mineralima i aminokiselinama brzo prodire u kožu, vraćajući vlagu i pružajući osećaj hlađenja i osveženja. Umiruje osetljivu i reaktivnu kožu: Formula je idealna za kožu sklonu crvenilu i iritacijama, zahvaljujući blagim i biljnim sastojcima koji deluju protivupalno i regenerišuće. Tanka i prijanjajuća sheet struktura: Maska je izrađena od laganog, bio-razgradivog materijala koji se savršeno prilagođava konturama lica i omogućava maksimalnu apsorpciju aktivnih sastojaka. Kome je namenjena? Ova maska je idealna za dehidriranu, osetljivu i umornu kožu kojoj je potrebna brza rehidratacija i umirenje. Pogodna je za sve tipove kože, uključujući masnu i kombinovanu, naročito kada je koža izložena stresu, klimatskim promenama ili nakon izlaganja suncu. Zašto volimo Round Lab Birch Moisturizing Sheet Mask? Birch Moisturizing Sheet Mask predstavlja spoj tradicionalnih korejskih biljnih sastojaka i savremenog pristupa njezi kože. Sok bele breze, poznat po svojoj sposobnosti zadržavanja vlage, deluje direktno na ćelijski nivo, poboljšavajući tonus i vitalnost kože. Uz svakodnevnu upotrebu ili kao SOS tretman, maska trenutno osvežava lice, umanjuje zategnutost i vraća prirodan sjaj. Njena lagana tkanina omogućava da esencija uđe duboko u epiderm, bez ostavljanja lepljivog osećaja. Pored hidratacije, aktivni sastojci podstiču regeneraciju kože i poboljšavaju barijernu funkciju, čineći je otpornijom na spoljašnje stresore. Koža je nakon tretmana meka, elastična i vizuelno odmorna. Aktivni sastojci Sok bele breze (Betula Platyphylla Japonica Juice) Sok bele breze je bogat antioksidansima, mineralima (kalijum, kalcijum, magnezijum) i aminokiselinama koje obnavljaju nivo vlažnosti u koži. Deluje umirujuće i antiinflamatorno, pa je izuzetno koristan za tretiranje crvenila, upala i iritacija. Osim toga, podstiče proizvodnju prirodnog hijalurona u koži, čime se postiže dugoročna hidratacija. Njegova lagana struktura brzo se upija, bez zagušivanja pora, što ga čini pogodnim i za masnu i za kombinovanu kožu. Takođe, pomaže u regulaciji sebuma i balansiranju pH vrednosti kože. U ovoj sheet maski, sok breze je glavni nosilac osvežavajuće i regenerišuće funkcije. Hijaluronska kiselina Hijaluronska kiselina je moćan humektant koji može vezati do 1000 puta više vode od svoje mase. U ovoj formuli, pomaže koži da zadrži vlagu i smanjuje transepidermalni gubitak vode. Koža postaje zaglađena, elastična i vizuelno punija. Posebno je korisna za tretman dehidrirane kože, bez obzira na njen tip. Pored hidratacije, hijaluronska kiselina doprinosi boljoj apsorpciji ostalih aktivnih sastojaka. Redovnom upotrebom doprinosi dugotrajnom osećaju mekoće i zdravog sjaja. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Birch Moisturizing Sheet Mask pruža trenutni „boost” hidratacije zahvaljujući soku korejske bele breze. Umiruje, osvežava i jača kožu već nakon prve upotrebe – idealna za dane kada koži treba dodatna nega i balans.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Round-Lab-Birch-Moisturizing-Sheet-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
