INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (786, 137, 'Purito Luminous Moisture Shea Butter Body Lotion', 'purito-luminous-moisture-shea-butter-body-lotion', 'Ključne prednosti: Intenzivna hidratacija: Ši buter i glicerin dubinski hidriraju kožu, čineći je glatkom i elastičnom. Obnavljanje kožne barijere: Fermentisano ulje semena kamelije i ekstrakt Jeju Starflower biljke jačaju i regenerišu kožnu barijeru. Bez iritacija: Formulacija bez alergena i sintetičkih mirisa, pogodna za osetljivu kožu. Kome je namenjen? Ovaj losion je idealan za osobe sa suvom, osetljivom ili dehidriranom kožom koje traže proizvod koji pruža dugotrajnu hidrataciju bez osećaja težine ili masnoće. Pogodan je za sve tipove kože, uključujući i najosetljivije. Zašto volimo Purito Luminous Moisture Shea Butter Body Lotion? Luminous Moisture Shea Butter Body Lotion pruža koži intenzivnu i dugotrajnu hidrataciju zahvaljujući kombinaciji prirodnih sastojaka. Ši buter bogat esencijalnim masnim kiselinama i vitaminima A i E hrani i omekšava kožu, dok fermentisano ulje semena kamelije brzo prodire u dublje slojeve kože, zadržavajući vlagu i poboljšavajući njenu elastičnost. Ekstrakt Jeju Starflower biljke, poznat po svojoj sposobnosti zadržavanja vlage, dodatno doprinosi hidrataciji i revitalizaciji kože. Lagana, mlečna tekstura losiona brzo se upija, ostavljajući kožu mekom, glatkom i bez lepljivog osećaja. Aktivni sastojci Ši buter (Butyrospermum Parkii) Prirodni emolijent bogat esencijalnim masnim kiselinama i vitaminima A i E. Pruža dubinsku hidrataciju, omekšava kožu i pomaže u obnavljanju njene elastičnosti. Takođe ima protivupalna svojstva koja umiruju iritiranu kožu. Fermentisano ulje semena kamelije (Camellia Japonica Seed Oil) Lako se apsorbuje i bogato je antioksidansima, pomažući u zaštiti kože od slobodnih radikala. Fermentacija poboljšava njegovu sposobnost prodiranja u kožu, pružajući dubinsku hidrataciju i poboljšavajući teksturu kože. Ekstrakt Jeju Starflower biljke (Stellaria Media) Poznat po svojoj sposobnosti zadržavanja vlage, ovaj ekstrakt pomaže u hidrataciji i revitalizaciji suve i osetljive kože. Takođe ima umirujuća svojstva koja pomažu u smanjenju crvenila i iritacija. Glicerin Prirodni humektant koji privlači vlagu iz okoline u kožu, održavajući je hidriranom i mekom. Takođe pomaže u jačanju kožne barijere i poboljšava elastičnost kože. Lactobacillus ferment Probiotski sastojak koji pomaže u održavanju zdrave mikroflore kože, jačajući njenu prirodnu odbranu i smanjujući osetljivost. Candida Bombicola/Glucose/Methyl Rapeseedate Ferment Fermentisani sastojak koji deluje kao prirodni emolijent, poboljšavajući hidrataciju i elastičnost kože. Dodaj u listu želja Dodaj u listu želja', 'Purito Luminous Moisture Shea Butter Body Lotion je bogat, ali lagan veganski losion koji dubinski hrani i umiruje suvu kožu. Zahvaljujući ši buteru, fermentisanom ulju kamelije i Jeju Starflower ekstraktu, vraća mekoću, elastičnost i prirodan sjaj već nakon prvog nanošenja.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Purito-Luminous-Moisture-Shea-Butter-Body-Lotion-Midnight-Romance.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
