INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (789, 131, 'Parnell Cicamanu 92 Serum', 'parnell-cicamanu-92-serum', 'Ključne prednosti: Trenutno umiruje crvenilo i iritacije: Klinički je dokazano da serum smanjuje crvenilo kože za 21,67% u roku od 60 sekundi. Hidratacija i jačanje barijere: Kombinacija Centella Asiatica, madekasoida i manuka meda pruža intenzivnu hidrataciju i regeneraciju. Pogodan za osetljivu kožu: Bez agresivnih sastojaka, formulisan da smiri, osveži i ojača čak i najreaktivniju kožu. Kome je namenjen? Cicamanu 92 Serum je namenjen osobama sa osetljivom, crvenilom sklonom, iritiranom ili reaktivnom kožom. Idealan je i za one koji žele da umire kožu nakon izlaganja UV zračenju, pilinga, upotrebe aktivnih sastojaka ili nakon profesionalnih tretmana. Zašto volimo Parnell Cicamanu 92 Serum? Serum koristi Parnell DFS sistem koji kombinuje tri ključna elementa: Centella Asiatica, Cicamanu ekstrakt i melatonin. Centella Asiatica i madekasoidi deluju regenerativno i protivupalno, dok melatonin poboljšava noćni oporavak kože i štiti od oksidativnog stresa. Manuka med dodatno hrani i štiti kožu, čineći je otpornijom i glatkijom. Formulacija je klinički testirana i dokazana u efikasnosti – već nakon jedne upotrebe koža pokazuje smanjeno crvenilo i poboljšanu elastičnost. Njegova gelasta tekstura se lako upija i ne ostavlja masni film, što ga čini pogodnim za dnevnu i noćnu upotrebu, samostalno ili u kombinaciji sa drugim proizvodima. Aktivni sastojci Centella Asiatica ekstrakt Biljka poznata po svojim moćnim antiinflamatornim i regenerativnim svojstvima. Pomaže u umirivanju iritacija, zaceljivanju oštećenja i jačanju kapilara. Takođe pospešuje sintezu kolagena, čime doprinosi čvrstoći kože i boljoj strukturi. Cicamanu ekstrakt Proprietarni sastojak koji kombinuje fermentisane derivate Centelle Asiatice sa hranljivim biljnim komponentama. Ima intenzivan efekat umirivanja i ubrzava obnavljanje kože, idealan za reaktivne i oslabljene tenove. Melatonin Poznat po svojoj ulozi u regeneraciji tokom noći, melatonin u ovoj formuli deluje kao snažan antioksidans. Štiti ćelije kože od oksidativnog stresa, pomaže u prevenciji prevremenog starenja i poboljšava oporavak kože tokom sna. Ekstrakt manuka meda Bogata supstanca sa antibakterijskim i hranljivim svojstvima. Hidrirajući i umirujući efekti čine ga idealnim za grubu, dehidriranu ili oštećenu kožu. Takođe doprinosi boljoj apsorpciji drugih aktivnih sastojaka. Madekasozoid Aktivna komponenta Centelle Asiatice sa snažnim regenerativnim dejstvom. Umiruje iritiranu kožu, smanjuje crvenilo i upalne procese, te pomaže u zaštiti i obnovi kožne barijere. Lactobacillus Ferment Fermentisani sastojak koji poboljšava teksturu i otpornost kože, balansira mikrobiom i smanjuje osetljivost. Idealan je za kožu kojoj nedostaje otpornost i balans. Dodaj u listu želja Dodaj u listu želja', 'Parnell Cicamanu 92 Serum je umirujući serum visoke koncentracije koji sadrži 92% Centella Asiatica kompleksa i Cicamanu™ ekstrakta, obogaćen melatoninom i manuka medom. Klinički dokazano smanjuje crvenilo i pruža trenutno olakšanje osetljivoj koži – već u prvom minutu. Hidrira, umiruje i jača kožnu barijeru, ostavljajući ten vidljivo uravnoteženim i negovanim.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Parnell-Cicamanu-92-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
