INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (790, 129, 'OOTD Star Spot Patch', 'ootd-star-spot-patch', 'Ključne prednosti: Efikasna apsorpcija i zaštita: Hidrogel tehnologija omogućava snažnu apsorpciju nečistoća iz akni, dok istovremeno štiti zahvaćeno područje od spoljašnjih faktora. Posvetljivanje i umirenje kože: Niacinamid pomaže u smanjenju hiperpigmentacija i crvenila, doprinoseći ujednačenijem tenu. Obnova kožne barijere: Ceramidi i hidrogenizovani lecitin jačaju prirodnu barijeru kože, sprečavajući dehidrataciju i iritacije. Kome su namenjeni? OOTD Star Spot Patch je idealan za osobe sa masnom i aknama sklonom kožom koje traže diskretno i efikasno rešenje za tretiranje pojedinačnih nepravilnosti. Pogodni su za sve tipove kože, uključujući i osetljivu. Zašto volimo OOTD Star Spot Patch? Zato što spajaju cool dizajn i ozbiljnu negu! Ovi šareni zvezdasti flasteri nisu tu samo da izgledaju slatko – njihova hidrogel formula upija nečistoće, smiruje crvenilo i ubrzava zarastanje akni. Niacinamid posvetljuje mrlje, ceramidi i lecitin jačaju kožnu barijeru, a zaštitni sloj sprečava dalje iritacije. Dolaze u pet boja, pa su zabavni za nošenje – bilo da spavaš, učiš ili praviš selfie. Aktivni sastojci Niacinamid Niacinamid, poznat i kao vitamin B3, ima višestruke prednosti za kožu. Deluje protiv upala, reguliše lučenje sebuma i posvetljuje ten, čime umanjuje postupalne mrlje i ujednačava teksturu kože. Takođe jača barijernu funkciju kože, što je ključno kod osoba koje koriste eksfolijante. Ceramidi Ceramidi su ključni lipidi u kožnoj barijeri. Oni pomažu u zadržavanju vlage i zaštiti kože od spoljašnjih uticaja. Njihova prisutnost u formulaciji doprinosi jačanju kožne barijere i smanjenju transepidermalnog gubitka vode. Hidrogenizovani lecitin Hidrogenizovani lecitin je emolijent koji pomaže u obnavljanju i jačanju kožne barijere. Pruža hidrataciju i poboljšava elastičnost kože, čineći je mekšom i otpornijom na spoljašnje agresore. Dodaj u listu želja Dodaj u listu želja', 'OOTD Star Spot Patch su zvezdasti flasteri za akne koji ne samo da izgledaju cool, već i stvarno deluju. Sa niacinamidom i ceramidima, smanjuju crvenilo, ubrzavaju oporavak i štite kožu – savršeni za tvoj #skincareroutine i svaki selfie bez filtera.', 'https://beauty-health.rs/wp-content/uploads/2025/05/OOTD-Star-Spot-Patch.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
