INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (792, 114, 'Medicube PDRN Lip Sleeping Mask', 'medicube-pdrn-lip-sleeping-mask', 'Ključne prednosti: Dubinska hidratacija i obnova: PDRN i kolagen regenerišu kožu usana i poboljšavaju njihovu čvrstoću i elastičnost. Zaštita i umirenje: Ši buter i bisabolol smiruju iritacije i obnavljaju barijernu funkciju usana. Neiritirajuća formula: Bez alkohola, parfema i parabena – pogodna za osetljive usne i svakodnevnu upotrebu. Kome je namenjena? Maska je namenjena osobama sa suvim, osetljivim ili ispucalim usnama, kao i onima koji žele regeneraciju i poboljšanje teksture i volumena usana. Idealna je i za negu usana tokom hladnijih meseci ili nakon izlaganja suncu i vetru. Zašto volimo Medicube PDRN Lip Sleeping Mask? PDRN Lip Sleeping Mask pruža potpunu noćnu negu zahvaljujući regenerativnim, hidratantnim i zaštitnim svojstvima svojih aktivnih sastojaka. PDRN iz lososove DNK stimuliše obnovu ćelija, dok kolagen pomaže u jačanju strukture kože i vidljivo povećava elastičnost usana. Ši buter i bisabolol obezbeđuju bogatu ishranu i umirujuće delovanje, čime se sprečava ljuštenje i nelagodnost. Klinička testiranja potvrđuju povećanje nivoa hidratacije i smanjenje mrtvih ćelija na usnama već posle jedne noći korišćenja. Maska ima glatku, nelepljivu teksturu i blago sjajan finiš, ostavljajući usne osveženim i negovanim do jutra. Aktivni sastojci PDRN (natrijum DNK iz lososa) PDRN je bioaktivna komponenta koja podstiče regeneraciju kože i sintezu kolagena. U kontekstu nege usana, pomaže u obnavljanju oštećenih i isušenih delova, čineći ih glatkijim, elastičnijim i otpornijim na spoljne uticaje. Hidrolizovani kolagen Kolagen je ključan za očuvanje čvrstoće i jedrine kože. Hidrolizovani oblik omogućava bolju apsorpciju i dublje delovanje, poboljšavajući volumen i punoću usana, istovremeno zadržavajući vlagu u dubljim slojevima kože. Ši buter (Butyrospermum Parkii) Prirodni emolijent sa bogatim sadržajem vitamina A i E koji pruža duboku hidrataciju i štiti usne od isušivanja. Takođe poseduje umirujuće i antiinflamatorne osobine, pomažući u regeneraciji ispucale kože. Bisabolol Biljni ekstrakt poznat po blagom i efikasnom umirujućem dejstvu. Deluje protiv crvenila i iritacija, posebno koristan kod preosetljive kože usana i nakon izlaganja nepovoljnim vremenskim uslovima. Adenozin Snažan anti-age sastojak koji doprinosi smanjenju finih linija i bora, poboljšava elastičnost kože i deluje regenerativno, čineći usne vizuelno mlađim i glatkijim. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Lip Sleeping Mask je intenzivna noćna nega za suve i ispucale usne, obogaćena PDRN-om iz lososove DNK, kolagenom i ši buterom. Dubinski hidrira, regeneriše i omekšava, ostavljajući usne punijim, mekšim i elastičnijim već nakon prve noći. Lagana tekstura bez lepljenja – za savršeno negovane usne do jutra.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Medicube-PDRN-Lip-Sleeping-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
