INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (793, 84, 'Isntree Hyaluronic Acid Fresh Sun Serum SPF50+', 'isntree-hyaluronic-acid-fresh-sun-serum', 'Ključne prednosti: Napredna UV zaštita bez iritacije: Pet savremenih UV filtera pružaju širokospektralnu zaštitu od UVA i UVB zračenja, bez izazivanja peckanja očiju ili osećaja težine. Dubinska hidratacija i obnova barijere: Višestruki oblici hijaluronske kiseline, skvalan i ektoin zajedno deluju na zadržavanje vlage i jačanje kožne barijere. Idealna baza za šminku: Serumasta tekstura se brzo upija, ostavljajući prirodan, nemastan finiš bez belog traga, pogodna za svakodnevnu upotrebu i slojevito nanošenje. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom, dehidriranom, masnom ili kombinovanom kožom, kao i za one sklone aknama. Preporučuje se svima koji traže visok nivo zaštite od sunca uz dodatne benefite hidratacije i umirenja kože. Zašto volimo Isntree Hyaluronic Acid Fresh Sun Serum? Hyaluronic Acid Fresh Sun Serum predstavlja inovativan pristup zaštiti od sunca, kombinujući efikasne UV filtere sa bogatim hidratantnim sastojcima. Njegova lagana, serumasta tekstura omogućava brzo upijanje bez osećaja težine ili masnoće, čineći ga idealnim za svakodnevnu upotrebu, čak i ispod šminke. Višeslojna hijaluronska kiselina različitih molekulskih težina obezbeđuje dubinsku hidrataciju, dok skvalan i ektoin jačaju kožnu barijeru i štite od spoljašnjih stresora. Dodatni sastojci poput niacinamida i pantenola pomažu u ujednačavanju tena i umirenju kože, čineći ovaj serum sveobuhvatnim rešenjem za zaštitu i negu kože. Aktivni sastojci Hijaluronska kiselina (u više oblika) Ova formulacija sadrži različite oblike hijaluronske kiseline, uključujući natrijum hijaluronat, hidroksipropiltrimonijum hijaluronat i natrijum acetiliran hijaluronat. Ovi sastojci deluju sinergijski kako bi obezbedili hidrataciju u svim slojevima kože, poboljšavajući njenu elastičnost i glatkoću. Redovnom upotrebom, koža postaje vidljivo hidrirana i osvežena. Skvalan Skvalan je prirodni emolijent koji imitira lipide koje koža sama proizvodi. Pomaže u očuvanju vlage i jačanju kožne barijere, ne zapušava pore i pogodan je za sve tipove kože, uključujući masnu i osetljivu. Skvalan poboljšava teksturu kože, čineći je mekom i glatkom. Alantoin Alantoin je poznat po svojim umirujućim i regenerativnim svojstvima. Pomaže u smanjenju iritacija, pospešuje zarastanje kože i poboljšava njenu glatkoću. Njegova prisutnost u formulaciji doprinosi smanjenju crvenila i osećaja nelagodnosti na koži. Ektoin Ektoin je prirodni sastojak koji štiti ćelije od stresa izazvanog UV zračenjem i zagađenjem. Pomaže u očuvanju hidratacije, jača kožnu barijeru i smanjuje upalne procese, čineći kožu otpornijom i zdravijom. Niacinamid (Vitamin B3) Niacinamid je multifunkcionalni sastojak koji pomaže u poboljšanju barijerne funkcije kože, smanjenju upala i regulaciji proizvodnje sebuma. Takođe je efikasan u smanjenju hiperpigmentacija i ujednačavanju tona kože. Njegova antiinflamatorna svojstva čine ga pogodnim za kožu sklonu aknama i rozacei. Dodaj u listu želja Dodaj u listu želja', 'Isntree Hyaluronic Acid Fresh Sun Serum je lagani hemijski SPF 50+ PA++++ serum koji kombinuje višeslojnu hidrataciju sa naprednom UV zaštitom. Formulisan je sa 8 vrsta hijaluronske kiseline, skvalanom, alantoinom i ektoinom, pružajući koži svežinu, elastičnost i zaštitu bez masnog osećaja ili belog traga.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Isntree-Hyaluronic-Acid-Fresh-Sun-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
