INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (794, 104, 'Laneige Radian-C Sun Cream', 'laneige-radian-c-sun-cream', 'Ključne prednosti: Napredna UV zaštita: Kombinacija savremenih filtera pruža širokospektralnu zaštitu od UVA i UVB zračenja bez belog traga i bez masnog osećaja. Ujednačavanje tena: Derivat vitamina C i Melasolv™ deluju sinergijski kako bi posvetlili ten i smanjili izraženost pigmentacija. Obnavljanje kožne barijere: Pantenol i ceramidi pomažu u očuvanju vlage i jačaju zaštitni sloj kože, čineći je otpornijom na spoljne agresore. Kome je namenjena? Krema je idealna za osobe sa normalnom, suvom i kombinovanom kožom koje žele visoku UV zaštitu uz dodatne efekte posvetljivanja i hidratacije. Posebno je pogodna za kožu sklonu flekama, neujednačenom tonu i fotostarenju. Zašto volimo Laneige Radian-C Sun Cream? Radian-C Sun Cream kombinuje efikasnu zaštitu od sunca sa naprednom negom kože. Njena lagana tekstura se brzo upija i ne ostavlja beli trag, što je čini pogodnom za svakodnevnu upotrebu, čak i ispod šminke. Zahvaljujući derivatu vitamina C i Melasolv™ kompleksu, posvetljuje ten, smanjuje hiperpigmentacije i sprečava nastanak novih mrlja. Pantenol umiruje iritacije, dok ceramidi obnavljaju barijeru kože i zadržavaju vlagu. Aktivni sastojci 3-O-Etil askorbinska kiselina (derivat vitamina C) Stabilan oblik vitamina C koji ima snažno antioksidativno delovanje. Deluje na posvetljivanje tena, smanjuje tamne mrlje i štiti kožu od oksidativnog stresa izazvanog UV zračenjem. Za razliku od čistog vitamina C, ovaj derivat je stabilniji, manje iritira kožu i duže zadržava efikasnost. Melasolv™ Patentirani sastojak koji utiče na regulaciju sinteze melanina, glavnog uzroka pigmentacija. Klinički je ispitan i pokazao je visok stepen efikasnosti u smanjenju postojećih mrlja i ujednačavanju tena, bez izazivanja iritacija. Ceramid NP Ceramidi su ključni lipidi u kožnoj barijeri. Ceramid NP jača tu barijeru, sprečava gubitak vlage i čini kožu otpornijom na spoljašnje štetne uticaje. Idealni su za suvu i osetljivu kožu, kao i za prevenciju preuranjenog starenja. UV filteri (hemijski i fizički) Kombinacija modernih filtera (kao što su Diethylamino Hydroxybenzoyl Hexyl Benzoate, Homosalat, Ethylhexyl Salicylate) i mineralnog filtera titanijum dioksida obezbeđuje široku zaštitu od UVB i UVA zračenja. Ova formulacija je pogodna za osetljivu kožu, ne iritira oči i ne ostavlja beli trag. Dodaj u listu želja Dodaj u listu želja', 'Laneige Radian-C Sun Cream SPF50+ PA++++ pruža naprednu zaštitu i osvetljava ten u jednom koraku. Zahvaljujući moćnoj kombinaciji UV filtera, derivata vitamina C i Melasolv™ sastojka, ova lagana SPF krema štiti kožu od štetnog zračenja, smanjuje tamne mrlje i vraća prirodan sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Laneige-Radian-C-Sun-Cream-SPF50.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
