INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (798, 84, 'Isntree Onion Newpair Soothing Mask', 'isntree-onion-newpair-soothing-mask', 'Ključne prednosti: Umiruje i obnavlja osetljivu kožu: Ekstrakt crvenog luka i centela azijatika deluju sinergijski kako bi smanjili upale i pospešili regeneraciju kože. Intenzivna hidratacija: Višestruki oblici hijaluronske kiseline pružaju dubinsku hidrataciju, poboljšavajući elastičnost i glatkoću kože. Ujednačava ton kože: Traneksaminska kiselina i niacinamid pomažu u smanjenju tamnih mrlja i posvetljavanju tena. Kome je namenjena? Ova maska je idealna za osobe sa osetljivom, suvom ili iritiranom kožom, kao i za one koji se bore sa postinflamatornim hiperpigmentacijama i neujednačenim tonom kože. Pogodna je za sve tipove kože, uključujući i kožu sklonu aknama. Zašto volimo Isntree Onion Newpair Soothing Mask? Onion Newpair Soothing Mask koristi moćne sastojke za pružanje sveobuhvatne nege kože. Ekstrakt crvenog luka bogat je antioksidansima i sumpornim jedinjenjima koji pomažu u smanjenju upala i pospešuju zarastanje kože. Višestruki oblici hijaluronske kiseline obezbeđuju hidrataciju u svim slojevima kože, poboljšavajući njenu elastičnost i glatkoću. Traneksaminska kiselina i niacinamid deluju na smanjenje tamnih mrlja i ujednačavanje tena. Centela azijatika dodatno umiruje kožu i pospešuje njenu regeneraciju. Maska pruža osvežavajući efekat hlađenja, čineći je idealnom za upotrebu nakon izlaganja suncu ili u stresnim uslovima. Aktivni sastojci Ekstrakt crvenog luka (Allium Cepa Bulb Extract) Ekstrakt crvenog luka bogat je antioksidansima i sumpornim jedinjenjima koji pomažu u smanjenju upala i pospešuju zarastanje kože. Takođe je poznat po svojoj sposobnosti da poboljša izgled ožiljaka i hiperpigmentacija. Njegova antibakterijska svojstva čine ga korisnim za kožu sklonu aknama. U kombinaciji sa drugim umirujućim sastojcima, ekstrakt crvenog luka doprinosi smanjenju crvenila i iritacija. Njegova prisutnost u maski pruža koži dodatnu zaštitu i podršku u regeneraciji. Hijaluronska kiselina (u više oblika) Hijaluronska kiselina u različitim molekulskim težinama obezbeđuje hidrataciju u svim slojevima kože. Visokomolekularni oblici formiraju zaštitni sloj na površini kože, dok niskomolekularni prodiru dublje, pružajući dugotrajnu hidrataciju. Ova kombinacija poboljšava elastičnost kože, smanjuje pojavu finih linija i čini kožu glatkom i hidriranom. Redovnom upotrebom, hijaluronska kiselina doprinosi zdravijem i mladalačkijem izgledu kože. Traneksaminska kiselina Traneksaminska kiselina je poznata po svojoj sposobnosti da smanji hiperpigmentacije i ujednači ton kože. Deluje inhibirajući sintezu melanina, što pomaže u smanjenju tamnih mrlja i postinflamatornih hiperpigmentacija. Takođe ima umirujuća svojstva, smanjujući crvenilo i iritacije. U kombinaciji sa drugim aktivnim sastojcima, traneksaminska kiselina doprinosi svetlijem i ujednačenijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Isntree Onion Newpair Soothing Mask je maska za lice koja koristi ekstrakt crvenog luka, hijaluronsku kiselinu i traneksaminsku kiselinu kako bi umirila, hidrirala i posvetlila kožu. Formulisana je za smanjenje crvenila, iritacija i hiperpigmentacija, pružajući osvežavajući efekat hlađenja i poboljšanu elastičnost kože.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Isntree-Onion-Newpair-Soothing-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
