INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (799, 48, 'Dr. Althea Jelly Seal Dewy Mask', 'dr-althea-jelly-seal-dewy-mask', 'Ključne prednosti: Intenzivna hidratacija u svim slojevima kože: HyalDeca kompleks sadrži 10 tipova hijaluronske kiseline za višeslojnu vlagu. Jačanje barijere i umirenje osetljive kože: Pantenol i madekasosid ublažavaju iritacije i obnavljaju zaštitni sloj. Vidno čvršća i blistavija koža: PhytoPDRN iz lista lotosa stimuliše regeneraciju i poboljšava tonus kože Kome je namenjena? Maska je idealna za osetljivu, nadraženu, suvu i kombinovanu kožu, kao i za one koji se bore sa gubitkom elastičnosti i beživotnim tenom. Preporučuje se osobama sa oslabljenom kožnom barijerom, neravnotežom vlage i opuštenom teksturom kože. Zašto volimo Dr. Althea Jelly Seal Dewy Mask? Jelly Seal Dewy Mask pruža tretmanski efekat već u jednoj primeni zahvaljujući svojoj naprednoj dvoslojnoj strukturi i visokoj koncentraciji aktivnih sastojaka. Jelly sheet napravljena tehnologijom gel gaze savršeno prijanja uz kožu i omogućava duboku apsorpciju esencije. HyalDeca kompleks kombinuje 10 vrsta hijaluronske kiseline različitih molekulskih veličina koje prodiru u više slojeva kože i obezbeđuju dugotrajnu hidrataciju. Biljni PDRN iz listova lotosa deluje regenerativno, vraća čvrstinu i povećava otpornost kože. Pantenol i madekasosid doprinose obnovi i umirenju osetljivih i iritiranih zona. Polymer sistem dodatno potiskuje aktivne sastojke dublje u kožu, čime se postiže efektan i trajan rezultat. Koža nakon tretmana izgleda zategnuto, osveženo i vidno hidrirano, bez crvenila ili osećaja težine. Aktivni sastojci HyalDeca kompleks (10 vrsta hijaluronske kiseline) Ovaj napredni kompleks hidrira sve slojeve kože – od površinskog do dubinskog, zahvaljujući različitim molekulskim veličinama hijaluronske kiseline. Vraća koži elastičnost, mekoću i ublažava dehidrirane linije. Održava kožu vlažnom satima nakon uklanjanja maske. Idealan je za kožu kojoj nedostaje voda, a ne mast. Ne izaziva iritaciju, ni kod osetljive kože. Ujedno poboljšava apsorpciju drugih aktivnih supstanci. PhytoPDRN (ekstrakt iz listova lotosa) Biljni PDRN je derivat DNK koji se u ovoj formuli dobija iz listova lotosa, poznat po svojim regenerativnim i anti-age svojstvima. Stimuliše sintezu kolagena i popravlja oštećenja kože izazvana stresom, UV zračenjem ili isušivanjem. Deluje antiinflamatorno i podstiče zarastanje mikrooštećenja. Daje koži elastičniji, zdraviji i „puniji“ izgled. Posebno koristan za opuštenu i umornu kožu. Obezbeđuje prirodan, zdrav sjaj bez prekomernog sjaja. Pantenol & Madekasosid Pantenol(provitamin B5) deluje kao humektant i emolijent, zadržavajući vlagu i ubrzavajući obnavljanje kože. Madekasosid, aktivna komponenta iz centelle asiatice, ima snažno umirujuće i protivupalno dejstvo. Kombinovano deluju na jačanje barijere, smanjenje crvenila i ublažavanje iritacija. Idealan duo za osetljivu, reaktivnu i isušenu kožu. Poboljšavaju otpornost kože na spoljne stresore. Ne sadrže parfeme ni iritanse. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Jelly Seal Dewy Mask je inovativna gel sheet maska sa dvoslojnom jelly teksturom, koja dubinski hidrira, jača barijeru kože i vraća prirodan sjaj i čvrstinu. Formulisana s moćnim kompleksom hijaluronske kiseline, biljnim PDRN i umirujućim sastojcima, pruža efikasnu negu bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Dr.-Althea-Jelly-Seal-Dewy-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
