INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (801, 48, 'Dr. Althea Amino Acid Gentle Bubble Cleanser', 'dr-althea-amino-acid-gentle-bubble-cleanser', 'Ključne prednosti: Nežno, ali temeljno čišćenje pora: Aminokiselinski surfaktanti uklanjaju šminku i nečistoće bez narušavanja pH ravnoteže kože. Jačanje i obnova barijere kože: Ceramidi i perila ekstrakt umanjuju crvenilo, iritaciju i jačaju otpornost kože. Veganska, hipoalergena formula: Bez sulfata, parabena i veštačkih boja – pogodna i za najosetljiviju kožu. Kome je namenjen? Ova pena je idealna za osobe sa osetljivom, dehidriranom ili aknama sklonom kožom. Preporučuje se i onima koji imaju narušenu barijeru kože, osećaj zatezanja nakon umivanja, kao i neujednačen balans vode i ulja u koži. Zašto volimo Dr. Althea Amino Acid Gentle Bubble Cleanser? Amino Acid Gentle Bubble Cleanser donosi potpuno nov nivo nege kroz čišćenje. Formulisana sa čak 17 vrsta aminokiselina, ova pena deluje kao prirodni ovlaživač i sredstvo za regeneraciju, dok ujedno uklanja nečistoće, višak sebuma i ostatke šminke. Zahvaljujući naprednoj UFD nano-peni (200 nm), prodire duboko u pore bez mehaničkog trenja, čime se eliminiše rizik od iritacije. Ceramidi pomažu u obnovi oštećene kožne barijere, dok hijaluronska kiselina hidrira i sprečava isušivanje. Ekstrakti bambusa i perile smanjuju crvenilo i upalne procese, što ovu penu čini pogodnom i za kožu sklonu aknama. Njena veganska, hipoalergena i EWG-zeleno ocenjena formula garantuje sigurnost i efikasnost čak i kod najosetljivijih korisnika. Aktivni sastojci Aminokiselinski kompleks (17 vrsta) Aminokiseline su osnovni gradivni elementi proteina i igraju ključnu ulogu u očuvanju vlažnosti, elastičnosti i zaštitne funkcije kože. U ovoj formuli, njih 17 deluju sinergijski kako bi nežno, ali efikasno očistile kožu bez narušavanja njene prirodne pH vrednosti. One takođe stimulišu regeneraciju ćelija i pomažu u oporavku kože nakon iritacija. Za razliku od agresivnih tenzida, aminokiselinski surfaktanti pružaju temeljno čišćenje bez zatezanja. Posebno su korisne kod osetljive i upaljene kože jer ne izazivaju dodatne reakcije. Hijaluronska kiselina Hijaluronska kiselina pomaže u zadržavanju vlage u koži tokom i nakon čišćenja, sprečavajući tipično isušivanje koje ostavljaju klasični čistači. Ovaj sastojak trenutno hidrira i poboljšava osećaj mekoće na koži. Takođe podržava funkciju kožne barijere i smanjuje transepidermalni gubitak vode. U kombinaciji s ostalim umirujućim sastojcima, čini kožu elastičnijom i manje sklonom iritacijama. Idealan je za suvu i dehidriranu kožu kojoj je potrebna dodatna vlaga već u prvom koraku rutine. Ceramid NP Ceramidi su prirodne lipidne komponente kože koje pomažu u obnavljanju zaštitne barijere i zadržavanju vlage. Ceramid NP posebno deluje na jačanje oslabljene barijere, što je ključno kod osetljive i reaktivne kože. Sprečava isušivanje i štiti od spoljnih uticaja kao što su zagađenje i UV zračenje. Pomaže u smanjenju crvenila i iritacija izazvanih upotrebom kozmetike ili čišćenja. Perilla Ocymoides Seed ekstrakt Ekstrakt semena perile bogat je omega-3 masnim kiselinama i antiinflamatornim jedinjenjima. Efikasno umiruje kožu, smanjuje crvenilo, svrab i osećaj zatezanja. Ima i antimikrobna svojstva koja pomažu kod kože sklone aknama i inflamaciji. Posebno koristan kod oslabljene, reaktivne kože koja burno reaguje na spoljašnje faktore. Ujedno jača sposobnost kože da se samostalno regeneriše. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Amino Acid Gentle Bubble Cleanser je izuzetno blaga, veganska pena za čišćenje lica koja koristi kompleks od 17 različitih aminokiselina za efikasno uklanjanje nečistoća uz očuvanje prirodne barijere kože. Zahvaljujući dodatku ceramida, hijaluronske kiseline i biljnih ekstrakata, pruža dubinsku negu i umiruje osetljivu kožu već pri samom čišćenju.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Dr.-Althea-Amino-Acid-Gentle-Bubble-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product_category (product_id, category_id) VALUES (801, 46);
