INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (803, 46, 'Derma:B Everyday Sun Block SPF50+', 'dermab-everyday-sun-block', 'Ključne prednosti: Efikasna UV zaštita širokog spektra: SPF 50+ PA++++ štiti kožu od preranog starenja i oštećenja izazvanih suncem. Hidratacija i umirenje kože: Pantenol i biljni ekstrakti pomažu u očuvanju vlažnosti i smanjuju iritacije izazvane izlaganjem suncu. Idealna podloga za šminku: Ne ostavlja bele tragove ni masni film, brzo se upija i ne zapušava pore. Kome je namenjena? Ova krema je namenjena svim tipovima kože, uključujući osetljivu, masnu i kombinovanu. Idealna je za svakodnevnu zaštitu u gradskim uslovima, ali i prilikom dužeg boravka na suncu, jer pruža pouzdanu zaštitu uz negu i komfor. Zašto volimo Derma:B Everyday Sun Block? Everyday Sun Block osmišljen je kao višenamenski zaštitni preparat koji pruža više od običnog SPF-a. Njegova hibridna UV formula kombinuje hemijske i fizičke filtere kako bi obezbedila stabilnu i sveobuhvatnu zaštitu od UVA/UVB zračenja, čak i tokom dužeg boravka napolju. Zahvaljujući dodatku pantenola, hijaluronske kiseline i antioksidativnih biljnih ekstrakata, ovaj proizvod ne samo da štiti već i neguje – smanjuje crvenilo, hidrira i jača kožnu barijeru. Formula je lagana, nelepljiva i brzo se upija, čineći je idealnom kao podloga za šminku. Ne sadrži alkohol, mineralna ulja ni veštačke mirise, što ga čini pogodnim i za reaktivnu kožu. Aktivni sastojci UV filteri širokog spektra (SPF 50+ PA++++) Ova formula kombinuje fizičke i hemijske UV filtere kako bi pružila potpunu zaštitu od UVA (starenje) i UVB (crvenilo i opekotine) zračenja. Stabilni filteri pružaju dugotrajnu efikasnost čak i pri izlaganju suncu duži vremenski period. Sprečavaju fotostarenje, pojavu tamnih fleka i gubitak elastičnosti. Idealni su za svakodnevnu upotrebu jer ne izazivaju iritacije. Deluju u sinergiji sa antioksidansima i hidratantnim sastojcima, čime štite i neguju kožu istovremeno. N Pantenol (provitamin B5) Pantenol ima umirujuće i obnavljajuće dejstvo, što ga čini posebno korisnim u SPF formulama koje se koriste svakodnevno. Smanjuje crvenilo, zatezanje i osećaj nelagodnosti izazvane UV zračenjem. Ujedno hidrira kožu i poboljšava njenu otpornost na spoljne stresore. Njegovo prisustvo doprinosi blagoj i efikasnoj zaštiti kože, naročito kod duže izloženosti suncu. Hijaluronska kiselina Ovaj moćni hidratantni sastojak privlači i zadržava vlagu u dubljim slojevima kože, čime se sprečava isušivanje koje često prati korišćenje SPF proizvoda. Poboljšava elastičnost kože, čini je glatkijom i smanjuje pojavu sitnih linija. Posebno korisna kod dužeg boravka na suncu jer pomaže u očuvanju prirodne hidratacije. Njena lagana tekstura savršeno se uklapa u nekomedogene formulacije. Dodaj u listu želja Dodaj u listu želja', 'Derma:B Everyday Sun Block je svakodnevna zaštitna krema sa širokim spektrom delovanja (SPF 50+ PA++++) koja štiti kožu od UVA i UVB zračenja, dok istovremeno hidrira i umiruje zahvaljujući prisustvu pantenola i biljnih ekstrakata. Lagana, nelepljiva formula idealna je za svakodnevnu upotrebu bez osećaja težine ili belih tragova.', 'https://beauty-health.rs/wp-content/uploads/2025/05/DermaB-Everyday-Sun-Block-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
