INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (809, 11, 'Anua Rice 70 Glow Collagen Mask', 'anua-rice-70-glow-collagen-mask', 'Ključne prednosti: Dugotrajna hidratacija i osvežen izgled: Zahvaljujući visokom udelu fermentisane pirinčane vode, maska dubinski hidrira i pomaže u osvetljavanju tena. Vidljivo čvršća koža: Kolagen niske molekularne mase deluje na elastičnost i punoću kože, čineći je glatkom i zategnutom. Zaštita barijere i zadržavanje vlage: Ceramidi pomažu u obnovi lipidnog sloja i štite kožu od dehidratacije i spoljnih iritansa. Kome je namenjena? Ova maska je idealna za sve tipove kože kojima je potrebna dodatna hidratacija, osvetljenje i učvršćivanje, naročito za umornu, beživotnu i dehidriranu kožu. Pogodna je i za osetljivu kožu zahvaljujući blagoj, hipoalergenskoj formuli bez štetnih sastojaka. Zašto volimo Anua Rice 70 Glow Collagen Mask? Rice 70 Glow Collagen Mask kombinuje blagotvorna svojstva fermentisane pirinčane vode sa moćnim hidratantnim i obnavljajućim komponentama, pružajući intenzivnu negu i osvežen izgled kože. Fermentisana pirinčana voda doprinosi ujednačavanju tena, dok ceramidi jačaju prirodnu barijeru kože i pomažu u zadržavanju vlage tokom dužeg vremenskog perioda. Kolagen niske molekularne mase deluje ciljano na elastičnost, čineći kožu čvršćom i zategnutijom bez osećaja težine. Posebno formulisana za dublju apsorpciju, maska pruža prijatan osećaj hlađenja i ostavlja kožu glatkom, hidriranom i prirodno blistavom. Zahvaljujući transparentnoj teksturi, pogodna je za dugotrajno nošenje, a rezultati su vidljivi već nakon prve upotrebe. Učinkovito smanjuje umoran izgled i pruža trenutni efekat &#8220;osveženog tena&#8221;. Aktivni sastojci Fermentisana pirinčana voda (Rice Water+&#x2122; 70%) Fermentisana pirinčana voda, poznata po svojoj bogatoj koncentraciji vitamina B, minerala i aminokiselina, tradicionalno se koristi u azijskoj kozmetici za osvetljavanje i negu kože. U ovoj formuli čini čak 70% sastava, čime se postiže intenzivna hidratacija i poboljšanje jasnoće tena. Njena fermentacija dodatno pojačava apsorpciju hranljivih materija, čineći je visoko efikasnom u obnavljanju oštećene i dehidrirane kože. Deluje i na smanjenje tamnih fleka i crvenila, uz istovremeno smanjenje upala. Ova komponenta pomaže koži da postigne prirodni “glass skin” efekat, a redovnom upotrebom pruža dugoročno ujednačen i zdrav izgled. Ceramidi Ceramidi su ključne lipidne komponente koje čine do 50% kožne barijere. Njihova uloga u ovoj maski je da ojačaju prirodnu zaštitu kože, sprečavajući transepidermalni gubitak vode (TEWL) i smanjujući osetljivost kože na spoljne faktore. Posebno su korisni u tretiranju suve i dehidrirane kože jer obnavljaju slojeve kože koji su oštećeni agresivnim proizvodima ili UV zračenjem. Dodatno, ceramidi omogućavaju bolje zadržavanje hidratantnih i aktivnih sastojaka unutar kože. Njihova prisutnost u ovoj formuli doprinosi mekoj, elastičnoj i otpornijoj koži već nakon nekoliko tretmana. Takođe doprinose glatkijoj teksturi i smanjuju osećaj zatezanja. Kolagen niske molekularne mase (Soluble Collagen 60 ppm) Ovaj oblik kolagena lakše prodire u dublje slojeve kože zahvaljujući manjoj molekularnoj težini, omogućavajući poboljšanje elastičnosti iznutra. Njegova funkcija nije samo površinsko zatezanje već i dugoročna stimulacija čvrstoće i regeneracije dermalnih vlakana. Kolagen u ovoj maski pomaže koži da izgleda punije, zaglađenije i blistavije. Deluje i kao sredstvo za omekšavanje, čineći kožu svilenkastom na dodir. Osim toga, podržava prirodne procese obnove ćelija i smanjuje vidljivost sitnih bora. Zahvaljujući ovom sastojku, maska pruža trenutni efekat svežine, ali i dugoročne benefite ako se koristi redovno. Dodaj u listu želja Dodaj u listu želja', 'Anua Rice 70 Glow Collagen Mask je bogata hidratantna maska sa 70% fermentisane pirinčane vode, kolagenom i ceramidima koja poboljšava tonus, zadržava vlagu i vraća koži prirodni sjaj. Namenjena je korisnicima koji žele vidljivo zategnutiju, glatkiju i zdraviju kožu bez osećaja zatezanja ili iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Anua-Rice-70-Glow-Collagen-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
