INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (813, 14, 'Arencia Hyssop Fume Balm', 'arencia-hyssop-fume-balm', 'Ključne prednosti: Povećava elastičnost i volumen kože: Zahvaljujući niacinamidu, balzam podstiče sintezu kolagena i poboljšava tonus kože. Smanjuje vidljivost bora: Adenozin cilja fine linije i doprinosi zaglađivanju teksture kože za mladalačkiji izgled. Obnavlja i štiti suvu kožu: Balzam stvara zaštitni film koji zaključava vlagu, obnavlja barijeru kože i čini je dugotrajno mekom i nahranjenom. Kome je namenjen? Ovaj balzam je idealan za osobe sa suvom, zrelom ili dehidriranom kožom koja je izgubila elastičnost i volumen. Posebno se preporučuje za ciljanu negu područja sa izraženim borama – čelo, oči, usne i vrat. Zašto volimo Arencia Hyssop Fume Balm? Hyssop Fume Balm osmišljen je kao visokoefikasan tretman za kožu kojoj je potrebna obnova, elastičnost i zaštita. Njegova bogata, ali neljepljiva tekstura pruža osećaj luksuzne hidratacije koja traje satima nakon nanošenja. Niacinamid deluje na ćelijskom nivou kako bi poboljšao barijeru kože, ujednačio ton i poboljšao otpornost kože na dehidrataciju. Adenozin, poznat po svom anti-age delovanju, pomaže u smanjenju izraženih bora, dok koži vraća glatkoću i zategnutost. Formulisan bez štetnih sastojaka, balzam se može nanositi i na osetljive regije poput predela oko očiju, usana i vrata. Već nakon nekoliko dana upotrebe, koža postaje mekša, zategnutija i vidno osvežena. Aktivni sastojci Niacinamid Niacinamid (vitamin B3) je jedan od najistraženijih sastojaka u kozmetici zbog svoje sposobnosti da poboljša elastičnost, ujednači ten i ojača barijernu funkciju kože. Deluje tako što stimuliše sintezu ceramida i kolagena, čime se poboljšava otpornost kože na spoljne faktore i smanjuje gubitak vlage. Takođe pomaže u smanjenju hiperpigmentacija i ublažava upalne procese, što ga čini pogodnim i za kožu sa nepravilnostima. U ovoj formuli niacinamid ima dodatnu ulogu u obnavljanju kože nakon iritacija i poboljšanju ukupne teksture. Njegovo redovno korišćenje čini kožu elastičnijom, ujednačenijom i prirodno blistavom. Adenozin Adenozin je funkcionalni anti-age sastojak koji deluje tako što poboljšava glatkoću kože i smanjuje vidljivost finih linija. Prirodno se nalazi u telu, a topikalna primena stimuliše ćelijsku energiju (ATP), što ubrzava regeneraciju i jača kožnu strukturu. Posebno efikasan u tretiranju bora na čelu, oko očiju i vrata, adenozin doprinosi ujednačenoj teksturi i elastičnosti kože. Takođe ima umirujuće dejstvo, što ga čini pogodnim za svakodnevnu upotrebu i kod osetljive kože. U kombinaciji sa hidratantnim agensima pomaže u postizanju “plump” efekta – kože koja izgleda puno i sveže. Dodaj u listu želja Dodaj u listu želja', 'Arencia Hyssop Fume Balm je koncentrovani hidratantni balzam formulisan sa niacinamidom i adenozinom, koji dubinski hidrira i pomaže u vraćanju elastičnosti kože. Namenjen je regeneraciji suve i oštećene kože, uz vidljivo poboljšanje teksture i smanjenje bora.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Arencia-Hyssop-Fume-Balm-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
