INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (814, 6, 'Abib Collagen Eye Patch Jericho Rose Jelly jastučići', 'abib-collagen-eye-patch-jericho-rose-jelly', 'Ključne prednosti: Smanjuju natečenost i tamne kolutove – Kofein stimuliše mikrocirkulaciju i deluje protiv zadržavanja tečnosti. Hidriraju i poboljšavaju elastičnost – Hijaluronska kiselina i veganski kolagen dubinski vlaže i učvršćuju tanku kožu oko očiju. Vidljivo ujednačavaju i osvežavaju ten – Prirodni antioksidansi iz biljnih ekstrakata štite kožu i smanjuju znake umora. Kome je namenjen? Proizvod je idealan za sve tipove kože, uključujući i osetljivu. Preporučuje se svima koji se bore sa znakovima umora, dehidriranom kožom oko očiju, finim linijama, podočnjacima i gubitkom čvrstine. Može se koristiti ujutru i uveče, kao deo dnevne ili večernje rutine. Zašto volimo Abib Collagen Eye Patch Jericho Rose Jelly? Quick Sunstick Protection Bar je osmišljen kao brzo rešenje za pouzdanu zaštitu od sunca uz dodatnu negu kože. Formulisan sa fermentisanim uljima masline, argana i tamanu-a, ovaj stik pruža snažnu antioksidativnu podršku i neutralizuje štetne slobodne radikale. Centella asiatica, aloe vera i ekstrakt zelenog čaja umiruju kožu i smanjuju crvenilo. Ceramidi i peptidi jačaju barijeru i čine kožu otpornijom. Hidratantni agensi poput hijaluronske kiseline, skvalana i tokoferola (vitamin E) dubinski vlaže i štite kožu od isušivanja. Praktičan za upotrebu tokom celog dana, ovaj sunstick ostavlja nevidljiv sloj zaštite, bez zapušavanja pora, čak i kada se nanosi preko šminke. Aktivni sastojci Veganski kolagen Pruža podršku strukturi kože, poboljšava elastičnost i zateže područje oko očiju, ostavljajući kožu čvršćom i glađom. Jerihonska ruža (Selaginella lepidophylla) Biljka otporna na ekstremne uslove, bogata antioksidansima koji štite kožu i pomažu u očuvanju vlage. Doprinosi regeneraciji i otpornosti kože. Kofein Smanjuje tamne kolutove i natečenost stimulacijom mikrocirkulacije i eliminacijom viška tečnosti u području oko očiju. Hijaluronska kiselina Intenzivno hidrira i pomaže u popunjavanju sitnih linija pružajući puniji i svežiji izgled kože. Ceramidi Jačaju zaštitnu barijeru kože, sprečavaju transepidermalni gubitak vode i doprinose dugotrajnoj hidrataciji. Dodaj u listu želja Dodaj u listu želja', 'Abib Collagen Eye Patch Jericho Rose Jelly su hidrogel jastučići za područje oko očiju, formulisani da ciljano deluju na tamne podočnjake, nadutost, fine linije i dehidriranu kožu. Obogaćeni kolagenom biljnog porekla, kofeinom i hijaluronskom kiselinom, pružaju vidljivo osvežen i zategnut izgled već nakon prve upotrebe.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Abib-Collagen-Eye-Patch-Jericho-Rose-Jelly-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
