INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (815, 6, 'Abib Quick Sunstick Protection Bar SPF50+', 'abib-quick-sunstick-protection-bar', 'Ključne prednosti: Širokospektralna zaštita SPF 50+ – Štiti od UVA i UVB zračenja i pomaže u prevenciji fotostarenja. Lagano, nelepljivo i providno – Ne ostavlja tragove ni preko šminke, sa prijatnom, glatkom završnicom. Pogodan za osetljivu kožu – Dermatološki testiran i bez iritacija; bez alkohola i veštačkih mirisa. Kome je namenjen? Idealan za svakodnevnu upotrebu na svim tipovima kože, uključujući osetljivu. Preporučuje se onima koji traže praktičan način da obnavljaju SPF tokom dana – čak i preko šminke – bez osećaja težine, sjaja ili lepljivosti. Takođe je odličan za sport, putovanja i negu u pokretu. Zašto volimo Abib Quick Sunstick Protection Bar? Quick Sunstick Protection Bar je osmišljen kao brzo rešenje za pouzdanu zaštitu od sunca uz dodatnu negu kože. Formulisan sa fermentisanim uljima masline, argana i tamanu-a , ovaj stik pruža snažnu antioksidativnu podršku i neutralizuje štetne slobodne radikale. Centella asiatica, aloe vera i ekstrakt zelenog čaja umiruju kožu i smanjuju crvenilo, dok ceramidi i peptidi jačaju barijeru i čine kožu otpornijom. Hidratantni agensi poput hijaluronske kiseline, skvalana i tokoferola (vitamin E) dubinski vlaže i štite kožu od isušivanja. Praktičan za upotrebu tokom celog dana, ovaj sunstick ostavlja nevidljiv sloj zaštite , bez zapušavanja pora, čak i kada se nanosi preko šminke. Aktivni sastojci Fermentisano ulje masline, argana i tamanu ulje Prirodni izvori antioksidanasa koji štite od UV oštećenja i poboljšavaju elastičnost i sjaj kože. Fermentacija povećava bioraspoloživost i efikasnost ovih ulja. Centella Asiatica, Aloe vera, Zeleni čaj Umirujući biljni ekstrakti sa dokazanim protivupalnim delovanjem. Deluju na iritacije, crvenilo i podržavaju regeneraciju kože izložene suncu. Ceramide & Acacia Peptid Obnavljaju i jačaju zaštitnu barijeru kože. Pomažu u očuvanju vlage i otpornosti kože na spoljne agresore. Hijaluronska kiselina, Skvalan i Tokoferol (Vitamin E) Dubinski hidriraju, povećavaju elastičnost kože i smanjuju transepidermalni gubitak vode. Deluju i kao antioksidansi sa anti-age efektom. Peptidi (Copper Tripeptide-1 & Acetyl Hexapeptide-8) Poboljšavaju tonus kože, ujednačavaju teksturu i podržavaju sintezu kolagena. Doprinosi elastičnosti i smanjenju finih linija. Dodaj u listu želja Dodaj u listu želja', 'Abib Quick Sunstick Protection Bar SPF 50+ je transparentni zaštitni stik sa visokom UV zaštitom, formulisan za brzo, lako i svakodnevno nanošenje bez lepljivog osećaja i belih tragova. Obogaćen je biljnim uljima, antioksidansima i umirujućim sastojcima za dodatnu negu i zaštitu kože tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Abib-Quick-Sunstick-Protection-Bar-SPF50.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
