INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (818, 11, 'Anua Peach 70 Niacin Brightening Collagen Mask', 'anua-peach-70-niacin-brightening-collagen-mask', 'Ključne prednosti: Ujednačava ten i osvetljava kožu: Zahvaljujući 2% niacinamida, maska deluje na diskoloracije i sivilo tena, ostavljajući kožu blistavijom i zdravijom. Poboljšava elastičnost i tonus kože: Kolagen niske molekularne mase prodire dublje u epiderm i podstiče zategnut izgled kože. Obnavlja i hidrira umornu kožu: PeachNia+&#x2122; kompleks sa ekstraktom breskve neguje i blago eksfolira, ostavljajući kožu glatkom, nahranjenom i osveženom. Kome je namenjena? Ova maska je idealna za osobe sa umornom, sivkastom i neujednačenom kožom koje žele trenutno osveženje, blistavost i hidrataciju. Pogodna je i za one sa dehidriranom kožom sklonom gubitku elastičnosti ili finim linijama. Zašto volimo Anua Peach 70 Niacin Brightening Collagen Mask? Peach 70 Niacin Brightening Collagen Mask deluje kao intenzivan tretman za osvetljavanje i regeneraciju kože. Njena bogata, ali lagana formulacija, koristi prirodne ekstrakte breskve i klinički efikasan procenat niacinamida da bi koži pružila vidljivu blistavost i svežinu već nakon jedne upotrebe. Kolagen niske molekularne mase prodire duboko u slojeve kože i doprinosi zategnutijem i čvršćem izgledu. Maska ujedno hidrira i osvežava ten, a istovremeno blago uklanja odumrle ćelije kože, ostavljajući površinu glatkom i nežnom. Idealan je izbor pred važan događaj ili kao deo večernje rutine, jer pruža &#8220;glow efekt&#8221; bez potrebe za dodatnom negom. Njena upotreba doprinosi stvaranju ujednačenog i zdravog tena, a koža nakon tretmana deluje revitalizovano, mekano i osveženo. Aktivni sastojci Ekstrakt breskve (PeachNia+&#x2122;) Ovaj patentirani kompleks sadrži 70% ekstrakta breskve, bogate vitaminima A i C, antioksidansima i prirodnim šećerima. Deluje umirujuće, poboljšava tonus kože i podstiče prirodni sjaj. Takođe sadrži voćne kiseline koje blago eksfoliraju kožu i uklanjaju odumrle ćelije, čime se povećava upijanje ostalih sastojaka. Redovnom upotrebom doprinosi smanjenju sivila tena i vraća koži blistavost. Prirodni antioksidansi iz breskve štite kožu od oksidativnog stresa i starenja. Kompleks pomaže i u balansiranju sebuma, pa je pogodan i za mešovitu kožu. Niacinamid 2% Niacinamid, poznat i kao vitamin B3, jedan je od najefikasnijih sastojaka u borbi protiv neujednačenog tena, proširenih pora i znakova umora na koži. U ovoj maski prisutan je u optimalnoj koncentraciji od 2%, što omogućava svakodnevnu upotrebu bez iritacija. Deluje tako što inhibira sintezu melanina, pomaže u smanjenju tamnih fleka i ujednačavanju boje kože. Takođe pospešuje sintezu ceramida, čime jača barijeru kože i poboljšava hidrataciju. Njegovo umirujuće dejstvo čini ga pogodnim za osetljive i problematične tipove kože. Koža već nakon jedne upotrebe deluje svežije, odmornije i mekše. Kolagen niske molekularne mase (2,000 ppm) Kolagen je protein koji čini osnovnu strukturu kože, a njegova niska molekularna masa omogućava dublju apsorpciju i efikasnije rezultate. Ova forma kolagena prodire u epidermalni sloj i poboljšava elastičnost kože iznutra. Pomaže u smanjenju finih linija i poboljšanju teksture kože, čineći je vidno glatkom i čvršćom. Ujedno deluje kao zaptivač vlage, čime se pojačava hidratantni efekat maske. Njegova redovna upotreba doprinosi dugoročno zdravijem i zategnutijem tenu. Posebno je koristan u noćnim tretmanima, kada se koža prirodno regeneriše. Dodaj u listu želja Dodaj u listu želja', 'Anua Peach 70 Niacin Brightening Collagen Mask je hidratantna i osvetljavajuća maska obogaćena ekstraktom breskve (70%), niacinamidom i kolagenom niske molekularne mase. Namenjena je revitalizaciji umorne, neujednačene kože i poboljšanju njene elastičnosti, sjaja i glatkoće.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Anua-Peach-70-Niacin-Brightening-Collagen-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
