INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (820, 161, 'The Ordinary Glycolic Acid 7% Toning Solution', 'the-ordinary-glycolic-acid-7-toning-solution', 'Ključne prednosti: Poboljšava teksturu i ton kože – Glikolna kiselina efikasno uklanja mrtve ćelije i stimuliše regeneraciju kože, što dovodi do ujednačenijeg i blistavijeg tena. Ublažava hiperpigmentacije i neujednačenost – Redovnom upotrebom smanjuje tamne fleke, postupalne mrlje i diskoloracije. Održava balans zahvaljujući umirujućim sastojcima – Ekstrakti aloje, ruzmarina, ginsenga i paprati smanjuju potencijalne iritacije i podržavaju kožnu barijeru. Kome je namenjen? Ovaj tonik je namenjen osobama sa neujednačenim tonom kože, površinskim ožiljcima, hiperpigmentacijama i teksturalnim nepravilnostima. Najpogodniji je za normalnu, kombinovanu i masnu kožu , dok osobe sa osetljivom kožom treba da ga uvode postepeno i sa oprezom. Zašto volimo The Ordinary Glycolic Acid 7% Toning Solution? Glycolic Acid 7% Toning Solution koristi AHA (alfa-hidroksi) kiselinu – glikolnu kiselinu , koja ima najmanju molekulsku masu među AHA kiselinama i može da prodre dublje u površinske slojeve kože. Njeno dejstvo se zasniva na razlaganju međustaničnih veza između mrtvih ćelija, čime se ubrzava njihovo ljuštenje i otkrivaju zdraviji, svetliji slojevi kože. Ovo dovodi do poboljšanja teksture, redukcije površinskih ožiljaka i neujednačenosti. Tonik takođe sadrži Tasmannia Lanceolata ekstrakt (paprat sa antiinflamatornim svojstvima), aloju veru za hidrataciju, i ginseng koji stimuliše mikrocirkulaciju. pH tonika je oko 3.6, što omogućava optimalno delovanje glikolne kiseline uz minimalan rizik od iritacija. Redovnom upotrebom koža postaje ujednačenija, čistija i sjajnija, a pore vizuelno suženije. Aktivni sastojci Glikolna kiselina (7%) Glikolna kiselina je AHA eksfolijant koji razlaže veze između mrtvih ćelija na površini kože, ubrzava njihovo uklanjanje i stimuliše obnavljanje. U koncentraciji od 7%, nudi balans između efikasnosti i tolerancije. Pomaže u smanjenju hiperpigmentacija, površinskih ožiljaka i grube teksture. Tasmannia Lanceolata ekstrakt Australijska biljka sa dokazanim umirujućim i protivupalnim dejstvom. Smanjuje osećaj peckanja i crvenila koje može izazvati glikolna kiselina, čineći formulu pogodnijom za redovnu upotrebu. Aloe vera Prirodni hidratant koji smiruje kožu, pomaže u regeneraciji i sprečava dehidrataciju tokom procesa eksfolijacije. Ginseng i ruzmarin ekstrakt Biljni antioksidansi koji poboljšavaju cirkulaciju, štite od oksidativnog stresa i doprinose osveženju tena. Deluju revitalizirajuće i antiinflamatorno. Dodaj u listu želja Dodaj u listu želja', 'The Ordinary Glycolic Acid 7% Toning Solution je tonik na bazi glikolne kiseline koji vrši blagu hemijsku eksfolijaciju površinskog sloja kože, poboljšava teksturu, posvetljuje ten i obnavlja sjaj. Uz dodatke umirujućih biljnih ekstrakata, ovaj eksfolijant efikasno uklanja mrtve ćelije i ubrzava ćelijski obrt bez potrebe za fizičkim pilingom.', 'https://beauty-health.rs/wp-content/uploads/2025/05/The-Ordinary-Glycolic-Acid-7-Toning-Solution.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
