INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (821, 161, 'The Ordinary Hyaluronic Acid 2% + B5', 'the-ordinary-hyaluronic-acid-2-b5', 'Ključne prednosti: Višeslojna hidratacija – Tri molekulske mase hijaluronske kiseline prodiru u različite slojeve kože, osiguravajući sveobuhvatnu i dugotrajnu hidrataciju. Regeneracija i umirenje – Vitamin B5 (pantenol) i ceramidi jačaju barijeru, ublažavaju iritacije i poboljšavaju elastičnost kože. Lagano, nelepljivo i kompatibilno sa svim tipovima kože – Formulacija bez mirisa, alkohola i ulja, pogodna je i za osetljivu i aknama sklonu kožu. Kome je namenjen? Serum je idealan za sve tipove kože, uključujući suvu, dehidriranu, osetljivu i kožu narušene barijere. Preporučuje se korisnicima koji žele da poboljšaju hidrataciju, elastičnost i opšte stanje kože bez opterećenja formulom. Zašto volimo The Ordinary Hyaluronic Acid 2% + B5? Hyaluronic Acid 2% + B5 predstavlja klasičan, ali unapređen hidratantni serum koji se fokusira na funkcionalnu i efikasnu hidrataciju bez nepotrebnih dodataka . Hijaluronska kiselina u tri različite molekulske veličine deluje u površinskim i dubljim slojevima kože, obezbeđujući sveobuhvatnu vlagu i poboljšavajući volumen i elastičnost. Vitamin B5 deluje umirujuće i regenerativno, smanjuje crvenilo i iritaciju. Formula se brzo upija, ne ostavlja lepljiv sloj i može se lako kombinovati sa ostalim proizvodima, uključujući retinoide, kiseline i SPF. Koža postaje vidljivo mekša, punija i hidriranija već nakon nekoliko dana redovne upotrebe. Aktivni sastojci Hijaluronska kiselina (2%) Hijaluronska kiselina u ovom serumu dolazi u tri molekulske veličine – niskoj, srednjoj i visokoj – što omogućava hidrataciju u više slojeva kože. Visokomolekularna ostaje na površini i vezuje vlagu iz okoline, srednjomolekularna deluje u epidermu, dok niskomolekularna prodire dublje, poboljšavajući elastičnost i glatkoću. Efekat je trenutno vidljiv i dugotrajan. Vitamin B5 (Pantenol) Provitamin B5 poznat je po svom regenerativnom i umirujućem dejstvu. Jača zaštitnu barijeru kože, ublažava iritacije, ubrzava zaceljivanje i doprinosi zdravijem izgledu kože. Deluje sinergijski sa hijaluronskom kiselinom za maksimalnu hidrataciju. Ceramidi Ceramidi su lipidi prirodno prisutni u koži koji učvršćuju barijeru i sprečavaju gubitak vlage. Njihova prisutnost u ovoj verziji seruma obezbeđuje otpornost kože na stresne faktore i pomaže u oporavku narušene ili reaktivne kože. Dodaj u listu želja Dodaj u listu želja', 'The Ordinary Hyaluronic Acid 2% + B5 with Ceramides je napredni hidratantni serum koji kombinuje višeslojnu hijaluronsku kiselinu, provitamin B5 i ceramide za intenzivnu hidrataciju i jačanje zaštitne barijere kože. Ova pH-balansirana formula pruža koži vlagu, elastičnost i otpornost bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/05/The-Ordinary-Hyaluronic-Acid-2-B5.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
