INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (823, 130, 'P.CALM Cicalacto Exosome 45 Sleeping Mask', 'p-calm-cicalacto-exosome-45-sleeping-mask', 'Ključne prednosti: Dubinsko prodiranje i regeneracija – Egzozomi i spikule omogućavaju aktivnim sastojcima da efikasno deluju u dubljim slojevima kože, ubrzavajući regeneraciju i poboljšavajući elastičnost. Umiruje akne i crvenilo – Cica kompleks u kombinaciji sa pantenolom i madecassoside-om ublažava aktivne upale i ubrzava zarastanje. Podržano LED terapijom za ujednačen ten – Crveni LED uređaj dodatno pomaže u smanjenju fleka, hiperpigmentacija i ožiljaka od akni, bez izazivanja iritacije. Kome je namenjena? Maska je namenjena osobama koje imaju kožu sklonu aknama, crvenilu, ožiljcima i hiperpigmentacijama. Pogodna je za sve tipove kože, uključujući i veoma osetljivu, zahvaljujući formuli bez mirisa i dermatološki testiranim sastojcima. Zašto volimo P.CALM Cicalacto Exosome 45 Sleeping Mask? Obogaćena egzozomima iz Cicalacto kompleksa i prirodnim spikulama, ova maska deluje direktno na osetljiva i problematična područja kože. Egzozomi prenose regenerativne signale između ćelija, dok spikule omogućavaju da aktivne komponente prodru dublje, stimulišu mikrocirkulaciju i ubrzaju ćelijski obrt. Tokom noći, Cica ekstrakti, madecassoside, pantenol i hijaluronska kiselina umiruju kožu, smanjuju crvenilo i obnavljaju barijeru. Dodatna vrednost maske je upotreba crvenog LED uređaja koji dolazi u pakovanju, a koristi se za ciljano tretiranje fleka, hiperpigmentacija i ožiljaka – deluje bezbedno i bez iritacija zahvaljujući niskofrekventnoj svetlosnoj terapiji. Tekstura maske je lagana i nelepljiva, a proizvod je potpuno bez mirisa, što ga čini idealnim i za najosetljivije korisnike. Ujutru, koža je smirenija, blistavija i otpornija na spoljne agresore. Aktivni sastojci Egzozomi (Exosome 45) Biološki nosioci signalnih molekula koji obnavljaju kožu tako što poboljšavaju međućelijsku komunikaciju, podstiču sintezu kolagena i ubrzavaju zarastanje. U kombinaciji sa ostalim aktivnim komponentama, egzozomi doprinose dubljoj regeneraciji i elastičnosti kože, naročito u večernjoj regenerativnoj fazi. Spikule Prirodne mikroiglice koje prodiru u površinski sloj kože i stvaraju blagu fizičku stimulaciju. Podstiču mikrocirkulaciju i obnavljanje ćelija, a istovremeno omogućavaju efikasniji ulazak egzozoma i aktivnih biljnih ekstrakata. Ne oštećuju kožu i bezbedne su i za osetljive tipove. Centella Asiatica (Cica kompleks) Poznata po regenerativnim i protivupalnim svojstvima, centella asiatica smanjuje iritacije, ubrzava obnavljanje kože i podržava sintezu kolagena. Madecassoside i asiaticoside iz ovog kompleksa pomažu u obnavljanju barijere i smanjenju crvenila. Laktobacili i prebiotici Obnavljaju balans mikrobioma kože, jačaju njenu otpornost i smanjuju učestalost akni i upalnih procesa. Doprinosi stabilizaciji kože nakon upotrebe agresivnijih sastojaka ili u stresnim uslovima (UV, zagađenje). Pantenol i hijaluronska kiselina Ovi sastojci imaju zadatak da umire, hidriraju i osnaže kožnu barijeru. Pantenol smanjuje svrab i crvenilo, dok hijaluronska kiselina u više molekulskih veličina veže vlagu i čini kožu elastičnijom i punijom. Dodaj u listu želja Dodaj u listu želja', 'P.CALM Cicalacto Exosome 45 Sleeping Mask je noćna maska formulisana sa egzozomima iz Cicalacto kompleksa i prirodnim spikulama, koja deluje dubinski za umirenje upala, akni i crvenila. Maska dolazi u setu sa crvenim LED uređajem koji pomaže u redukciji hiperpigmentacija i ožiljaka, bez iritacije, čak i kod osetljive kože.', 'https://beauty-health.rs/wp-content/uploads/2025/05/P.CALM-Cicalacto-Exosome-45-Sleeping-Mask-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
