INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (824, 114, 'Medicube TXA Niacinamide 15% Serum', 'medicube-txa-niacinamide-15-serum', 'Ključne prednosti: Ciljana depigmentacija i prevencija melanina – Traneksaminska kiselina inhibira stvaranje melanina, čime posvetljuje tamne fleke i sprečava pojavu novih. Snažno osvetljavanje i antiinflamacija – Niacinamid deluje protivupalno, ujednačava ten i poboljšava elastičnost kože. Minimalna iritacija, maksimalna efikasnost – Formulisan za visoku koncentraciju aktivnih sastojaka uz nisku verovatnoću izazivanja crvenila ili ljuštenja. Kome je namenjen? Serum je idealan za osobe koje se bore sa melazmom, postinflamatornom hiperpigmentacijom, tamnim flekama od akni, neujednačenim tenom ili sivilom kože. Pogodan je za sve tipove kože, uključujući osetljivu, zahvaljujući neagresivnoj formulaciji bez alkohola i parfema. Zašto volimo Medicube TXA Niacinamide 15% Serum? TXA Niacinamide 15% Serum kombinuje dva snažna osvetljavajuća agensa – 5% traneksaminske kiseline (TXA) i 10% niacinamida – u klinički relevantnim koncentracijama koje pružaju brze i vidljive rezultate bez iritacije. Traneksaminska kiselina deluje na ćelijskom nivou inhibirajući puteve melanogeneze, dok niacinamid deluje na površini i dublje slojeve kože smanjujući upale, posvetljujući ten i poboljšavajući hidrataciju. Serum ima laganu, brzo upijajuću teksturu koja ne ostavlja lepljiv trag i ne komedogen je, što ga čini pogodnim za svakodnevnu upotrebu i ujutru i uveče. Redovnom upotrebom dolazi do značajnog posvetljavanja pigmentacija, smanjenja tonalne neujednačenosti i osvežavanja kože. Koža postaje vidno blistavija, glatkija i zdravijeg izgleda. Aktivni sastojci Traneksaminska kiselina (5%) Traneksaminska kiselina je moćan depigmentacioni agens koji inhibira plazmin i time blokira signalni lanac koji aktivira sintezu melanina. Za razliku od tradicionalnih sredstava poput hidrohinona, TXA deluje nežno ali efikasno, bez izazivanja oštećenja kože. U koncentraciji od 5%, klinički je dokazano da značajno smanjuje melazmu, fleke i diskoloracije uz odličnu podnošljivost. Takođe ima protivupalna svojstva i doprinosi stabilizaciji kože. Niacinamid (10%) Vitamin B3 u visokoj koncentraciji posvetljuje kožu, smanjuje sintezu melanina, umiruje inflamaciju i poboljšava sintezu ceramida. Efikasan je kod tretmana akni, proširenih pora, finih linija i sive kože bez sjaja. U ovoj formulaciji, niacinamid dodatno jača efekat TXA i deluje na višestruke probleme kože istovremeno. Adenozin Anti-age sastojak koji poboljšava elastičnost kože i smanjuje vidljivost bora stimulacijom proizvodnje kolagena. Takođe deluje umirujuće i doprinosi ujednačenijem tenu. Njegova prisutnost čini serum pogodnim za zrelu i umornu kožu. Alantoin i pantenol Ovi sastojci imaju snažno umirujuće dejstvo i poboljšavaju toleranciju kože na visoke koncentracije aktivnih agenasa. Pomažu u obnovi barijere, smanjuju crvenilo i ublažavaju iritacije. Dodaj u listu želja Dodaj u listu želja', 'Medicube TXA Niacinamide 15% Serum je visokoefikasni serum protiv hiperpigmentacija, formulisan sa 5% traneksaminske kiseline i 10% niacinamida. Ciljano posvetljuje tamne fleke, poboljšava ujednačenost tena i jača kožnu barijeru, bez izazivanja iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Medicube-TXA-Niacinamide-15-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
