INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (829, 143, 'Round Lab Pine Calming Cica Body Wash', 'round-lab-pine-calming-cica-body-wash', 'Ključne prednosti: Umiruje i jača kožnu barijeru: Ekstrakt kore bora i Centella Asiatica efikasno umanjuju crvenilo, iritacije i osećaj zatezanja. Hipoalergenska formulacija: Blagi surfaktanti biljnog porekla čiste kožu bez narušavanja prirodne barijere. Hidratacija i obnova: Pantenol i alantoin deluju regenerativno, zadržavaju vlagu i čine kožu mekom i elastičnom. Kome je namenjen? Pogodan za svakodnevnu upotrebu kod svih tipova kože, a naročito za osetljivu, suvu, atopiji sklonu i reaktivnu kožu tela. Idealan za osobe koje žele nežnu, a delotvornu negu bez agresivnih sastojaka. Zašto volimo Round Lab Pine Calming Cica Body Wash? Pine Calming Cica Body Wash pruža efikasno, ali blago čišćenje kože uz trenutni osećaj umirenja i osveženja. Formulisan je sa Panthanol-Cica kompleksom, koji kombinuje pro-vitamin B5 (pantenol) i ekstrakte centelle asiatice, poznate po regenerativnim i protivupalnim svojstvima. Ekstrakt bora doprinosi dodatnoj zaštiti kože zahvaljujući svojim snažnim antioksidativnim efektima. Ovaj gel za tuširanje ne sadrži sulfate ni agresivne sapune, već koristi aminokiselinske tenzide koji čiste bez isušivanja. Tokom upotrebe razvija se bogata, kremasta pena koja obavija kožu i ostavlja je hidriranom i smirenom čak i nakon ispiranja. Dermatološki je testiran i hipoalergenski. Aktivni sastojci Ekstrakt bora (Pinus Densiflora Bark Extract) Ekstrakt dobijen iz kore bora bogat je polifenolima i flavonoidima koji deluju kao snažni antioksidansi. Pomaže u neutralisanju slobodnih radikala i zaštiti kože od spoljašnjih agresora poput zagađenja i UV zračenja. Takođe ima umirujuća svojstva i pomaže u ublažavanju inflamacije i crvenila. Ovaj sastojak osvežava i balansira osetljivu kožu tela, čineći je otpornijom na iritacije. Centella Asiatica (Cica) Biljka poznata po svojim lekovitim svojstvima, bogata aktivnim komponentama poput madecassoside i asiaticoside. Deluje protivupalno, ubrzava regeneraciju kože i pomaže u obnavljanju oštećene barijere. U gelu za tuširanje smanjuje iritacije, crvenilo i svrab, naročito kod suve i reaktivne kože. Pantenol (Provitamin B5) Dubinski hidrira kožu, poboljšava zadržavanje vlage i ubrzava obnavljanje kože nakon iritacija ili suvoće. Doprinosi mekoći, elastičnosti i opštoj udobnosti kože, posebno nakon svakodnevnog tuširanja. Dodatno jača kožnu barijeru i ublažava osećaj zatezanja. Alantoin Poznat po svom regenerativnom i umirujućem delovanju, alantoin pomaže u zarastanju mikropovreda i ublažava osećaj suvoće i perutanja. Takođe pomaže u omekšavanju kože i poboljšava glatkoću. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Pine Calming Cica Body Wash je nežni gel za tuširanje formulisan za umirivanje, hidrataciju i obnavljanje osetljive kože tela. Sadrži ekstrakt bora i centelle asiatice (cica), uz dodatak pantenola i hipoalergenskih tenzida koji čiste bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Round-Lab-Pine-Calming-Cica-Body-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
