INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (833, 31, 'Celimax Oil Control Capsule Essence', 'celimax-oil-control-capsule-essence', 'Ključne prednosti: Reguliše lučenje sebuma: Aktivni sastojci u kapsulama ciljano smanjuju prekomerno mašćenje, čime se ten dugoročno matira bez isušivanja kože. Poboljšava teksturu kože: Esencija hidrira i zaglađuje kožu, smanjuje vidljivost pora i poboljšava upijanje narednih proizvoda. Lagana, nekomedogena formula: Ne zagušuje pore, brzo se upija i ne ostavlja lepljiv trag – idealna i kao priprema za šminku. Kome je namenjena? Preporučuje se za masnu, kombinovanu i kožu sklonu proširenim porama, naročito u T-zoni. Pogodna je za svakodnevnu upotrebu i za one koji žele dugotrajan balans između hidratacije i kontrole sjaja. Zašto volimo Celimax Oil Control Capsule Essence? Oil Control Capsule Essence donosi savršen balans između matiranja i hidratacije zahvaljujući naprednoj kapsuliranoj tehnologiji. Svaka kapsula sadrži aktivne komponente koje se oslobađaju direktno prilikom nanošenja, omogućavajući maksimalnu efikasnost bez iritacije. Esencija pomaže u vizuelnom smanjenju pora, poboljšava ravnotežu vlažnosti i masnoće i doprinosi ujednačenom tonu kože. Lagana tekstura momentalno se upija, ostavljajući kožu osveženom, ali ne sjajnom. Aktivni sastojci Niacinamid Niacinamid, poznat i kao vitamin B3, ima višestruko delovanje – smanjuje lučenje sebuma, poboljšava barijernu funkciju kože i umanjuje upale. Efikasan je u borbi protiv proširenih pora i hiperpigmentacija, pa doprinosi ujednačenijem tenu. Njegova blaga priroda čini ga pogodnim čak i za osetljivu kožu, bez rizika od iritacije. U ovoj esenciji koristi se u stabilnoj formi koja garantuje dugoročne rezultate. Čajevac (Tea Tree) ekstrakt Čajevac je prirodni antiseptik poznat po svom antibakterijskom i protivupalnom dejstvu. Smanjuje crvenilo i aktivne upale, čime pomaže u prevenciji akni i mitisera. Osvežava kožu i daje osećaj čistoće bez isušivanja. Posebno je koristan u proizvodima za masnu i kombinovanu kožu zbog svoje sposobnosti da neutrališe bakterije i balansira proizvodnju sebuma. U kombinaciji sa drugim aktivnim sastojcima, jača efekat regulacije masnoće. Zeleni čaj (Camellia Sinensis) ekstrakt Zeleni čaj je snažan antioksidans koji štiti kožu od slobodnih radikala i deluje umirujuće. Bogat polifenolima, pomaže u smanjenju upala i crvenila, dok istovremeno hidrira i jača prirodnu otpornost kože. Njegovo protivupalno dejstvo doprinosi jasnijem tenu i smanjenju sklonosti ka iritacijama. U ovoj formuli pomaže u stabilizaciji masne kože i održavanju zdrave barijere. Dodaj u listu želja Dodaj u listu želja', 'Celimax Oil Control Capsule Essence je esencija sa inkapsuliranim aktivnim sastojcima koja deluje na regulaciju sebuma, hidrataciju i poboljšanje teksture kože. Namenjena je osobama sa masnom i kombinovanom kožom koje žele matiran, balansiran i osvežen ten bez zatezanja ili isušivanja.', 'https://beauty-health.rs/wp-content/uploads/2025/05/Celimax-Oil-Control-Capsule-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
