INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (835, 11, 'Anua Heartleaf 70 Soothing Collagen Mask', 'anua-heartleaf-70-soothing-collagen-mask', 'Ključne prednosti: Umirujuća i hidratantna akcija: Ekstrakt Heartleaf pomaže u smanjenju crvenila i iritacija, čineći kožu smirenijom i uravnoteženijom. Povećava elastičnost kože: Kolagen u sastavu pomaže u obnavljanju kože, čineći je glatkijom i čvršćom. Hidratacija koja traje: Maska pruža dugotrajnu hidrataciju i svežinu, čak i nakon nekoliko sati ili preko noći, zahvaljujući visokom sadržaju vlage. Kome je namenjena? Maska je idealna za sve tipove kože, a posebno za osetljivu, dehidriranu i kožu sklonu crvenilu ili iritacijama. Pogodna je i za osobe koje traže nežnu, ali efikasnu njegu sa umirujućim i učvršćujućim efektima. Zašto volimo Anua Heartleaf 70 Soothing Collagen Mask? Heartleaf 70 Soothing Collagen Mask je savršen izbor za korisnike koji žele da se pobrinu za zdravlje svoje kože bez korišćenja jakih hemijskih sastojaka. S njenim dubokim umirujućim delovanjem, koža je instantno osvežena, dok visoki nivo vlage stvara efekt &#8220;staklene kože&#8221; , sa prirodnim sjajem i glatkoćom. Heartleaf smanjuje upale i pomaže u balansiranju osetljive kože, dok hijaluronska kiselina obnavlja hidrataciju i čini kožu elastičnom. Kolagen pomaže u smanjenju finih linija i poboljšava tonus, ostavljajući kožu čvršćom i mlađom. Maska je takođe odlična za korišćenje tokom noći, jer pruža kontinuiranu hidrataciju i osvežava kožu i ujutro. Aktivni sastojci Heartleaf ekstrakt (Houttuynia Cordata) Ovaj biljni sastojak je poznat po svojim antiinflamatornim i antibakterijskim svojstvima, što ga čini idealnim za negu osetljive i problematične kože. Efikasno umiruje crvenilo i iritacije, dok istovremeno pomaže u regulaciji sebuma i jačanju kožne barijere. Heartleaf takođe deluje kao antioksidans, štiteći kožu od spoljnih agresora i zagađenja. Njegova blaga priroda čini ga pogodnim i za dnevnu i za noćnu negu. U formulaciji maske koristi se u visokoj koncentraciji (70%), što garantuje vidljive efekte nakon samo jedne upotrebe. Takođe, pomaže u revitalizaciji umorne i oslabljene kože. Hijaluronska kiselina Ovaj snažan humektant privlači i zadržava vlagu u koži, čime se obezbeđuje intenzivna i dugotrajna hidratacija. Hijaluronska kiselina obnavlja elastičnost i daje koži puniji, glađi izgled. Takođe pomaže u smanjenju finih linija izazvanih dehidratacijom. U kombinaciji sa drugim hidratantnim sastojcima, ona pojačava barijernu funkciju kože i štiti je od isušivanja. Posebno je korisna kod osoba sa suvom ili dehidriranom kožom. U ovoj formuli koristi se u optimalnoj koncentraciji kako bi efekti bili dubinski i postojani. Kolagen Kolagen niske molekulske mase pomaže koži da postane vidljivo čvršća i elastičnija, jer prodire dublje u epidermalni sloj. Ovaj oblik kolagena stimuliše prirodnu sintezu kolagena u koži, što doprinosi glatkom i zategnutom izgledu. Ujedno poboljšava teksturu kože i smanjuje vidljivost finih linija. Zahvaljujući svojoj lakoj apsorpciji, brzo deluje i ostavlja kožu mekom i osveženom. U ovoj maski se koristi kao funkcionalni anti-age sastojak, bez izazivanja težine ili masnog sloja. Redovnom upotrebom doprinosi očuvanju tonusa i mladalačkog izgleda kože. Dodaj u listu želja Dodaj u listu želja', 'Anua Heartleaf 70 Soothing Collagen Mask je hidratantna i umirujuća maska sa 70% Heartleaf ekstrakta, hijaluronskom kiselinom i kolagenom , koja obnavlja kožu, pružajući duboku hidrataciju i smirujući iritacije. Ova maska je idealna za one koji traže brzo i efikasno umirivanje kože, uz dodatnu elastičnost i osvežavajući efekat.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Anua-Heartleaf-70-Soothing-Collagen-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
