INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (837, 11, 'Anua Airy Sun Cream SPF 50+', 'anua-airy-sun-cream', 'Ključne prednosti: 100% mineralna UV zaštita: Sadrži isključivo Cink oksid , koji efikasno blokira UVA i UVB zrake, štiteći kožu od oštećenja, hiperpigmentacija i preuranjenog starenja. Bez belog traga: Zahvaljujući poroznom puderu, formula se ravnomerno nanosi i prirodno ujednačava ten, bez veštačkog izgleda. Baršunasta tekstura i brzo upijanje: Ne ostavlja lepljivost, pruža lagan osećaj na koži i pogodna je kao podloga za šminku ili samostalnu upotrebu. Kome je namenjena? Proizvod je namenjen svim tipovima kože, uključujući osetljivu, masnu i kombinovanu. Idealna je za svakodnevnu UV zaštitu bez hemijskih filtera i teških formulacija. Zašto volimo Anua Airy Sun Cream? Airy Sun Cream pruža naprednu zaštitu od štetnog sunčevog zračenja uz osećaj laganosti koji traje tokom celog dana. Njena formula se brzo upija i ne ostavlja masni trag, čineći je idealnim izborom za svakodnevnu negu i zaštitu, čak i u toplim i vlažnim uslovima. Zahvaljujući inovativnoj tehnologiji pudera, koža ostaje meka, ujednačena i bez vidljivog belog sloja. Aktivni sastojci Cink oksid (Zinc Oxide) Cink oksid je prirodni mineralni filter koji obezbeđuje širokospektralnu zaštitu od UVA i UVB zračenja. Za razliku od hemijskih filtera, on reflektuje UV zrake sa površine kože, pružajući trenutno dejstvo bez potrebe za apsorpcijom. Njegova prednost je u tome što je blag prema osetljivoj koži i ne izaziva iritacije. Osim toga, ima antiinflamatorna svojstva , što ga čini pogodnim i za osobe sklone crvenilu i rozacei. U Airy Sun Cream koristi se u stabilnom, ne-nano obliku, što dodatno doprinosi bezbednosti i efikasnosti. Dodaj u listu želja Dodaj u listu želja', 'Anua Airy Sun Cream je mineralna krema za sunčanje sa SPF 50+ PA++++ , formulisana isključivo sa cink oksidom za bezbednu, širokospektralnu UV zaštitu. Zahvaljujući tehnologiji disperzije pudera, pruža prirodan finiš bez belog traga i lako se stapa sa kožom.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Anua-Airy-Sun-Cream-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
