INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (838, 114, 'Medicube Deep Peptide Radiance Mask', 'medicube-deep-peptide-radiance-mask', 'Ključne prednosti: Peptidna regeneracija: Kompleks peptida (uključujući Acetyl Dipeptide-1 Cetyl Ester) stimuliše obnovu kože i poboljšava njenu elastičnost. Blistav i ujednačen ten: Niacinamid posvetljuje kožu i ujednačava ten, umanjujući tragove umora i diskoloracije. Hidratacija i zaštita: Pantenol dubinski hidrira, umiruje crvenilo i štiti od spoljašnjih stresora. Kome je namenjena? Idealna je za umornu, dehidriranu i kožu bez sjaja, kao i za sve tipove kože kojima je potrebna dubinska hidratacija, obnova i anti-age nega. Posebno pogodna za kožu izloženu stresu i oštećenjima usled spoljašnjih faktora. Zašto volimo Medicube Deep Peptide Radiance Mask? Deep Peptide Radiance Mask pruža intenzivnu negu kroz kremastu esencu bogatu aktivnim sastojcima, koja se efikasno apsorbuje u kožu bez lepljivog osećaja. Zahvaljujući Acetyl Dipeptide-1 Cetyl Ester sastojku, maska deluje na opuštanje mišića lica, čime doprinosi smanjenju mimičkih bora i jačanju tonusa kože. Niacinamid u formulaciji ujednačava ten, posvetljuje tamne mrlje i pruža koži zdravi sjaj. Pantenol obnavlja oštećenu kožnu barijeru i trenutno ublažava osećaj suvoće ili zategnutosti. Peptidni kompleks dodatno stimuliše sintezu kolagena, dok sama tekstura maske omogućava maksimalnu adheziju i isporuku sastojaka. Redovnom upotrebom, koža postaje mekša, elastičnija i vizuelno zaglađenija. Aktivni sastojci Acetyl Dipeptide-1 Cetyl Ester Peptid koji utiče na opuštanje mišića i ima anti-age efekte slične botulinu. Pomaže u prevenciji i smanjenju izraženosti mimičkih bora i doprinosi glatkijem tenu. Niacinamid Oblik vitamina B3 sa višestrukim benefitima – posvetljuje hiperpigmentacije, poboljšava teksturu kože, reguliše lučenje sebuma i jača kožnu barijeru. Pantenol Poznat i kao provitamin B5, dubinski hidrira i umiruje, podstiče regeneraciju i ublažava crvenilo, svrab i iritacije. Peptidni kompleks Kombinacija funkcionalnih peptida koji stimulišu proizvodnju kolagena i elastina, poboljšavaju tonus kože i učvršćuju konture lica. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Peptide Radiance Mask je intenzivno hidrirajuća sheet maska obogaćena peptidnim kompleksom, niacinamidom i pantenolom, koja doprinosi vidljivo osveženom, čvršćem i blistavijem tenu. Namenjena je jačanju kožne barijere, umirivanju kože i obnavljanju elastičnosti kroz luksuznu kremastu esencu.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-Deep-Peptide-Radiance-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
