INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (839, 164, 'Tirtir PINK Mask Fit All Cover Cushion', 'tirtir-mask-fit-all-cover-cushion', 'Ključne prednosti: Potpuna pokrivenost i prirodan finiš: Ravnomerno prekriva crvenilo, fleke i pore bez efekta maske. 72-časovna hidratacija: Obogaćen hijaluronskom kiselinom i biljnim ekstraktima za dugotrajnu vlažnost i blistavost kože. Lagano i prilagodljivo nanošenje: Prozračna tekstura pogodna za osetljivu i kožu sklonu aknama, uz mogućnost nadogradnje pokrivenosti. Kome je namenjen? Preporučuje se osobama koje žele postojanu podlogu sa visokom pokrivnom moći, bez isušivanja kože. Pogodan je za sve tipove kože, uključujući osetljivu, suvu i aknama sklonu kožu, zahvaljujući blagoj, nekomedogenoj formuli. Zašto volimo TIRTIR Mask Fit All Cover Cushion? Mask Fit All Cover Cushion kombinuje vrhunski efekat prekrivanja sa negom kože, stvarajući balans između šminke i hidratacije. Njegova inovativna formula efikasno ujednačava ten, &#8220;zamagljuje&#8221; pore i prikriva nesavršenosti dok kožu čini mekom i hidriranom. Zahvaljujući 72-časovnom hidratantnom efektu, koža ostaje elastična i negovana, čak i tokom celodnevnog nošenja. Lagana i nekomedogena tekstura omogućava slojevito nanošenje bez zgrušavanja ili osećaja težine. Ovaj cushion puder se ne razmazuje ispod maske, ne ostavlja tragove i postojano izgleda sveže tokom celog dana. Dermatološki testiran i omiljen među korisnicima, pruža skincare + makeup efekat u jednom koraku. Aktivni sastojci Hijaluronska kiselina Deluje kao moćan humektant koji privlači i zadržava vlagu u koži. Pomaže u održavanju elastičnosti, smanjuje dehidrataciju i doprinosi svežem i punijem izgledu kože. Botanički ekstrakti (biljni kompleksi) Prirodni biljni sastojci pružaju umirujuće i antioksidativno delovanje. Štite kožu od spoljašnjih uticaja i pomažu u održavanju zdravog mikrookruženja kože. Niacinamid Pomaže u ujednačavanju tona kože i posvetljavanju hiperpigmentacija. Dodatno jača barijernu funkciju kože i pruža blistavost. Adenozin Ima anti-age dejstvo, poboljšava glatkoću kože i smanjuje vidljivost finih linija i bora. Skvalan Biljni emolijens koji hidrira i omekšava kožu bez začepljivanja pora, čineći je prijatno glatkom i zaštićenom. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit All Cover Cushion je multifunkcionalni tečni puder u jastučiću koji pruža puno prekrivanje uz 72 sata hidratacije. Zahvaljujući hijaluronskoj kiselini i botaničkim ekstraktima, koži pruža prirodan, besprekoran izgled bez osećaja težine i isušivanja. Nijanse detaljno možete pogledati na zvaničnom sajtu preparata.', 'https://beauty-health.rs/wp-content/uploads/2025/04/TIRTIR-Mask-Fit-All-Cover-Cushion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
