INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (840, 109, 'Manyo Panthetoin Enriched Balm', 'manyo-panthetoin-enriched-balm', 'Ključne prednosti: Duboka i dugotrajna hidratacija: Višeslojna vlaga zahvaljujući hijaluronskoj kiselini, patentiranim molekulima i ceramidima. Umiruje crvenilo i iritacije: SYMCALMIN® i alantoin ciljano smanjuju nadraženost i pružaju osećaj prijatnosti. Jača kožnu barijeru i otpornost: Kompleks Panthetoin™ deluje zaštitno i regenerativno u nepovoljnim uslovima. Kome je namenjena? Preporučuje se za suvu, dehidriranu, oslabljenu i osetljivu kožu, kao i za korisnike koji traže intenzivnu, ali nemasnu negu. Idealna za upotrebu tokom zime ili kod narušene barijere usled upotrebe aktivnih sastojaka (npr. retinola, kiselina). Zašto volimo Manyo Panthetoin Enriched Balm? Panthetoin Enriched Balm pruža efikasnu hidrataciju bez osećaja težine, zahvaljujući kombinaciji klinički potvrđenih sastojaka i inovativnih tehnologija. Patentirani Sydney Ringer+ kompleks brzo obnavlja nivoe vlage. Niskomolekularna hijaluronska kiselina omogućava prodiranje do dubljih slojeva kože. U-Oliosom ceramidi, zbog svoje mikroskopske veličine, prodiru duboko u kožu i pomažu u jačanju barijere. Zahvaljujući prisustvu Panthetoin™ kompleksa, koji kombinuje 20.000 ppm pantenola i 5.000 ppm ektoina, balzam istovremeno hidrira, umiruje i štiti kožu od oksidativnog stresa. Allantoin i SYMCALMIN® dodatno ublažavaju crvenilo i ostavljaju kožu mekom, elastičnom i bez ljuštenja. Tekstura je bogata, ali se brzo upija, ostavljajući kožu osveženom i negovanom. Aktivni sastojci Panthetoin™ (Panthenol + Ectoin) Patentirani kompleks u zlatnom odnosu 4:1 koji kombinuje hidrataciju (Panthenol) i zaštitu od stresa i zagađenja (Ectoin). Pomaže u očuvanju vlage i jača kožnu otpornost čak i u suvim i ekstremnim uslovima. Hijaluronska kiselina (niskomolekularna) Prodire duboko u epidermis i veže vlagu u ćelijama kože. Održava elastičnost, čini kožu punijom i smanjuje osećaj zatezanja. Ceramidi (U-Oliosome) Mikro-ceramidi manji od pora prodiru u kožu i pomažu u obnavljanju oštećene lipidne barijere. Pružaju koži dugotrajnu zaštitu i sprečavaju gubitak vlage. SYMCALMIN® Patentirani sastojak na bazi ovsa koji deluje protivupalno, umiruje crvenilo i reaktivnu kožu. Posebno koristan kod iritacija izazvanih hladnoćom ili aktivnim sastojcima. Alantoin Smiruje grubu i nadraženu kožu, pomaže u uklanjanju mrtvih ćelija i ubrzava regeneraciju površinskog sloja. Dodaj u listu želja Dodaj u listu želja', 'Manyo Panthetoin Enriched Balm je bogata, ali nelepljiva hidratantna krema, formulisana sa patentiranim kompleksom Panthetoin™ (Panthenol + Ectoin), niskomolekularnom hijaluronskom kiselinom i ceramidima, za intenzivnu i dugotrajnu hidrataciju. Posebno je namenjena umirenju, obnavljanju i jačanju kožne barijere, čak i u ekstremno suvim uslovima.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Manyo-Panthetoin-Enriched-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
