INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (842, 82, 'Innisfree Green Tea Seed Hyaluronic Cream', 'innisfree-green-tea-seed-hyaluronic-cream', 'Ključne prednosti: Dubinski hidrira i zadržava vlagu: Hijaluronski kompleks i zeleni čaj pružaju višeslojnu hidrataciju i osvežavaju kožu. Poboljšava elastičnost i barijernu funkciju: Antioksidansi iz zelenog čaja štite kožu i jačaju njenu otpornost. Lagana, nelepljiva tekstura pogodna za sve tipove kože: Idealna za dnevnu i noćnu negu bez osećaja težine. Kome je namenjena? Preporučena za normalnu, kombinovanu i suvu kožu, kao i za korisnike sa dehidriranom, umornom i stresiranom kožom. Pogodna za sve tipove kože, uključujući i osetljivu, zahvaljujući umirujućoj i biljno zasnovanoj formuli. Zašto volimo Innisfree Green Tea Seed Hyaluronic Cream? Green Tea Seed Cream koristi inovativnu Beauty Green Tea™ formulu, razvijenu iz posebne vrste zelenog čaja uzgajanog isključivo na čistom Jeju ostrvu, bogatog 16 aminokiselina koje obnavljaju i hidriraju kožu. U kombinaciji sa uljem semenki zelenog čaja, ova krema prodire dublje u kožu i pomaže joj da zadrži vlagu duže vreme. Pet vrsta hijaluronske kiseline omogućava višeslojnu hidrataciju i vidno smanjuje osećaj zategnutosti i suvoće. Pored hidratacije, antioksidansi iz zelenog čaja pomažu u zaštiti kože od štetnih uticaja iz okoline i poboljšavaju tonus kože. Tekstura je bogata, ali brzo upijajuća i nelepljiva, što je čini pogodnom za svakodnevnu negu i kao podloga za šminku. Aktivni sastojci Ekstrakt zelenog čaja (Beauty Green Tea™) Dobijen iz posebno kultivisane vrste zelenog čaja sa Jeju ostrva, bogat aminokiselinama i polifenolima koji hidrira, umiruje i štiti kožu. Doprinosi ujednačenijem tenu i zdravom sjaju. Ulje semena zelenog čaja Doprinosi dugotrajnijem zadržavanju vlage u koži, jača kožnu barijeru i ima umirujuće dejstvo. Pogodno za osetljivu i isušenu kožu. 5 vrsta hijaluronske kiseline Višemolekularna hijaluronska kiselina hidrira više slojeva kože – od površinskog do dubinskog – ostavljajući kožu punijom, elastičnijom i glatkom. Pantenol (Provitamin B5) Umiruje i obnavlja kožu, jača zaštitnu funkciju i sprečava isušivanje. Doprinosi boljoj otpornosti kože na spoljašnje agresore. Skvalan Lagana lipidna komponenta koja oponaša prirodna ulja kože. Hidrira, omekšava i štiti bez začepljenja pora ili masnog osećaja. Dodaj u listu želja Dodaj u listu želja', 'Innisfree Green Tea Seed Cream je hidratantna i antioksidativna krema formulisana sa ekstraktom i uljem zelenog čaja sa Jeju ostrva, kao i 5 vrsta hijaluronske kiseline, koja intenzivno hidrira, umiruje i štiti kožu od isušivanja i spoljašnjih stresora. Namenjena je koži kojoj je potrebna dubinska hidratacija i jačanje zaštitne barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Innisfree-Green-Tea-Seed-Hyaluronic-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
