INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (843, 80, 'Illiyoon Hyaluronic Moisture Cream', 'illiyoon-hyaluronic-moisture-cream', 'Ključne prednosti: Višeslojna hidratacija: Hijaluronska kiselina različitih molekulskih masa hidrira površinske i dublje slojeve kože. Jačanje barijere kože: Ceramidi i biljni lipidi obnavljaju zaštitnu funkciju kože i štite od isušivanja. Prijatna, nelepljiva tekstura: Bogata, ali brzo upijajuća formula idealna za dnevnu i noćnu negu. Kome je namenjena? Preporučena za suvu, dehidriranu, osetljivu i reaktivnu kožu, kao i za korisnike koji traže kremu za dugotrajnu hidrataciju bez iritacije. Pogodna je za sve tipove kože, naročito tokom hladnijih meseci ili kod narušene barijere. Zašto volimo ILLIYOON Hyaluronic Moisture Cream? Hyaluronic Moisture Cream koristi snagu višestruko umreženih hijaluronskih molekula za hidrataciju u svim slojevima kože – od epidermisa do dubljih slojeva dermisa. Ova hidratantna krema se ističe i prisustvom ceramida iz sojinog ulja, koji doprinose obnovi i zaštiti oštećene barijere kože, čineći je otpornijom i elastičnijom. Lagana, ali hranljiva tekstura prijatno se razmazuje, brzo upija i ne ostavlja lepljiv film, što je čini pogodnom za jutarnju rutinu i nanošenje ispod šminke. Redovnom upotrebom koža postaje mekša, hidriranija i manje sklona iritacijama i zatezanju, dok se prirodna ravnoteža ulja i vlage održava stabilnom. Aktivni sastojci Višemolekularna hijaluronska kiselina Kombinuje molekule različite veličine koje prodiru u više slojeva kože. Površinske hidrira odmah, dok dubinske zadržavaju vlagu tokom celog dana. Efekat je punija, mekša i elastičnija koža. Biljni ceramidi (Ceramide NP) Pomažu u obnovi lipidne barijere kože i sprečavaju gubitak vlage. Posebno su efikasni u tretiranju suve, zategnute i oslabljene kože. Ekstrakt fermentisanog sojinog ulja Bogat esencijalnim masnim kiselinama koje hrane kožu, poboljšavaju njenu teksturu i doprinose zdravijem mikrobiomu. Glicerin Prirodni ovlaživač koji pomaže u vezivanju vlage i održava mekoću i hidriranost kože tokom celog dana. Skvalan Lagani lipid koji ne opterećuje kožu, pomaže u zadržavanju vlage i jača prirodnu otpornost kože na spoljne uticaje. Dodaj u listu želja Dodaj u listu želja', 'ILLIYOON Hyaluronic Moisture Cream je intenzivno hidratantna krema obogaćena višemolekularnom hijaluronskom kiselinom i biljnim ceramidima, formulisana za dubinsku hidrataciju i jačanje kožne barijere. Idealna za suvu, osetljivu i dehidriranu kožu, pruža dugotrajan osećaj vlažnosti bez lepljivosti.', 'https://beauty-health.rs/wp-content/uploads/2025/04/ILLIYOON-Hyaluronic-Moisture-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
