INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (844, 151, 'Shiseido Fino Premium Touch Shampoo', 'shiseido-fino-premium-touch-shampoo', 'Ključne prednosti: Nežno, ali efikasno čišćenje: Uklanja nečistoće bez isušivanja vlasišta i kose. Dubinska regeneracija i hidratacija: Pomaže u oporavku oštećenih vlasi i vraća elastičnost. Ojačava kosu i poboljšava njen sjaj: Aktivni sastojci deluju u sinergiji za puniji, zdraviji izgled kose. Kome je namenjen? Idealan za suvu, oštećenu, hemijski tretiranu ili često stilizovanu kosu. Preporučuje se i osobama koje žele profesionalnu negu kose kod kuće, uz istovremenu hidrataciju i zaštitu od mehaničkih i toplotnih oštećenja. Zašto volimo Shiseido Fino Premium Touch Shampoo? Fino Premium Touch Shampoo pruža spa-nivou negu u kućnim uslovima, zahvaljujući luksuznoj formuli bogatoj funkcionalnim kozmetičkim sastojcima. Royal jelly ekstrakt (matični mleč) revitalizuje kosu iznutra, dok skvalan i lipidni agensi hidriraju vlasi bez da ih otežaju. Proteini pšenice pomažu u obnavljanju oštećenih vlakana kose, poboljšavajući teksturu i otpornost. Formula nežno peni, ne isušuje i pogodna je za svakodnevno pranje, čineći kosu mekšom, elastičnijom i lakšom za oblikovanje. U kombinaciji sa Fino Premium Touch regeneratorom ili maskom, efekti nege su znatno intenzivniji i dugotrajniji. Aktivni sastojci Royal Jelly Ekstrakt Bogat izvor aminokiselina, vitamina i minerala koji revitalizuju i obnavljaju kosu, povećavajući njenu mekoću i sjaj. Skvalan Lagani emolijent biljnog porekla koji hidrira i omekšava kosu, bez osećaja masnoće. Poboljšava elastičnost i štiti vlasi od isušivanja. Proteini pšenice Popunjavaju oštećene delove vlasi, jačaju strukturu kose i poboljšavaju njenu otpornost na spoljne agresore (toplota, UV, hemikalije). Lipidni kompleksi Pomažu u zadržavanju vlage i vraćanju prirodne zaštitne funkcije kose, štiteći od gubitka sjaja i pucanja. Trehaloza Hidratantni šećer koji štiti kosu od dehidratacije i oksidativnog stresa izazvanog UV zračenjem ili zagađenjem. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Fino Premium Touch Shampoo je obnavljajući šampon za kosu koji kombinuje royal jelly ekstrakt, skvalan, pšenične proteine i hidratantne agense kako bi dubinski očistio vlasište i istovremeno ojačao, omekšao i zaštitio kosu od isušivanja i lomljenja. Namenjen je nezi oštećene, suve i tretirane kose.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Shiseido-Fino-Premium-Touch-Shampoo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
