INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (846, 151, 'Shiseido Fino Premium Touch Hair Mask', 'shiseido-fino-premium-touch-hair-mask', 'Ključne prednosti: Obnavlja oštećenu strukturu dlake: Keratin i proteini svile prodiru duboko i rekonstruišu vlakna kose. Pruža intenzivnu hidrataciju i zaštitu: Skvalan i pantenol vraćaju vlagu i elastičnost. Poboljšava sjaj, mekoću i upravljivost: Kosa postaje vidno glađa i lakša za stilizovanje. Kome je namenjena? Idealna za suvu, hemijski tretiranu, farbanu i često feniranu kosu, kao i za sve koji žele dubinski tretman za oporavak kose bez otežavanja vlasi. Pogodna za sve tipove kose, posebno za oštećenu i beživotnu kosu. Zašto volimo Shiseido Fino Premium Touch Hair Mask? Fino Premium Touch Hair Mask je luksuzna tretmanska maska razvijena kako bi vratila vitalnost i elastičnost kosi izložene svakodnevnim stresorima – od farbanja i toplote do UV zračenja. Njena formula bogata 6 vrsta aktivnih sastojaka, uključujući keratin, pantenol, skvalan i lipide, prodire duboko u jezgro dlake i obnavlja je iznutra. Posebna kombinacija proteina i ovlaživača zadržava vlagu unutar dlake, čime se sprečava lomljenje i perutanje krajeva. Rezultat je glatka, jaka i sjajna kosa koja zrači zdravljem. Maska ne masti vlasište, brzo se ispira i ostavlja dugotrajan efekat već nakon prve upotrebe. Njena baršunasta tekstura i nežan miris čine svaki tretman prijatnim ritualom. Aktivni sastojci Keratin Prirodni protein koji popunjava oštećene delove dlake, povećava snagu, otpornost i štiti kosu od budućih oštećenja. Idealno za hemijski oslabljenu i farbanu kosu. Skvalan Lipid koji hidrira i obnavlja površinski sloj dlake, čineći je mekom i sjajnom bez otežavanja. Sprečava isušivanje izazvano toplotom i UV zracima. Pantenol (Provitamin B5) Obnavlja i jača dlaku iznutra, povećava elastičnost i smanjuje lomljenje. Pruža prirodan sjaj i poboljšava strukturu dlake. Ekstrakt svile Sadrži proteine koji zaglađuju površinu kose, čineći je svilenkastom i lakšom za raščešljavanje. Pomaže u zatvaranju kutikule za dugotrajan sjaj. Fitosteroli i lipidi Obnavljaju lipidni balans kose i štite je od gubitka vlage. Deluju kao prirodna barijera protiv agresivnih spoljašnjih faktora. Dodaj u listu želja Dodaj u listu želja', 'Shiseido Fino Premium Touch Hair Mask je intenzivna maska za dubinsku regeneraciju kose, obogaćena keratinom, skvalanom, pantenolom i ekstraktima svile. Namenjena je za obnovu suve, oštećene i hemijski tretirane kose, pružajući joj zdrav izgled, mekoću i dugotrajan sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Shiseido-Fino-Premium-Touch-Hair-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
