INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (847, 146, 'S.Nature Aqua Squalane Moisturizing Cream', 's-nature-aqua-squalane-moisturizing-cream', 'Ključne prednosti: Intenzivna i dugotrajna hidratacija: Biljni skvalan i hijaluronska kiselina obnavljaju vlagu u dubljim slojevima kože. Poboljšava barijernu funkciju kože: Pantenol i ceramidi umiruju, obnavljaju i štite kožu od spoljnih uticaja. Veliko pakovanje za svakodnevnu negu: Jumbo format odlično odgovara porodicama, salonima ili korisnicima koji žele visoku vrednost i dugotrajnu upotrebu. Kome je namenjena? Preporučena za suvu, dehidriranu, normalnu i osetljivu kožu, kao i za one koji žele bogatu, ali nelepljivu svakodnevnu hidrataciju. Idealan izbor i za kožu pod stresom, nakon kozmetičkih tretmana ili tokom promena godišnjih doba. Zašto volimo S.NATURE Aqua Squalane Moisturizing Cream? Aqua Squalane Moisturizing Cream Jumbo donosi jednostavnu, ali moćnu negu kože zahvaljujući pažljivo biranim, funkcionalnim sastojcima. Skvalan biljnog porekla imitira prirodne lipide kože i obezbeđuje zaštitu i elastičnost bez osećaja težine ili masnoće. Pantenol (provitamin B5) umiruje crvenilo, iritacije i pomaže u regeneraciji barijere, dok hijaluronska kiselina hidrira sve slojeve kože, ostavljajući je mekom i punom. Uz to, ekstrakti morskih algi i ceramidi doprinose zaštiti kože od zagađenja i gubitka vlage. Kremasta tekstura se brzo upija i ne ostavlja lepljiv trag, zbog čega je pogodna za dnevnu i noćnu upotrebu. Jumbo pakovanje čini ovaj proizvod izuzetno praktičnim za celu porodicu ili profesionalnu upotrebu. Aktivni sastojci Skvalan Biljni emolijent koji je izuzetno kompatibilan sa prirodnim lipidima kože. Omekšava kožu, sprečava transepidermalni gubitak vlage i poboljšava njenu elastičnost bez zagušivanja pora. Pantenol (Provitamin B5) Umiruje iritacije, ubrzava regeneraciju i jača zaštitnu funkciju kože. Posebno koristan kod osetljive i reaktivne kože sklone crvenilu i isušivanju. Hijaluronska kiselina Ovlaživač koji privlači i zadržava vlagu u koži, popunjava fine linije i doprinosi dugotrajnoj hidrataciji i sjaju. Ceramidi Lipidi koji obnavljaju prirodnu barijeru kože, čineći je otpornijom na spoljašnje uticaje i gubitak vlage. Neophodni za suvu i dehidriranu kožu. Morske alge (ekstrakt algi) Prirodni antioksidansi koji detoksikuju i štite kožu od oksidativnog stresa. Deluju umirujuće i doprinose ujednačenijem tenu. Dodaj u listu želja Dodaj u listu želja', 'S.NATURE Aqua Squalane Moisturizing Cream je bogata, ali lagana hidratantna krema koja kombinuje biljni skvalan, pantenol i ekstrakte morskih algi kako bi koži pružila dugotrajnu vlagu, mekoću i zaštitu. Formulisana za osetljivu kožu, jača barijeru i obnavlja suvu i dehidriranu kožu bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2025/04/S.NATURE-Aqua-Squalane-Moisturizing-Cream-Jumbo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
