INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (848, 114, 'Medicube PDRN Pink Collagen Exosome Shot Serum 2000', 'medicube-pdrn-pink-collagen-exosome-shot-serum-2000', 'Ključne prednosti: Blaga formulacija za svakodnevnu negu: 2.000 ppm aktivnih čestica omogućava efikasnu, ali nežnu stimulaciju kože. Povećava nivo vlage i elastičnost: Hijaluronska kiselina i kolagen vraćaju koži punoću i hidriranost. Umiruje i jača barijeru kože: PDRN i peptidi obnavljaju kožu i štite je od spoljašnjih faktora. Kome je namenjen? Idealna za osetljivu, suvu, dehidriranu i zrelu kožu, kao i za one koji počinju sa aktivnim anti-age negama. Pogodna je za korisnike koji traže dugoročne rezultate bez iritacija i žele proizvod koji se može koristiti svakog dana. Zašto volimo Medicube PDRN Pink Collagen Exosome Shot Serum 2000? PDRN Pink Collagen Exosome Shot Serum 2000 je razvijen kao svakodnevna verzija intenzivne anti-age terapije, pružajući vidljive efekte bez agresivnih reakcija. Formulacija sa 2.000 ppm mikročestica omogućava delikatnu penetraciju u kožu, čineći je pogodnom i za početnike. PDRN ubrzava obnavljanje ćelija i jača strukturu kože, dok ultra-niskomolekularni kolagen (200DA) doprinosi čvrstoći i sjaju. 8 vrsta hijaluronske kiseline hidrira u više slojeva, dajući koži „glass skin“ efekat, dok 3-peptidni kompleks deluje na povećanje elastičnosti i smanjenje finih linija. Serum ima osvežavajuću teksturu koja se brzo upija, ostavljajući kožu punijom, zdravijom i dugotrajno hidriranom bez lepljivosti. Aktivni sastojci PDRN (Polidezoksiribonukleotid) Obnavlja ćelijsku strukturu kože, ubrzava regeneraciju i štiti od prevremenog starenja. Pogodan za svakodnevnu upotrebu zahvaljujući nižoj koncentraciji. 200DA Kolagen Ultra-niskomolekularni kolagen brzo prodire u kožu, povećava čvrstoću i vraća prirodan sjaj bez zatezanja ili isušivanja. 8 vrsta hijaluronske kiseline Različite molekulske mase omogućavaju višeslojnu hidrataciju, čime se sprečava transepidermalni gubitak vlage i povećava elastičnost. 3-peptidni kompleks Podstiče sintezu kolagena i elastina, poboljšava tonus kože i deluje protiv finih linija i gubitka čvrstoće. Kolagen egzozomi Mikročestice koje efikasno prenose kolagen i aktivne komponente duboko u epidermis, povećavajući efikasnost tretmana. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Collagen Exosome Shot Serum 2000 je hidratantni anti-age serum formulisan za svakodnevnu upotrebu, sa blagim, ali efikasnim dejstvom zahvaljujući PDRN-u, 8 vrsta hijaluronske kiseline, 200DA kolagenu i 3-peptidnom kompleksu. Ova verzija pruža regeneraciju, dubinsku hidrataciju i osnaživanje kože bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-PDRN-Pink-Collagen-Exosome-Shot-Serum-2000.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
