INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (849, 114, 'Medicube PDRN Pink Collagen Exosome Shot Serum 7500', 'medicube-pdrn-pink-collagen-exosome-shot-serum-7500', 'Ključne prednosti: Povećava nivo vlažnosti za 47,7% nakon jedne primene: Zahvaljujući hijaluronskim kompleksima i kolagenu ultra-niske molekulske mase. Regeneriše i zateže kožu: PDRN i peptidi stimulišu obnavljanje i čine kožu čvršćom i otpornijom. Intenzivna apsorpcija kroz mikrostrukturu: Napredna tekstura sa mikronizovanim egzosomima efikasno dostavlja aktivne sastojke duboko u kožu. Kome je namenjen? Preporučuje se osobama sa znacima starenja, gubitkom elastičnosti, suvom i beživotnom kožom, kao i onima koji žele profesionalnu anti-age negu kod kuće. Verzija 7.500 ppm namenjena je iskusnijim korisnicima koji žele intenzivan efekat u kratkom vremenskom periodu (3-dnevni ciklus). Zašto volimo Medicube PDRN Pink Collagen Exosome Shot Serum 7500? PDRN Pink Collagen Exosome Shot Serum 7500 donosi inovativan pristup kućnoj nezi, koristeći aktivne komponente inspirisane dermatološkim tretmanima. Formulisan sa 7.500 ppm mikročestica u obliku iglica (prirodna pojava sastojaka), ovaj serum omogućava dubinsku penetraciju i brze rezultate. PDRN (Polidezoksiribonukleotid) stimuliše ćelijsku obnovu i poboljšava strukturu kože, dok 200DA kolagen – ultra-niske molekulske mase – pruža elastičnost i sjaj. 8 vrsta hijaluronske kiseline hidrira više slojeva kože, sprečavajući transepidermalni gubitak vode. 3-peptidni kompleks deluje ciljano na zatezanje kože, popunjavanje finih linija i očuvanje čvrstoće. Serum je formulisan za brzo upijanje bez lepljivosti i idealan je kao deo intenzivne anti-age rutine u ciklusima. Aktivni sastojci PDRN (Polidezoksiribonukleotid) Biotehnološki derivat DNK koji ubrzava regeneraciju kože, stimuliše sintezu kolagena i smanjuje znake starenja. Klinički priznat za tretman oštećene, opuštene i tanke kože. 200DA Kolagen Kolagen ultra-niske molekulske mase omogućava bržu i dublju apsorpciju. Poboljšava čvrstoću, smanjuje bore i vraća prirodan sjaj koži. 8 vrsta hijaluronske kiseline Obezbeđuju višeslojnu hidrataciju – od površine do dubljih slojeva dermisa. Koža postaje mekša, elastičnija i manje sklona perutanju ili zatezanju. 3-peptidni kompleks Signalni peptidi stimulišu proizvodnju kolagena i elastina, čime poboljšavaju elastičnost i strukturu kože iznutra. Kolagen egzosomi Mikročestice visoke bioraspoloživosti koje efikasno prenose kolagen i ostale aktivne sastojke dublje u kožu, za brže i ujednačenije rezultate. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Collagen Exosome Shot Serum 7500 je visokokoncentrovani serum za čvrstoću i regeneraciju kože, formulisan sa PDRN-om, egzozomima kolagena, 3-peptidnim kompleksom i 8 vrsta hijaluronske kiseline. Vidljivo povećava nivo hidratacije i elastičnosti već nakon jedne upotrebe, ostavljajući kožu čvršćom, blistavijom i obnovljenom.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-PDRN-Pink-Collagen-Exosome-Shot-Serum-7500.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
