INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (850, 174, 'VT Cosmetics S4 Moisture Ampoule', 'vt-cosmetics-s4-moisture-ampoule', 'Ključne prednosti: Jača barijeru kože: Skvalan prirodnog porekla poboljšava elastičnost i sprečava gubitak vlage. Intenzivno umiruje i regeneriše: Cica egzosomi ciljano ublažavaju crvenilo i osetljivost. Balansira sebum i vlagu: Ekstrakt zelenog čaja osvežava ten i održava zdravu kožnu mikrofloru. Kome je namenjena? Idealna za osetljivu, dehidriranu, masnu i kombinovanu kožu, kao i za one koji žele ojačati prirodnu barijeru kože bez osećaja težine. Pogodna za svakodnevnu upotrebu, uključujući i kožu sklonu iritacijama. Zašto volimo VT Cosmetics S4 Moisture Ampoule? S4 Moisture Ampoule je formulisana kako bi pružila intenzivnu, ali nežnu negu kože zahvaljujući kombinaciji inovativnih i biljnih sastojaka. Biljni skvalan pruža koži neophodne lipide koji obnavljaju barijeru i zadržavaju vlagu, bez osećaja masnoće. Cica egzosomi (visokokoncentrisani aktivni derivati iz Centella Asiatica) prodiru dublje u kožu, ciljano smanjuju crvenilo, umiruju iritacije i pospešuju oporavak osetljive kože. Ekstrakt zelenog čaja deluje antioksidativno i antibakterijski, pomažući u regulaciji sebuma i osvežavanju tena. Tekstura je bogata, ali se brzo upija i ne ostavlja lepljiv trag, što ovu ampulu čini idealnom i za jutarnju i večernju negu. Koža ostaje elastična, uravnotežena i dugotrajno hidrirana. Aktivni sastojci Skvalan (biljnog porekla) Prirodni lipid koji oponaša sopstvene masnoće kože, pomažući u obnovi barijere i sprečavanju isušivanja. Ne začepljuje pore i ostavlja kožu mekom i zaštićenom. Cica Exosome Egzosomi iz Centella Asiatica omogućavaju bolju penetraciju aktivnih jedinjenja, pružajući snažno umirujuće i regenerativno dejstvo. Deluju efikasno na crvenilo, osetljivost i mikrooštećenja kože. Ekstrakt zelenog čaja Bogat polifenolima i antioksidansima, pomaže u borbi protiv slobodnih radikala i upala. Reguliše sebum i pruža svež i čist izgled kože. Pantenol (Provitamin B5) Hidratantni i umirujući sastojak koji pomaže u oporavku kože i sprečava iritacije. Idealan za osetljivu i reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics S4 Moisture Ampoule je intenzivno hidratantna i umirujuća ampula na bazi biljnog skvalana , Cica egzosoma i ekstrakta zelenog čaja . Namenjena je jačanju kožne barijere, dugotrajnoj hidrataciji i balansiranju odnosa ulja i vlage u koži.', 'https://beauty-health.rs/wp-content/uploads/2025/04/VT-Cosmetics-S4-Moisture-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
