INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (852, 174, 'VT Cosmetics R5 Firming Ampoule', 'vt-cosmetics-r5-firming-ampoule', 'Ključne prednosti: Zateže i učvršćuje kožu: R5 retinoidni kompleks stimuliše sintezu kolagena i obnavlja kožnu strukturu. Smanjuje bore i fine linije: Peptidi i kolagen deluju dubinski, poboljšavajući elastičnost i glatkoću kože. Obnavlja tonus i revitalizuje ten: Hranljiva formula vraća volumen i svežinu umornoj koži. Kome je namenjena? Ova ampula je idealna za zrelu, opuštenu i kožu sa vidljivim znacima starenja, uključujući fine linije, gubitak čvrstoće i neujednačenu teksturu. Pogodna za normalnu, suvu i kombinovanu kožu, osim izrazito osetljive (zbog prisustva retinoida). Zašto volimo VT Cosmetics R5 Firming Ampoule? VT R5 Firming Ampoule je visokoefikasna anti-age ampula formulisana sa fokusom na lifting efekat i zatezanje kože. Njena ključna komponenta, R5 kompleks, kombinuje pet oblika retinoida uključujući retinol, retinal i retinyl estere, kako bi se postigla maksimalna efikasnost sa minimalnom iritacijom. Ovaj kompleks podstiče regeneraciju kože, povećava proizvodnju kolagena i elastina i vidljivo smanjuje dubinu bora. Peptidi dodatno učvršćuju kožu i pomažu u redefinisanju kontura lica. Kolagen i skvalan hidrira i omekšava, vraćajući koži glatkoću i elastičnost. Tekstura je bogata, ali brzo upijajuća, pogodna za noćnu i dnevnu rutinu (uz SPF). Rezultat je zategnutija, čvršća i blistavija koža, sa dugotrajnim efektima. Aktivni sastojci R5 Retinoid Complex Kombinacija 5 stabilizovanih oblika retinoida – uključujući retinol, retinaldehid, retinyl palmitate, retinyl propionate i HPR – pruža anti-age efekte bez iritacije. Deluje na obnavljanje ćelija, povećava elastičnost, smanjuje bore i poboljšava ukupnu teksturu kože. Peptidni kompleks Signalni molekuli koji stimulišu proizvodnju kolagena i elastina. Pomažu u zatezanju kože, smanjuju vidljivost bora i podržavaju regeneraciju ćelijskog matriksa. Hidrolizovani kolagen Pruža koži elastičnost i mekoću, deluje kao humektant koji zadržava vlagu u dubljim slojevima kože. Doprinosi efektu „punije“ kože i poboljšava tonus. Skvalan Prirodni lipid koji hidrira, umiruje i štiti kožu od dehidratacije bez začepljenja pora. Održava kožnu barijeru i povećava apsorpciju aktivnih sastojaka. Pantenol (Provitamin B5) Smiruje iritacije i crvenilo koje može biti izazvano retinoidima. Pruža regenerativni efekat i povećava otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics R5 Firming Ampoule je intenzivna lifting i učvršćujuća ampula obogaćena R5 kompleksom od 5 vrsta retinoida, peptidima i kolagenom za vidljivo poboljšanje elastičnosti, čvrstoće i teksture kože. Namenjena je ciljanom anti-age delovanju i obnavljanju tonusa opuštene kože.', 'https://beauty-health.rs/wp-content/uploads/2025/04/VT-Cosmetics-R5-Firming-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
