INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (855, 154, 'Skin1004 Madagascar Centella Tone Brightening Tone-Up Sunscreen', 'skin1004-madagascar-centella-tone-brightening-tone-up-sunscreen', 'Ključne prednosti: Visoka UV zaštita i posvetljivanje kože: Širokospektralni SPF50+ PA++++ štiti od UVA/UVB zračenja, dok niacinamid i glutation ujednačavaju ten. Nežan tone-up efekat bez belih tragova: Lagana formula pruža prirodno osvetljen ten bez osećaja težine i bez zatvaranja pora. Umiruje i štiti kožnu barijeru: Centella Asiatica i madecassoside smanjuju crvenilo i podržavaju kožu pod stresom. Kome je namenjena? Idealno za normalnu, masnu, kombinovanu i osetljivu kožu, kao i za osobe koje traže nevidljivu zaštitu od sunca sa blagim efektom posvetljivanja i dodatnim benefitima nege. Pogodno i kao primer ispod šminke za ujednačen ten. Zašto volimo SKIN1004 Madagascar Centella Tone Brightening Tone-Up Sunscreen? Madagascar Centella Tone Brightening Tone-Up Sunscreen kombinuje naprednu fizičku zaštitu od sunca sa funkcionalnim sastojcima koji ne samo da štite, već i poboljšavaju izgled kože. Titanijum dioksid reflektuje UV zrake bez hemijskih filtera, dok Centella Asiatica iz Madagaskara (21%) deluje umirujuće i obnavlja kožu izloženu stresu. Niacinamid i glutation posvetljuju ten, smanjuju fleke i ujednačavaju boju kože, dok madecassoside i pantenol dodatno ublažavaju crvenilo i jačaju barijeru. Tonirana formula ima nežan roze-bež podton koji neutrališe sivilo i žućkast ten, ostavljajući prirodan, osvetljen izgled bez „flashbacka“. Ne sadrži alkohol, parfeme ni iritativne sastojke, čineći ga idealnim za svakodnevnu upotrebu. Aktivni sastojci Centella Asiatica (Madagaskarski ekstrakt – 21%) Deluje umirujuće, protivupalno i regenerativno. Bogata asiaticoside-om, madecassoside-om i asiatic acid-om, Centella iz Madagaskara štiti kožu od iritacija izazvanih suncem i jača kožnu otpornost. Niacinamide Vitamin B3 posvetljuje kožu, smanjuje pigmentacije i jača barijeru. U ovoj formuli doprinosi ujednačavanju tena i dodatnoj zaštiti od oksidativnog stresa. Glutation Snažan antioksidans koji inhibira proizvodnju melanina i doprinosi ujednačenijem, blistavijem tenu. Takođe deluje kao zaštita od spoljašnjih agresora i stresa iz okoline. Madecassoside Jedan od glavnih aktivnih komponenti Centelle, poznat po svojim snažnim umirujućim i antiinflamatornim svojstvima. Ublažava iritacije, smanjuje crvenilo i podržava regeneraciju kože. Titanijum dioksid (Titanium Dioxide) Fizički UV filter koji odbija UVA i UVB zrake. Blag prema koži, ne izaziva iritacije i ne prodire u kožu. Idealan za osetljivu kožu i svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Tone Brightening Tone-Up Sunscreen je višenamenski tonirani SPF koji kombinuje visoku UV zaštitu (SPF50+ PA++++) sa njegom i efektom posvetljivanja, zahvaljujući Centella Asiatica ekstraktu, niacinamidu i glutationu. Ovaj mineralni sunscreen ujednačava ten, pruža prirodan „tone-up“ efekat i štiti kožu bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/04/SKIN1004-Madagascar-Centella-Tone-Brightening-Tone-Up-Sunscreen.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
