INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (857, 143, 'Round Lab Soybean Panthenol Toner', 'round-lab-soybean-panthenol-toner', 'Ključne prednosti: Obnavlja i jača kožnu barijeru: Pantenol u visokoj koncentraciji umiruje i štiti kožu od isušivanja i spoljašnjih iritansa. Intenzivna hidratacija bez osećaja težine: Tekstura bogata, ali brzo upijajuća, ostavlja kožu osveženom i elastičnom. Umiruje osetljivu i nadraženu kožu: Fermentisana crna soja i madecassoside deluju protivupalno i regenerativno. Kome je namenjen? Ovaj tonik je idealan za suvu, osetljivu, dehidriranu ili oslabljenu kožu, uključujući i kožu sklonu crvenilu, zatezanju i iritacijama. Pogodan je za sve tipove kože koji zahtevaju jačanje barijere i hidrataciju bez opterećenja. Zašto volimo ROUND LAB Soybean Panthenol Toner? Soybean Panthenol Toner je formulisan za dubinsku negu osetljive i oštećene kože, posebno nakon izlaganja spoljašnjim stresorima kao što su vetar, hladnoća, sunce ili agresivni kozmetički tretmani. Zahvaljujući 5% pantenola, tonik momentalno umiruje iritacije i obnavlja zaštitnu funkciju kože. Fermentisani ekstrakt crne soje iz Jeongseon regije bogat je aminokiselinama i izoflavonima koji doprinose elastičnosti i otpornosti kože. Formula je dodatno obogaćena ceramidima, beta-glukanom i madecassoside-om za dodatni efekat smanjenja crvenila i očuvanja hidratacije. Tonik ima blagu, ali bogatu teksturu, koja se brzo upija i priprema kožu za dalju negu, ostavljajući je mekšom, elastičnijom i zaštićenom. Aktivni sastojci Pantenol (5%) Poznat i kao provitamin B5, pantenol intenzivno hidrira, smanjuje iritacije i pomaže koži da zadrži vlagu. U visokoj koncentraciji, pantenol deluje i kao zaštitni sloj koji jača barijeru i poboljšava otpornost kože na spoljne faktore. Fermentisani ekstrakt crne soje (Glycine Max) Bogata izoflavonima i aminokiselinama, crna soja deluje antioksidativno i regenerativno. Proces fermentacije pojačava efikasnost ovih sastojaka, pružajući koži bolju ishranu, elastičnost i zdraviji izgled. Beta-glukan Prirodni polisaharid sa snažnim protivupalnim i imunostimulativnim dejstvom. Umiruje nadraženu kožu, poboljšava hidrataciju i ubrzava regeneraciju. Madecassoside Aktivna komponenta biljke Centella Asiatica, poznata po sposobnosti da smanjuje crvenilo, iritacije i pospešuje regeneraciju oštećene kože. Ceramidi Pomažu u obnovi lipidne barijere kože, štiteći je od isušivanja i spoljašnjih uticaja. Osiguravaju da koža ostane hidrirana i elastična, posebno kod redovne upotrebe. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Soybean Panthenol Toner je umirujući, regenerativni tonik koji kombinuje fermentisani ekstrakt crne soje i 5% pantenola za dubinsku hidrataciju, jačanje barijere kože i smanjenje crvenila. Namenjen je osetljivoj, reaktivnoj i suvoj koži kojoj je potrebna nežna, ali efikasna nega.', 'https://beauty-health.rs/wp-content/uploads/2025/04/ROUND-LAB-Soybean-Panthenol-Toner-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
