INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (861, 126, 'Numbuzin No.9 NAD Bio Lifting Full Cover Facial Mask', 'numbuzin-no-9-nad-bio-lifting-full-cover-facial-mask', 'Ključne prednosti: Instant lifting efekat i zatezanje kože: NAD+ i peptidi aktivno stimulišu regeneraciju kože i podižu konture lica. Dubinska hidratacija i puniji izgled: Hijaluronska kiselina i pantenol vraćaju koži vlagu i elastičnost bez masnog osećaja. Poboljšanje teksture i čvrstoće kože: Biocelulozna maska savršeno prijanja uz lice, omogućavajući optimalnu apsorpciju aktivnih sastojaka. Kome je namenjena? Idealna je za zrelu, opuštenu i dehidriranu kožu , kao i za sve koji žele trenutan efekat podizanja i osvežen izgled pred važne događaje. Pogodna za sve tipove kože, uključujući osetljivu, zahvaljujući hipoalergenskoj i rashlađujućoj bioceluloznoj osnovi. Zašto volimo Numbuzin No.9 NAD Bio Lifting Full Cover Facial Mask? No.9 NAD Bio Lifting Full Cover Facial Mask pruža luksuzno, spa-nivou iskustvo u obliku napredne sheet maske koja koristi NAD+ (nikotinamid adenin dinukleotid) – koenzim ključan za ćelijsku energiju i regeneraciju. U kombinaciji sa 10 vrsta peptida, adenozinom i niacinamidom, maska deluje protiv gubitka čvrstoće, smanjuje vidljivost bora i vraća koži elastičnost. Hijaluronska kiselina u više molekularnih težina hidrira i zaglađuje kožu, dok biocelulozna struktura omogućava savršeno prijanjanje i ravnomernu isporuku aktivnih sastojaka. Osim trenutnog efekta liftinga i osveženja, maska redovnom upotrebom pomaže u jačanju kožne barijere, poboljšava tonus i pruža zdrav, blistav izgled lica. Aktivni sastojci NAD+ (Nikotinamid adenin dinukleotid) Moćan bioaktivni koenzim prirodno prisutan u ćelijama, odgovoran za energetski metabolizam i ćelijsku reparaciju. U topikalnoj primeni NAD+ podstiče sintezu kolagena, regeneraciju ćelija i poboljšava čvrstoću kože. Ključan za borbu protiv znakova starenja, kao što su opuštenost, bore i umoran izgled. Peptidi (10 vrsta) Peptidi deluju kao signalni molekuli koji stimulišu kožu da proizvodi više kolagena i elastina. Različiti tipovi u ovoj maski ciljano deluju na zatezanje, elastičnost, zaglađivanje i obnavljanje kože. Smanjuju vidljivost bora i poboljšavaju konture lica. Adenozin Dermatološki priznat sastojak za borbu protiv bora. Deluje na zategnutost i elastičnost kože, čineći je vizuelno punijom i glađom. Takođe umiruje kožu i pojačava reparativne procese tokom noćne regeneracije. Niacinamide Multifunkcionalni aktivni sastojak koji posvetljuje kožu, ujednačava ten, poboljšava barijeru i kontroliše upalne procese. U ovoj formuli dodatno doprinosi blistavosti i zdravijem izgledu kože. Hijaluronska kiselina (višemolekularna) Osigurava dubinsku i dugotrajnu hidrataciju. Molekuli različitih veličina prodiru u različite slojeve kože, čineći je punijom, glatkijom i otpornijom. Poboljšava efekat liftinga i smanjuje osećaj zategnutosti. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.9 NAD Bio Lifting Full Cover Facial Mask je inovativna biocelulozna sheet maska obogaćena NAD+ kompleksom, peptidima, adenozinom i hijaluronskom kiselinom, osmišljena za vidljivo lifting dejstvo, povećanje elastičnosti i intenzivnu hidrataciju. Maska je dizajnirana da pokrije celo lice do vilice, ciljano delujući na opuštenost, fine linije i umoran ten. Važno: Lifting traka dolazi samo uz pakovanje od 4 maske.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Numbuzin-No.9-NAD-Bio-Lifting-Full-Cover-Facial-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
