INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (863, 119, 'Mixsoon Centella Cleansing Foam', 'mixsoon-centella-cleansing-foam', 'Ključne prednosti: Temeljno čisti bez iritacije: Blaga pena uklanjaja nečistoće i višak sebuma bez narušavanja zaštitne barijere. Umiruje i obnavlja kožu: Centella Asiatica i pantenol smanjuju crvenilo i štite osetljivu kožu. Ne isušuje ni ne zateže: Niska pH vrednost (4.5) i hidratantna formula čuvaju prirodni balans kože. Kome je namenjena? Ova pena je idealna za osobe sa osetljivom, suvom, kombinovanom i kožom sklonom aknama, koje traže nežan, ali efikasan čistač koji ne izaziva zatezanje niti iritaciju. Pogodna je za svakodnevnu upotrebu, uključujući i reaktivnu kožu. Zašto volimo Mixsoon Centella Cleansing Foam? Centella Cleansing Foam je nežna, ali efikasna pena za čišćenje, dizajnirana da ukloni preostale nečistoće, sebum i mrtve ćelije kože bez oštećivanja barijere. Zahvaljujući ekstraktu Centella Asiatica, poznatom po svojim umirujućim i regenerativnim svojstvima, ovaj čistač smanjuje crvenilo, iritacije i pruža prijatan osećaj svežine nakon pranja. Salicilna kiselina u formulaciji pomaže u sprečavanju pojave mitisera i akni, nežno čisteći pore i uklanjajući višak ulja. Blaga pH vrednost od 4.5 pomaže u očuvanju prirodne barijere kože, dok hidratantni sastojci poput pantenola i glicerina sprečavaju isušivanje. Kremasta pena se lako ispira i ostavlja kožu čistom, mekom i izbalansiranom – spremnom za dalju negu. Aktivni sastojci Centella Asiatica Extract Poznata i kao &#8220;cica&#8221;, ova biljka ima snažno umirujuće i protivupalno dejstvo. Bogata je aktivnim komponentama poput madecassoside-a i asiaticoside-a, koje pomažu u regeneraciji kože, smanjenju crvenila i iritacija. Savršena je za osetljivu i reaktivnu kožu. Salicilna kiselina (BHA) Deluje dubinski unutar pora, razgrađuje sebum i mrtve ćelije kože, sprečava nastanak mitisera i bubuljica. Ima blago keratolitičko i antibakterijsko dejstvo, idealno za problematičnu kožu. Pruža efikasno, ali blago čišćenje koje ne oštećuje barijeru. Pantenol (Provitamin B5) Pantenol pruža hidrataciju i umiruje iritiranu kožu. Pomaže u obnavljanju kožne barijere i čini kožu mekom i elastičnom. Posebno koristan nakon čišćenja, jer sprečava osećaj zatezanja. Glicerin Prirodni ovlaživač koji zadržava vlagu u koži, doprinosi mekoći i elastičnosti. Sprečava isušivanje kože i održava optimalan nivo hidratacije i nakon čišćenja. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Centella Cleansing Foam je blaga pH-balansirana pena za čišćenje lica, formulisana sa ekstraktom Centella Asiatica i salicilnom kiselinom koja dubinski čisti pore, umiruje kožu i ostavlja je hidriranom bez osećaja zatezanja. Idealan je za drugi korak čišćenja u rutini, posebno kod osetljive, problematične i dehidrirane kože.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Mixsoon-Centella-Cleansing-Foam.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
