INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (864, 119, 'Mixsoon Bean Eye Cream', 'mixsoon-bean-eye-cream', 'Ključne prednosti: Smanjuje bore i fine linije: Adenozin i fermentisani sastojci stimulišu proizvodnju kolagena i povećavaju elastičnost. Dubinski hidrira i obnavlja barijeru: Pantenol i ceramidi jačaju zaštitnu funkciju kože i smanjuju suvoću i zatezanje. Umiruje i osvežava zonu oko očiju: Formulacija bez iritansa pogodna je za osetljivu kožu i pruža umirujući efekat. Kome je namenjena? Idealna za osetljivu, suvu i zrelu kožu oko očiju, kao i za sve koji žele da spreče ili ublaže pojavu bora, podočnjaka i dehidratacije. Pogodna za dnevnu i noćnu upotrebu, uključujući i osetljive tipove kože. Zašto volimo Mixsoon Bean Eye Cream? Bean Eye Cream koristi snagu fermentisane soje (bean extract) i minimalne, ali efektivne formule kako bi ojačala kožu oko očiju i pružila dubinsku negu bez iritacija. Fermentacija pojačava apsorpciju aktivnih jedinjenja, pa tako ekstrakt soje bogat proteinima, izoflavonima i aminokiselinama deluje regenerativno i protivupalno. Adenozin, klinički dokazan anti-age sastojak, zaglađuje fine linije i vraća čvrstoću, dok ceramidi i pantenol pomažu u obnavljanju barijere i održavanju hidratacije. Lagana, ali hranljiva tekstura se lako razmazuje, brzo upija i ostavlja kožu mekom i osveženom. Redovnom upotrebom, područje oko očiju postaje elastičnije, svetlije i vizuelno odmornije. Aktivni sastojci Fermentisani ekstrakt soje (Bean Extract) Bogat biljnim proteinima, aminokiselinama i fitonutrijentima, ekstrakt soje pomaže u jačanju strukture kože, poboljšava elastičnost i deluje umirujuće. Fermentacijom se povećava biodostupnost ovih hranljivih materija, čime se ubrzava regeneracija kože. Posebno je efikasan kod tanke kože oko očiju, koja brzo pokazuje znake starenja. Adenozin Snažan anti-age sastojak koji podstiče proizvodnju kolagena i pomaže u smanjenju izraženosti bora. Deluje umirujuće i poboljšava mikrocirkulaciju, što doprinosi svežem i odmornom izgledu očne zone. U ovoj kremi igra ključnu ulogu u tretmanu finih linija i prevenciji starenja. Ceramidi Prirodni lipidi koji obnavljaju i jačaju kožnu barijeru, smanjuju transepidermalni gubitak vode i poboljšavaju otpornost kože na spoljne faktore. Idealni su za suvu, osetljivu i dehidriranu kožu oko očiju. Pantenol (Provitamin B5) Deluje umirujuće, regenerativno i hidratantno. Pomaže u zadržavanju vlage i obnavlja oštećena i suva područja. U kombinaciji sa ceramidima pruža dugotrajan osećaj mekoće i zaštite. Beta-glukan Prirodni polisaharid koji ima antiinflamatorno dejstvo i stimuliše sintezu kolagena. Pomaže u zatezanju kože i smanjuje iritacije, čineći ga idealnim za upotrebu oko očiju. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Bean Eye Cream je hranljiva i nežna krema za područje oko očiju formulisana sa fermentisanim ekstraktom soje, ceramidima, adenozinom i pantenolom, koja ciljano deluje na bore, dehidrataciju i gubitak elastičnosti. Namenjena je jačanju tanke i osetljive kože oko očiju, pružajući intenzivnu hidrataciju i anti-age zaštitu.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Mixsoon-Bean-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
