INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (865, 118, 'Missha Time Revolution Immortal Youth Cream', 'missha-time-revolution-immortal-youth-cream', 'Ključne prednosti: Smanjuje bore i poboljšava čvrstoću kože: Kompleks peptida i adenozin stimulišu sintezu kolagena i vraćaju tonus opuštenoj koži. Ujednačava ten i posvetljuje: Niacinamid i fermentisani ekstrakti deluju na pigmentacije, sivilo i ujednačavaju ton kože. Dubinska hidratacija i zaštita barijere: Formula bogata antioksidansima i lipidima pruža dugotrajan osećaj komfora i hidratacije. Kome je namenjena? Krema je idealna za zrelu kožu, kao i za one sa vidljivim znacima starenja – borama, opuštenošću, gubitkom sjaja i neujednačenim tenom. Pogodna je za normalnu do suvu kožu, kao i za kombinovanu kožu tokom hladnijih sezona. Zašto volimo MISSHA Time Revolution Immortal Youth Cream? Time Revolution Immortal Youth Cream je deo prestižne linije za naprednu anti-age negu i formulisana je tako da deluje na najdublje slojeve kože. Njena bogata tekstura se lako upija i donosi intenzivnu regeneraciju zahvaljujući fermentisanim sastojcima i biljnim ekstraktima koji podstiču obnovu ćelija. Adenozin i peptidi ciljano deluju na smanjenje bora i poboljšanje elastičnosti, dok niacinamid osvetljava ten i jača barijeru kože. Kompleks hidrirajućih ulja i antioksidanasa, uključujući ekstrakte borovnice, goji bobica i žalfije, štiti kožu od oksidativnog stresa i čini je otpornijom na spoljne agresore. Redovnom upotrebom, koža postaje punija, zategnutija i vizuelno mlađa, sa prirodnim sjajem i ravnomernijim tonom. Aktivni sastojci Adenozin Snažan anti-age sastojak koji deluje na smanjenje bora stimulacijom sinteze kolagena i elastina. Ima umirujuće i protivupalno dejstvo, poboljšava elastičnost i učvršćuje konture lica. Pogodan je za svakodnevnu upotrebu, čak i kod osetljive kože. Niacinamide (Vitamin B3) Deluje posvetljujuće i ujednačava ten, dok jača zaštitnu funkciju kože. U ovoj formuli dodatno doprinosi smanjenju pigmentacija, poboljšanju tonusa i suzbijanju sivila i umornog izgleda kože. Fermentisani sastojci (Lactobacillus, Bifida Ferment Lysate) Ovi probiotski fermenti pomažu u jačanju mikrobioma kože i povećavaju njenu otpornost. Deluju antioksidativno, poboljšavaju regeneraciju ćelija i podstiču zdrav sjaj kože. Takođe doprinose boljoj apsorpciji ostalih aktivnih sastojaka. Biljni peptidi i ceramidi Peptidi stimulišu sintezu kolagena i elastina, poboljšavajući tonus i zategnutost kože. Ceramidi jačaju lipidnu barijeru, zadržavaju vlagu i štite kožu od spoljašnjih iritansa, čime je čine elastičnijom i manje reaktivnom. Ekstrakt goji bobica, borovnice i žalfije Bogati antioksidansi koji štite kožu od slobodnih radikala i oksidativnog stresa. Doprinosi zdravijem, svežijem tenu i usporava procese preranog starenja. Goji bobice dodatno revitalizuju i osnažuju umornu kožu. Dodaj u listu želja Dodaj u listu želja', 'MISSHA Time Revolution Immortal Youth Cream je luksuzna, višefunkcionalna anti-age krema koja kombinuje adenozin, niacinamid, fermentisane sastojke i biljne peptide kako bi vidljivo smanjila bore, poboljšala elastičnost i posvetlila ten. Namenjena je intenzivnoj regeneraciji kože i borbi protiv znakova starenja na više nivoa.', 'https://beauty-health.rs/wp-content/uploads/2025/04/MISSHA-Time-Revolution-Immortal-Youth-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
