INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (866, 114, 'Medicube Zero Pore Toner', 'medicube-zero-pore-toner', 'Ključne prednosti: Efikasno čisti i sužava pore: BHA prodire duboko u pore, razgrađuje sebum i eliminiše mitisere. Ujednačava teksturu i ton kože: AHA kiseline uklanjaju mrtve ćelije, posvetljuju ten i smanjuju neujednačenost. Kontroliše sebum bez isušivanja: Lagana, osvežavajuća formula balansira kožu i ostavlja je matiranom i čistom. Kome je namenjen? Idealan za masnu, kombinovanu i kožu sklonu aknama, mitiserima i proširenim porama. Pogodan i za dehidriranu, ali problematičnu kožu jer ne sadrži alkohol i parabene. Osetljivoj koži se preporučuje postepena upotreba (2–3x nedeljno). Zašto volimo Medicube Zero Pore Toner? Zero Pore Toner je jedan od najpoznatijih proizvoda iz &#8220;Zero&#8221; linije brenda, osmišljen da dubinski očisti pore, smanji pojavu mitisera i višak sebuma, ali i da istovremeno ojača kožnu barijeru. Formulisan je sa salicilnom kiselinom (BHA) koja prodire u pore i razgrađuje nagomilani sebum, i mliječnom kiselinom (AHA) koja uklanja površinske mrtve ćelije i poboljšava tonus i sjaj kože. Zahvaljujući ekstraktima voća i alantoinu, tonik deluje umirujuće, sprečava iritacije i može se koristiti svakodnevno bez rizika od isušivanja. Već nakon dve nedelje redovne upotrebe, koža postaje vidno čistija, mekša i sa manje izraženim porama i nepravilnostima. Aktivni sastojci Salicilna kiselina (BHA) Salicilna kiselina je lipofilna kiselina koja prodire u pore, razgrađuje sebum i uklanja nečistoće koje izazivaju mitisere i akne. Ima snažno protivupalno i antibakterijsko dejstvo, što je čini idealnom za masnu i problematičnu kožu. U ovoj formuli deluje dubinski, ali u kontrolisanoj koncentraciji kako bi se izbegla iritacija. Mlečna kiselina (AHA) AHA blago eksfolira površinski sloj kože, uklanja mrtve ćelije i podstiče regeneraciju. Poboljšava tonus, posvetljuje tamne fleke i ujednačava ten. Pored toga, pomaže u povećanju hidratacije kože, jer mlečna kiselina ima humektantna svojstva. Sinergija sa BHA kiselinom pruža efikasno, ali uravnoteženo čišćenje. Ekstrakt jabuke i papaje Ovi voćni ekstrakti sadrže prirodne enzime i antioksidanse koji pomažu u nežnoj eksfolijaciji i obnavljanju kože. Doprinosi osveženju tena, čini kožu svetlijom i pomaže u obnavljanju oštećene teksture. Alantoin Umirujući i regenerativni agens koji ublažava crvenilo i iritacije, a takođe ubrzava obnavljanje kože. Savršen balansni sastojak u formuli sa kiselinama, jer povećava podnošljivost čak i kod osetljivije kože. Doprinosi glatkijem osećaju i manjoj reaktivnosti. Pantenol (Provitamin B5) Pantenol ima snažno hidratantno i umirujuće dejstvo. Održava elastičnost i vlagu u koži, dok jača njenu zaštitnu funkciju. U kombinaciji sa kiselinama, pantenol štiti od isušivanja i iritacije. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore Toner je tonik za lice sa AHA i BHA kiselinama, namenjen za dubinsko čišćenje pora, eksfolijaciju mrtvih ćelija i regulaciju sebuma, bez isušivanja kože. Formulisan za svakodnevnu upotrebu, poboljšava teksturu kože, smanjuje mitisere i vidljivo sužava pore.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-Zero-Pore-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
