INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (868, 118, 'MISSHA Bee Pollen Renew Ampouler', 'missha-bee-pollen-renew-ampouler', 'Ključne prednosti: Obnavlja i revitalizuje kožu: Ekstrakt polena pčele bogat nutrijentima pomaže u jačanju barijere i smanjenju znaka umora i stresa na koži. Posvetljuje i ujednačava ten: Niacinamid deluje na pigmentacije, poboljšava teksturu i vraća koži blistavost. Anti-age zaštita i elastičnost: Adenozin stimuliše sintezu kolagena i smanjuje vidljivost finih linija i bora. Kome je namenjen? Proizvod je namenjen osobama sa umornom, sivom, dehidriranom i zrelijom kožom, kao i koži oslabljenoj nakon izlaganja stresu, vremenskim uslovima ili estetskim tretmanima. Pogodan za sve tipove kože, uključujući osetljivu. Zašto volimo MISSHA Bee Pollen Renew Ampouler? Bee Pollen Renew Ampouler je luksuzna, koncentrisana ampula koja koristi 42% fermentisanog ekstrakta polena pčele, poznatog po bogatom sadržaju proteina, aminokiselina i minerala. Polen deluje kao prirodni revitalizator – poboljšava otpornost kože, smanjuje inflamaciju i stimuliše regeneraciju. Formula je dodatno obogaćena niacinamidom, koji posvetljuje, smanjuje neujednačenost tena i ojačava barijeru kože, te adenozinom, koji deluje na bore i gubitak elastičnosti. Njena lagana, ali hranljiva tekstura brzo se upija i ostavlja kožu hidriranom, mekom i osveženom bez masnog sloja. Ampula je posebno efikasna kod kože koja deluje umorno, zategnuto i bez sjaja. Već nakon nekoliko dana upotrebe, koža postaje osvetljena, elastična i primetno zdravija. Aktivni sastojci Ekstrakt polena pčele (Bee Pollen Extract – 42%) Ovaj sastojak sadrži preko 200 bioaktivnih jedinjenja, uključujući vitamine, minerale, flavonoide i proteine koji dubinski obnavljaju i hrane kožu. Deluje kao antioksidans, jača kožnu barijeru i štiti od spoljašnjih agresora. Posebno koristan kod umorne i reaktivne kože. Pomaže i u smanjenju upala i podržava prirodnu regeneraciju kože. U ovoj ampuli koristi se fermentisani oblik za bolju apsorpciju i efikasnost. Niacinamide (Vitamin B3) Deluje kao multifunkcionalni sastojak za posvetljivanje, jačanje barijere i regulaciju sebuma. Smanjuje pigmentacije i postinflamatorne fleke, dok poboljšava tonus i teksturu kože. U sinergiji s bee pollen ekstraktom pruža osvetljavajući i umirujući efekat, bez isušivanja. Adenozin Poznat po svom anti-age dejstvu – stimuliše sintezu kolagena i elastina, poboljšava mikrocirkulaciju i elastičnost kože. U ovoj formuli deluje na fine linije i prevremene znakove starenja, naročito u zoni oko očiju i čela. Dodatno ima protivupalni efekat i podržava zdravlje kože pod stresom. Pantenol (Provitamin B5) Pruža snažnu hidrataciju, umiruje kožu i ubrzava oporavak oštećenih područja. Deluje sinergijski sa polenom u obnavljanju zaštitnog sloja kože. Smanjuje crvenilo i peckanje, čineći formulu pogodnom i za osetljivu kožu. Ekstrakt propolisa i meda Deluju antibakterijski, regenerativno i zaštitno. Propolis je poznat po efektima na problematičnu i iritiranu kožu, dok med hidrira i omekšava. Povećavaju prirodnu otpornost kože i doprinose zdravijem izgledu tena. Dodaj u listu želja Dodaj u listu želja', 'MISSHA Bee Pollen Renew Ampouler je visokokoncentrovano antioksidativno i regenerativno serumsko ulje, formulisano sa ekstraktom polena pčele (Bee Pollen Extract), niacinamidom i adenozinom, koje intenzivno hrani, obnavlja i jača kožu. Namenjeno je revitalizaciji umorne, oslabljene i dehidrirane kože uz efekte posvetljivanja i anti-age nege.', 'https://beauty-health.rs/wp-content/uploads/2025/04/MISSHA-Bee-Pollen-Renew-Ampouler-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
