INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (869, 118, 'MISSHA All-Around Safe Block Essence Sun Milk EX SPF50+', 'missha-all-around-safe-block-essence-sun-milk-ex', 'Ključne prednosti: Visoka zaštita od sunca i zagađenja: SPF50+ PA+++ štiti od štetnog UV zračenja i spoljašnjih agresora koji ubrzavaju starenje. Hidratantna i lagana formula bez masnog finiša: Esencijalna tekstura se brzo upija, ostavljajući kožu mekom i pripremljenom za šminku. Umirujući biljni kompleks: Ekstrakti kamilice, cveta ruže i vodenog ljiljana pomažu u smanjenju crvenila i osetljivosti. Kome je namenjen? Ovaj SPF fluid je idealan za sve tipove kože, posebno normalnu, kombinovanu i suvu kožu. Namenjen je svima koji žele nevidljivu, nemasnu i svakodnevno nosivu zaštitu od sunca uz dodatne benefite nege i hidratacije. Zašto volimo MISSHA All-Around Safe Block Essence Sun Milk EX? All-Around Safe Block Essence Sun Milk EX kombinuje naprednu UV zaštitu sa njegom esencije, kreirajući proizvod koji ne samo da štiti, već i revitalizuje kožu. Za razliku od teških ili lepljivih SPF krema, ova sun milk formula ima teksturu lagane emulzije koja se trenutno upija, ostavljajući mekan, osvežen i hidriran osećaj. Ne ostavlja bele tragove, ne izaziva začepljenje pora i ne narušava šminku. Biljni kompleks, uključujući ekstrakt vodenog ljiljana, kamilice i ruže, deluje umirujuće i protivupalno, dok antioksidansi štite kožu od spoljašnjih stresora i prevremenog starenja. Savršen je za svakodnevnu upotrebu – kako u gradskoj sredini, tako i na otvorenom. Aktivni sastojci Ekstrakt vodenog ljiljana (Nymphaea Alba Flower Extract) Deluje osvežavajuće, protivupalno i umirujuće, pomažući u smanjenju crvenila i iritacija izazvanih sunčevim zračenjem. Takođe doprinosi osećaju hlađenja i hidrira kožu bez masnoće. U ovom SPF-u pomaže u održavanju balansa čak i kod osetljive kože. Ekstrakt kamilice (Chamomilla Recutita Flower Extract) Poznat po svojim umirujućim i regenerativnim svojstvima. Kamilica smanjuje upale, iritacije i crvenilo, čineći ovaj SPF pogodnim i za reaktivne tipove kože. Takođe štiti od oksidativnog stresa. Ekstrakt ruže (Rosa Centifolia Flower Extract) Doprinosi hidrataciji, omekšavanju i osvežavanju kože, dok njen prirodni miris pruža prijatno iskustvo pri nanošenju. Bogata je antioksidansima i pomaže u zaštiti od slobodnih radikala. Niacinamide (Vitamin B3) Pomaže u posvetljavanju kože, poboljšava barijernu funkciju i ujednačava ten. Takođe doprinosi kontroli sebuma, čime se smanjuje masni sjaj tokom dana. Idealan za one koji žele dodatnu negu u svom SPF-u. UVA/UVB filteri širokog spektra (hemijski filteri) Efikasna kombinacija modernih hemijskih UV filtera pruža zaštitu širokog spektra od UVB (opekotine) i UVA (starenje) zračenja. Ne ostavljaju bele tragove i prilagođeni su za svakodnevnu primenu, bez osećaja težine na koži. Dodaj u listu želja Dodaj u listu želja', 'MISSHA All-Around Safe Block Essence Sun Milk EX je lagani, hidratantni dnevni SPF fluid koji pruža visoku zaštitu od UVA i UVB zračenja (SPF50+ PA+++), dok istovremeno hidrira, osvežava i umiruje kožu. Formulisan sa biljnim ekstraktima, antioksidansima i hidrirajućim esencijama, idealan je za svakodnevnu upotrebu bez osećaja težine ili belih tragova.', 'https://beauty-health.rs/wp-content/uploads/2025/04/MISSHA-All-Around-Safe-Block-Essence-Sun-Milk-EX-SPF50.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
