INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (871, 114, 'Medicube Kojic Acid Turmeric Night Wrapping Mask', 'medicube-kojic-acid-turmeric-night-wrapping-mask', 'Ključne prednosti: Efikasno posvetljuje i ujednačava ten : Kojična kiselina i niacinamid deluju protiv tamnih fleka, postupalnih tragova i neujednačenosti. Regeneriše i jača barijeru kože preko noći : Ceramidi i pantenol obnavljaju lipidnu barijeru, zadržavaju vlagu i sprečavaju isušivanje. Umiruje i poboljšava tonus kože : Kurkuma i alantoin smanjuju crvenilo i upale, ostavljajući kožu osveženom, glatkom i blistavom. Kome je namenjena? Maska je idealna za osobe sa pigmentacijama, umornim tenom, sivom kožom, postupalnim flekama ili oštećenom barijerom. Pogodna je za sve tipove kože, uključujući mešovitu i suvu, dok se kod osetljive kože preporučuje prethodni test tolerancije. Zašto volimo Medicube Kojic Acid Turmeric Night Wrapping Mask? Kojic Acid Turmeric Night Wrapping Mask deluje dok vi spavate, koristeći moć ciljanih aktivnih sastojaka da posvetli, regeneriše i zaštiti vašu kožu. Glavni sastojak, kojična kiselina, inhibira sintezu melanina i smanjuje vidljivost tamnih fleka i pigmentacija. Kurkuma deluje protivupalno i osvetljava ten bez iritacija. Niacinamid dodatno ujednačava ten i jača kožnu barijeru. Ceramidi i pantenol osiguravaju dugotrajnu hidrataciju i umirenje. Masku karakteriše bogata gel-kremasta tekstura koja se lako razmazuje, formira zaštitni film i &#8220;zaključava&#8221; aktivne sastojke u koži tokom noći. Do jutra, ten izgleda svežije, koža je vidno mekša, ujednačenija i sa prirodnim sjajem. Aktivni sastojci Kojična kiselina Prirodni derivat koji deluje kao inhibitor enzima tirozinaze, zaduženog za proizvodnju melanina. Efikasno smanjuje pojavu pigmentacija, tamnih fleka i neujednačenog tona kože. U ovoj formuli koristi se u optimalnoj koncentraciji za svakodnevnu, bezbednu noćnu upotrebu. U kombinaciji sa niacinamidom i kurkumom, efekat posvetljivanja se dodatno pojačava. Pogodna je i za kožu sklonu postupalnim flekama i aknama. Ekstrakt kurkume (Curcuma Longa Root Extract) Prirodni antiinflamatorni i antioksidativni sastojak koji umiruje crvenilo, smanjuje iritacije i osvetljava kožu. Deluje sinergijski sa kojic kiselinom na pigmentacije, ali istovremeno sprečava pojavu iritacija. Kurkuma takođe poboljšava tonus kože i doprinosi zdravijem, blistavijem izgledu. Niacinamide (Vitamin B3) Višenamenski sastojak koji deluje na posvetljivanje kože, smanjenje tamnih fleka, regulaciju sebuma i poboljšanje barijerne funkcije kože. U ovoj maski pojačava efekat kojic kiseline i kurkume, ali i štiti kožu od dehidratacije. Dodatno smanjuje upalne procese i ujednačava teksturu. Ceramidi Ključni lipidi za očuvanje i obnovu kožne barijere. U noćnoj maski obnavljaju oštećenu barijeru, sprečavaju transepidermalni gubitak vode i povećavaju otpornost kože. Posebno korisni za kožu oslabljenu usled upotrebe aktivnih sastojaka poput kiseline i vitamina C. Ceramidi pomažu koži da ostane hidrirana i umirena do jutra. Dodaj u listu želja Dodaj u listu želja', 'Medicube Kojic Acid Turmeric Night Wrapping Mask je noćna tretmanska maska za lice koja kombinuje kojičnu kiselinu, kurkumu, niacinamid i ceramide kako bi posvetlila ten, smanjila pigmentacije i obnovila barijeru kože dok spavate. Lagana, ali bogata tekstura formira zaštitni sloj koji intenzivno hidrira, ujednačava ten i poboljšava teksturu kože do jutra.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-Kojic-Acid-Turmeric-Night-Wrapping-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
