INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (873, 114, 'Medicube AGE-R Glutathione Glow Toner', 'medicube-age-r-glutathione-glow-toner', 'Ključne prednosti: Posvetljuje i osvežava kožu: Glutation i niacinamid sinergijski deluju na ublažavanje tamnih fleka i sivila. Dubinski hidrira i jača barijeru: Pantenol i alantoin obnavljaju i umiruju kožu, smanjujući iritacije i zatezanje. Pruža antioksidativnu zaštitu: Štiti kožu od oksidativnog stresa i spoljašnjih agresora, čime usporava vidljive znake starenja. Kome je namenjen? Tonik je idealan za osobe sa umornim, neujednačenim tenom, tamnim flekama i kožom bez sjaja. Pogodan je za sve tipove kože, uključujući osetljivu, zahvaljujući blagoj i hidratantnoj formuli bez iritansa. Zašto volimo Medicube AGE-R Glutathione Glow Toner? AGE-R Glutathione Glow Toner pruža luksuzan početak rutine nege kože kroz spoj visokoefikasnih posvetljujućih i umirujućih sastojaka. Glavni aktivni sastojak – glutation – deluje kao snažan antioksidans koji inhibira sintezu melanina, posvetljuje kožu i štiti ćelije od oštećenja izazvanih slobodnim radikalima. U kombinaciji sa niacinamidom, značajno doprinosi ujednačavanju tena i smanjenju pigmentacija. Formula je dodatno obogaćena pantenolom i alantoinom, koji umiruju i obnavljaju kožnu barijeru, dok istovremeno sprečavaju dehidrataciju i zatezanje. Tekstura tonika je osvežavajuća, brzo se upija i ostavlja kožu vidno mekšom i sjajnijom. Priprema kožu za naredne korake rutine i poboljšava efikasnost seruma i krema koji dolaze nakon. Aktivni sastojci Glutation Glutation je jedan od najsnažnijih prirodnih antioksidanasa koji se već nalazi u ljudskom telu. U nezi kože koristi se za posvetljivanje tena jer deluje na inhibiciju enzima tirozinaze, odgovornog za sintezu melanina. Takođe pomaže u detoksikaciji ćelija i zaštiti od UV oštećenja. U ovoj formuli, glutation osvetljava, osvežava i usporava pojavu znakova starenja. Pogodan je i za osetljivu kožu jer ne izaziva iritacije. Njegova redovna upotreba vodi ka ujednačenijem, blistavijem tenu. Niacinamide (Vitamin B3) Višenamenski sastojak koji deluje na smanjenje pigmentacija, jačanje kožne barijere i regulaciju sebuma. U ovoj formuli pojačava efekat glutationa u posvetljavanju kože, dok istovremeno doprinosi smanjenju crvenila i poboljšanju teksture. Posebno efikasan kod kože sklone flekama i neujednačenosti. Takođe poboljšava otpornost kože i sprečava isušivanje. Pantenol (Provitamin B5) Pantenol je snažan ovlaživač koji prodire u dublje slojeve kože i vezuje vodu, čime povećava elastičnost i smanjuje zatezanje. Doprinosi regeneraciji kože, ublažava iritacije i stvara osećaj komfora. Idealno balansira aktivne sastojke poput glutationa i niacinamida, pružajući toniku svakodnevnu podnošljivost. Alantoin Alantoin ima snažno umirujuće i regenerativno delovanje. Podstiče zarastanje mikrooštećenja, čini kožu glatkijom i otpornijom na spoljašnje uticaje. U ovoj formuli umanjuje potencijalne iritacije i doprinosi osećaju svežine i mekoće nakon nanošenja tonika. Dodaj u listu želja Dodaj u listu želja', 'Medicube AGE-R Glutathione Glow Toner je osvetljavajući tonik sa glutationom, niacinamidom i pantenolom, koji hidrira, ujednačava ten i pruža koži zdrav, prirodan sjaj. Formulisan za svakodnevnu upotrebu, ovaj toner poboljšava blistavost kože, istovremeno je umirujući i štiteći od oksidativnog stresa.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-AGE-R-Glutathione-Glow-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
