INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (874, 114, 'Medicube AGE-R Booster Pro Mini', 'medicube-age-r-booster-pro-mini', 'Tvoja svakodnevna nega – sada u mini formatu! U svetu u kojem nemamo vremena za dugu skincare rutinu, a koža nam svakodnevno trpi stres, zagađenje i promene vremena, sve više tražimo efikasna rešenja koja daju rezultate – bez komplikacija. Upravo tu nastupa Medicube AGE-R Booster Pro Mini Pink – tvoj novi beauty saveznik koji staje u dlan, ali pruža moćnu negu kože svakog dana. Zamisli ovo: umorna si nakon posla, nemaš volje za deset koraka u rutini, ali želiš da uradiš nešto za sebe. Uključuješ Mini Booster, biraš svetlo koje ti tog dana najviše treba – crveno za osvežen, zategnut ten ili plavo da umiriš kožu nakon dužeg dana. Uređaj nežno klizi preko kože, serum koji si nanela prodire dublje, a ti imaš onaj osećaj kao posle tretmana u salonu. Sve to za manje od 5 minuta. Šta je zapravo AGE-R Booster Pro Mini? Radi se o pametnom, kompaktnom uređaju koji koristi elektroporaciju – tehnologiju koja bez igala otvara mikrokanale u koži, omogućavajući aktivnim sastojcima da prodru mnogo dublje nego običnim nanošenjem. Takođe koristi LED svetlosnu terapiju u dve boje: Crveno svetlo – podstiče regeneraciju, proizvodnju kolagena i vraća koži elastičnost. Plavo svetlo – deluje antibakterijski, umiruje kožu i reguliše višak sebuma. Kombinacijom ove dve funkcije dobijaš nežan, ali efikasan tretman koji možeš da koristiš svakog dana – bez oporavka, bez bola i bez dodatnih preparata poput provodnog gela. Zašto ćeš ga voleti? Zato što radi ono što ti treba – brzo, jednostavno i gde god da si. Ujutru pre šminke, uveče pre spavanja, ili čak u pauzi između sastanaka – Booster Pro Mini je uvek uz tebe. Njegov minimalistički dizajn i lakoća upotrebe čine ga savršenim za sve koji žele rezultate bez komplikovane rutine. Pogodan je za sve tipove kože, ne izaziva iritacije i savršeno se uklapa u tvoju postojeću skincare kolekciju. Nemaš potrebu da menjaš proizvode koje voliš – već samo da im pomogneš da rade bolje. Mini vs EX – Koji je za tebe? Ako si se već susretala sa Booster Pro EX , znaš koliko ozbiljno Medicube pristupa nezi kože. EX je prava mala beauty laboratorija: 6 tehnologija, više LED svetala, mikrostruja, EMS, električne iglice&#8230; I sve to donosi napredne tretmane i dublje efekte. Booster Pro Mini, s druge strane, zadržava ono najbitnije – efikasnost i jednostavnost. Bez previše opcija, samo ono što ti zaista treba. Idealno za početnike, za one koji ne žele previše “dugmića” ili za korisnike u pokretu. Ako želiš osnovnu, ali snažnu negu – Mini je tvoj izbor. Ako ciljaš na punu spa rutinu kod kuće – EX ostaje kralj. Dostupan u dve nijanse: Pink – ženstveno, veselo i moderno. Beloj – čisto, elegantno, minimalistički. Oba modela imaju iste performanse – biraš samo stil koji tebi više odgovara. Ne moraš da ideš u kozmetički salon da bi imala zdravu, blistavu i negovanu kožu. Medicube AGE-R Booster Pro Mini Pink ti donosi klinički potvrđenu tehnologiju u jednostavnom, prenosivom formatu. U samo nekoliko minuta dnevno, možeš da napraviš veliku razliku – u izgledu, ali i u osećaju koji imaš prema svojoj koži. Dodaj u listu želja Dodaj u listu želja', 'Medicube AGE-R Booster Pro Mini je kompaktan uređaj za negu kože koji koristi elektroporaciju u kombinaciji sa LED svetlosnom terapijom kako bi unapredio apsorpciju aktivnih sastojaka iz kozmetičkih proizvoda. Uređaj je idealan za svakodnevnu upotrebu i odličan je izbor za one koji žele efikasnu rutinu. Dostupan je u pink i beloj varijanti.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-AGE-R-Booster-Pro-Mini-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
