INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (875, 111, 'Mary & May Shea Butter & Rice Bran Hand Cream', 'mary-may-shea-butter-rice-bran-hand-cream', 'Ključne prednosti: Dubinska hidratacija i obnova barijere: Ši puter i ulje pirinčanih mekinja hrane kožu i sprečavaju transepidermalni gubitak vode. Umiruje i štiti osetljivu kožu: Pantenol deluje regenerativno, ublažava iritacije i čini kožu otpornijom na spoljne uticaje. Brzo upijajuća tekstura bez lepljivosti: Idealna za svakodnevnu upotrebu – ne ostavlja masan trag i pogodna je za korišćenje u toku dana. Kome je namenjena? Krema je namenjena osobama sa suvom, dehidriranom i grubom kožom ruku, posebno onima koji često peru ruke, koriste sredstva za dezinfekciju ili rade u uslovima koji isušuju kožu. Pogodna je za sve tipove kože, uključujući i osetljivu. Zašto volimo Mary & May Shea Butter & Rice Bran Hand Cream? Shea Butter & Rice Bran Hand Cream pruža bogatu, ali neotežavajuću negu suvim i osetljivim rukama koje su svakodnevno izložene stresu. Zahvaljujući visokom sadržaju ši putera, krema dubinski hidrira i omekšava kožu, obnavljajući prirodnu lipidnu barijeru i sprečavajući dalje isušivanje. Ulje pirinčanih mekinja, bogato antioksidansima i vitaminom E, štiti kožu od spoljašnjih štetnih faktora i doprinosi glatkoći i elastičnosti. Pantenol umiruje iritiranu i oštećenu kožu, ubrzava zarastanje mikrooštećenja i pomaže u očuvanju vlage. Krema ima prijatnu, neutralnu aromu i brzo se upija, što je čini idealnom za svakodnevnu upotrebu kod kuće, na poslu ili u pokretu. Aktivni sastojci Ši puter (Butyrospermum Parkii Butter) Ši puter je snažan prirodni emolijent bogat esencijalnim masnim kiselinama i vitaminima A i E. Obnavlja oštećenu kožu, omekšava suve i grube regije i pruža dugotrajnu zaštitu od isušivanja. Deluje kao prirodna barijera protiv hladnoće, vetra i čestog pranja ruku. U ovoj kremi omogućava brzo i dubinsko omekšavanje kože bez osećaja masnoće. Ulje pirinčanih mekinja (Oryza Sativa Bran Oil) Ovo ulje je bogat izvor antioksidansa – uključujući feruličnu kiselinu i vitamin E – koji štite kožu od oksidativnog stresa i prevremenog starenja. Ima laganu teksturu, brzo se upija i ne ostavlja mastan film. Pomaže u omekšavanju grube kože i ujednačavanju tona kože ruku. U kombinaciji sa ši puterom čini kožu elastičnijom i vidno zdravijom. Pantenol (Provitamin B5) Pantenol prodire u dublje slojeve kože, hidrira i umiruje suvu, crvenu ili iritiranu kožu. Takođe pomaže u regeneraciji ćelija i ubrzava oporavak od oštećenja izazvanih čestim pranjem ili izloženošću hemikalijama. Doprinosi mekoći i fleksibilnosti kože, a posebno je koristan kod kože sklone ispucalosti i perutanju. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Shea Butter & Rice Bran Hand Cream je bogata, hranljiva krema za ruke koja kombinuje ši puter, ulje pirinčanih mekinja i pantenol za dubinsku hidrataciju, omekšavanje i zaštitu suve i grube kože ruku. Lagana i nemasna formula brzo se upija, ostavljajući kožu negovanom i elastičnom tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Mary-May-Shea-Butter-Rice-Bran-Hand-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
