INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (876, 114, 'Medicube Deep Vita C Pad', 'medicube-deep-vita-c-pad', 'Ključne prednosti: Vidljivo posvetljuje i ujednačava ten: Stabilizovani vitamin C i niacinamid sinergijski deluju na pigmentacije, fleke i sivilo kože. Poboljšava teksturu i tonus kože: Jastučići imaju blagi eksfolijacioni efekat koji zaglađuje površinu kože i otkriva svež, zdraviji ten. Praktična dnevna nega sa anti-age efektom: Adenozin i antioksidansi stimulišu regeneraciju i deluju protiv finih linija i opuštenosti. Kome su namenjeni? Idealni su za osobe sa neujednačenim tenom, postupalnim flekama, pigmentacijama, sivilom i kožom bez sjaja. Pogodan je za sve tipove kože, osim izrazito osetljive, uz prethodni test tolerancije. Zašto volimo Medicube Deep Vita C Pad? Deep Vita C Pad omogućava ciljani tretman posvetljavanja i revitalizacije kože kroz jednostavnu, svakodnevnu upotrebu. Natopljeni jastučići sadrže stabilizovani oblik vitamina C (etil askorbinska kiselina) koji deluje na dublje slojeve kože i pomaže u redukciji tamnih fleka i hiperpigmentacija bez tipičnih iritacija koje uzrokuje čisti askorbinska kiselina. Niacinamid dodatno posvetljuje kožu i poboljšava barijernu funkciju, dok adenozin deluje anti-age, poboljšava elastičnost i umanjuje fine linije. Blaga tekstura jastučića omogućava lagani fizički piling koji ne oštećuje kožu, ali doprinosi glatkoći i osveženom izgledu. Uz redovnu upotrebu, koža postaje ujednačenija, svetlija, mekša i vizuelno zdravija. Aktivni sastojci Etil askorbinska kiselina (Ethyl Ascorbic Acid) Ovo je stabilizovan i delotvoran derivat vitamina C, poznat po svojoj sposobnosti da inhibira sintezu melanina i posvetli tamne mrlje. Za razliku od čistog vitamina C, etil askorbat je manje iritativan, ali zadržava visok stepen efikasnosti. Poboljšava sintezu kolagena, ujednačava ten i daje koži blistavost. Takođe deluje kao snažan antioksidans koji štiti od UV i zagađenja. U kombinaciji sa niacinamidom pruža snažan sinergijski efekat u borbi protiv diskoloracija i neujednačenosti. Niacinamide (Vitamin B3) Niacinamid je višenamenski aktivni sastojak koji deluje na smanjenje pigmentacija, regulaciju sebuma i jačanje kožne barijere. U ovom proizvodu dopunjuje efekat vitamina C, posvetljuje kožu i smanjuje crvenilo. Takođe deluje umirujuće i pomaže koži da zadrži vlagu. Ključan je za ujednačen ten i svež izgled kože. Adenozin Adenozin je sastojak sa izraženim anti-age delovanjem – pomaže u opuštanju mišića lica, čime se umanjuje vidljivost finih linija i bora. Dodatno stimuliše obnavljanje ćelija i doprinosi elastičnosti kože. Blag je, ne izaziva iritacije i može se koristiti svakodnevno. Njegova uloga u ovoj formuli je podrška antioksidativnoj i regenerativnoj funkciji. Ekstrakt limuna i grejpa Prirodni voćni ekstrakti obogaćeni vitaminima i antioksidansima koji osvežavaju kožu, posvetljuju i daju blagi efekat eksfolijacije. Limun ima adstringentna svojstva koja sužavaju pore, dok grejp podstiče obnavljanje površinskog sloja kože. Pružaju i prijatan, osvežavajući miris proizvoda. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Vita C Pad su visokokoncentrovani tonirani jastučići natopljeni stabilizovanom vitamin C formulom, koji posvetljuju ten, poboljšavaju teksturu kože i smanjuju hiperpigmentacije. Kombinuju etil askorbinsku kiselinu, niacinamid i adenozin za ciljanu anti-age i posvetljujuću negu u praktičnom formatu.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Medicube-Deep-Vita-C-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
