INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (878, 111, 'Mary & May Shea Butter & Rice Bran Body Cream', 'mary-may-shea-butter-rice-bran-body-cream', 'Ključne prednosti: Intenzivna i dugotrajna hidratacija: Ši puter i biljna ulja obnavljaju lipidni sloj kože, sprečavajući dehidrataciju i perutanje. Poboljšava elastičnost i teksturu kože: Ulje pirinčanih mekinja bogato antioksidansima pomaže u omekšavanju i ujednačavanju kože. Prirodna, umirujuća formula bez iritansa: Bez parabena, veštačkih mirisa i alkohola – pogodna i za veoma osetljivu kožu. Kome je namenjena? Ova krema je idealna za suvu, grubu, zategnutu i dehidriranu kožu tela, uključujući kolena, laktove, noge i ruke. Pogodna je za svakodnevnu upotrebu i za sve koji žele bogatu, ali prijatnu formulu koja brzo donosi olakšanje i dugotrajan komfor. Zašto volimo Mary & May Shea Butter & Rice Bran Body Cream? Shea Butter & Rice Bran Body Cream donosi sve prednosti bogate, prirodne hidratacije u sofisticiranoj i lako upijajućoj formuli. Ši puter je poznat po svom dubinskom emolijentnom dejstvu – obnavlja suvu, ispucalu kožu i stvara zaštitnu barijeru bez osećaja težine. Ulje pirinčanih mekinja, bogato vitaminom E i feruličnom kiselinom, neguje kožu i poboljšava njenu elastičnost, dok biljni ekstrakti umiruju iritacije i poboljšavaju tonus. Iako hranljiva, krema se brzo upija i ne ostavlja lepljiv ili mastan film, čineći je pogodnom i za jutarnju i za večernju rutinu. Redovnom upotrebom, koža postaje mekša, glađa, vidno elastičnija i zaštićena od spoljnih agresora. Aktivni sastojci Ši puter (Butyrospermum Parkii Butter) Ši puter je prirodni emolijent bogat masnim kiselinama i vitaminima A i E. On stvara zaštitni sloj na koži koji sprečava gubitak vlage i ubrzava regeneraciju suve i oštećene kože. Njegovo dubinsko hranljivo dejstvo čini kožu elastičnijom i otpornijom, a istovremeno je umiruje i omekšava. Posebno je efikasan kod grube i zategnute kože, kao i na ispucalim delovima poput laktova, peta i kolena. U ovoj kremi, ši puter ima ključnu ulogu u vraćanju mekoće i glatkoće koži tela. Ulje pirinčanih mekinja (Oryza Sativa Bran Oil) Ovo ulje je bogato vitaminom E, fitosterolima i feruličnom kiselinom – prirodnim antioksidansima koji štite kožu od slobodnih radikala i ubrzanog starenja. Deluje umirujuće i pomaže u zadržavanju vlage, čineći kožu mekom i ujednačenom. Ulje pirinčanih mekinja takođe posvetljuje kožu i poboljšava njen prirodni sjaj. U kombinaciji sa ši puterom, pojačava elastičnost i oporavlja barijernu funkciju kože. Idealno za svakodnevnu negu suve i dehidrirane kože. Pantenol (Provitamin B5) Pantenol ima snažno hidratantno i umirujuće dejstvo. Prodire duboko u kožu, vezuje vodu i ubrzava regeneraciju epidermisa. Smanjuje iritacije, peckanje i crvenilo, čineći kožu otpornijom i prijatnijom na dodir. U telu je naročito koristan kod suvih regija koje su često podložne trenju ili spoljašnjim stresorima. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Shea Butter & Rice Bran Body Cream je bogata, hranljiva krema za telo formulisana sa ši puterom, uljem pirinčanih mekinja i biljnim ekstraktima, namenjena za dubinsku hidrataciju, obnavljanje i zaštitu suve i osetljive kože. Njena raskošna, ali lako upijajuća tekstura ostavlja kožu mekom, glatkom i intenzivno nahranjenom.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Mary-May-Shea-Butter-Rice-Bran-Body-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
