INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (880, 74, 'House of Hur Midnight Soothing Cleansing Balm', 'house-of-hur-midnight-soothing-cleansing-balm', 'Ključne prednosti: Temeljno uklanjanje šminke i SPF-a: topi čak i dugotrajnu šminku bez grubog trljanja. Umiruje i štiti kožnu barijeru: biljni ekstrakti smanjuju crvenilo i osećaj iritacije. Hidratacija bez masnog traga: koža ostaje meka i elastična nakon ispiranja. Kome je namenjen? Ovaj balzam je pogodan za sve tipove kože – normalnu, suvu, kombinovanu i osetljivu. Posebno se preporučuje osobama koje koriste SPF i šminku svakodnevno, kao i koži sklonoj crvenilu i dehidrataciji, kojoj je potrebno nežno, ali efikasno čišćenje. Zašto volimo House of Hur Midnight Soothing Cleansing Balm? Zato što čini čišćenje kože prijatnim ritualom, a ne obavezom. Efikasno uklanja sve nečistoće, dok kožu istovremeno neguje i smiruje. Njegova tekstura i bogata, ali uravnotežena formula čine ga odličnim izborom za večernju rutinu, čak i kada je koža umorna ili reaktivna. Aktivni sastojci Caprylic/Capric Triglyceride Blagi emolijent koji omekšava kožu i pomaže rastvaranje šminke bez začepljenja pora. C13–15 Alkane Lagani emolijent koji poboljšava razmazivost i daje svilenkast osećaj tokom masaže. Ricinusovo ulje (Ricinus Communis Seed Oil) Efikasno rastvara šminku i nečistoće, a pritom štiti kožu od isušivanja. Ulje suncokreta (Helianthus Annuus Seed Oil) Bogato masnim kiselinama koje jačaju kožnu barijeru i pružaju dodatnu negu. Ekstrakt pirinča (Oryza Sativa Extract) Umiruje kožu, poboljšava hidrataciju i doprinosi elastičnosti. Ekstrakt čia semena (Salvia Hispanica Seed Extract) Pomaže zadržavanje vlage u koži i doprinosi njenoj mekoći. Ekstrakt kestena (Castanea Crenata Shell Extract) Deluje antioksidativno i umirujuće, doprinosi ujednačenijem tonu i boljoj teksturi kože. Vitamin E (Tocopheryl Acetate) Štiti kožu od spoljašnjih uticaja i pomaže očuvanje zdrave barijere. Dodaj u listu želja Dodaj u listu želja', 'House of Hur Midnight Soothing Cleansing Balm kombinuje pažljivo odabrana biljna ulja i umirujuće ekstrakte kako bi temeljno očistio kožu, a istovremeno pružio hidrataciju i osećaj komfora. Ekstrakti crnog pirinča, čia semena i kestena doprinose smirenju, elastičnosti i boljoj teksturi kože, čineći ovaj balzam idealnim prvim korakom dvostrukog čišćenja.', 'https://beauty-health.rs/wp-content/uploads/2025/04/House-of-Hur-Midnight-Soothing-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
