INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (881, 73, 'Heveblue Salmon Fruity Centella Body Wash', 'heveblue-salmon-fruity-centella-body-wash', 'Ključne prednosti: Blago, ali efikasno čišćenje kože: Gel formulacija nežno uklanja nečistoće bez narušavanja prirodne pH vrednosti kože. Umirujuće i regenerativno delovanje: Ekstrakt lososa i Centella Asiatica obnavljaju kožu i ublažavaju crvenilo, svrab i iritacije. Voćni miris i antioksidativna nega: Kompleks voćnih ekstrakata osvežava kožu i štiti je od spoljašnjih agresora. Kome je namenjen? Ovaj gel za tuširanje idealan je za sve tipove kože, uključujući suvu, osetljivu i reaktivnu kožu sklonu iritacijama. Pogodan je i za svakodnevnu upotrebu kod cele porodice – uključujući decu stariju od 6 meseci i osobe sa atopičnom kožom. Zašto volimo HEVEBLUE Salmon Fruity Centella Body Wash? Salmon Fruity Centella Body Wash pruža luksuzno iskustvo tuširanja uz terapeutske benefite za kožu. Umesto agresivnih sulfata, koristi blage surfaktante koji ne isušuju, već očuvaju prirodni zaštitni sloj kože. Ekstrakt lososa bogat omega-3 masnim kiselinama i proteinima doprinosi regeneraciji kože i povećava njenu otpornost. Centella Asiatica, uz madecassoside, umiruje upale, svrab i crvenilo, što ovaj gel čini pogodnim i za osetljivu ili atopičnu kožu. Voćni ekstrakti breskve, manga i nara pružaju antioksidativnu zaštitu i osvežavaju kožu, dok lagani miris ostavlja dugotrajan osećaj čistoće i svežine. Nakon upotrebe, koža je čista, umirena, elastična i prijatno mirisna, bez osećaja zatezanja. Aktivni sastojci Ekstrakt lososa Bogat omega-3 masnim kiselinama, proteinima i astaksantinom, ekstrakt lososa pruža koži intenzivnu ishranu i podstiče regeneraciju ćelija. Deluje protivupalno i poboljšava elastičnost, čineći kožu mekšom i otpornijom na svakodnevne iritacije. Idealan je za negu suve i oslabljene kože. U ovoj formuli, ekstrakt lososa deluje već tokom tuširanja, pripremajući kožu za hidratantnu negu. Centella Asiatica + Madecassoside Poznata po svojim obnavljajućim i umirujućim svojstvima, Centella Asiatica ublažava iritacije, crvenilo i svrab, dok madecassoside pospešuje zarastanje i jača kožnu barijeru. Ovaj sastojak je ključan za osobe sa osetljivom ili reaktivnom kožom. Takođe pomaže u smirivanju kože nakon sunčanja, depilacije ili izlaganja spoljnim stresorima. Voćni kompleks (breskva, mango, nar) Ovi ekstrakti bogati su vitaminima C i E, flavonoidima i prirodnim kiselinama koje pomažu u zaštiti kože od oksidativnog stresa. Voćni kompleks osvežava, omekšava i revitalizuje kožu, ostavljajući je svetlijom i glatkijom. Takođe doprinosi prirodno prijatnom i osvežavajućem mirisu formule. Blagi surfaktanti na bazi kokosa Umesto sulfata, korišćeni su blagi surfaktanti (npr. Cocamidopropyl Betaine) koji stvaraju bogatu, ali nežnu penu. Ne narušavaju zaštitni sloj kože i ne izazivaju osećaj zatezanja. Idealni su za svakodnevnu upotrebu i kod osoba sa osetljivom kožom. Dodaj u listu želja Dodaj u listu želja', 'HEVEBLUE Salmon Fruity Centella Body Wash je blagi gel za tuširanje formulisan sa ekstraktom lososa, Centella Asiatica i voćnim kompleksom, koji temeljno čisti kožu bez isušivanja, dok istovremeno umiruje, hidrira i osvežava. Njegova hranljiva pena obavija kožu laganim voćnim mirisom i ostavlja je mekom, elastičnom i negovanom.', 'https://beauty-health.rs/wp-content/uploads/2025/04/HEVEBLUE-Salmon-Fruity-Centella-Body-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
