INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (882, 73, 'Heveblue Salmon Fruity Centella Body Cream', 'heveblue-salmon-fruity-centella-body-cream', 'Ključne prednosti: Dubinska hidratacija i obnova kože: Ekstrakt lososa i ceramidi pomažu u obnovi kožne barijere i sprečavaju isušivanje. Umiruje crvenilo i iritacije: Visok sadržaj Centella Asiatica i madecassoside-a ublažava osetljivost i pospešuje regeneraciju kože. Voćni antioksidansi za sjaj i elastičnost: Voćni ekstrakti bogati vitaminima štite kožu i ostavljaju je osveženom, nežnom i mirisnom. Kome je namenjena? Ova krema je idealna za suvu, osetljivu i reaktivnu kožu tela, uključujući osobe sklone crvenilu, iritacijama ili atopičnim reakcijama. Pogodna je za svakodnevnu upotrebu i za celu porodicu – uključujući i decu uzrasta 6+ meseci. Zašto volimo HEVEBLUE Salmon Fruity Centella Body Cream? Salmon Fruity Centella Body Cream je spoj funkcionalne dermokozmetike i senzornog užitka. Njen glavni sastojak – ekstrakt lososa – bogat je proteinima i omega-3 masnim kiselinama, koje intenzivno hrane kožu i podstiču ćelijsku regeneraciju. Centella Asiatica, zajedno sa madecassoside-om, brzo umiruje iritacije, poboljšava zaceljivanje i štiti kožu od spoljnih uticaja. Voćni kompleks (breskva, mango, nar) bogat antioksidansima osvežava kožu, doprinosi ujednačenijem tenu i ostavlja blagi, voćni miris. Krema se lako razmazuje, brzo upija i ne ostavlja lepljiv trag, što je čini idealnom i za jutarnju i za večernju rutinu. Redovnom upotrebom, koža postaje meka, glatka i vidljivo zdravija. Aktivni sastojci Ekstrakt lososa Ekstrakt lososa je izuzetno bogat omega-3 masnim kiselinama, proteinima i astaksantinom – snažnim antioksidansom koji jača kožnu barijeru, poboljšava elastičnost i podstiče regeneraciju. Ovaj sastojak hidrira u dubinu i pomaže koži da zadrži vlagu duže vreme. Takođe pospešuje zaceljivanje mikrooštećenja i doprinosi ujednačenijem tonu kože. Idealan je za suvu, dehidriranu ili reaktivnu kožu. Njegovo dejstvo posebno dolazi do izražaja kod kože sklone osetljivosti, perutanju i zatezanju. Centella Asiatica (i madecassoside) Centella Asiatica je dobro poznata po svom regenerativnom i protivupalnom delovanju. Smiruje crvenilo, umanjuje svrab i stimuliše prirodnu sintezu kolagena. Madecassoside, kao jedan od njenih najaktivnijih derivata, dodatno ubrzava obnavljanje oštećene kože i poboljšava njenu otpornost. U telu, posebno deluje na regije sklone iritacijama – poput nogu, laktova, nadlaktica i leđa. Redovnom upotrebom koža postaje mirnija, glatkija i manje reaktivna. Dodaj u listu želja Dodaj u listu želja', 'HEVEBLUE Salmon Fruity Centella Body Cream je bogata, brzo upijajuća krema za telo formulisana sa ekstraktom lososa, Centella Asiatica i voćnim kompleksom. Namenjena je za intenzivnu hidrataciju, umirenje i regeneraciju suve, osetljive i iritirane kože tela, uz prijatan osvežavajući miris.', 'https://beauty-health.rs/wp-content/uploads/2025/04/HEVEBLUE-Salmon-Fruity-Centella-Body-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
