INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (883, 73, 'Heveblue Salmon Caring Centella Cream', 'heveblue-salmon-caring-centella-cream', 'Ključne prednosti: Regeneriše i obnavlja oštećenu kožu: Ekstrakt lososa bogat proteinima i omega-3 masnim kiselinama ubrzava ćelijsku obnovu i jača otpornost kože. Smanjuje crvenilo i upale: Visoka koncentracija Centella Asiatica i madecassoside-a umiruje iritacije i ubrzava zaceljivanje kože. Jača barijeru i hidrira: Peptidi i ceramidi obnavljaju strukturu kože, sprečavaju transepidermalni gubitak vode i pružaju dugotrajnu hidrataciju. Kome je namenjena? Krema je posebno formulisana za osetljivu, crvenu, reaktivnu i oslabljenom barijerom kožu – idealna za korišćenje nakon agresivnih tretmana (npr. pilinga, retinola, sunčanja). Pogodna je i za suvu i normalnu kožu kojoj je potrebna balansirana nega sa antiinflamatornim efektima. Zašto volimo HEVEBLUE Salmon Caring Centella Cream? Salmon Caring Centella Cream kombinuje moć regenerativnih i umirujućih sastojaka kako bi pružila potpunu obnovu i zaštitu osetljive kože. Ključni sastojak – ekstrakt lososa – bogat je proteinima, omega-3 masnim kiselinama i astaksantinom, snažnim antioksidansom koji poboljšava elastičnost, ten i oporavak kože. Visok sadržaj Centella Asiatica, uključujući madecassoside i asiaticoside, smanjuje crvenilo, ublažava upale i ubrzava zarastanje mikrooštećenja. Dodaci poput ceramida i peptida jačaju kožnu barijeru i poboljšavaju hidrataciju, dok niacinamid pomaže u ujednačavanju tena. Tekstura je bogata, ali se brzo upija, ostavljajući kožu umirenom, mekom i zaštićenom – bez osećaja težine ili masnoće. Aktivni sastojci Ekstrakt lososa Ekstrakt lososa sadrži dragocene nutrijente kao što su proteini, omega-3 masne kiseline (npr. DHA i EPA) i astaksantin – jedan od najsnažnijih prirodnih antioksidanasa. Deluje regenerativno, poboljšava elastičnost i ubrzava zarastanje oštećene kože. Posebno je koristan kod tanke, suve i osetljive kože koja je sklona upalama ili sporoj regeneraciji. Takođe ima efekat osvetljavanja kože i ujednačavanja tena. U ovoj kremi, ekstrakt lososa deluje kao „super-hrana” za kožu, podstičući ćelijsku obnovu i otpornost. Njegovo dejstvo vidljivo je već nakon nekoliko dana redovne upotrebe. Centella Asiatica (i derivati: madecassoside, asiaticoside) Centella Asiatica je poznata po svojim snažnim umirujućim i regenerativnim svojstvima. Aktivni derivati poput madecassoside-a i asiaticoside-a ubrzavaju zarastanje kože, smanjuju upale i štite od spoljašnjih iritansa. Posebno efikasna kod kože sklone crvenilu, osipima i reaktivnosti. Pomaže i kod postinflamatornih tragova i obnavlja barijernu funkciju kože. Centella stimuliše sintezu kolagena i čini kožu elastičnijom i otpornijom. Ne izaziva iritacije i pogodna je za svakodnevnu upotrebu čak i kod atopične kože. Peptidi Peptidi su signalni molekuli koji stimulišu sintezu kolagena i elastina, čime koža postaje čvršća, zategnutija i otpornija. Takođe pomažu u reparaciji oštećenja izazvanih UV zračenjem i stresom. U ovoj formuli deluju regenerativno i umirujuće, obnavljajući strukturu oštećene barijere. U kombinaciji sa ceramidima, peptidi pružaju dubinsku obnovu i smanjuju znakove umora. Pogodni su za zrelu, osetljivu i oštećenu kožu. Ceramidi Ceramidi su lipidi koji obnavljaju barijernu funkciju kože, smanjuju gubitak vlage i štite od agresivnih spoljnih faktora. U HEVEBLUE formuli, oni sprečavaju isušivanje i jačaju otpornost kože na iritacije. Redovnom upotrebom, koža postaje hidriranija, mekša i manje sklona crvenilu i perutanju. Ceramidi doprinose glatkoći teksture kože i pružaju osećaj dugotrajnog komfora. Dodaj u listu želja Dodaj u listu želja', 'HEVEBLUE Salmon Caring Centella Cream je intenzivno regenerativna i umirujuća krema formulisana sa ekstraktom lososa, Centella Asiatica i peptidima, namenjena jačanju barijere kože, ubrzanju regeneracije i smanjenju upala. Idealna je za osetljivu, crvenu, iritiranu i oslabljenu kožu kojoj je potrebna reparativna nega.', 'https://beauty-health.rs/wp-content/uploads/2025/04/HEVEBLUE-Salmon-Caring-Centella-Cream-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
