INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (884, 56, 'Elizavecca Cer-100 Collagen Coating Hair Muscle Treatment Rinse', 'elizavecca-cer-100-collagen-coating-hair-muscle-treatment-rinse', 'Ključne prednosti: Obnavlja i jača slabu i oštećenu kosu: Kolagen i keratin deluju iznutra, obnavljajući strukturu vlasi i štiteći je od pucanja. Zaglađuje kutikulu i povećava sjaj: Zahvaljujući ceramidima i biljnim uljima, kosa postaje glatka, meka i sjajna već nakon prvog korišćenja. Pruža zaštitni sloj i elastičnost: Tretman stvara proteinski film koji jača „mišiće“ kose i povećava njenu otpornost na spoljašnje agresore. Kome je namenjen? Ovaj tretman je idealan za osobe sa suvom, oštećenom, izbeljenom ili hemijski tretiranom kosom kojoj je potrebna intenzivna obnova i zaštita. Pogodan je za sve tipove kose, posebno one koje su sklone lomljenju, perutanju i gubitku sjaja. Zašto volimo Elizavecca Cer-100 Collagen Coating Hair Muscle Treatment Rinse? CER-100 Collagen Coating Hair Muscle Treatment Rinse je kultni tretman za kosu koji deluje kao &#8220;protein booster&#8221; i istovremeno kao regenerator. Formula bogata kolagenom i keratinom osmišljena je da cilja slabe tačke u strukturi vlasi, obnavljajući ih iznutra i formirajući zaštitni sloj na površini. Rezultat je kosa koja izgleda gušće, zdravije i elastičnije, a pritom ostaje lagana i podatna. Tretman deluje već nakon jednog korišćenja – trenutno omekšava kosu, olakšava raščešljavanje i pruža osećaj luksuzne mekoće. Redovnim korišćenjem, efekti se akumuliraju: kosa postaje jača, manje sklona pucanju, a kutikula sve glađa. Prijatna tekstura i osvežavajući miris dodatno doprinose SPA iskustvu kod kuće. Aktivni sastojci Hidrolizovani kolagen Kolagen je protein koji čini osnovnu strukturu dlake, a njegova hidrolizovana forma u ovoj formuli lako prodire u dublje slojeve vlasi. On jača kosu iznutra, poboljšava elastičnost i smanjuje lomljenje. Hidrolizovani kolagen stvara zaštitni film na površini dlake, sprečavajući gubitak vlage i štiteći od mehaničkih oštećenja. Takođe daje kosi zategnutiji, puniji izgled. Njegovo prisustvo značajno doprinosi otpornosti kose na češljanje i stilizovanje. Idealno za regeneraciju kose nakon hemijskog tretmana ili čestog izlaganja toploti. Keratin Keratin je osnovni protein kose, odgovoran za njenu čvrstinu i elastičnost. U ovoj formuli, keratin popunjava oštećene delove dlake, poboljšava integritet vlasi i štiti je od pucanja. Takođe doprinosi glatkoći i sjaju, čineći kosu podatnijom. Keratin deluje regenerativno i antistatički, čime smanjuje friz efekat. Redovnim korišćenjem, kosa postaje otpornija i lakša za oblikovanje. Ključan je sastojak za obnavljanje ispucalih i oslabljenih vlakana dlake. Ceramidi Ceramidi u ovoj formuli deluju kao lipidna zaštita koja zatvara kutikulu i čuva hidrataciju unutar vlasi. Oni pomažu u jačanju spoljašnjeg sloja dlake i smanjuju poroznost kose. Time se kosa štiti od isušivanja, UV zračenja i agresivnih tretmana. Ceramidi poboljšavaju teksturu i ujednačenost kose, čineći je sjajnijom i glatkijom. Pomažu i u obnavljanju ravnoteže kod kose sklone lomljenju. Kombinovani sa proteinima, pružaju i mehaničku i hemijsku zaštitu. Dodaj u listu želja Dodaj u listu želja', 'Elizavecca CER-100 Collagen Coating Hair Muscle Treatment Rinse je bogati proteinski tretman i regenerator u jednom, formulisan da ojača, regeneriše i obloži vlas kolagenom i proteinima. Kombinuje hidrolizovani kolagen, keratin, ceramide i biljne ekstrakte kako bi dubinski oporavio oštećenu kosu i poboljšao njenu elastičnost i sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Elizavecca-CER-100-Collagen-Coating-Hair-Muscle-Treatment-Rinse-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
