INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (895, 40, 'Cosrx Two in One Poreless Power Liquid', 'cosrx-two-in-one-poreless-power-liquid', 'Ključne prednosti: Smanjuje i čisti pore: Blagi BHA piling prodire duboko u pore i uklanja višak sebuma i nečistoće, smanjujući njihovu vidljivost i sprečavajući pojavu mitisera. Hidrira i osvežava kožu: Zahvaljujući mentolu i hidratantnim sastojcima, pruža efekat hlađenja i trenutan osećaj svežine bez isušivanja. Reguliše masnoću i poboljšava ton kože: Deluje balansirajuće na kožu sklonu pojačanom lučenju sebuma, čime doprinosi ujednačenijem, matiranom tenu. Kome je namenjen? Ovaj proizvod je idealan za osobe sa proširenim porama, masnom i kombinovanom kožom, kao i za sve koji se bore sa mitiserima, teksturalnim nepravilnostima i prekomernim sjajem. Pogodan je i za osetljivu kožu zahvaljujući blagoj formulaciji bez alkohola i veštačkih mirisa. Zašto volimo COSRX Two in One Poreless Power Liquid? Two in One Poreless Power Liquid je multifunkcionalna nega koja kombinuje efekte tonera i seruma u jednom koraku. Njegov BHA derivat – betain salicilat – deluje dubinski u porama, rastvarajući višak sebuma i sprečavajući začepljenja, dok ekstrakt kore vrbe ima prirodna adstringentna svojstva koja zatežu kožu i smanjuju vidljivost pora. Posebno formulisana vodena tekstura omogućava brzo upijanje bez lepljivosti, ostavljajući kožu hidriranom, svežom i matiranom. Mentol dodatno doprinosi efekatu hlađenja, što ga čini odličnim izborom za upotrebu tokom toplih meseci ili nakon izlaganja toploti. Redovnom upotrebom, ten postaje ujednačeniji, pore čistije i manje izražene, a koža zdravija i balansirana. Aktivni sastojci Betain salicilat (BHA) Betain salicilat je blaga, ali efikasna alternativa tradicionalnoj salicilnoj kiselini. Deluje eksfolijativno i antibakterijski, čime sprečava pojavu mitisera i upalnih procesa. Pomaže u smanjenju viška sebuma i čisti pore u dubinu bez izazivanja iritacija. Za razliku od jačih BHA kiselina, betain salicilat je pogodan i za osetljivu kožu. Dugotrajnom upotrebom, ujednačava teksturu kože i poboljšava njen ukupni izgled. Ekstrakt kore vrbe Ovaj prirodni sastojak bogat je salicilinskom kiselinom i deluje kao biljna alternativa BHA, s blagim adstringentnim i umirujućim svojstvima. Pomaže u sužavanju pora, kontroli sebuma i ublažavanju upala. Doprinosi obnavljanju površinskog sloja kože i blago eksfolira, bez iritacija. U kombinaciji sa betain salicilatom pruža sinergijski efekat u detoksikaciji pora. Takođe sadrži antioksidanse koji štite kožu od štetnih uticaja okoline. Mentol Mentol pruža trenutni efekat hlađenja i osveženja, što pomaže u smanjenju osećaja zatezanja ili iritacije. Deluje umirujuće na kožu i daje prijatan osećaj čistoće. Takođe ima blagi adstringentni efekat, koji doprinosi vizuelnom sužavanju pora. Koristan je za regulaciju masnoće i kao dodatna pomoć kod upalnih procesa. Ne isušuje kožu, već doprinosi ravnoteži između hidratacije i kontrole sebuma. Dodaj u listu želja Dodaj u listu želja', 'COSRX Two in One Poreless Power Liquid je lagani tonik-serum formulisan za trenutnu hidrataciju i dugoročno sužavanje pora. Kombinuje BHA (betain salicilat) i prirodni ekstrakt kore vrbe kako bi efikasno čistio pore, regulisao višak sebuma i poboljšao teksturu kože.', 'https://beauty-health.rs/wp-content/uploads/2025/04/COSRX-Two-in-One-Poreless-Power-Liquid.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
