INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (897, 40, 'Cosrx The Hyaluronic Acid 3 Serum', 'cosrx-the-hyaluronic-acid-3-serum', 'Ključne prednosti: +223% hidratacije nakon prve upotrebe – 3% hijaluronske kiseline deluje u različitim slojevima kože i osigurava dubinsku vlagu. Obnova i zaštita kože – Ceramide NP i aminokiseline jačaju barijeru i štite kožu od dehidratacije. Formulisano za osetljivu kožu – Dermatološki testirano i dokazano kao neiritirajuće, čak i kod najosetljivijih tipova. Kome je namenjen? Preporučuje se osobama sa suvom, dehidriranom, zategnutom ili osetljivom kožom, kao i onima koji žele da povrate elastičnost, sjaj i glatkoću kože. Pogodno za svakodnevnu upotrebu u rutini hidratacije, u kombinaciji sa drugim aktivnim proizvodima. Zašto volimo Cosrx The Hyaluronic Acid 3 Serum? The Hyaluronic Acid 3 Serum je formulisan sa visokom koncentracijom hijaluronske kiseline (3%), koja ima sposobnost da zadrži i do 1000 puta veću količinu vode od svoje težine, pružajući trenutnu i dugotrajnu hidrataciju. Kombinacijom aminokiselina i ceramida NP, serum ne samo da hidrira, već i jača prirodnu zaštitnu barijeru kože, štiti od isušivanja i spoljašnjih agresora. Tekstura je lagana, nelepljiva i brzo se upija, ostavljajući kožu mekom, punijom i elastičnijom. Klinički testovi pokazuju povećanje hidratacije kože za više od 223% nakon samo jedne primene, dok 100% korisnika potvrđuje da je koža hidrirana i zaglađena tokom celog dana. Idealan je za samostalnu upotrebu, kao i u slojevitim rutinama uz druge serume ili hidratantne kreme. Aktivni sastojci Hijaluronska kiselina (3%) Multimolekularna hijaluronska kiselina obezbeđuje hidrataciju u različitim slojevima kože – od površinskog do dubinskog. Povećava elastičnost, popunjava fine linije i daje koži zdrav, pun izgled. Ceramide NP Ključni lipid koji jača kožnu barijeru i sprečava gubitak vlage. Pomaže koži da ostane zaštićena, elastična i otporna na iritanse i spoljne faktore. Aminokiseline Prirodne komponente koje podržavaju strukturu kože, pomažu u održavanju vlažnosti i ubrzavaju regeneraciju. Deluju umirujuće i poboljšavaju funkcionalnost ostalih aktivnih sastojaka. Klinički dokazana efikasnost +223% povećanje hidratacije nakon 1 upotrebe 100% korisnika potvrdilo: Koža je celodnevno hidrirana Površinski slojevi kože bolje zadržavaju vlagu Koža je zaglađena i elastičnija Dermatološki testirano, ne izaziva iritacije kod osetljive kože Dodaj u listu želja Dodaj u listu želja', 'COSRX The Hyaluronic Acid 3 Serum je intenzivno hidratantni serum sa 3% hijaluronske kiseline, aminokiselinama i ceramidom NP, formulisan da trenutno poveća nivo vlažnosti kože, ojača barijernu funkciju i vrati koži punoću i elastičnost. Klinički je potvrđeno da ne izaziva iritacije, što ga čini pogodnim i za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Cosrx-The-Hyaluronic-Acid-3-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
