INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (898, 40, 'Cosrx Moisture Power Enriched Cream', 'cosrx-moisture-power-enriched-cream', 'Ključne prednosti: Obnavlja i štiti kožnu barijeru – Ceramidi zaključavaju vlagu i štite od dehidratacije. Umiruje i hidrira – D-pantenol i ekstrakt propolisa sinergijski smanjuju crvenilo i jačaju otpornost kože. Lagana tekstura, bogat efekat – Iako hranljiva, krema se brzo upija i ne ostavlja mastan trag. Kome je namenjena? Idealna za osobe sa suvom, dehidriranom, zategnutom ili iritiranom kožom, kao i za one koji koriste klimatizaciju leti ili grejanje zimi. Posebno pogodna za korisnike koji traže bezmirisnu i nekomedogenu hidratantnu kremu. Zašto volimo COSRX Moisture Power Enriched Cream? Moisture Power Enriched Cream koristi trostruki kompleks – D-pantenol, propolis i ceramide – da bi stvorila tzv. Water Blanket System, odnosno zaštitni hidratantni sloj koji sprečava gubitak vode iz kože i pomaže u održavanju balansa ulja i vlage. D-pantenol (provitamin B5) ima snažna umirujuća i regenerativna svojstva, dok propolis dodatno deluje antibakterijski i protuupalno. Ceramidi pomažu u jačanju zaštitne funkcije kože, čineći je elastičnijom i otpornijom. Kremasta, ali lagana tekstura čini je pogodnom za upotrebu ujutru i uveče, samostalno ili kao završni korak u slojevitoj rutini. Posebno korisna u suvim klimatskim uslovima ili u sezoni grejanja/klimatizacije kada koža brzo gubi vlagu. Aktivni sastojci D-pantenol (Provitamin B5) Poznat po umirujućem, obnavljajućem i hidratantnom dejstvu. Pomaže u jačanju kožne barijere, smanjuje crvenilo i poboljšava elastičnost. Odličan za osetljivu i reaktivnu kožu. Ekstrakt propolisa Prirodni antioksidans sa antibakterijskim i regenerativnim svojstvima. Podstiče obnavljanje kože, smanjuje upalne procese i daje prirodan sjaj. Pomaže u balansiranju proizvodnje sebuma. Ceramidi Lipidi prirodno prisutni u koži, ključni za očuvanje vlage i zaštitu od spoljnih agresora. Obnavljaju kožnu barijeru i sprečavaju transepidermalni gubitak vode. Neophodni kod suve i osetljive kože. Dodaj u listu želja Dodaj u listu želja', 'COSRX Moisture Power Enriched Cream je intenzivno hidratantna krema koja koristi provitamin B5 (D-pantenol), propolis i ceramide kako bi stvorila zaštitni sloj vlage, poboljšala elastičnost kože i pružila dugotrajnu mekoću bez osećaja težine. Savršena je za suvu i osetljivu kožu, naročito u uslovima suve klime ili nakon iritacija.', 'https://beauty-health.rs/wp-content/uploads/2025/04/COSRX-Moisture-Power-Enriched-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
