INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (899, 40, 'Cosrx Full Fit Propolis Light Ampoule', 'cosrx-full-fit-propolis-light-ampoule', 'Ključne prednosti: Dubinska hidratacija i jačanje kože – Crni propolis bogat antioksidansima jača prirodnu zaštitnu funkciju kože i umiruje upale. Povećava elastičnost i sjaj – Hijaluronska kiselina i pantenol doprinose glatkoći i punoći kože uz dugotrajnu vlagu. Brzi rezultati i klinička efikasnost – Dokazano povećava hidrataciju kože za 168,34% već nakon jedne upotrebe. Kome je namenjena? Preporučuje se osobama sa suvoj, dehidriranoj, umornoj ili nadraženoj koži, kao i onima koje žele vidljiv “honey glow” efekat bez iritacija. Pogodna za sve tipove kože, uključujući osetljivu. Zašto volimo COSRX Full Fit Propolis Light Ampoule? Full Fit Propolis Light Ampoule je deo Propolis linije zasnovane na visokom udelu crnog pčelinjeg propolisa, poznatog po moćnim umirujućim, regenerativnim i antioksidativnim svojstvima. Sa 83,3% ekstrakta propolisa, ova ampula nudi višestruke benefite – od jačanja kožne barijere do ublažavanja crvenila i iritacija. U kombinaciji sa 0,2% hijaluronske kiseline i 0,1% pantenola, pruža višeslojnu hidrataciju i podržava obnovu kože iznutra. Tekstura je bogata, ali lagana i nelepljiva, što omogućava lako nanošenje i brzo upijanje. Klinički podaci pokazuju povećanje nivoa hidratacije za 168,34% nakon samo jedne upotrebe, uz 95% zadovoljnih korisnika i 100% onih koji bi preporučili proizvod. Idealna je za svakodnevnu upotrebu, samostalno ili u okviru kompletne rutine. Aktivni sastojci Propolis Extract (83,3%) Prirodni sastojak koji potiče iz pčelinjih košnica, poznat po antibakterijskim, antiinflamatornim i regenerativnim svojstvima. Jača kožnu barijeru, umiruje upale i poboljšava otpornost kože. Doprinosi zdravom sjaju i smanjuje crvenilo. Hijaluronska kiselina (0,2%) Vrhunski humektant koji zadržava vlagu u dubljim slojevima kože. Pruža trenutni i dugotrajni hidratantni efekat, popunjava sitne linije i poboljšava elastičnost kože. Pantenol (0,1%) Poznat i kao provitamin B5, deluje umirujuće i regenerativno. Pomaže u obnavljanju kože i štiti od spoljašnjih uticaja, čineći je mekom i elastičnom. Klinički rezultati +168,34% hidratacije nakon samo jedne upotrebe 95% korisnika zadovoljno nivoom hidratacije 100% bi preporučilo proizvod Istraživanje sprovedeno 2021. godine na 20 žena tokom 2 nedelje (Derma Cosmetics Dermatology Research Institute) Dodaj u listu želja Dodaj u listu želja', 'COSRX Full Fit Propolis Light Ampoule je visoko koncentrisana ampula sa 83,3% ekstrakta crnog propolisa, formulisana da intenzivno hidrira, umiri i revitalizuje kožu, pružajući joj zdrav, prirodan sjaj. Uz dodatak hijaluronske kiseline i pantenola, pruža višeslojnu hidrataciju i pomaže u obnavljanju osetljive, dehidrirane kože.', 'https://beauty-health.rs/wp-content/uploads/2025/04/COSRX-Full-Fit-Propolis-Light-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
