INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (900, 39, 'Cos De BAHA PC M.A Peptide Cream', 'cos-de-baha-pc-m-a-peptide-cream', 'Ključne prednosti: Smanjuje bore i linije – Matrixyl 3000 i Argireline deluju sinergijski kako bi podstakli sintezu kolagena i opustili mikromišiće lica. Poboljšava elastičnost i teksturu – Niacinamid i hijaluronska kiselina jačaju kožnu barijeru i vraćaju koži glatkoću i punoću. Brza apsorpcija bez masnog osećaja – Lagana, nemasna formula se brzo upija i ostavlja kožu mekšom, hidriranom i zategnutijom. Kome je namenjena? Krema je idealna za zrelu, dehidriranu ili umornu kožu sa izraženim borama, linijama ili gubitkom tonusa. Pogodna je i za osetljivu kožu jer ne sadrži alkohol, parabene, veštačke boje ni mirise. Namenjena je korisnicima koji žele vidljive anti-age rezultate uz visok nivo tolerancije. Zašto volimo Cos De BAHA PC M.A Peptide Cream? PC M.A Peptide Cream kombinuje najsavremenije peptide sa dokazanim hidratantnim i regenerativnim sastojcima kako bi pružila snažan anti-age efekat bez iritacija. Matrixyl 3000, moćni kompleks peptida, stimuliše sintezu kolagena i elastina, čineći kožu čvršćom i punijom, dok Matrixyl Synthe’6 dodatno pospešuje obnovu dermalne strukture. Argireline, poznat kao prirodna alternativa botoksu, opušta mimične mišiće i sprečava formiranje novih linija. Niacinamid u formulaciji ujednačava ten, posvetljuje i jača barijernu funkciju, dok hijaluronska kiselina intenzivno hidrira i zadržava vlagu u dubokim slojevima kože. Krema se lako razmazuje, brzo upija i ne ostavlja mastan trag, što je čini idealnom za dnevnu i noćnu negu. Redovnom upotrebom, koža postaje elastičnija, glatkija i vidljivo podmlađena. Aktivni sastojci Matrixyl 3000 Kompleks peptida (palmitoyl oligopeptide i palmitoyl tetrapeptide-7) koji stimulišu proizvodnju kolagena i elastina. Pomaže u regeneraciji kože i značajno smanjuje vidljivost bora i linija. Klinički dokazan sastojak za poboljšanje čvrstoće i elastičnosti kože. Argireline (Acetyl Hexapeptide-8) Peptid koji deluje na opuštanje mimičnih mišića lica, čime smanjuje izraženost bora, posebno u zoni čela i oko očiju. Poznat kao prirodna alternativa botoksu, bez invazivnih procedura. Niacinamid (Vitamin B3) Multifunkcionalni vitamin koji poboljšava tonus kože, smanjuje hiperpigmentacije, jača barijernu funkciju i umanjuje crvenilo. Ima i blago antiinflamatorno dejstvo. Hijaluronska kiselina Molekul koji zadržava vlagu i do 1000 puta veću od svoje težine. Hidrirana koža izgleda punije, zdravije i elastičnije. Idealna za sve tipove kože, naročito dehidriranu i zrelu. Matrixyl Synthe’6 Napredni peptid koji stimuliše sintezu šest ključnih komponenti kože: kolagena I, III i IV, fibronectina, hijaluronske kiseline i laminina-5. Deluje dubinski protiv bora i poboljšava strukturu dermisa. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA PC M.A Peptide Cream je intenzivna anti-age krema formulisana sa Matrixyl 3000, Argireline-om, niacinamidom i hijaluronskom kiselinom za vidljivo smanjenje bora i poboljšanje elastičnosti kože. Ova hranljiva formula stimuliše proizvodnju kolagena, umiruje, hidrira i jača kožnu barijeru bez iritacija – pogodna i za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Cos-De-BAHA-PC-M.A-Peptide-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
