INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (901, 31, 'Celimax The Real Noni Energy Repair Cream', 'celimax-the-real-noni-energy-repair-cream', 'Ključne prednosti: Regeneracija i umirenje kože – Ekstrakt nonija u visokoj koncentraciji pomaže obnavljanje i osvežavanje oštećene, dehidrirane kože. Anti-age i hidratacij a – Ceramidi jačaju barijeru, dok adenozin deluje protiv bora i poboljšava elastičnost. Brza apsorpcija i prirodni miris – Lagana tekstura se brzo upija i ostavlja kožu glatkom, sa blagim, umirujućim mirisom ruzmarina. Kome je namenjena? Ova krema je idealna za suvu, osetljivu i oštećenu kožu kojoj je potrebna svakodnevna nega i obnavljanje. Posebno pogodna za korisnike koji žele da kombinuju anti-age dejstvo sa hidratacijom i zaštitom barijere kože. Zašto volimo Celimax The Real Noni Energy Repair Cream? The Real Noni Energy Repair Cream koristi snagu fermentisanog ploda i ulja nonija kako bi obnovila kožu iznutra, smanjila upalne procese i poboljšala otpornost kože na spoljne faktore. Ekstrakt nonija (55%) bogat je vitaminima, antioksidansima i esencijalnim aminokiselinama koje revitalizuju umoran i beživotan ten. Ulje semena nonija (1%) prodire u dublje slojeve kože, hrani je i daje elastičnost. Ceramidi ojačavaju zaštitnu funkciju kože i zadržavaju vlagu, dok adenozin pruža ciljanu anti-age negu i smanjuje pojavu finih linija. Iako bogata hranljivim sastojcima, krema ima izuzetno laganu, nemasnu teksturu, pa se brzo upija i ne ostavlja težinu na koži. Blagi, prirodni miris ruzmarina doprinosi opuštajućem osećaju tokom nanošenja. Aktivni sastojci Ekstrakt nonija (Morinda Citrifolia Fruit Extract) – 55% Supervoće bogato vitaminima C, A i B3, esencijalnim aminokiselinama i antioksidansima. Deluje regenerativno, umirujuće i revitalizujuće. Pomaže u smanjenju crvenila, jača kožnu barijeru i osvežava ten. Posebno je efikasan kod osetljive i umorne kože. Ulje semena nonija (Noni Seed Oil) – 1% Dubinski hrani i omekšava kožu zahvaljujući visokom sadržaju masnih kiselina. Pomaže u obnavljanju lipidnog sloja kože, čineći je elastičnijom i otpornijom. U sinergiji sa ekstraktom nonija doprinosi potpunoj regeneraciji. Ceramidi Ključni sastojci za očuvanje zdrave i funkcionalne kožne barijere. Sprečavaju gubitak vlage, umiruju osetljivu kožu i poboljšavaju teksturu. Neophodni u nezi dehidrirane ili oslabljene kože. Adenozin Sastojak sa dokazanim anti-age delovanjem – pomaže u smanjenju vidljivosti finih linija i bora. Ubrzava regeneraciju ćelija i poboljšava čvrstoću kože. Posebno koristan za zrelu kožu i one koji žele prevenciju znakova starenja. Dodaj u listu želja Dodaj u listu želja', 'Celimax The Real Noni Energy Repair Cream je regenerativna krema za lice obogaćena sa 55% ekstrakta nonija i 1% ulja semena nonija, formulisana da umiri, hidrira i revitalizuje oštećenu i umornu kožu. Zahvaljujući dodatku ceramida i adenozina, pruža bogatu hidrataciju i vidljivu anti-age negu, uz laganu teksturu i prijatan miris ruzmarina.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Celimax-The-Real-Noni-Energy-Repair-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
