INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (902, 31, 'Celimax Dual Barrier Watery Sun Cream SPF 50+', 'celimax-dual-barrier-watery-sun-cream-spf-50', 'Ključne prednosti: 100% mineralna UV zaštita bez iritacija – Non-nano cink oksid pruža širokospektralnu zaštitu od UVA i UVB zraka, pogodnu za najosetljiviju kožu. Intenzivna i dugotrajna hidratacija – 5 ceramida u sinergiji sa Aquatide™ jačaju barijeru kože i sprečavaju gubitak vlage. Bez bele &#8220;maske&#8221; i težine – Iako je fizički SPF, lagana tekstura se lako razmazuje i ostavlja prirodan, blistav finiš bez tragova. Kome je namenjena? Ova krema je idealna za osobe sa suvom, osetljivom i reaktivnom kožom, uključujući i one koji ne podnose hemijske filtere. Pogodna je za svakodnevnu upotrebu, čak i kod kože sklone crvenilu, perutanju i osetljivosti na sunce. Zašto volimo Celimax Dual Barrier Watery Sun Cream SPF 50+? Dual Barrier Watery Sun Cream je pažljivo formulisana 100% mineralna SPF krema koja koristi non-nano cink oksid – bezbedan filter koji ne prodire u kožu i ne izaziva iritacije. Za razliku od većine fizičkih SPF-ova, ova formula je izuzetno lagana, brzo se upija i ne ostavlja beli trag, što je čini idealnom i kao podlogom za šminku. Zahvaljujući patentiranom sastojku Aquatide™, koji stimuliše regeneraciju ćelija i hidrira dubinske slojeve, koža ostaje osvežena i zaštićena tokom celog dana. Dodatno, kompleks 5 ceramida pomaže u obnavljanju i očuvanju kožne barijere, smanjujući transepidermalni gubitak vode. Rezultat je koža koja je ne samo zaštićena od sunca, već i nahranjena, umirena i blistava. Aktivni sastojci Non-nano cink oksid (Zinc Oxide) Mineralni UV filter koji reflektuje UVA i UVB zrake sa površine kože. Non-nano čestice su prevelike da bi prodrle u kožu, pa su bezbedne čak i za osetljivu kožu i trudnice. Ne izaziva iritacije, crvenilo niti začepljuje pore. Pruža trenutnu zaštitu odmah po nanošenju. 5 prirodnih ceramida Ceramidi su lipidi koji obnavljaju i jačaju prirodnu zaštitnu barijeru kože. U kombinaciji deluju protiv isušivanja, štiteći kožu od spoljašnjih agresora. Posebno su važni kod suve, oslabljene ili osetljive kože. Pomažu da koža ostane hidrirana i elastična. Aquatide™ Patentirani bioaktivni peptid koji deluje antioksidativno, regenerativno i hidratantno. Stimuliše prirodne mehanizme obnavljanja ćelija, poboljšava teksturu kože i povećava zadržavanje vlage. Ujedno ima i blago anti-age dejstvo. Dodaj u listu želja Dodaj u listu želja', 'Celimax Dual Barrier Watery Sun Cream je mineralna (fizička) zaštitna krema sa non-nano cink oksidom, namenjena suvoj i osetljivoj koži. Pruža visoku SPF 50+ PA++++ zaštitu od UV zračenja, bez iritacija, bele maske ili osećaja težine, dok istovremeno hidrira i jača kožnu barijeru zahvaljujući kompleksu 5 prirodnih ceramida i patentiranom sastojku Aquatide™.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Celimax-Dual-Barrier-Watery-Sun-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
