INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (904, 25, 'Benton Honest Lip Balm', 'benton-honest-lip-balm', 'Ključne prednosti: Intenzivna hidratacija i zaštita – Zahvaljujući prirodnim biljnim uljima , balzam štiti usne od isušivanja i pomaže u obnovi oštećene barijere. Hipoalergenska formula bez iritacija – 100% ispitanika je osetilo vlagu bez neprijatnosti, zahvaljujući blagim, koži srodnim sastojcima. Higijensko pakovanje u tubi – Sprečava kontaminaciju proizvoda, omogućava preciznu i čistu primenu. Kome je namenjen? Idealan za osobe sa suvim, ispucalim ili osetljivim usnama koje traže prirodan, nemasan balzam bez sintetičkih mirisa, boja, vazelina ili mineralnih ulja. Pogodan je i za decu i one sa reaktivnom kožom. Zašto volimo Benton Honest Lip Balm? Honest Lip Balm je razvijen kao zdravija alternativa standardnim balzamima za usne koji sadrže vazelin ili parafine. Njegova formula koristi 99% prirodnih sastojaka, među kojima je 7 biljnih ulja poznatih po svojoj kompatibilnosti sa kožom: ulje suncokreta, argana, kamelije, zelenog čaja, masline, makadamije i jojobe. Ova ulja deluju sinergijski – dubinski hidriraju, omekšavaju i pomažu u regeneraciji ispucalih usana. Pored toga, lagana, nelepljiva tekstura pruža prijatan osećaj na usnama, bez zagušivanja kože. U kliničkom ispitivanju, 100% korisnika je izjavilo da su osetili vlagu bez iritacija, a 91% da je došlo do smanjenja mrtvih ćelija. Dizajn tube omogućava higijensko i jednostavno nanošenje, što dodatno čini ovaj balzam praktičnim za svakodnevnu upotrebu. Aktivni sastojci Ulje suncokreta (Helianthus Annuus Seed Oil) Bogato vitaminom E i esencijalnim masnim kiselinama, ovo ulje štiti kožu od isušivanja i pomaže u regeneraciji barijere. Ima laganu teksturu koja se brzo upija i ne ostavlja mastan trag. Umiruje osetljivu kožu i pruža antioksidativnu zaštitu. Arganovo ulje (Argania Spinosa Kernel Oil) Poznato kao &#8220;tečno zlato&#8221;, bogato je omega masnim kiselinama i antioksidansima. Regeneriše ispucalu i suvu kožu usana, vraćajući joj elastičnost i mekoću. Doprinosi glatkom, zdravom izgledu usana. Ulje semena kamelije (Camellia Japonica Seed Oil) Ima visok sadržaj oleinske kiseline i odlična je za dubinsku hidrataciju. Deluje umirujuće i antiinflamatorno, što ga čini pogodnim za osetljive usne. Takođe pospešuje elastičnost kože. Ulje zelenog čaja (Camellia Sinensis Seed Oil) Prirodni izvor antioksidansa, štiti usne od štetnih spoljnih uticaja. Pomaže u smanjenju upala i iritacija. Idealno za regeneraciju oštećenih i suvlje kože. Maslinovo ulje (Olea Europaea Fruit Oil) Dubinski hrani kožu usana, štiti od pucanja i pruža dugotrajnu mekoću. Sadrži vitamine A i E koji pomažu u obnovi tkiva i sprečavaju isušivanje. Ulje makadamije (Macadamia Integrifolia Seed Oil) Hranljivo ulje koje sadrži palmitoleinsku kiselinu – važnu za obnovu i zaštitu ćelija kože. Daje baršunasti osećaj na usnama. Jojobino ulje (Simmondsia Chinensis Seed Oil) Najpribližnije ljudskom sebumu, dubinski hidrira bez zatvaranja pora. Umiruje i obnavlja usne, ostavljajući ih mekim i elastičnim. Dodaj u listu želja Dodaj u listu želja', 'Benton Honest Lip Balm je prirodni balzam za usne u tubi, formulisan sa 99% biljnih sastojaka i bez mineralnih ulja, namenjen za intenzivnu hidrataciju, zaštitu i regeneraciju ispucalih usana. Sadrži kombinaciju sedam biljnih ulja koja hrane, omekšavaju i obnavljaju osetljivu kožu usana bez iritacija.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Benton-Honest-Lip-Balm-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
