INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (905, 22, 'Beauty Of Joseon Apricot Blossom Peeling Gel', 'beauty-of-joseon-apricot-blossom-peeling-gel', 'Ključne prednosti: Blaga eksfolijacija bez oštećenja kože – Kombinacija prirodne celuloze i biljnih enzima uklanja mrtve ćelije bez trenja i crvenila. Pročišćava pore i osvežava ten – Ekstrakt kajsije i jabuke deluju sinergijski u uklanjanju nečistoća, viška sebuma i sivog tona. Hidratacija i umirenje – Skvalan i pantenol doprinose zadržavanju vlage i štite kožu od isušivanja. Kome je namenjen? Proizvod je idealan za sve tipove kože, uključujući osetljivu, suvu i dehidriranu kožu koja loše reaguje na mehaničke ili kiseline-bazirane pilinge. Preporučuje se onima koji žele glatku i osveženu kožu bez crvenila i iritacija. Zašto volimo Beauty Of Joseon Apricot Blossom Peeling Gel? Apricot Blossom Peeling Gel je inspirisan tradicionalnom korejskom hanbang kozmetikom i koristi blagu, ali efikasnu tehnologiju za uklanjanje mrtvih ćelija sa površine kože. U kontaktu sa kožom, gel formira mekane grudvice prirodne celuloze koje na nežan način “rolaju” nečistoće i površinske naslage. Ekstrakt cveta kajsije bogat je vitaminima i antioksidansima koji osvežavaju i ujednačavaju ten, dok dodatni voćni ekstrakti poboljšavaju teksturu i čistoću pora. Skvalan i pantenol pružaju osećaj mekoće i dodatne nege, sprečavajući isušivanje koje često dolazi s piling tretmanima. Redovnom upotrebom, koža postaje blistava, glatka i vidljivo zdravija, spremna da bolje upije aktivne sastojke iz narednih koraka nege. Aktivni sastojci Ekstrakt kajsije (Prunus Mume Fruit Extract) Ovaj fermentisani ekstrakt bogat je prirodnim voćnim kiselinama, vitaminima i antioksidansima. Pomaže u otapanju mrtvih ćelija i nežno posvetljuje kožu. Njegova antioksidativna svojstva štite kožu od oksidativnog stresa i doprinose ujednačenom tenu. Takođe ima blago protivupalno dejstvo koje umiruje iritiranu kožu. Fermentacija dodatno pojačava njegovu efikasnost i čini ga pogodnim čak i za osetljive tipove kože. Daje prirodan sjaj i osvežava kožu nakon svake upotrebe. Prirodna celuloza Delikatna biljna vlakna koja fizički uklanjaju mrtve ćelije bez oštećenja kože. Ne sadrži abrazivne čestice koje mogu izazvati mikrooštećenja. Pomaže u otčepljivanju pora i zaglađivanju površine kože. Idealna je za osetljive i reaktivne tipove kože koji ne podnose grublje pilinge. U kombinaciji sa hidratantnim sastojcima, pruža piling bez osećaja zatezanja. Omogućava koži da diše i izgleda svežije. Skvalan Prirodni lipid sličan onom koji koža sama proizvodi. Hidratantni agens koji obnavlja lipidnu barijeru i sprečava gubitak vlage. Ne masti kožu i ne izaziva zapušavanje pora, pa je pogodan i za masniju kožu. Deluje umirujuće i pomaže u regeneraciji nakon eksfolijacije. Kožu ostavlja svilenkastom i elastičnom. Pruža zaštitu od iritacija i spoljnih faktora. Pantenol (Provitamin B5) Intenzivno umirujući sastojak koji hidrira i regeneriše kožu. Smanjuje crvenilo i ublažava potencijalne iritacije nakon pilinga. Jača zaštitnu funkciju kože i doprinosi njenoj mekoći. Deluje protivupalno i podržava obnovu ćelija. Ne izaziva osećaj težine i odličan je za osetljivu kožu. Doprinosi glatkoj i zdravoj teksturi lica. Ekstrakt jabuke (Pyrus Malus Fruit Water) Prirodni izvor AHA kiselina, jabuka deluje blago eksfolirajuće i osvetljava ten. Pomaže u uklanjanju mrtvih ćelija i osvežava kožu. Bogata je antioksidansima i vitaminima koji štite od spoljašnjih uticaja. U sinergiji sa kajsijom pruža dodatnu snagu u borbi protiv sivog i umornog izgleda kože. Hidrira i daje osećaj čistoće i svežine. Idealna za nežnu, svakodnevnu eksfolijaciju. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Apricot Blossom Peeling Gel je nežni enzimski piling formulisan sa ekstraktom kajsije i prirodnim celuloznim česticama, osmišljen da ukloni mrtve ćelije kože bez iritacije. Obogaćen antioksidansima i hidratantnim agensima, ostavlja kožu glatkom, pročišćenom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/04/Beauty-Of-Joseon-Apricot-Blossom-Peeling-Gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
