INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (910, 138, 'Pyunkang Yul Balancing Gel', 'pyunkang-yul-balancing-gel', 'Ključne prednosti: Intenzivna hidratacija u samo jednom sloju. Njegova elastična, “honey-like” tekstura stvara zaštitni sloj koji zadržava vlagu tokom celog dana. Umiruje i revitalizuje osetljivu i iscrpljenu kožu. Astragalus root extract bogat antioksidansima pomaže u jačanju otpornosti i pruža prirodnu energiju koži. Balansira odnos ulja i vlage. Ulje semena jojobe hidrira i štiti bez zapušavanja pora, čineći ga pogodnim za sve tipove kože. Kome je namenjen? Balancing Gel je idealan za osobe sa suvom, dehidriranom ili umornom kožom kojoj je potrebna dubinska obnova i zaštita. Zahvaljujući blagoj formuli bez parfema i boja, pogodan je i za osetljivu i reaktivnu kožu, uključujući onu sklonu crvenilu i iritacijama. Zašto volimo Pyunkang Yul Balancing Gel? Balancing Gel pruža jedinstveno senzorno iskustvo: njegova gusta, lepljiva tekstura se prilikom nanošenja vraća u prvobitni oblik, što omogućava optimalno prijanjanje uz kožu i bolju apsorpciju. Formulisan sa 90% ekstrakta Astragalusa , biljke poznate po svojim antioksidativnim i umirujućim svojstvima, ovaj gel obnavlja tonus, elastičnost i blistavost kože. Kombinovanjem sa jojobinim uljem , gel deluje i kao emolijens, zaključavajući vlagu bez osećaja težine. S obzirom na svoju sposobnost da formira zaštitni film, odličan je kao završni korak u večernjoj nezi. Koža već nakon prvih korišćenja izgleda odmorno, elastično i blistavo. Aktivni sastojci Astragalus Root Extract Ekstrakt korena Astragalusa koristi se umesto vode kao glavni sastojak ove formule. Bogat je izoflavonoidima, polisaharidima i calicosinom, koji deluju antioksidativno i protivupalno. Pomaže u regeneraciji kože, štiti od oksidativnog stresa i stimuliše prirodne obrambene mehanizme kože. Ovaj sastojak je naročito efikasan kod suve i oslabljene kože jer poboljšava hidrataciju iznutra i pruža osećaj svežine. Njegovo prisustvo u ovoj minimalističkoj formuli dodatno naglašava sigurnost i efikasnost. Ključan je za elastičnost, zdrav sjaj i otpornost kože. Jojobino ulje (Jojoba Seed Oil) Jojobino ulje je biljni emolijens koji po sastavu najviše podseća na ljudski sebum. Hidratantno je, ali nekomedogeno – idealno za kožu sklonu zapušavanju pora. Stvara zaštitni film koji sprečava isparavanje vlage bez začepljenja, čineći ga odličnim za sve tipove kože. Sadrži prirodne antioksidanse i vitamine E i B-kompleksa koji pomažu u smanjenju iritacija i crvenila. Njegovo prisustvo doprinosi ujednačenom tenu i dugotrajnoj mekoći kože. U ovoj formuli igra ključnu ulogu u balansiranju ulja i vlage. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Balancing Gel je visoko koncentrisani hidratantni gel koji koristi ekstrakt korena Astragalusa umesto vode kako bi pružio dubinsku ishranu i revitalizaciju suvoj i umornoj koži. Sa samo sedam pažljivo odabranih sastojaka, ovaj proizvod umiruje, štiti i obnavlja kožnu barijeru bez rizika od iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Pyunkang-Yul-Balancing-Gel-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
