INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (911, 138, 'Pyunkang Yul Moisture Ampoule', 'pyunkang-yul-moisture-ampoule', 'Ključne prednosti: Dubinski hidrira bez zatezanja ili masnog sjaja. Lagana tekstura brzo se upija i ostavlja kožu elastičnom, mekom i blistavom. Minimalna, sigurna formula pogodna za osetljivu kožu. Samo 6 esencijalnih sastojaka, bez parfema, boja i potencijalno iritirajućih supstanci. Umiruje i hladi kožu sklona crvenilu i iritacijama. Coptis root extract bogat antioksidansima i antiinflamatornim jedinjenjima smanjuje stres kože i pomaže u očuvanju njene prirodne otpornosti. Kome je namenjena? Idealna je za sve tipove kože, posebno za suvu, dehidriranu i osetljivu kožu koja traži jednostavnu, ali efikasnu negu. Zahvaljujući blagoj formuli, može se koristiti i kao dodatni hidratantni sloj u rutini za masnu i kombinovanu kožu. Zašto volimo Pyunkang Yul Moisture Ampoule? Moisture Ampoule oslanja se na jednostavnost i funkcionalnost – njen glavni sastojak, ekstrakt korena Coptis Japonica , deluje kao prirodni antioksidans i umirujući agens, smanjujući osećaj toplote i iritacije. Zahvaljujući gustoj, ali neljepljivoj teksturi, ampula stvara tanki zaštitni sloj koji zadržava vlagu duboko u koži. Redovnom upotrebom, koža postaje vidno hidriranija, elastičnija i otpornija na spoljne faktore. Posebno pogodna za korišćenje u večernjoj rutini, kada pruža osećaj umirene i nahranjene kože do jutra. Njena formulacija bez mirisa, etanola i silikona čini je sigurnom i za najosetljivije korisnike. Aktivni sastojci Coptis Japonica Root Extract Ekstrakt korena Coptis Japonica sadrži visoku koncentraciju aktivnih komponenti poput berberina, palmatina i coptisina, koji imaju snažno protivupalno, antibakterijsko i antioksidativno dejstvo. Pomaže u smirivanju kože koja je sklona crvenilu, iritacijama i preosetljivosti. Deluje na smanjenje osećaja zagrejanosti kože i štiti od oksidativnog stresa izazvanog UV zračenjem i zagađenjem. Ovaj ekstrakt hidrira kožu iznutra, ostavljajući je svežom i uravnoteženom. Koristi se umesto vode u formuli, što pojačava njegovu efikasnost i čini ga ključnim sastojkom za revitalizaciju kože. Dugotrajnom upotrebom poboljšava tonus, elastičnost i otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Moisture Ampoule je minimalistički formulisana hidratantna ampula sa svega šest pažljivo odabranih sastojaka, među kojima se ističe ekstrakt korena Coptis Japonica . Namenjena je dubinskoj hidrataciji, umirivanju i jačanju kožne barijere bez osećaja težine ili masnoće.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Pyunkang-Yul-Moisture-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
