INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (917, 109, 'Manyo Galactomy Essence Mist', 'manyo-galactomy-essence-mist', 'Ključne prednosti: Trenutno osvežava i hidrira kožu. Ultra-fini mist momentalno vraća vlagu i vitalnost licu, ostavljajući kožu osveženom i elastičnijom bez narušavanja šminke. Posvetljuje i ujednačava ten. Niacinamid i Galactomyces ferment filtrat sinergijski deluju na smanjenje tamnih fleka i sivila, vraćajući koži prirodan sjaj. Smanjuje fine linije i poboljšava tonus. Adenozin doprinosi elastičnosti i glatkosti kože, vidljivo smanjujući pojavu finih bora kod redovne upotrebe. Kome je namenjen? Ovaj proizvod je namenjen osobama sa dehidriranom, umornom ili neujednačenom kožom, kao i onima koji traže praktičan način da osveže lice tokom dana. Pogodan je za sve tipove kože, uključujući osetljivu i kožu pod stresom od spoljašnjih faktora poput zagađenja ili klimatskih promena. Zašto volimo Manyo Galactomy Essence Mist? Galactomy Essence Mist funkcioniše kao esencija u spreju – efikasna kao serum, a lagana kao voda. Svaki pritisak raspršivača donosi ne samo trenutno osveženje, već i koncentrisanu negu u obliku fermentisanih sastojaka i vitamina. Formulisan sa visokom koncentracijom Galactomyces filtrata , ovaj proizvod obnavlja kožnu barijeru, ujednačava ton i pomaže koži da zadrži vlagu tokom celog dana. Zahvaljujući niacinamidu , ten postaje svetliji, dok adenozin poboljšava elastičnost i čvrstinu. Idealno je rešenje za kožu koja je stalno izložena stresu – u kancelariji, tokom putovanja ili u uslovima suvog vazduha. Dugoročnom upotrebom, koža postaje zdravija, otpornija i vidno blistavija. Aktivni sastojci Galactomyces Ferment Filtrate Galactomyces ferment filtrat je fermentisani sastojak bogat nutrijentima koji obnavlja i balansira mikrobiom kože. Pomaže u regulaciji sebuma, posvetljava kožu i čini je ujednačenijom i mekšom. Njegova sposobnost da poboljša teksturu kože bez iritacije čini ga pogodnim i za najosetljivije tipove kože. Fermentacija omogućava bolju apsorpciju aktivnih komponenti i doprinosi oporavku kože nakon izlaganja stresu. Niacinamid Niacinamid, odnosno vitamin B3, poznat je po svom efektu u ujednačavanju tena i smanjenju tamnih fleka. On jača barijeru kože, poboljšava teksturu i smanjuje upalne procese. U formulama poput ove, niacinamid se koristi i za sužavanje pora i kontrolu sebuma, čineći kožu čistijom i glatkijom. Pomaže u osvetljavanju tena bez izbeljivanja i iritacije. U sinergiji sa fermentisanim sastojcima, dodatno se pojačava njegova efikasnost. Adenozin Adenozin je sastojak koji stimuliše ćelijsku aktivnost, pomaže u obnovi kolagena i smanjuje vidljivost finih linija. Njegovo dejstvo na elastičnost čini ga odličnim za prevenciju prvih znakova starenja. Pored toga, ima umirujući efekat i podržava kožu u borbi protiv umora i gubitka tonusa. U mistu, adenozin funkcioniše kao dodatna nega koja koži vraća punoću i glatkoću. Njegova blaga, ali efektna priroda pogodna je za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Manyo Galactomy Essence Mist je višenamenski mist za lice koja kombinuje Galactomyces ferment filtrat , niacinamid i adenozin za osvežavanje, posvetljavanje i poboljšanje teksture kože. Ovaj lagani sprej pruža trenutnu hidrataciju i dugoročne benefite u borbi protiv neujednačenog tena i znakova umora.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Manyo-Galactomy-Essence-Mist-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
