INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (923, 14, 'Arencia Fresh Red Smoothie Serum 30', 'arencia-fresh-red-smoothie-serum-30', 'Ključne prednosti: Povećava čvrstinu i elastičnost kože . Zahvaljujući kolagenu i peptidima, serum pomaže u jačanju strukture kože, poboljšava tonus i smanjuje vidljivost finih linija. Umiruje i obnavlja umornu kožu. Ekstrakt ginseng bobice i roselle (hibiskus) ekstrakt deluju protiv stresa i upala, vraćajući koži svežinu i prirodan balans. Ujednačava ten i posvetljuje kožu. Niacinamid i ekstrakt šipka posvetljuju tamne fleke, poboljšavaju teksturu i vraćaju koži prirodan sjaj. Kome je namenjen? Ovaj serum je idealan za osobe koje žele da poboljšaju čvrstinu, teksturu i ujednačenost kože, naročito ako se bore sa prvim znakovima starenja. Pogodan je za sve tipove kože, uključujući osetljivu, zbog umirujućih i hranljivih biljnih ekstrakata. Zašto volimo Arencia Fresh Red Smoothie Serum 30? Fresh Red Smoothie Serum 30 deluje kao intenzivna nega za kožu kojoj je potrebna čvrstina, osveženje i podmlađen izgled. Njegova želeasta tekstura se brzo upija i stvara osećaj prijatne punoće, dok bogat kompleks aktivnih sastojaka deluje dubinski. Kolagen i peptidi jačaju kožnu strukturu, vraćajući čvrstinu i elastičnost, dok niacinamid ujednačava ten i ublažava diskoloracije. Roselle i ginseng bobica umiruju kožu pod stresom, dok šipak i tokoferol (vitamin E) pružaju dodatnu antioksidativnu zaštitu. Dugotrajnom upotrebom, koža postaje glatkija, svetlija i vidno odmornija. Ovaj serum je savršen izbor za one koji žele sveobuhvatnu, biljno baziranu anti-age negu bez osećaja težine. Aktivni sastojci Kolagen Kolagen je ključni protein za očuvanje čvrstoće i elastičnosti kože. Njegova uloga u ovom serumu jeste da ojača strukturu kože i smanji vidljivost finih linija, čineći kožu zategnutijom i glatkom. Kolagen takođe poboljšava hidrataciju i zadržavanje vlage, što doprinosi punijem i zdravijem izgledu kože. Kao deo anti-age formule, pomaže u obnovi tonusa i vraćanju mladalačkog sjaja. Peptidi Peptidi su kratki lanci aminokiselina koji podstiču proizvodnju kolagena i elastina u koži. Deluju kao „glasnici“ koji signaliziraju ćelijama da se obnavljaju i regenerišu. U ovom serumu, peptidi doprinose smanjenju bora, poboljšanju tonusa i ukupnoj čvrstoći kože. Njihovo dejstvo je blago, ali efikasno, što ih čini pogodnim za svakodnevnu upotrebu. Peptidi takođe imaju sposobnost da poboljšaju barijernu funkciju kože, štiteći je od spoljašnjih štetnih uticaja. Niacinamid Niacinamid, poznat i kao vitamin B3, ima višestruko dejstvo: ujednačava ten, smanjuje tamne fleke, poboljšava teksturu kože i jača barijernu funkciju. Pomaže i u regulaciji lučenja sebuma, što ga čini pogodnim i za masniju ili kombinovanu kožu. Njegovo dejstvo na posvetljivanje kože je klinički potvrđeno, a uz to umanjuje crvenilo i iritacije. Deluje antioksidativno i podstiče obnovu kože, što ga čini ključnim sastojkom u borbi protiv starenja. Ekstrakt roselle Roselle, poznata i kao hibiskus, bogata je AHA kiselinama koje prirodno pospešuju blagi piling kože. Doprinosi glatkijoj teksturi, smanjuje pojavu finih linija i pomaže u obnavljanju ćelija. Takođe ima antiinflamatorna svojstva i štiti kožu od oksidativnog stresa. Bogata antioksidansima, roselle pomaže u održavanju elastičnosti kože i poboljšava cirkulaciju. Zbog svog nežnog, ali efektivnog delovanja, idealna je za osetljivu i umornu kožu. Ginseng bobica Ginseng bobica je poznata po svojoj sposobnosti da revitalizuje i podstakne mikrocirkulaciju kože. Sadrži snažne antioksidanse koji štite od slobodnih radikala i štetnih uticaja iz spoljašnje sredine. Njeno dejstvo pomaže u borbi protiv znaka umora, poboljšava tonus i doprinosi blistavijem izgledu kože. Posebno je efikasna kod kože kojoj nedostaje sjaj ili koja je podložna stresu. Ginseng deluje i kao prirodni umirivač, smanjujući crvenilo i iritacije. Dodaj u listu želja Dodaj u listu želja', 'Arencia Fresh Red Smoothie Serum 30 je serum protiv starenja koji kombinuje kolagen, peptide, niacinamid i biljne ekstrakte kako bi obnovio čvrstinu kože i poboljšao njen tonus. Njegova osvežavajuća, želeasta formula revitalizuje kožu, smanjuje znake umora i pruža blistav, podmlađen izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Arencia-Fresh-Red-Smoothie-Serum-30-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
