INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (924, 123, 'Neogen Bio-Peel Gauze Peeling Wine', 'neogen-bio-peel-gauze-peeling-wine', 'Ključne prednosti: Dvostruka eksfolijacija bez iritacije: Kombinacija fizičke (mrežasta tekstura gaze) i hemijske (AHA kiseline) eksfolijacije omogućava temeljno čišćenje kože bez oštećenja zaštitne barijere, što rezultira glatkom i prozračnom kožom. Anti-age delovanje zahvaljujući resveratrolu: Ekstrakt fermentisanog crnog vina bogat resveratrolom deluje kao snažan antioksidans, usporava starenje kože i pomaže u očuvanju njene elastičnosti i čvrstine. Vidljivo ujednačenija i osvetljenija koža: Redovnim korišćenjem, ten postaje ujednačeniji, beživotni izgled nestaje, a koža poprima zdrav sjaj i mekoću. Kome je namenjen? Proizvod je idealan za osobe sa umornom, beživotnom i grubom kožom, kao i one koje se bore sa začepljenim porama i neujednačenim tenom. Preporučuje se za sve tipove kože osim izrazito osetljive, zbog kombinacije fizičke i hemijske eksfolijacije. Zašto volimo NEOGEN Bio-Peel Gauze Peeling Wine? Kao da ste se vratili s tretmana kod kozmetičara – tako koža izgleda posle korišćenja Bio-Peel Wine gaze. Inovativna tehnologija trostrukog sloja omogućava istovremeno uklanjanje nečistoća i negu kože bogatu antioksidansima. Osetićete razliku već nakon prve upotrebe – koža će biti glatkija, pore vidljivo čistije, a ten svežiji. Zahvaljujući prisustvu resveratrola , ovaj piling ne samo da čisti, već i obnavlja kožu, podstičući njenu otpornost na spoljne uticaje. Dugoročno, koža postaje vidno osvežena, gipkija i manje sklona upalnim procesima. Za razliku od agresivnijih pilinga, ovaj tretman je osmišljen tako da pruža rezultate bez oštećenja ili iritacije. Koža je hidrirana, umirena i spremna da upije sve benefite daljih koraka u nezi. Aktivni sastojci Resveratrol Resveratrol je moćan antioksidans dobijen iz fermentisanog crnog vina, poznat po svojoj sposobnosti da neutrališe slobodne radikale i spreči prevremeno starenje kože. Deluje umirujuće na kožu, pomaže u očuvanju kolagena i elastina i doprinosi čvršćem izgledu kože. Zahvaljujući svom antiinflamatornom dejstvu, ublažava crvenilo i štiti kožu od oksidativnog stresa izazvanog UV zračenjem i zagađenjem. Njegova anti-age svojstva čine ga ključnim sastojkom u nezi zrele kože. Takođe pomaže u posvetljavanju tena i smanjenju pojave fleka i diskoloracija. U kombinaciji s piling efektom gaze, omogućava koži da zablista i obnovi se iznutra. Mlečna kiselina (Lactic Acid) Mlečna kiselina je blaga AHA kiselina koja nežno uklanja mrtve ćelije s površine kože, poboljšava teksturu i podstiče prirodnu regeneraciju. Pored eksfolijacije, ona deluje i kao humektant – zadržava vlagu u koži, sprečavajući isušivanje nakon pilinga. Pomaže u smanjenju vidljivosti hiperpigmentacija i ujednačava ten. Zahvaljujući svom delovanju na površinski sloj kože, omogućava bolje upijanje aktivnih sastojaka iz narednih koraka u rutini. Posebno je korisna kod grube, zadebljale i umorne kože. Njeno dejstvo je dovoljno efikasno, a istovremeno dovoljno blago da se koristi dva do tri puta nedeljno bez iritacija. Dodaj u listu želja Dodaj u listu želja', 'NEOGEN Bio-Peel Gauze Peeling Wine su dvostrane gaze za piling koje kombinuju mehaničku i hemijsku eksfolijaciju uz pomoć resveratrola iz fermentisanog crnog vina. Ovaj proizvod efikasno uklanja mrtve ćelije kože, čisti pore i vidno poboljšava teksturu kože, ostavljajući je mekšom, osvetljenijom i elastičnijom.', 'https://beauty-health.rs/wp-content/uploads/2025/03/NEOGEN-Bio-Peel-Gauze-Peeling-Wine.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
