INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (926, 39, 'Cos De BAHA AZ20 Cream', 'cos-de-baha-az20-cream', 'aKljučne prednosti: Smanjuje upale i akne: Azelainska kiselina deluje antibakterijski i keratolitički, sprečavajući stvaranje zapušenih pora i smanjujući crvenilo. Ujednačava ten i posvetljuje fleke: Deluje na pigmentaciju inhibicijom enzima tirozinaze, uz pomoć CICA ekstrakta i pantenola. Dubinski hidrira i regeneriše: Kombinacija hijaluronske kiseline i MSM-a obnavlja kožnu barijeru i pruža elastičnost i mekoću. Kome je namenjena? Ova krema je idealna za osobe sa masnom, kombinovanom i problematičnom kožom sklonom aknama, rozacei, upalama ili postinflamatornoj hiperpigmentaciji. Zahvaljujući balansiranoj formulaciji, pogodna je i za osetljivu kožu kojoj je potrebna istovremena nega i obnova. Zašto volimo Cos De BAHA AZ20 Cream? Redovnom upotrebom AZ20 kreme vidljivo se smanjuju akne, crvenilo i hiperpigmentacije. Njena visoka koncentracija azelainske kiseline deluje protivupalno, antibakterijski i eksfolijativno, dok hijaluronska kiselina obezbeđuje snažnu hidrataciju bez osećaja težine. MSM doprinosi jačanju strukture kože i poboljšava apsorpciju aktivnih supstanci, a pantenol deluje umirujuće i regenerišuće. Ekstrakt Centella Asiatica dodatno ublažava iritacije, podstiče sintezu kolagena i pomaže koži da povrati ujednačen izgled i zdrav sjaj. Tekstura kreme je lagana, brzo se upija i ne ostavlja mastan trag. Aktivni sastojci Azelainska kiselina (20%) Efikasno smanjuje bakterije koje izazivaju akne, ublažava upale i deluje kao blagi hemijski eksfolijant. Inhibira enzime odgovorne za sintezu melanina, čime posvetljuje fleke i ujednačava ten. Pogodna je za tretiranje rozacee, jer deluje protiv crvenila i peckanja. Ne izaziva iritacije kao jači kiseli agensi i pogodna je za osetljivu kožu. Korisna je i kod problema kao što su keratoza pilaris i postinflamatorna hiperpigmentacija. Hijaluronska kiselina Privlači i zadržava vlagu u koži, čime poboljšava hidriranost i čini ten punijim i zdravijim. Ublažava vidljivost finih linija i doprinosi elastičnosti kože. Pomaže u transportu ostalih aktivnih sastojaka u dublje slojeve kože. Ne izaziva iritacije i ne zapušava pore, pogodna je za sve tipove kože. Ujednačava teksturu kože i daje joj osvežen izgled. MSM (Metilsulfonilmetan) Organski izvor sumpora koji poboljšava prodiranje aktivnih sastojaka i stimuliše sintezu kolagena i keratina. Smanjuje upalne procese u koži, ublažava akne i pomaže u zarastanju oštećenja. Jača strukturu kože i povećava otpornost na spoljne iritanse. Efikasno se bori protiv slobodnih radikala i doprinosi usporavanju procesa starenja. Centella Asiatica (CICA) ekstrakt Tradicionalno korišćena biljka za regeneraciju kože i smanjenje upala. Bogata je asiaticosidima i madecassosidima koji stimulišu sintezu kolagena. Pomaže u obnavljanju oštećene barijere kože, posebno kod upala i iritacija. Deluje umirujuće, što je idealno za osobe sa crvenilom, osetljivošću ili nakon hemijskih tretmana. Pruža antioksidativnu zaštitu i jača otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA AZ20 cream sadrži visoku koncentraciju azelainske kiseline (20%) u kombinaciji sa umirujućim i hidratantnim sastojcima poput pantenola, hijaluronske kiseline, MSM-a i ekstrakta CICA biljke. Namenjena je ciljanoj nezi kože sklone aknama, rozacei, hiperpigmentaciji i upalama.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Cos-De-BAHA-AZ20-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
