INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (932, 148, 'Scinic Cicanoid Retinal Cream', 'scinic-cicanoid-retinal-cream', 'Ključne prednosti: Smanjenje znakova starenja: Retinala efikasno smanjuje fine linije i bore, poboljšavajući teksturu kože.​ Povećanje elastičnosti kože: Adenozin i retinal rade zajedno na poboljšanju elastičnosti kože, čineći je čvršćom i zategnutijom.​ Umirujuće dejstvo: Ekstrakt centela azijatike i madeskasozid pružaju umirujuće i regenerativno dejstvo, smanjujući iritacije i crvenilo. Kome je namenjen? Ovaj proizvod je idealan za osobe sa zrelom kožom koja pokazuje znakove starenja, poput finih linija i smanjene elastičnosti. Takođe je pogodan za one sa osetljivom kožom koja zahteva umirujuću i regenerativnu negu. Zašto volimo Scinic Cicanoid Retinal Cream? Cicanoid Retinal Cream pruža sveobuhvatnu anti-age negu zahvaljujući sinergiji aktivnih sastojaka. Redovnom upotrebom, retinal stimuliše obnavljanje ćelija, što dovodi do vidljivog smanjenja bora i finih linija. Adenozin dodatno poboljšava elastičnost kože, čineći je čvršćom i zategnutijom. Ekstrakt centela azijatike i madeskasozid deluju umirujuće, smanjujući iritacije i crvenilo, dok niacinamid posvetljuje ten i ujednačava boju kože. Hijaluronska kiselina pruža dubinsku hidrataciju, ostavljajući kožu mekom i osveženom. Aktivni sastojci Retinal Retinal je napredna forma vitamina A i efikasniji je od klasičnog retinola u stimulaciji obnove ćelija i sintezi kolagena. Pomaže u smanjenju izraženosti bora, poboljšava teksturu kože i podstiče ujednačen ten. Za razliku od retinola, brže deluje, a istovremeno je blaži za osetljivu kožu kada je pravilno formulisan. Redovnom primenom vidljivo se poboljšava elastičnost kože i ublažavaju znaci starenja. Phyto Retinol Phyto Retinol je biljna alternativa retinolu, poznata po blagom ali efikasnom delovanju protiv znakova starenja. Dobija se iz biljnih izvora i pruža koži benefite poput poboljšanja čvrstine, posvetljivanja tena i smanjenja sitnih linija – bez iritacije koju retinoidi ponekad izazivaju. Njegova primena je posebno pogodna za osetljivu i reaktivnu kožu. U kombinaciji sa retinalom, pojačava ukupni efekat obnove i regeneracije. Adenozin Adenozin je sastojak poznat po svojoj sposobnosti da poboljša elastičnost kože i umanji vidljivost bora. Deluje tako što stimuliše sintezu kolagena i elastina, što doprinosi čvršćoj, zategnutijoj i mlađoj koži. Takođe ima umirujuće dejstvo i može pomoći u smanjenju crvenila i iritacija, čineći ga pogodnim i za osetljive tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Scinic Cicanoid Retinal Cream je krema protiv starenja koja kombinuje retinal i adenozin kako bi poboljšala elastičnost kože i smanjila pojavu finih linija i bora. Obogaćena je sastojcima poput ekstrakta centela azijatike i madeskasozida za umirujuće dejstvo, pružajući sveobuhvatnu negu kože.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Scinic-Cicanoid-Retinal-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
