INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (933, 103, 'Lagom Cellus Sun Gel Plus', 'lagom-cellus-sun-gel-plus', 'Ključne prednosti: Visoka zaštita od sunca: Sa SPF50+ PA++++, pruža snažnu zaštitu od štetnih UV zraka, čime se smanjuje rizik od oštećenja kože i prevremenog starenja. ​ Hidratacija i nega: Sadrži Aqualicia® i Aquatide®, koji dubinski hidriraju kožu i poboljšavaju njenu elastičnost, ostavljajući je mekom i glatkom. Svetliji ten: Glutation pomaže u smanjenju pojave tamnih fleka i hiperpigmentacije, doprinoseći ujednačenom i blistavom tenu. Kome je namenjen? Ovaj proizvod je pogodan za sve tipove kože, uključujući osetljivu i masnu kožu. Idealan je za osobe koje traže visoku zaštitu od sunca uz dodatne benefite hidratacije i posvetljivanja tena.​ Zašto volimo Lagom Cellus Sun Gel Plus? Cellus Sun Gel Plus pruža sveobuhvatnu zaštitu od sunca bez osećaja težine ili masnoće na koži. Njegova lagana gel tekstura brzo se upija, ne ostavljajući beli trag, što ga čini idealnim za svakodnevnu upotrebu, čak i ispod šminke. Osim zaštite, ovaj gel obezbeđuje intenzivnu hidrataciju zahvaljujući Aqualicia® tehnologiji, koja pomaže u zadržavanju vlage u koži tokom celog dana. Prisustvo Glutationa doprinosi smanjenju tamnih fleka i ujednačavanju tena, dok Aquatide® pruža antioksidativnu zaštitu, štiteći kožu od slobodnih radikala i znakova starenja. Redovnom upotrebom, koža postaje mekša, hidrirana i zaštićena od štetnih uticaja okoline. Aktivni sastojci Glutation Moćan antioksidans koji pomaže u neutralisanju slobodnih radikala, smanjuje oksidativni stres i posvetljuje kožu, čineći je blistavijom i ujednačenom. ​ Aqualicia® Patentirani sastojak koji poboljšava sposobnost kože da zadrži vlagu, pružajući dubinsku hidrataciju i jačajući barijernu funkciju kože. ​ Aquatide® Peptid sa antioksidativnim svojstvima koji štiti kožu od oštećenja izazvanih slobodnim radikalima i pomaže u regeneraciji ćelija, doprinoseći mladalačkom izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'Lagom Cellus Sun Gel Plus je lagani gel za zaštitu od sunca sa SPF50+ PA++++, koji pruža visoku zaštitu od UVA i UVB zraka. Obogaćen je sastojcima poput Glutationa, Aqualicia® i Aquatide®, koji pomažu u hidrataciji kože, sprečavanju tamnih fleka i pružanju antioksidativnih benefita.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Lagom-Cellus-Sun-Gel-Plus.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
