INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (935, 6, 'Abib Heartleaf Sun Essence Calming Drop', 'abib-heartleaf-sun-essence-calming-drop', 'Ključne prednosti: Visoka UV zaštita: Pruža širok spektar zaštite od štetnih UVA i UVB zraka zahvaljujući SPF 50+ PA++++, čime se smanjuje rizik od oštećenja kože izazvanih sunčevim zračenjem.​ Umirujući efekat: Ekstrakt Houttuynia Cordata deluje protivupalno i antioksidativno. Pomaže u smirivanju iritacija i zaštiti kože od slobodnih radikala.​ Lagana i hidratantna formula: Esencija se brzo upija, ne ostavlja masni trag. Pruža dugotrajnu hidrataciju, čineći je pogodnom za svakodnevnu upotrebu. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom, masnom ili kombinovanom kožom koje traže efikasnu zaštitu od sunca bez osećaja težine ili masnoće na koži. Zašto volimo Abib Heartleaf Sun Essence Calming Drop? Heartleaf Sun Essence Calming Drop kombinuje visoku zaštitu od sunca sa blagodatima nege kože. Njegova lagana tekstura omogućava lako nanošenje i brzo upijanje, ostavljajući kožu hidriranom bez masnog osećaja. Ekstrakt Houttuynia Cordata pruža umirujuće i antioksidativne efekte. Naime, on štiti kožu od spoljašnjih agresora i smanjuje crvenilo. Niacinamid, poznat i kao vitamin B3, pomaže u poboljšanju teksture kože i ujednačava ten. Dodatni sastojci kao što su pantenol i glicerin pružaju dubinsku hidrataciju, održavajući kožu mekom i elastičnom. Ovaj proizvod je bez mirisa i esencijalnih ulja, što ga čini pogodnim za osetljivu kožu sklonu iritacijama.​ Aktivni sastojci Ekstrakt Houttuynia Cordata Ovaj ekstrakt, poznat i kao ekstrakt biljke srcolisne houtuinije, bogat je flavonoidima poput kvercetina. Ima snažna antioksidativna i protivupalna svojstva. Pomaže u smirivanju iritacija, zaštiti kože od slobodnih radikala i može smanjiti oštećenja izazvana UVB zračenjem. Niacinamid (Vitamin B3) Višenamenski sastojak koji poboljšava barijernu funkciju kože, smanjuje hiperpigmentacije i poboljšava elastičnost. Takođe deluje protivupalno, što može pomoći u smanjenju crvenila i iritacija. Istovremeno reguliše proizvodnju sebuma, što je korisno za masnu i kombinovanu kožu.​ Diethylamino Hydroxybenzoyl Hexyl Benzoate Organski UV filter koji pruža zaštitu od UVA zraka, štiteći kožu od prevremenog starenja i oštećenja izazvanih UV zračenjem. Stabilan je na svetlosti i kompatibilan sa drugim UV filterima, što ga čini efikasnim u formulacijama za zaštitu od sunca. Dodaj u listu želja Dodaj u listu želja', 'Abib Heartleaf Sun Essence Calming Drop je lagana dnevna esencija sa zaštitnim faktorom SPF 50+ PA++++. Obogaćena je sa 50.000 ppm ekstrakta Houttuynia Cordata, koji umiruje kožu izloženu spoljašnjim stresorima.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Abib-Heartleaf-Sun-Essence-Calming-Drop.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
