INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (936, 154, 'Skin1004 Hyalu-Cica Sunsational Kit', 'skin1004-hyalu-cica-sunsational-kit', 'Šta set sadrži? Madagascar Centella Hyalu-Cica Silky-Fit Sun Stick – praktičan stik za zaštitu od sunca sa svilenkastim završetkom i laganom teksturom. Madagascar Centella Hyalu-Cica Water-Fit Sun Serum – hidratantni serum sa visokim SPF faktorom, idealan za svakodnevnu upotrebu ispod šminke. Ključne prednosti: Visoka UV zaštita: Oba proizvoda pružaju širok spektar zaštite sa SPF50+ PA++++, štiteći kožu od štetnih UVA i UVB zraka. ​ Hidratacija i umirenje kože: Kombinacija Centella Asiatica ekstrakta i hijaluronske kiseline pomaže u umirivanju iritacija i održavanju optimalne hidratacije kože. ​ Lagana tekstura bez belih tragova: Sun serum se brzo upija, ostavljajući kožu hidriranom i blistavom, dok sun stick pruža svilenkast završni sloj bez lepljivosti ili belih tragova. Kome je namenjen? Ovaj set je idealan za osobe sa svim tipovima kože, posebno za one sa osetljivom ili suvom kožom koja zahteva dodatnu hidrataciju i umirenje. Takođe je pogodan za one koji traže efikasnu zaštitu od sunca bez teškog ili masnog osećaja na koži. Zašto volimo SKIN1004 Hyalu-Cica Sunsational Kit? Hyalu-Cica Sunsational Kit pruža sveobuhvatnu zaštitu i negu kože tokom izlaganja suncu. Sun serum, sa svojom laganom i brzoupijajućom formulom, obezbeđuje dubinsku hidrataciju i ostavlja kožu blistavom bez masnog osećaja. Sun stick, zahvaljujući svom praktičnom obliku, omogućava jednostavnu i ravnomernu aplikaciju, pružajući svilenkast završni sloj koji ne ostavlja bele tragove. Kombinacija ovih proizvoda osigurava da je koža zaštićena od štetnih UV zraka, dok istovremeno ostaje hidrirana i umirena zahvaljujući blagodatima Centella Asiatica ekstrakta i hijaluronske kiseline. ​ Aktivni sastojci Centella Asiatica ekstrakt Poznata i kao tigrova trava, ova biljka je cenjena zbog svojih umirujućih i regenerativnih svojstava. Pomaže u smanjenju upala, ubrzava zarastanje rana i poboljšava ukupnu elastičnost kože. U ovom setu, Centella Asiatica ekstrakt deluje kao ključni sastojak koji umiruje iritacije izazvane izlaganjem suncu i jača barijeru kože. ​ Hijaluronska kiselina Ovaj moćni humektant može zadržati vodu do 1000 puta svoje težine, pružajući intenzivnu hidrataciju koži. Pomaže u popunjavanju finih linija i bora, ostavljajući kožu glatkom i punijom. U kombinaciji sa Centella Asiatica ekstraktom, hijaluronska kiselina osigurava da koža ostane hidrirana i elastična tokom celog dana. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Hyalu-Cica Sunsational Kit je set proizvoda za zaštitu kože od sunca, koji sadrži Madagascar Centella Hyalu-Cica Silky-Fit Sun Stick i dva Madagascar Centella Hyalu-Cica Water-Fit Sun Seruma. Ovi proizvodi kombinuju ekstrakt biljke Centella Asiatica i hijaluronsku kiselinu kako bi pružili efikasnu UV zaštitu i hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2025/03/SKIN1004-Hyalu-Cica-Sunsational-Kit.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
