INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (939, 39, 'Cos De BAHA L2 Bakuchiol & Retinol serum', 'cos-de-baha-l2-bakuchiol-retinol-serum', 'Ključne prednosti: Dvostruko anti-age dejstvo: Kombinacija bakučiola i retinola smanjuje bore i poboljšava elastičnost kože bez agresivnih efekata. Umirivanje i hidratacija: Niacinamid i adenozin jačaju barijeru kože, smanjuju iritacije i ujednačavaju ten. Pogodno za osetljivu kožu: Biljni retinol (bakučiol) pruža regenerativne benefite, a istovremeno smanjuje rizik od isušivanja i crvenila. Kome je namenjen? Ovaj serum je idealan za osobe sa znacima starenja, hiperpigmentacijom i nepravilnostima kože, kao i one sa masnom ili kombinovanom kožom sklonom aknama. Posebno je formulisan za one koji žele benefite retinola, ali imaju osetljivu kožu. Zašto volimo Cos De BAHA L2 Bakuchiol & Retinol serum? L2 Bakuchiol & Retinol serum predstavlja balansiranu kombinaciju klasičnih i biljnih aktivnih sastojaka za podmlađivanje kože. Zahvaljujući bakučiolu, biljnog porekla, koža dobija slične benefite kao od retinola – poboljšana elastičnost, redukcija finih linija i posvetljivanje tena – ali bez agresivnih nuspojava. Retinol u koncentraciji od 0,5% podstiče regeneraciju ćelija, dok niacinamid deluje na kontrolu sebuma i ujednačavanje tena. Adenozin dodatno smanjuje vidljivost bora, a istovremeno umiruje kožu. Ova formula poboljšava opšti kvalitet kože, pružajući joj mladalački i svež izgled. Aktivni sastojci Bakučiol (2%) Bakučiol je biljna alternativa retinolu, poznat po svojim antioksidativnim i regenerativnim svojstvima. Za razliku od klasičnog retinola, ne izaziva iritaciju niti isušivanje kože, što ga čini pogodnim i za osetljive tipove kože. Ovaj sastojak pomaže u stimulaciji sinteze kolagena, čime se poboljšava čvrstina i elastičnost kože. Takođe, smanjuje hiperpigmentaciju i poboljšava ujednačenost tena. Retinol (0,5%) Retinol je jedan od najefikasnijih sastojaka za podmlađivanje kože, jer ubrzava regeneraciju ćelija i poboljšava teksturu kože. U koncentraciji od 0,5%, dovoljno je snažan da smanji bore i poboljša elastičnost, a da pri tom ne izazove preteranu iritaciju. Njegova sposobnost da reguliše proizvodnju sebuma takođe doprinosi smanjenju akni i proširenih pora. Niacinamid Niacinamid (vitamin B3) poznat je po svojim višestrukim benefitima za kožu – smanjuje upale, poboljšava barijernu funkciju i smanjuje crvenilo. Takođe posvetljuje tamne mrlje i ujednačava ten, što ga čini ključnim sastojkom u formulama koje tretiraju hiperpigmentaciju. Adenozin Adenozin je moćan anti-age sastojak koji podstiče proizvodnju kolagena, čime se smanjuju fine linije i bore. Takođe pomaže u umirivanju kože, smanjujući crvenilo i iritacije uzrokovane spoljnim faktorima. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA L2 Bakuchiol & Retinol serum kombinuje 2% bakučiola i 0,5% retinola, pružajući snažan anti-age efekat uz minimalnu iritaciju. Formula dodatno sadrži niacinamid i adenozin, koji posvetljuju ten, poboljšavaju teksturu kože i umanjuju nepravilnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Cos-De-BAHA-L2-Bakuchiol-Retinol-serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
