INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (940, 84, 'Isntree Hyper Vitamin C 30 Cream', 'isntree-hyper-vitamin-c-30-cream', 'Ključne prednosti: Visok sadržaj vitamina C : Sadrži 30% askorbinske kiseline koja efikasno posvetljuje kožu i smanjuje tamne mrlje. ​ Hidratacija i umirenje: Pantenol i 3-Beta kompleks pružaju dubinsku hidrataciju, dok ekstrakt Centella Asiatica i alantoin umiruju iritiranu kožu. ​ Pogodna za osetljivu kožu: Hipoalergena formula čini ovu kremu bezbednom za osobe sa osetljivom kožom. Kome je namenjena? Ova krema je idealna za osobe koje žele da tretiraju post-akne tragove, hiperpigmentaciju, tamne mrlje ili neujednačen ten. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Isntree Hyper Vitamin C 30 Cream? Hyper Vitamin C 30 Cream pruža intenzivnu negu zahvaljujući visokoj koncentraciji čistog vitamina C, poznatog po svojoj sposobnosti da posvetli kožu i smanji vidljivost tamnih mrlja. Redovnom upotrebom, ova krema može pomoći u ujednačavanju tena, dajući koži zdrav i blistav izgled. Pored toga, prisustvo vitamina E pruža dodatnu zaštitu od slobodnih radikala, dok hidratantni sastojci poput panthenola i 3-Beta kompleksa osiguravaju da koža ostane meka i hidrirana. Umirujući sastojci, kao što su ekstrakt Centella Asiatica i alantoin, pomažu u smirivanju iritacija, čineći ovu kremu pogodnom čak i za najosetljiviju kožu. Aktivni sastojci Askorbinska kiselina (Vitamin C) Sa koncentracijom od 30%, askorbinska kiselina je snažan antioksidans koji posvetljuje kožu, smanjuje hiperpigmentaciju i podstiče sintezu kolagena, što rezultira čvršćom i elastičnijom kožom. ​ Tokoferol (Vitamin E) Vitamin E je poznat po svojim antioksidativnim svojstvima koja štite kožu od oštećenja izazvanih slobodnim radikalima i UV zračenjem. Takođe, pomaže u hidrataciji kože i poboljšava njenu elastičnost. ​ Panthenol (Provitamin B5) Panthenol hidrira kožu, poboljšava njenu elastičnost i smanjuje upale, što ga čini idealnim za umirivanje iritirane ili osetljive kože. ​ Ekstrakt Centella Asiatica Ovaj ekstrakt je poznat po svojim umirujućim i lekovitim svojstvima, pomažući u regeneraciji kože i smanjenju upala, što doprinosi zdravijem izgledu kože. ​ Alantoin Alantoin je sastojak koji umiruje kožu, podstiče regeneraciju ćelija i poboljšava teksturu kože, čineći je mekšom i glađom. Dodaj u listu želja Dodaj u listu želja', 'Isntree Hyper Vitamin C 30 Cream je hranljiva krema formulisana sa 30% čistog vitamina C (askorbinske kiseline) koja pomaže u posvetljivanju tena i smanjenju hiperpigmentacije. Obogaćena vitaminom E i umirujućim ekstraktima, ova hipoalergena krema revitalizuje i hidrira kožu, čineći je pogodnom za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Isntree-Hyper-Vitamin-C-30-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
