INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (944, 13, 'Aprilskin Pink Aloe Pack Cleanser', 'aprilskin-pink-aloe-pack-cleanser', 'Ključne prednosti: Višenamenska formula: Kombinuje funkcije maske, pilinga i penećeg čistača, pružajući sveobuhvatnu negu kože.​ Prirodni sastojci: Sadrži ekstrakt ružičaste aloe, zrna mung pasulja i čajevca koji umiruju, čiste i osvežavaju kožu.​ Pogodan za osetljivu kožu: Blaga formula koja ne iritira, idealna za svakodnevnu upotrebu. Kome je namenjen? Ovaj proizvod je idealan za osobe sa svim tipovima kože, posebno za one sa osetljivom ili problematičnom kožom sklonom iritacijama i aknama. Takođe je pogodan za one koji traže efikasan i blag čistač koji pruža dodatne benefite poput hidratacije i umirivanja kože. Zašto volimo APRILSKIN Pink Aloe Pack Cleanser? Pink Aloe Pack Cleanser pruža sveobuhvatnu negu kože kroz svoju jedinstvenu formulu koja kombinuje tri funkcije u jednom proizvodu. Kao maska, omogućava dubinsko prodiranje aktivnih sastojaka koji umiruju i hidriraju kožu. Prirodne piling čestice, poput zrna mung pasulja, nežno uklanjaju mrtve ćelije kože, ostavljajući je glatkom i osveženom. Kao pena za čišćenje, efikasno uklanja nečistoće i ostatke šminke bez isušivanja kože. Redovnom upotrebom, koža postaje vidljivo čistija, mekša i blistavija, dok se smanjuje pojava nesavršenosti i iritacija. Aktivni sastojci Ekstrakt ružičaste aloe Ovaj sastojak poznat je po svojim snažnim hidratantnim i umirujućim svojstvima. Pomaže u obnavljanju oštećene kože, smanjuje crvenilo i iritacije, te pruža dubinsku hidrataciju koja kožu čini mekom i elastičnom. Takođe, bogat je antioksidansima koji štite kožu od štetnih spoljašnjih uticaja i prevremenog starenja.​ Prah zrna mung pasulja Prirodni eksfolijant koji nežno uklanja mrtve ćelije kože, poboljšava teksturu i tonus kože. Takođe, sadrži vitamine i minerale koji hrane kožu, pružajući joj zdrav i blistav izgled.​ Ekstrakt čajevca Poznat po svojim antibakterijskim i antiinflamatornim svojstvima, pomaže u borbi protiv akni i drugih kožnih problema. Umiruje kožu, smanjuje crvenilo i upale, te sprečava nastanak novih nesavršenosti. Dodaj u listu želja Dodaj u listu želja', 'APRILSKIN Pink Aloe Pack Cleanser je višenamenski proizvod koji kombinuje čišćenje, piling i hidrataciju kože u jednom koraku. Obogaćen ekstraktom ružičaste aloe i prirodnim piling česticama, ovaj čistač efikasno uklanja nečistoće, umiruje kožu i pruža joj svežinu.', 'https://beauty-health.rs/wp-content/uploads/2025/03/APRILSKIN-Pink-Aloe-Pack-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
