INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (949, 155, 'Skinfood Egg White Pore Mask', 'skinfood-egg-white-pore-mask', 'Ključne prednosti: Dubinsko čišćenje i sužavanje pora: Ekstrakt belanaca, bentonit i kaolin uklanjaju nečistoće i višak sebuma, smanjujući vidljivost pora. Regulisanje lučenja sebuma: Niacinamid pomaže u kontroli masnoće kože i posvetljava ten, pružajući ujednačen izgled. Hidratacija i umirujući efekat: Panthenol i vitamin E umiruju i hidriraju kožu, sprečavajući isušivanje nakon čišćenja. Kome je namenjena? Ova maska je idealna za osobe sa masnom i kombinovanom kožom koja je sklona proširenim porama, miteserima i viškom sebuma. Takođe je pogodna za osobe sa normalnom kožom koje žele temeljno čišćenje i osvežen izgled kože. Zašto volimo SKINFOOD Egg White Pore Mask? Egg White Pore Mask je savršen dodatak rutini nege kože za one koji žele čistu, osveženu i balansiranu kožu. Ekstrakt belanaca deluje adstrigentno, zatežući pore i smanjujući njihovu vidljivost, dok glina i minerali pomažu u apsorpciji viška masnoće bez isušivanja kože. Niacinamid posvetljuje ten i reguliše lučenje sebuma, dok vitamin E i pantenol pružaju hidrataciju i štite kožu od iritacija. Redovnom upotrebom, koža postaje vidljivo glatkija, mekša i zdravija, sa manjim brojem mitesera i manje izraženim porama. Aktivni sastojci Ekstrakt belanaca (Albumen Extract) Ovaj sastojak je bogat proteinima i aminokiselinama koji pomažu u zatezanju i čišćenju pora. Takođe, pomaže u uklanjanju viška sebuma, čineći kožu matiranom, ali ne isušujući je. Deluje kao prirodni adstrigent, smanjujući vidljivost pora i poboljšavajući teksturu kože. Njegova sposobnost da učvrsti kožu doprinosi osveženom i revitalizovanom izgledu lica. Bentonit i kaolin Ove prirodne gline imaju moćnu sposobnost upijanja viška masnoće i nečistoća iz pora, čineći ih manjim i čistijim. Bentonit pomaže u smanjenju upala i crvenila, dok kaolin nežno pročišćava kožu bez iritacija. Ove gline čine kožu glatkom i ujednačenom, pružajući osećaj osveženja nakon upotrebe. Niacinamid (Vitamin B3) Deluje kao snažan antioksidans koji poboljšava barijeru kože, smanjuje crvenilo i posvetljuje ten. Takođe pomaže u regulaciji sebuma, smanjujući prekomerno mašćenje kože i stvaranje mitesera. Ovaj sastojak doprinosi ujednačenijem tenu i svežem izgledu kože. Tokoferil (Vitamin E) Poznat po svojim antioksidativnim svojstvima, vitamin E pomaže u zaštiti kože od slobodnih radikala i održava je hidriranom. Pruža umirujući efekat, smanjuje crvenilo i poboljšava elastičnost kože. Pantenol Ovaj provitamin B5 deluje umirujuće i hidratantno, pomažući u regeneraciji kože nakon čišćenja. Sprečava suvoću i iritaciju, čineći kožu mekom i elastičnom. Njegova sposobnost da poboljša barijernu funkciju kože doprinosi dugoročnom zdravlju kože. Dodaj u listu želja Dodaj u listu želja', 'SKINFOOD Egg White Pore Mask je pročišćujuća maska za lice formulisana sa ekstraktom belanaca, bentonitom i kaolinom, koji zajedno rade na dubinskom čišćenju pora, apsorpciji viška sebuma i poboljšanju teksture kože. Ova maska zateže pore, umiruje iritacije i ostavlja kožu osveženom, glatkom i matiranom.', 'https://beauty-health.rs/wp-content/uploads/2025/03/SKINFOOD-Egg-White-Pore-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
