INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (952, 169, 'Uodo Veil Matte Lasting Foundation For Oily Skin', 'uodo-veil-matte-lasting-foundation-for-oily-skin', 'Ključne prednosti: Kontrola sebuma: Perlit apsorbuje višak ulja, održavajući kožu matiranom i svežom tokom celog dana. ​ Negujući sastojci: Niacinamid, vitamin C i E posvetljuju kožu i pružaju joj potrebnu negu, poboljšavajući njen ukupni izgled. ​ Umirujući efekat: Ekstrakt zelenog čaja i pantenol umiruju kožu, smanjujući iritacije i crvenilo. Kome je namenjen? Ovaj proizvod je idealan za osobe sa masnom, kombinovanom ili normalnom kožom koje traže dugotrajnu mat podlogu sa visokom pokrivnom moći. Takođe je pogodan za one koji žele da kontrolišu sjaj i poboljšaju teksturu kože. Zašto volimo UODO Veil Matte Lasting Foundation For Oily Skin? Veil Matte Lasting Foundation pruža savršenu osnovu za šminku zahvaljujući svojoj laganoj formuli koja se lako nanosi i pruža visoku pokrivnu moć bez osećaja težine. Obogaćen je niacinamidom, vitaminom C i E, koji posvetljuju kožu i pružaju joj potrebnu negu, dok perlit efikasno kontroliše lučenje sebuma, održavajući mat izgled tokom celog dana. Ekstrakt zelenog čaja i pantenol umiruju kožu, smanjujući iritacije i crvenilo, što ovaj proizvod čini idealnim za osobe sa osetljivom kožom sklonom nepravilnostima. Dostupan je u tri nijanse: C01 za hladne tonove kože, W02 za svetle tople tonove i W03 za prirodne tople tonove, omogućavajući prilagođavanje različitim podtonovima kože. Aktivni sastojci Perlit Prirodni mineral poznat po svojoj sposobnosti apsorpcije viška ulja, što pomaže u kontroli sjaja i održavanju mat izgleda kože tokom celog dana. ​ Niacinamid (Vitamin B3) Poboljšava elastičnost kože, pojačava funkciju barijere, ujednačava tonus kože i smanjuje upale, što rezultira zdravijim izgledom kože. ​ Vitamin C (3-O-Etil askorbinska kiselina) Stabilan oblik vitamina C koji posvetljuje kožu, smanjuje pojavu hiperpigmentacija i pruža antioksidativnu zaštitu protiv slobodnih radikala. ​ Vitamin E (Tokoferol acetat) Moćan antioksidans koji štiti kožu od oštećenja izazvanih slobodnim radikalima, hidrira je i poboljšava njenu teksturu. Dodaj u listu želja Dodaj u listu želja', 'UODO Veil Matte Lasting Foundation j e lagana mat podloga namenjena masnoj i kombinovanoj koži, koja pruža visoku pokrivnu moć i dugotrajan mat finiš bez osećaja težine. Obogaćena je sastojcima poput niacinamida, vitamina C i E, koji posvetljuju i neguju kožu, dok perlit kontroliše lučenje sebuma, pružajući svež izgled tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/03/UODO-Veil-Matte-Lasting-Foundation-For-Oily-Skin.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
