INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (956, 161, 'The Ordinary Multi Peptide + Copper Peptides 1% Serum', 'the-ordinary-multi-peptide-copper-peptides-1-serum', 'Ključne prednosti: Povećanje elastičnosti kože: Peptidi u serumu podržavaju proizvodnju kolagena, što rezultira čvršćom i elastičnijom kožom.​ Smanjenje znakova starenja: Redovna upotreba može smanjiti pojavu finih linija i bora, poboljšavajući teksturu kože.​ Antioksidativna zaštita: Bakarni peptidi pružaju antiinflamatorne i antioksidativne efekte, štiteći kožu od oštećenja izazvanih spoljašnjim faktorima. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za one koji žele da poboljšaju elastičnost kože i smanje vidljive znakove starenja. Pogodan je za osobe koje traže proizvod bez mirisa i sa fokusom na efikasne sastojke. Zašto volimo The Ordinary Multi Peptide + Copper Peptides 1% Serum? Peptidi deluju kao glasnici koji signaliziraju koži da proizvodi više kolagena, što rezultira smanjenjem finih linija i bora. Bakarni peptidi dodatno pružaju antiinflamatorne i antioksidativne benefite, štiteći kožu od oštećenja izazvanih slobodnim radikalima i spoljašnjim zagađivačima. Lagana tekstura seruma omogućava brzo upijanje bez ostavljanja masnog traga, čineći ga pogodnim za upotrebu u jutarnjoj i večernjoj rutini nege kože. Redovnom upotrebom, koža postaje glatkija, hidrirana i blistava, sa poboljšanim ukupnim tonusom i teksturom. Aktivni sastojci Bakarni tripeptid-1 (Copper Tripeptide-1) Ovaj peptid je poznat po svojoj sposobnosti da stimuliše sintezu kolagena i elastina, ključnih proteina za održavanje čvrstoće i elastičnosti kože. Takođe, poseduje antiinflamatorna svojstva koja pomažu u smanjenju upala i crvenila na koži. Bakarni tripeptid-1 deluje kao antioksidans, štiteći kožu od oštećenja izazvanih slobodnim radikalima i UV zračenjem. Pomaže u ubrzanju procesa zarastanja rana i regeneracije kože, što može doprineti smanjenju ožiljaka i hiperpigmentacija. Njegova sposobnost da poboljša mikrocirkulaciju doprinosi zdravijem i blistavijem izgledu kože.​ Acetil heksapeptid-8 (Acetyl Hexapeptide-8) Poznat i kao &#8220;Botox u bočici&#8221;, ovaj peptid deluje tako što inhibira signale koji uzrokuju kontrakciju mišića lica, što može smanjiti pojavu dinamičkih bora. Redovnom upotrebom, može pomoći u smanjenju dubine postojećih bora i sprečiti formiranje novih. Pruža hidrataciju koži, poboljšavajući njenu elastičnost i glatkoću. Njegova blaga priroda čini ga pogodnim za osetljivu kožu, bez rizika od iritacija. Može se koristiti kao preventiva protiv znakova starenja, održavajući mladalački izgled kože.​ Palmitoil tripeptid-1 (Palmitoyl Tripeptide-1) Ovaj peptid stimuliše sintezu kolagena i glikozaminoglikana, što doprinosi poboljšanju strukture i čvrstoće kože. Pomaže u smanjenju finih linija i bora, posebno onih uzrokovanih UV oštećenjima. Poboljšava elastičnost kože, čineći je otpornijom na spoljašnje agresore. Takođe, može pomoći u ujednačavanju tona kože i smanjenju hiperpigmentacija. Njegova sposobnost da poveća hidrataciju kože čini je mekom i glatkom na dodir.​ Palmitoil tetrapeptid-7 (Palmitoyl Tetrapeptide-7) Ovaj peptid deluje tako što smanjuje proizvodnju proinflamatornih citokina, što može smanjiti hroničnu upalu kože i degradaciju kolagena. Pomaže u obnovi kože nakon oštećenja izazvanih UV zračenjem i drugim spoljašnjim faktorima. Poboljšava elastičnost i čvrstoću kože, smanjujući pojavu finih linija i bora. Takođe, može pomoći u smanjenju tamnih kolutova ispod očiju i otoka. Njegova antiinflamatorna svojstva čine ga pogodnim za upotrebu kod osetljive kože sklone crvenilu i iritacijama. Dodaj u listu želja Dodaj u listu želja', 'The Ordinary Multi-Peptide + Copper Peptides 1% Serum je napredni serum formulisan za poboljšanje elastičnosti kože, smanjenje finih linija i bora, te pružanje sveukupnog mladalačkog izgleda. Kombinuje višestruke peptide i bakarne peptide kako bi stimulisao sintezu kolagena i pružio antiinflamatorne benefite.', 'https://beauty-health.rs/wp-content/uploads/2025/03/The-Ordinary-Multi-Peptide-Copper-Peptides-1-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
