INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (958, 6, 'Abib Heartleaf TECA Capsule Serum Calming Drop', 'abib-heartleaf-teca-capsule-serum-calming-drop', 'Ključne prednosti: Intenzivno umirivanje kože: Ekstrakt srca lista i TECA kapsule deluju sinergijski kako bi smanjili crvenilo i iritacije, vraćajući koži prirodnu ravnotežu.​ Dubinska hidratacija: Serum pruža optimalnu hidrataciju, ostavljajući kožu mekom i elastičnom, bez osećaja masnoće.​ Jačanje barijere kože: Aktivni sastojci pomažu u obnavljanju i jačanju zaštitne barijere kože, povećavajući njenu otpornost na spoljašnje agresore. Kome je namenjen? Ovaj serum je idealan za osobe sa osetljivom, iritiranom ili problematičnom kožom koja je sklona crvenilu i upalama. Takođe je pogodan za sve tipove kože koji zahtevaju dodatnu hidrataciju i umirujuću negu. Zašto volimo Abib Heartleaf TECA Capsule Serum Calming Drop? Ekstrakt srca lista, poznat po svojim antiinflamatornim svojstvima, efikasno smanjuje crvenilo i upale, dok TECA kapsule podstiču regeneraciju kože i jačaju njenu barijeru. Lagana tekstura seruma omogućava brzo upijanje bez ostavljanja masnog traga, čineći ga idealnim za svakodnevnu upotrebu. Pored umirujućih efekata, serum pruža dubinsku hidrataciju koja poboljšava elastičnost i tonus kože. Njegova formulacija bez iritansa čini ga pogodnim čak i za najosetljiviju kožu, pružajući osećaj svežine i udobnosti tokom celog dana. Aktivni sastojci Ekstrakt srca lista (Houttuynia cordata) Ovaj biljni ekstrakt poznat je po svojim snažnim antiinflamatornim i antibakterijskim svojstvima. Pomaže u smirivanju iritacija i crvenila, čineći ga idealnim za osetljivu i problematičnu kožu. Takođe, bogat je antioksidansima koji štite kožu od slobodnih radikala i prevremenog starenja. Ekstrakt srca lista pomaže u regulaciji proizvodnje sebuma, što doprinosi smanjenju pojave akni i drugih nesavršenosti. Njegova sposobnost da hidrira i osveži kožu čini je mekom i blistavom. Redovnom upotrebom, koža postaje uravnoteženija i otpornija na spoljašnje agresore.​ TECA (Total Centella Asiatica) TECA je visoko pročišćeni ekstrakt biljke Centella Asiatica, poznate po svojim regenerativnim svojstvima. Sadrži aktivne komponente poput azijatikozida, madekasinske kiseline i azijatinske kiseline, koje podstiču sintezu kolagena i ubrzavaju proces zarastanja kože. TECA pomaže u jačanju zaštitne barijere kože, povećavajući njenu otpornost na spoljašnje faktore. Takođe, smanjuje upale i iritacije, pružajući umirujući efekat na osetljivu kožu. Njegova sposobnost da poboljša elastičnost i hidrataciju kože čini je glatkom i čvrstom. Pored toga, TECA ima antioksidativna svojstva koja štite kožu od oksidativnog stresa i prevremenog starenja. Dodaj u listu želja Dodaj u listu želja', 'Abib Heartleaf TECA Capsule Serum Calming Drop je umirujući serum koji kombinuje ekstrakt srca lista (Houttuynia cordata) i TECA (Total Centella Asiatica) kapsule kako bi pružio intenzivnu hidrataciju i smirio iritacije kože. Ovaj proizvod je posebno formulisan za osobe sa osetljivom i iritiranom kožom, pružajući efikasno rešenje za crvenilo i upale.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Abib-Heartleaf-TECA-Capsule-Serum-Calming-Drop.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
