INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (965, 48, 'Dr. Althea Gentle Vitamin C Serum', 'dr-althea-gentle-vitamin-c-serum', 'Ključne prednosti: Ujednačavanje tena i smanjenje hiperpigmentacije: Kombinacija niacinamida i stabilnog oblika vitamina C pomaže u smanjenju tamnih mrlja i posvetljavanju kože, što rezultira blistavijim i ujednačenijim tenom.​ Povećanje elastičnosti kože: Sastojci seruma stimulišu sintezu kolagena, poboljšavajući čvrstoću i elastičnost kože, što doprinosi smanjenju finih linija i bora.​ Hidratacija i zaštita: Ekstrakt ploda pasjeg trna i dodatni hidratantni sastojci pružaju dubinsku hidrataciju, štiteći kožu od isušivanja i spoljašnjih agresora. Kome je namenjen? Ovaj serum je idealan za osobe sa neujednačenim tenom, hiperpigmentacijom ili prvim znacima starenja.Pogodan je za sve tipove kože, uključujući osetljivu i aknama sklonu kožu, zahvaljujući svojoj blagoj i efikasnoj formuli. Zašto volimo Dr. Althea Gentle Vitamin C Serum? Redovnom upotrebom Gentle Vitamin C Seruma, koža postaje vidljivo blistavija i ujednačenija.Aktivni sastojci deluju sinergijski na smanjenje tamnih mrlja i hiperpigmentacije, pružajući svež i mladalački izgled.Povećanjem proizvodnje kolagena, serum poboljšava strukturu kože, čineći je čvršćom i elastičnijom.Dodatna hidratacija osigurava mekoću i glatkoću, dok antioksidativna svojstva štite kožu od štetnih spoljašnjih faktora. Ovaj serum pruža sveobuhvatnu negu, ciljajući specifične probleme poput neujednačenog tena i gubitka elastičnosti, bez izazivanja iritacija. Aktivni sastojci 3-O-etil askorbinska kiselina Ovaj stabilan derivat vitamina C poznat je po svojoj sposobnosti da prodre duboko u kožu, pružajući snažan antioksidativni efekat. Stimuliše sintezu kolagena, što dovodi do poboljšanja čvrstoće i elastičnosti kože. Takođe, inhibira proizvodnju melanina, smanjujući pojavu tamnih mrlja i ujednačavajući ten. Pruža zaštitu od oksidativnog stresa izazvanog UV zračenjem i zagađenjem, čime sprečava preuranjeno starenje kože. Ekstrakt ploda pasjeg trna (Hippophae Rhamnoides) Bogat vitaminima C, E i K, kao i esencijalnim masnim kiselinama, ovaj ekstrakt pruža snažnu hidrataciju i ishranu koži. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i spoljašnjih agresora. Pomaže u smanjenju upala i crvenila, što je posebno korisno za osetljivu i problematičnu kožu. Doprinosi regeneraciji ćelija, ubrzavajući proces zarastanja i obnavljanja kože. Takođe, poboljšava elastičnost i tonus kože, čineći je čvršćom i mladalačkijom. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Gentle Vitamin C Serum je formulisan sa ključnim sastojcima poput niacinamida, 3-O-etil askorbinske kiseline i ekstrakta ploda pasjeg trna. Ovi sastojci zajednički deluju na posvetljivanje tena, ujednačavanje boje kože i poboljšanje njene elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/03/Dr.-Althea-Gentle-Vitamin-C-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
