INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (966, 154, 'Skin1004 Madagascar Centella Probio-Cica Glow Sun Ampoule', 'skin1004-madagascar-centella-probio-cica-glow-sun-ampoule', 'Ključne prednosti: Visoka UV zaštita: Štiti kožu od štetnog delovanja UVA i UVB zraka, smanjujući rizik od fotostarenja i hiperpigmentacija. Dubinska hidratacija i obnova: Zahvaljujući bogatoj esencijalnoj formuli, intenzivno hidrira kožu, sprečava gubitak vlage i čini je elastičnijom. Umirujuće i regenerativno dejstvo: Centella Asiatica i probiotički sastojci smanjuju iritacije, crvenilo i pomažu u obnavljanju oštećene kože. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom, suvom i iritiranom kožom koja je sklona crvenilu i upalama. Takođe je pogodan za sve tipove kože koji žele visoku zaštitu od sunca uz dodatne benefite hidratacije i umirenja. Zašto volimo SKIN1004 Madagascar Centella Probio-Cica Glow Sun Ampoule? Madagascar Centella Probio-Cica Glow Sun Ampoule pruža kompletnu zaštitu i negu kože uz izuzetno laganu teksturu koja se brzo upija i ne ostavlja beli trag. Njegova formula kombinuje moćnu UV zaštitu sa hidratantnim i regenerativnim sastojcima, što ga čini idealnim za svakodnevnu upotrebu. Osim što štiti kožu od štetnog delovanja sunca, poboljšava njen tonus i elastičnost, pružajući zdrav i blistav izgled. Redovnom upotrebom, koža postaje otpornija na spoljašnje agresore i manje sklona iritacijama. Proizvod ne sadrži veštačke mirise i esencijalna ulja, što ga čini pogodnim i za najosetljivije tipove kože. Aktivni sastojci Centella Asiatica ekstrakt : Ovaj prirodni sastojak poznat je po svom umirujućem i regenerativnom dejstvu. Bogat je aminokiselinama i antioksidansima koji pomažu u smanjenju crvenila, ubrzavaju obnovu kože i jačaju njenu zaštitnu barijeru. Takođe, hidrira i poboljšava elastičnost kože, čineći je otpornijom na spoljašnje faktore. Niacinamid : Oblik vitamina B3 koji pomaže u kontroli sebuma, ujednačava ten i smanjuje vidljivost pora. Osim što doprinosi hidrataciji, niacinamid pomaže u smanjenju upala i crvenila, čineći ga posebno korisnim za osetljivu i problematičnu kožu. Panthenol : Takođe poznat kao provitamin B5, ovaj sastojak ima moćno hidratantno i umirujuće dejstvo. Pomaže u regeneraciji kože, smanjuje osećaj suvoće i pruža dugotrajnu zaštitu od iritacija. Glicerin : Prirodni humektant koji privlači vlagu u kožu i sprečava njen gubitak. Poboljšava teksturu kože, čineći je mekšom i elastičnijom. Keramid NP : Lipid koji jača zaštitnu barijeru kože, smanjuje gubitak vlage i poboljšava njenu otpornost na spoljašnje agresore. Neophodan je za održavanje zdrave i hidrirane kože. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Probio-Cica Glow Sun Ampoule je lagana zaštitna ampula sa SPF50+ PA++++ koja pruža snažnu UV zaštitu, dubinsku hidrataciju i umirujuće dejstvo zahvaljujući ekstraktu madagaskarske Centelle Asiatice. Obogaćena probiotičkim kompleksima, jača kožnu barijeru i poboljšava otpornost kože na spoljašnje iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/03/SKIN1004-Madagascar-Centella-Probio-Cica-Glow-Sun-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
