INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (969, 154, 'Skin1004 Madagascar Centella Glow 1004 Duo Set', 'skin1004-madagascar-centella-glow-1004-duo-set', 'Ključne prednosti: Sveobuhvatna zaštita od sunca – Sun Serum sa SPF50+ PA++++ pruža visoku zaštitu od štetnih UV zraka. Sprečava prevremeno starenje kože i oštećenja izazvana suncem. Intenzivna hidratacija i umirenje – Ampula bogata ekstraktom Centella Asiatica i probioticima dubinski hidrira kožu, jača njenu barijeru i umiruje iritacije. Lagana i brzo upijajuća formula – Oba proizvoda imaju lagane teksture koje se brzo upijaju, ne ostavljajući masni trag. Kome je namenjen? Ovaj duo set je idealan za osobe sa svim tipovima kože koje žele efikasnu zaštitu od sunca, intenzivnu hidrataciju i umirenje kože. Posebno je pogodan za one sa osetljivom ili iritiranom kožom koja zahteva dodatnu negu i zaštitu. Zašto volimo SKIN1004 Madagascar Centella Glow 1004 Duo Set? Redovnom upotrebom Madagascar Centella Glow 1004 Duo Seta, koža postaje vidljivo blistavija i zdravija. Sun Serum efikasno štiti kožu od štetnih UV zraka, sprečavajući pojavu tamnih fleka i znakova starenja. Istovremeno, ampula obnavlja oštećenu kožnu barijeru, pružajući dubinsku hidrataciju i umirujući upale. Kombinacija ovih proizvoda poboljšava teksturu kože, čineći je mekšom i elastičnijom, dok se neujednačen ten postepeno ujednačava. Lagana formula omogućava brzo upijanje, što je čini idealnom podlogom za šminku ili kao deo jutarnje i večernje rutine nege. Bez veštačkih mirisa i boja, ovaj set je siguran za svakodnevnu upotrebu, čak i kod najosetljivije kože. Aktivni sastojci Ekstrakt Centella Asiatica – Poznat i kao tigrova trava, ovaj sastojak je cenjen zbog svojih izuzetnih umirujućih i regenerativnih svojstava. Pomaže u smanjenju upala, crvenila i iritacija, dok istovremeno stimuliše sintezu kolagena, što doprinosi čvrstoći i elastičnosti kože. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i spoljašnjih agresora, čineći je otpornijom na svakodnevne stresore. Redovnom upotrebom, ekstrakt Centella Asiatica pomaže u obnavljanju oštećene kože, poboljšava njenu teksturu i vraća prirodni sjaj. ProBio-Cica (fermentisani ekstrakt Centella Asiatica) – Ovaj inovativni sastojak kombinuje prednosti probiotika i Centella Asiatica kroz proces fermentacije. Poboljšava apsorpciju i efikasnost aktivnih komponenti, jačajući kožnu barijeru i povećavajući njenu otpornost na spoljašnje agresore. ProBio-Cica pomaže u balansiranju mikrobioma kože, što je ključno za održavanje njenog zdravlja i vitalnosti. Takođe, pruža dubinsku hidrataciju, smanjuje upale i iritacije, te poboljšava ukupnu teksturu i tonus kože. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Glow 1004 Duo Set kombinuje dva ključna proizvoda za postizanje blistave i zdrave kože: Madagascar Centella Hyalu-Cica Water-Fit Sun Serum sa SPF50+ PA++++ i Madagascar Centella Probio-Cica Intensive Ampoule. Ovaj set pruža sveobuhvatnu negu, štiteći kožu od štetnih UV zraka i istovremeno je intenzivno hidrira i umiruje.', 'https://beauty-health.rs/wp-content/uploads/2025/03/SKIN1004-Madagascar-Centella-Glow-1004-Duo-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
