INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (971, 85, 'iUNIK Propolis Vitamin Synergy Serum', 'iunik-propolis-vitamin-synergy-serum', 'Ključne prednosti: Umiruje i štiti kožu: Visok sadržaj propolisa pruža snažna antiinflamatorna i antibakterijska svojstva, idealna za osetljivu i aknama sklonu kožu.​ Posvetljuje i ujednačava ten: Ekstrakt ploda pasjeg trna, bogat vitaminom C, pomaže u smanjenju hiperpigmentacija i poboljšava ukupni izgled kože.​ Dubinski hrani i hidrira: Prisustvo hijaluronske kiseline i niacinamida osigurava optimalnu hidrataciju i elastičnost kože. Kome je namenjen? Ovaj serum je pogodan za sve tipove kože, posebno za osobe sa suvom, osetljivom ili aknama sklonom kožom. Idealan je za one koji žele da poboljšaju hidrataciju, ujednače ten i smanje iritacije. Zašto volimo iUNIK Propolis Vitamin Synergy Serum? Propolis Vitamin Synergy Serum pruža sveobuhvatnu negu zahvaljujući pažljivo odabranim prirodnim sastojcima.&gt;Ekstrakt propolisa umiruje iritacije i štiti kožu od spoljašnjih agresora, dok ekstrakt ploda pasjeg trna posvetljuje i revitalizuje kožu. Niacinamid poboljšava teksturu kože i smanjuje vidljivost pora, dok hijaluronska kiselina osigurava dubinsku hidrataciju.Redovnom upotrebom, koža postaje glatka, blistava i otpornija na spoljašnje uticaje. Aktivni sastojci Ekstrakt propolisa Prirodni sastojak poznat po svojim antibakterijskim i antiinflamatornim svojstvima. Pomaže u umirivanju iritacija, ubrzava regeneraciju kože i štiti je od štetnih mikroorganizama. Takođe, pruža esencijalne hranljive materije koje jačaju kožnu barijeru.​ Ekstrakt ploda pasjeg trna (Hippophae Rhamnoides) Bogat vitaminima C, E i K, ovaj ekstrakt posvetljuje kožu, smanjuje hiperpigmentacije i pruža antioksidativnu zaštitu. Pomaže u poboljšanju elastičnosti kože i daje joj zdrav sjaj.​ Niacinamid (Vitamin B3) Višenamenski sastojak koji poboljšava elastičnost kože, jača njenu barijeru, ujednačava ten i smanjuje vidljivost pora. Takođe, pomaže u regulaciji proizvodnje sebuma i ima antiinflamatorna svojstva. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Propolis Vitamin Synergy Serum je lagan serum koji kombinuje 70% ekstrakta propolisa i 12% ekstrakta ploda pasjeg trna , bogatog vitaminima C, E i K, kako bi umirio, nahranio i revitalizovao kožu. Ovaj proizvod pruža dubinsku hidrataciju, poboljšava tonus kože i pomaže u smanjenju znakova starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/03/iUNIK-Propolis-Vitamin-Synergy-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
