INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (972, 164, 'Tirtir Waterism Glow Melting Balm', 'tirtir-waterism-glow-melting-balm', 'Ključne prednosti: Dugotrajna hidratacija: Održava usne vlažnim do 12 sati, sprečavajući isušivanje i pucanje. Prirodni sjaj: Pruža proziran, sjajan finiš koji ističe prirodnu lepotu usana. Raznovrsne nijanse: Dostupan u devet nijansi koje se prilagođavaju različitim prilikama i tonovima kože. Kome je namenjen? Ovaj balzam je idealan za osobe sa suvim ili ispucalim usnama koje traže dugotrajnu hidrataciju i sjaj. Takođe je pogodan za one koji žele suptilnu boju uz negu usana. Zašto volimo TIRTIR Waterism Glow Melting Balm? Waterism Glow Melting Balm se ističe svojom sposobnošću da obezbedi intenzivnu hidrataciju zahvaljujući kombinaciji prirodnih ulja. Njegova lagana formula se lako nanosi, ostavljajući usne mekim i glatkim bez osećaja lepljivosti. Balzam pruža suptilan sjaj koji poboljšava prirodnu boju usana, čineći ih vizuelno punijim i zdravijim. Raznovrsne nijanse omogućavaju prilagođavanje različitim stilovima i prilikama, od svakodnevnog izgleda do posebnih događaja. Pored estetskih prednosti, ovaj balzam štiti usne od spoljašnjih faktora, sprečavajući isušivanje i oštećenja. Redovnom upotrebom, usne postaju elastičnije i otpornije na nepovoljne uslove okoline. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Waterism Glow Melting Balm je hidratantni balzam za usne koji pruža dugotrajnu vlagu, sjaj i efekat 3D volumena za zdrav i blistav izgled. Njegova lagana formula omogućava jednostavnu primenu za hidrirane i sjajne usne u samo jednom koraku. Sve nijanse možete pogledati ovde .', 'https://beauty-health.rs/wp-content/uploads/2025/02/TIRTIR-Waterism-Glow-Melting-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
