INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (975, 164, 'Tirtir Hydro Boost Enzyme Cleansing Balm', 'tirtir-hydro-boost-enzyme-cleansing-balm', 'Ključne prednosti: Dubinsko čišćenje i uklanjanje šminke: Efikasno uklanja 99,21% vodootporne šminke i 99,1% SPF proizvoda u samo jednom korišćenju. Hidratacija i posvetljivanje kože: Obogaćen ekstraktom pirinča, niacinamidom i uljem pirinčanih mekinja za intenzivnu hidrataciju i poboljšan sjaj kože. Nežna eksfolijacija i poboljšanje teksture kože: Aktivni enzimi i sastojci dobijeni iz pirinča uklanjaju mrtve ćelije kože, smanjujući crne i bele mitisere, dok zatežu pore i ujednačavaju ten. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože, uključujući osetljivu. Posebno za one koji traže efikasno rešenje za uklanjanje šminke, dubinsko čišćenje i hidrataciju. Takođe je pogodan za osobe koje žele poboljšati teksturu kože i smanjiti pojavu mitisera. Zašto volimo TIRTIR Hydro Boost Enzyme Cleansing Balm? Hydro Boost Enzyme Cleansing Balm pruža sveobuhvatnu negu kombinovanjem dubinskog čišćenja, hidratacije i eksfolijacije u jednom koraku. Njegova jedinstvena formula sa patentiranim Rice Enziotics Complex-om i pet probiotika podržava zdrav mikrobiom kože. Time poboljšava njenu otpornost i sposobnost zadržavanja vlage. Redovnom upotrebom, balzam smanjuje crne mitisere za 15,18% i bele mitisere za 38,51%, dok zateže pore i ujednačava tonus kože. Dermatološki je testiran i hipoalergen, što ga čini pogodnim za osetljivu kožu. Aktivni sastojci Rice Enziotics Complex™ Napredni kompleks na bazi fermentisanog pirinča koji hidrira i osvetljava ten. Pomaže u uklanjanju nečistoća dok čuva prirodnu vlagu kože. Ostavlja kožu čistom, mekom i ujednačenom. Patentirani enzimi Enzimi u formuli deluju kao nežni eksfolijanti – čiste pore, uklanjaju mrtve ćelije i pomažu u prevenciji začepljenja. Osvežavaju kožu bez iritacija, čineći je glatkijom i prozračnijom. Niacinamid Oblik vitamina B3 koji ujednačava ton kože, smanjuje vidljivost pora i jača kožnu barijeru. Deluje posvetljujuće i balansira proizvodnju sebuma, ostavljajući kožu čvrstom i osveženom. Ulje pirinčanih mekinja (Rice Bran Oil) Prirodno bogato antioksidansima i vitaminom E, pomaže u hidrataciji i zaštiti kože od spoljašnjih uticaja. Omekšava kožu i doprinosi zdravom sjaju. 5 Probiotika Kompleks probiotika koji jača mikrobiom kože i štiti njenu prirodnu barijeru. Pomaže u smanjenju osjetljivosti i iritacija, posebno kod reaktivne kože. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Hydro Boost Enzyme Cleansing Balm je luksuzni balzam za čišćenje bez mineralnih ulja koji dubinski hidrira i nežno eksfolira kožu zahvaljujući aktivnim enzimima i patentiranom Rice Enziotics Complex -u. Ovaj proizvod efikasno uklanja šminku, nečistoće i SPF, ostavljajući kožu osveženom i blistavom.', 'https://beauty-health.rs/wp-content/uploads/2025/02/TIRTIR-Hydro-Boost-Enzyme-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
