INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (976, 124, 'Nine Less Ample SET', 'nine-less-ample-set', 'Ključne prednosti: Ujednačavanje tena i smanjenje hiperpigmentacije: Niacinamid i azelaična kiselina sinergijski deluju na smanjenje tamnih mrlja i postupalnih hiperpigmentacija. Regulacija proizvodnje sebuma i smanjenje pora: Niacinamid pomaže u kontroli lučenja ulja i smanjenju proširenih pora, poboljšavajući teksturu kože. Umirujuće dejstvo i smanjenje upala: Azelaična kiselina i ekstrakt Centella Asiatica umiruju iritacije i crvenilo, čineći ovaj set idealnim za osetljivu i aknama sklonu kožu. Kome je namenjen? Ovaj set je posebno formulisan za osobe sa masnom i kombinovanom kožom sklonom aknama, hiperpigmentacijama i neujednačenom tonu. Takođe je pogodan za one koji žele poboljšati teksturu kože i smanjiti vidljivost pora. Zašto volimo Nine Less Ample SET? Redovnom upotrebom Ample SET-a, korisnici mogu očekivati značajno poboljšanje u izgledu kože. B-Boost 10% Niacinamide Serum efikasno smanjuje proizvodnju sebuma, što dovodi do manje masnog sjaja i smanjenja pojave akni. Istovremeno, ovaj serum minimizuje izgled pora i poboljšava elastičnost kože. A-Control 10% Azelaic Acid Serum deluje na smanjenje upala i crvenila, brzo umirujući iritiranu kožu. Njegova sposobnost da posvetli tamne mrlje i izjednači ton kože čini ga neprocenjivim za one koji se bore sa postupalnim hiperpigmentacijama. Kombinacija ovih seruma pruža sveobuhvatan pristup nezi kože, rezultirajući čistijom, svetlijom i zdravijom kožom. Dodaj u listu želja Dodaj u listu želja', 'Nine Less Ample SET kombinuje dva moćna seruma— B-Boost 10% Niacinamide Serum i A-Control 10% Azelaic Acid Serum —koji zajedno ciljano deluju na različite probleme kože, uključujući neujednačen ton, hiperpigmentaciju i akne. Ova kombinacija pruža sveobuhvatnu negu za postizanje čiste, blistave i uravnotežene kože.', 'https://beauty-health.rs/wp-content/uploads/2025/02/Nine-Less-Ample-SET.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
