INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (979, 48, 'Dr. Althea 0.1% Gentle Retinol Serum', 'dr-althea-0-1-gentle-retinol-serum', 'Ključne prednosti: Smanjenje znakova starenja: Kombinacija retinola i bakučiola deluje sinergijski na smanjenje bora i finih linija, poboljšavajući teksturu kože. Poboljšana elastičnost kože: Aktivni sastojci povećavaju čvrstinu i elastičnost kože, dajući joj mladalački izgled. Dubinska hidratacija: Sastojci poput pantenola, soka breze i sojinog ulja pružaju intenzivnu hidrataciju, sprečavajući suvoću i iritacije. Kome je namenjen? Ovaj serum je idealan za osobe sa osetljivom kožom koja je sklona iritacijama od retinol. Posebno za one koji žele da smanje znakove starenja i poboljšaju elastičnost kože. Zašto volimo Dr. Althea 0.1% Gentle Retinol Serum? 0.1% Gentle Retinol Serum predstavlja inovativno rešenje za one koji žele da uvedu retinol u svoju rutinu nege kože bez rizika od iritacija. Kombinacija 0,1% čistog retinola i bakučiola pruža efikasnu anti-age negu. Bakučiol, poznat po svojim svojstvima poboljšanja elastičnosti pora, deluje kao prirodna alternativa retinolu. On pružaja slične benefite bez iritacija. Dodatno, serum je obogaćen hidratantnim sastojcima poput pantenola, soka breze i sojinog ulja. Oni osiguravaju da koža ostane hidrirana i meka tokom celog dana. Lagana tekstura seruma omogućava brzo upijanje bez ostavljanja masnog traga. Aktivni sastojci Retinol (0,1%) Retinol je oblik vitamina A koji je poznat po svojoj sposobnosti da ubrza obnavljanje ćelija kože i stimuliše sintezu kolagena. Ovo dovodi do smanjenja pojave finih linija i bora, poboljšavajući ukupnu teksturu i tonus kože. Takođe, retinol pomaže u smanjenju hiperpigmentacija i ujednačavanju tena. Zbog svoje efikasnosti, često se koristi u proizvodima protiv starenja. Koncentracija od 0,1% idealna za početnike ili osobe sa osetljivom kožom. ​ Bakuchiol Bakuchiol je biljni ekstrakt koji se često koristi kao prirodna alternativa retinolu zbog svojih sličnih efekata na kožu. Pomaže u poboljšanju elastičnosti i čvrstine kože, smanjujući pojavu finih linija i bora. Za razliku od retinola, bakuchiol je manje iritantan i pogodan je za osetljivu kožu. Ima antiinflamatorna i antioksidativna svojstva koja štite kožu od slobodnih radikala i upala. Kombinacija bakuchiola i retinola u ovom serumu omogućava postizanje maksimalnih benefita uz minimalnu iritaciju. Sok breze (Betula Alba Juice) Sok breze je prirodni sastojak bogat aminokiselinama, enzimima i antioksidansima koji pružaju intenzivnu hidrataciju i ishranu koži. Pomaže u umirivanju iritacija i crvenila, čineći kožu mirnijom i osveženom. Takođe, poboljšava elastičnost i čvrstinu kože, doprinoseći njenom mladalačkom izgledu. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea 0.1% Gentle Retinol Serum je formulisan sa 0,1% retinola i bakučiolom kako bi pružio efikasnu negu protiv starenja uz minimalnu iritaciju. Ovaj serum poboljšava elastičnost kože, smanjuje pojavu finih linija i bora, istovremeno održavajući kožu hidriranom i glatkom.', 'https://beauty-health.rs/wp-content/uploads/2025/02/Dr.-Althea-0.1-Gentle-Retinol-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
