INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (985, 75, 'Hyaah Kelp Concentrate Synergy mask', 'hyaah-kelp-concentrate-synergy-mask', 'Ključne prednosti: Dubinska hidratacija: Visok sadržaj morskih algi obezbeđuje optimalnu vlažnost kože, čineći je mekom i osveženom. Poboljšana elastičnost: Redovnom upotrebom maska doprinosi povećanju čvrstine i elastičnosti kože. Smanjenje iritacija: Prirodni sastojci pomažu u umirivanju crvenila i iritacija, čineći je pogodnom za osetljivu kožu. Kome je namenjena? Ova maska je idealna za osobe sa suvom, dehidriranom ili osetljivom kožom sklonom iritacijama. Takođe je preporučljiva za one koji žele poboljšati elastičnost i ukupni tonus kože. Zašto volimo Hyaah Kelp Concentrate Synergy mask? Kelp Concentrate Synergy maska pruža intenzivnu negu zahvaljujući visokom procentu ekstrakta morske alge iz čistih voda Wando regiona. Ova maska ne samo da hidrira površinske slojeve kože, već prodire dublje, obezbeđujući dugotrajnu vlažnost i svežinu. Prirodni minerali i vitamini iz morskih algi hrane kožu, poboljšavajući njen tonus i elastičnost. Redovnom upotrebom, koža postaje vidno glatkija, mekša i otpornija na spoljašnje uticaje. Osim toga, maska pomaže u smanjenju crvenila i umiruje iritacije, što je čini savršenim izborom za osetljivu kožu. Njena lagana tekstura omogućava lako nanošenje i brzo upijanje, ostavljajući kožu osveženom i revitalizovanom. Aktivni sastojci Kelp Extract (ekstrakt morskih algi – 90%) Kelp ekstrakt je bogat izvor minerala, vitamina i antioksidanata koji dubinski hrane i revitalizuju kožu. Zahvaljujući visokim koncentracijama joda, alginska kiselina i polifenola, ovaj ekstrakt deluje detoksikujuće i umirujuće. Pomaže u zadržavanju vlage u koži, jača kožnu barijeru i smanjuje iritacije. Takođe pomaže u posvetljavanju tena, smanjenju crvenila i poboljšanju elastičnosti kože. Posebno je efikasan za umornu, dehidriranu i stresiranu kožu kojoj je potrebna intenzivna hidratacija i osveženje. Dodaj u listu želja Dodaj u listu želja', 'Hyaah Kelp Concentrate Synergy mask sadrži 90% ekstrakta morske alge iz korejskog Wando regiona, pružajući intenzivnu hidrataciju i poboljšanje elastičnosti kože. Ovaj proizvod efikasno rešava probleme suve i dehidrirane kože, vraćajući joj prirodan sjaj i čvrstinu.', 'https://beauty-health.rs/wp-content/uploads/2025/02/Hyaah-Kelp-Concentrate-Synergy-mask-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
