INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (991, 56, 'Elizavecca Milky Piggy Carbonated Bubble Clay Mask', 'elizavecca-milky-piggy-carbonated-bubble-clay-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Mikro-mehurići prodiru duboko u pore, uklanjajući nečistoće i smanjujući pojavu mitesera. Regulacija sebuma: Kaolin apsorbuje višak ulja, pomažući u održavanju ravnoteže masne i kombinovane kože. Osvežavajući efekat: Karbonacija pruža blagi masažni efekat, poboljšavajući cirkulaciju i ostavljajući kožu revitalizovanom. Kome je namenjen? Ovaj proizvod je idealan za osobe sa masnom i kombinovanom kožom sklonom začepljenim porama i viškom sebuma. Takođe je pogodan za one koji traže efikasno rešenje za dubinsko čišćenje i osvežavanje kože. Zašto volimo Elizavecca Milky Piggy Carbonated Bubble Clay Mask? Milky Piggy Carbonated Bubble Clay Mask pruža jedinstveno iskustvo nege kože kroz svoju inovativnu formulu koja se transformiše u mehuriće pri kontaktu sa vazduhom. Ovi mehurići deluju kao mikromasaža, stimulišući cirkulaciju i pomažući u uklanjanju duboko usađenih nečistoća iz pora. Kaolin, poznat po svojim apsorbujućim svojstvima, efikasno uklanja višak sebuma, smanjujući sjaj i sprečavajući nastanak akni. Ekstrakt zelenog čaja pruža antioksidativnu zaštitu, smirujući iritacije i poboljšavajući tonus kože. Redovnom upotrebom, koža postaje vidljivo čistija, mekša i osvežena, sa smanjenom pojavom mitesera i masnog sjaja. Carbonated Water Gazirana voda u formuli stvara mehuriće koji blago masiraju kožu i otvaraju pore, podstičući dublje čišćenje. Ovaj proces poboljšava mikrocirkulaciju i pomaže u uklanjanju nečistoća i sebuma. Gazirani mehurići deluju osvežavajuće i pomažu u detoksikaciji kože. Takođe poboljšavaju kiseoničku ishranu ćelija, što doprinosi zdravijem tenu. Kaolin (White Clay) Kaolin je blaga glina koja upija višak ulja i uklanja nečistoće bez isušivanja kože. Deluje kao prirodni detoksikator i blagi eksfolijant, uklanjajući mrtve ćelije i poboljšavajući teksturu kože. Pomaže u smanjenju sjaja i matiranju kože, što ga čini idealnim za kombinovanu i masnu kožu. Takođe umiruje upale i crvenilo zahvaljujući svom antiinflamatornom delovanju. Charcoal Powder Aktivni ugalj deluje kao magnet za toksine, izvlačeći nečistoće i višak sebuma iz pora. Pomaže u dubinskom čišćenju i smanjenju pojave mitisera. Njegovo antibakterijsko dejstvo doprinosi čistijoj i zdravijoj koži, posebno kod osoba sa problematičnim tenom. Doprinosi ujednačenom tenu i poboljšava teksturu kože. Dodaj u listu želja Dodaj u listu želja', 'Elizavecca Milky Piggy Carbonated Bubble Clay Mask je maska za lice koja kombinuje čišćenje pora i detoksikaciju kože pomoću uglja i ugljen-dioksida. Formulisana sa sastojcima poput kaolina i ekstrakta zelenog čaja, ova maska efikasno uklanja nečistoće i višak sebuma, ostavljajući kožu čistom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Elizavecca-Milky-Piggy-Carbonated-Bubble-Clay-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
