INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1000, 143, 'Round Lab 1025 Dokdo Ampoule', 'round-lab-1025-dokdo-ampoule', 'Ključne prednosti: Dubinska hidratacija: Dubokomorska voda sa 72 prirodna minerala poput magnezijuma, kalcijuma i cinka pomaže u održavanju optimalne vlažnosti kože. Brza apsorpcija: Lagani, blago viskozni serum brzo se upija, ostavljajući kožu osveženom bez osećaja lepljivosti. Umirujući efekat: Formulacija bez mirisa pogodna je za osetljivu kožu, smanjujući crvenilo i iritacije. Kome je namenjen? Ovaj serum je idealan za osobe sa suvom, dehidriranom ili osetljivom kožom koje traže efikasnu hidrataciju i umirenje. Takođe je pogodan za one koji žele lagani proizvod koji se brzo upija bez ostavljanja masnog traga. Zašto volimo ROUND LAB 1025 Dokdo Ampoule? 1025 Dokdo Ampoule pruža intenzivnu hidrataciju zahvaljujući kombinaciji dubokomorske vode i hijaluronske kiseline. Redovnom upotrebom, koža postaje vidljivo mekša i elastičnija, dok se smanjuju znakovi suvoće i hrapavosti. Serum pomaže u jačanju prirodne barijere kože, štiteći je od štetnih spoljašnjih faktora i smanjujući osetljivost na iritacije. Njegova lagana tekstura omogućava brzo upijanje, čineći ga idealnim za upotrebu ispod šminke ili kao deo večernje rutine nege. Bez dodatnih mirisa i boja, ovaj proizvod je formulisan da minimizira rizik od alergijskih reakcija, pružajući sigurnu i efikasnu negu za sve tipove kože. Aktivni sastojci Dubinska morska voda (Deep Sea Water) Dubinska morska voda, bogata mineralima poput kalcijuma, magnezijuma i natrijuma, pomaže u očuvanju optimalne vlažnosti i balansa kože. Njen prirodni sastav podržava regeneraciju i jačanje kožne barijere, posebno kod dehidrirane i osetljive kože. U ovoj ampuli, morska voda pruža temeljnu hidrataciju, dok istovremeno osvežava i revitalizuje umornu kožu. Deluje umirujuće i remineralizujuće, pružajući koži stabilnost i otpornost na spoljne stresore. Njeno prisustvo čini formulu laganom, a efikasnom u pružanju intenzivne vlage. Idealna je za svakodnevnu upotrebu kod svih tipova kože, naročito onih kojima nedostaje sjaj i elastičnost. Hijaluronska kiselina Hijaluronska kiselina je jedan od najmoćnijih prirodnih humektanata koji privlači vlagu iz okoline i zadržava je unutar kože. Pruža višeslojnu hidrataciju, čime koža postaje punija, glađa i elastičnija. U ovoj formuli, hijaluronska kiselina pomaže u smanjenju osećaja zatezanja i dehidratacije, pružajući dugotrajnu vlažnost bez masnog osećaja. Brzo se apsorbuje zahvaljujući gel-vodastoj teksturi ampule. Njena prisutnost pojačava efikasnost ostalih aktivnih sastojaka. Prikladna je za sve tipove kože, uključujući osetljivu i reaktivnu. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB 1025 Dokdo Ampoule je hidratantni serum koji kombinuje dubokomorsku vodu bogatu mineralima sa hijaluronskom kiselinom za intenzivnu hidrataciju i umirenje kože. Ovaj proizvod efikasno rešava probleme suvoće i iritacije, pružajući koži svežinu i elastičnost.', 'https://beauty-health.rs/wp-content/uploads/2025/01/ROUND-LAB-1025-Dokdo-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
