INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1002, 135, 'Purcell 88B/mL L-Glutathione Flexible Liposome', 'purcell-88b-ml-l-glutathione-flexible-liposome', 'Ključne prednosti: Smanjenje hiperpigmentacije: Visoka koncentracija glutationa pomaže u kontroli formiranja pega i smanjenju melaninske pigmentacije, što rezultira ujednačenijim tenom. Posvetljivanje tena: Serum pruža efekat posvetljivanja, revitalizujući ten i dajući koži blistav izgled. Blaga formula: Iako je visoko koncentrovan, serum je formulisan da bude blag prema koži, čineći ga pogodnim i za osetljivu kožu sklonu aknama. Kome je namenjen? Ovaj serum je idealan za osobe koje žele da ujednače ten, smanje tamne fleke i poboljšaju opšti izgled kože. Pogodan je za sve tipove kože, uključujući kožu sklonu aknama, zahvaljujući svojoj blagoj formuli bez štetnih sastojaka. Zašto volimo PURCELL 88B/mL L-Glutathione Flexible Liposome? 88B/mL L-Glutathione Flexible Liposome serum pruža intenzivnu negu usmerenu na smanjenje hiperpigmentacije i poboljšanje opšteg izgleda kože. Visoka koncentracija glutationa deluje na smanjenje tamnih fleka i pega, dok istovremeno posvetljuje ten, dajući koži zdrav i blistav izgled. Formulisan bez štetnih sastojaka, serum je pogodan za svakodnevnu upotrebu, čak i kod osoba sa osetljivom kožom sklonom aknama. Njegova lagana, vodenasta tekstura omogućava brzo upijanje, ostavljajući kožu hidriranom i osveženom. Redovnom upotrebom, korisnici mogu očekivati ujednačeniji ten, smanjenje vidljivosti tamnih fleka i opšti osećaj revitalizovane kože. Aktivni sastojci L-Glutathione (5% u fleksibilnoj liposomskoj formi) L-Glutathione je snažan antioksidans koji deluje kao prirodni inhibitor sinteze melanina, efikasno posvetljujući kožu i smanjujući pojavu tamnih fleka, pega i hiperpigmentacija. U ovom proizvodu koristi se u visokoj koncentraciji od 5%, ali u liposomski inkapsuliranom obliku, što omogućava dublji prodor u kožu i bolju stabilnost. Liposomska tehnologija osigurava postepeno otpuštanje glutathiona, čime se smanjuje rizik od iritacija i povećava efikasnost tretmana. Deluje tako što neutrališe slobodne radikale, smanjuje oksidativni stres i poboljšava sveukupni ton i jasnoću kože. Pored efekta posvetljavanja, doprinosi i jačanju ćelijske otpornosti i regeneraciji. Idealno za svakodnevnu upotrebu kod osoba sa neujednačenim tenom i kožom sklonom aknama. Dodaj u listu želja Dodaj u listu želja', 'PURCELL 88B/mL L-Glutathione Flexible Liposome je visokokoncentrovani serum koji sadrži 5% čistog glutationa, namenjen za poboljšanje nepravilnosti na koži i smanjenje pega. Ovaj serum efikasno smanjuje pigmentaciju melanina, pročišćava ten i pruža blistav izgled kože.', 'https://beauty-health.rs/wp-content/uploads/2025/01/PURCELL-88BmL-L-Glutathione-Flexible-Liposome-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
