INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1003, 135, 'Purcell 24/7 Colostrum Pore Defence Ampoule', 'purcell-24-7-colostrum-pore-defence-ampoule', 'Ključne prednosti: Brza hidratacija: Sprej-ampula pruža trenutnu hidrataciju dehidriranoj koži, ostavljajući je osveženom i revitalizovanom. Sužavanje pora: Redovnom upotrebom, proizvod pomaže u smanjenju proširenih pora, poboljšavajući teksturu kože. Jačanje kožne barijere: Aktivni sastojci poput peptida i pantenola jačaju prirodnu barijeru kože. Kome je namenjena? Ova ampula je idealna za osobe sa dehidriranom kožom sklonom proširenim porama i viškom sebuma. Pogodna je za sve tipove kože, uključujući osetljivu, i može se koristiti tokom celog dana za osveženje i hidrataciju. Zašto volimo PURCELL 24/7 Colostrum Pore Defence Ampoule? 24/7 Colostrum Pore Defence Ampoule pruža trenutnu hidrataciju zahvaljujući hijaluronskoj kiselini, koja zadržava vlagu u koži i sprečava isušivanje. Kolostrum, bogat proteinima i antitelima, pomaže u regeneraciji kože i smanjenju upala. Peptidi stimulišu sintezu kolagena, poboljšavajući elastičnost i čvrstinu kože. Pantenol umiruje iritacije i crvenilo. Adenozin deluje protiv starenja, smanjujući vidljivost finih linija i bora. Sprej format omogućava jednostavnu i ravnomernu aplikaciju, čineći ga praktičnim za korišćenje tokom dana, čak i preko šminke, za trenutnu dozu hidratacije i osveženja. Redovnom upotrebom, koža postaje hidrirana, glatka i blistava, sa smanjenim porama i poboljšanom teksturom. Aktivni sastojci Pixcell Biom™ (kompleks 5 vrsta mlečnokiselinskih bakterija) Pixcell Biom™ je patentirani probiotski kompleks koji sadrži pet različitih vrsta mlečnokiselinskih bakterija (lactobacillus i bifidobacterium sojevi), poznatih po svom regenerativnom, balansirajućem i barijerno-jačajućem delovanju. Deluje tako što poboljšava mikrobiotsku ravnotežu kože, jača prirodni imunitet i povećava otpornost kože na spoljne stresore. Takođe pomaže u smanjenju upala i poboljšava funkciju zaštitne barijere, naročito kod osetljive ili iritirane kože. U ovoj formuli doprinosi zdravijem, stabilnijem i ujednačenijem tenu. Posebno je koristan u tretmanu kože sklone aknama i preosetljivosti. Njegovo prisustvo čini ovaj sprej-ampulu funkcionalnim za svakodnevnu upotrebu i trenutno umirenje kože. Dodaj u listu želja Dodaj u listu želja', 'PURCELL 24/7 Colostrum Pore Defence Ampoule je sprej-ampula formulisana sa kolostrumom i hijaluronskom kiselinom, namenjena za brzu hidrataciju kože i dugotrajno sužavanje proširenih pora. Obogaćena peptidima, pantenolom i adenozinom, ova ampula jača kožnu barijeru i smanjuje višak sebuma, pružajući svež i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/01/PURCELL-247-Colostrum-Pore-Defence-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
