INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1004, 114, 'Medicube Age-R Vita C Pro Ampoule', 'medicube-age-r-vita-c-pro-ampoule', 'Ključne prednosti: Posvetljivanje kože: Visoka koncentracija vitamina C efikasno smanjuje hiperpigmentacije i ujednačava ten, dajući koži blistav izgled. Poboljšanje elastičnosti: Kombinacija aktivnih sastojaka poboljšava elastičnost kože, smanjujući vidljivost finih linija i bora. Umirujuće dejstvo: Sastojci poput vitamina B5 i ekstrakta korena kurkume umiruju iritacije i crvenilo, čineći kožu smirenijom i zdravijom. Kome je namenjena? Ova ampula je idealna za osobe sa neujednačenim tenom, tamnim flekama ili kožom sklonom hiperpigmentacijama. Takođe je pogodna za one koji žele da poboljšaju elastičnost kože i smanje vidljivost znakova starenja. Zašto volimo Medicube Age-R Vita C Pro Ampoule? Age-R Vita C Pro Ampoule pruža intenzivnu negu zahvaljujući visokoj koncentraciji čistog vitamina C. On je pre svega poznat po svojoj sposobnosti da posvetli kožu i smanji vidljivost tamnih fleka. Redovnom upotrebom, ova ampula pomaže u ujednačavanju tena, dajući koži blistav i zdrav izgled. Pored toga, formula je obogaćena vitaminom B5, koji hidrira i umiruje kožu, smanjujući iritacije i crvenilo. Adenozin i ekstrakt korena kurkume doprinose poboljšanju elastičnosti kože, smanjujući vidljivost finih linija i bora. Lagana tekstura ampule omogućava brzo upijanje bez ostavljanja lepljivog osećaja, što je čini pogodnom za sve tipove kože. Najbolji efekti Za optimalne rezultate, preporučuje se korišćenje u kombinaciji sa uređajem Medicube Age-R Booster Pro , koji poboljšava apsorpciju aktivnih sastojaka i povećava efikasnost proizvoda. Aktivni sastojci Vitamin C (askorbinska kiselina) Vitamin C je snažan antioksidans koji deluje na smanjenje pigmentacija, posvetljivanje kože i ujednačavanje tena. Pomaže u inhibiciji sinteze melanina, čime vidljivo smanjuje tamne fleke i neujednačen ton kože. Takođe stimuliše proizvodnju kolagena, čime doprinosi čvrstoći i elastičnosti kože. U ovoj ampuli, visoka koncentracija vitamina C omogućava intenzivan osvetljavajući efekat i vidljive rezultate u kratkom vremenskom periodu. Vitamin C kapsule Vitamin C kapsule omogućavaju stabilnu i ciljanu isporuku aktivnih jedinjenja direktno na kožu, čime se maksimalizuje njihova efikasnost bez gubitka potentnosti. Mikroinkapsulirani oblik vitamina C čuva aktivni sastojak od oksidacije i omogućava postupno oslobađanje, čime se produžava njegovo dejstvo. Kapsule deluju direktno na tamne fleke, beživotan ten i prve znakove starenja. Njihova struktura omogućava bolju apsorpciju i smanjen rizik od iritacije, čak i kod osetljive kože. Gel baza (Transparent Gel) Transparentna gel baza omogućava brzo upijanje formule i prijatan osećaj na koži bez lepljivosti. Služi kao nosač za vitamin C kapsule i dodatno hidrira kožu, pripremajući je za bolje usvajanje aktivnih sastojaka. Deluje umirujuće i osvežavajuće, čineći proizvod pogodnim i za dnevnu i za noćnu rutinu. Takođe doprinosi smanjenju osećaja suvoće i zategnutosti, čineći kožu mekom i glatkom. Dodaj u listu želja Dodaj u listu želja', 'Medicube Age-R Vita C Pro Ampoule je visokokoncentrovana ampula formulisana sa 21% čistog vitamina C, namenjena za posvetljivanje tamnih fleka i neujednačenog tena, kao i za poboljšanje elastičnosti kože. Obogaćena vitaminom B5, adenosinom i ekstraktom korena kurkume, ova lagana formula revitalizuje kožu, zaglađuje njenu teksturu i umiruje iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-Age-R-Vita-C-Pro-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
