INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1005, 126, 'Numbuzin No.9 NAD Bio Lifting-sil Essence', 'numbuzin-no-9-nad-bio-lifting-sil-essence', 'Ključne prednosti: Smanjenje bora i finih linija: Kombinacija NAD+ i peptida efikasno smanjuje različite vrste bora, uključujući linije smeha, bore mrštenja i bore ispod očiju. Poboljšanje elastičnosti kože: Aktivni sastojci podstiču sintezu kolagena, što rezultira čvršćom i elastičnijom kožom. Revitalizacija i obnova kože: Antioksidansi poput glutationa i vitamina C pomažu u regeneraciji ćelija i vraćaju koži prirodni sjaj. Kome je namenjena? Ova esencija je idealna za osobe koje se suočavaju sa znakovima starenja, poput bora, opuštene kože i gubitka elastičnosti. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Numbuzin No.9 NAD Bio Lifting-sil Essence? No.9 NAD Bio Lifting-sil Essence pruža sveobuhvatnu negu protiv starenja zahvaljujući sinergiji svojih sastojaka. NAD+ stimuliše obnavljanje ćelija i poboljšava metabolizam kože. 50 različitih peptida ciljano deluje na različite vrste bora, smanjujući njihovu vidljivost. Antioksidansi poput glutationa i vitamina C štite kožu od oksidativnog stresa i posvetljuju ten. Esencija ima jedinstvenu teksturu sličnu elastičnim nitima, koja se brzo upija, ostavljajući kožu hidriranom i blistavom. Redovnom upotrebom, koža postaje čvršća, elastičnija i vidno mlađa. Aktivni sastojci NAD+ (Nikotinamid adenin dinukleotid) NAD+ je koenzim prisutan u svakoj ćeliji i ključan za ćelijski metabolizam, regeneraciju i obnovu kože. Sa godinama, nivo NAD+ u telu opada, što direktno utiče na starenje kože i pojavu bora. U topikalnim proizvodima, NAD+ stimuliše energetski ciklus ćelija (ATP proizvodnju), ubrzava regeneraciju i pomaže u popravljanju oštećenja izazvanih UV zračenjem i zagađenjem. Glutation Glutation je jedan od najmoćnijih antioksidanasa u ljudskom telu, poznat po svojoj sposobnosti da neutralizuje slobodne radikale i uspori proces starenja. Inhibira proizvodnju melanina, čime pomaže u smanjenju tamnih fleka i posvetljavanju tena. U kombinaciji sa NAD+ i vitaminom C, glutation u ovoj formuli pruža sinergijski efekat protiv starenja i za posvetljivanje kože. Pruža dodatni sloj zaštite ćelijama kože i podržava njihovu regeneraciju. Vitamin C (Askorbil derivat) Vitamin C je snažan antioksidans koji posvetljuje kožu, stimuliše sintezu kolagena i pomaže u smanjenju finih linija i bora. U stabilizovanom obliku, deluje efikasno bez izazivanja iritacija i pospešuje regeneraciju kože. U ovoj esenciji doprinosi osvetljenju tena i zategnutijem izgledu kože. Idealno je za postizanje blistavog i ujednačenog tena. Kompleks od 50 peptida Peptidi su kratki lanci aminokiselina koji imaju specifične funkcije u stimulaciji sinteze kolagena, elastina i drugih strukturnih proteina kože. U ovom kompleksu se nalaze funkcionalni peptidi koji ciljano deluju na različite tipove bora: nazolabijalne linije, bore između obrva i sitne linije oko očiju. Redovnom upotrebom, peptidi jačaju dermalnu strukturu i povećavaju elastičnost, dok istovremeno smanjuju vidljivost postojećih bora. U ovoj formuli, kompleks peptida pruža intenzivno lifting i regenerativno dejstvo bez potrebe za agresivnim tretmanima. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.9 NAD Bio Lifting-sil Essence je visokokoncentrovana esencija formulisana sa NAD+ i 50 različitih peptida, namenjena za poboljšanje elastičnosti kože i smanjenje vidljivosti bora. Ovaj proizvod revitalizuje kožu, čineći je čvršćom i glatkijom, dok istovremeno pruža intenzivnu hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Numbuzin-No.9-NAD-Bio-Lifting-sil-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
