INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1006, 114, 'Medicube PDRN Pink Hyaluronic Moisturizing Cream', 'medicube-pdrn-pink-hyaluronic-moisturizing-cream', 'Ključne prednosti: Smanjenje fleka i posvetljivanje tena: Kombinacija PDRN-a i niacinamida efikasno smanjuje vidljivost tamnih fleka i ujednačava ten, dajući koži blistav izgled. Dubinska hidratacija i jačanje barijere: Deset vrsta hijaluronskih kiselina prodiru u različite slojeve kože, pružajući intenzivnu hidrataciju i jačajući njenu zaštitnu barijeru. Poboljšanje elastičnosti kože: Peptidi i adenozin podstiču sintezu kolagena, smanjujući pojavu finih linija i bora, čineći kožu čvršćom i elastičnijom. Kome je namenjena? Ova krema je idealna za osobe sa neujednačenim tenom, tamnim flekama ili oštećenjima od sunca, kao i za one koji žele da poboljšaju elastičnost kože i ojačaju njenu barijernu funkciju. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Medicube PDRN Pink Hyaluronic Moisturizing Cream? PDRN Pink Hyaluronic Moisturizing Cream pruža sveobuhvatnu negu kože kroz sinergijsko delovanje svojih aktivnih sastojaka. PDRN iz lososa pomaže u regeneraciji kože, smanjujući vidljivost ofleka. Niacinamid posvetljuje tamne oblasti i ujednačava ten. Deset različitih hijaluronskih kiselina obezbeđuje višeslojnu hidrataciju, zadržavajući vlagu u koži. Peptidi i adenozin deluju na dublje slojeve kože, podstičući proizvodnju kolagena i elastina. Ovo rezultira smanjenjem bora i poboljšanjem čvrstine kože. Pantenol i ekstrakt centele umiruju iritacije i upale, čineći ovu kremu pogodnom i za osetljivu kožu. Redovnom upotrebom, koža postaje hidrirana, blistava i vidno zdravija. Aktivni sastojci PDRN (Polidezoksiribonukleotid iz lososa) PDRN je bioaktivni sastojak dobijen iz DNK lososa, poznat po izuzetnoj sposobnosti regeneracije kože. Doprinosi obnovi oštećenih ćelija, jačanju kožne barijere i poboljšanju ukupne elastičnosti i strukture kože. Njegovo delovanje pomaže u smanjenju vidljivosti postojećih fleka i ujednačavanju tona kože, dok istovremeno deluje preventivno na nastanak novih nepravilnosti. Ima i snažno umirujuće dejstvo, pa je pogodan i za osetljivu i reaktivnu kožu. U ovoj formuli, PDRN značajno doprinosi jačanju kožne barijere i očuvanju mladalačkog izgleda kože. Koža postaje otpornija, čvršća i vizuelno zdravija. Niacinamid (2%) Niacinamid je multifunkcionalni aktivni sastojak koji deluje na posvetljavanje hiperpigmentacija, poboljšanje teksture i jačanje zaštitne funkcije kože. U koncentraciji od 2%, efikasno smanjuje tamne fleke, poboljšava ujednačenost tena i doprinosi smanjenju upalnih procesa. Takođe pomaže u regulaciji proizvodnje sebuma, smanjenju crvenila i obnavljanju prirodne barijere kože. Deluje antioksidativno, štiti kožu od štetnih spoljašnjih uticaja i usporava pojavu znakova starenja. U kombinaciji sa PDRN-om, pruža efikasan tretman za neujednačen i umoran ten. Rezultat je svetlija, čistija i zdravija koža. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Hyaluronic Moisturizing Cream je hidratantna krema formulisana sa PDRN-om iz lososa, niacinamidom i hijaluronskim kiselinama. Namenjena je za smanjenje tvrdokornih fleka, posvetljivanje neujednačenog tena i jačanje kožne barijere.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-PDRN-Pink-Hyaluronic-Moisturizing-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
