INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1008, 84, 'Isntree Green Tea Fresh Cleanser', 'isntree-green-tea-fresh-cleanser', 'Ključne prednosti: Kontrola sebuma: Ekstrakt zelenog čaja pomaže u regulaciji prekomerne proizvodnje sebuma, smanjujući masni sjaj i održavajući pore čistim. Dubinska hidratacija: 4 vrste hijaluronske kiseline prodiru u različite slojeve kože, pružajući intenzivnu hidrataciju i održavajući kožu elastičnom i glatkom. Umirujuće dejstvo: Prirodni ekstrakti, poput ekstrakta zelenog čaja, deluju umirujuće na kožu, smanjujući crvenilo i iritacije, te poboljšavajući ukupni tonus kože. Kome je namenjen? Ovaj čistač je idealan za osobe sa masnom i kombinovanom kožom sklonom prekomernom lučenju sebuma i začepljenim porama. Takođe je pogodan za one koji traže blagi, ali efikasan proizvod koji ne isušuje kožu i pomaže u održavanju njene prirodne ravnoteže. Zašto volimo Isntree Green Tea Fresh Cleanser? Green Tea Fresh Cleanser pruža osvežavajuće iskustvo čišćenja zahvaljujući svojoj laganoj gel formuli. Ona se pri kontaktu s vodom pretvara u bogatu penu. Ekstrakt zelenog čaja sa ostrva Jeju bogat je antioksidansima koji štite kožu od štetnih uticaja slobodnih radikala. Takođe, pomažu u smanjenju upalnih procesa. Četiri vrste hijaluronske kiseline različitih molekularnih težina omogućavaju višeslojnu hidrataciju. Zadržavaju vlagu u koži i sprečavaju njeno isušivanje nakon čišćenja. Aktivni sastojci Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Ekstrakt zelenog čaja bogat je antioksidansima, posebno polifenolima poput EGCG-a, koji štite kožu od oštećenja izazvanih slobodnim radikalima. Ima antiinflamatorna svojstva koja pomažu u smirivanju iritacija i crvenila, čineći ga pogodnim za osetljivu kožu. Takođe, ekstrakt zelenog čaja može regulisati proizvodnju sebuma, što doprinosi smanjenju masnoće kože. Njegova antimikrobna svojstva pomažu u borbi protiv bakterija koje uzrokuju akne. Hijaluronska kiselina Hijaluronska kiselina je moćan humektant koji privlači i zadržava vlagu u koži, pružajući intenzivnu hidrataciju. Pomaže u popunjavanju finih linija i bora, čineći kožu glatkom i elastičnom. Ojačava kožnu barijeru, sprečavajući gubitak vlage i štiteći je od spoljašnjih agresora. Njena mala molekularna masa omogućava dublju penetraciju u slojeve kože. Dodaj u listu želja Dodaj u listu želja', 'Isntree Green Tea Fresh Cleanser je blagi gel čistač formulisan sa ekstraktom zelenog čaja sa ostrva Jeju i 4 vrste hijaluronske kiseline, namenjen efikasnom uklanjanju nečistoća i viška sebuma bez isušivanja kože. Ovaj čistač pomaže u regulaciji proizvodnje sebuma, poboljšava teksturu kože i održava optimalan nivo hidratacije, ostavljajući kožu osveženom i mekom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Isntree-Green-Tea-Fresh-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
