INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1009, 69, 'Haruharu Wonder Black Rice Night Knight Retinol Serum', 'haruharu-wonder-black-rice-night-knight-retinol-serum', 'Ključne prednosti: Poboljšanje teksture kože: Kombinacija retinola i bakučiola deluje sinergijski na obnavljanje površine kože. Smanjenje znakova starenja: Redovnom upotrebom, serum pomaže u smanjenju vidljivosti finih linija i bora. Ujednačavanje tena: Aktivni sastojci pomažu u smanjenju hiperpigmentacija i neujednačenosti boje kože. Kome je namenjen? Ovaj serum je idealan za osobe sa osetljivom kožom koje žele da uvedu retinol u svoju rutinu nege. Takođe je pogodan za sve tipove kože koji teže poboljšanju teksture, smanjenju znakova starenja i ujednačavanju tena. Zašto volimo Haruharu Wonder Black Rice Night Knight Retinol Serum? Black Rice Night Knight Retinol Serum predstavlja savršenu ravnotežu između efikasnosti i nežnosti, zahvaljujući kombinaciji mikroenkapsuliranog retinola i prirodnog ekstrakta bakučiola. Mikroenkapsulirani retinol omogućava postepeno oslobađanje aktivnog sastojka tokom noći, minimizujući iritacije i povećavajući efikasnost u stimulaciji ćelijske obnove. Bakučiol, poznat kao prirodna alternativa retinolu, pruža slične benefite bez potencijalnih iritacija, dodatno pojačavajući anti-age efekte seruma. Obogaćen fermentisanim ekstraktom crnog pirinča, serum pruža snažnu antioksidativnu zaštitu, štiteći kožu od slobodnih radikala i spoljašnjih agresora. Ceramidi i ulje semenki suncokreta doprinose jačanju kožne barijere i održavanju optimalne hidratacije, čineći kožu otpornijom i elastičnijom. Aktivni sastojci Retinol (0.08%) Retinol je klinički dokazan sastojak koji podstiče obnavljanje ćelija i sintezu kolagena, čime poboljšava čvrstoću i elastičnost kože. Pomaže u smanjenju bora, finih linija i hiperpigmentacija, dajući koži glatkiji i ujednačeniji izgled. U koncentraciji od 0.08%, pruža efikasne rezultate uz kontrolisani potencijal iritacije. Takođe deluje komedolitički – otčepljuje pore i smanjuje nastanak akni i mitisera. Retinol ubrzava obnavljanje površinskog sloja kože, čineći ten osveženim i mladalačkim. Idealno je koristiti ga uveče uz obaveznu dnevnu zaštitu od sunca. Bakuchiol (1%) Bakuchiol je biljna alternativa retinolu koja pruža slične benefite, ali bez iritacija i suvoće. Kliničke studije pokazuju da podstiče sintezu kolagena i elastina, čime poboljšava čvrstoću i glatkoću kože. Deluje antioksidativno i antiinflamatorno, što ga čini pogodnim za osetljivu kožu sklonu crvenilu i aknama. Pomaže u smanjenju bora i ujednačavanju tona kože, bez izazivanja ljuštenja ili preosetljivosti. U kombinaciji s retinolom, pruža balans između efikasnosti i podnošljivosti. Koža postaje elastična, glatka i vidno osvežena. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Night Knight Retinol Serum je blagi noćni serum formulisan sa mikroenkapsuliranim retinolom (0,08%) i bakučiolom (1%) za poboljšanje teksture kože, smanjenje finih linija i bora, te ujednačavanje tena. Ovaj serum je posebno dizajniran za osetljivu kožu, pružajući efikasnu, ali nežnu negu tokom noći.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Haruharu-Wonder-Black-Rice-Night-Knight-Retinol-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
