INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1010, 73, 'Heveblue Salmon Caring Centella Toner', 'heveblue-salmon-caring-centella-toner', 'Ključne prednosti: Dubinska hidratacija: Ekstrakt lososovih jaja i hijaluronska kiselina obezbeđuju intenzivnu hidrataciju, poboljšavajući elastičnost i vitalnost kože. Umirujuće dejstvo: Visok sadržaj centela azijatike smiruje iritacije i crvenilo, pružajući osećaj olakšanja za osetljivu kožu. Jačanje kožne barijere: Formulacija sa pH vrednošću 5.5 pomaže u održavanju optimalne ravnoteže kože, jačajući njenu prirodnu zaštitnu barijeru. Kome je namenjen? Ovaj toner je idealan za osobe sa osetljivom, suvom ili iritiranom kožom koje traže rešenje za smanjenje crvenila i poboljšanje hidratacije. Takođe je pogodan za sve tipove kože koji žele da održe balans pH vrednosti i ojačaju kožnu barijeru. Zašto volimo Heveblue Salmon Caring Centella Toner? Salmon Caring Centella Toner pruža potpunu revitalizaciju i zaštitu kože. Visoka koncentracija ekstrakta centela azijatike donosi snažno umirujuće dejstvo, smanjujući upale i crvenilo, dok ekstrakt lososovih jaja bogat hranljivim materijama dubinski hrani i hidrira kožu. Hijaluronska kiselina pomaže u zadržavanju vlage, čineći kožu glatkom i elastičnom. Formulacija sa pH vrednošću 5.5 osigurava optimalnu kiselost kože, što je ključno za njenu zaštitnu funkciju. Redovnom upotrebom, koža postaje otpornija na spoljašnje agresore, dok se njena tekstura i tonus vidno poboljšavaju. Aktivni sastojci Centella Asiatica Leaf Water Voda lista biljke Centella Asiatica poznata je po svom snažnom umirujućem i regenerativnom delovanju. Pomaže u smanjenju crvenila, iritacija i upala, što je čini idealnom za osetljivu i reaktivnu kožu. Bogata je aktivnim komponentama poput madecassoside i asiaticoside, koje jačaju kožnu barijeru. PDRN (Polydeoxyribonucleotide) PDRN je bioaktivna supstanca dobijena iz DNK lososa koja ubrzava regeneraciju ćelija i popravlja oštećeno tkivo. Deluje antiinflamatorno i podržava sintezu kolagena, čime doprinosi obnavljanju strukture kože. Posebno je efikasan kod oslabljene, nadražene i zrele kože. Povećava elastičnost i jača kožnu barijeru, čineći kožu otpornijom na iritacije i spoljne faktore. Houttuynia Cordata Water Voda biljke Houttuynia Cordata poznata je po svojim antibakterijskim i protivupalnim svojstvima. Efikasno čisti kožu od nečistoća i sebuma, pomažući u prevenciji akni i iritacija. Bogata flavonoidima, deluje antioksidativno i štiti kožu od oksidativnog stresa. Salmon Egg Extract Ekstrakt lososovih jaja bogat je proteinima, peptidima i esencijalnim masnim kiselinama koje obnavljaju i hrane kožu. Pomaže u regeneraciji ćelija i jačanju elastičnosti kože. Takođe sadrži antioksidanse koji štite kožu od starenja izazvanog spoljašnjim uticajima. Pruža dubinsku ishranu i revitalizaciju, čineći kožu blistavom i mekom. Dodaj u listu želja Dodaj u listu želja', 'Heveblue Salmon Caring Centella Toner je hidratantni i umirujući tonik formulisan sa visokim sadržajem ekstrakta centela azijatike (830.000 ppm) i ekstrakta lososovih jaja, koji efikasno smanjuje crvenilo, hidrira kožu i jača njenu zaštitnu barijeru. Sa pH vrednošću 5.5, ovaj toner balansira kožu, čineći je otpornijom i blistavijom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Heveblue-Salmon-Caring-Centella-Toner-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
