INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1011, 73, 'Heveblue Salmon Caring Centella Ampoule', 'heveblue-salmon-caring-centella-ampoule', 'Ključne prednosti: Intenzivna hidratacija: Hijaluronska kiselina i njeni derivati dubinski hidriraju kožu, povećavajući njenu elastičnost i smanjujući pojavu finih linija. Umirujuće dejstvo: Ekstrakt centela azijatike i madekasozaid deluju protivupalno, smanjujući crvenilo i iritacije, čineći kožu smirenijom i ujednačenijom. Regeneracija kože: Ekstrakt lososovih jaja bogat je hranljivim materijama koje podstiču regeneraciju kože, poboljšavajući njenu teksturu i tonus. Kome je namenjena? Ova ampula je idealna za osobe sa suvom, osetljivom i iritiranom kožom koja zahteva dubinsku regeneraciju i smanjenje crvenila. Takođe je pogodna za one koji žele poboljšanje elastičnosti i mladalački sjaj kože. Zašto volimo Heveblue Salmon Caring Centella Ampoule? Salmon Caring Centella Ampoule je visokoefikasna formula dizajnirana da pruži intenzivnu negu i obnovu kože. Zahvaljujući kombinaciji lososove DNK, peptida i centelle azijatike, ampula pomaže u jačanju zaštitne barijere kože i smanjenju upalnih procesa. Redovnom upotrebom, koža postaje vidno hidrirana, elastičnija i otpornija na spoljašnje faktore. Peptidi u sastavu podstiču sintezu kolagena, što doprinosi čvrstoći kože i smanjenju bora, dok centella azijatika deluje umirujuće, smanjujući crvenilo i iritacije. Ampula je lagane teksture i brzo se upija, ostavljajući kožu osveženom i glatkom, bez osećaja lepljivosti. Aktivni sastojci Centela azijatika (Centella Asiatica Extract) : Poznata i kao gotu kola ili tigrova trava, ovaj ekstrakt se vekovima koristi u tradicionalnoj medicini za lečenje manjih rana, opekotina i ogrebotina zbog svojih protivupalnih i antioksidativnih svojstava. Sadrži aktivne komponente poput azijatikozida i madekasoida, koji stimulišu sintezu hijaluronske kiseline u koži, poboljšavajući njenu hidrataciju i elastičnost. Ekstrakt lososovih jaja (Salmon Egg Extract) : Ovaj ekstrakt je bogat esencijalnim masnim kiselinama, proteinima i vitaminima koji hrane i revitalizuju kožu. Masne kiseline pomažu u održavanju integriteta kožne barijere, smanjujući gubitak vlage i štiteći kožu od spoljašnjih agresora. Proteini doprinose regeneraciji tkiva, poboljšavajući teksturu i tonus kože. Vitamini, posebno vitamini A i D, podržavaju zdravlje kože, pospešujući obnavljanje ćelija i pružajući antioksidativnu zaštitu. Hijaluronska kiselina – Ovaj moćni humektant privlači i zadržava vlagu u koži, čineći je hidriranom i punijom. Njegova sposobnost vezivanja vode pomaže u smanjenju finih linija i bora, dok istovremeno poboljšava elastičnost kože. Takođe jača prirodnu barijeru kože, smanjujući gubitak vlage i štiteći od isušivanja. Pogodna je za sve tipove kože, uključujući i one sklone iritacijama. Dodaj u listu želja Dodaj u listu želja', 'Heveblue Salmon Caring Centella Ampoule je intenzivno regenerativna ampula formulisana sa ekstraktom lososove DNK i centelom azijatikom, pružajući koži dubinsku hidrataciju, umirenje i poboljšanu elastičnost. Ova moćna kombinacija sastojaka pomaže u obnovi oštećene kože, smanjuje crvenilo i poboljšava ukupnu teksturu tena.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Heveblue-Salmon-Caring-Centella-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
