INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1012, 39, 'COS DE BAHA Salicylic Acid 4% serum', 'cos-de-baha-salicylic-acid-4-serum', 'Ključne prednosti: Dubinski čisti pore i smanjuje akne tako što uklanja višak sebuma i nečistoće, sprečavajući njihovo zapušavanje. Reguliše lučenje sebuma i smanjuje masni sjaj, održavajući kožu uravnoteženom i svežom. Ublažava crvenilo i iritacije zahvaljujući svojim protivupalnim svojstvima, čineći kožu vidno smirenijom. Kome je namenjen? Serum je idealan za masnu, kombinovanu i problematičnu kožu sklonu aknama, mitiserima i proširenim porama. Takođe, pogodan je za osobe koje žele da poboljšaju teksturu kože i smanje nepravilnosti. Zašto volimo COS DE BAHA Salicylic Acid 4% serum ? Salicylic Acid 4% serum deluje kao snažan tretman za problematičnu kožu sklonu nepravilnostima. Salicilna kiselina prodire duboko u pore i rastvara višak sebuma, čime sprečava njihovo zapušavanje i smanjuje pojavu akni i mitisera. Zahvaljujući blagim eksfolijativnim svojstvima, serum pomaže u uklanjanju mrtvih ćelija sa površine kože, čineći ten glatkim i osveženim. Redovnom upotrebom koža postaje uravnoteženija, dok se pore postepeno sužavaju. Njegova formula sadrži hidratantne i umirujuće sastojke koji smanjuju rizik od iritacija i održavaju kožu hidriranom, čineći ga pogodnim čak i za osetljiviju kožu koja je sklona crvenilu. Aktivni sastojci Salicilna kiselina (4%) Salicilna kiselina je beta-hidroksi kiselina (BHA) koja prodire duboko u pore i rastvara višak sebuma i nečistoće. Pruža snažnu eksfolijaciju, uklanjajući mrtve ćelije kože i smanjujući mogućnost zapušavanja pora. Ima protivupalna svojstva koja pomažu u smanjenju crvenila i otoka povezanih sa aknama. Redovnom upotrebom, poboljšava teksturu kože, smanjuje pojavu mitesera i sprečava nastanak novih bubuljica. Takođe doprinosi ujednačavanju tena i smanjenju hiperpigmentacija. Preporučuje se postepeno uvođenje u rutinu nege kako bi se izbegla prekomerna suvoća ili iritacija. Dodaj u listu želja Dodaj u listu želja', 'COS DE BAHA Salicylic Acid 4% serum je visokoefikasan tretman za problematičnu kožu koji dubinski čisti pore, reguliše lučenje sebuma i smanjuje akne. Formulisan sa salicilnom kiselinom, pruža nežnu eksfolijaciju, pomaže u uklanjanju mitisera i sprečava nastanak novih nepravilnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/01/COS-DE-BAHA-Salicylic-Acid-4-serum-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
