INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1014, 65, 'Fwee Pink Obsession Stay-Fit Lip Tint', 'fwee-pink-obsession-stay-fit-lip-tint', 'Ključne prednosti: Postojanost i dugotrajnost: Boja za usne koja se ne razmazuje i ne isušuje usne, uz zadržavanje boje tokom celog dana. Hidratacija i nega: Aktivni sastojci pružaju dubinsku hidrataciju i štite usne od isušivanja. Prirodno lep izgled: Bogate pigmentacije daju efekt prirodnog ružičastog sjaja, uz udobnost bez osećaja težine. Kome je namenjen? Pink Obsession Stay-Fit Lip Tint namenjen je svima koji žele dugotrajnu boju i negu usana u jednom proizvodu. Idealno za osobe sa suvim usnama koje traže postojan, ali udoban proizvod koji ne isušuje. Zašto volimo Fwee Pink Obsession Stay-Fit Lip Tint? Pink Obsession Stay-Fit Lip Tint kombinuje intenzitet boje i dugotrajnost sa negom usana, pružajući optimalan balans između estetike i udobnosti. Njegova formula obogaćena prirodnim uljima i hidratantnim agensima neguje usne, sprečava isušivanje i osigurava njihovu mekoću tokom celog dana. Zahvaljujući laganoj teksturi, tinta se lako nanosi i brzo se fiksira, pružajući ravnomeran premaz koji se ne razmazuje. Boja ostaje postojana i živahna, dok usne deluju prirodno osveženo. Ovaj proizvod se može koristiti samostalno za prirodan izgled ili u kombinaciji sa sjajem za dodatni efekat. Dodaj u listu želja Dodaj u listu želja', 'Fwee Pink Obsession Stay-Fit Lip Tint pruža dugotrajnu boju usana sa postojanošću koja traje satima, ostavljajući usne mekanima i hidriranim. Formula je obogaćena hranljivim sastojcima koji neguju usne, dok intenzivne pigmentacije pružaju efekat prirodno ružičastih usana.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Fwee-Pink-Obsession-Stay-Fit-Lip-Tint.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
