INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1015, 65, 'Fwee 4D Voluming Plumper', 'fwee-4d-voluming-plumper', 'Ključne prednosti: Trenutna punoća: Specijalna formula stvara efekat volumena, čineći usne punijima i privlačnijima. Hidratacija i nega: Kombinacija hijaluronske kiseline i prirodnih ulja pruža dubinsku hidrataciju i obnavlja isušene usne. 4D sjaj: Poseban završni sloj obezbeđuje visok sjaj i luksuzan izgled, idealan za sve prilike. Kome je namenjen? Fwee 4D Voluming Plumper je namenjen svima koji žele da postignu efekat punijih, glatkijih usana uz dodatnu hidrataciju. Idealan je za osobe sa suvim usnama koje žele da im dodaju volumen i sjaj, uz negu i zaštitu. Zašto volimo Fwee 4D Voluming Plumper? 4D Voluming Plumper kombinuje naučno razvijenu tehnologiju sa hranljivim sastojcima kako bi pružio trenutni efekat punijih usana. Njegova formula obogaćena hijaluronskom kiselinom dubinski hidrira usne, čineći ih mekanima i otpornima na isušivanje. Prirodna ulja i vitamini pružaju dodatnu negu i zaštitu, dok posebna tehnologija volumizacije stvara vizuelni efekat punoće koji traje satima. Sjajna završnica ovog proizvoda dodatno ističe oblik usana i daje im luksuzan izgled, savršen za svakodnevno nošenje ili posebne prilike. Uz redovnu upotrebu, usne postaju hidrirane, negovane i vizuelno poboljšane. Dodaj u listu želja Dodaj u listu želja', 'Fwee 4D Voluming Plumper je sjaj za negu usana koji pruža trenutan efekat punoće i dugotrajnu hidrataciju. Obogaćen aktivnim sastojcima poput hijaluronske kiseline i prirodnih ulja, ovaj proizvod dodatno njeguje i štiti usne, čineći ih vizuelno punijima i glatkima.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Fwee-4D-Voluming-Plumper.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
