INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1016, 65, 'Fwee 3D Changing Gloss', 'fwee-3d-changing-gloss', 'Ključne prednosti: Prilagodljiva boja: Formula reaguje na pH usana, stvarajući personalizovanu nijansu koja savršeno odgovara svakom korisniku. Hidratacija i nega: Hranljivi sastojci poput biljnih ulja i hijaluronske kiseline pružaju dubinsku hidrataciju i negu. Lagani finiš: Nelepljiva tekstura omogućava ugodno nošenje tokom celog dana, uz visok nivo sjaja. Kome je namenjen? Fwee 3D Changing Gloss je idealan za sve tipove kože i namenjen svima koji žele sjajne, negovane usne sa jedinstvenom nijansom. Savršen je za svakodnevnu upotrebu, kao i za posebne prilike kada je potrebna dodatna elegancija. Zašto volimo Fwee 3D Changing Gloss? 3D Changing Gloss je više od običnog sjaja – njegova jedinstvena tehnologija omogućava da se boja prilagodi prirodnoj pH vrednosti usana, kreirajući jedinstvenu nijansu za svakog korisnika. Zahvaljujući obogaćenoj formuli, ovaj sjaj hidrira usne, čineći ih glatkima i zdravima. Hijaluronska kiselina pomaže u zadržavanju vlage, dok prirodna ulja pružaju zaštitu od spoljašnjih uticaja. Sjajna, nelepljiva tekstura omogućava lako nanošenje i dugotrajnu udobnost, čineći ga savršenim izborom za svakodnevnu rutinu ili posebne prilike. 3D efekat pruža iluziju punijih usana, a formula bez štetnih sastojaka čini ga sigurnim za osetljivu kožu. Aktivni sastojci Hijaluronska kiselina Ovaj moćni hidratantni sastojak zadržava vlagu u usnama, pružajući im punoću i glatkoću. Hijaluronska kiselina stvara zaštitni sloj koji sprečava isušivanje usana i održava ih mekanima tokom celog dana. Pomaže u smanjenju sitnih linija, čineći usne vizuelno mlađima. Prirodna biljna ulja Biljna ulja, poput ulja jojobe i suncokreta, pružaju dubinsku ishranu i zaštitu usana od štetnih spoljašnjih uticaja. Ova ulja omekšavaju usne i održavaju njihovu elastičnost, dok istovremeno obnavljaju oštećenja i umiruju iritacije. Vitamin E Kao snažan antioksidans, vitamin E štiti usne od slobodnih radikala i podržava prirodnu regeneraciju kože. On pomaže u održavanju usana mekanima, glatkima i otpornim na spoljašnje uticaje. Dodaj u listu želja Dodaj u listu želja', 'Fwee 3D Changing Gloss je sjaj za usne koji pruža jedinstveni efekat promenljive boje, prilagođavajući se pH vrednosti usana. Obogaćen hranljivim sastojcima, ovaj sjaj hidrira, štiti i istovremeno pruža blistav, 3D završni sjaj.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Fwee-3D-Changing-Gloss-0-Clear.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
