INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1017, 65, 'Fwee 3D Voluming Gloss', 'fwee-3d-voluming-gloss', 'Ključne prednosti: Voluminizujući efekat: Zahvaljujući hijaluronskoj kiselini, usne dobijaju prirodno puniji izgled uz dodatnu hidriranost. Lagani finiš: Sjajna formula koja nije lepljiva, pruža dugotrajnu udobnost i savršen završni sloj. Negujući sastojci: Obogaćen prirodnim uljima i ekstraktima koji hrane usne, ostavljajući ih mekanima i zdravima. Kome je namenjen? Fwee 3D Voluming Gloss je idealan za sve koji žele trenutni efekat punijih, sjajnijih usana uz negu i hidrataciju. Pogodan je za sve tipove kože, uključujući i osetljive usne, i može se koristiti samostalno ili preko omiljenog ruža. Zašto volimo Fwee 3D Voluming Gloss? 3D Voluming Gloss pruža trenutno osveženje usana, čineći ih hidriranim, punijim i blistavim. Njegova lagana formula savršena je za svakodnevnu upotrebu, jer ne ostavlja osećaj težine niti lepljivost na usnama. Efekat volumena dolazi iz hijaluronske kiseline koja privlači vlagu i vizuelno povećava punoću usana, dok prirodni ekstrakti dodatno hrane i štite usne od isušivanja. Luksuzan sjaj koji ovaj proizvod pruža stvara sofisticiran izgled, dok se suptilni sloj lako nanosi i zadržava dugotrajan sjaj. Može se koristiti samostalno za prirodan izgled ili kao završni sloj preko ruža kako bi se postigao savršen finiš. Dodaj u listu želja Dodaj u listu želja', 'Fwee 3D Voluming Gloss je sjaj za usne koji pruža trenutni efekat punijih i hidriranih usana, zahvaljujući pažljivo odabranim sastojcima poput hijaluronske kiseline i biljnih ekstrakata. Njegova lagana, nelepljiva formula omogućava dugotrajnu hidrataciju i luksuzan sjaj sa suptilnim 3D voluminizujućim efektom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Fwee-3D-Voluming-Gloss.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
