INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1020, 164, 'Tirtir Silver Mask Fit Aura Silver Cushion', 'tirtir-mask-fit-aura-silver-cushion', 'Ključne prednosti: Prirodno prekrivanje: Omogućava besprekoran i prirodan izgled kože bez osećaja težine. Dubinska hidratacija: Formulisan sa sastojcima koji održavaju optimalan nivo vlage tokom celog dana. Antioksidativna zaštita: Sadrži hranljive komponente koje štite kožu od spoljašnjih agresora. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, posebno za osobe koje žele prirodan i ujednačen izgled tena uz dodatnu hidrataciju. Pogodan je za svakodnevnu upotrebu i pruža dugotrajnu svežinu čak i u uslovima visokog stresa ili vlažnosti. Zašto volimo TIRTIR Mask Fit Aura Silver Cushion? Mask Fit Red Mini Cushion donosi savršenu kombinaciju visoke pokrivne moći i lagane teksture. Omoguća koži da diše dok ostavlja besprekornu završnicu. Polumat efekat pruža balans između hidratacije i kontrole masnoće, čineći ga idealnim za celodnevno nošenje. Njegova formula sadrži prirodne antioksidante koji štite kožu od štetnih spoljašnjih uticaja. Puder se ne prenosi i otporan je na znoj, što ga čini pogodnim za aktivan stil života ili nošenje pod maskom. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit Aura Silver Cushion je puder u jastučiću koji pruža dugotrajno prekrivanje, prirodan sjaj i dubinsku hidrataciju zahvaljujući naprednim formulacijama sa hidratantnim i antioksidativnim sastojcima. Nijanse detaljno možete pogledati na zvaničnom sajtu preparata.', 'https://beauty-health.rs/wp-content/uploads/2025/01/TIRTIR-Mask-Fit-Aura-Silver-Cushion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
