INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1025, 174, 'VT Cosmetics VTVT Cica Reti-A Cream 0.05', 'vt-cosmetics-vtvt-cica-reti-a-cream-0-05', 'Ključne prednosti: Efikasno smanjuje bore i fine linije: Retinol stimuliše proizvodnju kolagena i poboljšava elastičnost kože. Pruža umirujuću i hidratantnu negu: Centela asiatika i dodatni hidratantni sastojci umiruju iritacije i održavaju kožu hidratizovanom. Uravnotežuje ten i rešava akne: Deluje na neujednačen ton kože i pomaže u borbi protiv akni i proširenih pora. Kome je namenjen? Idealan je za osobe sa zrelom kožom koje žele da smanje vidljivost bora i poboljšaju elastičnost. Takođe je pogodan za masnu ili kombinovanu kožu sklonu aknama i ožiljcima, kao i za one sa osetljivom kožom koja zahteva balansiranu negu. Zašto volimo VT Cosmetics VTVT Cica Reti-A Cream 0.05? VTVT Cica Reti-A Cream 0.05 kombinuje snagu retinola sa umirujućim svojstvima centela asiatike kako bi pružio vidljive rezultate u borbi protiv starenja i problema sa teksturom kože. Retinol u koncentraciji od 0.05% stimuliše regeneraciju ćelija i sintezu kolagena, čineći kožu glatkijom i elastičnijom. Zahvaljujući prisustvu centela asiatike, krem istovremeno umiruje crvenilo i iritacije, što ga čini sigurnim za redovnu upotrebu čak i kod osetljive kože. Pored toga, hijaluronska kiselina i ceramidi intenzivno hidrira kožu, čineći je mekanom i zaštićenom od isušivanja. Aktivni sastojci Hydroxypinacolone Retinoate (HPR) Hydroxypinacolone Retinoate je stabilan retinoidni derivat koji deluje direktno na retinoidne receptore u koži bez potrebe za metaboličkom aktivacijom. U ovoj formuli koristi se u visokoj čistoći (99%), što obezbeđuje brze i efikasne rezultate u poboljšanju teksture kože. HPR stimuliše sintezu kolagena, smanjuje fine linije i bore, i doprinosi ujednačenom tonu kože. Deluje i na regulaciju sebuma i sužavanje pora, što ga čini pogodnim za masnu i kombinovanu kožu. Za razliku od klasičnih oblika retinola, ima niži potencijal za iritaciju i pogodan je za osetljivu kožu. Cicahylon&#x2122; Cicahylon&#x2122; je patentirani kompleks koji sadrži ekstrakt Centella Asiatica i tri vrste hijaluronske kiseline, formulisan za intenzivnu hidrataciju i umirenje kože. Centella Asiatica ima protivupalna i regenerativna svojstva, ubrzava zarastanje i jača kožnu barijeru. Hijaluronske kiseline različite molekulske mase deluju u više slojeva kože, obezbeđujući dugotrajnu hidrataciju i elastičnost. Ovaj kompleks pomaže u umanjivanju potencijalnih iritacija koje mogu nastati usled delovanja retinoida. Povećava otpornost kože na spoljne faktore i doprinosi oporavku i balansu kože. Centella Asiatica Extract Ekstrakt Centella Asiatica poznat je po svojim umirujućim i obnavljajućim svojstvima, naročito kod osetljive i upaljene kože. Deluje antiinflamatorno i stimuliše proizvodnju kolagena, što doprinosi čvrstoći i elastičnosti kože. Ubrzava regeneraciju kože nakon oštećenja i pomaže u smanjenju crvenila i iritacija. Zbog svojih adaptogenih svojstava, idealan je u formulacijama koje sadrže aktivne sastojke poput retinoida. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics VTVT Cica Reti-A Cream 0.05 je tretman sa retinolom formulisan za poboljšanje teksture kože, smanjenje vidljivosti bora i regulaciju problema kao što su akne i neujednačen ten. Obogaćen centelom asiatikom i umirujućim sastojcima, ovaj krem pruža balansiranu njegu koja je pogodna i za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/01/VT-Cosmetics-VTVT-Cica-Reti-A-Cream-0.05.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
