INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1026, 164, 'Tirtir Niacinamide 20% Serum', 'tirtir-niacinamide-20-serum', 'Ključne prednosti: Ujednačava ten i smanjuje hiperpigmentacije: Visoka koncentracija niacinamida efikasno posvetljuje tamne mrlj. Smanjuje pore i kontroliše sebum: Pomaže u regulaciji lučenja sebuma i smanjuje veličinu pora. Dubinska hidratacija i jačanje barijere: Sadrži hijaluronsku kiselinu za intenzivnu hidrataciju i jačanje zaštitne barijere kože. Kome je namenjen? Serum je idealan za sve tipove kože, posebno za one sa problemima hiperpigmentacija, proširenih pora i masne kože. Takođe je pogodan za zrelu kožu koja pokazuje znakove starenja, poput finih linija i gubitka elastičnosti. Zašto volimo TIRTIR Niacinamide 20% Serum? Niacinamide 20% serum nudi sveobuhvatnu negu kože, kombinujući snažne aktivne sastojke za rešavanje različitih problema kože. Visoka koncentracija niacinamida smanjuje tamne mrlje i osvetljava ten, dok alfa-arbutin dodatno ujednačava pigmentaciju. Glutation, snažan antioksidans, štiti kožu od oksidativnog stresa i podstiče njen zdrav izgled. Hijaluronska kiselina pruža dubinsku hidrataciju, dok retinol podstiče sintezu kolagena, smanjujući fine linije i bore. Formula takođe sadrži cink PCA, koji kontroliše lučenje sebuma i umiruje kožu, čineći ovaj serum idealnim za masnu i aknama sklonu kožu. Aktivni sastojci Niacinamid (20%) Visok procenat niacinamida deluje efikasno na posvetljavanje tena, smanjenje hiperpigmentacija i regulaciju lučenja sebuma. Vidljivo sužava pore i poboljšava teksturu kože. Takođe jača kožnu barijeru i smanjuje upalne procese, čineći kožu otpornijom i ujednačenijom. Alpha-Arbutin Snažan posvetljujući agens koji inhibira proizvodnju melanina, pomažući u uklanjanju tamnih mrlja i postupalnih fleka. Blag je prema koži, ali izuzetno efikasan u borbi protiv hiperpigmentacija. Poboljšava blistavost i tonus kože bez iritacija. Glutation Prirodni antioksidans koji detoksikuje i posvetljuje kožu. Smanjuje oksidativni stres i sprečava nastanak novih pigmentacija. Doprinosi mladalačkom, ujednačenom i osveženom izgledu kože. Hijaluronska kiselina (višestruki molekularni oblici) Dubinski hidrira i zadržava vlagu u različitim slojevima kože. Povećava elastičnost, smanjuje osećaj zatezanja i poboljšava ukupnu otpornost kože. Ostavlja kožu mekom, punom i osveženom. Retinol Pomaže u borbi protiv znakova starenja, poput finih linija i gubitka elastičnosti. Podstiče regeneraciju ćelija i sintezu kolagena. Deluje revitalizujuće i obnavljajuće na umornu kožu. Zinc PCA Reguliše proizvodnju sebuma i ima antibakterijsko delovanje, idealno za kožu sklonu aknama. Umiruje upale i doprinosi čistijem, ujednačenijem tenu. Takođe pomaže u očuvanju balansa vlage u koži. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Niacinamide 20% serum je visokokoncentrovani proizvod formulisan sa 20% niacinamida za ujednačavanje tena, kontrolu sebuma i intenzivnu hidrataciju. Pomaže u smanjenju hiperpigmentacija, bora i proširenih pora, ostavljajući kožu glatkom, blistavom i elastičnom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/TIRTIR-Niacinamide-20-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
