INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1028, 154, 'Skin1004 Madagascar Centella Poremizing Deep Cleansing Foam', 'skin1004-madagascar-centella-poremizing-deep-cleansing-foam', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja višak sebuma i nečistoće iz pora uz pomoć prirodnih glina i ekstrakta centelle asiatice. Smirivanje i obnavljanje kože: Centella asiatica umiruje iritacije i pomaže u regeneraciji kože, čineći je otpornijom na spoljne uticaje. Ravnoteža hidratacije: Ne isušuje kožu, već održava njen prirodni nivo vlage, pružajući osećaj svežine i čistoće nakon svakog korišćenja. Kome je namenjen? Ovaj proizvod je idealan za masnu i mešovitu kožu, kao i za kožu sa proširenim porama i f, sklonošću ka aknama. Pogodan je za sve koji traže nežnu, ali efikasnu penu za čišćenje koja ne narušava prirodnu barijeru kože. Zašto volimo Skin1004 Madagascar Centella Poremizing Deep Cleansing Foam? Madagascar Centella Poremizing Deep Cleansing Foam nudi sveobuhvatno rešenje za probleme sa porama i viškom sebuma. Zahvaljujući glini, dubinski čisti pore i uklanja nečistoće koje se nakupljaju tokom dana, dok centella asiatica pruža umirujuće i regenerativne efekte. Pena održava pH ravnotežu kože, čineći je svežom i mekom bez osećaja zatezanja. Redovnom upotrebom, pore postaju manje vidljive, a koža zadržava svoj prirodni sjaj. Formula je dovoljno nežna za svakodnevnu upotrebu i ne izaziva iritacije, čak ni kod osetljive kože. Savršena je za održavanje zdrave, čiste i balansirane kože, naročito u urbanim sredinama gde je koža izložena svakodnevnom zagađenju. Aktivni sastojci Centella Asiatica Extract Centella Asiatica pruža snažno umirujuće i regenerativno dejstvo, što ovu formulu čini idealnom za osetljivu kožu. Deluje protivupalno i pomaže u ublažavanju crvenila i iritacija koje mogu nastati tokom čišćenja. Takođe ubrzava zarastanje mikrolezija i jača zaštitnu barijeru kože. U kombinaciji sa piling i detoks sastojcima, Centella obezbeđuje balans – dubinsko čišćenje bez kompromitovanja hidratacije i komfora. Pink Himalayan Salt Ružičasta himalajska so bogata je mineralima poput magnezijuma, kalijuma i kalcijuma, koji pomažu u detoksikaciji i remineralizaciji kože. U ovoj formuli, deluje kao prirodni čistač koji uklanja toksine, pročišćava pore i smanjuje višak sebuma. Njena nežna granulacija doprinosi blagoj eksfolijaciji bez iritacije. Posebno pogodna za masnu i kombinovanu kožu, kao i za kožu sa začepljenim porama. Papain Papain je prirodni enzim iz papaje koji deluje kao blag hemijski eksfolijant, pomažući u uklanjanju mrtvih ćelija sa površine kože. Njegovo dejstvo doprinosi osvetljavanju tena, poboljšanju teksture i prevenciji zapušavanja pora. Deluje bez abrazije, pa je pogodan čak i za osetljivu kožu. U ovoj formulaciji, sinergijski deluje sa Centellom i kaolinom za sveobuhvatnu negu i osveženje. Kaolin Kaolin je nežna glina koja upija višak sebuma i uklanja nečistoće iz pora bez isušivanja kože. U ovoj peni za čišćenje, pomaže u pročišćavanju tena, matiranju i sužavanju proširenih pora. Takođe deluje umirujuće i pomaže kod upalnih procesa, čineći ga pogodnim za aknoznu i reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Poremizing Deep Cleansing Foam je pena za čišćenje lica obogaćena ekstraktom centelle asiatice sa Madagaskara i glinom, namenjena dubinskom čišćenju pora i kontroli sebuma. Ovaj proizvod uklanja nečistoće, smanjuje vidljivost pora i ostavlja kožu osveženom, balansiranom i glatkom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Skin1004-Madagascar-Centella-Poremizing-Deep-Cleansing-Foam.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
