INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1031, 143, 'Round Lab Birch Moisturizing Sunscreen', 'round-lab-birch-moisturizing-sunscreen', 'Ključne prednosti: Visok nivo UV zaštite: SPF 50+ PA++++ štiti kožu od štetnog UV zračenja, sprečavajući oštećenja. Dubinska hidratacija: Brezin sok i hijaluronska kiselina pružaju intenzivnu vlagu i osvežavaju kožu. Ujednačen ton kože: Niacinamid posvetljuje ten i smanjuje vidljivost tamnih mrlja. Kome je namenjen? Birch Moisturizing Sunscreen je savršen za sve tipove kože, uključujući osetljivu i suvu kožu koja zahteva dodatnu hidrataciju i zaštitu od sunca. Idealan je za svakodnevnu upotrebu, posebno za one koji traže laganu i nemasnu formulu. Zašto volimo Round Lab Birch Moisturizing Sunscreen? Ova krema za sunčanje pruža optimalnu zaštitu od UVA i UVB zračenja zahvaljujući visokom faktoru SPF 50+ PA++++, čime sprečava fotostarenje i pigmentacije. Obogaćena brezinim sokom, poznatim po svojim umirujućim i hidratantnim svojstvima, trenutno osvežava i revitalizuje kožu, pružajući joj dugotrajnu vlagu. Hijaluronska kiselina dodatno hidrira kožu, popunjavajući fine linije i čineći je elastičnijom. Niacinamid posvetljuje ten i smanjuje crvenilo. Blaga, brzo upijajuća formula ne ostavlja beli trag i ne opterećuje pore. Aktivni sastojci Glyceryl Glucoside Glyceryl glucoside je inovativni hidratantni sastojak koji stimuliše prirodne antioksidativne enzime u koži, povećavajući njenu otpornost na spoljne agresore poput UV zračenja i zagađenja. Takođe doprinosi očuvanju vlažnosti i smanjuje sklonost kože ka dehidrataciji, naročito pod uticajem sunca i vetra. U ovoj kremi za sunčanje, glyceryl glucoside deluje kao zaštitna i balansirajuća komponenta koja održava kožu hidriranom tokom celog dana. Njegovo dejstvo podržava prirodnu regeneraciju ćelija i čini ten ujednačenim i zdravim. Posebno je koristan kod suve i osetljive kože. Pruža optimalan balans hidratacije i zaštite. Homosalate Homosalate je UVB filter koji efikasno apsorbuje UVB zrake i štiti kožu od opekotina, fotostarenja i oštećenja DNK. Deluje tako što pretvara UV zračenje u toplotu, sprečavajući njegov štetan uticaj na ćelije kože. U ovoj formulaciji obezbeđuje visoku UV zaštitu (SPF), čineći proizvod pogodnim za svakodnevnu i produženu izloženost suncu. Njegovo dejstvo je stabilno i bezbedno u kombinaciji sa drugim filterima. Idealno za one koji traže laganu, nekomedogenu i efikasnu zaštitu. Pogodan je za sve tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Birch Moisturizing Sunscreen je lagana, hidratantna krema za zaštitu od sunca sa SPF 50+ PA++++, koja kombinuje zaštitu od UV zračenja i intenzivnu hidrataciju. Sadrži brezin sok, hijaluronsku kiselinu i niacinamid, čineći kožu osveženom, zaštićenom i negovanom tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Round-Lab-Birch-Moisturizing-Sunscreen.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
