INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1032, 143, 'Round Lab Soybean Panthenol Ampoule', 'round-lab-soybean-panthenol-ampoule', 'Ključne prednosti: Dubinska hidratacija i obnova: Pantenol i hijaluronska kiselina intenzivno hidriraju kožu i vraćaju joj elastičnost. Regeneracija i jačanje barijere: Fermentisani sojin ekstrakt revitalizuje kožu i jača njenu prirodnu zaštitnu funkciju. Smanjenje crvenila i umirivanje kože: Formula bogata antiinflamatornim svojstvima smanjuje iritacije i vraća balans osetljivoj koži. Kome je namenjen? Ovaj serum je idealan za osobe sa suvom, osetljivom ili iritiranom kožom koja zahteva dodatnu negu i hidrataciju. Takođe, pogodan je za sve tipove kože, uključujući kožu sklonu crvenilu ili dehidraciji. Zašto volimo Round Lab Soybean Panthenol Ampoule? Soybean Panthenol Ampoule koristi visokokoncentrovani pantenol kako bi obezbedio dubinsku hidrataciju i umirio osetljivu kožu. Fermentisani sojin ekstrakt bogat antioksidansima pomaže u obnavljanju oštećene barijere kože, vraćajući joj vitalnost i svežinu. Formula je obogaćena hijaluronskom kiselinom, koja zadržava vlagu u koži i poboljšava njenu teksturu. Niacinamid dodatno posvetljuje kožu, ujednačava njen ton i smanjuje pojavu tamnih fleka. Njegova lagana, ali bogata tekstura brzo se upija, ostavljajući kožu mekanom, zategnutom i osveženom. Aktivni sastojci Glycerin Glicerin je moćan humektant koji privlači vlagu iz okoline i vezuje je u koži, pružajući intenzivnu i dugotrajnu hidrataciju. U ovoj ampuli, glicerin osvežava površinu kože, ublažava suvoću i deluje kao emolijens koji omekšava gruba i dehidrirana područja. Njegovo dejstvo pomaže u očuvanju elastičnosti kože i smanjuje zategnutost. Redovnom upotrebom, koža postaje vidno mekša, nahranjena i otpornija na spoljne uticaje. Pogodan je za sve tipove kože, uključujući i osetljivu. Ne izaziva iritacije i pruža osećaj udobnosti tokom celog dana. Glycine Max (Soybean) Seed Extract Ekstrakt semena soje bogat je antioksidansima kao što su vitamin E i genistein, koji pomažu u posvetljavanju hiperpigmentacija i balansiranju tena. U ovoj formulaciji, deluje na smanjenje vidljivosti fleka izazvanih suncem i starenjem, čineći kožu ujednačenijom i blistavijom. Takođe ima regenerativna svojstva i doprinosi zdravijem izgledu kože kroz zaštitu od slobodnih radikala. Njegovo dejstvo jača barijernu funkciju i pruža dodatnu negu umornoj i neujednačenoj koži. Posebno je efikasan kod tena sa znakovima fotostarenja. Bezbedan je za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Soybean Panthenol Ampoule je moćan serum formulisan sa fermentisanim sojinim ekstraktom i pantenolom, osmišljen za intenzivnu hidrataciju, regeneraciju i jačanje barijere kože. Njegova formula efikasno smiruje iritacije, obnavlja oštećenu kožu i pruža dugotrajan osećaj svežine i elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Round-Lab-Soybean-Panthenol-Ampoule-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
