INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1034, 138, 'Pyunkang Yul Black Tea Line Gift Set', 'pyunkang-yul-black-tea-line-gift-set', 'Šta set sadrži? Black Tea Toner (130 ml). Tonik s koncentrisanom snagom fermentisanog crnog čaja pomaže u zatezanju i revitalizaciji kože sklone borama. Obogaćen ekstraktom pelina, biljke poznate po otpornosti i vitalnosti, tonik pruža osvežavajuću negu za grubu i umornu kožu. Sastojci poput peptida i adenozina obezbeđuju koži zdrav izgled, dok niacinamid pomaže u posvetljavanju i hidrataciji kože. Black Tea Serum (45 ml). Ovaj serum sadrži kondenzovani fermentisani crni čaj, koji pruža snažno regenerativno dejstvo za kožu sklonu borama. Obogaćen ekstraktom ploda ženšena, bogatim ključnim hranljivim materijama ženšena, dubinski hrani kožu i vraća joj izgubljenu vitalnost. Peptidi i adenozin dodatno doprinose zdravom i mladalačkom izgledu kože. Black Tea Cream (60 ml). Hidratantna krema koja koristi antioksidativnu energiju fermentisanog crnog čaja za regeneraciju i zaštitu kože. Sadrži sastojke za posvetljivanje i smanjenje bora, pružajući koži svežinu, elastičnost i zdrav sjaj. Ključne prednosti: Snažna anti-age zaštita: Fermentisani crni čaj i peptidi smanjuju pojavu bora i poboljšavaju elastičnost kože. Intenzivna hidratacija: Dubinski hidrira kožu, obnavljajući njenu prirodnu barijeru i pružajući dugotrajan osećaj svežine. Poboljšanje teksture kože: Ujednačava ton kože, smanjuje crvenilo i pruža zdrav, blistav izgled. Kome je namenjen? Ovaj set je idealan za osobe sa zrelom kožom ili kožom koja pokazuje znakove umora i stresa. Takođe je pogodan za sve tipove kože koji traže intenzivnu negu i regeneraciju. Zašto volimo Pyunkang Yul Black Tea Line Gift Set? Yul Black Tea Line Gift Set nudi kompletnu rutinu nege kože, fokusirajući se na regeneraciju, hidrataciju i zaštitu. Fermentisani crni čaj, poznat po svojim snažnim antioksidativnim svojstvima, neutralizuje slobodne radikale i štiti kožu od starenja uzrokovanog spoljašnjim faktorima. U kombinaciji sa peptidima i ceramidima, ovi proizvodi obnavljaju oštećenu kožnu barijeru, povećavaju elastičnost i čvrstinu kože. Niacinamid u sastavu doprinosi smanjenju hiperpigmentacija i ujednačava ton kože, dok hijaluronska kiselina pruža intenzivnu hidrataciju koja traje tokom celog dana. Tekstura proizvoda je lagana, brzo se upija i ostavlja kožu mekom, glatkom i osveženom. Redovnom upotrebom, koža postaje vidno zdravija, zategnutija i blistavija. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Black Tea Line Gift Set je luksuzni set proizvoda za negu kože, obogaćen fermentisanim crnim čajem i moćnim antioksidansima. Ovaj set pruža dubinsku hidrataciju, regeneraciju i zaštitu kože, čineći je blistavom i revitalizovanom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Pyunkang-Yul-Black-Tea-Line-Gift-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
