INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1037, 137, 'Purito Wonder Releaf Centella BB Cushion', 'purito-wonder-releaf-centella-bb-cushion', 'Ključne prednosti: Umirivanje i regeneracija kože: Zahvaljujući ekstraktu centelle asiatice, smanjuje crvenilo i iritacije. Zaštita od sunca: Formula sa SPF 50+ štiti kožu od štetnih UV zraka, sprečavajući prevremeno starenje. Prirodni izgled: Obezbeđuje lagano do srednje prekrivanje, ostavljajući kožu blistavom i ujednačenog tona. Kome je namenjen? Ovaj BB puder je idealan za osobe sa osetljivom, suvom ili kombinovanom kožom, kao i za one koje traže lagan, ali pouzdan proizvod koji pruža ujednačen ton kože i zaštitu od UV zračenja. Zašto volimo Purito Wonder Releaf Centella BB Cushion? Wonder Releaf Centella BB Cushion je savršen spoj nege i šminke, dizajniran da pruži prirodan i blistav izgled kože dok istovremeno hidrira i štiti. Ekstrakt centelle asiatice poznat je po svojim umirujućim i regenerativnim svojstvima. Odličan je za kožu sklonu crvenilu ili iritacijama. Lagana formula omogućava koži da diše. SPF 50+ obezbeđuje efikasnu zaštitu od UV zračenjapr, sečavajući oštećenja od sunca i hiperpigmentacije. BB puder ima kremastu teksturu koja se lako nanosi i pruža dugotrajnu hidrataciju, čineći ga idealnim za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Purito Wonder Releaf Centella BB Cushion je multifunkcionalni BB puder u jastučiću koji pruža srednju pokrivnu moć, umiruje osetljivu kožu i štiti je od spoljašnjih uticaja. Obogaćen ekstraktom centelle asiatice i dodatkom SPF zaštite, ovaj proizvod hidrira, posvetljuje i štiti kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Purito-Wonder-Releaf-Centella-BB-Cushion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
