INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1040, 126, 'Numbuzin No.5 Vitamin Boosting Essential Toner', 'numbuzin-no-5-vitamin-boosting-essential-toner', 'Ključne prednosti: Posvetljivanje tena: Vitamin C smanjuje tamne fleke i ujednačava ten, čineći kožu blistavijom. Hidratacija i obnova: Formula obogaćena vitaminima E i B3 hidrira i jača kožu, smanjujući vidljive znakove starenja. Povećanje elastičnosti: Aktivni sastojci podržavaju proizvodnju kolagena, poboljšavajući čvrstinu i elastičnost kože. Kome je namenjen? Ovaj toner je idealan za osobe koje se bore sa neujednačenim tonom kože, tamnim flekama ili umornim izgledom kože. Pogodan je za sve tipove kože, uključujući masnu, kombinovanu i osetljivu kožu. Zašto volimo Numbuzin No.5 Vitamin Boosting Essential Toner? No.5 Vitamin Boosting Essential Toner je savršeno rešenje za kožu kojoj je potrebna dodatna energija i blistavost. Bogat vitaminom C, toner efikasno posvetljuje tamne fleke i hiperpigmentacije, dok vitamini E i B3 jačaju kožu i pružaju dubinsku hidrataciju. Njegova formula podstiče regeneraciju ćelija, pomaže u borbi protiv znakova starenja i vraća koži elastičnost i glatkoću. Uz redovnu upotrebu, koža postaje meka, sveža i zdravog sjaja. Lagana tekstura omogućava brzo upijanje bez osećaja masnoće, što ga čini pogodnim za jutarnju i večernju rutinu nege kože. Aktivni sastojci Niacinamid (Vitamin B3 – 50,000 ppm) Niacinamid u visokoj koncentraciji od 50,000 ppm deluje izuzetno efikasno na posvetljavanje kože i redukciju hiperpigmentacija. Inhibira prenos melanina, čime pomaže u smanjenju tamnih fleka i ujednačavanju tena. Takođe jača kožnu barijeru, smanjuje transepidermalni gubitak vode i povećava elastičnost. Arbutin Arbutin je prirodni derivat hidrohinona koji deluje na inhibiciju sinteze melanina bez iritirajućeg efekta. Efikasno smanjuje hiperpigmentacije, staračke pege i neujednačen ton kože. Njegovo osvetljavajuće dejstvo čini ga pogodnim za dnevnu upotrebu, čak i kod osetljive kože. Vitamin C (Askorbil derivat) Vitamin C u stabilizovanom obliku deluje kao snažan antioksidans koji osvetljava kožu, poboljšava sintezu kolagena i smanjuje uticaj slobodnih radikala. Efikasno deluje na tamne fleke i sivilo kože izazvano umorom, stresom ili spoljnim faktorima. Madewhite&#x2122; (20,000 ppm – Centella Asiatica kompleks) Madewhite&#x2122; je patentirani kompleks koji sadrži Centella Asiatica ekstrakt sa dodatnim posvetljujućim efektima. Osim što umiruje i obnavlja kožu, pomaže i u ujednačavanju tena zahvaljujući antiinflamatornim i regenerativnim svojstvima. Aktivne komponente poput madecassosida i asiaticosida stimulišu sintezu kolagena i smanjuju oksidativni stres. U ovoj formuli doprinosi dvostrukom efektu – smirenju i posvetljavanju kože. Glutathione Liposome Glutation u liposomalnom obliku omogućava dublji prodor u kožu i efikasniji uticaj na ćelijskom nivou. Deluje kao snažan antioksidans koji inhibira proizvodnju melanina i osvetljava tamne mrlje. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.5 Vitamin Boosting Essential Toner je visokoefikasan tonik bogat vitaminima, formulisan da osveži, posvetli i revitalizuje kožu. Njegova snažna kombinacija vitamina C, E i B3 obnavlja kožu, smanjuje hiperpigmentaciju i poboljšava ukupnu teksturu tena.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Numbuzin-No.5-Vitamin-Boosting-Essential-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
