INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1041, 119, 'Mixsoon Reishi Mushroom Essence', 'mixsoon-reishi-mushroom-essence', 'Ključne prednosti: Umirivanje i regeneracija: Ekstrakt reishi pečurke smiruje iritacije i pomaže u regeneraciji oštećene kože. Antioksidativna zaštita: Smanjuje štetne efekte slobodnih radikala, štiteći kožu od preuranjenog starenja. Dubinska hidratacija: Esencija obnavlja prirodni nivo vlage u koži, ostavljajući je mekom i elastičnom. Kome je namenjen? Idealan je za osobe sa suvom, osetljivom ili reaktivnom kožom koja traži umirenje i hidrataciju. Takođe je pogodan za zrelu kožu koja želi da smanji vidljive znakove starenja i ojača zaštitnu barijeru. Zašto volimo Mixsoon Reishi Mushroom Essence? Reishi Mushroom Essence je pažljivo formulisana esencija koja koristi blagodeti reishi pečurke za umirenje i revitalizaciju kože. Bogata antioksidansima, esencija pomaže u smanjenju oksidativnog stresa, što koži omogućava da izgleda sveže i mladalački. Njena dubinska hidratacija dolazi od prirodnih polisaharida prisutnih u pečurki, koji istovremeno jačaju zaštitnu barijeru kože. Redovna upotreba ove esencije doprinosi smanjenju crvenila, poboljšava tonus kože i vraća joj prirodni sjaj. Njena lagana tekstura brzo se upija, ostavljajući kožu osveženom i spremnom za dalju negu. Aktivni sastojci Ekstrakt Reishi gljive (Reishi Mushroom Extract) Ekstrakt Reishi gljive, poznate i kao „gljiva besmrtnosti“, bogat je beta-glukanima, polisaharidima, triterpenima i antioksidansima koji imaju snažan regenerativni i zaštitni efekat na kožu. Deluje tako što poboljšava ćelijsku obnovu, jača kožnu barijeru i štiti od oksidativnog stresa, čime doprinosi zdravijem, ujednačenijem tenu. Takođe ima umirujuća i protivupalna svojstva, što ga čini pogodnim za osetljivu i stresiranu kožu. Reishi pomaže u revitalizaciji beživotne kože i vraća joj prirodnu blistavost i elastičnost. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Reishi Mushroom Essence je esencija bogata ekstraktom pečurke reishi, poznate po svojim umirujućim i antioksidativnim svojstvima. Ovaj proizvod dubinski hidrira, revitalizuje kožu i pruža snažnu zaštitu od starenja, čineći kožu glatkom i zdravom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Mixsoon-Reishi-Mushroom-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
