INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1043, 114, 'Medicube Deep Vita A Retinol Serum', 'medicube-deep-vita-a-retinol-serum', 'Ključne prednosti: Smanjenje znakova starenja: Kombinacija retinola i bakučiola pomaže u smanjenju finih linija i bora, poboljšavajući ukupni izgled kože. Poboljšanje teksture kože: Serum podstiče obnavljanje ćelija, što rezultira glatkijom i ujednačenijom kožom. Hidratacija i jačanje barijere: Sadrži skvalan i pantenol koji pružaju dubinsku hidrataciju. Kome je namenjen? Ovaj serum je idealan za osobe sa zrelom kožom koja pokazuje znakove starenja, poput finih linija, bora i neujednačenog tena. Takođe je pogodan za one koji žele poboljšati teksturu i elastičnost kože. Zašto volimo Medicube Deep Vita A Retinol Serum? Deep Vita A Retinol Serum predstavlja naprednu formulu koja kombinuje sedam slojeva stabilizovanog retinola sa bakučiolom, kako bi pružio sveobuhvatnu anti-ageing negu. Redovnom upotrebom, ovaj serum stimuliše sintezu kolagena, što dovodi do povećane čvrstoće i elastičnosti kože. Pored toga, prisustvo niacinamida doprinosi smanjenju hiperpigmentacija i ujednačavanju tena. Skvalan i pantenol obezbeđuju neophodnu hidrataciju i jačaju zaštitnu barijeru kože. Ova sinergija sastojaka rezultira glatkijom, svetlijom i vidno podmlađenom kožom. Aktivni sastojci Retinol Retinol je klinički potvrđen anti-age sastojak koji stimuliše sintezu kolagena i ubrzava ćelijsku obnovu, čime se vidljivo poboljšava čvrstina i tekstura kože. U visokoj koncentraciji, retinol pomaže u smanjenju bora, finih linija i hiperpigmentacija, a istovremeno pospešuje regeneraciju kože. Ova formulacija koristi sistem od sedam slojeva retinola koji omogućava postepeno otpuštanje aktivnih sastojaka kako bi se smanjila iritacija i povećala efikasnost. Takođe podstiče zadebljanje dermisa i poboljšava elastičnost kože koja je oslabljena usled starenja. Retinoidi (napredni derivati retinola) Retinoidi u ovoj formuli uključuju stabilne i snažne oblike vitamina A koji pospešuju proizvodnju kolagena čak do 158% u odnosu na osnovne retinol formule. Deluju efikasno, ali sa manjom verovatnoćom izazivanja iritacija zahvaljujući naprednoj tehnologiji kontrole isporuke. Ovi derivati deluju na smanjenje bora, poboljšanje elastičnosti i posvetljivanje tena. Takođe pomažu u uklanjanju mrtvih ćelija sa površine kože, čineći ten blistavijim i glađim. Višeslojna retinol tehnologija (7-layer Retinol Layering) Tehnologija višeslojne isporuke omogućava kontrolisano i ravnomerno oslobađanje retinola u kožu, minimizujući iritacije i povećavajući podnošljivost čak i kod osetljive kože. Svaki sloj se aktivira u različitom vremenskom okviru, pružajući produžen efekat bez preopterećenja kože. Ovaj pristup omogućava efikasniju isporuku visoke koncentracije retinoida duboko u dermis. Takođe pomaže u održavanju stabilnosti aktivnih sastojaka i sprečava njihovu razgradnju tokom vremena. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Vita A Retinol Serum je moćan anti-ageing tretman formulisan sa 7 slojeva retinola i bakučiolom, namenjen poboljšanju teksture kože, smanjenju finih linija i bora, te ujednačavanju tena. Ovaj serum stimuliše proizvodnju kolagena, povećava elastičnost kože i pruža hidrataciju za mladalački izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-Deep-Vita-A-Retinol-Serum-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
