INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1045, 114, 'Medicube Deep Vita C Ampoule', 'medicube-deep-vita-c-ampoule', 'Ključne prednosti: Smanjenje hiperpigmentacija: Pomaže u smanjenju tamnih mrlja i ujednačavanju tona kože. Poboljšanje elastičnosti kože: Povećava čvrstinu i elastičnost kože, dajući joj mladalački izgled. Brzi rezultati: Vidljivo poboljšava stanje kože u roku od jedne nedelje redovne upotrebe. Kome je namenjen? Ovaj proizvod je idealan za osobe sa neujednačenim tenom, tamnim mrljama ili ožiljcima od akni, koje žele da posvetle kožu i poboljšaju njenu elastičnost. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo Medicube Deep Vita C Ampoule? Deep Vita C Ampoule pruža intenzivnu negu kroz visoku koncentraciju čistog vitamina C, koji deluje kao moćan antioksidans i sredstvo za posvetljivanje kože. Redovnom upotrebom, serum smanjuje vidljivost tamnih mrlja, hiperpigmentacija i ožiljaka. Ovo dovodi do ujednačenog tona kože. Poboljšava elastičnost, čineći kožu čvršćom i glađom. Njegova lagana tekstura omogućava brzo upijanje bez osećaja težine, ostavljajući kožu osveženom i hidriranom. Kliničke studije su pokazale značajno poboljšanje u izgledu kože već nakon 7 dana upotrebe, što ga čini efikasnim rešenjem za brzo postizanje zdravog i blistavog tena. Aktivni sastojci Vitamin C (Askorbinska kiselina, 145,000 ppm) Vitamin C je snažan antioksidans koji u visokoj koncentraciji od 145,000 ppm efikasno deluje na posvetljivanje kože i ujednačavanje tena. Inhibira sintezu melanina, čime smanjuje vidljivost pigmentacija, tamnih fleka i neravnomernog tona kože. Takođe stimuliše sintezu kolagena, poboljšavajući čvrstoću i elastičnost, što doprinosi smanjenju bora i finih linija. Glutation Glutation je snažan endogeni antioksidans koji pomaže u borbi protiv slobodnih radikala i štiti kožu od spoljašnjih stresora kao što su UV zračenje i zagađenje. Efikasno deluje na posvetljivanje kože, inhibirajući proizvodnju melanina i ujednačavajući ten. Takođe ima sposobnost da poboljša elastičnost kože i smanji znakove preranog starenja. Pantenol (Vitamin B5) Pantenol je poznat po svojim snažnim hidratantnim i umirujućim svojstvima, koji privlači i zadržava vlagu u koži. Deluje regenerativno, pomažući u obnavljanju kožne barijere i smanjenju crvenila i iritacija. Pomaže u poboljšanju teksture kože, ostavljajući je mekom i elastičnom. Takođe doprinosi smanjenju transepidermalnog gubitka vode, čime se poboljšava ukupna hidratacija. Dodaj u listu želja Dodaj u listu želja', 'Medicube Deep Vita C Ampoule je visokokoncentrovani serum sa 14,5% čistog vitamina C , formulisan za posvetljivanje kože, smanjenje hiperpigmentacija i poboljšanje elastičnosti. Ovaj proizvod pomaže u ujednačavanju tena i pruža koži zdrav i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-Deep-Vita-C-Ampoule-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
