INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1046, 114, 'Medicube PDRN Pink Cica Soothing Toner', 'medicube-pdrn-pink-cica-soothing-toner', 'Ključne prednosti: Umirivanje iritirane kože: Kombinacija PDRN-a i ekstrakta centela smiruje crvenilo i smanjuje upale, čineći kožu otpornijom. Hidratacija i obnova: Aktivni sastojci intenzivno hidriraju i podržavaju regeneraciju oštećene kože. Poboljšanje teksture i tena: Tonik pomaže u ujednačavanju kože i vraća joj prirodni sjaj. Kome je namenjena? PDRN Pink Cica Soothing Toner je idealan za osobe sa osetljivom, suvom ili reaktivnom kožom koja je sklona iritacijama i crvenilu. Pogodan je za sve tipove kože, uključujući i masnu kožu koja zahteva hidrataciju i balans. Zašto volimo Medicube PDRN Pink Cica Soothing Toner? Ovaj tonik pruža intenzivno umirujuće dejstvo zahvaljujući naprednoj kombinaciji PDRN-a i centele asiatice. Deluje dubinski na obnovu oštećene kože, smanjuje crvenilo i pruža trenutan osećaj svežine i udobnosti. Njegova formula sadrži prirodne biljne ekstrakte koji dodatno poboljšavaju hidrataciju i obnavljaju prirodnu barijeru kože, čineći je otpornijom na spoljne agresore. Pored toga, ovaj tonik doprinosi ujednačavanju tena, smanjuje sitne nepravilnosti i vraća koži zdrav, blistav izgled. Njegova lagana tekstura čini ga savršenim za svakodnevnu upotrebu, čak i kod najosetljivijih tipova kože. Aktivni sastojci PDRN (Polidezoksiribonukleotid iz lososa) PDRN je snažan bioaktivni sastojak koji stimuliše regeneraciju ćelija, poboljšava elastičnost kože i potpomaže oporavak oštećene barijere. Dobijen iz DNK lososa, visoko je kompatibilan sa ljudskom kožom i poznat po svojoj sposobnosti da obnavlja kožu iznutra. Doprinosi ujednačenju tena, smanjenju znakova starenja i oštećenja od UV zračenja. Njegovo antiinflamatorno dejstvo pomaže u umirivanju iritacija, dok istovremeno povećava otpornost kože. Niacinamid Niacinamid (vitamin B3) deluje višeslojno – posvetljuje tamne fleke i hiperpigmentacije, smanjuje upale i poboljšava barijernu funkciju kože. Deluje tako što inhibira prenos melanina, što doprinosi svetlijem i ujednačenijem tenu. Takođe pomaže u smanjenju crvenila, poboljšava elastičnost i zadržava vlagu u koži. U sinergiji s PDRN-om i Cica kompleksom, dodatno pojačava umirujuće i osvetljavajuće dejstvo. Cica (Centella Asiatica) Centella Asiatica, poznata i kao Cica, sadrži aktivne komponente poput madecassoside i asiaticoside, koje deluju snažno protivupalno i regenerativno. Pomaže u smanjenju crvenila, umiruje iritiranu kožu i ubrzava zaceljivanje. Ova biljka stimuliše sintezu kolagena i obnavlja kožnu barijeru, čineći kožu otpornijom na stres i spoljne uticaje. Posebno je pogodna za osetljivu, reaktivnu i upaljenu kožu. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Cica Soothing Toner je nežan i umirujući tonik formulisan sa PDRN-om, centelom i ekstraktima biljaka za obnavljanje, hidrataciju i jačanje osetljive kože. Ovaj proizvod pruža brzo umirivanje iritacija, jača zaštitnu barijeru kože i pomaže u postizanju ujednačenog i blistavog tena.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-PDRN-Pink-Cica-Soothing-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
