INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1047, 114, 'Medicube Exosome Cica Ampoule', 'medicube-exosome-cica-ampoule', 'Ključne prednosti: Intenzivno umirivanje kože: Egzozom centela brzo smanjuje crvenilo i iritacije, čineći kožu mirnijom i otpornijom. Ujednačavanje tena: Niacinamid pomaže u posvetljivanju hiperpigmentacija i smanjenju tamnih fleka. Dubinska hidratacija: Formula sa pantenolom i skvalanom održava optimalan nivo vlage u koži, poboljšavajući njenu elastičnost. Kome je namenjena? Ampula je idealna za osobe sa osetljivom, aknama sklonom ili iritiranom kožom, koje žele da umire crvenilo i posvetle tamne mrlje. Pogodna je za sve tipove kože, uključujući i one sa masnom ili kombinovanom kožom. Zašto volimo Medicube Exosome Cica Ampoule? Exosome Cica Ampoule pruža sveobuhvatnu negu za umirenje i regeneraciju kože zahvaljujući naprednoj tehnologiji egzozoma. Njena formulacija omogućava dublje prodiranje aktivnih sastojaka, što rezultira bržim i efikasnijim smanjenjem crvenila i iritacija. Pored toga, niacinamid doprinosi ujednačavanju tena i smanjenju hiperpigmentacija, dok pantenol i skvalan obezbeđuju hidrataciju i jačaju zaštitnu barijeru kože. Ova ampula je bez mirisa i veštačkih boja, čineći je savršenom za osetljivu kožu. Redovnom upotrebom, koža postaje mirnija, mekša i vidno zdravija. Aktivni sastojci Exosome Cica Exosome Cica predstavlja napredni kompleks dobijen kombinacijom centelle asiatice i egzozoma, koji omogućava dublju i bržu penetraciju aktivnih sastojaka u kožu. Njegova nano-veličina (1/510 manja od prosečne pore) obezbeđuje brzo i efikasno umirivanje iritacija, čak i kod najosetljivijih tipova kože. Klinička ispitivanja potvrđuju 5.3 puta jače umirujuće dejstvo u poređenju sa standardnim ekstraktom Cice. Dodatno, Exosome Cica popunjava vlagu u dubljim slojevima kože, poboljšava barijernu funkciju i pruža zaštitu od spoljašnjih agresora. Dokazano je da doprinosi smanjenju veličine pora (21.1%), poboljšanju teksture kože (5.2%) i uklanjanju mrtvih ćelija (77.4%). Koža postaje umirena, hidrirana, glatka i osvežena. 12 vrsta Cica sastojaka (Centella Asiatica derivati) Formulacija obuhvata ključne aktivne komponente centelle asiatice, uključujući madecassoside, asiaticoside, asiatic acid i madecassic acid, koje pružaju intenzivno umirujuće i regenerativno dejstvo. Ovi sastojci deluju protivupalno i ubrzavaju zarastanje mikropovreda na koži. Takođe pomažu u jačanju zaštitne barijere, povećavaju otpornost kože i ublažavaju crvenilo i iritacije. Savršeni su za svakodnevnu negu reaktivne, osetljive i problematične kože. U kombinaciji sa egzozomima, Cica sastojci pružaju dublje i brže dejstvo. Rezultat je koža koja izgleda zdravije, smirenije i ravnotežnije. Dodaj u listu želja Dodaj u listu želja', 'Medicube Exosome Cica Ampoule je visokokoncentrovana ampula obogaćena egzozom centelom i 2% niacinamida, namenjena umirivanju iritacija i smanjenju crvenila. Njena napredna formulacija posvetljuje kožu, jača njenu barijeru i pruža dubinsku hidrataciju za svež i zdrav izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-Exosome-Cica-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
