INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1049, 114, 'Medicube Zero Foam Cleanser', 'medicube-zero-foam-cleanser', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja mikročestice prašine i zagađenja, ostavljajući kožu čistom i osveženom. Sužavanje pora: Sadrži ekstrakt dunje koji pomaže u zatezanju i smanjenju vidljivosti pora. Hidratacija i elastičnost: Ekstrakti limunove melise i cveta narandže pružaju koži potrebnu vlagu. Kome je namenjen? Ovaj čistač je idealan za osobe sa masnom i kombinovanom kožom sklonom proširenim porama i nakupljanju nečistoća. Takođe je pogodan za one koji žive u urbanim sredinama sa visokim nivoom zagađenja. Zašto volimo Medicube Zero Foam Cleanser? Zero Foam Cleanser pruža temeljno čišćenje kože. Efikasno uklanja mikročestice prašine i zagađenja koje mogu začepiti pore i dovesti do problema sa kožom. Njegova bogata, penasta tekstura omogućava dubinsko čišćenje bez iritacije. Prirodni sastojci poput ekstrakta dunje pomažu u sužavanju pora, ostavljajući kožu glatkom. Dodatno, ekstrakti limunove melise i cveta narandže pružaju hidrataciju i poboljšavaju elastičnost kože, čineći je mekom i osveženom nakon svakog pranja. Aktivni sastojci Ekstrakt matičnjaka (Lemon Balm) Ekstrakt matičnjaka deluje umirujuće i antiinflamatorno, pomažući u smanjenju iritacija koje mogu nastati usled čišćenja kože. Bogat je antioksidansima koji štite kožu od slobodnih radikala i oksidativnog stresa. Takođe deluje adstringentno, što doprinosi zatezanju pora i osvežavanju tena. Njegovo antibakterijsko dejstvo pomaže u smanjenju pojave akni i održavanju čiste kože. Ekstrakt dunje (Quince) Ekstrakt dunje bogat je vitaminima, mineralima i taninima koji pomažu u jačanju elastičnosti kože i njenoj regeneraciji. Deluje antioksidativno, štiteći kožu od negativnih spoljašnjih uticaja i usporavajući procese starenja. Takođe doprinosi smanjenju gubitka vlage i poboljšava tonus kože. Njegovo umirujuće dejstvo čini ga pogodnim za kožu sklonu crvenilu i stresu. Ekstrakt cveta narandže (Orange Blossom) Ekstrakt narandžinog cveta ima tonizirajuće i revitalizujuće dejstvo, koje doprinosi ujednačenijem tenu i svežini kože. Njegova prirodna astringentna svojstva pomažu u zatezanju pora i balansu masnoće, dok istovremeno održava vlagu. Takođe pruža osvežavajući i blagi miris, čineći čišćenje prijatnijim iskustvom. U kombinaciji sa drugim biljnim ekstraktima, pomaže u postizanju vidno mekše i svežije kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Foam Cleanser je blagi penasti čistač lica formulisan da efikasno uklanja nečistoće i mikročestice prašine sa kože, dok istovremeno pomaže u sužavanju pora. Sadrži prirodne ekstrakte poput limunove melise, dunje i cveta narandže, koji doprinose elastičnosti i hidrataciji kože.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Medicube-Zero-Foam-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
