INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1050, 104, 'Laneige Cica Sleeping Mask', 'laneige-cica-sleeping-mask', 'Ključne prednosti: Duboka hidratacija: Obezbeđuje intenzivnu vlagu tokom noći, ostavljajući kožu mekom i osveženom ujutru. Jačanje kožne barijere: Forest Yeast Extract pomaže u regeneraciji kože, povećavajući njenu otpornost. Umirujuće dejstvo: Smanjuje crvenilo i iritacije, pružajući osećaj ugodnosti za osetljivu kožu. Kome je namenjena? Ova maska je idealna za osobe sa suvom i osetljivom kožom sklonom iritacijama, koje traže proizvod za noćnu negu koji umiruje i obnavlja kožu. Pogodna je za sve tipove kože, posebno za one sa potrebom za jačanjem kožne barijere i intenzivnom hidratacijom. Zašto volimo Laneige Cica Sleeping Mask? Cica Sleeping Mask pruža intenzivnu negu zahvaljujući kombinaciji regenerativnih i hidratantnih svojstava. Patentirani Forest Yeast Extract, jači od tradicionalnog madecassoside-a, obnavlja oštećenu kožu i jača njenu otpornost na spoljašnje stresore. Panthenol i squalane doprinose dubinskoj hidrataciji i umiruju iritacije, čineći kožu mekšom i glatkijom. Kremasta tekstura lako se nanosi i brzo upija, pružajući osećaj udobnosti bez masnog filma. Nakon noći sa ovom maskom, koža postaje osvežena, blistava i zdravog izgleda. Redovna upotreba doprinosi dugotrajnoj otpornosti kože i smanjuje pojavu crvenila. Aktivni sastojci Forest Yeast (Lisimachia Herbacea Ferment Lysate) Forest Yeast&#x2122; je ekskluzivni fermentisani sastojak brenda Laneige, dobijen iz biljke Lisimachia Herbacea, poznate po svojim regenerativnim svojstvima. Klinički je dokazan kao 111.9% efikasniji od madecassoside-a u regeneraciji i umirivanju kože. Ovaj ferment pomaže u obnavljanju oslabljene barijere kože, ubrzava prirodnu regeneraciju i poboljšava otpornost kože na stres i iritacije. Posebno je koristan za osetljivu, reaktivnu i dehidriranu kožu. Doprinosi jačanju imuniteta kože i smanjuje crvenilo i nelagodnost. Idealno je rešenje za noćnu obnovu oštećene i oslabljene kože. Pantenol (Provitamin B5) Pantenol je poznat po svojim hidratantnim i umirujućim svojstvima. Prodire duboko u kožu i pomaže u zadržavanju vlage, čime povećava elastičnost i glatkoću kože. Takođe ima regenerativni efekat, pomažući u obnavljanju oštećene kože i smanjenju crvenila. Doprinosi stabilizaciji kožne barijere i smanjuje iritacije. Idealno je za osetljivu kožu sklonu upalama i suvoći. Pruža dugotrajnu udobnost i zaštitu tokom noći. Dodaj u listu želja Dodaj u listu želja', 'LANEIGE Cica Sleeping Mask je noćna maska formulisana sa patentiranim Forest Yeast Extract -om, koja pruža duboku hidrataciju i umiruje osetljivu kožu tokom noći. Ova maska jača kožnu barijeru, čineći kožu otpornijom na spoljašnje uticaje i smanjujući iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Laneige-Cica-Sleeping-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
