INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1051, 92, 'K-Secret Vitamin C Extra Illuminating Eye Gel Patches', 'k-secret-vitamin-c-extra-illuminating-eye-gel-patches', 'Ključne prednosti: Posvetljivanje kože: Vitamin C pomaže u smanjenju hiperpigmentacije i ujednačavanju tena. Intenzivna hidratacija: Hidrogel formula pruža dubinsku hidrataciju, poboljšavajući teksturu kože. Svestrana primena: Veći i manji flasteri omogućavaju ciljanu negu različitih delova lica, uključujući područje ispod očiju, smejalice i vrat. Kome su namenjeni? Ove gel maske su idealne za osobe sa neujednačenim tenom, tamnim podočnjacima ili dehidriranom kožom. Pogodne su za sve tipove kože koji traže osveženje i posvetljivanje. Zašto volimo K-SECRET Vitamin C Extra Illuminating Eye Gel Patches? Vitamin C Extra Illuminating Eye Gel Patches pružaju sveobuhvatnu negu za delikatno područje oko očiju. Obogaćene moćnim antioksidansom, vitaminom C, ove maske efikasno smanjuju pojavu tamnih podočnjaka i ujednačavaju boju kože sprečavanjem proizvodnje melanina. Hidrogelna tekstura omogućava optimalnu apsorpciju aktivnih sastojaka, pružajući trenutnu hidrataciju i osveženje. Veći flasteri su dizajnirani za širu pokrivenost, dok manji omogućavaju preciznu aplikaciju na specifičnim područjima poput smejalica i vrata. Redovnom upotrebom, koža postaje vidno svetlija, glatkija i revitalizovana, sa smanjenim znakovima umora i starenja. Aktivni sastojci Vitamin C (Ascorbic Acid Derivative) Vitamin C je snažan antioksidans koji posvetljuje tamne kolutove i ujednačava ton kože oko očiju. Deluje protiv pigmentacija stimulacijom sinteze kolagena i inhibicijom melaninske aktivnosti. Pomaže u smanjenju znakova umora i pruža koži blistav, osvežen izgled. Takođe štiti kožu od oštećenja izazvanih slobodnim radikalima i UV zračenjem. Redovnom upotrebom, područje oko očiju postaje svetlije i elastičnije. Ovaj stabilan derivat vitamina C pogodan je i za osetljivu kožu. Ekstrakt kore duda (Morus Alba Bark Extract) Ekstrakt bele murve poznat je po svom prirodnom učinku na posvetljivanje kože. Deluje kao inhibitor enzima tirozinaze, čime sprečava nastanak prekomerne pigmentacije. Umiruje kožu i smanjuje upalne procese. U kombinaciji sa vitaminom C, pojačava efekat posvetljavanja. Takođe pruža antioksidativnu zaštitu, čuvajući kožu od preranog starenja. Ekstrakt ploda šipka (Rosa Canina Fruit Extract) Bogat vitaminima C i A, ekstrakt šipka regeneriše i posvetljuje kožu. Ima antioksidativno i protivupalno dejstvo, što ga čini korisnim za umirivanje umorne i natečene kože. Pomaže u smanjenju tamnih kolutova i sitnih linija. Dodaj u listu želja Dodaj u listu želja', 'K-SECRET Vitamin C Extra Illuminating Eye Gel Patches su obogaćene vitaminom C, namenjene za posvetljivanje kože i smanjenje tamnih podočnjaka. Ove hidrogelske maske pružaju intenzivnu hidrataciju i ujednačavaju ten, ciljajući specifične probleme korisnika.', 'https://beauty-health.rs/wp-content/uploads/2025/01/K-SECRET-Vitamin-C-Extra-Illuminating-Eye-Gel-Patches.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
