INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1053, 92, 'K-Secret Seoul 1988 Cleansing Oil 1% Pine Cica', 'k-secret-seoul-1988-cleansing-oil-1-pine-cica', 'Ključne prednosti: Dubinsko čišćenje pora: Efikasno uklanja nečistoće i višak sebuma, pomažući u smanjenju mitesera i belih tačaka. Umirujuće dejstvo: Pine Cica kompleks umiruje iritacije, smanjuje crvenilo i pomaže u regeneraciji kože. Jačanje kožne barijere: Probiotici podržavaju obnovu kožne barijere, poboljšavajući elastičnost i otpornost kože. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući osetljivu i aknama sklonu kožu. Namenjen je onima koji žele efikasno i nežno sredstvo za uklanjanje šminke i čišćenje kože, bez osećaja zatezanja ili iritacije. Zašto volimo K-SECRET Seoul 1988 Cleansing Oil 1% Pine Cica? Cleansing Oil Pine Cica 1% + Probiotics kombinuje moć prirodnih biljnih ulja i umirujućih sastojaka kako bi obezbedio temeljno, ali nežno čišćenje kože. Pine Cica kompleks, koji sadrži ekstrakt bora i Centella Asiatica, poznat je po svom snažnom umirujućem i regenerativnom efektu. Probiotici dodatno podržavaju prirodni balans kože, jačajući njenu otpornost na spoljašnje uticaje. Kombinacija biljnih ulja, poput makadamije, masline i jojobe, omogućava lako rastvaranje šminke i prljavštine, dok kožu ostavlja mekom i hidriranom. Redovna upotreba ovog ulja doprinosi glatkoj, osveženoj i uravnoteženoj koži. Aktivni sastojci Pine Cica Complex 1% Pine Cica kompleks kombinuje umirujuće i antiinflamatorne efekte bora (pine tree) i Centella Asiatica biljke (poznate i kao Cica). Ova kombinacija pomaže u smirivanju crvenila, iritacija i upalnih procesa na koži. Bor ima antiseptička svojstva i deluje pročišćavajuće na pore, dok Cica stimuliše regeneraciju kože i jača njenu barijeru. Zajedno deluju na obnavljanje kože, čineći je otpornijom i balansiranijom. Idealno za kožu koja je izložena stresu, sklonu aknama ili crvenilu. Bifida Ferment Lysate Bifida Ferment Lysate je probiotski sastojak dobijen fermentacijom Bifida bakterija, koji jača kožnu barijeru i povećava otpornost kože na spoljne faktore. Deluje regenerativno, smanjuje osetljivost kože i poboljšava njenu elastičnost. Takođe podstiče oporavak kože od oštećenja izazvanih UV zračenjem i zagađenjem. Poznat je po tome što umanjuje crvenilo i ojačava prirodne mehanizme odbrane kože. Koristan je za sve tipove kože, uključujući osetljivu i reaktivnu. Lactobacillus/Soybean Ferment Extract Ovaj fermentisani ekstrakt soje bogat je aminokiselinama i enzimima koji pomažu u hidrataciji i posvetljavanju kože. U kombinaciji sa Lactobacillus fermentima, deluje antioksidativno i pomaže u obnavljanju oštećene barijere kože. Takođe poboljšava teksturu kože, čineći je mekšom i blistavijom. Fermentacija povećava efikasnost sastojaka i omogućava bolju apsorpciju u koži. Dodaj u listu želja Dodaj u listu želja', 'K-SECRET Cleansing Oil Pine Cica 1% + Probiotics je blago ulje za čišćenje koje efikasno uklanja šminku, nečistoće i višak sebuma, dok umiruje kožu i jača njenu barijeru. Sadrži 1% Pine Cica kompleksa i probiotike koji pružaju dubinsku hidrataciju i podržavaju zdravu kožnu mikrofloru.', 'https://beauty-health.rs/wp-content/uploads/2025/01/K-SECRET-Seoul-1988-Cleansing-Oil-sa-1-Pine-Cica-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
