INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1056, 77, 'I Dew Care Panda Headband', 'i-dew-care-panda-headband', 'Ključne prednosti: Fiksira kosu: Sigurno drži kosu van lica, omogućavajući nesmetano nanošenje proizvoda za negu kože ili šminke. Mekana i rastegljiva: Materijal visokog kvaliteta pruža udobnost i prilagođava se svim veličinama glave. Jedinstven dizajn: Panda motiv čini vašu rutinu nege zabavnijom, idealan za ličnu upotrebu ili kao poklon. Kome je namenjena? Traka za kosu je namenjena svima koji žele praktičan i estetski dodatak u svojoj rutini nege. Pogodna je za sve uzraste, posebno za ljubitelje kreativnih i funkcionalnih dodataka za negu. Zašto volimo I Dew Care Panda Headband? Panda Headband kombinuje funkcionalnost i zabavan dizajn, čineći svakodnevnu rutinu nege kože jednostavnijom i prijatnijom. Njena rastegljiva traka osigurava sigurno prianjanje, dok mekan materijal pruža nežnost prema koži i kosi, bez povlačenja ili iritacije. Idealan je dodatak za nanošenje maski, seruma ili šminke, držeći kosu uredno povučenu. Osim funkcionalnosti, panda motiv unosi veselu notu u vašu rutinu, savršeno prilagođenu za sve ljubitelje zanimljivih dodataka. Lako se čisti i održava, što doprinosi njenoj trajnosti i higijeni. Ova traka je praktičan izbor za svakodnevnu upotrebu kod kuće, na putovanju ili kao deo opuštajuće rutine. Dodaj u listu želja Dodaj u listu želja', 'I Dew Care Panda Headband je mekana i rastegljiva traka za kosu sa zabavnim dizajnom inspirisanim pandama, savršena za držanje kose podalje od lica tokom rutine nege kože ili šminkanja. Napravljena od visokokvalitetnih materijala, pruža udobnost i funkcionalnost uz dozu razigranosti.', 'https://beauty-health.rs/wp-content/uploads/2025/01/I-Dew-Care-Panda-Headband.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
