INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1057, 77, 'I Dew Care White Cat Headband', 'i-dew-care-white-cat-headband', 'Ključne prednosti: Fiksira kosu: Sigurno drži kosu podalje od lica, olakšavajući nanošenje maski, seruma i šminke. Mekani materijal: Izrađena od visokokvalitetnog, rastegljivog materijala, pruža udobnost i ne iritira kožu. Zabavan i praktičan dizajn: Mačji uši dodaju razigranost vašoj rutini, čineći je savršenim dodatkom za ličnu upotrebu ili poklon. Kome je namenjena? Ova traka je pogodna za sve tipove kose i idealna za osobe koje žele praktičan i estetski dodatak u rutini nege ili šminkanja. Savršena je za ljubitelje zabavnih i funkcionalnih dodataka koji unapređuju svakodnevnu negu. Zašto volimo I Dew Care White Cat Headband? White Cat Headband je idealan dodatak vašoj rutini nege, pružajući praktičnost i estetsku privlačnost. Njena rastegljiva traka sigurno drži kosu, omogućavajući nesmetanu primenu proizvoda poput maski, seruma ili šminke. Mekani materijal čini je udobnom za svakodnevnu upotrebu. Jedinstveni dizajn sa belim mačjim ušima unosi zabavu u vašu rutinu. Njena funkcionalnost omogućava lako održavanje čistoće i higijene tokom nege kože. Pogodna za sve uzraste, traka je savršen saputnik za kućne tretmane ili kao poklon za prijatelje koji vole detalje koji osvežavaju svakodnevnicu. Dodaj u listu želja Dodaj u listu želja', 'I Dew Care White Cat Headband je praktična i mekana traka za kosu dizajnirana da drži kosu podalje od lica tokom rutine nege kože ili šminkanja. Sa jedinstvenim dizajnom inspirisanim belom mačkom, traka kombinuje funkcionalnost i zabavan izgled, čineći svakodnevnu rutinu još prijatnijom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/I-Dew-Care-White-Cat-Headband.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
