INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1060, 69, 'Haruharu Wonder Black Rice Botanical 2GF Ampoule', 'haruharu-wonder-black-rice-botanical-2gf-ampoule', 'Ključne prednosti: Ubrzava regeneraciju kože: Biljni EGF i FGF proteini stimulišu proizvodnju kolagena, poboljšavajući elastičnost i čvrstinu kože. Dubinska hidratacija: Hijaluronska kiselina zadržava vlagu u koži, održavajući je mekom i glatkom. Smanjuje bore: Adenosin efikasno umanjuje vidljivost finih linija i bora, dajući koži mladalački izgled. Kome je namenjena? Ova ampula je idealna za osobe sa suvom, dehidriranom ili zrelom kožom koja pokazuje znakove starenja, poput smanjene elastičnosti i prisustva finih linija. Takođe je pogodna za one koji žele da poboljšaju teksturu i tonus kože. Zašto volimo Haruharu Wonder Black Rice Botanical 2GF Ampoule? Black Rice Botanical 2GF Ampoule koristi moć fermentisanog crnog pirinča, bogatog antioksidansima, za zaštitu kože od štetnih spoljašnjih uticaja i slobodnih radikala. Biljni EGF i FGF proteini ubrzavaju regeneraciju ćelija, što rezultira glatkijom i čvršćom kožom. Adenosin, poznat po svojim anti-age svojstvima, smanjuje vidljivost bora, dok hijaluronska kiselina pruža dubinsku hidrataciju, održavajući kožu elastičnom i svežom. Lagana tekstura ampule omogućava brzo upijanje bez osećaja lepljivosti, čineći je savršenom za svakodnevnu upotrebu. Redovnom upotrebom koža postaje blistava, čvrsta i revitalizovana. Aktivni sastojci Fermented Black Rice Extract Fermentisani ekstrakt crnog pirinča bogat je antioksidansima, flavonoidima i antocijaninima koji štite kožu od oksidativnog stresa. Proces fermentacije dodatno povećava biodostupnost hranljivih materija, čineći ih efikasnijim u regeneraciji kože. Ovaj ekstrakt hidrira, posvetljuje i poboljšava elastičnost kože, dok istovremeno jača njenu barijeru. Takođe deluje umirujuće i obnavljajuće, posebno na umornu i zrelu kožu. Bogat je vitaminima B i E, koji podržavaju vitalnost i zdrav izgled tena. 2GF (EGF & FGF – Plant-Based Growth Factors) Biljni EGF (epidermalni faktor rasta) i FGF (fibroblastni faktor rasta) stimulišu ćelijsku regeneraciju i podstiču proizvodnju kolagena i elastina. Ovi rastni faktori pomažu u zaglađivanju kože, smanjenju bora i poboljšanju ukupnog tonusa i teksture. Deluju kao signalni proteini koji ubrzavaju obnovu kože i čine je otpornijom. Biljni izvor ovih faktora obezbeđuje visoku kompatibilnost i minimalan rizik od iritacije. Posebno su efikasni kod zrele, tanke i umorne kože kojoj je potrebna revitalizacija. Adenozin Adenozin je moćan sastojak za negu protiv starenja, poznat po svojoj sposobnosti da smanji vidljivost finih linija i bora. Deluje tako što stimuliše sintezu kolagena i poboljšava elastičnost kože. Takođe ima umirujuće dejstvo i pomaže u smanjenju crvenila i iritacija. Pogodan je za sve tipove kože, uključujući osetljivu. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Botanical 2GF Ampoule je anti-age ampula formulisana sa fermentisanim crnim pirinčem, biljnim EGF i FGF proteinima, koji ubrzavaju regeneraciju ćelija kože, smanjujući pojavu finih linija i bora. Hijaluronska kiselina pruža intenzivnu hidrataciju, dok adenosin dodatno doprinosi smanjenju znakova starenja.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Haruharu-Wonder-Black-Rice-Botanical-2GF-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
