INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1061, 72, 'Heimish RX AHA BHA Peeling Serum', 'heimish-rx-aha-bha-peeling-serum', 'Ključne prednosti: Dubinska eksfolijacija: Visoka koncentracija AHA i BHA kiselina temeljno uklanja mrtve ćelije kože, poboljšavajući teksturu i tonus. Pročišćavanje pora: Salicilna kiselina prodire duboko u pore, smanjujući njihovu zapušenost i pojavu akni. Hidratacija i umirenje: Prisustvo hijaluronske kiseline i pantenola osigurava hidrataciju i umiruje kožu tokom eksfolijacije. Kome je namenjen? Ovaj serum je idealan za osobe sa masnom i aknama sklonom kožom koje traže efikasno rešenje za poboljšanje teksture i ujednačavanje tena. Preporučuje se iskusnim korisnicima hemijskih pilinga zbog visoke koncentracije kiselina. Zašto volimo Heimish RX AHA BHA Peeling Serum? RX AHA BHA Peeling Serum pruža intenzivnu eksfolijaciju zahvaljujući kombinaciji alfa-hidroksi (AHA) i beta-hidroksi kiselina (BHA). Glikolna i mlečna kiselina deluju na površini kože, uklanjajući mrtve ćelije i pospešujući regeneraciju, što rezultira glatkijom i sjajnijom kožom. Salicilna kiselina prodire u pore, razgrađujući sebum i nečistoće, čime smanjuje pojavu akni i mitesera. Dodatno, hijaluronska kiselina pruža neophodnu hidrataciju, dok pantenol umiruje kožu, smanjujući mogućnost iritacije tokom tretmana. Redovnom upotrebom, ovaj serum pomaže u postizanju ujednačenog tena i poboljšava ukupni izgled kože. Aktivni sastojci Glikolna kiselina Glikolna kiselina je alfa-hidroksi kiselina (AHA) koja dubinski eksfolira kožu uklanjanjem mrtvih ćelija sa njene površine. Zahvaljujući maloj molekulskoj masi, prodire dublje u kožu i podstiče njeno obnavljanje. Pomaže u smanjenju hiperpigmentacija, neujednačenog tena i finih linija. Koži vraća svežinu, glatkoću i ujednačen sjaj. Mlečna kiselina Mlečna kiselina je nežnija AHA koja eksfolira površinski sloj kože, čineći je glatkom i hidriranom. Posebno je pogodna za suvu i osetljivu kožu, jer istovremeno deluje i kao humektant. Pomaže u uklanjanju površinskih nepravilnosti i osvetljava tamne fleke. Poboljšava teksturu kože i podržava prirodnu barijeru kože. Salicilna kiselina Salicilna kiselina je beta-hidroksi kiselina koja prodire u pore i rastvara sebum i nečistoće. Efikasno deluje protiv akni i mitisera zahvaljujući svojim antibakterijskim i antiinflamatornim svojstvima. Smanjuje crvenilo i sprečava nastanak novih upalnih procesa. Regulisanjem proizvodnje sebuma, poboljšava izgled masne i problematične kože. Dodaj u listu želja Dodaj u listu želja', 'Heimish RX AHA BHA Peeling Serum je moćan piling serum koji kombinuje 30% AHA (glikolna i mlečna kiselina) i 0,5% BHA (salicilna kiselina) za efikasno uklanjanje mrtvih ćelija kože, pročišćavanje pora i postizanje glatke i blistave kože. Ova formula pruža intenzivnu eksfolijaciju uz istovremenu hidrataciju i umirenje kože.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Heimish-RX-AHA-BHA-Peeling-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
