INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1064, 72, 'Heimish Dailism Smudge Stop Mascara', 'heimish-dailism-smudge-stop-mascara', 'Ključne prednosti: Postojanost bez razmazivanja: Tehnologija obavija svaku trepavicu, sprečavajući razmazivanje i ljuštenje, čak i u uslovima vlage ili suza. Jednostavno uklanjanje: Maskara se lako uklanja toplom vodom bez iritacija ili potrebe za jakim trljanjem. Definicija i uvijanje: Zakrivljena četkica pruža precizno nanošenje i dodatno uvijanje trepavica za otvoren i svež izgled očiju. Kome je namenjena? Ova maskara je idealna za svakodnevnu upotrebu kod osoba koje žele definisane i atraktivne trepavice uz dugotrajnu postojanost. Pogodna je za sve tipove kože, uključujući osetljivu, jer se lako uklanja bez dodatnih hemikalija. Zašto volimo Heimish Dailism Smudge Stop Curling Mascara? Dailism Smudge Stop Curling Mascara koristi inovativnu tubastu formulu koja obavija svaku trepavicu fleksibilnim polimerima, pružajući dramatičan volumen i dužinu bez grudvica. Zahvaljujući svojoj postojanosti, maskara ostaje na mestu tokom celog dana, bez obzira na aktivnosti ili vremenske uslove. Lagana i prilagodljiva tekstura omogućava lako nanošenje bez osećaja težine na trepavicama. Zakrivljena mikro četkica doseže čak i najkraće trepavice, osiguravajući preciznu definiciju i savršen završetak. Za razliku od tradicionalnih maskara, ova formula se uklanja samo toplom vodom, što je čini jednostavnom za korišćenje i posebno pogodnom za osobe sa osetljivim očima. Uz redovnu upotrebu, pruža vam besprekoran izgled bez napora. Dodaj u listu želja Dodaj u listu želja', 'Heimish Dailism Smudge Stop Mascara je tubasta maskara koja pruža produžene i definisane trepavice, uz dugotrajnu postojanost bez razmazivanja. Ova lagana formula lako se uklanja toplom vodom, pružajući praktičnost i njegu trepavicama. Dolazi u 2 verzije: Volume koja dodaje volumen i Curling za uvijene trepavice.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Heimish-Dailism-Smudge-Stop-Mascara-6.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
