INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1067, 64, 'Fully Green Tomato Serum', 'fully-green-tomato-serum', 'Ključne prednosti: Smanjenje pora: Ekstrakt zelenog paradajza pomaže u smanjenju veličine pora, čineći kožu ujednačenijom i glatkijom. Poboljšanje elastičnosti: Visok sadržaj vitamina C stimuliše proizvodnju kolagena, povećavajući čvrstinu i elastičnost kože. Kontrola sebuma: Sastojci poput PHA i LHA pružaju blagu eksfolijaciju, regulišući proizvodnju sebuma i smanjujući masni sjaj. Kome je namenjen? Ovaj serum je idealan za osobe sa masnom i kombinovanom kožom sklonom proširenim porama i prekomernom lučenju sebuma. Takođe je pogodan za osetljivu kožu zbog svoje blage formulacije bez sintetičkih mirisa. Zašto volimo FULLY Green Tomato Serum? Green Tomato Serum pruža sveobuhvatnu negu kože kroz sinergiju pažljivo odabranih sastojaka. Ekstrakt zelenog paradajza, bogat antioksidansima poput likopena i vitamina C, štiti kožu od štetnih uticaja okoline i posvetljuje ten. Blaga eksfolijacija zahvaljujući PHA i LHA uklanja mrtve ćelije kože, poboljšavajući njenu teksturu i sjaj. Redovnom upotrebom, serum smanjuje vidljivost pora i finih linija, dok hidratantna svojstva održavaju kožu mekom i elastičnom. Bez sintetičkih mirisa, ova dermatološki testirana formula pruža sigurnu i efikasnu negu za sve tipove kože, uključujući i osetljivu. Aktivni sastojci Ekstrakt zelenog paradajza Sadrži visok nivo antioksidanasa, uključujući likopen i vitamin C, koji pomažu u neutralisanju slobodnih radikala i zaštiti kože od oksidativnog stresa. Takođe, ovaj ekstrakt posvetljuje kožu i poboljšava njenu elastičnost, smanjujući vidljivost pora i nepravilnosti. PHA (Polihidroksi kiselina) Deluje kao blagi eksfolijant koji uklanja površinske mrtve ćelije kože, poboljšavajući njenu teksturu i tonus. PHA molekuli su veći od drugih kiselina, što omogućava sporiju penetraciju i smanjuje rizik od iritacije, čineći ih pogodnim za osetljivu kožu. LHA (Lipohidroksi kiselina) Slična salicilnoj kiselini, LHA prodire u pore i pomaže u njihovom čišćenju, smanjujući pojavu akni i mitesera. Ima antiinflamatorna svojstva i doprinosi ujednačenom tenu kože. Dodaj u listu želja Dodaj u listu želja', 'FULLY Green Tomato Serum je veganski serum sa 67% ekstrakta zelenog paradajza, bogat vitaminom C, koji poboljšava elastičnost kože i sužava proširene pore. Njegova lagana gel tekstura omogućava brzo upijanje bez masnog osećaja, ostavljajući kožu glatkom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/FULLY-Green-Tomato-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
