INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1068, 64, 'Fully Rice Dough Modeling Mask', 'fully-rice-dough-modeling-mask', 'Ključne prednosti: Dubinska hidratacija: Hijaluronska kiselina zadržava vlagu u koži, čineći je glatkom i elastičnom. Posvetljivanje tena: Pirinčana voda bogata je antioksidansima koji pomažu u ujednačavanju tena i smanjenju tamnih mrlja. Umirujuće dejstvo: Alginat iz morskih algi pruža trenutni efekat hlađenja, smanjujući crvenilo i iritacije. Kome je namenjena? Ova maska je idealna za sve tipove kože, posebno za one sa suvom, osetljivom ili iritiranom kožom. Takođe je pogodna za osobe koje žele da poboljšaju teksturu i tonus svoje kože. Zašto volimo FULLY Rice Dough Modeling Mask? Rice Dough Modeling Mask pruža spa iskustvo kod kuće, kombinujući tradicionalne korejske sastojke sa modernom tehnologijom. Njena jedinstvena formulacija omogućava lako mešanje i nanošenje bez potrebe za dodatnim posudama ili vodom. Kada se pomeša, maska stvara glatku teksturu koja se ravnomerno nanosi na lice, pružajući intenzivnu hidrataciju i umirujući efekat. Klinička ispitivanja su pokazala smanjenje crvenila kože za 15,73% i poboljšanje elastičnosti za 30,02% nakon samo jedne upotrebe. Redovnom upotrebom, koža postaje blistava, ujednačena i revitalizovana. Aktivni sastojci Pirinčana voda Bogata vitaminima i mineralima, pirinčana voda hidrira i posvetljuje kožu, pomažući u smanjenju tamnih mrlja i ujednačavanju tena. Takođe sadrži antioksidante koji štite kožu od štetnih spoljašnjih uticaja. Hijaluronska kiselina Prirodni humektant koji može zadržati do 1000 puta svoje težine u vodi, pružajući intenzivnu hidrataciju. Pomaže u popunjavanju finih linija i bora, ostavljajući kožu glatkom i elastičnom. Alginat Ekstrakt morskih algi koji pruža trenutni efekat hlađenja i umirivanja. Pomaže u smanjenju crvenila i iritacija, dok istovremeno zadržava vlagu u koži. Dodaj u listu želja Dodaj u listu želja', 'FULLY Rice Dough Modeling Mask je veganska maska za lice koja kombinuje pirinčanu vodu i hijaluronsku kiselinu za dubinsku hidrataciju i posvetljivanje kože. Ova maska pruža trenutni efekat hlađenja i umirivanja, smanjujući crvenilo i iritacije.', 'https://beauty-health.rs/wp-content/uploads/2025/01/FULLY-Rice-Dough-Modeling-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
