INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1069, 52, 'Dr.Melaxin Peel Shot Exfoliant White Rice Ampoule', 'dr-melaxin-peel-shot-exfoliant-white-rice-ampoule', 'Ključne prednosti: Nežna eksfolijacija: Prirodni sastojci uklanjaju mrtve ćelije kože, otkrivajući glatku i osveženu površinu. Posvetljivanje tena: Niacinamid pomaže u smanjenju hiperpigmentacija, pružajući ujednačen i blistav izgled kože. Hidratacija: Hijaluronska kiselina dubinski hidrira kožu, održavajući njenu elastičnost i mekoću. Kome je namenjena? Ova ampula je idealna za osobe sa neujednačenom teksturom kože, prisustvom belih mitisera ili hiperpigmentacijom. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Dr.Melaxin Peel Shot Exfoliant White Rice Ampoule? Peel Shot Exfoliant White Rice Ampoule pruža dvostruko dejstvo eksfolijacije i nege. Formulisana sa visokim sadržajem ekstrakta pirinčanih mekinja, ova ampula efikasno uklanja mrtve ćelije kože i višak sebuma, poboljšavajući njenu teksturu. Niacinamid posvetljuje kožu i smanjuje vidljivost tamnih mrlja, dok hijaluronska kiselina obezbeđuje dubinsku hidrataciju. Redovnom upotrebom, koža postaje glatka, blistava i ujednačenog tena. Aktivni sastojci Rice Bran Water Voda od mekinja pirinča bogata je vitaminima B i E, mineralima i antioksidansima koji poboljšavaju tonus i zdrav izgled kože. Pomaže u hidrataciji i posvetljavanju kože, istovremeno jačajući prirodnu barijeru. Deluje umirujuće i osvežavajuće, što je čini pogodnom i za osetljivu kožu. Blago eksfolira i pomaže u ujednačavanju teksture kože. Takođe podržava prirodnu regeneraciju ćelija. Rezultat je mekana, glatka i blistava koža. AHA, BHA, PHA Complex Ova trostruka kombinacija kiselina deluje kao nežni, ali efikasni eksfolijator za različite slojeve kože. AHA (alfa-hidroksi kiseline) uklanjaju mrtve ćelije sa površine kože i poboljšavaju teksturu. BHA (beta-hidroksi kiseline), poput salicilne kiseline, prodiru u pore i uklanjaju višak sebuma i mitisere. PHA (polihidroksi kiseline) pružaju blag efekat eksfolijacije i dodatnu hidrataciju bez iritacije. Zajedno poboljšavaju ujednačenost tena i pročišćavaju kožu. Pentavitin® Pentavitin® je prirodni biljni hidratantni kompleks koji pruža dubinsku i dugotrajnu hidrataciju do 72 sata. Vezuje se za keratin u koži i ostaje aktivan i nakon ispiranja, za razliku od običnih humektanata. Pomaže u obnavljanju barijerne funkcije i smanjuje suvoću, perutanje i iritacije. Posebno je pogodan za osetljivu i dehidriranu kožu. Takođe poboljšava glatkoću i elastičnost kože uz kontinuiranu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin Peel Shot Exfoliant White Rice Ampoule je visokokoncentrovana ampula koja kombinuje eksfolijaciju i hidrataciju, nežno uklanjajući mrtve ćelije kože i poboljšavajući njenu teksturu. Obogaćena je ekstraktom pirinčanih mekinja i niacinamidom, pružajući blistav i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Dr.Melaxin-Peel-Shot-Exfoliant-White-Rice-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
