INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1070, 50, 'Dr.G Bakuchiol Pore-Jet Serum', 'dr-g-bakuchiol-pore-jet-serum', 'Ključne prednosti: Smanjenje proširenih pora: Bakučiol, prirodna alternativa retinolu, pomaže u smanjenju veličine pora i poboljšava teksturu kože. Ujednačavanje tena: Visoka koncentracija niacinamida (5%) posvetljuje kožu i smanjuje pojavu tamnih mrlja. Poboljšanje elastičnosti: Cica PDRN kompleks doprinosi čvrstoći i elastičnosti kože, pružajući mladalački izgled. Kome je namenjen? Ovaj serum je idealan za osobe sa proširenim porama, neujednačenim tonom kože i smanjenom elastičnošću. Pogodan je za sve tipove kože, uključujući osetljivu i sklonu iritacijama. Zašto volimo Dr.G Bakuchiol Pore-Jet Serum? Bakuchiol Pore-Jet Serum pruža sveobuhvatnu negu kože fokusirajući se na ključne probleme poput proširenih pora, neujednačenog tena i gubitka elastičnosti. Bakuhiol deluje slično retinolu, ali bez iritacija, smanjujući veličinu pora i poboljšavajući teksturu kože. Niacinamid u visokoj koncentraciji posvetljuje kožu, smanjuje hiperpigmentacije i ujednačava ten. Cica PDRN kompleks regeneriše kožu, povećava njenu čvrstoću i elastičnost, pružajući mladalački izgled. Redovnom upotrebom, koža postaje glatka, blistava i vidljivo poboljšane strukture. Aktivni sastojci Bakuchiol (2,000 ppm) Prirodna alternativa retinolu, bakuchiol pruža slične benefite u borbi protiv znakova starenja, ali sa manjim rizikom od iritacija. Pomaže u smanjenju pojave finih linija i bora, poboljšava elastičnost kože i ujednačava ten. Njegova antioksidativna svojstva štite kožu od oksidativnog stresa i oštećenja izazvanih slobodnim radikalima. Takođe, bakuchiol deluje umirujuće na kožu, smanjujući crvenilo i iritacije. Niacinamide Poznat i kao vitamin B3, niacinamid je višenamenski sastojak koji pomaže u poboljšanju barijerne funkcije kože, smanjenju hiperpigmentacija i regulaciji proizvodnje sebuma. Deluje protivupalno, što ga čini efikasnim u tretiranju akni i crvenila. Takođe poboljšava elastičnost kože i smanjuje vidljivost pora. Njegova antioksidativna svojstva štite kožu od oštećenja izazvanih spoljnim faktorima. Centella Asiatica Leaf Extract Ekstrakt lista Centella Asiatica, poznat i kao &#8220;tigar trava&#8221;, cenjen je zbog svojih umirujućih i regenerativnih svojstava. Pomaže u ubrzavanju procesa zarastanja rana, smanjenju upala i crvenila, te jačanju kožne barijere. Bogat je antioksidansima koji štite kožu od štetnih spoljašnjih uticaja. Takođe hidrira kožu i poboljšava njenu elastičnost. Dodaj u listu želja Dodaj u listu želja', 'Dr.G Bakuchiol Pore-Jet Serum je visokokoncentrovani serum dizajniran za smanjenje proširenih pora, poboljšanje elastičnosti kože i ujednačavanje tena. Ključni sastojci uključuju bakuhiol, niacinamid i Cica PDRN kompleks, koji zajedno pružaju efikasnu negu kože.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Dr.G-Bakuchiol-Pore-Jet-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
