INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1073, 31, 'Celimax Pore Dark Spot Brightening Serum', 'celimax-pore-dark-spot-brightening-serum', 'Ključne prednosti: Posvetljavanje i ujednačavanje tena: Traneksaminska kiselina smanjuje vidljivost tamnih mrlja i hiperpigmentacija, čineći kožu blistavijom i ujednačenom. Poboljšanje teksture kože: Formula pomaže u smanjenju proširenih pora i neravnina, ostavljajući kožu glatkom i zategnutom. Hidratacija i obnova: Dodatni hidratantni i regenerativni sastojci jačaju barijeru kože i vraćaju joj prirodnu svežinu. Kome je namenjen? Ovaj serum je idealan za osobe sa problemima hiperpigmentacije, tamnih mrlja i proširenih pora. Posebno je pogodan za normalnu, kombinovanu i masnu kožu koja zahteva dodatnu negu i osvetljavanje. Zašto volimo Celimax Pore Dark Spot Brightening Serum? Pore Dark Spot Brightening Serum kombinuje naučno dokazane sastojke za efikasno rešavanje problema hiperpigmentacije i neujednačenog tena. Njegova lagana tekstura omogućava brzo upijanje. Ciljano delovanje na tamne mrlje uz pomoć traneksaminske kiseline smanjuje proizvodnju melanina i sprečava nastanak novih pigmentacija. Serum takođe poboljšava teksturu kože smanjujući vidljivost pora, dok hidratantni sastojci obnavljaju prirodnu vlažnost kože. Dugotrajnom upotrebom, koža postaje vidno svetlija, glatkija i svežija, sa ujednačenim tonom. Aktivni sastojci Traneksaminska kiselina (3%) Traneksaminska kiselina je sintetički derivat lizina poznat po svojoj sposobnosti da inhibira melanogenezu, proces stvaranja melanina u koži. Deluje tako što blokira interakciju između melanocita i keratinocita, čime se smanjuje hiperpigmentacija i pojava tamnih mrlja. Takođe, ima protivupalna svojstva koja pomažu u smirivanju kože i smanjenju crvenila. Njena efikasnost u tretiranju melazme i drugih oblika hiperpigmentacije čini je cenjenim sastojkom u proizvodima za posvetljivanje kože. Niacinamid (5%) Niacinamid, poznat i kao vitamin B3, multifunkcionalni je sastojak koji pruža brojne benefite za kožu. Pomaže u smanjenju hiperpigmentacije inhibicijom transfera melanina do površinskih ćelija kože, čime se ujednačava ten. Takođe, poboljšava funkciju kožne barijere povećanjem sinteze ceramida i slobodnih masnih kiselina, što dovodi do bolje hidratacije i otpornosti kože. Njegova antiinflamatorna svojstva čine ga efikasnim u tretiranju akni i smanjenju crvenila. Pored toga, niacinamid smanjuje proizvodnju sebuma, što je korisno za osobe sa masnom kožom. Melazero V2 (1%) Melazero V2 je patentirani biljni kompleks dizajniran za smanjenje hiperpigmentacije i posvetljivanje kože. Deluje razgradnjom postojećeg melanina u koži, što dovodi do smanjenja tamnih mrlja i ujednačenijeg tena. Njegova efikasnost u posvetljavanju kože čini ga popularnim izborom u proizvodima namenjenim tretiranju hiperpigmentacije. Pored toga, Melazero V2 pruža antioksidativnu zaštitu, štiteći kožu od oštećenja izazvanih slobodnim radikalima. Ovaj sastojak je blag prema koži i pogodan za sve tipove, uključujući osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'Celimax Pore Dark Spot Brightening Serum je serum namenjen posvetljivanju tamnih mrlja, ujednačavanju tena i smanjenju proširenih pora. Ključni sastojci, uključujući traneksaminsku kiselinu, ciljano deluju na hiperpigmentacije i poboljšavaju teksturu kože.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Celimax-Pore-Dark-Spot-Brightening-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
