INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1075, 31, 'Celimax Dual Barrier Mild Gel Cleanser', 'celimax-dual-barrier-mild-gel-cleanser', 'Ključne prednosti: Blago čišćenje bez iritacije: Formulisan sa blagim surfaktantima, ovaj gel efikasno uklanja nečistoće i ostatke šminke. Bez isušivanja ili iritacije kože. Obnavljanje i jačanje kožne barijere: 5 vrsta prirodnih ceramida pomažu u obnovi i jačanju zaštitne barijere kože. Dubinska hidratacija: Ekstrakt biljke Jerihonske ruže, poznat po sposobnosti zadržavanja vlage, pruža intenzivnu hidrataciju. Kome je namenjen? Ovaj gel za čišćenje je idealan za osobe sa suvom, osetljivom ili iritiranom kožom, koje traže blago, ali efikasno sredstvo za svakodnevno čišćenje lica. Takođe je pogodan za one koji žele da očuvaju i ojačaju prirodnu barijeru kože. Zašto volimo Celimax Dual Barrier Mild Gel Cleanser? Dual Barrier Mild Gel Cleanser pruža nežno, ali temeljno čišćenje, uklanjajući nečistoće i ostatke šminke bez narušavanja prirodne ravnoteže kože. Njegova jedinstvena formula sa niskim pH vrednošću od 5,2 (+/- 0,5) pomaže u održavanju optimalne acidobazne ravnoteže kože. Ovo je ključno za njenu zaštitnu funkciju. Prisustvo 5 vrsta prirodnih ceramida doprinosi jačanju kožne barijere. Ekstrakt biljke Jerihonske ruže pruža dugotrajnu hidrataciju. Nakon upotrebe, koža ostaje čista, meka i osvežena, bez osećaja zatezanja ili suvoće. Ovaj gel je dermatološki testiran i pogodan za svakodnevnu upotrebu, čak i kod najosetljivijih tipova kože. Aktivni sastojci Ceramidi Ovaj gel čistač sadrži pet vrsta prirodno derivovanih ceramida: Ceramide AS, Ceramide AP, Ceramide EOP, Ceramide NP i Ceramide NS. Ceramidi su lipidi koji čine ključni deo zaštitne barijere kože, pomažući u zadržavanju vlage i zaštiti od spoljašnjih agresora. Njihova prisutnost u formuli jača barijernu funkciju kože, smanjuje gubitak vode i poboljšava hidrataciju, što rezultira glatkom i zdravom kožom. Redovnom upotrebom proizvoda bogatih ceramidima, koža postaje otpornija, elastičnija i manje sklona iritacijama. ​ Aquatide (Heptasodium Hexacarboxymethyl Dipeptide-12) Aquatide je patentirani peptid poznat po svojim antioksidativnim svojstvima i sposobnosti da stimuliše autofagiju, proces kojim ćelije uklanjaju oštećene komponente. Ovaj sastojak pomaže u zaštiti kože od oksidativnog stresa, usporava proces starenja i poboljšava ukupno zdravlje kože. Takođe, doprinosi jačanju barijerne funkcije kože i poboljšava njenu hidrataciju, čineći je glatkom i blistavom. ​ Glicerin (Glycerin) Glicerin je prirodni humektant koji privlači vlagu iz okoline u kožu, pružajući dubinsku hidrataciju. Pomaže u održavanju optimalnog nivoa vlage u koži, čineći je mekom i glatkom. Takođe, jača zaštitnu barijeru kože, sprečavajući isušivanje i štiteći je od spoljašnjih agresora. Glicerin poboljšava elastičnost kože i može pomoći u smanjenju iritacija, što ga čini pogodnim za sve tipove kože, uključujući i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'Celimax Dual Barrier Mild Gel Cleanser je blagi gel za čišćenje lica sa niskim pH, formulisan da nežno ukloni nečistoće bez narušavanja prirodne barijere kože. Obogaćen je sa 5 vrsta prirodnih ceramida i ekstraktom Jerihonske ruže, pružajući hidrataciju i zaštitu, posebno pogodnu za suvu i osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Celimax-Dual-Barrier-Mild-Gel-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
