INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1077, 35, 'CKD Retino Collagen Small Molecule 300 Guasha Neck Cream', 'ckd-retino-collagen-small-molecule-300-guasha-neck-cream', 'Ključne prednosti: Povećava proizvodnju kolagena: Sadrži 300 daltona niskomolekularnog kolagena, koji duboko prodire u kožu, smanjujući bore i poboljšavajući čvrstinu. Hidrira i podmlađuje kožu: Formula sa hijaluronskom kiselinom i elastinom pruža intenzivnu hidrataciju i dugotrajan osećaj glatkoće. Poboljšava tonus i teksturu kože: Retinal i hranljivi sastojci stimulišu regeneraciju ćelija, čineći kožu čvršćom i blistavijom. Kome je namenjena? Ova krema je idealna za osobe koje žele da smanje vidljivost bora i učvrste kožu vrata. Posebno je pogodna za suvu i zrelu kožu koja pokazuje znake starenja. Zašto volimo CKD Retino Collagen Small Molecule 300 Guasha Neck Cream? Retino Collagen Small Molecule 300 Guasha Neck Cream predstavlja savršeno rešenje za negu vrata zahvaljujući kombinaciji naprednih sastojaka i masaže. Njena formula, obogaćena niskomolekularnim kolagenom, dublje prodire u kožu i pruža intenzivnu hidrataciju. Retinal deluje na regeneraciju ćelija, smanjujući duboke i fine bore. Elastin vraća koži elastičnost, dok hijaluronska kiselina zadržava vlagu i povećava punoću kože. Čelični Gua Sha valjak uključen u pakovanje poboljšava cirkulaciju i omogućava bolju apsorpciju aktivnih sastojaka. Dugotrajnom upotrebom, koža vrata postaje hidrirana, zategnuta i glatka, sa smanjenim znakovima starenja. Aktivni sastojci Hidrolizovani kolagen (73,5%) Hidrolizovani kolagen je oblik kolagena razložen na manje peptide, što omogućava lakšu apsorpciju u kožu. Ovaj sastojak pomaže u poboljšanju elastičnosti i čvrstoće kože, smanjujući pojavu finih linija i bora. Takođe, pruža hidrataciju, čineći kožu mekom i glatkom. Podržava regeneraciju kože, ubrzavajući zaceljivanje manjih oštećenja i poboljšavajući ukupnu teksturu kože. Retinal (0,2%) Retinal, poznat i kao retinaldehid, je efikasna forma vitamina A koja se direktno pretvara u retinoičnu kiselinu u koži, pružajući snažne anti-age benefite. Stimulacijom sinteze kolagena, retinal pomaže u smanjenju finih linija i bora, poboljšavajući elastičnost i čvrstoću kože. Takođe, ubrzava obnavljanje ćelija, što rezultira ujednačenijim tonom i teksturom kože. Njegova sposobnost da reguliše proizvodnju melanina može smanjiti pojavu hiperpigmentacija i tamnih mrlja. Hijaluronska kiselina Hijaluronska kiselina je snažan humektant koji može vezati vodu do 1000 puta više od svoje težine, pružajući intenzivnu hidrataciju koži. Pomaže u popunjavanju finih linija i bora, poboljšavajući elastičnost i glatkoću kože. Takođe, igra ključnu ulogu u obnavljanju i održavanju kožne barijere, što je esencijalno za zdravu kožu. Njena sposobnost da zadrži vlagu čini je idealnim sastojkom za suvu i dehidriranu kožu. Dodaj u listu želja Dodaj u listu želja', 'CKD Retino Collagen Small Molecule 300 Guasha Neck Cream je specijalizovana krema za negu vrata koja kombinuje niskomolekularni kolagen i retinal za efikasnu borbu protiv bora i opuštene kože. Ova formula hidrira, zateže i poboljšava elastičnost kože, pružajući mladalački izgled.', 'https://beauty-health.rs/wp-content/uploads/2025/01/CKD-Retino-Collagen-Small-Molecule-300-Guasha-Neck-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
