INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1081, 25, 'Benton Vitamin C Serum', 'benton-vitamin-c-serum', 'Ključne prednosti: Posvetljuje i ujednačava ten: Smanjuje vidljivost tamnih mrlja i hiperpigmentacija. Hidrira i regeneriše: Hijaluronska kiselina obezbeđuje intenzivnu hidrataciju, dok pomaže u oporavku oštećene kože. Antioksidativna zaštita: Vitamin C štiti kožu od slobodnih radikala i znakova starenja. Kome je namenjen? Ovaj serum je savršen za osobe sa umornom, neujednačenom kožom ili kožom sklonom tamnim mrljama i pigmentacijama. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo Benton Vitamin C Serum? Vitamin C Serum donosi osveženje i regeneraciju vašoj koži Vitamin C u stabilnom obliku dubinski prodire u kožu, smanjujući hiperpigmentacija i vraćajući koži blistav izgled. Uz dodatak hijaluronske kiseline, koža postaje duboko hidrirana, čvrsta i elastična, sa nežnim i baršunastim osećajem. Serum takođe sadrži ekstrakte zelenog čaja i borovnice koji smiruju kožu i štite je od oksidativnog stresa. Dugotrajnom upotrebom, koža postaje ujednačena, glatkija i otpornija na znakove starenja. Ova lagana i brzo upijajuća formula ne ostavlja lepljiv trag, već koži pruža osećaj svežine tokom celog dana. Aktivni sastojci Askorbinska kiselina (Vitamin C) Askorbinska kiselina je snažan antioksidans koji neutralizuje slobodne radikale, štiteći kožu od oštećenja izazvanih UV zračenjem i zagađenjem. Potiče sintezu kolagena, što poboljšava elastičnost kože i smanjuje pojavu finih linija i bora. Takođe, inhibira proizvodnju melanina, pomažući u posvetljavanju hiperpigmentacija i ujednačavanju tena. Njena sposobnost da poboljša barijernu funkciju kože doprinosi boljoj hidrataciji i otpornosti kože na spoljašnje agresore. Redovnom upotrebom, koža postaje blistavija, čvršća i zdravijeg izgleda. ​ Glutation Glutation je tripeptid poznat po svojim snažnim antioksidativnim svojstvima, koji štiti ćelije kože od oksidativnog stresa i oštećenja. Pomaže u detoksikaciji kože, uklanjajući štetne toksine i slobodne radikale. Takođe, inhibira aktivnost enzima tirozinaze, što može doprineti posvetljavanju hiperpigmentacija i ujednačavanju tena. Povećava otpornost kože na UV zračenje i druge spoljašnje agresore. Njegova uloga u regeneraciji drugih antioksidanasa, poput vitamina C i E, dodatno pojačava zaštitu kože. Redovnom upotrebom, koža postaje svetlija, čistija i zdravijeg izgleda. ​ INCIDecoder Tokoferol (Vitamin E) Tokoferol je moćan antioksidans koji štiti kožu od oštećenja izazvanih slobodnim radikalima i UV zračenjem. Pomaže u održavanju hidratacije kože, jačajući njenu barijernu funkciju i sprečavajući transepidermalni gubitak vode. Ima protivupalna svojstva koja umiruju iritacije i crvenilo, čineći ga pogodnim za osetljivu kožu. Takođe, poboljšava elastičnost kože, smanjujući pojavu finih linija i bora. U kombinaciji sa vitaminom C, pruža pojačanu zaštitu od oksidativnog stresa. Redovnom upotrebom, koža postaje mekša, glatkija i zaštićenija. ​ Ferulinska kiselina Ferulinska kiselina je snažan antioksidans koji neutralizuje slobodne radikale, štiteći kožu od oštećenja izazvanih UV zračenjem i zagađenjem. Povećava stabilnost i efikasnost drugih antioksidanasa, poput vitamina C i E, pružajući sinergistički efekat u zaštiti kože. Ima protivupalna svojstva koja pomažu u smanjenju crvenila i iritacija. Takođe, može doprineti posvetljavanju hiperpigmentacija, ujednačavajući ten. Pomaže u očuvanju integriteta ćelijskih membrana, što doprinosi zdravijem izgledu kože. Redovnom upotrebom, koža postaje zaštićenija, blistavija i ujednačenijeg tona. Dodaj u listu želja Dodaj u listu želja', 'Benton Vitamin C Serum je moćna, ali nežna formula koja sadrži 20% stabilnog vitamina C i glutationa kako bi pružila koži ujednačen ten, posvetlila tamne mrlje i poboljšala elastičnost. Ovaj serum je idealan za hidrataciju, regeneraciju i zaštitu kože od oksidativnog stresa.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Benton-Vitamin-C-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
