INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1082, 17, 'Axis-Y Vegan Collagen Eye Serum', 'axis-y-vegan-collagen-eye-serum', 'Ključne prednosti: Podstiče elastičnost: Veganski kolagen pomaže u jačanju strukture kože i vraća joj mladalački izgled. Intenzivna hidratacija: Dubinski hidrira kožu, smanjuje suvoću i poboljšava teksturu područja oko očiju. Smanjuje tamne kolutove: Biljni ekstrakti i umirujući sastojci osvežavaju kožu i smanjuju znakove umora. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za osobe koje žele da smanje pojavu bora, fine linije i tamne kolutove. Pogodan je za osobe sa osetljivom kožom koje traže efikasnu i prirodnu negu područja oko očiju. Zašto volimo AXIS-Y Vegan Collagen Eye Serum? Vegan Collagen Eye Serum je više od običnog seruma za oči – to je sveobuhvatno rešenje za negu i revitalizaciju osetljive kože. Formulisan sa veganskim kolagenom, pomaže u obnavljanju elastičnosti i jačanju tanke kože oko očiju. Njegova lagana, brzo upijajuća formula pruža trenutni osećaj svežine, dok dubinski hidrira i smanjuje suvoću. Zahvaljujući prirodnim ekstraktima, poput zelenog čaja i ekstrakta nevena, serum efikasno umiruje kožu, smanjujući vidljive znakove umora. Redovnom upotrebom, tamni kolutovi postaju manje primetni, bore se ublažavaju, a koža oko očiju deluje blistavo i negovano. Aktivni sastojci Vegan kolagen Vegan kolagen je biljna alternativa tradicionalnom kolagenu, dizajnirana da poboljša elastičnost i čvrstinu kože. Pomaže u smanjenju pojave finih linija i bora, posebno u delikatnoj zoni oko očiju. Ovaj sastojak hidrira kožu, čineći je glatkom i mekom na dodir. Takođe, podržava prirodnu barijeru kože, štiteći je od spoljašnjih agresora. Njegova lagana tekstura omogućava brzo upijanje bez osećaja težine ili masnoće. Redovna upotreba proizvoda sa vegan kolagenom može doprineti mladalačkom i osveženom izgledu kože. ​ 5-peptidni kompleks Ovaj kompleks sadrži pet različitih peptida koji sinergijski deluju na poboljšanje strukture i elastičnosti kože. Peptidi stimulišu sintezu kolagena i elastina, ključnih proteina za čvrstoću i elastičnost kože. Pomažu u smanjenju dubine bora i finih linija, pružajući glatkiji izgled kože. Takođe, peptidi imaju sposobnost da poboljšaju regeneraciju kože, ubrzavajući proces obnove ćelija. Njihova antiinflamatorna svojstva pomažu u smirivanju iritacija i crvenila. Redovna upotreba proizvoda sa peptidima može rezultirati čvršćom i otpornijom kožom. ​ Tri tipa hijaluronske kiseline Serum sadrži hijaluronsku kiselinu, hidrolizovanu hijaluronsku kiselinu i natrijum hijaluronat. Ovi sastojci deluju kao snažni humektanti, privlačeći i zadržavajući vlagu u koži. Pružaju dubinsku hidrataciju, poboljšavajući elastičnost i punoću kože. Takođe, pomažu u popunjavanju finih linija, čineći kožu glatkijom. Njihova sposobnost da zadrže veliku količinu vode održava kožu hidriranom tokom dužeg perioda. Redovna upotreba proizvoda sa hijaluronskom kiselinom može doprineti svežijem i blistavijem izgledu kože. ​ Ekstrakti bogati vitaminom C (zelena jabuka, zelena šljiva, zeleni grožđe) Ovi voćni ekstrakti bogati su vitaminom C, poznatim po svojim antioksidativnim svojstvima. Pomažu u neutralizaciji slobodnih radikala, štiteći kožu od oksidativnog stresa. Vitamin C posvetljuje kožu, smanjujući pojavu tamnih kolutova i neujednačenog tena. Takođe, stimuliše sintezu kolagena, poboljšavajući elastičnost i čvrstinu kože. Njihova prirodna svojstva pomažu u osvežavanju i revitalizaciji umorne kože. Redovna upotreba proizvoda sa ovim ekstraktima može doprineti blistavijem i zdravijem izgledu kože. ​ Dodaj u listu želja Dodaj u listu želja', 'AXIS-Y Vegan Collagen Eye Serum je inovativni serum za negu kože oko očiju koji kombinuje veganski kolagen i prirodne ekstrakte kako bi umanjio vidljive znake starenja i osvežio osetljivo područje. Ovaj serum pruža dubinsku hidrataciju, čini kožu čvršćom i smanjuje tamne kolutove i otečenost.', 'https://beauty-health.rs/wp-content/uploads/2025/01/AXIS-Y-Vegan-Collagen-Eye-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
