INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1085, 11, 'Anua Heartleaf Pore Clay Pack', 'anua-heartleaf-pore-clay-pack', 'Ključne prednosti: Dubinsko čišćenje i detoksikacija: Glinena baza apsorbuje višak ulja i toksine, ostavljajući kožu čistu i osveženu. Smirivanje i obnavljanje kože: Ekstrakt srcolikog lista umiruje iritacije i pruža antibakterijsku zaštitu. Smanjenje pora: Redovnom upotrebom, maska vidljivo sužava pore i poboljšava teksturu kože. Kome je namenjena? Idealna za osobe sa masnom, kombinovanom i kožom sklonom aknama, kao i za one koje žele rešenje za proširene pore i kontrolu sebuma. Pogodna je i za osetljivu kožu zahvaljujući umirujućim sastojcima. Zašto volimo Anua Heartleaf Pore Clay Pack? Heartleaf Pore Clay Pack pruža vašu rutinu dubinskog čišćenja sa snažnim, ali umirujućim učinkom. Glinena baza efikasno apsorbuje višak sebuma, dok uklanja nečistoće i toksine iz pora, što čini kožu čistom i matiranom, ali bez osećaja zatezanja. Ekstrakt Heartleaf-a poznat je po svojim antibakterijskim i antiinflamatornim svojstvima, smirujući crvenilo i smanjujući iritacije. Uz redovnu upotrebu, maska deluje na smanjenje veličine pora i ujednačavanje teksture kože, čineći je glatkom i zdravom. Osvežavajuća i kremasta tekstura lako se nanosi i ispira, ostavljajući kožu osveženom, revitalizovanom i spremnom za dalje korake nege. Aktivni sastojci Kaolin (20%) Kaolin je blaga glina koja efikasno apsorbuje višak sebuma i nečistoće iz pora, pružajući dubinsko čišćenje bez isušivanja kože. Njegova nežna priroda čini ga pogodnim za sve tipove kože, uključujući osetljivu. Pomaže u smanjenju masnog sjaja i ostavlja kožu matiranom i osveženom. Takođe, deluje kao blagi eksfolijant, uklanjajući mrtve ćelije kože i poboljšavajući njenu teksturu. Redovnom upotrebom, koža postaje glatka i mekana. ​ Ekstrakt Houttuynia Cordata (10,1%) Ovaj ekstrakt, poznat i kao srcolisna biljka, ima snažna antioksidativna i antiinflamatorna svojstva koja pomažu u smirivanju iritacija i crvenila kože. Takođe, poseduje antibakterijska svojstva koja mogu pomoći u borbi protiv akni i drugih kožnih problema. Pruža hidrataciju i poboljšava elastičnost kože, čineći je zdravijom i blistavijom. Njegova sposobnost da balansira proizvodnju sebuma doprinosi čistijem i ujednačenijem tenu. Ovaj sastojak je posebno koristan za masnu i problematičnu kožu. ​ Bentonit (35.000 ppm) Bentonit je glina poznata po svojoj sposobnosti da apsorbuje toksine i nečistoće iz kože, pružajući dubinsko čišćenje. Pomaže u smanjenju upala i može ubrzati zaceljivanje kože, što je korisno za osobe sklone aknama. Takođe, poboljšava teksturu kože, ostavljajući je glatkom i osveženom. Njegova sposobnost da zategne pore doprinosi smanjenju njihovog izgleda. Redovnom upotrebom, koža postaje čistija i zdravija. Dodaj u listu želja Dodaj u listu želja', 'Anua Heartleaf Pore Clay Pack je dubinska maska sa glinom i ekstraktom biljke kameleon (Houttuynia Cordata) , koja pomaže u uklanjanju viška sebuma, detoksikaciji kože i sužavanju pora. Ovaj proizvod pruža balans između temeljnog čišćenja i nežne nege, ostavljajući kožu osveženom i glatkom.', 'https://beauty-health.rs/wp-content/uploads/2025/01/Anua-Heartleaf-Pore-Clay-Pack.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
