INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1094, 164, 'Tirtir RED Mask Fit Mini Cushion', 'tirtir-mask-fit-red-mini-cushion', 'Ključne prednosti: Dugotrajna postojanost: Formula osigurava nepromenljiv izgled do 72 sata, uz otpornost na znoj i razmazivanje. Polumat završnica: Pruža prirodan sjaj bez osećaja masnoće, idealno za sve tipove kože. Praktično pakovanje: Kompaktna veličina omogućava jednostavno nošenje i brzo popravljanje šminke tokom dana. Kome je namenjen? Ovaj puder je namenjen svim tipovima kože, uključujući masnu, suvu i mešovitu kožu. Idealan je za osobe koje traže dugotrajnu pokrivenost uz prirodan izgled. Posebno je pogodan za one sa problemima poput crvenila, podočnjaka ili neujednačenog tena. Zašto volimo TIRTIR Mask Fit Red Mini Cushion? Mask Fit Red Mini Cushion donosi savršenu kombinaciju visoke pokrivne moći i lagane teksture, omogućavajući koži da diše dok ostavlja besprekornu završnicu. Polumat efekat pruža balans između hidratacije i kontrole masnoće, čineći ga idealnim za celodnevno nošenje. Njegova formula sadrži prirodne antioksidante koji štite kožu od štetnih spoljašnjih uticaja i usporavaju znakove starenja. Puder se ne prenosi i otporan je na znoj, što ga čini pogodnim za aktivan stil života ili nošenje pod maskom. Kompaktna veličina ovog proizvoda omogućava lako nanošenje u pokretu. https://www.youtube.com/watch?v=-66rG7l3FVg Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit Red Mini Cushion je kompaktni puder u jastučiću sa dugotrajnom, laganom i nadogradivom pokrivenošću, savršen za postizanje prirodnog, blistavog izgleda kože. Njegova formula pruža zaštitu od sunca sa SPF40/PA++ i omogućava koži da diše. Nijanse detaljno možete pogledati na zvaničnom sajtu preparata. Dostupan na prodajnom štandu &#8221; Beauty & Health Factory&#8221; u TC Ušće.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Tirtir-Mask-Fit-Red-Cushion.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
