INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1096, 164, 'Tirtir RED Mask Fit Cushion', 'tirtir-mask-fit-red-cushion', 'Ključne prednosti: Dugotrajna pokrivenost: Ovaj puder obezbeđuje postojanost do 72 sata, otporan je na znoj i ne prenosi se na odeću. Polumat završnica: Pruža prirodan, blistav izgled kože bez prekomernog sjaja, održavajući svežinu tokom celog dana. Širok spektar nijansi: Dostupan u 40 nijansi, prilagođava se različitim tonovima i podtonovima kože, omogućavajući savršeno uklapanje. Kome je namenjen? Mask Fit Red Cushion je pogodan za sve tipove kože, uključujući masnu, mešovitu i suvu. Posebno je koristan za osobe koje traže dugotrajnu, potpunu pokrivenost sa prirodnim izgledom, kao i za one koji žele zaštitu od sunca integrisanu u svoj puder. Zašto volimo Tirtir Mask Fit Red Cushion? Ovaj inovativni puder kombinuje visoku pokrivnu moć sa laganom teksturom, omogućavajući koži da diše dok pruža besprekornu završnicu. Njegova formula obogaćena je antioksidansima poput ekstrakta hibiskusa i propolisa. Oni neguju kožu i poboljšavaju njenu elastičnost. Polumat završnica pruža prirodan sjaj bez prekomernog masnog izgleda. SPF40/PA++ štiti kožu od štetnih UV zraka. Puder je otporan na znoj i ne prenosi se, što ga čini idealnim za nošenje pod maskom ili tokom fizičkih aktivnosti. Širok spektar nijansi omogućava prilagođavanje različitim tonovima kože, osiguravajući ujednačen i prirodan izgled. https://www.youtube.com/watch?v=-66rG7l3FVg Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Mask Fit Red Cushion je visokokvalitetni tečni puder u jastučiću koji pruža dugotrajnu, potpunu pokrivenost sa polumat završnicom, idealan za postizanje blistavog izgleda kože. Njegova lagana formula omogućava koži da diše, dok istovremeno prikriva nesavršenosti i pruža zaštitu od sunca sa SPF40/PA++. Nijanse detaljno možete pogledati na zvaničnom sajtu preparata. Dostupan na prodajnom štandu &#8221; Beauty & Health Factory&#8221; u TC Ušće.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Tirtir-Mask-Fit-Red-Cushion-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
