INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1105, 143, 'Round Lab Birch Juice Hand Cream', 'round-lab-birch-juice-hand-cream', 'Ključne prednosti: Dubinska hidratacija: Tri vrste hijaluronske kiseline prodiru u različite slojeve kože, pružajući optimalnu vlažnost i elastičnost. Jačanje barijere kože: Ceramidi obnavljaju i jačaju zaštitnu barijeru kože, sprečavajući gubitak vlage i štiteći od spoljašnjih agresora. Nega noktiju: Keratin u formuli pomaže u jačanju lomljivih noktiju, čineći ih otpornijim i zdravijim. Kome je namenjena? Ova krema je idealna za osobe sa suvom i osetljivom kožom ruku, kao i za one čiji su nokti skloni lomljenju i slabosti. Takođe je pogodna za sve koji traže nemasnu, brzo upijajuću formulu za svakodnevnu upotrebu. Zašto volimo ROUND LAB Birch Juice Hand Cream? Birch Juice Hand Cream koristi sok azijske bele breze (Betula Platyphylla Japonica Juice), bogat aminokiselinama, mineralima i vitaminima, koji pruža intenzivnu hidrataciju i umiruje iritacije. Tri vrste hijaluronske kiseline različitih molekularnih težina omogućavaju višeslojnu hidrataciju, zadržavajući vlagu u koži i poboljšavajući njenu elastičnost. Ceramidi obnavljaju lipidnu barijeru kože, štiteći je od dehidratacije i štetnih spoljašnjih faktora. Shea puter i skvalan dodatno omekšavaju i hrane kožu, ostavljajući je glatkom i mekom na dodir. Keratin jača strukturu noktiju, smanjujući njihovu lomljivost i poboljšavajući njihov izgled. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Birch Juice Hand Cream pruža intenzivnu hidrataciju i negu za suve, ispucale ruke, zahvaljujući kombinaciji brezinog soka, ceramida i hijaluronske kiseline. Ova bogata krema se brzo upija, ostavljajući kožu mekom i glatkom, bez masnih tragova.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-Birch-Juice-Hand-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
