INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1111, 111, 'Mary & May Rice Niacin 10% Triple Vitamin Serum', 'mary-may-rice-niacin-10-triple-vitamin-serum', 'Ključne prednosti: Posvetljivanje kože: Visoka koncentracija niacinamida i vitamina C pomaže u smanjenju tamnih fleka i ujednačavanju tena. Hidratacija i umirenje: Ekstrakt pirinča i pantenol pružaju dubinsku hidrataciju i umiruju iritacije, čineći kožu mekom i elastičnom. Antioksidativna zaštita: Vitamini E i glutation štite kožu od oksidativnog stresa i prevremenog starenja. Kome je namenjen? Ovaj serum je idealan za osobe sa neujednačenim tenom, hiperpigmentacijom ili umornom kožom bez sjaja. Pogodan je za sve tipove kože, uključujući i osetljivu, zahvaljujući blagoj formuli bez iritansa. Zašto volimo Mary & May Rice Niacin 10% Triple Vitamin Serum? Niacin 10% Triple Vitamin Serum pruža trostruku akciju u posvetljivanju kože, blokirajući aktivaciju melanina, oksidaciju i migraciju ćelija epidermisa. Klinički je dokazano da poboljšava svetlinu kože za 19%, smanjuje fleke za 15% i povećava sjaj za 14%. Organski ekstrakt Hiami pirinča iz Haenama, Koreja, bogat vitaminima B, aminokiselinama i ferulinskom kiselinom, hrani i revitalizuje kožu, ostavljajući je zdravom i blistavom. Pantenol dodatno umiruje i hidrira kožu, čineći ovaj serum pogodnim za svakodnevnu upotrebu bez iritacija. Aktivni sastojci Ekstrakt pirinča (73%) Ekstrakt pirinča je tradicionalni sastojak u nezi kože poznat po svom posvetljujućem, umirujućem i hranljivom dejstvu. Bogat vitaminima, mineralima i aminokiselinama, on jača prirodnu barijeru kože i pomaže u njenoj regeneraciji. Doprinosi ujednačenju tena i smanjenju tamnih fleka, dok istovremeno poboljšava teksturu kože. Ima sposobnost da zadrži vlagu u koži, ostavljajući je mekom, hidriranom i glatkom. Niacinamid (10%) Niacinamid, poznat i kao vitamin B3, je višestruko delotvoran sastojak koji pomaže u smanjenju hiperpigmentacija i ujednačenju tena. Deluje tako što inhibira transport melanina, čime sprečava stvaranje novih tamnih fleka i posvetljuje postojeće. Takođe jača zaštitnu barijeru kože, poboljšava hidrataciju i smanjuje upalne procese. Ima blago seboregulativno dejstvo, pa pomaže i kod masne i kombinovane kože. Vitamin C (Ascorbic Acid) Vitamin C je snažan antioksidans koji štiti kožu od slobodnih radikala i UV oštećenja, istovremeno posvetljujući ten i podstičući sintezu kolagena. Efikasno deluje na tamne mrlje, neujednačen ten i beživotan izgled kože. Takođe poboljšava elastičnost i tonus, doprinoseći svežem i zdravom izgledu lica. U kombinaciji sa niacinamidom i drugim vitaminima, ima pojačan efekat posvetljavanja. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Retinol 0,1% Bakuchiol Cica Serum kombinuje 0,1% čistog retinola, biljni bakučiol i ekstrakt centela azijatike kako bi poboljšao elastičnost kože, smanjio pojavu bora i umirio iritacije. Ovaj serum efikasno rešava probleme poput finih linija, proširenih pora i osetljive kože sklone crvenilu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Mary-May-Rice-Niacin-10-Triple-Vitamin-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
