INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1112, 111, 'Mary & May Retinol 0.1% Bakuchiol Cica Serum', 'mary-may-retinol-0-1-bakuchiol-cica-serum', 'Ključne prednosti: Poboljšava elastičnost kože: Kombinacija retinola i bakučiola stimuliše proizvodnju kolagena, čineći kožu čvršćom i glatkijom. Smanjuje bore i fine linije: Aktivni sastojci pomažu u smanjenju vidljivosti znakova starenja, pružajući mladalačkiji izgled. Umiruje i regeneriše kožu: Ekstrakt centela azijatike deluje protivupalno, smanjujući iritacije i crvenilo, dok pospešuje regeneraciju kože. Kome je namenjen? Ovaj serum je idealan za osobe sa zrelim tipom kože koje žele da smanje vidljivost bora i poboljšaju elastičnost. Takođe je pogodan za one sa osetljivom kožom sklonom iritacijama, zahvaljujući umirujućim svojstvima centela azijatike. Zašto volimo Mary & May Retinol 0.1% Bakuchiol Cica Serum? Retinol 0,1% Bakuchiol Cica Serum predstavlja sinergiju moćnih sastojaka koji zajednički deluju na poboljšanje teksture i tonusa kože. Retinol, poznat po svojoj sposobnosti da ubrza obnavljanje ćelija, u koncentraciji od 0,1% efikasno smanjuje fine linije i bore bez izazivanja iritacija. Bakučiol, biljna alternativa retinolu, pruža slične benefite uz manji rizik od neželjenih reakcija, čineći serum pogodnim i za osetljivu kožu. Ekstrakt centela azijatike dodatno umiruje kožu, smanjujući upale i crvenilo, dok istovremeno pospešuje regeneraciju i jačanje barijere kože. Redovnom upotrebom, koža postaje vidljivo čvršća, glatkija i otpornija, sa smanjenom pojavom pora i ujednačenijim tenom. Aktivni sastojci Retinol (0.1%) Retinol, oblik vitamina A, je dermatološki potvrđen sastojak koji stimuliše proizvodnju kolagena i ubrzava ćelijski promet kože. Efikasan je u smanjenju vidljivosti bora, finih linija i pigmentacija, čineći kožu glatkom i ujednačenom. Njegova koncentracija od 0.1% pruža balans između efikasnosti i minimalnog iritativnog potencijala, idealno za početnike u retinol rutini. Takođe pomaže u smanjenju zapušenih pora i akni, pružajući koži jasniji izgled. Bakuchiol Bakuchiol je prirodna, biljna alternativa retinolu dobijena iz biljke Psoralea corylifolia, koja pruža slične benefite bez izazivanja iritacija. Deluje antioksidativno i antiinflamatorno, pomažući u smanjenju znakova starenja poput bora i gubitka elastičnosti. Za razliku od retinola, ne izaziva crvenilo, suvoću ili perutanje, što ga čini pogodnim za osetljivu kožu. Bakuchiol stimuliše sintezu kolagena i ujednačava ten, pomažući u borbi protiv hiperpigmentacija. Centella Asiatica (Cica) Centella Asiatica, poznata i kao Cica, je moćan biljni sastojak koji umiruje, obnavlja i jača kožnu barijeru. Bogata je aktivnim komponentama kao što su madecassoside i asiaticoside koje deluju protivupalno i stimulišu zaceljivanje. Posebno je pogodna za osetljivu i nadraženu kožu, jer ublažava crvenilo i iritacije izazvane aktivnim sastojcima poput retinola. Cica pomaže u hidrataciji kože, poboljšavajući njenu elastičnost i otpornost. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Retinol 0,1% Bakuchiol Cica Serum kombinuje 0,1% čistog retinola, biljni bakučiol i ekstrakt centela azijatike kako bi poboljšao elastičnost kože, smanjio pojavu bora i umirio iritacije. Ovaj serum efikasno rešava probleme poput finih linija, proširenih pora i osetljive kože sklone crvenilu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Mary-May-Retinol-0.1-Bakuchiol-Cica-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
