INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1113, 85, 'iUNIK Calendula Complete Cleansing Oil', 'iunik-calendula-complete-cleansing-oil', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja čak i vodootpornu šminku i nečistoće, ostavljajući kožu čistom i osveženom. Hidratacija i nega: Biljna ulja pružaju potrebnu vlagu, sprečavajući isušivanje kože tokom čišćenja. Umirujuće dejstvo: Ekstrakt nevena poznat je po svojim umirujućim svojstvima, što ga čini pogodnim za osetljivu kožu. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući suvu, masnu i osetljivu. Posebno je koristan za one koji traže efikasan način za uklanjanje šminke bez iritacije ili isušivanja kože. Zašto volimo iUNIK Calendula Complete Cleansing Oil? Calendula Complete Cleansing Oil pruža temeljno čišćenje lica. Efikasno uklanjai šminku, uključujući vodootpornu maskaru, kao i višak sebuma i nečistoća nakupljenih tokom dana. Njegova lagana tekstura omogućava lako nanošenje i masažu. Biljna ulja poput ulja suncokreta i jojobe hrane kožu i održavaju njenu prirodnu ravnotežu vlage. Ekstrakt cveta nevena deluje umirujuće, smanjujući crvenilo i iritacije, što ga čini pogodnim za osetljivu kožu. Redovnom upotrebom, koža postaje mekša, glatka i zdravijeg izgleda, bez osećaja zatezanja ili suvoće nakon čišćenja. Aktivni sastojci Ekstrakt cveta nevena (Calendula Officinalis Flower Extract) Ekstrakt cveta nevena poznat je po svojim umirujućim i antiinflamatornim svojstvima, pomažući u smanjenju crvenila i iritacija na osetljivoj koži. Bogat je flavonoidima, koji deluju kao antioksidansi, štiteći kožu od oksidativnog stresa i slobodnih radikala. Takođe, podstiče regeneraciju kože, ubrzavajući proces zarastanja manjih oštećenja. Ulje semenki suncokreta (Helianthus Annuus Seed Oil) Ulje semenki suncokreta je bogato esencijalnim masnim kiselinama, poput linolne kiseline, koje pomažu u održavanju integriteta kožne barijere i zadržavanju vlage. Sadrži visok nivo vitamina E, snažnog antioksidansa koji štiti kožu od slobodnih radikala i prevremenog starenja. Ulje semenki suncokreta je lagano i nekomedogeno, što znači da ne zapušava pore, čineći ga pogodnim za sve tipove kože. Kanola ulje (Canola Oil) Kanola ulje je lagano ulje koje pruža osećaj svežine na koži, dok istovremeno pruža dubinsku hidrataciju. Bogat je vitaminima E i K, kao i esencijalnim masnim kiselinama koje pomažu u održavanju zdrave kožne barijere. Njegova emolijentna svojstva pomažu u omekšavanju i zaglađivanju kože, poboljšavajući njen ukupni izgled. Kanola ulje takođe ima antioksidativna svojstva, štiteći kožu od oksidativnog stresa i slobodnih radikala. Ulje cveta ilang-ilanga (Cananga Odorata Flower Oil) Ulje cveta ilang-ilanga poznato je po svojim opuštajućim aromaterapijskim svojstvima, pomažući u smanjenju stresa i napetosti. Na koži deluje umirujuće, smanjujući upale i iritacije. Takođe, pomaže u regulaciji proizvodnje sebuma, što može biti korisno za masnu i kombinovanu kožu. Ulje ilang-ilanga ima antiseptička svojstva, pomažući u održavanju čistoće kože i sprečavanju nesavršenosti. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Calendula Complete Cleansing Oil je blagi uljani čistač formulisan sa 94% prirodnih biljnih ulja, namenjen za efikasno uklanjanje šminke i nečistoća, dok istovremeno umiruje i hidrira kožu. Glavni sastojci uključuju ulje suncokreta, ekstrakt cveta nevena, ulje jojobe i ulje makadamije, koji zajedno pružaju dubinsko čišćenje i negu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/iUNIK-Calendula-Complete-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
