INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1114, 82, 'Innisfree Super Volcanic Pore Clay Mask', 'innisfree-super-volcanic-pore-clay-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Vulkanski pepeo uklanja nečistoće i višak sebuma, ostavljajući kožu čistom i svežom. Smanjenje pora i eksfolijacija: Deluje kao blagi eksfolijant koji uklanja mrtve ćelije kože i poboljšava teksturu. Kontrola masnoće: Pruža mat efekat i dugotrajnu kontrolu sebuma bez isušivanja kože. Kome je namenjena? Ova maska je idealna za osobe sa masnom i kombinovanom kožom koje žele da smanje vidljivost pora i kontrolišu višak sebuma. Takođe je pogodna za one koji traže intenzivno čišćenje i osvežavanje kože. Zašto volimo Innisfree Super Volcanic Pore Clay Mask? Super Volcanic Pore Clay Mask kombinuje moć prirodnih minerala sa tehnologijom za dubinsko čišćenje. Vulkanski pepeo, bogat mineralima, efikasno upija višak sebuma i uklanja nečistoće iz pora. Blagi eksfolijantni efekat pomaže u obnavljanju teksture kože. Formula sadrži i hidratantne komponente koje sprečavaju isušivanje, ostavljajući kožu glatkom i hidriranom. Nakon redovne upotrebe, koža postaje čistija, pore manje vidljive, a tekstura lica znatno poboljšana. Osvežavajući efekat maske čini je idealnom za opuštanje i dubinsko osvežavanje kože. Aktivni sastojci Vulkanski klasteri (Volcanic Clusters) Vulkanski klasteri su prirodni minerali nastali od očvrsle vulkanske lave sa ostrva Jeju, bogati elementima u tragovima koji deluju kao prirodni apsorbenti. Ovi čestice deluju tako što upijaju višak sebuma i nečistoće iz pora, ostavljajući kožu matiranom i čistom. Njihova visoka poroznost omogućava dublje čišćenje pora, što doprinosi smanjenju pojave mitisera i akni. Takođe imaju blago detoksikaciono dejstvo, oslobađajući kožu od toksina i zagađivača iz okoline. Vulkanski klasteri poboljšavaju teksturu kože i čine je glatkom na dodir, bez osećaja zategnutosti. AHA (Mlečna kiselina / Lactic Acid) Mlečna kiselina je alfa-hidroksi kiselina (AHA) koja blago eksfolira površinske slojeve kože uklanjajući mrtve ćelije i ubrzavajući ćelijski obrt. Pomaže u otvaranju zapušenih pora i poboljšava prodiranje ostalih aktivnih sastojaka. Ovaj sastojak istovremeno hidrira kožu jer deluje kao humektant, zadržavajući vlagu u epidermi. U maski deluje sinergijski sa vulkanskim česticama, pružajući dvostruki efekat čišćenja i obnavljanja kože. Redovnom upotrebom mlečna kiselina smanjuje vidljivost pora i neujednačene teksture, ostavljajući kožu glatkijom i svetlijom. Dodaj u listu želja Dodaj u listu želja', 'Innisfree Super Volcanic Pore Clay Mask je intenzivna glinena maska obogaćena vulkanskim pepelom sa Jeju ostrva, koja dubinski čisti pore i apsorbuje višak sebuma. Namenjena je za masnu i kombinovanu kožu, pomažući u smanjenju vidljivosti pora i poboljšanju teksture kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Innisfree-Super-Volcanic-Pore-Clay-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
