INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1115, 39, 'Cos De BAHA GS AHA BHA Facial Toner', 'cos-de-baha-gs-aha-bha-facial-toner', 'Ključne prednosti: Dubinsko čišćenje pora: Salicilna kiselina prodire u pore, uklanja višak sebuma i nečistoće, smanjujući pojavu mitesera i akni. Poboljšava teksturu kože: Glikolna kiselina eksfolira površinski sloj kože, otkrivajući glatkiju i sjajniju kožu. Ujednačava ten: Niacinamid posvetljuje kožu i smanjuje vidljivost tamnih fleka, doprinoseći ravnomernijem tenu. Kome je namenjen? Ovaj tonik je idealan za osobe sa masnom i kombinovanom kožom sklonom aknama, kao i za one koje žele poboljšati teksturu i ujednačenost tena. Pogodan je za sve tipove kože, ali se preporučuje oprez kod osetljive kože zbog prisustva kiselina. Zašto volimo Cos De BAHA GS AHA BHA Facial Toner? GS AHA BHA Facial Toner pruža sveobuhvatnu eksfolijaciju kombinovanjem alfa-hidroksi (AHA) i beta-hidroksi kiselina (BHA). Glikolna kiselina (7%) deluje na površini kože, uklanjajući mrtve ćelije i poboljšavajući sjaj i glatkoću. Salicilna kiselina (0,5%) prodire duboko u pore, razgrađujući sebum i nečistoće, što pomaže u prevenciji akni i smanjenju upala. Niacinamid dodatno posvetljuje kožu i poboljšava barijernu funkciju. Ekstrakt aloe vere umiruje i hidrira kožu, smanjujući iritacije. Redovnom upotrebom, tonik doprinosi čistijoj, glatkijoj i zdravijoj koži sa ujednačenim tenom. Aktivni sastojci Glikolna kiselina (7%) Glikolna kiselina je alfa-hidroksi kiselina (AHA) poznata po svojoj sposobnosti da eksfolira površinski sloj kože, uklanjajući mrtve ćelije i poboljšavajući teksturu i tonus kože. Ona prodire u površinski sloj kože, stimulišući proizvodnju kolagena, što može smanjiti pojavu finih linija i bora. Takođe, pomaže u ujednačavanju tena smanjujući hiperpigmentacije i tamne mrlje. Glikolna kiselina može poboljšati hidrataciju kože povećavajući sposobnost zadržavanja vlage. Njena redovna upotreba može rezultirati sjajnijom i glatkijom kožom. Salicilna kiselina (0,5%) Salicilna kiselina je beta-hidroksi kiselina (BHA) koja deluje kao efikasan eksfolijant, prodireći u pore i uklanjajući nakupljeni sebum i nečistoće. Ima antiinflamatorna svojstva, što je čini idealnom za tretiranje akni i smanjenje crvenila. Redovnom upotrebom, salicilna kiselina može smanjiti pojavu mitesera i bubuljica, poboljšavajući ukupni izgled kože. Takođe, pomaže u regulaciji proizvodnje sebuma, što je korisno za masnu kožu. Njena sposobnost da eksfolira bez mehaničkog trenja čini je pogodnom za osetljivu kožu sklonu iritacijama. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA GS AHA BHA Facial Toner je eksfolijantni tonik formulisan sa 7% glikolne kiseline (AHA) i 0,5% salicilne kiseline (BHA), namenjen za uklanjanje mrtvih ćelija kože i poboljšanje teksture kože. Ovaj proizvod efikasno čisti pore, smanjuje pojavu akni i doprinosi ujednačenom tenu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Cos-De-BAHA-GS-AHA-BHA-Facial-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
