INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1117, 72, 'Heimish All Clean Balm Mandarin', 'heimish-all-clean-balm-mandarin', 'Ključne prednosti: Višenamensko čišćenje: Efikasno uklanja vodootpornu šminku, prljavštinu i višak sebuma, ostavljajući kožu temeljno čistom i osveženom. Ne izaziva iritacije: Blaga formula prilagođena je čak i osetljivoj koži, bez peckanja očiju ili neprijatnog osećaja. Dubinska hidratacija: Prirodni emolijenti i ekstrakti hrane kožu i sprečavaju isušivanje, održavajući njenu mekoću i ravnotežu. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože, uključujući osetljivu i aknama sklonu kožu. Posebno je koristan za one koji traže efikasno i nežno sredstvo za uklanjanje šminke i nečistoća, uz osvežavajući miris mandarine. Zašto volimo Heimish All Clean Balm Mandarin? All Clean Balm Mandarin pruža sveobuhvatno rešenje za čišćenje kože lica. Njegova transformativna tekstura prelazi iz čvrstog balzama u svilenkasto ulje, omogućavajući lako uklanjanje čak i najotpornije šminke i nečistoća. Obogaćen prirodnim ekstraktima poput papaje i moringe, ovaj balzam blago eksfolira kožu, uklanja mrtve ćelije i pruža dubinsku hidrataciju. Ekstrakt mandarine dodaje osvežavajući miris, dok umirujuća formula ne izaziva iritacije. Nakon upotrebe, koža ostaje čista, glatka i revitalizovana, bez osećaja zatezanja ili suvoće. Aktivni sastojci Ulje mandarine (Citrus Unshiu Fruit Oil) Ovo ulje je poznato po svojim osvežavajućim i revitalizujućim svojstvima. Bogato je vitaminom C i antioksidansima koji pomažu u borbi protiv slobodnih radikala, posvetljuju ten i poboljšavaju teksturu kože. Njegova prirodna aroma pruža umirujući efekat tokom čišćenja, pretvarajući rutinu nege u spa iskustvo. Takođe, ulje mandarine pomaže u balansiranju proizvodnje sebuma, što je korisno za masnu i kombinovanu kožu. Njegova antiinflamatorna svojstva mogu smanjiti crvenilo i iritacije, čineći ga pogodnim za osetljivu kožu. Pored toga, ulje mandarine doprinosi regeneraciji ćelija kože, što može poboljšati njen ukupni izgled i sjaj. Shea puter (Butyrospermum Parkii Butter) Prirodni emolijent koji pruža dubinsku hidrataciju i ishranu koži. Bogat je masnim kiselinama i vitaminima, posebno vitaminom E, koji pomaže u obnavljanju barijere kože i zadržavanju vlage. Shea puter omekšava kožu i poboljšava njenu elastičnost, što je čini glatkom i podatnom. Njegova antiinflamatorna svojstva mogu pomoći u smanjenju iritacija i crvenila, što je korisno za osetljivu kožu. Takođe, shea puter pruža zaštitu od spoljašnjih agresora, poput zagađenja i vetra, formirajući zaštitni sloj na površini kože. Njegova lagana tekstura omogućava lako upijanje bez ostavljanja masnog traga, što ga čini pogodnim za sve tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Heimish All Clean Balm Mandarin je veganski, hipoalergeni balzam za čišćenje lica koji se pretvara u ulje, efikasno uklanjajući šminku, nečistoće i višak sebuma. Obogaćen mandarinom i prirodnim ekstraktima, pruža osvežavajući citrusni miris i luksuzni spa-efekat tokom čišćenja.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Heimish-All-Clean-Balm-Mandarin-2-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
