INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1118, 52, 'Dr.Melaxin Necksphalt ECM Neck Barrier Cream', 'dr-melaxin-necksphalt-ecm-neck-barrier-cream', 'Ključne prednosti: Poboljšava elastičnost kože: ECM-5 i peptidi povećavaju elastičnost kože, čineći je čvršćom i otpornijom. Smanjuje bore i fine linije: Aktivni sastojci poput niacinamida i adenozina deluju na smanjenje vidljivosti bora i finih linija. Intenzivna hidratacija: Hijaluronska kiselina i njeni derivati pružaju dubinsku hidrataciju, ostavljajući kožu mekom i glatkom. Kome je namenjena? Ova krema je idealna za osobe sa zrelom kožom koje žele da poboljšaju izgled i teksturu kože vrata, smanje bore i povećaju elastičnost. Pogodna je za sve tipove kože, uključujući osetljivu. Zašto volimo Dr.Melaxin Necksphalt ECM Neck Barrier Cream? Necksphalt ECM Neck Barrier Cream pruža sveobuhvatnu negu za delikatnu kožu vrata. Kombinacija patentiranog sastojka ECM-5 i liposomiranih peptida deluje sinergijski na povećanje elastičnosti i čvrstine kože, dok niacinamid i adenozin smanjuju vidljivost bora i finih linija. Hijaluronska kiselina i njeni derivati obezbeđuju intenzivnu hidrataciju, poboljšavajući teksturu kože i vraćajući joj mladalački izgled. Redovnom upotrebom, koža vrata postaje zategnutija, glatkija i vidljivo podmlađena. Aktivni sastojci ECM-5 Complex (20,000 ppm) ECM-5 je visoko koncentrovani kompleks koji podržava obnavljanje ekstracelularne matrice kože (ECM), ključne za čvrstoću i elastičnost. Ova matrica je odgovorna za strukturnu stabilnost kože, a njen gubitak dovodi do opuštanja i bora, posebno u regiji vrata. ECM-5 stimuliše sintezu kolagena i elastina, što vidno učvršćuje i podiže kožu. Pomaže i u sprečavanju transepidermalnog gubitka vlage, čime održava optimalnu hidrataciju. Njegovo delovanje je ciljano na “tech neck” problem – bore izazvane ponavljanim pokretima vrata. Redovnom primenom koža vrata postaje čvršća, zategnutija i otpornija na starenje. Liposomal Peptide Complex Liposomalni peptidi su inkapsulirani u mikroskopske lipidne sfere koje omogućavaju dubinsku isporuku aktivnih molekula direktno u dermalne slojeve. Peptidi stimulišu sintezu proteina kože poput kolagena, elastina i laminina, ključnih za čvrstoću i regeneraciju. Zahvaljujući liposomalnom sistemu, njihova stabilnost i efikasnost su znatno povećane. Ovaj kompleks doprinosi zaglađivanju kože vrata i smanjenju vidljivosti horizontalnih linija i neravnina. Takođe pomaže u vraćanju elastičnosti i zadržavanju vlage. Rezultat je snažniji “lifting” efekat i dugotrajna hidratacija osetljive zone vrata. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin Necksphalt ECM Neck Barrier Cream je napredna krema namenjena nezi kože vrata, formulisana sa patentiranim sastojkom ECM-5 i liposomiranim peptidima za poboljšanje elastičnosti i čvrstine kože. Ova krema pruža intenzivnu hidrataciju i pomaže u smanjenju bora i finih linija na vratu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Dr.Melaxin-Necksphalt-ECM-Neck-Barrier-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
