INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1119, 35, 'CKD Retinal 4X Guasha Eye Cream', 'ckd-retinal-4x-guasha-eye-cream', 'Ključne prednosti: Povećava elastičnost kože: Ojačana formula sa retinalom poboljšava čvrstinu i elastičnost kože oko očiju, smanjujući znakove starenja. Smanjuje tamne kolutove: Aktivni sastojci posvetljuju područje ispod očiju, čineći ten ujednačenijim i svežijim. Ugrađeni Gua Sha masažer: Poseban čelični masažer poboljšava cirkulaciju i apsorpciju kreme, pružajući dodatni efekat podizanja i osvežavanja kože. Kome je namenjena? Ova krema je idealna za osobe sa znakovima starenja oko očiju, uključujući opuštenu kožu, duboke bore i tamne kolutove. Pogodna je za sve tipove kože koji zahtevaju dodatnu negu i revitalizaciju u osetljivom području oko očiju. Zašto volimo CKD Retinal 4X Guasha Eye Cream? Retinal 4X Guasha Eye Cream pruža sveobuhvatnu negu za područje oko očiju, kombinujući naprednu formulu sa inovativnim dizajnom. Četvorostruko pojačana formula sa retinalom efikasno smanjuje duboke bore i poboljšava elastičnost kože. Niacinamid posvetljuje tamne kolutove, dajući očima odmoran i mladalački izgled. Ugrađeni Gua Sha masažer od specijalnog čelika omogućava ciljanu masažu, poboljšava mikrocirkulaciju i pospešuje apsorpciju aktivnih sastojaka. Na taj način pružaja dodatni efekat podizanja i osvežavanja kože. Redovnom upotrebom, koža postaje čvršća i vidno revitalizovana, dok se znakovi umora i starenja značajno smanjuju. Aktivni sastojci Retinal (800 ppm) Retinal, poznat i kao retinaldehid, je efikasna forma vitamina A koja se direktno pretvara u retinoičnu kiselinu u koži, pružajući snažne anti-age benefite. Stimulacijom sinteze kolagena, retinal pomaže u smanjenju finih linija i bora, poboljšavajući elastičnost i čvrstoću kože. Takođe, ubrzava obnavljanje ćelija, što rezultira ujednačenijim tonom i teksturom kože. Njegova sposobnost da reguliše proizvodnju melanina može smanjiti pojavu hiperpigmentacija i tamnih mrlja. Za razliku od drugih oblika vitamina A, retinal često izaziva manje iritacija, što ga čini pogodnim za osetljivu kožu. Redovna upotreba proizvoda sa retinalom može značajno poboljšati ukupni izgled i vitalnost kože. Hidrolizovani kolagen Hidrolizovani kolagen je oblik kolagena razložen na manje peptide, što omogućava lakšu apsorpciju u kožu. Pomaže u poboljšanju elastičnosti i čvrstoće kože, smanjujući pojavu finih linija i bora. Takođe, pruža hidrataciju, čineći kožu mekom i glatkom. Podržava regeneraciju kože, ubrzavajući zaceljivanje manjih oštećenja i poboljšavajući ukupnu teksturu kože. Njegova prisutnost u proizvodima za negu kože može doprineti mladalačkom i zdravom izgledu. Hidrolizovani kolagen je kompatibilan sa većinom tipova kože i često se koristi u anti-age proizvodima. Dodaj u listu želja Dodaj u listu želja', 'CKD Retinal 4X Guasha Eye Cream je krema za područje oko očiju koja kombinuje 4 puta jaču formulu sa ugrađenim Gua Sha masažerom od specijalnog čelika. Ovaj proizvod poboljšava elastičnost opuštene kože, smanjuje duboke bore i tamne kolutove, pružajući svež i mladalački izgled.', 'https://beauty-health.rs/wp-content/uploads/2024/12/CKD-Retinal-4X-Guasha-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
