INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1120, 22, 'Beauty of Joseon Matte Sun Stick: Mugwort+Camelia', 'beauty-of-joseon-matte-sun-stick', 'Ključne prednosti: Visoka UV zaštita: SPF 50+ PA++++ štiti kožu od štetnih efekata sunčevog zračenja, sprečavajući prevremeno starenje i oštećenja. Kontrola sebuma i mat finiš: Silika prah apsorbuje višak ulja, pružajući mat izgled bez sjaja tokom celog dana. Hidratacija i umirenje kože: Ekstrakti artemisije i zelenog čaja umiruju iritacije i pružaju potrebnu vlagu, održavajući kožu zdravom i svežom. Kome je namenjen? Ovaj sun stik je idealan za osobe sa masnom i kombinovanom kožom koje traže visoku UV zaštitu bez masnog osećaja. Takođe je pogodan za one koji preferiraju praktičnu i higijensku aplikaciju zaštite od sunca tokom dana. Zašto volimo Beauty of Joseon Matte Sun Stick: Mugwort + Camelia ? Matte Sun Stick: Mugwort + Camellia kombinuje tradicionalne korejske biljne sastojke sa modernom tehnologijom zaštite od sunca. Njegova lagana formula omogućava jednostavno nanošenje bez ostavljanja belih tragova ili lepljivog osećaja. Silika prah efikasno kontroliše lučenje sebuma, održavajući kožu matiranom čak i u toplim i vlažnim uslovima. Ekstrakt artemisije poznat je po svojim umirujućim svojstvima, pomažući u smanjenju crvenila i iritacija, dok ekstrakt kamelije pruža antioksidativnu zaštitu i hidrataciju. Ovaj sun stik je praktičan za nošenje i omogućava brzu i higijensku reaplikaciju zaštite od sunca tokom dana, čak i preko šminke. Aktivni sastojci Ekstrakt Artemisia Capillaris (Mugwort) Artemisia Capillaris, poznata i kao mugwort, tradicionalno se koristi u orijentalnoj medicini zbog svojih umirujućih i isceljujućih svojstava. Ovaj sastojak bogat je vitaminima A i C, kao i mineralima koji pomažu u ishrani i zaštiti kože. Takođe, poznat je po svojim rashlađujućim svojstvima, pomažući u smirivanju nadražene kože i smanjenju crvenila. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i prevremenog starenja. Pomaže u regulaciji proizvodnje sebuma, čineći ga pogodnim za masnu i kombinovanu kožu. Redovna upotreba proizvoda sa mugwort ekstraktom može poboljšati celokupno zdravlje kože, ostavljajući je osveženom i umirenom. SPF i PA zaštita Beauty of Joseon Matte Sun Stick pruža visoku zaštitu od UV zraka, potvrđenu testiranjima u laboratorijama u Koreji i Španiji. SPF testiranje pokazalo je zaštitni faktor koji pruža efikasnu UVB zaštitu, dok je PA testiranjem utvrđena visoka UVA zaštita (P++++). Ova zaštita pomaže u sprečavanju fotostarenja, hiperpigmentacija i oštećenja kože izazvanih UV zračenjem. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Matte Sun Stick: Mugwort + Camellia je praktičan stik za zaštitu od sunca sa SPF 50+ PA++++, koji pruža visoku zaštitu od UVA i UVB zraka. Obogaćen ekstraktima artemisije (mugwort) i kamelije, ovaj proizvod kontroliše lučenje sebuma, ostavljajući kožu matiranom i hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Beauty-of-Joseon-Matte-Sun-Stick-MugwortCamelia.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
