INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1121, 6, 'Abib Glutathiosome Dark Spot Serum Vita Drop', 'abib-glutathiosome-dark-spot-serum-vita-drop', 'Ključne prednosti: Smanjuje tamne fleke: Aktivni sastojci inhibiraju sintezu melanina, čime se smanjuje vidljivost tamnih fleka i hiperpigmentacija. Ujednačava ten: Kombinacija niacinamida i vitamina C posvetljuje kožu, dajući joj zdrav i blistav izgled. Poboljšava elastičnost kože: Serum hidrira i revitalizuje kožu, čineći je čvršćom i glatkom. Kome je namenjen? Ovaj serum je idealan za osobe sa svim tipovima kože koje se suočavaju sa problemima tamnih fleka, hiperpigmentacije ili neujednačenog tena. Takođe je pogodan za one koji žele da poboljšaju elastičnost i hidrataciju kože. Zašto volimo Abib Glutathiosome Dark Spot Serum Vita Drop? Glutathiosome Dark Spot Serum Vita Drop koristi naprednu tehnologiju glutationsoma (egzozomi+glutation) , koja omogućava duboku apsorpciju glutationa u kožu, efikasno inhibirajući sintezu melanina i smanjujući tamne fleke. Niacinamid (5%) i vitamin C (5%) sinergijski deluju na posvetljivanje kože, ujednačavajući ten i vraćajući joj prirodni sjaj. Serum takođe sadrži hidratantne komponente koje poboljšavaju elastičnost kože. Redovnom upotrebom, korisnici mogu primetiti smanjenje hiperpigmentacija i poboljšanje ukupnog izgleda kože. Aktivni sastojci Glutationsom Ova jedinstvena kombinacija glutationa i egzozoma omogućava duboku penetraciju u kožu, gde glutation deluje kao snažan antioksidans, inhibirajući sintezu melanina i smanjujući tamne fleke. Pored toga, štiti kožu od oksidativnog stresa i poboljšava njen ukupni tonus. Niacinamid (5%) Poznat i kao vitamin B3, niacinamid je multifunkcionalni sastojak koji posvetljuje kožu, smanjuje vidljivost tamnih fleka i poboljšava barijernu funkciju kože. Takođe pomaže u regulaciji proizvodnje sebuma i ima antiinflamatorna svojstva, što ga čini pogodnim za sve tipove kože. Vitamin C (5%) Kao snažan antioksidans, vitamin C posvetljuje kožu, stimuliše sintezu kolagena i štiti od oštećenja izazvanih UV zračenjem. U ovom serumu koristi se stabilan oblik vitamina C, koji pruža dugotrajne benefite bez iritacije. Madecassoside Ekstrakt iz biljke Centella Asiatica, madecassoside ima umirujuća i antiinflamatorna svojstva, pomažući u smanjenju crvenila i iritacija. Takođe doprinosi regeneraciji kože i poboljšava njenu elastičnost. Beta-glukan Prirodni polisaharid koji hidrira kožu, poboljšava njenu elastičnost i jača barijernu funkciju. Takođe ima umirujuća svojstva, smanjujući iritacije i crvenilo. Dodaj u listu želja Dodaj u listu želja', 'Abib Glutathiosome Dark Spot Serum Vita Drop je serum formulisan sa glutationsomom, niacinamidom i vitaminom C, namenjen za smanjenje tamnih fleka i ujednačavanje tena. Ovaj proizvod efikasno rešava probleme hiperpigmentacije i neujednačenog tena.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Abib-Glutathiosome-Dark-Spot-Serum-Vita-Drop.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
