INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1123, 174, 'VT Cosmetics Glucamune Cream', 'vt-cosmetics-glucamune-cream', 'Ključne prednosti: Intenzivna hidratacija: Glucamune kompleks pruža 111% više vlage u poređenju sa hijaluronskom kiselinom, obezbeđujući trenutnu i dugotrajnu hidrataciju. Umirujuće dejstvo: Sastojci poput pantenola i alantoina smiruju iritiranu kožu, smanjujući crvenilo i nelagodnost. Jačanje barijere kože: Skvalan i pantenol pomažu u jačanju zaštitne barijere kože, sprečavajući gubitak vlage i štiteći je od spoljašnjih agresora. Kome je namenjena? Ova krema je idealna za osobe sa osetljivom, suvom ili dehidriranom kožom, kao i za one koji se suočavaju sa iritacijama ili oslabljenom barijerom kože. Takođe je pogodna za kožu sklonu crvenilu i nelagodnosti usled spoljašnjih faktora. Zašto volimo VT Cosmetics Glucamune Cream? Nakon redovne upotrebe Glucamune kreme, koža postaje vidljivo hidrirana i elastična. Umirujući efekti pantenola i alantoina doprinose smanjenju crvenila, dok skvalan obnavlja lipidni sloj kože, čineći je otpornijom na spoljašnje uticaje. Lagana tekstura kreme omogućava brzo upijanje bez osećaja težine ili masnoće, ostavljajući kožu mekom i glatkom. Bez dodatka mirisa, ova formula je prilagođena i najosetljivijoj koži, pružajući joj potrebnu negu i zaštitu tokom celog dana. Aktivni sastojci Pantenol (Provitamin B5) Umiruje i hidrira kožu, istovremeno jačajući njenu zaštitnu barijeru. Pomaže u regeneraciji suve i oštećene kože, smanjuje crvenilo i iritacije. Idealan za osetljivu i dehidriranu kožu. Skvalan Lagan, nemasan emolijent koji pruža dugotrajnu hidrataciju i poboljšava elastičnost kože. Štiti kožu od isušivanja i jača njenu otpornost na spoljašnje faktore. Prikladan za sve tipove kože, uključujući osetljivu. Alantoin Deluje umirujuće i regenerativno, ubrzava obnavljanje kože i omekšava njenu površinu. Smanjuje iritacije i pomaže koži da zadrži vlagu. Posebno efikasan za grubu, suvu ili reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Glucamune Cream je hidratantna krema namenjena intenzivnoj hidrataciji i umirivanju kože, posebno formulisana za osetljivu i dehidriranu kožu. Obogaćena je sastojcima poput Glucamune kompleksa, pantenola, skvalana i alantoina, koji zajedno pružaju dubinsku hidrataciju, jačaju barijeru kože i smanjuju iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/12/VT-Cosmetics-Glucamune-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
