INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1134, 165, 'Tocobo Cica Calming Sun Serum', 'tocobo-cica-calming-sun-serum', 'Ključne prednosti: Visoka zaštita od UV zračenja: Štiti kožu od štetnih UV zraka zahvaljujući SPF50+ PA++++ formuli. Umirujuće dejstvo: Ekstrakti centelle asiatice i aloe vere smiruju iritacije i upale na koži. Dubinska hidratacija: Sadrži kompleks od deset vrsta hijaluronske kiseline koje intenzivno hidriraju kožu. Kome je namenjen? Ovaj serum je pogodan za sve tipove kože, uključujući osetljivu i sklonu aknama, pružajući zaštitu i umirenje bez zapušavanja pora. Zašto volimo TOCOBO Cica Calming Sun Serum? Korišćenjem Cica Calming Sun Seruma, koža postaje zaštićena od štetnih UV zraka, čime se sprečava prevremeno starenje i oštećenje. Aktivni sastojci poput centelle asiatice i aloe vere pružaju umirujuće dejstvo, smanjujući crvenilo i iritacije. Kompleks hijaluronske kiseline obezbeđuje dubinsku hidrataciju, ostavljajući kožu mekom i elastičnom tokom celog dana. Lagani, nemasni sastav omogućava brzo upijanje, bez ostavljanja belih tragova ili osećaja težine na koži. Redovnom upotrebom, koža postaje otpornija na spoljašnje stresore, dok se održava optimalan nivo vlažnosti i zdrav izgled. Aktivni sastojci CICA kompleks (Centella Asiatica Leaf & Root Extract) Umiruje kožu, smanjuje crvenilo i upale, te jača prirodnu barijeru kože. Posebno je efikasan za osetljivu i reaktivnu kožu izloženu UV zračenju. Deluje regenerativno i štiti kožu od iritacija. HA kompleks (Hijaluronska kiselina) Višeslojna hijaluronska kiselina obezbeđuje intenzivnu hidrataciju, popunjava kožu vlagom i poboljšava elastičnost. Sprečava isušivanje izazvano UV zracima i ostavlja kožu punom i osveženom. Aloe Ferox Leaf Extract Prirodni sastojak sa snažnim umirujućim i hidratantnim svojstvima. Smanjuje upale, poboljšava hidrataciju i pomaže u očuvanju vlage u koži. Carthamus Tinctorius (Safflower) Flower Extract Bogat antioksidansima i linolnom kiselinom, deluje protivupalno i štiti kožu od oksidativnog stresa. Pomaže u umirivanju iritacija i poboljšava opšti izgled kože. Hemijski UV filteri (SPF50+ PA++++) Obezbeđuju visok nivo zaštite od UVA i UVB zračenja bez belih tragova. Lako se upijaju i ne zapušavaju pore, idealni za svakodnevnu upotrebu ispod šminke. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Sun Serum je lagani serum za zaštitu od sunca sa SPF50+ PA++++, obogaćen ekstraktima centelle asiatice i aloe vere, koji pruža umirujuće dejstvo i hidrataciju koži.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Sun-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
