INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1135, 165, 'Tocobo Cica Calming Aqua Pad', 'tocobo-cica-calming-aqua-pad', 'Ključne prednosti: Brzo umirivanje kože: Fermentisani Cica kompleks smiruje iritacije i crvenilo, pružajući trenutno olakšanje osetljivoj koži. Dubinska hidratacija: Višestruki oblici hijaluronske kiseline prodiru duboko u kožu, pružajući dugotrajnu vlažnost i poboljšavajući zadržavanje vlage. Hlađenje i osveženje: Jastučići pružaju trenutni efekat hlađenja, osvežavajući umornu kožu i smanjujući crvenilo. Kome su namenjeni? Ovi jastučići su idealni za osobe sa osetljivom, iritiranom ili suvom kožom, kojima je potrebno brzo umirivanje i intenzivna hidratacija. Takođe su pogodni za one koji žele brzo osveženje i smanjenje crvenila, posebno nakon izlaganja spoljašnjim stresorima. Zašto volimo TOCOBO Cica Calming Aqua Pad? Kada vaša koža zahteva trenutnu negu i umirenje, Cica Calming Aqua Pad jastučići pružaju trenutno rešenje. Svaki jastučić, natopljen umirujućim esencijama, hladi i smanjuje temperaturu kože, pružajući osećaj svežine. Redovnom upotrebom, koža postaje vidljivo smirenija, sa manje crvenila i iritacija. Dubinska hidratacija koju pruža hijaluronska kiselina čini kožu elastičnijom i zdravijom, dok fermentisani ekstrakti jačaju njenu prirodnu barijeru. Jastučići ne samo da umiruju, već i revitalizuju kožu, ostavljajući je osveženom i blistavom tokom celog dana. Aktivni sastojci Fermentisani Cica kompleks Sadrži bogate derivate biljke Centella Asiatica, koji pomažu u smirivanju upala, regeneraciji kože i jačanju njene prirodne zaštite. Ovaj kompleks takođe smanjuje crvenilo i pruža intenzivnu hidrataciju. Hijaluronska kiselina Ova moćna supstanca prodire u dublje slojeve kože, pružajući višeslojnu hidrataciju i zadržavanje vlage, čime koža postaje glatkija i elastičnija. Ekstrakt lista čajevca Deluje antibakterijski i antiinflamatorno, smanjuje pojavu akni i iritacija, dok osvežava i balansira ten. Ekstrakt aloe ferox Hidratantni i umirujući sastojak koji pomaže u smirivanju iritacija, dok osigurava dubinsku negu i svežinu kože. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Aqua Pad su hipoalergeni jastučići namenjeni umirivanju i hidrataciji osetljive kože. Obogaćeni fermentisanim kompleksom centele (Cica) i hijaluronskom kiselinom, ovi jastučići pružaju trenutni osećaj hlađenja, smanjujući temperaturu kože i pomažući u smirivanju iritacija.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Aqua-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
