INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1137, 165, 'Tocobo Bio Watery Sun Cream', 'tocobo-bio-watery-sun-cream', 'Ključne prednosti: Visoka UV zaštita: SPF50+ PA++++ pruža pouzdanu zaštitu od štetnih sunčevih zraka, sprečavajući oštećenja kože i prevremeno starenje. Dubinska hidratacija: Sastojci poput hijaluronske kiseline obezbeđuju intenzivnu hidrataciju, održavajući kožu mekom i elastičnom. Bez belih tragova: Lagana tekstura se brzo upija, ne ostavljajući bele tragove niti osećaj težine na koži. Kome je namenjena? Ova krema je idealna za sve tipove kože, uključujući masnu i kombinovanu, kao i za one sa osetljivom kožom sklonom iritacijama. Posebno je pogodna za osobe koje traže visoku UV zaštitu bez masnog osećaja ili belih tragova. Zašto volimo TOCOBO Bio Watery Sun Cream? Bio Watery Sun Cream pruža visoku zaštitu od štetnih UV zraka, čuvajući vašu kožu od oštećenja i prevremenog starenja. Njena lagana, vodena tekstura omogućava brzo upijanje. Bez belih tragova i masnog osećaja, ova krema je savršen izbor za svakodnevnu upotrebu. Obogaćena niacinamidom, pomaže u ujednačavanju tena i smanjenju tamnih fleka. Hijaluronska kiselina pruža dubinsku hidrataciju, održavajući kožu mekom i elastičnom. Sa Bio Watery Sun Cream, vaša koža je zaštićena, hidrirana i blistava svakog dana. Aktivni sastojci Hemijski UV filteri (SPF 50+ PA++++) Pružaju visoku zaštitu od UVA i UVB zračenja bez ostavljanja belih tragova. Idealni su za svakodnevnu upotrebu, lako se upijaju i ne narušavaju izgled šminke. Štite kožu od fotostarenja, oštećenja i hiperpigmentacija. Ekstrakt mung pasulja (Vigna Radiata Extract – 1,000 ppm) Bogat antioksidansima i antiinflamatornim jedinjenjima. Umiruje nadraženu kožu, pomaže u kontroli nepravilnosti i osvežava ten. Posebno koristan za problematičnu i reaktivnu kožu. Bio-hijaluronska kiselina (1,000 ppm) Napredni oblik hijaluronske kiseline koji pruža dubinsku hidrataciju i poboljšava elastičnost kože. Sprečava isušivanje uz zadržavanje vlage tokom celog dana. Ostavlja kožu mekom, glatkom i punom. Niacinamid Doprinosi ujednačenju tena, smanjenju pigmentacija i poboljšanju teksture kože. Takođe jača kožnu barijeru i balansira proizvodnju sebuma. Pantenol (Provitamin B5) Umiruje kožu, ublažava crvenilo i iritacije, te podržava obnavljanje oštećene barijere. Idealan za svakodnevnu zaštitu osetljive kože. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Bio Watery Sun Cream SPF50+ PA++++ je lagana, hidratantna krema za sunčanje koja pruža visoku zaštitu od UVA i UVB zraka, zahvaljujući naprednim hemijskim filterima. Obogaćena je sastojcima poput niacinamida i hijaluronske kiseline, koji posvetljuju i intenzivno hidriraju kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Bio-Watery-Sun-Cream-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
