INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1138, 165, 'Tocobo Cica Calming Gel Cream', 'tocobo-cica-calming-gel-cream', 'Ključne prednosti: Brzo umirivanje kože: Fermentisani Cica kompleks pruža intenzivno i brzo umirujuće dejstvo na iritiranu kožu. Dubinska hidratacija: Multi-hijaluronski kompleks sa pantenolom i beta-glukanom omogućava dubinsku hidrataciju i poboljšava zadržavanje vlage u koži. Jačanje barijere kože: Sastojci poput ceramida NP pomažu u jačanju zaštitne barijere kože, čineći je otpornijom na spoljašnje uticaje. Kome je namenjena? Ova gel-krema je idealna za osobe sa osetljivom, iritiranom ili suvom kožom koja zahteva brzo umirivanje i intenzivnu hidrataciju. Takođe je pogodna za kožu sklonu crvenilu i upalama, pružajući olakšanje i poboljšavajući ukupno stanje kože. Zašto volimo TOCOBO Cica Calming Gel Cream? Nakon napornog dana, vaša koža zaslužuje trenutak nege i obnove. Cica Calming Gel Cream pruža upravo to – trenutnu svežinu i umirenje za umornu kožu. Njena lagana tekstura se brzo upija, ostavljajući osećaj hlađenja i olakšanja. Redovnom upotrebom, koža postaje vidno hidrirana, mekša i elastičnija. Smanjuje se pojava crvenila i iritacija, dok se prirodna barijera kože jača, pružajući zaštitu od svakodnevnih stresora. Ova gel-krema ne samo da hidrira, već i revitalizuje kožu, vraćajući joj zdrav i blistav izgled. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Gel Cream je lagana, hipoalergena gel-krema namenjena umirivanju i dubinskoj hidrataciji osetljive i iritirane kože. Obogaćena fermentisanim kompleksom centele (Cica) i multi-hijaluronskom kiselinom, pruža intenzivno umirujuće dejstvo i poboljšava zadržavanje vlage u koži.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Gel-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
