INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1139, 165, 'Tocobo Cica Cooling Sun Stick', 'tocobo-cica-cooling-sun-stick', 'Ključne prednosti: Visoka UV zaštita: Efikasno štiti kožu od štetnih UVA i UVB zraka zahvaljujući SPF50+ PA++++ formuli. Umirujući efekat: Smanjuje crvenilo i iritacije zahvaljujući ekstraktu centele asiatice, poznatom po svojim antiinflamatornim svojstvima. Hidratacija i hlađenje: Obezbeđuje hidrataciju i prijatan osećaj hlađenja, idealno za vrele letnje dane. Kome je namenjen? Ovaj proizvod je pogodan za sve tipove kože, uključujući osetljivu i sklonu iritacijama. Posebno je koristan za osobe koje traže visoku UV zaštitu uz umirujuće i hidratantne benefite. Zašto volimo TOCOBO Cica Cooling Sun Stick? U vrelim letnjim danima, važno je imati pouzdanu zaštitu koja ne samo da štiti od sunca, već i pruža osećaj svežine. Cica Cooling Sun Stick kombinuje visoku UV zaštitu sa umirujućim svojstvima centele asiatice, smanjujući crvenilo i iritacije nakon izlaganja suncu. Njegova lagana, nemasna formula omogućava lako nanošenje bez belih tragova, ostavljajući kožu hidriranom i osveženom. Praktičan oblik stika čini ga idealnim za ponovnu aplikaciju tokom dana, čak i preko šminke. Redovnom upotrebom, koža ostaje zaštićena, umirena i zdrava, bez osećaja težine ili zapušenih pora. Aktivni sastojci CICA kompleks (Centella Asiatica Leaf & Root Extract) Biljni kompleks poznat po umirujućem, protivupalnom i regenerativnom delovanju. Pomaže u smanjenju crvenila i iritacija, jača kožnu barijeru i deluje protiv opuštanja kože. Idealan za osetljivu i reaktivnu kožu izloženu UV zračenju. HA kompleks (Hijaluronska kiselina) Sastoji se od više oblika hijaluronske kiseline koji intenzivno hidrira različite slojeve kože. Obezbeđuje dugotrajnu hidrataciju, poboljšava elastičnost i sprečava isušivanje izazvano suncem. Aloe Ferox Leaf Extract Bogat antioksidansima i polisaharidima, ovaj ekstrakt smanjuje upale i ubrzava regeneraciju kože. Maksimizira hidrataciju i pomaže u zaključavanju vlage unutar kože. Hemijski UV filteri (SPF50+ PA++++) Širokospektralna zaštita od UVA i UVB zračenja bez bele tragove. Nezačepljujuća formula pogodna za sve tipove kože, uključujući masnu i osetljivu. Nevena (Calendula Officinalis Extract – moguće prisustvo u CICA mešavini) Umiruje, regeneriše i dodatno štiti kožu izloženu suncu. Deluje kao prirodan antiinflamatorni agens i ublažava nelagodnosti. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Cooling Sun Stick je hemijski zaštitni stik za sunce sa SPF50+ PA++++, obogaćen kompleksom fermentisane centele i hijaluronske kiseline, pružajući visoku zaštitu od UV zračenja uz umirujući efekat na kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Cooling-Sun-Stick.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
