INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1140, 165, 'Tocobo Cica Calming Aqua Toner', 'tocobo-cica-calming-aqua-toner', 'Ključne prednosti: Umiruje iritacije: Smanjuje crvenilo i nelagodnost zahvaljujući umirujućim sastojcima. Poboljšava hidrataciju: Pruža dubinsku hidrataciju, ostavljajući kožu osveženom i mekom. Održava balans kože: Pomaže u održavanju optimalnog nivoa vlažnosti i zdravog izgleda kože. Kome je namenjen? Ovaj tonik je idealan za osobe sa osetljivom ili iritiranom kožom, kao i za one koji traže proizvod koji pruža umirujuće i hidratantne efekte. Zašto volimo TOCOBO Cica Calming Aqua Toner? Nakon dugog dana, vaša koža zaslužuje nežnu negu koja će je osvežiti i umiriti. Cica Calming Aqua Toner pruža trenutnu hidrataciju, smanjujući osećaj zategnutosti i nelagodnosti. Redovnom upotrebom, koža postaje otpornija na spoljašnje stresore, dok se crvenilo i iritacije vidno smanjuju. Lagana tekstura tonika omogućava brzo upijanje, ostavljajući kožu glatkom i pripremljenom za naredne korake u rutini nege. Ovaj tonik ne samo da hidrira, već i pomaže u obnavljanju prirodne barijere kože, čineći je zdravijom i blistavijom. Aktivni sastojci Camellia Sinensis Leaf Water (voda zelenog čaja) Prirodni antioksidans bogat polifenolima koji umiruje kožu i smanjuje upale. Štiti od slobodnih radikala i pomaže u očuvanju zdravlja kože. Deluje osvežavajuće i balansira proizvodnju sebuma. Sodium Hyaluronate Oblik hijaluronske kiseline sa manjom molekularnom masom koji prodire dublje u kožu. Intenzivno hidrira, zadržava vlagu i poboljšava elastičnost. Ostavlja kožu glatkom, punom i osveženom. Mentha Aquatica Leaf Extract (ekstrakt vodenog nane) Pruža efekat hlađenja, tonira i zateže kožu. Doprinosi osvežavanju tena i smanjenju umora na koži. Daje trenutni osećaj smirenosti i revitalizacije. Aloe Ferox Leaf Extract Biljni ekstrakt bogat vitaminima i antiinflamatornim jedinjenjima. Umiruje iritacije, crvenilo i suvoću, dok istovremeno pomaže u obnavljanju kože. Idealan za osetljivu ili reaktivnu kožu. Niacinamid Ujednačava ton kože, smanjuje hiperpigmentacije i vidljivost pora. Jača barijeru kože, pomaže u hidrataciji i posvetljuje kožu. Doprinosi glatkom i blistavom izgledu tena. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Aqua Toner je veganski tonik osmišljen da umiri i hidrira osetljivu kožu, koristeći sastojke poput ekstrakta lista kamelije i natrijum hijaluronata za zadržavanje vlage i smanjenje upala.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Aqua-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
