INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1141, 165, 'Tocobo Cica Calming Serum', 'tocobo-cica-calming-serum', 'Ključne prednosti: Brzo umirivanje kože: Fermentisani cica kompleks efikasno smanjuje iritacije i crvenilo, pružajući olakšanje osetljivoj koži. Dubinska hidratacija: Multi-hijaluronska kiselina obezbeđuje 24-časovnu hidrataciju, ostavljajući kožu mekom i osveženom. Jačanje barijere kože: Ekstrakt čajevca pomaže u jačanju prirodne zaštitne barijere kože, štiteći je od spoljašnjih agresora. Kome je namenjena? Ovaj serum je idealan za osobe sa osetljivom, iritiranom ili suvom kožom, kao i za one koji se suočavaju sa problemima poput crvenila i upala. Zašto volimo TOCOBO Cica Calming Serum? Korišćenjem Cica Calming Seruma, vaša koža postaje otpornija i manje sklona iritacijama. Vremenom, primetićete smanjenje crvenila i poboljšanje ukupnog tonusa kože. Dubinska hidratacija koju pruža serum čini kožu elastičnijom i zdravijom. Pored toga, jača se prirodna barijera kože, što je čini otpornijom na spoljašnje faktore poput zagađenja i stresa. Redovnom upotrebom, koža postaje vidljivo smirenija i blistavija. Serum se brzo upija, ostavljajući prijatan osećaj bez lepljivosti. Aktivni sastojci Melaleuca Alternifolia (Tea Tree) Extract Poznat po snažnim antibakterijskim i protivupalnim svojstvima, čajevac efikasno umiruje iritacije i crvenilo. Pomaže u regulaciji sebuma i ublažava promene na koži, naročito kod problematičnih i osetljivih tipova. Bifida Ferment Lysate Fermentisani probiotski sastojak koji jača kožnu barijeru, štiti od spoljašnjih agresora i smanjuje osetljivost kože. Doprinosi ravnoteži mikrobioma i poboljšava otpornost kože. Lactococcus Ferment Lysate Podstiče regeneraciju ćelija i obnavljanje kože. Deluje umirujuće, jača kožu i povećava njenu sposobnost da se brani od štetnih uticaja iz spoljašnje sredine. Ceramide NP Ključni lipid koji obnavlja zaštitnu barijeru kože i sprečava transepidermalni gubitak vode. Hidrirana i zaštićena koža postaje elastičnija, otpornija i manje sklona iritacijama. Sodium Hyaluronate Oblik hijaluronske kiseline sa odličnom sposobnošću zadržavanja vlage. Dubinski hidrira, popunjava fine linije i poboljšava elastičnost kože, čineći je punijom i osveženom. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Serum je lagani, vodeni serum formulisan sa fermentisanim cica kompleksom, multi-hijaluronskom kiselinom i ekstraktom čajevca, koji brzo umiruje iritiranu kožu i pruža dubinsku hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
