INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1142, 165, 'Tocobo Multi Ceramide cream', 'tocobo-multi-ceramide-cream', 'Ključne prednosti: Dubinska hidratacija: Tri vrste hijaluronske kiseline prodiru u različite slojeve kože, obezbeđujući optimalnu vlažnost i elastičnost. Jačanje barijere kože: Pet tipova ceramida pomažu u obnovi i zaštiti prirodne barijere kože, sprečavajući gubitak vlage. Umirujući efekat: Shea maslac i ekstrakt hlorele smiruju iritacije i crvenilo, pružajući osećaj udobnosti i svežine. Kome je namenjena? Ova krema je idealna za osobe sa suvom, osetljivom ili dehidriranom kožom. Posebno za one koji žele da ojačaju barijeru kože i poboljšaju njenu elastičnost. Zašto volimo TOCOBO Multi Ceramide cream? U svetu gde je koža svakodnevno izložena stresu i zagađenju, Multi Ceramide krema postaje vaš verni saveznik. Njena bogata, ali lagana tekstura topi se na koži, pružajući trenutnu hidrataciju i osećaj umirenosti. Svakim nanošenjem, ceramidi i hijaluronska kiselina rade zajedno na jačanju barijere kože, čineći je otpornijom i elastičnijom. Vremenom, primetićete kako vaša koža postaje mekša, glatkija i blistavija, dok se znaci suvoće i iritacije povlače. Ova krema ne samo da hidrira, već i revitalizuje kožu, vraćajući joj prirodni sjaj i zdrav izgled. Aktivni sastojci Multi-ceramide kompleks (5 vrsta ceramida) Obnavlja i jača zaštitnu barijeru kože, sprečava gubitak vlage i štiti od spoljašnjih iritansa. Ceramidi su ključni za očuvanje zdravlja kože, naročito kod suve, osetljive i oslabljene kože. Doprinosi mekoj, elastičnoj i otpornijoj koži. Hijaluronska kiselina (3 vrste) Kombinacija različitih molekulskih težina omogućava hidrataciju na više nivoa kože. Vezuje i zadržava vlagu, popunjava sitne linije i poboljšava elastičnost kože. Ostavlja kožu punom, glatkom i osveženom. Skvalan Prirodni emolijent koji omekšava i hidrira bez osećaja težine. Pomaže u zaštiti kože od isušivanja i ima antioksidativna svojstva. Kompatibilan sa svim tipovima kože, uključujući osetljivu. Pantenol (Provitamin B5) Umiruje iritacije i crvenilo, poboljšava zadržavanje vlage i doprinosi regeneraciji kože. Idealan za svakodnevnu upotrebu kod osetljive ili dehidrirane kože. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Multi Ceramide Cream je bogata, hranljiva krema koja kombinuje 5 tipova ceramida i 3 vrste hijaluronske kiseline za intenzivnu hidrataciju i jačanje barijere kože. Ova veganska i hipoalergena krema pruža dubinsku negu, čineći kožu mekom i otpornom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Multi-Ceramide-cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
