INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1144, 165, 'Tocobo Cica Calming Powder Wash', 'tocobo-cica-calming-powder-wash', 'Ključne prednosti: Nežno eksfolira kožu: Papain enzim uklanja mrtve ćelije kože, ostavljajući je glatkom i osveženom. Dubinsko čisti pore: Ekstrakt lista čajevca pomaže u otčepljivanju pora, smanjujući pojavu akni i nesavršenosti. Umiruje iritacije: Ekstrakt Centella Asiatica smiruje upale i crvenilo, pružajući olakšanje osetljivoj koži. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom i aknama sklonom kožom, koje traže blago, ali efikasno sredstvo za čišćenje koje umiruje iritacije i poboljšava teksturu kože. Zašto volimo TOCOBO Cica Calming Powder Wash? Cica Calming Powder Wash pruža nežno, ali temeljno čišćenje, uklanjajući nečistoće i višak sebuma bez isušivanja. Redovnom upotrebom, koža postaje vidljivo čistija i smirenija, dok se crvenilo i upale smanjuju. Njegova jedinstvena formula u prahu, koja se pretvara u bogatu penu, pruža luksuzno iskustvo čišćenja, ostavljajući kožu mekom i osveženom. Vremenom, ten postaje ujednačeniji, a koža otpornija na spoljašnje agresore. Aktivni sastojci Papain Enzim iz papaje koji nežno eksfolira kožu razgrađujući mrtve ćelije i nečistoće sa površine kože. Otpušava pore bez oštećenja zaštitne barijere, ostavljajući kožu glatkom i čistom. Pogodan za svakodnevnu upotrebu kod osetljive i problematične kože. Melaleuca Alternifolia (Tea Tree) Leaf Extract Prirodni antibakterijski sastojak koji smanjuje upale i iritacije. Efikasno pomaže kod akni i crvenila, istovremeno balansirajući proizvodnju sebuma i osvežavajući kožu. Centella Asiatica Extract Poznata po svojim umirujućim, antiinflamatornim i regenerativnim svojstvima. Ubrzava zarastanje, jača kožnu barijeru i pomaže kod nadražene i osetljive kože. Takođe doprinosi hidrataciji i zdravijem izgledu kože. Camellia Sinensis (zeleni čaj) Leaf Powder Bogata antioksidansima, ova biljka štiti kožu od slobodnih radikala i pomaže u umirivanju upalnih procesa. Dodatno osvežava, hidrira i smanjuje reaktivnost kože. Maltodekstrin Prirodni sastojak koji pomaže u očuvanju vlage u koži. Stabilizuje formulu i doprinosi glatkoj teksturi proizvoda prilikom primene. Omogućava koži da ostane mekana i elastična nakon čišćenja. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Cica Calming Powder Wash je blago kiseli puder za čišćenje lica, formulisan sa papainom i ekstraktom lista čajevca, koji zajedno deluju na nežno eksfoliranje kože i dubinsko otčepljivanje pora bez uklanjanja esencijalne vlage.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Cica-Calming-Powder-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
