INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1145, 165, 'Tocobo Calamine pore Control Cleansing Oil', 'tocobo-calamine-pore-control-cleansing-oil', 'Ključne prednosti: Efikasno čišćenje pora: Kombinacija kalamin praha i mlečnog ulja pomaže u uklanjanju sebuma i mitesera. Hidratacija i umirenje: Sadrži vegansko belo mleko i ekstrakt Saponaria Officinalis, koji pružaju hidrataciju i umiruju kožu. Niska iritacija: Formulisan za osetljivu kožu, omogućava nežno i glatko čišćenje sa minimalnom iritacijom. Kome je namenjen? Ovaj proizvod je idealan za osobe sa masnom i kombinovanom kožom sklonom aknama i proširenim porama. Posebno za one sa osetljivom kožom koja zahteva nežno, ali efikasno čišćenje. Zašto volimo TOCOBO Calamine Pore Control Cleansing Oil? Svaki dan, vaša koža se suočava sa zagađenjem i stresom, što dovodi do začepljenih pora i nečistoća. Calamine Pore Control Cleansing Oil pruža rešenje koje ne samo da uklanja šminku, već i dubinski čisti pore. Time smanjuje pojavu mitesera i akni. Njegova jedinstvena formula sa kalaminom umiruje iritacije. Vegansko belo mleko i ekstrakt Saponaria Officinalis obezbeđuju hidrataciju. Redovnom upotrebom, koža postaje balansirana, sa smanjenim viškom sebuma i zdravijim izgledom. Ovo ulje za čišćenje pruža osećaj svežine i čistoće, bez osećaja zatezanja ili suvoće. Aktivni sastojci Calamine (5,000 ppm) Mineralni sastojak poznat po svom umirujućem i seboregulacionom dejstvu. Pomaže u smanjenju crvenila, iritacija i upala, dok istovremeno matira i pročišćava pore. Idealan za masnu i problematičnu kožu. Vegan White Milk (100 ppm) Biljna alternativa mlečnim proteinima koja omekšava kožu i pomaže u održavanju hidratacije. Doprinosi osvetljavanju tena i vraća koži prirodnu svežinu bez izazivanja iritacija. Maslinovo ulje (10,000 ppm) Prirodno bogato antioksidansima i vitaminima E i K, maslinovo ulje efikasno uklanja nečistoće i šminku, dok istovremeno neguje i hidrira kožu. Ostavlja kožu mekom, elastičnom i nahranjenom. Kokosovo ulje (1,000 ppm) Deluje kao emolijent i hidratant, pomaže u zadržavanju vlage i zaštiti kože od isušivanja. Ima blaga antibakterijska svojstva, pogodna za čišćenje i umirenje kože. Ekstrakt sapunike (Saponaria Officinalis Extract) Prirodni izvor saponina sa blagim penjenjem i hidratantnim efektom. Pomaže u nežnom čišćenju kože bez isušivanja, uz dodatnu zaštitu i osveženje. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Calamine Pore Control Cleansing Oil je ulje za čišćenje lica koje kombinuje 5.000 ppm kalamin praha i 100 ppm veganskog belog mleka, efikasno uklanjajući nečistoće, višak sebuma i ostatke šminke, dok istovremeno neguje i hidrira kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Calamine-pore-Control-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
