INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1146, 165, 'Tocobo Coconut Clay Cleansing Foam', 'tocobo-coconut-clay-cleansing-foam', 'Ključne prednosti: Dubinsko čišćenje pora: Mikro mehurići manji od prosečne veličine pora prodiru duboko, uklanjajući nečistoće i višak sebuma. Kontrola sebuma i umirujući efekat: Ružičasta i mineralna glina apsorbuju višak ulja i umiruju kožu, poboljšavajući njen izgled i teksturu. Hidratacija i nega: Ekstrakt lista Saponaria officinalis (100 ppm) pruža hidrataciju, sprečavajući isušivanje kože nakon čišćenja. Kome je namenjen? Ovaj čistač je pogodan za sve tipove kože, uključujući i osetljivu. Posebno je koristan za osobe sa masnom ili kombinovanom kožom sklonom prekomernom lučenju sebuma i začepljenim porama. Zašto volimo TOCOBO Coconut Clay Cleansing Foam? Coconut Clay Cleansing Foam pruža dubinsko čišćenje zahvaljujući mikro mehurićima koji prodiru u pore, uklanjajući nečistoće i ostavljajući kožu osveženom. Ružičasta i mineralna glina rade zajedno na apsorpciji viška ulja, dok istovremeno umiruju kožu. Nakon svakog pranja, koža ostaje hidrirana zahvaljujući ekstraktu Saponaria officinalis, koji sprečava osećaj zatezanja i suvoće. Redovnom upotrebom, tekstura kože se poboljšava, pore postaju manje vidljive, a ten blistaviji. Ovaj čistač ne samo da uklanja nečistoće, već i balansira proizvodnju sebuma, pružajući dugotrajnu svežinu i čistoću. Aktivni sastojci Kokosov ekstrakt (Cocos Nucifera Extract) Prirodni umirujući sastojak koji hidrira i omekšava kožu dok čisti. Pomaže u sprečavanju iritacija i štiti kožu od isušivanja tokom čišćenja. Posebno pogodan za osetljivu i reaktivnu kožu. Ružičasta i bela mineralna glina (Pink & White Clay) Deluju kao prirodni eksfolijanti koji uklanjaju mrtve ćelije i dubinski pročišćavaju pore. Apsorbuju višak sebuma i detoksikuju kožu bez isušivanja. Doprinose osveženom, matiranom i glatkom tenu. Kaolin Blaga glina koja nežno čisti i umiruje kožu, pomažući u uklanjanju viška ulja i nečistoća. Poboljšava teksturu kože bez narušavanja njene prirodne barijere. Glicerin Efikasan ovlaživač koji zadržava vlagu u koži, pružajući osećaj mekoće i elastičnosti čak i nakon umivanja. Sprečava zatezanje i suvoću. Alantoin Umirujući sastojak koji pomaže u regeneraciji i zaštiti kože. Smanjuje crvenilo i iritacije, ostavljajući kožu smirenom i negovanom. Dodaj u listu želja Dodaj u listu želja', 'TOCOBO Coconut Clay Cleansing Foam je proizvod namenjen dubinskom čišćenju kože lica. Formulisan sa 27% surfaktanata poreklom iz kokosa i palme, kao i 10.000 ppm ružičaste i mineralne gline, ovaj čistač efikasno uklanja nečistoće i višak sebuma iz pora, ostavljajući kožu čistom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TOCOBO-Coconut-Clay-Cleansing-Foam.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
