INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1147, 164, 'Tirtir Collagen Lifting Eye Cream', 'tirtir-collagen-lifting-eye-cream', 'Ključne prednosti: Povećava elastičnost kože: Biljni kolagen i peptidi doprinose čvrstoći i elastičnosti kože oko očiju. Smanjuje pojavu bora: Redovnom upotrebom, vidljivost finih linija i bora se značajno smanjuje. Osvetljava tamne podočnjake: Niacinamid i vitamin C pomažu u smanjenju tamnih kolutova ispod očiju, dajući svež i odmoran izgled. Kome je namenjena? Ova krema je idealna za osobe sa znakovima starenja oko očiju, uključujući fine linije, bore i gubitak elastičnosti. Takođe je pogodna za one koji se bore sa tamnim podočnjacima i žele osvežen izgled. Zašto volimo TIRTIR Collagen Lifting Eye Cream? U svetu nege kože, Collagen Lifting Eye Cream se izdvaja svojom jedinstvenom formulom koja cilja na specifične probleme područja oko očiju. Sa svakim nanošenjem, koža postaje hidrirana i nahranjena, dok aktivni sastojci deluju na poboljšanje njene strukture. Vremenom, elastičnost kože se povećava, čineći je otpornijom na znakove starenja. Fini metalni aplikator pruža osvežavajući efekat hlađenja, smanjujući natečenost i umor. Kontinuiranom upotrebom, područje oko očiju postaje svetlije i ujednačenije, dok se bore i fine linije ublažavaju, vraćajući licu mladalački sjaj. Aktivni sastojci Biljni kolagen kompleks (10,000 ppm) Biljni kolagen pomaže u poboljšanju elastičnosti i čvrstoće kože oko očiju. Doprinosi zaglađivanju finih linija i vraća tonus tankoj i osjetljivoj koži. Obezbeđuje hidrataciju i podržava strukturu kože za mladolikiji izgled. 5 peptida Peptidi stimulišu proizvodnju kolagena i elastina, poboljšavajući tonus i teksturu kože. Deluju ciljano na znakove starenja kao što su bore, opuštenost i gubitak elastičnosti. Učvršćuju i revitalizuju područje oko očiju. Niacinamid Osvežava i posvetljuje kožu, smanjuje tamne podočnjake i ujednačava ten. Takođe jača kožnu barijeru i pomaže u smanjenju pigmentacija. Idealan za osvetljavanje i revitalizaciju osetljive regije oko očiju. Ulje avokada Bogato esencijalnim masnim kiselinama i vitaminima, dubinski hidrira i neguje kožu. Umiruje suvoću, smanjuje osećaj zatezanja i vraća mekoću. Pruža zaštitu i hranljivost bez iritacija. Adenozin Snažan anti-age sastojak koji pomaže u smanjenju bora i finih linija. Stimuliše sintezu kolagena i poboljšava elastičnost. Deluje umirujuće na osetljivu kožu i ostavlja je glatkom i čvršćom. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Collagen Lifting Eye Cream je visokokvalitetna krema za područje oko očiju, obogaćena biljnim kolagenom i peptidima, koja pruža intenzivnu hidrataciju i poboljšava elastičnost kože, smanjujući vidljivost finih linija i bora.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TIRTIR-Collagen-Lifting-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
