INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1148, 164, 'Tirtir Pure Vitamin C24 Serum', 'tirtir-pure-vitamin-c24-serum', 'Ključne prednosti: Posvetljivanje kože: Visoka koncentracija vitamina C pomaže u smanjenju hiperpigmentacija i ujednačavanju tena. Poboljšanje elastičnosti: Triple kolagen kompleks doprinosi čvrstoći i elastičnosti kože. Umirujući efekat: CICA-7 kompleks pruža umirujuće dejstvo, smanjujući iritacije i crvenilo.. Kome je namenjen? Ovaj serum je idealan za osobe sa umornom, beživotnom kožom sklonom hiperpigmentacijama. Takođe i za one koji žele poboljšati elastičnost i postići ujednačen ten. Zašto volimo TIRTIR Pure Vitamin C24 Serum? Pure Vitamin C24 Serum pruža sveobuhvatnu negu koja direktno cilja na znakove umora i hiperpigmentacije. Već nakon nekoliko upotreba, koža postaje osvežena i vidno ujednačenija. Dugoročno, visokokoncentrovani vitamin C posvetljuje tamne mrlje. Snažni umirujući kompleksi smanjuju crvenilo i iritacije. Povećanjem elastičnosti, koža izgleda čvršće i mlađe, a fine linije postaju manje vidljive. Uz ovaj serum, vaša koža postaje hidrirana, revitalizovana i spremna za svaki dan. Aktivni sastojci Vitamin C (Askorbinska kiselina – 24%) Visokokoncentrovani oblik čistog vitamina C koji posvetljuje kožu, smanjuje tamne mrlje i hiperpigmentacije. Deluje kao snažan antioksidans, štiti kožu od slobodnih radikala i podstiče sintezu kolagena. Ujednačava ten i vraća prirodan sjaj beživotnoj koži. Pruža anti-age benefite uz vidljivo osvežen i prozračan ten. Triple Collagen kompleks Kombinacija tri tipa kolagena koji deluju sinergijski kako bi poboljšali elastičnost i tonus kože. Smanjuju pojavu bora i finih linija, zatežu kožu i pružaju joj punoću. Posebno efikasan kod zrele i opuštene kože. CICA-7 kompleks Napredna umirujuća formula sastavljena od sedam derivata biljke Centella Asiatica (uključujući madecassoside, asiaticoside, azijatičnu i madekasičnu kiselinu). Umiruje crvenilo, ublažava iritacije i podržava regeneraciju kože. Pogodna je za osetljivu, nadraženu i reaktivnu kožu. Vitamin E (Tokoferol) Pruža dodatnu antioksidativnu zaštitu i potpomaže stabilnost vitamina C u formuli. Hidratantni efekat dodatno poboljšava glatkoću i otpornost kože. Ekstrakt kore sladića (Glycyrrhiza Glabra Root Extract) Posvetljuje kožu i deluje protivupalno. Pomaže u borbi protiv neujednačenog tena i smanjuje vidljivost pigmentacija. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Pure Vitamin C24 Serum je visokokoncentrovani serum sa 24% čistog vitamina C, namenjen za posvetljivanje tena, poboljšanje elastičnosti i postizanje blistavog izgleda kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/TIRTIR-Pure-Vitamin-C24-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
