INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1156, 156, 'Some By Mi Galactomyces Pure Vitamin C Glow Toner', 'some-by-mi-galactomyces-pure-vitamin-c-glow-toner', 'Ključne prednosti: Posvetljivanje kože: Visok sadržaj galaktomiceta i vitamina C pomaže u smanjenju tamnih mrlja i ujednačavanju tena, dajući koži zdrav sjaj. Hidratacija i elastičnost: Galaktomiceti ferment filtrat pruža dubinsku hidrataciju, poboljšava elastičnost kože i čini je glatkom. Zaštita od oksidativnog stresa: Vitamin C deluje kao snažan antioksidans, štiteći kožu od štetnih uticaja okoline i usporavajući proces starenja. Kome je namenjen? Ovaj tonik je idealan za osobe sa neujednačenim tenom, tamnim mrljama ili kožom koja je izgubila elastičnost i sjaj, kao i za one koji žele preventivnu negu protiv znakova starenja. Zašto volimo SOME BY MI Galactomyces Pure Vitamin C Glow Toner? Korišćenjem Galactomyces Pure Vitamin C Glow Tonera, vaša koža postaje blistavija i ujednačenija. Aktivni sastojci deluju sinergijski kako bi smanjili vidljivost tamnih mrlja i vratili koži mladalački sjaj. Redovnom upotrebom, primetićete poboljšanje elastičnosti i hidratacije kože, što je čini otpornijom na spoljašnje faktore. Ovaj tonik ne samo da posvetljuje ten, već i pruža neophodnu negu koja čini kožu zdravijom i svežijom. Aktivni sastojci Galactomyces Ferment Filtrate (88%) Fermentisani sastojak bogat vitaminima, mineralima, aminokiselinama i enzimima koji obnavlja i hidrira kožu. Pomaže u smanjenju nepravilnosti, poboljšava elastičnost i vraća koži prirodni sjaj. Deluje umirujuće i balansira tonus kože, posebno kod umorne i beživotne kože. Povećava upijanje ostalih aktivnih sastojaka. Čini kožu mekšom, osveženom i zdravijom. Vitamin C (Askorbinska kiselina – 1%) Snažan antioksidans koji ujednačava ten, posvetljuje tamne mrlje i postupalne fleke, i štiti kožu od spoljašnjih oštećenja. Stimuliše sintezu kolagena, čime poboljšava čvrstinu i elastičnost kože. Deluje protiv hiperpigmentacija i doprinosi svežem, blistavom izgledu. U niskoj koncentraciji (1%) pogodna je i za osetljivu kožu. Niacinamid (Vitamin B3) Ujednačava ton kože, smanjuje vidljivost pora i reguliše proizvodnju sebuma. Deluje umirujuće, jača kožnu barijeru i ima blago posvetljujuće efekte. Pomaže u poboljšanju teksture kože i u smanjenju crvenila. Dodaj u listu želja Dodaj u listu želja', 'SOME BY MI Galactomyces Pure Vitamin C Glow Toner je tonik koji sadrži 88% filtrata fermenta galaktomiceta i 1% čistog vitamina C, namenjen za posvetljivanje tena, hidrataciju i poboljšanje teksture kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/SOME-BY-MI-Galactomyces-Pure-Vitamin-C-Glow-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
