INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1157, 156, 'Some By Mi Galactomyces Pure Vitamin C Glow Serum', 'some-by-mi-galactomyces-pure-vitamin-c-glow-serum', 'Ključne prednosti: Posvetljivanje kože: Visok sadržaj vitamina C pomaže u smanjenju tamnih mrlja i ujednačavanju tena, dajući koži zdrav sjaj. Poboljšanje elastičnosti: Galaktomiceti ferment filtrat poboljšava elastičnost kože, čineći je čvršćom i glatkijom. Hidratacija i umirenje: Dodatni sastojci poput niacinamida i hijaluronske kiseline pružaju dubinsku hidrataciju i umiruju iritacije. Kome je namenjen? Ovaj serum je idealan za osobe sa neujednačenim tenom, tamnim mrljama ili kožom koja je izgubila elastičnost i sjaj, kao i za one koji žele preventivnu negu protiv znakova starenja. Zašto volimo SOME BY MI Galactomyces Pure Vitamin C Glow Serum? Zamislite kožu koja svakim danom postaje sve blistavija i ujednačenija. Galactomyces Pure Vitamin C Glow Serum kombinuje moćne sastojke koji ciljano deluju na problematična područja, smanjujući vidljivost tamnih mrlja i vraćajući koži mladalački sjaj. Redovnom upotrebom, primetićete kako vaša koža postaje elastičnija, hidrirana i otpornija na spoljašnje faktore. Ovaj serum ne samo da posvetljuje ten, već i pruža neophodnu negu koja čini kožu zdravijom i svežijom. Aktivni sastojci Galactomyces Ferment Filtrate (75%) Fermentisani sastojak bogat hranljivim materijama koji poboljšava teksturu kože, hidrira i jača elastičnost. Ujednačava ten i podstiče prirodan sjaj. Takođe poboljšava upijanje ostalih aktivnih sastojaka, čineći formulu efikasnijom. Deluje umirujuće i obnavljajuće, idealno za umornu ili neujednačenu kožu. Vitamin C (Askorbinska kiselina – 3%) Efikasno posvetljuje ten, smanjuje hiperpigmentacije i postupalne fleke, dok istovremeno podstiče sintezu kolagena. Deluje kao snažan antioksidans koji štiti kožu od slobodnih radikala i prevremenog starenja. Pruža koži blistav, ujednačen izgled i vidno osvežava ten. Niacinamid (Vitamin B3) Ujednačava boju kože, smanjuje vidljivost pora i poboljšava teksturu. Pomaže u kontroli sebuma i jača zaštitnu funkciju kože. Ima dodatni posvetljujući efekat i deluje umirujuće. Adenozin Anti-age sastojak koji pomaže u zaglađivanju finih linija i borica. Poboljšava čvrstoću i elastičnost kože, čineći je vidno zategnutijom i svežijom. Ekstrakt korena sladića (Glycyrrhiza Glabra Root Extract) Prirodni antioksidans sa umirujućim i posvetljujućim efektima. Deluje protiv crvenila i iritacija, dok doprinosi ujednačenju tena i osvetljavanju tamnih mrlja. Dodaj u listu želja Dodaj u listu želja', 'SOME BY MI Galactomyces Pure Vitamin C Glow Serum je visokokoncentrovani serum koji sadrži 75% filtrata fermenta galaktomiceta i 30.000 ppm čistog vitamina C, namenjen za posvetljivanje tena, poboljšanje elastičnosti kože i smanjenje hiperpigmentacija.', 'https://beauty-health.rs/wp-content/uploads/2024/12/SOME-BY-MI-Galactomyces-Pure-Vitamin-C-Glow-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
