INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1159, 156, 'Some By Mi AHA BHA PHA 30 Days Miracle Toner', 'some-by-mi-aha-bha-pha-30-days-miracle-toner', 'Ključne prednosti: Blaga eksfolijacija: AHA, BHA i PHA kiseline uklanjaju mrtve ćelije kože, pročišćavaju pore i smanjuju višak sebuma. Umirujuće dejstvo: Ekstrakt čajevca i niacinamid smiruju iritacije i crvenilo, pomažući u borbi protiv akni i upala. Hidratacija i balansiranje: Tonik održava optimalnu ravnotežu vlage u koži, čineći je mekom i osveženom. Kome je namenjen? Ovaj tonik je idealan za osobe sa masnom, kombinovanom i aknama sklonom kožom, kao i za one koji žele poboljšati teksturu kože i smanjiti vidljivost pora. Zašto volimo SOME BY MI AHA BHA PHA 30 Days Miracle Toner? Blaga eksfolijacija uklanja nečistoće i mrtve ćelije, otkrivajući svežiji ten. Aktivni sastojci poput ekstrakta čajevca i niacinamida umiruju upale i smanjuju crvenilo, dok istovremeno jačaju zaštitnu barijeru kože. Redovnom upotrebom, tonik pomaže u smanjenju pojave akni i kontroliše lučenje sebuma, ostavljajući kožu uravnoteženom i hidriranom. Poboljšava teksturu kože, čineći je glatkom i mekom na dodir. Ovaj tonik pruža sveobuhvatnu negu, ciljajući više problema odjednom, što ga čini neophodnim dodatkom vašoj rutini nege kože. Aktivni sastojci AHA (alfa-hidroksi kiseline) AHA kiseline, poput glikolne ili mlečne, deluju na površini kože, uklanjajući mrtve ćelije i podstičući obnavljanje. Pomažu u ujednačavanju tena, smanjenju ožiljaka i poboljšanju teksture kože. Poboljšavaju apsorpciju ostalih aktivnih sastojaka i osvetljavaju kožu. Posebno korisne za suvu i zrelu kožu sa neujednačenom površinom. Redovnom upotrebom koža postaje glađa i blistavija. Pomažu u prevenciji začepljenih pora i mitisera. BHA (beta-hidroksi kiselina – salicilna kiselina) BHA prodire duboko u pore i uklanja višak sebuma i nečistoće. Efikasno pomaže u prevenciji i tretmanu akni. Doprinosi sužavanju pora i poboljšanju teksture kože. Ima protivupalna i antibakterijska svojstva, pogodna za masnu i problematičnu kožu. Redovnom upotrebom čisti pore i smanjuje pojavu nepravilnosti. Ne isušuje kožu i deluje postepeno, bez iritacija. PHA (poli-hidroksi kiseline) PHA su nežnije eksfolijantne kiseline koje uklanjaju mrtve ćelije bez iritacije, dok istovremeno zadržavaju vlagu u koži. Idealne su za osetljivu i suvu kožu. Jačaju barijeru kože i pomažu u zadržavanju hidratacije. Imaju antioksidativna svojstva i doprinose ujednačenom tenu. Ne izazivaju crvenilo ni zatezanje. Pomažu koži da postane glatka, elastična i hidrirana. Ekstrakt čajevca (Melaleuca Alternifolia Leaf Extract – Tea Tree) Poznat po snažnim antibakterijskim i antiinflamatornim svojstvima. Efikasno deluje protiv akni i upalnih procesa, smanjuje crvenilo i umiruje kožu. Reguliše lučenje sebuma i čisti pore. Idealan za masnu i problematičnu kožu. Pomaže u ubrzavanju procesa zarastanja i sprečava nastanak novih nepravilnosti. Ostavlja osećaj svežine i čistoće na koži. Dodaj u listu želja Dodaj u listu želja', 'SOME BY MI AHA BHA PHA 30 Days Miracle Toner je multifunkcionalni tonik koji kombinuje AHA, BHA i PHA kiseline sa ekstraktom čajevca i niacinamidom, pružajući blagu eksfolijaciju, hidrataciju i umirujuće dejstvo za kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/SOME-BY-MI-AHA-BHA-PHA-30-Days-Miracle-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
