INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1165, 156, 'Some By Mi Real Hyaluron Hydra Care Mask', 'some-by-mi-real-hyaluron-hydra-care-mask', 'Ključne prednosti: Dubinska hidratacija: Hijaluronska kiselina prodire u dublje slojeve kože, pružajući optimalnu vlažnost i elastičnost. Poboljšanje teksture kože: Redovnom upotrebom, maska doprinosi glatkijoj i mekšoj koži, smanjujući pojavu finih linija. Umirujući efekat: Prirodni biljni ekstrakti pomažu u smirivanju iritacija i crvenila, čineći kožu zdravijom i uravnoteženijom. Kome je namenjena? Ova maska je idealna za osobe sa suvom, dehidriranom ili osetljivom kožom koja zahteva intenzivnu hidrataciju i umirenje. Takođe je pogodna za one koji žele poboljšati teksturu i elastičnost svoje kože. Zašto volimo Some By Mi Real Hyaluron Hydra Care Mask? Pomoću ove maske, vaša koža postaje vidljivo hidrirana i osvežena. Hijaluronska kiselina zadržava vlagu, čineći kožu punijom i elastičnijom. Biljni ekstrakti, poput aloe vere i ruzmarina, pružaju umirujuće dejstvo, smanjujući crvenilo i iritacije. Nakon samo nekoliko upotreba, koža postaje mekša, glatkija i blistavija, dok se barijera kože jača, štiteći je od spoljašnjih uticaja. Aktivni sastojci Hijaluronska kiselina Intenzivno hidrira i vezuje vodu u koži, čime sprečava gubitak vlage. Pruža efekat zaglađivanja i poboljšava elastičnost, dok istovremeno osvetljava ten i deluje protiv bora. Pantenol (Provitamin B5) Umiruje crvenilo i iritacije, podstiče regeneraciju kože i jača njenu zaštitnu barijeru. Efikasan kod ožiljaka, post-akni i oslabljene kože. Glicerin Dubinski hidrira i poboljšava otpornost kože. Štiti od isušivanja, ubrzava regeneraciju i pruža osećaj mekoće, čak i kod suve ili osetljive kože. Betaine Biljni ovlaživač koji hidrira, štiti i umiruje kožu. Doprinosi glatkoći i elastičnosti, a dodatno daje svilenkast osećaj tokom upotrebe maske. Dodaj u listu želja Dodaj u listu želja', 'Some By Mi Real Hyaluron Hydra Care Mask je sheet maska dizajnirana da intenzivno hidrira i osveži suvu i dehidriranu kožu. Obogaćena hijaluronskom kiselinom, pruža dubinsku hidrataciju, poboljšava teksturu kože i vraća joj prirodni sjaj.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Some-By-Mi-Real-Hyaluron-Hydra-Care-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
