INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1168, 156, 'Some By Mi Real Aloe Soothing Care Mask', 'some-by-mi-real-aloe-soothing-care-mask', 'Ključne prednosti: Dubinska hidratacija: Aloe vera i natrijum hijaluronat intenzivno vlaže kožu, poboljšavajući njenu elastičnost i mekoću. Umirujuće dejstvo: Panthenol i ekstrakt aloe vere smanjuju crvenilo i iritacije, čineći kožu smirenijom i osveženom. Prirodna zaštita: Antioksidansi poput tokoferola štite kožu od štetnih spoljašnjih faktora, doprinoseći njenom zdravom izgledu. Kome je namenjena? Ova maska je idealna za osobe sa suvom, osetljivom ili iritiranom kožom, kao i za one koji traže brzo rešenje za umirenje i hidrataciju nakon izlaganja suncu ili stresnim uslovima okoline. Zašto volimo Some By Mi Real Aloe Soothing Care Mask? Nakon napornog dana, vaša koža zaslužuje trenutak nege i opuštanja. Real Aloe Soothing Care Mask pruža upravo to – trenutnu hidrataciju i umirenje zahvaljujući bogatom ekstraktu aloe vere. Dok se maska prilagođava konturama vašeg lica, aktivni sastojci prodiru duboko u epiderm, obnavljajući vlagu i vraćajući koži prirodni sjaj. Ova maska je vaš saveznik u postizanju blistavog i svežeg tena, bez obzira na izazove koje donosi svakodnevica. Aktivni sastojci Aloe vera ekstrakt (Aloe Barbadensis Leaf Extract) Poznat po svojim umirujućim i hidratantnim svojstvima, aloe vera pomaže u smanjenju crvenila i iritacija, pružajući osećaj svežine i obnove. Dodaj u listu želja Dodaj u listu želja', 'Some By Mi Real Aloe Soothing Care Mask je veganska sheet maska obogaćena ekstraktom aloe vere, namenjena umirivanju i hidrataciji kože. Ova maska pruža osvežavajući efekat, ostavljajući kožu revitalizovanom i zdravom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Some-By-Mi-Real-Aloe-Soothing-Care-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
