INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1170, 154, 'Skin1004 Centella Air-Fit Suncream Plus SPF50+ PA++++', 'skin1004-centella-air-fit-suncream-plus', 'Ključne prednosti: Visoka UV zaštita: SPF50+ PA++++ štiti kožu od štetnih UVA i UVB zraka, smanjujući rizik od oštećenja i prevremenog starenja. Umirujući efekat: Ekstrakt Centella Asiatica (10,972 ppm) pomaže u smirivanju iritacija i regeneraciji kože. Prirodno posvetljivanje: Sadrži niacinamid i MadeWhite&#x2122; koji doprinose ujednačavanju tena i posvetljavanju kože. Kome je namenjena? Ova krema je idealna za osobe sa masnom i kombinovanom kožom koje traže visoku UV zaštitu uz umirujuće i posvetljujuće efekte. Zašto volimo Skin1004 Centella Air-Fit Suncream Plus? Madagascar Centella Air-Fit Suncream Plus kombinuje moćnu UV zaštitu sa negujućim svojstvima prirodnih sastojaka. Ekstrakt Centella Asiatica smiruje kožu, čineći je otpornijom na spoljašnje agresore. Fizički filteri, poput cink-oksida, reflektuju UV zrake, pružajući sigurnu zaštitu bez iritacija. Njena lagana tekstura se lako nanosi, brzo upija i ne ostavlja osećaj težine ili masnoće na koži. Bež ton blago ujednačava ten, dajući licu osvežen izgled bez dodatnog šminkanja. Dugotrajna hidratacija i zaštita čine ovu kremu savršenim saveznikom za svakodnevnu upotrebu, bilo da ste kod kuće ili napolju. Aktivni sastojci Centella Asiatica Extract Centella Asiatica, poznata kao &#8220;tigrova trava&#8221;, ima snažno umirujuće i obnavljajuće dejstvo koje pomaže u zaštiti i regeneraciji kože izložene UV zračenju. U ovoj mineralnoj kremi za sunčanje, ekstrakt deluje protivupalno, ublažava crvenilo i jača kožnu barijeru. Takođe podstiče prirodnu sintezu kolagena, što doprinosi čvrstoći i elastičnosti kože. Njeno dejstvo čini SPF formulaciju pogodnom za osetljivu i reaktivnu kožu. Niacinamide Niacinamid (vitamin B3) je višenamenski sastojak koji u ovoj formulaciji pomaže u smanjenju crvenila, ujednačavanju tena i kontroli sebuma. Takođe deluje kao antioksidans i pomaže u jačanju kožne barijere, čime kožu čini otpornijom na spoljašnje uticaje. Njegova upotreba u SPF kremi dodatno doprinosi zaštiti kože od oštećenja izazvanih UV zračenjem. Poboljšava teksturu kože i umanjuje pojavu tamnih mrlja i upalnih procesa. Blag je, neiritirajući i pogodan za sve tipove kože. Posebno koristan kod kože sklone aknama, rozacei i diskoloracijama. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Centella Air-Fit Suncream Plus SPF50+ PA++++ je lagana fizička krema za sunčanje sa blagim bež tonom koja pruža visoku zaštitu od UV zračenja, umiruje kožu i ostavlja prirodan mat završni sloj.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Centella-Air-Fit-Suncream-Plus.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
