INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1174, 154, 'Skin1004 Madagascar Centella Toning Toner', 'skin1004-madagascar-centella-toning-toner', 'Ključne prednosti: Blaga eksfolijacija: PHA (glukonolakton) nežno uklanja mrtve ćelije kože, poboljšavajući njenu teksturu i sjaj. Intenzivna hidratacija: Hijaluronska kiselina i betain zadržavaju vlagu, održavajući kožu hidriranom i elastičnom. Umirujuće dejstvo: Ekstrakt Centella Asiatica smiruje iritacije i crvenilo, pogoduje osetljivoj koži. Kome je namenjen? Ovaj toner je idealan za osobe sa normalnom do osetljivom kožom, uključujući i one sklone aknama ili crvenilu. Pogodan je za svakodnevnu upotrebu i za one koji traže blagu eksfolijaciju bez iritacija. Zašto volimo Skin1004 Madagascar Centella Toning Toner? Redovnom upotrebom Madagascar Centella Toning Tonera, koža postaje vidljivo glatkija i blistavija. Blaga eksfolijacija omogućava bolju apsorpciju narednih proizvoda u rutini nege, dok hijaluronska kiselina pruža dubinsku hidrataciju, čineći kožu elastičnom i svežom. Umirujuća svojstva Centella Asiatica ekstrakta pomažu u smanjenju crvenila i iritacija, pružajući osećaj ugodnosti tokom celog dana. Betain održava ravnotežu vlage, sprečavajući isušivanje i perutanje kože. Ovaj toner doprinosi ujednačenom tenu i smanjenju vidljivosti finih linija, pružajući mladalački izgled. Aktivni sastojci Gluconolactone (PHA) Gluconolactone je poli-hidroksi kiselina (PHA) poznata po svojim blagim eksfolijativnim svojstvima. Pomaže u uklanjanju mrtvih ćelija sa površine kože, otkrivajući svežiji i svetliji ten. Za razliku od alfa-hidroksi kiselina (AHA), gluconolactone je nežniji prema koži, što ga čini pogodnim za osetljive tipove kože. Takođe, deluje kao humektant, privlačeći vlagu i poboljšavajući hidrataciju kože. Ima antioksidativna svojstva koja pomažu u zaštiti kože od slobodnih radikala i prevremenog starenja. Redovna upotreba proizvoda sa gluconolactoneom može doprineti ujednačenijem tenu i poboljšanoj teksturi kože.​ Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Toning Toner je blagi eksfolijant namenjen svakodnevnoj upotrebi, koji sadrži 84% ekstrakta biljke Centella Asiatica i PHA (glukonolakton) za poboljšanje teksture kože. Ovaj toner hidrira, umiruje i posvetljuje kožu, pružajući joj svež i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Toning-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
