INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1177, 154, 'Skin1004 Madagascar Centella Soothing Cream', 'skin1004-madagascar-centella-soothing-cream', 'Ključne prednosti: Intenzivna hidratacija: Ekstrakt Centella Asiatica dubinski hidrira kožu i vraća joj elastičnost. Umirujuće dejstvo: Ceramidi i pantenol smanjuju iritacije i crvenilo, čineći kožu smirenijom i otpornijom. Jačanje kožne barijere: Aktivni sastojci obnavljaju prirodnu barijeru kože, štiteći je od spoljašnjih faktora. Kome je namenjena? Ova krema je namenjena osobama sa normalnom, suvom i osetljivom kožom, posebno onima koje se suočavaju sa iritacijama, crvenilom i oštećenom kožnom barijerom. Pogodna je i za svakodnevnu negu kože koja zahteva dodatnu hidrataciju i umirujući efekat. Zašto volimo Skin1004 Madagascar Centella Soothing Cream? Madagascar Centella Soothing Cream pruža umirujući efekat i dubinsku hidrataciju za osetljivu kožu koja zahteva dodatnu negu. Njena lagana gel formula lako se upija, ostavljajući kožu svežom i bez osećaja masnoće. Zahvaljujući visokom sadržaju Centella Asiatica, krema smanjuje crvenilo i iritacije, dok istovremeno ubrzava regeneraciju kože. Ceramidi jačaju zaštitnu barijeru kože, čineći je otpornijom na štetne spoljne uticaje. Dugotrajnom upotrebom, koža postaje vidljivo hidrirana, glatka i elastična, dok se osećaj zatezanja i suvoće značajno smanjuje. Pantenol dodatno pruža zaštitu i hidraciju, čineći ovu kremu idealnom za svakodnevnu upotrebu, posebno u uslovima stresa i spoljašnjih agresora. Aktivni sastojci Centella Asiatica ekstrakt Poznata po svojim umirujućim i regenerativnim svojstvima, Centella Asiatica pomaže u obnavljanju kože, smanjuje crvenilo i štiti od iritacija. Idealna je za osetljivu i reaktivnu kožu. Biljni ceramidi (EOP, NS, NP, AP) Četiri vrste biljnih ceramida jačaju kožnu barijeru, sprečavaju gubitak vlage i pružaju dugotrajnu hidrataciju. Posebno pogodno za suvu i osetljivu kožu. Mentol i ekstrakt nane Ovi sastojci osvežavaju i hlade kožu, trenutno umiruju iritacije i daju prijatan osećaj na koži. Ekstrakt đumbira Pomaže u zaštiti kože zahvaljujući antioksidantima, poboljšava tonus i ima blagi protivupalni efekat. Beta-glukan Hidratantni sastojak koji umiruje i jača prirodnu otpornost kože, idealan za svakodnevnu negu. Natrijum hijaluronat Dubinski hidrira i pomaže koži da zadrži vlagu, čineći je punijom, mekšom i elastičnijom. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Soothing Cream je umirujuća gel-krema koja sadrži 72% ekstrakta Centella Asiatica i ceramide, pružajući intenzivnu hidrataciju, jačanje kožne barijere i smanjenje iritacija. Njena lagana tekstura čini je pogodnom za svakodnevnu upotrebu, ostavljajući kožu osveženom i uravnoteženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Soothing-Cream-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
