INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1178, 154, 'Skin1004 Madagascar Centella Cream', 'skin1004-madagascar-centella-cream', 'Ključne prednosti: Dubinska hidratacija: Skvalan i tehnologija ulje-u-vodi emulzije omogućavaju dublju i dugotrajniju hidrataciju, održavajući kožu mekom i glatkom. Umirujuće dejstvo: Ekstrakt Centella Asiatica smiruje iritacije i pomaže u regeneraciji kože, čineći je otpornijom na spoljašnje faktore. Anti-age efekat: Aktivni sastojci poput TECA (Total Centella Asiatica) stimulišu sintezu kolagena, poboljšavajući elastičnost kože i smanjujući vidljivost finih linija i bora. Kome je namenjena? Ova krema je idealna za osobe sa normalnom do osetljivom kožom koje traže laganu, ali efikasnu hidrataciju. Posebno je pogodna za one koji žele umiriti iritacije i poboljšati elastičnost kože. Zašto volimo Skin1004 Madagascar Centella Cream? Redovnom upotrebom Madagascar Centella kreme, koža postaje vidljivo hidrirana i umirena. Lagani sastav omogućava brzo upijanje bez osećaja težine, dok aktivni sastojci rade na obnavljanju prirodne barijere kože. Vremenom, koža postaje otpornija na spoljašnje stresore, a znaci starenja, poput finih linija i gubitka elastičnosti, bivaju smanjeni. Ova krema pruža sveobuhvatnu negu koja rezultira zdravijim i svežijim izgledom kože. Aktivni sastojci Centella Asiatica Extract Ekstrakt Centella Asiatica deluje snažno umirujuće i obnavljajuće, čineći ga idealnim za osetljivu i nadraženu kožu. U ovoj kremi, pomaže u smanjenju crvenila, ubrzava zarastanje mikrolezija i jača prirodnu barijeru kože. Posebno je efikasan u zaštiti kože izložene stresorima kao što su UV zračenje, zagađenje i prekomerno isušivanje. Pantenol Pantenol, poznat i kao provitamin B5, ima izraženo hidratantno, umirujuće i reparativno dejstvo. U ovoj formulaciji, pomaže u zadržavanju vlage u koži i smanjuje simptome kao što su suvoća, perutanje i crvenilo. Takođe podstiče obnavljanje ćelija i jača kožnu barijeru, što doprinosi glatkijem i otpornijem tenu. TECA (Madecassoside, Asiaticoside, Madecassic Acid, Asiatic Acid) TECA je visoko koncentrisani kompleks aktivnih komponenti iz Centella Asiatica biljke, poznat po svom ciljanom dejstvu na regeneraciju i smirivanje kože. Madecassoside i Asiaticoside smanjuju upale, ubrzavaju zarastanje i poboljšavaju elastičnost kože. Madecassic i Asiatic Acid dodatno jačaju barijernu funkciju i deluju antioksidativno, štiteći kožu od slobodnih radikala. Ova kombinacija pruža efikasnu pomoć kod crvenila, ožiljaka, suvih i reaktivnih stanja kože. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Cream je lagana hidratantna krema koja umiruje i neguje kožu zahvaljujući ekstraktu biljke Centella Asiatica i skvalanu. Ova kombinacija sastojaka formira zaštitni sloj koji zadržava vlagu i pruža dugotrajnu hidrataciju, čineći kožu mekom i elastičnom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
