INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1179, 154, 'Skin1004 Madagascar Centella Tone Brightening Capsule Ampoule', 'skin1004-madagascar-centella-tone-brightening-capsule-ampoule', 'Ključne prednosti: Posvetljivanje i ujednačavanje tena: Niacinamid i traneksaminska kiselina efikasno smanjuju hiperpigmentacije i tamne fleke. Regeneracija i umirivanje kože: Ekstrakt Centella Asiatica smanjuje iritacije i pomaže u obnavljanju kože. Hidratacija i jačanje barijere: Kombinacija aktivnih sastojaka pruža intenzivnu hidrataciju, ostavljajući kožu mekom i otpornom. Kome je namenjen? Ovaj serum je namenjen osobama sa svim tipovima kože, uključujući osetljivu, koje žele da posvetle tamne fleke, ujednače ten i poboljšaju teksturu kože. Pogodan je i za kožu sklonu iritacijama, zahvaljujući umirujućim svojstvima Centella Asiatica. Zašto volimo Skin1004 Madagascar Centella Tone Brightening Capsule Ampoule? Madagascar Centella Tone Brightening Capsule Ampoule čini vašu rutinu nege kože efikasnom i luksuznom. Njegova formula sadrži moćnu kombinaciju niacinamida i traneksaminske kiseline koja cilja tamne fleke i neujednačen ten, pružajući blistaviji izgled. Aktivni ekstrakt Centella Asiatica umiruje kožu, smanjuje crvenilo i ubrzava regeneraciju, dok 3-O-etil askorbinska kiselina pruža dodatnu antioksidativnu zaštitu. Uz laganu teksturu koja se brzo upija, serum pruža dugotrajnu hidrataciju bez masnog osećaja. Redovna upotreba čini kožu vidljivo svetlijom, ujednačenom i otpornijom na spoljašnje faktore. Mikrokapsule u serumu oslobađaju aktivne sastojke, povećavajući efikasnost formule i omogućavajući ciljano delovanje. Aktivni sastojci Traneksaminska kiselina Traneksaminska kiselina je sintetički aminokiselinski derivat koji inhibira aktivaciju enzima odgovornog za proizvodnju melanina, čime efikasno deluje protiv hiperpigmentacija. Koristi se za tretman melazme, postupalnih fleka i neujednačenog tena zahvaljujući svom depigmentacionom efektu. Osim toga, poseduje snažna antiinflamatorna svojstva, što je čini pogodnom i za osetljivu kožu sklonu crvenilu. MadeWhite&#x2122; (Centella Asiatica ekstrakt + Niacinamid) MadeWhite&#x2122; je patentirani kompleks koji kombinuje ekstrakt Centella Asiatica poreklom sa Madagaskara i niacinamid, ciljano delujući na umirivanje kože i ujednačavanje tena. Centella je poznata po svojim regenerativnim i antiinflamatornim svojstvima, dok niacinamid utiče na smanjenje hiperpigmentacija i regulaciju sebuma. Ova sinergija pruža efikasnu, ali nežnu negu za osetljivu i reaktivnu kožu. MadeWhite&#x2122; takođe doprinosi jačanju kožne barijere i smanjenju crvenila. Ekstrakt papaje (Carica Papaya Fruit Extract) Ekstrakt papaje sadrži prirodne enzime poput papaina koji pomažu u nežnoj enzimatskoj eksfolijaciji kože. Uklanja mrtve ćelije sa površine kože bez mehaničkog trenja, čime doprinosi glatkom i osveženom tenu. Pored eksfolijativnog efekta, papaja sadrži i vitamine A i C koji dodatno pomažu u posvetljavanju kože i podsticanju regeneracije. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Tone Brightening Capsule Ampoule je serum obogaćen ekstraktom Centella Asiatica, 4% niacinamida i 2% traneksaminske kiseline, koji posvetljuje kožu, smanjuje hiperpigmentacije i pruža dubinsku hidrataciju. Njegova lagana formula pomaže u postizanju ujednačenog tena i revitalizovanog izgleda.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Tone-Brightening-Capsule-Ampoule-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
