INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1180, 154, 'Skin1004 Madagascar Centella Poremizing Clarifying Mask', 'skin1004-madagascar-centella-poremizing-clarifying-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Ružičasta himalajska so uklanja nečistoće i mrtve ćelije kože, čisteći pore i poboljšavajući teksturu. Kontrola sebuma: Sukcinska kiselina pomaže u regulaciji viška sebuma, smanjujući masni sjaj kože. Hidratacija i umirivanje: Ekstrakt Centella Asiatica pruža hidrataciju, umiruje crvenilo i pospešuje regeneraciju kože. Kome je namenjen? Ovaj proizvod je idealan za masnu i kombinovanu kožu sklonu začepljenim porama, aknama i nepravilnostima. Takođe je pogodan za osobe sa osetljivom kožom koje traže dubinsko čišćenje bez iritacija. Zašto volimo Skin1004 Madagascar Centella Poremizing Clarifying Mask? Madagascar Centella Poremizing Clarifying Mask pruža osvežavajuće i dubinsko čišćenje koje čini kožu glatkom i balansiranom. Ružičasta himalajska so efikasno uklanja nečistoće i mrtve ćelije kože, dok sukcinska kiselina pomaže u regulaciji sebuma, ostavljajući kožu matiranom. Ekstrakt Centella Asiatica umiruje iritacije i smanjuje crvenilo, dok hidrira kožu i pomaže u njenoj regeneraciji. Rezultat je čista, osvežena koža sa smanjenim porama i ujednačenim tonom. Uz redovnu upotrebu, maska doprinosi smanjenju akni i vraća koži zdrav, blistav izgled. Praktična formula omogućava jednostavno nanošenje i brzo delovanje, čineći je idealnim dodatkom vašoj rutini nege. Aktivni sastojci Centella Asiatica Extract Ekstrakt Centella Asiatica deluje intenzivno umirujuće i regenerativno, što ga čini savršenim za osetljivu i reaktivnu kožu. U ovoj maski, pomaže u smanjenju crvenila, ublažava iritacije i jača kožnu barijeru. Bogat aktivnim komponentama kao što su madecassoside i asiaticoside, podstiče prirodnu sintezu kolagena i ubrzava obnavljanje kože. Adenosine Adenozin je funkcionalni sastojak poznat po svojim anti-age i regenerativnim svojstvima. U ovoj maski, pomaže u ublažavanju sitnih bora i poboljšava elastičnost kože stimulisanjem sinteze kolagena. Takođe ima protuupalno dejstvo koje dodatno umiruje kožu i ubrzava proces oporavka. Plant-Based Collagen Biljni kolagen hidrira i poboljšava elastičnost kože, ostavljajući je glatkom i punijom. Iako ne prodire u dublje slojeve kože kao prirodni kolagen, deluje na površini stvarajući zaštitni film koji sprečava gubitak vlage. Himalayan Pink Salt Ružičasta himalajska so bogata je mineralima koji detoksikuju kožu i pomažu u uklanjanju toksina i viška sebuma. U ovoj maski, deluje pročišćavajuće i pomaže u dubinskom čišćenju pora. Njena blaga eksfolijacija doprinosi osveženom i glatkijem tenu. Succinic Acid Sukcinska kiselina je blagi eksfolijant koji uklanja mrtve ćelije kože i pomaže u smanjenju upala, posebno kod akni. U ovoj maski, deluje antibakterijski i pročišćavajuće, bez izazivanja iritacija. BHA & PHA BHA (salicilna kiselina) prodire duboko u pore, rastvara višak sebuma i sprečava nastanak mitisera i akni. PHA, s druge strane, deluje na površini kože uklanjajući mrtve ćelije bez izazivanja iritacija, što ga čini pogodnim za osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Poremizing Clarifying Mask je glinena maska obogaćena ekstraktom Centella Asiatica i ružičastom himalajskom solju, koja dubinski čisti pore i reguliše proizvodnju sebuma. Dizajnirana je da hidrira, umiruje iritacije i ostavi kožu glatkom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Poremizing-Clarifying-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
