INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1182, 154, 'Skin1004 Madagascar Centella Poremizing Quick Clay Stick Mask', 'skin1004-madagascar-centella-poremizing-quick-clay-stick-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Kombinacija pet vrsta gline, uključujući 18% kaolina, apsorbuje višak sebuma i uklanja nečistoće iz pora, smanjujući pojavu mitesera i belih tačkica. Blaga eksfolijacija: Fino mleveni crveni pasulj uklanja mrtve ćelije kože, poboljšavajući teksturu i vraćajući prirodni sjaj. Umirujuće dejstvo: Ekstrakt Centella Asiatica i aloe vera smiruju iritacije i crvenilo, čineći proizvod pogodnim za osetljivu kožu. Kome je namenjena? Ova maska je idealna za osobe sa masnom, kombinovanom ili normalnom kožom, posebno onima koji se bore sa proširenim porama, viškom sebuma ili nepravilnostima u teksturi kože. Zašto volimo Skin1004 Madagascar Centella Poremizing Quick Clay Stick Mask? Kombinacija 5 vrsta gline efikasno uklanja višak sebuma, dok crveni pasulj pruža blagu eksfolijaciju, otkrivajući glatkiju i blistaviju kožu. Umirujući sastojci poput Centella Asiatica i aloe vere smanjuju iritacije, pružajući osećaj udobnosti nakon svakog tretmana. Praktičan oblik stika omogućava jednostavnu i higijensku primenu, bez nereda karakterističnog za tradicionalne glinene maske. Nakon ispiranja, koža ostaje meka, glatka i spremna za dalju negu. Aktivni sastojci Centella Asiatica ekstrakt Umiruje iritiranu kožu, smanjuje crvenilo i pomaže u regeneraciji. Deluje antiinflamatorno i obnavlja zaštitnu barijeru kože. Posebno koristan za kožu sklonu nepravilnostima, oštećenjima ili upalama. Poboljšava elastičnost i doprinosi zdravijem tenu. Pomaže u balansiranju masnoće i smanjenju osipa. Idealna je za redovnu negu osetljive, masne i problematične kože. Kaolin Blaga glina koja nežno apsorbuje višak sebuma i nečistoće bez isušivanja kože. Čisti pore i pomaže u smanjenju njihove vidljivosti. Pogodna je za osetljivu kožu zahvaljujući svojoj nežnoj teksturi. Pruža mat izgled i poboljšava tonus kože. Deluje umirujuće i balansira prirodna ulja na koži. Redovnom upotrebom doprinosi čistijoj i ujednačenijoj koži. Bentonit Mineralna glina poznata po snažnom detoksikacionom dejstvu. Efikasno uklanja toksine, višak ulja i nečistoće iz pora. Ima antibakterijska svojstva koja pomažu u borbi protiv akni i upala. Istovremeno umiruje kožu i podstiče regeneraciju. Pogodna je za masnu i kombinovanu kožu. Ostavlja osećaj čistoće i zategnutosti bez iritacija. Illite Prirodna crvena glina bogata mineralima, poznata po svojoj sposobnosti da revitalizuje i osveži umornu kožu. Uklanja toksine, čisti pore i poboljšava mikrocirkulaciju. Deluje lagano eksfolijativno, osvetljava ten i ujednačava teksturu. Pomaže u balansiranju masnoće i poboljšava tonus kože. Idealna za mešovitu i masnu kožu. Koristi se za pročišćavanje i osveženje tena. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Poremizing Quick Clay Stick Mask je inovativna maska u stiku koja efikasno čisti i sužava pore, uklanja višak sebuma i nečistoće, ostavljajući kožu osveženom i glatkom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Poremizing-Quick-Clay-Stick-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
