INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1183, 154, 'Skin1004 Madagascar Centella Double Cleansing Duo', 'skin1004-madagascar-centella-double-cleansing-duo', 'Ključne prednosti: Temeljno čišćenje: Kombinacija uljanog i penušavog čistača efikasno uklanja šminku, prljavštinu i višak sebuma, ostavljajući kožu čistom i osveženom. Umirujuće dejstvo: Obogaćen ekstraktom Centella Asiatica, poznatim po svojim umirujućim svojstvima, pomaže u smirivanju iritacija i crvenila. Hidratacija: Prirodni sastojci poput ulja suncokreta i jojobe pružaju hidrataciju, održavajući kožu mekom i elastičnom. Kome je namenjen? Ovaj set je idealan za osobe sa svim tipovima kože koje traže efikasno, ali blago rešenje za uklanjanje šminke i nečistoća, posebno one sa osetljivom ili iritiranom kožom sklonom crvenilu. Zašto volimo Skin1004 Madagascar Centella Double Cleansing Duo? Korišćenjem ovog dvojca, vaša koža će svakodnevno uživati u temeljnom čišćenju bez osećaja zatezanja ili suvoće. Centella Light Cleansing Oil rastapa čak i najuporniju šminku. Centella Ampoule Foam uklanja preostale nečistoće, pružajući osećaj svežine i čistoće. Redovnom upotrebom, koža postaje vidljivo čistija, umirena i hidrirana, spremna za dalju negu. Dodaj u listu želja Dodaj u listu želja', 'Skin1004 Madagascar Centella Double Cleansing Duo je savršeni set za dvostruko čišćenje lica koji kombinuje Centella Light Cleansing Oil i Centella Ampoule Foam, pružajući temeljno i nežno uklanjanje nečistoća i šminke.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Skin1004-Madagascar-Centella-Double-Cleansing-Duo.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
