INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1185, 149, 'Secret Key Sweet Glam Tint Glow', 'secret-key-sweet-glam-tint-glow', 'Ključne prednosti: Intenzivna hidratacija: Lanolin i ulje slatkog badema dubinski hrane usne, održavajući ih mekim i glatkim. Prirodni sjaj: Vita Berry kompleks pruža suptilan, zdrav sjaj, ističući prirodnu lepotu usana. Praktično pakovanje: Lako nošenje i brzo osvežavanje boje tokom dana. Kome je namenjen? Idealan za osobe sa suvim ili ispucalim usnama koje traže hidrataciju i blagu boju, kao i za one koji preferiraju prirodan izgled sa suptilnim sjajem. Zašto volimo Secret Key Sweet Glam balzam za usne? Daje nežnu i prirodnu boju koja se prilagođava tonu usana, ističući njihovu prirodnu punoću. Lagana teksture omogućavaju glatko nanošenje bez osećaja težine ili lepljivosti. Praktično pakovanje čini ga savršenim saputnikom za torbicu, omogućavajući brzo osvežavanje boje i hidratacije u svakom trenutku. Redovnom upotrebom, usne postaju mekše, glatkije i vizuelno privlačnije. Dodaj u listu želja Dodaj u listu želja', 'Secret Key Sweet Glam Tint Glow je tonirani balzam za usne, obogaćena lanolinom, Vita Berry kompleksom i uljem slatkog badema, koji pružaju hidrataciju i suptilan sjaj bez lepljivosti. Baby Pink nijansa.', 'https://beauty-health.rs/wp-content/uploads/2024/12/balzam-za-usne-u-boji.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
