INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1188, 143, 'Round Lab Birch Juice Moisturizing Sun Cream', 'round-lab-birch-juice-moisturizing-sun-cream', 'Ključne prednosti: Visoka UV zaštita: Pruža pouzdanu zaštitu od štetnih UVA i UVB zraka, sprečavajući oštećenja kože uzrokovana sunčevim zračenjem. Dubinska hidratacija: Sok breze i hijaluronska kiselina obezbeđuju intenzivnu vlažnost, čineći kožu mekom i elastičnom tokom celog dana. Bez belog traga: Formula se brzo upija, ne ostavljajući beli trag niti osećaj težine na koži, što je čini idealnom za svakodnevnu upotrebu. Kome je namenjena? Ova krema je idealna za sve tipove kože. Posebno za osobe sa suvom ili dehidriranom kožom koja zahteva dodatnu hidrataciju i pouzdanu zaštitu od sunca. Zašto volimo ROUND LAB Birch Juice Moisturizing Sun Cream? Uz svakodnevnu upotrebu Birch Juice Moisturizing Sun Cream, vaša koža ostaje zaštićena od štetnih UV zraka. Time se smanjuje rizik od preuranjenog starenja i pigmentacija. Hidratantna svojstva soka breze i hijaluronske kiseline pružaju dugotrajnu vlažnost, smanjujući osećaj suvoće i zategnutosti. Lagana tekstura omogućava lako nanošenje i brzo upijanje. Koža je glatka i pripremljena za šminku ili druge proizvode za negu. Redovnom upotrebom, koža postaje vidljivo zdravija, blistavija i otpornija na spoljašnje uticaje. Aktivni sastojci Glyceryl Glucoside Glyceryl glucoside je derivat glicerina i glukoze koji pomaže u jačanju prirodnih antioksidativnih enzima u koži, čime poboljšava njenu otpornost na stres iz okoline. Ovaj sastojak aktivira unutrašnje mehanizme zaštite ćelija, omogućavajući koži da se efikasnije bori protiv UV zračenja, zagađenja i gubitka vlage. U ovoj formuli, glyceryl glucoside deluje kao funkcionalni hidratant koji sprečava dehidrataciju i poboljšava ukupnu hidrataciju kože tokom izlaganja suncu. Takođe doprinosi ujednačenom tonu i mekoj teksturi kože. Homosalate Homosalate je hemijski UVB filter koji apsorbuje UVB zrake i sprečava oštećenja izazvana sunčevim zračenjem, kao što su opekotine, preuranjeno starenje i rizik od razvoja raka kože. Deluje tako što pretvara UVB svetlost u toplotu, čime sprečava njen prodor u dublje slojeve kože. U ovoj kremi, homosalate čini osnovu SPF zaštite i osigurava efikasnu barijeru protiv svakodnevnog izlaganja suncu. Niacinamide Niacinamid (Vitamin B3) je višenamenski sastojak koji pomaže u smanjenju hiperpigmentacija, ujednačavanju tena i posvetljavanju kože. Takođe ima izražena protivupalna svojstva, što ga čini korisnim za kožu sklonu aknama, crvenilu i iritacijama poput ekcema. U ovoj formuli, niacinamid deluje sinergijski sa UV filterima kako bi umanjio štetu izazvanu UV zracima i pospešio oporavak kože. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Birch Juice Moisturizing Sun Cream je lagana hidratantna krema sa SPF50+ PA++++, koja kombinuje sok breze i hijaluronsku kiselinu za optimalnu zaštitu od UV zračenja i intenzivnu hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-Birch-Juice-Moisturizing-Sun-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
