INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1190, 143, 'Round Lab Birch Juice Moisturizing Cream', 'round-lab-birch-juice-moisturizing-cream', 'Ključne prednosti: Dubinska hidratacija: Kombinacija soka breze i hijaluronske kiseline obezbeđuje optimalan nivo vlažnosti, čineći kožu mekom i elastičnom. Jačanje barijere kože: Aktivni sastojci pomažu u obnovi i jačanju zaštitne barijere kože, štiteći je od spoljašnjih uticaja. Umirujuće dejstvo: Prirodni ekstrakti smanjuju iritacije i crvenilo, pružajući olakšanje osetljivoj koži. Kome je namenjena? Ova krema je idealna za sve tipove kože, posebno za one sa suvom, dehidriranom ili osetljivom kožom koja zahteva dodatnu hidrataciju i umirenje. Zašto volimo ROUND LAB Birch Juice Moisturizing Cream? Lagana tekstura ove kreme omogućava brzo upijanje bez osećaja težine. Sok breze bogat mineralima i antioksidansima pruža neophodnu negu. Hijaluronska kiselina zadržava vlagu u dubljim slojevima kože, smanjujući pojavu finih linija i čineći ten blistavijim. Prirodni ekstrakti dodatno umiruju iritacije, ostavljajući kožu osveženom i zaštićenom tokom celog dana. Aktivni sastojci Betula Platyphylla Japonica Juice (10,000 ppm) Sok japanske bele breze (Betula Platyphylla Japonica) bogat je sa 17 aminokiselina, mineralima, antioksidansima i vitaminima koji pružaju višeslojnu negu kože. Ovaj prirodni ekstrakt ima trostruko dejstvo: smanjuje upale, pročišćava kožu i intenzivno hidrira. U ovoj kremi deluje kao centralni hidratantno-umirujući agens koji pomaže u obnavljanju kože izložene stresu, suvoći ili iritacijama. Njegovo antiinflamatorno dejstvo umanjuje crvenilo i osnažuje kožnu barijeru, dok antioksidansi štite od štetnih uticaja iz okoline. Idealno je prilagođen za osetljivu i dehidriranu kožu. Redovnom upotrebom koža postaje elastičnija, svetlija i zdravijeg izgleda. Jojoba Esters Jojoba esteri su derivat jojobinog ulja sa sličnim lipidnim sastavom kao prirodni sebum kože, što im omogućava lako upijanje i visoku podnošljivost. U ovoj formuli deluju kao stabilizujući emolijensi koji poboljšavaju zadržavanje vlage i jačaju prirodnu zaštitnu barijeru kože. Pomažu u sprečavanju transepidermalnog gubitka vode, ostavljajući kožu hidriranom, mekom i glatkom. Takođe poboljšavaju teksturu kreme, čineći je svilenkastom i pogodnom za sve tipove kože. Deluju bez iritacije i komedogenog efekta. Savršeni su za svakodnevnu hidratantnu negu. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Birch Juice Moisturizing Cream je lagana hidratantna krema obogaćena sokom breze i hijaluronskom kiselinom, pružajući intenzivnu hidrataciju i umirujući efekat za sve tipove kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-Birch-Juice-Moisturizing-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
