INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1193, 143, 'Round Lab 1025 Dokdo Toner', 'round-lab-1025-dokdo-toner', 'Ključne prednosti: Intenzivna hidratacija: Duboka morska voda bogata mineralima prodire duboko u kožu, pružajući dugotrajnu vlagu i poboljšavajući elastičnost. Umirujuće dejstvo: Pantenol i alantoin smiruju iritacije i crvenilo, čineći ga idealnim za osetljivu kožu sklonu upalama. Blaga eksfolijacija: Patentirani kompleks HATCHING EX-07 nežno uklanja mrtve ćelije kože, otkrivajući glatku i blistavu površinu. Kome je namenjen? Ovaj tonik je pogodan za sve tipove kože, uključujući osetljivu i suvu kožu koja zahteva dodatnu hidrataciju i umirenje. Takođe je idealan za osobe koje se suočavaju sa neravnotežom vlage ili blagim iritacijama. Zašto volimo ROUND LAB 1025 Dokdo Toner? Korišćenjem 1025 Dokdo Tonera, vaša koža postaje dubinski hidrirana, meka i elastična. Minerali iz duboke morske vode pomažu u jačanju barijere kože, štiteći je od spoljašnjih agresora. Pantenol i alantoin deluju sinergijski kako bi smanjili crvenilo i iritacije, pružajući osećaj ugodnosti tokom celog dana. Redovna upotreba ovog tonika doprinosi ujednačenom tenu i zdravom sjaju kože. Blaga eksfolijacija omogućava bolju apsorpciju narednih proizvoda u rutini nege, maksimizirajući njihove efekte. Bez prisustva štetnih sastojaka, ovaj tonik je siguran za svakodnevnu upotrebu, čak i kod najosetljivijih tipova kože. Aktivni sastojci Dubinska morska voda sa ostrva Dokdo (Deep Sea Water) Morska voda sa dubina oko ostrva Dokdo bogata je mineralima poput kalcijuma, magnezijuma i natrijuma, koji pomažu u održavanju optimalnog balansa vode i ulja u koži. Doprinosi hidrataciji, jačanju kožne barijere i zaštiti od štetnih uticaja iz okoline. U ovom toniku, dubinska morska voda deluje umirujuće, osvežavajuće i remineralizujuće, pružajući koži osećaj ravnoteže i stabilnosti. Njeno prisustvo čini formulaciju idealnom za svakodnevnu upotrebu, bez izazivanja iritacija. Posebno pogodna za dehidriranu, reaktivnu i oslabljenu kožu. Rezultat je hidrirana, osvežena i blistava koža. HATCHING EX-07 HATCHING EX-07 je blag, patentiran kompleks za eksfolijaciju koji nežno uklanja mrtve ćelije kože i višak sebuma bez iritacije. Ovaj sastojak poboljšava teksturu kože, čini ten ujednačenijim i doprinosi smanjenju začepljenih pora. U ovoj formuli, HATCHING EX-07 deluje kao hemijski piling pogodan i za osetljivu kožu, omogućavajući svakodnevnu upotrebu bez narušavanja barijerne funkcije. Koža postaje glatkija, mekša i spremnija za upijanje aktivnih sastojaka iz narednih koraka nege. Savršen je za korisnike koji žele čistu i osveženu kožu bez grubih čestica. Posebno je koristan kod kombinovane i masne kože. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB 1025 Dokdo Toner je blagi tonik formulisan sa dubokom morskom vodom bogatom mineralima, pantenolom i alantoinom, koji pruža intenzivnu hidrataciju i umiruje kožu. Ovaj tonik pomaže u održavanju optimalne ravnoteže vlage, ostavljajući kožu osveženom i revitalizovanom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-1025-Dokdo-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
