INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1194, 143, 'Round Lab Mugwort Calming Sheet Mask', 'round-lab-mugwort-calming-sheet-mask', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja nečistoće i višak sebuma bez isušivanja kože. Hranljiva nega: Ekstrakt crnog sočiva pruža esencijalne nutrijente koji revitalizuju kožu. Jačanje barijere kože: Ceramidi pomažu u obnavljanju i jačanju prirodne zaštitne barijere kože. Kome je namenjena? Ova maska je idealna za osobe sa suvom, osetljivom ili iritiranom kožom, kao i za one koji žele da umire crvenilo i poboljšaju hidrataciju. Zašto volimo ROUND LAB Mugwort Calming Sheet Mask? Pomoću Mugwort Calming Sheet maske koža postaje umirena i osvežena, zahvaljujući moćnim svojstvima pelina koji smanjuje upale i iritacije. Dubinska hidratacija koju pruža maska čini kožu mekom i elastičnom, dok madecassoside doprinosi obnovi i jačanju kožne barijere, štiteći je od spoljašnjih agresora. Redovnom upotrebom, ten postaje ujednačeniji, a osećaj zategnutosti i suvoće nestaje, ostavljajući kožu zdravom i blistavom. Aktivni sastojci Artemisia Vulgaris Extract (10,000 ppm) Ekstrakt pelina (Artemisia Vulgaris) poznat je po svojim snažnim umirujućim i antibakterijskim svojstvima, što ga čini idealnim za negu iritirane i aknama sklone kože. U ovoj sheet maski, pelin efikasno smanjuje crvenilo, balansira lučenje sebuma i ublažava zapaljenske procese. Takođe pomaže u zaštiti kože od spoljašnjih faktora poput zagađenja i UV stresa. Madecassoside Madecassoside je snažna aktivna komponenta iz biljke Centella Asiatica, poznata po svojim regenerativnim i protivupalnim svojstvima. U ovoj maski, pomaže u smirivanju nadražene kože, ubrzava proces zarastanja i jača barijernu funkciju kože. Deluje umirujuće čak i na najosetljivijoj koži i smanjuje efekat spoljašnjih agresora. Althaea Rosea Flower Extract Ekstrakt cveta sleza (Althaea Rosea) bogat je polisaharidima koji deluju kao prirodni ovlaživači, zadržavajući vlagu u koži i štiteći je od isušivanja. U ovoj formuli, pruža intenzivnu hidrataciju i istovremeno deluje umirujuće na upaljena i osetljiva područja. Caffeine Kofein je poznat po svom efektu smanjenja natečenosti i stimulaciji mikrocirkulacije, što pomaže u osvežavanju i zaštiti kože. U ovoj sheet maski, kofein poboljšava tonus kože, smanjuje znake umora i pruža antioksidativnu zaštitu od slobodnih radikala. Takođe ima umirujuće dejstvo koje ublažava crvenilo i stres u koži. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Mugwort Calming Sheet Mask je hidratantna maska od čistog pamuka, natopljena prirodnim sastojcima koji umiruju i osvežavaju kožu, ostavljajući je mekom i revitalizovanom. Ključni sastojci uključuju ekstrakt pelina (Artemisia Vulgaris) i madecassoside, koji zajedno pružaju antiinflamatorne i umirujuće benefite.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-Mugwort-Calming-Sheet-Mask-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
