INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1195, 143, 'Round Lab Soybean Cleanser', 'round-lab-soybean-cleanser', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja nečistoće i višak sebuma bez isušivanja kože. Hranljiva nega: Ekstrakt crnog sočiva pruža esencijalne nutrijente koji revitalizuju kožu. Jačanje barijere kože: Ceramidi pomažu u obnavljanju i jačanju prirodne zaštitne barijere kože. Kome je namenjen? Ovaj proizvod je idealan za osobe sa suvom ili dehidriranom kožom koja zahteva dodatnu hidrataciju i jačanje barijere. Takođe je pogodan za one koji traže blago, ali efikasno sredstvo za čišćenje koje ne iritira kožu. Zašto volimo ROUND LAB Soybean Cleanser? Sa LAB Soybean Cleanser-om, vaša koža postaje temeljno očišćena i osvežena, bez osećaja zatezanja ili suvoće. Hranljivi sastojci, poput ekstrakta crnog sočiva, pružaju esencijalne vitamine i minerale koji revitalizuju kožu, čineći je mekom i glatkom na dodir. Ceramidi u formuli rade na jačanju zaštitne barijere kože, pomažući u zadržavanju vlage i zaštiti od spoljašnjih agresora. Redovnom upotrebom, koža postaje otpornija, hidrirana i blistava, dok se smanjuje pojava suvih područja i iritacija. Aktivni sastojci Glycine Max (Soybean) Seed Extract Ekstrakt semena soje bogat je izoflavonima koji deluju kao snažni antioksidansi, pomažući u neutralizaciji slobodnih radikala koji uzrokuju prevremeno starenje kože. U ovoj peni za čišćenje, soja pomaže u očuvanju elastičnosti, umanjuje pojavu finih linija i bora, i doprinosi ujednačenijem tenu. Njegovo umirujuće i obnavljajuće dejstvo blagotvorno deluje na kožu tokom čišćenja, sprečavajući isušivanje i iritaciju. Ceramide NP Ceramide NP je lipid sličan onima koji se prirodno nalaze u koži, i ključan je za očuvanje i obnovu njene zaštitne barijere. U ovoj formuli, ceramid deluje umirujuće i regenerativno, smanjujući iritacije i štiteći kožu od transepidermalnog gubitka vlage koji se može javiti nakon čišćenja. Posebno je efikasan kod suve, grube i osetljive kože jer pruža intenzivnu negu i pomaže u očuvanju prirodne hidratacije. Doprinosi osećaju mekoće i elastičnosti bez osećaja zatezanja. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB Soybean Cleanser je hranljiva pena za čišćenje lica, obogaćena ekstraktom crnog sočiva i ceramidima, koja efikasno uklanja nečistoće dok istovremeno hidrira i jača barijeru kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/ROUND-LAB-Soybean-Cleanser-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product_category (product_id, category_id) VALUES (1195, 68);
