INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1196, 143, 'Round Lab 1025 Dokdo Cleansing Water', 'round-lab-1025-dokdo-cleansing-water', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja šminku i nečistoće bez iritacije kože. Hidratacija: Sadrži hijaluronsku kiselinu koja zadržava vlagu, ostavljajući kožu mekom i glatkom. Umirujuće dejstvo: Pantenol i alantoin smiruju iritacije i poboljšavaju barijernu funkciju kože. Kome je namenjen? Pogodan za sve tipove kože, uključujući osetljivu i suvu kožu sklonu iritacijama. Idealan za one koji traže efikasan, ali blag čistač koji održava hidrataciju kože. Zašto volimo Round Lab 1025 Dokdo Cleansing Water? Korišćenjem ovog proizvoda, koža postaje temeljno očišćena bez osećaja zatezanja ili suvoće. Minerali iz dubokomorske vode doprinose održavanju optimalne ravnoteže vlage, dok hijaluronska kiselina pruža dubinsku hidrataciju. Pantenol i alantoin deluju umirujuće, smanjujući crvenilo i iritacije, čineći kožu zdravijom i otpornijom na spoljašnje faktore. Aktivni sastojci Dubinska morska voda (Deep Sea Water) Dubinska morska voda sa ostrva Dokdo sadrži prirodno prisutne minerale poput magnezijuma, kalcijuma i natrijuma, koji pomažu u očuvanju balansa vlažnosti i jačanju zaštitne funkcije kože. Ovaj sastojak ne samo da hidrira, već i umiruje kožu, smanjujući osećaj zatezanja nakon čišćenja. U ovoj micelarnoj vodi, dubinska morska voda deluje kao hidratantna osnova koja neguje i osvežava, dok uklanja nečistoće. Micelarni kompleks (Micelle Particles) Miceli su molekulske strukture koje efikasno privlače i „zarobljavaju“ nečistoće, šminku i višak sebuma bez potrebe za trljanjem. U ovoj formuli, miceli deluju kao nežni ali moćni čistači koji uklanjaju prljavštinu bez isušivanja kože. Oni formiraju zaštitni sloj koji čuva vlagu i ostavlja kožu osveženom, čistom i negovanom. Pantenol (Provitamin B5) Pantenol ima sposobnost da dubinski hidrira i umiri kožu, dok istovremeno poboljšava njenu elastičnost i obnavlja zaštitnu barijeru. U ovoj micelarnoj vodi, pomaže u očuvanju mekoće kože nakon čišćenja, smanjujući mogućnost iritacija. Njegova sposobnost da zadrži vlagu u ćelijama čini ga savršenim za osetljivu i suvu kožu. Alantoin Alantoin je blag, ali efikasan sastojak koji smiruje i regeneriše kožu, naročito nakon izlaganja spoljnim stresorima poput šminke, zagađenja ili UV zračenja. U ovoj formuli deluje kao zaštitnik kože, pomažući u smanjenju crvenila i ubrzavajući proces obnove ćelija. Hijaluronska kiselina Hijaluronska kiselina je poznata po svojoj sposobnosti da privlači i zadržava vlagu u koži, ostavljajući je punom, mekom i elastičnom. U ovoj micelarnoj vodi, hijaluronska kiselina osigurava da koža ostane hidrirana i nakon uklanjanja šminke, sprečavajući suvoću i zatezanje. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB 1025 Dokdo Cleansing Water je blagi čistač lica obogaćen mineralima iz dubokomorske vode, koji efikasno uklanja nečistoće i šminku dok održava prirodnu hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Round-Lab-1025-Dokdo-Cleansing-Water.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
