INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1197, 143, 'Round Lab 1025 Dokdo Cleansing Gel', 'round-lab-1025-dokdo-cleansing-gel', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja nečistoće i višak sebuma bez isušivanja kože. Intenzivna hidratacija: Osam tipova hijaluronske kiseline pružaju dubinsku hidrataciju, ostavljajući kožu mekom i elastičnom. Umirujuće dejstvo: Prirodni biljni ekstrakti smanjuju iritacije i crvenilo, pogodno za osetljivu kožu. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući osetljivu i suvu kožu, kao i za one koji traže blago, ali efikasno sredstvo za čišćenje koje pruža hidrataciju i umirenje. Zašto volimo Round Lab 1025 Dokdo Cleansing Gel? Uz pomoć Dokdo Cleansing Gela, vaša koža će biti temeljno očišćena od svakodnevnih nečistoća i ostataka šminke, dok će istovremeno zadržati prirodnu vlagu. Osam tipova hijaluronske kiseline prodiru duboko u kožu, pružajući višeslojnu hidrataciju koja poboljšava elastičnost i čini kožu glatkom. Minerali iz morske vode bogati hranljivim sastojcima revitalizuju kožu. Biljni ekstrakti umiruju iritacije i smanjuju crvenilo. Redovnom upotrebom, koža postaje osvežena, hidrirana i blistava, bez osećaja zatezanja ili suvoće. Dodaj u listu želja Dodaj u listu želja', 'ROUND LAB 1025 Dokdo Cleansing Gel je blagi gel za čišćenje lica sa niskim pH, obogaćen mineralima iz morske vode i 8 tipova hijaluronske kiseline, koji efikasno uklanja nečistoće dok hidrira i umiruje kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Round-Lab-1025-Dokdo-Cleansing-Gel-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
