INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1198, 138, 'Pyunkang Yul Miniature 4-Type Set', 'pyunkang-yul-miniature-4-type-set', 'Šta set sadrži? Essence Toner (30ml). Ovaj toner kombinuje laganu teksturu i dubinsku hidrataciju uz pomoć biljnih ekstrakata i hijaluronske kiseline. Obnavlja pH ravnotežu kože, pripremajući je za bolju apsorpciju narednih proizvoda. Idealan je za umirenje iritacija i regeneraciju dehidrirane kože. Moisture Serum (9ml). Formulisan sa skvalanom i ekstraktima biljaka, pruža intenzivnu hidrataciju i smanjuje gubitak vlage. Jača barijeru kože, ostavljajući je glatkom i mekom tokom celog dana. Lagan, nemasni serum savršen je za sve tipove kože, uključujući masnu i kombinovanu Nutrition Cream (20ml). Krema bogata hranljivim sastojcima poput makadamijinog ulja i shea maslaca, dubinski hrani i obnavlja kožu. Poboljšava elastičnost i tonus kože, dok je istovremeno štiti od isušivanja. Ova krema idealna je za zrelu, suvu i umornu kožu kojoj je potrebna dodatna nega. Low pH Pore Deep Cleansing Foam (40ml). Penušavi čistač sa niskim pH nivoom nježno uklanja nečistoće i višak sebuma bez narušavanja prirodne barijere kože. Formulisan sa ekstraktom zelenog čaja i biljnim sastojcima, umiruje kožu i pruža osećaj svežine. Idealan je za svakodnevno čišćenje i osveženje svih tipova kože. Ključne prednosti: Kompletna rutina nege kože: Set uključuje proizvode za čišćenje, toniranje, hidrataciju i ishranu kože. Pogodan za putovanja: Mini formati omogućavaju jednostavno pakovanje i praktičnu upotrebu. Prilagođen svim tipovima kože: Formule su nežne, hidratantne i bez potencijalno iritantnih sastojaka. Kome je namenjen? Ovaj set je idealan za sve tipove kože, posebno za osobe koje traže lagane i efikasne proizvode za hidrataciju, umirenje i regeneraciju kože. Pogodan je za osetljivu kožu, zahvaljujući formulama bez alkohola, veštačkih mirisa i boja. Zašto volimo Pyunkang Yul Miniature 4-Type Set? Uz Miniature 4-Type Set, vaša koža će dobiti sve što joj je potrebno za optimalnu negu. Essence Toner pomaže u vraćanju vlage i priprema kožu za efikasniju apsorpciju seruma i kreme. Moisture Serum obezbeđuje dubinsku hidrataciju, dok Nutrition Cream pruža bogatu ishranu i regeneraciju kože, poboljšavajući njenu elastičnost. Low pH Pore Deep Cleansing Foam nežno uklanja nečistoće, ostavljajući kožu osveženom i čistom. Svi proizvodi zajedno deluju sinergijski, čineći kožu mekom, glatkom i zdravom. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Miniature 4-Type Set sadrži 4 osnovna proizvoda za kompletnu rutinu nege kože: Essence Toner , Moisture Serum , Nutrition Cream , i Low pH Pore Deep Cleansing Foam . Svaki proizvod je formulisan da hidrira, umiri i revitalizuje kožu, čineći je mekom, elastičnom i blistavom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Pyunkang-Yul-Miniature-4-Type-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
