INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1199, 137, 'Purito Pure Vitamin C Serum', 'purito-pure-vitamin-c-serum', 'Ključne prednosti: Posvetljivanje tena: Askorbinska kiselina smanjuje hiperpigmentaciju i osvetljava kožu. Poboljšanje elastičnosti: Hijaluronska kiselina hidrira kožu, povećavajući njenu čvrstinu. Ujednačavanje boje kože: Niacinamid smanjuje crvenilo i neujednačen ton kože. Kome je namenjen? Ovaj serum je idealan za osobe sa umornom, beživotnom kožom sklonom hiperpigmentaciji ili neujednačenom tonu. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo PURITO Pure Vitamin C Serum? Redovnom upotrebom Pure Vitamin C Seruma, koža postaje blistavija i ujednačenija. Aktivni sastojci sinergijski deluju na smanjenje tamnih mrlja i finih linija, dok istovremeno poboljšavaju teksturu kože. Lagana tekstura seruma omogućava brzo upijanje bez ostavljanja masnog traga, čineći ga idealnim za svakodnevnu upotrebu. Bez prisustva esencijalnih ulja i veštačkih mirisa, ovaj serum je pogodan i za najosetljivije tipove kože. Pružajući dubinsku hidrataciju i antioksidativnu zaštitu, koža postaje otpornija na spoljašnje stresore i zrači zdravim sjajem. Aktivni sastojci Vitamin C (Askorbinska kiselina) Vitamin C je snažan antioksidans poznat po svojoj sposobnosti da posvetli kožu, ujednači ten i poboljša izgled hiperpigmentacija, tamnih fleka i ožiljaka od akni. Stimuliše sintezu kolagena, čime doprinosi većoj elastičnosti i smanjenju finih linija i bora. Takođe štiti kožu od štetnog dejstva UV zračenja i slobodnih radikala, usporavajući proces starenja. Redovnom upotrebom, koža postaje osvetljenija, zategnutija i svežijeg izgleda. U ovoj formuli, vitamin C deluje sinergijski sa vitaminom E i biljnim ekstraktima za maksimalan anti-age efekat. Hijaluronska kiselina Hijaluronska kiselina je moćan humektant koji zadržava vlagu u koži, poboljšava njenu elastičnost i doprinosi punijem i hidriranom izgledu. Njena sposobnost da privuče i zadrži do 1000 puta više vode od sopstvene težine čini je ključnim sastojkom za borbu protiv suvoće i gubitka volumena. Vitamin E (Tokoferol) Vitamin E je snažan liposolubilni antioksidans koji štiti kožu od oksidativnog stresa i potpomaže regeneraciju ćelija. Povećava efikasnost vitamina C, stabilizuje formulu i pojačava anti-age delovanje. Takođe pomaže u zadržavanju vlage u koži, čineći je mekšom, elastičnijom i otpornijom na spoljašnje faktore. Ekstrakt korena ginsenga (Panax Ginseng Root Extract) Ekstrakt ginsenga bogat je saponinima i antioksidansima koji podstiču mikrocirkulaciju, poboljšavaju tonus kože i pomažu u regeneraciji. Deluje protivupalno, revitalizujuće i doprinosi većoj elastičnosti kože. Takođe pospešuje sintezu kolagena i smanjuje izraženost finih linija i bora. Ginseng ima sposobnost da osveži i &#8220;probudi&#8221; umoran ten, dajući koži blistav izgled. Ekstrakt korena kurkume (Curcuma Longa Root Extract) Kurkuma je poznata po svom snažnom antiinflamatornom i antioksidativnom dejstvu. Pomaže u umirivanju kože, ujednačavanju tena i smanjenju hiperpigmentacija. Takođe pomaže u borbi protiv slobodnih radikala, čime se usporava proces starenja i pojava bora. Deluje antibakterijski i idealna je za kožu sklonu aknama i neujednačenostima. U ovoj formuli doprinosi anti-age i osvetljavajućem efektu seruma. Dodaj u listu želja Dodaj u listu želja', 'PURITO Pure Vitamin C Serum kombinuje 5% askorbinske kiseline sa niacinamidom i hijaluronskom kiselinom kako bi posvetlio ten, ujednačio boju kože i poboljšao njenu elastičnost. Ova veganska i bezmirisna formula pruža snažnu antioksidativnu zaštitu, smanjujući vidljivost tamnih mrlja i finih linija.', 'https://beauty-health.rs/wp-content/uploads/2024/12/PURITO-Pure-Vitamin-C-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
