INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1203, 137, 'Purito Dermide Cica Barrier Sleeping Pack', 'purito-dermide-cica-barrier-sleeping-pack', 'Ključne prednosti: Obnavljanje kožne barijere: Ceramidi pomažu u jačanju i obnovi zaštitne barijere kože, sprečavajući gubitak vlage. Dubinska hidratacija: Skvalan i pantenol pružaju intenzivnu hidrataciju, čineći kožu glatkom i elastičnom. Umirujuće dejstvo: Ekstrakt centelle asiatice smiruje iritacije i crvenilo, pogoduje osetljivoj koži. Kome je namenjena? Ova noćna maska je idealna za osobe sa suvom, osetljivom ili iritiranom kožom, kao i za one koji žele da poboljšaju hidrataciju i ojačaju kožnu barijeru. Zašto volimo Purito Dermide Cica Barrier Sleeping Pack? Tokom noći, koža prolazi kroz proces regeneracije, a Dermide Cica Barrier Sleeping Pack pruža optimalne uslove za taj proces. Ceramidi obnavljaju zaštitni sloj kože, dok skvalan i pantenol osiguravaju neophodnu vlagu. Ekstrakt centelle asiatice deluje umirujuće, smanjujući crvenilo i iritacije. Redovnom upotrebom, koža postaje otpornija na spoljašnje faktore, mekša i zdravijeg izgleda. Aktivni sastojci Centella Asiatica Extract Centella Asiatica, poznata i kao &#8220;tiger grass&#8221;, tradicionalno se koristi za ublažavanje rana i regeneraciju kože. Bogata je aktivnim komponentama poput madecassosida, asiaticosida i asiatske kiseline, koje efikasno smanjuju upale i pospešuju sintezu kolagena. Ima snažna umirujuća i antiinflamatorna svojstva, što je čini idealnom za osetljivu, iritiranu i upaljenu kožu. Takođe jača barijeru kože, ubrzava zarastanje i smanjuje crvenilo. U ovoj noćnoj maski pruža intenzivnu regeneraciju dok spavate, ostavljajući kožu smirenom i obnovljenom. Skvalan Skvalan je stabilizovana forma skvalena – prirodnog lipida koji je kompatibilan sa ljudskom kožom i ključan za očuvanje hidratacije. Deluje kao emolijens koji sprečava isparavanje vlage iz kože, ostavljajući je glatkom, mekom i elastičnom. Ima izuzetno blago dejstvo, nekomedogen je i ne izaziva iritacije, što ga čini pogodnim za sve tipove kože, uključujući i osetljivu. Takođe ima antioksidativna svojstva i pomaže u zaštiti kože od slobodnih radikala. U ovoj formuli podržava noćnu regeneraciju i očuvanje optimalne vlažnosti. Ceramide NP Ceramide NP je lipid identičan onima koji se prirodno nalaze u koži, pa je izuzetno kompatibilan i nežan. Njegova osnovna funkcija je jačanje kožne barijere i sprečavanje transepidermalnog gubitka vlage. Deluje kao &#8220;cement&#8221; između ćelija kože, zadržavajući vlagu i štiteći od spoljašnjih iritansa, zagađenja i UV zračenja. Takođe pomaže u obnavljanju suve, oslabljene i narušene kože, vraćajući joj otpornost i zdrav izgled. Dodaj u listu želja Dodaj u listu želja', 'PURITO Dermide Cica Barrier Sleeping Pack je noćna maska koja intenzivno hidrira i obnavlja kožnu barijeru tokom noći, zahvaljujući ključnim sastojcima poput ceramida, pantenola i skvalana. Ovaj proizvod umiruje iritacije i pruža dubinsku hidrataciju, ostavljajući kožu mekom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Purito-Dermide-Cica-Barrier-Sleeping-Pack.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
