INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1205, 137, 'Purito Galacto Niacin 97 Power Essence', 'purito-galacto-niacin-97-power-essence', 'Ključne prednosti: Poboljšava teksturu kože: Redovnom upotrebom, koža postaje glatka i mekana. Ujednačava ten: Smanjuje pojavu tamnih mrlja i diskoloracija, dajući koži zdrav izgled. Kontroliše sebum: Pomaže u regulaciji proizvodnje sebuma, smanjujući masni sjaj. Kome je namenjena? Ova esencija je idealna za sve tipove kože, posebno za one koji žele ujednačen ten i kontrolu sebuma. Takođe je pogodna za osobe sa neujednačenom teksturom kože ili hiperpigmentacijom. Zašto volimo PURITO Galacto Niacin 97 Power Essence? Sa Galacto Niacin 97 Power esencijom, vaša koža postaje blistavija i ujednačenija. Visok sadržaj filtrata fermenta galaktomiceta pruža dubinsku hidrataciju, dok niacinamid smanjuje pojavu tamnih mrlja. Esencija takođe jača barijeru kože, čineći je otpornijom na spoljašnje uticaje. Redovna upotreba rezultira glatkom i osveženom kožom, sa smanjenim porama i kontrolisanim sebumom. Bez veštačkih mirisa i boja, pogodna je i za osetljivu kožu. Aktivni sastojci Galactomyces Ferment Filtrate Galactomyces je fermentisani sastojak bogat nutrijentima kao što su vitamini, minerali, aminokiseline i enzimi koji revitalizuju i obnavljaju kožu. Podstiče prirodnu regeneraciju ćelija, poboljšava teksturu i ton kože, i pomaže u ujednačavanju tena. Takođe pomaže u smanjenju veličine pora, kontroli sebuma i posvetljavanju kože. Deluje antioksidativno, štiteći kožu od slobodnih radikala i štetnih spoljašnjih uticaja. Redovnom upotrebom, koža postaje glatkija, elastičnija i vidno svetlija. Ovaj sastojak čini osnovu formule, pružajući esencijalnu negu za umornu i neujednačenu kožu. Bacillus/Soybean Ferment Extract Bacillus/Soybean Ferment je fermentisani ekstrakt soje koji je bogat peptidima i izoflavonima, poznatim po svojim anti-age i regenerativnim svojstvima. Pomaže u hidrataciji, poboljšava elastičnost i smanjuje vidljivost finih linija. Deluje antioksidativno i umirujuće, pa je pogodan i za osetljivu kožu. Takođe pospešuje sintezu kolagena i obnavlja zaštitnu barijeru kože. U ovoj formuli ima ulogu hranljive baze koja dodatno pojačava učinak fermentisanih sastojaka. Doprinosi mekoj, elastičnoj i osveženoj koži. Niacinamid (Vitamin B3) Niacinamid je višenamenski aktivni sastojak koji osvetljava ten, ujednačava pigmentaciju i jača kožnu barijeru. Deluje protivupalno, smanjuje crvenilo i iritacije, i doprinosi smanjenju hiperpigmentacija i neujednačenog tena. Pomaže i u regulaciji sebuma i poboljšanju elastičnosti kože. Njegova kombinacija sa fermentisanim sastojcima doprinosi zdravijem, blistavijem i stabilnijem tenu. Takođe je izuzetno blag, što ga čini pogodnim i za osetljivu i problematičnu kožu. U ovoj esenciji deluje sinergijski sa ostalim sastojcima za sveobuhvatni efekat osvetljavanja i jačanja kože. Dodaj u listu želja Dodaj u listu želja', 'PURITO Galacto Niacin 97 Power Essence je esencija koja sadrži 92% filtrata fermenta galaktomiceta i 5% niacinamida, pružajući blistav i ujednačen ten.', 'https://beauty-health.rs/wp-content/uploads/2024/12/PURITO-Galacto-Niacin-97-Power-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
