INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1207, 137, 'Purito Wonder Releaf Centella Toner Unscented', 'purito-wonder-releaf-centella-toner-unscented', 'Ključne prednosti: Umiruje iritacije: Visok sadržaj Centella Asiatica ekstrakta smanjuje crvenilo i upale, pružajući osećaj olakšanja. Hidrira kožu: Sodium Hyaluronat i šantenol obezbeđuju dubinsku hidrataciju, ostavljajući kožu mekom i elastičnom. Jača kožnu barijeru: Aktivni sastojci poput Madecassoside-a doprinose obnovi i jačanju zaštitne barijere kože. Kome je namenjen? Ovaj tonik je idealan za osobe sa osetljivom kožom sklonom crvenilu i iritacijama, kao i za one koji traže proizvod bez mirisa i esencijalnih ulja. Pogodan je za sve tipove kože, uključujući masnu i kombinovanu. Zašto volimo PURITO Wonder Releaf Centella Toner Unscented? Korišćenjem ovog tonika, koža postaje vidno smirenija i ujednačenija. Redovna upotreba doprinosi smanjenju crvenila i jačanju kožne barijere, čineći kožu otpornijom na spoljašnje iritacije. Hidratantni sastojci obezbeđuju dugotrajnu vlažnost, sprečavajući isušivanje i perutanje. Tonik se lako apsorbuje, ostavljajući kožu osveženom bez osećaja lepljivosti. Bez prisustva mirisa i esencijalnih ulja, minimizuje rizik od alergijskih reakcija, pružajući sigurnu negu za najosetljiviju kožu. Aktivni sastojci Centella Asiatica Extract Centella Asiatica, poznata i kao “tigrova trava”, cenjena je zbog svojih snažnih umirujućih, regenerativnih i antiinflamatornih svojstava. Bogata aktivnim komponentama kao što su madecassoside, asiaticoside i asiatic acid, ova biljka pomaže u smanjenju crvenila, ubrzava zarastanje kože i jača zaštitnu barijeru. Takođe stimuliše sintezu kolagena, što doprinosi elastičnosti i oporavku kože oštećene upalama ili spoljnim stresorima. Sodium Hyaluronate (natrijum hijaluronat) Sodium Hyaluronate je stabilan i niskomolekularni oblik hijaluronske kiseline koji prodire dublje u kožu, pružajući intenzivnu i dugotrajnu hidrataciju. Pomaže u održavanju optimalnog nivoa vlažnosti, povećava elastičnost kože i smanjuje vidljivost finih linija. Takođe poboljšava glatkoću kože i čini je mekšom na dodir. Panthenol (Provitamin B5) Panthenol je hidratantni, umirujući i regenerativni sastojak koji pomaže u obnovi kože i očuvanju njene zaštitne funkcije. Veže vlagu i sprečava transepidermalni gubitak vode, ostavljajući kožu elastičnijom i otpornijom na spoljne uticaje. Deluje antiinflamatorno i idealan je za smanjenje crvenila, iritacija i osećaja zategnutosti. Dodaj u listu želja Dodaj u listu želja', 'PURITO Wonder Releaf Centella Toner Unscented je nežni tonik formulisan sa 10% ekstrakta Centella Asiatica, namenjen umirivanju iritacija i jačanju kožne barijere. Bez mirisa i esencijalnih ulja, idealan je za osetljivu kožu sklonu crvenilu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/PURITO-Wonder-Releaf-Centella-Toner-Unscented.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
