INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1209, 137, 'Purito From Green Avocado Cleansing Balm', 'purito-from-green-avocado-cleansing-balm', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja šminku, SPF i nečistoće, ostavljajući kožu čistom i osveženom. Hidratacija i ishrana: Ulje avokada i ekstrakti zelenog povrća pružaju intenzivnu hidrataciju i hrane kožu, poboljšavajući njenu elastičnost. Pogodno za osetljivu kožu: Bez mirisa i esencijalnih ulja, ovaj balzam je idealan za osetljivu kožu sklonu iritacijama. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože, posebno za one sa suvom ili osetljivom kožom koja zahteva nežno, ali efikasno čišćenje bez iritacija. Zašto volimo PURITO From Green Avocado Cleansing Balm? Sa From Green Avocado Cleansing Balm-om, svakodnevno čišćenje lica postaje prijatno iskustvo koje neguje vašu kožu. Balzam se lako topi na koži, pretvarajući se u svilenkasto ulje koje efikasno rastvara čak i vodootpornu šminku i SPF. Ulje avokada, bogato vitaminima A, E i D, dubinski hrani kožu. Ekstrakti kelja, spanaća i brokolija pružaju antioksidativnu zaštitu, čineći kožu blistavom i zdravom. Redovnom upotrebom, kožna barijera postaje jača, smanjujući osetljivost i crvenilo. Bez mirisa i esencijalnih ulja, ovaj balzam je savršen za one sa osetljivom kožom koja reaguje na jake sastojke. Aktivni sastojci Ulje avokada (Avocado Oil) Ulje avokada bogato je esencijalnim masnim kiselinama, vitaminima A, D i E, te snažno hidrira i neguje kožu dok uklanja nečistoće. Zahvaljujući svom bogatom sastavu, prodire duboko u kožu, omekšava je i obnavlja lipidnu barijeru. Ima umirujuća i antioksidativna svojstva, što ga čini idealnim za suvu, osetljivu i dehidriranu kožu. U ovom balzamu, avokado ulje pomaže da se šminka i SPF temeljno uklone bez isušivanja. Zeleni biljni kompleks (kelj, spanać, pelin, kupus i brokoli) Ekstrakti zelenog povrća bogati su antioksidansima, vitaminima C i K, kao i hlorofilom, koji osvežavaju, štite i revitalizuju kožu. Kelj i spanać deluju protivupalno i umirujuće, dok pelin (mugwort) ima izražena antibakterijska i regenerativna svojstva. Kupus i brokoli sadrže fitonutrijente koji pomažu u detoksikaciji i održavanju zdrave barijere kože. Ovaj biljni kompleks pruža nežnu podršku tokom čišćenja, dodatno umirujući kožu. Ulje semena lubenice (Watermelon Seed Oil) Ulje semena lubenice je lagano, brzo upijajuće ulje koje sadrži visok procenat linolne kiseline, pogodnu za balansiranje masne i mešovite kože. Doprinosi hidrataciji bez zapušavanja pora, a bogato je i antioksidansima koji štite kožu od spoljašnjih uticaja. Takođe ima svojstva umirivanja i obnavljanja, čineći ga pogodnim za osetljivu i aknama sklonu kožu. Ulje semena baobaba (Baobab Seed Oil) Baobab ulje je bogato omega-3, -6 i -9 masnim kiselinama, kao i vitaminima A, D, E i F, što ga čini izuzetno hranljivim i zaštitnim za kožu. Dubinski hidrira, poboljšava elastičnost i pomaže u regeneraciji suve i oštećene kože. Deluje umirujuće i antiinflamatorno, što je korisno kod crvenila i iritacija. Dodaj u listu želja Dodaj u listu želja', 'PURITO From Green Avocado Cleansing Balm je veganski, hranljivi balzam za čišćenje lica koji efikasno uklanja šminku, SPF i nečistoće, istovremeno hidrirajući kožu zahvaljujući ulju avokada i kompleksu zelenih biljaka.', 'https://beauty-health.rs/wp-content/uploads/2024/12/PURITO-From-Green-Avocado-Cleansing-Balm-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
