INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1215, 126, 'Numbuzin No.2 Goodbye Redness Derma Tone Up SPF50+', 'numbuzin-no-2-goodbye-redness-derma-tone-up', 'Ključne prednosti: Smanjuje crvenilo: Zeleni pigment neutralizuje crvenilo i ujednačava ten kože. Zaštita od UV zraka: SPF50+ PA+++ osigurava visoku zaštitu od štetnih UVA i UVB zraka. Umiruje iritacije: Umirujući biljni ekstrakti pomažu u smanjenju upala i crvenila. Kome je namenjena? Ova krema je idealna za osobe sa osetljivom kožom sklonom crvenilu, iritacijama ili rosacei. Pogodna je za sve tipove kože, uključujući i masnu ili kombinovanu kožu, zahvaljujući svojoj laganoj i nemasnoj formuli. Zašto volimo Numbuzin No.2 Goodbye Redness Derma Tone Up? No.2 Goodbye Redness Derma Tone Up pruža savršenu kombinaciju nege i prekrivanja. Njegova lagana formula brzo se upija, ostavljajući kožu glatkom i osveženom. Zeleni pigment trenutno prekriva crvenilo, dok biljni ekstrakti aktivno smiruju iritacije. Zaštita od sunca sa SPF50+ PA+++ štiti kožu od oštećenja izazvanih UV zracima, sprečavajući prevremeno starenje. Redovnom upotrebom, koža postaje otpornija na spoljašnje stresore i prirodno blistavija. Ton kože je ujednačen, a koža izgleda zdravije i negovanije. Aktivni sastojci UV filteri (hemijski i/ili fizički SPF50+ PA+++) Ova tone-up krema sadrži snažne UV filtere koji obezbeđuju širokospektralnu zaštitu od UVA i UVB zračenja, sprečavajući fotostarenje i oštećenje kože. SPF50+ PA+++ označava visok nivo zaštite koji je idealan za svakodnevnu upotrebu, naročito kod osoba sa osetljivom ili reaktivnom kožom. UV filteri štite ćelije kože od oksidativnog stresa, upalnih procesa i gubitka kolagena. Time se smanjuje rizik od pigmentacija, crvenila i prevremenog starenja kože. Niacinamid (Vitamin B3) Niacinamid je poznat po svom višestrukom dejstvu na posvetljivanje kože, ujednačavanje tena i smanjenje crvenila. Doprinosi umanjenju hiperpigmentacija i postupalnih mrlja, dok istovremeno poboljšava elastičnost i hidrataciju kože. Njegovo antiinflamatorno dejstvo pomaže kod rozacee i kože sklone aknama. Pomaže u jačanju kožne barijere i čini kožu otpornijom na spoljašnje uticaje. U kombinaciji sa UV zaštitom, niacinamid dodatno poboljšava celokupno stanje kože i njen sjaj. Tone-up pigmenti Tone-up pigmenti u ovoj formuli pomažu u trenutnom vizuelnom smanjenju crvenila i nepravilnosti na koži. Deluju reflektujuće i korektivno, pružajući koži svetliji, ujednačen ton bez potrebe za dodatnim slojem šminke. Formulisani su da se prirodno stope sa tonom kože, ne ostavljajući beli trag. Osim estetskog efekta, doprinose boljoj pripremi kože za šminku i produžavaju postojanost podloge. Pogodni su za sve tipove kože, a posebno korisni za crvenilo i neujednačen ten. U ovoj SPF kremi omogućavaju kombinaciju zaštite i estetskog poboljšanja. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.2 Goodbye Redness Derma Tone Up SPF50+ PA+++ je višenamenska krema koja istovremeno smiruje crvenilo, štiti od štetnih UV zraka i ujednačava ton kože. Formulisan sa umirujućim biljnim ekstraktima i zelenim pigmentom, pruža prirodan izgled i zdraviji ten.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Numbuzin-No.2-Goodbye-Redness-Derma-Tone-Up.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
