INSERT INTO inventory (id, product_variant_id, store_location_id, quantity, created_at, updated_at) VALUES (3648, 1216, 3, 12, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1217, 126, 'Numbuzin No.3 Super Glowing Essence Toner', 'numbuzin-no-3-super-glowing-essence-toner', 'Ključne prednosti: Povećava sjaj kože: Fermentisani sastojci poboljšavaju elastičnost i blistavost kože. Smanjuje pore i proizvodnju sebuma: Klinički dokazano smanjuje veličinu pora i reguliše lučenje sebuma. Duboka hidratacija: Pruža intenzivnu hidrataciju, ostavljajući kožu glatkom i osveženom. Kome je namenjen? Ovaj toner je idealan za osobe sa umornom, beživotnom kožom koja je izgubila elastičnost i sjaj. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo Numbuzin No.3 Super Glowing Essence Toner? Uz pomoć No.3 Super Glowing Essence Tonera, vaša koža postaje vidljivo blistavija i elastičnija. Fermentisani sastojci prodiru duboko u kožu, pružajući esencijalne vitamine i minerale koji revitalizuju ten. Redovnom upotrebom, tonus kože se ujednačava, dok se fine linije i bore smanjuju. Hidratantna svojstva ovog tonera osiguravaju da koža ostane meka i glatka tokom celog dana. Pored toga, smanjuje se pojava pora, ostavljajući kožu besprekorno čistom i osveženom. Aktivni sastojci Fermentisani kompleks (50 fermentisanih sastojaka) Fermentisani sastojci su bogati enzimima, amino kiselinama, vitaminima i antioksidansima koji intenzivno hrane, obnavljaju i revitalizuju kožu. Fermentacija povećava bioraspoloživost aktivnih jedinjenja, omogućavajući dublju apsorpciju i bolju efikasnost sastojaka. Ovaj kompleks poboljšava elastičnost, osvetljava ten i pospešuje prirodni sjaj kože. Takođe pomaže u smanjenju veličine pora, regulaciji sebuma i ujednačavanju teksture kože. Galactomyces Ferment Filtrate Galactomyces je jedan od najpoznatijih fermentisanih sastojaka, bogat nutrijentima koji revitalizuju kožu, podstiču obnovu ćelija i ujednačavaju ten. Efikasno smanjuje vidljivost pora i daje koži ujednačen, prozračan izgled. Ima hidratantna i antioksidativna svojstva koja pomažu u zaštiti kože od spoljašnjih štetnih faktora. Bifida Ferment Lysate Bifida Ferment Lysate je probiotik koji pomaže u obnavljanju i jačanju kožne barijere, štiteći kožu od svakodnevnog stresa i iritacija. Ima sposobnost da smanji osetljivost kože i ublaži znake starenja izazvane UV zračenjem i zagađenjem. Takođe pomaže u održavanju vlažnosti i poboljšava glatkoću kože. Njegovo antioksidativno delovanje doprinosi jačanju prirodnih obrambenih mehanizama kože. Lactobacillus Ferment Lactobacillus ferment je još jedan probiotski derivat koji ima umirujuće, balansirajuće i zaštitne efekte na mikrobiom kože. Pomaže u obnavljanju narušene barijere i smanjenju reaktivnosti kože, naročito kod crvenila i upala. Ima blago hidratantno i omekšavajuće dejstvo koje doprinosi poboljšanju teksture kože. Takođe jača sposobnost kože da se zaštiti od zagađenja i oksidativnog stresa. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.3 Super Glowing Essence Toner je formulisan sa 50 vrsta fermentisanih sastojaka, uključujući niacinamid, kako bi posvetlio i učvrstio umornu kožu, pružajući duboku hidrataciju i hranljive benefite esencije.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Numbuzin-No.3-Super-Glowing-Essence-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
