INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1224, 124, 'Nine Less A-Control Azelaic Acid Cream', 'nine-less-a-control-azelaic-acid-cream', 'Ključne prednosti: Smanjenje upala i akni: Azelaična kiselina deluje antibakterijski, pomažući u smanjenju upalnih procesa i sprečavanju nastanka novih akni. Poboljšanje teksture kože: Laktična kiselina blago eksfolira kožu, uklanjajući mrtve ćelije i ostavljajući je glatkom i osveženom. Hidratacija i regeneracija: Pantenol i filtrat puževe sluzi pružaju dubinsku hidrataciju i podstiču regeneraciju kože, povećavajući njenu elastičnost. Kome je namenjena? Ovaj tonik je idealan za osobe sa masnom i aknama sklonom kožom, kao i za one koji žele ujednačen ten i smanjenje hiperpigmentacija. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo NINE LESS A-Control Azelaic Acid Cream? A-Control Azelaic Acid Cream pruža koži neophodnu negu kroz pažljivo odabranu kombinaciju aktivnih sastojaka. Azelaična kiselina efikasno smanjuje upale, dok pantenol umiruje i hidrira kožu. Filtrat puževe sluzi podstiče regeneraciju ćelija, smanjujući ožiljke i ujednačavajući ton. Laktična kiselina uklanja mrtve ćelije kože, otkrivajući blistav i gladak ten. Ova krema istovremeno pruža dugotrajnu hidrataciju i smanjuje pojavu nepravilnosti, dok štiti kožu od spoljašnjih faktora. Redovna upotreba donosi glatkiju, čistiju i zdraviju kožu. Aktivni sastojci Azelainska kiselina Azelainska kiselina je višefunkcionalni sastojak poznat po svojim antibakterijskim, protivupalnim i komedolitičkim svojstvima. Efikasno smanjuje broj akni i mitisera, delujući direktno na Propionibacterium acnes, bakteriju odgovornu za nastanak akni. Istovremeno ublažava crvenilo i iritacije, što je čini pogodnom za osobe sa rozaceom i osetljivom kožom. Azelainska kiselina takođe inhibira proizvodnju melanina, čime doprinosi ujednačenju tena i smanjenju postupalnih hiperpigmentacija. Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Ekstrakt zelenog čaja bogat je polifenolima, naročito epigalokatehin galatom (EGCG), koji imaju snažno antioksidativno i protivupalno dejstvo. Deluje umirujuće na kožu, smanjuje crvenilo i iritacije, a pritom pomaže u regulaciji lučenja sebuma. Njegova antibakterijska svojstva čine ga efikasnim u tretmanu akni i nečiste kože. Takođe štiti ćelije kože od oštećenja izazvanih UV zračenjem i drugim spoljnim faktorima. Mlečna kiselina (Lactic Acid) Mlečna kiselina spada u AHA kiseline i poznata je po svojim eksfolijativnim i hidratantnim svojstvima. Blago uklanja mrtve ćelije kože, pospešuje regeneraciju i poboljšava teksturu kože. Njena molekularna struktura omogućava dubinsko delovanje uz zadržavanje vlažnosti u koži. Mlečna kiselina stimuliše sintezu ceramida, što dodatno jača kožnu barijeru. Redovnom upotrebom doprinosi ujednačenijem tonu kože, smanjenju fleka i finih linija. Dodaj u listu želja Dodaj u listu želja', 'NINE LESS A-Control Azelaic Acid Cream je lagana krema formulisana sa 10.000 ppm azelaične kiseline, pantenolom i filtratom puževe sluzi, pružajući efikasno rešenje za kožu sklonu aknama, smanjujući upale i poboljšavajući teksturu kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/NINE-LESS-A-Control-Azelaic-Acid-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
