INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1226, 124, 'Nine Less A-Control Azelaic Acid Toner', 'nine-less-a-control-azelaic-acid-toner', 'Ključne prednosti: Smanjenje upala i akni: Azelaična kiselina deluje antibakterijski i protivupalno, pomažući u smanjenju crvenila i sprečavanju nastanka novih akni. Ujednačavanje tena: Niacinamid posvetljuje kožu i smanjuje pojavu tamnih mrlja, pružajući ujednačen ten. Hidratacija i umirenje kože: Ekstrakt lista čajevca umiruje iritacije i pruža neophodnu hidrataciju, ostavljajući kožu osveženom. Kome je namenjen? Ovaj tonik je idealan za osobe sa masnom i aknama sklonom kožom, kao i za one koji žele ujednačen ten i smanjenje hiperpigmentacija. Pogodan je za sve tipove kože, uključujući osetljivu. Zašto volimo NINE LESS A-Control Azelaic Acid Toner? Upotrebom A-Control Azelaic Acid Tonera, vaša koža postaje čistija i blistavija. Azelaična kiselina efikasno smanjuje upale i crvenilo, dok niacinamid posvetljuje tamne mrlje i ujednačava ten. Ekstrakt lista čajevca umiruje iritacije i pruža hidrataciju, ostavljajući kožu osveženom i revitalizovanom. Redovnom upotrebom, tekstura kože se poboljšava, pore postaju manje vidljive, a koža izgleda zdravije i sjajnije. Aktivni sastojci AHA (7.5%) AHA (alfa-hidroksi kiseline), kao što su glikolna i mlečna kiselina, deluju površinski, nežno uklanjajući mrtve ćelije kože i podstičući regeneraciju. Ova koncentracija od 7.5% pruža efikasnu eksfolijaciju bez preteranog iritiranja kože. Redovnom upotrebom posvetljuju ten i ujednačavaju ton kože, čineći je glatkijom i blistavijom. Takođe poboljšavaju apsorpciju drugih aktivnih sastojaka. Niacinamid (3%) Niacinamid, ili vitamin B3, poznat je po širokom spektru blagotvornih efekata za kožu, uključujući poboljšanje teksture i tona. U koncentraciji od 3% efikasno umanjuje vidljivost proširenih pora i nežno posvetljuje hiperpigmentacije. Deluje protivupalno, pa je odličan za kožu sklonu aknama i crvenilu. Takođe jača kožnu barijeru i poboljšava hidrataciju. Filtrat sekreta puža (0.01%) U maloj, ali ciljanoj koncentraciji, filtrat sekreta puža pruža umirujuće i regenerativno dejstvo na osetljivu i iritiranu kožu. Sadrži komponente poput alantoina, glikolne kiseline i enzima koji podstiču obnovu ćelija. Ovaj sastojak pomaže u zaceljivanju mikrooštećenja i ublažavanju upalnih procesa. Takođe doprinosi zadržavanju vlage, čime poboljšava elastičnost kože. Azelainska kiselina (0.5%) U koncentraciji od 0.5%, azelainska kiselina blago, ali efikasno deluje na postupalne fleke i neujednačen ten. Ima antibakterijsko i protivupalno dejstvo koje je korisno za kožu sklonu aknama i crvenilu. Ova kiselina inhibira sintezu melanina, čime pomaže u osvetljavanju tamnih mrlja i ujednačavanju tena. Pored toga, ima blagi keratolitički efekat koji doprinosi glatkijoj teksturi kože. Dodaj u listu želja Dodaj u listu želja', 'NINE LESS A-Control Azelaic Acid Toner je višenamenski tonik koji kombinuje azelaičnu kiselinu, niacinamid i ekstrakt lista čajevca kako bi smanjio upale, ujednačio ten i pružio blistav izgled kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/NINE-LESS-A-Control-Azelaic-Acid-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
