INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1228, 122, 'Needly Daily Toner Pad', 'needly-daily-toner-pad', 'Ključne prednosti: Blaga eksfolijacija: BHA i PHA kiseline uklanjaju mrtve ćelije kože, poboljšavajući teksturu i tonus. Intenzivna hidratacija: Hijaluronska kiselina zadržava vlagu, ostavljajući kožu mekom i elastičnom. Umirujuće dejstvo: Ekstrakt artemisije princeps lista smanjuje crvenilo i iritacije, pogoduje osetljivoj koži. Kome su namenjeni? Idealan za masnu i kombinovanu kožu sklonu nepravilnostima, kao i za one koji žele blagu eksfolijaciju i hidrataciju bez iritacija. Zašto volimo Needly Daily Toner Pad? Uz Daily Toner Pad, svakodnevna nega postaje jednostavna i efikasna. Svaki jastučić je natopljen esencijom koja uklanja nečistoće i višak sebuma, dok istovremeno hidrira kožu. Redovnom upotrebom, pore postaju manje vidljive, a ten ujednačeniji. Blaga formula omogućava svakodnevnu upotrebu bez rizika od iritacija, čak i za osetljivu kožu. Praktičan dizajn jastučića olakšava upotrebu kod kuće ili na putu, pružajući svežinu i čistoću u svakom trenutku. Aktivni sastojci BHA (salicilna kiselina) Prodire duboko u pore, uklanja višak sebuma i mrtve ćelije, sprečavajući nastanak akni i mitesera. Ima antiinflamatorna svojstva koja smanjuju crvenilo i upale, poboljšavajući ukupni izgled kože. PHA (glukonolakton) Blaga eksfolijaciona kiselina koja uklanja površinske mrtve ćelije, poboljšava teksturu kože i ujednačava ten. Zbog veće molekulske mase, deluje površinski, smanjujući rizik od iritacija, što je čini pogodnom za osetljivu kožu. Hijaluronska kiselina Prirodni humektant koji privlači i zadržava vlagu u koži, pružajući dubinsku hidrataciju. Održava kožu elastičnom i glatkom, smanjujući pojavu finih linija i bora. Ekstrakt artemisije princeps lista Poznat po umirujućim i antiinflamatornim svojstvima, pomaže u smirivanju iritacija i crvenila. Bogat antioksidansima, štiti kožu od štetnih spoljašnjih faktora. Dodaj u listu želja Dodaj u listu želja', 'Needly Daily Toner Pad je svakodnevni tonik u obliku jastučića koji kombinuje BHA i PHA kiseline za blago eksfoliranje, dok hijaluronska kiselina i ekstrakt artemisije princeps lista pružaju dubinsku hidrataciju i umiruju kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Needly-Daily-Toner-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
