INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1229, 122, 'Needly Mild Cleansing Pad', 'needly-mild-cleansing-pad', 'Ključne prednosti: Efikasno uklanjanje nečistoća: Uklanja šminku, zaštitni faktor i nečistoće bez iritacije, ostavljajući kožu čistom i osveženom. Dubinska hidratacija: Pantenol i skvalan obezbeđuju intenzivnu hidrataciju, održavajući kožu mekom i glatkom. Umirujuće dejstvo: Alantoin smiruje iritacije, čineći proizvod pogodnim za osetljivu kožu. Kome su namenjeni? Ovi jastučići su idealni za sve tipove kože, uključujući osetljivu. Posebno za one koji traže efikasno uklanjanje šminke uz očuvanje hidratacije i smanjenje iritacija. Zašto volimo Needly Mild Cleansing Pad? Uz Mild Cleansing Pad, svakodnevno čišćenje postaje prijatno iskustvo. Njegova jedinstvena formula efikasno uklanja nečistoće, dok aktivni sastojci poput pantenola i skvalana pružaju neophodnu hidrataciju. Alantoin dodatno umiruje kožu, smanjujući crvenilo i iritacije. Redovnom upotrebom, koža postaje mekša, glatkija i zdravijeg izgleda. Ovi jastučići su dizajnirani da očiste kožu bez narušavanja njene prirodne barijere. Ovo ih čini savršenim izborom za one sa osetljivom kožom. Aktivni sastojci Pantenol Poznat i kao provitamin B5, pantenol deluje kao humektant, privlačeći vlagu u kožu. Pomaže u održavanju optimalnog nivoa hidratacije, što rezultira mekšom i elastičnijom kožom. Takođe ima umirujuća svojstva, smanjujući crvenilo i iritacije, što ga čini idealnim za osetljivu kožu. Alantoin Prirodni ekstrakt koji pospešuje regeneraciju ćelija kože. Deluje umirujuće, smanjujući upale i iritacije. Pomaže u omekšavanju kože i poboljšava njenu teksturu, ostavljajući je glatkom i zdravom. Skvalan Prirodni emolijens koji oponaša lipide prisutne u ljudskoj koži. Pruža dubinsku hidrataciju bez začepljenja pora. Ima antioksidativna svojstva koja štite kožu od slobodnih radikala i pomaže u održavanju njene elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Needly Mild Cleansing Pad je nežni, ali efikasni proizvod za uklanjanje šminke i zaštitnog faktora, koji istovremeno neguje kožnu barijeru. Obogaćen pantenolom, alantoinom i skvalanom, pruža dubinsku hidrataciju i umiruje kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Needly-Mild-Cleansing-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
