INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1232, 119, 'Mixsoon Centella Asiatica Toner', 'mixsoon-centella-asiatica-toner', 'Ključne prednosti: Intenzivna hidratacija: Pomaže koži da zadrži vlagu, poboljšavajući njenu elastičnost i mekoću. Umirujuće dejstvo: Smanjuje upale i crvenilo, pružajući olakšanje osetljivoj i iritiranoj koži. Obnavljanje kože: Podstiče regeneraciju ćelija, pomažući u zaceljivanju ožiljaka i manjih oštećenja. Kome je namenjen? Idealan za osobe sa osetljivom, suvom ili iritiranom kožom sklonom crvenilu i upalama. Pogodan za sve tipove kože koji traže dodatnu hidrataciju i umirenje. Zašto volimo Mixsoon Centella Asiatica Toner? Korišćenjem ovog tonika, koža postaje vidno hidrirana i osvežena. Redovna upotreba doprinosi smanjenju crvenila i iritacija, čineći ten ujednačenijim. Aktivni sastojci podstiču prirodnu regeneraciju kože, što rezultira glatkijom i zdravijom površinom. Tonik takođe jača barijeru kože, štiteći je od spoljašnjih agresora. Njegova lagana formula brzo se upija, ostavljajući kožu mekom i bez osećaja lepljivosti. Bez alkohola i veštačkih mirisa, ovaj proizvod je pogodan i za najosetljivije tipove kože. Aktivni sastojci Centella Asiatica ekstrakt (100%) Ovaj toner sadrži 100% čisti ekstrakt Centella Asiatica (Cica), poznat po svojim izuzetno umirujućim, obnavljajućim i protivupalnim svojstvima. Deluje efikasno na smanjenje crvenila, iritacija i inflamacije, što ga čini idealnim za osetljivu, reaktivnu i problematičnu kožu. Aktivne komponente – madecassoside, asiaticoside, asiatic acid i madecassic acid – podstiču sintezu kolagena, ubrzavaju zarastanje kože i jačaju njenu prirodnu barijeru. Zahvaljujući blagom, ali moćnom delovanju, ovaj sastojak uravnotežuje kožu, poboljšava otpornost na spoljne agresore i umanjuje znake stresa. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Centella Asiatica Toner je umirujući tonik koji koristi 100% ekstrakt biljke Centella Asiatica za hidrataciju i obnavljanje osetljive kože, smanjujući crvenilo i iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Mixsoon-Centella-Asiatica-Toner-je-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
