INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1233, 119, 'Mixsoon Centella Face Mask', 'mixsoon-centella-face-mask', 'Ključne prednosti: Intenzivna hidratacija: Dubinski vlaži kožu, poboljšavajući njenu elastičnost i mekoću. Umirujuće dejstvo: Smanjuje crvenilo i iritacije, pružajući osećaj olakšanja za osetljivu kožu. Obnavljanje barijere: Jača prirodnu barijeru kože, štiteći je od spoljašnjih štetnih faktora. Kome je namenjena? Ova maska je idealna za osobe sa osetljivom, suvom ili iritiranom kožom, kao i za one koji se suočavaju sa crvenilom ili upalama. Takođe je pogodna za sve tipove kože koji žele poboljšati hidrataciju i smiriti kožu. Zašto volimo Mixsoon Centella Face Mask? Redovna upotreba Centella Face maske pruža koži neophodnu vlagu, čineći je glatkom i osveženom. Ekstrakt Centella Asiatica deluje umirujuće, smanjujući crvenilo i iritacije koje mogu nastati usled spoljašnjih faktora. Ova maska pomaže u jačanju zaštitne barijere kože, čineći je otpornijom na svakodnevne stresore. Lagana tekstura maske omogućava brzo upijanje, ostavljajući kožu mekom bez osećaja lepljivosti. Pogodna je za upotrebu pre posebnih prilika ili kao deo redovne nege, pružajući trenutni osećaj osveženja i revitalizacije. Uz redovnu upotrebu, koža postaje blistavija i zdravijeg izgleda. Aktivni sastojci Centella Asiatica ekstrakt (200,000 ppm) Ekstrakt biljke Centella Asiatica, poznate i kao Cica, izuzetno je cenjen u dermokozmetici zbog svojih umirujućih, obnavljajućih i protivupalnih svojstava. U visokoj koncentraciji od 200,000 ppm, efikasno smanjuje crvenilo, iritacije i stres kože izazvan spoljnom sredinom ili upalnim procesima. Njene glavne aktivne komponente – madecassoside, asiaticoside i asiatic acid – podstiču sintezu kolagena, ubrzavaju zarastanje i jačaju prirodnu barijeru kože. Cica deluje i kao snažan antioksidans, štiteći ćelije kože od oksidativnog stresa i usporavajući vidljive znake starenja. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Centella Face Mask je hidratantna maska obogaćena ekstraktom Centella Asiatica, poznatom po umirujućim i regenerativnim svojstvima, koja pomaže u smirivanju iritacija i dubinskoj hidrataciji kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Mixsoon-Centella-Mask-Pack.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
