INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1239, 118, 'Missha Airy Fit Sheet Mask Rice', 'missha-airy-fit-sheet-mask-rice', 'Ključne prednosti: Intenzivna hidratacija: Ekstrakt pirinča pruža dubinsku vlagu, ostavljajući kožu osveženom i elastičnom. Posvetljujući efekat: Pomaže u ujednačavanju tena i smanjenju tamnih mrlja, dajući koži zdrav sjaj. Poboljšanje teksture kože: Redovnom upotrebom, koža postaje glatkija i mekša na dodir. Kome je namenjena? Ova maska je idealna za osobe sa suvom i umornom kožom koja je izgubila sjaj. Takođe je pogodna za sve tipove kože koji žele poboljšati hidrataciju i ujednačiti ten. Zašto volimo Missha Airy Fit Sheet Mask Aloe? Airy Fit Sheet Mask Rice koristi prirodnu moć ekstrakta pirinča da revitalizuje kožu. Ovaj sastojak je poznat po svojim hidratantnim i posvetljujućim svojstvima, pomažući koži da povrati svoju prirodnu blistavost. Ultra-tanka maska omogućava da aktivni sastojci efikasno prodru u kožu, pružajući trenutne rezultate. Nakon upotrebe, koža je vidno mekša, glatkija i osvežena. Redovna primena ove maske može doprineti dugoročnom poboljšanju teksture i tona kože, čineći je otpornijom na spoljašnje agresore. Aktivni sastojci Ekstrakt pirinča (Rice Extract) Ekstrakt pirinča bogat je vitaminima, mineralima i amino kiselinama koje pomažu u hidrataciji, posvetljavanju i ujednačavanju tena. Deluje kao prirodni osvetljivač kože, pomažući u smanjenju tamnih fleka i beživotnog tena. Takođe sadrži feruličnu kiselinu i orizanol – moćne antioksidanse koji štite kožu od slobodnih radikala i preranog starenja. Pirinčana voda je poznata po sposobnosti da poboljša elastičnost kože i podstakne prirodan sjaj. Njegova blaga i umirujuća svojstva čine ga pogodnim i za osetljivu kožu. Koža nakon upotrebe postaje meka, osvetljena i osvežena. Dodaj u listu želja Dodaj u listu želja', 'Missha Airy Fit Sheet Mask Rice je ultra-tanka maska obogaćena ekstraktom pirinča, koja hidrira i posvetljuje kožu, čineći je mekom i blistavom. Napravljena od celuloznih vlakana, maska savršeno prianja uz lice, omogućavajući optimalnu apsorpciju aktivnih sastojaka.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Missha-Airy-Fit-Sheet-Mask-Rice.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
