INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1243, 113, 'Medi-Peel Premium Collagen Naite Thread Neck Cream 2.0', 'medi-peel-premium-collagen-naite-thread-neck-cream-2-0', 'Ključne prednosti: Dubinska hidratacija i učvršćivanje: Hijaluronska kiselina i kolagen dubinski vlaže i učvršćuju kožu, čineći je glatkom i revitalizovanom. Podrška elastičnosti kože: Peptidi podstiču sintezu kolagena i elastina, poboljšavajući čvrstoću kože i smanjujući znakove starenja. Precizno ciljano dejstvo na bore: Specijalno formulisan za delikatnu kožu vrata, krema pomaže u smanjenju finih linija i poboljšava konture. Kome je namenjena? Ovaj proizvod je idealan za osobe sa suvom i zrelom kožom, kao i za one koji žele smanjiti vidljivost bora i poboljšati elastičnost kože vrata i dekoltea. Preporučuje se korisnicima starijim od 30 godina ili onima koji primećuju prve znakove starenja na koži vrata. Zašto volimo Medi-Peel Premium Collagen Naite Thread Neck Cream 2.0? Krema pruža sveobuhvatnu negu za delikatnu regiju vrata, ciljajući specifične probleme poput gubitka elastičnosti, bora i suvoće. Njena formula bogata kolagenom pomaže u obnavljanju strukture kože, dok peptidi stimulišu proizvodnju elastina za zategnutiji i mlađi izgled. Proizvod koristi inovativnu tehnologiju vlakana za lifting, koja vizuelno redefiniše konture vrata. Redovnom upotrebom, koža postaje glatkija, hidrirana i ujednačenog tona, dok su linije i bore vidno smanjene. Lagana i kremasta tekstura brzo se upija, ostavljajući osećaj svežine bez lepljivosti. Aktivni sastojci Niskomolekularni kolagen (97,500 ppm) Niskomolekularni kolagen s lakoćom prodire u dublje slojeve kože, gde deluje na obnavljanje čvrstoće i elastičnosti. Njegova uloga je da popuni praznine u dermalnoj strukturi, čime se umanjuje pojava bora i opuštene kože, posebno u osetljivom području vrata. Kolagen pomaže u zadržavanju vlage, čineći kožu glatkom i punijom na dodir. Takođe podstiče sintezu prirodnog kolagena, što dugoročno doprinosi regeneraciji i otpornosti kože. Adenozin Adenozin je funkcionalni sastojak sa dokazanim anti-age efektom, posebno efikasan u tretiranju finih linija i bora. Doprinosi povećanju sinteze kolagena i elastina, čime se poboljšava tonus i čvrstina kože vrata. Takođe deluje umirujuće i protivupalno, čineći ga pogodnim i za osetljivu kožu. Pomaže u ujednačavanju teksture kože i vraća joj glatkoću i elastičnost. Peptidi (uključujući Palmitoylphen Peptide-5) Peptidi su signalne molekule koje stimulišu obnavljanje ćelija i sintezu strukturnih proteina poput kolagena i elastina. Palmitoylphen Peptide-5, kao deo patentiranog peptidnog kompleksa, deluje ciljano na opuštenu kožu vrata, poboljšavajući čvrstinu i smanjujući vidljivost dubokih linija. Peptidi takođe jačaju kožnu barijeru i povećavaju otpornost na spoljašnje faktore. Njihovo delovanje je blago, ali kontinuirano, sa kumulativnim efektom u nezi kože. U sinergiji sa kolagenom i adenosinom, peptidi značajno doprinose anti-age učinku. Dodaj u listu želja Dodaj u listu želja', 'Medi-Peel Premium Collagen Naite Thread Neck Cream 2.0 obogaćen je kolagenom, peptidima i hijaluronskom kiselinom kako bi pružio intenzivnu hidrataciju, učvrstio kožu vrata i smanjio vidljivost bora. Ovaj luksuzni krem sadrži vlakna inspirisana tretmanima liftinga za redefinisanje kontura vrata i dekoltea.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medi-Peel-Premium-Collagen-Naite-Thread-Neck-Cream-2.0.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
