INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1246, 114, 'Medicube PDRN Pink Glutathione Serum Mist', 'medicube-pdrn-pink-glutathione-serum-mist', 'Ključne prednosti: Povećava elastičnost kože: PDRN iz lososa pomaže u regeneraciji ćelija, što rezultira čvršćom i elastičnijom kožom. Posvetljuje ten: Glutation deluje kao snažan antioksidans koji smanjuje hiperpigmentacije i ujednačava ton kože. Hidrira i umiruje: Lagana formula pruža trenutnu hidrataciju i umiruje iritacije, ostavljajući kožu osveženom. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom ili iritacijama sklonom kožom koje žele poboljšati elastičnost i posvetliti ten. Pogodan je za sve tipove kože i starosne grupe koje traže hidrataciju i umirenje. Zašto volimo Medicube PDRN Pink Glutathione Serum Mist? Zamislite proizvod koji ne samo da osvežava vašu kožu, već joj pruža i neophodne sastojke za regeneraciju i posvetljivanje. PDRN Pink Glutathione Serum Mist kombinuje moć PDRN-a iz lososa, poznatog po svojim regenerativnim svojstvima, sa glutationom, snažnim antioksidansom koji ujednačava ten. Svaki pritisak na pumpicu oslobađa finu maglu koja trenutno hidrira i umiruje kožu, smanjujući crvenilo i iritacije. Redovnom upotrebom, koža postaje vidljivo čvršća, elastičnija i blistavija, dok se znakovi starenja i umora smanjuju. Ovaj serum u spreju je savršen dodatak vašoj dnevnoj rutini nege, pružajući profesionalne rezultate u udobnosti vašeg doma. Aktivni sastojci PDRN (Polidezoksiribonukleotid iz lososa) PDRN je bioaktivna molekula DNK dobijena iz lososa, koja ima visoku biokompatibilnost sa ljudskom kožom i deluje kao snažan faktor regeneracije. U ovoj formulaciji koristi se za poboljšanje elastičnosti, hidratacije i sjaja kože, čime se postiže mladalački i zdrav izgled. PDRN stimuliše regeneraciju ćelija, podstiče sintezu kolagena i ubrzava oporavak kože izloženoj stresu, UV zračenju i iritacijama. Njegovo dejstvo je dokumentovano kroz klinička ispitivanja kao efikasno u borbi protiv znakova starenja i opuštenosti kože. Takođe jača kožnu barijeru i vraća čvrstinu i vitalnost. Koža postaje zategnutija, mekša i vidno osvežena već nakon nekoliko upotreba. Glutation Glutation je snažan antioksidans koji neutrališe slobodne radikale i deluje direktno na posvetljavanje kože. Efikasno inhibira sintezu melanina, čime smanjuje hiperpigmentacije, fleke i ujednačava ten. Takođe štiti kožu od oksidativnog stresa izazvanog zagađenjem i UV zračenjem. U kombinaciji sa PDRN-om, pruža dvostruko dejstvo: regeneraciju i osvetljavanje kože. Glutation poboljšava tonus i vraća prirodnu blistavost beživotnoj i umornoj koži. Klinički je potvrđeno da doprinosi trenutnom poboljšanju sjaja kože za 17.63%. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Glutathione Serum Mist je osvežavajući sprej koji kombinuje PDRN iz lososa i glutation kako bi poboljšao elastičnost kože i posvetlio ten. Ovaj lagani serum u obliku magle pruža trenutnu hidrataciju i umirujući efekat, čineći ga idealnim za osetljivu ili iritacijama sklonu kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-PDRN-Pink-Glutathione-Serum-Mist.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
