INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1247, 114, 'Medicube PDRN Pink Peptide Serum', 'medicube-pdrn-pink-peptide-serum', 'Ključne prednosti: Povećava elastičnost kože: PDRN iz lososa podržava vitalnost kože i poboljšava njeno opšte stanje, dajući joj jasniji i blistaviji izgled. Ujednačava ten: Serum pomaže u smanjenju tamnih mrlja i hiperpigmentacije, ostavljajući kožu svetlijom i ujednačenijom. Hidratacija bez lepljivosti: Lagana formula seruma pruža intenzivnu hidrataciju bez osećaja lepljivosti, čineći kožu mekom i glatkom. Kome je namenjen? Ovaj serum je idealan za osobe sa svim tipovima kože koje žele poboljšati elastičnost, ujednačiti ten i smanjiti vidljive znakove starenja. Pogodan je za sve koji traže rešenje za neujednačen ten i gubitak čvrstine kože. Zašto volimo Medicube PDRN Pink Peptide Serum? PDRN Pink Peptide Serum kombinuje moć PDRN-a iz lososa i peptida kako bi pružio sveobuhvatnu negu kože. Redovnom upotrebom, ovaj serum može smanjiti pojavu finih linija i bora, dok istovremeno poboljšava teksturu kože. Njegova jedinstvena formula deluje na obnavljanje oštećene kože, pružajući joj mladalački i zdrav izgled. Osim toga, serum pomaže u smanjenju tamnih mrlja, čineći ten svetlijim i ujednačenijim. Lagana i nelepljiva tekstura omogućava brzo upijanje, ostavljajući kožu hidriranom i osveženom tokom celog dana. Dodaj u listu želja Dodaj u listu želja', 'Medicube PDRN Pink Peptide Serum je visokokvalitetni serum formulisan sa PDRN-om iz lososa i peptidima, namenjen poboljšanju elastičnosti kože i ujednačavanju tena.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-PDRN-Pink-Peptide-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
