INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1248, 114, 'Medicube Triple Collagen Toner', 'medicube-triple-collagen-toner', 'Ključne prednosti: Poboljšava elastičnost kože : Kombinacija hidrolizovanog kolagena, atelo kolagena i rastvorljivog kolagena deluje sinergijski kako bi povećala čvrstinu i elastičnost kože. Dubinska hidratacija : Hijaluronska kiselina i natrijum hijaluronat pružaju intenzivnu hidrataciju, ostavljajući kožu glatkom i mekom. Ujednačava ten : Niacinamid pomaže u posvetljavanju kože i smanjenju hiperpigmentacija, dajući licu blistav izgled. Kome je namenjen? Ovaj tonik je idealan za osobe sa suvom ili dehidriranom kožom, kao i za one koji žele poboljšati elastičnost i ujednačiti ten. Pogodan je za sve koji teže zdravom i blistavom izgledu kože. Zašto volimo Medicube Triple Collagen Toner? Redovnom upotrebom Triple Collagen Tonera, koža postaje vidljivo hidrirana i elastična. Njegova lagana formula brzo se upija, ostavljajući osećaj svežine bez lepljivog ostatka. Aktivni sastojci prodiru duboko u kožu, pružajući dugotrajnu hidrataciju i poboljšavajući teksturu. Tonik takođe pomaže u smanjenju finih linija i bora, čineći kožu glatkom i mladalačkom. Uz redovnu upotrebu, ten postaje ujednačeniji, a koža dobija prirodan sjaj. Aktivni sastojci Triple Collagen Complex (hidrolizovani kolagen, atelo kolagen, rastvorljivi kolagen) Triple Collagen Complex kombinuje tri vrste kolagena koje ciljano deluju na obnavljanje elastičnosti i čvrstoće kože. Hidrolizovani kolagen ima nisku molekulsku masu, što mu omogućava da prodre dublje u kožu i poboljša hidrataciju i tonus. Atelo kolagen je visoko prečišćen oblik koji smanjuje rizik od iritacija, jača kožnu strukturu i doprinosi zategnutosti. Rastvorljivi kolagen deluje na površini kože stvarajući zaštitni sloj koji zadržava vlagu i poboljšava teksturu. Ova sinergija kolagena doprinosi koži koja je elastična, zaglađena i vizuelno podmlađena. Redovnom upotrebom, koža postaje čvršća i otpornija na znakove starenja. Hijaluronska kiselina Hijaluronska kiselina je snažan humektant koji privlači vlagu i zadržava je u koži, pružajući dugotrajnu hidrataciju i efekat popunjene kože. Njena sposobnost da zadrži do 1000 puta veću količinu vode od svoje težine čini je idealnim sastojkom za dehidriranu i umornu kožu. Poboljšava elastičnost i glatkoću, čineći ten osveženim i punijim. Takođe smanjuje osećaj zategnutosti i umiruje iritiranu kožu. U toniku deluje kao baza za bolje upijanje ostalih aktivnih sastojaka. Koža ostaje mekana, hidrirana i vidljivo revitalizovana. Dodaj u listu želja Dodaj u listu želja', 'Medicube Triple Collagen Toner je hidratantni tonik obogaćen trostrukim kolagen kompleksom, dizajniran da poboljša elastičnost kože i pruži joj zdrav sjaj.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Triple-Collagen-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
