INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1250, 114, 'Medicube Collagen Glow Booster Serum', 'medicube-collagen-glow-booster-milk-serum', 'Ključne prednosti: Dubinska hidratacija i obnova: Zahvaljujući hijaluronskoj kiselini i kolagenu, serum povećava nivo vlage u koži i obnavlja njenu elastičnost. Učvršćivanje i podmlađivanje: Aktivni peptidi stimulišu proizvodnju kolagena, čime se smanjuju vidljivi znaci starenja poput bora i opuštene kože. Poboljšanje blistavosti: Serum posvetljuje ten i ujednačava teksturu kože, čineći je glatkom i zdravom. Kome je namenjen? Ovaj serum je idealan za osobe svih tipova kože koje žele dubinsku hidrataciju, regeneraciju i anti-age efekte. Posebno je pogodan za suvu, zrelu ili umornu kožu koja pokazuje prve znakove starenja. Zašto volimo Medicube Collagen Glow Booster Milk Serum? Lagano mlečno formulisan, Collagen Glow Booster Milk Serum pruža trenutnu vlagu i dugoročne rezultate u poboljšanju elastičnosti kože. Hidrolizovani kolagen duboko prodire u epidermis, učvršćuje i revitalizuje kožu, dok peptidi stimulišu prirodnu proizvodnju kolagena. Hijaluronska kiselina zaključava vlagu unutar kože, ostavljajući je mekšom i glatkijom već nakon prve upotrebe. Redovnom primenom, ten postaje ujednačeniji i blistaviji, a bore manje izražene. Jedinstvena formulacija seruma štiti kožu od oštećenja izazvanih spoljnim uticajima, dok je mlečna tekstura idealna za brzo upijanje bez masnog osećaja. Ovo je savršen dodatak svakoj rutini nege kože za dugoročno zdrav i blistav izgled. Aktivni sastojci Kolagen (260 Dalton) Ovaj ultra-niskomolekularni kolagen težine svega 260 Daltona omogućava duboku penetraciju u slojeve dermisa, čime se efikasno poboljšava elastičnost i čvrstina kože. Zahvaljujući svojoj veličini, brzo se apsorbuje i deluje iznutra, popunjavajući fine linije i vraćajući koži volumen. Stimuliše prirodnu sintezu kolagena i doprinosi jačanju kožne strukture. U kombinaciji sa drugim aktivnim sastojcima, pojačava efekat zatezanja i podmlađivanja kože. PDRN (Polidezoksiribonukleotid) PDRN je bioaktivna komponenta dobijena iz DNK lososa koja stimuliše regeneraciju ćelija, ubrzava zarastanje i poboljšava ukupnu funkciju kože. Deluje na molekularnom nivou tako što aktivira fibroblaste i podstiče proizvodnju kolagena i elastina. Posebno je efikasan u revitalizaciji oštećene i umorne kože, čineći je mlađom i zdravijom. Takođe pomaže u poboljšanju teksture kože i ujednačavanju tena. Proteini mleka Mlečni proteini bogati su aminokiselinama i hranljivim materijama koje pomažu u obnavljanju kože, smanjuju iritacije i poboljšavaju elastičnost. Deluju hidratantno i umirujuće, ostavljajući kožu glatkom i osveženom. Takođe doprinose osvetljavanju tena i pospešuju prirodan sjaj kože. Mlečni proteini podržavaju sintezu kolagena i poboljšavaju zaštitnu funkciju kože. U sinergiji sa PDRN-om i kolagenom, pospešuju ukupnu regeneraciju i otpornost kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube Collagen Glow Booster Milk Serum kombinuje snagu hidrolizovanog kolagena, peptida i hijaluronske kiseline kako bi intenzivno hidratizovao, regenerisao i učvrstio kožu. Njegova lagana mlečna tekstura duboko prodire u kožu, pružajući joj svež, blistav i mladalački izgled.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Collagen-Glow-Booster-Milk-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
