INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1253, 114, 'Medicube Triple Collagen Cream 4.0', 'medicube-triple-collagen-cream-4-0', 'Ključne prednosti: Poboljšava elastičnost kože: Kombinacija tri tipa kolagena i elastina povećava čvrstinu i elastičnost kože, smanjujući pojavu finih linija i bora. Dubinska hidratacija: Hijaluronska kiselina pruža intenzivnu hidrataciju, ostavljajući kožu mekom i glatkom. Ujednačava ten: Niacinamid pomaže u smanjenju tamnih mrlja i hiperpigmentacija, dajući koži blistav i ujednačen izgled. Kome je namenjena? Ova krema je idealna za osobe sa suvom i zrelom kožom koje žele poboljšati elastičnost i smanjiti znakove starenja. Takođe je pogodna za one koji se bore sa neujednačenim tenom i dehidratacijom kože. Zašto volimo Medicube Triple Collagen Cream 4.0? Redovnom upotrebom Triple Collagen Cream 4.0, koža postaje vidljivo čvršća i elastičnija. Dubinska hidratacija koju pruža hijaluronska kiselina pomaže u obnavljanju prirodne barijere kože, štiteći je od spoljašnjih uticaja. Niacinamid deluje na smanjenje tamnih mrlja, čineći ten ujednačenijim i blistavijim. Kombinacija ovih sastojaka rezultira kožom koja izgleda mlađe, zdravije i osveženo. Aktivni sastojci Elastin (premium elastin iz Francuske) Elastin je ključni strukturni protein koji daje koži sposobnost da se vraća u prvobitni oblik, čime doprinosi čvrstoći i elastičnosti. Ovaj premium elastin poreklom iz Francuske pomaže u obnavljanju izgubljene elastičnosti usled starenja i spoljašnjih oštećenja. Doprinosi vidljivom zatezanju kože i poboljšava konture lica. Takođe povećava otpornost kože na opuštanje i vraća joj mladalački izgled. U kombinaciji s kolagenom, pruža efekat „plump-up“ i zategnute kože. Kolagen (Triple Collagen Complex) Kombinacija više oblika kolagena – uključujući hidrolizovani, rastvorljivi i atelo kolagen – pruža slojevitu negu kože iznutra i spolja. Hidrolizovani kolagen deluje dubinski, poboljšava elastičnost i zadržava vlagu. Rastvorljivi kolagen hidrira površinski sloj kože, dok atelo kolagen jača kožnu barijeru i pruža efekat zatezanja. Ova sinergija doprinosi sveukupnom učvršćivanju kože, popunjavanju finih linija i vraćanju volumena. Takođe podstiče prirodnu sintezu kolagena, čime se poboljšava struktura i tonus kože. Ekstrakt kore Enantia Chlorantha Ekstrakt kore drveta Enantia Chlorantha poznat je po svom adstringentnom i regulativnom delovanju na pore i lučenje sebuma. Deluje tako što vidljivo smanjuje veličinu pora, matira ten i poboljšava teksturu kože. Takođe ima antiinflamatorna i antibakterijska svojstva, što ga čini pogodnim za mešovitu i masnu kožu. U kremi pomaže u postizanju ujednačenijeg tena i finijeg izgleda kože. Pruža balans između čišćenja i hidratacije. Dodaj u listu želja Dodaj u listu želja', 'Medicube Triple Collagen Cream 4.0 je bogata hidratantna krema formulirana s tri tipa kolagena i premium elastinom iz Francuske, namenjena poboljšanju elastičnosti kože i smanjenju znakova starenja. Obogaćena je niacinamidom i hijaluronskom kiselinom za dubinsku hidrataciju i ujednačavanje tena.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Triple-Collagen-Cream-4.0.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
