INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1255, 114, 'Medicube Zero Pore Serum 2.0', 'medicube-zero-pore-serum-2-0', 'Ključne prednosti: Sužavanje pora: Smanjuje vidljivost pora, ostavljajući kožu glatkom. Kontrola sebuma: Reguliše proizvodnju ulja, sprečavajući prekomerno mašćenje kože. Uravnotežena hidratacija: Održava optimalan nivo vlage, sprečavajući isušivanje. Kome je namenjen? Idealan za osobe sa masnom i kombinovanom kožom sklonom proširenim porama i prekomernom lučenju sebuma. Pogodan za sve koji žele poboljšati teksturu kože i smanjiti vidljivost pora. Zašto volimo Medicube Zero Pore Serum 2.0? U srcu ove formulacije nalazi se ekstrakt kamelije, poznat po svojoj sposobnosti da reguliše lučenje sebuma i sužava pore, pružajući koži zdrav i uravnotežen izgled. Redovnom upotrebom, serum pomaže u održavanju optimalne ravnoteže ulja i vlage u koži, sprečavajući pojavu masnog sjaja i dehidratacije. Njegova lagana tekstura brzo se upija, ostavljajući kožu mekom i glatkom bez osećaja lepljivosti. Klinička ispitivanja su potvrdila njegovu efikasnost u sužavanju pora, čineći ga pouzdanim izborom za one koji teže besprekornom tenu. Pored toga, hipoalergena formula čini ga pogodnim i za osetljivu kožu, pružajući nežnu, ali efikasnu negu. Aktivni sastojci Ekstrakt kamelije (Camellia Japonica Flower Extract) Ekstrakt cveta kamelije poznat je po svojoj sposobnosti da uravnoteži proizvodnju sebuma i poboljša opšte stanje kože sklone proširenim porama. Bogat je antioksidansima i taninima koji pomažu u zatezanju pora, smanjenju masnoće i poboljšanju teksture kože. Deluje adstringentno, ali istovremeno i umirujuće, čime održava zdrav odnos ulja i vlage u koži bez izazivanja isušivanja. Njegova nežna priroda čini ga pogodnim za svakodnevnu upotrebu i za osetljive tipove kože. Takođe doprinosi jačanju kožne barijere i smanjenju crvenila i iritacija. Redovnom upotrebom koža postaje balansirana, vidno rafinirana i sa smanjenim porama. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore Serum 2.0 je lagani serum formulisan za sužavanje pora i kontrolu lučenja sebuma, pružajući uravnoteženu hidrataciju za čistiju i glatkiju kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Zero-Pore-Serum-2.0.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
