INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1256, 114, 'Medicube Zero Pore One Day Serum', 'medicube-zero-pore-one-day-serum', '﻿ Ključne prednosti: Smanjenje pora i kontrole sebuma : Salicilna kiselina čisti pore i smanjuje masnoću, dok niacinamid sužava pore i poboljšava teksturu kože. Hidratacija i obnova kože : Beta-glukan i pantenol pružaju intenzivnu hidrataciju i umiruju kožu, smanjujući iritacije. Eksfolijacija i čišćenje : Formulacija omogućava blagu eksfolijaciju koja uklanja mrtve ćelije kože i vraća svežinu i vitalnost tena. Kome je namenjen? Ovaj serum je idealan za masnu, kombinovanu i kožu sklonu aknama, ali se može koristiti i na normalnoj koži koja ima problema sa proširenim porama. Pogodan za sve koji žele efikasnu kontrolu sebuma i poboljšanje teksture kože. Zašto volimo Medicube Zero Pore One Day Serum? Zero Pore One Day Serum deluje ciljano na problematične pore i višak sebuma. Salicilna kiselina pročišćava kožu dubinski, uklanjajući višak masnoće i nečistoće iz pora. Niacinamid dodatno poboljšava izgled pora i smanjuje crvenilo, pružajući ujednačeniji ten. Beta-glukan hidrira i obnavlja kožu, čineći je otpornijom na spoljašnje faktore. Pantenol smiruje iritacije, dok blaga eksfolijacija vraća koži prirodnu glatkoću. Redovnom upotrebom, koža postaje svežija, prozračnija i vizuelno zdravija, dok se nepravilnosti vidno smanjuju. Aktivni sastojci AHA + BHA + PHA kompleksi Kombinacija AHA, BHA i PHA kiselina pruža trostruku eksfolijaciju kože — uklanja mrtve ćelije, čisti pore i poboljšava teksturu. AHA (alfa-hidroksi kiseline) deluju na površini kože i osvetljavaju ten uklanjanjem odumrlih ćelija. BHA (beta-hidroksi kiseline) prodire dublje u pore i razgrađuje sebum, čime efikasno uklanja mitisere i sprečava začepljenje pora. PHA (poli-hidroksi kiseline) imaju veću molekulsku masu, pa su blaže i pogodne za osetljivu kožu — istovremeno hidratantne i eksfolijantne. Ova sinergijska formulacija pročišćava pore, kontroliše lučenje sebuma i doprinosi jasnijem, čistijem tenu. Ekstrakt Myosotis-a (nezaboravak) Ekstrakt nezaboravka (Myosotis) ima umirujuće dejstvo koje pomaže u smanjenju crvenila i upala, posebno kod kože izložene hemijskim eksfolijantima. Ovaj cvetni ekstrakt je takođe poznat po svojim hidratantnim svojstvima i sposobnosti da zaštiti kožnu barijeru. Doprinosi balansu između tretiranja pora i očuvanja vlažnosti kože. Njegova blagost čini ga pogodnim za svakodnevnu upotrebu, posebno kod osetljive i reaktivne kože. Ekstrakt Jeju chickweed-a (Stellaria media) Ovaj prirodni biljni ekstrakt sa ostrva Jeju poznat je po svom antioksidativnom i posvetljujućem efektu. Pomaže u poboljšanju tonusa kože, čineći je ujednačenijom i blistavijom. Takođe deluje osvežavajuće i podstiče obnavljanje kože, dajući joj zdraviji, živahniji izgled. Njegovo dejstvo posebno je korisno za umornu, sivkastu kožu kojoj nedostaje sjaj. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore One Day Serum je specijalno formulisan serum za sužavanje pora, poboljšanje teksture kože i kontrolu sebuma. Obogaćen niacinamidom, beta-glukanom i salicilnom kiselinom, pomaže u smanjenju nesavršenosti i ostavlja kožu glatkom, blistavom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Zero-Pore-One-Day-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
