INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1257, 114, 'Medicube AGE-R Glutathione Glow Capsule Cream', 'medicube-age-r-glutathione-glow-capsule-cream', 'Ključne prednosti: Posvetljivanje i ujednačavanje tena : Glutation i niacinamid deluju sinergijski kako bi smanjili hiperpigmentaciju i posvetlili kožu. Dubinska hidratacija : Hijaluronska kiselina intenzivno hidrira, povećava elastičnost i čini kožu glatkom. Zaštita od oksidativnog stresa : Antioksidativni efekti štite kožu od štetnih spoljašnjih faktora i podržavaju regeneraciju. Kome je namenjen? Ovaj proizvod je idealan za osobe svih tipova kože, posebno za one sa problemima poput hiperpigmentacije, neujednačenog tona i dehidratacije. Preporučuje se za starosnu grupu 25+ koja traži rešenje za posvetljivanje kože i sprečavanje znakova starenja. Zašto volimo Medicube AGE-R Glutathione Glow Capsule Cream? AGE-R Glutathione Glow Capsule Cream transformiše kožu svojim naprednim formulacijama. Glutation, poznat po svojim moćnim posvetljujućim svojstvima, pomaže u smanjenju tamnih mrlja i ujednačava ten. Niacinamid dodatno smanjuje crvenilo i pruža zaštitu kožnoj barijeri. Uz hidrataciju koju pruža hijaluronska kiselina, koža postaje elastična i osvežena. Formula je bogata antioksidansima koji smanjuju uticaj slobodnih radikala, čineći kožu zdravijom. Kapsule aktivnih sastojaka oslobađaju se prilikom nanošenja, omogućavajući dublje prodiranje i bolji efekat. Redovnom upotrebom, koža izgleda blistavo i revitalizovano, dok se njena tekstura vidljivo poboljšava. Aktivni sastojci Glutation (99.4% čistoće, u kapsulama) Glutation je jedan od najsnažnijih prirodnih antioksidanasa koji deluje na posvetljivanje kože i ujednačavanje tena inhibicijom sinteze melanina. U obliku kapsula visoke čistoće, omogućava ciljanu i stabilnu isporuku direktno na kožu za maksimalni efekat sjaja i revitalizacije. Glutation takođe štiti kožu od oksidativnog stresa i štetnih uticaja iz spoljašnje sredine, uključujući UV zračenje i zagađenje. Njegova anti-age svojstva uključuju poboljšanje elastičnosti i smanjenje finih linija i nepravilnosti tena. Pro Peptid & Elastic Peptid Ovi specijalizovani peptidi deluju kao signalne molekule koje stimulišu sintezu kolagena i elastina, čime se poboljšava čvrstina i zategnutost kože. Pro Peptid pospešuje regeneraciju ćelija i obnavlja strukturu kože, dok Elastic Peptid direktno cilja na elastičnost i učvršćivanje. Zajedno deluju na smanjenje bora, podizanje tonusa i redefinisanje kontura, naročito u regijama poput vrata i dekoltea. Ovi peptidi takođe pomažu u jačanju kožne barijere i povećavaju otpornost kože na spoljašnje faktore. Hidro-ceramid Hidro-ceramid je napredna hidratantna komponenta koja kombinuje sposobnost zadržavanja vlage sa jačanjem zaštitne barijere kože. Deluje kao emolijent i humektant, obezbeđujući dugotrajnu hidrataciju i sprečavajući transepidermalni gubitak vode. Takođe doprinosi glatkoći i mekoći kože, smanjujući osećaj zategnutosti i suvoće. Njegova uloga u &#8220;wrap-effect&#8221; formulaciji dodatno pojačava zadržavanje aktivnih sastojaka na površini kože. Dodaj u listu želja Dodaj u listu želja', 'Medicube AGE-R Glutathione Glow Capsule Cream kombinuje snagu glutationa, niacinamida i hijaluronske kiseline za posvetljivanje, dubinsku hidrataciju i ujednačavanje tena. Njegova jedinstvena kapsulirana formula obezbeđuje intenzivan sjaj i elastičnost kože, čineći je vidljivo blistavom i revitalizovanom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-AGE-R-Glutathione-Glow-Capsule-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
