INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1259, 114, 'Medicube Zero Pore Blackhead Mud Mask', 'medicube-zero-pore-blackhead-mud-mask', 'Ključne prednosti: Dubinsko čišćenje pora: Kombinacija AHA, BHA i PHA kiselina uklanja mrtve ćelije kože i nečistoće, poboljšavajući teksturu kože. Smanjenje mitisera i sebuma: Pet vrsta glina apsorbuju višak sebuma i nečistoća, pomažući u smanjenju mitisera i kontroli sjaja. Umirujući efekat: Sastojci poput guaiazulen-a umiruju osetljivu kožu, smanjujući crvenilo i iritacije. Kome je namenjena? Ova maska je idealna za osobe sa kombinovanom do masnom kožom sklonom mitiserima i proširenim porama. Pogodna je za sve koji žele poboljšati teksturu kože i smanjiti pojavu mitisera. Zašto volimo Medicube Zero Pore Blackhead Mud Mask? Nakon čišćenja lica, nanesite odgovarajuću količinu maske na suvu kožu, izbegavajući područja oko očiju i usana. Dok se maska suši, aktivni sastojci prodiru duboko u pore, apsorbujući nečistoće i višak sebuma. Nakon 3-5 minuta, kada se maska potpuno osuši, isperite je mlakom vodom. Redovnom upotrebom, koža postaje glatka, pore sužene, a ten blistaviji. Ovaj tretman pruža osećaj svežine i čistoće, ostavljajući kožu revitalizovanom i osveženom. Aktivni sastojci AHA, BHA, PHA kompleksi Ova maska sadrži kombinaciju AHA (alfa-hidroksi kiseline), BHA (beta-hidroksi kiseline) i PHA (poli-hidroksi kiseline) koje deluju sinergijski na eksfolijaciju i pročišćavanje pora. AHA deluju na površinskom nivou, uklanjajući mrtve ćelije i posvetljujući ten, dok BHA prodire duboko u pore i efikasno razgrađuje višak sebuma i mitisere. PHA su nežniji eksfolijanti koji istovremeno hidrira kožu i čine je pogodnom za osetljive tipove. Ova kombinacija rezultira brzom apsorpcijom nečistoća iz pora u roku od 3 minuta, čime se poboljšava njihov izgled i smanjuje vidljivost. Klinički je potvrđeno smanjenje zapremine, broja, veličine i dubine pora nakon dve nedelje upotrebe. Koža postaje glađa, čistija i vidno rafinirana. Guaiazulene Guaiazulene je sastojak dobijen iz ulja kamilice poznat po svojim izuzetnim umirujućim i protivupalnim svojstvima. Deluje tako što smanjuje crvenilo, ublažava iritacije i balansira kožu tokom i nakon dubinskog čišćenja. Njegova plava boja potiče iz prirodnih jedinjenja sa antioksidativnim efektom, a posebno je koristan kod reaktivne, osetljive kože. U ovoj maski, Guaiazulene ublažava moguće nuspojave eksfolijacije i ostavlja kožu smirenom i zaštićenom. Koži pruža osećaj udobnosti i oporavka bez zatezanja. Rezultat je uravnotežena i osvežena koža nakon tretmana. Blue Peptid Blue Peptid je inovativni hidratantni i umirujući peptid koji deluje unutar i na površini kože, pružajući dvosmernu negu. Pomaže u poboljšanju unutrašnje hidratacije kože, dok spolja deluje na jačanje kožne barijere i umanjuje osećaj suvoće i nelagodnosti. Takođe ima blagi anti-age efekat, poboljšavajući elastičnost i tonus kože. Njegovo &#8220;cool calm&#8221; dejstvo doprinosi osećaju svežine i hlađenja nakon upotrebe maske, što je idealno za kožu koja je prošla intenzivno čišćenje. Dodaj u listu želja Dodaj u listu želja', 'Medicube Zero Pore Blackhead Mud Mask je formulisan sa AHA, BHA i PHA kiselinama, kao i pet vrsta glina, pružajući dubinsko čišćenje pora i efikasno uklanjanje mitisera.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Medicube-Zero-Pore-Blackhead-Mud-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
