INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1268, 90, 'Jumiso Super Soothing Cica & Aloe Facial Serum', 'jumiso-super-soothing-cica-aloe-facial-serum', 'Ključne prednosti: Intenzivno umirivanje kože: Visok sadržaj Centella Asiatica ekstrakta pomaže u smanjenju crvenila i iritacija, pružajući olakšanje osetljivoj koži. Dubinska hidratacija: Sedam vrsta hijaluronske kiseline obezbeđuju optimalnu vlažnost, čineći kožu mekom i elastičnom. Obnova barijere kože: Ekstrakt aloe vere doprinosi regeneraciji oštećene kože i jačanju njene zaštitne funkcije. Kome je namenjen? Ovaj serum je idealan za osobe sa osetljivom, suvom ili iritiranom kožom, kao i za one koji se suočavaju sa crvenilom ili oštećenjima kože. Zašto volimo Jumiso Super Soothing Cica & Aloe Facial Serum? Super Soothing Cica & Aloe Serum transformiše kožu pružajući instant olakšanje od iritacija i upala. Centella Asiatica, poznata kao &#8220;tigrova trava&#8221;, regeneriše oštećenu kožu i pomaže u smanjenju crvenila. Aloe vera prodire duboko u slojeve kože, pružajući intenzivnu hidrataciju i osveženje. Serum je lagane teksture, brzo se upija i ostavlja kožu mekom i glatkom bez masnog osećaja. Njegova moćna formula jača prirodnu barijeru kože, štiteći je od uticaja zagađenja i stresa. Uz redovnu upotrebu, koža postaje zdravija, otpornija i ujednačenog tona. Aktivni sastojci Centella Asiatica (41%) Centella Asiatica je poznata po svojim umirujućim i isceljujućim svojstvima. Pomaže u regeneraciji kože, smanjuje crvenilo i ublažava iritacije. Bogata je triterpenima, koji stimulišu sintezu kolagena i jačaju strukturu kože. Njena antiinflamatorna svojstva čine je idealnim sastojkom za osetljivu kožu. Aloe vera (31%) Aloe vera hidrira, osvežava i umiruje kožu. Bogata vitaminima i mineralima, pomaže u obnavljanju oštećene kože, dok njeni polisaharidi pomažu u zadržavanju vlage. Takođe poseduje antioksidativna svojstva koja štite kožu od slobodnih radikala. Alantoin Ovaj prirodni sastojak poznat je po umirujućim svojstvima. Pomaže u smanjenju iritacija, pospešuje regeneraciju ćelija kože i doprinosi glatkom i mekom osećaju kože. Beta-glukan Beta-glukan hidrira kožu i pruža zaštitni sloj koji pomaže u jačanju prirodne barijere kože. Njegova antioksidativna svojstva dodatno štite od oštećenja izazvanih spoljnim faktorima. Ekstrakt zelenog čaja Snažan antioksidans koji smanjuje upale i štiti kožu od oštećenja slobodnim radikalima. Takođe pomaže u smanjenju crvenila i sprečava prekomernu proizvodnju sebuma. Dodaj u listu želja Dodaj u listu želja', 'Jumiso Super Soothing Cica & Aloe Facial Serum je formulisan sa 41% ekstrakta Centella Asiatica i 31% ekstrakta aloe vere kako bi smirio iritiranu kožu, smanjio crvenilo i pružio dubinsku hidrataciju. Idealan je za osetljivu i upaljenu kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Jumiso-Super-Soothing-Cica-Aloe-Facial-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
