INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1269, 90, 'Jumiso All Day Vitamin Pure C 5.5 Glow Serum', 'jumiso-all-day-vitamin-pure-c-5-5-glow-serum', 'Ključne prednosti: Posvetljuje kožu: Visoka koncentracija vitamina C pomaže u smanjenju hiperpigmentacija i vraća prirodni sjaj koži. Ujednačava ten: Kombinacija vitamina C i alfa-arbutina deluje sinergijski na smanjenje tamnih mrlja i diskoloracija. Antioksidativna zaštita: Ferulična kiselina i tokoferol štite kožu od oštećenja izazvanih slobodnim radikalima, usporavajući proces starenja. Kome je namenjen? Ovaj serum je pogodan za sve tipove kože, uključujući osetljivu. Preporučuje se osobama koje žele da posvetle ten, smanje vidljivost tamnih mrlja ili ublaže znakove preranog starenja. Zašto volimo Jumiso All Day Vitamin Pure C 5.5 Glow Serum? All Day Vitamin Pure C 5.5 Glow Serum delikatno transformiše ten kože zahvaljujući pažljivo biranoj formulaciji sa 5,5% vitamina C. Ovaj serum ne samo da posvetljuje kožu već i smanjuje vidljivost tamnih mrlja, hiperpigmentacija i ožiljaka od akni. Svojim laganim i brzo upijajućim svojstvima, serum prodire duboko u kožu, obnavljajući njenu teksturu i pružajući prirodni sjaj. Kombinacija alfa-arbutina i ferulične kiseline dodatno ujednačava ten i pruža snažnu antioksidativnu zaštitu, štiteći kožu od oštećenja izazvanih slobodnim radikalima i spoljašnjim zagađivačima. Tokoferol (vitamin E) i ekstrakt aronije doprinose hidrataciji i umiruju iritacije, čineći serum pogodnim i za osetljivu kožu. Aktivni sastojci Askorbinska kiselina (L-Ascorbic Acid, 5.5%) Askorbinska kiselina je čista forma vitamina C, poznata po svojoj sposobnosti da posvetli kožu i ujednači ten. Doprinosi smanjenju tamnih fleka i hiperpigmentacija inhibiranjem sinteze melanina. Stimuliše proizvodnju kolagena, poboljšavajući elastičnost kože i smanjujući vidljivost finih linija. Kao snažan antioksidans, štiti kožu od oštećenja izazvanih slobodnim radikalima i UV zračenjem. Askorbil glukozid (Ascorbyl Glucoside) Askorbil glukozid je stabilan derivat vitamina C koji se aktivira u kontaktu s kožom, pružajući iste prednosti kao čista askorbinska kiselina, ali sa manjom iritacijom. Ima snažno antioksidativno dejstvo, štiteći kožu od spoljašnjih agresora. Efikasno posvetljuje tamne mrlje i neujednačen ten. Pomaže u sintezi kolagena, čime doprinosi čvrstoći i elastičnosti kože. Alfa-arbutin (Alpha-Arbutin) Alfa-arbutin je moćan sastojak za posvetljivanje kože koji deluje inhibiranjem enzima tirozinaze, odgovornog za proizvodnju melanina. Efikasno smanjuje pojavu tamnih fleka, staračkih pega i postupalne hiperpigmentacije. Pruža ujednačen i svetliji ten bez iritacije, što ga čini pogodnim za sve tipove kože. U kombinaciji sa vitaminom C, njegova efikasnost u borbi protiv diskoloracije se dodatno pojačava. Dodaj u listu želja Dodaj u listu želja', 'Jumiso All Day Vitamin Pure C 5.5 Glow Serum je serum za posvetljivanje kože koji sadrži 5,5% čistog vitamina C (L-askorbinska kiselina) i dodatne antioksidanse, formulisan za ujednačavanje tena i smanjenje tamnih fleka.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Jumiso-All-Day-Vitamin-Pure-C-5.5-Glow-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
