INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1272, 90, 'Jumiso All Day Vitamin Brightening & Balancing Serum', 'jumiso-all-day-vitamin-brightening-balancing-serum', 'Ključne prednosti: Posvetljivanje tena: Niacinamid pomaže u smanjenju hiperpigmentacija i ujednačava ton kože. Hidratacija: Ekstrakt vučjeg trna i hijaluronska kiselina obezbeđuju dubinsku hidrataciju, ostavljajući kožu mekom i glatkom. Antioksidativna zaštita: Prisustvo vitamina C i biljnih ekstrakata štiti kožu od slobodnih radikala i spoljašnjih agresora. Kome je namenjen? Ovaj serum je pogodan za sve tipove kože, uključujući osetljivu, posebno za one koji žele da posvetle ten, ujednače boju kože i poboljšaju njenu elastičnost. Zašto volimo JUMISO All Day Vitamin Brightening & Balancing Serum? Svaka kap All Day Vitamin seruma donosi bogatstvo prirodnih sastojaka koji revitalizuju kožu. Visoka koncentracija ekstrakta vučjeg trna pruža intenzivnu hidrataciju. Niacinamid smanjuje pojavu tamnih fleka i crvenila. Biljni ekstrakti, poput zelenog čaja i sladića, umiruju iritacije i pružaju antioksidativnu zaštitu. Redovnom upotrebom, koža postaje blistavija, elastičnija i otpornija na spoljašnje faktore. Aktivni sastojci Ekstrakt drveta vitamina (Hippophae Rhamnoides – Sea Buckthorn) Ekstrakt drveta vitamina, poznat i kao ekstrakt ploda pasjeg trna, bogat je antioksidansima poput vitamina C, E i beta-karotena. Ovaj sastojak pomaže u borbi protiv beživotnog izgleda kože tako što neutrališe slobodne radikale i pospešuje prirodan sjaj. Podstiče regeneraciju ćelija, poboljšavajući tonus i teksturu kože. Takođe doprinosi jačanju kožne barijere i otpornosti na spoljne agresore. Poznat je po svojim antiinflamatornim i umirujućim svojstvima, što ga čini pogodnim za osetljivu i problematičnu kožu. Redovna upotreba proizvoda sa ovim ekstraktom poboljšava blistavost, ujednačenost tena i svežinu kože. Niacinamid (Vitamin B3) Niacinamid je dobro poznat sastojak koji ujednačava ten i posvetljuje tamne fleke nastale od sunca, akni ili starenja. Pomaže u regulaciji proizvodnje sebuma, čime se smanjuje pojava proširenih pora i masnog sjaja. Deluje antiinflamatorno i ublažava crvenilo, što ga čini idealnim za osetljivu i aknama sklonu kožu. Podstiče sintezu ceramida, jačajući kožnu barijeru i poboljšavajući hidrataciju. Ekstrakt Centella Asiatica Ekstrakt Centella Asiatica ima umirujuća svojstva koja pomažu u obnavljanju i jačanju kožne barijere. Bogata aktivnim komponentama kao što su asiaticoside i madecassoside, ova biljka stimuliše sintezu kolagena i ubrzava zarastanje kože. Deluje protiv upala i crvenila, što je čini savršenim izborom za reaktivnu i osetljivu kožu. Takođe pomaže u zadržavanju vlage, čineći kožu hidriranom i punijom. Dodaj u listu želja Dodaj u listu želja', 'JUMISO All Day Vitamin Brightening & Balancing Serum je lagani serum koji sadrži 86,14% ekstrakta ploda vučjeg trna (Sea Buckthorn) i 20.000 ppm niacinamida, pružajući koži blistavost i ujednačen ton.', 'https://beauty-health.rs/wp-content/uploads/2024/12/JUMISO-All-Day-Vitamin-Brightening-Balancing-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
