INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1273, 90, 'Jumiso Blackhead Melting Softener & Cotton Pad Set', 'jumiso-blackhead-melting-softener-cotton-pad-set', 'Ključne prednosti: Efikasno uklanjanje mitisera: Sukcinska kiselina omekšava i uklanja sebum i mitisere, čisteći pore. Smanjenje iritacija: Ekstrakt čempresa i voda lista čajevca umiruju i smiruju kožu, smanjujući crvenilo i iritacije. Hidratacija i obnova kože: Pantenol i hijaluronske kiseline hidriraju kožu i zaključavaju vlagu, poboljšavajući njenu teksturu. Kome je namenjen? Ovaj proizvod je idealan za osobe sa masnom ili kombinovanom kožom sklonom mitiserima i začepljenim porama. Zašto volimo JUMISO Blackhead Melting Softener & Cotton Pad Set? Blackhead Melting Softener je pažljivo formulisan da obezbedi dugotrajne rezultate u čišćenju kože. Sukcininska kiselina deluje direktno na problematične pore, omekšavajući sebum i mitisere kako bi ih bilo lakše ukloniti. Poli-hidroksi kiseline (PHA) obezbeđuju blagu eksfolijaciju, uklanjajući mrtve ćelije kože bez izazivanja iritacija. Ekstrakti čempresa i lista čajevca pružaju antiseptička svojstva koja smanjuju crvenilo i sprečavaju pojavu novih nesavršenosti. Pantenol i hijaluronska kiselina obnavljaju hidrataciju, ostavljajući kožu mekom i osveženom. Ovaj proizvod pomaže u dugoročnom poboljšanju teksture i izgleda kože. Aktivni sastojci Sukcinska kiselina (Succinic Acid) Sukcinska kiselina je prirodni sastojak poznat po svojoj sposobnosti da omekša i razgradi sebum, olakšavajući uklanjanje mitisera. Deluje antibakterijski, pomažući u sprečavanju nastanka novih nepravilnosti na koži. Takođe pomaže u regulaciji proizvodnje sebuma, čime doprinosi smanjenju masnog sjaja. Njena blaga eksfolijantna svojstva pomažu u uklanjanju mrtvih ćelija kože, poboljšavajući teksturu i tonus. Čempresova voda (Chamaecyparis Obtusa Water) Čempresova voda je poznata po svojim umirujućim i antiinflamatornim svojstvima, što je čini idealnom za osetljivu i iritiranu kožu. Pomaže u smanjenju crvenila i pruža osećaj svežine. Takođe ima antibakterijska svojstva koja pomažu u održavanju čistoće kože. Bogata je fitoncidima, prirodnim jedinjenjima koja jačaju odbrambeni mehanizam kože. Doprinosi hidrataciji i balansiranju proizvodnje sebuma. Polihidroksi kiselina (PHA) PHA je nežna eksfolijantna kiselina koja uklanja mrtve ćelije sa površine kože, poboljšavajući njenu teksturu i tonus. Za razliku od drugih kiselina, PHA je pogodna za osetljivu kožu jer manje iritira. Takođe deluje kao humektant, privlačeći vlagu i pružajući hidrataciju. Njena antioksidativna svojstva pomažu u zaštiti kože od slobodnih radikala. Redovnom upotrebom, PHA doprinosi glatkijoj, svetlijoj i zdravijoj koži. Dodaj u listu želja Dodaj u listu želja', 'JUMISO Blackhead Melting Softener & Cotton Pad Set je ciljano rešenje za uklanjanje mitisera i viška sebuma, formulisan sa sukcininskom kiselinom i nežnim eksfolijantima. Ovaj set uključuje mekane pamučne jastučiće za jednostavnu i efikasnu aplikaciju, ostavljajući kožu čistom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/JUMISO-Blackhead-Melting-Softener-Cotton-Pad-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
