INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1275, 85, 'iUNIK Beta-Glucan Daily Moisture Cream', 'iunik-beta-glucan-daily-moisture-cream', 'Ključne prednosti: Dubinska hidratacija: Beta-glukan zadržava vlagu u koži, pružajući dugotrajnu hidrataciju i poboljšavajući elastičnost. Umirujući efekat: Ekstrakt centela azijatike smiruje iritacije i crvenilo, čineći je pogodnom za osetljivu kožu. Revitalizacija kože: Kompleks crvenog voća bogat antioksidansima pomaže u zaštiti kože od slobodnih radikala i vraća joj prirodni sjaj. Kome je namenjena? Ova krema je idealna za osobe sa suvom i osetljivom kožom, kao i za one koji traže proizvod koji pruža intenzivnu hidrataciju i umiruje iritacije. Zašto volimo iUNIK Beta-Glucan Daily Moisture Cream? Beta-Glucan Daily Moisture Cream pruža koži neophodnu vlagu, čineći je mekom i elastičnom tokom celog dana. Redovnom upotrebom, koža postaje otpornija na spoljašnje stresore, dok se smanjuju znakovi suvoće i iritacije. Lagana tekstura omogućava brzo upijanje bez masnog osećaja, ostavljajući kožu glatkom i osveženom. Aktivni sastojci deluju sinergijski kako bi obnovili prirodnu barijeru kože, pružajući joj zdrav i blistav izgled. Ova krema ne samo da hidrira, već i revitalizuje kožu, vraćajući joj mladalački sjaj. Aktivni sastojci Beta-glukan Beta-glukan je polisaharid poznat po svojim izuzetnim hidratantnim svojstvima, pružajući dubinsku vlagu koži. Deluje kao snažan antioksidans, štiteći kožu od štetnih slobodnih radikala i oksidativnog stresa. Pomaže u jačanju kožne barijere, povećavajući njenu otpornost na spoljašnje iritanse. Takođe, poseduje umirujuće i antiinflamatorne efekte, smanjujući crvenilo i iritacije, što ga čini pogodnim za osetljivu kožu. Beta-glukan stimuliše regeneraciju ćelija, ubrzavajući proces zarastanja manjih oštećenja i ožiljaka. Ekstrakt Centella Asiatica Ekstrakt biljke Centella Asiatica poznat je po svojim regenerativnim svojstvima, podstičući sintezu kolagena i ubrzavajući zarastanje rana. Deluje umirujuće na kožu, smanjujući upale i crvenilo, što je posebno korisno za osetljivu i iritiranu kožu. Takođe, ima antioksidativna svojstva koja štite kožu od štetnih spoljašnjih faktora i prevremenog starenja. Pomaže u poboljšanju elastičnosti i čvrstine kože, čineći je glatkijom i toniranijom. Ekstrakt Centella Asiatica doprinosi hidrataciji kože, zadržavajući vlagu i sprečavajući isušivanje. Dodaj u listu želja Dodaj u listu želja', 'iUNIK Beta-Glucan Daily Moisture Cream je lagana hidratantna krema koja sadrži 3% beta-glukana, pružajući intenzivnu hidrataciju i poboljšavajući elastičnost kože. Obogaćena je ekstraktima crvenog voća i centela azijatike za dodatne umirujuće i revitalizujuće efekte.', 'https://beauty-health.rs/wp-content/uploads/2024/12/iUNIK-Beta-Glucan-Daily-Moisture-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
