INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1280, 84, 'Isntree Green Tea Fresh Toner', 'isntree-green-tea-fresh-toner', 'Ključne prednosti: Kontrola sebuma: Reguliše proizvodnju ulja, smanjujući masni sjaj i održavajući pore čistim. Umirujuće dejstvo: Ublažava iritacije i crvenilo zahvaljujući antioksidativnim svojstvima zelenog čaja. Hidratacija bez opterećenja: Pruža laganu hidrataciju bez začepljenja pora, ostavljajući kožu mekom i osveženom. Kome je namenjen? Idealan za osobe sa masnom i kombinovanom kožom, posebno onima koji se bore sa viškom sebuma i povremenim aknama. Zašto volimo Isntree Green Tea Fresh Toner? Ovaj toner sadrži visok procenat zelenog čaja sa ostrva Jeju, poznatog po svojim moćnim antioksidativnim svojstvima. Redovnom upotrebom, koža postaje vidno čistija i uravnoteženija, dok se smanjuje pojava nesavršenosti. Lagana formula brzo se upija, ostavljajući prijatan osećaj svežine bez lepljivog ostatka. Prirodni ekstrakti dodatno hrane kožu, čineći je glatkom i blistavom. Ovaj toner ne samo da hidrira, već i pomaže u održavanju optimalnog balansa ulja i vlage, što je ključno za zdrav izgled kože. Aktivni sastojci Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Ekstrakt zelenog čaja sa ostrva Jeju čini 80% formulacije ovog tonika i bogat je antioksidansima, naročito epigalokatehin galatom (EGCG). Ovaj sastojak deluje umirujuće i antiinflamatorno, što ga čini idealnim za tretman osetljive, crvene ili upaljene kože. Zeleni čaj pomaže u regulaciji sebuma i sprečava oksidaciju sebuma u porama, čime se smanjuje verovatnoća začepljenja i nastanka akni. Takođe pomaže u zaštiti kože od štetnih efekata UV zračenja i slobodnih radikala. Redovnom upotrebom poboljšava tonus kože, ublažava znakove umora i revitalizuje ten. Anti Sebum P (HD) kompleks Anti Sebum P (HD) je patentirani kompleks sastojaka (uključujući ulmus davidiana root extract, evening primrose extract, portulaca oleracea extract i ivy leaf/stem extract) dizajniran da smanji prekomerni sebum i pročisti pore. Ovaj kompleks apsorbuje višak masnoće bez isušivanja kože, čime pomaže u održavanju balansa između hidratacije i kontrole sjaja. Deluje adstringentno i pomaže u smanjenju veličine pora, poboljšavajući ukupnu teksturu kože. Njegovo protivupalno i antibakterijsko delovanje doprinosi smanjenju akni i sprečava ponovnu pojavu nepravilnosti. Takođe doprinosi smirenijem i ujednačenijem tenu, posebno kod kože sklone masnoći u T-zoni. Dodaj u listu želja Dodaj u listu želja', 'Isntree Green Tea Fresh Toner sadrži 80% ekstrakta zelenog čaja sa ostrva Jeju, pružajući umirujuće i osvežavajuće dejstvo za kožu sklonu masnoći i aknama.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Isntree-Green-Tea-Fresh-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
