INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1287, 74, 'House of Hur Purifying Cleansing Balm', 'house-of-hur-purifying-cleansing-balm', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja šminku, kremu za sunčanje i nečistoće, ostavljajući kožu potpuno čistom, a istovremeno hidriranom. Održavanje hidratacije: Formulisan tako da zadržava prirodnu vlagu kože, sprečavajući suvoću i zatezanje tokom čišćenja. Umirujuće i balansirajuće delovanje: Aktivni sastojci poput ricinusovog ulja i vitamina E smiruju kožu i pomažu u kontroli proizvodnje sebuma. Kome je namenjena? Ovaj balzam je savršen za sve tipove kože, uključujući osetljivu i problematičnu, zbog svoje nežne, ali efikasne formule. Namenjen je onima koji traže dubinsko čišćenje i hidrataciju, uz održavanje prirodne barijere kože. Zašto volimo House of Hur Purifying Cleansing Balm? Purifying Cleansing Balm pruža ne samo dubinsko čišćenje, već i osveženje za kožu nakon dugog dana. Njegova bogata, šerbetasta tekstura lako se transformiše u ulje, otapajući čak i najuporniju šminku i SPF. Ulje se tokom ispiranja pretvara u mlečnu emulziju, koja uklanja sve nečistoće bez narušavanja prirodne vlažnosti kože. Zahvaljujući pažljivo odabranim sastojcima, balzam pomaže u jačanju barijere kože, smanjuje crvenilo i iritacije. Redovnom upotrebom, koža postaje glatka, ujednačena i vidno blistavija. Idealno je rešenje za svakodnevnu rutinu nege, pružajući balans između dubinskog čišćenja i umirujuće nege! Aktivni sastojci Ekstrakt divlje jagode Ekstrakt divlje jagode bogat je antioksidansima, vitaminom C i voćnim kiselinama koje pomažu u osvetljavanju i revitalizaciji kože. Deluje blago eksfolirajuće, uklanjajući mrtve ćelije i pospešujući obnavljanje kože. Takođe ima adstringentna svojstva, što pomaže u sužavanju pora i kontroli viška sebuma. Zahvaljujući svojim protivupalnim svojstvima, umiruje kožu i doprinosi ujednačenijem tenu. Podržava zdrav mikrobiom kože i ostavlja kožu svežom i osvetljenom. Nakon čišćenja, koža je glatka, čista i prirodno blistava. Ekstrakt trešnje Ekstrakt trešnje bogat je vitaminima A i C, koji pomažu u posvetljavanju tena i zaštiti kože od slobodnih radikala. Ima snažno antioksidativno i umirujuće dejstvo, što je korisno kod umorne i nadražene kože. Takođe sadrži prirodne kiseline koje pomažu u blagom čišćenju i osveženju kože. Deluje hidratantno i doprinosi poboljšanju elastičnosti kože. U balzamima za čišćenje, pomaže u smanjenju upalnih procesa i umanjuje efekat iritacija. Koža nakon upotrebe izgleda odmorno, osvetljeno i revitalizovano. Ekstrakt ploda &#8220;vitaminskog drveta&#8221; (Sea Buckthorn) Ekstrakt ploda &#8220;vitaminskog drveta&#8221; izuzetno je bogat vitaminima C, E i omega masnim kiselinama koje hrane i štite kožu. Pomaže u jačanju zaštitne barijere kože i poboljšava njenu otpornost na spoljne faktore. Ima sposobnost da balansira proizvodnju sebuma i umanji pojavu nepravilnosti. Doprinosi ujednačenijem tenu i ubrzava regeneraciju ćelija. Takođe deluje umirujuće i pomaže u smanjenju crvenila. Rezultat je koža koja izgleda zdravije, svetlije i zaštićeno. Dodaj u listu želja Dodaj u listu želja', 'House of Hur Purifying Cleansing Balm je trofazno sredstvo za čišćenje koje se transformiše iz balzama u ulje, a zatim u mleko, efikasno uklanjajući šminku, SPF i nečistoće. Ovaj balzam dubinski čisti kožu, održava njen prirodni balans i pruža osećaj svežine bez zatezanja.', 'https://beauty-health.rs/wp-content/uploads/2024/12/House-of-Hur-Purifying-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
