INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1300, 48, 'Dr. Althea 345 Relief Cream', 'dr-althea-345-relief-cream', 'Ključne prednosti: Smanjuje fleke i ujednačava ten: Visoka koncentracija niacinamida (10.000 ppm) pomaže u smanjenju tamnih mrlja i ujednačavanju tena. Intenzivna hidratacija i obnova barijere: Pantenol (10.000 ppm) pruža dubinsku hidrataciju, umiruje crvenilo i jača zaštitnu barijeru kože. Umiruje iritacije i crvenilo: Ekstrakt stabljike opuncije (10.000 ppm) pruža izuzetnu hidrataciju, idealnu za suvu ili osetljivu kožu. Kome je namenjena? Ova krema je idealna za osobe sa suvom, osetljivom ili kombinovanom kožom, posebno onima koji se suočavaju sa post-aknama, crvenilom ili iritacijama. Zašto volimo Dr. Althea 345 Relief Cream? 345 Relief Cream kombinuje moćne sastojke kako bi pružila sveobuhvatnu negu kože. Niacinamid poboljšava barijeru kože, reguliše proizvodnju sebuma i smanjuje pojavu tamnih mrlja, dok panthenol hidrira i umiruje iritacije. Ekstrakt opuncije pruža dodatnu hidrataciju, čineći kožu mekom i elastičnom. Ova krema je formulisana bez veštačkih boja i mirisa, što je čini pogodnom za osetljivu kožu. Njena lagana tekstura omogućava brzo upijanje bez masnog osećaja, ostavljajući kožu osveženom i negovanom. Aktivni sastojci Niacinamid Niacinamid, poznat i kao vitamin B3, višestruko deluje na poboljšanje zdravlja kože. Pomaže u jačanju kožne barijere, smanjujući transepidermalni gubitak vlage i poboljšavajući hidrataciju. Efikasan je u regulaciji proizvodnje sebuma, što ga čini pogodnim za kožu sklonu aknama. Takođe doprinosi ujednačavanju tena smanjujući tamne fleke, hiperpigmentacije i crvenilo. Njegova antiinflamatorna svojstva pomažu u smirivanju iritacija i poboljšavaju opšte stanje osetljive kože. Panthenol Panthenol, ili provitamin B5, je sastojak poznat po svojoj sposobnosti da dubinski hidrira i umiri kožu. Deluje kao humektant, zadržavajući vlagu u koži i sprečavajući isušivanje. Ima regenerativna svojstva, podstičući obnavljanje oštećenog epidermisa i ubrzavajući zaceljivanje manjih iritacija. Njegovo dejstvo je posebno korisno nakon akni ili dermatoloških tretmana. Umiruje crvenilo i upalne procese, čineći ga izuzetno pogodnim za osetljivu ili reaktivnu kožu. Opuntia Ficus-Indica Stem Extract Ekstrakt stabljike opuncije (kaktusa) poznat je po svojim izuzetnim hidratantnim i umirujućim svojstvima. Bogat je antioksidansima, polisaharidima i flavonoidima koji štite kožu od oksidativnog stresa i gubitka vlage. Efikasan je u ublažavanju suvoće, iritacija i crvenila, naročito kod osetljive kože. Njegova sposobnost da zadrži vodu u koži doprinosi dugotrajnoj hidrataciji i poboljšanju tonusa. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea 345 Relief Cream je lagana, regenerativna krema bogata hranljivim sastojcima, namenjena smirivanju iritacija, hidrataciji i obnavljanju kože nakon akni.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Dr.-Althea-345-Relief-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
