INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1304, 48, 'Dr. Althea Pure Grinding Cleansing Balm', 'dr-althea-pure-grinding-cleansing-balm', 'Ključne prednosti: Efikasno uklanjanje nečistoća: Uklanja čak i vodootpornu šminku i višak sebuma, ostavljajući kožu savršeno čistom. Dubinska hidratacija: Održava prirodnu vlažnost kože zahvaljujući hranljivim uljima i biljnim ekstraktima. Prijatelj za osetljivu kožu: Formulisan bez iritansa, pogodan je za sve tipove kože, uključujući i najosetljiviju. Kome je namenjen? Ovaj balzam je savršen za osobe sa suvom, masnom ili kombinovanom kožom koje traže nežno, ali efikasno rešenje za uklanjanje šminke. Idealan je za korisnike svih starosnih grupa koji žele temeljno čišćenje uz hidrataciju. Zašto volimo Dr. Althea Pure Grinding Cleansing Balm? Pure Grinding Cleansing Balm transformiše rutinu čišćenja lica u luksuzni spa doživljaj. Njegova bogata tekstura se na koži topi u uljnu formu, razlažući tvrdokornu šminku i nečistoće. Zahvaljujući pažljivo odabranim prirodnim sastojcima, ne samo da čisti, već i neguje kožu, čineći je mekanom i blistavom. Pri upotrebi ovog balzama, koža ostaje hidrirana, bez osećaja zategnutosti, dok njegova lagana formula ne ostavlja masni trag. Uz redovnu upotrebu, koža postaje zdravija, uravnoteženija i bolje pripremljena za dalju negu. Aktivni sastojci Vitis Vinifera (Grape) Seed Oil Ulje semenki grožđa bogato je linolnom kiselinom, antioksidansima i vitaminom E, što ga čini idealnim za nežno, ali dubinsko čišćenje kože. Efikasno razgrađuje šminku, SPF i nečistoće bez narušavanja prirodne barijere kože. Njegova lagana tekstura ne ostavlja mastan film i pogodna je čak i za masnu i aknoznu kožu. Deluje protivupalno i pomaže u smanjenju crvenila i upala. Camellia Sinensis Seed Oil Ulje semena zelenog čaja ima snažna antioksidativna svojstva zahvaljujući prisustvu polifenola i vitamina. Dubinski hidrira i hrani kožu, ostavljajući je mekom i elastičnom nakon čišćenja. Njegova umirujuća svojstva smanjuju crvenilo i iritacije, što ga čini pogodnim i za osetljivu kožu. Takođe pomaže u zaštiti kože od slobodnih radikala i štetnih uticaja iz spoljašnje sredine. Pruža osećaj ugodnosti i ne zateže kožu nakon ispiranja. Madecassoside Madecassoside je aktivna komponenta iz biljke Centella Asiatica i poznat je po svom snažnom umirujućem i protivupalnom delovanju. Pomaže u smanjenju crvenila, iritacija i upalnih procesa, posebno kod osetljive i reaktivne kože. Takođe podstiče regeneraciju kože i jača kožnu barijeru. Dodaj u listu želja Dodaj u listu želja', 'Dr. Althea Pure Grinding Cleansing Balm je balzam za čišćenje koji temeljno uklanja šminku i nečistoće dok istovremeno hidrira i hrani kožu. Njegova veganska formula pruža dubinsku negu bez iritacija, čineći ga idealnim za svakodnevnu upotrebu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Dr.-Althea-Pure-Grinding-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
