INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1305, 50, 'Dr.G Black Snail Retinol Ampoule', 'dr-g-black-snail-retinol-ampoule', 'Ključne prednosti: Podstiče regeneraciju kože: Retinol pospešuje obnavljanje ćelija, smanjuje fine linije i bore. Dubinska hidratacija: Crna puževa sluz pruža intenzivnu hidrataciju, jača barijeru kože i umiruje iritacije. Ujednačava ton kože: Smanjuje hiperpigmentaciju i osvetljava kožu za zdrav i blistav izgled. Kome je namenjen? Namenjen je osobama sa zrelim kožom, neujednačenim tonom, borama ili suvoćom. Idealan je za sve tipove kože, uključujući i osetljivu, zahvaljujući umirujućim svojstvima puževe sluzi. Zašto volimo Dr.G Black Snail Retinol Ampoule? Ova ampula kombinuje snagu prirodnih i aktivnih sastojaka za sveobuhvatnu negu kože. Retinol, poznat po svojim regenerativnim svojstvima, pomaže u smanjenju bora i pospešuje prirodni kolagen, čineći kožu čvršćom. Crna puževa sluz obogaćena je hranljivim proteinima i elastinom, pružajući dubinsku hidrataciju i umirujući iritacije. Dugotrajnom upotrebom, koža postaje ujednačenija, a tamne mrlje manje vidljive. Ovaj proizvod dodatno obnavlja oštećenja od sunca i umiruje crvenilo. Njegova lagana tekstura brzo se upija, ostavljajući kožu glatkom i hidriranom bez masnog osećaja. Aktivni sastojci Retinol Retinol je jedan od najefikasnijih sastojaka u borbi protiv znakova starenja. On stimuliše proizvodnju kolagena, čime poboljšava elastičnost i čvrstinu kože. Deluje dubinski i ubrzava obnavljanje ćelija, što doprinosi glađem i ujednačenijem tenu. Takođe pomaže u smanjenju vidljivosti finih linija, bora i hiperpigmentacija. Peptidi Peptidi su kratki lanci aminokiselina koji deluju kao signalne molekule za obnavljanje kože. Oni stimulišu sintezu kolagena i elastina, čime se povećava čvrstina i zategnutost kože. Peptidi pomažu u smanjenju vidljivosti bora i poboljšanju opšteg tonusa kože. Black Snail Crni puž je bogat mukinom, hijaluronskom kiselinom, cinkom i glikolnom kiselinom, što ga čini izuzetnim u regeneraciji kože. Pomaže u zarastanju oštećenja, smanjenju ožiljaka i poboljšanju opšteg stanja kože. Njegova sekretorna filtracija pospešuje hidrataciju, čineći kožu glatkom i elastičnom. Crni puž ima viši nivo izlučivanja sluzi u poređenju s običnim, što dodatno pojačava njegov efekat. Active Mucin Aktivni mucin je visokokoncentrisani sekret puževe sluzi sa snažnim regenerativnim svojstvima. Deluje tako što obnavlja oštećenu kožu, smanjuje crvenilo i iritacije. Takođe pomaže u zadržavanju vlage, čime koža postaje hidriranija i punija. Mucin pospešuje obnavljanje ćelija i utiče na smanjenje ožiljaka i teksturalnih nepravilnosti. Dodaj u listu želja Dodaj u listu želja', 'Dr.G Black Snail Retinol Ampoule kombinuje snagu retinola i crne puževe sluzi kako bi podstakao regeneraciju kože, smanjio vidljivost bora i neujednačen ton. Njegova bogata formula dubinski hrani i hidrira kožu, ostavljajući je glatkom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Dr.G-Black-Snail-Retinol-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
