INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1306, 50, 'Dr.G pH Cleansing Gel Foam', 'dr-g-ph-cleansing-gel-foam', 'Ključne prednosti: Dubinsko čišćenje bez iritacije: Efikasno uklanja nečistoće, uključujući sitnu prašinu i ostatke šminke, bez isušivanja ili iritacije kože. Jačanje kožne barijere: Sadrži MultiProbio kompleks sa probiotskim sastojcima koji pomažu u jačanju i održavanju zdrave kožne barijere. Održavanje optimalne pH vrednosti: Formulisan sa blagom, slabo kiselom pH vrednošću koja odgovara prirodnoj pH ravnoteži kože, čime se smanjuje rizik od iritacija. Kome je namenjena? Ovaj gel za čišćenje pogodan je za sve tipove kože, uključujući osetljivu i sklonu iritacijama. Preporučuje se osobama koje traže efikasno, ali blago sredstvo za svakodnevno čišćenje lica koje neće narušiti prirodnu ravnotežu kože. Zašto volimo Dr.G pH Cleansing Gel Foam? pH Cleansing Gel Foam pruža temeljno čišćenje koje uklanja nečistoće poput sitne prašine i ostataka šminke, dok istovremeno održava kožu hidriranom i mekom. Njegova jedinstvena formula, obogaćena MultiProbio kompleksom, jača kožnu barijeru. Blaga, slabo kisela pH vrednost osigurava da se prirodna ravnoteža kože ne narušava tokom čišćenja, smanjujući rizik od iritacija. Gel se lako pretvara u bogatu, mekanu penu koja pruža osvežavajući osećaj i ostavlja kožu čistom, glatkom i zdravom. Aktivni sastojci Pollen Extract™ Patentirani Pollen Extract™ je prirodni kompleks bogat vitaminima, amino-kiselinama i antioksidansima koji dubinski hrane i štite kožu. Deluje umirujuće i istovremeno jača kožnu barijeru, čineći je otpornijom na spoljne uticaje. Zahvaljujući svojim hidratantnim svojstvima, sprečava osećaj zatezanja nakon čišćenja. Takođe pomaže u obnavljanju kože, posebno kod osetljive i dehidrirane kože. Njegov bogat nutritivni profil pruža koži potrebnu energiju i blistav izgled. Surfactant Complex (Mild pH-Based) Blagi surfaktanti sa pH vrednošću bliskom koži omogućavaju efikasno, ali nežno uklanjanje nečistoća bez narušavanja prirodne zaštitne barijere. Ovi sastojci ne isušuju kožu i ne izazivaju iritaciju, što ih čini pogodnim za sve tipove, uključujući osetljivu kožu. Formulacija je pH-uravnotežena kako bi podržala zdrav mikrobiom i optimalnu funkciju kože. Osiguravaju čistoću bez osećaja suvoće ili zatezanja. Dodaj u listu želja Dodaj u listu želja', 'Dr.G pH Cleansing Gel Foam je blagi gel za čišćenje lica koji efikasno uklanja nečistoće, dok istovremeno održava prirodnu ravnotežu pH vrednosti kože. Obogaćen je MultiProbio kompleksom koji jača kožnu barijeru i pruža hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Dr.G-pH-Cleansing-Gel-Foam.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
