INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1307, 40, 'Cosrx The Vitamin C 23 Serum', 'cosrx-the-vitamin-c-23-serum', 'Ključne prednosti: Poboljšava elastičnost kože: Visoka koncentracija vitamina C podstiče sintezu kolagena. Ujednačava ten: Redovnom upotrebom smanjuje pojavu tamnih mrlja i hiperpigmentacija. Smanjuje bore i fine linije: Antioksidativna svojstva vitamina C pomažu u borbi protiv slobodnih radikala. Kome je namenjena? Ovaj serum je idealan za osobe sa normalnom do suvom kožom. Posebno za one koje se suočavaju sa problemima neujednačenog tena, hiperpigmentacije ili ranim znacima starenja. Zašto volimo COSRX The Vitamin C 23 Serum? The Vitamin C 23 Serum pruža intenzivnu negu zahvaljujući visokoj koncentraciji čistog vitamina C, poznatog po svojoj sposobnosti da posvetli kožu i smanji hiperpigmentacije. Redovnom upotrebom, serum stimuliše sintezu kolagena, što rezultira čvršćom i elastičnijom kožom sa smanjenom pojavom finih linija i bora. Dodatno, antioksidativna svojstva vitamina C štite kožu od štetnih efekata slobodnih radikala, smanjujući oštećenja izazvana UV zračenjem i zagađenjem. Formulacija seruma uključuje i hidratantne sastojke koji obezbeđuju optimalnu hidrataciju. Ovaj serum je posebno koristan za one koji žele da poboljšaju ujednačenost tena i smanje vidljivost tamnih fleka. Aktivni sastojci Vitamin C (23% L-askorbinska kiselina) L-askorbinska kiselina je najčistiji i najaktivniji oblik vitamina C, poznat po snažnom antioksidativnom delovanju. Štiti kožu od oksidativnog stresa i slobodnih radikala, čime usporava proces starenja. Pomaže u posvetljavanju hiperpigmentacija, ujednačavanju tena i smanjenju tamnih mrlja. Stimuliše sintezu kolagena, poboljšavajući elastičnost i čvrstoću kože. Redovnom upotrebom smanjuje fine linije i bore, dok istovremeno osvetljava i revitalizuje kožu. Zbog visoke koncentracije (23%), serumu je potrebna postepena adaptacija uz obaveznu dnevnu SPF zaštitu. Tokotrienol (Super vitamin E) Tokotrienol je napredna forma vitamina E sa do 50 puta jačim antioksidativnim delovanjem u poređenju sa tokoferolom. Deluje zaštitno i regenerativno, štiteći ćelijske membrane od oksidativnog oštećenja. Pomaže u stimulaciji sinteze kolagena, čime dodatno doprinosi učvršćivanju kože i smanjenju bora. U kombinaciji sa vitaminom C pojačava stabilnost i efikasnost formule. Ublažava upale i ubrzava oporavak kože izložene UV zračenju i zagađenju. Obezbeđuje anti-age podršku i doprinosi zdravijem, osvetljenijem tenu. Hijaluronska kiselina Hijaluronska kiselina je moćan hidratant koji zadržava vlagu u dubljim slojevima kože, čime pruža trenutno i dugotrajno osveženje. Pomaže u popunjavanju finih linija, čineći kožu glatkom, punijom i elastičnijom. Jača kožnu barijeru i štiti je od dehidratacije, naročito kod upotrebe aktivnih sastojaka poput vitamina C. Lako se apsorbuje bez osećaja težine, pa je pogodna za sve tipove kože. Održava kožu hidriranom, što je ključno za ujednačen ton i zdrav sjaj. Dodaj u listu želja Dodaj u listu želja', 'COSRX The Vitamin C 23 Serum je visoko koncentrovani serum sa 23% čistog vitamina C, formulisan da poboljša tonus kože, smanji bore i revitalizuje umornu kožu pružajući joj blistavost.', 'https://beauty-health.rs/wp-content/uploads/2024/12/COSRX-The-Vitamin-C-23-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
