INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1308, 40, 'Cosrx Full Fit Propolis Synergy Toner', 'cosrx-full-fit-propolis-synergy-toner', 'Ključne prednosti: Duboka hidratacija i umirenje: Bogat sadržaj propolisa i meda smiruje iritacije i pruža intenzivnu hidrataciju. Poboljšanje teksture i elastičnosti: Podstiče regeneraciju kože, čineći je mekšom i elastičnijom. Prirodan sjaj i zaštita: Doprinosi zdravom sjaju kože i jača barijeru za dugotrajnu otpornost na spoljašnje uticaje. Kome je namenjen? Toner je pogodan za sve tipove kože, uključujući osetljivu i dehidriranu kožu. Namenjen je osobama koje žele da umire iritacije, regenerišu oštećenu kožu i postignu blistav i zdrav izgled. Zašto volimo COSRX Full Fit Propolis Synergy Toner? Full Fit Propolis Synergy Toner unosi novi nivo luksuzne hidratacije u vašu rutinu nege kože. Sadrži visok procenat propolisa i ekstrakta meda, koji zajedno deluju na umirivanje crvenila i poboljšanje elastičnosti kože. Ovaj toner lagane teksture duboko prodire u kožu, ostavljajući je osveženom i osnaženom. Idealno balansirana formula jača zaštitnu barijeru kože, smanjujući gubitak vlage tokom dana. Pored toga, doprinosi ravnomernom tenu i smanjuje vidljivost finih linija. Bez obzira na to da li se koristi samostalno ili kao deo slojevite rutine, toner pruža dugotrajan efekat svežine i zdravog sjaja. Aktivni sastojci Ekstrakt propolisa (72.6%) Ekstrakt propolisa bogat je flavonoidima i antioksidansima koji pomažu u zaštiti kože od oksidativnog stresa i spoljašnjih agresora. Deluje umirujuće, smanjuje crvenilo i poboljšava regeneraciju kože, što je posebno korisno za umornu i osetljivu kožu. Jača kožnu barijeru, pomažući u zadržavanju vlage i sprečavanju isušivanja. Obezbeđuje bogatu ishranu, čineći kožu elastičnijom i otpornijom. Redovnom upotrebom doprinosi zdravijem tenu i boljoj teksturi kože. Idealan je za one koji traže balans između hidratacije i zaštite. Ekstrakt meda (10.7%) Ekstrakt meda deluje kao prirodni humektant, zadržavajući vlagu i poboljšavajući hidrataciju kože. Sadrži enzime, vitamine i antioksidanse koji revitalizuju kožu i vraćaju joj prirodan sjaj. Ima antibakterijska i umirujuća svojstva, što je čini pogodnim za kožu sklonu aknama i iritacijama. Pomaže u održavanju ujednačenog tona kože i doprinosi njenoj mekoći i elastičnosti. Kombinovan sa propolisom, dodatno jača efekat nege i obnove. Obezbeđuje energiju i svežinu umornoj i dehidriranoj koži. Panthenol (0.2%) Panthenol, ili provitamin B5, poznat je po svojim hidratantnim i umirujućim svojstvima. Pomaže u zadržavanju vlage u koži, smanjujući suvoću i perutanje. Deluje protivupalno i pomaže u regeneraciji oštećene kože, umirujući iritacije i crvenilo. Jača prirodnu zaštitnu barijeru kože, poboljšavajući njenu otpornost. Njegova lagana, neiritirajuća formula čini ga pogodnim za sve tipove kože, uključujući osetljivu. U kombinaciji sa propolisom i medom doprinosi optimalnoj hidrataciji, zaštiti i umirenju kože. Dodaj u listu želja Dodaj u listu želja', 'COSRX Full Fit Propolis Synergy Toner je lagan, ali bogat toner sa 72,6% ekstrakta propolisa i 10% ekstrakta meda, kreiran za dubinsku hidrataciju i umirivanje kože, dok istovremeno poboljšava njenu elastičnost i prirodni sjaj. Idealan je za osetljivu i dehidriranu kožu koja traži dodatnu negu.', 'https://beauty-health.rs/wp-content/uploads/2024/12/COSRX-Full-Fit-Propolis-Synergy-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
