INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1309, 40, 'Cosrx Salicylic Acid Daily Gentle Cleanser', 'salicylic-acid-daily-gentle-cleanser', 'Ključne prednosti: Dubinsko čišćenje i kontrola sebuma: Salicilna kiselina prodire u pore, uklanjajući masnoće i mrtve ćelije kože. Umirujući efekat za iritiranu kožu: Sadrži prirodne ekstrakte koji smiruju crvenilo i iritacije. Ne isušuje kožu: Formula obogaćena hidratantnim sastojcima održava kožu mekom i elastičnom čak i nakon svakodnevne upotrebe. Kome je namenjen? Namenjen je osobama sa masnom i kombinovanom kožom, sklonom aknama i miteserima, ali je dovoljno blag za sve tipove kože. Zašto volimo Salicylic Acid Daily Gentle Cleanser? Njegova nežna pena dubinski čisti pore i uklanja masnoće koje često uzrokuju začepljenja. Salicilna kiselina se postepeno otpušta, tretirajući problematična područja bez iritacije. Zahvaljujući pažljivo biranim hidratantnim sastojcima, koža ostaje hidrirana i osvežena, umesto isušena. Umirujući biljni ekstrakti dodatno smanjuju crvenilo i sprečavaju iritacije, čineći proizvod pogodnim za svakodnevnu upotrebu. Ovaj čistač pruža osećaj čistoće i revitalizacije, pomažući koži da se vrati u svoju prirodnu ravnotežu. Aktivni sastojci Salicilna kiselina Salicilna kiselina (BHA) je sastojak koji dubinski prodire u pore i efikasno uklanja višak sebuma, mrtve ćelije i nečistoće. Deluje keratolitički, razlažući veze između mrtvih ćelija kože, čime se sprečava njihovo nakupljanje i stvaranje mitisera i bubuljica. Ima snažna protivupalna svojstva, zbog čega umiruje crvenilo i upale kod problematične kože. Redovnom upotrebom pomaže u smanjenju postojećih akni i sprečavanju novih izbijanja. Pored toga, poboljšava teksturu kože i doprinosi ujednačenijem tenu. Pogodna je za masnu, mešovitu i aknama sklonu kožu. Ulje čajevca (Tea Tree Oil) Ulje čajevca je prirodni antibakterijski i antiseptički sastojak koji deluje direktno na bakterije odgovorne za akne. Efikasno smanjuje upale, crvenilo i iritacije, dok istovremeno balansira proizvodnju sebuma. Pomaže u pročišćavanju kože i sužavanju pora bez agresivnog isušivanja. Takođe pospešuje proces zarastanja kože i smanjuje rizik od nastanka ožiljaka. Njegova umirujuća svojstva čine ga pogodnim za svakodnevnu upotrebu, čak i kod osetljivije problematične kože. U kombinaciji sa salicilnom kiselinom, pruža snažan, ali blag efekat čišćenja i nege. Dodaj u listu želja Dodaj u listu želja', 'COSRX Salicylic Acid Daily Gentle Cleanser j e blaga pena za čišćenje lica koja efikasno uklanja višak sebuma, nečistoće i mrtve ćelije kože, dok salicilna kiselina dubinski čisti pore. Idealna je za svakodnevnu upotrebu, pružajući osvežavajući i umirujući efekat bez isušivanja kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/COSRX-Salicylic-Acid-Daily-Gentle-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
