INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1312, 39, 'Cos De BAHA Arbutin Niacinamide Serum', 'cos-de-baha-arbutin-niacinamide-serum', 'Ključne prednosti: Ujednačava ten: Arbutin smanjuje hiperpigmentacije i tamne mrlje, ostavljajući kožu blistavom. Smanjuje upale: Niacinamid smanjuje crvenilo, akne i iritacije, dok jača kožnu barijeru. Dubinska hidratacija: Hijaluronska kiselina osigurava optimalnu hidrataciju i pomaže zadržavanju vlage. Kome je namenjen? Pogodan za sve tipove kože, uključujući masnu, mešovitu i osetljivu kožu. Posebno je dizajniran za osobe koje žele smanjiti hiperpigmentacije, akne i fine linije. Zašto volimo Cos De BAHA Arbutin Niacinamide Serum? Arbutin Niacinamide Serum deluje na višestruke probleme kože zahvaljujući pažljivo odabranim sastojcima. Arbutin, poznat po svojim moćnim svojstvima posvetljivanja kože, efikasno smanjuje tamne mrlje i pigmentacije, dok niacinamid deluje umirujuće, smanjujući upale i regulisanje sebuma. Hijaluronska kiselina dubinski hidrira kožu, ostavljajući je mekom i osveženom. Dugotrajnom upotrebom, ovaj serum pomaže u izgradnji jače kožne barijere, poboljšava teksturu i vraća koži prirodni sjaj. Bez iritansa i bez teškog osećaja, serum se lako integriše u dnevnu i noćnu rutinu, pružajući vidljive rezultate već nakon nekoliko nedelja. Aktivni sastojci Arbutin (5%) Arbutin je prirodni derivat hidrohinona koji deluje na posvetljivanje kože bez iritacija i neželjenih efekata. Pomaže u inhibiciji enzima tirozinaze, koji je odgovoran za proizvodnju melanina, čime smanjuje hiperpigmentacije, tamne mrlje i ožiljke od akni. Ovaj sastojak pruža ujednačen ten i doprinosi blistavijem izgledu kože. Takođe, arbutin ima antioksidativna svojstva koja štite kožu od oštećenja izazvanih slobodnim radikalima. Njegova blaga priroda čini ga pogodnim za osetljivu kožu. Redovna upotreba može pomoći u sprečavanju pojave novih tamnih mrlja. Niacinamid (5%) Niacinamid, poznat i kao vitamin B3, pomaže u smanjenju upala i crvenila, što je korisno za kožu sklonu aknama i iritacijama. Reguliše proizvodnju sebuma, smanjujući masni sjaj i proširene pore. Takođe poboljšava funkciju kožne barijere, čineći je otpornijom na spoljašnje faktore. Njegova sposobnost da inhibira proizvodnju melanina pomaže u smanjenju hiperpigmentacija i ujednačavanju tena. Niacinamid deluje kao antioksidans, štiteći kožu od oksidativnog stresa i prevremenog starenja. Blag je i dobro podnošljiv, što ga čini pogodnim za sve tipove kože. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA Arbutin Niacinamide Serum kombinuje 5% arbutina i niacinamida sa hijaluronskom kiselinom kako bi smanjio hiperpigmentacije, ujednačio ten i pružio intenzivnu hidrataciju. Idealan je za borbu protiv tamnih mrlja, akni i starenja kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Cos-De-BAHA-Arbutin-Niacinamide-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
