INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1320, 31, 'Celimax Noni Energy Ampoule', 'celimax-noni-energy-ampoule', 'Ključne prednosti: Dubinska hidratacija: Visok sadržaj noni ekstrakta pruža intenzivnu hidrataciju, poboljšavajući elastičnost kože. Antioksidativna zaštita: Prisustvo antioksidanata štiti kožu od slobodnih radikala i usporava proces starenja. Umirujuće dejstvo: Formulacija sa ruzmarinovim uljem smiruje iritacije i crvenilo, ostavljajući kožu osveženom. Kome je namenjen? Idealan za sve tipove kože, posebno za one sa suvom, dehidriranom ili umornom kožom koja pokazuje prve znake starenja. Zašto volimo Celimax Noni Energy Ampoule? Noni Energy Ampoule pruža dubinsku negu zahvaljujući bogatstvu hranljivih sastojaka iz ploda nonija, koji je poznat po svojim regenerativnim i antioksidativnim svojstvima. Redovnom upotrebom, koža postaje hidrirana i osvežena, sa poboljšanom elastičnošću i čvrstoćom. Ekstrakt nonija, bogat esencijalnim vitaminima i mineralima, pomaže u revitalizaciji umorne kože, dok adenozin doprinosi smanjenju vidljivih znakova starenja. Formulacija sadrži i ruzmarinovo ulje, koje umiruje iritacije i pomaže u postizanju ujednačenog tena. Ceramidi dodatno ojačavaju kožnu barijeru, štiteći je od gubitka vlage i spoljnih stresora. Ova ampula ima laganu teksturu koja se brzo upija, ostavljajući kožu blistavom i mekom na dodir, bez osećaja težine. Aktivni sastojci Ekstrakt ploda nonija (Morinda Citrifolia) (71,77%) Ekstrakt ploda nonija je bogat izvor preko 300 različitih hranljivih materija, uključujući vitamine, minerale i aminokiseline. Ovaj sastojak pruža snažnu antioksidativnu zaštitu, štiteći kožu od oštećenja izazvanih slobodnim radikalima i prevremenog starenja. Takođe, poznat je po svojim umirujućim svojstvima koja pomažu u smanjenju iritacija i crvenila, čineći ga pogodnim za osetljivu kožu. Ekstrakt nonija hidrira i revitalizuje kožu, poboljšavajući njen tonus i teksturu. Ulje lista ruzmarina (Rosmarinus Officinalis) Ulje lista ruzmarina je poznato po svojim antiinflamatornim i antimikrobnim svojstvima, što ga čini korisnim u smirivanju iritacija i zaštiti kože od bakterijskih infekcija. Njegova antioksidativna svojstva pomažu u neutralisanju slobodnih radikala, čime se sprečava oštećenje ćelija i prevremeno starenje kože. Takođe, ulje ruzmarina može poboljšati cirkulaciju krvi, što doprinosi boljoj ishrani i detoksikaciji kože. Pruža osvežavajući efekat i može pomoći u toniranju kože, čineći je čvršćom i elastičnijom. Adenozin Adenozin je jedinjenje koje se prirodno nalazi u ćelijama i igra ključnu ulogu u energetskom metabolizmu. U kozmetici, poznat je po svojim anti-age svojstvima, jer pomaže u smanjenju pojave finih linija i bora stimulacijom sinteze kolagena i elastina. Takođe, ima umirujuća svojstva koja mogu smanjiti iritacije i crvenilo kože. Adenozin poboljšava elastičnost kože, čineći je čvršćom i glatkijom. Dodaj u listu želja Dodaj u listu želja', 'Celimax Noni Energy Ampoule je visokokoncentrovani serum koji sadrži 71,77% ekstrakta ploda nonija, bogatog vitaminima i mineralima, namenjen revitalizaciji i hidrataciji kože.', 'https://beauty-health.rs/wp-content/uploads/2024/12/Celimax-Noni-Energy-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
