INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1332, 22, 'Beauty of Joseon Ginseng Moist Sun Serum', 'beauty-of-joseon-ginseng-moist-sun-serum', 'Ključne prednosti: Intenzivna hidratacija: Ekstrakt žen-šena dubinski hrani kožu, poboljšavajući njenu elastičnost i vitalnost. Ujednačavanje tena: Niacinamid pomaže u smanjenju hiperpigmentacija, ostavljajući kožu blistavom i ujednačenom. Neostavljajući beli trag: Lagana formula se brzo upija, ne ostavljajući masni osećaj niti beli trag na koži. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući osetljivu, i namenjen je osobama koje traže visoku UV zaštitu uz dodatne benefite nege kože, poput hidratacije i ujednačavanja tena. Zašto volimo Beauty of Joseon Ginseng Moist Sun Serum? Zahvaljujući visokom sadržaju žen-šena, ovaj serum pruža efikasnu zaštitu od sunca i istovremeno dubinski hrani kožu. N a taj način poboljšava njenu elastičnost i vitalnost. Niacinamid u formuli doprinosi smanjenju tamnih mrlja i hiperpigmentacija, pružajući koži ujednačen i blistav ten. Lagana tekstura seruma omogućava brzo upijanje. Ovo ga čini idealnim izborom za sve tipove kože, uključujući osetljivu. Redovnom upotrebom, koža postaje mekša, hidrirana i zaštićena od štetnih UV zraka, dok istovremeno zadržava prirodni sjaj i zdrav izgled. Serum ne ostavlja masni osećaj niti beli trag, što ga čini savršenim i kao baza za šminku. Aktivni sastojci Ekstrakt ginsenga (30%) Ekstrakt ginsenga bogat je saponinima, koji pomažu u intenzivnoj hidrataciji kože i održavanju vlage duboko u njenim slojevima. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i pomažu u sprečavanju prevremenog starenja. Takođe, ginseng poboljšava cirkulaciju kože, što doprinosi zdravijem i blistavijem tenu. Ekstrakti ginsengovih bobica i crvenog ginsenga dodatno pojačavaju anti-age dejstvo, čineći kožu elastičnijom i čvršćom. Njegova umirujuća svojstva pomažu u smanjenju iritacija, čineći ga pogodnim za osetljivu kožu. Redovna upotreba proizvoda sa ginsengom može doprineti regeneraciji kože i smanjenju pojave finih linija i bora. Adenozin Adenozin je vodorastvoran sastojak dobijen iz kvasca, poznat po svojoj sposobnosti da poboljša elastičnost kože i smanji vidljivost bora. Pomaže u regeneraciji kože, stimulišući ćelijsku aktivnost i ubrzavajući proces obnove kože. Takođe, ima umirujuća svojstva koja smanjuju crvenilo i iritacije, čineći ga pogodnim za osetljivu kožu. Njegova anti-age svojstva pomažu u jačanju strukture kože, poboljšavajući njen tonus i čvrstoću. Adenozin je siguran za sve tipove kože i efikasan je u tretiranju znakova starenja. Redovna upotreba ovog sastojka može doprineti zaglađenijoj i mladalačkijoj koži. SPF i PA zaštita Beauty of Joseon Ginseng Moist Sun Serum pruža visoku zaštitu od UV zračenja, potvrđenu testiranjima u laboratorijama u Koreji i Španiji. SPF testiranje pokazalo je zaštitni faktor od 57.6±3.9 (Koreja) i 60.3±10.5 (Španija), što osigurava efikasnu UVB zaštitu. PA testiranje je pokazalo vrednosti UVA PF 18.0±2.1 (Koreja) i UVA PF 26.4±4.2 (Španija), sa oznakom P++++, što znači veoma visoku zaštitu od UVA zraka. Ova visoka zaštita pomaže u sprečavanju fotostarenja, hiperpigmentacija i oštećenja kože uzrokovanih UV zračenjem. Ovaj lagani sun serum kombinuje anti-age benefite ginsenga i adenozina sa visokom zaštitom od sunca, pružajući hidrataciju, elastičnost i dugotrajnu negu. Pogodan je za sve tipove kože, uključujući suvu i osetljivu Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Ginseng Moist Sun Serum (SPF 50+ PA++++) je lagani, hidratantni serum za zaštitu od sunca, obogaćen sa 30% ekstrakta žen-šena i 2% niacinamida, pružajući visoku UV zaštitu uz negu kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Beauty-of-Joseon-Ginseng-Moist-Sun-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
