INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1333, 22, 'Beauty of Joseon Green Plum Refreshing Toner', 'beauty-of-joseon-green-plum-refreshing-toner', 'Ključne prednosti: Nežno eksfolira kožu: AHA i BHA uklanjaju mrtve ćelije kože i čiste pore. Hidrira i umiruje: Ekstrakt mung pasulja i voda zelenih šljiva pružaju hidrataciju i umiruju iritacije. Poboljšava sjaj kože: Redovnom upotrebom, toner posvetljuje ten i vraća prirodni sjaj kože. Kome je namenjen? Ovaj toner je idealan za osobe sa normalnom, masnom ili kombinovanom kožom. Posebno za one koji se bore sa neujednačenom teksturom, začepljenim porama ili blagim hiperpigmentacijama. Zašto volimo Beauty of Joseon Green Plum Refreshing Toner? Glavni sastojak ovog tonera je voda zelenih šljiva, tradicionalni korejski sastojak poznat po svojim osvežavajućim svojstvima. Kombinacija AHA i BHA kiselina deluje sinergijski kako bi uklonila površinske nečistoće i dubinski očistila pore, čineći kožu glatkom i čistom. Ekstrakt mung pasulja dodatno umiruje kožu, smanjujući crvenilo i iritacije. Redovna upotreba ovog tonera pomaže u smanjenju pojave sitnih linija i bora. Istovremeno posvetljuje ten, vraćajući mu mladalački sjaj. Aktivni sastojci Prunus Mume Fruit Water Prunus Mume , poznata kao zelena šljiva ili japanska kajsija, tradicionalno se koristi u azijskoj medicini zbog svojih nutritivnih i zdravstvenih benefita. Kao sastojak u kozmetici, voda ploda Prunus Mume bogata je vitaminima A, B i C, koji pomažu u hidrataciji i revitalizaciji kože. Ovaj ekstrakt deluje kao humektant, privlačeći vlagu i održavajući kožu hidriranom. Ekstrakt Vigna Radiata semena Ekstrakt semena Vigna Radiata, poznatog kao mung pasulj, tradicionalno se koristi u azijskoj medicini zbog svojih umirujućih i hidratantnih svojstava. Bogat je proteinima, vitaminima i mineralima koji hrane kožu i poboljšavaju njen izgled. Pomaže u smirivanju iritacija i crvenila, te pruža dubinsku hidrataciju. Glikolna kiselina Glikolna kiselina je najpoznatiji alfa-hidroksi kiselina (AHA) koja se koristi za eksfolijaciju kože. Njena glavna uloga je uklanjanje površinskog sloja mrtvih ćelija kože, omogućavajući novim ćelijama da izađu na površinu. Ovaj proces poboljšava teksturu kože, smanjuje pojavu finih linija i bora, te ujednačava ten. Salicilna kiselina Salicilna kiselina je beta-hidroksi kiselina (BHA) poznata po svojoj sposobnosti da prodre duboko u pore i ukloni nakupljene nečistoće i sebum. Deluje kao eksfolijant, pomažući u uklanjanju mrtvih ćelija kože i sprečavanju začepljenja pora, što je posebno korisno za masnu i aknama sklonu kožu. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Green Plum Refreshing Toner kombinuje 25% vode zelenih šljiva sa AHA i BHA kiselinama kako bi nežno uklonio mrtve ćelije kože i nečistoće.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Beauty-of-Joseon-Green-Plum-Refreshing-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
