INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1334, 22, 'Beauty of Joseon Centella Asiatica Calming Mask', 'beauty-of-joseon-centella-asiatica-calming-mask', 'Ključne prednosti: Umiruje iritacije : Visok sadržaj Centella Asiatica ekstrakta pomaže u smirivanju upala i crvenila, pružajući olakšanje osetljivoj koži. Dubinska hidratacija : Tri vrste hijaluronske kiseline obezbeđuju intenzivnu hidrataciju, ostavljajući kožu mekom i elastičnom. Poboljšava teksturu kože : Biljni ekstrakti poput zelenog čaja i pelina doprinose osvežavanju tena i poboljšanju ukupnog izgleda kože. Kome je namenjena? Ova maska je idealna za osobe sa osetljivom, suvom ili iritiranom kožom, bez obzira na starosnu dob. Takođe je pogodna za one koji žele da poboljšaju hidrataciju i umire kožu nakon izlaganja spoljnim stresorima. Zašto volimo Beauty of Joseon Centella Asiatica Calming Mask? U srcu ove maske nalazi se 15% ekstrakta Centella Asiatica, poznatog po svojim umirujućim svojstvima koja pomažu u smanjenju crvenila i iritacija. Kombinacija zelenog čaja i pelina pruža dodatnu zaštitu od slobodnih radikala, čineći kožu osveženom i revitalizovanom. Tri vrste hijaluronske kiseline prodiru duboko u kožu, obezbeđujući dugotrajnu hidrataciju i poboljšavajući elastičnost. Tanka tencel maska savršeno prijanja uz lice, omogućavajući optimalnu apsorpciju aktivnih sastojaka. Redovnom upotrebom, koža postaje vidljivo smirenija, hidrirana i blistava, sa poboljšanom teksturom i tonom. Aktivni sastojci Ekstrakt Centella Asiatica (15%) Centella Asiatica, poznata i kao &#8220;tigrasta trava&#8221;, tradicionalno se koristi zbog svojih umirujućih i isceljujućih svojstava. Ovaj ekstrakt pomaže u smirivanju iritacija i crvenila, čineći ga idealnim za osetljivu i problematičnu kožu. Takođe, stimuliše sintezu kolagena, što doprinosi poboljšanju elastičnosti i čvrstoće kože. Njegova antiinflamatorna svojstva pomažu u smanjenju upala i ubrzavaju proces regeneracije kože. Ekstrakt Centella Asiatica bogat je antioksidansima koji štite kožu od slobodnih radikala i prevremenog starenja. Redovna upotreba proizvoda sa ovim sastojkom može poboljšati ukupni izgled i zdravlje kože. ​ Hijaluronska kiselina Ova maska sadrži tri tipa hijaluronske kiseline: hijaluronsku kiselinu, hidrolizovanu hijaluronsku kiselinu i natrijum hijaluronat. Ovi sastojci deluju kao snažni humektanti, privlačeći i zadržavajući vlagu u koži, čime se postiže dubinska hidratacija. Hijaluronska kiselina pomaže u popunjavanju finih linija i bora, poboljšavajući elastičnost i glatkoću kože. Takođe, jača kožnu barijeru, sprečavajući transepidermalni gubitak vlage. Njena sposobnost da hidrira kožu bez začepljenja pora čini je pogodnom za sve tipove kože. Redovna upotreba proizvoda sa hijaluronskom kiselinom doprinosi zdravijem i blistavijem izgledu kože.​ Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Centella Asiatica Calming Mask je hidratantna maska za lice koja sadrži 15% ekstrakta Centella Asiatica, namenjena umirivanju i regeneraciji osetljive i iritirane kože. Obogaćena je hijaluronskom kiselinom i biljnim ekstraktima koji pružaju dubinsku hidrataciju i osvežavaju ten.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Beauty-of-Joseon-Centella-Asiatica-Calming-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
