INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1335, 22, 'Beauty of Joseon Green Plum Refreshing Cleanser', 'beauty-of-joseon-green-plum-refreshing-cleanser', 'Ključne prednosti: Blago čišćenje : Efikasno uklanja nečistoće i višak sebuma bez isušivanja kože. Održava hidrataciju : Zahvaljujući sastojcima poput vode zelene šljive i ekstrakta mung pasulja. Pogodan za osetljivu kožu : Niska pH vrednost i prirodni sastojci čine ga idealnim za sve tipove kože. Kome je namenjen? Ovaj proizvod je namenjen osobama svih tipova kože, uključujući osetljivu, koje traže blagi, ali efikasan čistač koji održava prirodnu ravnotežu vlažnosti kože. Zašto volimo Beauty of Joseon Ginseng Cleansing Oil? Korišćenjem ovog čistača, koža postaje temeljno očišćena bez osećaja zatezanja ili suvoće. Prirodni sastojci poput vode zelene šljive i ekstrakta mung pasulja pružaju hranljive materije koje pomažu u održavanju zdrave barijere kože. Redovnom upotrebom, ten postaje osvežen i blistav, dok se smanjuje pojava iritacija zahvaljujući blagoj formuli. Ovaj čistač ne samo da uklanja nečistoće, već i neguje kožu, ostavljajući je mekom i hidriranom tokom celog dana. Aktivni sastojci Plum Water (24%) Plum Water (Prunus Mume) je bogata organskim kiselinama i vitaminima koji doprinose zdravlju kože. Ovaj sastojak pomaže u omekšavanju mrtvih ćelija kože, omogućavajući blagu eksfolijaciju bez iritacija. Takođe, deluje kao prirodni humektant, privlačeći vlagu i održavajući kožu hidriranom. Njegova antioksidativna svojstva pomažu u zaštiti kože od oštećenja izazvanih slobodnim radikalima i spoljašnjim faktorima. U tradicionalnoj korejskoj medicini koristi se zbog svojih umirujućih svojstava i sposobnosti da osveži i revitalizuje kožu. Redovna upotreba proizvoda sa ovim sastojkom može poboljšati teksturu kože i pružiti joj zdraviji i blistaviji izgled. Ekstrakt semena mung pasulja (3%) Ekstrakt semena mung pasulja poznat je po svojim nežnim eksfolijacionim i hidratantnim svojstvima. Tradicionalno se koristio u dinastiji Joseon kao prirodno sredstvo za čišćenje lica, često kombinovan sa crvenim pasuljem i pirinčanim mekinjama. Njegov visok sadržaj saponina pomaže u održavanju vlage u koži, poboljšavajući njenu hidrataciju i elastičnost. Takođe, ima antiinflamatorna svojstva koja pomažu u smirivanju iritacija i crvenila, čineći ga pogodnim za osetljivu i nadraženu kožu. Njegova sposobnost da očisti pore i ukloni višak sebuma doprinosi glatkoj i osveženoj koži. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Green Plum Refreshing Cleanser je blagi gel za čišćenje lica sa niskim pH, formulisan sa 24,5% vode zelene šljive i 2,94% ekstrakta semena mung pasulja, koji efikasno uklanja nečistoće dok održava hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Beauty-of-Joseon-Green-Plum-Refreshing-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
