INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1338, 17, 'Axis-Y Complete No-Stress Physical Sunscreen', 'axis-y-complete-no-stress-physical-sunscreen', 'Ključne prednosti: Visoka zaštita od sunca : SPF 50+ PA++++ pruža snažnu zaštitu od štetnih UVA i UVB zraka. Umirujuće dejstvo : Ekstrakt divljeg pelina i kamilice pomažu u smirivanju iritacija i crvenila. Hidratacija i obnova : Skvalan i hijaluronska kiselina obezbeđuju dubinsku hidrataciju. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući osetljivu i aknama sklonu kožu. Pogodan je za osobe svih starosnih grupa koje traže efikasnu zaštitu od sunca uz dodatne benefite nege kože. Zašto volimo AXIS-Y Complete No-Stress Physical Sunscreen? U svakodnevnoj rutini nege kože, zaštita od sunca je ključna. Complete No-Stress Physical Sunscreen ne samo da pruža visoku zaštitu od štetnih UV zraka, već i neguje kožu zahvaljujući pažljivo odabranim sastojcima. Ekstrakt divljeg pelina deluje umirujuće, smanjujući crvenilo i iritacije, dok niacinamid pomaže u ujednačavanju tena i smanjenju tamnih mrlja. Skvalan i hijaluronska kiselina obezbeđuju dubinsku hidrataciju, ostavljajući kožu mekom i elastičnom tokom celog dana. Aktivni sastojci Cink oksid (Zinc Oxide) Cink oksid je mineralni sastojak koji pruža širok spektar zaštite od UVA i UVB zraka, delujući kao fizička barijera na površini kože. Njegova upotreba u kremama za sunčanje pomaže u sprečavanju oštećenja kože izazvanih sunčevim zračenjem, uključujući opekotine i prevremeno starenje. Cink oksid je poznat po svojoj stabilnosti na svetlosti i ne razgrađuje se pod UV zracima, što ga čini pouzdanim izborom za dugotrajnu zaštitu. Niacinamid Niacinamid, poznat i kao vitamin B3, multifunkcionalni je sastojak koji pruža brojne koristi za kožu. Pomaže u poboljšanju funkcije kožne barijere, povećavajući njenu otpornost na spoljašnje iritante i smanjujući transepidermalni gubitak vode. Niacinamid je efikasan u smanjenju hiperpigmentacija i ujednačavanju tena, što rezultira svetlijom i blistavijom kožom. Ekstrakt artemizije (Artemisia Capillaris Extract) Artemizija, poznata i kao mugwort, tradicionalno se koristi u azijskoj medicini zbog svojih umirujućih i isceljujućih svojstava. Bogata je antioksidansima koji štite kožu od oksidativnog stresa i prevremenog starenja. Ima antiinflamatorna svojstva koja pomažu u smirivanju iritacija, crvenila i upala, što je posebno korisno za osetljivu i problematičnu kožu. Ekstrakt artemizije takođe hidrira kožu, poboljšavajući njenu elastičnost i teksturu. Dodaj u listu želja Dodaj u listu želja', 'AXIS-Y Complete No-Stress Physical Sunscreen je fizički zaštitni faktor sa SPF 50+ PA++++, formulisan da štiti kožu od UVA i UVB zračenja. Istovremeno pruža umirujuće i hidratantne benefite zahvaljujući sastojcima poput divljeg pelina, niacinamida i skvalana.', 'https://beauty-health.rs/wp-content/uploads/2024/11/AXIS-Y-Complete-No-Stress-Physical-Sunscreen.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
