INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1339, 17, 'Axis-Y Cera-Heart My Type Duo Cream', 'axis-y-cera-heart-my-type-duo-cream', 'Ključne prednosti: Personalizovana hidratacija: Dve odvojene formule omogućavaju ciljanu negu masnijih i suvlјih delova lica, pružajući balansiranu hidrataciju. Smanjenje sebuma: Sastojci poput ekstrakta Houttuynia Cordata pomažu u regulaciji proizvodnje sebuma, smanjujući masni sjaj u T-zoni. Jačanje barijere kože: Ceramidi u formuli U-zone jačaju zaštitnu barijeru kože, sprečavajući gubitak vlage i poboljšavajući elastičnost. Kome je namenjena? Ova krema je idealna za osobe sa kombinovanom kožom, posebno one koje se bore sa masnom T-zonom i suvim obrazima. Pogodna je za sve starosne grupe koje žele prilagođenu hidrataciju i balansiranu negu kože. Zašto volimo AXIS-Y Cera-Heart My Type Duo Cream? U svakodnevnoj rutini nege kože, pronalaženje prave ravnoteže između hidratacije i kontrole sebuma može biti izazov. Cera-Heart My Type Duo Cream pruža rešenje kroz dve specifične formule u jednoj posudi. Lagani gel za T-zonu smanjuje masni sjaj i održava pore čistima, dok bogata krema za U-zonu dubinski hidrira suve delove lica. Ova sinergija omogućava koži da zadrži optimalan nivo vlage, istovremeno smanjujući rizik od izbijanja akni i iritacija. Redovnom upotrebom, koža postaje mekša, elastičnija i blistavija, odražavajući zdrav i negovan izgled. Aktivni sastojci T-Zone krema Formulisana za masniju T-zonu (čelo, nos i brada), ova krema sadrži ključne sastojke koji pomažu u kontroli sebuma i održavanju svežeg izgleda kože: Houttuynia Cordata . Poznat po svojim antioksidativnim i umirujućim svojstvima, pomaže u smanjenju upala i kontroli prekomernog lučenja sebuma, što doprinosi čistijoj i balansiranoj koži.​ Centella Asiatica . Ima umirujuća i regenerativna svojstva, pomaže u smanjenju crvenila i iritacija, te poboljšava elastičnost kože.​ Ekstrakt žalfije . Deluje antibakterijski i antiinflamatorno, pomaže u regulaciji proizvodnje sebuma i održava kožu čistom.​ U-Zone krema Namenjena suvljoj U-zoni (obrazi i vilica), ova krema pruža dubinsku hidrataciju i jačanje kožne barijere zahvaljujući sledećim sastojcima:​ Ceramide NP . Ključni lipid koji pomaže u obnavljanju i održavanju zaštitne barijere kože, zadržavajući vlagu i štiteći je od spoljašnjih agresora.​ Ulje jojobe . Emolijent koji hidrira i omekšava kožu, oponašajući prirodna ulja kože, pružajući dugotrajnu hidrataciju bez začepljenja pora. Shea puter . Bogato masnim kiselinama i vitaminima, pruža intenzivnu hidrataciju, omekšava kožu i poboljšava njenu elastičnost.​ Ovaj dvojni pristup omogućava personalizovanu negu, prilagođavajući se specifičnim potrebama različitih delova lica, čime se postiže uravnotežena, hidrirana i zdrava koža. Dodaj u listu želja Dodaj u listu želja', 'AXIS-Y Cera-Heart My Type Duo Cream je inovativna hidratantna krema koja kombinuje dve formule u jednoj posudi, prilagođavajući se specifičnim potrebama vaše T-zone i U-zone za optimalnu negu kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/AXIS-Y-Cera-Heart-My-Type-Duo-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
