INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1343, 14, 'Arensia Black Tea Yuzu Cleanser', 'arencia-black-tea-yuzu-cleanser', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja nečistoće i višak sebuma, smanjujući pojavu mitisera i začepljenih pora. Hidratacija i osveženje: Održava optimalan nivo vlažnosti kože, ostavljajući je mekom i osveženom. Prirodni sastojci: Formulisan sa preko 20 prirodnih sastojaka, uključujući crni čaj i yuzu, pogodan je za sve tipove kože. Kome je namenjen? Ovaj čistač je idealan za osobe sa masnom ili kombinovanom kožom sklonom mitiserima i začepljenim porama. Naročito za one koji traže proizvod sa prirodnim sastojcima za svakodnevnu negu. Zašto volimo Arensia Black Tea Yuzu Cleanser? Black Tea & Yuzu Cleanser pruža više od osnovnog čišćenja kože – on osnažuje vašu rutinu nege kombinacijom moćnih prirodnih sastojaka. Crni čaj deluje kao snažan antioksidans, štiteći kožu od svakodnevnih oštećenja i smanjujući crvenilo. Ekstrakt yuzu-a unosi svežinu i blistavost, osvetljavajući kožu i vraćajući joj elastičnost. Prah aktivnog uglja efikasno uklanja toksine i višak sebuma, pomažući da pore ostanu čiste i sužene. Dugoročno, ovaj čistač balansira nivoe ulja i vlage u koži, ostavljajući je hidriranom, ali matiranom. Aktivni sastojci Ekstrakt crnog čaja Ekstrakt crnog čaja bogat je polifenolima koji pružaju snažnu antioksidativnu zaštitu, pomažući u borbi protiv slobodnih radikala i poboljšavajući elastičnost kože. Takođe, poznat je po svojim umirujućim svojstvima koja smanjuju iritacije i crvenilo, čineći kožu mekšom i glatkijom.​ Ekstrakt citrusa (Yuzu) Ekstrakt citrusa, posebno Yuzu, bogat je vitaminom C i antioksidansima koji posvetljuju kožu i pružaju osvežavajući efekat. Pomaže u smanjenju hiperpigmentacija i daje koži blistav izgled.​ Glicerin Glicerin deluje kao humektant, privlačeći vlagu iz okoline i zadržavajući je u koži, čime pruža dubinsku hidrataciju. Poboljšava elastičnost kože i čini je mekšom na dodir.​ Prah pirinča (Oryza Sativa Powder) Prah pirinča deluje kao blagi eksfolijant koji uklanja mrtve ćelije kože, ostavljajući kožu glatkom i osveženom. Takođe, pomaže u posvetljivanju tena i poboljšanju teksture kože.​ Sodium Cocoyl Isethionate Sodium Cocoyl Isethionate je blagi surfaktant koji omogućava efikasno čišćenje kože bez isušivanja. Pruža bogatu penu koja uklanja nečistoće, ostavljajući kožu čistom i osveženom. Dodaj u listu želja Dodaj u listu želja', 'Arensia Black Tea Yuzu Cleanser je luksuzni čistač lica koji kombinuje antioksidativna svojstva crnog čaja sa osvežavajućim ekstraktom japanskog citrusa yuzu , pružajući temeljno čišćenje i hidrataciju kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Arencia-Black-Tea-Yuzu-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
