INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1347, 12, 'APLB Glutathione Niacinamide Cleansing Balm', 'aplb-glutathione-niacinamide-cleansing-balm', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja šminku, uključujući vodootpornu, i nečistoće, ostavljajući kožu čistom i osveženom. Posvetljivanje tena: Sadrži glutathion i niacinamid koji pomažu u ujednačavanju tena i smanjenju tamnih mrlja. Hidratacija i nega: Obogaćen uljima soje, suncokreta i jojobe, balzam održava kožu mekom i hidriranom nakon čišćenja. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući osetljivu. Posebno je koristan za osobe koje traže efikasno sredstvo za uklanjanje šminke koje istovremeno posvetljuje i hidrira kožu. Zašto volimo APLB Glutathione Niacinamide Cleansing Balm? U svakodnevnoj rutini nege, Glutathione Niacinamide Cleansing Balm postaje nezamenljiv saveznik. Njegova bogata, kremasta tekstura topi se na koži, pretvarajući se u ulje koje lako uklanja čak i najuporniju šminku. Nakon ispiranja, koža ostaje meka, hidrirana i osvežena, bez osećaja zatezanja. Redovnom upotrebom, ten postaje ujednačeniji, a koža blistavija, zahvaljujući sinergiji glutationa i niacinamida. Aktivni sastojci Glycine Soja (sojino) ulje Ovo ulje bogato esencijalnim masnim kiselinama i antioksidansima deluje kao emolijens, omekšavajući i hidrirajući kožu. Pomaže u održavanju elastičnosti kože i štiti je od isušivanja.​ Niacinamid Poznat i kao vitamin B3, niacinamid pomaže u ujednačavanju tena, smanjenju vidljivosti pora i kontroli proizvodnje sebuma. Takođe, jača barijeru kože i poboljšava njenu elastičnost.​ Glutation Snažan antioksidans koji štiti kožu od slobodnih radikala i pomaže u posvetljavanju tena, pružajući koži blistav izgled.​ Melaleuca Alternifolia (čajevac) ulje Ima antimikrobna i antiinflamatorna svojstva, pomaže u smirivanju iritacija i sprečavanju pojave akni.​ Helianthus Annuus (suncokretovo) ulje Bogato vitaminom E i masnim kiselinama, ovo ulje deluje kao emolijens, omekšavajući kožu i pružajući joj hidrataciju.​ Olea Europaea (maslinovo) ulje Sadrži antioksidanse i masne kiseline koje hrane kožu, poboljšavaju njenu elastičnost i pružaju zaštitu od isušivanja. Dodaj u listu želja Dodaj u listu želja', 'APLB Glutathione Niacinamide Cleansing Balm je nežni balzam za čišćenje lica koji efikasno uklanja šminku i nečistoće, istovremeno posvetljujući i osvežavajući kožu. Formulisan sa 68,6% Lipo Gluta Niac ulja, pruža hidrataciju i negu tokom čišćenja.', 'https://beauty-health.rs/wp-content/uploads/2024/11/APLB-Glutathione-Niacinamide-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
