INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1358, 11, 'Anua Heartleaf Pore Control Cleansing Oil', 'anua-heartleaf-pore-control-cleansing-oil', 'Ključne prednosti: Dubinsko čišćenje: Efikasno uklanja šminku, sebum i nečistoće iz pora bez iritacije. Regulisanje proizvodnje sebuma: Ekstrakt Houttuynia Cordata i ulje semena grožđa pomažu u smanjenju masnoće kože i otčepljivanju pora. Umirujuće dejstvo: Formula smiruje iritacije i crvenilo, čineći je pogodnom za osetljivu kožu. Kome je namenjen? Ovaj uljani čistač je idealan za osobe sa masnom, kombinovanom i problematičnom kožom, posebno za one koji se bore sa začepljenim porama i prekomernim sebumom. Prikladan je i za osetljivu kožu koja zahteva blage, ali efikasne sastojke. Zašto volimo Anua Heartleaf Pore Control Cleansing Oil? Heartleaf Pore Control Cleansing Oil pruža kompletnu negu čišćenja uz hidrataciju i umirujuće dejstvo. Njegova lagana uljana formula lako otklanja šminku i nečistoće, istovremeno održavajući prirodnu hidrataciju kože. Ekstrakt Houttuynia Cordata deluje umirujuće na iritiranu kožu. Ulje semena grožđa pomaže u balansiranju sebuma. Redovnom upotrebom, koža postaje vidljivo čistija i glađa, sa smanjenim izgledom pora i zdravim sjajem. Aktivni sastojci Ekstrakt Houttuynia Cordata Ekstrakt Houttuynia Cordata, poznat i kao srcolisna biljka, poseduje antiinflamatorna i umirujuća svojstva koja pomažu u smirivanju iritacija i crvenila na koži. Takođe, deluje kao antioksidans, štiteći kožu od slobodnih radikala i spoljašnjih agresora. Njegova sposobnost da balansira proizvodnju sebuma doprinosi čistijoj i zdravijoj koži. ​ Ulje semenki grožđa (Vitis Vinifera) Ulje semenki grožđa je lagano ulje bogato linolnom kiselinom i vitaminom E, koje pruža hidrataciju bez začepljenja pora. Njegova antioksidativna svojstva pomažu u zaštiti kože od oštećenja izazvanih slobodnim radikalima, dok istovremeno poboljšava elastičnost i tonus kože. ​ Ulje jojobe (Simmondsia Chinensis) Ulje jojobe je poznato po svojoj sličnosti sa prirodnim sebumom kože, što omogućava lako apsorbovanje i balansiranje masnoće. Pruža dubinsku hidrataciju, omekšava kožu i pomaže u regulaciji proizvodnje sebuma, čineći ga idealnim za masnu i mešovitu kožu. ​ Ulje masline (Olea Europaea) Ulje masline je bogato antioksidansima, uključujući vitamin E, koji štite kožu od oksidativnog stresa i prevremenog starenja. Njegova emolijentna svojstva pružaju dubinsku hidrataciju i poboljšavaju elastičnost kože, ostavljajući je mekom i glatkom. ​ Ekstrakt kurkume (Curcuma Longa) Ekstrakt kurkume poseduje antiinflamatorna i antioksidativna svojstva koja pomažu u smanjenju upala i zaštiti kože od oštećenja izazvanih slobodnim radikalima. Takođe, doprinosi posvetljivanju kože i ujednačavanju tena, pružajući blistav i zdrav izgled. Dodaj u listu želja Dodaj u listu želja', 'Anua Heartleaf Pore Control Cleansing Oil j e blago ulje za čišćenje lica koje kombinuje moć uklanjanja šminke i dubinskog čišćenja pora uz umirujuća svojstva ekstrakta Houttuynia Cordata. Idealno je za održavanje čiste i hidrirane kože bez masnog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Anua-Heartleaf-Pore-Control-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
