INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1359, 11, 'Anua Heartleaf Succinic Moisture Cleansing Foam', 'anua-heartleaf-succinic-moisture-cleansing-foam', 'Ključne prednosti: Dubinsko čišćenje pora: Salicilna kiselina prodire duboko u pore, uklanjajući nečistoće i smanjujući pojavu akni. Regulacija sebuma: Sukcinska kiselina pomaže u balansiranju proizvodnje ulja, sprečavajući prekomerno mašćenje kože. Nežno eksfoliranje: Ekstrakt Houttuynia Cordata i proteaza uklanjaju mrtve ćelije kože bez iritacije, otkrivajući glatku i blistavu kožu. Kome je namenjen? Ovaj proizvod je idealan za osobe sa masnom i aknama sklonom kožom, kao i za one sa osetljivom kožom koja zahteva nežno, ali efikasno čišćenje. Zašto volimo Anua Heartleaf Succinic Moisture Cleansing Foam? Heartleaf Succinic Moisture Cleansing Foam pruža temeljno čišćenje bez isušivanja kože. Njegova pena nežno uklanja nečistoće i višak sebuma, dok aktivni sastojci deluju na smanjenje upala i balansiranje masnoće. Formulacija sa umirujućim ekstraktom Houttuynia Cordata pomaže u smirivanju iritacija. Koža ostaje sveža, čista i glatka, pripremljena za sledeće korake nege. Redovnom upotrebom smanjuje pojavu akni i poboljšava teksturu kože. Aktivni sastojci Ekstrakt Houttuynia Cordata (10,000ppm) Ekstrakt Houttuynia Cordata, poznat i kao srcolisna biljka, bogat je flavonoidima poput kvercetina i rutinina, koji pružaju antioksidativna i antiinflamatorna svojstva, pomažući u smirivanju iritacija i zaštiti kože od slobodnih radikala. Takođe, sadrži polisaharide koji deluju kao humektanti, zadržavajući vlagu u koži i poboljšavajući njenu hidrataciju. Njegova antibakterijska svojstva doprinose održavanju čiste i zdrave kože, što je posebno korisno za osobe sklone aknama. Redovnom upotrebom, ovaj ekstrakt pomaže u balansiranju proizvodnje sebuma, čineći kožu manje masnom i sklonijom balansiranom izgledu. ​ Sukcinska kiselina (5,000ppm) Sukcinska kiselina je poznata po svojoj sposobnosti regulisanja proizvodnje sebuma, što pomaže u smanjenju masnoće kože i prevenciji začepljenih pora. Deluje kao blagi eksfolijant, uklanjajući mrtve ćelije kože i poboljšavajući njenu teksturu. Takođe, poseduje antimikrobna svojstva koja pomažu u borbi protiv bakterija odgovornih za nastanak akni. Njena prisutnost u formulaciji doprinosi održavanju optimalnog pH nivoa kože, što je ključno za zdravu kožnu barijeru. Redovnom upotrebom, sukcinska kiselina može poboljšati ukupni izgled kože, čineći je glatkom i blistavom. ​ Salicilna kiselina Salicilna kiselina je beta-hidroksi kiselina (BHA) koja prodire duboko u pore, otklanja nečistoće i višak sebuma, čime sprečava nastanak akni i mitesera. Deluje kao keratolitik, pomažući u uklanjanju mrtvih ćelija kože i pospešujući regeneraciju novih. Njena antiinflamatorna svojstva smanjuju crvenilo i upale, što je čini idealnom za tretiranje problematične kože. Takođe, poboljšava teksturu kože, ostavljajući je glatkom i osveženom. Redovnom upotrebom, salicilna kiselina može smanjiti pojavu proširenih pora i ujednačiti ten. ​ incidecoder.com Dodaj u listu želja Dodaj u listu želja', 'Anua Heartleaf Succinic Moisture Cleansing Foam je blaga gelasta pena za čišćenje lica, formulisana sa 10.000 ppm ekstrakta biljke kameleon i proteazom, namenjena nežnom uklanjanju mrtvih ćelija kože i nečistoća. Obogaćena salicilnom i sukcinskom kiselinom, pomaže u otčepljivanju pora i regulaciji proizvodnje sebuma.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Anua-Heartleaf-Succinic-Moisture-Cleansing-Foam-3.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
