INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1364, 6, 'Abib Jericho Rose Trial Kit', 'abib-jericho-rose-trial-kit', 'Ključne prednosti: Dubinska hidratacija i balansiranje kože: Jericho Rose Toner priprema kožu za dalju negu, pružajući hidrataciju i uklanjajući nečistoće. Regeneracija i elastičnost: Jericho Rose Serum i Cream revitalizuju i obnavljaju kožu, jačajući njenu barijeru i učvršćujući teksturu. Efekat podizanja i zatezanja: Jericho Rose Collagen Pads deluju ciljano na područja koja zahtevaju dodatnu negu, pružajući trenutni učinak učvršćivanja. Kome je namenjen? Ovaj set je idealan za sve tipove kože, uključujući osetljivu i zrelu, posebno za one koji žele sveobuhvatnu hidrataciju, poboljšanje elastičnosti i ujednačen ten. Zašto volimo Abib Jericho Rose Trial Kit? Jericho Rose Trial Kit pruža luksuzno iskustvo nege koje odgovara potrebama različitih tipova kože. Jericho Rose Toner nežno osvežava kožu i balansira pH vrednost. Jericho Rose Serum obogaćen ekstraktom ruže iz Jerihona prodire duboko, regeneriše i poboljšava elastičnost. Jericho Rose Cream intenzivno hidrira i štiti kožnu barijeru. Collagen Pads pružaju trenutnu zategnutost i vidljivo smanjuju pojavu finih linija. Set je osmišljen za kompletnu negu, ostavljajući kožu blistavom, hidriranom i glatkom. Sadržaj seta i njihovi ključni aktivni sastojci Jericho Rose PHA Toner/Skin Booster (30 ml) Ekstrakt ruže Jerihonske (Anastatica Hierochuntica Extract): Pruža intenzivnu hidrataciju i revitalizaciju kože.​ Gluconolactone (PHA): Blago eksfolira kožu, poboljšavajući njenu teksturu.​ Niacinamid (Vitamin B3): Ujednačava ten i poboljšava barijernu funkciju kože.​ Natrijum hijaluronat (Sodium Hyaluronate): Dubinski hidrira kožu, povećavajući njenu elastičnost.​ Bifida fermentat (Bifida Ferment Filtrate): Jača zaštitnu barijeru kože i povećava njenu otpornost.​ Jericho Rose Bifida Serum/Firming Drop (30 ml) Ekstrakt ruže Jerihonske: Hidrira i revitalizuje kožu.​ Bifida ferment lisat (Bifida Ferment Lysate): Poboljšava elastičnost kože i jača njenu otpornost.​ Niacinamid: Ujednačava ten i smanjuje vidljivost pora.​ Natrijum hijaluronat: Pruža dubinsku hidrataciju.​ Topivi kolagen (Soluble Collagen): Poboljšava čvrstoću i elastičnost kože.​ Jericho Rose Cream/Nutrition Tube (30 ml) Ekstrakt ruže Jerihonske: Pruža hidrataciju i revitalizaciju.​ Shea puter (Butyrospermum Parkii Butter): Hrani i omekšava kožu.​ Kokosovo ulje (Cocos Nucifera Oil): Hidrira i umiruje kožu.​ Ekstrakt agave (Agave Tequilana Leaf Extract): Pruža dodatnu hidrataciju.​ Ekstrakt čage (Inonotus Obliquus Extract): Deluje kao antioksidans, štiteći kožu od slobodnih radikala.​ Jericho Rose Collagen Pad/Firming Touch (3 komada) Ekstrakt kolagena (Collagen Extract): Poboljšava elastičnost i čvrstoću kože.​ Ekstrakt ruže Jerihonske: Hidrira i revitalizuje kožu.​ Niacinamid: Ujednačava ten i smanjuje hiperpigmentacije.​ Shea puter: Hrani i omekšava kožu.​ Natrijum hijaluronat: Pruža dubinsku hidrataciju. Dodaj u listu želja Dodaj u listu želja', 'Abib Jericho Rose Trial Kit je kompletan set za negu kože koji uključuje 4 ključna preparata: Jericho Rose Toner, Serum, Cream i Collagen Pads . Kombinacija moćnog ekstrakta ruže iz Jerihona i inovativnih formulacija pruža intenzivnu hidrataciju, jača elastičnost kože i poboljšava njenu teksturu. Set se sastoji od 30ml+30ml+30ml+3 jastučića.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Abib-Jericho-Rose-Trial-Kit.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
