INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1365, 6, 'Abib Heartleaf Calming Toner Skin Booster', 'abib-heartleaf-calming-toner-skin-booster', 'Ključne prednosti: Intenzivna hidratacija: Niska molekularna hijaluronska kiselina pruža dubinsku i dugotrajnu hidrataciju. Regulacija sebuma i eksfolijacija: Ekstrakt Heartleaf-a pomaže u kontroli viška ulja i uklanjanju mrtvih ćelija kože,. Umirujuće dejstvo: Sastojci poput Centella Asiatica i Bifida Ferment Lysate smiruju iritacije i crvenilo, pružajući osećaj olakšanja za osetljivu kožu. Kome je namenjen? Ovaj tonik je idealan za sve tipove kože, posebno za one sa osetljivom, masnom ili kombinovanom kožom sklonom iritacijama i aknama. Pogodan je za sve starosne grupe koje žele poboljšati teksturu i hidrataciju kože. Zašto volimo Abib Heartleaf Calming Toner Skin Booster? Zamislite tonik koji ne samo da hidrira, već i umiruje vašu kožu nakon napornog dana. Heartleaf Calming Toner Skin Booster koristi moć prirodnih sastojaka da obnovi ravnotežu vaše kože. Redovnom upotrebom, vaša koža postaje vidljivo čistija, mekša i otpornija na spoljašnje uticaje. Ovaj tonik ne ostavlja lepljiv trag, već pruža osećaj svežine i lakoće, pripremajući kožu za dalju negu. Aktivni sastojci Ekstrakt biljke kameleon (Heartleaf) Poznat po svojim antiinflamatornim i antibakterijskim svojstvima, ovaj ekstrakt pomaže u smanjenju crvenila i iritacija, dok istovremeno balansira proizvodnju sebuma, što je ključno za čistu i zdravu kožu. Niska molekularna hijaluronska kiselina Zahvaljujući svojoj sposobnosti da prodre duboko u kožu, ova forma hijaluronske kiseline pruža intenzivnu hidrataciju, povećava elastičnost i smanjuje pojavu finih linija, ostavljajući kožu glatkom i zategnutom. Centella Asiatica ekstrakt Ovaj sastojak je poznat po svojim umirujućim i regenerativnim svojstvima. Pomaže u zaceljivanju oštećenja kože, smanjuje upale i poboljšava ukupnu teksturu kože, čineći je otpornijom na spoljašnje uticaje. Dodaj u listu želja Dodaj u listu želja', 'Abib Heartleaf Calming Toner Skin Booster je hidratantni tonik koji umiruje kožu, obogaćen ekstraktom biljke kameleon (Heartleaf) u koncentraciji od 50.000 ppm, namenjen za svakodnevnu negu svih tipova kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Abib-Heartleaf-Calming-Toner-Skin-Booster.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
