INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1366, 6, 'Abib Heartleaf Facial Mist Calming Spray Set', 'abib-heartleaf-facial-mist-calming-spray-set', 'Ključne prednosti: Trenutno umirivanje kože : Visoka koncentracija ekstrakta Houttuynia Cordata efikasno smiruje iritacije i crvenilo. Dubinska hidratacija : Aqua Ceramide i Xylitol Complex obnavljaju nivoe vlage u koži i jačaju njenu barijeru. Ultra-fine čestice : Sprej ravnomerno prekriva lice, omogućavajući brzu apsorpciju i osvežavajući osećaj bez lepljivosti. Kome je namenjen? Ovaj proizvod je idealan za osobe sa osetljivom, iritiranom ili suvom kožom. Posebno za one koji traže brzo osveženje i hidrataciju tokom dana. Zašto volimo Abib Heartleaf Facial Mist Calming Spray? Zamislite da vaša koža dobije trenutnu dozu umirujuće hidratacije svaki put kada joj je to potrebno. Heartleaf Facial Mist Calming Spray pruža upravo to – zahvaljujući visokoj koncentraciji ekstrakta Houttuynia Cordata . Ova biljka je poznata po svojim antiinflamatornim svojstvima i efikasno smiruje iritacije i crvenilo. Dodatno, Aqua Ceramide i Xylitol Complex obnavljaju nivoe vlage u koži i jačaju njenu barijeru, ostavljajući je mekom i elastičnom. Bilo da ste kod kuće, na poslu ili u pokretu, ovaj sprej je vaš saveznik za trenutnu revitalizaciju kože. Aktivni sastojci Ekstrakt Houttuynia Cordata (30.000 ppm) Poznat po svojim antiinflamatornim i antioksidativnim svojstvima, ovaj ekstrakt efikasno smiruje iritacije, smanjuje crvenilo i štiti kožu od štetnih spoljašnjih faktora. Aqua Ceramide Pomaže u zadržavanju vlage u koži, jača njenu zaštitnu barijeru i sprečava gubitak vode, što rezultira hidriranom i zdravom kožom. Xylitol Complex Ovaj kompleks hidrira kožu i poboljšava njenu sposobnost zadržavanja vlage, čineći je glatkom i elastičnom. Dodaj u listu želja Dodaj u listu želja', 'Abib Heartleaf Facial Mist Calming Spray je hipoalergen sprej za lice koja trenutno umiruje i hidrira iritiranu kožu, zahvaljujući 30.000 ppm ekstrakta biljke kameleon sa planine Jiri u Južnoj Koreji. Set se sastoji od 150ml + dopune od 150ml.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Abib-Heartleaf-Facial-Mist-Calming-Spray-Set.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
