INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1367, 6, 'Abib Heartleaf Creme Calming Tube', 'abib-heartleaf-creme-calming-tube', 'Ključne prednosti: Umiruje iritacije: Ekstrakt biljke kameleon deluje protivupalno, smanjujući crvenilo i iritacije. Dubinska hidratacija: 8 vrsta hijaluronske kiseline obezbeđuju optimalnu vlažnost. Jačanje barijere kože: Ceramidi i pantenol jačaju zaštitnu barijeru kože, štiteći je od spoljašnjih uticaja. Kome je namenjena? Ova krema je idealna za osobe sa osetljivom, suvom ili iritiranom kožom. Preporučuje se i za one koji žele da poboljšaju hidrataciju i zaštitu svoje kože. Zašto volimo Abib Heartleaf Creme Calming Tube? Creme Calming Tube pruža vašu koži trenutak mira i oporavka, idealan za dane kada je koža umorna, iritirana ili pod stresom. Ova bogata, ali lagana krema nežno se upija, donoseći intenzivnu hidrataciju. Pruža umirujuće dejstvo zahvaljujući ekstraktu biljke kameleon. Formulacija sa 8 vrsta hijaluronske kiseline prodire u dublje slojeve kože, čineći je elastičnijom i osveženom. Istovremeno, ceramidi i pantenol obnavljaju zaštitnu barijeru, pružajući dugotrajnu zaštitu od spoljašnjih uticaja. Aktivni sastojci Houttuynia Cordata ekstrakt Ovaj moćni biljni sastojak poznat je po svom umirujućem i protivupalnom dejstvu. Smanjuje crvenilo i pomaže u smirivanju iritacija, čineći kožu mirnijom i otpornijom na spoljašnje stresore. Idealan je za osetljivu i problematičnu kožu koja zahteva dodatnu pažnju. Hijaluronska kiselina (8 vrsta) Kombinacija različitih veličina molekula hijaluronske kiseline prodire duboko u kožu, pružajući hidrataciju u svim slojevima. Ovaj sastojak zaključava vlagu, čineći kožu punijom, glatkijom i savršeno osveženom tokom celog dana. Ceramidi Prirodni lipidi koji jačaju zaštitnu barijeru kože i sprečavaju gubitak vlage. Ceramidi čine kožu čvrstom, otpornijom i manje podložnom iritacijama, pružajući dugotrajnu hidrataciju i zaštitu. Dodaj u listu želja Dodaj u listu želja', 'Abib Heartleaf Creme Calming Tube je umirujuća krema koja pruža intenzivnu hidrataciju i smiruje osetljivu kožu, zahvaljujući ekstraktu biljke kameleon ( Houttuynia Cordata) i hijaluronskoj kiselini.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Abib-Heartleaf-Creme-Calming-Tube.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
