INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1371, 6, 'Abib Protective Lip Balm Block Stick', 'abib-protective-lip-balm-block-stick', 'Ključne prednosti: Hidratacija i nega: Obogaćen bademovim uljem i shea puterom, balzam intenzivno hidrira i omekšava usne, ostavljajući ih glatkim i zdravim. Zaštita od UV zračenja: Sa SPF15, pruža efikasnu zaštitu od štetnih sunčevih zraka, sprečavajući oštećenja i prevremeno starenje kože usana. Prevencija gubitka vlage: Formulacija sa esencijalnim sastojcima i mekim ester voskom sprečava gubitak vlage, održavajući usne hidriranim tokom celog dana. Kome je namenjen? Ovaj lip balzam je idealan za osobe svih starosnih grupa koje žele da zaštite svoje usne od UV zračenja i održe ih hidriranim i negovanim. Posebno je pogodan za one sa suvim ili ispucalim usnama koje traže svakodnevnu zaštitu i hidrataciju. Zašto volimo Abib Protective Lip Balm Block Stick ? Zamislite dan proveden na suncu, bez brige o suvim ili oštećenim usnama. Abib Protective Lip Balm Block Stick pruža upravo to – kombinaciju hidratacije i zaštite. Njegova lagana, nelepljiva tekstura omogućava lako nanošenje, dok prirodni sastojci dubinski hrane usne. Redovnom upotrebom, usne postaju mekše, glatkije i zaštićene od spoljašnjih uticaja, pružajući vam samopouzdanje da se suočite sa svakodnevnim izazovima. Aktivni sastojci Butyrospermum Parkii Butter (Shea puter) Shea puter je prirodni emolijens bogat masnim kiselinama i vitaminima, poznat po svojim hidratantnim i umirujućim svojstvima. Pomaže u omekšavanju i zaštiti kože usana, sprečavajući isušivanje i pucanje. Takođe, sadrži antioksidanse koji štite kožu od slobodnih radikala.​ Ethylhexyl Methoxycinnamate (Octinoxate) Ovaj organski spoj deluje kao UVB filter, apsorbujući štetne UVB zrake i štiteći kožu od oštećenja izazvanih sunčevim zračenjem. Pruža zaštitu od sunčevih opekotina i fotostarenja.​ Ricinus Communis (Castor) Seed Oil (Ricinusovo ulje) Ricinusovo ulje je bogato ricinoleinskom kiselinom, koja deluje kao emolijens, pružajući hidrataciju i zaštitu usana. Takođe ima antibakterijska i antiinflamatorna svojstva koja doprinose zdravlju kože.​ Ethylhexyl Salicylate Ovaj sastojak deluje kao UVB apsorber, pružajući dodatnu zaštitu od štetnih efekata sunčevog zračenja. Takođe doprinosi stabilnosti formulacije i poboljšava teksturu proizvoda.​ Jojoba Esters (Estari jojobe) Estari jojobe su derivati ulja jojobe koji deluju kao emolijensi, pružajući hidrataciju i mekoću usnama. Njihova struktura je slična prirodnim uljima kože, što ih čini izuzetno kompatibilnim sa kožom.​ Olea Europaea (Olive) Fruit Oil (Maslinovo ulje) Maslinovo ulje je bogato masnim kiselinama i antioksidansima, pružajući hidrataciju i zaštitu usnama. Pomaže u omekšavanju i regeneraciji kože, čineći usne glatkima i zdravima.​ Dodaj u listu želja Dodaj u listu želja', 'Abib Protective Lip Balm Block Stick j e hidratantni balzam za usne koji pruža SPF15 zaštitu od UV zračenja, istovremeno negujući i omekšavajući usne zahvaljujući prirodnim sastojcima poput bademovog ulja i shea putera.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Abib-Protective-Lip-Balm-Block-Stick.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
