INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1378, 174, 'VT Cosmetics Cica Reti-A Essence 0.7', 'vt-cosmetics-cica-reti-a-essence-0-7', 'Ključne prednosti: Smanjuje pore i fine linije : Retinoid pomaže u smanjenju pora i ublažavanju finih linija za ujednačeniju teksturu kože. Dubinska hidratacija i umirenje : Trostruki hijaluronski kompleks zadržava vlagu, dok ekstrakt Cice umiruje iritacije. Jača barijeru kože : Pomaže koži da postane otpornija na spoljne uticaje, održavajući je elastičnom i mladalačkom. Kome je namenjena? Ova esencija je idealna za osobe sa masnom, kombinovanom ili zrelom kožom, posebno za one koji se suočavaju sa proširenim porama, finim linijama i čestim iritacijama. Zašto volimo VT Cosmetics Cica Reti-A Essence 0.7 ? Cica Reti-A Essence 0.7 pruža intenzivnu negu koži sklona promenama teksture i starenju. Hidroksipinakolon retinoat, stabilizovana forma retinoida, prodire duboko u kožu. Promoviše obnovu ćelija i time smanjuje pojavu finih linija i bora. Ova esencija nudi umirujući efekat zahvaljujući Cica kompleksu, koji regeneriše kožu i smanjujee crvenilo. Trostruki hijaluronski kompleks osigurava dubinsku hidrataciju bez težine, čime koža postaje mekana i osvežena. Uz redovnu upotrebu, koža postaje blistavija i otpornija, pružajući dugotrajan efekat mladalačkog sjaja. Cica Reti-A Essence 0.7 i 0.5: Koji odabrati? VT Cosmetics nudi dve varijante Cica Reti-A Essence proizvoda: 0.5% i 0.7%. Glavna razlika između njih je koncentracija aktivnog sastojka, hidroksipinakolon retinoata, oblika retinola poznatog po svojoj efikasnosti u borbi protiv znakova starenja i poboljšanju teksture kože. VT Cosmetics Cica Reti-A Essence 0.5% Ova verzija sadrži 0.5% hidroksipinakolon retinoata i namenjena je korisnicima koji žele umerenu koncentraciju retinola za svakodnevnu negu. Pogodna je za one koji tek počinju sa upotrebom retinola ili imaju osetljiviju kožu. Pored retinola, proizvod sadrži Cicahylon (ekstrakt Centella Asiatica i 3 vrste hijaluronske kiseline) za hidrataciju i umirenje kože. VT Cosmetics Cica Reti-A Essence 0.7% Ova verzija sadrži 0.7% hidroksipinakolon retinoata, što je viša koncentracija namenjena korisnicima koji su već navikli na retinol i žele intenzivniju negu. Pruža dublju negu protiv znakova starenja i poboljšava teksturu kože. Takođe sadrži Cicahylon za dodatnu hidrataciju i umirenje. Koji proizvod odabrati? Početnici ili osobe sa osetljivom kožom: Preporučuje se početak sa nižom koncentracijom, kao što je 0.5%, kako bi se koža postepeno navikla na retinol. Iskusni korisnici retinola: Ako ste već koristili retinol i vaša koža ga dobro podnosi, verzija sa 0.7% može pružiti intenzivnije rezultate. Uvek je važno pratiti reakciju kože i prilagoditi upotrebu prema individualnim potrebama. Aktivni sastojci Hydroxypinacolone Retinoate Hydroxypinacolone Retinoate (HPR) je stabilan derivat retinoične kiseline koji pruža efekte retinola bez uobičajene iritacije. Deluje direktno na receptore u koži, podstičući ćelijsku regeneraciju i proizvodnju kolagena. Ovaj sastojak efikasno smanjuje vidljivost bora, poboljšava teksturu kože i sužava pore. Zbog svoje visoke čistoće (99%), pokazuje brže i vidljivije rezultate u odnosu na klasične oblike retinola. Centella Asiatica Extract Centella Asiatica je biljni ekstrakt poznat po svojim umirujućim i regenerativnim svojstvima, naročito efikasan kod osetljive i nadražene kože. Deluje protivupalno i ubrzava zarastanje mikrooštećenja kože, jačajući prirodnu barijeru kože. Stimuliše sintezu kolagena, čime doprinosi čvrstoći i elastičnosti kože. Posebno je koristan u tretmanima za akne i crvenilo, jer smanjuje iritacije i pospešuje oporavak kože. Hijaluronska kiselina (3 tipa) Hijaluronska kiselina je snažan humektant koji privlači i zadržava vlagu, čime doprinosi dugotrajnoj hidrataciji kože. Kombinacija tri različita molekulska oblika omogućava hidrataciju na više nivoa – u površinskim i dubljim slojevima kože. Acetyl Hexapeptide-8 Acetyl Hexapeptide-8, poznat i kao &#8220;botox u bočici&#8221;, peptid je ', 'VT Cosmetics Cica Reti-A Essence 0.7 kombinuje snagu 0.7% retinoida i ekstrakta Cice kako bi smanjila pore, umirila kožu i tretirala znakove starenja. Ova esencija pruža intenzivnu hidrataciju i podršku kožnoj barijeri, čineći kožu glatkom i revitalizovanom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/VT-Cosmetics-Cica-Reti-A-Essence-0.7.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
INSERT INTO product_category (product_id, category_id) VALUES (1378, 55);
