INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1379, 174, 'VT Cosmetics Cica Reti-A Essence 0.5', 'vt-cosmetics-cica-reti-a-essence-0-5', 'Ključne prednosti: Poboljšava teksturu kože : Retinol i Cica umanjuju pore i pružaju glatku teksturu. Smanjuje bore : Hidroksipinakolon retinoat pomaže u borbi protiv znakova starenja. Duboko hidrira : Hijaluronska kiselina i Cica umiruju kožu i održavaju nivo hidratacije​. Kome je namenjena? Ovaj proizvod je idealan za osobe sa mešovitom, masnom ili zrelom kožom koje žele da redukuju bore, ujednače teksturu kože i kontrolišu višak sebuma, a da pritom izbegnu iritaciju. Zašto volimo VT Cosmetics Cica Reti-A Essence 0.5 ? Reti-A Essence 0.5 transformiše kožu čineći je glatkijom, jedrijom i dubinski hidriranom uz pomoć retinola i Cica kompleksa. Retinol, moćni sastojak u borbi protiv znakova starenja, smanjuje vidljivost bora i poboljšava teksturu kože. Hijaluronska kiselina intenzivno hidrira i zaključava vlagu, pružajući koži osećaj svežine. Cica komponenta umiruje kožu, deluje protiv crvenila i štiti osetljivu kožu od iritacija, dodatno jačajući njenu barijeru. Sa svakodnevnom upotrebom, koža postaje ujednačenija i blistavija, dajući licu svež, revitalizovan izgled. https://www.youtube.com/watch?v=JIQjKOOUjB4 Aktivni sastojci Hydroxypinacolone Retinoate (HPR – 99% čisti retinoid) Stabilna i efikasna forma retinoida koja deluje direktno na receptore kože bez potrebe za konverzijom. Pomaže u smanjenju pora, zatezanju kože i ublažavanju bora. Efikasan je, a nežniji od tradicionalnog retinola, što ga čini pogodnim i za osetljivu kožu. Acetyl Hexapeptide-8 Peptid poznat kao &#8220;botox u bočici&#8221;, koji opušta mikro-mišiće i smanjuje vidljivost mimičkih bora. Deluje na fine linije oko očiju, čela i usana, pružajući gladak i zategnut izgled kože. Idealan za anti-age negu. Cicahylon&#x2122; (Centella Asiatica + 3 vrste hijaluronske kiseline) Kombinacija umirujuće centelle i hijaluronskih kiselina različitih molekulskih težina koja intenzivno hidrira i regeneriše kožu. Smanjuje crvenilo, poboljšava elastičnost i pomaže u obnovi oštećene barijere. Centella Asiatica Extract Deluje protivupalno, ubrzava regeneraciju kože i smanjuje osjetljivost. Pomaže u smirivanju iritacija izazvanih retinoidima i pruža dodatnu zaštitu osetljivoj koži. Sodium Hyaluronate Oblik hijaluronske kiseline koji prodire duboko u kožu i zadržava vlagu, čineći kožu hidriranom, elastičnom i punijom. Ublažava suvoću i nadraženost. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica Reti-A Essence 0.5 je blaga, ali moćna esencija koje cilja na fine linije i proširene pore dok duboko hidrira i umiruje kožu. Formulacija uključuje 0,5% retinola u kombinaciji sa Cica ekstraktom i 3 vrste hijaluronske kiseline za optimalnu revitalizaciju kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/VT-Cosmetics-Cica-Reti-A-Essence-0.5.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
