INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1384, 162, 'The Potions Peptide Ampoule', 'the-potions-peptide-ampoule', 'Ključne prednosti: Podstiče sintezu kolagena : Kompleks peptida pomaže koži da održi čvrstoću i smanji fine linije. Dubinska hidratacija : Pruža dugotrajnu hidrataciju, što kožu čini mekom i osveženom. Regeneriše i obnavlja : Pomaže u bržoj regeneraciji kože, poboljšava tonus i umanjuje znake starenja. Kome je namenjena? Ova ampula je idealna za sve tipove kože, posebno za osobe koje se bore sa prvim znakovima starenja, dehidratacijom i gubitkom elastičnosti. Pogodna je za svakodnevnu negu i za one koji žele da poboljšaju teksturu i tonus svoje kože. Zašto volimo The Potions Peptide Ampoule ? Peptide Ampoule pruža intenzivnu negu kroz niz peptida koji čine kožu čvrstom i elastičnom. Već nakon prvih nanošenja, peptidi poput bakar tripeptida-1 i heksapeptida-9 stimulišu proizvodnju kolagena i elastina, ključnih proteina za mladalački izgled. Ova ampula hidrira i zadržava vlagu u koži. Njen efekat je posebno primetan kod kože koja pokazuje prve znake starenja ili se suočava sa gubitkom svežine. Redovna upotreba pomaže koži da održi elastičnost, smanji fine linije i daje licu prirodan sjaj i čvrstinu. Aktivni sastojci Bakar tripeptid-1 Poznat po svojoj moći da stimuliše sintezu kolagena i elastina, ovaj peptid obnavlja i regeneriše kožu. Takođe pomaže u smanjenju upala i štiti kožu od štetnih uticaja iz okoline. Tranexamoyl dipeptid-22 Ovaj peptid deluje na ujednačavanje tena, smanjuje pigmentaciju i osvetljava kožu, pružajući svež i zdrav izgled. Heksapeptid-9 Podstiče regeneraciju tkiva i ubrzava proces obnove kože, pomažući pri umanjenju ožiljaka i neravnina. Palmitoil pentapeptid-4 Poznat i kao Matrixyl, ovaj peptid pomaže u smanjenju bora i obnavlja teksturu kože, pružajući dubinsku hidrataciju i podstičući elastičnost. Acetil heksapeptid-8 Poznat kao &#8220;botox u bočici&#8221;, smanjuje mišićne kontrakcije lica, čime pomaže u prevenciji stvaranja finih linija i bora. Dodaj u listu želja Dodaj u listu želja', 'The Potions Peptide Ampoule je visoko koncentrisan serum sa nizom peptida koji podstiču regeneraciju kože, poboljšavaju elastičnost i pružaju dugotrajnu hidrataciju. Formula je lagana, brzo se upija i obnavlja kožu čineći je glatkom i svežom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/The-Potions-Peptide-Ampoule-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
