INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1385, 162, 'The Potions Calamine Ampoule', 'the-potions-calamine-ampoule', 'Ključne prednosti: Umiruje iritacije i crvenilo : Kalamin trenutno smiruje kožu, umanjujući crvenilo i iritaciju. Reguliše lučenje sebuma : Idealno za masnu i kombinovanu kožu jer pomaže u kontroli sebuma bez isušivanja. Štiti od spoljašnjih faktora : Sastojci jačaju kožnu barijeru, čineći je otpornijom na štetne uticaje okoline. Kome je namenjen? Ovaj serum je savršen za masnu, kombinovanu i osetljivu kožu sklonu crvenilu, aknama i iritacijama. Namenjen je onima koji žele hidrataciju bez težine i dodatnu zaštitu od spoljašnjih agresora. Zašto volimo The Potions Calamine Ampoule ? Calamine Ampoule pruža koži zaštitu i umirenje zahvaljujući kalaminu, ključnom sastojku koji se već decenijama koristi za tretiranje crvenila i iritacija. Nakon nanošenja, koža je umirena i osvežena, bez masnog osećaja ili lepljivog sloja. Kalamin i cink pomažu u balansiranju masnoće, smanjujući rizik od akni i masnog sjaja, a sve to dok nežno obnavljaju kožnu barijeru. Ova ampula se brzo upija, omogućavajući da je lako uključite u dnevnu i noćnu rutinu. Dugoročno, koža postaje otpornija, manje sklona crvenilu i blistavija​. Aktivni sastojci Kalamin Glavni aktivni sastojak, kalamin deluje umirujuće na kožu, smanjujući crvenilo i iritacije. Sa visokim sadržajem cinka, kalamin pomaže u kontroli lučenja sebuma, što ga čini idealnim za masnu i kombinovanu kožu. Cink oksid Prirodni antiseptik, cink oksid pomaže u borbi protiv akni i smanjuje upale. On takođe pruža blagu UV zaštitu, štiteći kožu od potencijalnog oštećenja od sunca. Pentilen glikol Hidratant i umirujući sastojak koji pruža vlagu i pomaže da koža ostane hidrirana i meka tokom celog dana. Glicerin Prirodni humektant koji privlači vlagu u kožu, održavajući je duboko hidriranom i poboljšavajući elastičnost. Ekstrakti bilja Neki biljni ekstrakti dodani su formuli za dodatno umirenje i hidrataciju, podržavajući zaštitnu barijeru i smanjujući sklonost kože ka iritaciji. Dodaj u listu želja Dodaj u listu želja', 'The Potions Calamine Ampoule je intenzivan serum sa kalaminom koji umiruje iritiranu kožu, smanjuje crvenilo i kontroliše prekomerno lučenje sebuma. Lagane je teksture, brzo se upija i pruža zaštitu koži od spoljašnjih stresora, čineći je glatkom i osveženom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/The-Potions-Calamine-Ampoule-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
