INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1386, 155, 'Skinfood Royal Honey Propolis Enrich Emulsion', 'skinfood-royal-honey-propolis-enrich-emulsion', 'Ključne prednosti: Intenzivna hidratacija i hranljivost : Bogat humektantima poput meda i hijaluronske kiseline koji duboko hidriraju i omekšavaju. Antioksidativna zaštita : Ekstrakti propolisa i matičnog mleča pomažu u zaštiti kože od oštećenja izazvanih slobodnim radikalima. Poboljšava elastičnost kože : Hranljivi sastojci deluju na tonus kože, čineći je čvršćom i elastičnijom. Kome je namenjena? Ova emulzija je idealna za sve tipove kože, posebno za suvu i grubu kožu kojoj je potrebna intenzivna hidratacija i regeneracija. Namenjena je i osobama sa osetljivom kožom koje žele blagu, ali efikasnu negu. Zašto volimo SKINFOOD Royal Honey Propolis Enrich Emulsion ? Royal Honey Essential Emulsion predstavlja bogatstvo prirodnih hranljivih sastojaka koje pčele stvaraju, čineći ga neizostavnim za ljubitelje prirodne kozmetike. Njegova formula obogaćena medom, propolisom i matičnim mlečom hidrira i omekšava kožu, pružajući joj baršunastu teksturu i dugotrajan osećaj svežine. Zahvaljujući laganoj teksturi, emulzija se brzo upija, a antioksidansi pomažu u smanjenju znakova starenja, čineći kožu svetlijom i elastičnijom. Ovaj proizvod osigurava da je koža osvežena i nahranjena, čak i u suvim klimatskim uslovima. Aktivni sastojci Ekstrakt propolisa (Propolis Extract) Propolis je poznat po svojim snažnim antioksidativnim i regenerativnim svojstvima. Štiti kožu od spoljašnjih štetnih uticaja i oksidativnog stresa, jačajući prirodnu zaštitnu barijeru. Umiruje iritacije, pospešuje zarastanje i poboljšava elastičnost kože. Pomaže u hidrataciji i daje koži zdrav, ujednačen izgled. Pogodan je za sve tipove kože, naročito osetljivu i oslabljenu. Deluje i kao prirodna zaštita od štetnih mikroorganizama. Ekstrakt meda (Honey Extract) Med je prirodni ovlaživač koji zadržava vlagu u koži i sprečava isušivanje. Sadrži vitamine, minerale i enzime koji hrane i revitalizuju kožu. Ima antibakterijska i antiinflamatorna svojstva, pogodna za kožu sklonu iritacijama. Doprinosi mekoći, elastičnosti i prirodnom sjaju kože. Poboljšava teksturu i ujednačava ton. Posebno efikasan za suvu i umornu kožu. Ekstrakt matičnog mleča (Royal Jelly Extract) Matični mleč sadrži bogat spektar nutrijenata – proteine, vitamine B grupe, aminokiseline i minerale. Podstiče regeneraciju kože, jača barijeru i poboljšava otpornost na spoljašnje stresore. Doprinosi ujednačenju tena i poboljšanju tonusa kože. Deluje protiv umora i poboljšava ukupnu vitalnost kože. Čini kožu čvršćom, elastičnijom i osveženom. Idealan za negu zrele i dehidrirane kože. Dodaj u listu želja Dodaj u listu želja', 'SKINFOOD Royal Honey Essential Emulsion kombinuje hranljive ekstrakte meda, propolisa i matičnog mleča za dubinsku hidrataciju i omekšavanje suve i grube kože. Ovaj lagani emolijent pruža antioksidativnu zaštitu, čineći kožu elastičnom i osveženom tokom celog dana.', 'https://beauty-health.rs/wp-content/uploads/2024/11/SKINFOOD-Royal-Honey-Propolis-Enrich-Emulsion-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
