INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1389, 154, 'Skin1004 Madagascar Centella Probio-Cica Essence Toner', 'skin1004-madagascar-centella-probio-cica-essence-toner', 'Ključne prednosti: Umiruje i smanjuje crvenilo : ProBio-Cica kompleks pruža umirujuće efekte, smanjujući iritacije i crvenilo. Dubinska hidratacija : Hijaluronske kiseline različitih molekularnih težina pružaju dugotrajnu vlagu i elastičnost. Jača zaštitnu barijeru kože : Ceramidi pomažu u obnavljanju barijere, čineći kožu otpornijom na spoljašnje stresore. Kome je namenjen? Ovaj toner je idealan za sve tipove kože, posebno za osetljivu, suvu i dehidriranu kožu sklonu crvenilu i iritacijama. Namenjen je onima koji traže efikasnu, ali blagu hidrataciju i zaštitu. Zašto volimo SKIN1004 Madagascar Centella Probio-Cica Essence Toner ? Madagascar Centella Probio-Cica Essence Toner donosi prirodnu snagu fermentisane Centelle Asiatice sa Madagaskara, koja dubinski umiruje i štiti kožu. Ovaj toner pruža balans hidratacije i umirujuće nege zahvaljujući 5 hijaluronskih kiselina koje prodiru u različite slojeve kože, obezbeđujući dugotrajan osećaj svežine. Zahvaljujući lakoj, vodenoj teksturi koja se brzo upija, koža postaje elastična, meka i blistava. ProBio-Cica kompleks jača kožnu barijeru. Bez obzira na to koliko je vaša koža osetljiva, ovaj toner čini je otpornijom i otpornom na crvenilo. Aktivni sastojci Centella Asiatica ekstrakt Poznata po umirujućem i regenerativnom dejstvu, Centella Asiatica pomaže u smanjenju crvenila, iritacija i ubrzava oporavak kože. Jača barijernu funkciju i doprinosi boljoj otpornosti kože na spoljašnje stresore. ProBio-Cica (fermentisani ekstrakt Centella Asiatica sa TECA) Ova veganska komponenta kombinuje fermentisanu Centellu i TECA kompleks za dublje umirivanje i jačanje oslabljene kožne barijere. Pruža efikasnu negu osetljivoj koži, povećava njenu otpornost i poboljšava sposobnost zadržavanja vlage. TECA (Titrirani ekstrakt Centella Asiatica) Koncentrovani aktivni kompleks koji sadrži najefikasnije komponente Centelle: azijatikozid, azijatična i medekasična kiselina. Deluje protiv upala, stimuliše proizvodnju kolagena i pomaže u obnavljanju kože. Betain Prirodni ovlaživač koji pomaže u očuvanju vlažnosti kože i štiti ćelije od dehidratacije. Umiruje i omekšava kožu, čineći je glatkom i elastičnom. Pantenol (Provitamin B5) Hidrira, umiruje i obnavlja kožu, posebno korisno kod osetljive i suve kože. Pomaže u jačanju barijere i sprečava iritacije. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Probio-Cica Essence Toner je esencija-tonik koji kombinuje fermentisanu Centellu Asiatica i 5 tipova hijaluronskih kiselina za dubinsku hidrataciju i jačanje barijere kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/SKIN1004-Madagascar-Centella-Probio-Cica-Essence-Toner-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
