INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1391, 154, 'Skin1004 Madagascar Centella Light Cleansing Oil', 'skin1004-madagascar-centella-light-cleansing-oil', 'Ključne prednosti: Efikasno uklanja šminku i nečistoće : Centella i biljna ulja tope sve slojeve šminke i viška sebuma. Umiruje i hidrira : Centella Asiatica poznata po umirujućim svojstvima, čini ovaj čistač savršenim za osetljivu kožu. Ne ostavlja masni trag : Laka tekstura osigurava da koža ostane sveža i čista, bez masnih ostataka​. Kome je namenjen? Ovaj čistač je idealan za sve tipove kože, posebno za osobe sa osetljivom i suvom kožom, kao i za one koji traže efikasno uklanjanje šminke i dubinsko čišćenje bez iritacije. Zašto volimo SKIN1004 Madagascar Centella Light Cleansing Oil ? Madagascar Centella Light Cleansing Oil osmišljen je da pruži nežno, ali temeljno čišćenje kože. Sastavljen od 10.000 ppm Centelle Asiatice, ovaj čistač smiruje crvenilo i iritacije. Ulja kao što su ulje suncokreta, masline i jojobe efikasno uklanjaju sve tragove šminke, prljavštine i viška ulja. Svaki put kada ga koristite, koža ostaje hidrirana, elastična i zdrava. Zahvaljujući svojoj lakoj formuli, ovo ulje je odličan prvi korak u rutini dvostrukog čišćenja, pripremajući kožu za dalju negu. Aktivni sastojci Centella Asiatica ekstrakt Centella Asiatica, poznata i kao Gotu Kola, tradicionalno se koristi za lečenje manjih rana, opekotina i ogrebotina. Ovaj ekstrakt ima antiinflamatorna svojstva koja mogu pomoći u ublažavanju simptoma ekcema. Aktivne komponente, poput azijatikozida i medekasosida, podstiču sintezu hijaluronske kiseline, što doprinosi hidrataciji kože. Takođe, medekasosid može ubrzati zarastanje opekotina povećanjem antioksidativne aktivnosti i stimulacijom sinteze kolagena. Centella Asiatica se često koristi u proizvodima namenjenim tretmanu celulita ili strija, jer može poboljšati mikrocirkulaciju i normalizovati metabolizam u ćelijama vezivnog tkiva. Ukratko, ovaj ekstrakt je odličan sastojak sa dokazanim svojstvima zarastanja rana, antiinflamatornim i antioksidativnim efektima.​ Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Light Cleansing Oil je lagani uljani čistač formulisan sa Centellom Asiatica iz Madagaskara i 6 biljnih ulja za uklanjanje šminke, sebuma i nečistoća bez iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/11/SKIN1004-Madagascar-Centella-Light-Cleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
