INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1392, 154, 'Skin1004 Madagascar Centella Hyalu-Cica Blue Serum', 'skin1004-madagascar-centella-hyalu-cica-blue-serum', 'Ključne prednosti: Dubinska i dugotrajna hidratacija : Kombinacija 5 molekularnih težina hijaluronske kiseline prodire u sve slojeve kože. Umiruje i osvežava kožu : Centella Asiatica sa Madagaskara smiruje crvenilo i iritacije, pružajući blagu, ali efikasnu negu osetljivoj koži. Jača barijeru kože : Ceramidi pomažu u obnovi kožne barijere i štite je od spoljašnjih uticaja, zadržavajući vitalnu vlagu i otpornost. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za suvu, dehidriranu ili osetljivu kožu. Preporučuje se svima koji žele intenzivnu hidrataciju i posvetljivanje tena uz umirujuće efekte. Zašto volimo SKIN1004 Madagascar Centella Hyalu-Cica Blue Serum ? Madagascar Centella Hyalu-Cica Blue Serum kombinuje umirujući ekstrakt Centelle Asiatice sa pet tipova hijaluronskih kiselina, pružajući optimalnu hidrataciju koja ne nestaje nakon nekoliko sati. Zahvaljujući formuli obogaćenoj ceramidima i niacinamidom, ovaj serum prodire duboko u kožu, pružajući dugotrajan osećaj osveženja i punoće. Nanosite ga svakodnevno za kožu koja izgleda zdravo, mekano i blistavo, bez iritacija. Lagana gelasta tekstura brzo se upija, ostavljajući kožu hidriranom i umirenom, savršeno pripremljenom za dalju negu. Hyalu-Cica (Centella Asiatica Leaf Water + Hyaluronic Acid kompleks) Hyalu-Cica je patentirana kombinacija vode lista Centelle Asiatice i pet različitih molekulskih težina hijaluronske kiseline. Ova sinergijska formula pruža i trenutno umirenje i dubinsku hidrataciju – hijaluronska kiselina prodire u više slojeva kože, dok Centella umiruje upale i jača barijeru. Ova kombinacija ublažava crvenilo, iritacije i osećaj zatezanja, dok istovremeno koži vraća punoću i elastičnost. Deluje brzo i efikasno, čak i kod osetljive i dehidrirane kože. Prikladna je za svakodnevnu upotrebu. Koža ostaje meka, hidrirana i vidljivo zdravija. Sodium Hyaluronate Crosspolymer Ova umrežena forma hijaluronske kiseline nudi produženo delovanje – stvara &#8220;rezervoar vlage&#8221; u koži koji osigurava dugotrajnu hidrataciju. Pored toga, deluje i kao antioksidans, štiteći ćelije kože od oksidativnog stresa. Njena struktura omogućava formiranje zaštitnog filma na površini kože bez osećaja težine. Idealan je sastojak za suvu, zrelu i dehidriranu kožu. Doprinosi glatkijem i punijem izgledu tena. Njegovo delovanje traje i nakon što se proizvod upije, pružajući kontinuiranu negu tokom dana. Niacinamide Niacinamid (Vitamin B3) je višenamenski aktivni sastojak sa dokazanim dejstvom u posvetljavanju kože, smanjenju hiperpigmentacija i regulaciji sebuma. Takođe jača kožnu barijeru, smanjuje upale i pomaže u prevenciji akni. Njegova anti-age svojstva uključuju poboljšanje elastičnosti i ublažavanje finih linija. U ovoj formulaciji, niacinamid doprinosi ujednačenom tenu i zdravijem izgledu kože. Blag je i efikasan, čak i kod reaktivne i problematične kože. Idealno se uklapa u rutinu svakodnevne nege. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Hyalu-Cica Blue Serum je visoko hidratantni serum formulisan za dubinsku hidrataciju, umirivanje i posvetljivanje kože. Kombinacija pet različitih hijaluronskih kiselina i ekstrakta Centelle Asiatice pruža intenzivnu vlagu i osveženje bez osećaja težine.', 'https://beauty-health.rs/wp-content/uploads/2024/11/SKIN1004-Madagascar-Centella-Hyalu-Cica-Blue-Serum-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
