INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1393, 154, 'Skin1004 Madagascar Centella Ampoule', 'skin1004-madagascar-centella-ampoule', 'Ključne prednosti: Umirivanje i obnova : Visoka koncentracija Centele smiruje iritacije i crvenilo, savršeno za osetljivu kožu. Poboljšava hidrataciju : Prirodni humektanti pomažu koži da zadrži vlagu, čineći je svežom i glatkom. Podstiče regeneraciju kože : Podstiče proizvodnju kolagena i ubrzava zaceljivanje. Kome je namenjena? Namenjena je svim tipovima kože, idealna za one sa osetljivom, suvom ili kožom sklonom aknama. Posebno koristna za one koji traže minimalne sastojke i ciljanu hidrataciju. Zašto volimo SKIN1004 Madagascar Centella Ampoule ? Madagascar Centella Ampoule je više od običnog seruma – to je izvor prirodne nege, osmišljen da koži pruži obnovu. Centella Asiatica, poznata kao “tigrova trava” u ovoj formuli igra ključnu ulogu u smirivanju crvenila i iritacija. Svaka kap ampule prožeta je njenim čistim ekstraktom sa Madagaskara, obogaćujući kožu vitalnim saponinima koji pomažu u smanjenju upala i povećavaju elastičnost. Laka, osvežavajuća tekstura ampule brzo se upija, bez masnog osećaja. Sa redovnim korišćenjem, koža postaje sve otpornija, ujednačenijeg tona i zrači prirodnom svežinom. Aktivni sastojci Centella Asiatica Extract Ekstrakt Centella Asiatica, poznat i kao &#8220;tigrova trava&#8221;, snažno deluje umirujuće, regenerativno i protivupalno, čineći ga idealnim za osetljivu, reaktivnu i oštećenu kožu. U ovoj ampuli, ekstrakt je prisutan u visokoj koncentraciji i pomaže u obnavljanju kožne barijere, smanjenju crvenila i iritacija, kao i u ubrzavanju zaceljivanja mikroupa i oštećenja. Aktivne komponente Centelle – madecassoside, asiaticoside i asiatic acid – podstiču sintezu kolagena, čime koža postaje elastičnija i otpornija. Njegovo dejstvo je blago, ali izuzetno efikasno, čak i kod stanja kao što su rozacea, akne i postinflamatorne promene. Dnevnom upotrebom doprinosi ravnoteži kože, čini je hidriranom, smirenom i zdravog izgleda. Ova ampula je formulisana sa minimalnim sastojcima, što je čini izuzetno pogodnom za sve tipove kože, uključujući izrazito osetljivu. Dodaj u listu želja Dodaj u listu želja', 'SKIN1004 Madagascar Centella Ampoule je čista, umirujuća ampula u bočici – napravljena od 100% ekstrakta centele sa Madagaskara. Donosi brzo olakšanje crvenilu, hidrira bez otežavanja i pomaže koži da se regeneriše iz dana u dan.', 'https://beauty-health.rs/wp-content/uploads/2024/11/skin1004-ampoul-serum-centella-ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
