INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1394, 144, 'Rovectin Skin Essentials Dr. Mask Pore', 'rovectin-skin-essentials-dr-mask-pore', 'Ključne prednosti: Smanjuje pore i kontroliše sebum : Taninski kompleks deluje na sužavanje pora i smanjenje viška sebuma. Dubinska hidratacija : Ekstrakt breze obnavlja vlagu u koži, čineći je hidriranom i elastičnom. Umiruje i osvežava : Ekstrakti čajevca i zelenog čaja umiruju iritacije, savršeni za problematičnu kožu. Kome je namenjena? Ova maska je idealna za sve tipove kože, posebno za one sa masnom ili kombinovanom kožom sklonom proširenim porama i viškom sebuma. Zašto volimo Rovectin Aqua Peptide Serum ? Dr. Mask Pore koristi naprednu formulu s taninskim kompleksom, prilagođenu za osobe koje se bore sa proširenim porama i masnim sjajem. Svaki sastojak pažljivo je odabran da pruži dugotrajne efekte: ekstrakt breze dubinski hidrira, vraćajući koži prirodnu svežinu. Čajevac i zeleni čaj umiru crvenilo i sprečavaju nastanak novih upala. Rezultat je ten koji izgleda čisto, sveže i rafinirano, bez osećaja masnoće ili iritacije. Aktivni sastojci Tannin Complex Tanin kompleks je kombinacija biljnih ekstrakata bogatih polifenolima koji deluju adstrigentno, stežući pore i smanjujući njihov vidljivi prečnik. U ovoj maski, osam biljnih izvora tanina efikasno regulišu prekomernu proizvodnju sebuma i doprinose čistijem i uravnoteženijem tenu. Tanini takođe imaju antioksidativno dejstvo koje štiti kožu od oksidativnog stresa izazvanog zagađenjem i UV zračenjem. Birch Tree Extract Ekstrakt breze (Betula) bogat je amino kiselinama, peptidima, solima i organskim kiselinama koje oponašaju prirodne hidratantne faktore kože (NMF). Deluje kao moćan ovlaživač koji obnavlja balans vlage u koži i jača njenu prirodnu barijeru. U ovoj maski pomaže u održavanju svežine i elastičnosti, sprečavajući dehidrataciju tokom tretmana čišćenja pora. Tea Tree Leaf Extract Ekstrakt lista čajevca poznat je po svojim snažnim antibakterijskim i protivupalnim svojstvima. U ovoj formulaciji deluje umirujuće na iritiranu i upaljenu kožu, posebno kod stanja poput akni i začepljenih pora. Takođe pomaže u smanjenju crvenila i ubrzava oporavak kože nakon izbijanja. Charcoal Powder Aktivni ugalj ima izuzetnu moć apsorpcije nečistoća, toksina i viška sebuma iz pora. U ovoj maski deluje kao prirodni detoksifikator koji dubinski čisti kožu, ostavljajući je osveženom i matiranom. Takođe pomaže u prevenciji nastanka mitisera i začepljenja pora, što ga čini idealnim za masnu i kombinovanu kožu. Dodaj u listu želja Dodaj u listu želja', 'Rovectin Skin Essentials Dr. Mask Pore je veganska maska za lice dizajnirana da smanji proširene pore i kontroliše sebum, koristeći jedinstveni kompleks tanina i visoku koncentraciju ekstrakta breze. Maska pruža dubinsku hidrataciju, ostavljajući kožu svežom i matiranom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Rovectin-Skin-Essentials-Dr.-Mask-Pore.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
