INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1401, 138, 'Pyunkang Yul Black Tea Deep Infusion Toner', 'pyunkang-yul-black-tea-deep-infusion-toner', 'Ključne prednosti: Dubinska hidratacija i osveženje : Kombinacija hijaluronske kiseline i niacinamida osigurava dugotrajnu vlagu i blistavost kože. Ojačana barijera i elastičnost : Fermentisani crni čaj i ceramidi jačaju zaštitni sloj kože, smanjujući crvenilo i iritacije. Antioskidativna zaštita i ujednačen ten : Ekstrakti žen-šena i pelina pružaju snažnu zaštitu od slobodnih radikala i poboljšavaju teksturu kože. Kome je namenjen? Prikladan za sve tipove kože, uključujući zrelu, dehidriranu i osetljivu kožu koja pokazuje prve znake starenja ili nepravilnosti u tenu. Zašto volimo Pyunkang Yul Black Tea Deep Infusion Toner ? Ovaj luksuzni tonik kombinuje blagodeti fermentisanog crnog čaja i prirodnih ekstrakata u gelastoj teksturi koja osvežava i revitalizuje kožu. Kombuča, koja je fermentisana tokom 7 do 8 nedelja, bogata je polifenolima koji pružaju snažnu antioksidativnu zaštitu i obnavljaju strukturu kože. Ekstrakti biljaka kao što su žen-šen i pelin, dodatno poboljšavaju teksturu. Hijaluronska kiselina dubinski hidrira i osigurava dugotrajnu mekoću. Redovnom upotrebom, koža postaje otpornija na spoljne faktore, blistava i ujednačenog tena. Aktivni sastojci Fermentisani crni čaj (Kombucha – Black Tea Ferment) Fermentisani crni čaj u ovoj toniranoj infuziji deluje kao pravi eliksir za umornu kožu – bogat je antioksidansima poput teaflavina i tearubigina koji pomažu u borbi protiv slobodnih radikala i znakova starenja. Ovaj sastojak podstiče revitalizaciju kože, poboljšava tonus i pomaže u očuvanju mladolikog izgleda. Zahvaljujući procesu fermentacije, aktivne komponente se bolje apsorbuju i deluju dublje u koži. Redovnom upotrebom, koža postaje elastičnija, svetlija i vidno odmornija. U kombinaciji sa umirujućim biljnim ekstraktima, kombucha daje toniku karakter luksuznog tretmana. Idealna za one koji žele osvežen ten i anti-age benefite u jednom koraku. Artemisia (ekstrakt pelina) Artemisia, poznata i kao pelin, vekovima se koristi u tradicionalnoj azijskoj medicini zbog svojih snažnih umirujućih, antibakterijskih i protivupalnih svojstava. U ovom toniku pomaže u ublažavanju crvenila, balansiranju sebuma i jačanju prirodne otpornosti kože. Bogata je flavonoidima i etarskim uljima koji pomažu u zaštiti kože od stresa iz spoljašnje sredine. Deluje harmonično sa fermentisanim crnim čajem, čineći tonik pogodnim čak i za osetljivu i reaktivnu kožu. Ovaj ekstrakt je tajna mirne i stabilne kože sa zdravim sjajem. Njegovo biljno poreklo doprinosi nežnom, ali efikasnom delovanju. Ekstrakt morske bokvice (Sea Buckthorn / Seaberry) Sea Buckthorn je super-biljka bogata vitaminom C, E i omega masnim kiselinama, poznata po svojim regenerativnim i posvetljujućim efektima. Pomaže u ujednačavanju tena, vraća prirodan sjaj i štiti kožu od UV oštećenja i zagađenja. U ovoj formuli, deluje kao nutritivni booster koji podiže ukupnu efikasnost tonika. Takođe pospešuje obnavljanje ćelija i pomaže u borbi protiv umornog, sivkastog tena. Daje koži energiju i blistavost bez iritacija. Idealna za kožu kojoj nedostaje sjaj i vitalnost. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Black Tea Deep Infusion Toner je luksuzni tonik obogaćen fermentisanim crnim čajem, hijaluronskom kiselinom i biljnim ekstraktima koji dubinski hidrira, ujednačava ten i jača kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Pyunkang-Yul-Black-Tea-Deep-Infusion-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
