INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1402, 138, 'Pyunkang Yul Black Tea Boosting Serum', 'pyunkang-yul-black-tea-boosting-serum', 'Ključne prednosti: Povećana elastičnost i čvrstina : Fermentisani crni čaj i peptidi jačaju strukturu kože, pomažući u smanjenju finih linija. Dubinska hidratacija i umirenje : Hijaluronska kiselina i ekstrakt macadamia ulja hidriraju kožu i poboljšavaju njenu mekoću. Osvetljavanje i ujednačen ten : Niacinamid smanjuje tamne mrlje i posvetljuje kožu, pružajući joj svežinu i blistavost. Kome je namenjen? Serum je idealan za sve tipove kože, posebno zrelu kožu koja pokazuje prve znakove starenja, kao i za osobe koje traže rešenje za umornu i beživotnu kožu. Zašto volimo Pyunkang Yul Black Tea Boosting Serum ? Ovaj serum s crnim čajem pruža moćnu kombinaciju hidratacije i antioksidativne zaštite. Fermentisani crni čaj, bogat polifenolima, obnavlja kožu iznutra, čineći je elastičnijom i otpornijom na štetne faktore iz okoline. Žen-šen i adenosin dodatno poboljšavaju teksturu kože i smanjuju vidljivost bora. Niacinamid posvetljuje ten i ujednačava ga. Uz redovnu upotrebu, koža postaje glatkija, osvežena i zrači zdravim sjajem. Aktivni sastojci Fermentisani crni čaj (Black Tea Ferment / Kombucha) Fermentisani crni čaj, poznat i kao kombucha, obogaćen je polifenolima i antioksidansima koji deluju kao snažna zaštita protiv oksidativnog stresa i znakova starenja. Pomaže u revitalizaciji umorne kože, povećava elastičnost i doprinosi zategnutijem, čvršćem tenu. Fermentacijom se poboljšava biodostupnost aktivnih komponenti, što omogućava dublje prodiranje i efikasnije dejstvo. Peptidi Peptidi su biološki aktivni molekuli koji stimulišu proizvodnju kolagena i elastina, čime direktno utiču na čvrstoću i tonus kože. U ovom serumu, peptidi deluju kao regenerativni agensi koji pomažu u ublažavanju finih linija i jačanju kožne strukture. Takođe doprinose bržem oporavku kože i smanjenju znakova starenja. Adenozin Adenozin je dermatološki priznat sastojak koji deluje protiv bora stimulacijom aktivnosti fibroblasta, ćelija odgovornih za proizvodnju kolagena. Takođe ima umirujuća i obnavljajuća svojstva, što ga čini pogodnim za osetljivu i reaktivnu kožu. U ovoj formuli, adenosin pomaže u ublažavanju znakova starenja i doprinosi zaglađenom i odmornom izgledu kože. Coptis Japonica Root Extract Coptis Japonica, tradicionalna lekovita biljka iz Istočne Azije, poznata je po svom snažnom protivupalnom i umirujućem delovanju. Bogata je berberinom i drugim antioksidantima koji pomažu u smirivanju crvenila, iritacija i upala. U ovom serumu pruža umirujući efekat, čineći ga idealnim za osetljivu, reaktivnu i crvenilu sklonu kožu. Ulje semena makadamije (Macadamia Seed Oil) Ulje makadamije bogato je oleinskom i palmitoleinskom kiselinom, koje obnavljaju lipidni sloj kože i sprečavaju transepidermalni gubitak vlage. Ima regenerativna i umirujuća svojstva, uz izuzetno blagu teksturu koja se brzo upija bez zagušivanja pora. Ekstrakt morske bokvice (Sea Buckthorn / Seaberry) Sea Buckthorn je moćan prirodni izvor vitamina C, E i esencijalnih masnih kiselina, koji osvetljava, revitalizuje i štiti kožu. Deluje antioksidativno, smanjuje znake stresa i umora na koži i pomaže u postizanju ujednačenog, blistavog tena. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Black Tea Boosting Serum je antioksidativni serum obogaćen fermentisanim crnim čajem, žen-šenom i niacinamidom za poboljšanje elastičnosti kože, smanjenje bora i vraćanje prirodnog sjaja licu.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Pyunkang-Yul-Black-Tea-Boosting-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
