INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1411, 111, 'Mary & May Vegan Blackberry Complex Cream Essence', 'mary-may-vegan-blackberry-complex-cream-essence', 'Ključne prednosti: Intenzivna hidratacija : Plava lotosova voda (100,000 ppm) dubinski hidrira kožu, čineći je elastičnom i osveženom. Antioksidativna zaštita : Ekstrakt kupine (50,000 ppm) bogat je antioksidansima, štiteći kožu od štetnih faktora iz okoline. Brzo upijanje : Dvokomponentna emulzija omogućava lako upijanje, ostavljajući kožu svežom i nahranjenom bez masnog osećaja. Kome je namenjena? Preporučuje se za normalnu i masnu kožu, kao i za kožu sklonu dehidrataciji. Idealna je za osobe koje traže laganu, ali intenzivnu hidrataciju uz anti-age efekat. Zašto volimo Mary & May Vegan Blackberry Complex Cream Essence ? Blackberry Complex Cream Essence pruža optimalnu hidrataciju i osveženje za kožu koja traži balans između kreme i esencije. Sa svakim nanošenjem, koža upija bogatstvo kupine, prirodnog izvora antioksidanata. Oni su nezamenljivi u borbi protiv slobodnih radikala, čime se smanjuju znakovi starenja. Plava lotus voda u formulaciji dodatno hidrira i umiruje kožu, dajući joj elastičnost i svežinu tokom celog dana. Lagana, brzo upijajuća tekstura omogućava jednostavno korišćenje bez masnog osećaja na koži. Aktivni sastojci Ekstrakt kupine (50,000 ppm) Ekstrakt kupine bogat je antocijaninima, prirodnim flavonoidima sa snažnim antioksidativnim svojstvima koji štite kožu od slobodnih radikala. Deluje preventivno protiv preranog starenja, poboljšavajući tonus i elastičnost kože. Takođe pomaže u osvežavanju tena i ublažavanju znakova umora i beživotnosti kože. Ovaj ekstrakt doprinosi detoksikaciji i revitalizaciji kože, ostavljajući je čistijom i zdravijom. Ekstrakt plavog lotosa (100,000 ppm) Ekstrakt plavog lotosa deluje umirujuće i hidratantno, dok istovremeno poboljšava elastičnost kože i vraća joj tonus. Bogat antioksidansima i flavonoidima, štiti kožu od oksidativnog stresa i usporava pojavu znakova starenja. Takođe pomaže u obnavljanju kože i podržava prirodni balans vlažnosti. Njegova blaga priroda čini ga pogodnim i za osetljivu kožu, pružajući efekat svežine i mekoće. Biljna ulja iz semena (80,000 ppm) Ulje iz semena bogato je esencijalnim masnim kiselinama koje ojačavaju prirodnu barijeru kože i sprečavaju gubitak vlage. Ova ulja doprinose dugotrajnoj hidrataciji i poboljšanju elastičnosti kože. Takođe deluju umirujuće, smanjujući iritacije i crvenilo, posebno kod suve i osetljive kože. Biljna ulja neguju kožu iznutra, poboljšavajući njenu teksturu i mekoću. Zahvaljujući svojoj hranljivoj i zaštitnoj funkciji, obnavljaju oštećenu kožnu barijeru i povećavaju otpornost na spoljne faktore. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Blackberry Complex Cream Essence nudi savršenu kombinaciju hidratacije i antioksidativne nege. Ovaj dvokomponentni preparat sadrži moćan ekstrakt kupine i plave lotosove vode, pružajući koži bogatu vlagu i zaštitu od slobodnih radikala.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Mary-May-Vegan-Blackberry-Complex-Cream-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
