INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1413, 111, 'Mary & May Idebenone Blackberry Complex Serum', 'mary-may-idebenone-blackberry-complex-serum', 'Ključne prednosti: Maksimalna antioksidantna zaštita : Idebenon je jači od vitamina C i koenzima Q10, štiti kožu od slobodnih radikala. Ujednačavanje tena : Kompleks crne kupine hidrira, poboljšava elastičnost i smanjuje znakove starenja. Lagano upijanje : Serum se brzo upija bez masnog osećaja, ostavljajući kožu svežom i hidriranom. Kome je namenjen? Idealan za sve tipove kože. Posebno za zrelu kožu sklonu finim linijama, suvoći i oštećenjima izazvanim UV zračenjem i drugim stresorima. Zašto volimo Mary & May Idebenone Blackberry Complex Serum ? Idebenone Blackberry Complex Serum kombinuje snagu idebenona, jednog od najefikasnijih antioksidanata, sa kompleksom crne kupine, bogatim antocijaninima. Na taj način dubinski štiti kožu i usporavaoproces starenja. Ovaj serum radi na ćelijskom nivou, boreći se protiv slobodnih radikala i štiteći kožu od oštećenja izazvanih spoljnim faktorima. S obzirom na to da je četiri puta jači od vitamina C i deset puta snažniji od koenzima Q10, idebenon pruža superiornu zaštitu. Pri tom, poboljšava tonus i teksturu kože. Kompleks crne kupine dodatno doprinosi elastičnosti, dajući koži mladalački izgled. Aktivni sastojci Idebenon (1000ppm) Idebenon je snažan sintetički antioksidans, poznat po svojoj visokoj efikasnosti u neutralizaciji slobodnih radikala i zaštiti kože od oksidativnog stresa. Naučno je dokazano da ima jače antioksidativno dejstvo od vitamina C i koenzima Q10, što ga čini izuzetno efikasnim u prevenciji preranog starenja. Pomaže u očuvanju integriteta ćelija kože, ubrzava regeneraciju i smanjuje pojavu finih linija i bora. Njegova stabilnost i niska iritabilnost čine ga pogodnim čak i za osetljive tipove kože. Idebenon takođe poboljšava teksturu kože, čineći je glatkijom i ujednačenijom. Ekstrakt kupine (20%) Ekstrakt kupine je bogat izvor antocijanina, prirodnih flavonoida sa jakim antioksidativnim svojstvima koji štite kožu od štetnih spoljašnjih faktora i stresa. Deluje preventivno protiv naprednih znakova starenja, uključujući gubitak elastičnosti i pojavu diskoloracija. Takođe pomaže u očuvanju vlažnosti kože, osiguravajući joj gipkost i zdrav sjaj. Prisustvo vitamina C i E doprinosi regeneraciji kože i ujednačavanju tena. Ekstrakt kupine ima i blago umirujuće dejstvo, što ga čini pogodnim za svakodnevnu upotrebu. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Idebenone Blackberry Complex Serum je intenzivni anti-age serum sa visokom koncentracijom antioksidanta idebenona i kompleksom crne kupine koji štiti kožu od oštećenja i posvetljuje ten.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Mary-May-Idebenone-Blackberry-Complex-Serum-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
