INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1415, 111, 'Mary & May Blackberry Glow Wash Off Pack', 'mary-may-blackberry-glow-wash-off-pack', 'Ključne prednosti: Dubinsko čišćenje pora – Kombinacija kanadske glacijalne zemlje i francuske zelene gline uklanja nečistoće i višak sebuma, poboljšavajući teksturu kože. Intenzivna hidratacija – Hijaluronska kiselina i alantoin održavaju kožu vlažnom i mekanom. Antioksidantna zaštita – Ekstrakt kupine, bogat antocijaninima, štiti kožu od slobodnih radikala i poboljšava njen ton. Kome je namenjen? Ova maska je idealna za sve tipove kože, posebno za osobe koje žele sveobuhvatnu negu, od dubinskog čišćenja do anti-aging zaštite. Prilagođena je osobama sa masnijom ili kombinovanom kožom, ali je dovoljno nežna i za osetljive tipove. Zašto volimo Mary&May Blackberry Glow Wash Off Pack ? Blackberry Complex Glow Wash Off Pack pruža bogato spa iskustvo kod kuće. Zahvaljujući hranljivom ekstraktu kupine i hidratantnim sastojcima poput hijaluronske kiseline, maska dubinski čisti pore i uklanja nečistoće. Rezultat je koža koja izgleda osveženo i sjajno, kao da je podvrgnuta luksuznoj nezi. Korišćenje maske jednom ili dva puta nedeljno pomaže u održavanju kože hidriranom. Njena nežna, kremasta tekstura omogućava lako nanošenje i ispiranje, čineći je pogodnom za brz i efikasan tretman lica kod kuće. Aktivni sastojci Ekstrakt kupine Ekstrakt kupine je izuzetno bogat antocijaninima, snažnim antioksidansima koji pomažu u neutralizaciji slobodnih radikala i usporavanju procesa starenja kože. Ovaj sastojak doprinosi detoksikaciji kože, uklanjajući nečistoće i toksine iz pora. Takođe podstiče prirodni sjaj kože, čineći ten ujednačenijim i blistavijim. Zahvaljujući visokom sadržaju flavonoida, pruža zaštitu od oksidativnog stresa izazvanog UV zračenjem i zagađenjem. Ekstrakt lista crnog čaja Ekstrakt crnog čaja sadrži bogatstvo polifenola i tanina koji deluju protivupalno i umirujuće na kožu. Njegova antioksidativna svojstva pomažu u zaštiti kože od štetnih uticaja iz okoline, kao što su UV zraci i zagađenje. Deluje adstringentno, što znači da zateže pore i smanjuje njihov izgled. Ovaj sastojak takođe podržava mikrocirkulaciju, čime pospešuje ujednačen ton kože i zdraviji izgled tena. Kaolin (glina) Kaolin je prirodna glina poznata po svojoj sposobnosti da nežno apsorbuje višak sebuma i pročisti pore bez isušivanja kože. Idealna je za masnu i kombinovanu kožu jer balansira lučenje sebuma i smanjuje sjaj. Doprinosi detoksikaciji kože izvlačeći nečistoće i toksine iz dubljih slojeva epidermisa. Njena blaga tekstura omogućava svakodnevnu upotrebu bez narušavanja prirodne barijere kože. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Blackberry Complex Glow Wash Off Pack je hranljiva maska za lice koja dubinski čisti i neguje kožu, ostavljajući je glatkom i blistavom. Obogaćena ekstraktom kupine bogatim antioksidantima, ova maska revitalizuje i štiti kožu, pomažući u borbi protiv znakova starenja.', 'https://beauty-health.rs/wp-content/uploads/2024/11/MaryMay-Blackberry-Glow-Wash-Off-Pack.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
