INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1416, 111, 'Mary & May 6 Peptide Complex Serum', 'mary-may-6-peptide-complex-serum', 'Ključne prednosti: Poboljšava elastičnost kože: Kompleks 6 peptida prodire duboko u kožu, stimulišući proizvodnju kolagena i čineći kožu zategnutijom. Ujednačava teksturu i tonus: Deluje na fine linije i bore, smanjujući njihov izgled i ujednačavajući površinu kože. Pruža dubinsku hidrataciju: Hidrira kožu iznutra, zadržavajući vlagu i održavajući je mekom i glatkom. Kome je namenjen? Idealan je za sve tipove kože, posebno za one koji žele čvrstu, elastičnu kožu i smanjenje vidljivih znakova starenja. Preporučuje se za zrelu kožu, ali i za preventivnu negu kod mlađih korisnika koji žele sačuvati mladalački izgled. Zašto volimo Mary & May 6 Peptide Complex Serum ? 6 Peptide Complex Serum donosi bogatstvo peptida koji prodiru duboko u kožu, pomažući u očuvanju kolagena i podsticanju regeneracije. Peptidi rade na popunjavanju kože, smanjujući bore i fine linije, čineći lice zategnutijim i svežijim. Ovaj serum nudi optimalnu hidrataciju koja traje tokom celog dana, dok svojom laganom teksturom ne opterećuje kožu. Koža postaje osvežena, meka na dodir i blistava, što ga čini idealnim dodatkom svakodnevnoj rutini za negu kože. Redovnom upotrebom, serum doprinosi obnovi kože i poboljšava njenu otpornost na stresne faktore okoline. Aktivni sastojci Peptidni kompleks (6 peptida) Peptidni kompleks sastoji se od šest različitih peptida koji sinergijski deluju kako bi podstakli proizvodnju kolagena i elastina u koži. Ovi biomimetički sastojci imitiraju prirodne signale kože, stimulišući obnavljanje ćelija i poboljšavajući strukturu kože. Posebno su efikasni u smanjenju vidljivosti finih linija i bora, doprinoseći glatkijem i zategnutijem tenu. Peptidi takođe poboljšavaju funkciju zaštitne barijere kože, jačajući njenu otpornost na spoljašnje faktore starenja. Adenozin Adenozin je visoko efikasan sastojak sa dokazanim anti-age dejstvom koji podstiče sintezu kolagena i elastina u dermisu. Deluje direktno na smanjenje bora i finih linija, čineći kožu glatkijom i elastičnijom. Ima umirujuće svojstvo, zbog čega je posebno koristan za osetljivu i nadraženu kožu. Adenozin takođe poboljšava mikrocirkulaciju, što doprinosi ujednačenijem tenu i osveženom izgledu kože. Glicerin Glicerin je prirodni humektant koji privlači vlagu iz okoline u površinske slojeve kože, obezbeđujući dugotrajnu hidrataciju. Ovaj sastojak pomaže u održavanju elastičnosti i mekoće kože, čineći je otpornijom na spoljne uticaje. Takođe doprinosi regeneraciji zaštitne barijere kože, sprečavajući transepidermalni gubitak vode. Dodaj u listu želja Dodaj u listu želja', 'Mary & May 6 Peptide Complex Serum je visoko koncentrovani serum sa 6 različitih peptida, kreiran da podstakne elastičnost i regeneraciju kože. Formulisan je za borbu protiv znakova starenja, poput bora i gubitka čvrstine, pružajući koži svež i blistav izgled.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Mary-May-6-Peptide-Complex-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
