INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1417, 109, 'Manyo Bifida Complex Ampoule Gel Cleanser', 'manyo-bifida-complex-ampoule-gel-cleanser', 'Ključne prednosti: Dubinsko čišćenje bez iritacije: Efikasno uklanja nečistoće, višak sebuma i šminku, bez isušivanja kože. Jača kožnu barijeru: Bifida ferment filtrat i probiotici obnavljaju kožu i štite je od spoljašnjih uticaja. Pruža hidrataciju i svežinu: Gel formula osigurava vlagu i ostavlja kožu mekom i glatkom nakon čišćenja. Kome je namenjena? Ovaj gel za čišćenje pogodan je za sve tipove kože, posebno za osetljivu i suvu kožu, kao i za osobe sa oslabljenom kožnom barijerom. Idealan je za one koji traže efikasno čišćenje bez kompromitovanja hidratacije. Zašto volimo Bifida Complex Ampoule Gel Cleanser ? Bifida Complex Ampoule Gel Cleanser je čistač koji zadovoljava sve potrebe kože: čisti, obnavlja i hidratizuje. Formulisan sa bifida ferment filtratom, deluje dubinski, uklanjajući sve nečistoće sa površine kože dok štiti prirodni balans vlage. Ova moćna formula jača barijeru kože i smanjuje osetljivost, čineći lice otpornijim na spoljašnje faktore i slobodne radikale. Zahvaljujući probioticima, koža postaje izbalansirana i osvežena. Gel tekstura se lako nanosi i transformiše čišćenje u opuštajući ritual koji ostavlja osećaj čistoće i mekoće. Aktivni sastojci Lactobacillus/Panax Ginseng Root Ferment Filtrate i Lactobacillus/Soymilk Ferment Filtrate Ovi fermentisani sastojci pomažu u jačanju zaštitne barijere kože, poboljšavaju njen balans i pružaju umirujuće dejstvo, doprinoseći zdravijem izgledu kože. ​ Kompleks hijaluronske kiseline Sadrži sedam tipova hijaluronske kiseline, uključujući natrijum hijaluronat, hidroksipropiltrimonijum hijaluronat i hidrolizovanu hijaluronsku kiselinu, koji zajedno pružaju intenzivnu hidrataciju, prodirući u različite slojeve kože i ostavljajući je mekom i elastičnom. ​ Ekstrakti biljaka Ekstrakti Centella Asiatica i Camellia Sinensis (zeleni čaj) poznati su po svojim umirujućim i antioksidativnim svojstvima, pomažući u smirivanju iritacija i zaštiti kože od slobodnih radikala. ​ Alantoin Alantoin ima umirujuće dejstvo, pomaže u regeneraciji kože i pruža dodatnu hidrataciju, čineći kožu glatkom i osveženom. ​ Dodaj u listu želja Dodaj u listu želja', 'Manyo Bifida Complex Ampoule Gel Cleanser je blagi gel za čišćenje lica formulisan sa bifida ferment filtratom i probioticima koji uklanjaju nečistoće, dok istovremeno jačaju kožnu barijeru i pružaju dubinsku hidrataciju. Idealan je za svakodnevnu upotrebu, ostavljajući kožu svežom i hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Manyo-Bifida-Complex-Ampoule-Gel-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
