INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1421, 78, 'I&#8217;m From Rice Toner', 'im-from-rice-toner', '9Ključne prednosti: Posvetljuje i ujednačava ten: Ekstrakt pirinča smanjuje hiperpigmentaciju, pružajući blistav i zdrav izgled kože. Dubinska hidratacija: Pomaže koži da zadrži vlagu, sprečavajući isušivanje i čineći je mekšom. Omekšava teksturu kože: Aminokiseline iz pirinča pomažu u regeneraciji, ostavljajući kožu glatkom i elastičnom. Kome je namenjen? Pogodan za sve tipove kože, posebno za osobe sa suvom i dehidriranom kožom koja pati od neujednačenog tena i teksture. Idealno rešenje za one koji traže blagu, prirodnu formulu koja pruža posvetljivanje i intenzivnu hidrataciju. Zašto volimo I&#8217;m From Rice Toner? Rice Toner se oslanja na bogatu tradiciju korišćenja pirinča u nezi kože, donoseći vam sve blagodeti ovog drevnog sastojka u savremenoj formuli. Zahvaljujući visokokvalitetnom ekstraktu pirinča iz Yeoju regiona, toner smanjuje vidljivost tamnih mrlja i ujednačava ten. Pri tom, pomaže koži da zadrži prirodnu vlagu. Kada se nanese, toner stvara baršunast osećaj svežine i hidracije, pripremajući kožu za dalje korake u rutini nege. Redovnim korišćenjem, ovaj toner omekšava grube delove kože, ostavljajući je glatkom, mekom i blistavom. Aktivni sastojci Goami Rice Extract (77.78%) Ekstrakt Goami pirinča bogat je aminokiselinama, vitaminima i mineralima koji revitalizuju kožu i poboljšavaju njenu elastičnost. Deluje umirujuće i pomaže u hidrataciji kože, čineći je glatkom i osveženom. Goami pirinač sadrži veću koncentraciju nutrijenata u poređenju sa običnim pirinčem, što doprinosi intenzivnijem efektu. Podržava prirodnu barijernu funkciju kože i poboljšava njen tonus. Posebno je efikasan kod umorne i beživotne kože kojoj je potrebna obnova. Redovnom upotrebom koža postaje osvetljena, mekša i vizuelno osvežena. Niacinamid Niacinamid, poznat i kao vitamin B3, deluje kao snažan posvetljujući i zaštitni agens za kožu. Pomaže u ujednačavanju tena, smanjenju hiperpigmentacija i osvetljavanju beživotne kože. Takođe jača kožnu barijeru, smanjuje gubitak vlage i balansira proizvodnju sebuma. Deluje protivupalno, što ga čini pogodnim i za osetljivu i aknoznu kožu. U ovoj formuli dodatno pojačava efekat ekstrakta pirinča na sjaj kože. Koža postaje glatka, izbalansirana i zdravog sjaja. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Rice Toner je hidratantni toner sadrži 77,78% ekstrakta pirinča iz Yeoju regije u Koreji, bogatog antioksidansima, za posvetljivanje i omekšavanje kože. Ovaj toner dubinski hidrira i ujednačava ton kože, ostavljajući ten blistavim i revitalizovanim.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Im-From-Rice-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
