INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1425, 82, 'Innisfree Retinol Cica Barrier Defense Cream', 'innisfree-retinol-cica-barrier-defense-cream', 'Ključne prednosti: Regeneriše i smanjuje fine linije: Retinol podstiče obnavljanje ćelija i smanjuje vidljive znakove starenja, poboljšavajući teksturu kože​. Jača i umiruje kožnu barijeru: Defense Cica™ formula sadrži centelu koja umiruje i pomaže u obnovi oštećene kože​. Smanjuje crvenilo i osvežava kožu: Blaga formulacija umanjuje upale i osvežava ten, bez iritacije​. Kome je namenjena? Prikladna za sve tipove kože, posebno za osetljivu, masnu i kožu sklonu aknama i upalama. Idealna za korisnike koji žele poboljšati teksturu kože i smanjiti crvenilo bez iritacija. Zašto volimo Innisfree Retinol Cica Barrier Defense Cream? Retinol Cica Barrier Defense Cream stvorena je za svakodnevnu zaštitu osetljive kože i jačanje njene otpornosti. Sa Defense Cica™ tehnologijom, ova krema smiruje i osnažuje kožu zahvaljujući centeli i fitosterolima, dok retinol visoke čistoće podstiče regeneraciju ćelija i ujednačava teksturu. Kremasta gel formulacija hladi i hidrira, pružajući trenutni osećaj svežine.Redovnom upotrebom smanjuju se vidljivi znakovi starenja i poboljšava tonus kože. Aktivni sastojci Retinol Retinol je visoko efikasan derivat vitamina A koji stimuliše proizvodnju kolagena i ubrzava ćelijsku obnovu. U ovoj formuli koristi se u blagoj koncentraciji, što je idealno za osetljivu kožu i korisnike koji tek uvode retinol u rutinu. Pomaže u smanjenju sitnih bora, poboljšanju teksture i ujednačavanju tena, dok istovremeno umanjuje akne i zapušenost pora. Retinol takođe smanjuje oštećenja nastala usled UV zračenja i podstiče regeneraciju kože. U kombinaciji sa umirujućim sastojcima, kao što je Cica, ovaj oblik retinola deluje bez izazivanja uobičajenih iritacija poput crvenila ili ljuštenja. Cica (Centella Asiatica) Centella Asiatica, poznata i kao Cica, biljka je sa snažnim regenerativnim i protivupalnim svojstvima. Bogata aktivnim komponentama kao što su madecassoside i asiaticoside, Cica umiruje nadraženu kožu i ubrzava proces zarastanja. U ovoj kremi deluje kao balansirajući sastojak koji pomaže u jačanju kožne barijere, posebno pri upotrebi potencijalno iritirajućih sastojaka poput retinola. Pomaže u smanjenju crvenila, osetljivosti i simptoma suve ili reaktivne kože. Takođe stimuliše sintezu kolagena, doprinosi elastičnosti kože i čini ten zdravijim i otpornijim na spoljne stresore. Dodaj u listu želja Dodaj u listu želja', 'Innisfree Retinol Cica Barrier Defense Cream kombinuje retinol visoke čistoće sa patentiranom Defense Cica™ formulom, pružajući dubinsku hidrataciju i umirenje iritacija dok jača kožnu barijeru. Ova lagana gel-krema idealna je za osetljivu kožu sklonu crvenilu i upalama.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Innisfree-Retinol-Cica-Barrier-Defense-Cream-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
