INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1427, 78, 'I&#8217;m From Rice Mask', 'im-from-rice-mask', 'Ključne prednosti: Nežna eksfolijacija i uklanjanje mrtvih ćelija: Pirinčana ljuska i puder pomažu u osvežavanju kože, otkrivajući zdrav sjaj​. Dubinska hidratacija i hranjenje: Vitamini i minerali iz pirinča dubinski hrane kožu, vraćajući joj elastičnost​. Ujednačavanje tena: Vitamin B2 i antioksidanti osvetljavaju i ujednačavaju ten, smanjujući pojavu tamnih mrlja. Kome je namenjena? Idealna je za sve tipove kože, posebno za suvu, grubu i beživotnu kožu koja traži osveženje i nežnu eksfolijaciju. Takođe, i za sve koji žele ujednačen, glatki ten i dubinsku hidrataciju. Zašto volimo I&#8217;m From Rice Cream? Rice Mask koristi prednosti prirodnog korejskog pirinča, bogatog vitaminima i mineralima, kako bi koži pružila dubinsku negu i osveženje. Tekstura maske sa finim granulama pirinča nežno uklanja nečistoće i mrtve ćelije, omogućavajući da koža zablista. Uz redovnu upotrebu, maska čini kožu hidriranom, mekom i otpornijom na spoljne uticaje. Ovo je proizvod koji vraća koži vitalnost i prirodnu blistavost, inspirisan tradicionalnim korejskim ritualima nege, što ga čini jedinstvenim u svakodnevnoj rutini nege lica. Aktivni sastojci Pirinač iz Yeoju, Koreja Pirinač iz Yeoju oblasti poznat je po svom visokom nutritivnom kvalitetu i bogatstvu antioksidansa. U kozmetici, ekstrakt pirinča pruža posvetljujući efekat, čineći ten ujednačenijim i svetlijim. Takođe ima umirujuća svojstva koja pomažu u smanjenju crvenila i iritacija. Njegova lagana eksfolijacija pomaže u uklanjanju mrtvih ćelija kože bez iritacije. Redovnom upotrebom doprinosi mekoj, glatkoj i osveženoj koži. Koža nakon upotrebe deluje čistije, blistavije i revitalizovano. Rice Husk & Rice Bran Ove komponente pirinča deluju kao blagi fizički eksfolijansi koji uklanjaju nakupljene mrtve ćelije kože. Poboljšavaju teksturu kože, oslobađajući površinu od nečistoća i sivila. Pirinčane mekinje su bogate feruličnom kiselinom, snažnim antioksidansom koji štiti kožu od slobodnih radikala. Takođe sadrže prirodne lipide koji podržavaju kožnu barijeru i hidrataciju. U kombinaciji, ove komponente podstiču prirodan sjaj i svežinu kože. Redovnom upotrebom, koža postaje mekša, glađa i zdravije izgleda. Pirinčana voda Pirinčana voda je bogata vitaminima B1, B2 i mineralima koji pomažu u obnavljanju kože i poboljšanju njene elastičnosti. Deluje posvetljujuće, zateže pore i doprinosi pročišćavanju tena. Njena hidratantna svojstva pomažu u održavanju balansa ulja i vlage u koži. Pruža prirodan osvežavajući efekat i vraća koži blistavost. Posebno je pogodna za umornu i beživotnu kožu kojoj je potrebna obnova. Nakon upotrebe, koža deluje podmlađeno, mekano i vidljivo osveženo. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Rice Mask je maska za lice koja koristi 4,1% korejskog pirinča iz Yeoju regiona za nežnu eksfolijaciju, uklanjanje mrtvih ćelija kože i vraćanje prirodnog sjaja. Obogaćena vitaminima B1 i B2, pruža dubinsku hidrataciju, osvežava i ujednačava ton kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Im-From-Rice-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
