INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1428, 78, 'I&#8217;m from Mugwort Essence', 'im-from-mugwort-essence', 'Ključne prednosti: Umiruje iritacije i crvenilo: Divlji pelin smanjuje inflamacije i pomaže koži sklonoj iritacijama​. Pruža dubinsku hidrataciju: Lagan, ali dovoljno hranljiv, ostavlja kožu hidriranom i svežom bez osećaja težine​. Poboljšava tonus i teksturu kože: Deluje blago protiv akni, ujednačava ten i ostavlja kožu čistom i osveženom​. Kome je namenjena? Idealna za sve tipove kože, uključujući osetljivu, masnu i aknama sklonu kožu, posebno za one koji se bore sa crvenilom i iritacijom. Ova esencija pruža potrebnu hidrataciju i smirenost, bez iritirajućih sastojaka. Zašto volimo I&#8217;m from Mugwort Essence? Mugwort Essence donosi blagodeti prirodnog divljeg pelina direktno u vašu rutinu nege kože. Sa jednim glavnim sastojkom &#8211; ekstraktom Artemisia Princeps &#8211; ova esencija umiruje kožu izloženu stresu, smanjujući crvenilo i nelagodnost. Esencija ima blago viskoznu teksturu koja se brzo upija, ostavljajući kožu osveženom i mekanom, idealnom bazom za dalju negu. Zahvaljujući bogatstvu antioksidanata i prirodnim antiinflamatornim svojstvima, ne samo da štiti kožu, već doprinosi ujednačenom tenu i kontroli nad iritacijama. Redovnom upotrebom, koža postaje smirenija, pročišćena i zdravijeg izgleda. Aktivni sastojci Ekstrakt pelina Ekstrakt pelina (mugwort) iz regiona Ganghwa poznat je po svojim snažnim umirujućim i protivupalnim svojstvima. Bogat je antioksidansima, vitaminima i mineralima koji pomažu u zaštiti kože od oksidativnog stresa. Efikasno umiruje iritiranu i osetljivu kožu, smanjujući crvenilo i upale. Takođe pomaže u balansiranju sebuma i pročišćavanju pora, što je čini pogodnom za kožu sklonu aknama. Njegova lagana, ali koncentrisana formula poboljšava teksturu kože i doprinosi ujednačenom tenu. Koža postaje osvežena, hidrirana i vizuelno smirenija. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Mugwort Essence je 100% čist ekstrakt divljeg pelina iz Ganghwa regije, poznat po svojim antiinflamatornim i umirujućim svojstvima, savršen za smirivanje iritacija osetljive kože. Ova jednostavna, ali moćna esencija dubinski hidrira i smanjuje crvenilo, bez dodatnih mirisa i iritacija​.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Im-from-Mugwort-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
