INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1430, 78, 'I&#8217;m from Honey Mask', 'im-from-honey-mask', 'Ključne prednosti: Intenzivna hidratacija i hranljivost: Prirodni med dubinski hidrira i revitalizuje, čineći kožu mekanom i osveženom​. Antibakterijsko i antiinflamatorno dejstvo: Propolis i pčelinji otrov smanjuju crvenilo i štite kožu od bakterija, što doprinosi čistijem tenu​. Poboljšava elastičnost i ujednačava ten: Med i ulja bogata masnim kiselinama smanjuju fine linije i vraćaju koži prirodan sjaj. Kome je namenjena? Prikladna za sve tipove kože, posebno za suvu, zrelu ili iritiranu kožu koja zahteva dodatnu hidrataciju i umirenje. Idealna za one koji žele osvežen ten, smanjenje crvenila i glatku, blistavu kožu. Zašto volimo I&#8217;m From Honey Mask? Honey Mask je inspirisana drevnim ritualima nege medom, poznatim po svojim antiinflamatornim i hranljivim svojstvima. Sa visokim udelom pravog meda sa planine Jirisan, maska dubinski hidrira i umiruje kož. Njena bogata, kremasta tekstura daje osećaj luksuznog tretmana kod kuće. Ekstrakti propolisa i pčelinjeg otrova dodatno smiruju upale i obnavljaju kožnu barijeru, pomažući u borbi protiv znakova starenja i umora. Nakon upotrebe, koža postaje svežija, gipkija i sa prirodnim sjajem, pružajući osećaj trajne udobnosti i elastičnosti. Aktivni sastojci Med (38.7%) Prirodni med iz planine Jiri sadrži obilje enzima, aminokiselina i antioksidanata koji hrane i revitalizuju kožu. Deluje kao prirodni humektant, zadržavajući vlagu u koži i sprečavajući njeno isušivanje. Ima antibakterijska i antiseptička svojstva, što ga čini idealnim za problematičnu i osetljivu kožu. Pomaže u zaceljivanju sitnih oštećenja i smiruje upalne procese. Med takođe pospešuje regeneraciju kože i vraća prirodni sjaj tenu. Koža nakon upotrebe ostaje mekana, hidrirana i zaštićena. Propolis Propolis je prirodni pčelinji proizvod poznat po svojim regenerativnim i zaštitnim svojstvima. Ima moćno antibakterijsko i antioksidativno dejstvo, koje štiti kožu od spoljašnjih uticaja. Pomaže u umirivanju upala i crvenila, te pospešuje zarastanje kože. Takođe jača kožnu barijeru i poboljšava otpornost kože na stres. Posebno koristan kod iritirane, umorne ili oštećene kože. Redovnom upotrebom, koža postaje čvršća, elastičnija i vizuelno osvežena. Pčelinji otrov Pčelinji otrov stimuliše mikrocirkulaciju i proizvodnju kolagena, što doprinosi zategnutijem i elastičnijem izgledu kože. Deluje kao prirodni &#8220;lifting&#8221; sastojak i pomaže u zaglađivanju finih linija. Takođe ima protivupalna svojstva, čime umanjuje crvenilo i iritacije. Povećava apsorpciju drugih aktivnih sastojaka u koži. Iako snažan, u malim količinama je siguran i efikasan u anti-age rutini. Koža postaje blistavija, zategnutija i mladalačkog izgleda. Dodaj u listu želja Dodaj u listu želja', 'I&#8217;m From Honey Mask je luksuzna maska koja sadrži 38,7% prirodnog meda sa planine Jirisan u Koreji, obezbeđujući dubinsku hidrataciju, umirujući efekat i obnovu kože. Ova bogata formula pomaže koži da povrati elastičnost i sjaj, ostavljajući je mekšom i svežom​.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Im-from-Honey-Mask-2.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
