INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1433, 69, 'Haruharu Wonder Centella Phyto &#038; 5 Peptide Concentrate Cream', 'haruharu-wonder-centella-phyto-5-peptide-concentrate-cream', 'Ključne prednosti: Regeneriše i zateže kožu: 5 peptida poboljšava elastičnost kože i smanjuje vidljive znake starenja, poput finih linija i bora​. Dubinska hidratacija i jačanje barijere: Skvalan i ceramidi dubinski hrane i hidriraju kožu, zadržavajući vlagu i jačajući zaštitnu barijeru​. Umiruje i vraća blistavost: Centela ekstrakt smiruje iritacije i poboljšava teksturu kože, dok kofein osvežava i osvetljava ten. Kome je namenjen? Savršen za sve tipove kože, a posebno za one s osetljivom, suvom ili zrelom kožom koja traži intenzivnu negu i anti-age efekat. Preporučuje se osobama koje žele da ojačaju kožnu barijeru, smanje znakove starenja i vrate koži elastičnost. Zašto volimo Haruharu Wonder Centella Phyto & 5 Peptide Concentrate Cream? Ova krema je obogaćena centela ekstraktom, poznatim po svojim umirujućim i regenerativnim svojstvima i moćnim kompleksom od 5 vrsta peptida koji poboljšavaju elastičnost i smanjuju bore. Skvalane i ceramidi zadržavaju vlagu i pružaju zaštitu koži. Kofein i biljni ekstrakti osvetljavaju ten, smanjujući vidljivost tamnih podočnjaka i umora. Sa svakim nanošenjem, koža postaje mekša, otpornija i vidno mlađa. Aktivni sastojci Kompleks 5 peptida Kompleks od pet peptida stimuliše proizvodnju kolagena i elastina, čime poboljšava čvrstoću i elastičnost kože. Peptidi deluju kao signalni molekuli koji podstiču regeneraciju ćelija i smanjuju vidljivost finih linija i bora. Takođe jačaju kožnu barijeru i poboljšavaju teksturu kože, čineći je zategnutijom i ujednačenijom. Njihovo delovanje doprinosi revitalizaciji umorne i zrele kože. Skvalan Skvalan je stabilan emolijent koji oponaša prirodne lipide kože, pružajući intenzivnu hidrataciju bez osećaja težine. Obnavlja lipidnu barijeru i sprečava gubitak vlage, čineći kožu mekom i elastičnom. Takođe ima antioksidativno dejstvo i štiti kožu od preranog starenja. Ne komedogeni je i idealan za sve tipove kože, uključujući masnu i osetljivu. Kofein Kofein ima sposobnost da stimuliše mikrocirkulaciju u koži, što pomaže u redukciji natečenosti i osvežavanju tena. Deluje kao antioksidans i štiti kožu od oksidativnog stresa. Pomaže u ujednačavanju tona i vraćanju svežine umornoj i sivoj koži. Takođe ima blagi efekat zatezanja, što doprinosi glatkijem izgledu. Hidrolizovani proteinski ekstrakt soje Hidrolizovani proteinski ekstrakt soje sadrži aminokiseline koje poboljšavaju elastičnost kože i pomažu u održavanju vlažnosti. Deluje umirujuće i regenerativno, posebno kod kože izložene stresu ili oštećenju. Pomaže u očuvanju čvrstoće kože i doprinosi njenoj glatkoći. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Centella Phyto & 5 Peptide Concentrate Cream je veganska krema koja kombinuje snagu centela ekstrakta i kompleksa od 5 peptida za intenzivnu hidrataciju, umirivanje i regeneraciju kože. Idealna je za poboljšanje elastičnosti i smanjenje finih linija.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Haruharu-Wonder-Centella-Phyto-5-Peptide-Concentrate-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
