INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1434, 69, 'Haruharu Wonder Black Rice Triple AHA Gentle Cleansing Gel', 'haruharu-wonder-black-rice-triple-aha-gentle-cleansing-gel', 'Ključne prednosti: Dubinsko čišćenje i eksfolijacija bez iritacija: Triple AHA kompleks uklanja mrtve ćelije, osvežavajući ten bez isušivanja​. Antioksidativna zaštita i jačanje barijere: Fermentisani crni pirinač i ekstrakt kore bambusa pružaju zaštitu od slobodnih radikala i pomažu koži da zadrži vlagu​. Hidrira i umiruje kožu: Betaine i glicerin pružaju dugotrajnu hidrataciju i smanjuju crvenilo​. Kome je namenjen? Ovaj gel je prikladan za sve tipove kože, posebno za masnu, kombinovanu i kožu sklonu neujednačenoj teksturi. Savršen je za sve koji traže nežno, a efektivno čišćenje s blagim eksfolijativnim efektom za svakodnevnu upotrebu. Zašto volimo Haruharu Wonder Black Rice Triple AHA Gentle Cleansing Gel? Black Rice Triple AHA Gentle Cleansing Gel kombinuje prirodnu snagu fermentisanog crnog pirinča, bogatog antioksidantima i mineralima, sa Triple AHA formulom (tartarinska, mandelična i limunska kiselina). Ova formulacija pomaže u uklanjanju mrtvih ćelija i pruža dubinsko čišćenje. Tokom svakodnevnog čišćenja lica, gel nežno uklanja višak sebuma i nečistoće. Pri tome ne narušava prirodni pH balans kože. Betain i glicerin dodatno osiguravaju hidrataciju i udobnost. Nakon upotrebe, koža je meka, osvežena i spremna za dalju negu. Nema osećaja zatezanja i isušivanja. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Triple AHA Gentle Cleansing Gel je pH-uravnotežen gel za čišćenje koji kombinuje fermentisani crni pirinač i 3 vrste AHA kiselina za dubinsko, a nežno čišćenje i eksfolijaciju. Ovaj veganski gel uklanja nečistoće, višak sebuma i mrtve ćelije, osvežavajući i hidratizujući kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Haruharu-Wonder-Black-Rice-Triple-AHA-Gentle-Cleansing-Gel-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
