INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1435, 69, 'Haruharu Wonder Black Rice Probiotics Barrier Essence', 'haruharu-wonder-black-rice-probiotics-barrier-essence', 'Ključne prednosti: Poboljšava i jača kožnu barijeru: Zahvaljujući kompleksu od pet ceramida i masnih kiselina, pomaže u očuvanju zaštitne barijere i hidratacije​. Povećava elastičnost i revitalizuje: Probiotici i galaktomiceti poboljšavaju elastičnost kože, čineći je glatkom i otpornijom.​ Antioksidativna zaštita: Ekstrakt crnog pirinča bogat je antioksidansima koji štite kožu od slobodnih radikala i znakova starenja. Kome je namenjena? Prikladna za sve tipove kože, a posebno korisna za dehidriranu i osetljivu kožu koja zahteva dodatnu hidrataciju i zaštitu od iritacija. Savršena je za one koji traže lagani, a intenzivno hranljiv proizvod koji obnavlja kožu i vraća joj zdrav sjaj. Zašto volimo Haruharu Wonder Black Rice Probiotics Barrier Essence? Black Rice Probiotics Barrier Essence je tvoj saveznik za svakodnevnu negu. Koristeći fermentisani crni pirinač i probiotike, ova esencija podržava prirodne funkcije kože, inspirišući se korejskom tradicijom. Optimalna hidratacija je osigurana, dok ceramidi i masne kiseline vraćaju koži glatkoću i elastičnost. Esencija bogata antioksidansima iz crnog pirinča pomaže u zaštiti od slobodnih radikala, pružajući koži neophodnu podršku i balans. Aktivni sastojci 3:1:1 Lipid Complex (Ceramides, Cholesterol & Fatty Acids) Ova optimalna kombinacija tri ključne komponente – ceramida, holesterola i masnih kiselina – u odnosu 3:1:1, oponaša prirodnu lipidnu strukturu kože. Pomaže u obnavljanju i jačanju zaštitne barijere kože, posebno kod suve i oslabljene kože. Ceramidi zadržavaju vlagu, holesterol poboljšava fleksibilnost, dok masne kiseline hrane i omekšavaju kožu. Sinergijski deluju na sprečavanje transepidermalnog gubitka vode (TEWL) i povećanje otpornosti kože na spoljne uticaje. Fermented Black Rice Extract Fermentisani ekstrakt crnog pirinča bogat je antioksidansima i nutrijentima koji štite kožu od oksidativnog stresa i pospešuju regeneraciju. Proces fermentacije poboljšava apsorpciju aktivnih sastojaka i čini ih efikasnijim. Deluje umirujuće, posvetljujuće i protivupalno, što ga čini pogodnim za umornu i osetljivu kožu. Galactomyces Ferment Filtrate Galactomyces fermentisani filtrat je bogat vitaminima, aminokiselinama i enzimima koji obnavljaju i ujednačavaju kožu. Deluje kao prirodni osvetljivač, pomažući u smanjenju tamnih mrlja i hiperpigmentacija. Takođe poboljšava hidrataciju i teksturu kože, čineći je glatkom i elastičnom. Ojačava barijernu funkciju i štiti od spoljašnjih iritacija. Bifida Ferment Lysate Bifida ferment lisat je probiotski sastojak koji jača kožnu barijeru i otpornost kože na stresne faktore iz okoline. Pomaže u obnovi kože oštećene UV zračenjem i jača njene prirodne odbrambene mehanizme. Takođe povećava hidrataciju i ublažava znakove starenja, kao što su fine linije i gubitak elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Probiotics Barrier Essence je bogata, mlečna esencija koja koristi moć fermentisanog crnog pirinča i probiotika za jačanje kožne barijere, hidrataciju i obnovu elastičnosti. Lagana i hranljiva, idealna je za svakodnevnu negu kože​.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Haruharu-Wonder-Black-Rice-Probiotics-Barrier-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
