INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1437, 49, 'Dr. Ceuracle Vegan Kombucha Tea Gel Cream', 'dr-ceuracle-vegan-kombucha-tea-gel-cream', 'Ključne prednosti: Dubinsko hidriranje i balansiranje: Kombinacija hidratantnih sastojaka i probiotika pomaže u obnavljanju vlage i zdravog balansa kože​. Smanjuje crvenilo i umiruje: Ekstrakti zelenog čaja i šisandre umiruju iritacije i crvenilo, štiteći kožu od oštećenja​. Antioksidativna zaštita: Kombuča čaj i Camellia Sinensis štite od slobodnih radikala i održavaju elastičnost kože. Kome je namenjena? Idealna za sve tipove kože, posebno za one koji žele laganu, a intenzivnu hidrataciju. Preporučuje se osobama s masnom, kombinovanom ili dehidriranom kožom, kao i onima koji žele efikasnu vegansku kremu za svakodnevnu negu. Zašto volimo Dr. Ceuracle Vegan Kombucha Tea Gel Cream? Ova gel-krema osvežava i revitalizuje kožu zahvaljujući kompleksu prirodnih sastojaka iz Vegan Tea Complex-a, koji uključuje fermentisani kombuča čaj, bogat probioticima i vitaminima B. Kremasta i brzo upijajuća formula prilagođava se svim tipovima kože. Njeno dubinsko hidriranje osigurava osećaj mekoće tokom celog dana. Uz detoksikaciju kože i snažno antioksidativno delovanje, Vegan Kombucha Tea Gel Cream umiruje nadraženost i osigurava dugotrajnu zaštitu od štetnih faktora okoline. Aktivni sastojci Kombucha (Fermented Black Tea) Extract Kombucha je fermentisani crni čaj bogat probioticima, vitaminima B i polifenolima koji jačaju barijernu funkciju kože. Fermentacija omogućava veću biodostupnost hranljivih materija, čime se povećava efikasnost u nezi kože. Deluje antioksidativno, štiteći ćelije kože od oksidativnog stresa i prevremenog starenja. Takođe pomaže u balansiranju sebuma i poboljšava tonus kože. Camellia Sinensis (Green Tea) Leaf Water Voda zelenog čaja bogata je katehinima, poznatim antioksidansima koji neutralizuju slobodne radikale i smanjuju inflamaciju. Doprinosi osveženju i hidrataciji kože bez zatezanja ili težine. Deluje umirujuće i pomaže kod crvenila i iritacija, posebno kod osetljivih i problematičnih tipova kože. Takođe podržava kontrolu viška sebuma, čineći je pogodnom za kombinovanu i masnu kožu. Tannins Tanini su prirodni adstringensi koji se nalaze u čajevima i biljkama, a poznati su po svom učvršćujućem i osvežavajućem efektu na kožu. Pomažu u smanjenju proširenih pora i kontroli proizvodnje sebuma. Imaju i blaga antibakterijska svojstva, korisna kod kože sklone aknama i nečistoćama. Tanini jačaju tonus kože i daju efekat zatezanja bez isušivanja. Dodaj u listu želja Dodaj u listu želja', 'Dr. Ceuracle Vegan Kombucha Tea Gel Cream je lagana hidratantna krema bogata antioksidansima iz fermentisanog kombuča čaja, formulisana za detoksikaciju, smirenje i balans vlage u koži. Ova gel-krema sa 78% kompleksa Vegan Tea Complex pruža dugotrajnu hidrataciju i osvežava kožu bez osećaja masnoće.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Dr.-Ceuracle-Vegan-Kombucha-Tea-Gel-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
