INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1442, 45, 'Dear, Klairs Rich Moist Soothing Cream', 'dear-klairs-rich-moist-soothing-cream', 'Ključne prednosti: Intenzivna i dugotrajna hidratacija: Beta-glukan i hijaluronska kiselina pružaju koži dubinsku hidrataciju koja traje tokom celog dana​. Jača kožnu barijeru: Ceramidi i ulje jojobe obnavljaju zaštitni sloj kože, povećavajući njenu otpornost na spoljašnje uticaje​. Umiruje i smanjuje crvenilo: Prirodni ekstrakti, poput centela i aloe vere, smiruju nadraženu kožu i pomažu u ublažavanju crvenila. Kome je namenjena? Idealna za sve tipove kože, posebno za suvu i osetljivu kožu sklonu iritacijama. Pogodna je za svakodnevnu upotrebu i pruža umirujući efekat za one s osetljivom ili reaktivnom kožom. Zašto volimo Dear, Klairs Rich Moist Soothing Cream? Rich Moist Soothing Cream pruža koži dubinsku hidrataciju i zaštitu tokom celog dana, stvarajući osećaj udobnosti i mekoće. Njena formula bogata beta-glukanom i ceramidima pomaže koži da se oporavi i uspostavi balans. Jojoba ulje i shea puter omekšavaju i hrane kožu. Svi sastojci zajedno smanjuju suvoću i crvenilo, čineći kožu otpornijom na svakodnevne stresove. Sa ovom kremom, koža je umirena, osvežena i vizuelno zdravija, čak i u najhladnijim uslovima. Aktivni sastojci Shea buter (Butyrospermum Parkii Butter) Shea buter je bogat masnim kiselinama i vitaminima, pružajući dubinsku ishranu i hidrataciju koži. Ima antiinflamatorna svojstva koja pomažu u smirivanju iritacija i crvenila. Takođe, štiti kožu od štetnih spoljašnjih faktora poput vetra i UV zračenja. Shea buter poboljšava elastičnost kože i pomaže u smanjenju vidljivosti finih linija. Njegova bogata tekstura čini ga idealnim za suvu i osetljivu kožu kojoj je potrebna dodatna nega. Jojoba ulje (Simmondsia Chinensis Seed Oil) Jojoba ulje je po sastavu slično prirodnim uljima kože, što omogućava lako upijanje bez ostavljanja masnog traga. Pruža dugotrajnu hidrataciju i pomaže u balansiranju proizvodnje sebuma. Ima antiinflamatorna svojstva koja umiruju iritiranu kožu i smanjuju crvenilo. Takođe, bogato je antioksidansima koji štite kožu od oksidativnog stresa i prevremenog starenja. Jojoba ulje poboljšava elastičnost kože i doprinosi njenom zdravom izgledu. Beta-glukan Beta-glukan je polisaharid poznat po svojim umirujućim i regenerativnim svojstvima. Pomaže u smanjenju crvenila i iritacija, čineći ga idealnim za osetljivu kožu. Stimuliše sintezu kolagena, poboljšavajući elastičnost i čvrstinu kože. Takođe, jača imunološku funkciju kože, pomažući u njenoj zaštiti od štetnih mikroorganizama. Beta-glukan pruža dubinsku hidrataciju i poboljšava barijernu funkciju kože. Redovna upotreba može doprineti zdravijem i mladalačkijem izgledu kože.​ Ceramid NP Ceramid NP je lipid koji se prirodno nalazi u koži i ključan je za održavanje njene barijerne funkcije. Pomaže u zadržavanju vlage, sprečavajući isušivanje i povećavajući hidrataciju kože. Obnavlja oštećenu kožnu barijeru, štiteći je od spoljašnjih iritansa i zagađenja. Njegova upotreba može smanjiti crvenilo i iritacije, čineći ga pogodnim za osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'Dear, Klairs Rich Moist Soothing Cream je bogata, hidratantna krema koja trenutno hidrira i umiruje, osiguravajući dugotrajnu udobnost i svežinu. Obogaćena beta-glukanom, ceramidima i uljem jojobe, ova krema jača barijeru kože i smanjuje iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Dear-Klairs-Rich-Moist-Soothing-Cream-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
