INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1443, 45, 'Dear, Klairs Midnight Blue Youth Activating Drop', 'dear-klairs-midnight-blue-youth-activating-drop', 'Ključne prednosti: Povećava elastičnost i čvrstinu: Sadrži peptide koji podržavaju proizvodnju kolagena i pomažu u smanjenju znakova starenja. Umiruje i regeneriše kožu: Sastojci poput guaiazulena smanjuju iritacije, pomažući koži da se oporavi​. Pruža dubinsku hidrataciju: Lagana formulacija hidrira bez težine, čineći kožu glatkom i elastičnom.​ Kome je namenjen? Pogodan za sve tipove kože, uključujući osetljivu i zrelu kožu sklonu prvim znakovima starenja. Idealan je za osobe koje žele blagi, ali efikasan serum koji hidrira, umiruje i pomaže u održavanju mladolikog izgleda. Zašto volimo Dear, Klairs Midnight Blue Youth Activating Drop? Midnight Blue Youth Activating Drop je stvoren za ljubitelje luksuzne noćne nege koja deluje dok spavate. S bogatim dvostrukim peptidima, serum se brzo upija, pomažući regeneraciju kože i ublažavajući znakove umora. Njegova plava nijansa dolazi od guaiazulena, koji smiruje crvenilo i iritacije. EGF (epidermalni faktor rasta) i bFGF (osnovni faktor rasta fibroblasta) podstiču elastičnost i čvrstinu. Ovaj serum deluje iznutra ka spolja, osiguravajući da se koža svakog jutra oseća hidriranom, svežom i obnovljenom. Aktivni sastojci Sh-Oligopeptid-1 (Epidermal Growth Factor, EGF) Sh-Oligopeptid-1, poznat kao EGF, je peptid koji stimuliše proliferaciju epidermalnih ćelija, podstičući regeneraciju kože. Pomaže u poboljšanju teksture kože i smanjenju finih linija i bora. EGF takođe može doprineti ujednačavanju tena i poboljšanju elastičnosti kože. Njegova upotreba može rezultirati glatkijom i mlađom kožom. Sh-Polipeptid-1 (Basic Fibroblast Growth Factor, bFGF) Sh-Polipeptid-1, ili bFGF, je protein koji stimuliše rast fibroblasta, ćelija odgovornih za proizvodnju kolagena i drugih komponenti ekstracelularnog matriksa. Podstiče sintezu kolagena, poboljšavajući čvrstinu i elastičnost kože. Njegova upotreba može doprineti smanjenju vidljivosti bora i poboljšanju ukupne teksture kože. bFGF takođe igra ulogu u procesu zarastanja rana, pomažući u regeneraciji oštećene kože. Gvaiazulen Gvaiazulen je komponenta dobijena iz ulja kamilice, poznata po svojim umirujućim i antiinflamatornim svojstvima. Pomaže u smanjenju crvenila i iritacija, čineći ga pogodnim za osetljivu kožu. Takođe ima antioksidativna svojstva koja štite kožu od štetnih spoljašnjih faktora. Gvaiazulen daje proizvodu karakterističnu plavu boju. Njegova upotreba može doprineti smirenijoj i uravnoteženijoj koži. Dodaj u listu želja Dodaj u listu želja', 'Dear, Klairs Midnight Blue Youth Activating Drop je noćni serum s formulom bogatom dvostrukim peptidima (EGF i bFGF) za smanjenje finih linija i poboljšanje elastičnosti kože. Kreiran da obnavlja i smiruje osetljivu kožu, pruža joj svežinu i mladalački sjaj.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Dear-Klairs-Midnight-Blue-Youth-Activating-Drop.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
