INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1445, 45, 'Dear, Klairs Fundamental Watery Oil Drop', 'dear-klairs-fundamental-watery-oil-drop', 'Ključne prednosti: Dubinska hidratacija bez težine: Ekstrakt zelenog čaja i fermentisani sastojci zadržavaju vlagu, ostavljajući kožu hidriranom i osveženom bez osećaja masnoće​. Antioksidativna zaštita i revitalizacija: Snažni antioksidansi štite kožu od štetnih spoljašnjih faktora, pomažući u borbi protiv znakova starenja​. Poboljšava čvrstoću kože: Peptidi deluju na učvršćivanje kože, pomažući da koža izgleda sveže i tonizirano​. Kome je namenjen? Idealan je za sve tipove kože, uključujući osetljivu i dehidriranu kožu, kao i za one koji žele svežinu i hidrataciju bez masnog osećaja. Preporučuje se za osobe koje traže lagani serum s dubinskom hidratacijom i anti-age efektom. Zašto volimo Dear, Klairs Fundamental Watery Oil Drop? Fundamental Watery Oil Drop osmišljen je za sve koji žele laganu, ali intenzivnu hidrataciju i revitalizaciju kože. Ovaj serum pruža &#8220;stakleni&#8221; sjaj kože, kombinovanjem hidrirajućih i regenerativnih sastojaka. To uključuje zeleni čaj s ostrva Jeju, koji obogaćuje kožu antioksidantima, i fermentisane ekstrakte koji poboljšavaju strukturu i teksturu kože. Zahvaljujući peptidima i ceramidima, koža postaje čvršća, otpornija i vidljivo osvežena. Ovaj serum je savršena dopuna dnevnoj rutini, pružajući dugotrajnu hidrataciju i blistavost tokom celog dana. Aktivni sastojci Camellia Sinensis Leaf Water Camellia Sinensis Leaf Water, poznata kao voda zelenog čaja, bogata je antioksidansima koji štite kožu od slobodnih radikala i oksidativnog stresa. Pomaže u smirivanju upala i crvenila, čineći je pogodnom za osetljivu kožu sklonu iritacijama. Ova komponenta doprinosi hidrataciji i osvežavanju kože, pružajući joj zdrav i blistav izgled. Takođe, poznata je po svojim antimikrobnim svojstvima, što može pomoći u prevenciji akni i drugih kožnih problema. Bifida Ferment Extract Bifida Ferment Extract je probiotski sastojak dobijen fermentacijom bakterija iz roda Bifida. Ojačava prirodnu barijeru kože, povećavajući njenu otpornost na štetne spoljašnje faktore poput zagađenja i UV zračenja. Pomaže u smanjenju osetljivosti kože i ublažava upalne procese, što je korisno za osobe sa iritiranom ili reaktivnom kožom. Ovaj ekstrakt doprinosi hidrataciji kože, poboljšavajući njen ukupni tonus i teksturu. Oryza Sativa (Rice) Extract Ekstrakt pirinča je tradicionalni azijski sastojak poznat po svojim posvetljujućim i omekšavajućim svojstvima. Bogat je vitaminima, mineralima i antioksidansima koji pomažu u ujednačavanju tena i smanjenju hiperpigmentacija. Deluje kao prirodni emolijens, pružajući koži glatkoću i mekoću. Takođe, jača kožnu barijeru, pomažući u zadržavanju vlage i zaštiti od spoljašnjih uticaja. Njegova antiinflamatorna svojstva čine ga pogodnim za umirivanje iritirane kože. Dodaj u listu želja Dodaj u listu želja', 'Dear, Klairs Fundamental Watery Oil Drop kombinuje laganu teksturu seruma sa dubinskom hidratacijom ulja, pružajući koži svežinu, antioksidativnu zaštitu i čvrstoću. Zahvaljujući sastojcima kao što su fermentisani ekstrakti, zeleni čaj i peptidi, ovaj serum pruža optimalnu negu bez masnog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Dear-Klairs-Fundamental-Watery-Oil-Drop.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
