INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1446, 40, 'Cosrx Ultimate Nourishing Rice Overnight Spa Mask', 'cosrx-ultimate-nourishing-rice-overnight-spa-mask', 'Ključne prednosti: Dubinska hidratacija i hranjenje kože: Ekstrakt pirinča hidrira i obnavlja kožu, čineći je glatkom i elastičnom. Ujednačava ten i posvetljuje kožu: Niacinamid u formuli pomaže u posvetljavanju pigmentacija i ujednačavanju tona kože​. Umiruje i štiti kožu: Alantoin umiruje iritacije, dok skvalan pruža dodatnu zaštitu i jača barijeru kože. Kome je namenjen? Savršen za sve tipove kože, posebno za suvu i dehidriranu kožu koja traži dodatnu hidrataciju i hranljive sastojke. Namenjen je osobama koje žele ujednačen ten, meku i osveženu kožu, pogotovo kao deo noćne rutine. Zašto volimo COSRX Ultimate Nourishing Rice Overnight Spa Mask? Ultimate Nourishing Rice Overnight Spa Mask nudi osećaj luksuzne noćne nege koja revitalizuje i obnavlja kožu tokom noći. Ekstrakt pirinča u ovoj maski ne samo da hidrira, već hrani kožu esencijalnim vitaminima i mineralima. Uz dodatak niacinamida za posvetljivanje i skvalana za zaštitu barijere, maska pomaže koži da se oporavi od stresa i suvih mesta, pružajući svež izgled kada se probudite. Lako upijajuća formula čini kožu prijatnom na dodir, dok svakodnevna upotreba doprinosi ujednačenom tenu i osećaju hidratacije koji traje. Aktivni sastojci Ekstrakt pirinča Ekstrakt pirinča je bogat izvor vitamina, minerala i antioksidanata koji doprinose zdravlju i ujednačenosti tena. Njegovo dejstvo na kožu uključuje posvetljivanje hiperpigmentacija i ujednačavanje tonusa, što ga čini pogodnim za neujednačenu i umornu kožu. Deluje kao prirodni emolijens, omekšava kožu i ostavlja je glatkom i hidriranom. Pomaže u jačanju kožne barijere, čime doprinosi zadržavanju vlage i zaštiti od spoljašnjih uticaja. Njegova antiinflamatorna svojstva pomažu u smirivanju iritacija i crvenila, što ga čini pogodnim i za osetljive tipove kože. Redovna upotreba ekstrakta pirinča doprinosi svežijem, blistavijem i odmornijem izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'COSRX Ultimate Nourishing Rice Overnight Spa Mask sadrži više od 68% ekstrakta pirinča za intenzivnu hidrataciju i blistav izgled kože. Ovaj noćni tretman hrani, omekšava i ujednačava ton kože dok spavate, pružajući osećaj kao da ste upravo izašli iz spa tretmana', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Ultimate-Nourishing-Rice-Overnight-Spa-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
