INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1447, 40, 'Cosrx The Retinol 0.5 Oil', 'cosrx-the-retinol-0-5-oil', 'Ključne prednosti: Smanjuje bore i fine linije: Retinol stimulira proizvodnju kolagena, smanjujući pojavu bora i vraćajući koži čvrstinu​. Ujednačava ton i teksturu: Poboljšava strukturu kože, smanjuje pore i posvetljuje pigmentacije.​ Pruža dubinsku hidrataciju i antioksidativnu zaštitu: Skvalan i Super vitamin E štite kožu od slobodnih radikala i zadržavaju vlagu. Kome je namenjeno? Preporučuje se za iskusnije korisnike retinola koji žele snažan anti-age tretman. Pogodan je za normalnu do suvu kožu i za one koji žele smanjenje bora, poboljšanje elastičnosti i hidrataciju. Zašto volimo COSRX The Retinol 0.5 Oil? The Retinol 0.5 Oil pruža luksuzan tretman koji transformiše izgled kože tokom noći. Formulisan sa 0.5% stabilizovanog čistog retinola, ovaj proizvod podstiče regeneraciju ćelija i sintezu kolagen. Efikasno targetira znakove starenja, poput dubokih bora i gubitka elastičnosti. Uz dodatak skvalana, prirodnog hidratanta koji jača barijeru kože, vitamina E, koji pruža antioksidativnu zaštitu, ovaj uljni serum osigurava da koža postane čvrsta, glatka i blistava. Savršen je za korisnike koji žele snažan, ali nežan retinol tretman koji se lako uklapa u noćnu rutinu. Aktivni sastojci Retinol (0.5%) Retinol je aktivna forma vitamina A koja stimuliše proizvodnju kolagena i ubrzava obnavljanje ćelija kože. Deluje dubinski u slojevima kože, smanjujući pojavu finih linija, bora i neujednačene teksture. Takođe pomaže u regulaciji sebuma i smanjenju začepljenih pora, što ga čini korisnim i za kožu sklonu aknama. Kod redovne upotrebe, koža postaje čvršća, glatkija i vizuelno podmlađena. Zbog jače koncentracije (0.5%), preporučuje se postepeno uvođenje kako bi se izbegle iritacije. Skvalan biljnog porekla Biljni skvalan je lagani, nemasni emolijent koji oponaša prirodne lipide kože i pruža dugotrajnu hidrataciju bez začepljivanja pora. Štiti kožu od spoljašnjih iritansa i pomaže u očuvanju njene barijerne funkcije. Deluje umirujuće i obnavljajuće, posebno korisno u formulama s retinolom jer ublažava potencijalnu suvoću i iritaciju. Skvalan doprinosi mekoći, elastičnosti i glatkoći kože. Tokotrienol (Super Vitamin E) Tokotrienol je snažna forma vitamina E sa višestruko jačim antioksidativnim delovanjem od standardnog tokoferola. Štiti kožu od oksidativnog stresa i UV oštećenja, usporavajući proces starenja. Pomaže u regeneraciji kože i ublažava posledice izloženosti spoljašnjim štetnim faktorima. Deluje sinergijski s retinolom, pojačavajući njegov efekat dok istovremeno umanjuje iritacije. Doprinosi smanjenju tamnih fleka, finih linija i gubitka elastičnosti. Dodaj u listu želja Dodaj u listu želja', 'COSRX The Retinol 0.5 Oil sadrži 0.5% čistog retinola za snažan anti-age tretman, namenjen borbi protiv dubokih bora, neujednačene teksture i tona kože. Sa dodatkom skvalana i Super Vitamina E, pruža hidrataciju, zaštitu i mladalački sjaj.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-The-Retinol-0.5-Oil-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
