INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1449, 40, 'Cosrx Low pH Goodnight Soft Peeling Gel', 'cosrx-low-ph-goodnight-soft-peeling-gel', 'Ključne prednosti: Blagi piling bez iritacija: PHA kiseline uklanjaju mrtve ćelije dok istovremeno hidriraju kožu, čineći je mekom i osveženom​. Intenzivna hidratacija: Tri vrste hijaluronske kiseline i biljni ekstrakti zadržavaju vlagu i umiruju kožu.​ Antioksidativna zaštita: Ekstrakti kamelije i ruže štite kožu od slobodnih radikala, pomažući u borbi protiv znakova starenja​. Kome je namenjen? Ovaj čistač je pogodan za sve tipove kože, uključujući osetljivu kožu, kao i za osobe koje žele blagi piling bez iritacija. Zašto volimo COSRX Low pH Goodnight Soft Peeling Gel? Low pH Good Night Soft Peeling Gel pruža noćnu negu koja obnavlja i osvežava kožu dok spavate. Sadrži PHA kiselinu, koja nežno uklanja mrtve ćelije sa površine kože, dok njena blaga formula ne izaziva crvenilo ili iritacije. Hijaluronska kiselina i fermentisani biljni ekstrakti zadržavaju vlagu, pomažući koži da ostane hidrirana i glatka tokom noći. Ovaj proizvod pruža luksuzni osećaj svežine i pomaže da se postigne prirodni sjaj kože, čineći je idealnim za redovnu upotrebu. Aktivni sastojci Celuloza (8%) Celuloza je prirodni biljni polimer koji u ovoj formuli deluje kao fizički eksfolijant za uklanjanje mrtvih ćelija sa površine kože. Njena uloga je da nežno ukloni nečistoće i omekšanu kožu bez iritacije, čime se obnavlja glatkoća i sjaj tena. Za razliku od grubih mehaničkih pilinga, celuloza se razgrađuje trenjem i deluje bez oštećivanja kože. Kombinovana sa blagim kiselinama, omogućava dvostruki efekat – fizički i hemijski piling. Pogodna je za osetljivu kožu jer ne izaziva crvenilo niti osećaj zatezanja. Redovna upotreba pomaže u poboljšanju teksture kože i pripremi za bolju apsorpciju ostalih proizvoda. Hijaluronska kiselina Hijaluronska kiselina je moćan humektant koji zadržava vlagu u koži, čime sprečava isušivanje koje može nastati tokom eksfolijacije. Pomaže u održavanju meke, glatke i elastične kože, čak i nakon uklanjanja mrtvih ćelija. Njena prisutnost u formulaciji omogućava nežnu, ali efikasnu eksfolijaciju uz istovremeno hidriranje. Jača kožnu barijeru i poboljšava sposobnost kože da zadrži vlagu. Pogodna je za sve tipove kože, uključujući i veoma osetljivu i dehidriranu. Rezultat je osvežena, blistava i dubinski hidrirana koža bez iritacija. Dodaj u listu želja Dodaj u listu želja', 'COSRX Low pH Good Night Soft Peeling Gel nudi blagi, ali efikasni piling koji koristi PHA kiselinu za uklanjanje mrtvih ćelija i nečistoća, ostavljajući kožu osveženom i glatkom. Uz dodatak hidratantnih i antioksidativnih sastojaka, ovaj gel je savršen za noćnu negu.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Low-pH-Goodnight-Soft-Peeling-Gel-3.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
