INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1450, 40, 'Cosrx The Retinol 0.3 Cream', 'cosrx-the-retinol-0-3-cream', 'Ključne prednosti: Smanjuje bore i fine linije: Retinol stimuliše proizvodnju kolagena, smanjujući vidljive znakove starenja​. Ujednačava ten i teksturu kože: Ova krema deluje na pore i hiperpigmentacije, pomažući da ten bude ujednačen i blistav​. Pruža dubinsku hidrataciju i zaštitu: Pantenol i hijaluronska kiselina hidriraju kožu, dok antioksidansi štite od oštećenja izazvanih slobodnim radikalima. Kome je namenjena? Preporučuje se za zrelu i normalnu do suvu kožu, kao i za osobe koje su već iskusne u korišćenju retinola. Idealna je za one koji žele tretman protiv bora i poboljšanje elastičnosti kože. Zašto volimo COSRX The Retinol 0.3 Cream? The Retinol 0.3 Cream predstavlja vrhunski tretman protiv starenja za sve koji žele uočljive rezultate. Sa 0.3% čistog retinola, ova krema podstiče regeneraciju ćelija i proizvodnju kolagena, ključnih za smanjenje dubokih bora i finih linija. Dodati Super Vitamin E pruža dodatnu zaštitu od slobodnih radikala. Hijaluronska kiselina i pantenol dubinski hidriraju, čineći kožu elastičnijom. Rezultat je čvršća, ujednačenija i svežija koža koja zrači vitalnošću i mladolikim sjajem. Aktivni sastojci Retinol (0.3%) Retinol, ili čisti oblik vitamina A, poznat je kao jedan od najučinkovitijih sastojaka za smanjenje znakova starenja. Doprinosi ubrzanju obnavljanja ćelija kože, čime se smanjuje vidljivost finih linija, bora i nepravilnosti u teksturi kože. Stimuliše sintezu kolagena, poboljšavajući čvrstoću i elastičnost kože. Takođe pomaže u borbi protiv akni i začepljenih pora, čisteći kožu iznutra. Tokotrienol (Super Vitamin E) Tokotrienol je napredna forma vitamina E sa snažnijim antioksidativnim delovanjem u poređenju sa običnim tokoferolom. Pomaže u zaštiti ćelijskih membrana od oksidativnog stresa i UV oštećenja, čime se usporava proces starenja. Deluje regenerativno, smanjujući crvenilo, upale i oštećenja uzrokovana spoljnim faktorima. Obezbeđuje dodatnu zaštitu retinolu i pomaže u stabilizaciji formule. Panthenol Panthenol (provitamin B5) pruža intenzivnu hidrataciju i pomaže u jačanju kožne barijere. Umiruje iritacije i crvenilo, čineći ga idealnim za upotrebu uz aktivne sastojke poput retinola. Pomaže u zadržavanju vlage, čime koža postaje mekša, elastičnija i otpornija. Doprinosi regeneraciji i obnavljanju kože, posebno kod suvoće izazvane tretmanima protiv starenja. Adenozin Adenozin je aktivni sastojak poznat po svojoj sposobnosti da poboljša elastičnost kože i smanji pojavu bora. Deluje na nivou ćelija, stimulišući njihovu aktivnost i podržavajući regeneraciju tkiva. Posebno je efikasan u zoni finih linija kao što su čelo, područje oko očiju i usta. Doprinosi glatkijem, zategnutijem i čvršćem izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'COSRX The Retinol 0.3 Cream je intenzivna noćna krema sa 0.3% čistog retinola, namenjena smanjenju dubokih bora, poboljšanju elastičnosti i ujednačavanju teksture kože. Formulacija sa Super Vitaminom E i pantenolom pruža hidrataciju i antioksidativnu zaštitu, čineći kožu glatkom i svežom​.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-The-Retinol-0.3-Cream-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
