INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1451, 40, 'Cosrx Clear Fit Master Patch', 'cosrx-clear-fit-master-patch', 'Ključne prednosti: Brzo smanjuje bubuljice: Flaster apsorbuje izlučevine iz bubuljica, čime ubrzava zaceljenje i smanjuje upalu​. Zaštita od spoljašnjih faktora: Kreira barijeru koja štiti problematična područja od bakterija i iritacija​. Diskretan i nevidljiv pod šminkom: Ultra-tanka i matirana završnica čine ga gotovo nevidljivim čak i kada se nosi preko dana. Kome su namenjeni? Flasteri su za osobe sa povremenim bubuljicama koje traže diskretan tretman tokom dana. Namenjeni su svim tipovima kože, uključujući i osetljivu. Zašto volimo COSRX Clear Fit Master Patch? Clear Fit Master Patch omogućava jednostavno i efikasno rešavanje bubuljica, čak i dok ste u pokretu. Zahvaljujući hidrokoloidnoj tehnologiji, ovi flasteri deluju tako što apsorbuju višak sebuma i nečistoće, stvarajući zaštitni sloj preko bubuljica. Njihova ultra-tanka, matirana završnica omogućava da ih nosite tokom dana bez brige o vidljivosti, čak i ispod šminke. Kao dodatna prednost, flasteri štite od bakterija i sprečavaju nastanak ožiljaka, pomažući koži da se brže oporavi. Aktivni sastojci Hidrokoloid (SomadermSpot &#8211; S) Hidrokoloid je materijal koji deluje kao zaštitna barijera i pomaže u ubrzanju zarastanja akni. Efikasno apsorbuje višak sebuma, nečistoće i gnoj iz bubuljica, smanjujući upalu i sprečavajući dalje iritacije. Održava optimalan nivo vlage na zahvaćenom području, čime se smanjuje rizik od ožiljaka i isušivanja kože. Stvara fizičku barijeru koja sprečava dodirivanje i kontaminaciju akni, smanjujući širenje bakterija. Pomaže u smanjenju crvenila i otoka, čineći bubuljice manje vidljivima. Dodaj u listu želja Dodaj u listu želja', 'COSRX Clear Fit Master Patch je ultra-tanki hidrokoloidni flaster dizajniran za brzo i diskretno tretiranje bubuljica. Omogućava brže zarastanje problematičnih područja dok štiti kožu od daljih iritacija i infekcija. U pakovanju se nalazi 18 flastera.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Clear-Fit-Master-Patch-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
