INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1453, 40, 'Cosrx Advanced Snail Peptide Eye Cream', 'cosrx-advanced-snail-peptide-eye-cream', 'Ključne prednosti: Smanjuje tamne kolutove i natečenost: Zahvaljujući niacinamidu i hidratantnim sastojcima, ovaj krem posvetljuje i osvežava umorno područje ispod očiju. Hidratacija i obnova: Puževa sluz i hijaluronska kiselina obezbeđuju dugotrajnu hidrataciju, poboljšavajući teksturu kože​. Smanjuje fine linije: Peptidi stimulišu proizvodnju kolagena, pomažući u održavanju elastičnosti i čvrstoće kože. Kome je namenjena? Idealan za sve tipove kože, posebno za one s vidljivim znakovima umora, tamnim kolutovima i finim linijama ispod očiju. Prilagođen je i za osetljivu kožu, bez parfema i alkohola. Zašto volimo COSRX Advanced Snail Peptide Eye Cream? Advanced Snail Peptide Eye Cream transformiše rutinu nege očiju pružajući bogatstvo hidratacije i regeneracije zahvaljujući puževoj sluzi i peptidima. Ova krema za područje oko očiju ciljano tretira tamne kolutove i natečenost, dok stimulacijom kolagena doprinosi smanjenju finih linija. Krem ima laganu, svilenkastu teksturu koja brzo upija, ostavljajući kožu osveženom i glatkom. Svakodnevnom upotrebom, koža oko očiju postaje blistavija i elastičnija, pružajući odmoran i mladalački izgled. Aktivni sastojci Filtrat puževe sluzi (73.6%) Filtrat puževe sluzi intenzivno hidrira i pomaže u obnavljanju kože oko očiju, smanjujući suvoću i iritacije. Bogat je alantoinom, glikoproteinima i hijaluronskom kiselinom, koji jačaju kožnu barijeru i poboljšavaju elastičnost. Pomaže u smanjenju finih linija i bora, čineći kožu glatkijom i čvršćom. Deluje umirujuće i pomaže u smanjenju nadutosti i tamnih kolutova ispod očiju. Njegova regenerativna svojstva ubrzavaju oporavak oštećene kože i poboljšavaju ukupni izgled. Lagana tekstura omogućava brzo upijanje bez osećaja lepljivosti. Peptidi Peptidi pomažu u stimulaciji sinteze kolagena i elastina, čime poboljšavaju čvrstoću i elastičnost kože oko očiju. Doprinosi smanjenju bora i finih linija, čineći kožu mlađom i svežijom. Ojačavaju strukturu kože i poboljšavaju njenu otpornost na spoljašnje faktore. Pomažu u smanjenju otečenosti i podočnjaka, poboljšavajući mikrocirkulaciju. Njihova moć regeneracije pomaže u dugoročnom očuvanju čvrste i negovane kože. Pogodni su za sve tipove kože, uključujući zrelu i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'COSRX Advanced Snail Peptide Eye Cream pruža intenzivnu hidrataciju i posvetljuje područje oko očiju pomoću 72% filtrata puževe sluzi i peptida. Smanjuje tamne kolutove, fine linije i vrećice ispod očiju, pružajući mladalački izgled.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Advanced-Snail-Peptide-Eye-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
