INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1454, 40, 'Cosrx Advanced Snail Mucin Gel Cleanser', 'cosrx-advanced-snail-mucin-gel-cleanser', 'Ključne prednosti: Dubinsko čišćenje bez isušivanja: Efikasno uklanja nečistoće i ostatke šminke, ali bez skidanja prirodne vlage kože. Obnavljajuće dejstvo: Puževa sluz pomaže regeneraciji ćelija i pruža koži gladak i sjajan izgled. Hipoalergenska formula: Prikladna za sve tipove kože, uključujući osetljivu, zahvaljujući nežnim, bezsulfatnim surfaktantima. Kome je namenjen? Savršen za sve tipove kože, posebno suvu, osetljivu i kožu koja traži regeneraciju i zaštitu od isušivanja. Zašto volimo COSRX Advanced Snail Mucin Gel Cleanser? Advanced Snail Mucin Gel Cleanser čini čišćenje kože prijatnim ritualom obnove i hidratacije. Formulisan sa 10,000 ppm puževe sluzi, ovaj gel omogućava dubinsko uklanjanje nečistoća dok istovremeno regeneriše kožu, čineći je elastičnom i glatkom. Svakim pranjem, koža postaje otpornija na spoljne faktore, dok ostaje mekana i sveža na dodir. Dugotrajnom upotrebom, koža pokazuje vidne znake oporavka i blistavog, mladalačkog izgleda. Aktivni sastojci Filtrat puževe sluzi (10,000 ppm) Filtrat puževe sluzi pruža dubinsku hidrataciju i pomaže u jačanju zaštitne barijere kože. Efikasno čisti kožu bez isušivanja, ostavljajući je mekom i elastičnom. Sadrži alantoin, glikoproteine i hijaluronsku kiselinu, koji umiruju kožu i smanjuju iritacije. Pomaže u regeneraciji kože, čineći je otpornijom na spoljašnje agresore. Takođe pomaže u održavanju prirodne vlage, sprečavajući osećaj zatezanja nakon umivanja. Idealan je za sve tipove kože, uključujući suvu i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'COSRX Advanced Snail Mucin Gel Cleanser koristi snagu puževe sluzi i nežne sastojke za dubinsko čišćenje bez isušivanja. Pruža koži hidrataciju i regeneraciju, ostavljajući je svežom i zaštićenom.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Advanced-Snail-Mucin-Gel-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
