INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1455, 40, 'Cosrx Advanced Snail Kit', 'cosrx-advanced-snail-kit', 'Šta sadrži ovaj set? COSRX Advanced Snail Kit je 4-delnа kolekcija koja uključuje sledeće proizvode: Advanced Snail Mucin Gel Cleanser (20ml) . Blagi gel za čišćenje koji koristi puževu sluz za uklanjanje nečistoća bez isušivanja. Čisti kožu dubinski, zadržavajući prirodnu vlagu, čineći je svežom i glatkom​. Advanced Snail 96 Mucin Power Essence (30ml). Koncentrat puževe sluzi sa 96% filtrata koji intenzivno hidrira i regeneriše kožu. Idealan za obnavljanje oštećenja i poboljšanje elastičnosti, dok kožu ostavlja blistavom i zdravom​ Advanced Snail Peptide Eye Cream (5ml). Luksuzna krema za područje oko očiju koja kombinuje puževu sluz i peptide. Smanjuje fine linije i tamne kolutove, pružajući odmoran izgled i osveženu kožu ispod očiju​. Advanced Snail 92 All In One Cream (20g). Višenamenska krema sa 92% puževe sluzi koja obezbeđuje dubinsku hidrataciju i smiruje kožu. Zadržava vlagu, obnavlja barijeru kože i daje joj glatku teksturu i mekoću​. Ovaj set nudi sveobuhvatnu negu – od čišćenja i hidratacije do revitalizacije kože oko očiju, što ga čini savršenim za dnevne i noćne rutine nege. Ključne prednosti: Duboka hidratacija i obnova: Puževa sluz intenzivno hidrira kožu i podržava prirodnu regeneraciju, poboljšavajući njen kvalitet. Umirujuće dejstvo: Blaga formula umiruje osetljivu i nadraženu kožu, smanjujući crvenilo i iritaciju. Posvetljivanje i ujednačavanje tena: Smanjuje tamne mrlje i posvetljuje kožu, vraćajući joj prirodni sjaj i ujednačenost. Kome je namenjen set? Idealno za sve tipove kože, uključujući osetljivu, suvu i zrelu kožu, kao i za osobe koje žele intenzivnu hidrataciju i tretman za neujednačen ten. Zašto volimo COSRX Advanced Snail Kit? Uz COSRX Advanced Snail Kit, svakodnevna nega postaje ritual obnove i hidratacije. Ovaj komplet sadrži četiri ključna proizvoda koji koriste blagodeti puževe sluzi za dubinsko obnavljanje kože i postizanje svežeg, mladalačkog izgleda. Svaki korak, od čišćenja do hidratacije, osmišljen je tako da poboljša teksturu kože i pomogne u smanjenju tamnih mrlja. Koža postaje vidljivo zdravija, hidrirana i meka na dodir, dok sjaji novom svežinom. Dodaj u listu želja Dodaj u listu želja', 'COSRX Advanced Snail Kit nudi sveobuhvatnu negu kože sa 4 Cosrx popularna preparata obogaćena puževom sluzi, namenjena za hidrataciju, regeneraciju i posvetljivanje tena. Ovaj set je savršen izbor za održavanje zdrave i mladolike kože.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Advanced-Snail-Kit.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
