INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1459, 40, 'Cosrx Acne Pimple Master Patch', 'cosrx-acne-pimple-master-patch', 'Ključne prednosti: Brzo upijanje nečistoća: Hidrogelni sloj upija tečnosti i ubrzava oporavak. Štiti od spoljašnjih faktora: Blokira kontakt s bakterijama i prljavštinom. Sprečava ožiljke: Održava vlagu, smanjujući rizik od trajnih ožiljaka. Kome su namenjeni? Idealni su za osobe sa povremenim ili upornim aknama koje žele brzo i diskretno rešenje za uklanjanje bubuljica. Zašto volimo COSRX Acne Pimple Master Patch? Acne Pimple Master Patch dizajniran je za ciljano tretiranje bubuljica, upijanjem nečistoća i formiranjem zaštitnog sloja koji omogućava koži da se brže oporavi bez iritacija. Hidrogelna tehnologija stvara optimalnu vlažnost na površini kože, sprečavajući dodatne infekcije i ožiljke. Dugotrajnom upotrebom, koža postaje čistija i bez upalnih mesta, omogućavajući korisnicima da izbegnu komplikacije vezane za akne. Aktivni sastojci Hidrokoloid Hidrokoloid je aktivni sastojak koji apsorbuje višak sebuma, nečistoće i gnoj iz bubuljica, ubrzavajući proces zarastanja. Održava optimalan nivo vlage na zahvaćenom području, sprečavajući isušivanje kože i stvaranje ožiljaka. Stvara zaštitnu barijeru koja štiti upaljeno područje od bakterija i spoljašnjih iritansa. Pomaže u smanjenju crvenila i otoka, omogućavajući bubuljicama da brže zarastu. Smanjuje potrebu za dodirivanjem i ceđenjem bubuljica, čime sprečava dalje širenje infekcija. Pogodan je za sve tipove kože, uključujući i osetljivu kožu sklonu aknama. Dodaj u listu želja Dodaj u listu želja', 'COSRX Acne Pimple Master Patch nudi brzo i efikasno rešenje za smanjenje bubuljica, štiteći zahvaćena područja i ubrzavajući proces zarastanja pomoću hidrogelne tehnologije. U pakovanju nalazi se 24 vodootporna flastera za jednokratnu upotrebu – 9 većih, 5 srednjih i 10 manjih, neutralne boje i bez mirisa.', 'https://beauty-health.rs/wp-content/uploads/2024/11/COSRX-Acne-Pimple-Master-Patch-flasteri-za-akne.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
