INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1460, 22, 'Beauty of Joseon Red Bean Refreshing Pore Mask', 'beauty-of-joseon-red-bean-refreshing-pore-mask', 'Ključne prednosti: Dubinsko čišćenje pora &#8211; Crveni pasulj uklanja nečistoće, čini pore manje vidljivim i kožu svežijom. Regulacija sebuma &#8211; Kaolin glina apsorbuje višak ulja, sprečavajući prekomerni sjaj i čineći kožu matiranom. Hidratacija i osveženje &#8211; Ekstrakti kruške i jagode revitalizuju i pružaju koži prirodan sjaj. Kome je namenjena? Ovaj proizvod je idealan za osobe sa kombinovanom do masnom kožom koje žele dubinsko čišćenje i regulaciju sebuma, kao i smanjenje vidljivosti pora. Posebno je pogodan za sve koji se bore sa proširenim porama, prekomernom masnoćom ili neravnom teksturom kože. Zašto volimo Beauty of Joseon Red Bean Refreshing Pore Mask? Zamislite opuštajući ritual uz masku koja ne samo da čisti, već i revitalizuje. Red Bean Refreshing Pore Mask kombinuje drevnu korejsku tradiciju sa savremenim potrebama kože. Crveni pasulj, bogat antioksidansima, nežno eksfolira i osvežava kožu. Kaolin glina temeljno upija višak masnoće bez isušivanja. Nakon tretmana, koža ostaje baršunasta, matirana i vidno osvežena, pružajući vam zdrav i blistav izgled. Aktivni sastojci Ekstrakt crvenog pasulja Haenam (30%) Ekstrakt crvenog pasulja Haenam poznat je po svojoj sposobnosti da apsorbuje višak sebuma i pročišćava pore. Bogat je saponinima koji deluju kao prirodni eksfolijanti, nežno uklanjajući mrtve ćelije kože i poboljšavajući njenu teksturu. Takođe, pomaže u smanjenju masnog sjaja, čineći kožu matiranom i uravnoteženom. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i podržavaju zdraviji izgled tena. Tradicionalno se koristio u dinastiji Joseon u kombinaciji sa mung pasuljem za čišćenje lica i održavanje svežeg i blistavog tena. Redovna upotreba ovog sastojka može poboljšati teksturu kože, smanjiti pojavu proširenih pora i sprečiti začepljenje pora. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Red Bean Refreshing Pore Mask pruža intenzivnu negu i osvežavajuće čišćenje pora, kombinujući prirodnu moć crvenog pasulja sa kaolin glinom. Ova maska osigurava suptilno eksfoliranje, uklanja višak sebuma i osvežava ten.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Beauty-of-Joseon-Red-Bean-Refreshing-Pore-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
