INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1463, 11, 'Anua Retinol 0.3% + Niacin Renewing Serum', 'anua-retinol-0-3-niacin-renewing-serum', 'Ključne prednosti: Smanjuje fine linije i bore : Retinol u koncentraciji od 0,3%stimuliše proizvodnju kolagena, pomažući u smanjenju finih linija. Poboljšava teksturu kože : Niacinamid smanjuje pore i ujednačava ton kože. Duboka hidratacija : Peptidi i ceramidi pružaju dubinsku hidrataciju i štite kožu od isušivanja. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno korisnike starije od 25 godina koji žele da poboljšaju teksturu i ton kože, smanje bore i pore, i pospeše hidrataciju i čvrstinu. Zašto volimo Anua Retinol 0.3% + Niacin Renewing Serum? Retinol 0.3% + Niacin Renewing Serum pruža sveobuhvatnu njegu kože kroz inovativnu kombinaciju retinola i niacinamida. Lagana formula brzo se upija, omogućavajući dubinsku penetraciju i efikasno delovanje aktivnih sastojaka. Retinol, poznat po svojim anti-ageing svojstvima, stimulira obnovu ćelija i povećava proizvodnju kolagena, što rezultira zategnutijom i ujednačenijom kožom. Niacinamid dodaje dodatnu prednost u borbi protiv hiperpigmentacije i velikih pora. Ceramidi i peptidi obnavljaju zaštitnu barijeru kože, čineći je glatkom i hidriranom tokom celog dana. Aktivni sastojci Retinol – 0,3% Retinol, oblik vitamina A, poznat je po svojoj sposobnosti da ubrza obnavljanje ćelija kože, stimuliše sintezu kolagena i elastina, čime smanjuje pojavu finih linija i bora. Takođe, pomaže u poboljšanju teksture kože i ujednačavanju tena, čineći kožu glatkijom i blistavijom. ​ Niacinamid (Vitamin B3) – 5% Niacinamid je višenamenski sastojak koji pomaže u posvetljivanju kože, smanjenju hiperpigmentacija i poboljšanju elastičnosti. Takođe, jača zaštitnu barijeru kože, smanjuje upale i reguliše proizvodnju sebuma, što doprinosi ujednačenom i zdravom tenu. ​ Ceramidi (Ceramide NP) Ceramidi su lipidi prirodno prisutni u koži koji igraju ključnu ulogu u održavanju njene barijerne funkcije. Ceramide NP pomaže u obnovi i jačanju zaštitne barijere kože, sprečava gubitak vlage i štiti je od spoljašnjih agresora, što rezultira hidriranom i otpornijom kožom. ​ Peptidi Serum sadrži kombinaciju peptida, uključujući acetil heksapeptid-8 i bakar tripeptid-1, koji deluju kao signalni molekuli, podstičući proizvodnju kolagena i elastina. Ovi peptidi pomažu u poboljšanju čvrstoće i elastičnosti kože, smanjujući vidljive znakove starenja i doprinoseći mladalačkom izgledu. Dodaj u listu želja Dodaj u listu želja', 'Anua Retinol 0.3% + Niacin Renewing Serum kombinuje moć retinola i niacinamida za ujednačeniji ten i smanjenje znakova starenja. Namenjen je svima koji žele blistaviju, zategnutiju kožu uz smanjene bore i pigmentacijske nepravilnosti.', 'https://beauty-health.rs/wp-content/uploads/2024/11/Anua-Retinol-0.3-Niacin-Renewing-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
