INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1465, 172, 'Vichy Minéral 89 Booster', 'vichy-mineral-89-booster', 'Ključne prednosti: Dubinska hidratacija: Kombinacija hijaluronske kiseline i mineralizovane vode Vichy zadržava vlagu u koži, čineći je punijom i svežijom. Jača kožnu barijeru: Pomaže u obnavljanju zaštitne funkcije kože, smanjujući osećaj zatezanja i suvoće​. Smanjuje znakove umora: Vraća koži blistavost i elastičnost, smanjujući vidljive znakove stresa i umora. Kome je namenjena? Booster je pogodan za sve tipove kože, uključujući i vrlo osetljivu kožu. Namenjen je osobama svih starosnih grupa koje žele dodatnu hidrataciju i jačanje barijerne funkcije kože. Zašto volimo Vichy Minéral 89 Booster? Minéral 89 Booster je prvi korak u rutini nege kože koji intenzivno hidrira i vraća punoću koži. Njegova lagana, brzo upijajuća tekstura omogućava dubinsku hidrataciju bez težine na koži. Zahvaljujući visokoj koncentraciji hijaluronske kiseline, booster zadržava vlagu, dok mineralizovana termalna voda jača kožu i smanjuje osetljivost na spoljašnje iritacije. Kao svakodnevni saveznik u borbi protiv umora, Minéral 89 povećava otpornost kože i daje joj svež, zdrav izgled. Aktivni sastojci Vichy mineralizovana termalna voda Sadrži 15 minerala koji jačaju prirodnu odbranu kože i smanjuju osetljivost na iritacije. Ova voda potiče iz vulkanskih izvora u Francuskoj, obogaćuje kožu esencijalnim mineralima i pomaže u održavanju njene ravnoteže​. Hijaluronska kiselina Visokomolekulska hijaluronska kiselina zadržava vodu na površini kože, dok niskomolekulska hidrira dublje slojeve, pružajući punoću i elastičnost​. Glicerin Doprinosi zadržavanju vlage i dodatno umiruje kožu, smanjujući osećaj suvoće i zatezanja​. Dodaj u listu želja Dodaj u listu želja', 'Vichy Minéral 89 Booster je ultrahidratantni serum formulisan sa 89% Vichy mineralizovane termalne vode i hijaluronskom kiselinom. Ovaj booster jača kožnu barijeru, intenzivno hidrira i obnavlja kožu, čineći je otpornijom na spoljašnje uticaje​.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Vichy-Mineral-89-Booster.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
