INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1468, 101, 'La Roche-Posay Toleriane gel za umivanje', 'la-roche-posay-toleriane-gel-za-umivanje', 'Ključne prednosti: Blago čišćenje: Uklanja nečistoće i šminku bez narušavanja zaštitne barijere kože, što je čini manje reaktivnom na spoljne iritanse. Dubinska hidratacija: Zahvaljujući glicerinima, koža ostaje hidrirana i zaštićena od isušivanja. Umirujuće dejstvo: Smanjuje crvenilo i svrab, ostavljajući kožu umirenom nakon svakog pranja. Kome je namenjena? Ovaj gel je posebno formulisan za osetljivu kožu, uključujući suvu i kožu sklonu iritacijama. Pogodan je za sve uzraste, uključujući decu i odrasle, kao i za osobe sa kožom sklonoj ekcemu ili atopijskom dermatitisu. Zašto volimo La Roche-Posay Toleriane negujući gel? Toleriane negujući gel za pranje lica osmišljen je da pruži optimalno čišćenje za osetljivu kožu bez izazivanja dodatne iritacije. Njegova jedinstvena formulacija sa termalnom vodom bogatom mineralima pruža umirujuće dejstvo, smanjuje osećaj zatezanja i čini kožu otpornijom na spoljašnje faktore. Zahvaljujući kombinaciji nežnih površinski aktivnih supstanci, ovaj gel obnavlja zaštitnu barijeru kože, čineći je hidriranom i zaštićenom tokom celog dana. Namenjen je za upotrebu kao deo svakodnevne rutine čišćenja lica, posebno kod osoba sa suvom i reaktivnom kožom. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Toleriane negujući gel za pranje lica je blagi čistač koji efikasno uklanja nečistoće i šminku, dok istovremeno umiruje i štiti osetljivu kožu. Pogodan je za svakodnevnu upotrebu, ostavljajući kožu hidriranom i mekom na dodir.', 'https://beauty-health.rs/wp-content/uploads/2024/10/La-Roche-Posay-Toleriane-negujuci-gel.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
