INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1469, 101, 'La Roche-Posay Cicaplast Baume B5+', 'la-roche-posay-cicaplast-baume-b5', 'Ključne prednosti: Umirivanje iritacija: Pantenol (provitamin B5) smiruje iritacije, crvenilo i svrab, čineći kožu udobnijom odmah nakon nanošenja. Brza regeneracija kože: Madecassoside, poznat po regenerativnim svojstvima, obnavlja kožnu barijeru i pospešuje zarastanje oštećene kože. Zaštita i hidratacija: Formula bogata hranjivim sastojcima, poput karite butera, pruža intenzivnu hidrataciju i obnavlja lipidni sloj kože. Kome je namenjena? Cicaplast Baume B5 je pogodan za sve tipove kože, uključujući osetljivu kožu, kožu sklonu suvoći i iritacijama. Može se koristiti kod beba, dece i odraslih, uključujući kožu sklonu atopijskom dermatitisu i ekcemima. Zašto volimo La Roche-Posay Cicaplast Baume B5+? Cicaplast Baume B5+ je balzam koji se koristi kada koži treba dodatna podrška – bilo posle iritacija, suvoće, povremenih ispucalosti ili manjih oštećenja. Pantenol u visokoj koncentraciji hidrira i umiruje, dok madecassoside, aktivni sastojak iz Centella asiatica, ubrzava prirodne procese obnove i smanjuje crvenilo. Dodata je i prebiotička komponenta koja podržava ravnotežu mikrobioma, čineći kožu otpornijom na spoljne faktore. Formula stvara zaštitni sloj koji štiti i pomaže zadržavanju vlage, ali bez osećaja težine ili lepljivosti. Tekstura je kremasta, lako se razmazuje i brzo upija. Redovnim korišćenjem, koža postaje mekša, smirenija i otpornija. Aktivni sastojci Pantenol (Vitamin B5) Pantenol je pro-vitamin koji intenzivno hidrira, smanjuje osećaj peckanja i nelagodnosti i ubrzava obnovu kože. Veže vodu u epidermu i smanjuje transepidermalni gubitak vlage. Ima umirujuće dejstvo i ublažava crvenilo i iritacije. Pomaže u obnovi kože nakon manjih oštećenja ili spoljašnjih faktora poput vetra i hladnoće. Dobro se podnosi kod svih tipova kože, uključujući osetljivu i dečju. U ovoj formuli prisutan je u visokoj koncentraciji za maksimalan efekat. Madecassoside Ovaj ekstrakt Centella asiatica biljke poznat je po regenerativnom i umirujućem delovanju. Podstiče fibroblaste, ubrzava obnavljanje tkiva i smanjuje upalu. Posebno je koristan kod crvenila i iritacija. Pomaže da koža bude otpornija na spoljne faktore i brže se oporavi. U kombinaciji sa pantenolom daje balansu hidratacije i reparacije. Blag je i siguran čak i kod osetljivih i dečjih tipova kože. Prebiotički kompleks (Aqua Posae Filiformis + Mannose) Podržava prirodni mikrobiom kože, pomažući korisnim bakterijama da dominiraju nad potencijalno štetnim. Time jača otpornost kože na iritacije i spoljne uticaje. Smanjuje učestalost suvoće i nelagodnosti. Radi sinergijski sa ostalim aktivnim sastojcima za dugotrajan osećaj komfora. Posebno važan kod kože sklone iritacijama i crvenilu. Poboljšava ukupni kvalitet i stabilnost kože. Shea maslac (u manjoj količini) Prirodni emolijent bogat lipidima koji hrani i omekšava površinski sloj. Stvara zaštitni film koji pomaže zadržavanju vlage. Pruža koži mekoću i elastičnost, bez masnog osećaja. Posebno koristan za suve i ispucale regije poput usana ili ruku. U kombinaciji sa pantenolom daje dugotrajan komfor. Pogodan i za osetljive tipove kože. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Cicaplast Baume B5 je višenamenski balzam koji umiruje, regeneriše i štiti osetljivu, nadraženu i suvu kožu. Formulisan je s pantenolom i Madecassoside -om, što ga čini pogodnim za tretiranje raznih stanja kože, uključujući iritacije, suvoću i manja oštećenja kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/La-Roche-Posay-Cicaplast-Baume-B5.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
