INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1470, 101, 'La Roche-Posay Toleriane Sensitive Riche krema', 'lla-roche-posay-toleriane-sensitive-riche-krema', 'Ključne prednosti: Umiruje osetljivost: Smanjuje crvenilo, svrab i osećaj zatezanja zahvaljujući umirujućem dejstvu neurosensina​. Obnavlja kožnu barijeru: Sadrži karite buter, koji pomaže u obnovi hidrolipidnog sloja, smanjujući suvoću i iritaciju​. Intenzivna hidratacija: Obezbeđuje dugotrajnu hidrataciju, ostavljajući kožu mekom i glatkom, bez osećaja masnoće. Kome je namenjena? Toleriane Sensitive Riche je namenjena osobama sa suvom, vrlo suvom i osetljivom kožom, uključujući i one sklone alergijama. Pogodna je za odrasle i decu, uključujući i bebe. Zašto volimo La Roche-Posay Toleriane Sensitive Riche kremu? Ova krema pruža trenutačno olakšanje i dugotrajnu zaštitu za suvu i reaktivnu kožu. Njena bogata tekstura umiruje osetljivost već nakon prve upotrebe, dok dugoročna upotreba pomaže u smanjenju reaktivnosti kože na spoljašnje faktore kao što su promene temperature, tvrda voda i zagađenje. Toleriane Sensitive Riche je dermatološki ispitana i bez mirisa, što dodatno smanjuje rizik od iritacija. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Toleriane Sensitive Riche je intenzivna hidratantna krema razvijena za suvu i osetljivu kožu sklonu alergijama. Formulisana sa minimalnim brojem sastojaka, ova krema umiruje, obnavlja kožnu barijeru i pruža dugotrajnu hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2024/10/La-Roche-Posay-Toleriane-Sensitive-Riche-krema.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
