INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1472, 101, 'La Roche-Posay Termalna Voda', 'la-roche-posay-termalna-voda', 'Ključne prednosti: Umiruje iritacije: Smanjuje crvenilo, osećaj vreline i svrab, što je čini idealnom za osetljivu i reaktivnu kožu. Antioksidativna zaštita: Selen štiti kožu od štetnih uticaja slobodnih radikala i zagađenja. Osvežava i hidrira: Obezbeđuje trenutnu hidrataciju, ostavljajući kožu osveženom i mekom. Kome je namenjen? Ova termalna voda je namenjena svima, uključujući osobe sa osetljivom kožom, ekcemom ili kožom sklonom crvenilu. Pogodna je za novorođenčad, decu, trudnice i odrasle, čineći je idealnim dodatkom svakodnevnoj nezi. Zašto volimo La Roche-Posay termalnu vodu ? La Roche-Posay termalna voda nije samo običan sprej za osveženje. Njena jedinstvena mineralna kompozicija, bogata selenom, pruža koži prirodnu zaštitu, umiruje iritacije i ubrzava zaceljivanje. Korisnici su primetili smanjenje crvenila i osećaja zatezanja već nakon prvih nanošenja, što je čini posebno korisnom nakon izlaganja suncu, brijanja ili drugih iritacija. Praktična za upotrebu u bilo koje doba dana, ova voda može biti čuvana u frižideru za dodatni efekat hlađenja i svežine. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay termalna voda je prirodno bogata selenom i oligoelementima, pružajući umirujuće i zaštitne efekte čak i na najosetljivijoj koži. Pogodna je za sve uzraste i stanja kože, uključujući novorođenčad, decu i odrasle.', 'https://beauty-health.rs/wp-content/uploads/2024/10/La-Roche-Posay-Termalna-Voda.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
