INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1473, 101, 'La Roche-Posay Lipikar Syndet AP+', 'la-roche-posay-lipikar-syndet-ap', 'Ključne prednosti: .Dubinsko čišćenje bez iritacije: Efikasno uklanja nečistoće, ostavljajući kožu mekom, hidriranom i umirenom bez osećaja zatezanja.​ Umiruje kožu i smanjuje svrab: Niacinamid smiruje iritacije, dok karite puter obnavlja lipidni sloj, što je idealno za kožu sklonu atopiji​. Pogodno za celu porodicu: Bez sapuna, sulfata i mirisa, formulacija je prilagođena za svakodnevnu upotrebu kod beba, dece i odraslih. Kome je namenjen? Lipikar Syndet AP+ je namenjen svim uzrastima, od novorođenčadi do odraslih, posebno osobama sa vrlo suvom kožom, atopijskim dermatitisom ili osetljivošću na agresivne sastojke. Zašto volimo La Roche-Posay Lipikar Syndet AP+? Lipikar Syndet AP+ nudi blago, ali temeljno čišćenje koje ne narušava prirodnu barijeru kože. Zahvaljujući Aqua Posae Filiformis kompleksu i niacinamidu, gel pomaže u obnovi ravnoteže mikrobioma kože, smanjujući ponovne epizode suvoće i svraba. Prilagođen je svakodnevnoj rutini nege. Njegova formula bez sulfata osigurava dugotrajnu udobnost kože nakon svakog tuširanja. Ovaj sindet je savršen za celu porodicu, pružajući umirenje i zaštitu suvoj i reaktivnoj koži​. Aktivni sastojci Niacinamid Vitamin B3 umiruje iritacije, smanjuje crvenilo i jača zaštitnu barijeru kože. Deluje protivupalno i pomaže u oporavku suve i reaktivne kože. Smanjuje transepidermalni gubitak vode, što je važno kod učestalog pranja. Blag je i pogodan za kožu svih uzrasta. U ovoj formuli obezbeđuje dodatnu zaštitu i komfor tokom čišćenja. Dugoročno doprinosi smirenijem i otpornijem tenu. Maslac od ši butera Prirodni izvor masnih kiselina koji hrani i omekšava kožu. Pomaže u nadoknadi lipida koji se gube tokom pranja. Stvara zaštitni film koji smanjuje osećaj suvoće i zatezanja. Blag je i siguran za osetljive tipove kože, uključujući bebe. U ovoj formuli daje dodatnu mekoću i sprečava isušivanje. Podržava zdrav izgled kože čak i kod čestog čišćenja. Aqua Posae Filiformis Prebiotički kompleks koji podržava ravnotežu mikrobioma kože. Kada je mikrobiom stabilan, koža je otpornija na iritacije i suvoću. Ovaj sastojak smanjuje učestalost pogoršanja kod atopijskih stanja. Radi u sinergiji sa niacinamidom i lipidima kako bi ojačao odbrambenu funkciju kože. Posebno važan za kožu beba i dece. Dugoročno pomaže održavanju zdrave, stabilne kože. Blagi surfaktanti Čiste kožu bez agresivnog delovanja, poštujući njen pH i prirodnu barijeru. Efikasno uklanjaju nečistoće i višak sebuma, a pritom ne izazivaju suvoću. Pogodni su za osetljive i reaktivne tipove kože. Lako se ispiraju i ostavljaju osećaj čistoće i mekoće. Obezbeđuju nežno, ali temeljno čišćenje svakodnevno. U ovoj formuli doprinose da čišćenje bude bezbedno i prijatno. Dodaj u listu želja Dodaj u listu želja', 'La Roche-Posay Lipikar Syndet AP+ je blagi penušavi gel za čišćenje kože namenjen vrlo suvoj koži i koži sklonoj atopiji. Obogaćen je umirujućim sastojcima poput niacinamida i karite putera, pružajući dugotrajnu hidrataciju i smanjenje svraba već od prvog korišćenja.', 'https://beauty-health.rs/wp-content/uploads/2024/10/La-Roche-Posay-Lipikar-Syndet-AP.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
