INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1475, 160, 'The Face Shop Daily Beauty Tools Mask Sheets', 'the-face-shop-daily-beauty-tools-mask-sheets', 'Ključne prednosti: Efikasna apsorpcija esencija : Suva maska optimizuje upijanje hranljivih sastojaka. Prilagodljivost : Može se koristiti sa bilo kojom esencijom ili serumom po vašem izboru. Lako se koristi : Jednostavno nanošenje omogućava efikasnu rutinu nege. Idealno za sve tipove kože : Pogodne su i za osetljivu kožu. Kome su namenjene? Ova maska je idealna za ljubitelje personalizovane nege, obezbeđujući jednostavan i efikasan način za održavanje zdrave i negovane kože kod kuće. Zašto volimo REJURAN Turnover Mask? THE FACE SHOP Daily Beauty Tools Mask Sheets su suve maske koje se lako koriste i dizajnirane su da upiju bilo koju esenciju ili serum koji odaberete. Ove maske pomažu u zadržavanju vlage i hranljivih sastojaka. Takođe omogućavaju dublju penetraciju aktivnih sastojaka u kožu. Prilagodljive su, što ih čini idealnim za sve tipove kože, bez obzira na specifične potrebe. Savršene su za svakodnevnu upotrebu ili kao deo vaše vikend skincare rutine. Dodaj u listu želja Dodaj u listu želja', 'THE FACE SHOP Daily Beauty Tools Mask Sheets su visokokvalitetne suve maske napravljene od mekog materijala koji efikasno upija sve vrste esencija, tonera ili seruma. Idealne su za personalizovane tretmane lica, pružajući vašoj koži potrebnu negu i hidrataciju.', 'https://beauty-health.rs/wp-content/uploads/2024/10/THE-FACE-SHOP-Daily-Beauty-Tools-Mask-Sheets.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
