INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1477, 140, 'Rejuran Derma Healer Moisture Treatment Mask', 'rejuran-derma-healer-moisture-treatment-mask', 'Ključne prednosti: Intenzivna hidratacija: Hijaluronska kiselina zadržava vlagu u koži, ostavljajući je elastičnom i glatkom. Obnavljanje kože: Polinukleotidi c-PDRN stimulišu regeneraciju oštećenih ćelija i poboljšavaju elastičnost kože. Zaštita kože: Ectoin štiti kožu od UV zračenja i zagađenja, smanjujući iritacije i jačajući kožnu barijeru. Kome je namenjen? Maska je idealna za sve tipove kože, posebno za suvu, osetljivu ili oštećenu kožu. Preporučuje se osobama koje žele intenzivnu hidrataciju, regeneraciju i smanjenje bora i crvenila. Zašto volimo REJURAN Derma Healer Moisture Treatment Mask? Derma Healer Moisture Treatment Mask pruža intenzivnu hidrataciju i regeneraciju tokom noći, koristeći c-PDRN, sastojak koji potiče iz DNK lososa. Ovaj polinukleotid ubrzava obnavljanje kože na ćelijskom nivou, poboljšava tonus i smanjuje fine linije. Pored c-PDRN-a, maska sadrži hijaluronsku kiselinu i Ectoin, koji pružaju dodatnu hidrataciju i zaštitu od spoljašnjih faktora, uključujući UV zračenje i zagađenje. Ova sinergija sastojaka rezultira glatkijom, punijom i elastičnijom kožom. Aktivni sastojci c-PDRN® (Polydeoxyribonucleotide) c-PDRN® je patentirani sastojak baziran na fragmentima DNK, poznat po svojoj sposobnosti da ubrza regeneraciju ćelija i oporavi oštećenu kožu. Deluje dubinski, stimulišući sintezu kolagena i obnavljajući strukturu kože iznutra. Njegovo snažno regenerativno dejstvo posebno dolazi do izražaja kod kože sa narušenom barijernom funkcijom, crvenilom i iritacijama. U ovoj maski, c-PDRN® deluje kao centralni obnavljajući agens, koji pomaže u jačanju otpornosti kože na spoljašnje stresore. Klinički je potvrđeno da poboljšava hidriranost kože i ujednačenost tona. Idealan je za osetljivu, dehidriranu i suvu kožu kojoj je potrebna dubinska obnova. Dodaj u listu želja Dodaj u listu želja', 'REJURAN Derma Healer Moisture Treatment Mask je maska za hidrataciju koja koristi polinukleotid c-PDRN, moćan sastojak poznat po svojim regenerativnim svojstvima. Ova maska poboljšava elastičnost, hidrataciju i tonus kože, čineći je glatkijom i sjajnijom.', 'https://beauty-health.rs/wp-content/uploads/2024/10/REJURAN-Derma-Healer-Moisture-Treatment-Mask-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
