INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1478, 166, 'Tonymoly Triple Collagen Total Tension Mist', 'tonymoly-triple-collagen-total-tension-mist', 'Ključne prednosti: Intenzivno zatezanje i hidratacija: Triple Collagen Complex zateže kožu i smanjuje vidljivost bora, dok je istovremeno dubinski hidrira i omekšava. Ujednačen ton kože: Niacinamid smanjuje hiperpigmentaciju i posvetljuje kožu, dajući joj ujednačeniji i blistaviji izgled. Zaštita od slobodnih radikala: Glutation pruža snažnu antioksidativnu zaštitu, smanjujući oštećenja uzrokovana UV zračenjem i zagađenjem, čineći kožu otpornijom. Kome je namenjen? Mist je namenjen svim tipovima kože, a posebno je koristan za zrelu kožu koja se suočava sa gubitkom elastičnosti, hiperpigmentacijom ili suvoćom. Pogodan je za sve koji žele dodatnu hidrataciju i posvetljivanje tena Zašto volimo TONYMOLY Triple Collagen Total Tension Mist? Triple Collagen Total Tension Mist pruža višestruke efekte u jednom jednostavnom koraku. Sa tri vrste kolagena, ovaj sprej ne samo da hidrira, već i aktivno zateže kožu, poboljšava njenu teksturu i smanjuje vidljivost bora. Niacinamid pomaže u ujednačavanju tena i smanjenju crvenila. Gutation dodatno osigurava zaštitu od oksidativnog stresa. Sprej je lagan i brzo se apsorbuje, ostavljajući kožu osveženom i blistavom tokom celog dana. Aktivni sastojci Triple Collagen (uključujući patentirani Collagen Boom™) Napredna kombinacija tri tipa kolagena koja intenzivno poboljšava elastičnost kože i smanjuje vidljivost bora. Fermentisani veganski kolagen dubinski prodire u kožu, učvršćuje je i vraća joj tonus. Posebno efikasan za kožu koja je izgubila čvrstinu i punoću. Niacinamid Vitamin B3 koji posvetljuje ten, smanjuje tamne mrlje i ujednačava boju kože. Takođe jača kožnu barijeru, poboljšava elastičnost i doprinosi osvetljenom i ujednačenom tenu. Vitamin C (Askorbinska kiselina) Snažan antioksidans koji posvetljuje i štiti kožu od slobodnih radikala. Pomaže u smanjenju hiperpigmentacija i podstiče sintezu kolagena za blistav, mladolik izgled. Dodaj u listu želja Dodaj u listu želja', 'TONYMOLY Triple Collagen Total Tension Mist je hidratantni sprej formulisan sa trostrukim kompleksom kolagena, niacinamidom i hijaluronskom kiselinom. Pruža momentalnu svežinu, zatezanje i posvetljivanje kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/TONYMOLY-Triple-Collagen-Total-Tension-Mist.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
