INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1480, 109, 'Manyo Bifida Ampoule Mist', 'manyo-bifida-ampoule-mist', 'Ključne prednosti: Jačanje kožne barijere: Bifida ferment lizat obnavlja oštećenu kožnu barijeru, čineći je otpornijom na spoljašnje faktore. Dubinska hidratacija: Hijaluronska kiselina zadržava vlagu u koži, povećavajući njenu punoću i elastičnost. Smanjenje bora: Peptidi stimulišu proizvodnju kolagena, zatežu kožu i smanjuju vidljivost finih linija. Kome je namenjen? Ovaj sprej je idealan za sve tipove kože, posebno za suvu, dehidriranu ili osetljivu kožu. Namenjen je svima koji žele dodatnu hidrataciju i jačanje barijere tokom dana, kao i borbu protiv znakova starenja​ Zašto volimo MANYO Bifida Ampoule Mist? Bifida Ampoule Mist je savršeno rešenje za trenutnu hidrataciju i dugotrajno jačanje kože. Njegova formula sadrži 20% bifida ferment lizata, koji regeneriše oštećenu kožu i povećava njenu otpornost. Peptidi deluju na povećanje elastičnosti kože, dok hijaluronska kiselina pruža dubinsku vlagu. Dodavanje gljivičnih ekstrakata doprinosi smanjenju iritacija, dok koži pruža zaštitu od štetnih uticaja iz spoljašnje sredine. Aktivni sastojci Bifida Lacto Kompleks Ovi probiotički fermenti pomažu u jačanju zaštitne barijere kože, poboljšavaju njenu otpornost na spoljašnje agresore i doprinose održavanju uravnoteženog stanja kože. ​ Peptidi Ovi peptidi poznati su po svojim anti-age svojstvima; pomažu u smanjenju vidljivosti finih linija i bora, poboljšavaju elastičnost kože i podržavaju njenu regeneraciju. ​ Kompleks pečuraka Ekstrakti ovih pečuraka pružaju bogatu ishranu koži, štite je od spoljašnjih iritacija i doprinose njenoj revitalizaciji. ​ Ekstrakt kore božura Ovaj ekstrakt ima umirujuća svojstva, pomaže u hidrataciji kože i doprinosi njenom osveženom izgledu. ​ Alantoin i Pantenol Ovi sastojci poznati su po svojim umirujućim i hidratantnim svojstvima; pomažu u smirivanju iritacija i pružaju dodatnu vlagu koži. Dodaj u listu želja Dodaj u listu želja', 'Manyo Factory Bifida Ampoule Mist je hidratantni sprej koji kombinuje bifidu, peptide i gljivične ekstrakte kako bi obnovio kožnu barijeru i smanjio iritacije. Ova ampula u spreju pruža trenutan efekat osveženja, dok istovremeno jača i hrani kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Manyo-Bifida-Ampoule-Mist.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
