INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1486, 22, 'Beauty of Joseon Relief Sun Aqua Fresh Rice + B5', 'beauty-of-joseon-relief-sun-aqua-fresh', 'Ključne prednosti: Dubinska hidratacija: Kombinacija pirinčane vode i pantenola zadržava vlagu, čineći kožu hidriranom i elastičnom tokom dana​. Brzo upijanje: Lagana tekstura se lako nanosi i ne ostavlja tragove, što ga čini pogodnim za sve tonove kože​. Umirivanje kože: Pantenol smiruje iritacije i pomaže u jačanju kožne barijere, što je idealno za osetljivu i dehidriranu kožu. Kome je namenjena? Ova krema za sunčanje pogodna je za sve tipove kože, uključujući masnu, suvu i osetljivu. Namenjena je osobama koje žele laganu, hidratantnu zaštitu od sunca bez masnog filma. Zašto volimo Beauty of Joseon Relief Sun Aqua-Fresh Rice+B5? Relief Sun Aqua-Fresh kombinuje tradicionalne sastojke korejske nege sa modernim filterima za zaštitu od UV zraka. Pirinčana voda, korišćena vekovima u azijskoj nezi kože, obogaćena je antioksidansima koji pomažu u osvežavanju i ujednačavanju tena. Pantenol dodatno hidrira i umiruje kožu. Lagana formula omogućava brzo upijanje, ostavljajući kožu svežom i blistavom. Zahvaljujući inovativnim filterima, krema pruža dugotrajnu zaštitu od UVA i UVB zračenja. Aktivni sastojci Voda semenki pirinča (30%) Voda semenki pirinča bogata je vitaminima, mineralima i antioksidansima koji pomažu u obnavljanju prirodne barijere kože. Tradicionalno se koristi u korejskoj nezi kože zbog svojih hidratantnih i osvetljujućih svojstava. Ovaj sastojak poboljšava teksturu kože, čineći je mekšom i glatkijom. Takođe, poseduje umirujuće i antiinflamatorne benefite, pomažući u smanjenju crvenila i iritacija. Njegova sposobnost da ujednači ten doprinosi svežijem i blistavijem izgledu kože. Redovna upotreba proizvoda sa pirinčanom vodom može poboljšati hidrataciju i elastičnost kože. Pantenol (Vitamin B5) Pantenol je poznat po svojim hidratantnim i umirujućim svojstvima, što ga čini idealnim za osetljivu i suvu kožu. Kada se apsorbuje, pretvara se u provitamin B5, koji pomaže u jačanju kožne barijere i smanjuje gubitak vlage. Takođe, poseduje antiinflamatorna svojstva koja pomažu u smirivanju iritacija izazvanih UV zračenjem i spoljašnjim faktorima. Pomaže u regeneraciji kože, čineći je otpornijom na stres i oštećenja. Ovaj sastojak poboljšava ukupnu hidrataciju kože, ostavljajući je mekom i elastičnom. Redovna upotreba proizvoda sa pantenolom može doprineti zdravijem i blistavijem tenu. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Relief Sun Aqua-Fresh:Rice + B5 je lagana zaštitna krema za sunčanje sa SPF 50+ PA++++ . Formulisana je sa pirinčanom vodom i pantenolom, pružajući snažnu zaštitu od sunca i hidrataciju, bez beličastog traga i masnog osećaja na koži.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Beauty-of-Joseon-Relief-Sun-Aqua-Fresh-Rice-B5.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
