INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1493, 43, 'd’Alba White Truffle First Spray Serum', 'd-alba-white-truffle-first-spray-serum', 'Ključne prednosti: Intenzivna hidratacija: Beli tartuf i hijaluronska kiselina dubinski hidriraju kožu, čineći je punijom i glatkom. Zaštita od oksidacije: Vitamin E pruža antioksidativnu zaštitu, čuvajući kožu od oštećenja uzrokovanih slobodnim radikalima. Posvetljivanje i ujednačavanje tena: Niacinamid poboljšava tonus kože, smanjuje tamne mrlje i posvetljuje kožu. Kome je namenjen? Serum je pogodan za sve tipove kože, uključujući suvu, osetljivu i zrelu kožu. Namenjen je osobama koje žele laganu, ali intenzivnu hidrataciju, ujednačen tonus i zaštitu od oksidativnog stresa. Zašto volimo d’Alba White Truffle First Spray Serum? Ovaj serum obogaćen je ekstraktom belog tartufa, jednim od najređih i najcenjenijih sastojaka u svetu nege kože, poznat po svojim antioksidativnim svojstvima. Sviđa vam se ideja trenutnog osveženja kože? Ovaj sprej-serum pruža brzu hidrataciju i blistavost tokom celog dana. Vitamin E dodatno štiti kožu od starenja, dok niacinamid ujednačava ten, čineći vašu kožu glatkom i elastičnom uz svaki pritisak na bočicu. Aktivni sastojci Niacinamid Poznat po svojoj sposobnosti da posvetli i ujednači ton kože, pomaže u smanjenju pigmentacije i poboljšava izgled kože, čineći je zdravijom i blistavijom. Deluje i kao antioksidans i štiti ćelije od oštećenja izazvanih spoljašnjim faktorima. Avokadovo ulje Pruža dubinsku hidrataciju i ishranu, bogato masnim kiselinama i vitaminima, čineći kožu mekom, podatnom i revitalizovanom. Ekstrakt tartufa (Tuber Magnatum) Prepun antioksidanata, štiti kožu od štetnih uticaja iz okoline, promovišući mladalački i živahan izgled. Natrijum hijaluronat Moćan sastojak za zadržavanje vlage, obezbeđuje dugotrajnu hidrataciju i pun, svež izgled. Dodaj u listu želja Dodaj u listu želja', 'd&#8217;Alba White Truffle First Spray Serum je lagani sprej-serum koji kombinuje ekstrakt belog tartufa iz Pijemonta i vitamin E za intenzivnu hidrataciju i blistav izgled kože. Veganska i hipoalergena formula pruža višestruku negu, uključujući hidrataciju, posvetljivanje i zaštitu od slobodnih radikala.', 'https://beauty-health.rs/wp-content/uploads/2024/10/dAlba-White-Truffle-First-Spray-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
