INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1494, 174, 'VT Cosmetics Cica Daily Soothing Mask', 'vt-cosmetics-cica-daily-soothing-mask', 'Ključne prednosti: Intenzivno umirivanje: CICALIAO&#x2122; i Cicahyalon&#x2122; smiruju iritacije, smanjuju crvenilo i pomažu u oporavku oštećene kože. Dubinska hidratacija: Cicahyalon&#x2122; kompleks održava optimalan nivo vlage, ostavljajući kožu mekom i elastičnom. Svakodnevna upotreba: Zahvaljujući nežnom sastavu i 0,2 mm tankom sloju maske, pogodna je za svakodnevnu primenu bez osećaja težine. Kome je namenjena? Maska je pogodna za sve tipove kože, posebno za osetljivu i suvu kožu koja se suočava sa crvenilom, dehidratacijom i iritacijom. Zašto volimo VT Cosmetics Cica Daily Soothing Mask? Cica Daily Soothing Mask je formulisana kako bi pružila trenutan osećaj umirenja za stresiranu kožu. Sa jedinstvenim CICALIAO&#x2122; kompleksom, maska pomaže u smanjenju crvenila. Kompleks Cicahyalon&#x2122; obezbeđuje dugotrajnu hidrataciju. Materijal maske je ultra-tanak, čime se postiže bolja apsorpcija esencije i omogućava efekat “druge kože”. Redovna upotreba poboljšava teksturu kože, ostavljajući je hidriranom, osveženom i otpornijom na spoljašnje faktore​. Aktivni sastojci Cicaliao&#x2122; Patentirani kompleks na bazi Centella Asiatica koji umiruje kožu, smanjuje crvenilo i pospešuje regeneraciju. Jača kožnu barijeru i štiti od spoljašnjih uticaja. Idealan je za osetljivu, nadraženu ili stresiranu kožu kojoj je potrebna nega i obnova. Cicahyalon&#x2122; Sinergijska kombinacija Centella Asiatica ekstrakta i 3 vrste hijaluronske kiseline koja pruža intenzivnu hidrataciju i umirujuće dejstvo. Hijaluronska kiselina zadržava vlagu u koži, dok centella umiruje i obnavlja oštećene delove. Sodium Hyaluronate Dubinski hidrira kožu, poboljšava elastičnost i daje efekat &#8220;punije&#8221; kože. Brzo se upija i ne ostavlja lepljiv trag, savršen za svakodnevnu hidrataciju. Panthenol (Provitamin B5) Umiruje kožu, pomaže u obnavljanju barijere i pruža dugotrajnu hidrataciju. Posebno koristan za suvu, zategnutu i osetljivu kožu. Dodaj u listu želja Dodaj u listu želja', 'VT Cosmetics Cica Daily Soothing Mask je dnevna maska za lice obogaćena CICALIAO&#x2122; i Cicahyalon&#x2122; kompleksima, formulisana za umirivanje, hidrataciju i obnavljanje osetljive kože. Tanak materijal maske omogućava maksimalnu apsorpciju esencije, pružajući dugotrajan osećaj svežine i smirenja.', 'https://beauty-health.rs/wp-content/uploads/2024/10/VT-Cosmetics-Cica-Daily-Soothing-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
