INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1496, 164, 'Tirtir My Glow Lip Oil', 'tirtir-my-glow-lip-oil', 'Ključne prednosti: Intenzivna hidratacija: Jojoba ulje i vitamin E dubinski hidriraju suve i ispucale usne, čineći ih mekim i punim. Poboljšanje elastičnosti: Ekstrakt Damask ruže i kamelijinog ulja poboljšavaju elastičnost usana, čineći ih glatkijim i otpornijim. Dugotrajna zaštita: Mango buter i neven stvaraju zaštitni sloj na usnama, sprečavajući gubitak vlage i održavajući ih hidriranim tokom celog dana. Kome je namenjeno? Ovo ulje je pogodno za sve tipove usana, naročito za suve i ispucale usne koje zahtevaju intenzivnu hidrataciju i sjaj. Namenjeno je svima koji žele prirodno sjajan izgled bez lepljivog osećaja. Zašto volimo TIRTIR My Glow Lip Oil? My Glow Lip Oil Rosy donosi kombinaciju prirodnih ulja i hranljivih sastojaka za nežnu, a dugotrajnu negu usana. Zahvaljujući jojoba ulju, dubinski hidrira i omekšava. Ekstrakt Damask ruže pruža delikatnu notu ružičastog sjaja. Lagana, nelepljiva tekstura čini ovo ulje idealnim za svakodnevnu upotrebu. Može da se koristi kao samostalni sjaj ili preko omiljenog karmina. Svakim nanošenjem, usne postaju punije, hidrirane i zaštićene od isušivanja, što doprinosi svežijem izgledu usana​. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR My Glow Lip Oil je hidratantno ulje za usne obogaćeno jojoba uljem, vitaminom E i ekstraktom Damask ruže. Ova lagana formula pruža dugotrajnu vlagu i sjaj bez osećaja lepljivosti​.', 'https://beauty-health.rs/wp-content/uploads/2024/10/TIRTIR-My-Glow-Lip-Oil-Rosy.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
