INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1498, 164, 'Tirtir SOS Serum', 'tirtir-sos-serum', 'Ključne prednosti: Dubinska hidratacija: Poliglutaminska kiselina veže vlagu u koži do deset puta efikasnije od hijaluronske kiseline, čime koža postaje dubinski hidrirana i zategnuta. Umirivanje iritacija: Hamamelis i kamilica smanjuju crvenilo i smiruju kožu, poboljšavajući njen tonus i smanjujući pojavu upala. Povećanje elastičnosti: Acetil hekapeptid-8 podstiče proizvodnju kolagena, čineći kožu čvršćom i glađom. Kome je namenjena? Serum je namenjen svim tipovima kože, posebno osetljivoj i suvoj koži sklonoj iritacijama. Pogodan je za osobe koje traže rešenje za dehidrataciju, crvenilo i smanjenje bora​. Zašto volimo TIRTIR SOS Serum? SOS Serum je formulisan kako bi pružio trenutnu hidrataciju i olakšanje za dehidriranu i iritiranu kožu. Poliglutaminska kiselina dubinski hidrira, dok hamamelis i kamilica efikasno umiruju i obnavljaju oštećenu kožu. Serum ima laganu gelastu teksturu koja se brzo upija, ostavljajući kožu mekšom i zategnutijom. Sa svakim nanošenjem, koža postaje vidljivo glatkija i blistavija, dok redovna upotreba poboljšava njen tonus i smanjuje sitne linije. Aktivni sastojci Poliglutaminska kiselina Moćan ovlaživač koji zadržava vlagu u koži čak efikasnije od hijaluronske kiseline. Intenzivno hidrira, zaglađuje fine linije i poboljšava elastičnost. Pomaže u jačanju kožne barijere i čini ten punijim i zdravijim. Ekstrakt centella asiatica Umiruje crvenilo, ubrzava zarastanje i jača prirodnu barijeru kože. Deluje protivupalno i regenerativno, čineći serum pogodnim i za osetljivu, reaktivnu kožu. Ekstrakt veštičje leske (Witch Hazel Extract) Adstrigent koji pomaže u sužavanju pora, smanjenju viška sebuma i ublažavanju iritacija. Idealno za osvežavanje i balansiranje kože sklone nepravilnostima. Ekstrakt kamilice Prirodni antiinflamatorni sastojak koji umiruje kožu, smanjuje osipe i crvenilo. Doprinosi mekoći, smirenom tenu i oporavku nadražene kože. Ekstrakt krastavca (Cucumis Sativus Extract) Osvežava, hidrira i umiruje kožu. Bogat antioksidansima i vitaminima, pomaže u revitalizaciji i osvetljavanju tena. Posebno koristan kod umorne i dehidrirane kože. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Milk Skin Toner je visokokoncentrovani toner koji pruža dugotrajnu hidrataciju i ujednačava ten. Sadrži niacinamid, ekstrakt mekinja pirinča i ceramide koji umiruju i jačaju barijeru kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/TIRTIR-SOS-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
