INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1499, 164, 'Tirtir Milk Skin Toner', 'tirtir-milk-skin-toner', 'Ključne prednosti: Dubinska hidratacija: Zahvaljujući niacinamidu i hijaluronskoj kiselini, ovaj toner zadržava vlagu u koži, pružajući dugotrajan osećaj svežine. Posvetljivanje tena: Ekstrakt mekinja pirinča i niacinamid posvetljuju tamne mrlje i ujednačavaju ten, čineći kožu blistavom i zdravom. Jačanje barijere: Ceramidi i pantenol pomažu u obnavljanju i jačanju barijere kože, štiteći je od isušivanja i spoljašnjih oštećenja. Kome je namenjena? Ovaj toner je namenjen svim tipovima kože, uključujući osetljivu. Pogodan je za osobe koje žele poboljšanje hidratacije, ujednačavanje tena i jačanje barijere​. Zašto volimo TIRTIR Milk Skin Toner? Milk Skin Toner kombinuje blagotvorne sastojke kao što su niacinamid i ekstrakt pirinča za poboljšanje teksture kože i postizanje “staklenog” izgleda kože. Sa svakim nanošenjem, toner dubinski hidrira i smiruje kožu, smanjujući crvenilo i iritacije. Uz dugotrajnu upotrebu, tonus i tekstura kože postaju ujednačeni, dok ceramidi dodatno jačaju kožnu barijeru, zadržavajući vlagu i smanjujući isušivanje​. Koji Milk Skin Toner odabrati? Za suvu i dehidriranu kožu, Milk Skin Toner je pravi izbor. Njegova bogata mlečna tekstura daje koži potrebnu hidrataciju i čini je mekom i elastičnom tokom celog dana! Uz dodatak 2% niacinamida, ovaj tonik je savršen za svakodnevnu negu i obnavljanje barijere kože. Ali, ako je tvoja koža masna i sklona aknama, onda je TIRTIR Milk Skin Toner Light prava stvar! Sa 4% niacinamida i sedam patentiranih veganskih svojstava za umirenje, ovaj tonik balansira vlagu i zateže pore, dok njegova lagana formula brzo osvaja tvoje lice bez osećaja težine. Aktivni sastojci Ekstrakt pirinčanih mekinja (Rice Bran Extract) Prirodni izvor vitamina B i E, antioksidanasa i masnih kiselina koji posvetljuju i omekšavaju kožu. Pomaže u obnavljanju oštećene barijere, pruža blistav izgled i ujednačava ten. Deluje umirujuće i hidrira čak i osetljivu kožu. Niacinamid Vitamin B3 koji posvetljuje tamne mrlje i ujednačava ten. Poboljšava elastičnost, jača barijernu funkciju kože i pomaže u regulaciji sebuma. Efikasan za osvetljavanje i pročišćavanje tena bez iritacije. Ceramidi Jačaju prirodnu zaštitnu barijeru kože i sprečavaju transepidermalni gubitak vode. Obezbeđuju dugotrajnu hidrataciju, smiruju i štite osetljivu kožu od spoljašnjih iritansa. Ekstrakt kamilice (Chamomile Extract) Poznata po svojim antiinflamatornim i umirujućim svojstvima, kamilica pomaže u smanjenju crvenila, iritacija i osipa. Savršena za osetljivu i reaktivnu kožu. Natrium hijaluronat (Sodium Hyaluronate) Oblik hijaluronske kiseline koji prodire dublje u kožu i vezuje vlagu, čineći kožu hidriranom, elastičnom i punijom. Efikasno poboljšava teksturu i osećaj glatkoće. Dodaj u listu želja Dodaj u listu želja', 'TIRTIR Milk Skin Toner je visokokoncentrovani toner koji pruža dugotrajnu hidrataciju i ujednačava ten. Sadrži niacinamid, ekstrakt mekinja pirinča i ceramide koji umiruju i jačaju barijeru kože.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Tirtir-Milk-Skin-Toner-Light-.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
