INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1502, 143, 'Round Lab Soybean Nourishing Toner', 'round-lab-soybean-nourishing-toner', 'Ključne prednosti: Intenzivna hidratacija: Visok sadržaj crnog sojinog ekstrakta i glicerina obezbeđuje dubinsku vlagu i elastičnost kože. Jačanje barijere: Ceramid NP obnavlja kožnu barijeru, zadržava vlagu i sprečava njeno isušivanje, čineći kožu jačom. Umirivanje i smanjenje bora: Adenozin pomaže u smanjenju finih linija, dok Chondrus crispus (crvena alga) umiruje i štiti kožu. Kome je namenjen? Ovaj toner je idealan za suvu, dehidriranu i zrelu kožu, ali je dovoljno blag i za osetljivu kožu. Zašto volimo Round Lab Soybean Nourishing Toner? Soybean Nourishing Toner pruža koži dubinsku negu kroz visok sadržaj ekstrakta crnog sojinog zrna, bogatog proteinima, vitaminima i antioksidansima. Njegova lagana, vodenasta tekstura olakšava višestruko nanošenje bez osećaja lepljivosti. Ceramidi dodatno jačaju zaštitnu barijeru. S vremenom, koža postaje otpornija na spoljašnje iritacije i dehidraciju, čime se smanjuje crvenilo i obnavlja prirodna elastičnost. Aktivni sastojci Adenozin Adenozin je snažan umirujući i anti-age sastojak koji pomaže u regeneraciji osetljive i oslabljene kože. Deluje tako što pospešuje sintezu kolagena i elastina, čime doprinosi smanjenju vidljivosti finih linija i bora. U ovoj formuli, adenozin istovremeno umiruje iritiranu kožu i poboljšava njen tonus, pružajući glatkiji i ujednačeniji izgled. Ceramide NP Ceramide NP je lipid sličan prirodnim komponentama kože koji jača zaštitnu barijeru i sprečava transepidermalni gubitak vode. Njegovo prisustvo u ovoj formuli omogućava koži da duže zadrži vlagu, čime postaje otpornija na suvoću, iritacije i spoljašnje faktore. Chondrus Crispus Extract (Crvena alga) Crvena alga, poznata i kao irska mahovina, bogata je proteinima, vitaminima i antioksidansima koji hrane i štite kožu. U ovom toniku, deluje kao prirodni ovlaživač koji pomaže u očuvanju vlažnosti i jačanju kožne barijere. Saccharum Officinarum (Sugarcane) Extract Ekstrakt šećerne trske je prirodan izvor alfa-hidroksi kiseline (glikolne kiseline), koja deluje blago eksfolijativno i pomaže u smanjenju nepravilnosti na koži. U ovoj formuli, doprinosi uklanjanju mrtvih ćelija, poboljšava teksturu i ujednačava ton kože. Theobroma Cacao (Cocoa) Seed Extract Ekstrakt kakao semena bogat je flavonoidima i masnim kiselinama koji dubinski hidriraju kožu i štite je od oksidativnog starenja. U ovom toniku, kakao deluje kao prirodni antioksidans koji pomaže u borbi protiv slobodnih radikala i poboljšava elastičnost kože. Dodaj u listu želja Dodaj u listu želja', 'Round Lab Soybean Nourishing Toner sadrži ekstrakt crnog sojinog zrna (11,700 ppm) koji pruža intenzivnu hidrataciju, jača barijeru kože i smanjuje pojavu sitnih bora. Obogaćen ceramidima i adenozinom, ovaj toner pomaže u obnavljanju suve i dehidrirane kože​.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Round-Lab-Soybean-Nourishing-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
