INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1503, 138, 'Pyunkang Yul Essence Toner', 'pyunkang-yul-essence-toner', 'Ključne prednosti: Intenzivna hidratacija: Duboko hidrira kožu, smanjujući osećaj zategnutosti i suvoće. Jača kožnu barijeru: Ekstrakt Astragalus membranaceus jača barijeru, smanjuje gubitak vlage i poboljšava elastičnost. Umiruje crvenilo i iritacije: Blaga formula smanjuje crvenilo, upale i iritacije, čineći kožu glatkom i ujednačenom. Kome je namenjen? Ovaj toner je idealan za sve tipove kože, posebno za suvu, dehidriranu i osetljivu kožu koja traži umirenje i dugotrajnu hidrataciju. Zašto volimo Pyunkang Yul Essence Toner? Essence Toner koristi snagu tradicionalnog bilja za intenzivnu, ali laganu hidrataciju. Visok sadržaj ekstrakta Astragalus membranaceus dubinski hidrira kožu i poboljšava njenu elastičnost, bez osećaja težine. Tekstura tonera je pogodna za višestruko nanošenje, bez lepljivog osećaja, što poboljšava apsorpciju narednih proizvoda u rutini. Redovnom upotrebom koža postaje otpornija, smanjuje se crvenilo, a ten postaje ujednačen i blistaviji. Aktivni sastojci Astragalus Membranaceus Root Extract (ekstrakt korena astragalusa) Astragalus je tradicionalna lekovita biljka iz kineske medicine poznata po snažnom umirujućem i antioksidativnom dejstvu. Ekstrakt korena bogat je saponinima, flavonoidima i polisaharidima koji pomažu u jačanju kožne barijere i poboljšanju otpornosti kože na stres i iritacije. U ovoj formuli, astragalus deluje kao glavni hidratantni i revitalizujući sastojak koji umiruje osetljivu kožu i pruža ujednačen, osvežen ten. Arginin Arginin je aminokiselina prirodno prisutna u koži koja pomaže u održavanju hidratacije i ubrzava proces zarastanja i obnove ćelija. Takođe ima antioksidativna svojstva i doprinosi elastičnosti i glatkoći kože. U ovoj formuli, arginin deluje kao podrška regeneraciji kože i pojačava zaštitnu funkciju barijere. Pomaže u ublažavanju iritacija i jačanju otpornosti kože na spoljne uticaje. Hydroxyethyl Cellulose Hydroxyethyl cellulose je biljni zgušnjivač i ovlaživač koji poboljšava teksturu formule i omogućava ravnomerno nanošenje. Deluje kao pomoćni hidratantni agens koji zadržava vlagu na površini kože, čineći je glatkom i prijatnom na dodir. U ovoj formuli pomaže da toner ima blago viskoznu, esencijalnu teksturu koja se lako apsorbuje bez osećaja lepljivosti. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul Essence Toner je hidratantni toner sa 91.3% ekstrakta astragalusa, poznatog po umirujućim i antioksidativnim svojstvima. Ova minimalistička formulacija pruža intenzivnu hidrataciju, jača kožnu barijeru i odgovara svim tipovima kože, uključujući i osetljivu​.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Pyunkang-Yul-Essence-Toner-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
