INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1505, 138, 'Pyunkang Yul 1/3 Cotton Pads 160ea (Pulp Rayon)', 'pyunkang-yul-1-3-cotton-pads', 'Ključne prednosti: Štedi toner: Jastučići koriste samo trećinu uobičajene količine tonera, smanjujući potrošnju proizvoda za čak 66%. Bez rasipanja proizvoda: Zahvaljujući materijalu, minimalno upijaju tečnost, pružajući bolju apsorpciju proizvoda na koži. Višenamenski: Pogodni su za čišćenje, nanošenje tonera i esencija, kao i za DIY maske kada se natapaju omiljenim proizvodom za negu kože. Kome su namenjeni? Ovi jastučići su pogodni za sve tipove kože, uključujući i osetljivu. Preporučuju se korisnicima koji žele smanjiti potrošnju proizvoda i povećati efikasnost upotrebe tonera, esencija i drugih tečnosti za negu kože. Zašto volimo Pyunkang Yul 1/3 Cotton Pads ? Jastučići su tanki, ali dovoljno čvrsti, omogućavajući ravnomerno raspoređivanje proizvoda na koži bez rasipanja. Kada su natopljeni tonikom ili esencijom, savršeno prijanjaju uz kožu, pružajući ravnomernu hidrataciju. Ova specijalna tekstura omogućava bolju penetraciju aktivnih sastojaka, čineći negu efikasnijom. Dodaj u listu želja Dodaj u listu želja', 'Pyunkang Yul 1/3 Cotton Pads – vaša tajna za ekonomičnu negu kože! Zadržavajući minimalnu količinu proizvoda, ovi pamučni jastučići prenose maksimalnu hidrataciju direktno na kožu, pružajući vam pun efekat uz manju potrošnju vaših omiljenih tonera i esencija.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Pyunkang-Yul-1-3-Cotton-Pads.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
