INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1508, 137, 'Purito Wonder Releaf Centella Serum Unscented', 'purito-wonder-releaf-centella-serum-unscented', 'Ključne prednosti: Brzo umiruje kožu: Visoka koncentracija Centella Asiatica smanjuje crvenilo i iritacije. Jača barijeru kože: Peptidi i ceramidi jačaju barijeru i poboljšavaju elastičnost. Dubinska hidratacija: Hijaluronska kiselina i pantenol dubinski hidriraju, ostavljajući kožu svežom i glatkom . Kome je namenjena? Pogodan je za sve tipove kože, posebno za osobe sa osetljivom, suvom ili iritiranom kožom, kao i one koji žele poboljšanje hidratacije i elastičnosti​. Zašto volimo Purito Wonder Releaf Centella Serum Unscented? Wonder Releaf Centella serum pruža intenzivnu negu sa visokom koncentracijom Centella Asiatica, koja ne samo da smanjuje crvenilo već jača barijeru kože. Alantoin dodatno pospešuje regeneraciju, smanjuje iritacije i zadržava vlagu, ostavljajući kožu umirenom i glatkom. Peptidi deluju na dubljem nivou, stimulišući sintezu kolagena i poboljšavajući elastičnost kože. Dugotrajna upotreba ovog seruma rezultira vidljivo zdravijom, otpornijom i hidriranom kožom koja je spremna za svakodnevne izazove. Aktivni sastojci Centella Asiatica Extract Centella Asiatica je biljka poznata po svom intenzivnom umirujućem i regenerativnom dejstvu, naročito kod osetljive, upaljene i iritirane kože. Bogata je aktivnim komponentama kao što su madecassoside, asiaticoside i asiatic acid, koje smanjuju crvenilo, stimulišu zarastanje i jačaju kožnu barijeru. Takođe podstiče sintezu kolagena, čime doprinosi obnavljanju elastičnosti i zdravlja kože. U ovoj serumskoj formuli, Centella deluje kao centralni sastojak za brzo umirenje i balans kože. Alantoin Alantoin je blag, ali efikasan sastojak koji umiruje i regeneriše oštećenu ili iritiranu kožu. Deluje keratolitički – uklanja mrtve ćelije sa površine kože i podstiče glatkiju, ujednačeniju teksturu. Takođe ima protivupalna i hidratantna svojstva koja doprinose udobnosti i balansu kože. U ovoj formuli, alantoin dodatno pojačava efekte Centelle, smanjujući osećaj zatezanja, suvoće i nelagodnosti. Peptidi Peptidi su kratki lanci aminokiselina koji stimulišu proizvodnju kolagena i elastina, ključnih za čvrstu, elastičnu i zdravu kožu. Deluju kao &#8220;signalni molekuli&#8221; koji obnavljaju oštećeno tkivo, smanjuju pojavu finih linija i poboljšavaju ukupni tonus kože. Dodaj u listu želja Dodaj u listu želja', 'Purito Wonder Releaf Centella Serum Unscented pruža intenzivnu hidrataciju i umiruje kožu, zahvaljujući visokokoncentrisanom ekstraktu Centella Asiatica (34,860 ppm). Sastav bez mirisa čini ga idealnim za osetljivu kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Purito-Wonder-Releaf-Centella-Serum-Unscented.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
