INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1509, 137, 'Purito Wonder Releaf Centella BB Cream', 'purito-wonder-releaf-centella-bb-cream', 'Ključne prednosti: Pruža ujednačen ten i pokrivnost: Ova BB krema nudi srednju do punu pokrivnost. Može slojevito nanositi, što je čini pogodnom za prikrivanje nesavršenosti. Umiruje iritacije: Zahvaljujući visokom sadržaju Centella Asiatica ekstrakta, umiruje crvenilo i iritacije. Pogodna i za osetljivu kožu. Štiti od sunca: Sa SPF 50+ i PA++++ zaštitom, BB krema efikasno blokira štetne UV zrake, štiteći kožu od oštećenja. Kome je namenjena? Ova BB krema je idealna za sve tipove kože, posebno za osobe sa osetljivom kožom sklonom crvenilu. Namenjena je svima koji žele ujednačen ten i hidrataciju uz svakodnevnu UV zaštitu​. Zašto volimo Purito Wonder Releaf Centella BB Cream? Purito Wonder Releaf Centella BB krema kombinuje negu i pokrivnost u jednom proizvodu, čineći kožu glatkom i zaštićenom tokom celog dana. Inspirisana tradicionalnom korejskom biljkom Centella Asiatica, ova BB krema ne samo da pokriva nesavršenosti, već i umiruje kožu. Takođe, smanjuje crvenilo i pruža dugotrajnu hidrataciju. Svojim laganim, polumat završetkom, ostavlja kožu svežom i prirodnom. Dugotrajna zaštita od UV zračenja dodatno doprinosi očuvanju mladalačkog izgleda kože. Kako da odaberete nijansu? Molimo vas da detaljno pogledate sve nijanse klikom na link. Dodaj u listu želja Dodaj u listu želja', 'Purito Wonder Releaf Centella BB Cream pruža prirodnu pokrivnost i dugotrajnu hidrataciju uz umirujuća svojstva Centella Asiatica. Ova BB krema ima SPF 50+ i PA++++ zaštitu , čineći je idealnom za svakodnevnu upotrebu i zaštitu kože od UV zračenja.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Purito-Wonder-Releaf-Centella-BB-Cream.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
