INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1511, 124, 'Nine Less B-Boost 1% Kojic Acid Toner', 'nine-less-b-boost-1-kojic-acid-toner', 'Ključne prednosti: Smanjuje hiperpigmentaciju: Kojična kiselina deluje na smanjenje tamnih fleka i sprečava prekomernu proizvodnju melanina, posvetljujući kožu. Jača kožnu barijeru: Niacinamid (2%) pomaže u smanjenju pigmentacije, jačanju barijere kože i poboljšava teksturu kože. Dubinska hidratacija i umirivanje: Hijaluronska kiselina pruža intenzivnu hidrataciju, dok dipotassium glycyrrhizinate smiruje crvenilo i iritacije. Kome je namenjen? Ovaj toner je idealan za sve tipove kože, uključujući osetljivu kožu i kožu sklonu aknama. Preporučuje se za osobe koje žele da smanje tamne mrlje, ujednače ten i poboljšaju hidrataciju. Zašto volimo Nine Less B-Boost 1% Kojic Acid Toner ? B-Boost 1% Kojic Acid Toner kombinuje moć kojične kiseline i niacinamida kako bi osvetlio ten i smanjio tamne fleke. Kojična kiselina inhibira sintezu melanina, što smanjuje hiperpigmentaciju, dok niacinamid pomaže u obnovi kože i smanjuje upale. Dodaci poput hijaluronske kiseline pružaju dubinsku hidrataciju, a biljni ekstrakti umiruju kožu, čineći je mekom i ujednačenom. Redovna upotreba ovog tonera može značajno poboljšati teksturu kože, vraćajući joj sjaj i zdrav izgled​. Aktivni sastojci Kojic acid (1%) Kojic acid deluje kao efikasan inhibitor enzima tirozinaze, što ga čini ključnim u tretiranju tamnih fleka, hiperpigmentacija i neujednačenog tena. U koncentraciji od 1%, pruža blago, ali postojano posvetljujuće dejstvo koje ne izaziva iritacije. Redovnom upotrebom ten postaje svetliji, jasniji i ujednačeniji. Kojic acid je posebno koristan za postupalne mrlje i fleke nastale usled UV izlaganja. Niacinamid (2%) Niacinamid, ili vitamin B3, poznat je po svojoj sposobnosti da posvetli kožu, smanji crvenilo i ojača kožnu barijeru. U koncentraciji od 2%, efikasno doprinosi ujednačenju tena i smanjenju diskoloracija, dok istovremeno poboljšava teksturu kože. Takođe pomaže u regulaciji proizvodnje sebuma, što je korisno za masnu i kombinovanu kožu. Deluje umirujuće i protivupalno, čime se smanjuje iritacija kod osetljivih stanja kože. Adenozin Adenozin je bioaktivni sastojak poznat po svom umirujućem i anti-age dejstvu, koji poboljšava ćelijsku komunikaciju i funkciju kože. Ima sposobnost da zagladi fine linije i poboljša elastičnost kože stimulacijom sinteze kolagena. Takođe ima antiinflamatorna svojstva, što ga čini korisnim za osetljivu i reaktivnu kožu. Dodaj u listu želja Dodaj u listu želja', 'Nine Less B-Boost 1% Kojic Acid Toner je visokoefikasni toner formulisan sa 1% kojične kiseline, dizajniran za smanjenje tamnih fleka i hiperpigmentacije. Pored toga, ovaj toner obnavlja kožnu barijeru, pruža dubinsku hidrataciju i umiruje iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Nine-Less-B-Boost-1-Kojic-Acid-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
