INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1512, 124, 'Nine Less B-Boost 1% Kojic Acid Serum', 'nine-less-b-boost-1-kojic-acid-serum', 'Ključne prednosti: Smanjuje hiperpigmentaciju i tamne fleke: Kojična kiselina i traneksaminska kiselina zajedno deluju na smanjenje proizvodnje melanina i posvetljavanje tamnih mrlja. Jača kožnu barijeru: Niacinamid obnavlja i jača kožu, smanjuje crvenilo i pomaže u hidrataciji. Poboljšava elastičnost: Peptidi u formuli stimulišu proizvodnju kolagena, čineći kožu čvršćom i elastičnijom. Kome je namenjena? Ovaj serum je idealan za sve tipove kože, posebno za osobe sa problemima hiperpigmentacije, melazmom i neujednačenim tenom. Pogodan je i za osetljivu kožu jer ne sadrži alkohol, veštačke mirise i boje. Zašto volimo NINE LESS B-Boost 1% Kojic Acid Serum? Zamislite serum koji se bori protiv tamnih mrlja, dok istovremeno hidrira i jača vašu kožu. B-Boost 1% Kojic Acid Serum kombinuje moćne sastojke poput kojične i traneksaminske kiseline da smanji vidljive znakove hiperpigmentacije. Niacinamid ne samo da posvetljuje ten, već jača kožnu barijeru i smanjuje upale. Uz dodatak peptida, ovaj serum podstiče regeneraciju ćelija, ostavljajući kožu glatkom, čvrstom i blistavom. Aktivni sastojci Kojic acid (1%) Kojic acid je poznat kao efikasan inhibitor tirozinaze – enzima odgovornog za proizvodnju melanina – čime deluje direktno na uzrok hiperpigmentacija. U koncentraciji od 1% blago, ali kontinuirano smanjuje vidljivost tamnih fleka, pega od sunca i postupalnih mrlja. Takođe ujednačava ton kože i posvetljuje ten bez izazivanja iritacija. Ima blaga antioksidativna i antibakterijska svojstva, što dodatno doprinosi čistoći i svežem izgledu kože. Niacinamid Niacinamid (vitamin B3) je multifunkcionalni sastojak koji u ovom serumu podržava delovanje kojic kiseline u borbi protiv hiperpigmentacija. Poboljšava teksturu kože, smanjuje vidljivost pora i pomaže u regulaciji lučenja sebuma. Njegovo antiinflamatorno dejstvo umiruje crvenilo i iritacije, čineći ga pogodnim za osetljivu i problematičnu kožu. Takođe jača barijernu funkciju kože i povećava njenu otpornost na spoljne faktore. Traneksaminska kiselina Traneksaminska kiselina je poznata po svom delovanju na melanin i sposobnosti da smanji hiperpigmentaciju, naročito kod melazme i fleka izazvanih UV zračenjem. Ima blago protivupalno dejstvo koje pomaže u smanjenju crvenila i iritacija, što je čini pogodnom i za osjetljivu kožu. Deluje na hemijskom nivou da spreči aktivaciju melanocita, čime efikasno redukuje nastanak novih mrlja. Njena kombinacija sa niacinamidom i kojic kiselinom pojačava efekat posvetljivanja tena. Peptidi Peptidi su kratki lanci aminokiselina koji podstiču sintezu kolagena i elastina, ključnih proteina za čvrstoću i elastičnost kože. Deluju regenerativno, poboljšavaju tonus kože i smanjuju vidljivost finih linija i bora. U ovoj formuli, peptidi dodatno podržavaju osvetljavajuće i umirujuće sastojke, pružajući anti-age benefite bez iritacije. Takođe poboljšavaju sposobnost kože da zadrži vlagu, čineći je punijom i hidriranijom. Dodaj u listu želja Dodaj u listu želja', 'NINE LESS B-Boost 1% Kojic Acid Serum je visokoefikasni serum formulisan sa 1% kojične kiseline, 10% niacinamida i 2% traneksaminske kiseline. Njegov cilj je smanjenje tamnih fleka, hiperpigmentacije i ujednačavanje tena, dok pruža dubinsku hidrataciju i obnavlja kožnu barijeru.', 'https://beauty-health.rs/wp-content/uploads/2024/10/NINE-LESS-B-Boost-1-Kojic-Acid-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
