INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1515, 111, 'Mary & May Calendula Peptide Ageless Sleeping Mask', 'mary-may-calendula-peptide-ageless-sleeping-mask', 'Ključne prednosti: Dubinska hidratacija: Hijaluronska kiselina i betain intenzivno hidriraju kožu, čineći je mekom i punom. Smanjuje upale: Ekstrakt nevena umiruje iritacije, smanjuje crvenilo i pomaže u obnavljanju oštećene kože​. Anti-age efekat: Peptidi poboljšavaju elastičnost kože, smanjuju bore i podstiču proizvodnju kolagena​. Kome je namenjen? Namenjena je osobama sa suvom, kombinovanom i osetljivom kožom, kao i onima koji traže rešenje za fine linije i gubitak elastičnosti. Zašto volimo Mary & May Calendula Peptide Ageless Sleeping Mask ? Zamislite kako se vaša koža regeneriše dok spavate, obogaćena umirujućim ekstraktima nevena i moćnim peptidima. Ova maska pruža dubinsku hidrataciju tokom noći, dok njeni aktivni sastojci smiruju iritacije i obnavljaju oštećenu kožu. Peptidi podstiču proizvodnju kolagena, smanjujući sitne linije i vraćajući elastičnost koži. Buđenje uz meku, osveženu kožu svaki dan sada je moguće sa ovom bogatom formulom. Aktivni sastojci Ekstrakt nevena (Calendula officinalis) Ekstrakt nevena je poznat po svojim umirujućim i regenerativnim svojstvima, čineći ga idealnim za osetljivu i iritiranu kožu. Bogat flavonoidima i saponinima, ovaj sastojak deluje protivupalno i pomaže u ublažavanju crvenila i manjih iritacija. Takođe podržava regeneraciju ćelija, ubrzavajući oporavak kože i jačajući njenu prirodnu barijeru. Neven sadrži i antioksidanse koji štite kožu od slobodnih radikala i spoljašnjih štetnih faktora. Peptidni kompleks (Peptide 25s) Peptidni kompleks podstiče sintezu kolagena i elastina, ključnih proteina odgovornih za čvrstinu i elastičnost kože. Ovaj napredni kompleks pomaže u smanjenju vidljivosti bora i finih linija, čime doprinosi mladalačkijem izgledu kože. Deluje regenerativno i revitalizujuće, isporučujući esencijalne nutrijente duboko u kožu tokom noćne regeneracije. Peptidi takođe poboljšavaju funkciju kožne barijere, čineći je otpornijom na spoljašnje stresore. Ekstrakt korena šargarepe Ekstrakt korena šargarepe bogat je beta-karotenom, provitaminom A, koji podstiče obnovu kože i poboljšava njenu strukturu. Njegova snažna antioksidativna svojstva pomažu u neutralisanju slobodnih radikala, usporavajući znake starenja. Takođe hidrira i omekšava kožu, ostavljajući je vidno blistavijom i zdravijom. Karotenoidi iz šargarepe ujednačavaju ten i daju koži prirodnu svetlost. Dodaj u listu želja Dodaj u listu želja', 'Mary & May Calendula Peptide Ageless Sleeping Mask je lagana gel maska koja hidrira i obnavlja kožu tokom noći. Ova maska koristi moć ekstrakta nevena i 25 vrsta peptida kako bi koži vratila elastičnost i smanjila znakove starenja.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Mary-May-Calendula-Peptide-Ageless-Sleeping-Mask-4.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
