INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1524, 104, 'Laneige Lip Sleeping Mask EX', 'laneige-lip-sleeping-mask-ex', 'Ključne prednosti: Intenzivna hidratacija: Moisture Wrap™ tehnologija stvara zaštitni sloj koji zaključava vlagu tokom noći, čineći usne nahranjenim do jutra. Eksfolijacija i regeneracija: Berry Mix Complex™, bogat antioksidansima i vitaminom C, pomaže u uklanjanju mrtvih ćelija i obnavljanju glatkih usana. Osvežavajući efekat: Prijatni miris mente i čokolade pruža umirujuće iskustvo i ostavlja osećaj svežine. Kome je namenjena? Ova maska je idealna za sve koji žele efikasno rešenje za ispucale i suve usne. Posebno je korisna tokom zimskih meseci ili za osobe sa usnama koje su često izložene isušivanju. Zašto volimo Laneige Lip Sleeping Mask EX? Laneige Lip Sleeping maska pruža više od obične nege za usne dok spavate. Zahvaljujući kombinaciji Moisture Wrap™ tehnologije i Berry Mix Complex™-a, ova maska hidrira i regeneriše usne tokom noći. Suve i ispucale usne postaju glatke i mekane, dok osvežavajući miris mente i čokolade pruža opuštajuće iskustvo. Njena lagana tekstura brzo se upija, ostavljajući osećaj svežine i mekoće do jutra – savršen početak svakog dana. https://www.youtube.com/watch?v=GjKAuswKluk&ab_channel=LANEIGEUS Aktivni sastojci Berry Fruit Complex™ Ovaj kompleks kombinuje ekstrakte različitih bobičastih plodova bogatih antioksidansima, uključujući jagodu, malinu, brusnicu i borovnicu. Antioksidansi pomažu u zaštiti usana od slobodnih radikala i spoljašnjih agresora, dok prirodni vitamini i hranljive materije iz ovih plodova doprinose zdravlju i vitalnosti usana. Vitamin C (Askorbinska kiselina) Vitamin C je poznat po svojim antioksidativnim svojstvima i ulozi u sintezi kolagena. U ovoj formuli, pomaže u posvetljavanju i ujednačavanju tona usana, dok istovremeno pruža zaštitu od oksidativnog stresa. ​ Kokosovo ulje (Cocos Nucifera Oil) Kokosovo ulje je prirodni emolijens koji dubinski hidrira i omekšava usne. Bogato je masnim kiselinama koje pomažu u obnavljanju i jačanju barijere kože usana, sprečavajući gubitak vlage. ​ Shea buter (Butyrospermum Parkii Butter) Shea buter je poznat po svojim izuzetnim hidratantnim i umirujućim svojstvima. Pruža intenzivnu negu suvim i ispucalim usnama, čineći ih mekšim i glatkijim. ​ LANEIGE Murumuru buter (Astrocaryum Murumuru Seed Butter) Murumuru buter je bogat masnim kiselinama koje pomažu u hidrataciji i obnavljanju usana. Ima laganu teksturu koja se lako upija, pružajući dugotrajnu hidrataciju bez osećaja težine. Dodaj u listu želja Dodaj u listu želja', 'Laneige Lip Sleeping Mask EX je intenzivna noćna maska koja omekšava, hidrira i neguje usne tokom noći. Ova maska sadrži inovativne komplekse, poput Moisture Wrap™ i Berry Mix Complex™, koji zadržavaju vlagu i pomažu u uklanjanju mrtvih ćelija.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Laneige-Lip-Sleeping-Mask-EX-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
