INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1527, 105, 'Lindsay Calming Herb Modeling Mask', 'lindsay-calming-herb-modeling-mask', 'Ključne prednosti: Umiruje i osvežava: Zeleni čaj i pelin smiruju iritacije i osvežavaju kožu, pružajući osećaj olakšanja. Hidratacija i zaštita: Betain pomaže u očuvanju hidratacije stvaranjem zaštitnog sloja na koži. Jednostavna upotreba: Maska se lako nanosi i uklanja, ostavljajući kožu glatkom i negovanom. Kome je namenjena? Ova maska je idealna za osobe sa osetljivom ili iritiranom kožom, kao i za one koje se bore sa dehidratacijom ili crvenilom. Zašto volimo LINDSAY Calming Herb Modeling Mask ? Ova maska je više od običnog tretmana – pruža trenutni osećaj relaksacije i svežine baš kao da ste izašl,i iz spa centra. Divlji pelin, poznat po svom umirujućem dejstvu, i bogat zeleni čaj zajednički smiruju kožu. Takođe, pomažu u oporavku od svakodnevnog stresa. Dok betain zaključava vlagu, maska revitalizuje lice, pružajući mekoću i prirodan sjaj. Idealan izbor za trenutke kada je koži potrebna dodatna pažnja i negovan izgled. Aktivni sastojci Ekstrakt pelina (Artemisia Capillaris Extract) Pelin je poznat po svojim umirujućim i protivupalnim svojstvima. Pomaže u smanjenju crvenila i iritacija, čineći ga idealnim za osetljivu i problematičnu kožu. ​ Ekstrakt zelenog čaja (Camellia Sinensis Leaf Extract) Bogata antioksidansima, ova komponenta štiti kožu od slobodnih radik Dodaj u listu želja Dodaj u listu želja', 'LINDSAY Calming Herb Modeling Mask Cup Pack kombinuje zeleni čaj i divlji pelin kako bi umirila iritiranu kožu i smanjila crvenilo. Zahvaljujući betainu, maska stvara zaštitni sloj koji zadržava vlagu i ostavlja kožu hidriranom i glatkom.', 'https://beauty-health.rs/wp-content/uploads/2024/10/LINDSAY-Calming-Herb-Modeling-Mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
