INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1528, 105, 'Lindsay Pack Tool Set', 'lindsay-pack-tool-set', 'Lindsay Pack Tool Set (Mixing Bowl/Measuring Spoon/Spatula) je savršen dodatak za ljubitelje DIY kozmetike. Set sadrži: Laganu posudu : Idealna za mešanje maski, laka za čišćenje. Mericu : Precizno doziranje sastojaka za savršenu teksturu maske. Fleksibilnu spatulu : Omogućava ravnomerno nanošenje maski na lice. Ovaj set čini proces pripreme maski jednostavnim i zabavnim, poboljšavajući vašu rutinu nege lica uz lako mešanje i precizno nanošenje. Dodaj u listu želja Dodaj u listu želja', 'Lindsay Pack Tool Set (Mixing Bowl/Measuring Spoon/Spatula) je praktičan set alata dizajniran za lako mešanje i pripremu maski za lice kod kuće.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Lindsay-Pack-Tool-Set.png', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
