INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1529, 104, 'Laneige Cream Skin Mist Pump', 'laneige-cream-skin-mist-pump', 'Laneige Cream Skin Mist Pump služi kao savršen dodatak za preoblikovanje vašeg omiljenog tonika u praktičan sprej. Ova pumpica ravnomerno raspršuje formulu tonika na kožu, pružajući instant hidrataciju i osvežavanje tokom dana. Idealan je za one trenutke kada vaša koža traži dodatnu vlagu ili kada želite osvežiti šminku, sve bez osećaja težine ili masnoće. Kompatibilan je sa 170 ml Cream Skin bočicom i idealan za osetljivu kožu, jer ne sadrži parabene, sulfate ni ftalate. Dodaj u listu želja Dodaj u listu želja', 'Laneige Cream Skin Mist Pump je praktičan dodatak koji pretvara tonik u finu maglicu za trenutnu hidrataciju kože. Pogodan je za osvežavanje tokom dana i održavanje svežine kože bez osećaja težine ili masnoće.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Laneige-Cream-Skin-Mist-Pump.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
