INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1534, 22, 'Beauty of Joseon Ginseng Essence Water', 'beauty-of-joseon-ginseng-essence-water', 'Ključne prednosti: Duboka hidratacija: Voda korena ginsenga pomaže u zadržavanju vlage u koži i poboljšava njen tonus. Balans vlage i sebuma: Zahvaljujući niacinamidu, esencija reguliše proizvodnju sebuma i poboljšava balans ulja i vlage. Jačanje barijere kože: Esencija pomaže u obnavljanju zaštitne barijere kože, čineći je otpornijom na spoljne agresore. Kome je namenjena? Ova esencija je idealna za sve tipove kože, posebno za osobe sa suvom, dehidriranom ili kombinovanom kožom koja ima problema sa balansiranjem ulja i vlage. Takođe je pogodna za one koji žele prirodno rešenje za duboku hidrataciju i osvežavanje kože. Zašto volimo Beauty of Joseon Ginseng Essence Water ? Esencija sadrži žen-šen, biljni sastojak koji je vekovima bio cenjen u korejskoj tradiciji kao &#8220;biljka bogova&#8221;. Njegova bogata istorija i sposobnost da podstakne zdravlje kože čine ovaj proizvod ne samo efikasnim, već i posebnim. Zahvaljujući visokom sadržaju saponina, žen-šen brzo hidrira kožu, pomažući joj da ostane osvežena i zdrava tokom celog dana. Aktivni sastojci Panax Ginseng Root Water Panax Ginseng Root Water, poznata i kao voda korena crvenog ginsenga, čini 80% ove esencije. Ginseng je bogat antioksidansima koji pomažu u zaštiti kože od slobodnih radikala i oštećenja izazvanih UV zračenjem. Takođe, poboljšava cirkulaciju krvi u koži, što doprinosi njenom zdravijem i blistavijem izgledu. Ginseng je poznat po svojim antiinflamatornim svojstvima, što može pomoći u smirivanju iritacija i crvenila. Pomaže u održavanju elastičnosti kože, smanjujući pojavu finih linija i bora. Redovna upotreba proizvoda sa ginsengom može doprineti ujednačenijem tonu kože i smanjenju hiperpigmentacija. ​ Niacinamid (2%) Niacinamid, poznat i kao vitamin B3, je multifunkcionalni sastojak koji pruža brojne koristi za kožu. Pomaže u poboljšanju funkcije kožne barijere, povećavajući njenu otpornost na spoljašnje iritante i smanjujući transepidermalni gubitak vode. Takođe, smanjuje hiperpigmentacije i ujednačava ten, što rezultira svetlijom i blistavijom kožom. Ima antiinflamatorna svojstva koja mogu smanjiti crvenilo i iritacije, što je korisno za osobe sa osetljivom ili aknama sklonom kožom. Pomaže u regulaciji proizvodnje sebuma, što može smanjiti masnoću kože i pojavu akni. Njegova sposobnost da stimuliše sintezu kolagena doprinosi poboljšanju elastičnosti kože i smanjenju pojave finih linija i bora. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Ginseng Essence Water je hranljiva esencija formulisana sa 80% vode korena žen-šena i žen-šen kompleksom. Ova esencija dubinski hidrira kožu, pomaže u održavanju njene elastičnosti, i balansira vlagu i ulje na koži.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Beauty-of-Joseon-Ginseng-Essence-Water-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
