INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1535, 22, 'Beauty of Joseon Red Bean Water Gel', 'beauty-of-joseon-red-bean-water-gel', 'Ključne prednosti: Kontrola viška sebuma: Ekstrakt crvenog pasulja apsorbuje sebum i doprinosi matiranju kože, ostavljajući je svežom i čistom. Poboljšanje elastičnosti: Peptidni kompleks pomaže u jačanju kože, pružajući joj glatku teksturu i čvrstoću. Dubinska hidratacija: Gel formula pruža intenzivnu, ali laganu hidrataciju, idealnu za balansiranje masne i kombinovane kože. Kome je namenjen? Ovaj gel je idealan za masnu i kombinovanu kožu, posebno onu sklonu višku sebuma i proširenim porama. Njegova lagana tekstura ne opterećuje kožu, a blagotvorni sastojci pomažu u balansiranju sebuma i hidrataciji. Zašto volimo Beauty of Joseon Red Bean Water Gel? Ovaj gel osvaja svojim dvostrukim dejstvom – pruža koži prijatnu, laganu hidrataciju, dok istovremeno kontroliše višak sebuma. Zahvaljujući ekstraktu crvenog pasulja, Red Bean Water Gel održava kožu čistom i svežom tokom celog dana, bez masnog sjaja. Takođe, u srcu ove formule je tradicija, jer su žene u Joseon dinastiji koristile crveni pasulj za negu kože. Aktivni sastojci Ekstrakt crvenog pasulja Haenam (44%) Ekstrakt crvenog pasulja Haenam poznat je po svojoj sposobnosti da upija višak sebuma i održi kožu uravnoteženom. Saponini prisutni u ljusci crvenog pasulja pomažu u poboljšanju elastičnosti kože i jačanju njene barijere. Ovaj sastojak takođe pomaže u uklanjanju toksina iz kože, čime doprinosi čistijem i zdravijem tenu. Njegova antioksidativna svojstva štite kožu od oksidativnog stresa i slobodnih radikala, smanjujući rizik od prevremenog starenja. Tradicionalno se koristio u kombinaciji sa mung pasuljem za čišćenje lica, čime je doprinosio osveženju i poboljšanju teksture kože. Redovna upotreba proizvoda sa ekstraktom crvenog pasulja može pomoći u kontroli sebuma i očuvanju zdrave i hidrirane kože. Peptidni kompleks Peptidni kompleks u ovoj formuli sadrži tri vrste peptida: SH-Oligopeptide-1, SH-Oligopeptide-2 i SH-Polypeptide-1, koji zajedno doprinose očuvanju zdravlja kože. Ovi peptidi podržavaju proizvodnju esencijalnih faktora rasta u koži, koji se prirodno smanjuju starenjem. Njihova uloga je u poboljšanju elastičnosti kože, smanjenju finih linija i podsticanju regeneracije ćelija. Takođe, peptidi jačaju kožnu barijeru i povećavaju otpornost kože na spoljašnje agresore. Imaju sposobnost da poboljšaju hidrataciju i zategnu kožu, dajući joj mladalački izgled. Redovna upotreba peptida može doprineti svežijem, punijem i čvršćem tenu. Ovaj lagani gel za hidrataciju idealan je za masnu i kombinovanu kožu, jer kontroliše višak sebuma dok istovremeno pruža potrebnu hidrataciju. Savršen je za upotrebu nakon Beauty of Joseon Red Bean Refreshing Pore Mask , jer pomaže u regeneraciji i balansiranju kože. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Red Bean Water Gel je lagana hidratantna gel krema, posebno formulisana za kontrolu viška sebuma i hidrataciju kože. Kombinacija tradicionalnih sastojaka kao što su ekstrakt crvenog pasulja i peptidni kompleks pomaže u postizanju balansirane, čiste i elastične kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Beauty-of-Joseon-Red-Bean-Water-Gel-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
