INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1536, 22, 'Beauty of Joseon Dynasty Cream', 'beauty-of-joseon-dynasty-cream', 'Ključne prednosti: Dubinska hidratacija : Krema pruža intenzivnu hidrataciju zahvaljujući bogatom kompleksu pirinča i niacinamida, što je čini idealnom za suvu i dehidriranu kožu. Ujednačavanje tena : Niacinamid pomaže u smanjenju tamnih mrlja, crvenila i hiperpigmentacija, čineći kožu ujednačenijom i sjajnijom. Poboljšanje elastičnosti i tonusa : Ekstrakt žen-šena revitalizuje kožu, poboljšava cirkulaciju i povećava elastičnost, smanjujući vidljive znakove starenja. Kome je namenjena? Ova krema je namenjena svim tipovima kože. Posebno je pogodna za osobe sa suvom, dehidriranom ili umornom kožom koja je izgubila elastičnost. Takođe je idealna za one koji se bore sa tamnim flekama, hiperpigmentacijom ili neujednačenim tenom, kao i za osobe koje žele da poboljšaju elastičnost i vitalnost svoje kože. Zašto volimo Beauty of Joseon Dynasty Cream? Ova krema pruža osećaj kraljevske nege zahvaljujući svojoj laganoj, ali hranljivoj teksturi. Njeni efekti na kožu su vidljivi gotovo odmah – koža postaje mekša, sjajnija i vidljivo hidratizovana. Krema ne samo da poboljšava teksturu kože, već pruža dugotrajan efekat hidratacije i regeneracije. Smanjuje vidljive znakove umora i suvoće, a njeni prirodni sastojci pružaju osećaj svežine tokom celog dana. Aktivni sastojci Voda od pirinčanih mekinja (29%) Voda od pirinčanih mekinja, poznata i kao &#8216;Beauty Water&#8217; u dinastiji Joseon, bogata je aminokiselinama, mineralima i vitaminom E. Ovi sastojci pomažu u održavanju vlažnosti i zdravlja kože, pružajući joj blistav i ujednačen ten. Redovna upotreba može poboljšati elastičnost kože i smanjiti pojavu finih linija. Takođe, deluje umirujuće na iritiranu kožu i pomaže u jačanju njene barijere. Njena lagana tekstura omogućava brzo upijanje bez osećaja lepljivosti. Pogodna je za sve tipove kože, uključujući i osetljivu. ​ Voda korena ginsenga (5%) Ginseng, poznat kao &#8216;Shincho&#8217; ili &#8216;biljka bogova&#8217; u korejskoj istoriji, sadrži bogate saponine koji pomažu u revitalizaciji i energizaciji kože. Ovaj sastojak poboljšava cirkulaciju krvi, što doprinosi zdravijem i blistavijem izgledu kože. Takođe, pomaže u smanjenju znakova starenja, poput bora i opuštenosti kože. Ima antiinflamatorna svojstva koja umiruju iritacije i crvenilo. Pruža dubinsku hidrataciju, ostavljajući kožu mekom i elastičnom. Njegova antioksidativna svojstva štite kožu od štetnih spoljašnjih faktora. ​ Skvalan (2%) Skvalan je sastojak sličan sebumu koji pomaže u balansiranju ulja i vlage u koži. Deluje kao barijera koja štiti kožu od spoljašnjih uticaja i sprečava gubitak vlage. Njegova lagana tekstura omogućava brzo upijanje bez začepljenja pora. Pruža dugotrajnu hidrataciju i poboljšava elastičnost kože. Takođe, ima antioksidativna svojstva koja štite kožu od slobodnih radikala. Pogodan je za sve tipove kože, uključujući i masnu i osetljivu. ​ Niacinamid (2%) Niacinamid, ili vitamin B3, pomaže u regulaciji proizvodnje sebuma i poboljšava funkciju barijere kože. Smanjuje pojavu finih linija i bora, ujednačava ten i posvetljuje tamne mrlje. Ima antiinflamatorna svojstva koja umiruju crvenilo i iritacije. Poboljšava elastičnost kože i smanjuje vidljivost pora. Takođe, povećava sintezu ceramida, što jača barijeru kože i sprečava gubitak vlage. Pogodan je za sve tipove kože, uključujući i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Dynasty Cream je krema koja dubinski hidrira i hrani kožu, poboljšavajući njen tonus i elastičnost. Formulisana sa ekstraktom pirinča, niacinamidom i žen-šenom, krema pomaže u obnavljanju kože, smanjuje vidljivost tamnih fleka i hiperpigmentacija, i vraća koži prirodni sjaj.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Beauty-of-Joseon-Dynasty-Cream-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
