INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1538, 22, 'Beauty of Joseon Radiance Cleansing Balm', 'beauty-of-joseon-radiance-cleansing-balm', 'Ključne prednosti: Efikasno uklanjanje šminke : Ovaj balzam lako uklanja čak i vodootpornu šminku, bez potrebe za jakim trljanjem. Dubinsko čišćenje : Formula se transformiše iz balzama u ulje, a zatim u mlečnu emulziju, omogućavajući temeljno čišćenje bez iritacija. Hidratacija i nega : Zahvaljujući bogatom kompleksu biljnih ekstrakata, balzam hidrira i omekšava kožu, čineći je glatkom i sjajnom. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože, uključujući i osetljivu kožu. Posebno je koristan za one koji žele nežno, ali temeljno čišćenje koje neće isušiti kožu. Zašto volimo Beauty of Joseon Radiance Cleansing Balm? Beauty of Joseon Radiance Cleansing balsam pruža temeljno čišćenje kože, uz dodatnu negu zahvaljujući drevnim korejskim sastojcima poput pirinča i žitarica. Ovaj balzam, inspirisan tradicionalnom korejskom negom kože, kombinuje prirodne sastojke koji obnavljaju balans i hidrataciju kože. Uz svaki tretman dobijate osećaj luksuznog rituala čišćenja, spajajući tradiciju sa savremenim rezultatima za zdravu i blistavu kožu. Aktivni sastojci Ekstrakt pirinča i kompleks žitarica Ekstrakt pirinča bogat je aminokiselinama, mineralima i vitaminima koji pomažu u hidrataciji i jačanju kožne barijere. Tradicionalno se koristio u dinastiji Joseon kao Beauty Water, služeći za postizanje glatke i blistave kože. Ovaj sastojak pomaže u nežnom uklanjanju nečistoća i šminke, istovremeno pružajući hidrataciju i osveženje. Kompleks žitarica dodatno poboljšava elastičnost kože i pruža esencijalne hranljive materije. Njegova antioksidativna svojstva pomažu u zaštiti kože od slobodnih radikala i spoljašnjih agresora. Redovna upotreba proizvoda sa ovim sastojkom može doprineti glatkijoj, hidriranoj i zdravijoj koži. Ovaj balzam za čišćenje efikasno uklanja šminku, SPF i nečistoće, dok istovremeno hidrira i umiruje kožu, čineći ga pogodnim za sve tipove kože, uključujući suvu i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'Beauty of Joseon Radiance Cleansing Balm je balzam za čišćenje lica koji efikasno uklanja šminku, nečistoće i višak sebuma, dok istovremeno neguje i hidrira kožu. Njegova blaga, ali efikasna formula se u kontaktu sa kožom transformiše iz balzama u ulje, a zatim u mlečnu emulziju koja temeljno čisti pore.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Beauty-of-Joseon-Radiance-Cleansing-Balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
