INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1540, 84, 'Isntree Onion Fresh Light Sun Stick', 'isntree-onion-fresh-light-sun-stick', 'Ključne prednosti: Visoka UV zaštita : SPF 50+ PA++++ pruža snažnu zaštitu od sunčevih zraka, sprečavajući oštećenja kože uzrokovana UV zračenjem. Kontrola sebuma : Formula pomaže u smanjenju viška masnoće na licu, ostavljajući kožu svežom i matiranom tokom celog dana. Poboljšanje teksture kože : Redovna upotreba ovog proizvoda pomaže u poboljšanju teksture kože, čineći je glatkom i mekom. Kome je namenjen? Ovaj stik je savršen izbor za osobe sa masnom i kombinovanom kožom, sklonim hiperpigmentacijama. Zašto volimo Isntree Onion Fresh Light Sun Stick? Isntree Onion Fresh Light Sun stik efikasno rešava izazove masne i kombinovane kože, pružajući zaštitu od sunca bez težine i osećaja masnoće. Njegova inovativna formula koja se lako nanosi čini ga savršenim za ponovno nanošenje tokom dana. Ovaj sun stick ne samo da pruža UV zaštitu, već i smanjuje proizvodnju sebuma, što rezultira dugotrajnim mat efektom, idealnim za letnje dane i boravak napolju. Aktivni sastojci Ekstrakt crvenog luka (Allium Cepa Bulb Extract) Ekstrakt crvenog luka bogat je jedinjenjima poput kvercetina koja pružaju antioksidativna i antiinflamatorna svojstva. Ovi sastojci pomažu u smanjenju upala i crvenila, čineći kožu smirenijom i ujednačenijom. Takođe, ekstrakt crvenog luka može doprineti posvetljivanju hiperpigmentacija i ujednačavanju tena. Njegova antimikrobna svojstva pomažu u održavanju čistoće kože, što je korisno za osobe sklone aknama. Niacinamid (Vitamin B3) Niacinamid je multifunkcionalni vitamin rastvorljiv u vodi poznat po svojoj sposobnosti da poboljša barijernu funkciju kože i ujednači njen ton. Deluje tako što smanjuje proizvodnju melanina, što doprinosi posvetljivanju tamnih fleka i hiperpigmentacija. Takođe, pomaže u regulaciji proizvodnje sebuma, što može smanjiti pojavu akni i proširenih pora. Niacinamid ima antiinflamatorna svojstva koja umiruju crvenilo i iritacije, čineći ga pogodnim za osetljivu kožu. Pored toga, doprinosi smanjenju finih linija i bora, poboljšavajući elastičnost i teksturu kože. Acetil glukozamin Acetil glukozamin je aminomonosaharid koji prirodno postoji u telu i igra ključnu ulogu u održavanju zdrave kože. Deluje tako što inhibira sintezu melanina, što pomaže u smanjenju hiperpigmentacija i ujednačavanju tena. Takođe, stimuliše proizvodnju hijaluronske kiseline, poboljšavajući hidrataciju i elastičnost kože. Kombinacija acetil glukozamina sa niacinamidom pruža sinergijski efekat u posvetljavanju kože i smanjenju znakova starenja. Ima blaga eksfolijativna svojstva koja pomažu u uklanjanju mrtvih ćelija kože, otkrivajući svežiji i sjajniji ten. Dodaj u listu želja Dodaj u listu želja', 'Isntree Onion Fresh Light Sun Stick je idealan za svakodnevnu zaštitu kože od štetnih UV zračenja, sa SPF 50+ PA++++ formulom koja štiti od UVA i UVB zraka. Lagan i nemastan, ovaj sun stick pruža mat završni sloj koji kontroliše proizvodnju sebuma, čineći ga savršenim izborom za one sa masnom ili kombinovanom kožom.', 'https://beauty-health.rs/wp-content/uploads/2024/10/isntreee-onion-fresh-light-sun-stick.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
