INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1544, 84, 'Isntree Onion Newpair Clear Pad', 'isntree-onion-newpair-clear-pad', 'Ključne prednosti: Smanjenje tamnih fleka i hiperpigmentacije : Pomaže u ujednačavanju tena i smanjenju vidljivosti tamnih mrlja. Poboljšanje teksture kože : Jastučići nežno uklanjaju mrtve ćelije kože i smanjuju pore. Obnavljanje kožne barijere : Hidrira i umiruje kožu, pomažući njenom oporavku nakon iritacija. Kome je namenjen? Ovi jastučići su savršeni za osobe koje se bore sa hiperpigmentacijom, tamnim mrljama, proširenim porama i osetljivom kožom sklonom iritacijama. Takođe su idealne za one koji žele nežnu, a efikasnu eksfolijaciju bez iritacije. Zašto volimo Isntree Onion Newpair Clear Pad? Isntree Onion jastučići pružaju koži nežnu, ali izuzetno efikasnu negu. Njihova sposobnost da posvetle i regenerišu kožu čini ih savršenim saveznikom u borbi protiv hiperpigmentacije i tamnih fleka. Oni ne samo da ujednačavaju ten, već i otkrivaju svežinu i prirodni sjaj vaše kože, čineći je zdravijom i blistavijom nakon svake upotrebe. Njihova blaga formula, bogata umirujućim i regenerativnim sastojcima, čini ih idealnim za svakodnevnu upotrebu. Aktivni sastojci Ekstrakt crvenog luka (Allium Cepa Bulb Extract) Ekstrakt crvenog luka bogat je antioksidansima i sumpornim jedinjenjima koja pomažu u zaštiti kože od oksidativnog stresa i smanjenju upala. Njegova antimikrobna svojstva doprinose borbi protiv bakterija koje uzrokuju akne, dok istovremeno posvetljuje hiperpigmentacije i ujednačava ten. Natrijum heparin Natrijum heparin je poznat po svojim antiinflamatornim svojstvima koja pomažu u smanjenju otoka i crvenila na koži. Deluje kao antikoagulans, poboljšavajući mikrocirkulaciju i ubrzavajući proces zarastanja rana. Takođe, ima sposobnost vezivanja vode, doprinoseći hidrataciji i elastičnosti kože. Njegova upotreba može smanjiti formiranje ožiljaka i poboljšati izgled postojećih. Beta-glukan Beta-glukan je polisaharid poznat po svojim umirujućim i hidratantnim svojstvima. Pomaže u jačanju kožne barijere, štiteći je od štetnih spoljašnjih faktora. Deluje antiinflamatorno, smanjujući crvenilo i iritacije, što ga čini pogodnim za osetljivu kožu. Takođe, podstiče regeneraciju ćelija, ubrzavajući proces zarastanja rana i ožiljaka. Beta-glukan ima antioksidativna svojstva koja štite kožu od prevremenog starenja. Derivati vitamina C (natrijum askorbil fosfat) Natrijum askorbil fosfat je stabilan derivat vitamina C poznat po svojim antioksidativnim svojstvima koja štite kožu od oštećenja izazvanih slobodnim radikalima. Pomaže u sintezi kolagena, poboljšavajući čvrstinu i elastičnost kože. Takođe, efikasan je u posvetljavanju hiperpigmentacija i ujednačavanju tena. Deluje antiinflamatorno, smanjujući crvenilo i iritacije na koži. Natrijum askorbil fosfat pomaže u zaštiti kože od štetnih efekata UV zračenja. Dodaj u listu želja Dodaj u listu želja', 'Isntree Onion Newpair Clear Pad je specijalizovan tretman za kožu u vidu pamučnih jastučića obogaćenih ekstraktom crnog luka. Ove blazinice su dizajnirane da efikasno posvetle kožu, smanje tamne fleke uz istovremeno smirivanje upala i nežno uklanjanje mrtvih ćelija kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Isntree-Onion-Newpair-Clear-Pad.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
