INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1545, 84, 'Isntree Onion Newpair Essence Toner', 'isntree-onion-newpair-essence-toner', 'Ključne prednosti: Umirivanje kože: Ovaj toner pomaže smirivanju iritacija i crvenila, što ga čini idealnim za kožu sklonu aknama. Regeneracija i obnova: Ekstrakt crnog luka pomaže u bržoj obnovi oštećene kože. Dubinska hidratacija: Formula obogaćena hidratantnim sastojcima osigurava optimalan nivo vlažnosti u koži. Kome je namenjen? Preporučuje se osobama sa problematičnom, suvom ili osetljivom kožom sklonom aknama. Takođe je pogodan za one koji žele da osveže i revitalizuju umornu kožu. Zašto volimo Isntree Onion Newpair Essence Toner? Zahvaljujući moćnoj kombinaciji ekstrakta crnog luka i B5 vitamina, ovaj toner pomaže u smanjenju upala i vraća koži njen prirodni sjaj. Njegova formula ne samo da osvežava kožu već pomaže i u održavanju zdrave barijere kože, što je od ključne važnosti za održavanje vlažnosti i zaštite od spoljašnjih agresora. Aktivni sastojci Ekstrakt crvenog luka (Allium Cepa Bulb Extract) Ekstrakt crvenog luka bogat je antioksidansima i sumpornim jedinjenjima koja pomažu u zaštiti kože od oksidativnog stresa i smanjenju upala. Njegova antimikrobna svojstva doprinose borbi protiv bakterija koje uzrokuju akne, dok istovremeno posvetljuje hiperpigmentacije i ujednačava ten. Takođe, stimuliše sintezu kolagena, poboljšavajući elastičnost i čvrstinu kože. Niacinamid (Vitamin B3) Niacinamid je multifunkcionalni sastojak poznat po svojim antiinflamatornim svojstvima koja pomažu u smanjenju crvenila i iritacija na koži. Efikasan je u regulaciji proizvodnje sebuma, što može smanjiti pojavu akni i proširenih pora. Takođe, pospešuje sintezu ceramida, jačajući kožnu barijeru i poboljšavajući hidrataciju. Njegova sposobnost da inhibira transfer melanina pomaže u posvetljavanju hiperpigmentacija i ujednačavanju tena. Traneksaminska kiselina Traneksaminska kiselina je poznata po svojoj sposobnosti da inhibira sintezu melanina, pomažući u posvetljavanju hiperpigmentacija i ujednačavanju tena. Deluje antiinflamatorno, smanjujući crvenilo i iritacije na koži. Takođe, jača kožnu barijeru, poboljšavajući njenu otpornost na spoljne agresore. Ova kiselina može pomoći u smanjenju pojave tamnih fleka nastalih usled izlaganja suncu ili hormonalnih promena. Derivati vitamina C (natrijum askorbil fosfat) Natrijum askorbil fosfat je stabilan derivat vitamina C poznat po svojim antioksidativnim svojstvima koja štite kožu od oštećenja izazvanih slobodnim radikalima. Pomaže u sintezi kolagena, poboljšavajući čvrstinu i elastičnost kože. Takođe, efikasan je u posvetljavanju hiperpigmentacija i ujednačavanju tena. Deluje antiinflamatorno, smanjujući crvenilo i iritacije na koži. Dodaj u listu želja Dodaj u listu želja', 'Isntree Onion Newpair Essence Toner je hidratantni i umirujući toner obogaćen ekstraktom crnog luka, specijalno formulisan za negu kože sklone aknama i osetljive kože. Njegova lagana, vodena tekstura lako se apsorbuje, pružajući intenzivnu hidrataciju i pomažući u regeneraciji kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Isntree-Onion-Newpair-Essence-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
