INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1547, 84, 'Isntree Onion Newpair B5 Ampoule', 'isntree-onion-newpair-b5-ampoule', 'Ključne prednosti: Smanjenje hiperpigmentacije: Efikasno pomaže u smanjenju postupalnih tamnih fleka zahvaljujući visokoj koncentraciji ekstrakta crnog luka. Umirivanje osetljive kože: B5 vitamin i umirujući sastojci obnavljaju kožu i pomažu u oporavku oštećene kožne barijere. Lagana hidratacija: Blaga formula obezbeđuje dubinsku hidrataciju bez iritacije, savršena za suvu i osetljivu kožu. Kome je namenjen? Idealno za osobe koje se bore sa tamnim flekama i osetljivom kožom sklonom iritacijama. Preporučuje se onima koji traže proizvod koji će pomoći u oporavku kože, uz laganu teksturu koja ne opterećuje. Zašto volimo ISNTREE Onion Newpair B5 Ampoule? Ovaj serum obogaćen je ekstraktom crnog luka, poznatim po svojim regenerativnim svojstvima. Deluje na ciljane probleme poput hiperpigmentacije, dok istovremeno pruža umirujuću hidrataciju. Njegova lagana tekstura omogućava brzo upijanje, ne ostavljajući lepljiv osećaj na koži. Rezultati postaju vidljivi već nakon nekoliko nedelja korišćenja, sa svetlijom i ujednačenijom kožom. Aktivni sastojci Ekstrakt crvenog luka (Allium Cepa Bulb Extract) Ekstrakt crvenog luka prisutan u koncentraciji od 85% bogat je flavonoidima, naročito kvercetinom, koji deluju antiinflamatorno i antioksidativno. Ovaj sastojak pomaže u smanjenju crvenila, iritacija i akni zahvaljujući svojim antibakterijskim svojstvima. Takođe doprinosi posvetljavanju tamnih fleka i ujednačavanju tena, što ga čini korisnim kod hiperpigmentacija. Deluje umirujuće na osetljivu kožu i pomaže u jačanju zaštitne barijere. Redovna upotreba ekstrakta crvenog luka može doprineti čistijoj, glatkijoj i zdravijoj koži. Zbog prirodnog porekla i visokog sadržaja aktivnih komponenti, efikasan je i kod problematične kože sklone upalama. Pantenol (Provitamin B5) Pantenol u koncentraciji od 5% ima snažno hidratantno i obnavljajuće dejstvo, idealno za oslabljenu i isušenu kožu. Deluje tako što zadržava vlagu u dubljim slojevima kože, povećavajući njenu elastičnost i mekoću. Takođe ima umirujuće svojstvo, smanjuje crvenilo i iritacije te ubrzava zarastanje oštećenja i mikropovreda. Pomaže u jačanju kožne barijere, čime se povećava otpornost na spoljašnje štetne faktore. Kombinacija sa ekstraktom crvenog luka pojačava regenerativni efekat ovog seruma. Pogodan je za sve tipove kože, uključujući i osetljivu. Dodaj u listu želja Dodaj u listu želja', 'Isntree Onion Newpair B5 Ampoule je koncentrovani serum sa 850,000 ppm ekstrakta crnog luka, razvijen za tretman osetljive kože sklone flekama. Njegova blaga, vodenasta formula umiruje kožu, dok aktivno deluje na smanjenje crvenila i tamnih fleka.', 'https://beauty-health.rs/wp-content/uploads/2024/10/ISNTREE-Onion-Newpair-B5-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
