INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1551, 72, 'Heimish All Clean balm', 'heimish-all-clean-balm', 'Ključne prednosti: Efikasno uklanjanje šminke: Balzam uklanja čak i najuporniju šminku, uključujući vodootpornu maskaru. Višenamenska formula: Transformiše se iz balzama u ulje, a zatim u mleko. Temeljno čisti kožu bez iritacije. Prirodni sastojci: Sadrži shea puter i kokosevo ulje koji neguju kožu i održavaju je hidriranom. Kome je namenjen? Ovaj balzam je idealan za sve tipove kože, uključujući osetljivu kožu. Pogodan je za one koji žele brzo i temeljno uklanjanje šminke i nečistoća, bez isušivanja. Zašto volimo Heimish All Clean Balm? Heimish All Clean balsam za čišćenje je omiljen zbog svoje luksuzne, ali jednostavne formule koja lako uklanja šminku i nečistoće. Nakon upotrebe, koža ostaje meka i hidrirana, a postupak čišćenja postaje ugodan ritual. Lagana formula se pretvara u ulje, što omogućava lako nanošenje, a mlečna emulzija osigurava temeljno čišćenje. Osim toga, ovaj balzam je hipoalergen i veganski. To ga čini savršenim izborom za one koji traže blage, ali efikasne proizvode. Aktivni sastojci Prirodna esencijalna ulja Prirodna esencijalna ulja u balzamu deluju kao rastvarači koji efikasno uklanjaju šminku, SPF i nečistoće sa kože. Ova ulja imaju aromaterapeutski efekat i pružaju osećaj svežine tokom čišćenja. Takođe imaju umirujuća, antibakterijska i balansirajuća svojstva koja doprinose zdravlju kože. Pogodna su za osetljivu kožu jer ne izazivaju iritacije i ne ostavljaju mastan trag. U kombinaciji sa biljnim emolijensima, olakšavaju topljenje proizvoda u dodiru sa kožom. Shea Puter Shea puter je prirodni emolijens bogat masnim kiselinama i vitaminima A i E, poznat po svojoj sposobnosti da dubinski hidrira i omekša kožu. Pomaže u očuvanju barijere kože i sprečava transepidermalni gubitak vlage tokom i nakon čišćenja. Njegova antiinflamatorna svojstva umiruju iritacije i crvenilo. Shea buter se lako topi na koži, ostavljajući je mekom i glatkom bez osećaja masnoće. Kokosovo ulje Kokosovo ulje deluje kao blagi, ali efikasni čistač koji uklanja čak i vodootpornu šminku. Sadrži laurinsku kiselinu koja ima prirodna antimikrobna svojstva, korisna za problematičnu i osetljivu kožu. Takođe neguje i omekšava kožu, čineći je glatkom i elastičnom nakon ispiranja. Kokos u balzamima za čišćenje deluje kao prirodni emolijens koji istovremeno čisti i hrani. Dodaj u listu želja Dodaj u listu želja', 'Heimish All Clean Balm je višenamenski balzam za čišćenje lica, koji se u kontaktu s kožom transformiše iz balzama u ulje, a zatim u mlečnu emulziju. Dizajniran je da efikasno ukloni šminku, nečistoće i višak sebuma, ostavljajući kožu čistu i hidriranu.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Heimish-All-Clean-balm.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
