INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1553, 90, 'Jumiso Antioxidant Glow Facial Essence', 'jumiso-antioxidant-glow-facial-essence', 'Ključne prednosti: Trenutni sjaj i osveženje: Pruža &#8220;glass skin&#8221; efekat, koža postaje blistava i osvežena odmah nakon upotrebe. Intenzivna hidratacija: Povećava nivo hidratacije do 110% i zadržava vlagu u koži do 100 sati. Antioksidativna zaštita: Vitamin E i antioksidanti štite kožu od slobodnih radikala i zagađenja, smanjujući oštećenja i bore. Kome je namenjen? Ova esencija je idealna za sve tipove kože, posebno za kožu sa neujednačenim tonom, tamnim flekama i gubitkom elastičnosti. Takođe je savršena za one koji žele da postignu blistav i zdrav izgled kože. Zašto volimo Jumiso Antioxidant Glow Facial Essence? Jumiso Antioxidant Glow esencija pruža osećaj instant transformacije. Nakon nanošenja, koža odmah postaje blistava i hidrirana, kao da je dobila &#8220;booster&#8221; energije. Osećaj mekoće i glatkoće kože je neodoljiv, dok dugoročno ova esencija pomaže u smanjenju hiperpigmentacija i tamnih mrlja. Njena lagana tekstura omogućava brzo upijanje, čineći je savršenim dodatkom jutarnje i večernje rutine nege kože. Pruža onaj željeni &#8220;glass skin&#8221; efekat, zbog čega je koža mladalačka i sveža iz svakog ugla. Aktivni sastojci Ekstrakt korena ašvagande Ekstrakt korena ašvagande, deluje kao adaptogen i antioksidans koji štiti kožu od štetnih spoljnih uticaja kao što su zagađenje i UV zračenje. Smanjuje vidljive znake starenja, uključujući fine linije, gubitak elastičnosti i umoran izgled kože. Deluje umirujuće i balansirajuće, posebno korisno kod stresa reaktivne kože. Takođe pomaže u poboljšanju ukupnog tonusa kože i štiti ćelije od oksidativnog stresa. Efikasno podržava prirodnu regeneraciju kože. Redovnom upotrebom doprinosi očuvanju mladalačkog izgleda i otpornosti kože. Alfa-arbutin (Alpha-Arbutin) Alfa-arbutin je nežan, ali snažan sastojak za posvetljivanje kože koji inhibira enzim tirozinazu odgovoran za proizvodnju melanina. Efikasno smanjuje hiperpigmentacije, tamne fleke i staračke pege. Ujednačava ten i poboljšava svetlinu kože bez izazivanja iritacija. Dodatno, štiti kožu od oksidativnog stresa, čime usporava proces starenja. Siguran je za sve tipove kože, uključujući osetljivu. Redovna upotreba proizvoda sa alfa-arbutinom daje svetliju, ujednačeniju i blistaviju kožu. Gliceryl glukozid (Glyceryl Glucoside) Gliceryl glukozid je hidratantni sastojak koji aktivira akvaporine – proteine koji poboljšavaju transport vlage u ćelijama kože. Poboljšava zadržavanje vlage i sprečava transepidermalni gubitak vode, čineći kožu mekom i punom. Takođe pomaže u jačanju barijerne funkcije kože. Njegovo antioksidativno delovanje doprinosi zaštiti kože od oksidativnih oštećenja izazvanih slobodnim radikalima. Dodaj u listu želja Dodaj u listu želja', 'Jumiso Antioxidant Glow Facial Essence je esencija bogata antioksidantima koja trenutno pruža efekat sjaja koži, ostavljajući je blistavom i hidratizovanom. Formulisana sa vitaminom E i drugim moćnim antioksidansima, ova esencija pomaže u ujednačavanju tena, smanjenju hiperpigmentacija i zaštiti kože od štetnih uticaja okoline.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Jumiso-Antioxidant-Glow-Facial-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
