INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1555, 52, 'Dr.Melaxin EYEPHALT Eyebag Cream', 'dr-melaxin-eyephalt-eyebag-cream', 'Ključne prednosti: Smanjuje podočnjake i tamne krugove: Aktivni sastojci pomažu u posvetljivanju kože i smanjenju tamnih kolutova. Poboljšava elastičnost i čvrstinu: Krema jača strukturu kože i smanjuje vidljivost finih linija i bora. Dubinska hidratacija: Ceramidi i kolagen pružaju intenzivnu hidrataciju, vraćajući koži elastičnost i čvrstinu. Kome je namenjen? Ova krema je idealna za sve tipove kože, posebno za one koji se bore sa podočnjacima, tamnim krugovima i borama ispod očiju. Zašto volimo Dr.Melaxin EYEPHALT Eyebag Cream? Dr.Melaxin EYEPHALT krema postaje omiljena zbog svoje sposobnosti da vidljivo smanji podočnjake i osveži kožu ispod očiju. Krema se brzo upija, ne ostavlja masne tragove, a njena formula pruža dugotrajnu hidrataciju. Redovna upotreba kreme rezultira zategnutijom, osveženom kožom, koja izgleda odmorno i mladalački. Aktivni sastojci Bio-Spicules Bio-spikule su ultra-fine mikročestice koje su 15 puta manje od pora i omogućavaju duboku penetraciju aktivnih sastojaka. Njihova mikrostimulacija aktivira regenerativne procese u koži, posebno u delikatnoj regiji ispod očiju. Ubrzavaju cirkulaciju i poboljšavaju apsorpciju, čineći tretman efikasnijim. Deluju kao mikroskopski aplikatori koji stimulišu obnavljanje ćelija bez oštećenja. Ovaj proces poboljšava čvrstinu i tonus kože, smanjujući natečenost i podočnjake. Koža postaje elastičnija, glađa i osvežena. EGF (Epidermal Growth Factor) EGF je proteinski faktor rasta koji stimuliše obnovu ćelija i poboljšava elastičnost kože. Posebno je efikasan u borbi protiv tankih linija i opuštenosti u regiji ispod očiju. Podstiče sintezu kolagena i elastina, čineći kožu gušćom i mlađom. U sinergiji s bio-spikulama, EGF dopire do dubljih slojeva kože za optimalni efekt. Ova kombinacija pruža i trenutne i dugoročne rezultate u učvršćivanju kože. Koža deluje čvršće, revitalizovano i bez umornog izgleda. Dodaj u listu želja Dodaj u listu želja', 'Dr.Melaxin EYEPHALT Eyebag Cream je specijalno formulisana krema za smanjenje podočnjaka i tamnih kolutova ispod očiju. Ova krema koristi ceramide, kolagen i EGF proteine kako bi učvrstila kožu, smanjila bore i poboljšala tonus, pružajući efekt liftinga za područje oko očiju.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Dr.Melaxin-EYEPHALT-Eyebag-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
