INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1558, 40, 'Cosrx Aloe Soothing Sun Cream SPF50+', 'cosrx-aloe-soothing-sun-cream', 'Ključne prednosti: Snažna UV zaštita (SPF50+ PA+++): Obezbeđuje zaštitu od UVA i UVB zraka, štiteći kožu od oštećenja izazvanih suncem. Umirujuća i hidratantna: Aloe vera smiruje iritacije i pruža intenzivnu hidrataciju, ostavljajući kožu osveženom i mekom. Lagani finiš: Ne ostavlja masne tragove, brzo se upija i daje koži zdrav sjaj. Kome je namenjen? Ova krema je pogodna za sve tipove kože, posebno za osobe sa osetljivom, suvom ili iritiranom kožom koja traži dodatnu negu i zaštitu od sunca. Zašto volimo COSRX Aloe Soothing Sun Cream? Aloe Soothing Sun Cream nije samo obična krema za sunčanje – ona kombinuje snažnu UV zaštitu sa intenzivnom hidratacijom. Dok se borimo sa letnjim suncem ili svakodnevnim izlaganjem UV zracima, ova krema nas podseća da ne moramo da biramo između zaštite i nege. Nakon nanošenja, osećaj je lagan, bez masnog sjaja, a koža ostaje osvežena, kao da je upravo dobila nežan tretman aloe vere. Aktivni sastojci Aloe vera kompleks (55,000 ppm) Aloe vera je poznata po svojim snažnim umirujućim i hidratantnim svojstvima, što je čini idealnim sastojkom za osetljivu i nadraženu kožu. Pomaže u smanjenju crvenila i upala, dok istovremeno pruža dugotrajnu hidrataciju. Bogata je antioksidansima, enzimima i vitaminima koji pomažu u regeneraciji kože i jačanju njene zaštitne barijere. Takođe doprinosi ubrzanju procesa zarastanja manjih oštećenja kože. Njena lagana i osvežavajuća tekstura omogućava brzo upijanje bez osećaja težine ili lepljivosti. Pogodna je za sve tipove kože, uključujući suvu, masnu i kombinovanu. Dodaj u listu želja Dodaj u listu želja', 'COSRX Aloe Soothing Sun Cream je lagana krema sa zaštitnim faktorom SPF50+ koja pruža snažnu UV zaštitu, dok istovremeno hidrira i umiruje kožu zahvaljujući ekstraktu aloe vere. Idealna je za svakodnevnu upotrebu, bez masnog osećaja.', 'https://beauty-health.rs/wp-content/uploads/2024/10/COSRX-Aloe-Soothing-Sun-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
