INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1559, 40, 'Cosrx Galactomyces 95 Tone Balancing Essence', 'cosrx-galactomyces-95-tone-balancing-essence', 'Ključne prednosti: Ujednačavanje tena: Galaktomiceti pomažu u smanjenju tamnih mrlja i hiperpigmentacija, ostavljajući kožu ujednačenijom i svetlijom. Hidratacija i osveženje: Fermentisani sastojci intenzivno hidriraju kožu, vraćajući joj mekoću i elastičnost. Poboljšava teksturu: Redovnom upotrebom koža postaje glatka, meka i svežeg izgleda. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, posebno za osobe sa neujednačenim tenom i onima koji žele dodatnu hidrataciju i osveženje kože. Zašto volimo COSRX Galactomyces 95 Tone Balancing Essence? Ova esencija brzo postaje omiljeni deo rutine, jer koža postaje svetlija i ujednačenija već nakon nekoliko upotreba. Lagana, osvežavajuća tekstura brzo se upija u kožu, ostavljajući je glatkom i hidriranom. Savršen je izbor za one koji žele da obnove svoju kožu i povrate joj prirodni sjaj. Aktivni sastojci Galactomyces Ferment Filtrate Galactomyces je fermentisani sastojak bogat aminokiselinama, enzimima, mineralima i vitaminima koji poboljšavaju teksturu i tonus kože. Pomaže u hidrataciji, jačanju barijerne funkcije kože i ujednačavanju tena. Njegova antioksidativna svojstva štite kožu od slobodnih radikala i prevremenog starenja. Fermentisana formula omogućava bolju apsorpciju i efikasniju isporuku hranljivih sastojaka duboko u kožu. Redovnom upotrebom koža postaje glatkija, sjajnija i ujednačenija. Takođe pomaže u smanjenju vidljivosti pora i finih linija. Niacinamid Niacinamid (vitamin B3) je višenamenski sastojak poznat po svojoj sposobnosti da posvetli ten i smanji hiperpigmentacije. Pomaže u regulaciji proizvodnje sebuma i poboljšava izgled proširenih pora. Jača kožnu barijeru, čime poboljšava otpornost kože i zadržavanje vlage. Ima protivupalna svojstva, što ga čini idealnim za kožu sklonu crvenilu, aknama i iritacijama. Redovnom upotrebom ten postaje ujednačeniji, a koža mekša i glatkija. Takođe pomaže u smanjenju finih linija i poboljšanju elastičnosti kože. Dodaj u listu želja Dodaj u listu želja', 'COSRX Galactomyces 95 Tone Balancing Essence sadrži 95% fermentisanih galaktomiceta, moćan sastojak koji poboljšava teksturu kože, ujednačava ten i pruža hidrataciju. Ova esencija pomaže u balansiranju tena, smanjuje tamne fleke i poboljšava sjaj kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/COSRX-Galactomyces-95-Tone-Balancing-Essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
