INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1562, 39, 'Cos De BAHA Glycolic Serum', 'cos-de-baha-glycolic-serum', 'Ključne prednosti: Eksfolijacija i obnova kože: Glikolna kiselina uklanja mrtve ćelije sa površine kože, otkrivajući svež i sjajan ten. Posvetljuje i ujednačava ten: Ovaj serum pomaže u smanjenju tamnih mrlja i hiperpigmentacije, čineći ten ujednačenijim. Poboljšava teksturu kože: Redovnom upotrebom, koža postaje glatka, a njena elastičnost se vraća. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za kožu sa hiperpigmentacijom, nepravilnostima i grubom teksturom. Pogodan je za sve koji žele posvetljivanje i obnavljanje tena. Zašto volimo Cos De BAHA Glycolic Serum? Cos De BAHA serum sa glikolnom kiselinom pretvara beživotnu kožu u blistavu i osveženu. Svaka primena ovog seruma otkriva novi, sjajni sloj kože, dajući osećaj glatkoće i posvetljenja. Nakon nekoliko upotreba, ten postaje ujednačeniji, dok tamne mrlje počinju da blede. Serum brzo postaje ključni deo rutine nege kože za one koji žele obnovljen i mladalački izgled. Aktivni sastojci Glikolna kiselina (10%) Glikolna kiselina je alfa-hidroksi kiselina (AHA) poznata po svojoj sposobnosti da eksfolira površinski sloj kože, uklanjajući mrtve ćelije i poboljšavajući teksturu i tonus kože. Ona prodire duboko u kožu, stimulišući proizvodnju kolagena, što može smanjiti pojavu finih linija i bora. Takođe, pomaže u ujednačavanju tena smanjujući hiperpigmentacije i tamne mrlje. Glikolna kiselina može poboljšati hidrataciju kože povećavajući sposobnost zadržavanja vlage. Njena redovna upotreba može rezultirati sjajnijom i glatkijom kožom. ​ Aloe vera ekstrakt Aloe vera je poznata po svojim umirujućim i hidratantnim svojstvima. Bogata je vitaminima, aminokiselinama i polisaharidima koji pomažu u smanjenju iritacija i crvenila kože. Njena sposobnost da zadrži vlagu čini je odličnim hidratantnim sredstvom, pružajući koži mekoću i elastičnost. Takođe, aloe vera ima antioksidativna svojstva koja štite kožu od oštećenja izazvanih slobodnim radikalima. Njena lagana tekstura omogućava brzo upijanje, bez ostavljanja masnog osećaja na koži. Pogodna je za sve tipove kože, posebno za osetljivu i iritiranu kožu. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA Glycolic Serum sadrži glikolnu kiselinu koja efikasno uklanja mrtve ćelije kože, posvetljuje ten i poboljšava teksturu kože. Ovaj serum je savršen za eksfolijaciju i ujednačavanje tena, ostavljajući kožu glatkom i sjajnom.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Cos-De-BAHA-Glycolic-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
