INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1563, 39, 'Cos De BAHA Peptide Serum', 'cos-de-baha-peptide-serum', 'Ključne prednosti: Podstiče proizvodnju kolagena: Peptidi u serumu stimulišu prirodnu regeneraciju kože, vraćajući joj čvrstinu i smanjujući vidljivost bora. Dubinska hidratacija: Hijaluronska kiselina pruža intenzivnu hidrataciju, zadržavajući vlagu u koži tokom celog dana. Poboljšava elastičnost kože: Redovnom upotrebom, koža postaje elastičnija i otpornija na spoljašnje faktore. Kome je namenjen? Idealan je za zrelu kožu koja pokazuje znake starenja, poput gubitka elastičnosti i pojave bora. Takođe je pogodan za osobe sa suvom i dehidriranom kožom kojima je potrebna dodatna hidratacija i obnova kože. Zašto volimo Cos De BAHA Peptide Serum? Peptide Complex Serum donosi revolucionarni pristup u nezi kože sa formulom koja kombinuje peptidne komplekse Matrixyl 3000 i Argireline. Matrixyl 3000 stimuliše sintezu kolagena i elastina, što rezultira čvršćom i punijom kožom. Istovremeno, Argireline pruža efekat nalik botoksu, smanjujući mikrokontrakcije mišića i ublažavajući fine linije i bore. Hijaluronska kiselina dubinski hidrira kožu, čineći je osveženom i revitalizovanom. Rezultat je ujednačenija tekstura i blistav ten, čak i kod kože sklone starenju. Ovaj serum ne sadrži iritanse, čineći ga pogodnim za svakodnevnu upotrebu. Aktivni sastojci Matrixyl 3000 Matrixyl 3000 je peptidni kompleks koji stimuliše proizvodnju kolagena i elastina u koži, čime poboljšava njenu čvrstoću i elastičnost. Pomaže u smanjenju bora i finih linija, čineći kožu glatkijom i mlađom. Takođe, poboljšava regeneraciju ćelija kože, ubrzavajući obnavljanje i povećavajući otpornost kože na spoljašnje faktore. Ovaj kompleks deluje kao antioksidans, štiteći kožu od oksidativnog stresa i prevremenog starenja. Njegova sposobnost da hidrira i učvrsti kožu čini ga idealnim sastojkom za anti-age proizvode. Argireline Peptide Complex Argireline, poznat kao Acetyl Hexapeptide-8, deluje tako što smanjuje kontrakcije mišića lica, čime pomaže u sprečavanju nastanka mimičkih bora. Ovaj peptid je često nazivan „prirodnim botoksom“ jer smanjuje dubinu bora na čelu i oko očiju. Takođe poboljšava hidrataciju kože, smanjujući njen umoran izgled. Pomaže u jačanju kožne barijere, čime koža postaje otpornija na gubitak vlage i spoljašnje iritanse. Njegova blaga formula omogućava bezbednu upotrebu, čak i za osetljivu kožu. Ekstrakt kamilice Ekstrakt kamilice je poznat po svojim umirujućim i protivupalnim svojstvima, što ga čini odličnim za iritiranu i osetljivu kožu. Bogat je flavonoidima i antioksidansima koji pomažu u zaštiti kože od oksidativnog stresa i oštećenja izazvanih spoljašnjim faktorima. Pomaže u smanjenju crvenila i upala, čineći ten ujednačenijim i umirenim. Njegova sposobnost da poboljša hidrataciju i regeneraciju kože doprinosi njenom zdravijem izgledu. Ekstrakt kamilice takođe može pomoći u smanjenju pojave akni i iritacija. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA Peptide Serum koristi moćne sastojke kao što su Matrixyl 3000 i Argireline, koji podstiču proizvodnju kolagena i smanjuju vidljivost bora. Uz dodatak hijaluronske kiseline i niacinamida, serum intenzivno hidrira kožu i pomaže u ujednačavanju tena.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Cos-De-BAHA-Peptide-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
