INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1565, 39, 'Cos De BAHA EGF Peptide Serum', 'cos-de-baha-egf-peptide-serum', 'Ključne prednosti: Obnavljanje kože: Epidermalni faktor rasta (EGF) stimuliše regeneraciju ćelija, pomažući u smanjenju finih linija i bora. Poboljšana elastičnost: Peptidi i madecassoside iz Centella Asiatica ekstrakta povećavaju čvrstinu i elastičnost kože. Intenzivna hidratacija: Hijaluronska kiselina i pantenol zadržavaju vlagu, održavajući kožu hidriranom i svežom. Kome je namenjen? Ovaj serum je idealan za zrelu kožu koja gubi elastičnost, kao i za sve koji žele da smanje bore i poboljšaju teksturu kože. Takođe, pogodan je za suvu i dehidriranu kožu kojoj je potrebna dubinska hidratacija i revitalizacija. Zašto volimo Cos De BAHA EGF Peptide Serum? Redovnom upotrebom EGF Peptide Seruma , koža postaje vidljivo glatka i čvršća. EGF podstiče prirodnu obnovu ćelija, što dovodi do smanjenja bora i poboljšanja teksture kože. Peptidi i madecassoside rade sinergijski na jačanju strukture kože, vraćajući joj elastičnost i mladalački izgled. Hijaluronska kiselina pruža dubinsku hidrataciju, dok pantenol i ekstrakt Centella Asiatica umiruju crvenilo i upale, čineći kožu zdravijom i blistavijom. Aktivni sastojci EGF Peptid (sh-Oligopeptid-1, 5ppm) Epidermalni faktor rasta (EGF), poznat kao sh-Oligopeptid-1, podstiče regeneraciju ćelija kože, poboljšava elastičnost i smanjuje pojavu finih linija i bora. Stimuliše sintezu kolagena i elastina, čime koža postaje čvršća i hidriranija. Takođe ubrzava proces zarastanja kože i smanjuje vidljivost ožiljaka i hiperpigmentacija. EGF jača kožnu barijeru i čini kožu otpornijom na spoljašnje agresore. Koristi se u proizvodima za zrelu kožu ili kožu sa znakovima starenja. Prisustvo ovog peptida u serumu poboljšava teksturu i tonus kože. Centella Asiatica ekstrakt Centella Asiatica, poznata i kao Cica, ima snažna umirujuća i regenerativna svojstva. Bogata je antioksidansima i amino kiselinama koje pomažu u smanjenju upala i crvenila. Jača kožnu barijeru i poboljšava hidrataciju, čineći kožu otpornijom i zdravijom. Stimuliše proizvodnju kolagena, što doprinosi poboljšanju elastičnosti kože. Njena lagana tekstura omogućava brzo upijanje bez ostavljanja masnog osećaja. Pogodna je za sve tipove kože, uključujući i osetljivu kožu sklonu iritacijama. Madecassoside Madecassoside je aktivni sastojak biljke Centella Asiatica, poznat po svojim antiinflamatornim i regenerativnim svojstvima. Pomaže u smanjenju crvenila i umirivanju iritacija, što ga čini pogodnim za osetljivu kožu. Jača zaštitnu barijeru kože, sprečavajući gubitak vlage i štiteći kožu od spoljašnjih uticaja. Stimuliše regeneraciju ćelija, ubrzavajući zaceljivanje oštećene kože i poboljšavajući njen tonus. Njegova antioksidativna svojstva pomažu u zaštiti kože od prevremenog starenja. Redovna upotreba proizvoda sa madecassoside-om poboljšava zdravlje i izgled kože. Dodaj u listu želja Dodaj u listu želja', 'Cos De BAHA EGF Peptide Serum je visoko koncentrisan serum koji pomaže u obnavljanju kože, poboljšava njenu elastičnost i smanjuje vidljivost bora. Zahvaljujući moćnim peptidima i EGF-u, podstiče regeneraciju ćelija i doprinosi svežem i mladalačkom izgledu.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Cos-De-BAHA-EGF-Peptide-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
