INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1568, 25, 'Benton Portable Toner Pad Case', 'benton-portable-toner-pad-case', 'Karakteristike: Dimenzije : 86.5mm x 86.5mm x 32.5mm – dovoljno mala za torbicu, a dovoljno velika da drži do 20 jastučića. Zaštita od curenja : Unutrašnji poklopac sprečava curenje tečnosti i isušivanje jastučića. Ugrađene pincete : Pincete omogućavaju higijensko vađenje jastučića bez dodirivanja prstima. Materijal visokog kvaliteta : Izrađena od čvrstih materijala, osigurava dugotrajnost i zaštitu. Moderan dizajn : Estetski dizajn koji se lako uklapa u bilo koju torbicu ili kozmetički neseser. Zašto volimo Benton Portable Toner Pad Case? Ova kutija je savršena za ljubitelje nege kože koji često putuju ili žele organizovan i higijenski način čuvanja jastučića sa tonerom. Zahvaljujući kompaktnom dizajnu i zaštiti od curenja, vaši jastučići će ostati sveži i spremni za upotrebu gde god da se nalazite. Idealna je za one koji cene praktičnost i visok nivo higijene u svakodnevnim beauty rutinama. Dodaj u listu želja Dodaj u listu želja', 'Benton Portable Toner Pad Case je praktična kutija za jastučiće sa tonerom i savršen je dodatak za vašu svakodnevnu rutinu nege kože. Njena konstrukcija uključuje poklopac koji sprečava curenje tečnosti, kao i unutrašnji poklopac koji održava svežinu jastučića i sprečava isparavanje.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Benton-Portable-Toner-Pad-Case.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
