INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1576, 12, 'APLB Hyaluronic Acid Ceramide HA B5 Facial Cream', 'aplb-hyaluronic-acid-ceramide-ha-b5-facial-cream', 'Ključne prednosti: Dubinska hidratacija : Zahvaljujući visokoj koncentraciji hijaluronske kiseline, ova krema efikasno zadržava vlagu u koži, smanjujući dehidraciju i poboljšavajući elastičnost. Jačanje barijere : Ceramidi obnavljaju zaštitnu barijeru kože, pomažući u sprečavanju gubitka vlage i zaštiti od spoljašnjih uticaja. Umirenje i obnova : Provitamin B5 (pantenol) umiruje iritiranu kožu, smanjuje crvenilo i pospešuje regeneraciju. Kome je namenjena? Idealna je za sve tipove kože, posebno za suvu, osetljivu i kožu sklonu iritacijama. Preporučuje se osobama koje traže dubinsku hidrataciju, kao i onima sa oštećenom ili dehidriranom kožom kojoj je potrebna obnova. Zašto volimo APLB Hyaluronic Acid Ceramide HA B5 Facial Cream? Ova krema pruža savršenu kombinaciju intenzivne hidratacije i zaštite, čineći kožu mekom i elastičnom. Njena lagana, ali bogata formula ne ostavlja masne tragove i brzo se upija, što je čini pogodnom za svakodnevnu upotrebu, bilo da je vaša koža suva ili sklona iritacijama. Ova krema posebno pomaže u oporavku kože tokom zimskih meseci kada je potrebna dodatna hidratacija i obnova barijere. Aktivni sastojci Centella Asiatica ekstrakt (30,4%) : Ovaj ekstrakt, poznat i kao gotu kola ili tigrova trava, tradicionalno se koristi za lečenje manjih rana, opekotina i ogrebotina zbog svojih antiinflamatornih svojstava. Sadrži aktivne komponente poput azijatikozida, madekasične kiseline i azijatične kiseline, koje stimulišu sintezu hijaluronske kiseline i kolagena, poboljšavajući hidrataciju i elastičnost kože. Takođe, pomaže u jačanju kožne barijere i smanjenju crvenila, što ga čini idealnim za osetljivu i iritiranu kožu. ​ Glicerin : Prirodni ovlaživač koji se nalazi i u našoj koži, glicerin privlači vodu iz dubljih slojeva kože i iz okoline, zadržavajući je u epidermisu. Pruža trenutnu i dugotrajnu hidrataciju, ostavljajući kožu mekom i glatkom. Takođe, pomaže u održavanju lipidne barijere kože, štiteći je od isušivanja i iritacija. ​ Natrijum hijaluronat (8.000 ppb) : So hijaluronske kiseline, natrijum hijaluronat je poznat po svojoj sposobnosti da veže velike količine vode, do 1.000 puta svoje težine. Ovaj sastojak dubinski hidrira kožu, povećava njenu elastičnost i popunjava fine linije i bore, dajući joj mladalački izgled. Takođe, poboljšava transport hranljivih materija do ćelija kože, podržavajući njen zdrav izgled. ​ Ceramid NP (5.000 ppb) : Ceramidi su lipidi koji čine oko 50% međustaničnog matriksa u gornjem sloju kože, igrajući ključnu ulogu u održavanju integriteta kožne barijere. Ceramid NP pomaže u obnavljanju i zaštiti barijere kože, sprečavajući gubitak vlage i štiteći je od spoljašnjih agresora. Njegova upotreba rezultira glatkom, hidriranom i otpornijom kožom. ​ Pantenol (5.000 ppm) : Poznat i kao provitamin B5, pantenol je ovlaživač koji prodire duboko u kožu, pružajući intenzivnu hidrataciju. Ima antiinflamatorna svojstva, smanjuje crvenilo i iritacije, te pospešuje proces zarastanja rana. Redovnom upotrebom, pantenol poboljšava elastičnost kože i daje joj glatki izgled. ​ Beta-glukan : Prirodni polisaharid koji se nalazi u ćelijskim zidovima kvasca, nekih gljiva i žitarica. Beta-glukan ima snažna antioksidativna i antiinflamatorna svojstva, pomaže u regeneraciji kože i poboljšava njenu otpornost na spoljašnje stresore. Takođe, pruža dubinsku hidrataciju i poboljšava teksturu kože, čineći je mekšom i elastičnijom. Dodaj u listu želja Dodaj u listu želja', 'APLB Hyaluronic Acid Ceramide HA B5 Facial Cream je hidratantna krema formulisana sa hijaluronskom kiselinom, ceramidima i provitaminom B5, koja pomaže u dubinskoj hidrataciji, jačanju kožne barijere i obnavljanju oštećene kože.', 'https://beauty-health.rs/wp-content/uploads/2024/10/APLB-Hyaluronic-Acid-Ceramide-HA-B5-Facial-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
