INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1582, 14, 'Arensia Holy Hyssop Serum 30', 'arencia-holy-hyssop-serum-30', 'Ključne prednosti: Posvetljivanje kože : Niacinamid i Vita ACE kompleks pomažu u smanjenju tamnih fleka i ujednačavanju tona kože. Smanjenje bora : Peptidi podstiču proizvodnju kolagena, čineći kožu čvršćom i smanjujući pojavu bora. Hidratacija : Hijaluronska kiselina dubinski hidrira kožu, pomažući u održavanju vlažnosti tokom celog dana. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za kožu sklonu tamnim flekama, ožiljcima i prvim znacima starenja. Preporučuje se osobama koje žele da ujednače ton kože, poboljšaju njenu teksturu i očuvaju mladalački izgled. Zašto volimo Arensia Holy Hyssop Serum 30? Holy Hyssop Serum koristi prirodnu snagu biljke izop- miloduha, poznate po svojim umirujućim i regenerativnim svojstvima, kako bi poboljšao izgled kože. Svaka kap ovog seruma pruža osećaj svežine i hidratacije, dok hijaluronska kiselina dubinski hidrira, čineći kožu vidno elastičnijom. Zamislite serum koji ujedno regeneriše, smiruje i štiti kožu. Idealan je za svakodnevnu upotrebu bez iritacija. Dugotrajnom upotrebom, koža postaje otpornija na štetne uticaje iz okoline, a ten izgleda zdravije i svetlije. Sastojci poput niacinamida pomažu u posvetljivanju tena i smanjenju znakova starenja. Aktivni sastojci Ekstrakt miloduha (Hyssopus Officinalis Extract) Ovaj ekstrakt bogat je vitaminima A, C i E, koji deluju kao snažni antioksidansi. Pomaže u smanjenju iritacija i upala na koži, pružajući umirujuće dejstvo i poboljšavajući njenu elastičnost. Takođe, doprinosi regeneraciji oštećene kože, čineći je glatkom i osveženom.​ Vita ACE kompleks (30%) Ovaj kompleks kombinuje visoko koncentrisane vitamine A, C i E, koji sinergijski deluju na posvetljivanje kože i borbu protiv slobodnih radikala. Vitamin A stimuliše obnovu ćelija, vitamin C posvetljuje ten i smanjuje fleke, dok vitamin E hidrira i štiti kožu od oštećenja, pružajući joj mladalački izgled.​ Niacinamid (10%) Poznat i kao vitamin B3, niacinamid je poznat po svojoj sposobnosti da smanji tamne fleke, crvenilo i ožiljke od akni. Pomaže u poboljšanju elastičnosti kože i zateže pore, čineći kožu glatkom i ujednačenom. Takođe, jača barijernu funkciju kože, štiteći je od spoljašnjih agresora.​ Hijaluronska kiselina Ovaj moćni ovlaživač zadržava vlagu u koži, pružajući joj elastičnost i punoću. Pomaže u smanjenju finih linija i bora, osiguravajući dugotrajnu hidrataciju i blistavost kože. Takođe, poboljšava teksturu kože, čineći je mekom i glatkom.​ Peptidi Peptidi podstiču proizvodnju kolagena, čime poboljšavaju čvrstinu i elastičnost kože. Smanjuju pojavu finih linija i bora, doprinoseći mladalačkom izgledu kože. Takođe, pomažu u regeneraciji kože i poboljšavaju njenu otpornost na spoljašnje faktore.​ Dodaj u listu želja Dodaj u listu želja', 'Arensia Holy Hyssop Serum 30 je visoko koncentrisan serum koji revitalizuje, hidrira i posvetljuje kožu. Sadrži 30% Vita ACE kompleks koji kombinuje vitamine A, C, i E, zajedno sa niacinamidom i peptidima za borbu protiv hiperpigmentacije, finih linija i gubitka elastičnosti.', 'https://beauty-health.rs/wp-content/uploads/2024/10/Arencia-Holy-Hyssop-Serum-30.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
