INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1585, 14, 'Arensia Fresh Royal Rosehip Cleanser', 'arencia-fresh-royal-rosehip-cleanser', 'Ključne prednosti: Dubinsko čišćenje : Efikasno uklanja šminku, sebum i nečistoće, ostavljajući kožu čistu i osveženu. Hidratacija i umirenje : Ekstrakti šipka i ruže hidratizuju kožu i smiruju iritacije, čineći je glatkom i mekom. Održavanje prirodnog balansa kože : Prirodni biljni sastojci pomažu u održavanju pH ravnoteže kože, što smanjuje rizik od iritacija. Kome je namenjen? Ovaj čistač je pogodan za sve tipove kože, uključujući kombinovanu, suvu, masnu i osetljivu kožu. Posebno je koristan za one koji žele dubinsko čišćenje bez narušavanja prirodne barijere kože. Zašto volimo Arensia Fresh Royal Rosehip Cleanser? Ovaj čistač je inspirisan snagom prirodnih sastojaka, kombinujući antioksidativno bogatstvo ulja šipka sa nežnim čistačima koji uklanjaju sve tragove nečistoća i šminke. Dok nežno masirate ovaj čistač na licu, osećate kako bogata formula prodire u pore, uklanja nečistoće i revitalizuje kožu, ostavljajući je osveženom i glatkom. Nakon upotrebe, koža je osvežena i mekana, dok ulje šipka pomaže u regeneraciji ćelija, dajući licu zdrav sjaj i čvrstinu. Redovnom upotrebom, ten postaje blistaviji i uravnoteženiji, bez osećaja zatezanja ili iritacije. Aktivni sastojci Ekstrakt šipka (Rosa Canina Fruit Extract) Bogat vitaminom C i antioksidansima, ekstrakt šipka pomaže u posvetljavanju kože i smanjenju hiperpigmentacija. Takođe, podstiče regeneraciju kože, poboljšava njenu elastičnost i štiti od oštećenja izazvanih slobodnim radikalima. ​ Ekstrakt lista aloe vere (Aloe Barbadensis Leaf Extract) Poznat po svojim umirujućim i hidratantnim svojstvima, ekstrakt aloe vere pomaže u smirivanju iritacija i crvenila, dok istovremeno pruža dubinsku hidrataciju, ostavljajući kožu mekom i osveženom. ​ Ekstrakt kamilice (Chamomilla Recutita (Matricaria) Extract) Ovaj ekstrakt ima umirujuća i antiinflamatorna svojstva, pomažući u smanjenju upala i iritacija na koži. Takođe, pruža antioksidativnu zaštitu, štiteći kožu od štetnih spoljašnjih faktora. ​ Prah slatkog badema (Prunus Amygdalus Dulcis (Sweet Almond) Seed Powder) Djeluje kao blagi fizički eksfolijant, uklanjajući mrtve ćelije kože i nečistoće, čime poboljšava teksturu kože i ostavlja je glatkom i osveženom. ​ Prah pirinča (Oryza Sativa (Rice) Powder) Pruža blagu eksfolijaciju, pomažući u uklanjanju mrtvih ćelija kože i nečistoća, čime se postiže glatka i sjajna koža. Dodaj u listu želja Dodaj u listu želja', 'Arensia Fresh Royal Rosehip Cleanser je inovativni čistač za lice sa veganskom formulacijom, bogat ekstraktima šipka i ruže. Njegova jedinstvena tekstura podseća na „mochi“ – tradicionalni japanski kolač, a ova struktura omogućava nežno, ali efikasno čišćenje kože.', 'https://beauty-health.rs/wp-content/uploads/2024/09/Arencia-Fresh-Royal-Rosehip-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
