INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1586, 14, 'Arensia Fresh Green Rice Mochi Cleanser', 'arencia-fresh-green-cleanser', 'Ključne prednosti: Dubinsko čišćenje : Pirinčani prah deluje kao blagi eksfolijant, uklanja mrtve ćelije kože i čisti pore. Hidratacija i umirenje : Ekstrakti hamamelisa i hijaluronske kiseline pomažu u zadržavanju vlage i umirivanju kože. Posvetljivanje tena : Prirodni ekstrakti poput zelenog čaja i slatkog badema pomažu u ujednačavanju tena i smanjuju hiperpigmentaciju. Kome je namenjen? Ovaj čistač je odličan za sve tipove kože, ali posebno za one sa masnom i kombinovanom kožom sklonom nečistoćama. Takođe je pogodan za osetljivu kožu zahvaljujući blagim i umirujućim sastojcima. Zašto volimo Arencia Fresh Green Cleanser? Arensia Fresh Green čistač pruža dubinsko čišćenje, uklanjajući mrtve ćelije i višak sebuma, a pritom ne isušuje kožu. Njegova gelasta tekstura osvežava lice, dok kombinacija prirodnih sastojaka pomaže u smirivanju iritacija i osvetljavanju kože. Ovaj preparat je savršen izbor za svakodnevnu upotrebu, jer balansira čišćenje i hidrataciju. Aktivni sastojci Hamamelis Virginiana (veštičja leska) ekstrakt Ovaj ekstrakt bogat je vitaminima A i C, poznatim po svojstvima ujednačavanja tena. Doprinosi smanjenju crvenila i iritacija, dok istovremeno pruža blago stezanje pora, čineći kožu glatkom i osveženom. ​ Oryza Sativa (pirinčani) prah Pirinčani prah je poznat po svojim hranljivim svojstvima, bogat vitaminima i mineralima koji njeguju kožu. Pomaže u blagoj eksfolijaciji, uklanjajući mrtve ćelije kože i ostavljajući je mekom i sjajnom. ​ Hyssopus Officinalis (hizop) ekstrakt Ekstrakt hizopa ima umirujuća svojstva koja pomažu u smirivanju iritirane kože. Takođe, poznat je po svojim antioksidativnim svojstvima koja štite kožu od štetnih uticaja slobodnih radikala. ​ Glycerin Prirodni ovlaživač koji privlači vlagu iz okoline u kožu, održavajući je hidriranom i mekom. Takođe, pomaže u jačanju kožne barijere, sprečavajući gubitak vlage. ​ Kaolin Bela glina koja deluje kao blagi abraziv i apsorbent, uklanjajući nečistoće i višak sebuma sa kože. Pruža glatku teksturu i pomaže u matiranju kože bez isušivanja. Dodaj u listu želja Dodaj u listu želja', 'Arensia Fresh Green Cleanser je osvežavajući gel za čišćenje lica, formulisan sa pirinčanim prahom i ekstraktom hamamelisa. Dubinski čisti pore i uklanja nečistoće, a pritom održava kožu hidriranom i umirenom.', 'https://beauty-health.rs/wp-content/uploads/2024/09/arencia-Fresh-Green-Cleanser.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
