INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1587, 9, 'Acwell Licorice pH Balancing Cleansing Toner', 'acwell-licorice-ph-balancing-cleansing-toner', 'Ključne prednosti: Dubinsko čišćenje : Efikasno uklanja preostale nečistoće posle umivanja, bez isušivanja kože. Balansiranje pH vrednosti : Zahvaljujući pH vrednosti od 5.5, toner balansira kožu i priprema je za sledeće korake nege. Posvetljivanje kože : Ekstrakti sladića i peonije pomažu u posvetljavanju i ujednačavanju tena, smanjujući tamne fleke i hiperpigmentaciju. Kome je namenjen? Ovaj toner je pogodan za sve tipove kože, uključujući osetljivu i kožu sklonu iritacijama. Idealan je za one koji žele osvetljavanje tena, smanjenje tamnih fleka i hidriranu kožu bez osećaja zatezanja. Zašto volimo Acwell Licorice pH Balancing Cleansing Toner? Ovaj toner je savršen za one koji žele multifunkcionalni proizvod – ne samo da čisti, već i hidrira i osvetljava kožu. Njegova lagana, nemasna tekstura brzo se upija i ostavlja kožu osveženom i spremnom za dalju negu. Zahvaljujući ekstraktu sladića i zelenom čaju, toner pomaže u smanjenju crvenila i smirivanju iritacija, što ga čini pogodnim za osetljivu kožu. Aktivni sastojci Voda korena sladića (Glycyrrhiza Glabra) Ovaj sastojak je poznat po svojoj sposobnosti da posvetljuje kožu i smanjuje tamne fleke. Takođe je snažan antioksidans koji pomaže u smirivanju iritacija i crvenila. Camellia Sinensis leaf extract (Zeleni čaj) Zeleni čaj je bogat polifenolima koji deluju kao antioksidansi, pomažući u zaštiti kože od oštećenja izazvanih slobodnim radikalima. Takođe smanjuje crvenilo i poboljšava teksturu kože, dok istovremeno smiruje upale. Ekstrakt peonije Ovaj ekstrakt ima sposobnost da osvetli kožu i ujednači njen ton, pružajući joj zdrav, blistav izgled. Pomaže i u smanjenju znakova starenja, poput finih linija. Hijaluronska kiselina Moćan humektant koji zadržava vlagu u koži, čineći je hidriranom i elastičnom. Pomaže u održavanju hidratacije tokom celog dana, bez osećaja težine na koži. Dodaj u listu želja Dodaj u listu želja', 'Acwell Licorice pH Balancing Cleansing Toner je toner sa licorice vodom i peonijom, formulisan za dubinsko čišćenje, balansiranje pH vrednosti kože (pH 5.5), i postizanje ujednačenog tena. Ovaj toner uklanja preostale nečistoće nakon čišćenja lica, dok istovremeno hidrira kožu i osvežava je.', 'https://beauty-health.rs/wp-content/uploads/2024/09/Acwell-Licorice-pH-Balancing-Cleansing-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
