INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1595, 6, 'Abib Collagen Gel Mask Heartleaf Jelly', 'abib-collagen-gel-mask-heartleaf-jelly', 'Ključne prednosti: Hidratacija i čvrstina : Kolagen i hijaluronska kiselina duboko vlaže kožu i vraćaju joj elastičnost. Umirujuće dejstvo : Heartleaf smiruje iritacije i crvenilo, dok Centella Asiatica pomaže u regeneraciji. Regeneracija : Peptidi pomažu u proizvodnji kolagena, što doprinosi smanjenju bora i čvrstoći kože. Kome je namenjena? Ova maska je idealna za sve tipove kože, posebno za osobe sa osetljivom, suvom ili dehidriranom kožom koja zahteva dubinsku hidrataciju i umirenje. Posebno je pogodna za one koji žele poboljšanje elastičnosti kože i smanjenje iritacija. Zašto volimo Abib Collagen Gel Mask Heartleaf Jelly? Abib Collagen Gel Mask Heartleaf zahvaljujući svojoj bogatoj gel teksturi osvežava kožu i istovremeno smanjuje znake stresa i iritacija. Ekstrakt Heartleaf-a pomaže u balansiranju sebuma i umiruje kožu, dok kolagen obnavlja elastičnost i čvrstinu, ostavljajući kožu blistavom. Ova maska je odlična opcija za sve koji žele instant osveženje nakon dugog dana ili kao deo redovne anti-age nege. Aktivni sastojci Kolagen i peptidi Kolagen i peptidi pomažu koži da zadrži čvrstinu i elastičnost, doprinoseći zaglađenijem i punijem izgledu. Podržavaju prirodnu strukturu kože i smanjuju vidljivost finih linija. Redovnom upotrebom koža izgleda negovanije, čvršće i ujednačenije. Heartleaf (Houttuynia cordata) Heartleaf je poznat po svom umirujućem delovanju i sposobnosti da smanji osećaj iritacije i crvenila. Pomaže u održavanju hidratacije i balansa kože, čineći je prijatnom i smirenom. Posebno je pogodan za osetljivu i reaktivnu kožu. Tanini Tanini deluju adstringentno i pomažu u vizuelnom sužavanju pora. Doprinosе zategnutijem i glađem izgledu kože. Koža nakon upotrebe deluje svežije, čistije i ujednačenije. Dodaj u listu želja Dodaj u listu želja', 'Abib Collagen Gel Mask Heartleaf Jelly je bogata gel maska koja kombinuje kolagen i ekstrakt biljke kameleon (Heartleaf) kako bi koži pružila intenzivnu hidrataciju, čvrstoću i umirujući efekat. Ova maska obnavlja kožu, vraća joj elastičnost i osvežava ten.', 'https://beauty-health.rs/wp-content/uploads/2024/09/Abib-collagen-gel-Hearleaf-jelly-mask.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
