INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1597, 6, 'Abib Gummy Sheet Mask Madecassoside Sticker', 'abib-gummy-sheet-mask-madecassoside-sticker', 'Ključne prednosti: Duboka hidratacija : Hijaluronska kiselina osigurava dugotrajnu hidrataciju. Regeneracija i zaštita : Madekazozid pomaže u obnavljanju kože, smanjujući crvenilo. Savršeno prianjanje : Maska se prilagođava obliku lica zahvaljujući naprednoj tehnologiji. Kome je namenjena? Ova maska je idealna za sve tipove kože. Posebno za osobe sa iritiranom i osetljivom kožom koja zahteva smirenje, obnavljanje i dubinsku hidrataciju. Odlično je rešenje za kožu koja je doživela stres, umor ili spoljne agresore poput zagađenja. Zašto volimo Abib Gummy Sheet Mask Madecassoside Sticker? Postoji nešto posebno u iskustvu korišćenja ove maske. Njena jedinstvena tekstura koja savršeno prianja uz lice stvara osećaj luksuza, dok svaki sastojak intenzivno radi na hidrataciji i regeneraciji kože. Kao nevidljivi štit, madekazozid umiruje kožu, pomažući joj da se oporavi od dnevniog stresa, dok hijaluronska kiselina intenzivno hidrira svaku poru. Nakon samo 20 minuta, osećaj na koži je osvežavajući, gotovo kao da je vaša koža dobila novu energiju. Ova maska je više od nege – to je trenutak odmora za vašu kožu. Dodaj u listu želja Dodaj u listu želja', 'Abib Gummy Sheet Mask Madecassoside Sticker je intenzivna maska koja kombinuje moć madekazozida za umirenje i regeneraciju sa naprednom tehnologijom prianjanja. Ova maska ne samo da hidrira, već i obnavlja oštećenu i osetljivu kožu, vraćajući joj balans i svežinu.', 'https://beauty-health.rs/wp-content/uploads/2024/09/Abib-Gummy-Sheet-Mask-Madecassoside-Sticker-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
