INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1598, 6, 'Abib Pore Cleansing Oil Heartleaf Oil-Wash', 'abib-pore-cleansing-oil-heartleaf-oil-wash', 'Ključne prednosti: Dubinsko čišćenje pora : Efikasno uklanja nečistoće, šminku i višak sebuma iz dubine pora. Održavanje vlažnosti kože : Zahvaljujući hidratantnim svojstvima, koža ostaje mekana i osvežena. Umirujuće dejstvo : Heartleaf ekstrakt smiruje upale, crvenilo i iritacije, savršen za osetljivu kožu. Kome je namenjen? Ovaj čistač je savršen za osobe sa masnom i kombinovanom kožom. Takođe, idealan je za osetljivu kožu sklonu crvenilu i upalama. Zašto volimo Abib Pore Cleansing Oil Heartleaf Oil-Wash? Ovaj uljani čistač ne samo da efikasno uklanja dnevnu prljavštinu i šminku, već donosi mir koži koja je svakodnevno izložena stresu i zagađenju. Njegova lagana tekstura nežno klizi po koži, topi nečistoće. Istovremeno ostavlja osećaj svežine. Ono što ga izdvaja je balans između efikasnog čišćenja i nežne nege. Kožu ostavlja hidriranom i umirenom, bez osećaja težine ili začepljenih pora. Bez obzira da li imate masnu ili osetljivu kožu, ovaj proizvod postaje osnova vaše rutine, pružajući svakodnevni trenutak opuštanja. Aktivni sastojci Ekstrakt Houttuynia Cordata (Heartleaf) Ovaj ekstrakt je poznat po svojim antiinflamatornim i antibakterijskim svojstvima, što ga čini idealnim za umirivanje osetljive i problematične kože sklone aknama. Pomaže u regulaciji proizvodnje sebuma i smanjuje upale, doprinoseći čistijem i zdravijem izgledu kože. ​ Gluconolactone (PHA) Gluconolactone je polihidroksi kiselina (PHA) koja deluje kao blagi eksfolijant. Pomaže u uklanjanju mrtvih ćelija kože, poboljšava teksturu kože i posvetljuje ten, a pritom je manje iritantna u poređenju sa drugim kiselinama, što je čini pogodnom za osetljivu kožu. ​ Ulje semena suncokreta (Helianthus Annuus Seed Oil) Ovo ulje je bogato esencijalnim masnim kiselinama i vitaminom E, pružajući hidrataciju i zaštitu koži. Deluje kao emolijent, omekšava kožu i pomaže u održavanju njene elastičnosti. ​ Ulje semena jojobe (Simmondsia Chinensis Seed Oil) Ulje jojobe je poznato po svojoj sličnosti sa prirodnim sebumom kože, što ga čini odličnim za balansiranje proizvodnje ulja. Pruža hidrataciju bez začepljenja pora i ima umirujuća svojstva koja pomažu u smanjenju upala. ​ Ulje makadamije (Macadamia Ternifolia Seed Oil) Ovo ulje je bogato mononezasićenim masnim kiselinama koje pomažu u obnavljanju i hidrataciji kože, čineći je mekom i glatkom. ​ Ulje pirinčanih mekinja (Oryza Sativa Bran Oil) Ulje pirinčanih mekinja sadrži antioksidante i esencijalne masne kiseline koje hrane kožu, poboljšavaju njenu elastičnost i pružaju zaštitu od spoljašnjih agresora. ​ Ulje avokada (Persea Gratissima Oil) Ulje avokada je bogato vitaminima A, D i E, pružajući dubinsku hidrataciju i ishranu koži. Takođe pomaže u smanjenju upala i poboljšava elastičnost kože. ​ Ulje semena kamelije (Camellia Japonica Seed Oil) Ovo ulje je poznato po svojim hidratantnim i antioksidativnim svojstvima, pomažući u zaštiti kože od slobodnih radikala i održavanju njene vitalnosti. Dodaj u listu želja Dodaj u listu želja', 'Abib Pore Cleansing Oil Heartleaf Oil-Wash je uljani čistač koji temeljno uklanja šminku, nečistoće i višak sebuma. Namenjen je osobama sa masnom, osetljivom ili kombinovanom kožom koje traže blagi, ali efikasan čistač.', 'https://beauty-health.rs/wp-content/uploads/2024/09/Abib-Pore-Cleansing-Oil-Heartleaf-Oil-Wash.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
