INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1601, 126, 'Numbuzin No.5 Vitamin Concentrated Serum', 'numbuzin-no-5-vitamin-concentrated-serum', 'Ključne prednosti: Posvetljuje i ujednačava ton kože : Smanjuje tamne mrlje i neujednačen ten. Hidrira i obnavlja : Poboljšava teksturu kože, čineći je mekom i glatkom. Antioksidativna zaštita : Štiti kožu od štetnih uticaja spoljašnje sredine i slobodnih radikala​. Kome je namenjen? Serum je lagane, hidratantne ali nelepljive teksture koja odgovara svim tipovima kože. Idealan je dodatak vašoj anti-age rutini jer pruža zaštitu od brojnih faktora iz spoljašnje sredine i zagađenja.Neizostavan je deo rutine ukoliko se borite protiv hiperpigmentacija i melazme. Zašto volimo Numbuzin No.5 Vitamin Concentrated Serum? Numbuzin No.5 Vitamin je savršen saveznik u borbi protiv tamnih fleka, neujednačenog tena i znakova starenja. Sa snažnom kombinacijom vitamina C, glutationa i niacinamida, ovaj serum pruža vašoj koži sve što joj je potrebno da zablista. Redovnom upotrebom, koža postaje vidljivo osvežena, glatka i blistava, sa smanjenim tragovima stresa i umora. Pantenol i adenozin dodatno umiruju i regenerišu kožu, pružajući joj potrebnu hidrataciju i zaštitu od spoljašnjih faktora. Aktivni sastojci Glutation Glutation je moćan antioksidans koji efikasno deluje na ujednačavanje tena i posvetljavanje kože. Inhibira enzim tirozinazu, koji je ključan u procesu sinteze melanina, čime pomaže u smanjenju tamnih fleka i hiperpigmentacija. Takođe štiti kožu od oksidativnog stresa izazvanog UV zračenjem i zagađenjem, čime usporava proces starenja. Podstiče prirodnu regeneraciju ćelija i doprinosi zdravijem, blistavijem izgledu kože. Njegova stabilna forma u ovom serumu omogućava svakodnevnu upotrebu bez iritacija. Ključan je u postizanju ujednačenog tona i osvetljenog tena. Niacinamid (Vitamin B3) Niacinamid je višenamenski aktivni sastojak koji pruža osvetljavajuće, hidratantne i umirujuće efekte. Pomaže u smanjenju vidljivosti tamnih mrlja i ujednačava ten inhibicijom prenosa melanina u epidermalne ćelije. Takođe jača kožnu barijeru, smanjuje transepidermalni gubitak vode i poboljšava elastičnost kože. Njegova protivupalna svojstva čine ga pogodnim za osetljivu i aknama sklonu kožu. U ovom serumu doprinosi zdravom, hidriranom i ujednačenom tenu sa prirodnim sjajem. Redovnom upotrebom koža postaje osvežena, glatkija i manje reaktivna. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.5 Vitamin Concentrated Serum je visoko koncentrisan serum osmišljen da pruži vašoj koži sve što joj je potrebno za blistav i zdrav izgled. Obogaćen ključnim vitaminima, uključujući niacinamid i vitamin C, ovaj serum je vaš idealan partner u borbi protiv tamnih mrlja, hiperpigmentacije, i neujednačenog tena.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Numbuzin-No.5-Vitamin-Concentrated-Serum-30ml.webp', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
