INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1602, 164, 'Tirtir Ceramic Milk Ampoule', 'tirtir-ceramic-milk-ampoule', 'Ključne prednosti: Dubinska hidratacija i jačanje barijere : Pruža intenzivnu hidrataciju dok istovremeno jača kožnu barijeru. Posvetljuje i ujednačava ton kože : Zahvaljujući niacinamidu i fermentisanim ekstraktima, ovaj proizvod ujednačava ten i smanjuje tamne mrlje. Poboljšava elastičnost i čvrstinu kože : Ceramidi i hijaluronska kiselina rade zajedno na poboljšanju elastičnosti kože i smanjenju finih linija. Kome je namenjen? Ova ampula je idealna za sve tipove kože, a posebno za one koji traže dubinsku hidrataciju, obnovu i elastičnost. Pogodna je i za osetljivu kožu koja zahteva nežnu, ali efikasnu negu​. Zašto volimo Tirtir Ceramic Milk Ampoule? TIRTIR Ceramic Milk ampula serum je vaša tajna za postizanje savršene &#8220;glass skin&#8221; kože. Ova jedinstvena ampula pruža intenzivnu hidrataciju, čineći kožu zategnutom i blistavom. Sa moćnim sastojcima poput fito-amino kiselina, peptida i squalana, ova ampula ne samo da obnavlja oštećenu kožu, već i jača njenu barijeru, pružajući dugotrajnu zaštitu i vlagu. Zahvaljujući glatkoj, mlečnoj teksturi, ampula se lako upija u kožu, ostavljajući je mekom, hidriranom i bez masnog osećaja. Aktivni sastojci Vegan Milk Complex (10,000 ppm) Biljna mešavina sastojaka na bazi soje, kokosa, badema, ovsa i pirinča. Soja poboljšava elastičnost kože, kokos hidrira, badem hrani, ovas jača kožnu barijeru, dok pirinač osvetljava i ujednačava ten. Zajedno, ovi sastojci dubinski hrane i obnavljaju kožu. Lactobacillus/Soybean Ferment Extract Fermentisani ekstrakt soje bogat nutrijentima koji pomaže u hidrataciji i regeneraciji kože. Povećava sposobnost kože da zadrži vlagu i smanjuje osetljivost, uz istovremenu podršku mikrobiomu kože. 6-Ceramide Complex Kompleks šest tipova ceramida koji jačaju kožnu barijeru, sprečavaju gubitak vlage i štite od spoljašnjih iritacija. Pomažu u obnovi suve, oštećene ili oslabljene kože. Phyto-Amino Acid Complex Biljni kompleks amino kiselina koji učestvuju u obnavljanju strukture kože i poboljšavaju elastičnost. Doprinosi zdravijem, punijem i hidriranom izgledu kože. Peptidi Deluju protiv znakova starenja, podstiču sintezu kolagena i pomažu u zaglađivanju finih linija. Poboljšavaju čvrstoću i tonus kože. Squalane Lagana i nemasna hidratantna komponenta koja omekšava, hidrira i štiti kožu. Ima antioksidativna svojstva i poboljšava elastičnost bez zagušivanja pora. Dodaj u listu želja Dodaj u listu želja', 'Tirtir Ceramic Milk Ampoule je luksuzna, trostruka ampula koja kombinuje vegan mleko, esenciju i ulje kako bi pružila dubinsku hidrataciju i regeneraciju kožne barijere. Sadrži ključne sastojke kao što su ceramidi, skvalan, hijaluronska kiselina i niacinamid, koji zajedno rade na očuvanju vlage, zaštiti kože i poboljšanju njenog opšteg zdravlja​.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Tirtir-Ceramic-Milk-Ampoule.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
