INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1603, 164, 'Tirtir Milk Skin Toner Light', 'tirtir-milk-skin-toner-light', 'Ključne prednosti: Dubinska hidratacija : Zahvaljujući ceramidima i beta-glukanu, tonik intenzivno hidrira kožu, poboljšavajući njenu teksturu i elastičnost. Ujednačava i posvetljuje ten : Niacinamid i ekstrakt pirinčanih mekinja deluju zajedno kako bi posvetlili kožu i smanjili pigmentacije. Kontrola sebuma i sužavanje pora : Niacinamid pomaže u regulaciji proizvodnje sebuma i sužavanju pora. Kome je namenjen? Ovaj toner je savršen za masnu, osetljivu i kožu sklonu aknama. Takođe je pogodan za sve tipove kože koji traže laganu hidrataciju i poboljšanje teksture kože. Zašto volimo Tirtir Milk Skin Toner Light? Tirtir Milk Skin Toner je formulisan da vašu svakodnevnu negu podigne na viši nivo . Ovaj lagani toner obogaćen je 4% niacinamida, što znači da nije samo običan hidratant. On je vaš tajni saveznik u borbi protiv neujednačenog tena, proširenih pora i masnog sjaja. Pantenol i alantoin rade u sinergiji kako bi vašu kožu umirili, regenerisali i zaštitili od svakodnevnih iritacija. Sa ovim tonerom, vaša koža će svakog dana biti sve bliže onom blistavom, zdravom izgledu kojem težite. Koju verziju Milk Skin Tonera odabrati? Tirtir Milk Skin Toner donosi 24-časovnu dubinsku hidrataciju baš tamo gde je tvoja koža najviše želi! Ovaj bogat, mlečni tonik sa 2% niacinamida idealan je za suvu i dehidriranu kožu, vraćajući joj svežinu i sjaj. Savršen je za one koji vole osećaj kremaste nege, dok dodatni sloj hidracije obnavlja barijeru kože. Za sve one koji se bore s masnom i problematičnom kožom, tu je TIRTIR Milk Skin Toner Light! Sa 4% niacinamida i sedam veganskih svojstava za umirenje, ovaj tonik pomaže u kontroli sebuma, zateže pore i lagano balansira vlagu. Njegova lagana, mlečna tekstura se brzo upija, ostavljajući kožu svežom i matiranom. Aktivni sastojci MultiEx BSAM Plus (patentirani biljni kompleks) Sastoji se od 7 biljnih ekstrakata poznatih po svojim umirujućim i revitalizujućim svojstvima (uključujući zeleni čaj, kamilicu i sladić). Pomaže u smanjenju iritacija, osvežava kožu i doprinosi zdravom, ujednačenom tenu. Pogodan za sve tipove kože, uključujući osetljivu. Niacinamid (4%) Visoka koncentracija ovog vitamina B3 pomaže u ujednačavanju tena, smanjenju hiperpigmentacija i regulaciji sebuma. Jača barijernu funkciju kože i poboljšava ukupni izgled kože čineći je osvetljenom i glatkom. Ekstrakt pirinčanih mekinja (Rice Bran Extract) Prirodni izvor antioksidanasa i vitamina koji posvetljuju, omekšavaju i štite kožu. Pomaže u održavanju vlažnosti i pruža ujednačen, zdrav izgled. Ceramidi Obnavljaju i jačaju zaštitnu barijeru kože, sprečavaju transepidermalni gubitak vode i štite od spoljašnjih iritacija. Posebno korisni za suvu, oštećenu i dehidriranu kožu. Glicerin Pouzdan humektant koji zadržava vlagu i poboljšava elastičnost kože. Omogućava mekoću i glatkoću bez osećaja težine ili masnoće. Dodaj u listu želja Dodaj u listu želja', 'Tirtir Milk Skin Toner Light je osvežavajući tonik koji pruža laganu hidrataciju i balansira kožu, ostavljajući je čistom i blistavom. Formulisan je s 4% niacinamida, ekstraktom pirinčanih mekinja i ceramidima, što pomaže u ujednačavanju tona kože, održavanju vlažnosti i zaštiti od gubitka vlage.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Tirtir-Milk-Skin-Toner-Light.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
