INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1608, 126, 'Numbuzin No.5 Daily Multi-Vitamin Cream', 'numbuzin-no-5-daily-multi-vitamin-cream', 'Ključne prednosti: Posvetljuje i ujednačava ten : Efikasno smanjuje tamne mrlje i hiperpigmentaciju. Hidrira i omekšava kožu : Dubinski hidrira, ostavljajući kožu mekanom i glatkom. Kome je namenjena? Ova krema je idealna za sve tipove kože, uključujući suvu, osetljivu i kožu sklonu hiperpigmentaciji. Pogodna je za svakodnevnu upotrebu i pruža neophodnu hidrataciju i zaštitu tokom celog dana​ Zašto volimo Numbuzin No.5 Daily Multi-Vitamin Cream? Numbuzin No.5 Daily Multi-Vitamin krema je svakodnevna doza hranljivih sastojaka koja transformiše vašu kožu u blistavu i zdravu. Ova krema, bogata vitaminom C iz Kakadu šljive, pomaže u borbi protiv tamnih fleka i neravnomernog tena, dok niacinamid ujednačava teksturu i smanjuje sitne bore. Pantenol i vitamin E pružaju dubinsku hidrataciju i zaštitu, čineći kožu mekom i otpornom. Svakodnevnim korišćenjem ove kreme, vaša koža će postati vidljivo osvežena, čvrsta i blistava. Aktivni sastojci Vitamin C (Askorbinska kiselina i njeni derivati) Vitamin C je snažan antioksidans koji neutrališe slobodne radikale, stimuliše sintezu kolagena i doprinosi ujednačavanju tena. Njegova ključna funkcija u ovoj kremi je upravljanje sintezom melanina – inhibira enzim tirozinazu i tako pomaže u smanjenju pigmentacija i tamnih fleka. Takođe pomaže u regeneraciji oštećene kože, osvetljavanju tena i poboljšanju elastičnosti. Redovnom upotrebom smanjuje znakove starenja i umornog izgleda kože. Niacinamid (Vitamin B3) Niacinamid je višefunkcionalni sastojak koji pomaže u posvetljavanju hiperpigmentacija, poboljšanju barijerne funkcije i regulaciji lučenja sebuma. U sinergiji s vitaminom C, efikasno smanjuje melanin u površinskim slojevima kože i osvetljava ten. Takođe poboljšava elastičnost kože i doprinosi njenoj glatkoći, smanjujući vidljivost pora i finih linija. Deluje protivupalno i pomaže u ublažavanju crvenila, čineći ovu kremu pogodnom za osetljivu i reaktivnu kožu. Alpha-Bisabolol Alpha-bisabolol je prirodni aktivni sastojak dobijen iz kamilice, poznat po svom snažnom umirujućem i posvetljujućem efektu. Deluje direktno na inhibiciju melanogeneze, čime doprinosi smanjenju tamnih mrlja i ujednačenju boje kože. Takođe ima protivupalna svojstva koja pomažu u umirivanju crvenila i iritacija, naročito kod osetljive kože. Njegova prisutnost u kremi pojačava efikasnost vitamina C i niacinamida bez izazivanja iritacija. Multivitaminski kompleks (22 vitamina + 27 nutrijenata) Ova bogata kombinacija uključuje vitamine A, E, B5, B6, H, F, kao i minerale, amino kiseline i koenzime koji zajedno obnavljaju, hrane i štite kožu. Pomaže u povećanju ćelijskog metabolizma, ubrzava regeneraciju i poboljšava tonus i teksturu kože. Vitamini deluju sinergijski u borbi protiv oksidativnog stresa, dok nutrijenti jačaju barijeru kože i održavaju optimalan nivo hidratacije. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.5 Daily Multi-Vitamin Cream je intenzivna vitaminska nega koja posvetljuje i ujednačava ten, smanjujući vidljive znakove starenja zahvaljujući moćnom ekstraktu Kakadu šljive bogatom vitaminom C. Sa više od 22 vrste vitamina i 27 hranljivih sastojaka, ova krema pruža vašu kožu neophodnom hidratacijom i zaštitom od oštećenja.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Numbuzin-No.5-Daily-Multi-Vitamin-Cream.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
