INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1612, 126, 'Numbuzin No.6 Deep Sleep Mask Serum', 'numbuzin-no-6-deep-sleep-mask-serum', 'Ključne prednosti: Obnavlja kožu dok spavate : Deluje tokom noći kako bi vaša koža izgledala sveže i odmorno ujutro. Dubinsko vlaženje : Hijaluronska kiselina i voda iz glečera prodiru u sve slojeve kože, pružajući dugotrajnu hidrataciju. Poboljšava elastičnost : Niacinamid i adenozin rade zajedno kako bi poboljšali čvrstoću i elastičnost kože. Kome je namenjen? Ovaj serum je savršen za sve tipove kože, a posebno je koristan za one sa suvom, umornom ili neujednačenom kožom koja traži dubinsku hidrataciju i revitalizaciju. Zašto volimo Numbuzin No.6 Deep Sleep Mask Serum? Probudite se sa blistavom i hidriranom kožom koja izgleda odmorno i sveže. Kao da ste spavali punih osam sati! Numbuzin No.6 Deep Sleep Serum je vaš verni pratilac u noćnoj nezi. Obogaćen vodom iz glečera i hijaluronskom kiselinom, pruža koži dubinsku hidrataciju i obnovu tokom noći. Niacinamid i biljni ekstrakti dodatno pomažu ujednačavanju tena i smanjenju znakova starenja. Dodaj u listu želja Dodaj u listu želja', 'Numbuzin No.6 Deep Sleep Mask Serum je jedinstveni serum namenje noćnoj upotrebi, koji pruža snažnu hidrataciju i revitalizaciju kože dok spavate. Ovaj serum je obogaćen sa 63% vode iz glečera i hijaluronskom kiselinom u više molekularnih veličina, što omogućava hidrataciju u svim slojevima kože.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Numbuzin-No.6-Deep-Sleep-Mask-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
