INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1619, 119, 'Mixsoon Bean Essence', 'mixsoon-bean-essence', 'Ključne prednosti: Dubinska hidratacija : Fermentisani sastojci obezbeđuju duboku hidrataciju i poboljšavaju elastičnost kože. Nežna eksfolijacija : Uklanja mrtve ćelije kože i smanjuje višak sebuma bez iritacija. Antioksidativna zaštita : Bogat vitaminima C i E, štiti kožu od štetnih spoljašnjih uticaja. Kome je namenjena? Ova esencija je idealna za sve tipove kože, uključujući osetljivu i zrelu kožu. Posebno je korisna za osobe sa suvom kožom ili kožom sklonom iritacijama. Takođe je odličan izbor za one koji žele da ujednače tonus kože i poboljšaju njenu teksturu. Zašto volimo Mixsoon Bean Essence? Mixsoon Bean Essence predstavlja sintezu prirode i nauke, pažljivo formulisan da vašoj koži pruži optimalnu negu. Ova esencija se izdvaja po svojoj jedinstvenoj kombinaciji fermentisanih ekstrakata soje, nara, ječma i korejske kruške, koji zajedno deluju kako bi dubinski hidrirali kožu, ujednačili njen ton i zaštitili je od svakodnevnih stresova. Šta čini ovu esenciju zaista posebnom? Pre svega, njen višenamenski pristup nezi kože. Nije samo hidratantna, već deluje i kao blagi eksfolijant koji efikasno uklanja mrtve ćelije kože, osvetljava ten i poboljšava teksturu. Fermentisani ekstrakti ne samo da poboljšavaju apsorpciju, već i osiguravaju da vaša koža dobije maksimum iz svakog sastojka, pružajući dubinsku regeneraciju i osveženje. Aktivni sastojci Fermentisani ekstrakt zrna soje (Fermented Bean) Fermentisani ekstrakt zrna soje bogat je aminokiselinama, proteinima i izoflavonima koji intenzivno hrane i regenerišu kožu. Proces fermentacije poboljšava apsorpciju hranljivih materija i čini ovaj sastojak izuzetno efikasnim u obnavljanju oštećene barijere kože. Deluje umirujuće, antioksidativno i hidratantno, pa je idealan za osetljivu, dehidriranu i umornu kožu. Takođe podstiče sintezu kolagena i poboljšava elastičnost kože. Njegovo dejstvo jača otpornost kože i daje joj zdrav, revitalizovan izgled. Koža postaje zaglađena, nahranjena i ujednačena. Fermentisani ekstrakt ječma (Fermented Barley) Ekstrakt fermentisanog ječma je bogat vitaminima B grupe, beta-glukanom i mineralima, koji pomažu u hidrataciji i umirenju kože. Fermentacija omogućava bolju biodostupnost ovih nutrijenata, što rezultira bržim i efikasnijim efektima na koži. Ima antiinflamatorna svojstva, pomaže u obnavljanju površinskog sloja kože i štiti je od štetnih uticaja iz okoline. Takođe poboljšava teksturu kože i ublažava crvenilo. U sinergiji sa fermentisanom sojom, dodatno jača zaštitnu funkciju kože. Koža postaje otpornija, uravnotežena i nežna na dodir. Fermentisani ekstrakt nara (Fermented Pomegranate) Fermentisani ekstrakt nara bogat je vitaminom C, polifenolima i elagičnom kiselinom, koji deluju kao snažni antioksidansi. Pomaže u posvetljavanju tena, ujednačavanju boje kože i zaštiti od slobodnih radikala. Proces fermentacije povećava njegovu efikasnost i smanjuje potencijal za iritaciju. Takođe stimuliše obnavljanje ćelija i poboljšava elastičnost kože. U formulaciji esencije doprinosi osveženju i revitalizaciji kože koja deluje umorno ili sivkasto. Koža postaje blistava, osvetljena i puna energije. Fermentisani ekstrakt korejske kruške (Fermented Korean Pear) Fermentisana korejska kruška bogata je prirodnim šećerima, antioksidansima i hidratantnim jedinjenjima koja deluju umirujuće i osvežavajuće. Ovaj sastojak pomaže u regulaciji proizvodnje sebuma, održava optimalan nivo vlage i poboljšava prozračnost tena. Zahvaljujući fermentaciji, omogućava dublju penetraciju i bolju stabilnost aktivnih jedinjenja. Posebno je koristan za kombinovanu i masniju kožu jer balansira hidrolipidni sloj bez opterećenja. Koža ostaje osvežena, glatka i prirodno sjajna. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Bean Essence je višenamenska esencija koja deluje kao nežni eksfolijant i hidratant za sve tipove kože. Ova esencija kombinuje fermentisane sastojke, uključujući soju, ječam, nar i korejsku krušku, kako bi pružila dubinsku hidrataciju i hranljive materije.', 'https://beauty-health.rs/wp-content/uploads/2024/08/Mixsoon-Bean-essence.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
