INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1623, 119, 'Mixsoon Bean Cleansing Oil', 'mixsoon-bean-cleansing-oil-195ml', 'Ključne prednosti: Dubinsko čišćenje : Efikasno uklanja šminku, sebum, mitisere i mrtve ćelije kože. Hidratacija i osveženje : Fermentisani ekstrakti soje, ječma, nara i korejske kruške obiluju vitaminima i proteinima, pružajući hranljive benefite koži. Lagano ulje : Tekstura koja se brzo upija i ne ostavlja ostatke, pogodna za svakodnevnu upotrebu. Kome je namenjen? Mixsoon Bean ulje za čišćenje je pogodno za sve tipove kože, uključujući suvu, masnu i osetljivu kožu. Njegova nemasna formula omogućava temeljno čišćenje. Zašto volimo Mixsoon Bean Cleansing Oil? Mixsoon Bean ulje je više od običnog sredstva za čišćenje! Ovaj lagani, ali moćni uljani čistač lako se nanosi, razgrađuje šminku i prljavštinu, dok fermentisani ekstrakt soje i prirodna ulja poput sojinog i jojobinog ulja njeguju vašu kožu. Nakon svakog korišćenja, vaša koža će biti osvežena, hidrirana i spremna za sledeći korak u vašoj rutini nege. Bez osećaja težine ili masnoće, ovaj čistač je savršen za svakodnevnu upotrebu i idealan je za sve tipove kože. Aktivni sastojci Lactobacillus/Soybean Ferment Extract Fermentisani ekstrakt soje uz pomoć Lactobacillus kulture bogat je vitaminima, mineralima i esencijalnim aminokiselinama koje doprinose hranjenju i regeneraciji kože. Ovaj sastojak pomaže u ojačavanju kožne barijere, poboljšava zadržavanje vlage i umiruje iritiranu kožu. Fermentacija omogućava dublju penetraciju nutrijenata i bolju iskoristivost sastojaka. Takođe ima antioksidativna svojstva, čime štiti kožu od štetnih spoljašnjih faktora. Idealno je rešenje za suvu, umornu ili oslabljenu kožu kojoj je potrebna dodatna nega prilikom čišćenja. Koža nakon čišćenja ostaje mekana, hidrirana i osvežena. Saccharomyces/Barley Seed Ferment Filtrate Ovaj fermentisani filtrat iz semena ječma sadrži prirodne antioksidanse, proteine i enzime koji pomažu u revitalizaciji i osvetljavanju kože. Deluje umirujuće i hidratantno, dok istovremeno pomaže u uklanjanju toksina i ostataka šminke, ne oštećujući zaštitni sloj kože. Fermentacija olakšava apsorpciju aktivnih jedinjenja i smanjuje rizik od iritacija. Takođe doprinosi zaglađivanju teksture i poboljšava otpornost kože na dehidrataciju. U kombinaciji sa fermentisanom sojom, pruža bogatu nutritivnu negu već u fazi čišćenja. Koža ostaje čista, izbalansirana i negovana. Dodaj u listu želja Dodaj u listu želja', 'Mixsoon Bean Cleansing Oil je dnevno ulje za čišćenje koje pruža dubinsko čišćenje kože uz hidratantna svojstva, bez iritacija. Ova lagana uljna formula efikasno uklanja šminku, sebum, mitisere i mrtve ćelije kože, ostavljajući kožu osveženom i hidriranom.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Mixsoon-BeanCleansing-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
