INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1627, 84, 'Isntree Hyper Retinol EX 1.0 Serum', 'isntree-hyper-retinol-ex-1-0-serum', 'Ključne prednosti: Smanjenje bora i finih linija : Sa 0,1% čistog retinola, 0.3% retinil palmitata i 0.6% bakučiola, serum efikasno smanjuje znakove starenja. Jačanje barijere kože : 5 različitih peptida i ceramida poboljšavaju čvrstoću kože i zadržavaju vlagu. Hidratacija i elastičnost : Dodatni sastojci poput niacinamida i alantoina obezbeđuju hidrataciju i elastičnost kože. Pogodno za sve tipove kože : Formulisano za sve tipove kože, uključujući osetljivu. Kome je namenjen? Ukoliko tražite multifunkcionalni proizvod koji pored retinola sadrži i peptide, ceramide i antioksidanse ovo je idealan serum za vas. Pogodan je i za osetljivu regiju oko očiju, pa vam nije potreban poseban preparat za zonu oko očiju. Zašto volimo Isntree Hyper Retinol EX 1.0 Serum? Isntree Hyper Retinol Serum je serum visokih performansi, kreiran da u jednom potezu transformiše vašu kožu. Kombinacijom retinola, bakučiola i niacinamida, ovaj serum cilja na fine linije i bore. Takođe poboljšava celokupnu teksturu i ujednačava ten. Zahvaljujući dodatku ceramida i peptida, serum ne samo da obnavlja, već i štiti vašu kožu, čineći je jačom i otpornijom. Aktivni sastojci Retinol Retinol je aktivni oblik vitamina A poznat po svojoj snažnoj anti-age efikasnosti. Deluje tako što stimuliše sintezu kolagena i ubrzava obnavljanje ćelija kože, što dovodi do smanjenja vidljivosti bora i finih linija. U ovoj formuli se nalazi u koncentraciji od 1%, što ga čini veoma potentnim, pa se preporučuje postepeno uvođenje u rutinu. Takođe može pomoći u smanjenju hiperpigmentacija i ujednačavanju tena. Redovnom upotrebom, koža postaje zategnutija, glatkija i vidno osvežena. Retinil palmitat Retinil palmitat je derivat vitamina A, blaži oblik retinoida koji se u koži pretvara u aktivni retinol. Njegova glavna uloga je da poboljša teksturu kože i ujednači ten bez izazivanja iritacija. U koncentraciji od 0.3%, pruža dodatni anti-age efekat uz manji rizik od neželjenih reakcija. Pomaže u smanjenju sitnih linija i obnavljanju površinskog sloja kože. Bakuchiol Bakuchiol je biljna alternativa retinolu, poznat po sličnim efektima bez izazivanja iritacija. U koncentraciji od 0.6%, bakuchiol pomaže u poboljšanju elastičnosti i ujednačavanju tona kože. Deluje antiinflamatorno i antioksidativno, čime umanjuje crvenilo i štiti kožu od oksidativnog stresa. Posebno je koristan za osetljivu kožu ili za one koji ne podnose retinoide. Peptidi Pet vrsta peptida u ovoj formuli deluju kao signalni molekuli koji stimulišu proizvodnju kolagena i elastina. Njihovo prisustvo doprinosi jačanju strukture kože, čineći je čvršćom i otpornijom na spoljne faktore. Peptidi takođe ubrzavaju regeneraciju tkiva i poboljšavaju glatkoću kože. Ovi sastojci su poznati po svojoj blagosti i odličnoj kompatibilnosti sa osetljivom kožom. Dodaj u listu želja Dodaj u listu želja', 'Isntree Hyper Retinol EX 1.0 Serum je moćan anti-age serum koji kombinuje visoku koncentraciju retinola sa naprednim sastojcima za negu kože. Formulisan je sa 0,1% retinola, 0.3% retinil palmitata i 0.6% bakuchiola, što pomaže u smanjenju bora, finih linija i hiperpigmentacija.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Isntree-Hyper-Retinol-EX-1.0-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
