INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1630, 84, 'Isntree Yam Root Vegan Milk Toner', 'yam-root-vegan-milk-toner', 'Ključne prednosti: Duboka hidratacija : Sadrži 80% korena divljeg jama za intenzivnu i dugotrajnu hidrataciju. Jačanje barijere kože : Kompleks lipida pomaže u jačanju i zaštiti barijere kože. Brza apsorpcija : Lagana tekstura koja se brzo upija bez teškog osećaja na koži. Kome je namenjen? Preporučujemo ovaj proizvod osobama sa suvom i osetljivom kožom, kao i onima čija koža lako postaje iritirana na vetru tokom zime. Idealan je za sve koji traže superiorna hidratantna svojstva. Zašto volimo Isntree Yam Root Vegan Milk Toner? Isntree Yam Root Vegan Milk tonik je formulisan za one koji traže dubinsku hidrataciju i obnovu kože. On kombinuje moć yama, ceramida i biljnih mleka kako bi vašoj koži pružio potrebnu negu i zaštitu. Njegova bogata, ali lagana tekstura se brzo upija, ostavljajući kožu osveženom, hidriranom i spremnom za dalju negu. Zahvaljujući svojoj formuli, toner ne samo da hidrira, već i jača kožnu barijeru, pomažući u zaštiti kože od svakodnevnih izazova. Aktivni sastojci Ekstrakt korena jama (Dioscorea Japonica Root Extract) Ekstrakt korena jama čini 80% formule ovog tonika, pružajući intenzivnu hidrataciju suvoj koži. Bogat je antioksidansima i poseduje antiinflamatorna svojstva, pomažući u smirivanju iritacija i zaštiti kože od oksidativnog stresa. Takođe, doprinosi poboljšanju elastičnosti i čvrstine kože, čineći je glatkom i revitalizovanom. Njegova sposobnost zadržavanja vlage pomaže u održavanju optimalnog nivoa hidratacije. Kompleks biljnih mleka (Vegan Milk Complex) Ovaj kompleks sadrži ekstrakte zobi, pirinča, kokosa i drugih biljnih sastojaka koji zajedno pružaju bogatu hidrataciju i ishranu koži. Ekstrakt zobi umiruje kožu i smanjuje crvenilo, dok ekstrakt pirinča posvetljuje ten i ujednačava boju kože. Kokosov ekstrakt deluje kao emolijens, omekšavajući kožu i pružajući joj glatkoću. Ovi biljni mlečni ekstrakti zajedno jačaju kožnu barijeru, štiteći je od spoljašnjih agresora. Takođe, doprinose elastičnosti i čvrstini kože, smanjujući vidljivost finih linija. Dodaj u listu želja Dodaj u listu želja', 'Isntree Yam Root Vegan Milk Toner je hidratantni mlečni toner koji sadrži 80% ekstrakta korena divljeg jama iz Andonga, Koreje. Ovaj toner pruža duboku hidrataciju i obnavlja vlagu zahvaljujući botaničkom fitomucinu i kompleksu biljnog mleka.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Isntree-Yam-Root-Vegan-Milk-Toner.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
