INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1640, 69, 'Haruharu Wonder Black Rice Facial Oil', 'haruharu-wonder-black-rice-facial-oil', 'Ključne prednosti: Dubinska hidratacija: 45% fermentisani ekstrakt crnog pirinča pruža intenzivnu hidrataciju, zadržavajući vlagu unutar kože. Antioksidativna zaštita: Visok sadržaj polifenola i flavonoida iz crnog pirinča štiti kožu od slobodnih radikala i UV oštećenja​. Umirujuće dejstvo: Prirodna ulja poput jojobe, badema, suncokreta i lavande umiruju kožu, smanjuju crvenilo i iritacije​​. Poboljšanje elastičnosti: Ulje semena kamelije i ulje makadamije pomažu u poboljšanju elastičnosti kože, čineći je čvrstom i glatkom​​. Kome je namenjeno? Ovo ulje je idealno za sve tipove kože, posebno za suvu i dehidriranu kožu koja zahteva dubinsku hidrataciju i zaštitu. Zahvaljujući svojoj laganoj formuli, pogodno je i za osobe sa masnom ili kombinovanom kožom, pružajući balansiranu negu bez zagušivanja pora Zašto volimo Haruharu Wonder Black Rice Facial Oil? Ovo ulje se brzo upija, pružajući bogatu hidrataciju bez osećaja težine. Fermentisano ulje crnog pirinča deluje kao moćan zaštitni sloj, zadržavajući vlagu i poboljšavajući elastičnost kože. Kombinacija suncokretovog i jojoba ulja dodatno neguje vašu kožu, dok lavanda i kamelija umiruju i omekšavaju. Ova jedinstvena formula osigurava da vaša koža izgleda zdravo, sjajno i mladalački. Aktivni sastojci Black Rice Bran Oil (45%) Ulje crnog pirinča bogato je antioksidansima, uključujući antocijanine, vitamin E i fitosterole koji štite kožu od oksidativnog stresa. Pruža intenzivnu hidrataciju i pomaže u jačanju kožne barijere, zadržavajući vlagu unutar epidermisa. Ovo ulje ima prirodnu sposobnost da balansira sebum, što ga čini pogodnim i za suvu i za kombinovanu kožu. Njegova hranljiva struktura regeneriše kožu i poboljšava njenu elastičnost. Ne ostavlja mastan trag, već kožu čini svilenkastom, sjajnom i negovanom. Tocopherol (Vitamin E) Tokoferol je snažan antioksidans koji štiti ćelije kože od slobodnih radikala i prevremenog starenja. Pomaže u smanjenju oštećenja izazvanih UV zračenjem i zagađenjem. Takođe poboljšava elastičnost i jača barijernu funkciju kože. Ima umirujuće dejstvo i smanjuje crvenilo, posebno kod suve i osetljive kože. U sinergiji sa uljem crnog pirinča, dodatno produžava efekat hidratacije. Dodaj u listu želja Dodaj u listu želja', 'Haruharu Wonder Black Rice Facial Oil je lagana, brzo upijajuća uljna formula sadrži 45% fermentisanog ekstrakta crnog pirinča. Bogat antioksidantima, on pruža intenzivnu hidrataciju, elastičnost i zaštitu kože.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Haruharu-Wonder-Black-Rice-Facial-Oil.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
