INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1643, 25, 'Benton Deep Green Tea Serum', 'benton-deep-green-tea-serum', 'Ključne prednosti: Dubinska hidratacija: Ekstrakt zelenog čaja i hijaluronska kiselina obezbeđuju intenzivnu hidrataciju, čineći kožu mekom i glatkom. Umirujuće dejstvo: Zeleni čaj umiruje kožu, smanjuje crvenilo i iritacije. Ekstrakti vrbe pomažu u kontroli sebuma i smanjenju upala. Posvetljivanje kože: Antioksidanti iz zelenog čaja i vitamina C pomažu u posvetljavanju tena i smanjenju pigmentacija. Kome je namenjen? Ovaj serum je idealan za sve tipove kože. Ipak, posebno je koristan za masnu, kombinovanu i osetljivu kožu. Namenjen je osobama koje žele da smanje iritacije i kontrolišu proizvodnju sebuma. Zašto volimo Benton Deep Green Tea Serum? Inspirisan snagom zelenog čaja iz regije Boseong, ovaj serum koristi bogatstvo antioksidanata i umirujućih svojstava kako bi vaša koža bila sveža i zaštićena od štetnih faktora iz okoline. Dok zeleni čaj umiruje i balansira vašu kožu, hijaluronska kiselina i pantenol rade u tandemu da zadrže vlagu, dubinski hidriraju i obnavljaju kožu iznutra. Aktivni sastojci Camellia Sinensis Leaf Extract Ekstrakt lista zelenog čaja bogat je antioksidansima, uključujući polifenole, koji pomažu u neutralizaciji slobodnih radikala i zaštiti kože od oštećenja izazvanih UV zračenjem. Takođe, poseduje antiinflamatorna svojstva koja umiruju iritacije i crvenilo, čineći ga pogodnim za osetljivu kožu. Ekstrakt zelenog čaja pomaže u regulaciji proizvodnje sebuma, što može smanjiti pojavu akni i pružiti mat izgled kože. Poboljšava elastičnost i čvrstinu kože, doprinoseći njenom mladalačkom izgledu. Njegova antimikrobna svojstva štite kožu od štetnih mikroorganizama. Redovnom upotrebom, koža postaje osvežena i revitalizovana. ​ Houttuynia Cordata Extract Ekstrakt biljke Houttuynia Cordata, poznate i kao &#8220;srcolika kiselica&#8221;, poseduje snažna antioksidativna svojstva koja štite kožu od oksidativnog stresa. Deluje antiinflamatorno, smanjujući upale i iritacije, što je korisno za kožu sklonu aknama i crvenilu. Takođe, ima antimikrobna svojstva koja pomažu u borbi protiv bakterija koje izazivaju akne. Poboljšava hidrataciju kože, čineći je mekom i glatkom. Ekstrakt Houttuynia Cordata može pomoći u regulaciji proizvodnje sebuma, održavajući balansiran ten. Redovnom upotrebom, koža postaje čistija i zdravijeg izgleda Dodaj u listu želja Dodaj u listu želja', 'Benton Deep Green Tea Serum je formulisan sa preko 53% ekstrakta zelenog čaja iz Boseonga, poznatog po svom visokom kvalitetu. Kombinacija zelenog čaja i 3 vrste hijaluronske kiseline pruža vašoj koži neophodnu vlagu. Istovremeno, ovaj serum umiruje i hladi osetljivu kožu, smanjujući crvenilo i iritacije.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Benton-Deep-Green-Tea-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
