INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1648, 22, 'Beauty of Joseon Relief Sun', 'beauty-of-joseon-relief-sun', 'Ključne prednosti Visoka UV zaštita: SPF50+ PA++++ pruža zaštitu od UVA i UVB zraka, čime štiti kožu od oštećenja sunca i prevremenog starenja​. Hidratacija i umirenje: Ekstrakt pirinča bogat vitaminima i mineralima pruža dubinsku hidrataciju, dok probiotici umiruju i jačaju kožnu barijeru​​. Pogodan za osetljivu kožu: Bez iritantnih mirisa i alkohola, ovaj sunscreen je idealan za osetljivu kožu sklonu crvenilu i iritacijama​. Kome je namenjen? Ovaj proizvod je idealan za sve tipove kože, uključujući i one sa osetljivom, suvom ili kombinovanom kožom. Namenjen je osobama koje traže efikasan SPF koji ne samo da štiti kožu, već i poboljšava njeno zdravlje i izgled. Takođe pruža dugotrajnu hidrataciju bez osećaja težine ili masnog sjaja​. Zašto volimo Beauty of Joseon Relief Sun? Beauty of Joseon Relief Sun: Rice + Probiotics nije samo običan SPF proizvod, već luksuzna nega za vašu kožu koja spaja tradiciju i nauku. Inspirisan drevnim korejskim ritualima lepote, ovaj lagani, hidratantni kremasti SPF pruža ne samo zaštitu, već i hranljivost. Ekstrakt pirinča osigurava dubinsku hidrataciju i pomaže u održavanju blistavog tena. Pobiotici jačaju kožnu barijeru, ostavljajući je otpornom i zdravom. Kombinacija ovih sastojaka zajedno sa snažnim UV filterima čini ovaj SPF savršenim izborom za svakodnevnu upotrebu. Idealan za one koji žele da spoje zaštitu i negu u jednom proizvodu. Aktivni sastojci Ekstrakt pirinča (30%) Ekstrakt pirinča bogat je vitaminima B, C i E, kao i aminokiselinama i mineralima koji pružaju dubinsku hidrataciju i antioksidativnu zaštitu. Ovaj sastojak jača kožnu barijeru, pomažući u zadržavanju vlage i zaštiti od spoljašnjih agresora. Takođe, doprinosi posvetljivanju tena i poboljšava teksturu kože, čineći je glatkijom i ujednačenijom. Njegova sposobnost da smiri iritacije i crvenilo čini ga pogodnim za osetljivu kožu. Pomaže u regeneraciji kože, pružajući joj zdrav i svež izgled. Redovna upotreba proizvoda sa pirinčnim ekstraktom može poboljšati elastičnost kože i pružiti dugotrajnu hidrataciju. Fermentisani ekstrakti žitarica Fermentisani ekstrakti žitarica deluju sinergijski sa ekstraktom pirinča, pružajući dubinsku hidrataciju i umirujući efekat. Ovi ekstrakti bogati su probiotici koji pomažu u jačanju mikrobioma kože, poboljšavajući njenu otpornost na iritacije i spoljašnje faktore. Takođe, podržavaju prirodni proces obnove kože, pomažući u smanjenju crvenila i osvežavanju tena. Njihova antioksidativna svojstva štite kožu od štetnih efekata UV zračenja i zagađenja. Ovi sastojci doprinose zaglađenijoj i osveženoj koži, čineći je mekom i elastičnom. Redovna upotreba fermentisanih žitarica pomaže u očuvanju zdrave i hidrirane kože. Dodaj u listu želja Dodaj u listu želja', 'Zaštitite i negujte svoju kožu kremom Beauty of Joseon Relief Sun: Rice + Probiotics, koja sa SPF50+ PA++++ pruža vrhunsku UV zaštitu i intenzivnu hidrataciju. Bogata ekstraktom pirinča i fermentisanim probioticima, ova krema umiruje i hidrira sve tipove kože, uključujući i osetljivu.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Beauty-of-Joseon-relief-sun.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
