INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1649, 22, 'Beauty of Joseon Light On Serum', 'beauty-of-joseon-light-on-serum', 'Ključne prednosti Posvetljivanje kože: Vitamin C posvetljuje kožu i smanjuje tamne mrlje i pigmentacije, poboljšavajući ujednačenost tena. Umirujuće dejstvo: Ekstrakt Centella Asiatica umiruje kožu, smanjuje crvenilo i iritacije, te pomaže u obnavljanju kožne barijere. Hidratacija: Pantenol i hijaluronska kiselina pružaju dubinsku hidrataciju, zadržavajući vlagu u koži i čineći je mekom i glatkom. Antioksidativna zaštita: Sastojci poput madekazozida iz Centella Asiatica ekstrakta pružaju antioksidativnu zaštitu. Kome je namenjen? Ovaj serum je idealan za sve tipove kože, posebno za one koji žele da umire iritacije, smanje tamne mrlje i poboljšaju tonus kože. Namenjen je osobama koje traže stabilan i efikasan serum koji neće izazvati iritacije. Zašto volimo Beauty of Joseon Light On Serum? Light On Serum je kreiran sa ciljem da vam pomogne da postignete sjajan, ujednačen ten. Sa svakim nanošenjem, Centella Asiatica smiruje kožu i ubrzava regeneraciju, dok vitamin C postepeno smanjuje tamne mrlje i daje koži blistavost. Ovaj serum je više od običnog proizvoda; on je korak ka zdravijoj, sjajnijoj koži, koji svakodnevno donosi rezultate koje možete videti i osetiti. Aktivni sastojci Ekstrakt Centella Asiatica (68%) Centella Asiatica, poznata i kao &#8220;tigrasta trava&#8221;, tradicionalno se koristi zbog svojih umirujućih i isceljujućih svojstava. Ovaj ekstrakt bogat je aktivnim jedinjenjima poput azijatikozida i madekazozida, koji imaju snažna antiinflamatorna i antioksidativna svojstva. Pomaže u smirivanju iritacija i crvenila, što je posebno korisno za osetljivu i problematičnu kožu. Takođe, stimuliše sintezu kolagena, poboljšavajući elastičnost i čvrstoću kože, što doprinosi smanjenju pojave finih linija i bora. 3-O-Etil askorbinska kiselina (10%) 3-O-Etil askorbinska kiselina je stabilan derivat vitamina C poznat po svojim antioksidativnim i posvetljujućim svojstvima. Ovaj oblik vitamina C efikasno inhibira sintezu melanina, pomažući u smanjenju hiperpigmentacija i ujednačavanju tena. Takođe, stimuliše sintezu kolagena, što doprinosi poboljšanju elastičnosti i čvrstoće kože, smanjujući pojavu finih linija i bora. Njegova stabilnost omogućava duži rok trajanja proizvoda bez gubitka efikasnosti, za razliku od čistog vitamina C koji je sklon oksidaciji. Dodaj u listu želja Dodaj u listu želja', 'Otkrijte moćnu kombinaciju prirodnih sastojaka sa Beauty of Joseon Light On Serum: Centella + Vita C . Ovaj serum je specijalno formulisan sa 68% ekstrakta Centella Asiatica i 10% stabilnog derivata vitamina C. Ova kombinacija pruža intenzivnu hidrataciju, umiruje kožu i smanjuje pigmentacije.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Beauty-of-Joseon-Light-On-Serum-1.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
