INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1651, 22, 'Beauty of Joseon: Set 4 mini seruma', 'set-od-4-mini-seruma', 'Sadržaj seta Revive Serum: Ginseng + Snail Mucin 10ml Opis: Revitalizuje i podmlađuje kožu sa 63% ekstrakta korena žen-šena i 3% puževe sluzi. Prednosti: Smanjuje bore i pigmentaciju, poboljšava elastičnost kože i daje joj zdrav sjaj. Tekstura: Lagana tekstura koja se brzo upija. Glow Deep Serum: Rice + Alpha Arbutin 10ml Opis: Posvetljuje i ujednačava ten sa 68% ekstrakta rižine vode i 2% alpha arbutina. Prednosti: Smanjuje tamne mrlje i hiperpigmentaciju, čineći kožu blistavom i sjajnom. Tekstura: Vodenasta i lagana tekstura. Glow Serum: Propolis + Niacinamide 10ml Opis: Bori se protiv akni i upala sa 60% ekstrakta propolisa i 2% niacinamida. Prednosti: Anti-akne, anti-inflamatorna svojstva, poboljšava teksturu kože i smanjuje pojavu nesavršenosti. Tekstura: Tekstura slična medu koja se lako nanosi i apsorbuje. Calming Serum: Green Tea + Panthenol 10ml Opis: Umiruje i hidrira kožu sa 76% ekstrakta zelenog čaja i 2% pantenola. Prednosti: Smiruje iritacije i crvenilo, pruža dubinsku hidrataciju i jača kožnu barijeru. Tekstura: Vodenasta i lagana tekstura. Dodaj u listu želja Dodaj u listu želja', 'Otkrijte svoju savršenu rutinu nege kože uz Hanbang Serum Discovery Kit . Ovaj set sadrži četiri mini seruma od po 10ml, pažljivo formulisanih da zadovolje različite potrebe vaše kože. Idealan za isprobavanje i kombinovanje kako biste pronašli najbolju formulu za vašu kožu.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Beauty-of-Joseon-Set-od-4-mini-seruma.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
