INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1652, 22, 'Beauty of Joseon Glow Deep Serum', 'beauty-of-joseon-glow-deep-serum', 'Ključne prednosti Posvetljivanje kože : Alfa arbutin efikasno inhibira formiranje melanina, smanjujući pigmentaciju i posvetljujući kožu​. Dubinska hidratacija : Ekstrakt pirinčane vode bogat aminokiselinama i mineralima hidrira kožu, čineći je glatkom i mekom​​. Ujednačavanje tena: Redovna upotreba seruma pomaže ujednačavanju tena, smanjujući vidljivost tamnih mrlja i diskoloracija​. Kome je namenjen? Ovaj serum je idealan za sve tipove kože. Posebno za osobe koje se bore sa hiperpigmentacijom, tamnim mrljama ili neujednačenim tonom kože. Zašto volimo Beauty of Joseon Glow Deep Serum? Beauty of Joseon Glow Deep Serum je osmišljen za one koji žele da postignu savršeno blistav i ujednačen ten. Korišćenje ovog seruma je kao da svakodnevno pružate svojoj koži drevnu tajnu nege koja osvežava i revitalizuje. Uz moćne sastojke poput pirinčane vode i alfa arbutina, svaki naneti sloj deluje kao štit protiv tamnih mrlja i neravnomernog tona. Ovaj serum hrani i štiti vašu kožu, čineći je zdravijom i svetlijom svakog dana. Njegova lagana tekstura omogućava brzo upijanje bez osećaja težine na koži. Aktivni sastojci Voda pirinčanih mekinja (68%) Voda pirinčanih mekinja, poznata i kao &#8220;Beauty Water&#8221; u dinastiji Joseon, tradicionalno se koristila za postizanje blistavog i zdravog tena. Ovaj sastojak bogat je aminokiselinama i mineralima koji pomažu u hidrataciji i jačanju kožne barijere. Pruža dugotrajnu vlagu suvoj i dehidriranoj koži, poboljšavajući njen tonus i elastičnost. Njegova sposobnost da ujednači teksturu kože čini je glatkom i osveženom. Takođe, poseduje antioksidativna svojstva koja pomažu u zaštiti kože od spoljašnjih agresora i slobodnih radikala. Redovna upotreba proizvoda sa vodom pirinčanih mekinja može doprineti zdravijem, hidriranom i blistavom tenu. Alfa-arbutin (2%) Alfa-arbutin je moćan posvetljujući sastojak koji inhibira aktivnost enzima tirozinaze, ključnog za sintezu melanina u koži. Efikasniji je od beta-arbutina i pruža vidljive rezultate u smanjenju hiperpigmentacija i tamnih mrlja. Takođe, pomaže u ujednačavanju tena, čineći kožu svetlijom i blistavijom bez iritacija. Njegova blaga, ali efikasna formula pogodna je za osetljivu kožu, jer ne izaziva iritacije ili crvenilo. Takođe, poseduje antioksidativna svojstva koja pomažu u zaštiti kože od oksidativnog stresa. Redovna upotreba proizvoda sa alfa-arbutinom može doprineti ravnomernijem tenu i zdravijem izgledu kože. Dodaj u listu želja Dodaj u listu želja', 'Glow Deep Serum: Rice + Alpha Arbutin je formulisan sa 68% ekstrakta pirinčane vode i 2% alfa arbutina, koji zajedno posvetljuju kožu i smanjuju tamne mrlje. Inspirisan tradicionalnom korejskom negom kože, ovaj serum nudi savremen pristup za postizanje blistavog i zdravog tena.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Beauty-of-Joseon-Glow-Deep-Serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
