INSERT INTO product (id, brand_id, name, slug, description, short_description, primary_image_url, is_featured, is_active, created_at, updated_at) VALUES (1659, 11, 'Anua Heartleaf 80% Ampula', 'anua-heartleaf-80-ampule', 'Ključne prednosti: Umirujući efekat: Visok sadržaj ekstrakta kameleona umiruje iritiranu i crvenu kožu, pružajući intenzivnu negu i zaštitu. Dubinska hidratacija: Kombinacija pantenola, hijaluronske kiseline i betaina pruža dubinsku hidrataciju, čineći kožu glatkom i mekom. Zaštita kože: Efikasno štiti kožu od spoljašnjih iritacija, uključujući zagađenje i stresove iz okoline, što je čini pogodnom za osetljivu kožu. Kome je namenjena? Namenjena je osobama sa osetljivom, suvom ili kombinovanom kožom koja je sklona crvenilu i iritacijama, kao i onima koji žele intenzivnu hidrataciju i smirenje za svoju kožu. Zašto volimo Anua Heartleaf 80% Ampulu? Korišćenjem ove ampule, vaša koža dobija moćan spoj prirodnih sastojaka koji je štite, umiruju i regenerišu. Svakodnevna upotreba ove ampule postaje ritual u kojem koža dobija neophodnu hidrataciju i zaštitu, što rezultira zdravim, blistavim izgledom. Ekstrakt biljke kameleon pomaže u smanjenju iritacija, dok pantenol i betaine rade zajedno na održavanju optimalnog nivoa vlažnosti. Ovaj proizvod nije samo efikasan, već i nežan prema koži, čineći ga savršenim za svakodnevnu rutinu nege. Aktivni sastojci Ekstrakt Houttuynia Cordata (80%) Ekstrakt Houttuynia Cordata, poznat i kao srcolisna biljka, bogat je flavonoidima poput kvercetina, koji pružaju antioksidativna i antiinflamatorna svojstva. Ovaj sastojak pomaže u umirivanju iritacija, smanjenju crvenila i zaštiti kože od slobodnih radikala. Takođe, poseduje antibakterijska svojstva koja mogu pomoći u održavanju čiste kože. Njegova sposobnost da hidrira i balansira kožu čini ga idealnim za osetljive i problematične tipove kože. ​ Glicerin Glicerin je prirodni humektant koji privlači vlagu iz okoline u kožu, pružajući intenzivnu hidrataciju. Pomaže u održavanju mekoće i elastičnosti kože, smanjujući suvoću i perutanje. Takođe, jača zaštitnu barijeru kože, štiteći je od štetnih spoljašnjih uticaja. Glicerin poboljšava apsorpciju drugih aktivnih sastojaka, omogućavajući im da efikasnije deluju. ​ Panthenol (Provitamin B5) Panthenol je poznat po svojim hidratantnim i umirujućim svojstvima, pomažući u zadržavanju vlage u koži i poboljšanju njene elastičnosti. Takođe, pospešuje proces zarastanja rana i smanjuje upale, čineći kožu mekšom i glatkijom. Njegova sposobnost da prodre duboko u kožu omogućava dugotrajnu hidrataciju i zaštitu od isušivanja. Panthenol takođe jača zaštitnu barijeru kože, štiteći je od spoljašnjih agresora i iritacija. ​ Dodaj u listu želja Dodaj u listu želja', 'Moćni eliksir za negu kože Anua heartleaf 80% ampula je obogaćena sa 80% ekstrakta biljke kameleon ( Houttuynia Cordata ). Ovaj serum je savršen za svakodnevnu upotrebu, pružajući intenzivnu hidrataciju i umirujući iritacije kože.', 'https://beauty-health.rs/wp-content/uploads/2024/07/Anua-Heartleaf-Ampula-serum.jpg', false, true, TIMESTAMP '2026-01-01 12:00:00', TIMESTAMP '2026-01-01 12:00:00');
